  [3666] = "{id=3666,NameZh='埃米尔的卡册',Icon='23',Type=41,Quality=2,MaxNum=99999,SellPrice=100,Desc='由卡片爱好者埃米尔先生收集整理的《米德加尔特卡片大全》，集齐后可以获得卡册内卡片。',}",
  [3667] = "{id=3667,NameZh='精装埃米尔的卡册',Icon='item_3667',Type=41,Quality=3,MaxNum=99999,SellPrice=100,Desc='限量发行的精装版《米德加尔特卡片大全》，由埃米尔家族成员补全，收录了更多稀有卡片，集齐后可以获得卡册内卡片。',Feature=1,}",
  [3668] = "{id=3668,NameZh='神秘箱子2.0',Icon='item_3026',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='会散发出神秘蓝色光芒的旧箱子，打开的话好像有什么东西会跑出来似的。',Feature=1,}",
  [3669] = "{id=3669,NameZh='品客礼物盒',Icon='item_3669',Type=30,MaxNum=99999,SellPrice=100,Desc='品客为RO玩家特意定制的专属礼物盒，装有美味的薯片和一些神秘礼物，打开之前最好祈祷一会。',Feature=1,}",
  [3670] = "{id=3670,NameZh='初心食材包包·Ⅰ',Icon='item_60',Type=30,MaxNum=99999,SellPrice=100,Desc='新手厨工常常因为技艺不精而造成食材的浪费，所以由皇家料理协会提供了一些最常用的基础食材用于练习。（开启包包可获得基础食材若干）',}",
  [3671] = "{id=3671,NameZh='入门食材包包·Ⅱ',Icon='item_59',Type=30,MaxNum=99999,SellPrice=100,Desc='稍微了解一些烹饪技巧的厨师，可以算是踏入料理界的大门了，现在开始可以尝试一些料理起来相对困难的食材。（开启包包可获得初阶食材若干）',}",
  [3672] = "{id=3672,NameZh='专家食材包包·Ⅲ',Icon='item_58',Type=30,MaxNum=99999,SellPrice=100,Desc='对火候和味道有了自己的理解，在食材处理方面也更加得心应手，可以向更高难度的食材发起挑战了。（开启包包可获得中阶食材若干）',}",
  [3673] = "{id=3673,NameZh='皇家食材包包·Ⅳ',Icon='item_57',Type=30,MaxNum=99999,SellPrice=100,Desc='深刻理解了大陆上绝大部分食材，在烹饪中显得游刃有余，已经没有什么食材算得上难搞了吧。（开启包包可获得高阶食材若干）',}",
  [3674] = "{id=3674,NameZh='勿忘初心食材包·Ⅴ',Icon='item_3620',Type=30,MaxNum=99999,SellPrice=100,Desc='站在料理界顶端的大厨，拥有将任何食材做成至上美味的实力，那么就请用这些食材尽情展示您的实力吧。（开启包包可获得顶级食材若干）',}",
  [3675] = "{id=3675,NameZh='初心烹饪礼盒·Ⅰ',Icon='item_3603',Type=30,MaxNum=99999,SellPrice=100,Desc='除了满足饱腹之欲外，初级的美食家意味着对味道有了一定的追求，试试品尝这几种常见的食物吧。（开启食盒可获得1星料理若干）',}",
  [3676] = "{id=3676,NameZh='入门烹饪礼盒·Ⅱ',Icon='item_3603',Type=30,MaxNum=99999,SellPrice=100,Desc='能够分辨出不同食物在味道和口感等方面的区别，可以尝试一些高级料理了。（开启食盒可获得2星料理若干）',}",
  [3677] = "{id=3677,NameZh='专家烹饪礼盒·Ⅲ',Icon='item_3604',Type=30,MaxNum=99999,SellPrice=100,Desc='对于品尝食物有了自己的见解，能够通过品尝食物在脑中还原料理过程，试着品鉴一些更高级的料理吧。（开启食盒可获得星3料理若干）',}",
  [3678] = "{id=3678,NameZh='皇家烹饪礼盒·Ⅳ',Icon='item_3604',Type=30,MaxNum=99999,SellPrice=100,Desc='在色香味的品鉴上都有了完备的标准，也能一针见血地指出烹饪中的问题，试试对这批高阶厨师烹饪的菜品进行品鉴吧。（开启食盒可获得4星料理若干）',}",
  [3679] = "{id=3679,NameZh='勿忘初心烹饪盒·Ⅴ',Icon='item_3602',Type=30,MaxNum=99999,SellPrice=100,Desc='在味觉享受的同时，亦能从美食中领悟制作者的情感，为了表彰最顶级的美食家，皇家料理协会收集了国内顶级大厨的拿手菜品在本食盒内。（开启食盒可获得5星料理若干）',}",
  [3680] = "{id=3680,NameZh='豪华全食材包包',Icon='item_3620',Type=30,MaxNum=99999,SellPrice=100,Desc='一个提供各等级食材的包包，有信心的厨师朋友就来挑战它吧！',}",
  [3681] = "{id=3681,NameZh='时间的礼物·单',Icon='item_3681',Type=30,Quality=3,MaxNum=99999,SellPrice=99,Desc='相片上艾波娜幸福地拥着一个丑陋的大块头，那便是时间魔物西罗诺。艾波娜丝毫不在意他的外表，眼神中满是爱意，嘴角微微的扬着，斜着眼看着西罗诺。拍摄这张照片的摄影师出卖了他们俩，被活生生的拔掉了眼睛和舌头永不见天日。',NoStorage=5,Feature=1,}",
  [3682] = "{id=3682,NameZh='时间的礼物·双',Icon='item_3682',Type=30,Quality=3,MaxNum=99999,SellPrice=99,Desc='一块被烧成炭黑色的金属怀表，实际是西罗诺自己的心脏，自从遇到了艾波娜，这颗本应波澜不惊的心脏便停止了跳动，他情愿时间永远停留在他们相遇的那一刻。西罗诺将这块怀表赠给了艾波娜，艾波娜被处死之前都一直藏在胸前的衣襟中，随着熊熊烈火，西罗诺怀表的表盘碎成了渣渣。',NoStorage=5,Feature=1,}",
  [3683] = "{id=3683,NameZh='B格猫福袋',Icon='item_3683',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='卡普拉公司为了感谢冒险者一直以来的支持，特推出本批次B格猫感恩福袋，打开后可获得华丽卡册×1、来自女武神的馈赠×2、尼伯龙根碎片×10。（本福袋每个账号每月限购3次）',}",
  [3684] = "{id=3684,NameZh='华丽卡册',Icon='item_3684',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='卡普拉公司神秘人士与埃米尔家族达成了商业合作，决定推出本款由埃米尔家族整理，卡普拉公司发行的华丽卡册。基于合作条款，本卡册仅随感恩福袋一起出售，开启可获得神秘卡片。（华丽卡册中开启的卡片可以解锁冒险手册图鉴）',Feature=1,}",
  [3685] = "{id=3685,NameZh='歉意盒子2.0',Icon='item_3654',Type=41,MaxNum=99999,SellPrice=100,Desc='谨以此箱子表达B格猫们深深的歉意！打开后有高概率产出一些高级的材料，还有只有从歉意箱子才能获得的歉意头饰。',Feature=1,}",
