  [3687] = "{id=3687,NameZh='蓝疯兔限定礼盒',Icon='item_3033',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='EP2.0宠物情人上线后可打开，打开后可获得疯兔蛋一枚和蓝疯兔皮肤一个。',Feature=1,}",
