  [3689] = "{id=3689,NameZh='好运扑满',Icon='item_3689',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='装有zeny的扑满，听说曾经被神秘力量加持过，所以里面的zeny个数会随着所有者当日的运气变化~（本道具每天可购买1次）',}",
  [3690] = "{id=3690,NameZh='来自女武神的馈赠',Icon='item_3690',Type=30,MaxNum=99999,SellPrice=100,Desc='使用后获得500点公会贡献。公会贡献可用于解锁【阿萨神碑】的节点。\n女武神赠予勇者爱之吻和战之力。',NoStorage=5,}",
