  [3708] = "{id=3708,NameZh='游园会福袋·下弦月',Icon='item_3707',Type=30,MaxNum=99999,SellPrice=20,Desc='月亮即将圆满，这份期待的心情，我和你一样。（使用后会获得这种对冒险有帮助的道具。）',NoStorage=5,}",
