  [3712] = "{id=3712,NameZh='回归冒险礼盒',Icon='item_3712',Type=30,Quality=2,MaxNum=99999,SellPrice=20,Desc='EP2.0宠物情人上线后可打开，打开后可获得疯兔蛋一枚和蓝疯兔皮肤一个。',NoStorage=5,}",
  [3713] = "{id=3713,NameZh='捣蛋鬼的糖果盒',Icon='item_3713',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='好吧好吧，拿走这个糖果盒，你们这些捣蛋鬼不要来捉弄我了（来自男爵阁下的糖果礼盒，可以获得万圣节时家庭中常见的糖果和点心若干）',NoStorage=5,}",
  [3714] = "{id=3714,NameZh='猫的报恩',Icon='item_550511',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='在猫猫中非常风靡的咸鱼干，如果它们愿意分享一条咸鱼干给你，你一定是对其相当重要之人。（诚心祈愿后使用，咸鱼干也可能带来意外之喜呢！）',NoStorage=5,}",
  [3715] = "{id=3715,NameZh='汪酱的忠贞',Icon='item_900004',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='emmmm…虽然肉已经被啃得一干二净，毕竟还是一根深受狗狗喜爱的大骨头，请阁下务必好好珍惜。（诚心祈愿后使用，大骨头也可能带来意外之喜呢！）',NoStorage=5,}",
  [3716] = "{id=3716,NameZh='双十一福袋',Icon='item_3707',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='卡普拉公司发行的双十一特供福袋，使用后可以获得zeny若干。（本福袋由杰克阁下代为发售）',NoStorage=5,}",
  [3717] = "{id=3717,NameZh='参战礼盒',Icon='item_111',Type=30,MaxNum=99999,SellPrice=100,Desc='王国为了鼓励各地的勇者参与到战斗的试练中，特地打造了这个礼盒，希望每个参加的成员都能获得奖赏。',NoStorage=5,}",
