  [3986] = "{id=3986,NameZh='蛋黄哥每日任务礼盒',Icon='item_3863',Type=30,MaxNum=99999,SellPrice=100,Desc='蛋黄哥赠送给冒险家的礼盒，打开之后必定获得以下道具中的一种：金质勋章*1、玛丝黛拉种子*1、来自公会的馈赠*10、锁链雷锭*2、莫拉硬币*1',}",
  [3987] = "{id=3987,NameZh='伯爵的万圣夜礼盒',Icon='item_3987',Type=30,MaxNum=99999,SellPrice=100,Desc='来自德古拉伯爵赠送的万圣夜礼盒，沉甸甸的，里面装的不会是血液吧！！！？？？~~~（开启后必定获得：万圣节南瓜*5、小恶魔曲奇*5、恶魔甜心*10，概率获得以下物品之一：祈祷晶片包*1、莫拉硬币*2、金质勋章*1、玛丝黛拉种子*1、女武神的馈赠*1，并有额外概率获得骨翼天使图纸*1）',}",
  [3988] = "{id=3988,NameZh='亡者冒险箱',Icon='item_111',Type=30,MaxNum=99999,SellPrice=100,Desc='打开箱子必定获得不定数量的七彩贝壳，并有概率获得焰之余烬，闪耀圣水，破斗篷的碎片，盾牌的碎片，小红帽，安眠木，黯魂粉尘，小型宠物经验药水，中型宠物经验药水，大型宠物经验药水等道具。',}",
  [3990] = "{id=3990,NameZh='火鸡盛宴礼盒',Icon='item_3871',Type=30,MaxNum=99999,SellPrice=100,Desc='隔着盒子都能闻到烤火鸡的香气！开启后必定获得5个「火鸡盛宴料理」，并获得以下道具中的随机一种：「玛丝黛拉种子」×1、「女武神的馈赠」×1、「金质勋章」×1、「莫拉硬币」×2、「祈祷晶片包」×1。',}",
  [3991] = "{id=3991,NameZh='魔女的礼物',Icon='item_3959',Type=30,MaxNum=99999,SellPrice=100,Desc='魔女赠送给欣赏之人的礼物',}",
  [3992] = "{id=3992,NameZh='魔女的心意',Icon='item_3960',Type=30,MaxNum=99999,SellPrice=100,Desc='魔女表达对喜爱之人的心意',}",
  [3993] = "{id=3993,NameZh='魔女的眼泪',Icon='item_3961',Type=30,MaxNum=99999,SellPrice=100,Desc='魔女流下为珍惜之人的眼泪',}",
  [3994] = "{id=3994,NameZh='学园豪华馈赠',Icon='item_3994',Type=30,MaxNum=99999,SellPrice=100,Desc='学园心动社的豪华馈赠，打开可以获得：水手服礼券*1、贝雷帽礼券*1、学园头饰礼券*1。礼券可用于兑换[学园心动社]系列时装及头饰哟~',Feature=1,}",
  [3995] = "{id=3995,NameZh='学园元气礼盒',Icon='item_3995',Type=30,MaxNum=99999,SellPrice=100,Desc='学园心动社推出的全新礼盒，打开可以获得1~10个秘银，并且有概率获得贝雷帽礼券*1、学园头饰礼券*1哟~',Feature=1,}",
  [3996] = "{id=3996,NameZh='神秘箱子5.0',Icon='item_3026',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='会散发出神秘蓝色光芒的旧箱子，打开的话好像有什么东西会跑出来似的。',Feature=1,}",
  [3997] = "{id=3997,NameZh='卡迪诺的课外书',Icon='item_3882',Type=30,MaxNum=99999,SellPrice=100,Desc='厨师卡迪诺的课外书 ，谁说厨师就只能看料理书了？打开必定获得5~15个古拉姆晶末，有概率获得华丽卡册*1。',Feature=1,}",
  [3998] = "{id=3998,NameZh='卡迪诺的珍藏品',Icon='item_3883',Type=30,MaxNum=99999,SellPrice=100,Desc='厨师卡迪诺的珍藏品，除了料理之外，卡迪诺似乎对卡片也很有兴趣。打开必定获得10~30个古拉姆晶末，必定获得卡册残页*1、精装卡册残页*1、华丽卡册*1中的一种，有概率获得稀有神谕卡片*1。',Feature=1,}",
  [3999] = "{id=3999,NameZh='冒险者召集行囊',Icon='item_3774',Type=48,MaxNum=1,SellPrice=100,Desc='欢迎回到RO，对新的世界感到迷茫了吗？冒险家协会为您准备了一份关于游戏世界的指引，快打开行囊查看吧！',NoStorage=5,ExistTimeType=1,ExistTime='2592000',Feature=1,}",
  [4000] = "{id=4000,NameZh='冒险的终点',Icon='item_4001',Type=41,Quality=4,UseMode=12,MaxNum=99999,SellPrice=100,Desc='魔导音乐唱片，可以到卡普拉公司新研制的音乐盒处点播歌曲。【这首曲子记录着古老的时代，关于勇者们将某个魔王击败的故事。并且，将由吟游诗人们继续传颂下去。】',NoStorage=5,Feature=1,}",
  [4001] = "{id=4001,NameZh='历战的勇者',Icon='item_4001',Type=41,Quality=4,UseMode=12,MaxNum=99999,SellPrice=100,Desc='魔导音乐唱片，可以到卡普拉公司新研制的音乐盒处点播歌曲。【勇敢的冒险者们呦~永远都不要因为眼前的艰难险阻而停下脚步，伴随着风，继续我们的旅程吧！】',NoStorage=5,Feature=1,}",
  [4002] = "{id=4002,NameZh='塔之下',Icon='item_4001',Type=41,Quality=3,UseMode=12,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='魔导音乐唱片，可以到卡普拉公司新研制的音乐盒处点播歌曲。【传说吉芬地下有一条通往无法知晓时代的遗迹，在那里，黑暗中总是有什么正在蠢蠢欲动，那片如今已成为禁忌之地也成为了冒险者的挑战目标。】',NoStorage=5,Feature=1,}",
  [4003] = "{id=4003,NameZh='斐扬的回忆',Icon='item_4001',Type=41,Quality=3,UseMode=12,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='魔导音乐唱片，可以到卡普拉公司新研制的音乐盒处点播歌曲。【听着岁月流逝的声音，听着树木年轮生长的声音，不知不觉中已打盹入睡了。梦中时常见面的奶奶，充满了思念，那是多么熟悉的面孔…】',NoStorage=5,Feature=1,}",
  [4004] = "{id=4004,NameZh='守护永恒的爱',Icon='item_4001',Type=41,Quality=3,UseMode=12,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='魔导音乐唱片，可以到卡普拉公司新研制的音乐盒处点播歌曲。【不管距离多么远，我们相信等到再次相会的那天。飞到你的身边，倾诉着我的思念。我和你的爱恋，LOVE…FOREVER】',NoStorage=5,Feature=1,}",
  [4005] = "{id=4005,NameZh='樱之季节',Icon='item_4001',Type=41,Quality=2,UseMode=12,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='魔导音乐唱片，可以到卡普拉公司新研制的音乐盒处点播歌曲。【听着这旋律，仿佛遥远东方国度的画面近在眼前。】',NoStorage=5,Feature=1,}",
  [4006] = "{id=4006,NameZh='十三月圣诞节',Icon='item_4001',Type=41,Quality=2,UseMode=12,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='魔导音乐唱片，可以到卡普拉公司新研制的音乐盒处点播歌曲。【凡人皆有一死，木乃伊现在学会了新的劲爆舞蹈，看来死亡国度的文艺水平还是相当高的。】',NoStorage=5,Feature=1,}",
  [4007] = "{id=4007,NameZh='艾尔贝塔',Icon='item_4001',Type=41,Quality=2,UseMode=12,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='魔导音乐唱片，可以到卡普拉公司新研制的音乐盒处点播歌曲。【“著名的商人国度有这样一个传说，大陆的某处存在着全是黄金构成的巨大昆虫，这也许是发笔横财的好机会。”于是，你相信传说吗？】',NoStorage=5,Feature=1,}",
  [4008] = "{id=4008,NameZh='梦想家的梦',Icon='item_4001',Type=41,Quality=2,UseMode=12,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='魔导音乐唱片，可以到卡普拉公司新研制的音乐盒处点播歌曲。【曾经渴求世界最大钻石之人的怨灵还徘徊在那里，即使他的这块石头被漂洋过海带到各地，那份诅咒依然围绕其上。】',NoStorage=5,Feature=1,}",
  [4009] = "{id=4009,NameZh='春天生活',Icon='item_4001',Type=41,Quality=2,UseMode=12,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='魔导音乐唱片，可以到卡普拉公司新研制的音乐盒处点播歌曲。【看似繁荣祥和的都市文明的背后，到底潜藏着多少的邪恶呢？】',NoStorage=5,Feature=1,}",
  [4010] = "{id=4010,NameZh='你在坠落',Icon='item_4001',Type=41,Quality=2,UseMode=12,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='魔导音乐唱片，可以到卡普拉公司新研制的音乐盒处点播歌曲。【其实皮里恩挺萌的，不是吗~】',NoStorage=5,Feature=1,}",
  [4011] = "{id=4011,NameZh='别来惹我',Icon='item_4001',Type=41,Quality=2,UseMode=12,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='魔导音乐唱片，可以到卡普拉公司新研制的音乐盒处点播歌曲。【酷热！干燥！眼前只有沙子！沙子！沙子！哦，天哪…你们不感觉热吗？】',NoStorage=5,Feature=1,}",
  [4012] = "{id=4012,NameZh='鲸鱼的梦',Icon='item_4001',Type=41,Quality=2,UseMode=12,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='魔导音乐唱片，可以到卡普拉公司新研制的音乐盒处点播歌曲。【一条做着深海和天空梦的鲸鱼。】',NoStorage=5,Feature=1,}",
  [4013] = "{id=4013,NameZh='我想念你',Icon='item_4001',Type=41,Quality=2,UseMode=12,MaxNum=99999,SellPrice=100,Desc='魔导音乐唱片，可以到卡普拉公司新研制的音乐盒处点播歌曲。【出发旅行前母亲曾对我说，哼着这首曲子便能回想起故乡，回想起亲人。如今这份思念依然回荡在旋律之中。】',NoStorage=5,Feature=4,}",
  [4014] = "{id=4014,NameZh='宝贝别哭',Icon='item_4001',Type=41,Quality=2,UseMode=12,MaxNum=99999,SellPrice=100,Desc='魔导音乐唱片，可以到卡普拉公司新研制的音乐盒处点播歌曲。【被银色包裹着的整个世界，在一年当中最特别的季节。你是否依然独自一人在灯光找不到的地方哭泣呢？】',NoStorage=5,Feature=4,}",
  [4015] = "{id=4015,NameZh='白色圣诞',Icon='item_4001',Type=41,Quality=2,UseMode=12,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='魔导音乐唱片，可以到卡普拉公司新研制的音乐盒处点播歌曲。【银白色的浪漫季节，和去年一样，靠在你的胸前，轻轻数着心跳声，这便是幸福之一呢~】',NoStorage=5,Feature=1,}",
  [4016] = "{id=4016,NameZh='银铃',Icon='item_4001',Type=41,Quality=4,UseMode=12,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='魔导音乐唱片，可以到卡普拉公司新研制的音乐盒处点播歌曲。【曾经的那段时光，飘雪的天空响彻着幸福的铃声，这是世界最初的回忆之一呢~你，是否还记得？】',NoStorage=5,Feature=1,}",
  [4017] = "{id=4017,NameZh='Ragnarok Title (Eternal Love Mix)',Icon='item_4001',Type=41,Quality=4,UseMode=12,MaxNum=99999,SellPrice=100,NoStorage=5,Feature=1,}",
  [4018] = "{id=4018,NameZh='ED',Icon='item_4001',Type=41,Quality=4,UseMode=12,MaxNum=99999,SellPrice=100,NoStorage=5,Feature=1,}",
  [4019] = "{id=4019,NameZh='奇迹再现',Icon='item_4019',Type=41,Quality=4,UseMode=12,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='正版授权！迪迦奥特曼片头曲，可以到卡普拉公司新研制的音乐盒处点播歌曲。绝版收藏品要珍惜使用哦~【熟悉的英雄旋律再次响起，有没有一种回到小时候的感觉？】',}",
  [4020] = "{id=4020,NameZh='永远的奥特曼',Icon='item_4020',Type=41,Quality=4,UseMode=12,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='正版授权！迪迦奥特曼片头曲，可以到卡普拉公司新研制的音乐盒处点播歌曲。绝版收藏品要珍惜使用哦~【我们终将长大，那些陪伴我们度过美好童年的英雄，却被定格在内心深处某个柔软的角落~】',}",
  [4021] = "{id=4021,NameZh='守护永恒的爱(孙燕姿)',Icon='item_4021',Type=41,Quality=4,UseMode=12,MaxNum=99999,SellPrice=100,Desc='孙燕姿倾情献唱，可以到卡普拉公司新研制的音乐盒处点播歌曲。【永恒像是光的弧线，串起每一个今天，爱是如何才能体会，初心是唯一秘诀！】',ExistTimeType=2,ExistTime='2020-04-29 05:00:00',Feature=1,}",
  [4024] = "{id=4024,NameZh='思念之花',Icon='item_4001',Type=41,Quality=4,UseMode=12,MaxNum=99999,SellPrice=100,Desc='这一朵花，无限地绽放开吧。现在，将它托付给你；今后，我将思念着你。',Feature=1,}",
