  [5032] = "{id=5032,NameZh='掠夺许可证',Icon='item_5032',Type=41,Quality=3,MaxNum=99999,SellPrice=100,Desc='野外魔物的掠夺许可证，使用后击杀的前85只魔物，掉落提升10倍，此物品每日最多使用3次，效果可叠加，对MINI和MVP无效。',Feature=1,}",
  [5033] = "{id=5033,NameZh='一袋Zeny',Icon='item_10000004',Type=30,Quality=2,MaxNum=99999,AuctionPrice=0,SellPrice=2000,Desc='装满Zeny的袋子，开启或者出售都能获得不少Zeny。',Feature=1,}",
  [5034] = "{id=5034,NameZh='信仰之证',Icon='item_5034',Type=62,Quality=2,MaxNum=99999,AuctionPrice=0,SellPrice=100,Desc='由公会管理中心颁发，可用于提升公会信仰的祝福等级，当信仰花费大于Zeny2000时自动消耗。',}",
  [5035] = "{id=5035,NameZh='幻想之证·银',Icon='item_5035',Type=62,Quality=5,MaxNum=99999,SellPrice=50,Desc='曾经【幻想马戏团】所发行的梦之旅的通用许可。拥有这个闪耀着光芒的象征，就能打开通向梦幻世界的大门了吧。而今已不再生效，可以将它作为历史的印记好好珍藏哦~',NoStorage=5,Feature=1,}",
  [5036] = "{id=5036,NameZh='幻想之证·金',Icon='item_5036',Type=62,Quality=5,MaxNum=99999,SellPrice=100,Desc='幻想马戏团的通用证明。（该道具暂未实装）',NoStorage=5,Feature=1,}",
  [5037] = "{id=5037,NameZh='第六感药水',Icon='item_52602',Type=40,MaxNum=99999,SellPrice=20,Desc='能发现地图上曼陀罗魔花种子的位置。',}",
  [5038] = "{id=5038,NameZh='曼陀罗魔花种子',Icon='item_52601',Type=62,MaxNum=99999,SellPrice=100,Desc='曼德拉种子身上掉落的特殊材料，有很高的价值',}",
  [5039] = "{id=5039,NameZh='锁链雷锭',Icon='item_5039',Type=46,Quality=3,MaxNum=99999,AuctionPrice=0,SellPrice=100,Desc='诸神用来捆绑邪恶之狼芬里尔的锁链，异常沉重和坚固。瓦尔哈拉的英灵们将它捆绑在身上，获得更好的锻炼效果。使用后，在野外加速消耗2倍战斗次数，获得2倍的经验和掉落，持续生效1000次，每日战斗次数耗尽后，暂停生效。不能与坠星陨铁叠加，效果同时存在时，优先消耗坠星陨铁。\n\n限制：对mini和mvp魔物无效',Feature=1,}",
  [5040] = "{id=5040,NameZh='卡普拉传送服务券',Icon='item_5040',Type=41,Quality=2,MaxNum=99999,SellPrice=1600,Desc='卡普拉公司的赠券，它曾经可帮助冒险者免去传送的费用。如今卡普拉公司已将传送服务免费提供给所有冒险者。使用此券，将兑换为Zeny*1600。',}",
  [5041] = "{id=5041,NameZh='卡普拉仓库服务券',Icon='item_5041',Type=41,Quality=2,MaxNum=99999,SellPrice=100,Desc='卡普拉公司的赠券，它曾经可帮助冒险者免去打开仓库的费用。如今卡普拉公司已将仓库服务免费提供给所有冒险者。使用此券，将兑换为Zeny*100。',}",
  [5042] = "{id=5042,NameZh='锁链德洛米',Icon='item_5042',Type=46,Quality=3,MaxNum=99999,SellPrice=100,Desc='诸神用来捆绑邪恶之狼芬里尔Fenrir的第二条锁链。使用后，1小时内获得5倍经验和掉落，同时会以2倍的速度进入战斗疲劳。此道具为「预言之地」测试服专用福利道具，感谢为我们抢先测试新内容的冒险者！如果你今天时间不多，可以使用这个道具。每日战斗疲劳后，暂停生效。\n\n限制：对mini和mvp魔物无效',Feature=1,}",
  [5043] = "{id=5043,NameZh='锁链格雷菲尔',Icon='item_5043',Type=46,Quality=3,MaxNum=99999,SellPrice=100,Desc='用猫的脚步声、石中的树根、女人的胡子、鱼的呼吸、熊的警觉、鸟的唾液制成的魔法锁链。使用后，1小时内获得4倍经验和掉率，普通人会以极快的速度进入战斗疲劳，如果你今天时间不多，可以使用这个道具。',Feature=1,}",
  [5044] = "{id=5044,NameZh='遗忘之水',Icon='item_5044',Type=41,Quality=4,MaxNum=99999,SellPrice=100,Desc='汇聚米德加尔特顶尖魔法的伟大产物，拥有遗忘之水的冒险者，可以前往罗兰处忘却之前的所有冒险技能，返还所有冒险技能点和Zeny。',Feature=1,}",
  [5045] = "{id=5045,NameZh='任务背包',Icon='item_5045',Type=65,MaxNum=1,SellPrice=100,NoSale=1,NoStorage=7,Feature=1,}",
  [5047] = "{id=5047,NameZh='料理收纳盒',Icon='item_5047',Type=65,MaxNum=1,SellPrice=100,NoSale=1,NoStorage=7,Feature=1,}",
  [5048] = "{id=5048,NameZh='鲁加租借券',Icon='item_5048',Type=41,UseMode=3025,MaxNum=99999,SellPrice=100,Desc='拥有了这张租借券，可以在普隆德拉的格拉蕾处租借到“逐风猎手”鲁加作为你忠实的伙伴！仅限【游侠】使用哦~',NoStorage=5,JobLimit={44},}",
  [5049] = "{id=5049,NameZh='卡仑租借券',Icon='item_5049',Type=41,UseMode=3025,MaxNum=99999,SellPrice=100,Desc='拥有了这张租借券，可以在普隆德拉的格拉蕾处租借到传说中的“永恒冰狼”卡仑作为你忠实的伙伴！仅限【游侠】使用哦~',NoStorage=5,JobLimit={44},}",
  [5050] = "{id=5050,NameZh='抗击魔潮入场券',Icon='item_5050',Type=41,MaxNum=99999,SellPrice=100,Desc='将这张稀有的券赠予魔物监视者，他会允许你能够多进入抗击魔潮两次，看起来像是个划算的生意，不过只能Base等级大于22级才可使用',Level=22,Delete=5050}",
