  [5128] = "{id=5128,NameZh='卡册残页',Icon='item_5128',Type=41,Quality=2,MaxNum=99999,SellPrice=10,ComposeID=14,Desc='由卡片爱好者埃米尔先生收集整理的《米德加尔特卡片大全》残页，因为年代久远，内页遗失殆尽，重新收集整理可是一项大工程呢~',Feature=1,}",
  [5129] = "{id=5129,NameZh='精装卡册的残页',Icon='item_3666',Type=41,Quality=3,MaxNum=99999,SellPrice=10,ComposeID=15,Desc='限量发行的精装版《米德加尔特卡片大全》，由埃米尔家族成员补全，收录了更多稀有卡片。因为历史原因同样只能收集到残页了。',Feature=1,}",
