  [5207] = "{id=5207,NameZh='罗纳德的特制硬币',Icon='item_5201',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='一枚刻着挑战者姓名的硬币，对于决斗俱乐部的人来说，这象征着荣誉与实力。',NoStorage=5,}",
  [5250] = "{id=5250,NameZh='克雷斯特皇家勋章',Icon='item_5250',Type=61,UseMode=4023,MaxNum=99999,SellPrice=1,Desc='可以在古城大厅的莫西处兑换珍贵的古代图纸。\n一枚象征着荣誉与繁荣的勋章，即使如今的废墟残骸是那么的狼狈也掩盖不了从点点滴滴中渗出的克雷斯特汉姆城当年的繁华,当你了解到一些真相后。',}",
  [5260] = "{id=5260,NameZh='银质勋章',Icon='item_5260',Type=61,UseMode=4107,MaxNum=99999,SellPrice=100,Desc='失去了光泽的银质勋章，使用后可以兑换金质勋章、尼伯龙根碎片和zeny',Feature=1,}",
  [5261] = "{id=5261,NameZh='金质勋章',Icon='item_5261',Type=62,Quality=2,MaxNum=99999,SellPrice=100,Desc='可用于解锁【阿萨神碑】上的节点，强化属性或技能。使用阿萨神碑道具开启界面。',NoStorage=5,Feature=1,}",
  [5262] = "{id=5262,NameZh='公会勋章',Icon='item_5262',Type=62,Quality=2,MaxNum=99999,SellPrice=100,Desc='一个金色勋章，可以用于公会石盘上。',NoStorage=5,}",
  [5263] = "{id=5263,NameZh='金质勋章·锁定',Icon='item_5263',Type=62,Quality=2,MaxNum=99999,SellPrice=100,Desc='可用于解锁【阿萨神碑】上的节点，强化属性或技能。使用阿萨神碑道具开启界面。',NoStorage=5,}",
  [5400] = "{id=5400,NameZh='任务手册',Icon='item_5549',Type=65,Quality=4,UseMode=2071,MaxNum=1,SellPrice=100,Desc='一本厚厚的故事书，冒险者在这里可以更清晰的看到自己在米德加尔特的旅程。',NoSale=1,NoStorage=7,Feature=1,}",
  [5500] = "{id=5500,NameZh='华丽金属',Icon='item_5500',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='象征着团结、勇敢、羁绊的美丽金属，蕴含着能够将世界各地勇者吸引过来的神秘力量。如果你愿意交给位于依斯鲁得的瓦尔基里，那么你就能开启一个公会，招募最值得信任的伙伴。',Feature=1,}",
  [5501] = "{id=5501,NameZh='阿萨神碑',Icon='item_5501',Type=65,Quality=4,UseMode=2053,MaxNum=1,SellPrice=100,Desc='使用阿萨神碑碎片可以阅读其中的深邃知识。这是一块印满卢恩符文的阿萨神碑的碎片，它将赐予拥有者无限的智慧与深邃的知识，对于人类而言，即使手掌大小的神碑碎片，其中蕴含的知识与力量也足够耗其一生来研究与掌握。',NoSale=1,NoStorage=7,Feature=1,}",
  [5502] = "{id=5502,NameZh='尼伯龙根碎片',Icon='item_12353',Type=41,Quality=2,MaxNum=99999,SellPrice=15,Desc='蕴含着强大的魔法力量，原本是打造神器的必备材料，可惜与现代的冶炼方式格格不入，渐渐被淘汰了，不过似乎可以兑换成别的什么东西？',Feature=1,}",
  [5503] = "{id=5503,NameZh='冒险丸子',Icon='item_5503',Type=61,MaxNum=99999,SellPrice=100,Desc='【宠物冒险】消耗道具，也可以快速完成委托看板。\n“冒险丸子，横扫饥饿！”',GetLimit={limit={[999]={20,20}},source={93},type=1},}",
  [5504] = "{id=5504,NameZh='宠物冒险指南',Icon='item_5504',Type=65,Quality=4,UseMode=2055,MaxNum=1,SellPrice=100,Desc='厚厚的本子上写满了关于大陆上各地的神奇故事，内容权威，科学，官方！比起指南更像是一本百科全书。',NoSale=1,NoStorage=5,Feature=1,}",
  [5505] = "{id=5505,NameZh='品客礼物票',Icon='item_5505',Type=41,MaxNum=99999,SellPrice=100,Desc='品客礼物盒里面开出的礼物票，可以在品客胡子商城兑换专属头饰和表情。',}",
  [5506] = "{id=5506,NameZh='师生系统图标',Icon='item_5506',Type=65,MaxNum=1,SellPrice=100,}",
  [5507] = "{id=5507,NameZh='冒险教程',Icon='item_5507',Type=44,MaxNum=99999,SellPrice=100,Desc='（24小时内仅能对Base等级<90级的同一名学生使用一次）冒险者协会指定教材，由导师向学生使用，使其获得大量的经验与经验加成。因为内容对于初心冒险者太过深奥，需要消耗大量的时间才能真正的理解教程中的知识。',ItemTarget={range=6,type=1},}",
  [5508] = "{id=5508,NameZh='教鞭',Icon='item_5508',Type=65,MaxNum=1,SellPrice=100,}",
  [5509] = "{id=5509,NameZh='敏捷提升指南',Icon='item_5509',Type=65,MaxNum=1,SellPrice=100,}",
  [5510] = "{id=5510,NameZh='智力提升指南',Icon='item_5510',Type=65,MaxNum=1,SellPrice=100,}",
