  [5514] = "{id=5514,NameZh='力量提升指南',Icon='item_5514',Type=65,MaxNum=1,SellPrice=100,}",
  [5515] = "{id=5515,NameZh='木天蓼的果实',Icon='item_5515',Type=40,MaxNum=99999,SellPrice=100,}",
  [5516] = "{id=5516,NameZh='B格猫福利券·I',Icon='item_5516',Type=41,Quality=4,UseMode=80,MaxNum=99999,SellPrice=100,Desc='可用于抽取普隆德拉“幻想创造器Ⅰ号”的奖励，每消耗30张福利券可以抽取一次。福利券不可与B格猫金币同时使用。\n卡普拉公司发行的特别福利券，用以酬谢守护米德加尔特的冒险者们。',Feature=1,Delete=5516}",
  [5517] = "{id=5517,NameZh='B格猫福利券·Ⅱ',Icon='item_5517',Type=41,Quality=4,UseMode=8061,MaxNum=99999,SellPrice=100,Desc='卡普拉公司发行的福利券，可以用于体验幻想创造器Ⅱ号（来自卡普拉工作人员的温馨提示：福利券不可与B格猫金币同时使用哟）',Feature=1,Delete=5517}",
  [5518] = "{id=5518,NameZh='B格猫福利券·Ⅲ',Icon='item_5518',Type=41,Quality=4,UseMode=82,MaxNum=99999,SellPrice=100,Desc='卡普拉公司发行的福利券，可以用于体验幻想创造器Ⅲ号（来自卡普拉工作人员的温馨提示：福利券不可与B格猫金币同时使用哟）',Feature=1,Delete=5518}",
  [5519] = "{id=5519,NameZh='扭蛋券',Icon='item_5519',Type=62,Quality=4,MaxNum=99999,SellPrice=100,Feature=1,Delete=5519}",
  [5520] = "{id=5520,NameZh='佣兵宅急便·委托',Icon='item_5520',Type=41,MaxNum=99999,SellPrice=100,Desc='曾经是快捷雇佣佣兵部队完成委托的道具券，随着科技的进步已经显得不太适用了，一些冒险丸子商人正在收购它！【这份陈旧的牛皮信封宛如一个誓言，“千百年来潜藏在黑暗中的究极死侍佣兵集团的象征，只要你肯花钱，貌似任何委托都能瞬间帮你完成...”当然~这个以前用来吓唬晚上不睡觉小孩子只是片面的传闻。迷之佣兵部队现在只为冒险者们的正义而服务。】',}",
  [5521] = "{id=5521,NameZh='古塔研究院·弹射器',Icon='item_5521',Type=41,MaxNum=99999,SellPrice=100,Desc='使用后可以让你直接开启恩德勒斯塔中，从第一层起，至曾经打过最高层中的任意层（但极限不会能超过70层），当然~只能维持到下次无限塔刷新前。',Delete=5521}",
  [5522] = "{id=5522,NameZh='圣歌教会·净化圣杯',Icon='item_5522',Type=41,MaxNum=99999,SellPrice=100,Desc='砸下圣杯，让圣水瞬间净化任意时空裂隙中的所有魔物。这曾是教会为了控制魔物而采用的临时手段，因为其效果的不稳定而被废除。现在可以用这个道具以合理的比价兑换成冒险丸子。',}",
  [5523] = "{id=5523,NameZh='赐福卷轴',Icon='item_5523',Type=44,MaxNum=99999,SellPrice=100,Desc='导师对学生使用后，可以使其获得[天赐]效果的神奇道具。因为稀少，这个道具只能由导师对他的学生使用。',}",
  [5524] = "{id=5524,NameZh='守护卷轴',Icon='item_5523',Type=44,MaxNum=99999,SellPrice=100,Desc='冒险者协会为了保护初心冒险者而制作的特殊道具，只能由导师向学生使用，能够使学生在短时间获得大量的属性加成，在导师不在的时候也能自由冒险！',ItemTarget={range=6,type=1},}",
  [5525] = "{id=5525,NameZh='七彩贝壳',Icon='item_5525',Type=61,Quality=3,UseMode=4019,MaxNum=99999,SellPrice=100,Desc='使用后可以开启商店，兑换各种宠物喂食道具。\n五颜六色的彩色小贝壳，颜色十分漂亮，很多魔物都会被色彩斑斓的东西吸引，而把这些贝壳当作宝贝。',Feature=1,}",
  [5526] = "{id=5526,NameZh='冒险者更名卡',Icon='item_5526',Type=41,UseMode=2057,MaxNum=99999,SellPrice=100,Desc='冒险者协会下发的空白更名卡，将喜欢的名字写在上面会召唤信鸽。信鸽会自动飞往普隆德拉，收到新名字的管理人员会帮忙修改名字哟~ღ',Feature=1,}",
  [5527] = "{id=5527,NameZh='公会更名卡',Icon='item_5527',Type=62,MaxNum=99999,SellPrice=100,Desc='寄往英灵殿的神圣卡片，如果想要修改公会名，可以将喜欢的名字写在卡片上寄给英灵们，他们会帮忙修改哟~ღ',Feature=1,}",
  [5528] = "{id=5528,NameZh='导师勋章',Icon='item_5528',Type=61,UseMode=4026,MaxNum=99999,SellPrice=100,Desc='可用于兑换导师商店内的稀有奖励。\n代表了奉献，付出与耐心的勋章，用于嘉奖辛勤指导初心冒险者的导师们的道具，',NoSale=1,Feature=1,}",
  [5529] = "{id=5529,NameZh='B格猫信用卡',Icon='item_5529',Type=65,Quality=4,UseMode=2059,MaxNum=1,SellPrice=100,Desc='打开后可以查看B格猫打赏积分的详细规则与积分收支记录。\n“信用卡就是用来刷刷刷的！”——普隆德拉富豪',NoSale=1,NoStorage=5,Feature=1,}",
  [5530] = "{id=5530,NameZh='攻击晶片',Icon='item_5530',Type=41,MaxNum=99999,SellPrice=100,Desc='战神托尔使用雷神之锤时迸发的火花，落入人间冷却后形成了蕴含战神力量的卡片，通过瓦尔基里可以将卡片的力量融合到冒险者意志里，使攻击力提高。',NoStorage=5,Feature=1,}",
  [5531] = "{id=5531,NameZh='防御晶片',Icon='item_5531',Type=41,MaxNum=99999,SellPrice=100,Desc='女神制作的愈合药膏从神域不小心流入人间后，被炼金术士制作成了具有女神守护能力的卡片。瓦尔基里可以将卡片的力量融合到冒险者身体里，帮助冒险者增强体质和防御能力。',NoStorage=5,Feature=1,}",
  [5532] = "{id=5532,NameZh='元素晶片',Icon='item_5532',Type=41,MaxNum=99999,SellPrice=100,Desc='元素小精灵挥舞翅膀时落下的光尘，落入普通的卡片上后，形成了极具元素亲和力的卡片。通过瓦尔基里的神力可以将这股力量融于冒险者的灵魂里，使冒险者更受元素的青睐。',NoStorage=5,Feature=1,}",
  [5533] = "{id=5533,NameZh='积分卡',Icon='item_5533',Type=65,Quality=4,UseMode=2053,MaxNum=1,SellPrice=100,Desc='使用阿萨神碑碎片可以阅读其中的深邃知识。这是一块印满卢恩符文的阿萨神碑的碎片，它将赐予拥有者无限的智慧与深邃的知识，对于人类而言，即使手掌大小的神碑碎片，其中蕴含的知识与力量也足够耗其一生来研究与掌握。',NoSale=1,NoStorage=5,Feature=1,}",
