  [5542] = "{id=5542,NameZh='打工穿梭器',Icon='item_5542',Type=65,Quality=4,UseMode=2063,MaxNum=1,SellPrice=100,Desc='想去哪就去哪的穿梭器，但这项暂时还不稳定的发明，目前只能让宠物穿梭去王国的各大场所。【这是王国内一项伟大的发明】',NoSale=1,NoStorage=5,}",
