  [5630] = "{id=5630,NameZh='宠物手册',Icon='item_5630',Type=65,Quality=4,UseMode=2073,MaxNum=1,SellPrice=100,Desc='宠物手册：宠物爱好者的福音！《宠物手册》是一本记载了最新宠物资料的魔法大全，不仅可以查看宠物的信息，还装载了宠物融合这一全新的伟大功能！——《卢恩皇家出版社》',NoSale=1,NoStorage=5,}",
  [5640] = "{id=5640,NameZh='宠物包裹',Icon='item_5640',Type=65,Quality=4,MaxNum=1,SellPrice=100,NoSale=1,NoStorage=7,Feature=1,}",
  [5650] = "{id=5650,NameZh='黑曜石魂晶',Icon='item_5650',Type=65,Quality=4,MaxNum=1,SellPrice=100,Desc='凝聚着瓦尔哈拉力量的神域圣器，曾经能吸收亡者气息并强化持有者的灵魂力量，甚至突破自身的巅峰！但是现在似乎已经失去了它的作用。',NoSale=1,NoStorage=7,Feature=1,Delete=5650}",
  [5660] = "{id=5660,NameZh='家具收纳盒',Icon='item_5660',Type=65,Quality=4,MaxNum=1,SellPrice=100,NoSale=1,NoStorage=7,}",
  [5661] = "{id=5661,NameZh='家园房产证',Icon='item_5661',Type=65,Quality=4,UseMode=2076,MaxNum=1,SellPrice=100,Desc='根据《特里斯坦大法典·第78章04条》：经审查核实，管理局准予登记该次申请的房产。此资格证是保护您合法拥有该房产的唯一凭据，请妥善保存。——卢恩王国·普隆德拉房产管理局',NoSale=1,NoStorage=7,}",
  [5662] = "{id=5662,NameZh='高原坚木',Icon='item_5662',Type=70,Quality=2,MaxNum=99999,SellPrice=100,Desc='由生长在艾因布洛克原野上的优质树木特殊加工而成，这种树木在其他地方并不多见，但在艾因布洛克原野上却随处可见。',}",
  [5663] = "{id=5663,NameZh='九界原石',Icon='item_5663',Type=70,Quality=3,MaxNum=99999,SellPrice=100,Desc='米德加尔特大陆诞生后最早存在的九界中的高能量矿石，产量十分稀少，由杰佩托家族在一次家具打造中尝试使用，发现经由原石影响的家具品质更加卓越，这之后便成为制作高级家具的必备物品。',}",
  [5664] = "{id=5664,NameZh='蓝图手册',Icon='item_5664',Type=65,Quality=4,UseMode=2077,MaxNum=1,SellPrice=100,Desc='巴洛克？哥特系？自然派？无论是舒心安适的幸福小窝，还是奢华尊贵的显赫豪宅，亦或是风格独特的个人空间，满足你的需求，就是我们的义务。',NoSale=1,NoStorage=7,}",
  [5670] = "{id=5670,NameZh='符文之匣',Icon='item_5670',Type=65,Quality=4,MaxNum=1,SellPrice=100,Desc='百年前由某位炼金大师制作，可以存储符文的魔法之匣。很久以前被人遗失在古迹中，等待着命运之人的再次开启。',NoSale=1,NoStorage=7,Delete=5670}",
  [5671] = "{id=5671,NameZh='符文背包',Icon='item_5671',Type=65,Quality=4,MaxNum=1,SellPrice=100,NoSale=1,NoStorage=7,Delete=5671}",
  [5672] = "{id=5672,NameZh='小符文背包',Icon='item_5672',Type=65,Quality=4,MaxNum=1,SellPrice=100,NoSale=1,NoStorage=7,Delete=5672}",
  [5673] = "{id=5673,NameZh='虚空刻刀',Icon='item_5673',Type=41,Quality=4,MaxNum=99999,SellPrice=100,Desc='将指定技能符文的任一激活条件改变为无限制。可以在【符文之匣】的【符文融炼】界面中消耗使用。\n符文专家贝恩随身携带的刻刀，平凡的外表中蕴含着不可思议的力量。',Delete=5673}",
  [5680] = "{id=5680,NameZh='旅行者笔记',Icon='item_5680',Type=65,Quality=4,UseMode=2075,MaxNum=1,SellPrice=100,Desc='样式古朴的小册子，页边微微有些泛黄，看起来有些年代了。里面用法术记录着大量魔物资料，涵盖了整个米德加尔特大陆。应该是某位旅行家四处游历写下的，对冒险者来说有重要的参考价值。',NoSale=1,NoStorage=7,}",
  [5681] = "{id=5681,NameZh='神谕镜鉴',Icon='item_5681',Type=65,Quality=4,UseMode=2079,MaxNum=1,SellPrice=100,Desc='在远古时代，为了对抗黑暗生物，减少灵性力量和神性力量的损耗，神灵们运用神谕宝石创造了能够存储灵性力量与神性力量的宝鉴，名为【神谕镜鉴】',NoSale=1,NoStorage=7,Delete=5681}",
  [5682] = "{id=5682,NameZh='不思议宠物袋',Icon='item_5682',Type=65,Quality=4,UseMode=2080,MaxNum=1,SellPrice=100,Desc='宠物协会最新推出的神奇道具，功能全面，使用便捷，帮助冒险者轻松孵化、养成、融合、管理所拥有的宠物。',NoSale=1,NoStorage=7,}",
  [5683] = "{id=5683,NameZh='证据手册',Icon='item_5683',Type=65,Quality=4,UseMode=8099,MaxNum=1,SellPrice=100,Desc='归纳汇总了各种证据信息的手册。玩家可以查阅此手册，快速复盘调查中发现的线索及人物档案。',NoSale=1,NoStorage=7,}",
  [5690] = "{id=5690,NameZh='好运币',Icon='item_5690',Type=41,Quality=4,MaxNum=99999,SellPrice=100,Desc='能够带来好运的古老金币，在【神谕副本】、【团队副本】、【亡者副本】、【公会副本】、【世界MVP】结算时消耗可以额外获得一份奖励',}",
