  [5799] = "{id=5799,NameZh='冒险大师宝箱',Icon='item_3770',Type=30,Quality=4,MaxNum=99999,SellPrice=100,Desc='每日的努力必有回报，而您正是天选的幸运儿！请收下这一份豪华的奖励~',}",
  [5800] = "{id=5800,NameZh='B格猫福利券·宴',Icon='item_5800',Type=41,Quality=4,UseMode=92,MaxNum=99999,SellPrice=100,Desc='可用于抽取普隆德拉“幻想创造器·宴”的奖励，每消耗30张福利券可以抽取一次。福利券不可与B格猫金币同时使用。\n卡普拉公司发行的特别福利券，用以酬谢守护米德加尔特的冒险者们。',Feature=1,Delete=5800}",
  [5802] = "{id=5802,NameZh='结婚证',Icon='item_5802',Type=166,Quality=4,MaxNum=1,SellPrice=100,Desc='命运的红线将两人系在一起，从此缔结良缘，花好月圆，欣燕尔之，此生不渝。谨订此约。',NoSale=1,NoStorage=5,Feature=1,}",
  [5803] = "{id=5803,NameZh='星界武器兑换券',Icon='item_5803',Type=61,Quality=4,UseMode=4005,MaxNum=99999,SellPrice=100,Desc='祝贺你，成为被命运选中的冒险家，请兑换自己想要的武器外观吧！',Feature=1,}",
  [5804] = "{id=5804,NameZh='炎魂武器兑换券',Icon='item_5804',Type=61,Quality=4,UseMode=4017,MaxNum=99999,SellPrice=100,Desc='哇！恭喜你唷，赶紧去兑换自己心仪的炎魂系列的武器外观吧!',}",
  [5805] = "{id=5805,NameZh='碎雪武器兑换券',Icon='item_5805',Type=61,Quality=4,UseMode=4018,MaxNum=99999,SellPrice=100,Desc='哇！恭喜你唷，赶紧去兑换自己心仪的碎雪系列的武器外观吧!',}",
  [5806] = "{id=5806,NameZh='斐扬3神器币',Icon='item_5806',Type=44,MaxNum=99999,SellPrice=100,Desc='斐扬3城守护者的奖励，可用来兑换琴和鞭的神器碎片',}",
  [5807] = "{id=5807,NameZh='10万额度兑换券',Icon='item_5807',Type=41,MaxNum=99999,SellPrice=100,Desc='幸运的冒险家，一张神奇的兑换券，使用后获得10万打赏积分！',Feature=1,}",
  [5808] = "{id=5808,NameZh='100万额度兑换券',Icon='item_5808',Type=41,MaxNum=99999,SellPrice=100,Desc='幸运的冒险家，一张神奇的兑换券，使用后获得100万打赏积分！',Feature=1,}",
  [5809] = "{id=5809,NameZh='1000万额度兑换券',Icon='item_5809',Type=41,MaxNum=99999,SellPrice=100,Desc='幸运的冒险家，一张神奇的兑换券，使用后获得1000万打赏积分！',Feature=1,}",
  [5810] = "{id=5810,NameZh='艾莉儿的赠礼',Icon='item_5810',Type=41,UseMode=4040,MaxNum=99999,SellPrice=100,Desc='“广阔的世界在等着你探索，我想你一定会需要它的！”音乐少女艾莉儿赠予你的特殊兑换券，使用后可以兑换到特别的礼物。',}",
  [5811] = "{id=5811,NameZh='骑士团的赠礼',Icon='item_5811',Type=41,UseMode=4041,MaxNum=99999,SellPrice=100,Desc='“以骑士团之名起誓！你是守护伙伴之盾，你是击破黑暗之刃。挑选一把武器然后用它履行你的誓言！”普隆德拉骑士团赠予你的特殊兑换券，使用后可以兑换到特别的礼物。',}",
  [5812] = "{id=5812,NameZh='圣恩会的赠礼',Icon='item_5812',Type=41,UseMode=4042,MaxNum=99999,SellPrice=100,Desc='“记住，你手中的武器只为正义挥动。”圣恩会赠予你的特殊兑换券，使用后可以兑换到特别的礼物。',}",
  [5813] = "{id=5813,NameZh='刺客公会的赠礼',Icon='item_5813',Type=41,UseMode=4043,MaxNum=99999,SellPrice=100,Desc='“你已经证明自己拥有足够的实力了，丢掉手里的玩具吧，挑一把真正的武器。”刺客公会赠予你的特殊兑换券，使用后可以兑换到特别的礼物。',}",
  [5814] = "{id=5814,NameZh='魔法学院的赠礼',Icon='item_5814',Type=41,UseMode=4044,MaxNum=99999,SellPrice=100,Desc='“魔导的力量就在你的身边，藏在你的每一次呼吸里，选择一份礼物吧，年轻人。”吉芬魔法学院赠予你的特殊兑换券，使用后可以兑换到特别的礼物。',}",
  [5815] = "{id=5815,NameZh='商会的赠礼',Icon='item_5815',Type=41,UseMode=4045,MaxNum=99999,SellPrice=100,Desc='“不管你再怎么谨慎小心，总有遇上麻烦的时候。所以，请收下我们为你准备的礼物”普隆德拉商会赠予你的特殊兑换券，使用后可以兑换到特别的礼物。',}",
  [5816] = "{id=5816,NameZh='武道馆的赠礼',Icon='item_5816',Type=41,UseMode=4046,MaxNum=99999,SellPrice=100,Desc='“施行武道的是人，不要忘记你的初心。”武道会赠予你的特殊兑换券，使用后可以兑换到特别的礼物。',}",
  [5817] = "{id=5817,NameZh='流氓公会的赠礼',Icon='item_5817',Type=41,UseMode=4047,MaxNum=99999,SellPrice=100,Desc='“热血，热血明白么？青春就应该这样！！！”流氓公会赠予你的特殊兑换券，使用后可以兑换到特别的礼物。',}",
  [5818] = "{id=5818,NameZh='克米莉娅的唇印',Icon='item_5818',Type=61,UseMode=4073,MaxNum=99999,SellPrice=10,Desc='来自超可爱女仆克米莉娅的唇印你可要小心收藏哦，要知道多少人想要都得不到呢！',}",
  [5819] = "{id=5819,NameZh='德图拉的纽扣',Icon='item_5819',Type=61,UseMode=4074,MaxNum=99999,SellPrice=10,Desc='衣装整洁是评价执事好坏的第一标准，这袖扣可以看出德图拉对主人的忠诚！！',}",
  [5820] = "{id=5820,NameZh='米勒的情书',Icon='item_5820',Type=61,UseMode=4075,MaxNum=99999,SellPrice=10,Desc='看完了这封情书，你还看不出来米勒对你的心意么？',}",
  [5821] = "{id=5821,NameZh='可可的魔法钥匙',Icon='item_5821',Type=61,UseMode=4076,MaxNum=99999,SellPrice=10,Desc='嘛哩嘛哩哄！这可是魔法少女可可的专属钥匙哦！据说钥匙有着神奇的力量，请妥善保管哦！',}",
  [5822] = "{id=5822,NameZh='伊斯菲尔的勋章',Icon='item_5822',Type=61,UseMode=4077,MaxNum=99999,SellPrice=10,Desc='伊斯菲尔家族是大陆上历史最悠久的执事家族，能收到他们家族的勋章，看来你是被他们家族认可之人呢！',}",
  [5823] = "{id=5823,NameZh='西西卡丽·蕾娜的图腾',Icon='item_5823',Type=61,UseMode=4078,MaxNum=99999,SellPrice=10,Desc='狐族是崇尚忠诚的种族，立下誓言绝不背叛，图腾是你和蕾娜之间的契约也是羁绊。',}",
  [5824] = "{id=5824,NameZh='西西卡丽·康娜的爪印',Icon='item_5824',Type=61,UseMode=4079,MaxNum=99999,SellPrice=10,Desc='执事是什么？要向主人展示自己的忠诚？那康娜按个爪印好了，康娜一定会乖乖听主人话的。',}",
  [5825] = "{id=5825,NameZh='星络的玫瑰',Icon='item_5825',Type=61,UseMode=4081,MaxNum=99999,SellPrice=10,Desc='烫金的玫瑰图腾在大陆上很是罕见，只有在仅剩的古籍中才有寥寥几字提到过关于这个图腾的故事，看来赠予你的人身份很不一般！',}",
  [5826] = "{id=5826,NameZh='执事兑换劵·孙燕姿',Icon='item_5826',Type=41,MaxNum=1,SellPrice=100,Desc='用心聆听爱的声音，跟随着音符的脚步去寻找那个身影，音乐精灵孙燕姿就在那里静静等待着你的到来！（要先开启执事功能哦！）',}",
  [5827] = "{id=5827,NameZh='遗失的乐章',Icon='item_5827',Type=61,UseMode=4082,MaxNum=99999,SellPrice=10,Desc='散落在米德加尔特各处的美妙乐章，听说有人在找寻它们，或许把收集到的乐章交给她是个不错的选择!',}",
  [5828] = "{id=5828,NameZh='执事的荣誉勋章',Icon='item_5828',Type=61,UseMode=4085,MaxNum=99999,SellPrice=10,Desc='可以在抉择之间与执事们交换各种道具材料。\n代表着执事无上荣耀的精美勋章，是执事们能力大小的体现。',}",
  [5829] = "{id=5829,NameZh='初心者的赠礼',Icon='item_5829',Type=41,UseMode=4086,MaxNum=99999,SellPrice=100,Desc='赛尼亚赠送的转职礼物，可以兑换一种进阶初心者使用的武器。',}",
  [5830] = "{id=5830,NameZh='名师之证',Icon='item_5830',Type=61,UseMode=4090,MaxNum=99999,SellPrice=100,Desc='可用于兑换导师商店内的稀有奖励。\n优秀的导师不仅充满了奉献精神，还拥有高超的授业技巧。用于嘉奖在教育事业上不断精进的导师们的奖章。',GetLimit={limit={[999]={900,0}},source={103},type=7},}",
  [5831] = "{id=5831,NameZh='魔物记录书',Icon='item_5831',Type=41,MaxNum=99999,SellPrice=100,Desc='此书是学者普鲁士进行多年魔物研究后的结晶，使用后立即获得一次最高级研究所通关奖励，不消耗次数与战斗时长。',Level=20,NoStorage=5,GetLimit={limit={[999]={7,0}},type=7},Feature=1,}",
  [5832] = "{id=5832,NameZh='坠星陨铁',Icon='item_5832',Type=46,MaxNum=99999,SellPrice=100,Desc='米德加尔特大陆最新发现的高能量反应物，研究表明，此反应物是神族遗留下来的强大原石，使用后，在野外加速消耗4倍战斗次数，获得4倍的经验和掉落，持续生效1000次，每日战斗次数耗尽后，暂停生效；不能与锁链雷锭叠加，效果同时存在时，优先消耗坠星陨铁。\n\n限制：对mini和mvp魔物无效',Feature=1,}",
  [5833] = "{id=5833,NameZh='宠物冒险券',Icon='item_5833',Type=41,MaxNum=99999,SellPrice=100,Desc='找不到出口的迷藏森林?鬼怪纵横的沉没之船？危机四伏的金字塔地下？再危险又怎样！真正的勇士一定会畅通无阻，勇往直前！宠物冒险时勾选使用，使本次宠物冒险不消耗时长且额外满足一项宠物能力（不可超过上限）。',NoStorage=5,GetLimit={limit={[999]={7,0}},type=7},Feature=1,}",
