  [6001] = "{id=6001,NameZh='魔王水晶',Icon='item_6001',Type=61,Quality=2,UseMode=4013,MaxNum=99999,SellPrice=100,Desc='魔王及麾下魔物掉落的能量水晶，充满了奇特的魔力，使用后可以打开魔王水晶商店。',}",
  [6002] = "{id=6002,NameZh='护卫奖章',Icon='item_6002',Type=61,Quality=2,UseMode=4021,MaxNum=99999,SellPrice=100,Desc='对冒险家在各种保卫活动中奋勇战斗的嘉奖，使用后可打开护卫奖章商店。',GetLimit={limit={[999]={30,0}},source={10,11,22,115},type=7,uniform_source=1},}",
  [6003] = "{id=6003,NameZh='魔导头盔',Icon='item_45657',Type=61,Quality=3,UseMode=4016,MaxNum=99999,SellPrice=100,Desc='神匠工坊邀请了卡普拉公司知名的服装设计艾诺斯，特地为【机匠】打造了这一套万能的魔导头盔，直接使用可以兑换十六种颜色的头盔，用来搭配机甲真是再好不过了~',NoSale=1,NoStorage=5,JobLimit={64},}",
  [6004] = "{id=6004,NameZh='卢恩古币',Icon='item_6004',Type=61,Quality=2,UseMode=4088,MaxNum=99999,SellPrice=100,Desc='使用后开启商店兑换稀有头饰。\n刻印着卢恩符文的古老硬币，据说每一枚都封印着一个失落的灵魂。也许有位来自黑夜的旅人正在收集它。',}",
  [6005] = "{id=6005,NameZh='芙洛拉星币',Icon='item_6005',Type=61,Quality=2,UseMode=4096,MaxNum=99999,SellPrice=100,Desc='可以在芙洛拉星币商店中兑换道具，直接使用即可开启商店。\n对冒险家在卡普拉保卫战、波利大乱斗和B格猫入侵活动中奋勇战斗的嘉奖。',GetLimit={limit={[999]={2000,0}},source={22},type=5},}",
  [6006] = "{id=6006,NameZh='友情之证',Icon='item_147',Type=61,Quality=2,UseMode=4199,MaxNum=99999,SellPrice=100,Desc='最终，你将会忘记每一次危险，每一个敌人以及每一个宝物，对于冒险者来说在旅途中遇到的伙伴才是最珍贵的，让人念念不忘的正是那份友情。\n在剩余奖励次数为0的前提下，协助有奖励次数的冒险者通关指定副本后可获取',GetLimit={limit={[999]={20,0}},type=6},}",
