  [6141] = "{id=6141,NameZh='深浓度竹露',Icon='item_6141',Type=40,Quality=4,MaxNum=99999,SellPrice=100,Desc='斐扬酒家的老板使用翠竹酿制的清酒，使用特殊方式提纯的高浓度饮品，饮用后能获得物理攻击增加20%的效果持续15分钟，效果不能与其他竹露叠加，死亡不影响效果，只能在PVP地图中使用。',}",
  [6142] = "{id=6142,NameZh='超大瓶艾草汁',Icon='item_6142',Type=40,Quality=4,MaxNum=99999,SellPrice=100,Desc='吉芬的魔药师使用艾草压榨出的青汁，豪饮一大口后能够获得魔法攻击增加20%的增益效果持续15分钟，效果不能与其他的艾草汁叠加，死亡不影响效果，只能在PVP地图中使用。',}",
  [6143] = "{id=6143,NameZh='波波利糖',Icon='item_6143',Type=40,Quality=4,MaxNum=99999,SellPrice=100,Desc='波波利形状的糖果，吃下去感觉整个人都被治愈了！食用后每秒恢复自身3%最大生命，持续120秒。冷却时间5分钟，只能在PVP地图中使用。',}",
  [6144] = "{id=6144,NameZh='火山绵绵冰',Icon='item_6144',Type=40,Quality=4,MaxNum=99999,SellPrice=100,Desc='克魔岛特产的火山绵绵冰，热辣又冰凉的双重能量，激发你的魔法潜能~食用后每秒恢复自身3%最大魔法，持续120秒。冷却时间5分钟，只能在PVP地图中使用。',}",
  [6145] = "{id=6145,NameZh='燃情咖啡豆',Icon='item_6145',Type=40,Quality=4,MaxNum=99999,SellPrice=100,Desc='艾尔帕兰的热卖商品。食用后会领悟到汹涌澎湃的思绪，使自己免疫地面魔法效果，持续15秒。冷却时间10分钟，只能在PVP地图中使用。',}",
  [6146] = "{id=6146,NameZh='勇气坚果',Icon='item_6146',Type=40,Quality=4,MaxNum=99999,SellPrice=100,Desc='罗比奥森林的百年传承，每一只松鼠的终极梦想。食用后使自己免于死亡，但同时无法进行攻击，持续7秒。',}",
  [6147] = "{id=6147,NameZh='黄金芭娜娜',Icon='item_6147',Type=40,Quality=4,MaxNum=99999,SellPrice=100,Desc='溜溜猴的珍藏，每三十年才诞生一根的绝世香蕉。食用后每秒持续驱散自身所有的减益效果，持续30秒。冷却时间10分钟，只能在PVP地图中使用。',}",
  [6148] = "{id=6148,NameZh='猫猫草拿铁',Icon='item_6148',Type=40,Quality=4,MaxNum=99999,SellPrice=100,Desc='用猫猫草浸泡十个小时后，倾情制作的超能特饮。食用后提升30%的物伤减免、魔伤减免、人形种族伤害减免，但这些属性上限限制为60%，持续10分钟。冷却时间30分钟，只能在PVP地图中使用。',}",
  [6200] = "{id=6200,NameZh='雷神之锤残片',Icon='item_6200',Type=44,MaxNum=99999,SellPrice=100,Desc='传说中的神器：雷神之锤的残片。通过收集一些稀有的材料与更多的残片，凭借远古的知识与传说中龙先生的技巧，或许能让它恢复往昔的模样。',NoStorage=5,}",
