  [6222] = "{id=6222,NameZh='安静的水波',Icon='item_6222',Type=44,MaxNum=99999,SellPrice=100,Desc='好天气在海边戏水时,海浪在脚底下骚弄你的脚,呈现在瓶子里面的映像。',NoStorage=5,}",
  [6223] = "{id=6223,NameZh='海浪雕像',Icon='item_6223',Type=44,MaxNum=99999,SellPrice=100,Desc='风大的天, 把波涛汹涌的海浪映像化,所做出来的雕塑品。',NoStorage=5,}",
  [6224] = "{id=6224,NameZh='空气雕像',Icon='item_6224',Type=44,MaxNum=99999,SellPrice=100,Desc='谁都不知道空气的形体,可是有一位工艺匠,感觉到空气的流通,所想象做出来的东西。',NoStorage=5,}",
  [6225] = "{id=6225,NameZh='巴吉利的愤怒',Icon='item_6225',Type=44,MaxNum=99999,SellPrice=100,Desc='召集战士时，巴吉利们愤怒的表情，有一位艺匠把它映像化处理，所做成的绝世雕塑品。',NoStorage=5,}",
  [6226] = "{id=6226,NameZh='天使翅膀羽毛',Icon='item_6226',Type=44,MaxNum=99999,SellPrice=100,Desc='据说是天使不小心掉了的翅膀羽毛，是否是真的呢是很难判别的。',NoStorage=5,}",
  [6227] = "{id=6227,NameZh='猫脚步声音',Icon='item_6227',Type=44,MaxNum=99999,SellPrice=100,Desc='把猫走路的脚步声音浓缩在一起，是一个不可相信的物品。',NoStorage=5,}",
  [6228] = "{id=6228,NameZh='女人的胡须',Icon='item_6228',Type=44,MaxNum=99999,SellPrice=100,Desc='搜集了些从女人身上长出来的胡须，一定是长的很像男性化的女人。',NoStorage=5,}",
  [6229] = "{id=6229,NameZh='石头的根',Icon='item_6229',Type=44,MaxNum=99999,SellPrice=100,Desc='在太古时代刚开始时，就有了石头的根，对路面上的石头，试着挖掘一下吧。',NoStorage=5,}",
