  [6232] = "{id=6232,NameZh='拷问器具',Icon='item_6232',Type=44,MaxNum=99999,SellPrice=100,Desc='古老时代的残忍工具，已经很久没被使用了。',NoStorage=5,}",
  [6233] = "{id=6233,NameZh='未知的铁齿轮',Icon='item_6233',Type=44,MaxNum=99999,SellPrice=100,Desc='不知用途的锯齿轮子,虽然一定能用在某个地方,不过谁都不知道这到底要用在那里是个大问题。',NoStorage=5,}",
