  [6256] = "{id=6256,NameZh='焰耀头盔残片',Icon='item_6256',Type=44,MaxNum=99999,SellPrice=100,Desc='传说中的神器：焰耀头盔残片。在众神决战中被遗落的残片，通过收集一些稀有的材料和更多的残片， 可以在芙特拉卡小姐那里，重新恢复往昔的光芒！',}",
  [6257] = "{id=6257,NameZh='守护之刚玉',Icon='item_6257',Type=44,MaxNum=99999,SellPrice=100,Desc='守护普隆德拉的意志化作的宝石，是将某些神器提升至四阶的必备材料。',}",
  [6258] = "{id=6258,NameZh='智慧之宝玉',Icon='item_6258',Type=44,MaxNum=99999,SellPrice=100,Desc='吉芬人民的求知之心化作的宝石，是将某些神器提升至四阶的必备材料。',}",
  [6259] = "{id=6259,NameZh='自由之魂玉',Icon='item_6259',Type=44,MaxNum=99999,SellPrice=100,Desc='斐扬人民对自由的向往化作的宝石，是将某些神器提升至四阶的必备材料。',}",
  [6260] = "{id=6260,NameZh='秩序之坚玉',Icon='item_6260',Type=44,MaxNum=99999,SellPrice=100,Desc='艾尔帕兰的人们对于守序的追求化作的宝石，是将某些神器提升至四阶的必备材料。',}",
  [6261] = "{id=6261,NameZh='格拉斯的统御号角',Icon='item_6261',Type=106,MaxNum=1,SellPrice=100,Desc='阿萨神之国中声音能响彻九界的号角。响时众神皆会俯首应召，因为无可违逆的寂灭终结之日已然降诞。\n使用后固定吟唱10秒，完整吟唱后将召唤在当前地图内的所有己方公会冒险者至身旁。\n只能在公会战地图中使用。公会战结束时，未使用的攻城神器将自动销毁。',ExistTimeType=11,}",
  [6262] = "{id=6262,NameZh='亚尔夫的圣辉之星',Icon='item_6262',Type=106,MaxNum=1,SellPrice=100,Desc='光精灵之国中高悬的治愈明星。精灵相信它昔照今照永照，然而永恒造物的宿命，便是见证永恒的终结。\n使用后每秒回复5米范围内友方目标MaxHp2%，包括华丽水晶和瓦尔基里哨塔，持续30秒。\n只能在公会战地图中使用。公会战结束时，未使用的攻城神器将自动销毁。',ExistTimeType=11,}",
  [6263] = "{id=6263,NameZh='米尔克的幻象魔戒',Icon='item_6263',Type=106,MaxNum=1,SellPrice=100,Desc='暗之国中锻造的幻象魔戒。有人奉若至宝，有人嗤之以鼻。智者？愚人？全凭持者的器量与能力而定。\n在公会战据点内使用后，当己方公会冒险者进入该据点时，将按3倍人数参与据点争夺判定，持续40秒。\n只能在公会战地图中使用。公会战结束时，未使用的攻城神器将自动销毁。',ExistTimeType=11,}",
  [6264] = "{id=6264,NameZh='约顿的群山之心',Icon='item_6264',Type=106,MaxNum=1,SellPrice=100,Desc='巨人国度连绵山脉的坚韧核心。然其只为已然坚强者而律动，盖因真正的力量只从内心中迸发。\n在公会战据点内使用后，当己方公会冒险者进入该据点时，MaxHp、物伤减免、魔伤减免增加30%，持续30秒。\n只能在公会战地图中使用。公会战结束时，未使用的攻城神器将自动销毁。',ExistTimeType=11,}",
  [6265] = "{id=6265,NameZh='尼弗尔的迷雾披风',Icon='item_6265',Type=106,MaxNum=1,SellPrice=100,Desc='雾之国边际封锁雾气的具象。冥界行人常常回首，未践之誓、未酬之志、未了之情，俱被茫茫大雾永世隔绝。\n在公会战据点内使用后，当前据点的快捷传送功能禁用15秒，期间若归属方变更则效果提前结束。\n只能在公会战地图中使用。公会战结束时，未使用的攻城神器将自动销毁。',ExistTimeType=11,}",
  [6266] = "{id=6266,NameZh='华纳的英灵秘酿',Icon='item_6266',Type=106,MaxNum=1,SellPrice=100,Desc='华纳神之国的祝佑蜜酒。世间尚存一位为正义而战的英灵，蜜酒便如勇气般永流不竭，如是不休。\n使用后，在本场公会战期间、任意公会战地图内的下一次图内复活附带减伤光环，使自身受到的最终伤害-90%，5米范围内的友方玩家目标减伤30%，持续15秒。\n只能在公会战地图中使用。公会战结束时，未使用的攻城神器将自动销毁。',ExistTimeType=11,}",
  [6300] = "{id=6300,NameZh='卡普拉MVP券Ⅰ',Icon='item_6300',Type=70,MaxNum=99999,SellPrice=100,Desc='在狄丝·瓦尔处完成任务后，可获得1个强身料理和300000Zeny',NoSale=1,NoStorage=5,}",
