  [6308] = "{id=6308,NameZh='执事兑换券·蕾娜',Icon='item_6309',Type=41,MaxNum=99999,SellPrice=250000,Desc='狐族女仆西西卡丽·蕾娜专用雇佣券，券上有着华丽的狐族标志，代表着狐族女仆蕾娜愿为主人奉上一切！（请前往普隆德拉皇宫更换对应的执事~）',Feature=1,}",
  [6309] = "{id=6309,NameZh='执事兑换券·星络',Icon='item_6308',Type=41,MaxNum=99999,SellPrice=250000,Desc='布满华丽花纹的雇佣券，彰显着星络的贵族身份，券的下方还有一排小字——（伊斯菲尔是个大笨蛋！）（请前往普隆德拉皇宫更换对应的执事~）',Feature=1,}",
  [6310] = "{id=6310,NameZh='执事兑换券·康娜',Icon='item_6309',Type=41,MaxNum=99999,SellPrice=250000,Desc='券上有一个可爱的狐狸爪印，是康娜的专属雇佣券，爪印可是康娜亲自按上去的哦~QWQ啵啵~（请前往普隆德拉皇宫更换对应的执事~）',Feature=1,}",
  [6311] = "{id=6311,NameZh='执事兑换券·伊斯菲尔 ',Icon='item_6308',Type=41,MaxNum=99999,SellPrice=250000,Desc='烫金的字体，古老的执事家族家徽，落款处\"伊斯菲尔敬上\"几个字代表着执事一族最高的荣耀！（请前往普隆德拉皇宫更换对应的执事~）',Feature=1,}",
  [6312] = "{id=6312,NameZh='执事兑换券·米勒',Icon='item_6308',Type=41,MaxNum=99999,SellPrice=50000,Desc='米勒的执事券不知道的还以为是哪个小孩子的情书，蓝色心形的卡片小心翼翼地写着“给我最爱的主人”。（请在EP5.0版本开放后，前往普隆德拉皇宫新增地图「抉择之间」更换对应的执事~）',Feature=1,}",
  [6313] = "{id=6313,NameZh='执事兑换券·可可',Icon='item_6309',Type=41,MaxNum=99999,SellPrice=50000,Desc='可可的执事券十分可爱，粉色的背景充满着少女心，券上的文字都是用魔法咒语写的，落款处还有个小扫把的图案~（请在EP5.0版本开放后，前往普隆德拉皇宫新增地图「抉择之间」更换对应的执事~）',Feature=1,}",
