  [6500] = "{id=6500,NameZh='亥神送福礼盒',Icon='item_6500',Type=30,MaxNum=99999,SellPrice=100,Desc='呼噜噜~猪年大吉！亥神送福喽~ \n开启后可获得“亥神礼赞”buff，持续1小时内击杀野外魔物获得Base、Job经验加成100%；随机获赠以下道具中的一种：「神谕之尘」×2、「神谕之晶」×2、「莫拉硬币」×2、「祈祷晶片包」×1、「女武神的馈赠」×2、「金质勋章」×2、「玛丝黛拉种子」×1。',Feature=1,}",
  [6501] = "{id=6501,NameZh='亥之红包',Icon='item_6501',Type=30,MaxNum=99999,SellPrice=100,Desc='恭喜发财！红包拿来！\n开启后可获得一定数量的zeny~',Feature=1,}",
  [6502] = "{id=6502,NameZh='亥神赐福',Icon='item_6502',Type=30,MaxNum=99999,SellPrice=100,Desc='呼噜~呼噜~福气到！呼噜~呼噜~霉运消！新的一年最好的祝福送给你！——来自全世界最可爱的亥神！\n开启后必定获得「B格猫皇家红包1.0」×3、「七彩贝壳」×100、「贺岁鞭炮」×20、「潇洒的B格猫随变箱 」×5、并有10%概率获赠「祥瑞赐福」×1。',Feature=1,}",
  [6503] = "{id=6503,NameZh='福猪喜钱',Icon='item_3869',Type=30,MaxNum=99999,SellPrice=100,Desc='喂喂喂！快和小福猪我说新年快乐！要不然我可不给你喜钱哦！',Feature=1,}",
  [6504] = "{id=6504,NameZh='B格猫守岁红包',Icon='item_6504',Type=30,MaxNum=99999,SellPrice=100,Desc='新的一年，作为大陆上最有钱的喵星人，本喵要给你们每个人都发守岁红包~喵呜~\n开启后必定获得「B格猫福利券·I」×30、「B格猫福利券·宴」×60，并随机获赠以下道具中的一种：「莫拉硬币」×10、「神谕之尘」×10、「神谕之晶」×10、「金质勋章」×5、「玛丝黛拉果实」×1、「祈祷晶片包」×5。',Feature=1,}",
  [6505] = "{id=6505,NameZh='一见钟情礼盒',Icon='item_3620',Type=30,MaxNum=99999,SellPrice=100,Desc='糟糕，是心动的感觉，我胸口的小鹿已经克制不住了！\n开启后必定获得「恋人絮语」×1，并随机获赠以下道具中的一种：「玛丝黛拉种子」×1、「莫拉硬币」×2、「金质勋章」×1、「祈祷晶片包」×1、「锁链雷锭」×2、「冒险丸子」×100。',Feature=1,}",
  [6506] = "{id=6506,NameZh='万家灯火宝箱·金',Icon='item_3770',Type=30,MaxNum=99999,SellPrice=100,Desc='世界上最美好的画面，莫过于在万家灯火中，看到她的蓦然回首。\n开启后必定获得Zeny ×8,888、「元宵料理」×5、「月之兔·天涯」×1、「月之兔·海角」×1，并随机获赠以下道具中的一种：「玛丝黛拉种子」×1、「冒险丸子」×100、「金质勋章」×1、「祈祷晶片包」×1、「女武神的馈赠」×1、「锁链雷锭」×2。\n（PS：月之兔是可永久使用的珍藏玩具，活动期间只能拿到一个哦~）',Feature=1,}",
