  [6594] = "{id=6594,NameZh='拼多多限定初心者礼包',Icon='item_710044',Type=30,MaxNum=99999,SellPrice=100,Desc='拼多多限定初心者礼包，拼团大优惠哦~ 开启后获得：Zeny×270000、「锁链雷锭」×10、「神秘佣兵券」×10、「暖心料理」×10、「波利成长秘药」×1。',Feature=1,Delete=6594}",
  [6595] = "{id=6595,NameZh='拼多多限定庆典礼包',Icon='item_3844',Type=30,MaxNum=99999,SellPrice=100,Desc='拼多多限定庆典礼包，拼团大优惠哦~\n开启后获得「莫拉硬币」×10、「B格猫福利券·宴」×30，并随机获赠Zeny×1,000,000~2,000,000。',Feature=1,Delete=6595}",
  [6597] = "{id=6597,NameZh='黄金勇气宝箱',Icon='item_3770',Type=30,MaxNum=99999,SellPrice=100,Desc='为了表彰你在此次战役中的杰出表现而特意颁发的礼包，打开之后可以获得「迷你梦罗克限定皮肤」×1、「梦罗克典藏头像」×1、「梦罗克之影」×1',Feature=1,}",
  [6598] = "{id=6598,NameZh='白银勇气宝箱',Icon='item_3760',Type=30,MaxNum=99999,SellPrice=100,Desc='为了表彰你在此次战役中的杰出表现而特意颁发的礼包，打开之后可以获得「梦罗克典藏头像」×1、「梦罗克之影」×1',Feature=1,}",
  [6599] = "{id=6599,NameZh='梦罗克典藏头像',Icon='item_51373',Type=30,MaxNum=99999,SellPrice=100000,Desc='使用之后可以解锁「梦罗克典藏头像」，如果同一帐号下已有角色解锁该头像，那就只能卖商店咯~',Feature=1,}",
  [6600] = "{id=6600,NameZh='波利祝福礼盒',Icon='item_6600',Type=30,MaxNum=99999,SellPrice=100,Desc='这是波利为了感谢冒险者的帮助，特意准备的礼盒。虽然不大，但满满都是祝福的心意。\n开启后必定获得「波利庆典奖章」*5、「波利成长秘药」*1，并可以随机获得以下道具中的一种：「七彩贝壳」*100、「玛丝黛拉种子」*1、「冒险丸子」*50、「7级天赋果实」*1',}",
  [6601] = "{id=6601,NameZh='桃花朵朵波利礼盒',Icon='item_6601',Type=30,MaxNum=99999,SellPrice=100,Desc='具有早春气息的礼盒，上面印着桃花的图案，十分精巧可爱。据说里面存放着波利珍藏的宝物！\n开启后获得「神谕之晶」x2~5、「神谕之尘」x3~6。',}",
  [6602] = "{id=6602,NameZh='落樱纷纷波利礼盒',Icon='item_6602',Type=30,MaxNum=99999,SellPrice=100,Desc='具有早春气息的礼盒，上面印着樱花的图案，唯美又梦幻。据说是从古老的大树根下挖出来的！\n开启后获得「莫拉硬币」x12~25。',}",
  [6603] = "{id=6603,NameZh='春日庆典礼盒',Icon='item_6603',Type=30,MaxNum=99999,SellPrice=100,Desc='来自春日庆典的小礼物，珍藏着哥布灵们的祝福心意。\n开启后随机获赠「强化精华Ⅰ」×4~6、「强化精华Ⅱ」×4~6、「强化精华Ⅲ」×4~6，并有0.1%概率获赠限定坐骑「宝石公爵」×1~',Feature=1,}",
  [6604] = "{id=6604,NameZh='新世界愿景礼盒',Icon='item_6604',Type=30,MaxNum=99999,SellPrice=100,Desc='来自另一个世界的宝藏，里面满是对爱与希望的祝愿。\n开启后必定获得「新世界战斗药水」×1，并随机获赠以下道具中的一种：Zeny ×50,000、「铝」×4、「神之金属」×4、「祈祷晶片包」×1、「莫拉硬币」×4、「玛丝黛拉种子」×1、「神谕之尘」×4、「神谕之晶」×4、「B格猫福利券」×10。',Feature=1,}",
  [6605] = "{id=6605,NameZh='波利庆典福袋',Icon='item_6605',Type=30,MaxNum=99999,SellPrice=100,Desc='随着波利庆典的顺利举行，波利们邀请冒险者一起来狂欢！\n开启后必定获得：跳跳波利头饰*1、魔力卡册*1、超大型JOB药水*100、Zeny *1,000,000。',Feature=1,}",
  [6606] = "{id=6606,NameZh='米德加尔特的初遇',Icon='item_6606',Type=30,MaxNum=99999,SellPrice=100,Desc='初遇你，仿若微风拂过一般温暖绵长，期待着我们的未来会拥有更美好的篇章——米德加尔特大陆赠予亲爱的你',Feature=1,}",
  [6607] = "{id=6607,NameZh='米德加尔特的回忆',Icon='item_6607',Type=30,MaxNum=99999,SellPrice=100,Desc='回忆你，和你在一起的时光似流水般飞逝，但你的一举一动都深深的刻画在我的脑海里，挥之不去。——米德加尔特大陆赠予亲爱的你',Feature=1,}",
  [6608] = "{id=6608,NameZh='哥布灵福袋',Icon='item_3871',Type=30,MaxNum=99999,SellPrice=100,Desc='神秘的小袋子。里面塞满了哥布灵的私藏，是不可思议的礼物。只有命中注定的冒险家可以打开。\n开启后必定获得「祈祷晶片包」×1，并随机获赠以下道具中的一种：「金质勋章」×1、「来自公会的馈赠」×5。',Feature=1,}",
  [6609] = "{id=6609,NameZh='里希塔乐冒险箱',Icon='item_111',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='打开箱子必定获得不定数量的七彩贝壳，并有概率获得邪恶之心，混沌金属，勇士的意志，破斗篷的碎片，盾牌的碎片，小红帽，发霉的金币，腐化的吊坠，小型宠物经验药水，中型宠物经验药水，大型宠物经验药水等道具。',}",
  [6610] = "{id=6610,NameZh='神秘箱子6.0',Icon='item_3026',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='会散发出神秘蓝色光芒的旧箱子，打开的话好像有什么东西会跑出来似的。',}",
  [6611] = "{id=6611,NameZh='黄木礼盒',Icon='item_3661',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='一份神秘的礼盒。散发着木质的清香，四周包裹的金属已经有些陈旧了。开启后可以得到一定贡献。',NoStorage=5,}",
  [6612] = "{id=6612,NameZh='秘银礼盒',Icon='item_3662',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='一份神秘的礼盒。有着美丽的银色光泽，或许是什么人故意留下的。开启后可以得到很多贡献。',NoStorage=5,}",
  [6613] = "{id=6613,NameZh='流金礼盒',Icon='item_3663',Type=30,Quality=4,MaxNum=99999,SellPrice=100,Desc='一份神秘的礼盒。闪烁着耀眼的金色，不知被谁悄悄塞在了你的包里。“谢谢你一直陪伴在我们的身边！”开启后可以得到大量贡献，有几率开出金质勋章哦~',NoStorage=5,}",
  [6614] = "{id=6614,NameZh='梦想之音礼盒',Icon='item_6614',Type=30,MaxNum=99999,SellPrice=100,Desc='爱与希望的歌姬将她的心意藏于礼盒中，愿收获之人皆能走向幸福。“祝愿你旅途中见到的天空，如最初的梦想一般美好辽阔……”',}",
  [6615] = "{id=6615,NameZh='初心冒险礼包',Icon='item_3863',Type=30,MaxNum=99999,SellPrice=100,Desc='我相信刚来到冒险世界的你一定会需要它的，使用后获得冒险丸子×300，乐园币×300。',}",
  [6616] = "{id=6616,NameZh='初心奇遇礼包',Icon='item_3864',Type=30,MaxNum=99999,SellPrice=100,Desc='呼呼，冒险就是一场奇遇之旅，带上它向着未知的旅程前进吧！使用后获得七彩贝壳×500,五级天赋果实×5。',}",
  [6617] = "{id=6617,NameZh='暖心成长礼盒',Icon='item_3994',Type=30,MaxNum=99999,SellPrice=100,Desc='咕噜噜……肚子饿啦？快点打开它，里面有你想要的美味料理哦！使用后获得暖心料理×10，料理兑换券×5。',}",
  [6618] = "{id=6618,NameZh='精炼成长礼盒',Icon='item_3854',Type=30,MaxNum=99999,SellPrice=100,Desc='想要提升装备武器的力量么，快用这些稀有金属去精炼吧！使用后获得神之金属×30，铝×30。',}",
  [6619] = "{id=6619,NameZh='勇者勋章礼盒',Icon='item_3838',Type=30,MaxNum=99999,SellPrice=100,Desc='年轻的勇士哦！这枚金质勋章送给付出巨大贡献的你！感谢你守护这片大陆！使用后获得金质勋章×8，贡献×2400。',}",
  [6620] = "{id=6620,NameZh='附魔大秘宝',Icon='item_3865',Type=30,MaxNum=99999,SellPrice=100,Desc='这是附魔大师猫小友从猫猫岛带来的秘宝，使用后可以获得莫拉硬币×30。',}",
  [6621] = "{id=6621,NameZh='女武神的馈赠',Icon='item_3855',Type=30,MaxNum=99999,SellPrice=100,Desc='这是女武神瓦尔基里赐予冒险者的荣耀！使用后获得祈祷晶片包×5。',}",
  [6622] = "{id=6622,NameZh='英雄勋章礼盒',Icon='item_3977',Type=30,MaxNum=99999,SellPrice=100,Desc='你的名字即是英雄的名字，感谢你为这片大陆的付出！我的英雄！使用后获得尼伯龙根碎片×100。',}",
  [6623] = "{id=6623,NameZh='神谕之礼',Icon='item_700019',Type=30,MaxNum=99999,SellPrice=100,Desc='是神的指引，让你成为了这片的大陆的守护者，你一定要坚定信念勇往直前哦！使用后获得神谕之尘×8，神谕之晶×12。',}",
  [6624] = "{id=6624,NameZh='初心秘银礼盒',Icon='item_3976',Type=30,MaxNum=99999,SellPrice=100,Desc='想要提升自己的实力，一定不能缺少的东西就是秘银哦，打开礼盒后可以获得秘银×15。',}",
  [6625] = "{id=6625,NameZh='国王波利的馈赠',Icon='item_3994',Type=30,MaxNum=99999,SellPrice=100,Desc='波利~波利~这可是本国王赐予你的礼物哦！好好珍惜哦，冒险者！使用可以获得华丽卡册×1，国王波利的恩惠×3。',}",
  [6626] = "{id=6626,NameZh='成长历练必备礼盒',Icon='item_146561',Type=30,MaxNum=99999,SellPrice=100,Desc='冒险者的道路上一定不能缺少历练，这个礼盒就是为了锻炼冒险者而生的！使用后可以获得血迹树枝×8。',}",
  [6627] = "{id=6627,NameZh='光影的秘密',Icon='item_3959',Type=30,MaxNum=99999,SellPrice=100,Desc='光影交织的背后，隐藏着黑暗秘密……打开后获得坠星陨铁×1，zeny×10000，乐园币×200，神秘箱子6.0×1',}",
  [6628] = "{id=6628,NameZh='地下的真相',Icon='item_3960',Type=30,MaxNum=99999,SellPrice=100,Desc='隐秘的地下研究，掩埋着痛苦真相……打开后获得金质勋章×1，坠星陨铁×2，zeny×20000，乐园币×500，神秘箱子6.0×1',}",
