  [6732] = "{id=6732,NameZh='《冒险：从入门到精通》',Icon='item_6732',Type=65,Quality=5,MaxNum=1,SellPrice=100,Desc='学院出版社的畅销之作，帮助无数青涩冒险者走向人生巅峰。这本书不仅能为你解答冒险中的疑问，还为你罗列出一系列能使你变强的挑战目标。完成所有目标后，将其交给学院的帕普金先生，用以兑换豪华家具：木马·蓝光琉璃。',NoSale=1,NoStorage=7,}",
  [6734] = "{id=6734,NameZh='阿萨神碑解锁券·Ⅰ',Icon='item_6734',Type=41,Quality=2,MaxNum=99999,SellPrice=100,Desc='此券可以点亮阿萨神碑的碎片节点。使用后可以破译阿萨神碑上的基础卢恩符文部分。使用者可开启随机的阿萨神碑节点而获得属性成长。使用所有神碑解锁券即可点亮阿萨神碑三转阶段前的所有节点，当前已点亮的加点会返还成对应的绑定·金质勋章和绑定·贡献。',NoSale=1,Delete=6734}",
