  [6754] = "{id=6754,NameZh='闪耀的符文石兑换券',Icon='item_6754',Type=61,Quality=3,UseMode=4123,MaxNum=99999,SellPrice=100,Desc='闪耀符文光辉的卡片。使用后可兑换一枚指定的S级符文。（不包括英雄职业的符文）',Delete=6754}",
  [6755] = "{id=6755,NameZh='瓦特阿尔凡尘',Icon='item_6755',Type=62,Quality=2,MaxNum=99999,SellPrice=100,Desc='【上古遗物重塑】的素材，在普隆德拉的”诺安“处重塑上古遗物可以使它拥有更好的属性加成。\n侏儒之国特有的尘埃，由普通神器分解而成，具备强大的神力。',NoStorage=5,Feature=1,Delete=6755}",
  [6756] = "{id=6756,NameZh='瓦特阿尔仙尘',Icon='item_6756',Type=62,Quality=3,MaxNum=99999,SellPrice=100,Desc='【上古遗物重塑】的顶级素材，在普隆德拉的”诺安“处重塑上古遗物可以使它拥有更好的属性加成。\n侏儒之国特有的尘埃，由高级神器分解而成，具备强大的神力。',Feature=1,Delete=6756}",
  [6757] = "{id=6757,NameZh='月之冰晶',Icon='item_3959',Type=30,MaxNum=99999,SellPrice=100,Desc='火之国蓝色火焰在寒冷中凝结而成的冰晶。打开后获得Zeny*10000、乐园币*200、坠星陨铁*1、神秘箱子7.0*1。',}",
  [6758] = "{id=6758,NameZh='月之辉光',Icon='item_3960',Type=30,MaxNum=99999,SellPrice=100,Desc='月亮的辉光，指引着前进的路途。打开后获得Zeny*30000、乐园币*500、祈祷晶片包*2、缚能之印*1、神秘箱子7.0*1。',}",
  [6759] = "{id=6759,NameZh='月之回响',Icon='item_3961',Type=30,MaxNum=99999,SellPrice=100,Desc='在静谧的月亮上，许下的愿望是否能得到回应？使用后获得Zeny*30000、缚能之印*6、祈祷晶片包*2、华丽卡册*1、神秘箱子7.0*1。',}",
  [6760] = "{id=6760,NameZh='勇气纹章',Icon='item_6760',Type=41,MaxNum=1,SellPrice=100,Desc='勇气赋予了无畏的力量。纹章激发波姬的勇气，使得波姬在揍敌人时更加果断坚决……并且疼。',NoSale=1,NoStorage=5,}",
  [6761] = "{id=6761,NameZh='智慧纹章',Icon='item_6761',Type=41,MaxNum=1,SellPrice=100,Desc='智慧赋予了洞察的明眸。似乎它能让波姬变得更聪明了，希望这不是一时的错觉？',NoSale=1,NoStorage=5,}",
  [6762] = "{id=6762,NameZh='神佑纹章',Icon='item_6762',Type=41,MaxNum=1,SellPrice=100,Desc='神灵赐下了宠爱的证明。当面对拥有这个纹章的波姬时，连魔物都开始不敢招惹她。',NoSale=1,NoStorage=5,}",
  [6763] = "{id=6763,NameZh='生命纹章',Icon='item_6763',Type=41,MaxNum=1,SellPrice=100,Desc='自然给予了生存的意义。波姬比以前更能吃能睡能跑能跳，身体也更壮——不，是更健康了。啊哈哈哈哈。',NoSale=1,NoStorage=5,}",
  [6764] = "{id=6764,NameZh='破坏纹章',Icon='item_6764',Type=41,MaxNum=1,SellPrice=100,Desc='太阳带来了冷酷的赠礼。随着战斗经验的积累，波姬越来越会一针见血、抓人痛脚了。物理意义的。',NoSale=1,NoStorage=5,}",
  [6765] = "{id=6765,NameZh='铁壁纹章',Icon='item_6765',Type=41,MaxNum=1,SellPrice=100,Desc='月亮献上了静默的守护。波姬对疼痛和伤害的耐受力提高了，这可能从侧面说明她脸皮更厚了。对不起，开个玩笑。',NoSale=1,NoStorage=5,}",
  [6766] = "{id=6766,NameZh='铜制钥匙',Icon='item_may1',Type=160,MaxNum=99999,SellPrice=100,Desc='普普通通的钥匙。不知道可以打开哪道门？',}",
  [6767] = "{id=6767,NameZh='特制钥匙',Icon='item_may2',Type=160,MaxNum=99999,SellPrice=100,Desc='形状有点奇怪的钥匙。看起来像是为了某种门特别锻造的。',}",
  [6768] = "{id=6768,NameZh='拾光邀请函',Icon='item_6768',Type=41,Quality=3,UseMode=31200,MaxNum=99999,SellPrice=100,Desc='可用于抽取普隆德拉“拾光许愿机”的奖励，每消耗30张邀请函可以抽取一次。邀请函不可与B格猫金币同时使用。拾光许愿机中包含往期幻想创造器I号、幻想创造器·宴中的奖励。',Delete=6768}",
  [6769] = "{id=6769,NameZh='头饰扭蛋券',Icon='item_6769',Type=41,Quality=3,MaxNum=99999,SellPrice=100,Delete=6769}",
  [6770] = "{id=6770,NameZh='装备扭蛋券',Icon='item_6770',Type=41,Quality=3,MaxNum=99999,SellPrice=100,Delete=6770}",
  [6771] = "{id=6771,NameZh='重逢之证',Icon='item_6771',Type=61,Quality=2,UseMode=31200,MaxNum=99999,SellPrice=100,Desc='可以用于兑换时光典藏商店中的头饰与时装。\n“奇妙的命运将让我们再次相逢！”',Delete=6771}",
  [6772] = "{id=6772,NameZh='镜面',Icon='item_12929',Type=160,MaxNum=99999,SellPrice=100,Desc='一整块镜子。大小正好符合某处……啊，小心锋利的边缘哦！',}",
  [6773] = "{id=6773,NameZh='阿斯加德冒险箱',Icon='item_111',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='打开箱子必定获得不定数量的七彩贝壳，并有概率获得无色泪滴，浮梦光子，蛇妖之瞳，燃烧的蛇鳞，冰晶琉璃，虚无之骸，风花铃铛，雪覆花，小型宠物经验药水，中型宠物经验药水，大型宠物经验药水等道具。',}",
