  [6786] = "{id=6786,NameZh='干净的水',Icon='item_5020',Type=160,MaxNum=99999,SellPrice=100,Desc='清澈，新鲜，不过也只是一瓶水而已。植物的必需品。',}",
  [6787] = "{id=6787,NameZh='肥沃土壤',Icon='item_12901',Type=160,MaxNum=99999,SellPrice=100,Desc='湿润粘腻的土壤，看起来肥力充足。证据就是它散发出的味道……',}",
  [6788] = "{id=6788,NameZh='夏基的手记Ⅰ',Icon='item_5032',Type=160,MaxNum=99999,SellPrice=100,Desc='我为什么在这里。那个恶心的女人，把我禁锢在这里想要做什么？头好痛。好痛。好痛。好痛。好痛。……痛得只想杀掉些什么。夏基留下的手记，最近总有人在打探它的消息。',}",
  [6789] = "{id=6789,NameZh='夏基的手记Ⅱ',Icon='item_5032',Type=160,MaxNum=99999,SellPrice=100,Desc='我似乎又痛昏过去了。已经不记得时间了。奇怪。我的身边有个什么白白的东西……是一朵花。它从哪儿来的？夏基留下的手记，最近总有人在打探它的消息。',}",
  [6790] = "{id=6790,NameZh='夏基的手记Ⅲ',Icon='item_5032',Type=160,MaxNum=99999,SellPrice=100,Desc='我可能是疯了。我在和花说话。不，那是女孩子，那是布里希加曼。花。女孩子。布里希加曼。……布里希加曼？那是谁？不……是的，我知道。你就是你。夏基留下的手记，最近总有人在打探它的消息。',}",
  [6791] = "{id=6791,NameZh='夏基的手记Ⅳ',Icon='item_5032',Type=160,MaxNum=99999,SellPrice=100,Desc='你的声音。你的手。你的眼神。你的呼吸。你需要什么？告诉我，告诉我你需要的一切，我会满足。所以——请不要，消失。夏基留下的手记，最近总有人在打探它的消息。',}",
  [6792] = "{id=6792,NameZh='夏基的手记Ⅴ',Icon='item_5032',Type=160,MaxNum=99999,SellPrice=100,Desc='我得到了永恒。我再也不会失去。这感受，和死亡一样。无所谓了，我已经快看不见了。你在那里吗，我的布里希加曼？夏基留下的手记，最近总有人在打探它的消息。',}",
  [6793] = "{id=6793,NameZh='静谧的晨曦',Icon='item_3959',Type=30,MaxNum=99999,SellPrice=100,Desc='在晨曦降临的时刻，初见之人与命运的约定。使用后获得坠星陨铁*1、Zeny*10000、乐园币*200、神秘箱子v2.0*1',}",
  [6794] = "{id=6794,NameZh='沉默的惑星',Icon='item_3960',Type=30,MaxNum=99999,SellPrice=100,Desc='在迷雾笼罩的旅途，星光赠予前行者的礼物。使用后获得祈祷晶片包*2、光洁的符文石*2、zeny*30000、乐园币*500、神秘箱子v2.0*1',}",
  [6795] = "{id=6795,NameZh='倾落的虹光',Icon='item_3961',Type=30,MaxNum=99999,SellPrice=100,Desc='在谎言破晓的刹那，时间指引被湮没的真实。使用后获得萃光结晶*4、闪耀的符文石*1、Zeny*30000、头饰【诗神的祝福】*1、华丽卡册*1、神秘箱子v2.0*1',}",
  [6796] = "{id=6796,NameZh='S11精英历战宝箱',Icon='item_6634',Type=30,MaxNum=99999,SellPrice=100,Desc='每次段位提升后获得的奖赏，使用后随机获得一件当前段位的奖励。对于经历无数战斗的强者，这份礼物是一种肯定。',}",
