  [6812] = "{id=6812,NameZh='英灵信标升级券·盔甲',Icon='item_6812',Type=70,Quality=2,MaxNum=99999,SellPrice=100,Desc='链接瓦尔哈拉的本源魔力，解放盔甲中封印的英灵力量。（使用后将任一“英灵信标”系列盔甲提升1级）',NoStorage=5,Delete=6812}",
