  [6815] = "{id=6815,NameZh='远古英灵之证',Icon='item_6815',Type=61,UseMode=4133,MaxNum=99999,SellPrice=100,Desc='记录着远古时期陨落英灵力量的徽记，可以用于兑换珍贵的上古遗物碎片。',Delete=6815}",
  [6816] = "{id=6816,NameZh='军功箱·副手',Icon='item_6816',Type=30,MaxNum=99999,SellPrice=100,Desc='来自“诸神宝库”的战利品，用于嘉奖那些战胜强敌的冒险者。使用后可以获得一件随机副手装备。',Delete=6816}",
