  [6819] = "{id=6819,NameZh='远古烙印·初心',Icon='item_6819',Type=61,UseMode=4144,MaxNum=99999,SellPrice=100,Desc='诸神在强大魔物身上打下的印记，是冒险者战胜强敌的证明，可用于兑换远古装备。',Delete=6819}",
