  [6951] = "{id=6951,NameZh='命运之光',Icon='item_6951',Type=41,MaxNum=1,SellPrice=100,Desc='来自霜巨人伊米尔的祝福之光，命运之风自此势不可挡。这份祝福又如同一道大门，为命运之风开启充满未知奇遇的新世界。',NoSale=1,NoStorage=7,}",
  [6952] = "{id=6952,NameZh='心之果实',Icon='item_6952',Type=61,UseMode=4168,MaxNum=99999,SellPrice=100,Desc='蕴含着卢恩符文能量的果实，是灌注心之始源产生的硕果。',}",
  [6955] = "{id=6955,NameZh='污秽之魂',Icon='item_6955',Type=41,Quality=3,MaxNum=99999,SellPrice=100,Desc='犯下亵渎之罪的生魂：生命的终结即是腐朽，污秽是万物的终途。',}",
  [6956] = "{id=6956,NameZh='原罪结晶',Icon='item_6956',Type=41,Quality=3,MaxNum=99999,SellPrice=100,Desc='虚空领域中的囚徒们都是在各自世界罪大恶极的魔王，所犯下的罪孽烙印在他们身上，形成了原罪结晶，对于某些人来说，似乎拥有着特殊的用处。',GetLimit={limit={[999]={800,0}},source={11,22,306,307},type=4,uniform_source=1},}",
  [6958] = "{id=6958,NameZh='幻想精粹',Icon='item_6938',Type=61,UseMode=4161,MaxNum=99999,SellPrice=100,Desc='幻想符文升华的产物，在幻想乡中较为罕见，据说是某些童话生物得以诞生的核心素材。可以兑换很稀有的MVP素材。',}",
