  [6971] = "{id=6971,NameZh='命运回响券',Icon='item_6971',Type=41,MaxNum=99999,SellPrice=100,Desc='宝石与记忆在书库中回响，指引命运的方向。该道具已经失效，使用后将获得[itemid]6553[/itemid]，可用于解锁冒险或英雄职业。',}",
