  [6995] = "{id=6995,NameZh='勇武钻石宝箱',Icon='item_111',Type=30,MaxNum=99999,SellPrice=100,Desc='为嘉奖公会战中英勇战斗攻击华丽水晶的勇士而颁发的宝箱。【大型城池所属公会】击破【大型城池】华丽水晶的专属宝箱，包含：荣誉之证*2000。',NoStorage=5,}",
  [6996] = "{id=6996,NameZh='30分钟玩法时长',Icon='item_6996',Type=74,MaxNum=99999,SellPrice=100,Desc='冒险者，听听唱片放松一下吧~获得后自动使用，本日增加30分钟玩法时长，未使用的时长不会累积至第二天！！！',NoStorage=5,Feature=1,}",
  [6997] = "{id=6997,NameZh='60分钟玩法时长',Icon='item_6997',Type=74,MaxNum=99999,SellPrice=100,Desc='浓缩了时空力量的药水，获得后自动使用，增加冒险者的玩法时长60点。',NoStorage=5,Feature=1,}",
  [7000] = "{id=7000,NameZh='青春不朽花环',Icon='item_7000',Type=550,Quality=2,MaxNum=1,SellPrice=100,Desc='女神伊登掌管着能让诸神长生的金苹果。她佩戴过的花环，同样具有让人不朽的能力。',Delete=7000}",
  [7001] = "{id=7001,NameZh='启示命运之镜',Icon='item_7001',Type=550,Quality=2,MaxNum=1,SellPrice=100,Desc='“凡人，拿走我的妆镜吧。倘若命运垂怜，你或许能从镜中一窥我眼里的未来。”',Delete=7001}",
  [7002] = "{id=7002,NameZh='托尔的神力腰带',Icon='item_7002',Type=550,Quality=2,MaxNum=1,SellPrice=100,Desc='雷神托尔使用过的腰带，能令持有者力大无穷。但不佩戴在身上，就无法发挥效用。',Delete=7002}",
  [7003] = "{id=7003,NameZh='光明圣盾指环',Icon='item_7003',Type=550,Quality=3,MaxNum=1,SellPrice=100,Desc='“万物曾起誓不可伤害我，光辉所照之处皆有我的庇佑。祈愿者，我已赐福于你。”',Delete=7003}",
  [7004] = "{id=7004,NameZh='暗夜匿影指环',Icon='item_7004',Type=550,Quality=3,MaxNum=1,SellPrice=100,Desc='“向我祈祷，只能分享黑夜的孤寂……兄长啊，何日你的光芒才能照耀到我的身上？”',Delete=7004}",
  [7005] = "{id=7005,NameZh='亚尔维斯的悲叹',Icon='item_7005',Type=550,Quality=3,MaxNum=1,SellPrice=100,Desc='全知侏儒为迎娶雷神之女卖弄智慧，却被日光照射化为石像，何其令人唏嘘。',Delete=7005}",
  [7006] = "{id=7006,NameZh='女武神的加护',Icon='item_7006',Type=550,Quality=3,MaxNum=1,SellPrice=100,Desc='只有真正的勇士才能得到女武神的加护，愿你在战斗中常胜不败。',Delete=7006}",
  [7007] = "{id=7007,NameZh='女武神的祝福',Icon='item_7007',Type=550,Quality=3,MaxNum=1,SellPrice=100,Desc='只有真正的勇士才能得到女武神的祝福，愿你在战斗中所向披靡。',Delete=7007}",
  [7008] = "{id=7008,NameZh='冲锋者号角',Icon='item_7008',Type=550,Quality=3,MaxNum=1,SellPrice=100,Desc='英灵在冲锋作战时使用的号角，呜呜的长鸣令人战意沸腾。',Delete=7008}",
  [7009] = "{id=7009,NameZh='不屈者号角',Icon='item_7009',Type=550,Quality=4,MaxNum=1,SellPrice=100,Desc='音色悲凉却雄浑的英灵号角。“唯有死战方能进入英灵殿，吹奏吧，直到我等性命终结。”',Delete=7009}",
  [7010] = "{id=7010,NameZh='警觉者号角',Icon='item_7010',Type=550,Quality=4,MaxNum=1,SellPrice=100,Desc='当神域遭到入侵时才吹响的号角。届时所有的神族都将披甲执锐，保卫自己的家园。',Delete=7010}",
  [7011] = "{id=7011,NameZh='黄金灵舟',Icon='item_7011',Type=550,Quality=4,MaxNum=1,SellPrice=100,Desc='侏儒巧匠出品的灵舟，可大可小。平日作为饰品佩戴；若放入水中行船，则永远有清风相伴。',Delete=7011}",
  [7012] = "{id=7012,NameZh='圣诗刻刀',Icon='item_7012',Type=550,Quality=4,MaxNum=1,SellPrice=100,Desc='萨迦女神用以篆刻英雄史诗的刀笔。“你的我已事迹刻下，万世万代将把它传唱。”',Delete=7012}",
  [7013] = "{id=7013,NameZh='异兽项环',Icon='item_7013',Type=550,Quality=4,MaxNum=1,SellPrice=100,Desc='以多种传说生物身上素材制作的项环，唯有最精英的猎手才有资格佩戴。',Delete=7013}",
  [7014] = "{id=7014,NameZh='精灵短笛',Icon='item_7014',Type=550,Quality=4,MaxNum=1,SellPrice=100,Desc='精灵族以神木制作的乐器，因音色优美而经常在神族宴会上演奏。',Delete=7014}",
  [7015] = "{id=7015,NameZh='希尔之翼',Icon='item_7018',Type=550,Quality=4,MaxNum=1,SellPrice=100,Desc='俊美冷漠的希尔用他的翅膀可以乘风而行。——不用担心，就算没有希尔那么英俊，这翅膀至少也能挡住飓风。',Delete=7015}",
  [7016] = "{id=7016,NameZh='加麦基的护符',Icon='item_7016',Type=550,Quality=4,MaxNum=1,SellPrice=100,Desc='降灵之主加麦基最常用的护符，可以吸收所有土地的力量，使得持有者免受伤害。甚至有传言，它能从土地中呼唤死者灵魂。',Delete=7016}",
  [7017] = "{id=7017,NameZh='克洛塞尔之盾',Icon='item_7015',Type=550,Quality=4,MaxNum=1,SellPrice=100,Desc='幻化之主克洛塞尔最强的防御神器。就连午夜的海潮在它面前也会化为空无，只剩下浪花激烈的回响。',Delete=7017}",
  [7018] = "{id=7018,NameZh='哈拜利的火玉',Icon='item_7017',Type=550,Quality=4,MaxNum=1,SellPrice=100,Desc='当三头的哈拜利手持火玉走过，它身边的一切都会为火焰毁灭。不过，现在看起来，火玉用在防御上似乎更有用，比如不用担心烫伤了。',Delete=7018}",
  [7019] = "{id=7019,NameZh='杜华林的灵玉',Icon='item_7019',Type=550,Quality=4,MaxNum=1,SellPrice=100,Desc='倾注了侏儒巧匠杜华林力量的宝石，拥有的力量被世间所有工匠觊觎。',Delete=7019}",
  [7020] = "{id=7020,NameZh='灵脉之主',Icon='item_7020',Type=550,Quality=4,MaxNum=1,SellPrice=100,Desc='“吾乃八方灵脉之主，元素啊，听我号令！”',Delete=7020}",
  [7021] = "{id=7021,NameZh='布莱奇的蜜酒',Icon='item_7021',Type=550,Quality=4,MaxNum=1,SellPrice=100,Desc='诗神布莱奇诞生于仙酒中，他的仙酒可以给诗人带来无穷无尽的灵感。',Delete=7021}",
  [7022] = "{id=7022,NameZh='混沌之锋',Icon='item_7022',Type=550,Quality=4,MaxNum=1,SellPrice=100,Desc='来自异界的恐怖战刃，哪怕被它轻轻划伤，也会留下难以愈合的创口。',Delete=7022}",
  [7023] = "{id=7023,NameZh='护命灵刃',Icon='item_7023',Type=550,Quality=4,MaxNum=1,SellPrice=100,Desc='天后弗丽嘉赐福过的匕首，据说能够为主人挡下致命的伤害。',Delete=7023}",
  [7024] = "{id=7024,NameZh='结晶铠甲',Icon='item_7024',Type=550,Quality=4,MaxNum=1,SellPrice=100,Desc='结晶之地所孕育之铠甲，虽然沉重，但却坚硬无比。',Delete=7024}",
  [7025] = "{id=7025,NameZh='秘法披风',Icon='item_7025',Type=550,Quality=4,MaxNum=1,SellPrice=100,Desc='远古巫师遗留之物，据说穿上可无惧任何魔法。',Delete=7025}",
  [7029] = "{id=7029,NameZh='神佑印记',Icon='item_7029',Type=550,Quality=4,MaxNum=1,SellPrice=100,Desc='当神降临，世间才有了光。',Delete=7029}",
  [7030] = "{id=7030,NameZh='霍德尔图腾',Icon='item_7030',Type=550,Quality=4,MaxNum=1,SellPrice=100,Desc='黑暗将吞噬一切，包括时间。',Delete=7030}",
  [7031] = "{id=7031,NameZh='哈提之眼',Icon='item_7031',Type=550,Quality=4,MaxNum=1,SellPrice=100,Desc='你的心，既是你的眼。',Delete=7031}",
  [7032] = "{id=7032,NameZh='万蚀宝珠',Icon='item_7032',Type=550,Quality=4,MaxNum=1,SellPrice=100,Desc='触之即死，无药可医。',Delete=7032}",
  [7033] = "{id=7033,NameZh='奥尔劳格之灵',Icon='item_7033',Type=550,Quality=4,MaxNum=1,SellPrice=100,Desc='从混沌到守序，一切皆为神谕。',Delete=7033}",
  [7034] = "{id=7034,NameZh='纪元火种',Icon='item_7034',Type=550,Quality=4,MaxNum=1,SellPrice=100,Desc='盗火者终将火种散播于大地。',Delete=7034}",
  [7100] = "{id=7100,NameZh='穆斯贝尔火石',Icon='item_7100',Type=551,Quality=2,MaxNum=99999,SellPrice=100,Desc='产自金伦加鸿沟之南的火之国，充斥着灼热与毁灭之力。',Delete=7100}",
  [7101] = "{id=7101,NameZh='虹色宝石',Icon='item_7101',Type=551,Quality=2,MaxNum=99999,SellPrice=100,Desc='由彩虹光芒变幻而来的宝石，可以凭制作者的心意变化出不同的颜色。',Delete=7101}",
  [7102] = "{id=7102,NameZh='莱茵少女之泪',Icon='item_7102',Type=551,Quality=2,MaxNum=99999,SellPrice=100,Desc='人鱼痛失黄金，泪水化作珍珠。虽然颗颗圆润美丽，却蕴藏着悲伤和诅咒的力量。',Delete=7102}",
  [7103] = "{id=7103,NameZh='莱茵黄金',Icon='item_7103',Type=551,Quality=2,MaxNum=99999,SellPrice=100,Desc='“莱茵河底曾藏有黄金。它被弃绝情爱者窃取，我等的世界失去光明。”',Delete=7103}",
  [7104] = "{id=7104,NameZh='卢恩铭文石板',Icon='item_7104',Type=551,Quality=2,MaxNum=99999,SellPrice=100,Desc='刻有卢恩铭文的石板，本身具有魔力，常用于制作强大的护身符。',Delete=7104}",
  [7105] = "{id=7105,NameZh='日光尘砂',Icon='item_7105',Type=551,Quality=2,MaxNum=99999,SellPrice=100,Desc='阿萨诸神从阳光中提取的尘砂，无论直接使用还是作为素材都具有神奇的效果。',Delete=7105}",
  [7106] = "{id=7106,NameZh='月光尘砂',Icon='item_7106',Type=551,Quality=2,MaxNum=99999,SellPrice=100,Desc='阿萨诸神从月光中提取的尘砂，无论直接使用还是作为素材都具有神奇的效果。',Delete=7106}",
  [7107] = "{id=7107,NameZh='星光尘砂',Icon='item_7107',Type=551,Quality=2,MaxNum=99999,SellPrice=100,Desc='阿萨诸神从星光中提取的尘砂，无论直接使用还是作为素材都具有神奇的效果。',Delete=7107}",
  [7108] = "{id=7108,NameZh='海妖之骨',Icon='item_7108',Type=551,Quality=3,MaxNum=99999,SellPrice=100,Desc='海妖死后留下的遗骨，若有风浪拍打，依稀可闻魅惑之声。',Delete=7108}",
  [7109] = "{id=7109,NameZh='金鬃野猪皮革',Icon='item_7109',Type=551,Quality=3,MaxNum=99999,SellPrice=100,Desc='取自神话野猪王古林博斯帝的皮革，刀枪不入、水火难侵，十分坚韧。',Delete=7109}",
  [7110] = "{id=7110,NameZh='尼夫海姆雾晶',Icon='item_7110',Type=551,Quality=3,MaxNum=99999,SellPrice=100,Desc='尼夫海姆特有的矿物，是死者国度最阴森幽冷的雾气凝聚而形成的结晶。',Delete=7110}",
  [7111] = "{id=7111,NameZh='百炼神钢',Icon='item_7111',Type=551,Quality=3,MaxNum=99999,SellPrice=100,Desc='瓦特阿尔海姆的侏儒工匠千锤百炼打造的钢铁，其坚硬程度驰名神域。',Delete=7111}",
  [7112] = "{id=7112,NameZh='阿萨秘银',Icon='item_7112',Type=551,Quality=3,MaxNum=99999,SellPrice=100,Desc='阿斯加德所产的银矿，成色灿若星辰，常被制成手环、项链或者其他饰品。',Delete=7112}",
  [7113] = "{id=7113,NameZh='金鬃野猪的獠牙',Icon='item_7113',Type=551,Quality=3,MaxNum=99999,SellPrice=100,Desc='野猪王古林博斯帝的獠牙，粗壮狰狞、寒光闪烁。',Delete=7113}",
  [7114] = "{id=7114,NameZh='变形头盔',Icon='item_7114',Type=551,Quality=4,MaxNum=99999,SellPrice=100,Desc='能让侏儒变成巨龙的传奇头盔，可惜无法复原。不过即使是碎片，也残存着些许神力。',Delete=7114}",
  [7115] = "{id=7115,NameZh='云霞纱线',Icon='item_7115',Type=551,Quality=4,MaxNum=99999,SellPrice=100,Desc='阿萨的女神们以云霞纺纱，一丝一线饱含着她们对亲人、爱人以及勇士们的爱与祝福。',Delete=7115}",
  [7116] = "{id=7116,NameZh='精灵神木',Icon='item_7116',Type=551,Quality=4,MaxNum=99999,SellPrice=100,Desc='精灵之国亚尔夫海姆特有的树木，吸收千年天地精华才能长成。',Delete=7116}",
  [7117] = "{id=7117,NameZh='陈旧的号角',Icon='item_7117',Type=551,Quality=4,MaxNum=99999,SellPrice=100,Desc='沾染着血迹与杀气的号角，应当是神域战士所用的物件，可惜略有破损，需要修补重制。',Delete=7117}",
  [7118] = "{id=7118,NameZh='巨龙的逆鳞',Icon='item_7118',Type=551,Quality=4,MaxNum=99999,SellPrice=100,Desc='龙族自愿献出的逆鳞，一面用魔法铭刻着：永别了，我的神族朋友。',Delete=7118}",
  [7119] = "{id=7119,NameZh='女武神的砾石',Icon='item_7119',Type=551,Quality=4,MaxNum=99999,SellPrice=100,Desc='女武神瓦尔基里用来磨砺武器的磨刀石，能为持有者带来不可思议的武运和战力。',Delete=7119}",
  [7120] = "{id=7120,NameZh='女武神的飞羽',Icon='item_7120',Type=551,Quality=4,MaxNum=99999,SellPrice=100,Desc='女武神瓦尔基里的双翼，既能飞行又可防御。持有她们飞羽的人，将受到女武神的加护。',Delete=7120}",
  [7121] = "{id=7121,NameZh='常青槲寄生',Icon='item_7121',Type=551,Quality=4,MaxNum=99999,SellPrice=100,Desc='看似柔弱实际坚韧的神域植物，是女神们常用的编织材料。',Delete=7121}",
  [7122] = "{id=7122,NameZh='天地树琥珀',Icon='item_7122',Type=551,Quality=4,MaxNum=99999,SellPrice=100,Desc='天地树的树脂坠入九界而形成的琥珀，澄澈透亮，蕴含着玄奥的生命气息。',Delete=7122}",
  [7123] = "{id=7123,NameZh='冥思之石',Icon='item_7123',Type=551,Quality=4,MaxNum=99999,SellPrice=100,Desc='沉睡在智慧泉底的卵石，无言却沉淀着时光赋予的智慧。',Delete=7123}",
  [7130] = "{id=7130,NameZh='历战之盾',Icon='item_7130',Type=551,Quality=4,MaxNum=99999,SellPrice=100,Desc='遗落于诸神战场上的盾牌残片，上面的斫痕诉说着它所见证过的惨烈纷争。',Delete=7130}",
  [7131] = "{id=7131,NameZh='历战之剑',Icon='item_7131',Type=551,Quality=4,MaxNum=99999,SellPrice=100,Desc='遗落于诸神战场上的长剑残骸，在断折前似乎也饮过无数神魔的鲜血。',Delete=7131}",
