  [7162] = "{id=7162,NameZh='随机上古遗物残片',Icon='item_7200',Type=41,Quality=2,MaxNum=99999,SellPrice=100,Desc='使用后可以随机获得上古遗物残片。\n古老的碎片，散发着一丝神秘气息。',Delete=7162}",
  [7200] = "{id=7200,NameZh='未知上古遗物碎片',Icon='item_7200',Type=553,Quality=2,MaxNum=99999,SellPrice=100,Desc='使用后可以随机获得上古遗物碎片或完整的上古遗物。\n古老的碎片，散发着一丝神秘气息。',NoStorage=5,Delete=7200}",
  [7201] = "{id=7201,NameZh='史诗上古遗物碎片',Icon='item_7201',Type=553,Quality=3,MaxNum=99999,SellPrice=100,Desc='尚未鉴定的上古遗物碎片，握在手中能感受到些许不同寻常的力量。',Delete=7201}",
  [7202] = "{id=7202,NameZh='至尊上古遗物碎片',Icon='item_7202',Type=553,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='尚未鉴定的神器碎片，即便并不完整，也能让人感受到澎湃的神力。',Delete=7202}",
  [7203] = "{id=7203,NameZh='无尽口袋',Icon='item_7203',Type=65,MaxNum=1,SellPrice=100,Desc='其貌不扬的小巧背包，却能容纳无数上古遗物。恐怕本身也是一件了不得的宝物呢。',NoSale=1,NoStorage=7,Delete=7203}",
  [7204] = "{id=7204,NameZh='远古封尘',Icon='item_7204',Type=61,UseMode=4134,MaxNum=99999,SellPrice=1,Desc='经年累月染上神器气息的尘埃。通过特殊的工艺，可以合成各种不同上古遗物碎片。',Delete=7204}",
  [7205] = "{id=7205,NameZh='守护者的馈赠·夏基',Icon='item_7201',Type=61,Quality=3,UseMode=4127,MaxNum=99999,SellPrice=100,Desc='“感谢你将我从痛苦中解救出来。——曾经的圣骑士长夏基敬上。”……似乎是被感谢了呢。使用后可以选择获得一个绿色品质的上古遗物碎片',NoStorage=5,Delete=7205}",
  [7206] = "{id=7206,NameZh='守护者的馈赠·卡瓦希尔',Icon='item_7201',Type=61,Quality=3,UseMode=4132,MaxNum=99999,SellPrice=100,Desc='“你绞尽脑汁解密的样子取悦了我。下次我会提高难度。——卡瓦希尔。”……不了不了，不会有下次了。',NoStorage=5,Delete=7206}",
  [7207] = "{id=7207,NameZh='守护者的馈赠·布拉基',Icon='item_7201',Type=61,Quality=3,UseMode=4135,MaxNum=99999,SellPrice=100,Desc='“我曾认为，若是为了母亲，一切行为都会被原谅。但这不过是自我傲慢而已。对于利用了你这件事，请允许我向你道歉。”……希望你也能从悲伤中走出来。',NoStorage=5,Delete=7207}",
