  [8008] = "{id=8008,NameZh='命运的馈赠Ⅴ',Icon='item_3000183',Type=30,MaxNum=99999,Desc='命运给予英雄的馈赠。完成任务后获得base经验*3687500、job经验*2138750、Zeny*41250、头饰[伊米尔之书]*1。',}",
  [8009] = "{id=8009,NameZh='坠落羽毛',Icon='item_8009',Type=41,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='布伦希尔德的落羽，由于蕴含着强大的神之力与虚空之力，成为虚空领域的囚徒争抢之物。集齐6个可接取任务虚空的守护，已获得布伦希尔德·羽落的冒险者可以在虚空边域找杜拉俾斯再次兑换。',Feature=1,}",
  [8010] = "{id=8010,NameZh='命运的馈赠',Icon='item_3959',Type=30,MaxNum=99999,SellPrice=100,Desc='命运给予前行者的馈赠。打开后获得坠星陨铁*1、Zeny*10000、乐园币*200、王室神秘箱子*1。',}",
