  [8012] = "{id=8012,NameZh='命运的回响',Icon='item_3961',Type=30,MaxNum=99999,SellPrice=100,Desc='命运给予前行者的回响。打开后获得祈祷晶片包*2、闪耀的符文石*1、Zeny*30000、华丽卡册*1、王室神秘箱子*1。',}",
  [8013] = "{id=8013,NameZh='次元树枝',Icon='item_8013',Type=41,MaxNum=99999,SellPrice=100,Desc='存在于异次元的魔力树枝，使用后可召唤来自【虚空领域】的MVP魔物，当魔物死亡后，召唤的冒险家将直接获得MVP称号（不会消耗时长），召唤出的魔物最多存活30分钟，只能在公会领地和家园使用。',}",
