  [12381] = "{id=12381,NameZh='万圣节南瓜',Icon='item_12381',Type=40,Quality=4,MaxNum=99999,SellPrice=100,Desc='看起来是一个普通的南瓜，打开之后是香气扑鼻的奶油焗南瓜泥。恢复20％Sp（SP恢复＋10%,持续30分钟）',Feature=1,}",
