  [12384] = "{id=12384,NameZh='结缘巧克力',Icon='item_700005',Type=40,MaxNum=99999,SellPrice=100,Desc='由B格猫星球的恋之神在特定日子到来时才在人间进行出售的拥有独特口味的巧克力，是这个节日赠送亲朋好友的最佳礼物。（效果：可以送给你喜爱的NPC或对其他冒险者使用，使其获得全能力+12，持续30分钟，时长可叠加，死亡下线不清除）',}",
  [12385] = "{id=12385,NameZh='真命巧克力',Icon='item_700006',Type=40,MaxNum=99999,SellPrice=100,Desc='充满纯洁美丽爱意的巧克力，只有通过特殊的素材并借由来自B格猫星球的恋之神的祝福才能制作成的特别巧克力，因为是本命，所以只能赠送给最特别的那个人！（选择你心中最心仪的那个人，即使脸红心跳也勇敢地赠送给他（她）吧！效果：对其他冒险者使用，使其获得特殊外观效果和每30秒恢复520HP的效果，全能力+25，持续12小时，效果不可叠加，死亡下线不清除）',}",
  [12386] = "{id=12386,NameZh='蜜恋糖果',Icon='item_12386',Type=40,MaxNum=99999,SellPrice=100,Desc='泰丽莎特制的甜蜜糖果，真是充满了恋爱般的香甜气息呢~~（效果：使用后可以恢复3%HP,14%SP，还会有糖果特效哦~）',NoStorage=5,}",
  [12387] = "{id=12387,NameZh='浓缩型JOB药水',Icon='item_12387',Type=40,Quality=4,MaxNum=99999,SellPrice=100,Desc='流浪术士史派克无意间将两种不同的Job药水混合的产物，相比之前不仅口感改良不少，JOB经验也提升到了660000，但仅限三转以下冒险家使用！',Level=80,Feature=1,}",
  [12388] = "{id=12388,NameZh='浓缩型宠物经验药水',Icon='item_12388',Type=41,Quality=3,MaxNum=99999,SellPrice=100,Desc='蕴含了神奇力量的药水，如果宠物喝下去的话，能够获得1000000点的经验值。',Level=60,NoStorage=5,}",
