  [12393] = "{id=12393,NameZh='精研型JOB药水',Icon='item_12392',Type=40,Quality=3,MaxNum=99999,SellPrice=100,Desc='使用后令当前职业获得4000000Job经验。\n流浪术士史派克历时多年潜心研制而成的JOB药水，为了尽可能照顾到全职业段冒险者的喜好，该款药水的口感更为柔和爽适。\n因药效过于强劲，需要冒险者达到大师等级段之后才能使用，并且无法享受多职业Job加速加成。',Level=80,JobLevel=220,}",
