  [12900] = "{id=12900,NameZh='枫色玛瑙',Icon='item_12900',Type=70,Quality=4,MaxNum=99999,SellPrice=100,Desc='经过时光沉淀，外表如流霞般美丽的玛瑙石。是荒境上最珍贵的秘藏之一。',Delete=12900}",
  [12901] = "{id=12901,NameZh='旷野之尘',Icon='item_12901',Type=70,Quality=3,MaxNum=99999,SellPrice=1000,Desc='于花草树木中诞生的魔法光子，蕴含着自然的灵气，十分罕见。该道具已失去作用，现在可以出售获得1000zeny',Delete=12901}",
  [12902] = "{id=12902,NameZh='远古遗骸',Icon='item_12902',Type=70,Quality=2,MaxNum=99999,SellPrice=1,Desc='荒境中掩埋的未知骸骨，它的主人已经不可追溯。而其中隐藏的秘密，再也无人知晓。',Delete=12902}",
  [12903] = "{id=12903,NameZh='时光流沙',Icon='item_12903',Type=129,Quality=4,Desc='弥漫在时间长河中，由无数回忆构成的流沙碎屑，逝去的岁月皆潜藏于此。也唯有它的力量，能唤醒沉睡于神树中的古老魔力。\n目前已经失效，请前往普隆德拉活动商人【霍克拉·金】处将其兑换为[itemid]12382[/itemid]。',NoStorage=5,Delete=12903}",
  [12904] = "{id=12904,NameZh='混沌气息',Icon='TechTree_12904',Type=134,Quality=2,Desc='击杀荒境地区的魔物可以掉落，携带的混沌气息越多，能够发现的黑化魔物也就越多。也可以在冰霜领域的“冰霜神像”处提交以解锁额外属性。死亡时会损失部分携带的混沌气息。\n弥漫在枫叶彼岸中的黑暗力量。来自未知的异世界，时刻扰乱来访者的意识。',Delete=12904}",
  [12905] = "{id=12905,NameZh='混沌结晶',Icon='item_12905',Type=61,UseMode=4106,MaxNum=99999,SellPrice=1,Desc='使用后可以开启商店，兑换稀有道具。\n由混沌气息凝聚而成的结晶。在用魔力将它具象化之后，其力量变得更加纯粹可怖。',Delete=12905}",
  [12906] = "{id=12906,NameZh='净化进度',Icon='TechTree_12904',Type=558,Quality=2,Desc='冒险者在时空矩阵区域击退各类入侵而来的时空垃圾而达成的进度。',}",
  [12910] = "{id=12910,NameZh='狩猎传送器',Icon='item_12910',Type=41,MaxNum=99999,SellPrice=1,Desc='狩猎者专属的传送器，能准确地定位附近区域的强大而稀有的魔物的位置。（该道具仅能在荒境或枫叶彼岸区域使用）',NoStorage=5,Delete=12910}",
  [12911] = "{id=12911,NameZh='定向传送器',Icon='item_12911',Type=41,MaxNum=99999,SellPrice=1,Desc='定向传送器可以令你实现精准降落，想去哪里就去哪里，再也不用担心迷路啦！（该道具仅能在荒境或枫叶彼岸区域使用）',NoStorage=5,Delete=12911}",
  [12912] = "{id=12912,NameZh='疾行飞靴',Icon='item_12912',Type=41,MaxNum=99999,SellPrice=1,Desc='受到了风之魔法祝福的这双靴子是用来疾行赶路的上佳选择，穿上它的冒险者会健步如飞。（该道具仅能在荒境或枫叶彼岸区域使用）',NoStorage=5,Delete=12912}",
  [12913] = "{id=12913,NameZh='鹰隼之眼',Icon='item_12913',Type=41,MaxNum=99999,SellPrice=1,Desc='能够探测宝藏具体方位的鹰隼之眼，发家致富全靠它！可对自身一定范围内的宝箱进行指引。冒险者，带上它就此开启你的寻宝之旅吧！（该道具仅能在荒境或枫叶彼岸区域使用）',NoStorage=5,Delete=12913}",
  [12914] = "{id=12914,NameZh='荒境传送器',Icon='item_12914',Type=41,MaxNum=99999,SellPrice=1,Desc='荒境专属的传送器，使用后可立即传送至荒境的神树附近。',NoStorage=5,Delete=12914}",
  [12915] = "{id=12915,NameZh='应急补给箱',Icon='item_12915',Type=41,MaxNum=99999,SellPrice=1,Desc='能提供应急物资补给的补给箱，是经常进行长途旅行的冒险者们的必备之物。使用后可进行一次消耗品的补给购买。',NoStorage=5,Delete=12915}",
  [12916] = "{id=12916,NameZh='魔物变形绘卷',Icon='item_12916',Type=41,MaxNum=99999,SellPrice=1,Desc='能给附近的魔物们施展变形魔法的神奇绘卷。据说，无论多么凶悍的魔物也会在这幅绘卷的威力下乖乖变成一个可爱的形态哦！（该道具仅能在荒境或枫叶彼岸区域使用）',NoStorage=5,Delete=12916}",
  [12917] = "{id=12917,NameZh='隐形斗篷',Icon='item_12917',Type=41,MaxNum=99999,SellPrice=1,Desc='这件斗篷会令你隐去自己的身形，感知再敏锐的魔物也不会觉察到你！不信的话就披上这件斗篷去魔物堆里转一转吧！（该道具仅能在荒境或枫叶彼岸区域使用）',NoStorage=5,Delete=12917}",
  [12918] = "{id=12918,NameZh='嫌隙相册',Icon='item_12918',Type=41,MaxNum=99999,SellPrice=1,Desc='一本离奇的魔法相册，会使被记录在相册里面的魔物们互生嫌隙，陷入混乱状态。“离我远点，讨厌鬼！”（该道具仅能在荒境或枫叶彼岸区域使用）',NoStorage=5,Delete=12918}",
  [12919] = "{id=12919,NameZh='阴郁雨云',Icon='item_12919',Type=41,MaxNum=99999,SellPrice=1,Desc='“雨天当然是阴郁的，这是常识啦！”阴郁雨云是应对火属性魔物的上佳选择，而对高原瑞佩斯使用的话，还会产生一些意想不到的效果哦！（该道具仅能在荒境或枫叶彼岸区域使用）',NoStorage=5,Delete=12919}",
  [12920] = "{id=12920,NameZh='使魔之笛',Icon='item_12920',Type=41,MaxNum=99999,SellPrice=1,Desc='一支诡异古怪的魔笛，能够吹奏出魅惑魔物心灵的乐曲，役使魔物们在一定时间内为你作战。',NoStorage=5,Delete=12920}",
  [12921] = "{id=12921,NameZh='上古地雷',Icon='item_12921',Type=41,MaxNum=99999,SellPrice=1,Desc='荒境的危险遗物，制作它的技艺似乎早已经失传了。布置它的时候请务必小心，哪怕经过了漫长的岁月，它的杀伤力却还是不容小看呢！（该道具仅能在荒境或枫叶彼岸区域使用）',NoStorage=5,Delete=12921}",
  [12922] = "{id=12922,NameZh='捣蛋小鬼盒',Icon='item_12922',Type=41,MaxNum=99999,SellPrice=1,Desc='捣蛋小鬼会对你身边的魔物具有显著的激怒效果，所以，最好不要试着使用它—除非，你做好了承受魔物们怒火的准备。（该道具仅能在荒境或枫叶彼岸区域使用）',NoStorage=5,Delete=12922}",
  [12923] = "{id=12923,NameZh='疯狂炸弹',Icon='item_12923',Type=41,MaxNum=99999,SellPrice=1,Desc='具有强力爆破效果的魔法炸弹，试着朝敌人进行炸弹投掷攻击吧，砰砰砰！（该道具仅能在荒境或枫叶彼岸区域使用）',NoStorage=5,Delete=12923}",
  [12924] = "{id=12924,NameZh='幸运福袋',Icon='item_12924',Type=41,MaxNum=99999,SellPrice=1,Desc='一只没打开的神秘钱袋总是最诱人的—因为你总可以期待从中获得一大笔财富。试着打开它看看吧，愿好运与你同在！',NoStorage=5,Delete=12924}",
  [12925] = "{id=12925,NameZh='上古熔炉',Icon='item_12927',Type=41,MaxNum=99999,SellPrice=1,Desc='荒境的珍贵遗物，熔炉中蕴藏的上古魔力使其有着强大的熔炼功效。',NoStorage=5,Delete=12925}",
  [12926] = "{id=12926,NameZh='亡灵之笛',Icon='item_12928',Type=41,MaxNum=99999,SellPrice=1,Desc='蕴含着亡灵魂魄的魔笛，可以给魔物的遗骸注入魔力使其复苏。“嘘，你看，那堆遗骸好像在动！”；直接使用时，回复自身100%的HP和SP。（该道具仅能在荒境或枫叶彼岸区域使用）',NoStorage=5,Delete=12926}",
  [12927] = "{id=12927,NameZh='摹仿之镜',Icon='item_12929',Type=41,MaxNum=99999,SellPrice=1,Desc='想和魔物们进行亲密无间的接触和交流吗？镜像魔法满足你！想变成什么魔物的话，就把这面摹仿之镜对准它试试看吧~（该道具仅能在荒境或枫叶彼岸区域使用）',ItemTarget={notnpcid={809957,809956,809953,809954,280321,280322,280323,280324,280332,280333,280334,280335,280336,809959,809856,811020,1058,809946,809947,809948,809949,809950,809951,809952,808302,808297,808298,808299,808300,808301,808305,808306,2064,808302},range=10,type=5},NoStorage=5,Delete=12927}",
  [12928] = "{id=12928,NameZh='回音海螺',Icon='item_12926',Type=41,MaxNum=99999,SellPrice=1,Desc='一只存取了人们的愿望的魔力海螺，将它放在耳畔仔细聆听，你将会听到来自远方的求助声。',NoStorage=5,Delete=12928}",
  [12929] = "{id=12929,NameZh='荒野之刃',Icon='item_12925',Type=41,MaxNum=99999,SellPrice=1,Desc='一把遗落在荒境的短刃，尽管它有些生锈并不够锋利，但偶尔拿来护身自卫还是可以的。（该道具仅能在荒境或枫叶彼岸区域使用）',NoStorage=5,Delete=12929}",
  [12930] = "{id=12930,NameZh='魔扉之钥',Icon='item_12930',Type=41,MaxNum=99999,SellPrice=1,Desc='开启异世界的大门的魔法钥匙，用以开启异界魔扉。（该道具仅能在荒境或枫叶彼岸区域使用）',NoStorage=5,Delete=12930}",
  [12931] = "{id=12931,NameZh='狸猫留声机',Icon='item_12931',Type=41,MaxNum=99999,SellPrice=1,Desc='在原地放置这台狸猫留声机，周围的魔物们会被留声机放送的音乐吸引并向其聚拢。此外，狸猫留声机对狸猫本体更有着某种神奇的效力哦！（该道具仅能在荒境或枫叶彼岸区域使用）',NoStorage=5,Delete=12931}",
  [12932] = "{id=12932,NameZh='点石成金铲',Icon='item_12932',Type=41,MaxNum=99999,SellPrice=1,Desc='有了这把点石成金铲，不管你到了哪里都可以挖出宝藏！使用后召唤麦基瑟员工为你服务，有机会在当前区域挖出宝箱—但运气不好的话，也会开出别的什么东西哦！（该道具仅能在荒境或枫叶彼岸区域使用）',NoStorage=5,Delete=12932}",
  [12933] = "{id=12933,NameZh='黄金之钥',Icon='item_12933',Type=41,MaxNum=99999,SellPrice=1,Desc='金制的锁钥，上面刻有精密复杂的纹路，可以用来开启一个稀有宝箱。',NoStorage=5,Delete=12933}",
  [12934] = "{id=12934,NameZh='白银之钥',Icon='item_12934',Type=41,MaxNum=99999,SellPrice=1,Desc='银制的锁钥，上面刻有简单质朴的纹路，可以用来开启一个特殊宝箱。',NoStorage=5,Delete=12934}",
  [12935] = "{id=12935,NameZh='梦斩之刃',Icon='item_12935',Type=41,MaxNum=99999,SellPrice=1,Desc='生命之晶在危机中也不会浑浊，用仅此一次的转机，在破碎后焕发出新的光辉，使用后混沌气息增加2点，混沌气息上限为1.5万。',NoStorage=5,Delete=12935}",
  [12936] = "{id=12936,NameZh='瞬息龙影',Icon='item_12936',Type=41,MaxNum=99999,SellPrice=1,Desc='这便是绝对的力量：敌人无法忽视它的存在，只能接受它带来的毁灭。使用后获得效果：对血量较低的魔物触发斩杀效果，对MVP/MINI无效。（该道具仅能在荒境或枫叶彼岸区域使用）',NoStorage=5,Delete=12936}",
  [12937] = "{id=12937,NameZh='回音勋章',Icon='item_12937',Type=41,MaxNum=99999,SellPrice=1,Desc='孤独的呼唤不再是零丁的回声，同伴的精神共鸣唱出最强力的和音，使用后获得光环效果：使自身以及自身范围内的队伍成员普通攻击附加额外伤害。（该道具仅能在荒境或枫叶彼岸区域使用）',NoStorage=5,Delete=12937}",
  [12938] = "{id=12938,NameZh='坚毅徽记',Icon='item_12938',Type=41,MaxNum=99999,SellPrice=1,Desc='同伴们热切的眼神给予自己无限的勇气。来吧！无论面对什么敌人，共有强烈的意志便是最强的武器，使用后获得效果：使自身以及自身范围内的队伍成员技能伤害伤害提升。（该道具仅能在荒境或枫叶彼岸区域使用）',NoStorage=5,Delete=12938}",
  [12939] = "{id=12939,NameZh='治愈之证',Icon='item_12939',Type=41,MaxNum=99999,SellPrice=1,Desc='最棒的同伴总是互相牵挂，共同跨越漫漫长夜，迈向希望的黎明。幸福从此加倍，痛苦减半，使用后获得效果：使自身以及自身范围内的队伍成员受治疗效果提升。（该道具仅能在荒境或枫叶彼岸区域使用）',NoStorage=5,Delete=12939}",
  [12940] = "{id=12940,NameZh='疾行者',Icon='item_12940',Type=41,MaxNum=99999,SellPrice=1,Desc='疾驰的身影一个个闪现而过，完美的配合美丽而强大，使用后获得效果：使自身以及自身范围内的队伍成员移动速度提升。（该道具仅能在荒境或枫叶彼岸区域使用）',NoStorage=5,Delete=12940}",
  [12942] = "{id=12942,NameZh='谜影之镜',Icon='item_48525',Type=41,MaxNum=99999,SellPrice=1,Desc='一面奇妙的魔镜，有时镜面上会浮现出若隐若现的人影，或许，这正代表着附近有什么人碰到了麻烦……',NoSale=1,NoStorage=5,Delete=12942}",
  [12943] = "{id=12943,NameZh='雪花盒子',Icon='item_52626',Type=41,MaxNum=99999,SellPrice=1,Desc='雪花形状的小盒子，闪烁着温暖的光芒。在下雪天，冰霜领域有一位名叫小白的少女，她正在寻找这件物品。（该道具仅能在荒境或枫叶彼岸区域使用）',NoStorage=5,Delete=12943}",
  [12944] = "{id=12944,NameZh='幻域祝福',Icon='item_12944',Type=41,MaxNum=99999,SellPrice=1,Desc='憎恶与仇恨只会带来毁灭，和平才是永恒的主题，使用后获得效果：短暂清除自身周围魔物的威胁。（该道具仅能在荒境或枫叶彼岸区域使用）',NoStorage=5,Delete=12944}",
  [12945] = "{id=12945,NameZh='迷金幻影',Icon='item_12945',Type=41,MaxNum=99999,SellPrice=1,Desc='金钱的声音不但悦耳，还具有强大的力量哦。你要赌上明天获得这最强能力吗？使用后获得技能迷金幻影，据说对喜爱金币的金钱龟有特殊效果。（该道具仅能在荒境或枫叶彼岸区域使用）',NoStorage=5,Delete=12945}",
  [12946] = "{id=12946,NameZh='幻力药水',Icon='item_12946',Type=41,MaxNum=99999,SellPrice=1,Desc='力量马上就能到全新的境界啦！可是还差一点点~这个时候就需要一点助力！使用后可提升自身的Base和Job，但对小野猪使用却会发生可怕的事情。',NoStorage=5,Delete=12946}",
  [12947] = "{id=12947,NameZh='烈焰舞铳',Icon='item_12947',Type=41,MaxNum=99999,SellPrice=1,Desc='冲天的火光映红了脸颊，强大的气势让人为之倾倒。使用后获得技能烈焰舞铳，似乎对大块的冰块有极强的融化作用。（该道具仅能在荒境或枫叶彼岸区域使用）',NoStorage=5,Delete=12947}",
  [12948] = "{id=12948,NameZh='魔力剪刀',Icon='item_12948',Type=41,MaxNum=99999,SellPrice=1,Desc='奇妙的果实难以获得？别担心，有了它，那些有趣的果实都是你的啦！',NoStorage=5,Delete=12948}",
  [12949] = "{id=12949,NameZh='奇异剪刀',Icon='item_12949',Type=41,MaxNum=99999,SellPrice=1,Desc='每一颗稀有果实的获得都离不开它哦，只有通过自己亲手采摘的果实才格外香甜呢！',NoStorage=5,Delete=12949}",
  [12950] = "{id=12950,NameZh='破碎背包',Icon='item_12950',Type=41,MaxNum=99999,SellPrice=1,Desc='获得了一只大背包，总算可以把繁多的行李好好收纳一下了，开心~什么？才用了一次就破了？！使用后背包格子永久增加30格。',NoSale=1,NoStorage=5,Delete=12950}",
  [12951] = "{id=12951,NameZh='梦境穿梭',Icon='item_12951',Type=41,MaxNum=99999,SellPrice=1,Desc='适合默念心中所想的那个地方吧，手指上的点点光辉迸发出巨大的能量。或许下一秒你已经在目标之地了哦。使用后可瞬间传送至枫叶彼岸。',NoStorage=5,Delete=12951}",
  [12952] = "{id=12952,NameZh='霹雳雷云',Icon='item_12952',Type=41,MaxNum=99999,SellPrice=1,Desc='一道耀眼的亮光划破黑暗的夜，奏响一曲壮阔的绝命交响曲。使用后获得效果：战斗时有概率触发闪电效果对自身周围单位造成伤害。（该道具仅能在荒境或枫叶彼岸区域使用）',NoStorage=5,Delete=12952}",
  [12953] = "{id=12953,NameZh='忆之留声机',Icon='item_12953',Type=41,MaxNum=99999,SellPrice=1,Desc='战斗中的呐喊、胜利的欢笑……那些珍贵的时光伴随着温暖的声音，永驻心间。使用后可在原地召唤一个持续30分钟的留声机，可恢复战斗时长。',NoStorage=5,Delete=12953}",
  [12954] = "{id=12954,NameZh='震荡爆弹',Icon='item_12923',Type=41,MaxNum=99999,SellPrice=1,Desc='美之宫中蕴含魔力的炸弹；使用后原地摆放一枚炸弹，可以清除一些碎裂的障碍物，但是千万小心别炸伤自己哦~',NoSale=1,NoStorage=5,Delete=12954}",
  [12955] = "{id=12955,NameZh='神像的头颅',Icon='item_12955',Type=160,MaxNum=99999,SellPrice=1,Desc='看起来像是某个神像的头颅，但是身体不知道去哪了，从来还没有人看过它们合体的样子。',Delete=12955}",
  [12956] = "{id=12956,NameZh='秘闻卷宗',Icon='item_12956',Type=41,Quality=4,MaxNum=99999,SellPrice=1,Desc='可以在王室狩猎场、心灵狩猎场的“剑碑”处解锁剧情。\n记录着卢恩王国王室秘辛的卷宗，一切传言皆有源头。',Delete=12956}",
  [12957] = "{id=12957,NameZh='修炼笔记',Icon='item_12957',Type=160,MaxNum=1,SellPrice=1,Desc='派特记录日常修炼感悟的笔记，经常会抄录给家族内其他成员，给予他们修炼上的帮助。',Delete=12957}",
  [12958] = "{id=12958,NameZh='竞技场徽章',Icon='item_12958',Type=160,MaxNum=1,SellPrice=1,Desc='是竞技场管理员颁发给卓越魔法师的徽章，是对魔法师实力的认可。',Delete=12958}",
  [12959] = "{id=12959,NameZh='情书',Icon='item_12959',Type=160,MaxNum=1,SellPrice=1,Desc='贵族小姐们写给尼希尔的情书，里面诉说着她们对尼希尔的爱意。',Delete=12959}",
  [12960] = "{id=12960,NameZh='火焰兰',Icon='item_12960',Type=160,MaxNum=1,SellPrice=1,Desc='火焰兰是海涅的族花，它象征着海涅家族燃烧，绽放，永不熄灭的魔法火焰。',Delete=12960}",
  [12961] = "{id=12961,NameZh='断弦',Icon='item_12961',Type=160,MaxNum=1,SellPrice=1,Desc='由奈利乌斯家秘制的特殊合金制作而成的琴弦。',Delete=12961}",
  [12962] = "{id=12962,NameZh='矢车菊',Icon='item_12962',Type=160,MaxNum=1,SellPrice=1,Desc='矢车菊是奈利乌斯的族花，它的花语是单身、优雅和温柔，就如同奈利乌斯家族的女性们一样。',Delete=12962}",
  [12963] = "{id=12963,NameZh='双子星',Icon='item_12963',Type=160,MaxNum=1,SellPrice=1,Desc='奈利乌斯家前任家主兰卡的武器，是卢恩顶尖的武器工匠以奈利乌斯家主和她的影武者为灵感制作的，代表着双生与守护。',Delete=12963}",
  [12964] = "{id=12964,NameZh='竖琴',Icon='item_12964',Type=160,MaxNum=1,SellPrice=1,Desc='玛丽希尔的竖琴，饱含着她与她姐姐卡迪娅珍贵而又温暖的回忆。',Delete=12964}",
  [12965] = "{id=12965,NameZh='朽木',Icon='item_12965',Type=160,MaxNum=1,SellPrice=1,Desc='一段毫无用处的朽木，替换了亚文原本制作出来献给王子的重型机甲。',Delete=12965}",
  [12966] = "{id=12966,NameZh='重型机甲',Icon='item_12966',Type=160,MaxNum=1,SellPrice=1,Desc='亚文制作出来献给王子的重型机甲。',Delete=12966}",
  [12967] = "{id=12967,NameZh='装载机甲的箱子',Icon='item_12967',Type=160,MaxNum=1,SellPrice=1,Desc='装载着亚文制作的重型机甲的箱子，由卫兵们负责运送。',Delete=12967}",
  [12968] = "{id=12968,NameZh='诅咒',Icon='item_12968',Type=160,MaxNum=1,SellPrice=1,Desc='朽木上刻着的诅咒，目标是谋害王子。',Delete=12968}",
  [12969] = "{id=12969,NameZh='望远镜',Icon='item_12969',Type=160,MaxNum=1,SellPrice=1,Desc='巴尔特先祖巴克萨遗留之物，代表着航海中观测定位。',Delete=12969}",
  [12970] = "{id=12970,NameZh='舵盘',Icon='item_12970',Type=160,MaxNum=1,SellPrice=1,Desc='巴尔特先祖巴克萨遗留之物，代表着航海中掌控方向。',Delete=12970}",
  [12971] = "{id=12971,NameZh='海盗弯刀',Icon='item_12971',Type=160,MaxNum=1,SellPrice=1,Desc='巴尔特先祖巴克萨遗留之物，代表着航海中掌控力量。',Delete=12971}",
