  [13151] = "{id=13151,NameZh='大航海之证【武器外观】',Icon='item_47272',Type=320,Quality=3,MaxNum=1,SellPrice=100,Condition=8,Desc='海上贸易大亨老巴尔特专属的黄金火枪，过于奢华的外饰配合先进的火枪技术，彰显出巴尔特家族无人能及的海上霸主地位。',}",
  [13152] = "{id=13152,NameZh='死之吻【武器外观】',Icon='item_3005193',Type=310,MaxNum=1,SellPrice=100,Condition=8,Desc='恶魔猎人的双枪，赐予过魔物死亡，也同样抵上过人类的额头。毕竟有一类“恶魔”，披着人类的皮囊，却长着野兽的心。',}",
  [13153] = "{id=13153,NameZh='伏虎记【武器外观】',Icon='item_3005202',Type=240,MaxNum=1,SellPrice=100,AdventureValue=1,Condition=8,Desc='洛阳城中广为流传的话本小说，控诉了一名男子酒后拳打萌虎的“罪恶”行径。',}",
  [13154] = "{id=13154,NameZh='甜蜜旋风【武器外观】',Icon='item_3005501',Type=300,MaxNum=1,SellPrice=100,Condition=8,Desc='一份美味的蛋糕。吃下去的瞬间心中升腾起微风，因为这份蛋糕的配方里，有甜、有香、有失败、有很多很多的爱。',}",
  [13155] = "{id=13155,NameZh='赛博之牙【武器外观】',Icon='item_3005694',Type=190,MaxNum=1,SellPrice=100,AdventureValue=1,Condition=8,Desc='智能机器人“赛博小兔”为适应战斗而变化成的重装形态，小兔的AI能够在战斗中为使用者提供帮助。',LoadShowSize=1.25,}",
  [13156] = "{id=13156,NameZh='天空巡猎者【武器外观】',Icon='item_3005804',Type=320,MaxNum=1,SellPrice=100,Condition=8,Desc='天空特化型来复枪，大幅增强了空对地作战能力，当然发挥它全部力量的前提是——你会飞。',}",
  [13157] = "{id=13157,NameZh='热带部落拳刃【武器外观】',Icon='item_3005994',Type=200,MaxNum=1,SellPrice=100,AdventureValue=1,Condition=8,Desc='从远方海岛舶来的贵重之物，相传曾被岛上的巨人勇士所使用。可惜这副拳刃实在太大了，只能挂在背后作为装饰。',}",
  [13158] = "{id=13158,NameZh='谁的奶酪【武器外观】',Icon='item_3006032',Type=230,MaxNum=1,SellPrice=100,AdventureValue=1,Condition=8,Desc='“吱！这是我的奶酪！你看！上面有我的徽章！”',}",
  [13159] = "{id=13159,NameZh='池塘勇士木剑【武器外观】',Icon='item_3005933',Type=180,MaxNum=1,SellPrice=100,AdventureValue=1,Condition=8,Desc='骑士王从石头里拔出宝剑，而你从泥巴里抽出一把木剑……唔，这样一把剑，或许可以让你成为鱼塘之王？',TFValidDate='2022-08-01 05:00:00',ValidDate='2022-08-01 05:00:00',}",
  [13160] = "{id=13160,NameZh='稻穂神杖【武器外观】',Icon='item_3006181',Type=190,MaxNum=1,SellPrice=100,AdventureValue=1,Condition=8,Desc='愿来年的天水之国能够风调雨顺，五谷丰登。',TFValidDate='2022-09-01 05:00:00',ValidDate='2022-09-01 05:00:00',}",
  [13161] = "{id=13161,NameZh='星宇狐尾草【武器外观】',Icon='item_3006530',Type=190,MaxNum=1,SellPrice=100,AdventureValue=1,Condition=8,Desc='以天外陨石铸成的武器，打磨后竟散发出星空般璀璨的光芒。可惜，它只具有观赏价值。',}",
  [13162] = "{id=13162,NameZh='法老猫【武器外观】',Icon='item_3006683',Type=510,MaxNum=1,SellPrice=100,AdventureValue=1,Condition=8,Desc='喵~要来本喵的永恒住所来作客吗？',}",
  [13163] = "{id=13163,NameZh='冰雪猎人【武器外观】',Icon='item_3006944',Type=210,MaxNum=1,SellPrice=100,AdventureValue=1,Condition=8,Desc='背上这只弓，你就是冰雪中最靓的那个仔。',TFValidDate='2022-12-01 05:00:00',ValidDate='2022-12-01 05:00:00',}",
  [13164] = "{id=13164,NameZh='远古巨锤【武器外观】',Icon='item_3006231',Type=220,MaxNum=1,SellPrice=100,AdventureValue=1,Condition=8,Desc='从远古时期流传下来的巨大的锤子，没有人知道它曾经击败过多少野兽！',TFValidDate='2022-06-24 05:00:00',ValidDate='2022-07-01 05:00:00',}",
