  [13300] = "{id=13300,NameZh='晨曦的露水',Icon='item_13300',Type=70,MaxNum=99999,SellPrice=100,Desc='在日光大亮之前凝结于花瓣的露水，据说是辉煌领域最纯洁的物质。',NoStorage=5,Feature=1,}",
  [13301] = "{id=13301,NameZh='流星的凝光',Icon='item_13301',Type=70,MaxNum=99999,SellPrice=10,Desc='在流星划过的夜晚被冰冻起来的宝石，在黑暗里竟然可以自己放出微光。',NoStorage=5,}",
  [13302] = "{id=13302,NameZh='微风的传言',Icon='item_13302',Type=70,MaxNum=99999,SellPrice=1,Desc='看不见又摸不着的诡异物质，只能感受到它在手中的流动，以及耳边无休无止的呼啸。',NoStorage=5,}",
  [13310] = "{id=13310,NameZh='云之岩',Icon='item_13310',Type=70,MaxNum=99999,SellPrice=1,Desc='书中世界最常见的建筑材料，洁白美丽、可塑性强。什么，你说云朵不能盖房子？拜托，幻想中什么都可能发生！',}",
  [13311] = "{id=13311,NameZh='幻想结晶',Icon='item_13311',Type=70,MaxNum=99999,SellPrice=1,Desc='幻想乡的通用货币，是固化的幻想之力，如水晶般剔透，折射出多彩的光辉。',}",
  [13312] = "{id=13312,NameZh='圆梦祝福',Icon='item_13312',Type=70,MaxNum=99999,SellPrice=1,Desc='每当你实现伙伴们的心愿，出于感激，他们也会给予你梦想成真的祝福。圆梦祝福集满后，可以开启梦幻之音获得奖励。',Feature=1,}",
  [13313] = "{id=13313,NameZh='匠心木料',Icon='item_13313',Type=70,MaxNum=99999,SellPrice=1,Desc='由巧手工匠采集原木、精心加工而成的木料，因为用途广泛，常备商人大量收购。',}",
  [13314] = "{id=13314,NameZh='星芒宝石',Icon='item_13314',Type=70,MaxNum=99999,SellPrice=1,Desc='掘开星辰沉睡的硬壳，你会发现其中瑰丽不朽的心。不够，开采星星实在是一桩困难的事情，所以星芒宝石是贵重而稀有的材料呢。',}",
  [13320] = "{id=13320,NameZh='棉花糖',Icon='item_13320',Type=41,MaxNum=99999,SellPrice=1,Desc='甜甜的棉花糖，造型与糖姐姐不能说非常相似，只能说完全一样。该物品在伙伴派遣中获得一次后，可在魔盒百宝屋不限量购买，每个礼物可增加两点好感度（一个爱心为四点好感度）。',NoStorage=5,Feature=1,}",
  [13321] = "{id=13321,NameZh='肉骨头',Icon='item_13321',Type=41,MaxNum=99999,SellPrice=1,Desc='极为干净的肉骨头，真的还有啃的价值吗……？该物品在伙伴派遣中获得一次后，可在魔盒百宝屋不限量购买，每个礼物可增加两点好感度（一个爱心为四点好感度）。',NoStorage=5,Feature=1,}",
  [13322] = "{id=13322,NameZh='能量蘑菇',Icon='item_13322',Type=41,MaxNum=99999,SellPrice=1,Desc='蕴含超级能量的蘑菇，吃下后令人如马达一样旋转！该物品在伙伴派遣中获得一次后，可在魔盒百宝屋不限量购买，每个礼物可增加两点好感度（一个爱心为四点好感度）。',NoStorage=5,Feature=1,}",
  [13323] = "{id=13323,NameZh='保养油',Icon='item_13323',Type=41,MaxNum=99999,SellPrice=1,Desc='带有幽香的保养油，可保证毛发润泽顺滑。该物品在伙伴派遣中获得一次后，可在魔盒百宝屋不限量购买，每个礼物可增加两点好感度（一个爱心为四点好感度）。',NoStorage=5,Feature=1,}",
  [13325] = "{id=13325,NameZh='痛痛飞飞草',Icon='item_13325',Type=41,MaxNum=99999,SellPrice=1,Desc='嚼碎敷上，痛痛~飞走啦~该物品在伙伴派遣中获得一次后，可在魔盒百宝屋不限量购买，每个礼物可增加两点好感度（一个爱心为四点好感度）。',NoStorage=5,Feature=1,}",
  [13326] = "{id=13326,NameZh='云朵砂糖',Icon='item_13326',Type=41,MaxNum=99999,SellPrice=1,Desc='轻柔如云的砂糖，是制作甜点的最高级食材。该物品在伙伴派遣中获得一次后，可在魔盒百宝屋不限量购买，每个礼物可增加两点好感度（一个爱心为四点好感度）。',NoStorage=5,Feature=1,}",
  [13327] = "{id=13327,NameZh='扳手',Icon='item_13327',Type=41,MaxNum=99999,SellPrice=1,Desc='铁质扳手，虽然普通，却具有精细严谨的美感。该物品在伙伴派遣中获得一次后，可在魔盒百宝屋不限量购买，每个礼物可增加两点好感度（一个爱心为四点好感度）。',NoStorage=5,Feature=1,}",
  [13328] = "{id=13328,NameZh='鱼竿',Icon='item_13328',Type=41,MaxNum=99999,SellPrice=1,Desc='最简单的钓竿，能钓到什么鱼，全看钓者水准。该物品在伙伴派遣中获得一次后，可在魔盒百宝屋不限量购买，每个礼物可增加两点好感度（一个爱心为四点好感度）。',NoStorage=5,Feature=1,}",
  [13329] = "{id=13329,NameZh='高倍放大镜',Icon='item_13334',Type=41,MaxNum=99999,SellPrice=1,Desc='深受推理爱好者喜爱的放大镜，这一款好像看得比其他的都要清晰。该物品在伙伴派遣中获得一次后，可在魔盒百宝屋中不限量购买，每个礼物可增加两点好感度（一个爱心为四点好感度）。',NoStorage=5,Feature=1,}",
  [13330] = "{id=13330,NameZh='可疑的漫画',Icon='item_13335',Type=41,MaxNum=99999,SellPrice=1,Desc='从封面到内容都看起来很可疑的漫画书，好像很受阿宅的欢迎。该物品在伙伴派遣中获得一次后，可在魔盒百宝屋中不限量购买，每个礼物可增加两点好感度（一个爱心为四点好感度）。',NoStorage=5,Feature=1,}",
  [13331] = "{id=13331,NameZh='杠铃',Icon='item_13336',Type=41,MaxNum=99999,SellPrice=1,Desc='太重了，恐怕只有最强壮的小伙伴才能举得起来……该物品在伙伴派遣中获得一次后，可在魔盒百宝屋中不限量购买，每个礼物可增加两点好感度（一个爱心为四点好感度）。',NoStorage=5,Feature=1,}",
  [13332] = "{id=13332,NameZh='流星耳坠',Icon='item_13337',Type=41,MaxNum=99999,SellPrice=1,Desc='镶嵌了星星宝石的耳坠，小巧又充满了神秘感。该物品在伙伴派遣中获得一次后，可在魔盒百宝屋中不限量购买，每个礼物可增加两点好感度（一个爱心为四点好感度）。',NoStorage=5,Feature=1,}",
  [13333] = "{id=13333,NameZh='闪亮蝴蝶结',Icon='item_13338',Type=41,MaxNum=99999,SellPrice=1,Desc='可以发光的蝴蝶结，充满了明星气场，戴上后闪耀度满分。该物品在伙伴派遣中获得一次后，可在魔盒百宝屋中不限量购买，每个礼物可增加两点好感度（一个爱心为四点好感度）。',NoStorage=5,Feature=1,}",
  [13334] = "{id=13334,NameZh='麦穗项链',Icon='item_13339',Type=41,MaxNum=99999,SellPrice=1,Desc='麦穗形状的项链，朴素而不失可爱。该物品在伙伴派遣中获得一次后，可在魔盒百宝屋中不限量购买，每个礼物可增加两点好感度（一个爱心为四点好感度）。',NoStorage=5,Feature=1,}",
