  [13401] = "{id=13401,NameZh='椅子',Icon='item_13401',Type=160,MaxNum=99999,SellPrice=1,Desc='朴实的木质椅子，却能有效的缓解各种疼痛症状。',}",
  [13402] = "{id=13402,NameZh='狗爪杯',Icon='item_13402',Type=160,MaxNum=99999,SellPrice=1,Desc='世界上仅有三只的狗爪杯，纯手工制作，看起来更像是某汪丢掉的物品。',}",
  [13403] = "{id=13403,NameZh='跑鞋',Icon='item_13403',Type=160,MaxNum=99999,SellPrice=1,Desc='最新款限量跑鞋。踩着它就仿佛踩在云朵上。',}",
  [13405] = "{id=13405,NameZh='幸运三叶草',Icon='item_13405',Type=160,MaxNum=99999,SellPrice=1,Desc='三瓣叶子的三叶草。虽然不知道为什么说它是幸运的象征……',}",
  [13406] = "{id=13406,NameZh='驱魔晶粉',Icon='item_13406',Type=160,MaxNum=99999,SellPrice=1,Desc='能让使用者在一段时间内，免疫邪恶幻想侵蚀的晶粉。需要多种材料制作，价格昂贵。',}",
  [13407] = "{id=13407,NameZh='缆车零部件',Icon='item_13407',Type=160,MaxNum=99999,SellPrice=1,Desc='修复缆车的零部件，在缆车损坏的时候能派上大用处。',}",
  [13408] = "{id=13408,NameZh='神奇的羊皮卷Ⅰ',Icon='item_13408',Type=160,MaxNum=99999,SellPrice=1,Desc='一份古老的羊皮卷，按照上面的路线走，感觉能找到什么大宝贝呢！',}",
  [13409] = "{id=13409,NameZh='神奇的羊皮卷Ⅱ',Icon='item_13409',Type=160,MaxNum=99999,SellPrice=1,Desc='一份古老的羊皮卷，按照上面的路线走，感觉能找到什么大宝贝呢！',}",
  [13410] = "{id=13410,NameZh='神奇的羊皮卷Ⅲ',Icon='item_13410',Type=160,MaxNum=99999,SellPrice=1,Desc='一份古老的羊皮卷，按照上面的路线走，感觉能找到什么大宝贝呢！',}",
  [13411] = "{id=13411,NameZh='神奇的羊皮卷Ⅳ',Icon='item_13411',Type=160,MaxNum=99999,SellPrice=1,Desc='一份古老的羊皮卷，按照上面的路线走，感觉能找到什么大宝贝呢！',}",
  [13412] = "{id=13412,NameZh='特殊的通行证',Icon='item_5820',Type=41,MaxNum=99999,SellPrice=1,Desc='进入某处山洞的特殊通行证，去洞穴看看吧，或许能有新发现。',}",
  [13413] = "{id=13413,NameZh='一份神奇的菜谱',Icon='item_13413',Type=41,MaxNum=99999,SellPrice=1,Desc='记录了制作料理的神奇菜谱，有了它，甚至可以挑战星级大厨。',}",
  [13415] = "{id=13415,NameZh='星陨铁石',Icon='item_13415',Type=160,MaxNum=99999,SellPrice=1,Desc='从坠落的星星上采集到的矿石，用它锻造的武器，可以有效克制邪恶的幻想。',}",
  [13420] = "{id=13420,NameZh='骄阳杀手',Icon='item_13431',Type=41,MaxNum=1,SellPrice=1,Desc='晴朗天空在头顶，凉爽清风在脚下。不管是多么毒辣的光线，它都会一一挡住，温柔交出舒适的清凉。',}",
  [13421] = "{id=13421,NameZh='米宝卫士',Icon='item_13432',Type=41,MaxNum=1,SellPrice=1,Desc='外形酷似仙人掌，一旦被戳破就会喷出粘稠液体。正因为这种自卫机制，它被冠以“卫士”的名号。',}",
  [13422] = "{id=13422,NameZh='圣洁之泉',Icon='item_13430',Type=41,MaxNum=1,SellPrice=1,Desc='传说奥菲莉娅女王为伤者流下的每一滴眼泪，都会成为一捧圣洁的泉水。直到今天，它们也无声诉说着千年的往事。',}",
  [13423] = "{id=13423,NameZh='美食防线',Icon='item_13429',Type=41,MaxNum=1,SellPrice=1,Desc='站住，不要离开！这里的美食那么多，没有全部吃完之前，不会放行的哟！',}",
  [13424] = "{id=13424,NameZh='美学木方',Icon='item_13426',Type=41,MaxNum=1,SellPrice=1,Desc='就算刚锯好的木方也要整齐划一、加以简单装饰，这就是我们刨刀锯木场厂长的审美要求。',}",
  [13425] = "{id=13425,NameZh='广场巨无霸',Icon='item_13422',Type=41,MaxNum=1,SellPrice=1,Desc='硕大无比的面包片堆积在甜品店前，该怎么才能向来店的客人解释，它们真的不能吃呢？',}",
  [13426] = "{id=13426,NameZh='树木王冠',Icon='item_13428',Type=41,MaxNum=1,SellPrice=1,Desc='知道大树为什么长得这么又高又挺拔吗？因为它们的根深深扎在地下尽情喝水，周围还有王冠保护它们呀。',}",
  [13427] = "{id=13427,NameZh='简朴休憩',Icon='item_13427',Type=41,MaxNum=1,SellPrice=1,Desc='一盏明灯，一个方箱。累了的时候，这样就足够休息了，如果来杯饮料自然更好。',}",
  [13428] = "{id=13428,NameZh='爱的门牌号',Icon='item_13433',Type=41,MaxNum=1,SellPrice=1,Desc='偷偷把情书投进去，闭上眼睛祈祷。放心吧，邮箱一定会把思念传达到。',}",
  [13429] = "{id=13429,NameZh='青金石灯',Icon='item_13420',Type=41,MaxNum=1,SellPrice=1,Desc='当黑夜降临之时，就是青金石灯的工作时间。荧荧青光不仅提供视野光线，甚至还能驱赶蚊虫。',}",
  [13430] = "{id=13430,NameZh='迎客菇',Icon='item_13424',Type=41,MaxNum=1,SellPrice=1,Desc='一棵、两棵、三四棵，都在门前争迎客。',}",
  [13431] = "{id=13431,NameZh='篝火营帐',Icon='item_13434',Type=41,MaxNum=1,SellPrice=1,Desc='在矿山劳累一天过后，躲进三房两厅的营帐中舒舒服服休息一晚……你说帐篷不可能这么大？别忘了，这可是幻想之地！',}",
  [13432] = "{id=13432,NameZh='无价之花',Icon='item_13423',Type=41,MaxNum=1,SellPrice=1,Desc='只需要充足的光线和几捧清水就足够了。这些鲜艳的小花所带来的的快乐，并不比百宝屋的礼物要少哟！',}",
  [13433] = "{id=13433,NameZh='蘑菇矮凳',Icon='item_13425',Type=41,MaxNum=1,SellPrice=1,Desc='就此证明蘑菇是好客的主人。你看，它为了让客人落座，甚至努力长出了矮凳！',}",
  [13434] = "{id=13434,NameZh='眺望远方号',Icon='item_13421',Type=41,MaxNum=1,SellPrice=1,Desc='悬浮在云海群岛周边的这艘飞空艇名叫“眺望远方”，意思就是，它真的只能用来眺望而已……',}",
  [13500] = "{id=13500,NameZh='粗铁铸剑',Icon='item_40332',Type=160,MaxNum=1,SellPrice=1,Desc='熔炼铁矿石，直接灌造成型的朴实铁剑。虽然不怎么精致锋锐，但是被打到的话也是非常疼的。',}",
  [13501] = "{id=13501,NameZh='原木弩',Icon='item_41212',Type=160,MaxNum=1,SellPrice=1,Desc='坚实原木制成的弩箭，使用起来有点重。由于杀伤力很可观，不用的时候请务必小心保存，避免误伤。',}",
  [13502] = "{id=13502,NameZh='伐木斧',Icon='item_41802',Type=160,MaxNum=1,SellPrice=1,Desc='易于手握的粗犷斧头。由于双面开刃，可以有效提升伐木效率，但挥动时请一定小心附近没有其他伙伴！',}",
  [13503] = "{id=13503,NameZh='双持木锤',Icon='item_41501',Type=160,MaxNum=1,SellPrice=1,Desc='带有铁蒺藜的木锤，用途多样。据某位匿名厨师所言，用来擀面是一流的。',}",
  [13504] = "{id=13504,NameZh='尖头叉',Icon='item_41537',Type=160,MaxNum=1,SellPrice=1,Desc='细长结实的铁杖，尖头部分的攻击力很惊人。杖身则可以用来晾晒衣物。',}",
  [13505] = "{id=13505,NameZh='蒙皮盾',Icon='item_42571',Type=160,MaxNum=1,SellPrice=1,Desc='造型非常帅气英武，但实际上是木质的……防御力马马虎虎，胜在轻便好用。使用者甚至可以拿它当枕头。',}",
  [13506] = "{id=13506,NameZh='鹤嘴镐',Icon='item_40005',Type=160,MaxNum=1,SellPrice=1,Desc='如果木柄断了，随便找根树枝塞进去就能继续用。是很方便的镐子！',}",
  [13507] = "{id=13507,NameZh='跌打损伤膏',Icon='item_13507',Type=160,MaxNum=1,SellPrice=1,}",
  [13508] = "{id=13508,NameZh='宝石银镜',Icon='item_13508',Type=160,MaxNum=1,SellPrice=1,Desc='纤毫毕现地照出影子的明镜，虽然既不是宝石也不是银做的。',}",
  [13509] = "{id=13509,NameZh='金铲铲',Icon='item_13509',Type=160,MaxNum=1,SellPrice=1,Desc='料理界的究极秘宝，世间厨师的毕生所求。使用它做出的菜品，都会散发出不可思议的诱人香气，让每位品尝者都情不自禁地哦呼三声，以示赞美。',}",
  [13520] = "{id=13520,NameZh='轻云酥酪',Icon='item_13520',Type=610,MaxNum=99999,SellPrice=100,Desc='“这是我这辈子吃过最美味的甜品，绝妙到可以与天体运行相媲美，我值得庆幸此刻活着，只因我的生命中能尝到这样美好的东西。”——某位不愿透露姓名的云岛居民',}",
  [13600] = "{id=13600,NameZh='灵感因子',Icon='item_13600',Type=79,MaxNum=99999,SellPrice=1,Desc='“在蛛丝马迹中迸发出的灵感，往往会成为破解谜题的钥匙。”可用于升级冒险者的探案能力。',}",
  [13601] = "{id=13601,NameZh='七王室副本零件',Icon='item_13601',Type=41,MaxNum=99999,SellPrice=1,}",
  [13602] = "{id=13602,NameZh='七王室副本锤子',Icon='item_13602',Type=41,MaxNum=99999,SellPrice=1,}",
  [13603] = "{id=13603,NameZh='悲伤符石',Icon='item_13603',Type=41,MaxNum=99999,SellPrice=1,Desc='散发着悲伤气息的符石，是心象之门形成的原因，只有将对应的三个符石镶嵌到心象之门上，心象之门才能被心象之钥打开。',}",
  [13604] = "{id=13604,NameZh='心象之钥',Icon='item_13604',Type=41,MaxNum=99999,SellPrice=1,Desc='用于开启心象之门的钥匙，可以拆卸并使用在不同的启动器上。',}",
  [13605] = "{id=13605,NameZh='心象之镜·Ⅰ',Icon='item_13605',Type=41,MaxNum=99999,SellPrice=1,Desc='记录着记忆的心象之镜，收集齐四片心象之镜将可以打开埋藏在深处的心象之门，获知她隐藏在内心深处的记忆......',}",
  [13606] = "{id=13606,NameZh='心象之镜·Ⅱ',Icon='item_13606',Type=41,MaxNum=99999,SellPrice=1,Desc='记录着记忆的心象之镜，收集齐四片心象之镜将可以打开埋藏在深处的心象之门，获知她隐藏在内心深处的记忆......',}",
