  [14002] = "{id=14002,NameZh='猫耳发圈图纸',Icon='item_45002',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=250,ComposeID=14002,Desc='猫耳模样的发圈。',Feature=1,}",
  [14003] = "{id=14003,NameZh='粉纱发圈图纸',Icon='item_45003',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=250,ComposeID=14003,Desc='用来固定头发的发圈，上面有一个小蝴蝶结为重点。',Feature=1,}",
  [14004] = "{id=14004,NameZh='天使发圈图纸',Icon='item_45004',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=2500,ComposeID=14004,Desc='搜集天使的羽毛所制成的发圈。',Feature=1,}",
  [14005] = "{id=14005,NameZh='渔夫帽[1]图纸',Icon='item_45005',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=250,ComposeID=14005,Desc='可以遮蔽阳光的宽松帽子。钓鱼爱好者常备',Feature=1,}",
  [14006] = "{id=14006,NameZh='紫蝶发带[1]图纸',Icon='item_45006',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=250,ComposeID=14006,Desc='用布条做成的蝴蝶发带，主要是给女性使用。',Feature=1,}",
  [14007] = "{id=14007,NameZh='黄金帽图纸',Icon='item_45007',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=2500,ComposeID=14007,Desc='用黄金制成的保护头部用器具。因为主要的原料为黄金，所以相当的坚硬，防御力强。不可破坏。',Feature=1,}",
