  [14235] = "{id=14235,NameZh='趴趴初心者·女图纸',Icon='item_45235',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=250,ComposeID=14235,Desc='不管经历了多少冒险的旅程，时刻勿忘初心。为了纪念这一刻，由卡普拉公司的美少女小姐姐们手工亲手缝制的玩偶，充满了温暖和关怀。（虽然是女孩子造型的娃娃，但是男生也可以佩戴哦~）',Feature=1,}",
  [14236] = "{id=14236,NameZh='趴趴初心者·男图纸',Icon='item_45236',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=250,ComposeID=14236,Desc='不管经历了多少冒险的旅程，时刻勿忘初心。为了纪念这一刻，由卡普拉公司的美少女小姐姐们手工亲手缝制的玩偶，充满了温暖和关怀。（虽然是男孩子造型的娃娃，但是女生也可以佩戴哦~）',Feature=1,}",
  [14245] = "{id=14245,NameZh='巧克力甜甜圈图纸',Icon='item_145245',Type=50,Quality=2,MaxNum=99999,AuctionPrice=0,SellPrice=250,ComposeID=14245,Desc='知名甜品品牌【ALICE & IRIS】的年度巨献：经典款的巧克力甜甜圈，因为使用了上等素材，所以口感极佳！而且由于主厨的手艺，所以一直以近乎完美的造型深的孩子们的喜爱！',Feature=1,}",
  [14246] = "{id=14246,NameZh='金色信仰图纸',Icon='item_145246',Type=50,Quality=2,MaxNum=99999,AuctionPrice=0,SellPrice=250,ComposeID=14246,Desc='“神的地上代理人，神罚的地上代行者，我们武道家，我们的使命是，以我们极限的肉体，违背神者，愚蠢的人之肉身，徘徊的人之肉身，彻底的追击，把他抹杀及消灭…”后面的字有些模糊，已经无法分辨。',Feature=1,}",
  [14247] = "{id=14247,NameZh='英灵·亡者抉择图纸',Icon='item_45247',Type=50,Quality=2,MaxNum=99999,SellPrice=100,ComposeID=14247,Desc='奥尔露恩代替英灵殿赐予冒险者的奖励，亡者抉择，象征着英灵殿之威严，同时也揭示着英灵殿的职责所在——为瓦尔哈拉殿堂挑选英勇的灵魂。',Feature=1,}",
  [14248] = "{id=14248,NameZh='布谷布谷图纸',Icon='item_45248',Type=50,Quality=3,MaxNum=99999,SellPrice=500,ComposeID=14248,Feature=1,}",
