  [14255] = "{id=14255,NameZh='永动发条图纸',Icon='item_45255',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=500,ComposeID=14255,Desc='如同白银色纹章般的冷月悬挂于寂静天空，停摆的时装再次转动，少女手里握紧着这个金属片，从此，被人类世界排挤的她得到了一个安身之处和自己的守护者。-----------【卡普拉童话物语·第四卷，三十七章：《大钟与少女》',Feature=1,}",
  [14256] = "{id=14256,NameZh='电波天线图纸',Icon='item_45256',Type=50,Quality=2,MaxNum=99999,SellPrice=100,Feature=1,}",
  [14257] = "{id=14257,NameZh='会动的蝴蝶[1]图纸',Icon='item_45257',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=2500,ComposeID=14257,Desc='当人类文明渐渐消逝在时光的长河中，废墟里只剩下这个机械大家伙，还有他的伙伴。',Feature=1,}",
  [14258] = "{id=14258,NameZh='时光之轮[1]图纸',Icon='item_45258',Type=50,Quality=4,MaxNum=99999,SellPrice=100,Feature=1,}",
  [14259] = "{id=14259,NameZh='兰草头饰图纸',Icon='item_45259',Type=50,Quality=3,MaxNum=99999,SellPrice=100,Feature=1,}",
  [14261] = "{id=14261,NameZh='海蓝发带图纸',Icon='item_45261',Type=50,Quality=2,MaxNum=99999,AuctionPrice=0,SellPrice=250,ComposeID=14261,Desc='佩戴上这个发带时，仿佛在闭上眼时可以听到来自大海和山脉的声音，究竟是谁在呼唤呢？',Feature=1,}",
  [14262] = "{id=14262,NameZh='山茶花发带[1]图纸',Icon='item_45262',Type=50,Quality=2,MaxNum=99999,AuctionPrice=0,SellPrice=250,ComposeID=14262,Desc='用山茶花制作的发带。',Feature=1,}",
  [14263] = "{id=14263,NameZh='魔法茶壶图纸',Icon='item_45263',Type=50,Quality=2,MaxNum=99999,AuctionPrice=0,SellPrice=250,ComposeID=14263,Desc='虽然感觉不到重量，但是这个茶壶里确实装满了水，听说幸运的人可以喝上用这个魔法茶壶烧开的水冲泡的红茶。',Feature=1,}",
  [14264] = "{id=14264,NameZh='风车头饰[1]图纸',Icon='item_45264',Type=50,Quality=3,MaxNum=99999,AuctionPrice=0,SellPrice=500,ComposeID=14264,Desc='儿童时代，追逐着风，那份心情，至今还历历在目，即使再也无法回到过去，至少我们现在可以继续当一个贪玩的孩子。',Feature=1,}",
  [14265] = "{id=14265,NameZh='雨伞帽图纸',Icon='item_45265',Type=50,Quality=3,MaxNum=99999,AuctionPrice=0,SellPrice=500,ComposeID=14265,Desc='可以为你遮风挡雨的伞型头饰，因为可以自动识别降雨，所以洗澡前记得要脱下来。',Feature=1,}",
  [14266] = "{id=14266,NameZh='恋之心·夏图纸',Icon='item_45266',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=250,ComposeID=14266,Desc='夏日的蝉鸣，海边的金鱼火花，恋爱的心在悸动着。',Feature=1,}",
  [14267] = "{id=14267,NameZh='恋之心·秋图纸',Icon='item_45267',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=250,ComposeID=14267,Desc='秋日的麦田，向日葵的花海，恋爱的心在思念。',Feature=1,}",
  [14268] = "{id=14268,NameZh='恋之心·冬图纸',Icon='item_45268',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=250,ComposeID=14268,Desc='冬日的银白，家门口推起的雪人，恋爱的心在期待。',Feature=1,}",
  [14269] = "{id=14269,NameZh='恋之心·春图纸',Icon='item_45269',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=250,ComposeID=14269,Desc='春日的花香，候鸟回归的城市，恋爱的心在发芽。',Feature=1,}",
