  [14452] = "{id=14452,NameZh='戌头巾图纸',Icon='item_45452',Type=50,MaxNum=99999,SellPrice=100,ComposeID=14452,Desc='超绝可爱的新年限定吉祥汪头饰，据说佩戴此头饰会旺哦！',Feature=1,}",
