  [14515] = "{id=14515,NameZh='西瓜猫图纸',Icon='item_45515',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=250,ComposeID=14515,Desc='夏日的夜晚，蚊香的味道淡淡地飘着，风铃被晚风吹得叮当作响，西瓜是这时候孩子们的最爱呢~',Feature=1,}",
