  [14542] = "{id=14542,NameZh='约定之冕图纸',Icon='item_45542',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14542,Desc='月满樱枝，澄净的宝石折射出特有的华彩。满心期待的人终于如约而至，戴上冠冕，完成月光下的约定。',Feature=1,}",
  [14548] = "{id=14548,NameZh='今晚吃鸡餐盒图纸',Icon='item_45548',Type=50,Quality=2,MaxNum=99999,AuctionPrice=0,SellPrice=100,ComposeID=14548,Desc='大吉大利，今晚吃鸡！',Share=1,Feature=1,}",
  [14550] = "{id=14550,NameZh='哥布灵飞行员图纸',Icon='item_45550',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14550,Desc='突突突~原地起飞！当然只有哥布灵才能驱动哥布灵直升机，冒险者们只能戴着看看啦~',Feature=1,}",
  [14574] = "{id=14574,NameZh='金苹果的秘密图纸',Icon='item_45574',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14574,Desc='传说神族之间的婚礼有一项习俗，用箭矢射中天地树上的金苹果，就能保佑婚姻美满，永远和睦…至于为什么会这样，恐怕人类是无法搞懂了。',Feature=1,}",
  [14575] = "{id=14575,NameZh='朱诺守备官图纸',Icon='item_45575',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14575,Desc='被朱诺市民评为最让人有安全感的帽子，只要看到戴着它的人来了，那正义也就来了。',Feature=1,}",
  [14587] = "{id=14587,NameZh='大吉大利桶图纸',Icon='item_45587',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14587,Desc='能一个人吃完整整一个大吉大利桶也是勇气的证明呢！亲爱的冒险者快戴上它吧！',Share=1,Feature=1,}",
  [14595] = "{id=14595,NameZh='国王波利的威严图纸',Icon='item_45595',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14595,Desc='欢迎来到波利王国的假日派对！',Feature=1,}",
  [14596] = "{id=14596,NameZh='国王波利的忧郁图纸',Icon='item_45596',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14596,Desc='欢迎来到波利王国的假日派对！',Feature=1,}",
  [14617] = "{id=14617,NameZh='趴趴欧布图纸',Icon='item_45602',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14617,Desc='趴在头上的欧布奥特曼，对待邪恶的力量，要敢于说出“哦~不！”',Feature=1,}",
  [14621] = "{id=14621,NameZh='曙光队长帽图纸',Icon='item_45621',Type=50,MaxNum=99999,SellPrice=100,ComposeID=14621,Desc='贤者塞壬的帽子，听说只有勇者才能戴上这个帽子',Feature=1,}",
  [14628] = "{id=14628,NameZh='鹡鸰头冠[1]图纸',Icon='item_45628',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14628,Desc='以鸟人哈比翅膀内侧的羽毛所制作出的头冠，据说长期佩戴后，头发会在无风的环境下也能向后飘散',Feature=1,}",
  [14629] = "{id=14629,NameZh='土拨土拨帽[1]图纸',Icon='item_45629',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14629,Desc='据说土拨鼠之间夸赞同类很厉害，就会发出“土拨土拨”的叫声，所以戴上这顶帽子后，说不定冒险家也会变得厉害起来呢！',Feature=1,}",
  [14630] = "{id=14630,NameZh='炎之小魔帽[1]图纸',Icon='item_45630',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14630,Desc='最近在女性冒险家中最受欢迎的帽子款式——据说还有部分男性冒险家也为这款帽子沦陷了？',Feature=1,}",
  [14631] = "{id=14631,NameZh='高原花发夹[1]图纸',Icon='item_45631',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14631,Desc='震惊！把这个发夹送给心爱的姑娘，表白成功率高达99%……她不喜欢你的情况属于那1%。',Feature=1,}",
  [14632] = "{id=14632,NameZh='懒懒波利[1]图纸',Icon='item_45632',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14632,Desc='连续三届全大陆最受欢迎的魔物，摸起来的手感甚至比撸猫还要舒服哟！-所有波利心中都有一个疑惑：吃饭睡觉之后…你们为什么总要打我？',Feature=1,}",
  [14633] = "{id=14633,NameZh='天兽角图纸',Icon='item_45633',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14633,Desc='据说在神界阿斯加德居住着一种凶猛的天兽，它们每年都要脱落自己的双角，等新的双角生产出来后，会比旧的角更为锋利坚硬。',}",
  [14634] = "{id=14634,NameZh='羽毛发卡[1]图纸',Icon='item_45634',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=14634,}",
  [14635] = "{id=14635,NameZh='天空护卫头盔[1]图纸',Icon='item_45635',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14635,Desc='只有朱诺最高阶层的护卫官才有机会使用的头盔，它闪耀的金色光芒能让一切罪恶都无所遁形。',}",
  [14636] = "{id=14636,NameZh='见习飞空艇船长帽图纸',Icon='item_45636',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14636,Desc='恭喜你成为了一名见习飞空艇船长，今后你的日常生活都要在天上了，可不要晕船了哟~',}",
  [14638] = "{id=14638,NameZh='打铁面具图纸',Icon='item_45638',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14638,Desc='《铁匠手册》第三章第一节：打铁时请务必佩戴专业面具，以防止火星子溅到眼睛引起受伤。',}",
  [14639] = "{id=14639,NameZh='风车头饰图纸',Icon='item_45639',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=14639,}",
  [14640] = "{id=14640,NameZh='独角兽盔图纸',Icon='item_45640',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14640,Desc='独角兽是能带来幸运的神兽，用它的角和鬃毛制作的头盔，想必戴上了运气一定会超厉害的吧！',}",
  [14641] = "{id=14641,NameZh='生命之轮图纸',Icon='item_45641',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=14641,Desc='基因学者们从基因链的结构中研究出了一种极为优雅的形状，经过改良设计后，将其制成了帽子。',}",
  [14642] = "{id=14642,NameZh='杀意犀角图纸',Icon='item_45642',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=14642,Desc='尖锐的角形装饰物材质极硬，顶端锋利异常，如果在必要的时候拔下双角当作武器，敌人必定措手不及。',}",
  [14643] = "{id=14643,NameZh='飞天猫仔帽图纸',Icon='item_45643',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=14643,Desc='伟大机匠察尔伊森养了一只调皮的猫，那只猫曾偷偷用他的机甲飞上了天空，为了纪念这件有趣的事情，察尔伊森托人制作了这款为猫订制的飞行帽。',}",
  [14644] = "{id=14644,NameZh='护林小队帽图纸',Icon='item_45644',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=14644,Desc='斐扬护林队毕生致力于抓捕非法伐木者，而这顶帽子就是护林队成员自豪的象征。',}",
  [14645] = "{id=14645,NameZh='斑毛狼耳图纸',Icon='item_45645',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=14645,Desc='以沙漠之狼的毛发制作的头饰，戴上之后可以可以听见非常细微的声音，在侦察方面有着极好的效果。',}",
  [14646] = "{id=14646,NameZh='纯白尖塔图纸',Icon='item_45646',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=14646,Desc='传说曾经有位偏执的大法师，用了一生的时间研究白色监狱魔法的奥秘，而他去世后，就将那份奥秘藏在了这顶帽子里。',}",
  [14647] = "{id=14647,NameZh='御龙银盔图纸',Icon='item_45647',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=14647,Desc='这顶头盔的防御力之强甚至可以承受龙族的爪击，但其惊人的重量可能也只有皇家卫士才能驾驭。',}",
  [14648] = "{id=14648,NameZh='魔力激荡者图纸',Icon='item_45648',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=14648,Desc='翠绿魔石镶嵌在绯红魔石上，魔力的激荡将会刺激佩戴者发挥体内深层未知的力量。',}",
  [14649] = "{id=14649,NameZh='毗摩质多罗的角图纸',Icon='item_45649',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=14649,Desc='以古代修罗·毗摩质多罗的样貌为基准打造的赤色尖角，戴上它仿佛能感受到古代修罗炙热的灵魂。',}",
  [14650] = "{id=14650,NameZh='圣十字使图纸',Icon='item_45650',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=14650,Desc='正天使双翼代表自由，逆天使双翼代表庇护。这顶帽子显然是后者，能庇护佩戴者不受恶魔的迫害。',}",
  [14651] = "{id=14651,NameZh='啾啾云雀图纸',Icon='item_45651',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=14651,Desc='作为一只特立独行的云雀，啾啾喜欢在冒险者的头上筑巢，如果你能坚持一个月不洗头的话，那么赶紧把这位小歌唱家请上你的头顶吧~',}",
  [14686] = "{id=14686,NameZh='卡普拉夏日甜筒图纸',Icon='item_45686',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14686,Desc='喜欢恶作剧的朋友竟然把甜筒扣到我的脑袋上了！！但是我一点都不生气，因为这样实在是太凉快啦~~',}",
  [14687] = "{id=14687,NameZh='鹉雀发夹图纸',Icon='item_45687',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14687,Desc='以鹉雀鸟的羽毛制作的神奇头饰，黄色羽毛的部分温热，蓝色羽毛的部分清凉。',}",
  [14688] = "{id=14688,NameZh='鹦鹦之羽图纸',Icon='item_45688',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14688,Desc='以鹦鹦鸟张开的双翼为原型，精心打造的头冠，中间镶嵌的宝石和鹦鹦鸟的瞳孔有着一样的颜色。',}",
  [14689] = "{id=14689,NameZh='双角犀鸟冠图纸',Icon='item_45689',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14689,Desc='仿造双角犀鸟的样子制作的金质头冠，在阳光下会反射出璀璨的光芒。',}",
  [14690] = "{id=14690,NameZh='黄金触角[1]图纸',Icon='item_45690',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=14690,Desc='以昆虫触角的原理为基础打造的超级环境探测装置，虽然看起来不太严肃，但其实是非常先进的科学产物。',}",
  [14691] = "{id=14691,NameZh='四翼天使图纸',Icon='item_45691',Type=50,Quality=4,MaxNum=99999,SellPrice=100,ComposeID=14691,Desc='施加着四翼天使·拉法叶的魔力的头冠，拥有治愈佩戴者心灵的神奇力量。',}",
  [14837] = "{id=14837,NameZh='悲伤召唤师头饰[1]图纸',Icon='item_45837',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14837,Desc='用骷髅作为装饰的魔女尖帽，散发着悲伤的气息，这顶帽子的主人，究竟拥有着怎样的过往呢？',}",
  [14838] = "{id=14838,NameZh='血色红帽[1]图纸',Icon='item_45838',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14838,Desc='曾经有一名叫做罗夏薇拉的女孩惨遭狼外婆毒害，这顶血色红帽，是她曾经最喜欢的东西......',}",
  [14839] = "{id=14839,NameZh='招魂蜡烛[1]图纸',Icon='item_45839',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14839,Desc='墓碑怪人头顶的蜡烛，散发着幽蓝的火光，据说只要把它顶在头上，就会招来一些不可名状的东西......',}",
  [14840] = "{id=14840,NameZh='乌鸦头饰[1]图纸',Icon='item_45840',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14840,Desc='戴上它，稻草人就会把你当作好朋友，甚至和你分享它的心路历程。',}",
  [14841] = "{id=14841,NameZh='趴趴鬼娃[1]图纸',Icon='item_45841',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14841,Desc='这个坏脾气的小家伙可不好对付，要是你惹她生气了，她就会把你精心梳理一早上的发型毫不客气地弄乱，我新弄的移花接木发型就是这样被摧毁的！',}",
