  [14844] = "{id=14844,NameZh='诅咒兔娃[1]图纸',Icon='item_45844',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=14844,Desc='带着诡异气息的兔子玩偶，不知为何，每天早上它都不在原本的位置上......呋嘿嘿，兔兔这么可爱，怎么可能会做坏事呢？',}",
