  [14849] = "{id=14849,NameZh='超强力蚊香圈图纸',Icon='item_45849',Type=50,MaxNum=99999,SellPrice=100,ComposeID=14849,Desc='普通的蚊香顶多只能毒死蚊子，但这盘蚊香连人都能毒死——所以至今也没人敢点着它睡觉。',Feature=1,}",
