  [16019] = "{id=16019,NameZh='乐园团背包图纸',Icon='item_47019',Type=50,MaxNum=99999,AuctionPrice=0,SellPrice=50,ComposeID=16019,Desc='乐园团为新人冒险者准备的背包。体贴的准备了地图，指南针，针线包，蝴蝶翅膀等冒险物品。',Feature=1,}",
