  [16021] = "{id=16021,NameZh='黑猫雷蒙盖顿图纸',Icon='item_47021',Type=50,Quality=3,MaxNum=99999,SellPrice=100,Desc='天哪！背上这个充满贵族皇家气质的玩偶，感觉整个人都升华了一样！这雍容华丽的手感，每天摸着它都能笑着睡去。',Feature=1,}",
  [16022] = "{id=16022,NameZh='喷射哥布灵背包图纸',Icon='item_47022',Type=50,Quality=3,MaxNum=99999,SellPrice=500,ComposeID=16022,Desc='圈绕在条盒内的是发条，主传动齿轮采用了圆弧齿形，点火后动听的机械声轰轰作响，就是那么带感！就是那么科技！就是那么骄傲！',Feature=1,}",
  [16023] = "{id=16023,NameZh='暗黑领主之翼图纸',Icon='item_47023',Type=50,MaxNum=99999,SellPrice=100,Feature=1,}",
