  [16034] = "{id=16034,NameZh='月之兔兔图纸',Icon='item_47050',Type=50,MaxNum=99999,SellPrice=100,Feature=1,}",
  [16035] = "{id=16035,NameZh='蔚蓝的依斯鲁得海图纸',Icon='item_47035',Type=50,MaxNum=99999,SellPrice=100,Desc='航海日记的最后写到：在月亮第51次沉入宛如天鹅绒的大海，我们终于看到了岸边的灯火，康韦斯特和摩尔仑的眼眶里都挂着激动的泪水，这二个傻大个儿的哭泣，除了在父亲的葬礼上，这还是我人生中第二次看到。我们沉默但默契地开始拿出手摇浆，哼着《天之津的老人》，我们出生后就学会的歌曲，然而现在，我们驶向岸边，那个父亲和母亲的故乡。',Feature=1,}",
  [16036] = "{id=16036,NameZh='万圣惊魂夜图纸',Icon='item_47036',Type=50,MaxNum=99999,SellPrice=100,Feature=1,}",
  [16037] = "{id=16037,NameZh='温蒂图纸',Icon='item_47037',Type=50,MaxNum=99999,SellPrice=100,Desc='温蒂明白，它必须始终注视着艾希。艾希明白，温蒂始终会注视着她。哪怕温蒂的背后不只是一双眼睛，但是那其中只要有TA在，她便心存温暖。',Feature=1,}",
  [16039] = "{id=16039,NameZh='金色圣诞铃铛图纸',Icon='item_47039',Type=50,Quality=4,MaxNum=99999,SellPrice=2500,ComposeID=16039,Feature=1,}",
