  [16076] = "{id=16076,NameZh='透明翅膀图纸',Icon='item_47076',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16076,Desc='万千信念汇聚而成的翅膀，缺乏信念的人，是看不到的哦~',Share=1,Feature=1,}",
  [16078] = "{id=16078,NameZh='燃烧禁止图纸',Icon='item_47078',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16078,Desc='自从上次厨房着火之后，忽克连就开始整天愁眉苦脸的……直到他发明了这个东西，好像叫做灭火器？！',Feature=1,}",
  [16094] = "{id=16094,NameZh='曙光之翼图纸',Icon='item_47094',Type=50,Quality=4,MaxNum=99999,SellPrice=100,ComposeID=16094,Desc='阳光辉映在正义的羽翼之上，折射出金色的光耀。既是荣誉的象征，也是一颗赤诚勇敢的心在诉说关于天空的歌谣。',Feature=1,}",
  [16096] = "{id=16096,NameZh='卡浩的庇护图纸',Icon='item_47096',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16096,Desc='炎之领主的庇护无疑是强大的，因为有了它，冒险家在冬天都不用穿外套就可以出去冒险了。',Feature=1,}",
  [16097] = "{id=16097,NameZh='随身小恶魔图纸',Icon='item_47097',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16097,Desc='每次冒险家想要起床的时候，这个小家伙都会推荐冒险家多睡十分钟…嗯，把它带在身边可能是个错误的选择吧。',Feature=1,}",
  [16098] = "{id=16098,NameZh='瓦蓝之印图纸',Icon='item_47101',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16098,Desc='时间神蒙迪尔法利的两大护卫种族之一，瓦蓝族的护卫长才能拥有的宝物，月出时，它的魔力会达到顶峰。',}",
  [16099] = "{id=16099,NameZh='瓦蓝之轮图纸',Icon='item_47102',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16099,Desc='时间神蒙迪尔法利的两大护卫种族之一，瓦蓝族的大族长才能拥有的宝物，子夜时，它的魔力会达到顶峰。',}",
  [16100] = "{id=16100,NameZh='瓦蓝之章图纸',Icon='item_47103',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16100,Desc='时间神蒙迪尔法利的两大护卫种族之一，瓦蓝族的祭祀长才能拥有的宝物，月落时，它的魔力会达到顶峰。',}",
  [16101] = "{id=16101,NameZh='绯红之印图纸',Icon='item_47098',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16101,Desc='时间神蒙迪尔法利的两大护卫种族之一，绯红族的护卫长才能拥有的宝物，日出时，它的魔力会达到顶峰。',}",
  [16102] = "{id=16102,NameZh='绯红之轮图纸',Icon='item_47099',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16102,Desc='时间神蒙迪尔法利的两大护卫种族之一，绯红族的大族长才能拥有的宝物，正午时，它的魔力会达到顶峰。',}",
  [16103] = "{id=16103,NameZh='绯红之章图纸',Icon='item_47100',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16103,Desc='时间神蒙迪尔法利的两大护卫种族之一，绯红族的祭祀长才能拥有的宝物，日落时，它的魔力会达到顶峰。',}",
  [16109] = "{id=16109,NameZh='天使之证图纸',Icon='item_47109',Type=50,Quality=4,MaxNum=99999,SellPrice=100,ComposeID=16109,Desc='只有心灵绝对纯洁，信仰无比坚定的人才能获得天使的认可，而一旦得到了天使的认可，这双羽翼便是属于你的证明，它将永生永世庇护你的灵魂。',}",
  [16117] = "{id=16117,NameZh='海拉的仆从图纸',Icon='item_47117',Type=50,Quality=2,MaxNum=99999,SellPrice=100,ComposeID=16117,Desc='这个难缠的小家伙最喜欢趁你不注意到处乱飘，要找一个能拴住它的项圈可真不容易！能治它的估计只有死亡女神本人了。',}",
  [16119] = "{id=16119,NameZh='万象月盘图纸',Icon='item_47119',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16119,Desc='“蕴藏着世间万物规律的月相之盘，请赐予我再次面对过去的勇气，当那晚的月光重新映照我的脸庞，希望这一次的轮回我能选对正确的道路。”——某个时空旅行者',}",
  [16120] = "{id=16120,NameZh='恶魔咕波钟图纸',Icon='item_47120',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16120,Desc='是谁把我的钟里的咕咕鸽换成了恶魔波利的？给我出来！',}",
  [16121] = "{id=16121,NameZh='幽灵船舵图纸',Icon='item_47121',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16121,Desc='背上这个幽灵船舵，海盗之王肩膀上的乌鸦就会飞过来把你认作主人，海盗之王擦了擦自己外套上鸟屎，松了一口气。',}",
  [16122] = "{id=16122,NameZh='鹗枭宝宝图纸',Icon='item_47122',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16122,Desc='就连鹗枭男爵也曾是个宝宝，这年头谁还不是个宝宝呢？',}",
  [16128] = "{id=16128,NameZh='针筒背饰图纸',Icon='item_47128',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16128,}",
  [16129] = "{id=16129,NameZh='断剑背饰图纸',Icon='item_47129',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16129,}",
  [16133] = "{id=16133,NameZh='骨翼天使图纸',Icon='item_47133',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,AdventureReward={buffid={61001680}},StorageReward={buffid={80013060}},ComposeID=16133,Desc='“这可是近来天国中最流行的翅膀款式！！相较于普通的羽翼更容易打理，外观也更为时尚！！……我才没有受到魔鬼的蛊惑呢！！！”',Feature=1,}",
  [16151] = "{id=16151,NameZh='五号机头盔图纸',Icon='item_47151',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16151,Desc='“幸福不会自己走过来，所以我要向他走过去，一日一步，三日三步......”——真希波·玛丽·伊兰崔亚斯',Feature=1,TFValidDate='2019-01-28 05:00:00',ValidDate='2019-01-31 05:00:00',}",
  [16152] = "{id=16152,NameZh='协奏发条图纸',Icon='item_47152',Type=50,MaxNum=99999,SellPrice=100,Desc='转一圈，你就能唱音乐剧；转两圈，你就能跳古典舞；转三圈，你就能边跳边唱；转四圈…别，你可能会坏的。',}",
  [16169] = "{id=16169,NameZh='兔兔彩蛋背包图纸',Icon='item_47169',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16169,Desc='充满了复活节气息的背包，色彩交织间溢满了早春的欢喜。“不可以砸破彩蛋，否则兔子会溜走哦！”',Feature=1,TFValidDate='2019-04-18 05:00:00',ValidDate='2019-04-21 05:00:00',}",
  [16174] = "{id=16174,NameZh='龙熠图纸',Icon='item_47174',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16174,Desc='迪塔勒泰晤勒身上最坚硬的一块鳞片，甚至可以抵挡魔王梦罗克的一击，是大陆上所有冒险者梦寐以求的珍宝！',Feature=1,}",
  [16182] = "{id=16182,NameZh='铃音金翼图纸',Icon='item_47182',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=16182,Desc='一铃摇曳生，神音庇左右，双铃叮咚响，圣光照四方。金铃轻摇，愿神祇永远守护你，远离一切黑暗与腐朽。',}",
  [16186] = "{id=16186,NameZh='冒险家的旅途图纸',Icon='item_47186',Type=50,MaxNum=99999,SellPrice=100,ComposeID=16186,Desc='大冒险家多拉贡的背包。继承这个背包的人，也会继承他的睿智、聪慧……和冷笑话。',}",
  [16188] = "{id=16188,NameZh='绯色烛光图纸',Icon='item_47188',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16188,Desc='上一任森林女巫留下的烛台，巴西里斯克吐出的魔法火焰可在其中永恒燃烧。',}",
  [16189] = "{id=16189,NameZh='甜心呱太图纸',Icon='item_47189',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16189,Desc='“呱呱呱！所有可爱的东西都是我们哒！”甜心罗达蛙的背包。沉甸甸的，里面塞满了它们偷来的糖果。',}",
  [16190] = "{id=16190,NameZh='蜂蜜糖罐图纸',Icon='item_47190',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16190,Desc='这罐蜂蜜诞生的那天，狂野蜂兵特意烫了新的发型，并请了十只摇滚蝗虫谱写了新歌以作纪念。',}",
  [16191] = "{id=16191,NameZh='呆呆鼬仔图纸',Icon='item_47191',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16191,Desc='毛绒绒的鼬仔是大陆上的高人气萌物之一，黑豆一样的眼睛，粉嫩的爪爪，外加上卷卷的呆毛，没有人能抵挡的了它的卖萌攻击，只是被它简单的看一眼，你的心就会融化掉。',}",
  [16192] = "{id=16192,NameZh='雪球背包图纸',Icon='item_47192',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16192,Desc='冰镐！冰锤！小雪兽！全部准备好！让我们一起向着未知的冰域出发，进行一场奇妙的冰域探险！',}",
  [16193] = "{id=16193,NameZh='珈利行囊图纸',Icon='item_47193',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16193,Desc='鬣狗珈利永远会记得这个行囊，这是小主人最后一次见面留给它的东西，里面装着他们一起玩过的飞盘，珈利的磨牙棒，还有小主人最爱的机器玩偶，这些都是它们的美好回忆，可惜都只能永久的封存在这个行囊里。',}",
  [16196] = "{id=16196,NameZh='喵星之王图纸',Icon='item_47196',Type=50,Quality=2,MaxNum=99999,SellPrice=100,ComposeID=16196,}",
  [16201] = "{id=16201,NameZh='凌宇星披图纸',Icon='item_47201',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16201,Desc='一件穿在身上气势倍增的披风，天下尽在自己手中，无所畏惧！',}",
  [16202] = "{id=16202,NameZh='猩红梦魇图纸',Icon='item_47202',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16202,Desc='赤红的剑身散发出魔性的气息，那一抹红色危险而美丽，让人欲罢不能。',}",
  [16203] = "{id=16203,NameZh='海之誓约图纸',Icon='item_47203',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16203,Desc='晶莹珍珠点缀着琴弦，缓缓拨动时，无比美妙的声音编织成真挚的誓约。',Feature=1,}",
  [16204] = "{id=16204,NameZh='祖蛇妖剑图纸',Icon='item_47204',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16204,Desc='将鲜血注入祭坛，用生命交换力量。祖蛇之灵在焰火中咆哮，淬炼出震颤天地的妖剑。',Feature=1,}",
  [16233] = "{id=16233,NameZh='新叶羽翼图纸',Icon='item_47233',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16233,Desc='喷涌的魔力汇聚成天地树的叶片，在天地树的祝福下翱翔吧！',}",
  [16234] = "{id=16234,NameZh='魂音激奏图纸',Icon='item_47234',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16234,Desc='去战斗，去歌唱，直至灵与肉消亡之刻。奏响吧，这令灵魂震颤的旋律！',}",
  [16235] = "{id=16235,NameZh='苗娃秋千图纸',Icon='item_47235',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16235,Desc='荡秋千，荡秋千，荡到白云边~这个秋千可是苗娃的专座，谁都不许抢哦！',}",
  [16246] = "{id=16246,NameZh='暴风雪之翼图纸',Icon='item_47246',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16246,Desc='冰暴骑士的宝物，穿上后可以掌控暴风雪的力量！“在狂风之中颤抖吧，鲁道夫的敌人们！”',}",
  [16254] = "{id=16254,NameZh='梦想·天空图纸',Icon='item_47254',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16254,Desc='每一只奈吉鸟都向往着天空，相传每一对奈吉鸟父母都会给自己的孩子准备一份礼物：一副护目镜和一根拐杖。护目镜用于飞行时看清前方，拐杖则保证摔断腿后仍能正常行走……\n“一个叫理想，一个叫现实！”',Feature=1,}",
  [16255] = "{id=16255,NameZh='海妖之触图纸',Icon='item_47255',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16255,Desc='利用魔鬼大乌贼的触须制作的法杖，据说拥有召唤海浪的能力。注意事项：请勿将该法杖靠近火源，否则会有可怕的事发生。\n“这……这是——碳烤鱿鱼丝！真香！”',Feature=1,}",
  [16256] = "{id=16256,NameZh='帝王大虾弓图纸',Icon='item_47256',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16256,Desc='霸王大蟹弓的远房表哥，觉得自己比霸王大蟹弓、喵喵大蟹弓更优秀——至少更好吃！',Feature=1,}",
  [16267] = "{id=16267,NameZh='幼鹿背包背饰图纸',Icon='item_47267',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16267,Desc='参照绒绒鹿制成的背包，虽然十分可爱，却装不下多少东西。你问口袋在哪里的话……大概在小鹿的脑袋里吧？',}",
  [16273] = "{id=16273,NameZh='命运的掌舵者图纸',Icon='item_47273',Type=50,Quality=2,MaxNum=99999,SellPrice=100,ComposeID=16273,Desc='船舵就如同一艘船的大脑，指挥着船只在大海上前进的方向。航海时如果不提高警惕，时刻注意船舵的话，或许命运就掌握在了别人的手上……',}",
  [16277] = "{id=16277,NameZh='稚嫩的誓言图纸',Icon='item_47277',Type=50,Quality=2,MaxNum=99999,SellPrice=100,ComposeID=16277,Desc='马西米利安是现任雷根弗莱格家的家主，他对孙子们的教育十分的严苛。但大家都不知道的是，深夜里的他总是会打开一个盒子，露出慈祥的笑容。这里面就有这把玩具剑，是他给年幼时的海尔穆特的奖励。他轻轻的擦拭着剑身，想起海尔穆特稚嫩的声音：“恶魔都倒在了我的剑下！我会守护雷根弗莱格！守护米德加尔特！”',}",
  [16320] = "{id=16320,NameZh='风魔龟甲图纸',Icon='item_47320',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16320,Desc='是武器也是护盾，是形如鬼魅的忍龟。',}",
  [16326] = "{id=16326,NameZh='失落甲骨图纸',Icon='item_47326',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16326,Desc='唯有龟壳上的印记诉说着失落的记忆。',}",
  [16332] = "{id=16332,NameZh='烈焰之心图纸',Icon='item_47332',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=16332,Desc='热烈奔放的火红花束,象征骑士那至死不渝的信念与忠诚,献给那些即使战败却仍然坚定的忠诚骑士。 ',}",
  [16333] = "{id=16333,NameZh='露菲尔之泪图纸',Icon='item_47333',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=16333,Desc='洁白无暇的纯净花束,寄托骑士面对黑暗时的无畏与勇气,献给那些饱受创伤却仍然忠诚的英勇骑士。',}",
  [16334] = "{id=16334,NameZh='永恒守望图纸',Icon='item_47334',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=16334,Desc='清淡雅致的鹅黄花束,承载骑士不离不弃守护所爱的无私精神,献给那些失去挚爱却继续守望的悲恋骑士。',}",
  [16335] = "{id=16335,NameZh='无畏之紫图纸',Icon='item_47335',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=16335,Desc='一束深沉的紫花,蕴含骑士驱散内心恐惧与软弱的无畏意志,献给那些外敌环伺却仍奋勇前行的无畏骑士。 ',}",
  [16336] = "{id=16336,NameZh='坚韧之道图纸',Icon='item_47336',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=16336,Desc='简朴典雅的花束,象征骑士追求梦想时持之以恒的毅力,献给那些跌倒时仍不放弃梦想的坚毅骑士。',}",
  [16337] = "{id=16337,NameZh='卑微馨香图纸',Icon='item_47337',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=16337,Desc='芬芳娇嫩的花蕊,彰显骑士心存谦逊、处事低调的美德,献给那些遭强权践踏却仍谦虚行事的高尚骑士。',}",
  [16338] = "{id=16338,NameZh='圣骑披肩图纸',Icon='item_47338',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=16338,Desc='身处黑暗，冲向光明。',}",
  [16339] = "{id=16339,NameZh='功勋之盾图纸',Icon='item_47339',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=16339,Desc='每一道伤痕，都是骑士的勋章。',}",
