  [16343] = "{id=16343,NameZh='急传密信·隐秘图纸',Icon='item_47343',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16343,Desc='无论付出任何代价，都要将密信送达！',}",
  [16344] = "{id=16344,NameZh='信仰之证图纸',Icon='item_47344',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=16344,Desc='请祈祷吧，如果祈祷真的有用……',}",
  [16383] = "{id=16383,NameZh='苍青之翼图纸',Icon='item_47383',Type=50,Quality=4,MaxNum=99999,SellPrice=100,ComposeID=16383,Desc='苍蓝舞动，击碎异界之恶。',}",
  [16397] = "{id=16397,NameZh='翡翠龙盾图纸',Icon='item_47397',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=16397,Desc='奥斯卡喜爱的宝物，翡翠的华光足以令伟大的时空龙也爱不释手。',LoadShowSize=1.3,LoadShowRotate=180,LoadShowPose={0,0.3,0},RefineStorageReward={{buffid={65000090},lv=6},{buffid={66000360},lv=8}},}",
