  [17005] = "{id=17005,NameZh='黑猫尾巴图纸',Icon='item_48005',Type=50,Quality=4,MaxNum=99999,SellPrice=100,Desc='黑猫尾巴。',Feature=1,}",
  [17006] = "{id=17006,NameZh='小恶魔尾巴图纸',Icon='item_48006',Type=50,Quality=3,MaxNum=99999,AuctionPrice=0,SellPrice=500,ComposeID=17006,Desc='使用恶魔的灵魂制作的翅膀，佩戴者可获得非常恐怖的能力，但是心智会被逐渐侵蚀。',Feature=1,}",
  [17007] = "{id=17007,NameZh='狐狸尾巴图纸',Icon='item_48007',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=500,ComposeID=17007,Desc='狐狸的尾巴。',Feature=1,}",
  [17008] = "{id=17008,NameZh='雷蒙盖顿的尾巴图纸',Icon='item_48008',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=500,ComposeID=17008,Desc='世间万物都需要讲究平衡，这条尾巴带来的微妙而又真实的平衡感让人觉得极度的安心。',Feature=1,}",
  [17010] = "{id=17010,NameZh='英灵·亡者引渡图纸',Icon='item_48010',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=17010,Desc='奥尔露恩代替英灵殿赐予冒险者的奖励，亡者引渡，淡蓝色的灵魂火焰划过的路径，即使英灵们所要走的路，瓦尔哈拉殿堂的大门，也向见到火焰痕迹的人们敞开大门。',Feature=1,}",
  [17011] = "{id=17011,NameZh='爱丽丝的魔术兔图纸',Icon='item_48011',Type=50,MaxNum=99999,SellPrice=100,Feature=1,}",
  [17017] = "{id=17017,NameZh='幸运独角兽图纸',Icon='item_48017',Type=50,MaxNum=99999,SellPrice=100,Feature=1,}",
  [17026] = "{id=17026,NameZh='火焰尾图纸',Icon='item_48026',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17026,Desc='虽然看起来挺酷的，可是……啊啊啊，屁股好烫啊，裤子怎么又烧着了！',Feature=1,}",
  [17034] = "{id=17034,NameZh='嘤嘤火焰鸟图纸',Icon='item_48034',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17034,Desc='成年后的火焰鸟嚎叫一声连天地都为之震动，而幼年火焰鸟却只会嘤嘤嘤，没人知道这中间的成长发生了什么。',Feature=1,}",
  [17038] = "{id=17038,NameZh='情谊千纸鹤图纸',Icon='item_48038',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17038,Desc='将情书折叠成千纸鹤的过程，一定充满了憧憬、害羞与紧张吧！！',}",
  [17047] = "{id=17047,NameZh='机械尾巴图纸',Icon='item_48047',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17047,}",
  [17048] = "{id=17048,NameZh='厨神之魂图纸',Icon='item_48048',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17048,Desc='“初心者，你想跟我学做菜吗？？”——厨之精灵站在街口，对每一个路过的初心者发出邀请，身前的厨师帽中，还散落着几枚Zeny…',}",
  [17049] = "{id=17049,NameZh='恶兽之尾图纸',Icon='item_48049',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17049,Desc='每年新年的时候，父母们都会给孩子戴上这个可爱的恶兽尾巴，这样当恶兽到来的时候就感受不到孩童们的气息，以此来保证孩子们的安全。',Feature=1,}",
  [17060] = "{id=17060,NameZh='古代逆鳞图纸',Icon='item_48060',Type=50,MaxNum=99999,SellPrice=100,Desc='古代时期古龙族的尾巴，据说尾巴曾是古龙作战时的武器，一旦刺入敌人的身体，鳞片就会张开，随后释放出喷涌的毒液。',}",
  [17069] = "{id=17069,NameZh='冲刺哥布灵图纸',Icon='item_48069',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17069,Desc='速度、热血与飞驰！这就是冲刺的人生！春日之光笼罩大地，而哥布灵的冒险永无止境！',Feature=1,}",
  [17071] = "{id=17071,NameZh='小甜嗡图纸',Icon='item_48071',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17071,Desc='辛勤劳作的小甜嗡最爱跟在主人身旁，如果它的脸上露出了小小的红晕，那可能是你的笑容让它想起了最美的蓝莓花。',}",
  [17076] = "{id=17076,NameZh='附灵卷轴图纸',Icon='item_48076',Type=50,Quality=2,MaxNum=99999,SellPrice=100,ComposeID=17076,Desc='“迷途的人啊，你心中是否存有困惑与迷惘？将你的灵魂献祭于吾，将你的心愿在卷轴上书写，吾将传达神谕，为你指引真正的方向。”',}",
  [17077] = "{id=17077,NameZh='九尾猫尾巴图纸',Icon='item_48077',Type=50,MaxNum=99999,SellPrice=100,ComposeID=17077,Desc='只存在于传说中的九尾猫灵，是远星大陆的丰收之神。多兰族的小猫咪们每年的狂欢节都会佩戴它的尾巴，以表敬仰。',}",
  [17079] = "{id=17079,NameZh='慵懒假日图纸',Icon='item_48079',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17079,Desc='杰克船长在某个晴朗的夏日，把多拉贡岛上最大的海螺改造成了自己的私人浴缸。',}",
  [17080] = "{id=17080,NameZh='夏日香蕉船图纸',Icon='item_48080',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17080,Desc='塔妮小姐制作的香蕉船冰淇淋，据说把多拉贡岛上能用的糖果酱都浇上了，还赔上了一颗香蕉树。',}",
  [17081] = "{id=17081,NameZh='食人芽芽图纸',Icon='item_48081',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17081,Desc='取自吃人草的根茎制成的小尾巴，大长的嘴和吃人草如出一辙，摆动的时候要千万小心，不要伤到别人哦~',}",
  [17082] = "{id=17082,NameZh='冰雕骨脊图纸',Icon='item_48082',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17082,Desc='它是寒冰雕像的前身——骑士查尔斯的脊梁，它有着自主意识，并且与查尔斯生前的性格一样，强大而坚毅但又残暴嗜血，想要驯服它的人必须是真正的勇士。',}",
  [17083] = "{id=17083,NameZh='条纹喵尾图纸',Icon='item_48083',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17083,}",
  [17086] = "{id=17086,NameZh='海魂尾翼图纸',Icon='item_48086',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17086,Desc='受到深海之魂眷顾的冒险者，将自由遨游于广阔的大洋，与万千生灵意念相通，永远得到祝福和庇护。',Feature=1,}",
  [17087] = "{id=17087,NameZh='白蛇风铃图纸',Icon='item_48087',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17087,Desc='叮铃铃，叮铃铃……风铃声响起时抬头眺望，远行的故人是否也能听见风中的想念呢？',Feature=1,}",
  [17105] = "{id=17105,NameZh='紫晶伴生灵图纸',Icon='item_48105',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17105,Desc='具有强大魔力的宝石会在各种机缘巧合中形成伴生灵。根据母体宝石的不同，伴生灵也拥有不同的力量，而紫水晶的伴生灵会帮助主人躲避不幸。',}",
  [17110] = "{id=17110,NameZh='冰原来客图纸',Icon='item_48110',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17110,Desc='小海豹在海中迷失了方向，待它看到陆地时，已经身处名叫“克魔岛”的陌生地域，在这里它遇到了自己的同类，令它惊奇的是，这里的海豹竟然连雪都没有见过！\n“这么热的地方，你们是怎么坚持下来的！”',Feature=1,}",
  [17111] = "{id=17111,NameZh='提灯矿精图纸',Icon='item_48111',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17111,Desc='孤单的矿石精终于找到了它的第一个朋友，它会紧紧跟在朋友身边的！\n“只要拎着提灯，别人就能注意到我了哦！”',Feature=1,}",
  [17115] = "{id=17115,NameZh='冥界使者图纸',Icon='item_48115',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17115,Desc='海拉的使者，通过烛火和引魂铃指引亡者的灵魂进入尼夫海姆……等等，为什么你能看到它？！',}",
  [17121] = "{id=17121,NameZh='小白鹫图纸',Icon='item_48121',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17121,Desc='幼年期的白鹫，因为身体虚弱，而被兄弟姐妹挤出了巢穴。为了让它活下去，只能拜托冒险者你收养它啦~',}",
  [17122] = "{id=17122,NameZh='恶魔锹型虫图纸',Icon='item_48122',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17122,Desc='究极进化的锹型虫，似乎受到了心灵猎场力量的感染。放任他乱跑太危险了，还请冒险者看住他吧~',}",
  [17123] = "{id=17123,NameZh='伞蜥气球图纸',Icon='item_48123',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17123,Desc='印着伞蜥头的气球，附加了跟踪魔法，所以能够跟着主人一起移动。然而，不知道是不是错觉……气球上的伞蜥，看起来更傻了呢！',}",
  [17124] = "{id=17124,NameZh='迷梦猫尾图纸',Icon='item_48124',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17124,Desc='虽然只是仿制的假体，但无论皮毛的色泽还是摇晃的动态，都与真正的尾巴无异。戴着这样的饰物走进夜色，恐怕会把胆小的旅人吓坏——“猫妖变成人类的形态了！他要把我抓走了！”',}",
  [17127] = "{id=17127,NameZh='力哈尔特的诅咒图纸',Icon='item_48127',Type=50,Quality=2,MaxNum=99999,SellPrice=100,ComposeID=17127,Desc='施展于朽木之上的力哈尔特的诅咒，是何人所下？又有何目的？',}",
  [17130] = "{id=17130,NameZh='塔妮的香蕉船图纸',Icon='item_48130',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17130,Desc='以塔妮小姐为原型制作的装饰品，看起来完全没有威胁性。不过她手里的叉子，倒是挺尖锐的样子，小心别被戳中哦~',Feature=1,}",
  [17132] = "{id=17132,NameZh='雷根弗莱格的家训图纸',Icon='item_48132',Type=50,Quality=2,MaxNum=99999,SellPrice=100,ComposeID=17132,Desc='雷根弗莱格家的家风严谨，对家族成员的管束也十分严苛。传闻，雷根弗莱格家的成员如果违反了家训，就会被关进小黑屋里，抄写家训，如果偷懒的话卷轴中会出现雷根弗莱格家的家养小恶魔出来给予人一生难忘的惩罚。',}",
  [17153] = "{id=17153,NameZh='贪欲之牙[1]图纸',Icon='item_48153',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17153,Desc='贪婪的利牙会撕碎所有觊觎之人。',}",
  [17156] = "{id=17156,NameZh='绝对掌控图纸',Icon='item_48156',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17156,Desc='巴尔特家族中的天才设计师打造出的饰品，具有浓烈的巴尔特霸道风格——“无论你逃到哪里，都无法逃出我的掌控哟。”',}",
