  [17526] = "{id=17526,NameZh='傲慢之像图纸',Icon='item_48526',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=500,ComposeID=17526,Desc='阿斯加德城主的私生子曾经饲养过一只类似猎鹰的神兽，这只无比傲慢的神兽每当看到卑微的人类时就会竖起耳边的碧青羽毛，私生子对他的宠物很失望，他叹息傲慢这种拙劣品质的无处不在，他亲手杀死了他宠物，最后他留下了这只神兽耳边的羽毛，来时刻提醒自己，不骄不躁',Feature=1,}",
