  [17628] = "{id=17628,NameZh='向日葵棒棒糖图纸',Icon='item_48628',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17628,Desc='以邪恶向日葵的花籽为原料压制出的棒棒糖，虽然看起来并不是好吃，但其实吃一次就会上瘾噢！',Feature=1,}",
