  [17703] = "{id=17703,NameZh='七彩防护镜图纸',Icon='item_48703',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17703,Desc='戴上七彩防护镜，潇洒自如地参加泼水节吧！',Feature=1,}",
  [17706] = "{id=17706,NameZh='炼金之喙图纸',Icon='item_48706',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17706,Desc='只有知晓天理者才能窥探炼金术的奥秘，这是宇宙中至高无上的智慧所在，蝼蚁只能在陆地上仰视炼金术师的存在。',Feature=1,}",
  [17708] = "{id=17708,NameZh='金面石雕图纸',Icon='item_48708',Type=50,Quality=2,MaxNum=99999,SellPrice=100,ComposeID=17708,Desc='古老厚重的金纹雕刻在石雕之上，传说佩戴它之人可以与神明沟通，预测一切灾害与危险，但是宝物存在必定伴有纷争，石雕在被世人争夺之间，左耳的金饰不慎丢失，失去了它原有的神力。',}",
  [17710] = "{id=17710,NameZh='衔叶松鼠图纸',Icon='item_48710',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17710,Desc='一只悄悄溜出森林的小松鼠。它手中的叶片是罕见的四叶草，只送给被认可的冒险者。',}",
  [17711] = "{id=17711,NameZh='群叶猫的凝视图纸',Icon='item_48711',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17711,Desc='模仿群叶猫造型制作的眼镜，镜片后的目光犀利又深沉。',}",
  [17712] = "{id=17712,NameZh='红翼魔镜图纸',Icon='item_48712',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17712,Desc='一切的罪恶都逃不过这副恶魔的眼镜，所有堕落的灵魂都无处可藏，因为，恶魔会窥视到人类内心的欲望。',}",
  [17713] = "{id=17713,NameZh='冰霜龙首图纸',Icon='item_48713',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17713,Desc='每个戴上它的人都会被尼格斯的意志所控制从而成为它的奴仆，想要彻底驾驭它，必须有极强的精神力，如果意志不坚，还是不要轻易触碰它。',}",
  [17714] = "{id=17714,NameZh='梦魇幽面图纸',Icon='item_48714',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17714,Desc='“天惶惶，照月光 ，梦里见它莫惊慌，睁眼它不见，闭眼才出现。”这是幽灵梦魇身上遗落的面具，戴上它就可以窥视他人的梦境，发现他人隐藏心底的秘密。',}",
  [17719] = "{id=17719,NameZh='王室威严图纸',Icon='item_48719',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17719,Desc='来自地底，来自过去，那古老的王室财宝在沉睡，你可以拿走它们，只要你不怕那同样古老的王室威仪。',}",
  [17720] = "{id=17720,NameZh='魅惑之吻图纸',Icon='item_48720',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17720,Desc='暗红色的蛇信吐出，空气随之变得暧昧起来。谁若难抵邪魅的诱惑，也便步入了危险的丛林。',Feature=1,}",
  [17722] = "{id=17722,NameZh='魔纹面罩图纸',Icon='item_48722',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17722,Desc='远古的魔法在唇齿间环绕，话语于是成为了谶言。',Feature=1,}",
  [17756] = "{id=17756,NameZh='飞马（彩色）脸饰图纸',Icon='item_48756',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=17756,}",
