  [18091] = "{id=18091,NameZh='梦中的皮里恩[1]图纸',Icon='item_49091',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18091,Desc='据说皮里恩睡觉时会留一只眼睛盯梢，只有在初生时才会在母亲的怀里闭上全部六只眼睛，戴上它闭上眼，你感受到了那份如棉花糖般温柔的梦乡了吗？',}",
  [18112] = "{id=18112,NameZh='信徒之冠图纸',Icon='item_49112',Type=50,MaxNum=99999,SellPrice=100,ComposeID=18112,Desc='在阿卢纳贝兹，所有的信徒都要向女神祈祷，歌颂女神的事迹，教国会根据信徒为神祇做出的贡献，为贡献最多的信徒赐予这顶礼冠。',}",
  [18113] = "{id=18113,NameZh='敬灵帽图纸',Icon='item_49113',Type=50,MaxNum=99999,SellPrice=100,ComposeID=18113,Desc='为了维护教国的权威，许多的勇士为女神献上了虔诚的灵魂，教国为了纪念这些勇士，将敬灵帽赐予了这些勇士的后人，佩戴这顶帽子的人在教国拥有特殊权利。',}",
  [18114] = "{id=18114,NameZh='自由圣鹰图纸',Icon='item_49114',Type=50,MaxNum=99999,SellPrice=100,ComposeID=18114,Desc='女神的神迹照耀拉赫，拿起武器与深渊一战，赢得和平与美好，自由圣鹰张开羽翼，为吾等抗争之路护航，带领拉赫前往正确的方向。',ItemShow=1,}",
  [18135] = "{id=18135,NameZh='蕾丝蛋糕[1]图纸',Icon='item_49135',Type=50,MaxNum=99999,SellPrice=100,ComposeID=18135,Desc='罗扎纳最受欢迎的甜品之一，经常卖断货。是烤箱酒吧伊蕾塔小姐的拿手甜点。',}",
  [18136] = "{id=18136,NameZh='帅气的巡逻帽[1]图纸',Icon='item_49136',Type=50,MaxNum=99999,SellPrice=100,ComposeID=18136,Desc='蝴蝶巡守队队员的帽子，戴上以后英俊值上升二十个百分点。',}",
  [18137] = "{id=18137,NameZh='灵巧的羽毛帽[1]图纸',Icon='item_49137',Type=50,MaxNum=99999,SellPrice=100,ComposeID=18137,Desc='蝴蝶巡守队传令兵的帽子，佩戴后跑步时脚下生风。',}",
  [18138] = "{id=18138,NameZh='冒险家的荣光[1]图纸',Icon='item_49138',Type=50,MaxNum=99999,SellPrice=100,ComposeID=18138,Desc='大冒险家多拉贡的帽子。继承这顶帽子的人，也会继承他的勇气、信念……和小肚子。',}",
  [18142] = "{id=18142,NameZh='飞龙的情歌[1]图纸',Icon='item_49142',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18142,Desc='七彩飞龙大王罗密欧的耳机，24小时不间断播放着浪漫爱情歌曲。',}",
  [18143] = "{id=18143,NameZh='七彩魔女帽[1]图纸',Icon='item_49143',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18143,Desc='七彩地龙公主茱莉叶的头饰，参考了森林小女巫的造型设计而成。',}",
  [18144] = "{id=18144,NameZh='寂寞的龙蛋[1]图纸',Icon='item_49144',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18144,Desc='一颗龙蛋，原本住在里面的小龙闻到甜品的香气飞走了，这让它变得非常寂寞。',}",
  [18145] = "{id=18145,NameZh='趴趴小海獭[1]图纸',Icon='item_49145',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18145,Desc='“哔叽~哔叽~我是不是多拉贡岛上最可爱的小动物？”',}",
  [18146] = "{id=18146,NameZh='椰果沙滩[1]图纸',Icon='item_49146',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18146,Desc='在附近藏着的鲨鱼大哥总在思考，什么时候能吃到掉下来的椰果。',}",
  [18147] = "{id=18147,NameZh='微笑蛋黄帽[1]图纸',Icon='item_49147',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18147,Desc='以蛋黄波利为造型的棒球帽。除了绝佳的遮阳效果外，还散发着蛋糕的香味，只要闻到就会露出笑容。',}",
  [18148] = "{id=18148,NameZh='羽状叶发带[1]图纸',Icon='item_49148',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18148,Desc='富有森林气息的发带，由希希娅小姐的专用裁缝使用了9999根群叶疯兔绒毛制成。',}",
  [18149] = "{id=18149,NameZh='石头波利帽[1]图纸',Icon='item_49149',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18149,Desc='波利！波利！不要因为我是石头就嫌弃我，我会乖乖的呆在你的头顶的，只对你展现我最柔软的一面！',}",
  [18150] = "{id=18150,NameZh='恶魔牙冠[1]图纸',Icon='item_49150',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18150,Desc='“嗷呜，这是本恶魔大人赐予你的东西，乖乖的收好，如果有人敢欺负你，就用我的尖牙吓他们！”',}",
  [18151] = "{id=18151,NameZh='妖之角[1]图纸',Icon='item_49151',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18151,Desc='妖精一族的力量源泉就在双角之中，强大而尖锐，充满着无尽的魔力，同时角也是所有妖精的禁区，任何生物都不得触碰。',}",
  [18152] = "{id=18152,NameZh='趴趴雪球[1]图纸',Icon='item_49152',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18152,Desc='米德加尔特大陆的特大新闻，“雪兽一族最萌的雪兽宝宝——球球，竟然离家出走，雪兽一族已经陷入了巨大的恐慌之中” “嗷呜~嗷呜~”哎？这是什么声音？球球怎么在你头上!!!',}",
  [18153] = "{id=18153,NameZh='冰波利帽[1]图纸',Icon='item_49153',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18153,Desc='“波利！波利！不要因为我的外表就嫌弃我，虽然我看起来冷冰冰的，但是我的内心却是一片火热的爱着主人呢！请快把我戴上！主人！”',}",
  [18154] = "{id=18154,NameZh='傀儡幽灵冠[1]图纸',Icon='item_49154',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18154,Desc='“既然神不能在我痛苦的时候帮助我逃离深渊，那么我便背离神灵，堕落入深渊，沉睡于暗处的幽灵啊，请听从我的差遣，将那些人变为我的傀儡吧！”',}",
  [18155] = "{id=18155,NameZh='希尔金冠[1]图纸',Icon='item_49155',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18155,Desc='这是希尔一族最高的荣耀，能佩戴它的只有族内最强大的战士，当希尔队长离开族内后，这只金冠就下落不明，不知什么原因才重现于世。',}",
  [18160] = "{id=18160,NameZh='嗷呜绒帽[1]图纸',Icon='item_49160',Type=50,MaxNum=99999,SellPrice=100,ComposeID=18160,}",
  [18181] = "{id=18181,NameZh='疯表匠礼帽[1]图纸',Icon='item_49181',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18181,Desc='一动不动的秒针，疯狂旋转的分针，以及倒着走的时针！什么人做出了这样的钟表？',}",
  [18182] = "{id=18182,NameZh='鱼潜灵灯[1]图纸',Icon='item_49183',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,AdventureSort=960,AdventureValue=210,AdventureReward={buffid={61001130}},StorageReward={buffid={80012920}},Condition=4,ComposeID=18182,Desc='挚友的祝福化为一盏温暖的灯火，黑暗的前路变得通明，一切未来美好的可能都在眼前展开。',Feature=1,}",
  [18183] = "{id=18183,NameZh='深海灵触[1]图纸',Icon='item_49182',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,AdventureSort=963,AdventureValue=150,AdventureReward={buffid={61001110}},StorageReward={buffid={80012640}},Condition=4,ComposeID=18183,Desc='夜晚躺在水中做了一个梦，在梦里将窥探深海的秘密，群鱼涌来，古老的海底宫殿显露真容。',Feature=1,}",
  [18184] = "{id=18184,NameZh='狐仙之聆[1]图纸',Icon='item_49184',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,AdventureSort=966,AdventureValue=210,AdventureReward={buffid={61001160}},StorageReward={buffid={80012930}},Condition=4,ComposeID=18184,Desc='一切声响都无法逃脱狐仙之耳，包括那些梦中呢喃的思念。',Feature=1,}",
  [18185] = "{id=18185,NameZh='熊猫轻语[1]图纸',Icon='item_49185',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,AdventureSort=962,AdventureValue=150,AdventureReward={buffid={61000870}},StorageReward={buffid={80012640}},Condition=4,ComposeID=18185,Desc='快跟我一起说：‘熊猫是最可爱的动物’！说完了我就在你头上多呆一会儿~',Feature=1,}",
  [18200] = "{id=18200,NameZh='邪念之帽[1]图纸',Icon='item_49200',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,AdventureSort=972,AdventureValue=210,AdventureReward={buffid={61001680}},StorageReward={buffid={80013020}},Condition=4,ComposeID=18200,Desc='散发着不祥气息的帽子，似乎来自某种巨大邪念的化身。',Feature=1,}",
  [18201] = "{id=18201,NameZh='枫色魅影[1]图纸',Icon='item_49201',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,AdventureSort=968,AdventureValue=300,AdventureReward={buffid={61000470}},StorageReward={buffid={80012980}},Condition=4,ComposeID=18201,Desc='荒境树林间，若有殷红的身影映入眼帘，可要小心哦！',Feature=1,}",
