  [18203] = "{id=18203,NameZh='冰河幻力[1]图纸',Icon='item_49203',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,AdventureSort=973,AdventureValue=210,AdventureReward={buffid={61001690}},StorageReward={buffid={80013030}},Condition=4,ComposeID=18203,Desc='茫茫冰原上，震动此起彼伏，强力的咆哮声刺激着耳膜。难道是欧德姆布拉？',Feature=1,}",
  [18527] = "{id=18527,NameZh='虫语者[1]图纸',Icon='item_49527',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18527,Desc='模仿昆虫触角制作成的魔法装置，戴上它就能与昆虫交流了。',ItemShow=1,}",
  [18528] = "{id=18528,NameZh='日光兽角[1]图纸',Icon='item_49528',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18528,Desc='以三角兽兽角为原型制作的护额，用日光石打磨而成，并非动物制品哦！',}",
  [18529] = "{id=18529,NameZh='月光兽角[1]图纸',Icon='item_49529',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18529,Desc='以月光三角兽兽角为原型制作的护额，用月光石打磨而成，并非动物制品哦！',}",
  [18530] = "{id=18530,NameZh='灼金羽冠[1]图纸',Icon='item_49530',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18530,Desc='使用金灿灿的羽毛制成的羽冠，野性与时尚的完美结合。',}",
  [18531] = "{id=18531,NameZh='莉姆露的魂龛[1]图纸',Icon='item_49531',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18531,Desc='被芙蕾雅杀死后，莉姆露的灵魂因诅咒封印在了这顶王冠中，永远无法离开。即使受尽折磨，莉姆露依旧没有向芙蕾雅屈服。',}",
  [18532] = "{id=18532,NameZh='啃啃魔妖帽[1]图纸',Icon='item_49532',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18532,Desc='以玩偶魔妖为造型的帽子，深受搞笑艺人们的喜爱。据说带上这顶帽子能变得像玩偶魔妖一样“聪明”。',}",
  [18539] = "{id=18539,NameZh='炎灵之眼[1]图纸',Icon='item_49539',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18539,Desc='炎之领主卡浩拥有能够燃烧的双眼，工匠大师埃德姆使用它的眼睛打造了一款永远燃烧的王冠。',}",
  [18545] = "{id=18545,NameZh='啤酒推销员[1]图纸',Icon='item_49545',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18545,Desc='在这炎热的夏天，要来一杯清凉可口的啤酒吗？企鹅工坊出品的啤酒，你值得拥有！',Feature=1,}",
  [18546] = "{id=18546,NameZh='时尚前沿[1]图纸',Icon='item_49546',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18546,Desc='美男团首席发型师托尼老师的全新力作，只要剪了这个发型，你就能成为引领潮流的时尚圈先锋！',Feature=1,}",
  [18547] = "{id=18547,NameZh='鳄鱼头套[1]图纸',Icon='item_49547',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18547,Desc='原本想做成巨龙造型的头套，由于设计图的不严谨制成了鳄鱼造型，没想到意外的受到大家的喜爱。\n“救命救命，我被鳄鱼吞掉了！”',Feature=1,}",
  [18548] = "{id=18548,NameZh='转转石假面[1]图纸',Icon='item_49548',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18548,Desc='克魔岛特色工艺品，可以转动的石雕四面雕刻着象征各种厄运的假面，只要转动石雕，就能转走厄运，带来好运气！喂，等等！你怎么把它戴在头上了！',Feature=1,}",
  [18569] = "{id=18569,NameZh='闪蝶发夹[1]图纸',Icon='item_49569',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18569,Desc='标本化的蝴蝶，最大限度地保留了它生前的魔魅与闪耀。不过为了消除具有致幻效果的鳞粉，炼金术师们可没少费工夫。',}",
  [18570] = "{id=18570,NameZh='精灵狐耳[1]图纸',Icon='item_49570',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18570,Desc='王室狩猎场的周边，一经推出便受到王都少女们的哄抢。然而，每出售一个狐耳发饰，就有一只精灵狐惨遭杀害。',}",
  [18571] = "{id=18571,NameZh='趴趴游魂[1]图纸',Icon='item_49571',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18571,Desc='尾随冒险者离开心灵猎场的游魂，似乎是在对方身上找到了家乡的味道。既然它没有害人的心思，就暂且带着它吧。或许在将来，当你踏上某一片土地时，他会获得解脱。',}",
  [18577] = "{id=18577,NameZh='不朽之木图纸',Icon='item_49577',Type=50,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=10479,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,ComposeID=18577,Desc='“这是秘密……不能告诉别人……”年轻的机甲师小心地藏起装有朽木的宝箱，希望有人能够帮助他度过难关。',}",
  [18593] = "{id=18593,NameZh='自恋日记图纸',Icon='item_49593',Type=50,Quality=2,MaxNum=99999,SellPrice=100,ComposeID=18593,Desc='要问米德加尔特大陆上最美的男人，可能所有的少女都会不约而同的告诉你——尤尔根·韦格纳。作为韦格纳家的下一任家主，尤尔根过着众星捧月的生活，这也养成了他极度自恋的性格。他的日记里记载着关于他所有的赞美，是他的宝物之一。',}",
  [18627] = "{id=18627,NameZh='神使之证[1]图纸',Icon='item_49627',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18627,Desc='为女神献上忠诚与勇敢。',}",
  [18632] = "{id=18632,NameZh='趴趴火焰龟[1]图纸',Icon='item_49632',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18632,Desc='小乌龟也想去冒险',}",
  [18648] = "{id=18648,NameZh='魔女誓约[1]图纸',Icon='item_49648',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18648,Desc='戴上它，与魔女签订誓约，无惧世俗，从此生命只为自己绽放，深夜的月空成了游乐场，谁又能定义你的正义与邪恶？',}",
  [18659] = "{id=18659,NameZh='墨蛇君之帽[1]图纸',Icon='item_49659',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18659,Desc='生当王者，死以妖雄，这便是阴阳之力。',}",
  [18662] = "{id=18662,NameZh='圣光面罩·守望[1]图纸',Icon='item_49662',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18662,Desc='英魂不灭，圣辉永存！',}",
  [18665] = "{id=18665,NameZh='勇士之炬·燃烧图纸',Icon='item_49665',Type=50,Quality=2,MaxNum=99999,SellPrice=100,ComposeID=18665,Desc='火炬的使命是燃烧，希望才能被点亮。',}",
  [18670] = "{id=18670,NameZh='混血印记[1]图纸',Icon='item_49670',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18670,Desc='紫色代表混血儿的身份，这是半龙人最不能被提及的部分。',}",
  [18671] = "{id=18671,NameZh='窥探之眼[1]图纸',Icon='item_49671',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18671,Desc='嘘，在深夜出门一定要小心，保持安静……',}",
  [18672] = "{id=18672,NameZh='夜羽之冠[1]图纸',Icon='item_49672',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18672,Desc='月夜下的翎羽，是胜利者的标志。',}",
  [18673] = "{id=18673,NameZh='饰金之冠[1]图纸',Icon='item_49673',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18673,Desc='由金丝打造，在夜间绽放成赤红的花。',}",
  [18720] = "{id=18720,NameZh='灵息龙面图纸',Icon='item_48826',Type=50,Quality=2,MaxNum=99999,SellPrice=100,ComposeID=18720,Desc='灵魂低语，生与死的边界不再清晰。',}",
  [18721] = "{id=18721,NameZh='黄昏之翼图纸',Icon='item_47381',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=18721,Desc='黄昏之际，万物在光明与黑暗中短暂共存。',}",
  [18722] = "{id=18722,NameZh='赤热尾刺图纸',Icon='item_48212',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=18722,Desc='每次挥动，将带来毁灭与重生的力量。',}",
  [18723] = "{id=18723,NameZh='邪恶之冠[1]图纸',Icon='item_49732',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=18723,Desc='低下头颅，恐惧与绝望将散布人间。',}",
  [18724] = "{id=18724,NameZh='悖誓赤瞳图纸',Icon='item_48839',Type=50,Quality=4,MaxNum=99999,SellPrice=100,ComposeID=18724,Desc='誓言是灵魂的枷锁，背叛则是向命运亮出的利刃。',}",
  [18737] = "{id=18737,NameZh='苍龙之角[1]图纸',Icon='item_49737',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=18737,Desc='湛蓝的龙角，是苍翼卫领队的象征。',}",
  [18742] = "{id=18742,NameZh='赤炎龙王（蛋）图纸',Icon='item_49742',Type=50,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=18742,Desc='别看我现在还小，长大后我要当龙王！',}",
  [18747] = "{id=18747,NameZh='龙怨之角[1]图纸',Icon='item_49747',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18747,Desc='执此角者，耳闻幽啸——那是诺博斯永不消散的怨。',}",
  [18749] = "{id=18749,NameZh='黑炎之怒[1]图纸',Icon='item_49749',Type=50,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=18749,Desc='黑炎自黯鬃腾起，暴君的意志永不熄灭。',}",
