  [25008] = "{id=25008,NameZh='天国之匙',Icon='item_25008',Type=90,Quality=5,MaxNum=1,AuctionPrice=1,SellPrice=100,AdventureSort=1000,AdventureValue=100,AdventureReward={buffid={63000250}},Condition=8,Desc='吟游诗人代代传唱的神话中经常出现的幻之生物。比起生物，称呼其为【幻想】本身更为直观。传说中，她会变为一座巨大的彩虹之桥来链接神明的居所【阿斯嘉特】和人类的世界【米德加尔特】。',Feature=1,}",
