  [25105] = "{id=25105,NameZh='彩羽鸵鸟·水蜜桃',Icon='item_25105',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000150}},Desc='彩羽鸵鸟有着米德加尔特大陆最美丽的鸟类之称，它们的羽毛薄若蝉翼，在阳光下能折射出绚烂的光芒，彩羽鸵鸟的速度极快，一般的魔物猎人根本捉不到它，想拥有这样美丽的坐骑的话，冒险者可要下一番功夫啦！',NoStorage=5,Feature=1,}",
  [25106] = "{id=25106,NameZh='巨齿斑鬣·布鲁斯',Icon='item_25106',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='斑鬣的身体虽然不是很巨大，但是强筋有力的四肢和流线型的躯体让它具有很强的爆发力，它甚至可以捕食比自身大很多倍的魔物，巨大锋利的牙齿可以瞬间咬断猎物的脖颈，所以冒险者在驯服斑鬣的时候一定要小心它锋利的牙齿伤害到自己哦！',NoStorage=5,Feature=1,}",
  [25107] = "{id=25107,NameZh='旅行大嘴鸟',Icon='item_25107',Type=90,Quality=5,MaxNum=1,SellPrice=100,Desc='极其珍贵的旅行大嘴鸟坐骑（超过15级的冒险者使用后会被乐园团回收）。',NoStorage=5,Feature=1,}",
  [25108] = "{id=25108,NameZh='飞马',Icon='item_25008',Type=90,Quality=5,MaxNum=1,SellPrice=100,Desc='极其珍贵的飞马坐骑（超过15级的冒险者使用后会被乐园团回收）。',NoStorage=5,Feature=1,}",
  [25109] = "{id=25109,NameZh='符文地龙',Icon='item_25114',Type=90,Quality=5,MaxNum=1,SellPrice=100,Desc='极其珍贵的地龙坐骑（超过15级的冒险者使用后会被乐园团回收）。',NoStorage=5,Feature=1,}",
  [25110] = "{id=25110,NameZh='幽灵马',Icon='item_25010',Type=90,Quality=5,MaxNum=1,SellPrice=100,Desc='极其珍贵的幽灵马坐骑（超过15级的冒险者使用后会被乐园团回收）。',NoStorage=5,Feature=1,}",
  [25111] = "{id=25111,NameZh='狮鹫',Icon='item_25115',Type=90,Quality=5,MaxNum=1,SellPrice=100,Desc='极其珍贵的狮鹫坐骑（超过15级的冒险者使用后会被乐园团回收）。',NoStorage=5,Feature=1,}",
  [25112] = "{id=25112,NameZh='烈鬃豪猪·枪',Icon='item_25112',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='烈鬃豪猪虽然平时只吃一些杂果蔬菜，但是不代表它们的性情就是温顺的，多少无知的生物惨死在它们锋利的犬齿之下，想要征服这种强力坐骑，一定要小心谨慎才行哦！',NoStorage=5,Feature=1,}",
  [25113] = "{id=25113,NameZh='疾星剑狮·金星',Icon='item_25013',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='疾星剑狮生活在植物稀缺的平原上，它们能适应任何的艰难生存环境，而且在所有陆地魔物中，疾星剑狮具有最强大的咬合力，它们锋利的牙齿可以轻易咬碎猎物的头骨，想要拥有这种强力的坐骑，冒险者可要展现出强大的实力哦！',NoStorage=5,Feature=1,}",
  [25114] = "{id=25114,NameZh='符文地龙',Icon='item_25114',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=3,AdventureValue=1,Condition=8,Desc='能负担起骑士沉重铠甲武器重量的生物屈指可数，强壮的地龙是不二之选，在古老的传说中，流传着龙骑士的英雄事迹，所以驯服地龙作为坐骑成为一种骑士传统，符文地龙可以背着重装的骑士不知疲倦的奔走，尖利的爪牙也成为战斗中不可小觑的力量。',NoStorage=5,Feature=1,}",
  [25115] = "{id=25115,NameZh='皇家狮鹫',Icon='item_25115',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=4,AdventureValue=1,Condition=8,Desc='由皇室的狮鹫专家从小训练的高级坐骑，对主人命令的执行力非常高，强大又忠诚，身上装载了特别的作战铠甲，是皇室军队的象征之一，能坐着皇家狮鹫去冒险是许多人从小到大的憧憬。',NoStorage=5,Feature=1,}",
  [25116] = "{id=25116,NameZh='亚特兰地龙',Icon='item_25116',Type=90,Quality=4,MaxNum=1,SellPrice=100,Desc='在古老传说中，由于地龙一族帮助了龙骑士，某位苍绿发色的女神赐予地龙三种不同的恩宠，力量，速度，坚韧。在地龙中，力量特别强大的稀有种被女神赋予亚特兰地龙之名，是不可多得的强大坐骑。',NoStorage=5,Feature=1,}",
  [25117] = "{id=25117,NameZh='杜兰格地龙',Icon='item_25117',Type=90,Quality=4,MaxNum=1,SellPrice=100,Desc='在古老传说中，由于地龙一族帮助了龙骑士，某位苍绿发色的女神赐予地龙三种不同的恩宠，力量，速度，坚韧。在地龙中，速度特别迅捷的稀有种被女神赋予杜兰格地龙之名，是不可多得的强大坐骑。',NoStorage=5,Feature=1,}",
  [25118] = "{id=25118,NameZh='瑞拉达地龙',Icon='item_25118',Type=90,Quality=4,MaxNum=1,SellPrice=100,Desc='在古老传说中，由于地龙一族帮助了龙骑士，某位苍绿发色的女神赐予地龙三种不同的恩宠，力量，速度，坚韧。在地龙中，耐力特别坚韧的稀有种被女神赋予瑞拉达地龙之名，是不可多得的强大坐骑。',NoStorage=5,Feature=1,}",
  [25119] = "{id=25119,NameZh='苍翼狮鹫',Icon='item_25119',Type=90,Quality=3,MaxNum=1,SellPrice=100,Desc='驯服狮鹫作为坐骑的难度在于他们天生性格高傲且力量强大，最好的办法是从狮鹫出生就开始训练他们，狮鹫对自己认可的主人忠心耿耿，栖息在依斯鲁得附近的特别品种被称作“苍翼”，是所有狮鹫中最迅捷的一种。',NoStorage=5,Feature=1,}",
  [25120] = "{id=25120,NameZh='赤鬃狮鹫',Icon='item_25120',Type=90,Quality=3,MaxNum=1,SellPrice=100,Desc='驯服狮鹫作为坐骑的难度在于他们天生性格高傲且力量强大，最好的办法是从狮鹫出生就开始训练他们，狮鹫对自己认可的主人忠心耿耿，栖息在熔岩洞窟附近的特别品种被称作“赤鬃”，比普通狮鹫脾气更暴躁。',NoStorage=5,Feature=1,}",
  [25121] = "{id=25121,NameZh='棕羽狮鹫',Icon='item_25121',Type=90,Quality=3,MaxNum=1,SellPrice=100,Desc='驯服狮鹫作为坐骑的难度在于他们天生性格高傲且力量强大，最好的办法是从狮鹫出生就开始训练他们，狮鹫对自己认可的主人忠心耿耿，栖息在梦罗克地区附近的特别品种被称作“棕羽”，忍耐力比普通狮鹫更强。',NoStorage=5,Feature=1,}",
  [25122] = "{id=25122,NameZh='瓦尔格地龙',Icon='item_25122',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=7,AdventureValue=1,Condition=8,Desc='善龙神巴哈姆特麾下的护卫一族，拥有火焰般炙热的鳞甲和极端暴躁的脾气，只有得到它认可的人类才有资格驾驭它。',NoStorage=5,Feature=1,}",
  [25123] = "{id=25123,NameZh='高级地龙2',Icon='item_25123',Type=90,Quality=3,MaxNum=1,SellPrice=100,NoStorage=5,Feature=1,}",
  [25124] = "{id=25124,NameZh='圣堂狮鹫',Icon='item_25124',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=8,AdventureValue=1,Condition=8,Desc='由依斯鲁得军队培育出的混血狮鹫，相比于一般的狮鹫更亲近人类，对自己的主人有很强的保护欲。',NoStorage=5,Feature=1,}",
  [25125] = "{id=25125,NameZh='夜焰狮鹫',Icon='item_25125',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=9,AdventureValue=1,Condition=8,Desc='由梦罗克军队培育出的混血狮鹫，相比于一般的狮鹫具有更强的战斗力，即使刚出生的时候也十分凶猛。',NoStorage=5,Feature=1,}",
  [25126] = "{id=25126,NameZh='奖励坐骑1',Icon='item_25126',Type=90,MaxNum=1,SellPrice=100,}",
  [25127] = "{id=25127,NameZh='奖励坐骑2',Icon='item_25127',Type=90,MaxNum=1,SellPrice=100,}",
  [25128] = "{id=25128,NameZh='奖励坐骑',Icon='item_25128',Type=90,MaxNum=1,SellPrice=100,}",
  [25130] = "{id=25130,NameZh='霸王龙卷风',Icon='item_25130',Type=90,MaxNum=1,AuctionPrice=1,SellPrice=100,AdventureSort=1001,AdventureValue=100,AdventureReward={buffid={63000250}},Condition=8,Desc='在数以万计的旋风叽中，近百年来只出现了这一只与众不同的品种。它拥有着和人类一样的智商，速度疾如风，快如闪电。它仿佛生来就是王者，旋风叽一族全都臣服在它的爪下，并尊称它为“霸王龙卷风”！',Feature=1,}",
  [25131] = "{id=25131,NameZh='极速小旋风',Icon='item_25131',Type=90,MaxNum=1,SellPrice=100,Desc='旋风叽一族在大陆上以速度极快闻名，它们的速度在大陆上的所有生物中是数一数二的。 但是有一点，它们的好奇心都很重，经常因此被人类引诱、捕获，并驯养成代步的坐骑。看来上帝是公平的，为它们开了一扇门，又关了一扇窗呢！',NoStorage=5,ExistTimeType=1,ExistTime='86400',Feature=1,}",
  [25132] = "{id=25132,NameZh='皇家站熊',Icon='item_25132',Type=90,MaxNum=1,SellPrice=100,Desc='是站熊，不是战熊，它只是[皇家战熊]的高仿版，除了名字有些不一样，其他地方都一样，但是因为害怕被打假，所以它存在的时间只有30分钟，最大的作用，应该就是找个美美的地方拍张美美的照片假装自己是美美的6V6高手吧~',NoStorage=5,ExistTimeType=1,ExistTime='1800',Feature=1,}",
  [25133] = "{id=25133,NameZh='银翼雪鹿',Icon='item_25133',Type=90,MaxNum=1,SellPrice=100,AdventureSort=1013,AdventureValue=1,AdventureReward={buffid={63000240}},Condition=8,Desc='这是大陆上的第一场雪，一只白鹿从雪夜中缓缓的显出身形，它的双眼如同红宝石一般闪耀，有着窥视人心的魔力，传说只要在它的面前诚心的祈愿便会实现。',NoStorage=5,Feature=1,TFValidDate='2020-12-24 05:00:00',ValidDate='2020-12-24 05:00:00',}",
  [25134] = "{id=25134,NameZh='宝石公爵',Icon='item_25134',Type=90,MaxNum=1,AuctionPrice=1,SellPrice=100,AdventureSort=1002,AdventureValue=100,AdventureReward={buffid={63000240}},Condition=8,Desc='zeny？钻石？珠宝？喵呜！在本公爵眼里都不值一提。你说你想要这些俗物？啧！很容易，只要征服本公爵，你想要多少就有多少！怎么样，要来试试么？两脚兽？（坏笑）',Feature=1,}",
  [25136] = "{id=25136,NameZh='芬里尔脉冲型Ⅵ号',Icon='item_25136',Type=90,Quality=5,MaxNum=1,AuctionPrice=1,SellPrice=100,AdventureSort=1006,AdventureValue=100,AdventureReward={buffid={63000250}},Condition=8,Desc='前身是雷根贝勒公司研发的智能犬型攻击机甲，依靠人造伊米尔之心碎片驱动。但因设计缺陷无法负荷碎片强大的力量而惨遭废弃。一位神秘拾荒者在垃圾场将被遗弃的机甲残躯带走并且进行了改造，重生后将其命名为“芬里尔脉冲型Ⅵ号”，优化了能源摄取比例，减轻了机甲材质，从而大幅度提升了移动速度。但身上还有多少人造伊米尔之心碎片就不得而知了，除非你有勇气撬开看看……',Feature=1,}",
  [25137] = "{id=25137,NameZh='白恋翱翔',Icon='item_25137',Type=90,Quality=5,MaxNum=1,AuctionPrice=1,SellPrice=100,Desc='吟游诗人代代传唱神话中经常出现的『恋』之生物。比起生物，称呼其为『爱恋』本身更为直观。传说中，她会变为一座巨大的彩虹之桥来连结神明的居所【阿斯嘉特】和人类的世界【米德加尔特】',Feature=1,}",
  [25138] = "{id=25138,NameZh='哈皮羊驼',Icon='item_25138',Type=90,Quality=5,MaxNum=1,AuctionPrice=1,SellPrice=100,AdventureSort=1057,AdventureValue=1,AdventureReward={buffid={60002030}},Condition=8,Desc='唱世界上最欢乐的歌，做世界上最哈皮的崽！没有困难可以难倒它，迈开四条小短腿，就是一往无前！',NoStorage=5,Feature=1,TFValidDate='2023-04-24 05:00:00',ValidDate='2023-05-01 05:00:00',}",
  [25139] = "{id=25139,NameZh='利力',Icon='item_25139',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureSort=10,AdventureValue=1,Condition=8,Desc='“骑士之星”赛伊连•瓦恩萨的坐骑，是六人小队最忠诚的伙伴。在六人小队的身影消失在地下研究所之后，利力承载着他们的信念，守护着希望，等待着重逢的那一天。',NoSale=1,Feature=1,}",
  [25140] = "{id=25140,NameZh='月光梦魇',Icon='item_25140',Type=90,Quality=4,MaxNum=1,SellPrice=100,AdventureSort=514,AdventureValue=50,AdventureReward={buffid={63000230}},Condition=8,Desc='“为这无能为力的命运，为这不可逆转的结局……吾愿融为黑暗，守护这场终将破碎的梦境。”',NoStorage=5,Feature=1,}",
  [25141] = "{id=25141,NameZh='波利',Icon='item_25002',Type=90,Quality=3,MaxNum=1,SellPrice=100,Desc='极其珍贵的波利坐骑，存在的时间只有30分钟。',NoStorage=5,ExistTimeType=1,ExistTime='1800',Feature=1,}",
  [25142] = "{id=25142,NameZh='旅行大嘴鸟',Icon='item_25107',Type=90,Quality=5,MaxNum=1,SellPrice=100,Desc='极其珍贵的旅行大嘴鸟坐骑，存在的时间只有30分钟。',NoStorage=5,ExistTimeType=1,ExistTime='1800',Feature=1,}",
  [25143] = "{id=25143,NameZh='波波蜗牛',Icon='item_25143',Type=90,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=1030,AdventureValue=1,AdventureReward={buffid={63000250}},Condition=8,Desc='【双人坐骑】\n蜗牛一族自古以来就流传着一个最速传说：当生的意志压过一切，最原始的本能被激发，蜗牛就可以化身为一道光，风驰电掣！而冒险者的实际乘坐体验表示：“慢吞吞的很悠闲，十分适合观光。”在PVP场景中乘客是无法乘坐的哦！',Feature=1,}",
  [25146] = "{id=25146,NameZh='黑骥',Icon='item_25146',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=1045,AdventureValue=1,AdventureReward={buffid={63000170}},Condition=8,Desc='用黑曜石铸造的身躯，携带着无尽的怒焰，传颂死亡的福音。',}",
  [25150] = "{id=25150,NameZh='风汐白鹿',Icon='item_25150',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=11,AdventureValue=1,Condition=8,Desc='它奔向枫林，雪原，和那时间的彼岸。',}",
  [25151] = "{id=25151,NameZh='宇迦神使',Icon='item_25151',Type=90,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=1079,AdventureValue=1,AdventureReward={buffid={63000240}},Condition=8,Desc='风调雨顺，五谷丰登。',Feature=1,TFValidDate='2023-09-24 05:00:00',ValidDate='2023-10-01 05:00:00',}",
  [25152] = "{id=25152,NameZh='天使波利',Icon='item_25152',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=1015,AdventureValue=1,AdventureReward={buffid={63000240}},Condition=8,Desc='注意体重，不要把波利压扁哦~',}",
  [25157] = "{id=25157,NameZh='彩虹石波利',Icon='item_25157',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=1026,AdventureValue=1,AdventureReward={buffid={63000060}},Condition=8,Desc='极其罕见的彩虹石波利坐骑。',}",
  [25158] = "{id=25158,NameZh='符文地龙（30天）',Icon='item_25114',Type=90,Quality=3,MaxNum=1,SellPrice=100,Desc='能负担起骑士沉重铠甲武器重量的生物屈指可数，强壮的地龙是不二之选，在古老的传说中，流传着龙骑士的英雄事迹，所以驯服地龙作为坐骑成为一种骑士传统，符文地龙可以背着重装的骑士不知疲倦的奔走，尖利的爪牙也成为战斗中不可小觑的力量。',NoStorage=5,ExistTimeType=1,ExistTime='2592000',Feature=1,}",
  [25159] = "{id=25159,NameZh='皇家狮鹫（30天）',Icon='item_25115',Type=90,Quality=3,MaxNum=1,SellPrice=100,Desc='由皇室的狮鹫专家从小训练的高级坐骑，对主人命令的执行力非常高，强大又忠诚，身上装载了特别的作战铠甲，是皇室军队的象征之一，能坐着皇家狮鹫去冒险是许多人从小到大的憧憬。',NoStorage=5,ExistTimeType=1,ExistTime='2592000',Feature=1,}",
  [25160] = "{id=25160,NameZh='陆行鸟健将',Icon='item_25160',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=18,AdventureValue=1,Condition=8,Desc='大嘴鸟竞速赛是每年学院庆典的保留项目，而这只鸟以令人惊讶的成绩打破了数十年无人撼动的比赛纪录——等等，它好像不是大嘴鸟啊喂！',Feature=1,TFValidDate='2020-12-10 05:00:00',ValidDate='2021-01-06 05:00:00',}",
  [25162] = "{id=25162,NameZh='虹光马·永恒',Icon='item_25162',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=1028,AdventureValue=1,AdventureReward={buffid={63000070}},Condition=8,Desc='据说是巨人赫朗格尼尔曾拥有的神马——金鬃马的后代。当阿斯加德得到了金鬃马后，以彩虹桥的魔力融入它们的血统，因此鬃毛和尾巴也变为七彩，能力也更强。',Feature=1,}",
  [25163] = "{id=25163,NameZh='虹光马·翱翔',Icon='item_25163',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=1029,AdventureValue=1,AdventureReward={buffid={63000070}},Condition=8,Desc='在古尔法克西马中，唯有最强、最美丽者才能拥有梦幻羽翼。它们既可以翱翔于空中，又能在水面上疾驰，还拥有世代不移的忠诚和聪慧，为守护世界而奔波不休。',Feature=1,}",
  [25164] = "{id=25164,NameZh='黎明火焰',Icon='item_25164',Type=90,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=1027,AdventureValue=1,AdventureReward={buffid={63000250}},Condition=8,Desc='这是在世界之初，神牛欧德姆布拉在金伦加之南沐浴烈焰后，诞生出的另一种姿态。“它踏着火光而来，点燃了黎明与最初的希望”。',}",
  [25165] = "{id=25165,NameZh='鲨鱼海盗船',Icon='item_25165',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=1033,AdventureValue=1,AdventureReward={buffid={63000170}},Condition=8,Desc='港口的钟声响起，从烟雾中冲出一艘气派的海盗船，霸气又不失俏皮的坏笑仿佛在发出邀请：“喂，要一起出发前往神秘海域嘛！”',Feature=1,}",
  [25168] = "{id=25168,NameZh='萌萌救生员',Icon='item_25168',Type=90,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=20,AdventureValue=1,AdventureReward={buffid={60002030}},Condition=8,Desc='米德加尔特大陆最萌的救生员，别看她长得乖乖萌萌的，在水里可没人能比得过她~',}",
  [25174] = "{id=25174,NameZh='深渊巨龙',Icon='item_25174',Type=90,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=1038,AdventureValue=1,AdventureReward={buffid={121330}},Condition=8,Desc='栖息在深渊之湖的巨龙，凶狠的外表下，是一颗热衷于给人祝福的炙热的心。',}",
  [25175] = "{id=25175,NameZh='深渊巡刑者',Icon='item_25175',Type=90,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=1039,AdventureValue=1,AdventureReward={buffid={64000430}},Condition=8,Desc='灵魂之火沉沦于黑暗。在埃琉德尼尔的深渊中，余烬燃起死亡的颂诗，终将唤醒它的双眸。',Feature=1,TFValidDate='2021-09-24 05:00:00',ValidDate='2021-10-01 05:00:00',}",
  [25176] = "{id=25176,NameZh='飓风',Icon='item_25176',Type=90,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=22,AdventureValue=1,AdventureReward={buffid={63000230}},Condition=8,Desc='远古克魔岛勇士祖尔的战马“飓风”，因它快如疾风的奔跑速度而得名。',}",
  [25185] = "{id=25185,NameZh='绯红王者',Icon='item_25185',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureSort=23,AdventureValue=1,AdventureReward={buffid={63000030}},Condition=8,Desc='身披锦缎、头戴华冠的雪豹，体态优美，气质威严。只有出身不凡的贵族，或者名扬四海的勇士，才有资格使用这样的坐骑吧。',}",
  [25186] = "{id=25186,NameZh='海渊行者',Icon='item_25186',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=1043,AdventureValue=1,AdventureReward={buffid={63000170}},Condition=8,Desc='潜行于深海中的巨兽，强壮的触手可以轻松击碎往来的船只。',}",
  [25188] = "{id=25188,NameZh='飞天蝴蝶猪',Icon='item_25188',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=1064,AdventureValue=1,AdventureReward={buffid={63000170}},Condition=8,Desc='拧紧发条，全力奔跑，只要跑得够快，就能体验到飞的感觉！',Feature=1,StageDisplay=0,}",
  [25189] = "{id=25189,NameZh='巨尾布布',Icon='item_25189',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=1065,AdventureValue=1,AdventureReward={buffid={60002030}},Condition=8,Desc='巨大的尾巴是布布的特征，一旦开始奔跑，就全靠这尾巴来掌握平衡了~！',Feature=1,}",
  [25190] = "{id=25190,NameZh='金铠圣灵（限时）',Icon='item_25210',Type=90,Quality=4,MaxNum=1,SellPrice=100,Desc='坚实的铠甲闪耀着灿烂温暖的光芒，坚定的眼神仿佛在对冒险者说：“这个世界，我们一起守护吧。”',NoStorage=5,ExistTimeType=4,ExistTime='604800',}",
  [25193] = "{id=25193,NameZh='幸运羊驼',Icon='item_25193',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=24,AdventureValue=1,AdventureReward={buffid={64000430}},Condition=8,Desc='快乐的羊驼，据说所到之处能给人们带来欢笑与幸运。',Feature=1,}",
  [25194] = "{id=25194,NameZh='泰雅象',Icon='item_25194',Type=90,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=1051,AdventureValue=1,AdventureReward={buffid={63000240}},Condition=8,Desc='【双人坐骑】\n位于异世界的国度“哎哟泰雅”栖息着一种神奇的生物，名为“象”，哎哟泰雅的人民信奉着象神。大象体积硕大，力大无穷，它拥有灵活的鼻子，和扑闪的大耳朵，大大方便了当地民众的生活。可以说，大象是很多民众的好搭档，甚至有人说，如果没有大象就没有哎哟泰雅。',Feature=1,TFValidDate='2023-02-06 05:00:00',ValidDate='2023-02-13 05:00:00',LoadShowSize=0.6,}",
  [25196] = "{id=25196,NameZh='赛博惠比特',Icon='item_25196',Type=90,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=1052,AdventureValue=1,AdventureReward={buffid={63000240}},Condition=8,Desc='作为优秀的猎犬，惠比特有着和谐而发达的肌肉，以及擅长奔跑的四肢。如今他装备上流光溢彩的机械外骨骼，能够负载着冒险者，征服更多复杂的地形。',Feature=1,TFValidDate='2022-06-02 05:00:00',ValidDate='2022-06-09 05:00:00',}",
  [25199] = "{id=25199,NameZh='初心冒险蟹',Icon='item_25199',Type=90,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=1066,AdventureValue=1,AdventureReward={buffid={60002030}},Condition=8,Desc='作为初心家族的最新成员，冒险蟹可是一位任劳任怨的选手！更是应急食品的绝佳候选！',Feature=1,}",
  [25200] = "{id=25200,NameZh='幸运羊驼（3天）',Icon='item_25193',Type=90,Quality=3,MaxNum=1,SellPrice=100,Desc='快乐的羊驼，据说所到之处能给人们带来欢笑与幸运。\n（存在的时间只有3天）',NoStorage=5,ExistTimeType=1,ExistTime='259200',Feature=1,}",
