  [25211] = "{id=25211,NameZh='魔焰御兽',Icon='item_25211',Type=90,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=1047,AdventureValue=1,AdventureReward={buffid={60002030}},Condition=8,Desc='不可思议的火焰彰显着它奇妙的力量，威严而勇猛。魔剑士深深地信赖着它。',Feature=1,TFValidDate='2022-03-31 05:00:00',ValidDate='2022-04-07 05:00:00',}",
  [25212] = "{id=25212,NameZh='天狼座',Icon='item_25212',Type=90,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=1072,AdventureValue=1,AdventureReward={buffid={63000240}},Condition=8,Desc='夜空中最璀璨夺目的光芒，跨越时空的忠诚陪伴，不论斗转星移，沧海桑田，都将永恒地镌刻于星空之中。',Feature=1,TFValidDate='2024-03-21 05:00:00',ValidDate='2024-03-21 05:00:00',}",
  [25216] = "{id=25216,NameZh='巫沙布提·青金',Icon='item_25216',Type=90,MaxNum=1,SellPrice=100,AdventureSort=15,AdventureValue=1,AdventureReward={buffid={63000230}},Condition=8,Desc='雄壮矫健的大型坐骑。爆发力惊人，尤其擅长战斗。身体呈现出深邃艳丽的宝石蓝色，再配上黄金和红宝石打造的盔甲，一旦出现就足以吸引所有人的目光。',}",
  [25217] = "{id=25217,NameZh='巫沙布提·白银',Icon='item_25217',Type=90,MaxNum=1,SellPrice=100,AdventureSort=16,AdventureValue=1,AdventureReward={buffid={64000440}},Condition=8,Desc='雄壮矫健的大型坐骑。四爪拥有厚实的肉垫，因此奔跑得再快也非常稳当。特点是以白银打造头盔和胸甲作为保护，不仅拥有极高的防御力，作为装饰也非常漂亮。',}",
  [25218] = "{id=25218,NameZh='叹息之羽',Icon='item_25218',Type=90,MaxNum=1,SellPrice=100,AdventureSort=17,AdventureValue=1,Condition=8,Desc='雪翼鸟追逐着梦的轨迹，本不该停下飞翔。但许多年前，它们机缘巧合来到了艾卡拉奇，从此便再也没有离开。“当那片光辉的羽翼飘落时，就连神明都会为之叹息。',Feature=1,}",
  [25219] = "{id=25219,NameZh='岁寒星君',Icon='item_25219',Type=90,Quality=4,MaxNum=1,SellPrice=100,AdventureSort=1056,AdventureValue=1,AdventureReward={buffid={63000070}},Condition=8,Desc='生活在极寒之地的灵兽，在洛阳的居民眼中是祥瑞的象征。',}",
  [25220] = "{id=25220,NameZh='岁寒星君（限时）',Icon='item_25219',Type=90,Quality=4,MaxNum=1,SellPrice=100,Desc='生活在极寒之地的灵兽，在洛阳的居民眼中是祥瑞的象征。',NoStorage=5,ExistTimeType=4,ExistTime='604800',}",
  [25221] = "{id=25221,NameZh='炎之·地狱三头犬',Icon='item_25221',Type=90,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=1063,AdventureValue=1,AdventureReward={buffid={63000240}},Condition=8,Desc='来自地狱的神灵，如熔岩一般的皮肤下流淌着不灭的真火！',Feature=1,TFValidDate='2023-02-23 05:00:00',ValidDate='2023-03-02 05:00:00',}",
  [25222] = "{id=25222,NameZh='荒境灵犀',Icon='item_25222',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=1068,AdventureValue=1,AdventureReward={buffid={63000170}},Condition=8,Desc='外表很野蛮，内心很温柔，因踏实肯干的性格被评为荒境最理想的四大坐骑之一。',Feature=1,TFValidDate='2023-03-01 05:00:00',ValidDate='2023-03-22 05:00:00',}",
  [25225] = "{id=25225,NameZh='深狱咆哮',Icon='item_25225',Type=90,Quality=4,MaxNum=1,SellPrice=100,AdventureSort=1061,AdventureValue=1,Condition=8,Desc='诞生自地狱岩浆的生物，性烈如火，只为勇士低头，征服它的人需拥有一颗赤忱的心。',Feature=1,}",
  [25226] = "{id=25226,NameZh='深狱咆哮（限时）',Icon='item_25225',Type=90,Quality=4,MaxNum=1,SellPrice=100,Desc='诞生自地狱岩浆的生物，性烈如火，只为勇士低头，征服它的人需拥有一颗赤忱的心。',NoStorage=5,ExistTimeType=4,ExistTime='604800',}",
  [25227] = "{id=25227,NameZh='圣诞小猪咪',Icon='item_25227',Type=90,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=1070,AdventureValue=1,AdventureReward={buffid={63000240}},Condition=8,Desc='因为偷吃了太多圣诞礼物而变得跟猪猪一样胖的小猫咪，最大的烦恼就是恨自己肚子太小，装不下更多的圣诞礼物！',Feature=1,TFValidDate='2022-12-15 05:00:00',ValidDate='2022-12-22 05:00:00',}",
  [25229] = "{id=25229,NameZh='布洛斯盾龟',Icon='item_25229',Type=90,MaxNum=1,SellPrice=100,AdventureSort=26,AdventureValue=1,AdventureReward={buffid={63000030}},Condition=8,Desc='受到乌龟岛神秘力量影响的乌龟坐骑，可以与岛屿上多样丰富的元素之力产生共鸣，镶嵌上不同的护甲，亦或变换不同的形象，陪伴在主人身边。',NoSale=1,}",
  [25230] = "{id=25230,NameZh='童梦',Icon='item_25230',Type=90,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=1071,AdventureValue=1,AdventureReward={buffid={63000240}},Condition=8,Desc='是棉花糖一样可口的云朵，是水晶般绚烂的月亮，是爱睡觉的独角兽的陪伴——是童年的梦，在未来的某一时间闪现。',Feature=1,TFValidDate='2023-05-25 05:00:00',ValidDate='2023-06-01 05:00:00',}",
  [25231] = "{id=25231,NameZh='君王暴龙',Icon='item_25231',Type=90,Quality=4,MaxNum=1,SellPrice=100,AdventureSort=1076,AdventureValue=1,Condition=8,Desc='诞生白垩纪的它有着名副其实的暴君之名，可是它却认为自己很温柔。',}",
