  [25243] = "{id=25243,NameZh='嬉皮士理查（限时）',Icon='item_25242',Type=90,Quality=4,MaxNum=1,SellPrice=100,Desc='嬉皮士的精神就是不断反抗，永远质疑！谁说一只蜥蜴不能成为龙呢？',NoStorage=5,ExistTimeType=4,ExistTime='604800',}",
