  [25246] = "{id=25246,NameZh='边缘行者·渊下VI号',Icon='item_25246',Type=90,Quality=4,MaxNum=1,SellPrice=100,AdventureSort=1119,AdventureValue=1,Condition=8,Desc='以迅猛剑鱼为仿生原型的载具，搭载了雷根贝勒公司的数项先进技术，以锐不可当的气势宣告着它对速度与力量的绝对掌握。',}",
  [25247] = "{id=25247,NameZh='边缘行者·渊下VI号（限时）',Icon='item_25246',Type=90,Quality=4,MaxNum=1,SellPrice=100,Desc='以迅猛剑鱼为仿生原型的载具，搭载了雷根贝勒公司的数项先进技术，以锐不可当的气势宣告着它对速度与力量的绝对掌握。',NoStorage=5,ExistTimeType=4,ExistTime='604800',}",
