  [25268] = "{id=25268,NameZh='杰克南瓜的水晶球',Icon='item_25268',Type=90,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=1129,AdventureValue=1,AdventureReward={buffid={63000240}},Condition=8,Desc='据说杰克南瓜的水晶球里面，是全世界最可爱的人~',Feature=1,TFValidDate='2025-10-23 05:00:00',ValidDate='2025-10-30 05:00:00',}",
  [25271] = "{id=25271,NameZh='初心号飞船',Icon='item_25271',Type=90,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=1133,AdventureValue=1,AdventureReward={buffid={63000240}},Condition=8,Desc='【六人坐骑】\n快上船，让我们一起去征服星辰大海！',Feature=1,}",
  [25273] = "{id=25273,NameZh='圣诞礼物袋',Icon='item_25273',Type=90,Quality=4,MaxNum=1,SellPrice=100,AdventureSort=1134,AdventureValue=1,AdventureReward={buffid={63000240}},Condition=8,Desc='在这个特殊的节日里，把自己装在礼物袋里，送给你~',Feature=1,TFValidDate='2025-12-15 05:00:00',ValidDate='2025-12-22 05:00:00',}",
  [25274] = "{id=25274,NameZh='虹光小飞龙',Icon='item_25274',Type=90,Quality=4,MaxNum=1,SellPrice=100,AdventureSort=1136,AdventureValue=1,AdventureReward={buffid={63000240}},Condition=8,Desc='小小的飞龙体内，蕴含着彩虹的力量。',Feature=1,TFValidDate='2025-12-25 05:00:00',ValidDate='2026-01-01 05:00:00',}",
  [25275] = "{id=25275,NameZh='青玉灵驹',Icon='item_25275',Type=90,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=1139,AdventureValue=1,AdventureReward={buffid={63000240}},Condition=8,}",
  [25276] = "{id=25276,NameZh='喵航·波利号',Icon='item_25276',Type=90,Quality=4,MaxNum=1,SellPrice=100,AdventureSort=1137,AdventureValue=1,AdventureReward={buffid={63000240}},Condition=8,Desc='喵航起飞！波利负责微笑，你负责出发！',}",
  [25300] = "{id=25300,NameZh='手推车',Icon='item_25300',Type=91,MaxNum=1,SellPrice=1,AdventureValue=1,Condition=8,Desc='初级手推车，转职成为商人后可使用',NoStorage=5,Feature=1,LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,0,0},}",
  [25301] = "{id=25301,NameZh='照明手推车',Icon='item_25302',Type=91,MaxNum=1,SellPrice=1,AdventureValue=1,Condition=8,Desc='木匠伍德设计的手推车，使用百年椴木作为原材料，坚固耐用适合长途奔波的冒险者，减轻行路上的负重哦。习得技能【改装手推车】Lv.5可使用',NoStorage=5,Feature=1,LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,0,0},}",
  [25302] = "{id=25302,NameZh='喵喵手推车',Icon='item_25303',Type=91,MaxNum=1,SellPrice=1,AdventureValue=1,Condition=8,Desc='喵星特有的手推车，没有一颗钉子哦，全靠喵星木匠们匠心独具设计的榫卯结构。车上还有可爱的招财猫，会给使用者带来好运哟！习得技能【改装手推车】Lv.5可使用',NoStorage=5,Feature=1,LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,0,0},}",
  [25304] = "{id=25304,NameZh='闪耀波利手推车',Icon='item_25304',Type=91,MaxNum=1,SellPrice=1,AdventureValue=1,Condition=8,Desc='波利王国引以为傲的宝物，百分百黄金打造的手推车。原是波利一族的传世宝箱，被某个神秘铁匠改造成了现在的模样。除了数不尽的金银之外，其中还珍藏着国王陛下的金像，是财富和力量的象征。由于太过华丽，刚问世就引起了惊叹。“说真的，难以想象会是怎样的人能得到它……”',NoStorage=5,Feature=1,LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,0,0},}",
  [25305] = "{id=25305,NameZh='泡泡鸭手推车',Icon='item_25305',Type=91,MaxNum=1,SellPrice=1,AdventureValue=1,Condition=8,Desc='一上市就广受欢迎的手推车，充满了悠哉的闲适气息。但因为过于可爱，经常有被偷走的风险。浴缸的造型让人想起宅在家的慵懒日常，而如果靠近它，漂浮的小黄鸭会对你悄悄眨眼：“嘎？嘎嘎？带我走吧！”',NoStorage=5,Feature=1,LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,0,0},}",
  [25306] = "{id=25306,NameZh='盆钵满满手推车',Icon='item_25306',Type=91,MaxNum=1,SellPrice=1,AdventureValue=1,Condition=8,Desc='我是一个有自主意识的手推车，我也会像人类一样感到饥饿，我最喜欢吃的东西就是金币了，啊~金币这种东西简直是吃多少都不会饱啊！！嗝~',NoStorage=5,Feature=1,LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,0,0},}",
  [25308] = "{id=25308,NameZh='神罗·灼莲巡',Icon='item_25308',Type=91,MaxNum=1,SellPrice=1,AdventureValue=1,Condition=8,Desc='由来自天津町的锻造师—神无月弥音锻造的手推车。设计灵感来自盛放的红莲。它也如同被火焰包裹一般，有着浓烈的冲击力。由于曾担任过神社巫女的缘故，她的每件作品中都蕴含着先神的护佑。',NoStorage=5,Feature=1,LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,0,0},}",
  [25309] = "{id=25309,NameZh='神罗·御名巡',Icon='item_25309',Type=91,MaxNum=1,SellPrice=1,AdventureValue=1,Condition=8,Desc='由来自天津町的锻造师—神无月弥音锻造的手推车。原型曾是御用之物，现经过改良后被广泛投入使用，象征着过往的荣耀。由于曾担任过神社巫女的缘故，她的每件作品中都蕴含着先神的护佑。',NoStorage=5,Feature=1,LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,0,0},}",
  [25312] = "{id=25312,NameZh='十方圣耀',Icon='item_25312',Type=91,MaxNum=1,SellPrice=1,AdventureValue=1,Condition=8,Desc='车轮划过地面，留下的痕迹残留着丝丝光蕴，十方圣明齐聚，照耀一方净土，十字闪耀，指引迷茫之人道路，圣光永远与你同在。',NoStorage=5,LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,0,0},}",
  [25400] = "{id=25400,NameZh='魔导机甲',Icon='item_25400',Type=90,MaxNum=1,SellPrice=100,AdventureValue=1,Condition=8,Desc='完美结合魔导与科技力量制造出的机甲，帅气的外型与强大的功能让他成为每个机匠的不二选择！',NoStorage=5,Feature=1,}",
  [25401] = "{id=25401,NameZh='荣鹰辉光号',Icon='item_25401',Type=90,Quality=4,MaxNum=1,SellPrice=100,AdventureValue=1,Condition=8,Desc='卢恩王国皇室机匠专用机甲，是王国最高科技生产力的象征，不可以进行服装染色，据说制造一台的成本相当于重建一座城堡。',NoStorage=5,Feature=9,}",
  [25402] = "{id=25402,NameZh='须佐·红莲丸',Icon='item_25402',Type=90,Quality=4,MaxNum=1,SellPrice=100,AdventureValue=1,Condition=8,Desc='隶属于须佐系列机甲的红莲丸，如同地狱的红莲业火，将污浊的灵魂燃烧殆尽。',NoStorage=5,Feature=9,}",
  [25403] = "{id=25403,NameZh='须佐·狱牙丸',Icon='item_25403',Type=90,Quality=4,MaxNum=1,SellPrice=100,AdventureValue=1,Condition=8,Desc='隶属于须佐系列机甲的狱牙丸，如同地狱百鬼的爪牙，将负罪者拖入永恒的深渊。',NoStorage=5,Feature=9,}",
  [25406] = "{id=25406,NameZh='圣翼·光重奏',Icon='item_25406',Type=90,MaxNum=1,SellPrice=100,AdventureSort=10169,AdventureValue=1,Condition=8,Desc='圣洁的羽毛，坚硬的陨铁，神灵的庇佑，交织缠绕熔铸成无坚不摧的铠甲，愿驾驭它的勇士，身披圣光，如同神明再临，驱逐一切邪恶与黑暗，将光明带给所爱之人。',NoStorage=5,Feature=9,}",
  [25407] = "{id=25407,NameZh='魔导机甲（30天）',Icon='item_25400',Type=90,MaxNum=1,SellPrice=100,Desc='完美结合魔导与科技力量制造出的机甲，帅气的外型与强大的功能让他成为每个机匠的不二选择！',NoStorage=5,ExistTimeType=1,ExistTime='2592000',Feature=1,}",
  [25500] = "{id=25500,NameZh='初心波利·软糖',Icon='item_25500',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='冒险者的英勇行为得到了波利国王的认可，波利国王为了奖励这些拼搏的冒险者，特意派遣了自己的爱将初心波利陪伴着冒险者一起成长，未来的冒险道路上，还会有更多的危机，一定要不负初心坚持下去哦！冒险者！',NoStorage=5,Feature=1,}",
  [25501] = "{id=25501,NameZh='初心波利·布丁',Icon='item_25501',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='冒险者的英勇行为得到了波利国王的认可，波利国王为了奖励这些拼搏的冒险者，特意派遣了自己的爱将初心波利陪伴着冒险者一起成长，未来的冒险道路上，还会有更多的危机，一定要不负初心坚持下去哦！冒险者！',NoStorage=5,Feature=1,}",
  [25502] = "{id=25502,NameZh='初心波利·薄荷',Icon='item_25502',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='冒险者的英勇行为得到了波利国王的认可，波利国王为了奖励这些拼搏的冒险者，特意派遣了自己的爱将初心波利陪伴着冒险者一起成长，未来的冒险道路上，还会有更多的危机，一定要不负初心坚持下去哦！冒险者！',NoStorage=5,Feature=1,}",
  [25503] = "{id=25503,NameZh='疾风九尾·雪',Icon='item_25503',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000150}},Desc='隔绝于世的九尾狐族， 宽大九条尾巴是它们的标志，九尾狐族的利爪可以撕碎坚硬的钢铁，并且拥有着疾风一般的速度。九尾狐族十分注重尊严与骄傲，如果它们愿意在你面前低下头颅，那么绝对是认可了你的实力！',NoStorage=5,Feature=1,}",
  [25504] = "{id=25504,NameZh='疾风九尾·月',Icon='item_25504',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000150}},Desc='隔绝于世的九尾狐族， 宽大九条尾巴是它们的标志，九尾狐族的利爪可以撕碎坚硬的钢铁，并且拥有着疾风一般的速度。九尾狐族十分注重尊严与骄傲，如果它们愿意在你面前低下头颅，那么绝对是认可了你的实力！',NoStorage=5,Feature=1,}",
  [25505] = "{id=25505,NameZh='疾风九尾·风',Icon='item_25505',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000150}},Desc='隔绝于世的九尾狐族， 宽大九条尾巴是它们的标志，九尾狐族的利爪可以撕碎坚硬的钢铁，并且拥有着疾风一般的速度。九尾狐族十分注重尊严与骄傲，如果它们愿意在你面前低下头颅，那么绝对是认可了你的实力！',NoStorage=5,Feature=1,}",
  [25506] = "{id=25506,NameZh='疾风九尾·花',Icon='item_25506',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000150}},Desc='隔绝于世的九尾狐族， 宽大九条尾巴是它们的标志，九尾狐族的利爪可以撕碎坚硬的钢铁，并且拥有着疾风一般的速度。九尾狐族十分注重尊严与骄傲，如果它们愿意在你面前低下头颅，那么绝对是认可了你的实力！',NoStorage=5,Feature=1,}",
  [25507] = "{id=25507,NameZh='流星九尾·辰',Icon='item_25507',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000210}},Desc='九尾狐族中血统地位等级分明，流星九尾拥有最高贵的血统，流星九尾从出生的时候就具备着强大的魔法力量，是大陆上很多魔法师都望尘莫及的，能够驯服这种强大生物的冒险者，实力一定非同小可。',NoStorage=5,Feature=1,}",
  [25508] = "{id=25508,NameZh='流星九尾·夜',Icon='item_25508',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000210}},Desc='九尾狐族中血统地位等级分明，流星九尾拥有最高贵的血统，流星九尾从出生的时候就具备着强大的魔法力量，是大陆上很多魔法师都望尘莫及的，能够驯服这种强大生物的冒险者，实力一定非同小可。',NoStorage=5,Feature=1,}",
  [25509] = "{id=25509,NameZh='流星九尾·夕',Icon='item_25509',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000210}},Desc='九尾狐族中血统地位等级分明，流星九尾拥有最高贵的血统，流星九尾从出生的时候就具备着强大的魔法力量，是大陆上很多魔法师都望尘莫及的，能够驯服这种强大生物的冒险者，实力一定非同小可。',NoStorage=5,Feature=1,}",
  [25510] = "{id=25510,NameZh='流星九尾·朝',Icon='item_25510',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000210}},Desc='九尾狐族中血统地位等级分明，流星九尾拥有最高贵的血统，流星九尾从出生的时候就具备着强大的魔法力量，是大陆上很多魔法师都望尘莫及的，能够驯服这种强大生物的冒险者，实力一定非同小可。',NoStorage=5,Feature=1,}",
  [25511] = "{id=25511,NameZh='铃铛羊驼·柠檬',Icon='item_25511',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000150}},Desc='咩~咩~咩~？呆萌的豆豆眼，毛绒绒的身子，这种可爱的萌物坐骑谁不想拥有呢，冒险疲倦的时候，可以把头枕在软软的羊驼身上，伤心的时候，它还会搞怪逗你开心，铃铛羊驼真是旅行冒险的必备坐骑呢！',NoStorage=5,Feature=1,}",
  [25512] = "{id=25512,NameZh='铃铛羊驼·甜橙',Icon='item_25512',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000150}},Desc='咩~咩~咩~？呆萌的豆豆眼，毛绒绒的身子，这种可爱的萌物坐骑谁不想拥有呢，冒险疲倦的时候，可以把头枕在软软的羊驼身上，伤心的时候，它还会搞怪逗你开心，铃铛羊驼真是旅行冒险的必备坐骑呢！',NoStorage=5,Feature=1,}",
  [25513] = "{id=25513,NameZh='铃铛羊驼·樱桃',Icon='item_25513',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000150}},Desc='咩~咩~咩~？呆萌的豆豆眼，毛绒绒的身子，这种可爱的萌物坐骑谁不想拥有呢，冒险疲倦的时候，可以把头枕在软软的羊驼身上，伤心的时候，它还会搞怪逗你开心，铃铛羊驼真是旅行冒险的必备坐骑呢！',NoStorage=5,Feature=1,}",
  [25514] = "{id=25514,NameZh='铃铛羊驼·蓝莓',Icon='item_25514',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000150}},Desc='咩~咩~咩~？呆萌的豆豆眼，毛绒绒的身子，这种可爱的萌物坐骑谁不想拥有呢，冒险疲倦的时候，可以把头枕在软软的羊驼身上，伤心的时候，它还会搞怪逗你开心，铃铛羊驼真是旅行冒险的必备坐骑呢！',NoStorage=5,Feature=1,}",
  [25515] = "{id=25515,NameZh='宝藏羊驼·海底沉船',Icon='item_25515',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000210}},Desc='宝藏羊驼特别喜欢收集宝物，是个狂热的宝物爱好者，在它可爱的斗篷下面藏着神奇的魔法书，昂贵的紫水晶，甚至还有什么稀奇古怪的小魔物，宝藏羊驼只喜欢把宝物分享给自己的朋友，如果你冲着宝物去和它打交道，我劝你还是不要去了，毕竟对于觊觎它宝物的人，宝藏羊驼可是会展露很疯狂的一面哦！',NoStorage=5,Feature=1,}",
  [25516] = "{id=25516,NameZh='宝藏羊驼·深渊古堡',Icon='item_25516',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000210}},Desc='宝藏羊驼特别喜欢收集宝物，是个狂热的宝物爱好者，在它可爱的斗篷下面藏着神奇的魔法书，昂贵的紫水晶，甚至还有什么稀奇古怪的小魔物，宝藏羊驼只喜欢把宝物分享给自己的朋友，如果你冲着宝物去和它打交道，我劝你还是不要去了，毕竟对于觊觎它宝物的人，宝藏羊驼可是会展露很疯狂的一面哦！',NoStorage=5,Feature=1,}",
  [25517] = "{id=25517,NameZh='宝藏羊驼·迷失森林',Icon='item_25517',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000210}},Desc='宝藏羊驼特别喜欢收集宝物，是个狂热的宝物爱好者，在它可爱的斗篷下面藏着神奇的魔法书，昂贵的紫水晶，甚至还有什么稀奇古怪的小魔物，宝藏羊驼只喜欢把宝物分享给自己的朋友，如果你冲着宝物去和它打交道，我劝你还是不要去了，毕竟对于觊觎它宝物的人，宝藏羊驼可是会展露很疯狂的一面哦！',NoStorage=5,Feature=1,}",
  [25518] = "{id=25518,NameZh='宝藏羊驼·失落迷城',Icon='item_25518',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000210}},Desc='宝藏羊驼特别喜欢收集宝物，是个狂热的宝物爱好者，在它可爱的斗篷下面藏着神奇的魔法书，昂贵的紫水晶，甚至还有什么稀奇古怪的小魔物，宝藏羊驼只喜欢把宝物分享给自己的朋友，如果你冲着宝物去和它打交道，我劝你还是不要去了，毕竟对于觊觎它宝物的人，宝藏羊驼可是会展露很疯狂的一面哦！',NoStorage=5,Feature=1,}",
  [25519] = "{id=25519,NameZh='彩羽鸵鸟·甜心橙',Icon='item_25519',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000150}},Desc='彩羽鸵鸟有着米德加尔特大陆最美丽的鸟类之称，它们的羽毛薄若蝉翼，在阳光下能折射出绚烂的光芒，彩羽鸵鸟的速度极快，一般的魔物猎人根本捉不到它，想拥有这样美丽的坐骑的话，冒险者可要下一番功夫啦！',NoStorage=5,Feature=1,}",
  [25520] = "{id=25520,NameZh='彩羽鸵鸟·黑加仑',Icon='item_25520',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000150}},Desc='彩羽鸵鸟有着米德加尔特大陆最美丽的鸟类之称，它们的羽毛薄若蝉翼，在阳光下能折射出绚烂的光芒，彩羽鸵鸟的速度极快，一般的魔物猎人根本捉不到它，想拥有这样美丽的坐骑的话，冒险者可要下一番功夫啦！',NoStorage=5,Feature=1,}",
  [25521] = "{id=25521,NameZh='彩羽鸵鸟·冰蓝莓',Icon='item_25521',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000150}},Desc='彩羽鸵鸟有着米德加尔特大陆最美丽的鸟类之称，它们的羽毛薄若蝉翼，在阳光下能折射出绚烂的光芒，彩羽鸵鸟的速度极快，一般的魔物猎人根本捉不到它，想拥有这样美丽的坐骑的话，冒险者可要下一番功夫啦！',NoStorage=5,Feature=1,}",
  [25522] = "{id=25522,NameZh='暗夜鸵鸟·威士忌',Icon='item_25522',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000210}},Desc='极其罕见的暗夜鸵鸟，脸带假面，头顶礼帽，据说在黑夜里它们的羽毛都能发出耀眼光芒，它们具备超高的智慧，如同人类皇室贵族一般具备礼仪和涵养，能拥有这样坐骑的人，必须也是个绅士或者淑女呢！',NoStorage=5,Feature=1,}",
  [25523] = "{id=25523,NameZh='暗夜鸵鸟·白兰地',Icon='item_25523',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000210}},Desc='极其罕见的暗夜鸵鸟，脸带假面，头顶礼帽，据说在黑夜里它们的羽毛都能发出耀眼光芒，它们具备超高的智慧，如同人类皇室贵族一般具备礼仪和涵养，能拥有这样坐骑的人，必须也是个绅士或者淑女呢！',NoStorage=5,Feature=1,}",
