  [25525] = "{id=25525,NameZh='暗夜鸵鸟·伏特加',Icon='item_25525',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000210}},Desc='极其罕见的暗夜鸵鸟，脸带假面，头顶礼帽，据说在黑夜里它们的羽毛都能发出耀眼光芒，它们具备超高的智慧，如同人类皇室贵族一般具备礼仪和涵养，能拥有这样坐骑的人，必须也是个绅士或者淑女呢！',NoStorage=5,Feature=1,}",
  [25526] = "{id=25526,NameZh='巨齿斑鬣·朋克',Icon='item_25526',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='斑鬣的身体虽然不是很巨大，但是强筋有力的四肢和流线型的躯体让它具有很强的爆发力，它甚至可以捕食比自身大很多倍的魔物，巨大锋利的牙齿可以瞬间咬断猎物的脖颈，所以冒险者在驯服斑鬣的时候一定要小心它锋利的牙齿伤害到自己哦！',NoStorage=5,Feature=1,}",
  [25527] = "{id=25527,NameZh='巨齿斑鬣·放克',Icon='item_25527',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='斑鬣的身体虽然不是很巨大，但是强筋有力的四肢和流线型的躯体让它具有很强的爆发力，它甚至可以捕食比自身大很多倍的魔物，巨大锋利的牙齿可以瞬间咬断猎物的脖颈，所以冒险者在驯服斑鬣的时候一定要小心它锋利的牙齿伤害到自己哦！',NoStorage=5,Feature=1,}",
  [25528] = "{id=25528,NameZh='巨齿斑鬣·雷鬼',Icon='item_25528',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='斑鬣的身体虽然不是很巨大，但是强筋有力的四肢和流线型的躯体让它具有很强的爆发力，它甚至可以捕食比自身大很多倍的魔物，巨大锋利的牙齿可以瞬间咬断猎物的脖颈，所以冒险者在驯服斑鬣的时候一定要小心它锋利的牙齿伤害到自己哦！',NoStorage=5,Feature=1,}",
  [25529] = "{id=25529,NameZh='枭首斑鬣·嫉妒',Icon='item_25529',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='它是斑鬣中的王者，金黄色的眼瞳是它力量的象征，身上的棺材是惹怒他的人最终的去处，这种斑鬣最可怕的地方不仅是它强大的咬合力，而是强大的族群号召力，它的吼声可以带动周边所有的斑鬣族群，那是死亡来临前的声音。嘘，不要说话，快点离开！',NoStorage=5,Feature=1,}",
  [25530] = "{id=25530,NameZh='枭首斑鬣·暴食',Icon='item_25530',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='它是斑鬣中的王者，金黄色的眼瞳是它力量的象征，身上的棺材是惹怒他的人最终的去处，这种斑鬣最可怕的地方不仅是它强大的咬合力，而是强大的族群号召力，它的吼声可以带动周边所有的斑鬣族群，那是死亡来临前的声音。嘘，不要说话，快点离开！',NoStorage=5,Feature=1,}",
  [25531] = "{id=25531,NameZh='枭首斑鬣·傲慢',Icon='item_25531',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='它是斑鬣中的王者，金黄色的眼瞳是它力量的象征，身上的棺材是惹怒他的人最终的去处，这种斑鬣最可怕的地方不仅是它强大的咬合力，而是强大的族群号召力，它的吼声可以带动周边所有的斑鬣族群，那是死亡来临前的声音。嘘，不要说话，快点离开！',NoStorage=5,Feature=1,}",
  [25532] = "{id=25532,NameZh='枭首斑鬣·贪婪',Icon='item_25532',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='它是斑鬣中的王者，金黄色的眼瞳是它力量的象征，身上的棺材是惹怒他的人最终的去处，这种斑鬣最可怕的地方不仅是它强大的咬合力，而是强大的族群号召力，它的吼声可以带动周边所有的斑鬣族群，那是死亡来临前的声音。嘘，不要说话，快点离开！',NoStorage=5,Feature=1,}",
  [25533] = "{id=25533,NameZh='烈鬃豪猪·弓',Icon='item_25533',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='烈鬃豪猪虽然平时只吃一些杂果蔬菜，但是不代表它们的性情就是温顺的，多少无知的生物惨死在它们锋利的犬齿之下，想要征服这种强力坐骑，一定要小心谨慎才行哦！',NoStorage=5,Feature=1,}",
  [25534] = "{id=25534,NameZh='烈鬃豪猪·剑',Icon='item_25534',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='烈鬃豪猪虽然平时只吃一些杂果蔬菜，但是不代表它们的性情就是温顺的，多少无知的生物惨死在它们锋利的犬齿之下，想要征服这种强力坐骑，一定要小心谨慎才行哦！',NoStorage=5,Feature=1,}",
  [25535] = "{id=25535,NameZh='烈鬃豪猪·盾',Icon='item_25535',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='烈鬃豪猪虽然平时只吃一些杂果蔬菜，但是不代表它们的性情就是温顺的，多少无知的生物惨死在它们锋利的犬齿之下，想要征服这种强力坐骑，一定要小心谨慎才行哦！',NoStorage=5,Feature=1,}",
  [25536] = "{id=25536,NameZh='泰坦豪猪·福柏',Icon='item_25536',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='巨大的身躯让一般的魔物都不敢靠近，泰坦豪猪的身躯上有着为它们的主人准备的舒适座椅，注意！没有实力的话千万不要轻易的尝试去触碰它们，毕竟泰坦豪猪的巨大犬齿可不是吃素的。',NoStorage=5,Feature=1,}",
