  [25539] = "{id=25539,NameZh='泰坦豪猪·科俄斯',Icon='item_25539',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='巨大的身躯让一般的魔物都不敢靠近，泰坦豪猪的身躯上有着为它们的主人准备的舒适座椅，注意！没有实力的话千万不要轻易的尝试去触碰它们，毕竟泰坦豪猪的巨大犬齿可不是吃素的。',NoStorage=5,Feature=1,}",
  [25540] = "{id=25540,NameZh='疾星剑狮·木星',Icon='item_25540',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='疾星剑狮生活在植物稀缺的平原上，它们能适应任何的艰难生存环境，而且在所有陆地魔物中，疾星剑狮具有最强大的咬合力，它们锋利的牙齿可以轻易咬碎猎物的头骨，想要拥有这种强力的坐骑，冒险者可要展现出强大的实力哦！',NoStorage=5,Feature=1,}",
  [25541] = "{id=25541,NameZh='疾星剑狮·冥王星',Icon='item_25541',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='疾星剑狮生活在植物稀缺的平原上，它们能适应任何的艰难生存环境，而且在所有陆地魔物中，疾星剑狮具有最强大的咬合力，它们锋利的牙齿可以轻易咬碎猎物的头骨，想要拥有这种强力的坐骑，冒险者可要展现出强大的实力哦！',NoStorage=5,Feature=1,}",
  [25542] = "{id=25542,NameZh='疾星剑狮·太阳',Icon='item_25542',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='疾星剑狮生活在植物稀缺的平原上，它们能适应任何的艰难生存环境，而且在所有陆地魔物中，疾星剑狮具有最强大的咬合力，它们锋利的牙齿可以轻易咬碎猎物的头骨，想要拥有这种强力的坐骑，冒险者可要展现出强大的实力哦！',NoStorage=5,Feature=1,}",
  [25543] = "{id=25543,NameZh='琰翎剑狮·皇冠',Icon='item_25543',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='琰翎剑狮是狮类族群的王者，他们具备着优秀的领导力和族群的带动力，它们的吼叫声可以震撼所有陆地的魔物，所有能驾驭琰翎剑狮的人，无一不是万里挑一的英雄人物！',NoStorage=5,Feature=1,}",
  [25544] = "{id=25544,NameZh='琰翎剑狮·铠甲',Icon='item_25544',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='琰翎剑狮是狮类族群的王者，他们具备着优秀的领导力和族群的带动力，它们的吼叫声可以震撼所有陆地的魔物，所有能驾驭琰翎剑狮的人，无一不是万里挑一的英雄人物！',NoStorage=5,Feature=1,}",
  [25545] = "{id=25545,NameZh='琰翎剑狮·王座',Icon='item_25545',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='琰翎剑狮是狮类族群的王者，他们具备着优秀的领导力和族群的带动力，它们的吼叫声可以震撼所有陆地的魔物，所有能驾驭琰翎剑狮的人，无一不是万里挑一的英雄人物！',NoStorage=5,Feature=1,}",
  [25546] = "{id=25546,NameZh='琰翎剑狮·权杖',Icon='item_25546',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='琰翎剑狮是狮类族群的王者，他们具备着优秀的领导力和族群的带动力，它们的吼叫声可以震撼所有陆地的魔物，所有能驾驭琰翎剑狮的人，无一不是万里挑一的英雄人物！',NoStorage=5,Feature=1,}",
  [25547] = "{id=25547,NameZh='豚鼠先生·乡村',Icon='item_25547',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='豚鼠先生的家族是远星大陆上最古老的物种之一，天性好动又充满好奇心的它们遍布整个大陆，无论是山川河流还是城市小巷，都是它们探索的对象，而由它们拉动的小车也是大陆上最受欢迎的交通工具。',NoStorage=5,Feature=1,}",
  [25548] = "{id=25548,NameZh='豚鼠先生·溪流',Icon='item_25548',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='豚鼠先生的家族是远星大陆上最古老的物种之一，天性好动又充满好奇心的它们遍布整个大陆，无论是山川河流还是城市小巷，都是它们探索的对象，而由它们拉动的小车也是大陆上最受欢迎的交通工具。',NoStorage=5,Feature=1,}",
  [25549] = "{id=25549,NameZh='豚鼠先生·荒野',Icon='item_25549',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='豚鼠先生的家族是远星大陆上最古老的物种之一，天性好动又充满好奇心的它们遍布整个大陆，无论是山川河流还是城市小巷，都是它们探索的对象，而由它们拉动的小车也是大陆上最受欢迎的交通工具。',NoStorage=5,Feature=1,}",
  [25550] = "{id=25550,NameZh='豚鼠先生·庄园',Icon='item_25550',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='豚鼠先生的家族是远星大陆上最古老的物种之一，天性好动又充满好奇心的它们遍布整个大陆，无论是山川河流还是城市小巷，都是它们探索的对象，而由它们拉动的小车也是大陆上最受欢迎的交通工具。',NoStorage=5,Feature=1,}",
  [25551] = "{id=25551,NameZh='豚鼠绅士·优雅',Icon='item_25551',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='历经古典音乐、山水风情以及礼仪修养的洗礼，豚鼠先生进阶成为了豚鼠绅士！优雅的单片眼镜，帅气的高筒礼帽，随风抖动的飒爽披风！有这样一位绅士带领，整个旅程都变得迷人了起来。',NoStorage=5,Feature=1,}",
  [25552] = "{id=25552,NameZh='豚鼠绅士·深邃',Icon='item_25552',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='历经古典音乐、山水风情以及礼仪修养的洗礼，豚鼠先生进阶成为了豚鼠绅士！优雅的单片眼镜，帅气的高筒礼帽，随风抖动的飒爽披风！有这样一位绅士带领，整个旅程都变得迷人了起来。',NoStorage=5,Feature=1,}",
  [25553] = "{id=25553,NameZh='豚鼠绅士·热忱',Icon='item_25553',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='历经古典音乐、山水风情以及礼仪修养的洗礼，豚鼠先生进阶成为了豚鼠绅士！优雅的单片眼镜，帅气的高筒礼帽，随风抖动的飒爽披风！有这样一位绅士带领，整个旅程都变得迷人了起来。',NoStorage=5,Feature=1,}",
  [25554] = "{id=25554,NameZh='豚鼠绅士·神秘',Icon='item_25554',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='历经古典音乐、山水风情以及礼仪修养的洗礼，豚鼠先生进阶成为了豚鼠绅士！优雅的单片眼镜，帅气的高筒礼帽，随风抖动的飒爽披风！有这样一位绅士带领，整个旅程都变得迷人了起来。',NoStorage=5,Feature=1,}",
  [25560] = "{id=25560,NameZh='归来蛙·黄丹',Icon='item_25560',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='神行蛙的顶点，能力大为提升。不仅速度更快、力量更大、耐久更强，甚至连颜值都达到了一个新的高度。自尊非常强，有着敏感细腻的心，务必要用温柔的心来敬重对待它哦。',NoStorage=5,Feature=1,}",
  [25561] = "{id=25561,NameZh='归来蛙·新桥',Icon='item_25561',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='神行蛙的顶点，能力大为提升。不仅速度更快、力量更大、耐久更强，甚至连颜值都达到了一个新的高度。自尊非常强，有着敏感细腻的心，务必要用温柔的心来敬重对待它哦。',NoStorage=5,Feature=1,}",
  [25562] = "{id=25562,NameZh='归来蛙·小葱',Icon='item_25562',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='神行蛙的顶点，能力大为提升。不仅速度更快、力量更大、耐久更强，甚至连颜值都达到了一个新的高度。自尊非常强，有着敏感细腻的心，务必要用温柔的心来敬重对待它哦。',NoStorage=5,Feature=1,}",
  [25563] = "{id=25563,NameZh='归来蛙·金藤',Icon='item_25563',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='神行蛙的顶点，能力大为提升。不仅速度更快、力量更大、耐久更强，甚至连颜值都达到了一个新的高度。自尊非常强，有着敏感细腻的心，务必要用温柔的心来敬重对待它哦。',NoStorage=5,Feature=1,}",
  [25564] = "{id=25564,NameZh='神行蛙·青竹',Icon='item_25564',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='天水之国特有动物，身形庞大却敏捷，不论在陆地上还是在水中都行动迅猛，是忍者必不可少的伙伴。不过，非常非常能吃，如果不喂饱它的话……请后果自负。',NoStorage=5,Feature=1,}",
  [25565] = "{id=25565,NameZh='神行蛙·柴柴',Icon='item_25565',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='天水之国特有动物，身形庞大却敏捷，不论在陆地上还是在水中都行动迅猛，是忍者必不可少的伙伴。不过，非常非常能吃，如果不喂饱它的话……请后果自负。',NoStorage=5,Feature=1,}",
  [25566] = "{id=25566,NameZh='神行蛙·阿茜',Icon='item_25566',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='天水之国特有动物，身形庞大却敏捷，不论在陆地上还是在水中都行动迅猛，是忍者必不可少的伙伴。不过，非常非常能吃，如果不喂饱它的话……请后果自负。',NoStorage=5,Feature=1,}",
  [25567] = "{id=25567,NameZh='神行蛙·桔梗',Icon='item_25567',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='天水之国特有动物，身形庞大却敏捷，不论在陆地上还是在水中都行动迅猛，是忍者必不可少的伙伴。不过，非常非常能吃，如果不喂饱它的话……请后果自负。',NoStorage=5,Feature=1,}",
  [25570] = "{id=25570,NameZh='钢铁骑士·鬼火',Icon='item_25570',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='雷根贝勒公司出产的新型越野摩托，涡轮引擎赋予强劲动力，让它能够适应各种地形的跋涉。其设计者坚信它的出现会颠覆整个坐骑行业，并最终让这种现代化工具取代传统坐骑——可惜由于由于速度过快难以驾驭，这种摩托并没有被大范围普及。',NoStorage=5,Feature=1,}",
  [25571] = "{id=25571,NameZh='钢铁骑士·天火',Icon='item_25571',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='雷根贝勒公司出产的新型越野摩托，涡轮引擎赋予强劲动力，让它能够适应各种地形的跋涉。其设计者坚信它的出现会颠覆整个坐骑行业，并最终让这种现代化工具取代传统坐骑——可惜由于由于速度过快难以驾驭，这种摩托并没有被大范围普及。',NoStorage=5,Feature=1,}",
  [25572] = "{id=25572,NameZh='钢铁骑士·雷火',Icon='item_25572',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='雷根贝勒公司出产的新型越野摩托，涡轮引擎赋予强劲动力，让它能够适应各种地形的跋涉。其设计者坚信它的出现会颠覆整个坐骑行业，并最终让这种现代化工具取代传统坐骑——可惜由于由于速度过快难以驾驭，这种摩托并没有被大范围普及。',NoStorage=5,Feature=1,}",
  [25573] = "{id=25573,NameZh='钢铁骑士·荒火',Icon='item_25573',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='雷根贝勒公司出产的新型越野摩托，涡轮引擎赋予强劲动力，让它能够适应各种地形的跋涉。其设计者坚信它的出现会颠覆整个坐骑行业，并最终让这种现代化工具取代传统坐骑——可惜由于由于速度过快难以驾驭，这种摩托并没有被大范围普及。',NoStorage=5,Feature=1,}",
  [25574] = "{id=25574,NameZh='天启骑士·纷争',Icon='item_25574',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='“钢铁骑士”型越野摩托的魔改版本，强化了车身结构的同时将引擎动力提升了七成。也正因如此，这台摩托成为了难以驾驭的钢铁猛兽，一些技术不精的骑手贸然驾驶这辆摩托，造成了不少交通事故，以致于雷根贝勒公司拒绝为经过改装的摩托车提供保修服务，而里希塔乐镇的居民们则用“天启骑士”来形容这种呼啸而过、带来麻烦的改装摩托。',NoStorage=5,Feature=1,}",
  [25575] = "{id=25575,NameZh='天启骑士·征服',Icon='item_25575',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='“钢铁骑士”型越野摩托的魔改版本，强化了车身结构的同时将引擎动力提升了七成。也正因如此，这台摩托成为了难以驾驭的钢铁猛兽，一些技术不精的骑手贸然驾驶这辆摩托，造成了不少交通事故，以致于雷根贝勒公司拒绝为经过改装的摩托车提供保修服务，而里希塔乐镇的居民们则用“天启骑士”来形容这种呼啸而过、带来麻烦的改装摩托。',NoStorage=5,Feature=1,}",
