  [25577] = "{id=25577,NameZh='天启骑士·死亡',Icon='item_25577',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='“钢铁骑士”型越野摩托的魔改版本，强化了车身结构的同时将引擎动力提升了七成。也正因如此，这台摩托成为了难以驾驭的钢铁猛兽，一些技术不精的骑手贸然驾驶这辆摩托，造成了不少交通事故，以致于雷根贝勒公司拒绝为经过改装的摩托车提供保修服务，而里希塔乐镇的居民们则用“天启骑士”来形容这种呼啸而过、带来麻烦的改装摩托。',NoStorage=5,Feature=1,}",
  [25580] = "{id=25580,NameZh='梦魂兽·水象',Icon='item_25580',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='传说中可以自由穿行于现实与梦境间的灵兽，以人们的恐惧为食，相传有它在的地方人们不会被噩梦纠缠。',NoStorage=5,}",
