  [25583] = "{id=25583,NameZh='梦魂兽·火象',Icon='item_25583',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='传说中可以自由穿行于现实与梦境间的灵兽，以人们的恐惧为食，相传有它在的地方人们不会被噩梦纠缠。',NoStorage=5,}",
  [25584] = "{id=25584,NameZh='安梦使者·水象',Icon='item_25584',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='以人们的噩梦为食的传说生物，拥有着自由穿梭于现实世界与心象世界的能力。它们常常与那些能够洞悉灵魂奥秘的人为伴',NoStorage=5,}",
  [25585] = "{id=25585,NameZh='安梦使者·土象',Icon='item_25585',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='以人们的噩梦为食的传说生物，拥有着自由穿梭于现实世界与心象世界的能力。它们常常与那些能够洞悉灵魂奥秘的人为伴',NoStorage=5,}",
  [25586] = "{id=25586,NameZh='安梦使者·冰象',Icon='item_25586',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='以人们的噩梦为食的传说生物，拥有着自由穿梭于现实世界与心象世界的能力。它们常常与那些能够洞悉灵魂奥秘的人为伴',NoStorage=5,}",
  [25587] = "{id=25587,NameZh='安梦使者·火象',Icon='item_25587',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='以人们的噩梦为食的传说生物，拥有着自由穿梭于现实世界与心象世界的能力。它们常常与那些能够洞悉灵魂奥秘的人为伴',NoStorage=5,}",
  [25590] = "{id=25590,NameZh='山麟·金',Icon='item_25590',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='流星林的密林中生活的异兽，与人类非常亲近，流星林的弟子们常常将它们作为代步工具。',}",
  [25591] = "{id=25591,NameZh='山麟·石',Icon='item_25591',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='流星林的密林中生活的异兽，与人类非常亲近，流星林的弟子们常常将它们作为代步工具。',}",
  [25592] = "{id=25592,NameZh='山麟·木',Icon='item_25592',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000160}},Desc='流星林的密林中生活的异兽，与人类非常亲近，流星林的弟子们常常将它们作为代步工具。',}",
  [25593] = "{id=25593,NameZh='山麟·玉',Icon='item_25593',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='流星林的密林中生活的异兽，与人类非常亲近，流星林的弟子们常常将它们作为代步工具。',}",
  [25594] = "{id=25594,NameZh='獬豸·金',Icon='item_25594',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='传说中的灵兽，拥有很高的智慧。能够辨别是非曲直，是勇猛、公正的象征。',}",
  [25595] = "{id=25595,NameZh='獬豸·石',Icon='item_25595',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='传说中的灵兽，拥有很高的智慧。能够辨别是非曲直，是勇猛、公正的象征。',}",
  [25596] = "{id=25596,NameZh='獬豸·木',Icon='item_25596',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000220}},Desc='传说中的灵兽，拥有很高的智慧。能够辨别是非曲直，是勇猛、公正的象征。',}",
  [25597] = "{id=25597,NameZh='獬豸·玉',Icon='item_25597',Type=90,Quality=3,MaxNum=1,SellPrice=100,Desc='传说中的灵兽，拥有很高的智慧。能够辨别是非曲直，是勇猛、公正的象征。',}",
  [26118] = "{id=26118,NameZh='萌萌',Icon='item_25002',Type=90,Quality=3,MaxNum=1,SellPrice=100,Desc='极其珍贵的波利坐骑。（存在的时间只有72小时）',NoStorage=5,ExistTimeType=1,ExistTime='259200',Feature=1,}",
  [26119] = "{id=26119,NameZh='利力',Icon='item_25139',Type=90,Quality=3,MaxNum=1,SellPrice=100,Desc='“骑士之星”赛伊连•瓦恩萨的坐骑，是六人小队最忠诚的伙伴。（存在时间只有72小时）',NoStorage=5,ExistTimeType=1,ExistTime='259200',Feature=1,}",
  [29001] = "{id=29001,NameZh='初心波利系列坐骑',Icon='item_25500',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureSort=501,AdventureValue=50,AdventureReward={buffid={63000160}},Condition=8,Desc='冒险者的英勇行为得到了波利国王的认可，波利国王为了奖励这些拼搏的冒险者，特意派遣了自己的爱将初心波利陪伴着冒险者一起成长，未来的冒险道路上，还会有更多的危机，一定要不负初心坚持下去哦！冒险者！',NoStorage=5,Feature=1,}",
  [29002] = "{id=29002,NameZh='疾风九尾系列坐骑',Icon='item_25503',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureSort=502,AdventureValue=50,AdventureReward={buffid={63000150}},Condition=8,Desc='隔绝于世的九尾狐族， 宽大九条尾巴是它们的标志，九尾狐族的利爪可以撕碎坚硬的钢铁，并且拥有着疾风一般的速度。九尾狐族十分注重尊严与骄傲，如果它们愿意在你面前低下头颅，那么绝对是认可了你的实力！',NoStorage=5,Feature=1,}",
  [29003] = "{id=29003,NameZh='流星九尾系列坐骑',Icon='item_25507',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=503,AdventureValue=100,AdventureReward={buffid={63000210}},Condition=8,Desc='九尾狐族中血统地位等级分明，流星九尾拥有最高贵的血统，流星九尾从出生的时候就具备着强大的魔法力量，是大陆上很多魔法师都望尘莫及的，能够驯服这种强大生物的冒险者，实力一定非同小可。',NoStorage=5,Feature=1,}",
  [29004] = "{id=29004,NameZh='铃铛羊驼系列坐骑',Icon='item_25511',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureSort=504,AdventureValue=50,AdventureReward={buffid={63000150}},Condition=8,Desc='咩~咩~咩~？呆萌的豆豆眼，毛绒绒的身子，这种可爱的萌物坐骑谁不想拥有呢，冒险疲倦的时候，可以把头枕在软软的羊驼身上，伤心的时候，它还会搞怪逗你开心，铃铛羊驼真是旅行冒险的必备坐骑呢！',NoStorage=5,Feature=1,}",
  [29005] = "{id=29005,NameZh='宝藏羊驼系列坐骑',Icon='item_25515',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=505,AdventureValue=100,AdventureReward={buffid={63000210}},Condition=8,Desc='宝藏羊驼特别喜欢收集宝物，是个狂热的宝物爱好者，在它可爱的斗篷下面藏着神奇的魔法书，昂贵的紫水晶，甚至还有什么稀奇古怪的小魔物，宝藏羊驼只喜欢把宝物分享给自己的朋友，如果你冲着宝物去和它打交道，我劝你还是不要去了，毕竟对于觊觎它宝物的人，宝藏羊驼可是会展露很疯狂的一面哦！',NoStorage=5,Feature=1,}",
  [29006] = "{id=29006,NameZh='彩羽鸵鸟系列坐骑',Icon='item_25105',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureSort=506,AdventureValue=50,AdventureReward={buffid={63000150}},Condition=8,Desc='彩羽鸵鸟有着米德加尔特大陆最美丽的鸟类之称，它们的羽毛薄若蝉翼，在阳光下能折射出绚烂的光芒，彩羽鸵鸟的速度极快，一般的魔物猎人根本捉不到它，想拥有这样美丽的坐骑的话，冒险者可要下一番功夫啦！',NoStorage=5,Feature=1,}",
  [29007] = "{id=29007,NameZh='暗夜鸵鸟系列坐骑',Icon='item_25522',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=507,AdventureValue=100,AdventureReward={buffid={63000210}},Condition=8,Desc='极其罕见的暗夜鸵鸟，脸带假面，头顶礼帽，据说在黑夜里它们的羽毛都能发出耀眼光芒，它们具备超高的智慧，如同人类皇室贵族一般具备礼仪和涵养，能拥有这样坐骑的人，必须也是个绅士或者淑女呢！',NoStorage=5,Feature=1,}",
  [29008] = "{id=29008,NameZh='巨齿斑鬣系列坐骑',Icon='item_25106',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureSort=508,AdventureValue=50,AdventureReward={buffid={63000160}},Condition=8,Desc='斑鬣的身体虽然不是很巨大，但是强筋有力的四肢和流线型的躯体让它具有很强的爆发力，它甚至可以捕食比自身大很多倍的魔物，巨大锋利的牙齿可以瞬间咬断猎物的脖颈，所以冒险者在驯服斑鬣的时候一定要小心它锋利的牙齿伤害到自己哦！',NoStorage=5,Feature=1,}",
  [29009] = "{id=29009,NameZh='地狱斑鬣系列坐骑',Icon='item_25529',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=509,AdventureValue=100,AdventureReward={buffid={63000220}},Condition=8,Desc='地狱斑鬣是斑鬣中的王者，它身上的棺材就是为那些惹怒它的生物准备的，这种斑鬣最可怕的地方不是它强大的咬合力，而是强大的族群号召力，它地狱般的吼声可以带动周边所有的斑鬣族群，所以没有强大的实力的话，见到这种地狱斑鬣一定要立刻躲开哦！',NoStorage=5,Feature=1,}",
  [29010] = "{id=29010,NameZh='烈鬃豪猪系列坐骑',Icon='item_25112',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureSort=510,AdventureValue=50,AdventureReward={buffid={63000160}},Condition=8,Desc='烈鬃豪猪虽然平时只吃一些杂果蔬菜，但是不代表它们的性情就是温顺的，多少无知的生物惨死在它们锋利的犬齿之下，想要征服这种强力坐骑，一定要小心谨慎才行哦！',NoStorage=5,Feature=1,}",
  [29011] = "{id=29011,NameZh='泰坦豪猪系列坐骑',Icon='item_25536',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=511,AdventureValue=100,AdventureReward={buffid={63000220}},Condition=8,Desc='巨大的身躯让一般的魔物都不敢靠近，泰坦豪猪的身躯上有着为它们的主人准备的舒适座椅，注意！没有实力的话千万不要轻易的尝试去触碰它们，毕竟泰坦豪猪的巨大犬齿可不是吃素的。',NoStorage=5,Feature=1,}",
  [29012] = "{id=29012,NameZh='疾星剑狮系列坐骑',Icon='item_25013',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureSort=512,AdventureValue=50,AdventureReward={buffid={63000160}},Condition=8,Desc='疾星剑狮生活在植物稀缺的平原上，它们能适应任何的艰难生存环境，而且在所有陆地魔物中，疾星剑狮具有最强大的咬合力，它们锋利的牙齿可以轻易咬碎猎物的头骨，想要拥有这种强力的坐骑，冒险者可要展现出强大的实力哦！',NoStorage=5,Feature=1,}",
  [29013] = "{id=29013,NameZh='琰翎剑狮系列坐骑',Icon='item_25543',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=513,AdventureValue=100,AdventureReward={buffid={63000220}},Condition=8,Desc='琰翎剑狮是狮类族群的王者，他们具备着优秀的领导力和族群的带动力，它们的吼叫声可以震撼所有陆地的魔物，所有能驾驭琰翎剑狮的人，无一不是万里挑一的英雄人物！',NoStorage=5,Feature=1,}",
  [29014] = "{id=29014,NameZh='深渊地龙系列坐骑',Icon='item_25116',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=5,AdventureValue=1,Condition=8,Desc='在古老传说中，由于地龙一族帮助了龙骑士，某位苍绿发色的女神赐予地龙三种不同的恩宠，力量，速度，坚韧。这些地龙是不可多得的强大坐骑。',NoStorage=5,Feature=1,}",
  [29015] = "{id=29015,NameZh='烈风狮鹫系列坐骑',Icon='item_25119',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=6,AdventureValue=1,Condition=8,Desc='驯服狮鹫作为坐骑的难度在于他们天生性格高傲且力量强大，最好的办法是从狮鹫出生就开始训练他们，狮鹫对自己认可的主人忠心耿耿，随时准备着与主人征战四方。',NoStorage=5,Feature=1,}",
  [29016] = "{id=29016,NameZh='豚鼠先生系列坐骑',Icon='item_25547',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureSort=514,AdventureValue=50,AdventureReward={buffid={63000160}},Condition=8,Desc='豚鼠先生的家族是远星大陆上最古老的物种之一，天性好动又充满好奇心的它们遍布整个大陆，无论是山川河流还是城市小巷，都是它们探索的对象，而由它们拉动的小车也是大陆上最受欢迎的交通工具。',NoStorage=5,Feature=1,}",
  [29017] = "{id=29017,NameZh='豚鼠绅士系列坐骑',Icon='item_25551',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=515,AdventureValue=100,AdventureReward={buffid={63000220}},Condition=8,Desc='历经古典音乐、山水风情以及礼仪修养的洗礼，豚鼠先生进阶成为了豚鼠绅士！优雅的单片眼镜，帅气的高筒礼帽，随风抖动的飒爽披风！有这样一位绅士带领，整个旅程都变得迷人了起来。',NoStorage=5,Feature=1,}",
  [29018] = "{id=29018,NameZh='归来蛙系列坐骑',Icon='item_25563',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureSort=517,AdventureValue=100,AdventureReward={buffid={63000220}},Condition=8,NoStorage=5,Feature=1,}",
  [29019] = "{id=29019,NameZh='神行蛙系列坐骑',Icon='item_25564',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=516,AdventureValue=50,AdventureReward={buffid={63000160}},Condition=8,NoStorage=5,Feature=1,}",
  [29020] = "{id=29020,NameZh='钢铁骑士系列坐骑',Icon='item_25573',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureSort=518,AdventureValue=50,AdventureReward={buffid={63000160}},Condition=8,Desc='雷根贝勒公司出产的新型越野摩托，涡轮引擎赋予强劲动力，让它能够适应各种地形的跋涉。其设计者坚信它的出现会颠覆整个坐骑行业，并最终让这种现代化工具取代传统坐骑——可惜由于由于速度过快难以驾驭，这种摩托并没有被大范围普及。知情人士透露：雷根贝勒公司正在加紧研发适合多兰族身材的摩托。',Feature=1,}",
  [29021] = "{id=29021,NameZh='天启骑士系列坐骑',Icon='item_25574',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=519,AdventureValue=100,AdventureReward={buffid={63000220}},Condition=8,Desc='“钢铁骑士”型越野摩托的魔改版本，强化了车身结构的同时将引擎动力提升了七成。也正因如此，这台摩托成为了难以驾驭的钢铁猛兽，一些技术不精的骑手贸然驾驶这辆摩托，造成了不少交通事故，以致于雷根贝勒公司拒绝为经过改装的摩托车提供保修服务，而里希塔乐镇的居民们则用“天启骑士”来形容这种呼啸而过、带来麻烦的改装摩托。知情人士透露：雷根贝勒公司正在加紧研发适合多兰族身材的摩托。',Feature=1,}",
  [29022] = "{id=29022,NameZh='梦魂兽系列坐骑',Icon='item_25583',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureSort=520,AdventureValue=50,AdventureReward={buffid={63000160}},Condition=8,Desc='传说中可以自由穿行于现实与梦境间的灵兽，以人们的恐惧为食，相传有它在的地方人们不会被噩梦纠缠。',}",
  [29023] = "{id=29023,NameZh='安梦使者系列坐骑',Icon='item_25587',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=521,AdventureValue=100,AdventureReward={buffid={63000220}},Condition=8,Desc='以人们的噩梦为食的传说生物，拥有着自由穿梭于现实世界与心象世界的能力。它们常常与那些能够洞悉灵魂奥秘的人为伴',}",
  [29024] = "{id=29024,NameZh='山麟系列坐骑',Icon='item_25593',Type=90,Quality=2,MaxNum=1,SellPrice=100,AdventureSort=522,AdventureValue=50,AdventureReward={buffid={63000160}},Condition=8,Desc='流星林的密林中生活的异兽，与人类非常亲近，流星林的弟子们常常将它们作为代步工具。',}",
  [29025] = "{id=29025,NameZh='獬豸系列坐骑',Icon='item_25594',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=523,AdventureValue=100,AdventureReward={buffid={63000220}},Condition=8,Desc='传说中的灵兽，拥有很高的智慧。能够辨别是非曲直，是勇猛、公正的象征。',}",
  [29453] = "{id=29453,NameZh='天火掠空者',Icon='item_29453',Type=90,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=28,AdventureValue=1,AdventureReward={buffid={63000030}},Condition=8,Desc='征服之路，从天火焚烬开始。',Feature=1,}",
  [30000] = "{id=30000,NameZh='书架·秘藏',Icon='item_30000',Type=938,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=10001,AdventureValue=45,AdventureReward={buffid={64000240},rewardid={3920}},Condition=4,ComposeID=130000,Desc='对于克拉拉来说，书籍就是最珍贵的宝藏。',Feature=1,}",
  [30001] = "{id=30001,NameZh='壁炉·流火',Icon='item_30001',Type=902,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=10002,AdventureValue=69,AdventureReward={buffid={64000230},rewardid={3920}},Condition=4,ComposeID=130001,Desc='克拉拉引以为傲的壁炉，透露着与小屋格格不入的华丽。似乎可以产出一些额外的材料，“低调，这叫低调的优雅。”',Feature=1,}",
  [30002] = "{id=30002,NameZh='沙发·时光摇椅',Icon='item_30002',Type=901,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=10003,AdventureValue=50,AdventureReward={buffid={64000190},rewardid={3920}},Condition=4,ComposeID=130002,Desc='很多年以前，克拉拉的奶奶曾坐在这里，为她织下空中的第一朵云彩。',Feature=1,}",
  [30003] = "{id=30003,NameZh='柜·悠扬',Icon='item_30003',Type=937,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=10004,AdventureValue=25,AdventureReward={buffid={64000040},rewardid={3920}},Condition=4,ComposeID=130003,Desc='上方雕有波利样式的简约长柜，优雅中又有着居家气息。',Feature=1,}",
  [30004] = "{id=30004,NameZh='壁灯·微光',Icon='item_30004',Type=909,MaxNum=99999,SellPrice=100,AdventureSort=10005,AdventureValue=16,AdventureReward={buffid={64000250},rewardid={3920}},Condition=4,ComposeID=130004,Desc='黑猫给某位半夜失眠的少女制作的小灯。“怕黑就直说嘛……”',Feature=1,}",
  [30005] = "{id=30005,NameZh='地毯·圆溜溜绒绒',Icon='item_30005',Type=903,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=10006,AdventureValue=25,AdventureReward={buffid={64000390},rewardid={3920}},Condition=4,ComposeID=130005,Desc='毛乎乎的地毯，经常被黑猫踩出一个个小脚印。',Feature=1,}",
  [30006] = "{id=30006,NameZh='地毯·“欢迎回家”',Icon='item_30006',Type=903,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=10007,AdventureValue=25,AdventureReward={buffid={64000390},rewardid={3920}},Condition=4,ComposeID=130006,Desc='绣着字母的手工地垫，看起来有些陈旧，不知出自何人之手。密密的针脚间，满满都是缝制者的心意。',Feature=1,}",
  [30007] = "{id=30007,NameZh='椅·素秋',Icon='item_30007',Type=906,MaxNum=99999,SellPrice=100,AdventureSort=10008,AdventureValue=16,AdventureReward={buffid={64000200},rewardid={3920}},Condition=4,ComposeID=130007,Desc='棉麻质地的沙发椅，在白与咖色的交错中，依稀能感到秋意。至于上面的抓痕，克拉拉说她并不知情。',Feature=1,}",
  [30008] = "{id=30008,NameZh='屏风·林间私语',Icon='item_30008',Type=939,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=10009,AdventureValue=50,AdventureReward={buffid={64000190},rewardid={3920}},Condition=4,ComposeID=130008,Desc='典雅精巧的木质屏风，是克拉拉很喜欢的装饰。',Feature=1,}",
  [30009] = "{id=30009,NameZh='床头柜·葱葱',Icon='item_30009',Type=936,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=10010,AdventureValue=25,AdventureReward={buffid={64000040},rewardid={3920}},Condition=4,ComposeID=130009,Desc='克拉拉和黑猫共同浇灌的小绿植，放在床头柜上，每天都有好心情~',Feature=1,}",
  [30010] = "{id=30010,NameZh='桌·雕刻时光',Icon='item_30010',Type=937,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=10011,AdventureValue=25,AdventureReward={buffid={64000040},rewardid={3920}},Condition=4,ComposeID=130010,Desc='造型十分典雅的桌子，上面摆着克拉拉心爱的花瓶，精巧又优雅。',Feature=1,}",
  [30011] = "{id=30011,NameZh='床·沉梦',Icon='item_30011',Type=905,MaxNum=99999,SellPrice=100,AdventureSort=10012,AdventureValue=80,AdventureReward={buffid={64000050},rewardid={3920}},Condition=4,ComposeID=130011,Desc='温暖质朴的大床。每当月亮升起，黑猫总会翘着尾巴来到床边，悄悄守护她入睡。',Feature=1,}",
  [30012] = "{id=30012,NameZh='窗·晨辉',Icon='item_30012',Type=908,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=10013,AdventureValue=30,AdventureReward={buffid={64000390},rewardid={3920}},Condition=4,ComposeID=130012,Desc='无论何时都溢满了阳光的窗户，让屋内充满了生机。',Feature=1,}",
  [30013] = "{id=30013,NameZh='衣橱·漆夜',Icon='item_30013',Type=907,MaxNum=99999,SellPrice=100,AdventureSort=10014,AdventureValue=44,AdventureReward={buffid={64000050},rewardid={3920}},Condition=4,ComposeID=130013,Desc='充满了古典色彩的衣橱。据说黑猫曾经窜到里面被关了一夜，所以当开关门时，衣橱会发出喵呜喵呜的声音。',Feature=1,}",
  [30014] = "{id=30014,NameZh='储物柜·古檀',Icon='item_30014',Type=910,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=10015,AdventureValue=45,AdventureReward={buffid={64000040},rewardid={3920}},Condition=4,ComposeID=130014,Desc='古色古香的储物柜，看起来有些年代了。里面藏着上一任主人留下的珍宝，克拉拉怎么也打不开。',Feature=1,}",
  [30015] = "{id=30015,NameZh='餐桌·秋森',Icon='item_30015',Type=945,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=10016,AdventureValue=75,AdventureReward={buffid={64000180},rewardid={3920}},Condition=4,ComposeID=130015,Desc='圆木做成的的桌椅，被人整整齐齐摆成了一套，简洁中带着独有的清新感。',Feature=1,}",
  [30016] = "{id=30016,NameZh='桌·清雅',Icon='item_30016',Type=911,MaxNum=99999,SellPrice=100,AdventureSort=10017,AdventureValue=44,AdventureReward={buffid={64000250},rewardid={3920}},Condition=4,ComposeID=130016,Desc='某个洁癖的少女每天都要把它打扫的整整齐齐，但是总会很快被黑猫弄乱。',Feature=1,}",
  [30017] = "{id=30017,NameZh='桌·微漾',Icon='item_30017',Type=911,MaxNum=99999,SellPrice=100,AdventureSort=10018,AdventureValue=44,AdventureReward={buffid={64000250},rewardid={3920}},Condition=4,ComposeID=130017,Desc='整洁干净的小桌子，不过使用了光洁的木料，黑猫经常抱怨这会让他的脚底打滑……',Feature=1,}",
  [30018] = "{id=30018,NameZh='书桌·黄梨木',Icon='item_30018',Type=904,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=10019,AdventureValue=65,AdventureReward={buffid={64000190},rewardid={3920}},Condition=4,ComposeID=130018,Desc='黄梨木制作成的纤细书桌，和它的主人十分相称。克拉拉经常在这里打发时间，一待就是一下午。',Feature=1,}",
  [30019] = "{id=30019,NameZh='壁纸·月下之森',Icon='item_30019',Type=946,MaxNum=99999,SellPrice=100,AdventureValue=0,Desc='小屋寂静卧在林中，月色朦胧间，窗内的灯火在唤她回家。',Feature=1,}",
  [30020] = "{id=30020,NameZh='天花板·夜雾凌晨',Icon='item_30020',Type=949,MaxNum=99999,SellPrice=100,AdventureValue=0,Desc='月色流淌在森林里，点点萤火透着微光。寂静之间，只有黑猫领着她寻找回家的路。',Feature=1,}",
  [30021] = "{id=30021,NameZh='地面·迷梦森林',Icon='item_30021',Type=947,MaxNum=99999,SellPrice=100,AdventureValue=0,Desc='实木做成的地板，颜色与屋外的大地完美地融合在了一起。踩在上面会发出吱呀的声响，不由会令人放缓步伐。',Feature=1,}",
  [30022] = "{id=30022,NameZh='楼梯·徘徊',Icon='item_30022',Type=948,MaxNum=99999,SellPrice=100,AdventureValue=0,Desc='钟声响起，午夜时分来临。她停留在此处不肯离去，等待着魔法的消逝。',Feature=1,}",
  [30023] = "{id=30023,NameZh='门·轻扉',Icon='item_30023',Type=950,MaxNum=99999,SellPrice=100,AdventureValue=0,Desc='造型简洁的木质小门，朴素中不失利落的气息。',Feature=1,}",
  [30100] = "{id=30100,NameZh='床·枕梦子',Icon='item_30100',Type=905,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=11001,AdventureValue=125,AdventureReward={buffid={64000030},rewardid={3920}},Condition=4,ComposeID=130100,Desc='用美梦编织出的被褥，枕上就会得到一夜好眠。',Feature=1,}",
  [30101] = "{id=30101,NameZh='窗·照夜',Icon='item_30101',Type=908,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=11002,AdventureValue=45,AdventureReward={buffid={64000370},rewardid={3920}},Condition=4,ComposeID=130101,Desc='倚窗凭栏处，照影夜归人。',Feature=1,}",
  [30102] = "{id=30102,NameZh='衣橱·绀夜',Icon='item_30102',Type=907,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=11003,AdventureValue=69,AdventureReward={buffid={64000030},rewardid={3920}},Condition=4,ComposeID=130102,Desc='充满日式风情的衣橱，由黄木制成。简洁大方的外表下，在保证足够空间的同时又不失巧思。',Feature=1,}",
  [30103] = "{id=30103,NameZh='床头柜·盎然',Icon='item_30103',Type=936,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=11004,AdventureValue=25,AdventureReward={buffid={64000040},rewardid={3920}},Condition=4,ComposeID=130103,Desc='有了温馨的绿植点缀，让空气多了一丝自然的宁静。',Feature=1,}",
  [30104] = "{id=30104,NameZh='储物柜·藏心',Icon='item_30104',Type=910,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=11005,AdventureValue=56,AdventureReward={buffid={64000030},rewardid={3920}},Condition=4,ComposeID=130104,Desc='看起来就深不可测的储物柜。横竖纵斜之间，它到底隐藏了多少秘密呢？',Feature=1,}",
  [30105] = "{id=30105,NameZh='餐桌·日食录',Icon='item_30105',Type=945,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=11006,AdventureValue=75,AdventureReward={buffid={64000180},rewardid={3920}},Condition=4,ComposeID=130105,Desc='精致优雅的日式餐桌，好像在这里用餐，整个人的心情都会平和许多。',Feature=1,}",
