  [30318] = "{id=30318,NameZh='旅行者浴缸',Icon='item_30318',Type=917,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=13019,AdventureValue=70,AdventureReward={buffid={64000090},rewardid={3920}},Condition=4,ComposeID=130318,Desc='就算身在异国他乡的列车上，只要有旅行浴缸便能随时享受泡澡的惬意时光！',Feature=1,}",
  [30319] = "{id=30319,NameZh='屏风·流星之夜',Icon='item_30319',Type=939,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=13020,AdventureValue=63,AdventureReward={buffid={64000180},rewardid={3920}},Condition=4,ComposeID=130319,Desc='让星星守护你在这里的每一个梦吧。',Feature=1,}",
  [30320] = "{id=30320,NameZh='壁纸·温热',Icon='item_30320',Type=946,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=13021,AdventureValue=15,AdventureReward={buffid={64000290},rewardid={3920}},Condition=64,ComposeID=130320,Desc='有了它，整个房间都流露着梅尔区那股温热的人情味。',Feature=1,}",
  [30321] = "{id=30321,NameZh='天花板·温情',Icon='item_30321',Type=949,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=13022,AdventureValue=15,AdventureReward={buffid={64000290},rewardid={3920}},Condition=64,ComposeID=130321,Desc='躺在床上抬头的时候，灯影绰绰中尽显温情。',Feature=1,}",
  [30322] = "{id=30322,NameZh='地面·温馨',Icon='item_30322',Type=947,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=13023,AdventureValue=15,AdventureReward={buffid={64000390},rewardid={3920}},Condition=64,ComposeID=130322,Desc='充满温情的设计，赤脚踩上去也很舒服。',Feature=1,}",
  [30323] = "{id=30323,NameZh='梅尔阶梯',Icon='item_30323',Type=948,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=13024,AdventureValue=15,AdventureReward={buffid={64000390},rewardid={3920}},Condition=64,ComposeID=130323,Desc='独具梅尔区风格的老式楼梯，作为楼梯，结实安全才是本分！',Feature=1,}",
  [30324] = "{id=30324,NameZh='星空门扉',Icon='item_30324',Type=950,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=13025,AdventureValue=15,AdventureReward={buffid={64000290},rewardid={3920}},Condition=64,ComposeID=130324,Desc='打开它吧，送你一片最温暖的星光。',Feature=1,}",
  [30325] = "{id=30325,NameZh='床头柜·暖夜',Icon='item_30325',Type=936,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=13026,AdventureValue=25,AdventureReward={buffid={64000040},rewardid={3920}},Condition=4,ComposeID=130325,Desc='在疲惫的夜晚，这道温暖总会在枕边陪伴着你入眠。',Feature=1,}",
  [30326] = "{id=30326,NameZh='书架·繁星',Icon='item_30326',Type=938,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=13027,AdventureValue=45,AdventureReward={buffid={64000240},rewardid={3920}},Condition=4,ComposeID=130326,Desc='这一本本书如同天上的繁星，你永远也数不清、读不完。',Feature=1,}",
  [30400] = "{id=30400,NameZh='沙发·天鹅绒之吻',Icon='item_30400',Type=901,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=14001,AdventureValue=50,AdventureReward={buffid={64000190},rewardid={3920}},Condition=4,ComposeID=130400,Desc='使用天鹅绒制成的高级沙发，大气的古褐色，尽显华贵！',Feature=1,}",
  [30401] = "{id=30401,NameZh='沙发·慵懒午后',Icon='item_30401',Type=901,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=14002,AdventureValue=50,AdventureReward={buffid={64000190},rewardid={3920}},Condition=4,ComposeID=130401,Desc='使用天鹅绒制成的高级沙发，舒适可爱，可以随时搬到庭院里晒太阳！',Feature=1,}",
  [30402] = "{id=30402,NameZh='沙发·绅士的优雅',Icon='item_30402',Type=901,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=14003,AdventureValue=63,AdventureReward={buffid={64000180},rewardid={3920}},Condition=4,ComposeID=130402,Desc='高贵典雅的天鹅绒沙发，纯金的镶边显示出主人不凡的身份。',Feature=1,}",
  [30403] = "{id=30403,NameZh='壁炉·鎏金闪耀',Icon='item_30403',Type=902,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=14004,AdventureValue=69,AdventureReward={buffid={64000230},rewardid={3920}},Condition=4,ComposeID=130403,Desc='将柴火投入这座设计精绝的壁炉，温热耀眼的火光中如同有黄金融于其中。',Feature=1,}",
  [30404] = "{id=30404,NameZh='地毯·丝质奢华',Icon='item_30404',Type=903,MaxNum=99999,SellPrice=100,AdventureSort=14005,AdventureValue=20,AdventureReward={buffid={64000400},rewardid={3920}},Condition=4,ComposeID=130404,Desc='这张地毯由纯金丝编织而成的……有钱真好啊（小声）。',Feature=1,}",
  [30405] = "{id=30405,NameZh='地毯·金丝幻想',Icon='item_30405',Type=903,MaxNum=99999,SellPrice=100,AdventureSort=14006,AdventureValue=20,AdventureReward={buffid={64000400},rewardid={3920}},Condition=4,ComposeID=130405,Desc='贝勒区的天鹅绒夫人耗时半年才制作而成的地毯，是身份和地位的绝对象征！',Feature=1,}",
  [30406] = "{id=30406,NameZh='地毯·波斯迷梦',Icon='item_30406',Type=903,MaxNum=99999,SellPrice=100,ComposeID=130406,Desc='精致的波斯工艺地毯，上面的刺绣似乎有某种魔力，长期盯着看会让人陷入沉睡。',Feature=1,}",
  [30407] = "{id=30407,NameZh='地毯·柔软金绒',Icon='item_30407',Type=903,MaxNum=99999,SellPrice=100,ComposeID=130407,Desc='据购置这张地毯的人口述，要在天鹅绒夫人那里足足排队三个月才能得到它。',Feature=1,}",
  [30408] = "{id=30408,NameZh='桌·沉夜',Icon='item_30408',Type=904,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=14009,AdventureValue=65,AdventureReward={buffid={64000190},rewardid={3920}},Condition=4,ComposeID=130408,Desc='据说是被贝勒区以前的贵族们用过的书桌。仅仅是远看一眼，便令人感到肃穆。',Feature=1,}",
  [30409] = "{id=30409,NameZh='床·贝勒海姆',Icon='item_30409',Type=905,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=14010,AdventureValue=150,AdventureReward={buffid={64000020},rewardid={3920}},Condition=4,ComposeID=130409,Desc='贝勒区的富人们用神域的词缀来命名的豪华大床，梦幻般的舒适度的确对得起这个傲慢的称呼。',Feature=1,}",
  [30410] = "{id=30410,NameZh='椅·小憩',Icon='item_30410',Type=906,MaxNum=99999,SellPrice=100,AdventureSort=14011,AdventureValue=16,AdventureReward={buffid={64000200},rewardid={3920}},Condition=4,ComposeID=130410,Desc='舒适度与精巧度都很高的椅子，坐在上面太久不动的话会睡着哦。',Feature=1,}",
  [30411] = "{id=30411,NameZh='衣橱·红枫金叶',Icon='item_30411',Type=907,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=14012,AdventureValue=55,AdventureReward={buffid={64000040},rewardid={3920}},Condition=4,ComposeID=130411,Desc='时尚女王莱德莉安的衣橱，可能是衣服装的太多，经常会发出奇怪的响声……',Feature=1,}",
  [30412] = "{id=30412,NameZh='窗·远眺之息',Icon='item_30412',Type=908,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=14013,AdventureValue=30,AdventureReward={buffid={64000390},rewardid={3920}},Condition=4,ComposeID=130412,Desc='用纯金做的窗台，从这里眺望的话，也许看到的风景也会更远一些？',Feature=1,}",
  [30413] = "{id=30413,NameZh='壁灯·夜曲',Icon='item_30413',Type=909,MaxNum=99999,SellPrice=100,AdventureSort=14014,AdventureValue=16,AdventureReward={buffid={64000250},rewardid={3920}},Condition=4,ComposeID=130413,Desc='一步，两步，是谁在灯下翩翩起舞？烛火摇曳，夜幕降临。',Feature=1,}",
  [30414] = "{id=30414,NameZh='储物柜·男爵酒柜',Icon='item_30414',Type=910,MaxNum=99999,SellPrice=100,AdventureSort=14015,AdventureValue=36,AdventureReward={buffid={64000050},rewardid={3920}},Condition=4,ComposeID=130414,Desc='常见于贝勒区贵族家庭的大型酒柜，用来装他们名贵的藏酒，一个酒柜远远不够。',Feature=1,}",
  [30415] = "{id=30415,NameZh='矮柜·珍宝之匣',Icon='item_30415',Type=937,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=14016,AdventureValue=25,AdventureReward={buffid={64000040},rewardid={3920}},Condition=4,ComposeID=130415,Desc='本来以为是贝勒区的贵族们戏称它为“宝物匣”，实际上富人的确需要好几个大橱柜来装他们的首饰......',Feature=1,}",
  [30416] = "{id=30416,NameZh='桌·星光晚宴',Icon='item_30416',Type=945,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=14017,AdventureValue=75,AdventureReward={buffid={64000180},rewardid={3920}},Condition=4,ComposeID=130416,Desc='夜色渐深，烛台点亮，主客入座，宴会的时间到了。“尊敬的客人，您看着杯红酒如何？我向您保证，绝不是什么可疑的东西哦……”',Feature=1,}",
  [30417] = "{id=30417,NameZh='壁画·奢华回忆',Icon='item_30417',Type=942,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=14018,AdventureValue=45,AdventureReward={buffid={64000190},rewardid={3920}},Condition=4,ComposeID=130417,Desc='只有最奢华的壁画才配得上最珍贵的回忆。',Feature=1,}",
  [30418] = "{id=30418,NameZh='钢琴·黄金缪斯',Icon='item_30418',Type=922,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=14019,AdventureValue=40,AdventureReward={buffid={64000140},rewardid={3920}},Condition=4,ComposeID=130418,Desc='这架奢华的钢琴，就像一位身着盛装的缪斯女神，带着闪耀的微笑，为你歌唱。',Feature=1,}",
  [30419] = "{id=30419,NameZh='至尊金桶',Icon='item_30419',Type=922,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=14020,AdventureValue=50,AdventureReward={buffid={64000130},rewardid={3920}},Condition=4,ComposeID=130419,Desc='百分之百纯金（包括厕纸！），只为了满足你那高贵的屁股！',Feature=1,}",
  [30420] = "{id=30420,NameZh='屏风·赤金交叠',Icon='item_30420',Type=939,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=14021,AdventureValue=50,AdventureReward={buffid={64000190},rewardid={3920}},Condition=4,ComposeID=130420,Desc='红丝绒夫人找遍了贝勒区所有的商店，终于用上好的红枫木和金漆做出了这面屏风。',Feature=1,}",
  [30421] = "{id=30421,NameZh='壁纸·筑梦',Icon='item_30421',Type=946,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=14022,AdventureValue=15,AdventureReward={buffid={64000290},rewardid={3920}},Condition=64,ComposeID=130421,Desc='每一块砖瓦的背后都有一颗星星。它们被埋在此处，记录着每一个夜晚与晨曦。',Feature=1,}",
  [30422] = "{id=30422,NameZh='天花板·沉星',Icon='item_30422',Type=949,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=14023,AdventureValue=15,AdventureReward={buffid={64000290},rewardid={3920}},Condition=64,ComposeID=130422,Desc='比起遮风挡雨，贝勒区的有钱人更在意它能装上多少个钻石吊灯。',Feature=1,}",
  [30423] = "{id=30423,NameZh='地面·寂夜',Icon='item_30423',Type=947,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=14024,AdventureValue=15,AdventureReward={buffid={64000390},rewardid={3920}},Condition=64,ComposeID=130423,Desc='砖瓦诉说着年轮的故事，踏在这里，仿佛已走过了漫长的百年。',Feature=1,}",
  [30424] = "{id=30424,NameZh='楼梯·辉煌回旋',Icon='item_30424',Type=948,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=14025,AdventureValue=15,AdventureReward={buffid={64000390},rewardid={3920}},Condition=64,ComposeID=130424,Desc='滴答、滴答，每逢夜晚，楼梯上便会响起轻柔的脚步，与一声温柔的叹息。',Feature=1,}",
  [30425] = "{id=30425,NameZh='门·岁月回响',Icon='item_30425',Type=950,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=14026,AdventureValue=15,AdventureReward={buffid={64000290},rewardid={3920}},Condition=64,ComposeID=130425,Desc='厚重的大门掩盖了时光，轻轻推开，是岁月发出的回响。',Feature=1,}",
  [30426] = "{id=30426,NameZh='书架·浩瀚书海',Icon='item_30426',Type=938,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=14027,AdventureValue=45,AdventureReward={buffid={64000240},rewardid={3920}},Condition=4,ComposeID=130426,Desc='这里的书虽然很多，但是那些贵族们都是不会读的……',Feature=1,}",
  [30427] = "{id=30427,NameZh='床头柜·迷迭红木',Icon='item_30427',Type=936,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=14028,AdventureValue=25,AdventureReward={buffid={64000040},rewardid={3920}},Condition=4,ComposeID=130427,Desc='用红木精雕细琢制成的床头柜，每一寸都显示着无以伦比的奢华。',Feature=1,}",
  [30500] = "{id=30500,NameZh='壁纸·清凉海风',Icon='item_30500',Type=946,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15001,AdventureValue=1,AdventureReward={buffid={64000510}},Condition=64,Desc='微风拂面，碧海蓝天，沙滩是你与我的初遇地点，阳光下的你嫣然的微笑永远被我记在心间。',Feature=1,}",
  [30501] = "{id=30501,NameZh='瀚海星梯',Icon='item_30501',Type=948,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15002,AdventureValue=1,AdventureReward={buffid={64000510}},Condition=64,Desc='想知道通往深海的道路么？在月圆之夜，拿出号角在礁石边吹响，你会发现海水仿佛有指引般的分开，随后水中会出现一条通往星梯，那就是通往深海的阶梯。',Feature=1,}",
  [30502] = "{id=30502,NameZh='星海之门',Icon='item_30502',Type=950,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15003,AdventureValue=1,AdventureReward={buffid={64000520}},Condition=64,Desc='母亲问着小男孩“你喜欢这里么？”小男孩眨着亮晶晶的眼睛看着门外的世界说道 “喜欢！这里有海马，水母，还有人鱼！我喜欢这里妈妈”“那你以后一定要像你爸爸一样成为优秀的海军，这样你就可以永远守护这里了!”“嗯！”小男孩用力的点了点头。',Feature=1,}",
  [30503] = "{id=30503,NameZh='海之陆',Icon='item_30503',Type=947,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15004,AdventureValue=1,AdventureReward={buffid={64000520}},Condition=64,Desc='沙滩和白云，浪花与飞鸟，我与你，我愿和我所爱的你一同沉溺在这深海里。',Feature=1,}",
  [30504] = "{id=30504,NameZh='海之空',Icon='item_30504',Type=949,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15005,AdventureValue=1,AdventureReward={buffid={64000530}},Condition=64,Desc='海与空的距离隔之千里，我与你的距离亦如此，但是无论相离多远，我都会跟随心的指引找到你。',Feature=1,}",
  [30505] = "{id=30505,NameZh='提灯照星海',Icon='item_30505',Type=909,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15006,AdventureValue=1,AdventureReward={buffid={64000570}},Condition=8,Desc='一望无际的深海让人到畏惧，在那深海之下埋藏着无尽的秘密，想要去探索，请带上我一起，让我为你照亮星海中的道路。',Feature=1,}",
  [30506] = "{id=30506,NameZh='蔚蓝星椅',Icon='item_30506',Type=906,MaxNum=99999,SellPrice=100,AdventureSort=15007,AdventureValue=1,AdventureReward={buffid={64000540}},Condition=8,Desc='星月交织，透过蔚蓝的大海，我看到了远方的你。',Feature=1,}",
  [30507] = "{id=30507,NameZh='鲨口夺食',Icon='item_30507',Type=945,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=15008,AdventureValue=1,AdventureReward={buffid={64000230}},Condition=8,Desc='深海中，无论是多么轻微的血腥味都逃不过巨齿鲨的鼻子，它们是古老而强大的种族，敢在它们的口中夺取食物，冒险者，看样子你胆子不小嘛！',Feature=1,}",
  [30508] = "{id=30508,NameZh='白浪飞鱼',Icon='item_30508',Type=951,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15009,AdventureValue=1,AdventureReward={buffid={64000050}},Condition=8,Desc='磅礴无边的大海，暗藏着无数的危险，想要在这片海域立足，就要征服这片大海，拿好的你的飞鱼板，待白浪翻涌，请你迎风而上直冲云霄',Feature=1,}",
  [30509] = "{id=30509,NameZh='章鱼铺子',Icon='item_30509',Type=952,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=15010,AdventureValue=1,AdventureReward={buffid={64000430}},Condition=8,Desc='“啊唔…唔…好吃”“唔嘛…还没吃够！”“嗝~再吃一口，这根本停不下来嘛！”“喂喂喂！你可不要全吃掉！章鱼先生烤的东西那么好吃！给我留一口！我也想吃！！！”',Feature=1,}",
  [30510] = "{id=30510,NameZh='前进波利号',Icon='item_30510',Type=940,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=15011,AdventureValue=1,AdventureReward={buffid={64000420}},Condition=8,Desc='扬帆，起航，前进波利号带着你一起乘风破浪出海啦。海风轻轻吹，船儿慢慢摇，不要急，海中的大秘宝就在那里等着你呦。',Feature=1,}",
  [30511] = "{id=30511,NameZh='沙海城堡',Icon='item_30511',Type=922,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15012,AdventureValue=1,AdventureReward={buffid={64000050}},Condition=8,Desc='妈妈说，作为一只优秀的海螺一定要有一座自己的城堡！嘿咻！嘿咻！我要在城堡顶搭一只超可爱的波利！嗯~~城堡的门还要再扩大一点，这边，还有这边，都要搭的结实一点，嘿嘿，有了华丽的城堡，海螺妹妹就会和我一起玩了！',Feature=1,}",
  [30512] = "{id=30512,NameZh='小企与阿豹',Icon='item_30512',Type=941,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15013,AdventureValue=1,AdventureReward={buffid={64000580}},Condition=8,Desc='“呐，阿豹，我们是不是会永远在一起啊~呼呼~”“永远？永远是多远啊，小企”“永远啊，就是太阳升起时我们在一起，月亮出现时我们还在一起，就是星星闪耀时，我们在一起，就是……哎？阿豹，你怎么把眼睛闭上了”“这个问题好麻烦啊，我只要现在能和你在一起就足够了啦~”',Feature=1,}",
  [30513] = "{id=30513,NameZh='云海浪歌',Icon='item_6606',Type=30,Quality=4,MaxNum=99999,SellPrice=100,Desc='晴空万里，碧海蓝天，浪花欢快的翻滚着，沙滩上满是晶莹细小的沙子，孩子们光着脚丫踩在在上尽情奔跑，海水冲刷到孩子们的脚上带来一丝丝凉爽和舒适，欢声笑语和潮汐海声相互交织构成了一首夏天的歌。',Feature=1,}",
  [30520] = "{id=30520,NameZh='床·椰风耳语',Icon='item_30520',Type=905,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=15014,AdventureValue=1,AdventureReward={buffid={64000430}},Condition=8,Desc='床柱是最喜阳光的蝶黄椰子树，床布是绣满海洋图腾的船帆布,只要躺在上面微微晃动，就能以最接近大海的姿态安然入眠！如果你不适应这样的特殊小床，也可以抬头思考一下椰子是否会掉下来的问题，会不会让你灵光一闪悟出什么定律？而真实的答案就是……你会真的安然入眠！！',Feature=1,}",
  [30521] = "{id=30521,NameZh='床头柜·椰椰岛',Icon='item_30521',Type=936,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15015,AdventureValue=1,AdventureReward={buffid={64000040}},Condition=8,Desc='传说每一棵椰子树下都有一个小秘密，何况是就在你枕边的椰椰岛？把你最羞羞的秘密都藏到小岛之下，海蓝之中，天知海知、你知……吼吼，还有椰子知哦！',Feature=1,}",
  [30522] = "{id=30522,NameZh='矮柜·鲨鳍之夏',Icon='item_30522',Type=937,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15016,AdventureValue=1,AdventureReward={buffid={64000510}},Condition=8,Desc='海洋中最不愿看见的就是那扇向你直冲而来的鲨鱼鳍，不过放心啦~这扇沙滩色的鲨鱼鳍之下空间满满，可以把你的冲浪设备都放进去沾沾“鲨气”哦，或许明天你就能成为征服海浪的踏浪之王！',Feature=1,}",
  [30523] = "{id=30523,NameZh='沙发·阿莎的温柔',Icon='item_30523',Type=901,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=15017,AdventureValue=1,AdventureReward={buffid={64000180}},Condition=8,Desc='阿莎很少会在别人面前将自己最温柔的一面展露出来，为此连尖锐的牙齿都打磨成了云朵的模样，在这里小憩一会，眼睛一闭一睁~阿莎向你保证——绝对不会偷偷亲吻你哟！',Feature=1,}",
  [30524] = "{id=30524,NameZh='窗户·星海之潮',Icon='item_30524',Type=908,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15018,AdventureValue=1,AdventureReward={buffid={64000480}},Condition=8,Desc='克魔岛可不只有阳光和沙滩，当明月升起时请将帘布系上，拂面而来的海潮之风，随浪传来的星云呢喃……你会陪我一起推开这扇心扉吗？',Feature=1,}",
  [30525] = "{id=30525,NameZh='躺椅·蔽日蓝鲸',Icon='item_30525',Type=906,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15019,AdventureValue=1,AdventureReward={buffid={64000490}},Condition=8,Desc='犹如躺在鲸鱼背脊，却又不受烈日灼烤，放眼——晨风照面，舒爽怡人；闭目——海味入鼻，直动心灵。还在犹豫什么，赶紧躺下歇歇吧！',Feature=1,}",
  [30526] = "{id=30526,NameZh='水族箱·巨蟹双鱼之家',Icon='item_30526',Type=922,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15020,AdventureValue=1,AdventureReward={buffid={64000570}},Condition=8,Desc='充满精神默契的海洋小屋里生活着双鱼多多、莉莉还有羞涩的小蟹仔，如果你仔细观察，这里每天都会上演感人的爱情文艺片……或许以后还会有苦情婆媳片……霸道总裁片……打住！还是先揉揉眼睛吧……',Feature=1,}",
  [30527] = "{id=30527,NameZh='喷泉·乌克之吻',Icon='item_30527',Type=928,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15021,AdventureValue=1,AdventureReward={buffid={64000580}},Condition=8,Desc='海马乌克是海难水手的向导，时常引导他们度过海上的漩涡，因此以海马乌克设计的喷泉象征着幸运、希望不灭。',Feature=1,}",
  [30528] = "{id=30528,NameZh='波利沙排冠军赛',Icon='item_30528',Type=951,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=15022,AdventureValue=1,AdventureReward={buffid={64000420}},Condition=8,Desc='波利们在沙滩上最爱的竞技运动，没有之一。发球！接球！托球！扣球！真好奇波们利真能做出那么复杂的动作？这个问题嘛……据说上一个在赛场旁思考这个问题的人已经被排球击晕了……（比分落后的波利好可怕的说~~）',Feature=1,}",
  [30529] = "{id=30529,NameZh='壁画·午后湾',Icon='item_30529',Type=942,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15023,AdventureValue=1,AdventureReward={buffid={64000520}},Condition=8,Desc='美丽的温暖海湾，望着它便会想起心中最爱之人。',Feature=1,}",
  [30530] = "{id=30530,NameZh='椰林鲨语',Icon='item_3863',Type=30,Quality=4,MaxNum=99999,SellPrice=100,Desc='我是海中的王者巨齿鲨，可是，我却对一种陆地上的食物产生了兴趣，可恶到底怎么才能弄到那个圆滚滚的椰子啊！章鱼先生帮帮忙啊！打开后获得床·椰风耳语*1、床头柜·椰椰岛*2、矮柜·鲨鳍之夏*1、鲨口夺食*1、章鱼铺子*1',Feature=1,}",
  [30531] = "{id=30531,NameZh='大梦想家',Icon='item_3864',Type=30,Quality=4,MaxNum=99999,SellPrice=100,Desc='我要成为优秀的冲浪手！”“我要成为排球冠军！”“我要成为英勇的海军！”“我…我…我只想和喜欢的人静静的待在一起。”使用后获得白浪飞鱼*1、小企与阿豹*1、波利沙排冠军赛*1、窗户·星海之潮*2',Feature=1,}",
  [30532] = "{id=30532,NameZh='琉克的藏品室',Icon='item_3865',Type=30,Quality=4,MaxNum=99999,SellPrice=100,Desc='大收藏家琉克在出海的时候遇到了一生挚爱，此后他便建造了这个藏品室，里面装满了他与爱人的所有回忆。使用后获得前进波利号*1、沙海城堡*1、喷泉·乌克之吻*1、壁画·午后湾*1、水族箱·巨蟹双鱼之家*1',Feature=1,}",
  [30533] = "{id=30533,NameZh='蓝鲸宝藏',Icon='item_3867',Type=30,Quality=4,MaxNum=99999,SellPrice=100,Desc='鲸鱼阿莎已经在深海中生活了数千年，见证了深海中所有的悲欢离合，时间会冲淡一切，只有这些遗留的物品会成为那些事物存在的证明。使用后蔚蓝星椅*2、躺椅·蔽日蓝鲸*1、沙发·阿莎的温柔*1、提灯照星海*4',Feature=1,}",
  [30604] = "{id=30604,NameZh='裁决骑士雕像',Icon='item_30604',Type=922,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=81017,AdventureValue=20,AdventureReward={buffid={64000180}},Condition=8,Desc='“我的利剑放在这里。我当牢记谦卑，怜悯，公正，荣誉，牺牲，英勇，灵性，诚实的美德。”捍卫正义，对抗邪恶，这是裁决骑士的信念。',Feature=1,}",
  [30612] = "{id=30612,NameZh='守护骑士雕像',Icon='item_30612',Type=922,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=81018,AdventureValue=20,AdventureReward={buffid={64000230}},Condition=8,Desc='“我的盾牌放在这里。我当牢记谦卑，怜悯，公正，荣誉，牺牲，英勇，灵性，诚实的美德。”怜悯弱者，守护良善，这是守护骑士的信念。',Feature=1,}",
  [30700] = "{id=30700,NameZh='学园榻榻米·朱古力',Icon='item_30700',Type=947,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15101,AdventureValue=15,AdventureReward={buffid={64000390},rewardid={3920}},Condition=64,ComposeID=130700,Desc='长得像巧克力板的榻榻米，踩起来十分柔软，能够消除疲劳。',Feature=1,}",
  [30701] = "{id=30701,NameZh='学园墙壁·青涩回忆',Icon='item_30701',Type=946,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15102,AdventureValue=15,AdventureReward={buffid={64000290},rewardid={3920}},Condition=64,ComposeID=130701,Desc='主打青春回忆的主题墙壁，让人回忆起曾经的校园生活。',Feature=1,}",
  [30702] = "{id=30702,NameZh='学园天花板·朝阳',Icon='item_30702',Type=949,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15103,AdventureValue=15,AdventureReward={buffid={64000290},rewardid={3920}},Condition=64,ComposeID=130702,Desc='色调温暖的天花板，见证了一届又一届学员们的成长。',Feature=1,}",
  [30703] = "{id=30703,NameZh='可怜兮兮的门',Icon='item_30703',Type=950,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15104,AdventureValue=15,AdventureReward={buffid={64000290},rewardid={3920}},Condition=64,ComposeID=130703,Desc='为学员们常年遮风避雨的木门，却在毕业的那一天遭受了非人的待遇。',Feature=1,}",
  [30704] = "{id=30704,NameZh='书途阶梯',Icon='item_30704',Type=948,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15105,AdventureValue=15,AdventureReward={buffid={64000390},rewardid={3920}},Condition=64,ComposeID=130704,Desc='在学园图书馆等地方常见的楼梯，禁止追逐打闹！',Feature=1,}",
  [30705] = "{id=30705,NameZh='优等生课桌',Icon='item_30705',Type=904,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15106,AdventureValue=65,AdventureReward={buffid={64000190},rewardid={3920}},Condition=4,ComposeID=130705,Desc='干净、整洁的课桌，看来他的主人是一位优等生，可是为什么一本书都没有呢...',Feature=1,}",
  [30706] = "{id=30706,NameZh='落寞讲台',Icon='item_30706',Type=904,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15107,AdventureValue=81,AdventureReward={buffid={64000080},rewardid={3920}},Condition=4,ComposeID=130706,Desc='入学后从来没有发挥过作用，只被当作涂鸦板的可怜讲台。',Feature=1,}",
  [30707] = "{id=30707,NameZh='回忆黑板',Icon='item_30707',Type=942,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15108,AdventureValue=45,AdventureReward={buffid={64000340},rewardid={3920}},Condition=4,ComposeID=130707,Desc='虽然面积不大，但记录了学园生活的点点滴滴，是学员们最熟悉的陌生人。',Feature=1,}",
  [30708] = "{id=30708,NameZh='吸引眼球的时钟',Icon='item_30708',Type=942,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15109,AdventureValue=45,AdventureReward={buffid={64000340},rewardid={3920}},Condition=4,ComposeID=130708,Desc='最近的一项研究发现，只要在教室中挂上一块时钟，所有学员的目光都会被其吸引。',Feature=1,}",
  [30709] = "{id=30709,NameZh='腰椎毁灭者',Icon='item_30709',Type=906,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15110,AdventureValue=20,AdventureReward={buffid={64000190},rewardid={3920}},Condition=4,ComposeID=130709,Desc='真正毁灭腰椎的不是这把无辜的椅子，而是学员堕落的生活习惯！',Feature=1,}",
  [30710] = "{id=30710,NameZh='违禁品收纳柜',Icon='item_30710',Type=910,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15111,AdventureValue=45,AdventureReward={buffid={64000190},rewardid={3920}},Condition=4,ComposeID=130710,Desc='只要被认定为“违禁”之物，那么必然无法逃脱被关入其中的命运。',Feature=1,}",
  [30711] = "{id=30711,NameZh='班级护卫',Icon='item_30711',Type=953,MaxNum=99999,SellPrice=100,AdventureSort=15112,AdventureValue=10,AdventureReward={buffid={64000300},rewardid={3920}},Condition=4,ComposeID=130711,Desc='默默守护班级的扫帚，平常清洁卫生，偶尔被抡起来当作武器。',Feature=1,}",
  [30712] = "{id=30712,NameZh='泡泡水壶',Icon='item_30712',Type=953,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15113,AdventureValue=12,AdventureReward={buffid={64000290},rewardid={3920}},Condition=4,ComposeID=130712,Desc='负责浇花的值日生迷上涂鸦后，它就变得五颜六色了起来。',Feature=1,}",
  [30713] = "{id=30713,NameZh='超精准红外探测仪',Icon='item_30713',Type=922,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15114,AdventureValue=50,AdventureReward={buffid={64000130},rewardid={3920}},Condition=4,ComposeID=130713,Desc='本来是学园的下课铃，后来被改造成侦察班主任动向的探测仪。',Feature=1,}",
  [30714] = "{id=30714,NameZh='知心哥哥木桩',Icon='item_30714',Type=927,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15115,AdventureValue=60,AdventureReward={buffid={64000240},rewardid={3920}},Condition=4,ComposeID=130714,Desc='学园中人气很高的大哥哥，温柔地接纳你所有的负面情绪。',Feature=1,}",
  [30715] = "{id=30715,NameZh='教导主任的画像',Icon='item_30715',Type=942,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15116,AdventureValue=45,AdventureReward={buffid={64000340},rewardid={3920}},Condition=4,ComposeID=130715,Desc='虽然本人不怎么受学员欢迎，但他的画像意外拥有与知心哥哥不相上下的人气。',Feature=1,}",
  [30716] = "{id=30716,NameZh='永久缺席画像',Icon='item_30716',Type=942,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15117,AdventureValue=45,AdventureReward={buffid={64000340},rewardid={3920}},Condition=4,ComposeID=130716,Desc='学园七大不可思议之一，出现在画像上的人必定会缺席毕业典礼。',Feature=1,}",
  [30717] = "{id=30717,NameZh='神秘转学生的课桌',Icon='item_30717',Type=904,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15118,AdventureValue=81,AdventureReward={buffid={64000130},rewardid={3920}},Condition=4,ComposeID=130717,Desc='在第二学期突然转学过来的神秘人物用的课桌，至今没人见过它的主人。',Feature=1,}",
  [30718] = "{id=30718,NameZh='番长杂物柜',Icon='item_30718',Type=937,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15119,AdventureValue=25,AdventureReward={buffid={64000190},rewardid={3920}},Condition=4,ComposeID=130718,Desc='学园最强不良生的储物柜，总是塞满了情书和挑战书。',Feature=1,}",
  [30719] = "{id=30719,NameZh='寂寞的课桌',Icon='item_30719',Type=904,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15120,AdventureValue=65,AdventureReward={buffid={64000190},rewardid={3920}},Condition=4,ComposeID=130719,Desc='虽然学员们总是不爱惜课桌，但在假期时它总会想念那些年轻的主人。',Feature=1,}",
  [30720] = "{id=30720,NameZh='学园情报交流中心',Icon='item_30720',Type=942,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15121,AdventureValue=45,AdventureReward={buffid={64000340},rewardid={3920}},Condition=4,ComposeID=130720,Desc='不论有多少消息都能写得下的神奇便签板。',Feature=1,}",
  [30721] = "{id=30721,NameZh='自由牢笼',Icon='item_30721',Type=908,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15122,AdventureValue=50,AdventureReward={buffid={64000190},rewardid={3920}},Condition=4,ComposeID=130721,Desc='“隔着这扇窗户看向外面，感觉自己就像被锁在这学园的囚徒。”',Feature=1,}",
  [30722] = "{id=30722,NameZh='大嗓门叭叭',Icon='item_30722',Type=916,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15123,AdventureValue=44,AdventureReward={buffid={64000130},rewardid={3920}},Condition=4,ComposeID=130722,Desc='教师讲课、不良生宣战、爱的告白都会麻烦这位大忙人，导致它最近一直在寻找喉宝片。',Feature=1,}",
  [30723] = "{id=30723,NameZh='无上荣誉奖状',Icon='item_30723',Type=942,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15124,AdventureValue=56,AdventureReward={buffid={64000080},rewardid={3920}},Condition=4,ComposeID=130723,Desc='被教导主任视为学园最高荣誉的奖状，叠出的纸飞机比一般货色飞得更高。',Feature=1,}",
  [30724] = "{id=30724,NameZh='勇气垃圾桶',Icon='item_30724',Type=953,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15125,AdventureValue=12,AdventureReward={buffid={64000290},rewardid={3920}},Condition=4,ComposeID=130724,Desc='曾经那些未能传达的感情都被揉成一团丢了进去，或许叫缺乏勇气垃圾桶更合适...',Feature=1,}",
  [30800] = "{id=30800,NameZh='熊熊壁炉',Icon='item_30800',Type=902,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=15201,AdventureValue=83,AdventureReward={buffid={64000420}},Condition=8,Desc='温情提示，若是想在平安夜收到礼物，请不要点起炉火，还要保持烟囱卫生。',Feature=1,TFValidDate='2019-12-16 05:00:00',ValidDate='2019-12-23 05:00:00',}",
  [30801] = "{id=30801,NameZh='量产型圣诞树MKⅡ',Icon='item_30801',Type=933,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15202,AdventureValue=40,AdventureReward={buffid={64000190}},Condition=8,Desc='圣诞节时随处可见的、平平无奇的树，但是没有它就不能算一个完整的圣诞节！',Feature=1,TFValidDate='2019-12-16 05:00:00',ValidDate='2019-12-23 05:00:00',}",
  [30802] = "{id=30802,NameZh='圣诞霓虹树',Icon='item_30802',Type=933,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15203,AdventureValue=50,AdventureReward={buffid={64000580}},Condition=8,Desc='披灯挂彩，绚丽迷人，整个平安夜最靓的树，毫无疑问，今夜是属于它的舞台！',Feature=1,TFValidDate='2019-12-16 05:00:00',ValidDate='2019-12-23 05:00:00',}",
  [30803] = "{id=30803,NameZh='圣诞丢丢袜',Icon='item_30803',Type=942,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15204,AdventureValue=56,AdventureReward={buffid={64000240}},Condition=8,Desc='外表华贵的针织袜，但是不建议用来收取圣诞礼物，因为很容易就会弄丢。',Feature=1,TFValidDate='2019-12-16 05:00:00',ValidDate='2019-12-23 05:00:00',}",
  [30804] = "{id=30804,NameZh='波利利铃铛',Icon='item_30804',Type=942,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15205,AdventureValue=56,AdventureReward={buffid={64000040}},Condition=8,Desc='专为一个人过圣诞的孤独者量身打造的魔法铃铛，轻轻一摇就可以召唤出可爱的波利陪伴你。',Feature=1,TFValidDate='2019-12-16 05:00:00',ValidDate='2019-12-23 05:00:00',}",
  [30805] = "{id=30805,NameZh='驯鹿的凝视',Icon='item_30805',Type=942,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15206,AdventureValue=45,AdventureReward={buffid={64000190}},Condition=8,Desc='清晨，午夜，大雪中，阳光下，它时刻都在注视着你....别害怕，它只是在督促你成为一个好孩子。',Feature=1,TFValidDate='2019-12-16 05:00:00',ValidDate='2019-12-23 05:00:00',}",
  [30806] = "{id=30806,NameZh='驯鹿摇摇乐',Icon='item_30806',Type=941,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15207,AdventureValue=38,AdventureReward={buffid={64000580}},Condition=8,Desc='摇~摇~晃~摇~全杉木打造，百分之九十还原圣诞老人的坐骑，百分之八十还原坐骑的使用体验，拥有它你就拥有了快乐！',Feature=1,TFValidDate='2019-12-16 05:00:00',ValidDate='2019-12-23 05:00:00',}",
  [30807] = "{id=30807,NameZh='雪雪窗扉',Icon='item_30807',Type=908,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15208,AdventureValue=38,AdventureReward={buffid={64000380}},Condition=8,Desc='不论春夏秋冬，不论刮风下雨，透过这扇神奇的窗户都能看到美妙的雪景。',Feature=1,TFValidDate='2019-12-16 05:00:00',ValidDate='2019-12-23 05:00:00',}",
  [30808] = "{id=30808,NameZh='温暖的梦',Icon='item_30808',Type=905,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15209,AdventureValue=125,AdventureReward={buffid={64000570}},Condition=8,Desc='柔软、舒适、温暖，冬眠向往者的不二选择，但是还请别睡懒觉呦。',Feature=1,TFValidDate='2019-12-16 05:00:00',ValidDate='2019-12-23 05:00:00',}",
  [30809] = "{id=30809,NameZh='驯鹿号沙发',Icon='item_30809',Type=901,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15210,AdventureValue=63,AdventureReward={buffid={64000180}},Condition=8,Desc='圣诞老人最宝贝的雪橇——的后座，能让你在家中体验飞驰云霄、跨越星途的感觉。',Feature=1,TFValidDate='2019-12-16 05:00:00',ValidDate='2019-12-23 05:00:00',}",
  [30810] = "{id=30810,NameZh='老爷爷衣柜',Icon='item_30810',Type=907,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15211,AdventureValue=69,AdventureReward={buffid={64000040}},Condition=8,Desc='圣诞老人专用衣柜，没错，就像你想的那样，里面塞满了几十套相同的红棉袄。',Feature=1,TFValidDate='2019-12-16 05:00:00',ValidDate='2019-12-23 05:00:00',}",
  [30811] = "{id=30811,NameZh='便携式雪之家',Icon='item_30811',Type=922,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15212,AdventureValue=50,AdventureReward={buffid={64000230}},Condition=8,Desc='终年穿着大棉袄的圣诞老人很怕热，在温暖地带送礼物时他总会随身携带这颗水晶球。',Feature=1,TFValidDate='2019-12-16 05:00:00',ValidDate='2019-12-23 05:00:00',}",
  [30812] = "{id=30812,NameZh='好孩子名册',Icon='item_30812',Type=941,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15213,AdventureValue=38,AdventureReward={buffid={64000430}},Condition=8,Desc='当当当~详细记载了每个地区所有好孩子的名册！近年来名单在逐渐减少，圣诞老人为此很是发愁。',Feature=1,TFValidDate='2019-12-16 05:00:00',ValidDate='2019-12-23 05:00:00',}",
  [30813] = "{id=30813,NameZh='地毯·红玫雪绒花',Icon='item_30813',Type=903,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15214,AdventureValue=25,AdventureReward={buffid={64000390}},Condition=8,Desc='虽然织绘着冰雪的图案，但却非常温暖的一条地毯，光着脚踩起来很舒服。',Feature=1,TFValidDate='2019-12-16 05:00:00',ValidDate='2019-12-23 05:00:00',}",
  [30814] = "{id=30814,NameZh='地毯·绿茵金铃铛',Icon='item_30814',Type=903,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15215,AdventureValue=25,AdventureReward={buffid={64000390}},Condition=8,Desc='红绿配色在时尚界饱受非议，圣诞老人为抗议这种歧视而订做了这条地毯，其实还是挺好看的吧？',Feature=1,TFValidDate='2019-12-16 05:00:00',ValidDate='2019-12-23 05:00:00',}",
  [30815] = "{id=30815,NameZh='被冷落的圣诞树',Icon='item_30815',Type=933,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15216,AdventureValue=40,AdventureReward={buffid={64000240}},Condition=8,Desc='当家人欢聚在壁炉边，有一颗杉树在雪地中瑟瑟发抖，但它并不灰心...谁还不是一颗圣诞树了！',Feature=1,TFValidDate='2019-12-16 05:00:00',ValidDate='2019-12-23 05:00:00',}",
  [30816] = "{id=30816,NameZh='礼帽男孩',Icon='item_30816',Type=941,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15217,AdventureValue=38,AdventureReward={buffid={64000180}},Condition=8,Desc='要温度也要风度，这个小子的眼中不存在障碍，礼帽男孩出街啦！',Feature=1,TFValidDate='2019-12-16 05:00:00',ValidDate='2019-12-23 05:00:00',}",
  [30817] = "{id=30817,NameZh='蝴蝶结女孩',Icon='item_30817',Type=941,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15218,AdventureValue=38,AdventureReward={buffid={64000230}},Condition=8,Desc='冬天虽然不能秀身材，但是可以搭一身好看的配饰，美美哒！',Feature=1,TFValidDate='2019-12-16 05:00:00',ValidDate='2019-12-23 05:00:00',}",
  [30830] = "{id=30830,NameZh='墙纸·星盒',Icon='item_30830',Type=946,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15219,AdventureValue=19,AdventureReward={buffid={64000480}},Condition=64,Desc='贴上这个，卧室就宛如变成了装满星星的盒子，栩栩生辉，睡觉时记得关闭电源哦。',Feature=1,TFValidDate='2019-12-16 05:00:00',ValidDate='2019-12-23 05:00:00',}",
  [30831] = "{id=30831,NameZh='地板·踏踏雪',Icon='item_30831',Type=947,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15220,AdventureValue=19,AdventureReward={buffid={64000480}},Condition=64,Desc='踩起来咯吱咯吱响，像是走在雪地上，放心，不会变形的，而且很暖和！',Feature=1,TFValidDate='2019-12-16 05:00:00',ValidDate='2019-12-23 05:00:00',}",
  [30832] = "{id=30832,NameZh='天花板·雪盖',Icon='item_30832',Type=949,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15221,AdventureValue=19,AdventureReward={buffid={64000490}},Condition=64,Desc='虽然充满圣诞气息，但是鉴于它的自动降雪功能，不建议在冬天使用哦。',Feature=1,TFValidDate='2019-12-16 05:00:00',ValidDate='2019-12-23 05:00:00',}",
  [30833] = "{id=30833,NameZh='楼梯·星途',Icon='item_30833',Type=948,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15222,AdventureValue=19,AdventureReward={buffid={64000490}},Condition=64,Desc='圣诞老人原来只是个普通的老爷爷，直到那一天，他踏上登神长阶......',Feature=1,TFValidDate='2019-12-16 05:00:00',ValidDate='2019-12-23 05:00:00',}",
  [30834] = "{id=30834,NameZh='雪雪门扉',Icon='item_30834',Type=950,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15223,AdventureValue=19,AdventureReward={buffid={64000480}},Condition=64,Desc='无论怎样的风雪席卷，它都能把它们挡在门外，守护你温馨的家。',Feature=1,TFValidDate='2019-12-16 05:00:00',ValidDate='2019-12-23 05:00:00',}",
  [30839] = "{id=30839,NameZh='远方的信',Icon='item_30839',Type=956,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15224,AdventureValue=50,AdventureReward={buffid={64000570}},Condition=8,Desc='圣诞老人居住的圣诞岛位置偏远，而且荒无人烟，虽然嘴上不说，但他还是会寂寞，就像他给邮箱起的名字：来自远方的信。',Feature=1,TFValidDate='2019-12-16 05:00:00',ValidDate='2019-12-23 05:00:00',}",
  [30900] = "{id=30900,NameZh='木马·蓝光琉璃',Icon='item_30900',Type=940,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=81036,AdventureValue=80,AdventureReward={buffid={64000420}},Condition=8,Desc='清澈的琉璃上反射出姜饼城孩子们的梦，马鞍波浪摇晃，带你驶进泡泡糖和绵绵云的梦乡。',Feature=1,}",
  [31001] = "{id=31001,NameZh='沉默的阿飘',Icon='item_31001',Type=927,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=81023,AdventureValue=1,AdventureReward={buffid={64000230}},Condition=8,Desc='一个普通的木桩。因为怕被揍，特意用白布伪装成了很不好欺负的样子。',Feature=1,}",
  [31010] = "{id=31010,NameZh='死间烛光',Icon='item_31010',Type=909,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=81024,AdventureValue=1,AdventureReward={buffid={64000180}},Condition=8,Desc='点亮黑暗，和每一个无所归依的灵魂。',Feature=1,}",
  [31015] = "{id=31015,NameZh='引魂者',Icon='item_31015',Type=953,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=81025,AdventureValue=1,AdventureReward={buffid={64000280}},Condition=8,Desc='前路通往夜光的彼岸，死者的梦乡。',Feature=1,}",
  [31100] = "{id=31100,NameZh='积雪覆盖的楼梯',Icon='item_31100',Type=948,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15001,AdventureValue=19,AdventureReward={buffid={64000380},rewardid={3920}},Condition=64,ComposeID=131100,Desc='一层阶梯一层白雪，交织着冰晶的楼梯，晶莹剔透，仿佛在为你指路。',Feature=1,}",
  [31101] = "{id=31101,NameZh='冰凌星窗',Icon='item_31101',Type=908,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15002,AdventureValue=38,AdventureReward={buffid={64000380},rewardid={3920}},Condition=4,ComposeID=131101,Desc='冰星与梦编织而成这剔透的星窗，愿你可以透过它看望向美好。',Feature=1,}",
  [31102] = "{id=31102,NameZh='冰凌星架',Icon='item_31102',Type=938,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15003,AdventureValue=45,AdventureReward={buffid={64000240},rewardid={3920}},Condition=4,ComposeID=131102,Desc='你可曾阅读过关于冰雪的故事，拿起书架上的书籍，进入到冰雪的世界中，享受这场关于冰雪的梦。',Feature=1,}",
  [31103] = "{id=31103,NameZh='冰凌星栏',Icon='item_31103',Type=955,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15004,AdventureValue=10,AdventureReward={buffid={64000380},rewardid={3920}},Condition=4,ComposeID=131103,Desc='冰霜与星梦遮挡不住你的美好，透过这屏风，又会有怎样怡人的景色呢？',Feature=1,}",
  [31104] = "{id=31104,NameZh='绒绒雪怪沙发',Icon='item_31104',Type=901,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15005,AdventureValue=63,AdventureReward={buffid={64000180},rewardid={3920}},Condition=4,ComposeID=131104,Desc='毛绒绒的雪怪为你在这充斥寒意的日子里增添一丝温暖，躺在上面不由得让你深陷其中，冒险什么的，明天再说啦~',Feature=1,}",
  [31105] = "{id=31105,NameZh='盛开的冰泉',Icon='item_31105',Type=928,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=15006,AdventureValue=90,AdventureReward={buffid={64000220},rewardid={3920}},Condition=4,ComposeID=131105,Desc='不同于湍流不息的泉水一样活泼而美好，停驻雕花的冰泉有着异样的风情，冰雪的美丽与泉水交织缠绕，诉说着一首冬季恋歌。',Feature=1,}",
  [31106] = "{id=31106,NameZh='冰星花·铃',Icon='item_31106',Type=918,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15007,AdventureValue=18,AdventureReward={buffid={64000190},rewardid={3920}},Condition=4,ComposeID=131106,Desc='生长，发芽，艳丽的绽放在这冬日这种，不似温室的娇花，冰霜中的花朵有着特有的芬芳，那是坚韧的味道。',Feature=1,}",
  [31107] = "{id=31107,NameZh='冰星花·兰',Icon='item_31107',Type=918,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15008,AdventureValue=18,AdventureReward={buffid={64000190},rewardid={3920}},Condition=4,ComposeID=131107,Desc='淡雅而内敛，芳香清远而悠长，让 人在若有若无之间沉溺其中不能自拔。',Feature=1,}",
  [31108] = "{id=31108,NameZh='冰翼星梯',Icon='item_31108',Type=940,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=15009,AdventureValue=240,AdventureReward={buffid={64000110},rewardid={3920}},Condition=4,ComposeID=131108,Desc='冰雪的魅力在滑梯体现到极致，松软的白雪构成滑梯的羽翼，冰霜为滑梯的表面镀上了一层星光，滑梯承载的不仅是欢笑，还是那段难忘的回忆。',Feature=1,}",
  [31109] = "{id=31109,NameZh='雪人哈恩',Icon='item_31109',Type=927,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15010,AdventureValue=75,AdventureReward={buffid={64000230},rewardid={3920}},Condition=4,ComposeID=131109,Desc='在寒冷的冬季，雪人哈恩在大雪中奔波着，一直寻找着真正的朋友，因为他相信，只要在真正的朋友身边，他就永远都不会融化。',Feature=1,}",
  [31110] = "{id=31110,NameZh='雪花制造机',Icon='item_31110',Type=940,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=15011,AdventureValue=240,AdventureReward={buffid={64000060},rewardid={3920}},Condition=4,ComposeID=131110,Desc='一份冰霜一份星光，两种东西混合在一起，加上最美好的心意，在机器的带动下缠绕交织，制造出一份份璀璨的冰晶雪花。',Feature=1,}",
  [31200] = "{id=31200,NameZh='隐夕',Icon='item_31200',Type=939,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=16001,AdventureValue=63,AdventureReward={buffid={64000180},rewardid={3920}},Condition=4,ComposeID=131200,Desc='赏心悦目的对称设计，上等的用料，还有风雅的梅兰竹菊四君子图，可谓美观与实用兼备。',}",
  [31201] = "{id=31201,NameZh='椅·悠霞',Icon='item_31201',Type=906,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=16002,AdventureValue=20,AdventureReward={buffid={64000190},rewardid={3920}},Condition=4,ComposeID=131201,Desc='云淡风轻间，闲适的时光缓缓流淌，意识也随着轻柔的摇曳开始漫游。',}",
  [31202] = "{id=31202,NameZh='福到',Icon='item_31202',Type=942,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=81006,AdventureValue=1,AdventureReward={buffid={64000190}},Condition=8,Desc='“福”字的文化最早源自于斐扬，传言只要在幸福的节日里将福字挂到家里，接下来一年的冒险都会与幸福相伴。',Feature=1,TFValidDate='2020-01-22 05:00:00',ValidDate='2020-01-29 05:00:00',}",
  [31203] = "{id=31203,NameZh='居游',Icon='item_31203',Type=908,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=16003,AdventureValue=30,AdventureReward={buffid={64000390},rewardid={3920}},Condition=4,ComposeID=131203,Desc='小桥流水，茂林修竹的景色都在这扇窗中成为最动人的画作。',}",
  [31204] = "{id=31204,NameZh='灯·烛夜',Icon='item_31204',Type=909,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=16004,AdventureValue=20,AdventureReward={buffid={64000240},rewardid={3920}},Condition=4,ComposeID=131204,Desc='纸帐中摇曳的烛火，是那未有归期的漂泊者的心之所向。',}",
  [31205] = "{id=31205,NameZh='星眠',Icon='item_31205',Type=936,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=16005,AdventureValue=25,AdventureReward={buffid={64000040},rewardid={3920}},Condition=4,ComposeID=131205,Desc='夜深了，静谧中是昏暗的烛光，映出思念的形状。',}",
  [31206] = "{id=31206,NameZh='桌·茶韵',Icon='item_31206',Type=911,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=16006,AdventureValue=55,AdventureReward={buffid={64000240},rewardid={3920}},Condition=4,ComposeID=131206,Desc='岭云间甘醇清香的新芽，只为最交心的友人奉上。典雅的茶桌上，茗香沁人心脾。',}",
  [31207] = "{id=31207,NameZh='夕照',Icon='item_31207',Type=903,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=16007,AdventureValue=25,AdventureReward={buffid={64000390},rewardid={3920}},Condition=4,ComposeID=131207,Desc='主打暖色系的地毯，加入花与叶的元素，触感舒适，华贵而不失大气。',}",
  [31208] = "{id=31208,NameZh='桌·团圆',Icon='item_31208',Type=911,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=16008,AdventureValue=69,AdventureReward={buffid={64000230},rewardid={3920}},Condition=4,ComposeID=131208,Desc='沉稳低调的设计，上等的木材，花纹精致的桌布配上丰盛可口的佳肴，家人团聚的幸福尽在这里。',}",
  [31209] = "{id=31209,NameZh='结·缘',Icon='item_31209',Type=942,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=81007,AdventureValue=1,AdventureReward={buffid={64000240}},Condition=8,Desc='交织的红色丝带承载着最诚挚的祈愿与最美好的祝福，与心爱的人一起编织，两个人的羁绊将会持续到永远。',Feature=1,TFValidDate='2020-01-22 05:00:00',ValidDate='2020-01-29 05:00:00',}",
  [31210] = "{id=31210,NameZh='床·橙空',Icon='item_31210',Type=905,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=16009,AdventureValue=125,AdventureReward={buffid={64000380},rewardid={3920}},Condition=4,ComposeID=131210,Desc='整体采用夕阳的意象，床灯宛如西沉的落日，床体选用高级红木，床褥松软有弹性，温柔地包裹身体，带给人一个好梦。',}",
  [31211] = "{id=31211,NameZh='福语·上',Icon='item_31211',Type=942,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=16010,AdventureValue=45,AdventureReward={buffid={64000340},rewardid={3920}},Condition=4,ComposeID=131211,Desc='用最迷人的金色，一笔一划写下最诚挚的祝福。',}",
  [31212] = "{id=31212,NameZh='福语·下',Icon='item_31212',Type=942,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=16011,AdventureValue=45,AdventureReward={buffid={64000340},rewardid={3920}},Condition=4,ComposeID=131212,Desc='用最迷人的金色，一笔一划写下最诚挚的祝福。',}",
  [31213] = "{id=31213,NameZh='灯·暖枫',Icon='item_31213',Type=909,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=16012,AdventureValue=20,AdventureReward={buffid={64000240},rewardid={3920}},Condition=4,ComposeID=131213,Desc='灯罩上的枫叶装饰富有季节感，吊垂的流苏平添几分秀丽。暖黄色的灯光，照亮了脚下的路，也温暖了行路者的心。',}",
  [31214] = "{id=31214,NameZh='金币多多',Icon='item_31214',Type=941,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=81008,AdventureValue=1,AdventureReward={buffid={64000390}},Condition=8,Desc='珍珠，宝石，无数的zeny，这些都是大家梦寐以求的东西，只要把带来好运的财神挂到墙上，你的梦想全部可以实现。',Feature=1,TFValidDate='2020-01-22 05:00:00',ValidDate='2020-01-29 05:00:00',}",
  [31215] = "{id=31215,NameZh='游龙',Icon='item_31215',Type=938,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=16013,AdventureValue=45,AdventureReward={buffid={64000240},rewardid={3920}},Condition=4,ComposeID=131215,Desc='流畅的整体造型，精致的雕花，将自己心爱的宝物陈列在此，室内雅趣又多几分。',}",
  [31216] = "{id=31216,NameZh='花舞',Icon='item_31216',Type=918,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=16014,AdventureValue=20,AdventureReward={buffid={64000190},rewardid={3920}},Condition=4,ComposeID=131216,Desc='温婉的曲线，自然的木色，与摆放的盆景一同为观者带来平静的心情。',}",
  [31217] = "{id=31217,NameZh='椅·闲梦',Icon='item_31217',Type=906,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=16015,AdventureValue=20,AdventureReward={buffid={64000190},rewardid={3920}},Condition=4,ComposeID=131217,Desc='椅背的造型灵动富有神采，舒适的的坐垫与脚垫，让人不禁想躺上去小憩一阵。',}",
  [31218] = "{id=31218,NameZh='椅·食逸',Icon='item_31218',Type=906,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=16016,AdventureValue=20,AdventureReward={buffid={64000190},rewardid={3920}},Condition=4,ComposeID=131218,Desc='椅背完美贴合身体，扶手的大曲线富有美感。坐在这样的椅子上就餐，想必十分愉快。',}",
  [31219] = "{id=31219,NameZh='相伴',Icon='item_31219',Type=942,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=16017,AdventureValue=45,AdventureReward={buffid={64000340},rewardid={3920}},Condition=4,ComposeID=131219,Desc='展开画卷，映入眼帘的是庄严的国王波利和可爱的天使波利，两只相伴的温馨一幕感染着看到这幅画作的每个人。',}",
  [31220] = "{id=31220,NameZh='椅·正心',Icon='item_31220',Type=906,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=16018,AdventureValue=25,AdventureReward={buffid={64000180},rewardid={3920}},Condition=4,ComposeID=131220,Desc='椅子透出一种庄重感，坐在上面似乎感到自己气势如虹。',}",
  [31221] = "{id=31221,NameZh='留锋',Icon='item_31221',Type=957,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=16019,AdventureValue=60,AdventureReward={buffid={64000040},rewardid={3920}},Condition=4,ComposeID=131221,Desc='贵重的武器怎能随意放置？当然要妥善保管。此架体阶梯式的设计让武器陈列显得气势十足。',}",
  [31222] = "{id=31222,NameZh='墨明',Icon='item_31222',Type=957,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=16020,AdventureValue=60,AdventureReward={buffid={64000240},rewardid={3920}},Condition=4,ComposeID=131222,Desc='造型匠心独具的书卷缸。因为常年装满书画而留下怡人的墨香，与缸本身的木香结合，散发出一种奇妙的芬芳。',}",
  [31223] = "{id=31223,NameZh='青浪',Icon='item_31223',Type=957,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=16021,AdventureValue=60,AdventureReward={buffid={64000190},rewardid={3920}},Condition=4,ComposeID=131223,Desc='釉彩素雅怡人，附上浪花与波利花纹，是一只十分别致的花瓶。',}",
  [31224] = "{id=31224,NameZh='桌·展墨',Icon='item_31224',Type=911,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=16022,AdventureValue=69,AdventureReward={buffid={64000230},rewardid={3920}},Condition=4,ComposeID=131224,Desc='方寸间的黑白世界，在平整的桌面上丰富起来。',}",
  [31225] = "{id=31225,NameZh='清影',Icon='item_31225',Type=957,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=16023,AdventureValue=60,AdventureReward={buffid={64000170},rewardid={3920}},Condition=4,ComposeID=131225,Desc='水池与盘龙的造型巧妙结合，潺潺流水，浮云飘动，闲适心情自在此。',}",
  [31226] = "{id=31226,NameZh='竹趣',Icon='item_31226',Type=918,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=16024,AdventureValue=27,AdventureReward={buffid={64000170},rewardid={3920}},Condition=4,ComposeID=131226,Desc='微风拂来，竹海涛声四起。那憨态可掬的生灵在竹海中畅游，好不惬意。',}",
  [31227] = "{id=31227,NameZh='暗香',Icon='item_31227',Type=918,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=16025,AdventureValue=27,AdventureReward={buffid={64000220},rewardid={3920}},Condition=4,ComposeID=131227,Desc='傲骨的花朵俏丽绽放，严寒中一阵幽然暗香。飞舞的花瓣不以己悲，因为山花烂漫的美好春光即将来临。',}",
  [31228] = "{id=31228,NameZh='香炉·紫烟',Icon='item_31228',Type=957,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=16026,AdventureValue=90,AdventureReward={buffid={64000170},rewardid={3920}},Condition=4,ComposeID=131228,Desc='熠熠生辉的金色香炉，配上造型沉稳流畅的檀木底座，紫烟氤氲，尽显高贵气质。',}",
  [31229] = "{id=31229,NameZh='飞焰',Icon='item_31229',Type=957,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=16027,AdventureValue=90,AdventureReward={buffid={64000220},rewardid={3920}},Condition=4,ComposeID=131229,Desc='烟花宛如飞龙衔珠，升空的宝珠在夜空绽放，燃尽自己，只为那转瞬即逝的美。',}",
  [31230] = "{id=31230,NameZh='金枫',Icon='item_31230',Type=946,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=16028,AdventureValue=15,AdventureReward={buffid={64000290}},Condition=64,Desc='对称的墙柱与雕花营造出古典之美，摇曳的烛光从镂空烛台透出，墙柱上的金漆绽放出迷人的光彩。',}",
  [31231] = "{id=31231,NameZh='地板·方寸之间',Icon='item_31231',Type=947,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=16029,AdventureValue=15,AdventureReward={buffid={64000390}},Condition=64,Desc='将规律之美发挥到极致，在脚下拼接出一幅精美的画作。',}",
  [31232] = "{id=31232,NameZh='枫语木心',Icon='item_31232',Type=948,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=16030,AdventureValue=15,AdventureReward={buffid={64000390}},Condition=64,Desc='木料的选用充分考虑了防潮防腐，坚实耐用，缓缓登上楼梯，沉稳的声音带来一种安心感。',}",
  [31233] = "{id=31233,NameZh='天花板·木穹',Icon='item_31233',Type=949,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=16031,AdventureValue=15,AdventureReward={buffid={64000290}},Condition=64,Desc='橙黄渐变的门帘，犹如夕阳西下的天空。门板上是古朴的线条花纹，方与圆之间达到了最和谐的平衡。',}",
  [31234] = "{id=31234,NameZh='落日长影',Icon='item_31234',Type=950,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=16032,AdventureValue=15,AdventureReward={buffid={64000290}},Condition=64,Desc='充满自然气息的木材上，几笔金线勾勒出规整的美，搭配地板，营造出一个沉静安详的美妙空间。',}",
  [31235] = "{id=31235,NameZh='金叶余晖',Icon='item_31236',Type=958,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=81019,AdventureValue=1,AdventureReward={buffid={64000180}},Condition=8,Desc='褪去夏日鲜亮的色彩，撑开金灿灿的叶之伞，叶雨中一阵凉风，树叶一起唱起了丰收之歌。',}",
  [31236] = "{id=31236,NameZh='文夕木灵',Icon='item_31235',Type=938,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=81020,AdventureValue=1,AdventureReward={buffid={64000230}},Condition=8,Desc='日暮时分，昏暗的书房亮起了温暖的灯光，架子上整齐摆放着的世界的记忆。翻开它们，与世界共享这份奇妙的记忆……',}",
  [31237] = "{id=31237,NameZh='夕照红枫礼包',Icon='item_3600',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='打开可获得一整套的夕照红枫装修物件，让你的家园充满浓浓秋意',}",
  [31301] = "{id=31301,NameZh='床·金色暖夜',Icon='item_31301',Type=905,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=17001,AdventureValue=125,AdventureReward={buffid={64000080},rewardid={3920}},Condition=4,ComposeID=131301,Desc='松软的床垫，实木用料配上暖色系的寝具，充裕的空间足够舒展身体，满满的都是安心感。',}",
  [31302] = "{id=31302,NameZh='沙发·遐思',Icon='item_31302',Type=901,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=17002,AdventureValue=50,AdventureReward={buffid={64000190},rewardid={3920}},Condition=4,ComposeID=131302,Desc='将身体沉入轻柔的守护中，一天的疲劳与不快就此烟消云散。难得的闲适时光,让心灵得到平静。',}",
  [31303] = "{id=31303,NameZh='椅·雅正',Icon='item_31303',Type=906,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=17003,AdventureValue=20,AdventureReward={buffid={64000190},rewardid={3920}},Condition=4,ComposeID=131303,Desc='中正而有棱有角的设计，让这把椅子带上一种浑然天成的威严，不由得让人正襟危坐。',}",
  [31304] = "{id=31304,NameZh='桌·墨雅',Icon='item_31304',Type=904,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=17004,AdventureValue=81,AdventureReward={buffid={64000180},rewardid={3920}},Condition=4,ComposeID=131304,Desc='笔下是一片清香的墨迹，思绪却早已随着笔墨飞往了远方。',}",
  [31305] = "{id=31305,NameZh='墨宇',Icon='item_31305',Type=938,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=17005,AdventureValue=56,AdventureReward={buffid={64000230},rewardid={3920}},Condition=4,ComposeID=131305,Desc='古朴的木色，典雅的设计，书卷的墨香为房间平添一份情趣。',}",
  [31306] = "{id=31306,NameZh='秘景',Icon='item_31306',Type=939,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=17006,AdventureValue=50,AdventureReward={buffid={64000190},rewardid={3920}},Condition=4,ComposeID=131306,Desc='幽幽夜幕下，屏风前出现的人影勾起无限的遐想——那熟悉的身影究竟是谁？',}",
  [31307] = "{id=31307,NameZh='弈趣',Icon='item_31307',Type=922,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=17007,AdventureValue=50,AdventureReward={buffid={64000130},rewardid={3920}},Condition=4,ComposeID=131307,Desc='方寸之间，黑与白构成世间最深邃的哲理，徜徉在无限的可能性中，那是无尽的宇宙。',}",
  [31308] = "{id=31308,NameZh='灯·伴明',Icon='item_31308',Type=924,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=17008,AdventureValue=25,AdventureReward={buffid={64000240},rewardid={3920}},Condition=4,ComposeID=131308,Desc='夜已深，摇曳的灯火撒满了整个房间。朦胧的光亮中，是自己映在墙上的是自己孤独的身影。',}",
  [31309] = "{id=31309,NameZh='秋爽',Icon='item_31309',Type=934,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=17009,AdventureValue=56,AdventureReward={buffid={64000230},rewardid={3920}},Condition=4,ComposeID=131309,Desc='秋日澄澈的天空下，金灿灿的叶为这个时节添上一笔耀眼的色彩。',}",
  [31310] = "{id=31310,NameZh='窗·夕影',Icon='item_31310',Type=908,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=17010,AdventureValue=30,AdventureReward={buffid={64000390},rewardid={3920}},Condition=4,ComposeID=131310,Desc='窗外眩目的橙色光芒，透过朦胧的窗，微微染红了窗边人的脸颊。窗栏将外界的景色做了一次精心的装裱。',}",
  [31311] = "{id=31311,NameZh='画·青山龙境',Icon='item_31311',Type=942,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=17011,AdventureValue=45,AdventureReward={buffid={64000340},rewardid={3920}},Condition=4,ComposeID=131311,Desc='神龙的力量滋养了山川大地，画中的龙目光炯炯有神，仿佛下一秒就要跑出画卷，现身于此。',}",
  [31312] = "{id=31312,NameZh='心源',Icon='item_31312',Type=953,MaxNum=99999,SellPrice=100,AdventureSort=17012,AdventureValue=10,AdventureReward={buffid={64000200},rewardid={3920}},Condition=4,ComposeID=131312,Desc='装载着香醇的美酒，在岁月的沉淀中留下了沧桑的痕迹，但也有了愈发宽广的胸怀。',}",
  [31313] = "{id=31313,NameZh='竹歌',Icon='item_31313',Type=903,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=17013,AdventureValue=25,AdventureReward={buffid={64000390},rewardid={3920}},Condition=4,ComposeID=131313,Desc='素雅的色彩，舒适的面料，富有规则性的拼接，简朴而充满情调。',}",
  [31314] = "{id=31314,NameZh='纳忆',Icon='item_31314',Type=910,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=17014,AdventureValue=56,AdventureReward={buffid={64000030},rewardid={3920}},Condition=4,ComposeID=131314,Desc='合理美观的布局设计，最大化创造收纳空间，蕴藏美好回忆的宝贝都在这里安睡着呢。',}",
  [31315] = "{id=31315,NameZh='夕海',Icon='item_31315',Type=946,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=17015,AdventureValue=15,AdventureReward={buffid={64000290},rewardid={3920}},Condition=64,ComposeID=131315,Desc='温柔的浅色打底，加上精美的镂花装饰，让人产生一种在海边凭栏观海的遐想。',}",
  [31316] = "{id=31316,NameZh='夕照之花',Icon='item_31316',Type=947,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=17016,AdventureValue=15,AdventureReward={buffid={64000390},rewardid={3920}},Condition=64,ComposeID=131316,Desc='与地板相呼应的配色和花纹，为房间带来完美的一体感。',}",
  [31317] = "{id=31317,NameZh='雅步',Icon='item_31317',Type=948,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=17017,AdventureValue=19,AdventureReward={buffid={64000380},rewardid={3920}},Condition=64,ComposeID=131317,Desc='精致的雕花，迷人的花纹点缀，辅之以上等的木料，连脚步声都是美妙的鼓点。',}",
  [31318] = "{id=31318,NameZh='木暖',Icon='item_31318',Type=949,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=17018,AdventureValue=19,AdventureReward={buffid={64000280},rewardid={3920}},Condition=64,ComposeID=131318,Desc='不经意间抬头一望，对称的花纹与温柔的木色让整个房间充满了温馨。',}",
  [31319] = "{id=31319,NameZh='门·暮忧',Icon='item_31319',Type=950,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=17019,AdventureValue=15,AdventureReward={buffid={64000290},rewardid={3920}},Condition=64,ComposeID=131319,Desc='典雅的线条，温暖的色调。轻轻推开门扉，那个人会在吗？',}",
  [31400] = "{id=31400,NameZh='墙纸·静夜',Icon='item_31400',Type=946,MaxNum=99999,SellPrice=100,AdventureSort=18001,AdventureValue=12,AdventureReward={buffid={64000300},rewardid={3920}},Condition=64,ComposeID=131400,Desc='幽蓝的墙壁，镶嵌白银装饰的镂花装饰，令人快速进入沉静的梦乡。',}",
  [31401] = "{id=31401,NameZh='地板·月光蝶',Icon='item_31401',Type=947,MaxNum=99999,SellPrice=100,AdventureSort=18002,AdventureValue=12,AdventureReward={buffid={64000400},rewardid={3920}},Condition=64,ComposeID=131401,Desc='经过附魔的特殊地板，华丽的魔纹在夜晚吸收月光，在白天释放，增强室内光照。',}",
  [31402] = "{id=31402,NameZh='楼梯·摘星',Icon='item_31402',Type=948,MaxNum=99999,SellPrice=100,AdventureSort=18003,AdventureValue=12,AdventureReward={buffid={64000400},rewardid={3920}},Condition=64,ComposeID=131402,Desc='拾阶而上，步入星空，与群星为伴。',}",
  [31403] = "{id=31403,NameZh='门·星森之风',Icon='item_31403',Type=950,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=18004,AdventureValue=15,AdventureReward={buffid={64000290},rewardid={3920}},Condition=64,ComposeID=131403,Desc='打开门扉，让风儿吹进来，带来森林的低语。',}",
  [31404] = "{id=31404,NameZh='窗·花萦小筑',Icon='item_31404',Type=908,MaxNum=99999,SellPrice=100,AdventureSort=18005,AdventureValue=24,AdventureReward={buffid={64000400},rewardid={3920}},Condition=4,ComposeID=131404,Desc='将小屋修建在林间，在鲜花绿草的萦绕间，安闲地度过悠长假期！',}",
  [31405] = "{id=31405,NameZh='床·林荫之梦',Icon='item_31405',Type=905,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=18006,AdventureValue=150,AdventureReward={buffid={64000020},rewardid={3920}},Condition=4,ComposeID=131405,Desc='躺在树荫下，让花香、月色与虫鸣带你进入美妙的梦乡。',}",
  [31406] = "{id=31406,NameZh='灯·星炬',Icon='item_31406',Type=909,MaxNum=99999,SellPrice=100,AdventureSort=18007,AdventureValue=16,AdventureReward={buffid={64000250},rewardid={3920}},Condition=4,ComposeID=131406,Desc='能够聚集星光的灯具，一颗星星的光芒或许很微弱，但无数颗星星聚集起来，就能点亮整片夜空。',}",
  [31407] = "{id=31407,NameZh='桌·书海探秘',Icon='item_31407',Type=904,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=18008,AdventureValue=65,AdventureReward={buffid={64000240},rewardid={3920}},Condition=4,ComposeID=131407,Desc='为什么有四季交替？秋叶为何飘落？天空中有多少星星？它们白天又去了哪里？这世间有那么多问题等待着我们探索——到知识的海洋中寻找答案吧！',}",
  [31408] = "{id=31408,NameZh='沙发·沉思者',Icon='item_31408',Type=901,MaxNum=99999,SellPrice=100,AdventureSort=18009,AdventureValue=40,AdventureReward={buffid={64000200},rewardid={3920}},Condition=4,ComposeID=131408,Desc='倚在躺椅上，与星辰共鸣，化身沉思者，探索关于世界最深邃的哲理。',}",
  [31409] = "{id=31409,NameZh='餐桌·森林的馈赠',Icon='item_31409',Type=945,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=18010,AdventureValue=75,AdventureReward={buffid={64000180},rewardid={3920}},Condition=4,ComposeID=131409,Desc='野果、清泉与果酒，这是森林的馈赠——在星空之下享用原生态的美食吧！',}",
  [31410] = "{id=31410,NameZh='地毯·仲夏夜空',Icon='item_31410',Type=903,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=18011,AdventureValue=25,AdventureReward={buffid={64000390},rewardid={3920}},Condition=4,ComposeID=131410,Desc='使用时间花园的稀有植物纤维织造的高档地毯，触感宛如夏夜拂面的晚风。',}",
  [31411] = "{id=31411,NameZh='浴缸·星海',Icon='item_31411',Type=917,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=18012,AdventureValue=70,AdventureReward={buffid={64000090},rewardid={3920}},Condition=4,ComposeID=131411,Desc='畅游在星海之中，让星辰之力涤清你的疲劳。',}",
  [31412] = "{id=31412,NameZh='雕像·星愿',Icon='item_31412',Type=929,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=18013,AdventureValue=50,AdventureReward={buffid={64000180},rewardid={3920}},Condition=4,ComposeID=131412,Desc='传说对着流星许愿，愿望就会成真——而这尊手捧陨星的雕像完美解决了流星消逝太快来不及许愿的问题。',}",
  [31413] = "{id=31413,NameZh='墙饰·鹿灵',Icon='item_31413',Type=922,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=18014,AdventureValue=50,AdventureReward={buffid={64000130},rewardid={3920}},Condition=4,ComposeID=131413,Desc='以森林的守护者鹿灵为原型制作的壁挂，传说能够保护家宅平安。',}",
  [31601] = "{id=31601,NameZh='床·米奇睡眠故事',Icon='item_31601',Type=905,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15301,AdventureValue=100,AdventureReward={buffid={64000040}},Condition=8,Desc='来吧，在可爱的米奇床上，被柔软被辱拥抱，进入幻梦世界，踏上你的奇迹冒险。',}",
  [31602] = "{id=31602,NameZh='窗·米奇奇妙故事',Icon='item_31602',Type=908,MaxNum=99999,SellPrice=100,AdventureSort=15302,AdventureValue=24,AdventureReward={buffid={64000400}},Condition=8,Desc='给世界加上童话的滤镜，即使是司空见惯的风景，也会变得奇妙！',}",
  [31603] = "{id=31603,NameZh='乒乓球台·米奇活力故事',Icon='item_31603',Type=951,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15303,AdventureValue=75,AdventureReward={buffid={64000180}},Condition=8,Desc='不论到哪里都不要忘记运动哦！你看，活力四射的故事里，只差一个可以做对手的小伙伴啦！',}",
  [31604] = "{id=31604,NameZh='提灯·米奇光明故事',Icon='item_31604',Type=924,MaxNum=99999,SellPrice=100,AdventureSort=15304,AdventureValue=20,AdventureReward={buffid={64000250}},Condition=8,Desc='想象力越丰富的孩子，对黑暗越抱有恐惧。这时，它会为你在黑暗里，点起一盏天真的明灯。',}",
  [31606] = "{id=31606,NameZh='米妮的梳妆台',Icon='item_31606',Type=954,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15305,AdventureValue=19,AdventureReward={buffid={64000030}},Condition=8,Desc='爱美是所有人的天性。不用着急，坐下来，在镜子前好好地整理自己。世界会在门外，等着崭新的你。',}",
  [31607] = "{id=31607,NameZh='米奇的电视机',Icon='item_31607',Type=915,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15306,AdventureValue=45,AdventureReward={buffid={64000140}},Condition=8,Desc='老古董一般的电视机，一样可以点燃孩子们的梦想。童话不会被成长打败。',}",
  [31608] = "{id=31608,NameZh='唐老鸭自鸣钟',Icon='item_31608',Type=913,MaxNum=99999,SellPrice=100,AdventureSort=81048,AdventureValue=1,AdventureReward={buffid={64000300}},Condition=8,Desc='每天清晨都能与可爱的唐老鸭相约。早上好，亲爱的冒险者。',}",
  [31609] = "{id=31609,NameZh='蔚蓝深处',Icon='item_31609',Type=947,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=81053,AdventureValue=1,AdventureReward={buffid={64000390}},Condition=64,Desc='踩在这样的地板上，仿佛行走在大海之中。海浪汹涌之间，还隐藏着怀念的面容。',}",
  [31610] = "{id=31610,NameZh='洗衣机·米奇清爽故事',Icon='item_31610',Type=940,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15307,AdventureValue=125,AdventureReward={buffid={64000420}},Condition=8,Desc='一身泥水也不怕！米奇洗衣机吞下脏衣服，还一套清爽的给你。不过，如果能不那么脏，那就更好了……',}",
  [31611] = "{id=31611,NameZh='幻想之门',Icon='item_31611',Type=950,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=81054,AdventureValue=1,AdventureReward={buffid={64000290}},Condition=64,Desc='在那个熟悉身影的背后，会隐藏着怎样美好的世界？鼓起勇气，推开这扇门，来一探究竟吧！',}",
  [31612] = "{id=31612,NameZh='唐老鸭蛋糕',Icon='item_31612',Type=911,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=81049,AdventureValue=1,AdventureReward={buffid={64000440}},Condition=8,Desc='糖霜编成帽檐，草莓织就领结。再贴心地放上小叉子，亲爱的冒险者，还不快来许个愿，再大快朵颐？',}",
  [31613] = "{id=31613,NameZh='与鸭共浴',Icon='item_31613',Type=917,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=81050,AdventureValue=1,AdventureReward={buffid={64000180}},Condition=8,Desc='海滩风情的浴缸内，漂浮在水面上的是最经典的海军服小鸭鸭哦！',}",
  [31614] = "{id=31614,NameZh='布鲁托之家',Icon='item_31614',Type=931,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=81051,AdventureValue=1,AdventureReward={buffid={64000230}},Condition=8,Desc='汪汪专属，闲人勿进。如果想要敲门，请务必使用肉骨头！',}",
  [31615] = "{id=31615,NameZh='米奇放映机',Icon='item_31615',Type=943,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=15308,AdventureValue=90,AdventureReward={buffid={64000370}},Condition=8,Desc='看多了电视会对视力有损害，放映机对保护视力更有益。',}",
  [31616] = "{id=31616,NameZh='米妮烧烤架',Icon='item_31616',Type=952,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15309,AdventureValue=75,AdventureReward={buffid={64000230}},Condition=8,Desc='正餐和甜食是两个胃，没错。至于烤肉……或许是第三个胃？',}",
  [31617] = "{id=31617,NameZh='沙发·米奇舒适故事',Icon='item_31617',Type=901,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=81047,AdventureValue=1,AdventureReward={buffid={64000190}},Condition=8,Desc='坐下吧，感受米奇沙发友好温暖的拥抱哦。',}",
  [31618] = "{id=31618,NameZh='南瓜床',Icon='item_31618',Type=905,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=15401,AdventureValue=150,AdventureReward={buffid={64000030}},Condition=8,Desc='南瓜马车全新升级，变成了最柔软的床。善良的人啊，请在这里休息，做一个甜美的梦吧。',}",
  [31619] = "{id=31619,NameZh='贝尔的蜡烛台灯',Icon='item_31619',Type=924,MaxNum=99999,SellPrice=100,AdventureSort=15402,AdventureValue=20,AdventureReward={buffid={64000250}},Condition=8,Desc='请为我照亮黑暗吧，手中的蜡烛。只要有你在，我就不会害怕任何未知的前路。',}",
  [31620] = "{id=31620,NameZh='阿拉丁飞毯',Icon='item_31620',Type=903,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15403,AdventureValue=25,AdventureReward={buffid={64000390}},Condition=8,Desc='魔毯魔毯，你要带我去哪里？我梦想着，你会带我去见识那大千世界!',}",
  [31621] = "{id=31621,NameZh='喧天小锣鼓',Icon='item_31621',Type=955,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=19016,AdventureValue=1,AdventureReward={buffid={64000380}},Condition=8,Desc='哐！哐！哐！肃静！听我说话。欢迎光临来到这个家哦，远方的客人。',}",
  [31622] = "{id=31622,NameZh='原木制纺车台',Icon='item_31622',Type=919,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=19017,AdventureValue=1,AdventureReward={buffid={64000230}},Condition=8,Desc='造型独特的桌子，充满了奇异的风情。请不用害怕，纺锤已经被卸掉了。',}",
  [31623] = "{id=31623,NameZh='白雪公主的魔镜',Icon='item_31623',Type=922,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15404,AdventureValue=50,AdventureReward={buffid={64000130}},Condition=8,Desc='“魔镜啊魔镜，你怎么会出现在我的家里？”“因为您是世界上最好的主人啊！”',}",
  [31624] = "{id=31624,NameZh='梦幻墙面',Icon='item_31624',Type=946,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=81055,AdventureValue=1,AdventureReward={buffid={64000290}},Condition=64,Desc='墙面上每一张熟悉的面容都在无声对来客宣称：亲爱的朋友，欢迎来到我的家！',}",
  [31625] = "{id=31625,NameZh='美人鱼洗手台',Icon='item_31625',Type=940,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=15405,AdventureValue=150,AdventureReward={buffid={64000370}},Condition=8,Desc='拧开水龙头，用深海水洗净双手。日常使用的话，皮肤是不是也会变得像美人鱼一样好呢？',}",
  [31626] = "{id=31626,NameZh='白雪公主的水井',Icon='item_31626',Type=928,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=15406,AdventureValue=90,AdventureReward={buffid={64000220}},Condition=8,Desc='口渴可以自己打水喝，保证清凉解渴。然后请坐下来，喝水时也可欣赏七个小矮人的表演。',}",
  [31627] = "{id=31627,NameZh='小狗矮凳',Icon='item_31627',Type=906,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=15407,AdventureValue=50,AdventureReward={buffid={64000190}},Condition=8,Desc='坐下来的时候要小心，不要踢到椅子脚。不然没准它会突然缩回去，吓你一跳。',}",
  [31628] = "{id=31628,NameZh='贝尔的衣柜',Icon='item_31628',Type=907,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15408,AdventureValue=69,AdventureReward={buffid={64000380}},Condition=8,Desc='衣柜里收满了衣衫，但我一定会选出你最爱的那一件，然后穿上它，出现在你面前。',}",
  [31629] = "{id=31629,NameZh='老鸭腹中书',Icon='item_31629',Type=938,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=81052,AdventureValue=1,AdventureReward={buffid={64000240}},Condition=8,Desc='都说腹中可容万卷书。如果是唐老鸭这样的肚子……万卷书没有，至少也能放得下五十本！',}",
  [31630] = "{id=31630,NameZh='行进的阶梯',Icon='item_31630',Type=948,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=81056,AdventureValue=1,AdventureReward={buffid={64000380}},Condition=64,Desc='厚实的踏板和精细的雕纹不可兼得？不，在我的家里，它们就是可以同时存在。',}",
  [31631] = "{id=31631,NameZh='Love And Princess',Icon='item_31631',Type=949,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=81057,AdventureValue=1,AdventureReward={buffid={64000290}},Condition=64,Desc='一个高贵的冒险家是怎样的？——她的周围会围绕着很多很多爱，而核心则是永恒的自尊、自爱和坚定。',}",
  [31632] = "{id=31632,NameZh='幻想物语礼包',Icon='item_3681',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='温馨有爱的物品，给予冒险者仿佛回到童年的安心感。',}",
  [31633] = "{id=31633,NameZh='公主秘境礼包',Icon='item_3682',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='公主的家具，最重要的一点是什么？华丽？精致？不，是一尘不染！',}",
  [31700] = "{id=31700,NameZh='南瓜马车',Icon='item_31700',Type=940,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=15409,AdventureValue=80,AdventureReward={buffid={64000060}},Condition=8,Desc='南瓜先生，谢谢你的护送。不论舞会上遇到哪位王子，唯有你才是真正的护花使者。',}",
  [31701] = "{id=31701,NameZh='罩中玫瑰',Icon='item_31701',Type=940,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=15410,AdventureValue=150,AdventureReward={buffid={64000420}},Condition=8,Desc='我爱的人啊，请不要用罩子将这么美的玫瑰罩起来吧。生命不应藏于其中，而该接受风吹雨打。因为我会与你一起承担命运，走向未来。',}",
  [31702] = "{id=31702,NameZh='矮人矿车',Icon='item_31702',Type=957,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=15411,AdventureValue=90,AdventureReward={buffid={64000030}},Condition=8,Desc='矮人并不是为了拯救公主而存在的！善良的公主得到了幸福，矮人的幸福还是脚踏实地的工作！',}",
  [31703] = "{id=31703,NameZh='深海之泪',Icon='item_31703',Type=940,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=15412,AdventureValue=100,AdventureReward={buffid={64000420}},Condition=8,Desc='珠蚌将入侵物默默舔舐，用长久的时间化伤口为珍珠。你可明白？坚韧的意志就是拥有这么强大的力量，和这么美的光辉。',}",
  [31704] = "{id=31704,NameZh='阿布猴',Icon='item_31704',Type=941,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=15413,AdventureValue=38,AdventureReward={buffid={64000280}},Condition=8,Desc='自由自在的阿布是阿拉丁最好的伙伴。那么你呢，和阿布拥有相同外貌的小猴子，愿意做我最好的伙伴吗？',}",
  [31705] = "{id=31705,NameZh='米妮·米奇伙伴故事',Icon='item_31705',Type=941,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=15311,AdventureValue=200,AdventureReward={buffid={64000410}},Condition=8,Desc='亲爱的伙伴必不可少。就算没有本人，也要有玩偶登场。让我们欢呼它的名字——米妮！',}",
  [31706] = "{id=31706,NameZh='高飞·米奇伙伴故事',Icon='item_31706',Type=957,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=15312,AdventureValue=60,AdventureReward={buffid={64000170}},Condition=8,Desc='亲爱的伙伴必不可少。就算没有本人，也要有玩偶登场。让我们欢呼它的名字——高飞！',}",
