  [31804] = "{id=31804,NameZh='开花的星星',Icon='item_31804',Type=925,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=19005,AdventureValue=1,AdventureReward={buffid={64000240}},Condition=8,Desc='藏在花蕊中，会闪烁明亮光辉的星星。据说是小魔女在梦里捡到的。',}",
