  [32034] = "{id=32034,NameZh='逐胜之路',Icon='item_32034',Type=948,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=81071,AdventureValue=1,AdventureReward={buffid={64000390}},Condition=64,Desc='有些坚定不移的信念在心中不断累积，越发强烈。我所居住的庭院，梦想依旧延续，你我必然走向辉煌。',}",
