  [32050] = "{id=32050,NameZh='警犬侠沙发',Icon='item_32050',Type=901,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=81074,AdventureValue=1,AdventureReward={buffid={64000420}},Condition=8,}",
