  [38015] = "{id=38015,NameZh='美颜立镜',Icon='item_38015',Type=921,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=80016,AdventureValue=25,AdventureReward={buffid={64000180},rewardid={3920}},Condition=4,ComposeID=138015,Desc='充满了日常气息的落地镜。但如同它的名字一样，使用镜子的人会变得越来越美丽。这是什么奇妙的魔法吗？',Feature=1,}",
  [38016] = "{id=38016,NameZh='俯瞰风景',Icon='item_38016',Type=942,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=80017,AdventureValue=45,AdventureReward={buffid={64000340},rewardid={3920}},Condition=4,ComposeID=138016,Desc='由著名的画师德兰·克雷斯坦绘制的一组壁画，记录了米德加尔特大陆上各处迷人的景象。据说曾在拍卖行被拍出天价，但一夜之间被怪盗团窃走了。无人知道为何它会出现在这里……',Feature=1,}",
  [38018] = "{id=38018,NameZh='回忆相框',Icon='item_38018',Type=912,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=80019,AdventureValue=45,AdventureReward={buffid={64000190},rewardid={3920}},Condition=4,ComposeID=138018,Desc='充满了回忆的朴素相框。看起来很久都没有人替换过相片。',Feature=1,}",
