  [38020] = "{id=38020,NameZh='缤纷小电视',Icon='item_38020',Type=915,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=80021,AdventureValue=56,AdventureReward={buffid={64000130},rewardid={3920}},Condition=4,ComposeID=138020,Desc='“别乱拍显示屏，不会出现雪花的！”',Feature=1,}",
  [38021] = "{id=38021,NameZh='时光留声机',Icon='item_38021',Type=916,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=80022,AdventureValue=44,AdventureReward={buffid={64000130},rewardid={3920}},Condition=4,ComposeID=138021,Desc='年代感满满的留声机。老唱片吱吱呀呀响着，转出时光的声音。',Feature=1,}",
