  [38101] = "{id=38101,NameZh='战时紧急围墙',Icon='item_38101',Type=955,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=70064,AdventureValue=8,AdventureReward={buffid={64000390},rewardid={3920}},Condition=4,ComposeID=138101,Desc='虽然看起来是不起眼的居家用墙，实则以军方标准打造，可以在战斗时当作坚固的堡垒。',}",
  [39000] = "{id=39000,NameZh='莱茵河之畔',Icon='item_39000',Type=940,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=80029,AdventureValue=240,AdventureReward={buffid={64000110},rewardid={3920}},Condition=4,ComposeID=139000,Desc='天鹅绒夫人精心设计，欧洲复古造型的大理石浴缸。精致中带着骄傲的慵懒感，单是看着，都能感觉到铺面而来的玫瑰香气……',Feature=1,}",
  [39001] = "{id=39001,NameZh='贝壳喵秘藏',Icon='item_39001',Type=940,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=80030,AdventureValue=240,AdventureReward={buffid={64000060},rewardid={3920}},Condition=4,ComposeID=139001,Desc='宝箱边上为什么会有游泳圈？！愤怒的黑猫探出头说明了一切：这里原是它的藏宝地，却被贪玩的小魔女据为己有，原本玩耍的地盘也被改造成了泡澡圣地……',Feature=1,}",
  [39002] = "{id=39002,NameZh='心想事成镜',Icon='item_39002',Type=940,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=80031,AdventureValue=240,AdventureReward={buffid={64000110},rewardid={3920}},Condition=4,ComposeID=139002,Desc='“由伟大的魔法精灵黄金波利看守的魔镜，包含了可以实现一切愿望的魔法。开启之时，也许就是世界毁灭的伊始……喂！喂！！不要随便拉开门把手！！！”',Feature=1,}",
  [39003] = "{id=39003,NameZh='晃悠悠秋千',Icon='item_39003',Type=940,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=80032,AdventureValue=240,AdventureReward={buffid={64000060},rewardid={3920}},Condition=4,ComposeID=139003,Desc='精致可爱的秋千架，一到午后就会有很多波利前来休息，有时他们也会和冒险者一起玩耍。“晃悠悠的波利晃悠悠的心，晃悠悠的秋千坐着你和我！”',Feature=1,}",
  [39004] = "{id=39004,NameZh='噼啪锅炉',Icon='item_39004',Type=940,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=80033,AdventureValue=240,AdventureReward={buffid={64000110},rewardid={3920}},Condition=4,ComposeID=139004,Desc='普隆德拉皇家料理师的专用锅炉，可以做出蒸羊羔蒸熊掌蒸鹿尾和……蒸馒头等美味！',Feature=1,}",
  [39005] = "{id=39005,NameZh='玩偶蹦蹦机',Icon='item_39005',Type=940,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=80034,AdventureValue=240,AdventureReward={buffid={64000060},rewardid={3920}},Condition=4,ComposeID=139005,Desc='占卜师蕾妮雅所制作的玩偶机，因为过于可爱，引起了众人的惊诧。“铃铃铃……当命运的按钮落下，你是否能抓住属于自己的幸运？”',Feature=1,}",
  [39006] = "{id=39006,NameZh='高级鞋景房',Icon='item_39006',Type=940,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=80035,AdventureValue=240,AdventureReward={buffid={64000110},rewardid={3920}},Condition=4,ComposeID=139006,Desc='为有品位的狗狗与主人量身打造，再也不用担心狗子咬坏鞋了。',}",
  [39008] = "{id=39008,NameZh='知识古树',Icon='item_39008',Type=940,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=80037,AdventureValue=240,AdventureReward={buffid={64000110},rewardid={3920}},Condition=4,ComposeID=139008,Desc='知识渊博的慈祥古树，闲暇的午后可以在树下一边听故事一边小憩。',}",
  [39009] = "{id=39009,NameZh='噗噗加湿机',Icon='item_39009',Type=940,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=80038,AdventureValue=240,AdventureReward={buffid={64000060},rewardid={3920}},Condition=4,ComposeID=139009,Desc='超越时代的大发明，消灭干涩脱皮，给你一个水润舒适的家。',}",
  [39010] = "{id=39010,NameZh='滚蛋滑梯',Icon='item_39010',Type=940,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=80039,AdventureValue=240,AdventureReward={buffid={64000060},rewardid={3920}},Condition=4,ComposeID=139010,Desc='“对魔物的胎教，我的意思是蛋教，是很重要的，不能让孩子输在起跑线上！”',}",
  [39500] = "{id=39500,NameZh='赛尼亚的相片',Icon='item_39500',Type=942,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=81001,AdventureValue=68,AdventureReward={buffid={64000040}},Condition=8,Desc='一张赛尼亚的照片，是国家地理杂志的首席摄影师希罗塔司在南门拍摄的。希罗塔司看着前方一个身着初心者服饰的少女和另一个初心者认真地敲打着波利，阳光下的少女令他忍不住举起相机想要记录下来。可能是相机的声音引起了赛尼亚的注意，她回头看到了对准自己的相机。希罗塔司有些尴尬，想要放下相机，没想到少女居然对着镜头露出了灿烂的笑容。他的快门不自觉的按了下去。真是一个温暖人心的笑容啊……',Feature=1,}",
  [39501] = "{id=39501,NameZh='愤怒卷轴',Icon='item_39501',Type=940,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=81003,AdventureValue=60,AdventureReward={buffid={64000040}},Condition=8,Desc='总是气鼓鼓的魔法卷轴，盯着看久了自己也会变得愤怒，到底是谁制作出来的呢......',}",
  [39502] = "{id=39502,NameZh='健喵房',Icon='item_39502',Type=940,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=81004,AdventureValue=60,AdventureReward={buffid={64000040}},Condition=8,Desc='专为精力过剩的主子准备，兼备有氧运动与无氧锻炼，明天开始，塑造迷人线条！',}",
  [39503] = "{id=39503,NameZh='井居鬼隐',Icon='item_30903',Type=940,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=81021,AdventureValue=72,AdventureReward={buffid={64000170}},Condition=8,Desc='以鸟居镇压的鬼井，传说井底勾连着异界',}",
  [39504] = "{id=39504,NameZh='咒火',Icon='item_31009',Type=924,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=81022,AdventureValue=10,AdventureReward={buffid={64000240}},Condition=8,Desc='被诅咒的篝火，燃烧时能听见鬼影的嚎哭声',}",
  [39505] = "{id=39505,NameZh='喜翁',Icon='Tumbler',Type=927,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=81032,AdventureValue=24,AdventureReward={buffid={64000040}},Condition=8,Desc='无论你做什么，他都会笑着面对。',}",
  [39507] = "{id=39507,NameZh='三色鲤鱼旗',Icon='item_39909',Type=956,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=81034,AdventureValue=20,AdventureReward={buffid={64000230}},Condition=8,Desc='“夏天的大雨下啊下，迎风的鲤鱼旗飘呀飘。”',}",
  [39508] = "{id=39508,NameZh='波利千层蛋糕',Icon='item_39908',Type=945,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=81035,AdventureValue=36,AdventureReward={buffid={64000170}},Condition=8,Desc='“呜哇！怎么会有这么诱人的蛋糕呢？趁没有人看见……让我舔一口吧！”',}",
  [39509] = "{id=39509,NameZh='摆件·游星天籁',Icon='item_39509',Type=924,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=81037,AdventureValue=16,AdventureReward={buffid={64000180}},Condition=8,Desc='偶像团体“闪耀少女”在演唱会时使用过的话筒，被某个狂热的粉丝搬回家制成的摆件。',}",
  [39510] = "{id=39510,NameZh='梳妆台·魔女变身记',Icon='item_39510',Type=910,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=81038,AdventureValue=28,AdventureReward={buffid={64000230}},Condition=8,Desc='美少女可是很善变的——白天，是人气偶像团体“闪耀少女”；到了夜晚，便化身为怪盗团体“偷星魔女”！不论何时，都是众人瞩目的焦点哦！',}",
  [39511] = "{id=39511,NameZh='琉璃花窗·金粉之家',Icon='item_39511',Type=922,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=81045,AdventureValue=16,AdventureReward={buffid={64000140}},Condition=8,Desc='精致的粉色系花窗，当日光照射玻璃时候，可以造成绚烂的粉粉效果；晚上，室内的灯光也让整个房间呈现出温暖色调，光线配合图案的效果让人过目不忘。',Feature=1,}",
  [39512] = "{id=39512,NameZh='琉璃暖阳',Icon='item_39512',Type=922,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=81046,AdventureValue=20,AdventureReward={buffid={64000180}},Condition=8,Desc='比花窗更加多样的琉璃配色，搭配上噼啪作响的炉火，窝在旁边可以获得彻底的放松，是只属于自己的“小小世界”。',Feature=1,}",
  [39513] = "{id=39513,NameZh='琉璃花窗·海洋之星',Icon='item_39513',Type=922,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=81047,AdventureValue=16,AdventureReward={buffid={64000140}},Condition=8,Desc='精致的蓝色系花窗，当日光照射玻璃时候，可以造成如同深海一般的效果；晚上，室内的灯光也让整个房间呈现出不一样的宁静色调。光线配合图案的效果让人过目不忘。',Feature=1,}",
  [39514] = "{id=39514,NameZh='壁挂·夜之凝视',Icon='item_39514',Type=922,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=81061,AdventureValue=20,AdventureReward={buffid={64000180}},Condition=8,Desc='嘿嘿，让我来看看那个愚蠢的人类在做什么喵~“黑猫，盯上你了！”',LoadShowPose={0,-2,0},}",
  [39515] = "{id=39515,NameZh='壁炉·欢欣之焰',Icon='item_39515',Type=922,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=81062,AdventureValue=20,AdventureReward={buffid={64000230}},Condition=8,Desc='雀跃的火焰精灵，为这冰冷的宫廷，带来一丝温暖。',LoadShowSize=0.8,}",
  [39516] = "{id=39516,NameZh='祈愿灵木',Icon='item_39516',Type=956,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=81064,AdventureValue=20,AdventureReward={buffid={64000230}},Condition=8,Desc='荒境有千年古树，吸纳天地灵气，带有祝福之力。如今，它的部分躯干被雕琢成了一件艺术品，为它的主人送去心想事成的幸运。',}",
  [39517] = "{id=39517,NameZh='南瓜马车',Icon='item_39517',Type=957,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=81065,AdventureValue=30,AdventureReward={buffid={64000180}},Condition=8,Desc='锵锵~童话中的南瓜马车驾到！虽然它不能将你送入王宫参加舞会，可是点亮车灯，在舒适的车厢里品尝茶点，也是一件浪漫的事情呀~',}",
  [39518] = "{id=39518,NameZh='藏品·竹林闲憩',Icon='item_39518',Type=917,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=81066,AdventureValue=20,AdventureReward={buffid={64000230}},Condition=8,Desc='用青石、翠竹搭建成的温泉，十分风雅。',LoadShowSize=0.3,}",
