  [40020] = "{id=40020,NameZh='死神之镰[1]',Icon='item_40020',Type=170,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=20340,AdventureSort=1000,AdventureValue=1,Condition=8,Desc='巨大的圆月镰刀，令人为之惊惧。',Feature=1,LoadShowSize=0.9,LoadShowRotate=70,LoadShowPose={0,-0.25,0},}",
