  [40022] = "{id=40022,NameZh='朗基鲁斯长矛[2]',Icon='item_40005',Type=170,MaxNum=99,SellPrice=100,Desc='沾满圣人的血，是种被诅咒的长矛。一个叫龙戚弩斯的士兵杀死圣人时所用的长矛。',Level=10,Feature=4,}",
