  [40025] = "{id=40025,NameZh='军用长矛',Icon='item_40025',Type=170,MaxNum=99,SellPrice=840,Desc='经历了多次战争不断修改设计并最终定型。重视实战效果的长矛。',Level=70,}",
  [40026] = "{id=40026,NameZh='制式长矛',Icon='item_40026',Type=170,MaxNum=99,SellPrice=960,Desc='专门为佣兵定制的骑士长矛。适应各种复杂环境。',Level=80,}",
  [40027] = "{id=40027,NameZh='击龙枪[1]',Icon='item_40027',Type=170,Quality=3,MaxNum=99,SellPrice=100,Feature=1,}",
  [40028] = "{id=40028,NameZh='龙之意志',Icon='item_40028',Type=170,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=100001,AdventureValue=1,Condition=8,Desc='暴君施密兹手下大将李·奥克用这把枪杀死了鼎鼎大名的龙族之王尼德霍格的分身。之后，他给这把枪改名为“龙之意志”，成为后来流传于世的“龙枪”。（建议作为武器外观使用）',Feature=1,LoadShowSize=0.9,LoadShowRotate=70,LoadShowPose={0,-0.25,0},}",
  [40029] = "{id=40029,NameZh='星界·夺魂者',Icon='item_40029',Type=170,MaxNum=99,AuctionPrice=1,SellPrice=79600,AdventureSort=100002,AdventureValue=1,Condition=8,Desc='利用星辰中提炼出的珍贵矿石制作而成，枪身流光反转，会使盯着它看的人失去灵魂的危险武器。',Feature=1,LoadShowSize=0.9,LoadShowRotate=70,LoadShowPose={0,-0.25,0},}",
