  [40034] = "{id=40034,NameZh='锥骑枪[1]',Icon='item_40034',Type=170,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=840,AdventureSort=1000,AdventureValue=1,Condition=8,Desc='骑兵最喜欢使用的长柄枪，可活用于长距离冲刺攻击，造成巨大的伤害。',Feature=1,LoadShowSize=0.9,LoadShowRotate=70,LoadShowPose={0,-0.3,0},}",
  [40035] = "{id=40035,NameZh='英灵·洁萝之荣光',Icon='item_40035',Type=170,MaxNum=99,SellPrice=100,AdventureSort=100006,AdventureValue=1,Condition=8,Desc='提枪冲锋神——洁萝露尔的武器，只有得到洁萝露尔看重的人，才会得到的神之恩赐。也只有这样才不会辱没了这一柄追随洁萝露尔多年的战斗利器。',Feature=1,LoadShowSize=0.9,LoadShowRotate=70,LoadShowPose={0,-0.3,0},}",
  [40036] = "{id=40036,NameZh='圣徒之矛[1]',Icon='item_40036',Type=170,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='圣歌教会曾经的荣耀，神圣骑士卡德罗的长矛。在卡德罗叛出圣歌教会后，而这柄长矛被封存在教会的地下兵器库之中，直到最近才被作为样品大量制造，用于装备日趋强大的教会骑士团。受到光明圣徒的祝福，安全精炼时消耗的装备件数减少一半。',Feature=1,LoadShowSize=0.9,LoadShowRotate=70,LoadShowPose={0,-0.25,0},}",
  [40037] = "{id=40037,NameZh='衔尾者蛇矛',Icon='item_40037',Type=170,MaxNum=99,SellPrice=100,AdventureSort=100004,AdventureValue=1,Condition=8,Desc='划开伤口并摄取敌人血液的蛇形长矛。',Feature=1,LoadShowSize=1,LoadShowRotate=70,LoadShowPose={0,-0.3,0},}",
  [40038] = "{id=40038,NameZh='青铁柱枪[1]',Icon='item_40038',Type=170,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=840,AdventureSort=1000,AdventureValue=1,Condition=8,Desc='精铁打造的双手矛，短小易持却威力强大，搭配枪筒也可做长矛使用。',Feature=1,LoadShowSize=0.9,LoadShowRotate=70,LoadShowPose={0,-0.5,0},}",
  [40039] = "{id=40039,NameZh='圣灵·洁萝之辉芒枪',Icon='item_40039',Type=170,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='提枪冲锋神——洁萝露尔的武器，只有在需要付诸生命的战斗时才会使用这把枪。',Feature=1,LoadShowSize=0.9,LoadShowRotate=70,LoadShowPose={0,-0.3,0},}",
  [40040] = "{id=40040,NameZh='皇家刺枪',Icon='item_40009',Type=170,MaxNum=99,SellPrice=1140,Desc='普隆德拉皇家卫兵专用的刺枪，采用了最顶级的红铜枪柄和雪花白银枪尖，十分锋利。',Level=95,}",
  [40041] = "{id=40041,NameZh='风暴之枪[1]',Icon='item_40041',Type=170,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=1000,AdventureValue=1,Condition=8,Desc='通晓大气流动之理的风之精灵啊，撕裂敌人吧！',Feature=1,LoadShowSize=1,LoadShowRotate=70,LoadShowPose={0,-0.25,0},}",
  [40042] = "{id=40042,NameZh='永恒之枪',Icon='item_40042',Type=450,Quality=4,MaxNum=1,SellPrice=100,AdventureSort=100004,Desc='主神奥丁曾使用过的武器，全名冈格尼尔，意为贯穿一切。它本身具有神性，任何对枪尖所发的誓言，都永不可反悔且必定实现。',NoSale=1,NoStorage=7,}",
