  [40044] = "{id=40044,NameZh='永恒之枪·神铸',Icon='item_40044',Type=450,Quality=4,MaxNum=1,SellPrice=100,AdventureSort=100004,Desc='主神奥丁曾使用过的武器，全名冈格尼尔，意为贯穿一切。它本身具有神性，任何对枪尖所发的誓言，都永不可反悔且必定实现。',NoSale=1,NoStorage=7,}",
  [40045] = "{id=40045,NameZh='月辉·奇星之矛',Icon='item_40045',Type=170,MaxNum=99,SellPrice=100,AdventureSort=100008,AdventureValue=1,Condition=8,Desc='暗月马戏团标志性的武器，因其式样低调而华丽又非常稀有，成为了年轻冒险家追捧的热门武器',LoadShowSize=0.8,LoadShowRotate=70,LoadShowPose={0,-0.35,0},}",
  [40046] = "{id=40046,NameZh='日耀·明心之矛',Icon='item_40046',Type=170,MaxNum=99,SellPrice=100,AdventureSort=100007,AdventureValue=1,Condition=8,Desc='太阳马戏团标志性的武器，耀眼的金光和精致的造型，是坚持爱与正义的冒险者所追寻的目标',LoadShowSize=0.8,LoadShowRotate=70,LoadShowPose={0,-0.35,0},}",
  [40047] = "{id=40047,NameZh='驯龙者长枪[1]',Icon='item_40047',Type=170,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=1000,AdventureValue=1,Condition=8,Desc='以传说中的龙骑士持有的长枪为原型而诞生武器，所以被冠上“驯龙者”的称谓。适合迅猛的突击，手感沉稳结实，是武器中不可多得的精品。“年轻人，拿上它去创造新的传说吧！”——某个传奇铁匠',Feature=1,LoadShowSize=0.9,LoadShowRotate=70,LoadShowPose={0,-0.3,0},}",
