  [40049] = "{id=40049,NameZh='碎雪·冰龙霜焰',Icon='item_40049',Type=170,MaxNum=99,SellPrice=100,AdventureSort=100009,AdventureValue=1,Condition=8,Desc='融合冰龙的霜冻吐息与魔力冰晶制作的长矛，每次刺出都如同冰龙吐出刺骨霜焰般威力无比。',LoadShowSize=0.8,LoadShowRotate=70,LoadShowPose={0,-0.3,0},}",
  [40050] = "{id=40050,NameZh='炎魂·红龙炽焰',Icon='item_40050',Type=170,MaxNum=99,SellPrice=100,AdventureSort=100010,AdventureValue=1,Condition=8,Desc='融合红龙的灼热吐息与火焰结晶制作的长矛，每次刺出都如同红龙吐出焚风龙焰般势不可挡。',LoadShowSize=0.8,LoadShowRotate=70,LoadShowPose={0,-0.3,0},}",
  [40051] = "{id=40051,NameZh='枫忆之矛',Icon='item_40051',Type=170,MaxNum=99,SellPrice=100,AdventureSort=100003,AdventureValue=1,Condition=8,Desc='红枫叶落地的一瞬间，就是它生命结束的时候，有消散就会有新生，亦或是秋天的馈赠，枫叶不见了，取而代之的是一把带着枫叶图案的长矛…',LoadShowSize=0.9,LoadShowRotate=70,LoadShowPose={0,-0.3,0},}",
  [40052] = "{id=40052,NameZh='信仰之矛',Icon='item_40052',Type=170,MaxNum=99,SellPrice=100,AdventureSort=100005,AdventureValue=1,Condition=8,Desc='巴风特曾带领手下对梦罗克进行过一次史无前例的大侵袭，这次的战争造成了数以万计的民众伤亡，在危难的关头有十四位勇士站了出来，他们牺牲了自己保护了梦罗克，死后的他们留下了自己的武器，这些武器被梦罗克的人们当做信仰的象征，这把长矛便是十四把武器的复制品之一。',LoadShowSize=0.9,LoadShowRotate=70,LoadShowPose={0,-0.1,0},}",
  [40053] = "{id=40053,NameZh='亡灵长矛',Icon='item_40053',Type=170,MaxNum=99,SellPrice=2100,AdventureValue=1,Condition=8,Desc='这把长矛带着亡灵的怨念，请戴上手套使用它。',Level=95,LoadShowSize=0.9,LoadShowRotate=70,LoadShowPose={0,-0.3,0},}",
  [40054] = "{id=40054,NameZh='埃琉德尼尔冥魂枪',Icon='item_40054',Type=170,MaxNum=99,SellPrice=100,AdventureSort=100012,AdventureValue=1,Condition=8,Desc='那位大人能够统治死者之都这么久，靠的可不是可爱的外貌和善解人意的性格，记清楚了！',TFValidDate='2019-10-28 05:00:00',ValidDate='2019-10-31 05:00:00',LoadShowSize=0.8,LoadShowRotate=70,LoadShowPose={0,-0.25,0},}",
