  [40061] = "{id=40061,NameZh='生命体长矛',Icon='item_40061',Type=170,MaxNum=99,SellPrice=2400,Desc='雷根贝勒公司所开发的，以生命体为能量的长矛。攻击时会剥夺敌人的生命力。',Level=100,}",
  [40062] = "{id=40062,NameZh='魔器·艾利欧格',Icon='item_40062',Type=170,MaxNum=99,SellPrice=100,AdventureSort=100011,AdventureValue=1,Condition=8,Desc='梦罗克碎片打造的禁忌武器，对应着异世界恶魔No.15·艾利欧格，手执长枪与旗帜，随意操控战士们的意志。',LoadShowSize=0.8,LoadShowRotate=70,LoadShowPose={0,-0.35,0},}",
  [40063] = "{id=40063,NameZh='朗基努斯之枪',Icon='item_40063',Type=170,MaxNum=99,SellPrice=100,AdventureSort=100013,AdventureValue=1,Condition=8,Desc='具有巨大的力量，能刺穿绝对领域。',Feature=1,LoadShowSize=0.8,LoadShowRotate=70,LoadShowPose={0,-0.3,0},}",
  [40064] = "{id=40064,NameZh='破晓',Icon='item_40064',Type=170,MaxNum=99,SellPrice=100,AdventureSort=100013,AdventureValue=1,Condition=8,Desc='击穿旧时代的虚壳，迎接新世纪的破晓吧......',Feature=1,LoadShowSize=0.85,LoadShowRotate=70,LoadShowPose={0,-0.35,0},}",
  [40065] = "{id=40065,NameZh='银锋长枪[1]',Icon='item_40065',Type=170,MaxNum=99,SellPrice=100,Desc='这一抹银白将会是敌人眼中最后的风景。',}",
  [40066] = "{id=40066,NameZh='修尔特长矛★[1]',Icon='item_40066',Type=170,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='上头有着弯刃的长矛，除了刺击之外也可以砍杀的长矛。',LoadShowSize=1,LoadShowRotate=70,LoadShowPose={0,-0.4,0},}",
  [40067] = "{id=40067,NameZh='科学救赎·长矛',Icon='item_40067',Type=170,MaxNum=99,SellPrice=100,AdventureSort=100014,AdventureValue=1,Condition=8,Desc='科学！科学！科学！为了科学一切的牺牲都是值得，蝼蚁们的生命本就毫无价值，因实验而死的他们应该觉得骄傲，这是他们的宿命！快了！就快了，我要用这把长矛刺穿反抗者的头颅，听着它们的求饶与哀嚎，啊~那可真美妙。',Feature=1,LoadShowSize=0.8,LoadShowPose={0,-0.35,0},}",
  [40069] = "{id=40069,NameZh='圣息崇聆·长矛',Icon='item_40069',Type=170,MaxNum=99,SellPrice=100,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='光与天空，圣洁的飞鸟，神的双翼已然张开，吾虔诚的信徒，愿你在吾的庇佑下体验幸福与美好，你的灵魂之音，吾等已经听到，这根圣矛赐予你，神祇永远与你同在。',LoadShowSize=0.8,LoadShowRotate=70,LoadShowPose={0,-0.3,0},}",
  [40070] = "{id=40070,NameZh='辉光十字·长矛',Icon='item_40070',Type=170,MaxNum=99,SellPrice=2600,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='这根长矛出自阿卢纳贝兹教国最有名的工匠——索罗克之手，他搜寻了整个教国寻找制作武器的材料，最终在圣域神殿的地下深处寻到了结果，吸取神灵信仰的矿石坚硬无比，制成的武器更是消灭黑暗的破晓之力。',Level=110,LoadShowSize=0.8,LoadShowRotate=70,LoadShowPose={0,-0.3,0},}",
  [40071] = "{id=40071,NameZh='蔷薇灵语之矛',Icon='item_40071',Type=170,MaxNum=99,SellPrice=3200,AdventureSort=1000,AdventureValue=1,Condition=8,Desc='这杆长矛被妖精一族的“灵语师”赋予了蔷薇的祝福。持有它的勇者将被视作守护妖精一族的骑士，受到妖精的尊重。',Level=110,LoadShowSize=1,LoadShowRotate=-90,LoadShowPose={0,-0.25,0},}",
  [40072] = "{id=40072,NameZh='红鱼花铃·长矛',Icon='item_40072',Type=170,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='长了一身红色鳞片的金鱼呀，喜欢在湖底的水草里悠闲地打瞌睡。有人投食的话，也会慢悠悠地钻到水面上，不紧不慢地吃鱼食。如果它会衔着长矛游出水面，也不要惊讶，这是金鱼族的报答哟~',LoadShowSize=0.8,LoadShowRotate=70,LoadShowPose={0,-0.1,0},}",
  [40073] = "{id=40073,NameZh='湛蓝天光·长矛',Icon='item_40073',Type=170,MaxNum=99,SellPrice=2800,AdventureValue=1,Condition=8,Desc='阔大的云海之上透出湛蓝天光，晴空下的战士们振作起了精神。战斗的号角即将吹响，握紧这根长矛吧，它印证着你的忠诚，勇敢与希望。',Level=110,LoadShowSize=0.8,LoadShowRotate=70,LoadShowPose={0,-0.3,0},}",
  [40074] = "{id=40074,NameZh='天虹圣遗·矛',Icon='item_40074',Type=170,MaxNum=99,SellPrice=100,AdventureSort=100019,AdventureValue=1,Condition=8,Desc='浮空精灵收集彩虹桥碎片锻造的长矛，刺出时的虹光直贯天际，宛如彩虹桥再现。',LoadShowSize=1,LoadShowPose={0,-0.35,0},}",
  [40075] = "{id=40075,NameZh='月下祈者·矛',Icon='item_40075',Type=170,MaxNum=99,SellPrice=100,AdventureSort=1000,AdventureValue=1,Condition=8,Desc='冰封千年的陨铁，王国的工匠们用尽办法也无法将其熔铸，却因小学徒的一次失误暴露在月光下。那一刻奇迹发生，陨铁融化宛若水银般流转，在月光下散发耀眼星辉。\n此乃月光赐福之圣枪，执枪者当以月光之力，刺破长夜，迎来黎明！',LoadShowRotate=90,LoadShowPose={0,-1.1,-1.8},}",
  [40076] = "{id=40076,NameZh='英灵起点·矛[2]',Icon='item_40076',Type=170,Quality=2,MaxNum=99,SellPrice=100,Desc='克里图拉新生领到的初心武器，致敬英灵而铸上蓝金涂装。据说设计者是一名枪兵，在血战中幸存，但战友都被女武神带去英灵殿。于是他设计此枪，缅怀逝者，旨在传承英灵的气魄，也奠定了其他武器的设计风格。',NoStorage=5,LoadShowSize=1,LoadShowPose={0,-0.3,0},}",
  [40077] = "{id=40077,NameZh='英灵信标·矛[2]',Icon='item_40077',Type=170,Quality=3,MaxNum=99,SellPrice=100,Desc='这把枪是指引女武神降临、迎接英灵的道标。阵亡的勇士抱着它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,LoadShowSize=1,LoadShowPose={0,-0.3,0},}",
  [40078] = "{id=40078,NameZh='英灵羽证·矛[2]',Icon='item_40078',Type=170,Quality=3,MaxNum=99,SellPrice=100,Desc='英灵的证明。潜入学院的女武神在这把枪中注入了奥丁领域的魔力。枪长出了羽翼，好像落在湖面的水鸟之足。',NoStorage=5,LoadShowSize=1,LoadShowPose={0,-0.3,0},}",
  [40080] = "{id=40080,NameZh='远古回音·矛',Icon='item_40080',Type=170,MaxNum=99,SellPrice=3200,AdventureSort=100020,AdventureValue=1,Condition=8,Desc='铭刻着神秘纹样的矛，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,LoadShowSize=0.8,LoadShowPose={0,-0.15,0},}",
  [40082] = "{id=40082,NameZh='王国荣辉·矛',Icon='item_40082',Type=170,MaxNum=99,SellPrice=100,AdventureSort=100023,AdventureValue=1,Condition=8,Desc='效忠于王室的宫廷侍卫所持的长矛，其上绘有卢恩王家纹章。华丽的金色装饰，暗示这把长矛的艺术价值远高于实用价值。',LoadShowSize=1.2,LoadShowRotate=90,LoadShowPose={0,-0.25,0},}",
  [40086] = "{id=40086,NameZh='永恒之枪·极限',Icon='item_40086',Type=450,Quality=4,MaxNum=1,SellPrice=100,Desc='主神奥丁曾使用过的武器，全名冈格尼尔，意为贯穿一切。它本身具有神性，任何对枪尖所发的誓言，都永不可反悔且必定实现。',NoSale=1,NoStorage=7,TFValidDate='2022-03-10 05:00:00',ValidDate='2022-03-23 05:00:00',}",
  [40087] = "{id=40087,NameZh='英灵信标·矛[2]',Icon='item_40077',Type=170,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=100024,AdventureValue=1,Condition=8,Desc='这把枪是指引女武神降临、迎接英灵的道标。阵亡的勇士抱着它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,LoadShowSize=1,LoadShowPose={0,-0.3,0},}",
  [40088] = "{id=40088,NameZh='英灵羽证·矛[2]',Icon='item_40078',Type=170,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=100025,AdventureValue=1,Condition=8,Desc='英灵的证明。潜入学院的女武神在这把枪中注入了奥丁领域的魔力。枪长出了羽翼，好像落在湖面的水鸟之足。',NoStorage=5,LoadShowSize=1,LoadShowPose={0,-0.3,0},}",
  [40089] = "{id=40089,NameZh='天启长矛[1]',Icon='item_40089',Type=170,Quality=4,MaxNum=99,SellPrice=100,Desc='拥有天启长矛的勇士往往是被神选中的人，无畏地冲锋，直到最后一刻！',LoadShowSize=0.6,}",
  [40301] = "{id=40301,NameZh='乐园团短剑',Icon='item_40301',Type=180,MaxNum=99,SellPrice=20,Desc='看起来任何人都可使用的剑。',Level=1,Feature=4,}",
