  [40306] = "{id=40306,NameZh='海东剑[1]',Icon='item_40306',Type=180,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=40,AdventureSort=2000,AdventureValue=1,Condition=8,Desc='在遥远的东方神秘岛国所制作出来的剑，不只杀伤用据说做人格修养时也可以使用。',Feature=1,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.2,0},}",
  [40307] = "{id=40307,NameZh='亚尔特剑',Icon='item_40307',Type=180,MaxNum=99,SellPrice=1080,Desc='不论什么砍杀或是刺杀时都很好使用的双手剑。',Level=90,Feature=4,}",
  [40308] = "{id=40308,NameZh='多刃尖刺刀[1]',Icon='item_40308',Type=180,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=241,AdventureSort=2000,AdventureValue=1,Condition=8,Desc='上头悬挂着好几把刀刃，攻击时能带给敌人多处伤口。',Feature=1,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.2,0},}",
  [40309] = "{id=40309,NameZh='骑兵之剑[2]',Icon='item_40301',Type=180,MaxNum=99,SellPrice=100,Desc='骑兵们专用的单手剑。不过使用于骑兵仪式方面较多。',Level=50,Feature=4,}",
  [40310] = "{id=40310,NameZh='水纹之剑[1]',Icon='item_40310',Type=180,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=11200,AdventureSort=2000,AdventureValue=1,Condition=8,Desc='剑刃上有着美丽水波花纹的剑。尽管有着美丽的外观，这把剑的杀伤力却出乎意料的强劲。',Feature=1,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.2,0},}",
  [40311] = "{id=40311,NameZh='狂击之剑[1]',Icon='item_40311',Type=180,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=121,AdventureSort=2000,AdventureValue=1,Condition=8,Desc='是船员们经常使用的剑。',Feature=1,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.2,0},}",
  [40312] = "{id=40312,NameZh='寻宝之剑[2]',Icon='item_40301',Type=180,MaxNum=99,SellPrice=100,Desc='透明又漂亮的刀刃，为独特的剑，感觉上杀掉魔物之后，会掉落很漂亮的东西。',Level=10,Feature=4,}",
  [40313] = "{id=40313,NameZh='铂金_弯刀[2]',Icon='item_40301',Type=180,MaxNum=99,SellPrice=100,Desc='为避开防具而设计成半圆形，拥有独特的型态。',Level=10,Feature=4,}",
  [40314] = "{id=40314,NameZh='生鱼片刀[1]',Icon='item_40314',Type=180,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=75,AdventureSort=2000,AdventureValue=1,Condition=8,Desc='苗条的刀刃，切成生鱼片非常适合的刀。鱼类面对这刀时，会产生恐惧感。',Feature=1,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.2,0},}",
  [40315] = "{id=40315,NameZh='水灵之剑[2]',Icon='item_40301',Type=180,MaxNum=99,SellPrice=100,Desc='拥有水的力量，有着蓝色刀身的刀。',Level=10,Feature=4,}",
  [40316] = "{id=40316,NameZh='火灵之剑[2]',Icon='item_40301',Type=180,MaxNum=99,SellPrice=100,Desc='拥有火的力量，有着红色剑身。',Level=10,Feature=4,}",
  [40317] = "{id=40317,NameZh='秘剑眷恋[1]',Icon='item_40317',Type=180,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=225,AdventureSort=2000,AdventureValue=1,Condition=8,Desc='制作者的名字已经不可考。采用古法锻造，比起兵器更像是件艺术品。',Feature=1,LoadShowSize=1.1,LoadShowRotate=70,LoadShowPose={0,-0.25,0},}",
  [40318] = "{id=40318,NameZh='烈阳之剑[2]',Icon='item_40301',Type=180,MaxNum=99,SellPrice=100,Desc='画有太阳模样的剑。拥有强韧的生命力以及战斗倾向。',Level=10,Feature=4,}",
  [40319] = "{id=40319,NameZh='神圣复仇者[1]',Icon='item_40319',Type=180,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=14960,AdventureSort=2000,AdventureValue=1,Condition=8,Desc='拥有神圣的神的惩罚，可以攻击敌人的神之剑。',Feature=1,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.2,0},}",
  [40320] = "{id=40320,NameZh='妖剑弑光[1]',Icon='item_40320',Type=250,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=38200,AdventureSort=4000,AdventureValue=1,Condition=8,Desc='传说中杀死光之神的武器，诡异可怖的剑刃散发着不详的妖气。',Feature=4,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.2,0},}",
  [40321] = "{id=40321,NameZh='魔刀吞神[2]',Icon='item_40301',Type=180,MaxNum=99,SellPrice=100,Desc='会为使用者带来不幸的魔剑。',Level=10,Feature=4,}",
  [40322] = "{id=40322,NameZh='名刀不知火[1]',Icon='item_40322',Type=180,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=872,AdventureSort=2000,AdventureValue=1,Condition=8,Desc='蕴含着邪恶气息，被称之为妖刀的刀 ，不过他的威力不可被忽视。 ',Feature=1,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.2,0},}",
  [40323] = "{id=40323,NameZh='圣剑混沌[2]',Icon='item_40301',Type=180,MaxNum=99,SellPrice=100,Desc='有形似无形的念力属性剑。可以扰乱敌人的精神。',Level=10,Feature=4,}",
  [40324] = "{id=40324,NameZh='元素之剑[2]',Icon='item_40301',Type=180,MaxNum=99,SellPrice=100,Desc='蕴含着4大属性力量的魔法剑。可以对无属性的敌人造成很强的伤害。',Level=10,Feature=4,}",
  [40325] = "{id=40325,NameZh='石中剑[2]',Icon='item_40301',Type=180,MaxNum=99,SellPrice=100,Desc='插在石头上的剑。会自我选择持有者，且拥有神圣的力量。',Level=10,Feature=4,}",
  [40326] = "{id=40326,NameZh='神器三十二朔月[2]',Icon='item_40301',Type=180,MaxNum=99,SellPrice=100,Desc='英雄基克布利，所使用过的双手巨剑。',Level=10,Feature=4,}",
  [40327] = "{id=40327,NameZh='红莲[2]',Icon='item_40301',Type=180,MaxNum=99,SellPrice=100,Desc='东方的某国利用陨落之石与九天玄冰所打造的用于祭奉天神的宝剑。',Level=10,Feature=4,}",
  [40328] = "{id=40328,NameZh='弯刀(删除)',Icon='item_40301',Type=180,MaxNum=99,SellPrice=100,Desc='刀刃适当的弯曲，适合砍杀任何东西。',Level=40,}",
  [40329] = "{id=40329,NameZh='日本刀',Icon='item_40301',Type=180,MaxNum=99,SellPrice=100,Desc='非常恐怖且尖锐的剑，是专门用来伤害敌方时使用。',Level=50,}",
  [40330] = "{id=40330,NameZh='厚刃剑',Icon='item_40330',Type=180,MaxNum=99,SellPrice=420,Desc='有着厚刃的剑，用处很广泛。 ',Level=30,}",
  [40331] = "{id=40331,NameZh='击刺长剑',Icon='item_40331',Type=180,MaxNum=99,SellPrice=600,Desc='有着细长刃的剑，专门做刺穿用。',Level=50,}",
  [40332] = "{id=40332,NameZh='合金剑',Icon='item_40332',Type=180,MaxNum=99,SellPrice=720,Desc='用特殊的炼金配方将好几种常规金属融合而成的新型材质制成的剑。',Level=60,}",
  [40333] = "{id=40333,NameZh='军用长剑',Icon='item_40333',Type=180,MaxNum=99,SellPrice=840,Desc='经历了多次战争不断修改设计并最终定型。重视实战效果的长剑。',Level=70,}",
  [40334] = "{id=40334,NameZh='制式长剑',Icon='item_40334',Type=180,MaxNum=99,SellPrice=960,Desc='专门为佣兵定制的厚刃剑。适应各种复杂环境。',Level=80,}",
  [40335] = "{id=40335,NameZh='杜兰达尔的幻影',Icon='item_40335',Type=180,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=100000,AdventureValue=1,Condition=8,Desc='剑原本的名字为“杜兰达尔”，后因主人弑神，剑身浸透了神的血，从而魔化为“弑神者”之剑。剑上寄宿着杜兰达尔的力量，但却被“弑神者”这股邪恶的力量封印着。剑的本尊不知所踪，此为剑灵的幻影，可被杜兰达尔的后继者继承。（建议作为武器外观使用）',Feature=1,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.3,0},}",
  [40336] = "{id=40336,NameZh='盟约·烈光',Icon='item_40336',Type=180,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=100001,AdventureValue=1,Condition=8,Desc='这把剑最初是施密特国王的随身佩剑。“白骑士团远征”之时，海因里希的剑断裂，施密特就将自己的剑赠予他，希望他继续用这把剑守护施密特王朝，就像这把剑曾经一直守护着施密特一样。海因里希致死，都坚守着他接过【盟约·烈光】时对国王的宣誓。（建议作为武器外观使用）',Feature=1,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.18,0},}",
  [40337] = "{id=40337,NameZh='星界·流光裁决',Icon='item_40337',Type=180,MaxNum=99,AuctionPrice=1,SellPrice=79600,AdventureSort=100002,AdventureValue=1,Condition=8,Desc='利用星辰中提炼出的珍贵矿石制作而成，剑身通体闪耀星辰之光，上面流转的光晕更是给人一股危险的气息。',Feature=1,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.25,0},}",
  [40338] = "{id=40338,NameZh='十字军佩剑',Icon='',Type=180,MaxNum=99,SellPrice=100,}",
  [40339] = "{id=40339,NameZh='深红圣剑',Icon='',Type=180,MaxNum=99,SellPrice=100,}",
  [40340] = "{id=40340,NameZh='英灵·赫萝克之剑',Icon='item_40340',Type=180,MaxNum=99,SellPrice=100,AdventureSort=100006,AdventureValue=1,Condition=8,Desc='武器搜集神——赫萝克众多收藏中最强大的一柄长剑，对英灵殿有足够的贡献才能获得神的赏赐，只有最强大的战士才配拥有这份荣耀。',Feature=1,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.2,0},}",
  [40341] = "{id=40341,NameZh='圣徒长剑[1]',Icon='item_40341',Type=180,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='圣歌教会著名的骑士团——神之光辉骑士团所配备的制式长剑，拥有极其优秀的攻击力，这个长剑还有个极其重要的特点：那就是信仰越虔诚，长剑就会越锋利。受到光明圣徒的祝福，安全精炼时消耗的装备件数减少一半。',Feature=1,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.2,0},}",
  [40342] = "{id=40342,NameZh='衔尾者长剑',Icon='item_40342',Type=180,MaxNum=99,SellPrice=100,AdventureSort=100004,AdventureValue=1,Condition=8,Desc='受诅咒的弑蛇长剑，剑柄的倒钩如同蛇尾般散发着危险气息。',Feature=1,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.17,0},}",
  [40343] = "{id=40343,NameZh='高级乐园团长剑[1]',Icon='item_40302',Type=180,MaxNum=99,SellPrice=100,Level=1,NoStorage=5,}",
  [40344] = "{id=40344,NameZh='圣灵·赫萝克之断陨剑',Icon='item_40344',Type=180,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='武器搜集神——赫萝克的武器，见识过无数武器的他，最终认为这把剑才是自己的归宿。',Feature=1,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.2,0},}",
  [40345] = "{id=40345,NameZh='纳西之剑',Icon='item_40307',Type=180,MaxNum=99,SellPrice=1140,Desc='人王纳西曾用于圣战之中的长剑，曾斩断过无数魔物的首级。',Level=95,}",
  [40346] = "{id=40346,NameZh='卡仑之牙[1]',Icon='item_40346',Type=250,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=4000,AdventureValue=1,Condition=8,Desc='冰狼卡仑只在成年后才会换牙，而新牙的第一颗将凝聚最纯粹的冰霜魔力，只有这颗牙，才有资格制成冠以卡仑之名的短剑。',Feature=1,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.17,0},}",
  [40347] = "{id=40347,NameZh='提尔锋',Icon='item_40347',Type=451,Quality=4,MaxNum=1,SellPrice=100,Desc='主神奥丁的孙子斯瓦弗尔，以杀死侏儒威胁他们打造了这柄旷世魔剑，然而侏儒怨恨斯瓦弗尔的霸道，悄悄在剑上刻下了致命的诅咒…',NoSale=1,NoStorage=7,}",
  [40348] = "{id=40348,NameZh='提尔锋·精锻',Icon='item_40348',Type=451,Quality=4,MaxNum=1,SellPrice=100,Desc='主神奥丁的孙子斯瓦弗尔，以杀死侏儒威胁他们打造了这柄旷世魔剑，然而侏儒怨恨斯瓦弗尔的霸道，悄悄在剑上刻下了致命的诅咒…',NoSale=1,NoStorage=7,}",
  [40349] = "{id=40349,NameZh='提尔锋·神铸',Icon='item_40349',Type=451,Quality=4,MaxNum=1,SellPrice=100,Desc='主神奥丁的孙子斯瓦弗尔，以杀死侏儒威胁他们打造了这柄旷世魔剑，然而侏儒怨恨斯瓦弗尔的霸道，悄悄在剑上刻下了致命的诅咒…',NoSale=1,NoStorage=7,}",
  [40350] = "{id=40350,NameZh='月辉·银光之剑',Icon='item_40350',Type=180,MaxNum=99,SellPrice=100,AdventureSort=100008,AdventureValue=1,Condition=8,Desc='暗月马戏团标志性的武器，因其式样低调而华丽又非常稀有，成为了年轻冒险家追捧的热门武器',LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.17,0},}",
  [40351] = "{id=40351,NameZh='日耀·天武之剑',Icon='item_40351',Type=180,MaxNum=99,SellPrice=100,AdventureSort=100007,AdventureValue=1,Condition=8,Desc='太阳马戏团标志性的武器，耀眼的金光和精致的造型，是坚持爱与正义的冒险者所追寻的目标',LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.17,0},}",
  [40352] = "{id=40352,NameZh='守备军长剑',Icon='item_40307',Type=180,MaxNum=99,SellPrice=2000,Level=90,}",
  [40353] = "{id=40353,NameZh='碎雪·白王冰刃',Icon='item_40353',Type=180,MaxNum=99,SellPrice=100,AdventureSort=100009,AdventureValue=1,Condition=8,Desc='传说中冻土剑士白王的武器，千年玄冰打造的剑身在魔焰中都维持着绝对零度，被它砍中的一切都会冰封冻结。',LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.17,0},}",
  [40354] = "{id=40354,NameZh='炎魂·红王炙刃',Icon='item_40354',Type=180,MaxNum=99,SellPrice=100,AdventureSort=100010,AdventureValue=1,Condition=8,Desc='传说中地狱剑士红王的武器，熔岩结晶打造的剑身在玄冰中都维持着绝对炙热，被它砍中的一切都会燃烧殆尽。',LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.17,0},}",
  [40355] = "{id=40355,NameZh='枫忆长剑',Icon='item_40355',Type=180,MaxNum=99,SellPrice=100,AdventureSort=100003,AdventureValue=1,Condition=8,Desc='他说枫叶落下之时就是他凯旋而归之日，少女抚摸着枫叶，思念着远方的人，不知不觉的趴在桌子上睡着了，少女再次醒来的时候，枫叶消失了，取而代之的是他的佩剑…',LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.17,0},}",
  [40356] = "{id=40356,NameZh='信仰长剑',Icon='item_40356',Type=180,MaxNum=99,SellPrice=100,AdventureSort=100005,AdventureValue=1,Condition=8,Desc='巴风特曾带领手下对梦罗克进行过一次史无前例的大侵袭，这次的战争造成了数以万计的民众伤亡，在危难的关头有十四位勇士站了出来，他们牺牲了自己保护了梦罗克，死后的他们留下了自己的武器，这些武器被梦罗克的人们当做信仰的象征，这把长剑便是十四把武器之一。',LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.17,0},}",
  [40357] = "{id=40357,NameZh='亡灵长剑',Icon='item_40357',Type=180,MaxNum=99,SellPrice=2100,AdventureValue=1,Condition=8,Desc='骑士亡魂在死后仍不愿舍弃伴随他一生的长剑。',Level=95,LoadShowSize=1,LoadShowRotate=70,LoadShowPose={0,-0.2,0},}",
  [40358] = "{id=40358,NameZh='埃琉德尼尔鬼灵剑',Icon='item_40358',Type=180,MaxNum=99,SellPrice=100,AdventureSort=100012,AdventureValue=1,Condition=8,Desc='冥河的水对于鬼魂是剧毒，而对那位大人来说就是甜美的蜜糖，没错，这把用冥河水打造的剑就是那位大人夏日消暑的冰棒。',TFValidDate='2019-10-28 05:00:00',ValidDate='2019-10-31 05:00:00',LoadShowSize=1.1,LoadShowRotate=70,LoadShowPose={0,-0.22,0},}",
  [40359] = "{id=40359,NameZh='多刃尖刺刀★[1]',Icon='item_40359',Type=180,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=2000,AdventureValue=1,Condition=8,Desc='上头悬挂着好几把刀刃，攻击时能带给敌人多处伤口。',Feature=1,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.2,0},}",
  [40360] = "{id=40360,NameZh='神圣复仇者★[1]',Icon='item_40360',Type=180,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=2000,AdventureValue=1,Condition=8,Desc='拥有神圣的神的惩罚，可以攻击敌人的神之剑。',Feature=1,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.2,0},}",
  [40361] = "{id=40361,NameZh='水纹之剑★[1]',Icon='item_40361',Type=180,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=2000,AdventureValue=1,Condition=8,Desc='剑刃上有着美丽水波花纹的剑。尽管有着美丽的外观，这把剑的杀伤力却出乎意料的强劲。',Feature=1,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.2,0},}",
  [40362] = "{id=40362,NameZh='暗剑士长剑[1]',Icon='item_40332',Type=180,MaxNum=99,SellPrice=720,Desc='用特殊的炼金配方将好几种常规金属融合而成的新型材质制成的剑。',Level=60,}",
  [40363] = "{id=40363,NameZh='生命体长剑',Icon='item_40363',Type=180,MaxNum=99,SellPrice=2400,Desc='雷根贝勒公司所开发的，以生命体为能量的长剑。能量粒子组成的剑刃十分锋利。',Level=100,}",
  [40364] = "{id=40364,NameZh='魔器·布提斯',Icon='item_40364',Type=180,MaxNum=99,SellPrice=100,AdventureSort=100011,AdventureValue=1,Condition=8,Desc='梦罗克碎片打造的禁忌武器，对应着异世界恶魔No.17·布提斯，它的形象是一条丑陋的毒蛇，偶尔他会呈现人形，手执号角与利刃。',LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.2,0},}",
  [40365] = "{id=40365,NameZh='弧光',Icon='item_40365',Type=180,MaxNum=99,SellPrice=100,AdventureSort=100013,AdventureValue=1,Condition=8,Desc='“剑气”已经过时了，现在我们追寻的是“弧光”！',Feature=1,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.2,0},}",
  [40366] = "{id=40366,NameZh='黑铁大剑[1]',Icon='item_40366',Type=180,MaxNum=99,SellPrice=100,Desc='你的敌人是这把大剑最喜欢的磨刀石。',}",
  [40367] = "{id=40367,NameZh='科学救赎·长剑',Icon='item_40367',Type=180,MaxNum=99,SellPrice=100,AdventureSort=100014,AdventureValue=1,Condition=8,Desc='科学！科学！科学！为了科学一切的牺牲都是值得，蝼蚁们的生命本就毫无机制，因实验而死的他们应该觉得骄傲，这是他们的宿命！快了！就快了，只要这把长剑制作出来，那些人就会知道我弗兰肯才是站在顶端的人！',Feature=1,LoadShowSize=1,LoadShowPose={0,-0.25,0},}",
  [40370] = "{id=40370,NameZh='初心者长剑[1]',Icon='item_40370',Type=180,Quality=2,MaxNum=99,SellPrice=100,Desc='乐园团为下定决心的初心者们特意准备的武器，锋利且耐用。',Feature=1,}",
  [40371] = "{id=40371,NameZh='圣息崇聆·长剑',Icon='item_40371',Type=180,MaxNum=99,SellPrice=100,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='光与天空，圣洁的飞鸟，神的双翼已然张开，吾虔诚的信徒，愿你在吾的庇佑下体验幸福与美好，你的灵魂之音，吾等已经听到，这把长剑赐予你，神祇永远与你同在。',LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.2,0},}",
  [40372] = "{id=40372,NameZh='辉光十字·长剑',Icon='item_40372',Type=180,MaxNum=99,SellPrice=2600,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='这柄长剑出自阿卢纳贝兹教国最有名的工匠——索罗克之手，他搜寻了整个教国寻找制作武器的材料，最终在圣域神殿的地下深处寻到了结果，吸取神灵信仰的矿石坚硬无比，制成的武器更是消灭黑暗的破晓之力。',Level=110,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.2,0},}",
  [40373] = "{id=40373,NameZh='红莲[1]',Icon='item_40373',Type=180,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=31200,AdventureSort=2000,AdventureValue=1,Condition=8,Desc='日出东方之国利用日落之石与寒天之冰所打造之祭奉天神之剑。',LoadShowSize=1,LoadShowRotate=70,LoadShowPose={0,-0.2,0},}",
  [40374] = "{id=40374,NameZh='蔷薇灵语之剑',Icon='item_40374',Type=180,MaxNum=99,SellPrice=3200,AdventureSort=2000,AdventureValue=1,Condition=8,Desc='这柄宝剑被妖精一族的“灵语师”赋予了蔷薇的祝福。唯有妖精们认可的高贵之人才能发挥它的力量。',Level=110,LoadShowSize=1.2,LoadShowRotate=90,LoadShowPose={0,-0.25,0},}",
  [40375] = "{id=40375,NameZh='红鱼花铃·长剑',Icon='item_40375',Type=180,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='长了一身红色鳞片的金鱼呀，喜欢在湖底的水草里悠闲地打瞌睡。有人投食的话，也会慢悠悠地钻到水面上，不紧不慢地吃鱼食。如果它会衔着长剑游出水面，也不要惊讶，这是金鱼族的报答哟~',LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.17,0},}",
  [40376] = "{id=40376,NameZh='黑炎剑[1]',Icon='item_40376',Type=180,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=2000,AdventureValue=1,Condition=8,Desc='漆黑剑士所使用的武器，蕴含着无尽的黑暗力量，使用者是否会被吞噬仍是个未知数。',LoadShowSize=1.5,LoadShowRotate=50,LoadShowPose={0,-0.36,0},}",
  [40377] = "{id=40377,NameZh='死寂月光',Icon='item_40377',Type=180,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='以死亡为名所封印的魔剑，其利刃沐浴在月光下，闪耀出一段血色的舞蹈。',LoadShowSize=1,LoadShowRotate=70,LoadShowPose={0,-0.2,0},}",
  [40378] = "{id=40378,NameZh='克拉肯之牙',Icon='item_40378',Type=180,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='以巨兽克拉肯为名的魔剑。“它战栗，狂欢，只为那末日的黄昏。”',LoadShowSize=1,LoadShowRotate=70,LoadShowPose={0,-0.2,0},}",
  [40379] = "{id=40379,NameZh='沉默梦魇',Icon='item_40379',Type=180,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='凝聚众生悲叹之音的魔剑。自深渊中呼啸，也随死亡而沉眠。',LoadShowSize=1,LoadShowRotate=70,LoadShowPose={0,-0.2,0},}",
  [40380] = "{id=40380,NameZh='湛蓝天光·长剑',Icon='item_40380',Type=180,MaxNum=99,SellPrice=2800,AdventureValue=1,Condition=8,Desc='阔大的云海之上透出湛蓝天光，晴空下的战士们振作起了精神。战斗的号角即将吹响，握紧这把长剑吧，它印证着你的忠诚，勇敢与希望。',Level=110,LoadShowSize=1,LoadShowRotate=70,LoadShowPose={0,-0.2,0},}",
  [40381] = "{id=40381,NameZh='天虹圣遗·长剑',Icon='item_40381',Type=180,MaxNum=99,SellPrice=100,AdventureSort=100019,AdventureValue=1,Condition=8,Desc='浮空精灵收集彩虹桥碎片锻造的长剑，传说中能呼唤彩虹的圣剑，虹光将引领你走向胜利！',LoadShowSize=1.2,}",
  [40382] = "{id=40382,NameZh='烈焰剑[1]',Icon='item_40382',Type=180,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='据说这把剑中潜藏着烈火的力量，使用它的人会获得火焰的祝福。',LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [40383] = "{id=40383,NameZh='苍炎剑[1]',Icon='item_40376',Type=180,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='断裂的烈焰剑，在苍炎中重生，唯有真正的勇士才能不被它的温度灼伤。',LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [40384] = "{id=40384,NameZh='月下祈者·长剑',Icon='item_40384',Type=180,MaxNum=99,SellPrice=100,AdventureSort=100021,AdventureValue=1,Condition=8,Desc='冰封千年的陨铁，王国的工匠们用尽办法也无法将其熔铸，却因小学徒的一次失误暴露在月光下。那一刻奇迹发生，陨铁融化宛若水银般流转，在月光下散发耀眼星辉。\n此乃月光赐福之神剑，持剑者当以月光之力，斩破荆棘，驱散邪恶！',LoadShowRotate=90,LoadShowPose={0.5,-1,-1.2},}",
  [40385] = "{id=40385,NameZh='名刀不知火·忍者[1]',Icon='item_40322',Type=180,Quality=3,MaxNum=99,SellPrice=872,Condition=8,Desc='蕴含着邪恶气息，被称之为妖刀的刀 ，不过他的威力不可被忽视。 啸霏专用',Feature=1,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.2,0},}",
  [40386] = "{id=40386,NameZh='英灵起点·长剑[2]',Icon='item_40386',Type=180,Quality=3,MaxNum=99,SellPrice=100,Desc='克里图拉新生领到的初心武器，致敬英灵而铸上蓝金涂装。设计者是达尔克，它的内侧镶嵌了初心者也不会烫手的安全符文。',NoStorage=5,LoadShowSize=1,}",
  [40387] = "{id=40387,NameZh='英灵信标·长剑[2]',Icon='item_40387',Type=180,Quality=3,MaxNum=99,SellPrice=100,Desc='这把剑是指引女武神降临、迎接英灵的道标。阵亡的勇士抱着它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,LoadShowSize=1,}",
  [40388] = "{id=40388,NameZh='英灵羽证·长剑[2]',Icon='item_40388',Type=180,Quality=3,MaxNum=99,SellPrice=100,Desc='英灵的证明。潜入学院的女武神在大剑中注入了奥丁领域的魔力。剑长出了羽翼，像是一把悬在头顶的制裁之刃。',NoStorage=5,LoadShowSize=1,}",
  [40389] = "{id=40389,NameZh='龙神之剑[1]',Icon='item_40371',Type=180,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='龙神之力，与米德加尔特大陆的高端工艺完美结合，最终铸成了这把如同艺术品般的宝剑。',LoadShowSize=1.35,LoadShowRotate=-90,LoadShowPose={0,-0.35,0},}",
  [40390] = "{id=40390,NameZh='龙王之剑[1]',Icon='item_40356',Type=180,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='龙王之力的灌注造就了这把战无不胜的龙王之剑。',LoadShowSize=1.35,LoadShowRotate=-90,LoadShowPose={0,-0.35,0},}",
  [40391] = "{id=40391,NameZh='勇者之剑',Icon='item_40389',Type=180,Quality=3,MaxNum=99,SellPrice=100,Desc='来自异世界的宝剑，是小救星与龙神丸的重要媒介之一，可以激发龙神丸真正的力量。',LoadShowSize=1.35,LoadShowRotate=-90,LoadShowPose={0,-0.35,0},}",
  [40392] = "{id=40392,NameZh='王者之剑',Icon='item_40390',Type=180,Quality=3,MaxNum=99,SellPrice=100,Desc='勇者之剑断裂后，千人隐士集合炽热之剑和寒冰之剑的力量，将勇者之剑进阶为了王者之剑。',LoadShowSize=1.35,LoadShowRotate=-90,LoadShowPose={0,-0.35,0},}",
  [40394] = "{id=40394,NameZh='远古回音·长剑',Icon='item_40394',Type=180,MaxNum=99,SellPrice=3200,AdventureSort=100020,AdventureValue=1,Condition=8,Desc='铭刻着神秘纹样的长剑，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,LoadShowSize=1,}",
  [40396] = "{id=40396,NameZh='王国荣辉·长剑',Icon='item_40396',Type=180,MaxNum=99,SellPrice=100,AdventureSort=100023,AdventureValue=1,Condition=8,Desc='效忠于王室的宫廷侍卫所持的长剑，其上绘有卢恩王家纹章。但其观赏价值，远大于实用意义，通常作为一种荣耀的象征。',LoadShowSize=1.35,LoadShowRotate=90,LoadShowPose={0,-0.25,0},}",
  [40400] = "{id=40400,NameZh='提尔锋·极限',Icon='item_40400',Type=451,Quality=4,MaxNum=1,SellPrice=100,Desc='主神奥丁的孙子斯瓦弗尔，以杀死侏儒威胁他们打造了这柄旷世魔剑，然而侏儒怨恨斯瓦弗尔的霸道，悄悄在剑上刻下了致命的诅咒…',NoSale=1,NoStorage=7,TFValidDate='2022-03-10 05:00:00',ValidDate='2022-03-23 05:00:00',}",
