  [40627] = "{id=40627,NameZh='言灵魔杖',Icon='item_40627',Type=190,MaxNum=99,SellPrice=600,Desc='魔法师入门时常用的蕴含魔法力量的手杖。',Level=50,}",
  [40628] = "{id=40628,NameZh='合金长杖',Icon='item_40628',Type=190,MaxNum=99,SellPrice=720,Desc='用特殊的炼金配方将好几种常规金属融合而成的新型材质制成的长杖。',Level=60,}",
  [40629] = "{id=40629,NameZh='军用魔杖',Icon='item_40629',Type=190,MaxNum=99,SellPrice=840,Desc='经历了多次战争不断修改设计并最终定型。重视实战效果的魔杖。',Level=70,}",
  [40630] = "{id=40630,NameZh='制式法杖',Icon='item_40630',Type=190,MaxNum=99,SellPrice=960,Desc='专门为佣兵定制的橡木魔杖。适应各种复杂环境。',Level=80,}",
  [40631] = "{id=40631,NameZh='附魔长杖',Icon='item_40631',Type=190,MaxNum=99,SellPrice=1080,Desc='法杖上的魔法符文储存有增强佩戴者属性的次级魔法。因为是魔法学徒的作品所以相对一般魔法道具要廉价得多。',Level=90,}",
  [40633] = "{id=40633,NameZh='元素融合之杖[1]',Icon='item_40616',Type=190,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=492,AdventureSort=3000,AdventureValue=1,Condition=8,Desc='杖顶端的宝石内奇迹般的存储了多系元素魔法的力量。',Feature=1,LoadShowSize=1.2,LoadShowRotate=160,LoadShowPose={0,0.5,0},}",
  [40634] = "{id=40634,NameZh='仲裁者[1]',Icon='item_40634',Type=190,MaxNum=99,SellPrice=100,}",
  [40635] = "{id=40635,NameZh='光辉晨星',Icon='item_40635',Type=190,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=100001,AdventureValue=1,Condition=8,Desc='路西菲尔大法师的法杖，千年以前，他和托利斯坦大帝路过后来建立克雷斯特汉姆古城的这片废墟时，怜悯废墟中游荡的千万亡魂，于是用尽法杖全部力量，安抚了亡魂。之后，他用法杖的碎片筑起了光辉晨星修道院的第一块砖墙，法杖残余的力量长久以来镇压着修道院墓地中的幽魂。（建议作为武器外观使用）',Feature=1,LoadShowSize=1.2,LoadShowRotate=160,LoadShowPose={0,0.15,0},}",
  [40636] = "{id=40636,NameZh='星界·幻魔者',Icon='item_40636',Type=190,MaxNum=99,AuctionPrice=1,SellPrice=79600,AdventureSort=100002,AdventureValue=1,Condition=8,Desc='利用星辰中提炼出的珍贵矿石制作而成，强大的魔法适应性使得发出的魔法更加稳定，是法师的不二选择。',Feature=1,LoadShowSize=0.9,LoadShowRotate=160,LoadShowPose={0,0.25,0},}",
  [40637] = "{id=40637,NameZh='英灵·格恩之咏唱',Icon='item_40637',Type=190,MaxNum=99,SellPrice=100,AdventureSort=100006,AdventureValue=1,Condition=8,Desc='魔力持有神——格恩达尔的法杖，密密麻麻的卢恩符文镶嵌其上，使用这把武器可以是魔力得到一个质的飞跃，只有对英灵殿有足够贡献且得到格恩达尔的赏识的魔法修习者才能得到这份赏赐。',Feature=1,LoadShowSize=1.2,LoadShowRotate=160,LoadShowPose={0,0.3,0},}",
  [40638] = "{id=40638,NameZh='圣徒之杖[1]',Icon='item_40638',Type=190,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='吉芬魔法研究所与圣歌教会联合研究而出的新一代法杖，法杖拥有良好的魔导性，适合各个层面的魔法师。现在已经广泛装备于教会与吉芬魔法部队。受到光明圣徒的祝福，安全精炼时消耗的装备件数减少一半。',Feature=1,LoadShowSize=1.1,LoadShowRotate=160,LoadShowPose={0,0.2,0},}",
  [40639] = "{id=40639,NameZh='衔尾者轮回杖',Icon='item_40639',Type=190,MaxNum=99,SellPrice=100,AdventureSort=100004,AdventureValue=1,Condition=8,Desc='向黑暗与巨蛇借来的魔力，会让敌人永远徘徊在无尽的轮回中失去自我。',Feature=1,LoadShowSize=1.2,LoadShowRotate=160,LoadShowPose={0,0.05,0},}",
  [40640] = "{id=40640,NameZh='幻影流沙',Icon='item_40640',Type=190,MaxNum=99,SellPrice=100,AdventureSort=110000,AdventureValue=1,Condition=8,Desc='当你面对未来的自己时，你是否还认得“你”，流沙不会告诉你答案，无论你如何努力，它都会从你的手心轻轻散去，也许命运就是如此…',Feature=1,LoadShowSize=1,LoadShowRotate=160,LoadShowPose={0,0.35,0},}",
  [40641] = "{id=40641,NameZh='高级乐园团之杖[1]',Icon='item_40605',Type=190,MaxNum=99,SellPrice=100,Desc='为了保障初心冒险者们的冒险之旅，乐园团为此制造的最新制式法杖。',Level=1,NoStorage=5,}",
  [40642] = "{id=40642,NameZh='圣灵·格恩之颂魂歌',Icon='item_40642',Type=190,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='魔力持有神——格恩达尔的法杖，上面书写的古代卢恩文字拥有引动灵魂世界的力量。',Feature=1,LoadShowSize=1.2,LoadShowRotate=160,LoadShowPose={0,0.3,0},}",
  [40643] = "{id=40643,NameZh='古树法杖',Icon='item_40631',Type=190,MaxNum=99,SellPrice=1140,Desc='使用黑暗密林里最年长的神树枝干制成的法杖，看起来很像普通的木棍，实际上蕴含了充沛的魔法能量。',Level=95,}",
  [40644] = "{id=40644,NameZh='万神的注视',Icon='item_40644',Type=452,Quality=4,MaxNum=1,SellPrice=100,Desc='瓦尔哈拉神殿的长廊前，一万位女武神祈祷了千个昼夜，终于将四大元素的魔力完美糅合在一起，铸造出了这柄至高无上的法杖。',NoSale=1,NoStorage=7,}",
  [40645] = "{id=40645,NameZh='金枝',Icon='item_40645',Type=452,Quality=4,MaxNum=1,SellPrice=100,Desc='天地树每隔十万年才会生长出新的枝干，百万年才会在最高的树枝上开花一次。这柄金枝便是用世界树之花的枝打造，生来拥有创造生命的魔力。',NoSale=1,NoStorage=7,}",
