  [40651] = "{id=40651,NameZh='日耀·金虹法杖',Icon='item_40651',Type=190,MaxNum=99,SellPrice=100,AdventureSort=100007,AdventureValue=1,Condition=8,Desc='太阳马戏团标志性的武器，耀眼的金光和精致的造型，是坚持爱与正义的冒险者所追寻的目标',LoadShowSize=1.2,LoadShowRotate=160,LoadShowPose={0,0.05,0},}",
  [40652] = "{id=40652,NameZh='法力风暴之杖[1]',Icon='item_40652',Type=190,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=3000,AdventureValue=1,Condition=8,Desc='只有拥有庞大魔法能量者才能驱动的特殊魔杖，能将使用者的魔力充分化作力量，驾驭它是成为伟大法师的必修课。“在我的法力风暴面前，敌人会像落叶一样随风凋零。”——雷藏',Feature=1,LoadShowSize=1.2,LoadShowRotate=160,LoadShowPose={0,0.35,0},}",
  [40653] = "{id=40653,NameZh='守备军法杖',Icon='item_40653',Type=190,MaxNum=99,SellPrice=2000,Level=90,}",
  [40654] = "{id=40654,NameZh='碎雪·霜寒封影',Icon='item_40654',Type=190,MaxNum=99,SellPrice=100,AdventureSort=100009,AdventureValue=1,Condition=8,Desc='寄宿着寒冰元素魂魄的魔杖，冰魂核心是它强大魔力的源泉，是传说中米德加尔特最强冰霜魔导师使用的武器。',LoadShowSize=0.95,LoadShowRotate=160,LoadShowPose={0,0.05,0},}",
  [40655] = "{id=40655,NameZh='炎魂·异火焚影',Icon='item_40655',Type=190,MaxNum=99,SellPrice=100,AdventureSort=100010,AdventureValue=1,Condition=8,Desc='寄宿着火焰元素魂魄的魔杖，火魂核心是它强大魔力的源泉，是传说中米德加尔特最强火焰魔导师使用的武器。',LoadShowSize=0.95,LoadShowRotate=160,LoadShowPose={0,0.05,0},}",
  [40656] = "{id=40656,NameZh='枫忆法杖',Icon='item_40656',Type=190,MaxNum=99,SellPrice=100,AdventureSort=100003,AdventureValue=1,Condition=8,Desc='她说她来自枫之国，我问她那是哪里，她笑了笑说哪里是一个我不知道的地方。后悔那时的我为何没有追问下去，如果问了，现在是不是就不会一直看着她留下的法杖发呆了…',LoadShowSize=1.1,LoadShowRotate=70,LoadShowPose={0,0.2,0},}",
  [40657] = "{id=40657,NameZh='信仰法杖',Icon='item_40657',Type=190,MaxNum=99,SellPrice=100,AdventureSort=100005,AdventureValue=1,Condition=8,Desc='巴风特曾带领手下对梦罗克进行过一次史无前例的大侵袭，这次的战争造成了数以万计的民众伤亡，在危难的关头有十四位勇士站了出来，他们牺牲了自己保护了梦罗克，死后的他们留下了自己的武器，这些武器被梦罗克的人们当做信仰的象征，这枝法杖便是十四把武器之一。',LoadShowSize=0.9,LoadShowRotate=160,LoadShowPose={0,0.1,0},}",
  [40658] = "{id=40658,NameZh='亡灵法杖',Icon='item_40658',Type=190,MaxNum=99,SellPrice=2100,AdventureValue=1,Condition=8,Desc='虽然名字有点不吉利，但是这法杖用起来格外的顺手。',Level=95,LoadShowSize=1,LoadShowRotate=160,LoadShowPose={0,0,0},}",
