  [40670] = "{id=40670,NameZh='萤光[1]',Icon='item_40670',Type=190,MaxNum=99,SellPrice=100,Desc='点点萤火，便能在黑暗中带来希望；魔导之光，为你指明前进的方向。',}",
  [40671] = "{id=40671,NameZh='高等生存魔杖★[1]',Icon='item_40671',Type=190,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=3000,AdventureValue=1,Condition=8,Desc='为了苦行的修行者们，魔法师公会和教团所协力完成的手杖，有两种类型.',LoadShowSize=1.2,LoadShowRotate=160,LoadShowPose={0,0.4,0},}",
  [40672] = "{id=40672,NameZh='科学救赎·之杖',Icon='item_40672',Type=190,MaxNum=99,SellPrice=100,AdventureSort=100014,AdventureValue=1,Condition=8,Desc='科学！科学！科学！为了科学一切的牺牲都是值得，蝼蚁们的生命本就毫无价值，因实验而死的他们应该觉得骄傲，这是他们的宿命！快了！就快了，只要这根法杖制作出来，我就可以慢慢欣赏那些反抗者的哀嚎了~',Feature=1,LoadShowSize=1,}",
  [40674] = "{id=40674,NameZh='圣息崇聆·杖',Icon='item_40674',Type=190,MaxNum=99,SellPrice=100,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='光与天空，圣洁的飞鸟，神的双翼已然张开，吾虔诚的信徒，愿你在吾的庇佑下体验幸福与美好，你的灵魂之音，吾等已经听到，这根神杖赐予你，神祇永远与你同在。',LoadShowSize=0.9,LoadShowRotate=160,LoadShowPose={0,0.1,0},}",
  [40675] = "{id=40675,NameZh='辉光十字·杖',Icon='item_40675',Type=190,MaxNum=99,SellPrice=2600,AdventureSort=100015,AdventureValue=1,Condition=8,Level=110,LoadShowSize=0.9,LoadShowRotate=160,LoadShowPose={0,0.1,0},}",
  [40676] = "{id=40676,NameZh='精神手杖★[1]',Icon='item_40676',Type=190,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=3000,AdventureValue=1,Condition=8,Desc='强大的精神力是成为魔法师的基本素养。',Feature=1,LoadShowSize=0.9,LoadShowRotate=160,LoadShowPose={0,0.22,0},}",
  [40677] = "{id=40677,NameZh='蔷薇灵语之杖',Icon='item_40677',Type=190,MaxNum=99,SellPrice=3200,AdventureSort=3000,AdventureValue=1,Condition=8,Desc='这根法杖被妖精一族的“灵语师”赋予了蔷薇的祝福，它被妖精们视作引领者的象征，只有最具智慧的人才能拥有它。',Level=110,LoadShowSize=1,LoadShowPose={0,0.25,0},}",
  [40678] = "{id=40678,NameZh='红鱼花铃·杖',Icon='item_40678',Type=190,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='长了一身红色鳞片的金鱼呀，喜欢在湖底的水草里悠闲地打瞌睡。有人投食的话，也会慢悠悠地钻到水面上，不紧不慢地吃鱼食。如果它会衔着杖游出水面，也不要惊讶，这是金鱼族的报答哟~',LoadShowSize=1.2,LoadShowRotate=140,LoadShowPose={0,0.2,0},}",
  [40679] = "{id=40679,NameZh='波尔多之杖[1]',Icon='item_40679',Type=190,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=3000,AdventureValue=1,Condition=8,Desc='像指挥棒一样短又简洁的手杖, 镶着秩序之力量的宝石。',LoadShowSize=1,LoadShowRotate=50,LoadShowPose={0,0,0},}",
  [40680] = "{id=40680,NameZh='湛蓝天光·法杖',Icon='item_40680',Type=190,MaxNum=99,SellPrice=2800,AdventureValue=1,Condition=8,Desc='阔大的云海之上透出湛蓝天光，晴空下的战士们振作起了精神。战斗的号角即将吹响，握紧这根法杖吧，它印证着你的忠诚，勇敢与希望。',Level=110,LoadShowSize=1,LoadShowRotate=70,LoadShowPose={0,-0.1,0},}",
  [40681] = "{id=40681,NameZh='天虹圣遗·杖',Icon='item_40681',Type=190,MaxNum=99,SellPrice=100,AdventureSort=100019,AdventureValue=1,Condition=8,Desc='浮空精灵收集彩虹桥碎片制作的法杖，传说能够召唤彩虹的力量，化为自身的魔力。',LoadShowSize=1.2,}",
  [40682] = "{id=40682,NameZh='邪念的权杖[1]',Icon='item_40682',Type=190,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,LoadShowSize=1.25,LoadShowRotate=60,LoadShowPose={0,0.3,0},}",
  [40683] = "{id=40683,NameZh='月下祈者·杖',Icon='item_40683',Type=190,MaxNum=99,SellPrice=100,AdventureSort=3000,AdventureValue=1,Condition=8,Desc='冰封千年的陨铁，王国的工匠们用尽办法也无法将其熔铸，却因小学徒的一次失误暴露在月光下。那一刻奇迹发生，陨铁融化宛若水银般流转，在月光下散发耀眼星辉。\n此乃月光赐福之神杖，持此杖者当以月光之力，引导光明，照亮阴影！',LoadShowRotate=90,LoadShowPose={0.5,-0.2,-1.8},}",
  [40684] = "{id=40684,NameZh='英灵起点·法杖[2]',Icon='item_40684',Type=190,Quality=2,MaxNum=99,SellPrice=100,Desc='克里图拉新生领到的初心武器，致敬英灵而铸上蓝金涂装。据说设计者是卡尔瓦西。它的杖头是颗不明形体，投射出“假如世界是圆的”的谬论。经由求真的学生们最终证实，杖头的星球真实存在于宇宙中。',NoStorage=5,LoadShowSize=1.5,}",
  [40685] = "{id=40685,NameZh='英灵信标·法杖[2]',Icon='item_40685',Type=190,Quality=3,MaxNum=99,SellPrice=100,Desc='这把法杖是指引女武神降临、迎接英灵的道标。阵亡的勇士抱着它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,LoadShowSize=1.5,}",
  [40686] = "{id=40686,NameZh='英灵羽证·法杖[2]',Icon='item_40686',Type=190,Quality=3,MaxNum=99,SellPrice=100,Desc='英灵的证明。潜入学院的女武神在法杖中注入了奥丁领域的魔力。行星长出羽翼，就像宇宙的中心。',NoStorage=5,LoadShowSize=1.5,}",
  [40687] = "{id=40687,NameZh='咒言护手[1]',Icon='item_40687',Type=190,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='镶上了魔珠的白手套。它既可以增幅魔力，也可以隔绝躁动的魔能，在咏唱时保护好你的手指。',}",
  [40688] = "{id=40688,NameZh='混沌之手[1]',Icon='item_40688',Type=190,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='专用于混沌魔法的黑手套。装备升级后变成了混沌的黑色。漆黑色能阻绝光子，让破灭之力以最纯净的形式放出。',}",
  [40690] = "{id=40690,NameZh='远古回音·杖',Icon='item_40690',Type=190,MaxNum=99,SellPrice=3200,AdventureSort=100020,AdventureValue=1,Condition=8,Desc='铭刻着神秘纹样的法杖，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,LoadShowSize=1,}",
  [40692] = "{id=40692,NameZh='王国荣辉·杖',Icon='item_40692',Type=190,MaxNum=99,SellPrice=100,AdventureSort=100023,AdventureValue=1,Condition=8,Desc='效忠于王室的宫廷侍卫所持的法杖，其上绘有卢恩王家纹章。聪明的施法者，不会被它美丽的外表欺骗——彰显身份的玩具，可不适用于实战。',LoadShowSize=1.2,LoadShowRotate=90,}",
  [40696] = "{id=40696,NameZh='万神的注视·极限',Icon='item_40696',Type=452,Quality=4,MaxNum=1,SellPrice=100,Desc='瓦尔哈拉神殿的长廊前，一万位女武神祈祷了千个昼夜，终于将四大元素的魔力完美糅合在一起，铸造出了这柄至高无上的法杖。',NoSale=1,NoStorage=7,TFValidDate='2022-03-10 05:00:00',ValidDate='2022-03-23 05:00:00',}",
  [40697] = "{id=40697,NameZh='金枝·极限',Icon='item_40697',Type=452,Quality=4,MaxNum=1,SellPrice=100,Desc='天地树每隔十万年才会生长出新的枝干，百万年才会在最高的树枝上开花一次。这柄金枝便是用世界树之花的枝打造，生来拥有创造生命的魔力。',NoSale=1,NoStorage=7,TFValidDate='2022-03-10 05:00:00',ValidDate='2022-03-23 05:00:00',}",
  [40698] = "{id=40698,NameZh='英灵信标·法杖[2]',Icon='item_40685',Type=190,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=100024,AdventureValue=1,Condition=8,Desc='这把法杖是指引女武神降临、迎接英灵的道标。阵亡的勇士抱着它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,LoadShowSize=1.5,}",
  [40699] = "{id=40699,NameZh='英灵羽证·法杖[2]',Icon='item_40686',Type=190,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=100025,AdventureValue=1,Condition=8,Desc='英灵的证明。潜入学院的女武神在法杖中注入了奥丁领域的魔力。行星长出羽翼，就像宇宙的中心。',NoStorage=5,LoadShowSize=1.5,}",
  [40701] = "{id=40701,NameZh='短剑[2]',Icon='item_40701',Type=250,MaxNum=99,SellPrice=100,Desc='为了方便任何人使用所制作出来的短剑。',Level=10,Feature=4,}",
  [40702] = "{id=40702,NameZh='卡特短剑',Icon='item_40702',Type=250,MaxNum=99,SellPrice=140,Desc='专门为了割东西所制造出来的短剑。',Level=10,Feature=4,}",
  [40703] = "{id=40703,NameZh='宽柄短剑',Icon='item_40703',Type=250,MaxNum=99,SellPrice=280,Desc='以实用性为目的制作而成的多用途短剑。',Level=20,Feature=4,}",
  [40704] = "{id=40704,NameZh='长柄短剑',Icon='item_40704',Type=250,MaxNum=99,SellPrice=420,Desc='古代某个王国使用的长握柄短剑。剑身有点长的短剑。',Level=30,Feature=4,}",
  [40705] = "{id=40705,NameZh='大驹短剑',Icon='item_40705',Type=250,MaxNum=99,SellPrice=1080,Desc='将刀刃适当弯曲的短剑。',Level=90,Feature=4,}",
  [40706] = "{id=40706,NameZh='厚刃短剑',Icon='item_40706',Type=250,MaxNum=99,SellPrice=560,Desc='沙漠某部落流传下来的特殊炼法所制成的短剑。',Level=40,Feature=4,}",
  [40707] = "{id=40707,NameZh='双刃短剑',Icon='item_40707',Type=250,MaxNum=99,SellPrice=600,Desc='以刀刃实用为诉求，所制造出的双刃短剑。',Level=50,Feature=4,}",
  [40708] = "{id=40708,NameZh='合金短剑',Icon='item_40708',Type=250,MaxNum=99,SellPrice=720,Desc='感觉上可让你赚大钱，有着钱型符号刀刃的短剑。',Level=60,Feature=4,}",
  [40709] = "{id=40709,NameZh='军用短剑',Icon='item_40709',Type=250,MaxNum=99,SellPrice=840,Desc='以大马士革钢制成的短剑。反射光源时，可看到海浪纹，让人觉得很美。',Level=70,Feature=4,}",
  [40710] = "{id=40710,NameZh='制式短剑',Icon='item_40710',Type=250,MaxNum=99,SellPrice=960,Desc='专门为佣兵定制的双刃短剑。适应各种复杂环境。',Level=80,Feature=4,}",
  [40711] = "{id=40711,NameZh='华丽短剑[1]',Icon='item_40711',Type=250,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=621,AdventureSort=4000,AdventureValue=1,Condition=8,Desc='拥有相当华丽外观的短剑。拥有高贵身分的人常拿它来当做装饰品或典礼时使用。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.15,0},}",
  [40712] = "{id=40712,NameZh='厨刀[2]',Icon='item_40703',Type=250,MaxNum=99,SellPrice=100,Desc='切肉片时非常有用的刀，使用方法很简单，所以很多人都会使用。',Level=10,Feature=4,}",
  [40713] = "{id=40713,NameZh='变形短剑[2]',Icon='item_40703',Type=250,MaxNum=99,SellPrice=100,Desc='用古代炼金术所制造出来之传说中的短剑。',Level=10,Feature=4,}",
  [40714] = "{id=40714,NameZh='削刃短剑[2]',Icon='item_40703',Type=250,MaxNum=99,SellPrice=100,Desc='专门破坏敌人武器的短剑，但机率不高。',Level=10,Feature=4,}",
  [40715] = "{id=40715,NameZh='幸运短剑[1]',Icon='item_40715',Type=250,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=2500,AdventureSort=4000,AdventureValue=1,Condition=8,Desc='会为使用者带来幸运的短剑。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.15,0},}",
  [40716] = "{id=40716,NameZh='神圣大驹短剑[1]',Icon='item_40716',Type=250,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=522,AdventureSort=4000,AdventureValue=1,Condition=8,Desc='用圣水来精炼，对任何恶魔气息都可消灭的短剑。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.15,0},}",
  [40717] = "{id=40717,NameZh='皇家短剑[2]',Icon='item_40703',Type=250,MaxNum=99,SellPrice=100,Desc='古代某一位公主，所使用过的漂亮的剑。做护身之用看起来很漂亮，有收藏的价值。',Level=10,Feature=4,}",
  [40718] = "{id=40718,NameZh='竹荚鱼剑[2]',Icon='item_40703',Type=250,MaxNum=99,SellPrice=100,Desc='竹荚鱼科海鱼，可做各式美味鱼料理，冷冻的关系非常坚硬。',Level=10,Feature=4,}",
  [40719] = "{id=40719,NameZh='巨毒短剑[1]',Icon='item_40719',Type=250,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=121,AdventureSort=4000,AdventureValue=1,Condition=8,Desc='紫色闪烁的刀刃，让看到这把刀的人，会感觉到害怕。在刀上面涂有强烈的剧毒。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [40720] = "{id=40720,NameZh='战斗短剑[2]',Icon='item_40703',Type=250,MaxNum=99,SellPrice=100,Desc='以方便战斗为诉求，专门杀伤敌人时使用的短剑。',Level=10,Feature=4,}",
  [40721] = "{id=40721,NameZh='远古短剑[2]',Icon='item_40703',Type=250,MaxNum=99,SellPrice=100,Desc='封面标有让人印象深刻的学问无止境字句，坚持不懈并且准确飞快地施展魔法的话自然实力就会提高。',Level=10,Feature=4,}",
  [40722] = "{id=40722,NameZh='天龙短剑[2]',Icon='item_40703',Type=250,MaxNum=99,SellPrice=100,Desc='用龙牙所做成的短剑 ，可以轻易的刺破龙族的厚皮，不理会龙族魔物的防御力。',Level=10,Feature=4,}",
  [40723] = "{id=40723,NameZh='沙漠之风[1]',Icon='item_40723',Type=250,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=240,AdventureSort=4000,AdventureValue=1,Condition=8,Desc='刺客工会制造的短剑。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [40724] = "{id=40724,NameZh='沙漠之暮[1]',Icon='item_40724',Type=250,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=120,AdventureSort=4000,AdventureValue=1,Condition=8,Desc='刺客工会制造的短剑。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [40725] = "{id=40725,NameZh='破甲短剑[2]',Icon='item_40703',Type=250,MaxNum=99,SellPrice=100,Desc='细长但尖硬的锥子。可以轻易的刺穿防具。假如对方的防御力越来越高的话，可以执行更强烈的攻击。',Level=50,Feature=4,}",
  [40726] = "{id=40726,NameZh='妖短剑 泣神怨[2]',Icon='item_40703',Type=250,MaxNum=99,SellPrice=100,Desc='暗杀者的短剑。',Level=10,Feature=4,}",
  [40727] = "{id=40727,NameZh='威娜短剑[2]',Icon='item_40703',Type=250,MaxNum=99,SellPrice=100,Desc='象征着战争的短剑，锯齿模样的剑身上涂有剧毒。',Level=10,Feature=4,}",
  [40728] = "{id=40728,NameZh='黑_翼[2]',Icon='item_40703',Type=250,MaxNum=99,SellPrice=100,Desc='流氓公会制作而成的黑色齿轮模样的短剑。',Level=10,Feature=4,}",
  [40729] = "{id=40729,NameZh='德克短剑[2]',Icon='item_40703',Type=250,MaxNum=99,SellPrice=100,Desc='古代某个西方国家所使用的短剑。',Level=30,}",
  [40730] = "{id=40730,NameZh='真·逗猫棒[1]',Icon='toy_506',Type=250,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1750,AdventureSort=100000,AdventureValue=1,Condition=8,Desc='能让猫咪开心的道具。使用不当有可能激怒猫咪。',Feature=1,LoadShowSize=1.3,LoadShowRotate=340,LoadShowPose={0,0.1,0},}",
  [40731] = "{id=40731,NameZh='永劫的火焰[1]',Icon='item_40731',Type=250,Quality=3,MaxNum=99,SellPrice=100,Feature=1,}",
  [40732] = "{id=40732,NameZh='至死的魔眼[1]',Icon='item_40732',Type=250,Quality=3,MaxNum=99,SellPrice=100,Feature=1,}",
  [40733] = "{id=40733,NameZh='风灵短剑[1]',Icon='item_40733',Type=250,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1660,AdventureSort=4900,AdventureValue=1,Condition=8,Desc='运用最新工艺将风灵矿石配合符文法阵试作的蕴含风之力的短剑。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [40734] = "{id=40734,NameZh='火灵短剑[1]',Icon='item_40734',Type=250,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1660,AdventureSort=4900,AdventureValue=1,Condition=8,Desc='运用最新工艺将火灵矿石配合符文法阵试作的蕴含火之力的短剑。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [40735] = "{id=40735,NameZh='地灵短剑[1]',Icon='item_40735',Type=250,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1660,AdventureSort=4900,AdventureValue=1,Condition=8,Desc='运用最新工艺将地灵矿石配合符文法阵试作的蕴含地之力的短剑。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [40736] = "{id=40736,NameZh='水灵短剑[1]',Icon='item_40736',Type=250,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1660,AdventureSort=4900,AdventureValue=1,Condition=8,Desc='运用最新工艺将水灵矿石配合符文法阵试作的蕴含水之力的短剑。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [40737] = "{id=40737,NameZh='星界·雷鸣之殇',Icon='item_40737',Type=250,MaxNum=99,AuctionPrice=1,SellPrice=79600,AdventureSort=100002,AdventureValue=1,Condition=8,Desc='利用星辰中提炼出的珍贵矿石制作而成，外形比较独特，短剑挥舞之时附带星辰之光，令敌人目不暇接。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [40738] = "{id=40738,NameZh='紫毒短剑[1]',Icon='item_40738',Type=250,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=241,AdventureSort=4000,AdventureValue=1,Condition=8,Desc='用某种剧毒鸟类毒腺里的紫色毒液，淬毒制成的锋利匕首。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [40739] = "{id=40739,NameZh='英灵·瑞吉之愤怒',Icon='item_40739',Type=250,MaxNum=99,SellPrice=100,AdventureSort=100006,AdventureValue=1,Condition=8,Desc='圣迹之神——瑞吉蕾芙的怒火所铸成的短剑，圣迹的荣耀，只有相当强大的人才能驾驭这个充满神之怒火的利刃。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [40740] = "{id=40740,NameZh='圣徒短剑[1]',Icon='item_40740',Type=250,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='短小精悍的利刃，“光明圣徒”安德鲁得意之作，是一柄同时兼顾了刺客短剑的轻巧与战士短剑的锋利的短剑。受到光明圣徒的祝福，安全精炼时消耗的装备件数减少一半。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [40741] = "{id=40741,NameZh='衔尾者弯刃',Icon='item_40741',Type=250,MaxNum=99,SellPrice=100,AdventureSort=100004,AdventureValue=1,Condition=8,Desc='能像蛇一般以闪电的速度攻击，锋利的刀口杀伤力如同巨蛇的咬合一般致命。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [40742] = "{id=40742,NameZh='考尔德短剑[1]',Icon='item_40742',Type=250,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=260,AdventureSort=4000,AdventureValue=1,Condition=8,Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [40743] = "{id=40743,NameZh='象牙匕首[1]',Icon='item_40743',Type=250,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=750,AdventureSort=4000,AdventureValue=1,Condition=8,Feature=1,LoadShowSize=1.4,LoadShowRotate=70,LoadShowPose={0,0.15,0},}",
  [40744] = "{id=40744,NameZh='手术刀[1]',Icon='item_40744',Type=250,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=750,AdventureSort=4000,AdventureValue=1,Condition=8,Desc='乍一看是医生常用的刀具，但其实刀刃涂有剧毒，可以出其不意的重创敌人。',Feature=1,LoadShowSize=2,LoadShowRotate=70,LoadShowPose={0,0.2,0},}",
  [40745] = "{id=40745,NameZh='牙科手术刀[1]',Icon='item_40745',Type=250,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=900,AdventureSort=4000,AdventureValue=1,Condition=8,Desc='全米德加尔特大陆刀法最精湛的人是谁？剑士？盗贼？错了，其实是私人牙医。',Feature=1,LoadShowSize=2,LoadShowRotate=70,LoadShowPose={0,0.2,0},}",
  [40746] = "{id=40746,NameZh='破甲短锥[1]',Icon='item_40746',Type=250,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1600,AdventureSort=4000,AdventureValue=1,Condition=8,Desc='流氓们最近很苦恼，因为总有其他职业的冒险者误会他们在用螺丝刀战斗……',Feature=1,LoadShowSize=2,LoadShowRotate=70,LoadShowPose={0,0.2,0},}",
  [40747] = "{id=40747,NameZh='黑翼[1]',Icon='item_40747',Type=250,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=650,AdventureSort=4000,AdventureValue=1,Condition=8,Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [40748] = "{id=40748,NameZh='高级乐园团短剑[1]',Icon='item_40706',Type=250,MaxNum=99,SellPrice=100,Desc='为了保障初心冒险者们的冒险之旅，乐园团为此制造的最新制式短剑。',Level=1,NoStorage=5,}",
  [40749] = "{id=40749,NameZh='梅林的赠礼',Icon='item_40749',Type=250,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=100001,AdventureValue=1,Condition=8,Desc='盗贼克克里曾向世人宣布要偷取大法师梅林随身携带的匕首，却被精明的梅林识破他的诡计，一直没有得手。正在他心灰意冷准备放弃之时，得到了一样神秘的赠礼，梅林将自己的随身匕首赠送给克克里，这把匕首一直陪伴着克克里，直到传奇大盗法格里斯偷走，从此下落不明。（建议作为武器外观使用）',Feature=1,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [40750] = "{id=40750,NameZh='圣灵·瑞吉之暴怒剑',Icon='item_40750',Type=250,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='圣迹之神——瑞吉蕾芙的短剑，据说这把剑具有自己的性格，越是沾血则越是愤怒，力量也愈发恐怖。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [40751] = "{id=40751,NameZh='金钩匕首',Icon='item_40705',Type=250,MaxNum=99,SellPrice=1140,Desc='侏儒大师设计的匕首，装有保护使用者手部的弯钩，被称为金钩匕首。',Level=95,}",
  [40752] = "{id=40752,NameZh='银槲之剑',Icon='item_40752',Type=457,Quality=4,MaxNum=1,SellPrice=100,Desc='黑暗之神霍德尔为了战胜光明之神巴德尔，将神界最锋利的银槲树枝制成利刃，以他纯粹的黑暗魔法淬炼数万年，终于制成了这对无坚不摧的银槲之剑。',NoSale=1,NoStorage=7,}",
  [40753] = "{id=40753,NameZh='银槲之剑·精锻',Icon='item_40753',Type=457,Quality=4,MaxNum=1,SellPrice=100,Desc='黑暗之神霍德尔为了战胜光明之神巴德尔，将神界最锋利的银槲树枝制成利刃，以他纯粹的黑暗魔法淬炼数万年，终于制成了这对无坚不摧的银槲之剑。',NoSale=1,NoStorage=7,}",
  [40754] = "{id=40754,NameZh='银槲之剑·神铸',Icon='item_40754',Type=457,Quality=4,MaxNum=1,SellPrice=100,Desc='黑暗之神霍德尔为了战胜光明之神巴德尔，将神界最锋利的银槲树枝制成利刃，以他纯粹的黑暗魔法淬炼数万年，终于制成了这对无坚不摧的银槲之剑。',NoSale=1,NoStorage=7,}",
  [40755] = "{id=40755,NameZh='幸福玫瑰[1]',Icon='item_40755',Type=250,MaxNum=99,SellPrice=100,AdventureSort=109999,AdventureValue=1,Condition=8,Desc='将所有的善良、美好与祝福捧于手心，玫瑰的香气在心间萦绕，神圣时刻即将到来。握紧手中的捧花，期待的喜悦溢于言表',Feature=1,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,0.05,0},}",
  [40756] = "{id=40756,NameZh='月辉·星光短刀',Icon='item_40756',Type=250,MaxNum=99,SellPrice=100,AdventureSort=100008,AdventureValue=1,Condition=8,Desc='暗月马戏团标志性的武器，因其式样低调而华丽又非常稀有，成为了年轻冒险家追捧的热门武器',LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,0.05,0},}",
  [40757] = "{id=40757,NameZh='日耀·恒星短刀',Icon='item_40757',Type=250,MaxNum=99,SellPrice=100,AdventureSort=100007,AdventureValue=1,Condition=8,Desc='太阳马戏团标志性的武器，耀眼的金光和精致的造型，是坚持爱与正义的冒险者所追寻的目标',LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,0.05,0},}",
  [40758] = "{id=40758,NameZh='守备军短剑',Icon='item_40705',Type=250,MaxNum=99,SellPrice=2000,Level=90,}",
  [40759] = "{id=40759,NameZh='碎雪·赤练寒华',Icon='item_40759',Type=250,MaxNum=99,SellPrice=100,AdventureSort=100009,AdventureValue=1,Condition=8,Desc='刀刃散发寒气的魔力匕首，当它被挥舞时便会化作咆哮的暴风雪，在一片冰风乱舞中将敌人的身体与灵魂一同冻结。',LoadShowSize=1.4,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [40760] = "{id=40760,NameZh='炎魂·赤霄红莲',Icon='item_40760',Type=250,MaxNum=99,SellPrice=100,AdventureSort=100010,AdventureValue=1,Condition=8,Desc='刀刃散发火焰的魔力匕首，当它被挥舞时便会化作炽热的流火，在一片赤红乱舞中将敌人的身体与灵魂烧为灰烬。',LoadShowSize=1.4,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [40761] = "{id=40761,NameZh='枫忆短剑',Icon='item_40761',Type=250,MaxNum=99,SellPrice=100,AdventureSort=100003,AdventureValue=1,Condition=8,Desc='“哥哥，为什么只有你拿着剑啊？”“因为哥哥要保护你啊，等你长大了，你再来保护哥哥好不好？”“好！”少年站在墓碑前回想起了儿时的对话，自嘲一笑，“我长大了，你呢…”。秋风吹过枫叶落下，或许只有它看到了，少年的脸上早已布满了泪水…',LoadShowSize=1.4,LoadShowRotate=70,LoadShowPose={0,0.05,0},}",
  [40762] = "{id=40762,NameZh='信仰短剑',Icon='item_40762',Type=250,MaxNum=99,SellPrice=100,AdventureSort=100005,AdventureValue=1,Condition=8,Desc='巴风特曾带领手下对梦罗克进行过一次史无前例的大侵袭，这次的战争造成了数以万计的民众伤亡，在危难的关头有十四位勇士站了出来，他们牺牲了自己保护了梦罗克，死后的他们留下了自己的武器，这些武器被梦罗克的人们当做信仰的象征，这把短剑便是十四把武器之一。',LoadShowSize=1,LoadShowRotate=70,LoadShowPose={0,0.05,0},}",
  [40763] = "{id=40763,NameZh='亡灵短剑',Icon='item_40763',Type=250,MaxNum=99,SellPrice=2100,AdventureValue=1,Condition=8,Desc='据说这把短剑可以让你变得像亡魂一样来无影去无踪。',Level=95,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [40764] = "{id=40764,NameZh='埃琉德尼尔汲魂刺',Icon='item_40764',Type=250,MaxNum=99,SellPrice=100,AdventureSort=100012,AdventureValue=1,Condition=8,Desc='你说这把武器的外形不适合那位大人？上一个说出这句话的鬼魂已经被吸进剑里了。',TFValidDate='2019-10-28 05:00:00',ValidDate='2019-10-31 05:00:00',LoadShowSize=1.1,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [40765] = "{id=40765,NameZh='光明猎手[1]',Icon='item_40765',Type=250,MaxNum=99,AuctionPrice=1,SellPrice=100,Feature=1,}",
  [40766] = "{id=40766,NameZh='沙漠之风★[1]',Icon='item_40766',Type=250,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=4000,AdventureValue=1,Condition=8,Desc='刺客工会制造的短剑。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [40767] = "{id=40767,NameZh='神圣大驹短剑★[1]',Icon='item_40767',Type=250,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=4000,AdventureValue=1,Condition=8,Desc='用圣水来精炼，对任何恶魔气息都可消灭的短剑。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.15,0},}",
  [40768] = "{id=40768,NameZh='暗盗贼短剑[1]',Icon='item_40701',Type=250,MaxNum=99,SellPrice=100,Desc='为了方便任何人使用所制作出来的短剑。',Level=10,Feature=4,}",
  [40769] = "{id=40769,NameZh='生命体短剑',Icon='item_40769',Type=250,MaxNum=99,SellPrice=2400,Desc='雷根贝勒公司所开发的，以生命体为能量的短剑。可以灵活的给予敌人致命一击。',Level=100,}",
  [40770] = "{id=40770,NameZh='魔器·安朵斯',Icon='item_40770',Type=250,MaxNum=99,SellPrice=100,AdventureSort=100011,AdventureValue=1,Condition=8,Desc='梦罗克碎片打造的禁忌武器，对应着异世界恶魔No.63·安朵斯，他是一个长着夜鸦头的天使，手持锋利短剑。',LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [40771] = "{id=40771,NameZh='粒子切割者',Icon='item_40771',Type=250,MaxNum=99,SellPrice=100,AdventureSort=100013,AdventureValue=1,Condition=8,Desc='由粒子组成刀刃的短剑，轻薄且致命。任何现有的防御手段，都无法承受它的杀意。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [40772] = "{id=40772,NameZh='决意之刃[1]',Icon='item_40772',Type=250,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='杀意已决！在送你的敌人去死者之都前，让他们享受生命的最后一秒吧。',}",
  [40773] = "{id=40773,NameZh='除灵短剑[1]',Icon='item_40773',Type=250,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=30000,AdventureSort=4000,AdventureValue=1,Condition=8,Desc='除灵仪式时所使用的短剑。对于“念”与“魔”有强大的抑制力。',LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [40774] = "{id=40774,NameZh='科学救赎·短剑',Icon='item_40774',Type=250,MaxNum=99,SellPrice=100,AdventureSort=100014,AdventureValue=1,Condition=8,Desc='科学！科学！科学！为了科学一切的牺牲都是值得，蝼蚁们的生命本就毫无价值，因实验而死的他们应该觉得骄傲，这是他们的宿命！快了！就快了，只要这把短剑制作出来，所有人都会我跪拜在我弗兰肯的脚下。',Feature=1,LoadShowSize=1,}",
  [40776] = "{id=40776,NameZh='圣息崇聆·短剑',Icon='item_40776',Type=250,MaxNum=99,SellPrice=100,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='光与天空，圣洁的飞鸟，神的双翼已然张开，吾虔诚的信徒，愿你在吾的庇佑下体验幸福与美好，你的灵魂之音，吾等已经听到，这把短剑赐予你，神祇永远与你同在。',LoadShowSize=1.1,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [40777] = "{id=40777,NameZh='辉光十字·短剑',Icon='item_40777',Type=250,MaxNum=99,SellPrice=2600,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='这柄短剑出自阿卢纳贝兹教国最有名的工匠——索罗克之手，他搜寻了整个教国寻找制作武器的材料，最终在圣域神殿的地下深处寻到了结果，吸取神灵信仰的矿石坚硬无比，制成的武器更是消灭黑暗的破晓之力。',Level=110,LoadShowSize=1.1,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [40779] = "{id=40779,NameZh='蔷薇灵语短剑',Icon='item_40779',Type=250,MaxNum=99,SellPrice=3200,AdventureSort=4000,AdventureValue=1,Condition=8,Desc='这把短剑被妖精一族的“灵语师”赋予了蔷薇的祝福。对于妖精来说，这其实是一把长剑。',Level=110,LoadShowSize=1.5,LoadShowRotate=90,LoadShowPose={0,-0.25,0},}",
  [40780] = "{id=40780,NameZh='红鱼花铃·短剑',Icon='item_40780',Type=250,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='长了一身红色鳞片的金鱼呀，喜欢在湖底的水草里悠闲地打瞌睡。有人投食的话，也会慢悠悠地钻到水面上，不紧不慢地吃鱼食。如果它会衔着短剑游出水面，也不要惊讶，这是金鱼族的报答哟~',LoadShowSize=1.5,LoadShowRotate=70,LoadShowPose={0,-0.2,0},}",
  [40781] = "{id=40781,NameZh='魔短剑·暗噬[1]',Icon='item_40781',Type=250,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=4000,AdventureValue=1,Condition=8,Desc='用魔物尖硬的牙只所制作而成的短剑。',LoadShowSize=1.5,LoadShowRotate=50,LoadShowPose={0,-0.2,0},}",
  [40782] = "{id=40782,NameZh='湛蓝天光·短剑',Icon='item_40782',Type=250,MaxNum=99,SellPrice=2800,AdventureValue=1,Condition=8,Desc='阔大的云海之上透出湛蓝天光，晴空下的战士们振作起了精神。战斗的号角即将吹响，握紧这把短剑吧，它印证着你的忠诚，勇敢与希望。',Level=110,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [40783] = "{id=40783,NameZh='天虹圣遗·短剑',Icon='item_40783',Type=250,MaxNum=99,SellPrice=100,AdventureSort=100019,AdventureValue=1,Condition=8,Desc='浮空精灵收集彩虹桥碎片铸造的短剑，出鞘的瞬间会散发出绚烂的虹光，让敌人在梦幻中迎来死亡。',LoadShowSize=1.5,}",
  [40784] = "{id=40784,NameZh='易燃短剑[1]',Icon='item_40784',Type=250,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,LoadShowSize=1.8,LoadShowRotate=90,LoadShowPose={0,-0.4,0},}",
  [40785] = "{id=40785,NameZh='月下祈者·短剑',Icon='item_40785',Type=250,MaxNum=99,SellPrice=100,AdventureSort=4000,AdventureValue=1,Condition=8,Desc='冰封千年的陨铁，王国的工匠们用尽办法也无法将其熔铸，却因小学徒的一次失误暴露在月光下。那一刻奇迹发生，陨铁融化宛若水银般流转，在月光下散发耀眼星辉。\n此乃月光赐福之短剑，持剑者当以月光之力，躬行黑夜，制裁邪恶！',LoadShowRotate=90,LoadShowPose={0,-0.2,-0.8},}",
  [40786] = "{id=40786,NameZh='英灵起点·短剑[2]',Icon='item_40786',Type=250,Quality=2,MaxNum=99,SellPrice=100,Desc='克里图拉新生领到的初心武器，致敬英灵而铸上蓝金涂装。据说设计者很缅怀普隆德拉南门的冒险时光，给“短剑”这种万能武器增添了纪念意义。',NoStorage=5,LoadShowSize=1.5,}",
  [40787] = "{id=40787,NameZh='英灵信标·短剑[2]',Icon='item_40787',Type=250,Quality=3,MaxNum=99,SellPrice=100,Desc='这把短剑是指引女武神降临、迎接英灵的道标。阵亡的勇士抱着它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,LoadShowSize=1.5,}",
  [40788] = "{id=40788,NameZh='英灵羽证·短剑[2]',Icon='item_40788',Type=250,Quality=3,MaxNum=99,SellPrice=100,Desc='英灵的证明。潜入学院的女武神在这把短剑中注入了奥丁领域的魔力。短剑长出了羽翼，好像一把迷你的雷瓦汀。',NoStorage=5,LoadShowSize=1.5,}",
  [40790] = "{id=40790,NameZh='远古回音·短剑',Icon='item_40790',Type=250,MaxNum=99,SellPrice=3200,AdventureSort=100020,AdventureValue=1,Condition=8,Desc='铭刻着神秘纹样的短剑，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,LoadShowSize=1,}",
  [40792] = "{id=40792,NameZh='王国荣辉·短剑',Icon='item_40792',Type=250,MaxNum=99,SellPrice=100,AdventureSort=100023,AdventureValue=1,Condition=8,Desc='效忠于王室的宫廷侍卫所持的短剑，其上绘有卢恩王家纹章。但考虑它如此娇小的尺寸，以及繁复的装饰……大概，更适合用作礼器吧。',LoadShowSize=1.8,LoadShowRotate=90,}",
  [40796] = "{id=40796,NameZh='银槲之剑·极限',Icon='item_40796',Type=457,Quality=4,MaxNum=1,SellPrice=100,Desc='黑暗之神霍德尔为了战胜光明之神巴德尔，将神界最锋利的银槲树枝制成利刃，以他纯粹的黑暗魔法淬炼数万年，终于制成了这对无坚不摧的银槲之剑。',NoSale=1,NoStorage=7,TFValidDate='2022-03-10 05:00:00',ValidDate='2022-03-23 05:00:00',}",
  [40797] = "{id=40797,NameZh='英灵信标·短剑[2]',Icon='item_40787',Type=250,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=100024,AdventureValue=1,Condition=8,Desc='这把短剑是指引女武神降临、迎接英灵的道标。阵亡的勇士抱着它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,LoadShowSize=1.5,}",
  [40798] = "{id=40798,NameZh='英灵羽证·短剑[2]',Icon='item_40788',Type=250,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=100025,AdventureValue=1,Condition=8,Desc='英灵的证明。潜入学院的女武神在这把短剑中注入了奥丁领域的魔力。短剑长出了羽翼，好像一把迷你的雷瓦汀。',NoStorage=5,LoadShowSize=1.5,}",
  [40803] = "{id=40803,NameZh='幸运短剑★[1]',Icon='item_40803',Type=250,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=2500,AdventureSort=4000,AdventureValue=1,Condition=8,Desc='会为使用者带来幸运的短剑。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.15,0},}",
  [40804] = "{id=40804,NameZh='手术专家[1]',Icon='item_40804',Type=250,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,Desc='专家的刀法总是稳准狠，只是有点难挂号，不过排队的人总会有耐心的，不是吗？毕竟死神也一样在等待呢。',}",
  [40805] = "{id=40805,NameZh='贯穿者[1]',Icon='item_40805',Type=250,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,Desc='注入了神秘力量的螺丝刀...啊不，短锥。可以轻而易举的贯穿一切事物。',}",
  [40806] = "{id=40806,NameZh='骑士之刃[1]',Icon='item_40806',Type=250,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='以此刃起誓，捍卫帝国尊严，至死不渝。',}",
