  [40914] = "{id=40914,NameZh='代理者拳刃[1]',Icon='item_40914',Type=200,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=480,AdventureSort=5000,AdventureValue=1,Condition=8,Desc='在紧急状况下也能命中目标的拳刃，广受暗杀者喜爱。据说会将运气集中在使用者的身上提高命中率。',Feature=1,LoadShowSize=1.8,LoadShowRotate=250,LoadShowPose={0,0.42,0},}",
  [40915] = "{id=40915,NameZh='火灵拳刃[2]',Icon='item_40905',Type=200,MaxNum=99,SellPrice=100,Desc='以火晶所做成的火属性拳刃，有一定的机率，使敌人陷入沉默的状态。',Level=10,Feature=4,}",
