  [40921] = "{id=40921,NameZh='圣辉之翼[2](删除)',Icon='item_40905',Type=200,MaxNum=99,SellPrice=100,Desc='传说是从天界掉下的一把神器，使用者会获得信仰的力量。',Level=10,Feature=4,}",
