  [40923] = "{id=40923,NameZh='刺杀拳刃[1]',Icon='item_40923',Type=200,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=14000,Desc='暗杀者老手使用它进行暗杀活动，专用于对人的拳刃。十分可怕。',Feature=1,}",
  [40924] = "{id=40924,NameZh='深埋[1]',Icon='item_40924',Type=200,Quality=3,MaxNum=99,SellPrice=100,Feature=1,}",
  [40925] = "{id=40925,NameZh='暗影之殇',Icon='item_40925',Type=200,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=100001,AdventureValue=1,Condition=8,Desc='“烈霜”是这把拳刃的名字，相传与“烈光之剑”为同一人铸造的宿敌兵刃。“烈光”侍奉王者，当王失德之时，“烈霜”就会出现，裁决王者。A.W800年“古城末日”之时，来自克雷霍尔伦家族的潜伏者用它刺伤希默梅思，给希默梅思造成永不能愈合的伤口。（建议作为武器外观使用）',Feature=1,LoadShowSize=1.8,LoadShowRotate=250,LoadShowPose={0,0.42,0},}",
  [40926] = "{id=40926,NameZh='星界·星辰挽歌',Icon='item_40926',Type=200,MaxNum=99,AuctionPrice=1,SellPrice=79600,AdventureSort=100002,AdventureValue=1,Condition=8,Desc='利用星辰中提炼出的珍贵矿石制作而成，取最锋利的矿石日夜打磨灼烧，锋利无比，其上的三道血槽对受到它攻击的生物显得尤为致命。',Feature=1,LoadShowSize=1.8,LoadShowRotate=250,LoadShowPose={0,0.42,0},}",
  [40927] = "{id=40927,NameZh='英灵·密丝特之隐秘',Icon='item_40927',Type=200,MaxNum=99,SellPrice=100,AdventureSort=100006,AdventureValue=1,Condition=8,Desc='迷雾之神——密丝特，作为最擅长刺杀的神，密丝特当然不会亏待那些暗影之中的潜伏者。',Feature=1,LoadShowSize=1.8,LoadShowRotate=250,LoadShowPose={0,0.42,0},}",
  [40928] = "{id=40928,NameZh='圣徒拳刃[1]',Icon='item_40928',Type=200,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='那些埋藏在阴影之中的刺客也受到了“光明圣徒”安德鲁的青睐，安德鲁为他们量身订做的拳刃不仅轻便，并且极其锋利，上面血槽能使血液快速流出，从而一击致命。受到光明圣徒的祝福，安全精炼时消耗的装备件数减少一半。',Feature=1,LoadShowSize=1.8,LoadShowRotate=250,LoadShowPose={0.2,0.4,0},}",
  [40929] = "{id=40929,NameZh='衔尾者拳刃',Icon='item_40929',Type=200,MaxNum=99,SellPrice=100,AdventureSort=100004,AdventureValue=1,Condition=8,Desc='采用远古巨蛇锋利的尖牙来制作的拳刃。',Feature=1,LoadShowSize=1.8,LoadShowRotate=250,LoadShowPose={0,0.42,0},}",
  [40930] = "{id=40930,NameZh='圣灵·密丝特之雾嗅刃',Icon='item_40930',Type=200,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='迷雾之神——密丝特的拳刃，当这把刃出招的时候，敌人只会感到一阵雾气飘过，随后便彻底失去了知觉。',Feature=1,LoadShowSize=1.8,LoadShowRotate=250,LoadShowPose={0,0.42,0},}",
  [40931] = "{id=40931,NameZh='白花拳刃',Icon='item_40908',Type=200,MaxNum=99,SellPrice=1140,Desc='镶嵌了白金刀片的拳刃，因为散开的刀片看上去如同盛放的白花，也被称为白花拳刃。',Level=95,}",
  [40932] = "{id=40932,NameZh='万物安息',Icon='item_40932',Type=453,Quality=4,MaxNum=1,SellPrice=100,Desc='传奇盗贼尤伦用它终结了无数敌人的生命，后世尊称这双拳刃为“万物安息”，寓意持有者有权力赐予任何生物死亡。',NoSale=1,NoStorage=7,}",
