  [40934] = "{id=40934,NameZh='万物安息·神铸',Icon='item_40933',Type=453,Quality=4,MaxNum=1,SellPrice=100,Desc='传奇盗贼尤伦用它终结了无数敌人的生命，后世尊称这双拳刃为“万物安息”，寓意持有者有权力赐予任何生物死亡。',NoSale=1,NoStorage=7,}",
  [40935] = "{id=40935,NameZh='月辉·星陨拳刃',Icon='item_40935',Type=200,MaxNum=99,SellPrice=100,AdventureSort=100008,AdventureValue=1,Condition=8,Desc='暗月马戏团标志性的武器，因其式样低调而华丽又非常稀有，成为了年轻冒险家追捧的热门武器',LoadShowSize=1.8,LoadShowRotate=250,LoadShowPose={0,0.42,0},}",
  [40936] = "{id=40936,NameZh='日耀·苍炎拳刃',Icon='item_40936',Type=200,MaxNum=99,SellPrice=100,AdventureSort=100007,AdventureValue=1,Condition=8,Desc='太阳马戏团标志性的武器，耀眼的金光和精致的造型，是坚持爱与正义的冒险者所追寻的目标',LoadShowSize=1.8,LoadShowRotate=250,LoadShowPose={0,0.42,0},}",
  [40937] = "{id=40937,NameZh='守备军拳刃',Icon='item_40908',Type=200,MaxNum=99,SellPrice=2000,Level=90,}",
  [40938] = "{id=40938,NameZh='碎雪·断雪燃魂',Icon='item_40938',Type=200,MaxNum=99,SellPrice=100,AdventureSort=100009,AdventureValue=1,Condition=8,Desc='用稀有的冰晶曜石打造的拳刃，手背上冰霜核心不停地燃烧着耀眼的冰焰。',LoadShowSize=1.8,LoadShowRotate=250,LoadShowPose={0,0.42,0},}",
  [40939] = "{id=40939,NameZh='炎魂·曜火碎尘',Icon='item_40939',Type=200,MaxNum=99,SellPrice=100,AdventureSort=100010,AdventureValue=1,Condition=8,Desc='用稀有的火焰曜石打造的拳刃，手背上火焰核心不停地燃烧着耀眼的火焰。',LoadShowSize=1.8,LoadShowRotate=250,LoadShowPose={0,0.42,0},}",
  [40940] = "{id=40940,NameZh='枫忆拳刃',Icon='item_40940',Type=200,MaxNum=99,SellPrice=100,AdventureSort=100003,AdventureValue=1,Condition=8,Desc='当我出现意识开始，树下总有一个小男孩诉说着他的烦恼，他说他想当一个英雄，可是他的朋友们总是嘲笑他，我想帮助他却做不到，只能无力的当一个倾听者，一直到我的身体变成了鲜艳的红色，意识消失的最后一刻我仍然想着那个男孩，或许是我的心意得到了回应，再次醒来时我发现我变成了拳刃，我和那个小男孩相遇了…',LoadShowSize=1.8,LoadShowRotate=250,LoadShowPose={0.3,0.42,0},}",
  [40941] = "{id=40941,NameZh='信仰拳刃',Icon='item_40941',Type=200,MaxNum=99,SellPrice=100,AdventureSort=100005,AdventureValue=1,Condition=8,Desc='巴风特曾带领手下对梦罗克进行过一次史无前例的大侵袭，这次的战争造成了数以万计的民众伤亡，在危难的关头有十四位勇士站了出来，他们牺牲了自己保护了梦罗克，死后的他们留下了自己的武器，这些武器被梦罗克的人们当做信仰的象征，这对拳刃便是十四把武器的复制品之一。',LoadShowSize=1.8,LoadShowRotate=250,LoadShowPose={0.1,0.42,0},}",
  [40942] = "{id=40942,NameZh='亡灵拳刃',Icon='item_40942',Type=200,MaxNum=99,SellPrice=2100,AdventureValue=1,Condition=8,Desc='戴着亡灵拳刃挑战亡者MVP、Mini，你就会变成亡魂刺客。',Level=95,LoadShowSize=1.8,LoadShowRotate=250,LoadShowPose={0,0.4,0},}",
  [40943] = "{id=40943,NameZh='埃琉德尼尔指虎',Icon='item_40943',Type=200,MaxNum=99,SellPrice=100,AdventureSort=100012,AdventureValue=1,Condition=8,Desc='别紧张，这玩意没有它看起来那么可怕，只要你不怕痛，只要你不怕死。',TFValidDate='2019-10-28 05:00:00',ValidDate='2019-10-31 05:00:00',LoadShowSize=1.8,LoadShowRotate=250,LoadShowPose={0.2,0.42,0},}",
