  [40948] = "{id=40948,NameZh='魔器·弗加洛',Icon='item_40948',Type=200,MaxNum=99,SellPrice=100,AdventureSort=100011,AdventureValue=1,Condition=8,Desc='梦罗克碎片打造的禁忌武器，对应着异世界恶魔No.41·弗加洛，擅控制风与海的力量，经常掀翻战舰、溺毙水手。',LoadShowSize=1.8,LoadShowRotate=250,LoadShowPose={0,0.42,0},}",
  [40949] = "{id=40949,NameZh='5.0拳刃[1]',Icon='item_40949',Type=200,MaxNum=99,SellPrice=100,}",
  [40950] = "{id=40950,NameZh='电离拳刃',Icon='item_40950',Type=200,MaxNum=99,SellPrice=100,AdventureSort=100013,AdventureValue=1,Condition=8,Desc='特殊研制的电离子刀锋拳刃，弥补了暗杀者们力量上的不足。配合高速的攻击，拥有可怕的破坏力。',LoadShowSize=1.8,LoadShowRotate=250,LoadShowPose={0,0.42,0},}",
  [40951] = "{id=40951,NameZh='伽罗拳刃[1]',Icon='item_40951',Type=200,MaxNum=99,SellPrice=100,Desc='将刀刃化为拳，将拳击化作刀锋。所有敌人都会在这力量下化作你前进道路上的垫脚石。',}",
  [40952] = "{id=40952,NameZh='科学救赎·拳刃',Icon='item_40952',Type=200,MaxNum=99,SellPrice=100,AdventureSort=100014,AdventureValue=1,Condition=8,Desc='科学！科学！科学！为了科学一切的牺牲都是值得，蝼蚁们的生命本就毫无价值，因实验而死的他们应该觉得骄傲，这是他们的宿命！快了！就快了，只要把拳刃制作出来，我就能让那些反抗者成为我下一批的实验品……哈哈哈……',Feature=1,LoadShowPose={0,0.3,0},}",
  [40954] = "{id=40954,NameZh='圣息崇聆·拳刃',Icon='item_40954',Type=200,MaxNum=99,SellPrice=100,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='光与天空，圣洁的飞鸟，神的双翼已然张开，吾虔诚的信徒，愿你在吾的庇佑下体验幸福与美好，你的灵魂之音，吾等已经听到，这副拳刃赐予你，神祇永远与你同在。',LoadShowSize=1.8,LoadShowRotate=250,LoadShowPose={0,0.42,0},}",
  [40955] = "{id=40955,NameZh='辉光十字·拳刃',Icon='item_40955',Type=200,MaxNum=99,SellPrice=2600,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='这副拳刃出自阿卢纳贝兹教国最有名的工匠——索罗克之手，他搜寻了整个教国寻找制作武器的材料，最终在圣域神殿的地下深处寻到了结果，吸取神灵信仰的矿石坚硬无比，制成的武器更是消灭黑暗的破晓之力。',Level=110,LoadShowSize=1.8,LoadShowRotate=250,LoadShowPose={0,0.42,0},}",
  [40956] = "{id=40956,NameZh='蔷薇灵语拳刃',Icon='item_40956',Type=200,MaxNum=99,SellPrice=3200,AdventureSort=5000,AdventureValue=1,Condition=8,Desc='这副拳刃被妖精一族的“灵语师”赋予了蔷薇的祝福。藏于掌间的利刃一如隐于蔷薇花下的尖刺。',Level=110,LoadShowRotate=-90,LoadShowPose={0.5,0,-0.25},}",
  [40957] = "{id=40957,NameZh='红鱼花铃·拳刃',Icon='item_40957',Type=200,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='长了一身红色鳞片的金鱼呀，喜欢在湖底的水草里悠闲地打瞌睡。有人投食的话，也会慢悠悠地钻到水面上，不紧不慢地吃鱼食。如果它会衔着拳刃游出水面，也不要惊讶，这是金鱼族的报答哟~',LoadShowSize=2,LoadShowRotate=70,LoadShowPose={0,0.4,0},}",
  [40958] = "{id=40958,NameZh='湛蓝天光·拳刃',Icon='item_40958',Type=200,MaxNum=99,SellPrice=2800,AdventureValue=1,Condition=8,Desc='阔大的云海之上透出湛蓝天光，晴空下的战士们振作起了精神。戴上这副拳刃吧，它印证着你的忠诚，勇敢与希望。',Level=110,LoadShowSize=2,LoadShowRotate=-90,LoadShowPose={0,0.3,0},}",
  [40959] = "{id=40959,NameZh='天虹圣遗·拳刃',Icon='item_40959',Type=200,MaxNum=99,SellPrice=100,AdventureSort=100019,AdventureValue=1,Condition=8,Desc='浮空精灵收集彩虹桥碎片锻造的拳刃，由于过于闪耀被刺客公会禁止在隐匿行动中使用。',LoadShowPose={0,0.3,0},}",
  [40960] = "{id=40960,NameZh='月下祈者·拳刃',Icon='item_40960',Type=200,MaxNum=99,SellPrice=100,AdventureSort=5000,AdventureValue=1,Condition=8,Desc='冰封千年的陨铁，王国的工匠们用尽办法也无法将其熔铸，却因小学徒的一次失误暴露在月光下。那一刻奇迹发生，陨铁融化宛若水银般流转，在月光下散发耀眼星辉。\n此乃月光赐福之拳刃，执刃者当以月光之力，撕裂黑暗，守望光明！',LoadShowRotate=270,LoadShowPose={0,0.5,0},}",
  [40961] = "{id=40961,NameZh='英灵起点·拳刃[2]',Icon='item_40961',Type=200,Quality=2,MaxNum=99,SellPrice=100,Desc='克里图拉新生领到的初心武器，致敬英灵而铸上蓝金涂装。据说设计者是个追求武器穿戴感的工匠大师，他疯狂到了会把人手伸进炉子里做模具。',NoStorage=5,LoadShowPose={0,0.3,0},}",
  [40962] = "{id=40962,NameZh='英灵信标·拳刃[2]',Icon='item_40962',Type=200,Quality=3,MaxNum=99,SellPrice=100,Desc='这把拳刃是指引女武神降临、迎接英灵的道标。阵亡的勇士穿戴它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,LoadShowPose={0,0.3,0},}",
  [40963] = "{id=40963,NameZh='英灵羽证·拳刃[2]',Icon='item_40963',Type=200,Quality=3,MaxNum=99,SellPrice=100,Desc='英灵的证明。潜入学院的女武神在这把拳刃中注入了奥丁领域的魔力。拳刃长出了羽翼，如鹰隼的钩爪一样干净、利落。',NoStorage=5,LoadShowPose={0,0.3,0},}",
  [40965] = "{id=40965,NameZh='远古回音·拳刃',Icon='item_40965',Type=200,MaxNum=99,SellPrice=3200,AdventureSort=100020,AdventureValue=1,Condition=8,Desc='铭刻着神秘纹样的拳刃，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,LoadShowPose={0,0.35,0},}",
  [40967] = "{id=40967,NameZh='王国荣辉·拳刃',Icon='item_40967',Type=200,MaxNum=99,SellPrice=100,AdventureSort=100023,AdventureValue=1,Condition=8,Desc='效忠于王室的宫廷侍卫所持的拳刃，其上绘有卢恩王家纹章。不过，拳刃的边缘并未被打磨锋利，不适合用作厮杀的武器。',LoadShowRotate=-90,}",
  [40971] = "{id=40971,NameZh='万物安息·极限',Icon='item_40971',Type=453,Quality=4,MaxNum=1,SellPrice=100,Desc='传奇盗贼尤伦用它终结了无数敌人的生命，后世尊称这双拳刃为“万物安息”，寓意持有者有权力赐予任何生物死亡。',NoSale=1,NoStorage=7,TFValidDate='2022-03-10 05:00:00',ValidDate='2022-03-23 05:00:00',}",
  [40972] = "{id=40972,NameZh='英灵信标·拳刃[2]',Icon='item_40962',Type=200,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=100024,AdventureValue=1,Condition=8,Desc='这把拳刃是指引女武神降临、迎接英灵的道标。阵亡的勇士穿戴它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,LoadShowPose={0,0.3,0},}",
  [40973] = "{id=40973,NameZh='英灵羽证·拳刃[2]',Icon='item_40963',Type=200,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=100025,AdventureValue=1,Condition=8,Desc='英灵的证明。潜入学院的女武神在这把拳刃中注入了奥丁领域的魔力。拳刃长出了羽翼，如鹰隼的钩爪一样干净、利落。',NoStorage=5,LoadShowPose={0,0.3,0},}",
  [41201] = "{id=41201,NameZh='长弓',Icon='item_41201',Type=210,MaxNum=99,SellPrice=420,Desc='伤害力并不是很高，但使用起来很方便的弓。',Level=30,Feature=4,}",
  [41202] = "{id=41202,NameZh='弓',Icon='item_41202',Type=210,MaxNum=99,SellPrice=140,Desc='轻便实用的木弓。',Level=10,Feature=4,}",
  [41203] = "{id=41203,NameZh='坎普兹弓',Icon='item_41203',Type=210,MaxNum=99,SellPrice=600,Desc='用各种材料混合而成的弓，拥有较高的伤害力为重点。',Level=50,Feature=4,}",
  [41204] = "{id=41204,NameZh='克洛伊特弓',Icon='item_41204',Type=210,MaxNum=99,SellPrice=560,Desc='巨大的弓，看起来很难操作。',Level=40,Feature=4,}",
  [41205] = "{id=41205,NameZh='喵喵大蟹弓[1]',Icon='item_41205',Type=210,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=755,AdventureSort=6001,AdventureValue=1,Condition=8,Desc='节肢动物甲壳纲，脚长生长在深海的沙堆中。',Feature=1,LoadShowSize=1.4,LoadShowRotate=250,LoadShowPose={0,0.4,0},}",
  [41206] = "{id=41206,NameZh='P.弓',Icon='item_41206',Type=210,MaxNum=99,SellPrice=280,Desc='有精准的射击和较高的伤害力，此项优点让使用者更加喜欢。',Level=20,Feature=4,}",
  [41207] = "{id=41207,NameZh='合金弓',Icon='item_41207',Type=210,MaxNum=99,SellPrice=720,Desc='兽人弓箭手使用的弓箭。需要巨力才能拉开。',Level=60,Feature=4,}",
  [41208] = "{id=41208,NameZh='连发弓[1]',Icon='item_41208',Type=210,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=121,AdventureSort=6000,AdventureValue=1,Condition=8,Desc='外观看起来既轻盈又有韧性，专用来连发的弓。',Feature=1,LoadShowSize=1.2,LoadShowRotate=250,LoadShowPose={-0.2,0.3,0},}",
  [41209] = "{id=41209,NameZh='军用弓',Icon='item_41209',Type=210,MaxNum=99,SellPrice=840,Desc='威力强大的弓。',Level=70,Feature=4,}",
  [41210] = "{id=41210,NameZh='制式弓',Icon='item_41210',Type=210,MaxNum=99,SellPrice=960,Desc='专门为佣兵定制的长弓。适应各种复杂环境。',Level=80,Feature=4,}",
  [41211] = "{id=41211,NameZh='角弓[1]',Icon='item_41211',Type=210,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=120,AdventureSort=6000,AdventureValue=1,Condition=8,Desc='用动物的角作成的弓，具有有极高的伤害力和精准度。',Feature=1,LoadShowSize=1.2,LoadShowRotate=250,LoadShowPose={-0.1,0.3,0},}",
  [41212] = "{id=41212,NameZh='战斗弓',Icon='item_41212',Type=210,MaxNum=99,SellPrice=1080,Desc='为了适应战场的烈度特别加固了弓身结构的弓。',Level=90,Feature=4,}",
  [41213] = "{id=41213,NameZh='大地之弓[2]',Icon='item_41201',Type=210,MaxNum=99,SellPrice=100,Desc='好像用泥巴制作的弓。',Level=10,Feature=4,}",
  [41214] = "{id=41214,NameZh='灼热之弓[2]',Icon='item_41201',Type=210,MaxNum=99,SellPrice=100,Desc='好像燃烧起来的弓。碰到有灼烧感。',Level=10,Feature=4,}",
  [41215] = "{id=41215,NameZh='冰霜之弓[2]',Icon='item_41201',Type=210,MaxNum=99,SellPrice=100,Desc='通体结霜的弓。不知能否使用。',Level=10,Feature=4,}",
  [41216] = "{id=41216,NameZh='红色闪电[1]',Icon='item_41216',Type=210,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=120,AdventureSort=6000,AdventureValue=1,Condition=8,Desc='奇特形状的红色弓，优雅而美丽。专为特定技能设计。',Feature=1,LoadShowSize=1.2,LoadShowRotate=250,LoadShowPose={-0.1,0.3,0},}",
  [41217] = "{id=41217,NameZh='神秘之弓[1]',Icon='item_41217',Type=210,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=572,AdventureSort=6000,AdventureValue=1,Condition=8,Desc='因为使用了未知的附魔，就连制作它的工匠也不知道弓里蕴含着何种能量。',Feature=1,LoadShowSize=1.3,LoadShowRotate=250,LoadShowPose={-0.1,0.3,0},}",
  [41218] = "{id=41218,NameZh='天龙之翼[1]',Icon='item_41218',Type=210,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=24400,AdventureSort=6000,AdventureValue=1,Condition=8,Desc='外形如同龙之翼的弓,据说是用龙的骨头做成的,射出的箭矢对龙族具有致命的威力。',Feature=4,LoadShowSize=1.3,LoadShowRotate=250,LoadShowPose={-0.1,0.3,0},}",
  [41219] = "{id=41219,NameZh='斑纹鳗鱼弓[2]',Icon='item_41201',Type=210,MaxNum=99,SellPrice=100,Desc='栖息在喵喵岛海边的斑纹鳗鱼，鱼身有弹性还呈一字型适合当弓用。',Level=10,Feature=4,}",
  [41220] = "{id=41220,NameZh='巨之弓[2]',Icon='item_41201',Type=210,MaxNum=99,SellPrice=100,Desc='它的名字叫巨之弓，它又大又重，因此会难以使用，但是它攻击力之恐怖却是让人啧啧称奇的。',Level=10,Feature=4,}",
  [41221] = "{id=41221,NameZh='露娜弓[1]',Icon='item_41221',Type=210,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1750,AdventureSort=6000,AdventureValue=1,Condition=8,Desc='用月石做成的弓，弓带有刀刃能防御敌人的攻击并射击，有一点重是它的缺点。 ',Feature=1,LoadShowSize=1.2,LoadShowRotate=250,LoadShowPose={-0.2,0.3,0},}",
  [41222] = "{id=41222,NameZh='束缚之弓[2]',Icon='item_41201',Type=210,MaxNum=99,SellPrice=100,Desc='用魔界植物坚硬的藤梗制成的弓，能够发射蛛丝之矢来困住敌人。',Level=10,Feature=4,}",
  [41223] = "{id=41223,NameZh='伊克西翁之翼[2]',Icon='item_41201',Type=210,MaxNum=99,SellPrice=100,Desc='纯白的羽翼舒展模样的弓。',Level=10,Feature=4,}",
  [41224] = "{id=41224,NameZh='精灵之弓[2]',Icon='item_41201',Type=210,MaxNum=99,SellPrice=100,Desc='按照古代守卫森林的种族使用的弓的样子制作而成。',Level=10,Feature=4,}",
  [41225] = "{id=41225,NameZh='无尽之弓[2]',Icon='item_41201',Type=210,MaxNum=99,SellPrice=100,Desc='这件武器有种奇怪的力量，好像其中的一部分被封印了。',Level=10,Feature=4,}",
  [41226] = "{id=41226,NameZh='炽天使之弓[1]',Icon='item_41226',Type=210,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=14000,AdventureSort=6000,AdventureValue=1,Condition=8,Desc='拥有神圣的力量，可给予较高的伤害力，让玩家的潜力彻底发挥。',Feature=1,LoadShowSize=1.2,LoadShowRotate=250,LoadShowPose={-0.2,0.3,0},}",
  [41227] = "{id=41227,NameZh='风暴之弓[2](删除)',Icon='item_41201',Type=210,MaxNum=99,SellPrice=100,Desc='其上拥有风暴符文，掩藏着惊人的魔力。',Level=10,Feature=4,}",
  [41228] = "{id=41228,NameZh='十字弓[1]',Icon='item_41228',Type=210,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=40,AdventureSort=6000,AdventureValue=1,Condition=8,Desc='优点为拥有快速连射和较高的破坏力为优点，为十字造型的弓。',Feature=1,LoadShowSize=1.3,LoadShowRotate=250,LoadShowPose={-0.2,0.3,0},}",
  [41229] = "{id=41229,NameZh='彗星之弓[1]',Icon='item_41229',Type=210,Quality=3,MaxNum=99,SellPrice=100,Feature=1,}",
  [41230] = "{id=41230,NameZh='赫克拉斯神弓',Icon='item_41230',Type=210,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=100001,AdventureValue=1,Condition=8,Desc='这是神族打造的弓，拥有能伤害神体，且弓弦永不断的传说。相传，追随托利斯坦大帝的神射手乌森诺·奥奇拉曾使用这把神弓，刺穿千里之外的魔族将领之躯。乌森诺·奥奇拉战死时，这把神弓发出了撼动天地的悲鸣。（建议作为武器外观使用）',Feature=1,LoadShowSize=1.15,LoadShowRotate=250,LoadShowPose={0,0.3,0},}",
  [41231] = "{id=41231,NameZh='星界·黯月之眼',Icon='item_41231',Type=210,MaxNum=99,AuctionPrice=1,SellPrice=79600,AdventureSort=100002,AdventureValue=1,Condition=8,Desc='利用星辰中提炼出的珍贵矿石制作而成，弓身弥漫着星辰的光辉，从这把弓射出的箭威力强大无比，受到所有弓箭手的追捧。',Feature=1,LoadShowSize=1,LoadShowRotate=250,LoadShowPose={0,0.3,0},}",
  [41232] = "{id=41232,NameZh='深红闪电[1]',Icon='item_41232',Type=210,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=240,AdventureSort=6000,AdventureValue=1,Condition=8,Desc='弓身的深红颜色被好事的人说成是用敌人的鲜血染成。',Feature=1,LoadShowSize=1.2,LoadShowRotate=250,LoadShowPose={-0.1,0.3,0},}",
  [41233] = "{id=41233,NameZh='诅咒之弓[1]',Icon='item_41233',Type=210,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=241,AdventureSort=6000,AdventureValue=1,Condition=8,Desc='让中箭者痛不欲生的诅咒之弓。',Feature=1,LoadShowSize=1.2,LoadShowRotate=250,LoadShowPose={-0.1,0.3,0},}",
  [41234] = "{id=41234,NameZh='英灵·海芙约特之弓',Icon='item_41234',Type=210,MaxNum=99,SellPrice=100,AdventureSort=100006,AdventureValue=1,Condition=8,Desc='军势神——海芙约特的长弓，冠以神之名的弓箭可以射出强大无比的箭矢。',Feature=1,LoadShowSize=1,LoadShowRotate=250,LoadShowPose={0,0.3,0},}",
  [41235] = "{id=41235,NameZh='圣徒之弓[1]',Icon='item_41235',Type=210,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='“光明圣徒”安德鲁曾在斐扬短暂的停留，见识了斐扬人优秀的狩猎技术，安德鲁对圣歌教会的弓进行改造，使之更加符合弓箭手的使用习惯，教会弓箭手也因此实力提升。受到光明圣徒的祝福，安全精炼时消耗的装备件数减少一半。',Feature=1,LoadShowSize=1,LoadShowRotate=250,LoadShowPose={0,0.3,0},}",
  [41236] = "{id=41236,NameZh='衔尾者鳞弓',Icon='item_41236',Type=210,MaxNum=99,SellPrice=100,AdventureSort=100004,AdventureValue=1,Condition=8,Desc='蛇骨打造的弓箭能将任何盔甲像纸一样击穿。',Feature=1,LoadShowSize=1,LoadShowRotate=250,LoadShowPose={0,0.3,0},}",
  [41237] = "{id=41237,NameZh='盗贼之弓[1]',Icon='item_41237',Type=210,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=700,AdventureSort=6000,AdventureValue=1,Condition=8,Feature=1,LoadShowSize=1.2,LoadShowRotate=250,LoadShowPose={-0.1,0.3,0},}",
  [41238] = "{id=41238,NameZh='高级乐园团长弓[1]',Icon='item_41204',Type=210,MaxNum=99,SellPrice=100,Desc='为了保障初心冒险者们的冒险之旅，乐园团为此制造的最新制式长弓。',Level=1,NoStorage=5,}",
  [41239] = "{id=41239,NameZh='圣灵·海芙约特之歼星弓',Icon='item_41239',Type=210,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='军势神——海芙约特的长弓，用其拉满弓一箭的威力，足以轻松射穿一颗恒星。',Feature=1,LoadShowSize=1,LoadShowRotate=250,LoadShowPose={0,0.3,0},}",
  [41240] = "{id=41240,NameZh='精钢连弩',Icon='item_41212',Type=210,MaxNum=99,SellPrice=1140,Desc='历经高温反复锻造制成的精钢打造而成的短弩，可以连续发箭，最适合战场上近距离作战。',Level=95,}",
  [41241] = "{id=41241,NameZh='凛冬结晶',Icon='item_41241',Type=454,Quality=4,MaxNum=1,SellPrice=100,Desc='霜之巨人中最强的战士名为赫朗格尼尔，他死后不屈的执念冰封了数万里的海洋，而许多年后人们才发现他的尸骸，居然化作了这把冰封的巨弓。',NoSale=1,NoStorage=7,}",
  [41242] = "{id=41242,NameZh='凛冬结晶·精锻',Icon='item_41242',Type=454,Quality=4,MaxNum=1,SellPrice=100,Desc='霜之巨人中最强的战士名为赫朗格尼尔，他死后不屈的执念冰封了数万里的海洋，而许多年后人们才发现他的尸骸，居然化作了这把冰封的巨弓。',NoSale=1,NoStorage=7,}",
  [41243] = "{id=41243,NameZh='凛冬结晶·神铸',Icon='item_41243',Type=454,Quality=4,MaxNum=1,SellPrice=100,Desc='霜之巨人中最强的战士名为赫朗格尼尔，他死后不屈的执念冰封了数万里的海洋，而许多年后人们才发现他的尸骸，居然化作了这把冰封的巨弓。',NoSale=1,NoStorage=7,}",
  [41244] = "{id=41244,NameZh='月辉·幻空之弓',Icon='item_41244',Type=210,MaxNum=99,SellPrice=100,AdventureSort=100008,AdventureValue=1,Condition=8,Desc='暗月马戏团标志性的武器，因其式样低调而华丽又非常稀有，成为了年轻冒险家追捧的热门武器',LoadShowSize=1.2,LoadShowRotate=250,LoadShowPose={-0.1,0.3,0},}",
  [41245] = "{id=41245,NameZh='日耀·金乌之弓',Icon='item_41245',Type=210,MaxNum=99,SellPrice=100,AdventureSort=100007,AdventureValue=1,Condition=8,Desc='太阳马戏团标志性的武器，耀眼的金光和精致的造型，是坚持爱与正义的冒险者所追寻的目标',LoadShowSize=1.2,LoadShowRotate=250,LoadShowPose={-0.1,0.3,0},}",
  [41246] = "{id=41246,NameZh='森林猎手[1]',Icon='item_41246',Type=210,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=6000,AdventureValue=1,Condition=8,Desc='最初为了在森林中作战而被设计出的装备，就算地形再复杂也丝毫不影响使用者发挥实力。“它就像我身体的一部分。”——某个老猎人',Feature=1,LoadShowSize=1.2,LoadShowRotate=250,LoadShowPose={0,0.3,0},}",
  [41247] = "{id=41247,NameZh='守备军之弓',Icon='item_41247',Type=210,MaxNum=99,SellPrice=2000,Level=90,}",
  [41248] = "{id=41248,NameZh='碎雪·十方冰裂',Icon='item_41248',Type=210,MaxNum=99,SellPrice=100,AdventureSort=100009,AdventureValue=1,Condition=8,Desc='蕴藏着冰雪力量的传说之弓，握住它时寒气便在指尖凝聚，每当松开弓弦，带着刺骨寒意的冰棱便会精准地射入敌人心脏。',LoadShowSize=1.2,LoadShowRotate=250,LoadShowPose={0,0.2,0},}",
  [41249] = "{id=41249,NameZh='炎魂·残焰惊天',Icon='item_41249',Type=210,MaxNum=99,SellPrice=100,AdventureSort=100010,AdventureValue=1,Condition=8,Desc='蕴藏着魔焰力量的传说之弓，握住它时魔焰便在指尖凝聚，每当松开弓弦，带着魔焰的箭矢便会精准地射入敌人心脏。',LoadShowSize=1.2,LoadShowRotate=250,LoadShowPose={0,0.2,0},}",
  [41250] = "{id=41250,NameZh='枫忆之弓',Icon='item_41250',Type=210,MaxNum=99,SellPrice=100,AdventureSort=100003,AdventureValue=1,Condition=8,Desc='“你真的要杀我么？”“魔物，不要想我会放过你，你们毁坏城市的时候也没有手下留情”“能死在心爱的人手里，我心甘情愿”弓箭破空刺入对面之人的胸膛，少女的身影缓缓倒下，猎人红着眼眶拔出了少女胸前的箭羽冲向自己的胸口，呢喃道“我怎么会让你自己孤单的离开呢”秋风吹过，两人身影躺在一片枫叶之上，仿若睡着了…',LoadShowSize=1.2,LoadShowRotate=250,LoadShowPose={0,0.3,0},}",
  [41251] = "{id=41251,NameZh='信仰之弓',Icon='item_41251',Type=210,MaxNum=99,SellPrice=100,AdventureSort=100005,AdventureValue=1,Condition=8,Desc='巴风特曾带领手下对梦罗克进行过一次史无前例的大侵袭，这次的战争造成了数以万计的民众伤亡，在危难的关头有十四位勇士站了出来，他们牺牲了自己保护了梦罗克，死后的他们留下了自己的武器，这些武器被梦罗克的人们当做信仰的象征，这把弓便是十四把武器的复制品之一。',LoadShowSize=1,LoadShowRotate=250,LoadShowPose={0,0.3,0},}",
  [41252] = "{id=41252,NameZh='亡灵之弓',Icon='item_41252',Type=210,MaxNum=99,SellPrice=2100,AdventureValue=1,Condition=8,Desc='这把弓射出的箭矢，穿透了灵魂，直达内心。但它还是会收到物理反伤的影响。',Level=95,LoadShowSize=1,LoadShowRotate=250,LoadShowPose={0,0.3,0},}",
  [41253] = "{id=41253,NameZh='埃琉德尼尔蛇弓',Icon='item_41253',Type=210,MaxNum=99,SellPrice=100,AdventureSort=100012,AdventureValue=1,Condition=8,Desc='那位大人并不会使用弓箭，但这把外形妖异的弓总挂在她的房间，似乎是为了纪念某个人。',TFValidDate='2019-10-28 05:00:00',ValidDate='2019-10-31 05:00:00',LoadShowSize=1,LoadShowRotate=250,LoadShowPose={0,0.3,0},}",
  [41254] = "{id=41254,NameZh='神秘之弓★[1]',Icon='item_41254',Type=210,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=6000,AdventureValue=1,Condition=8,Desc='因为使用了未知的附魔，就连制作它的工匠也不知道弓里蕴含着何种能量。',Feature=1,LoadShowSize=1.3,LoadShowRotate=250,LoadShowPose={-0.1,0.3,0},}",
  [41255] = "{id=41255,NameZh='喵喵大蟹弓★[1]',Icon='item_41255',Type=210,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=6000,AdventureValue=1,Condition=8,Desc='节肢动物甲壳纲，脚长生长在深海的沙堆中。',Feature=1,LoadShowSize=1.4,LoadShowRotate=250,LoadShowPose={0,0.4,0},}",
  [41256] = "{id=41256,NameZh='诅咒之弓★[1]',Icon='item_41256',Type=210,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=6000,AdventureValue=1,Condition=8,Desc='让中箭者痛不欲生的诅咒之弓。',Feature=1,LoadShowSize=1.2,LoadShowRotate=250,LoadShowPose={-0.1,0.3,0},}",
  [41257] = "{id=41257,NameZh='露娜弓★[1]',Icon='item_41257',Type=210,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=6000,AdventureValue=1,Condition=8,Desc='用月石做成的弓，弓带有刀刃能防御敌人的攻击并射击，有一点重是它的缺点。 ',Feature=1,LoadShowSize=1.2,LoadShowRotate=250,LoadShowPose={-0.2,0.3,0},}",
  [41258] = "{id=41258,NameZh='盗贼之弓★[1]',Icon='item_41258',Type=210,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=6000,AdventureValue=1,Condition=8,Desc='某个著名的神射手侠盗用过的弓，带着古老的幸运祝福。',Feature=1,LoadShowSize=1.2,LoadShowRotate=250,LoadShowPose={-0.1,0.3,0},}",
  [41259] = "{id=41259,NameZh='暗弓箭手之弓[1]',Icon='item_41202',Type=210,MaxNum=99,SellPrice=140,Desc='轻便实用的木弓。',Level=10,Feature=4,}",
  [41260] = "{id=41260,NameZh='生命体长弓',Icon='item_41260',Type=210,MaxNum=99,SellPrice=2400,Desc='雷根贝勒公司所开发的，以生命体为能量的长弓。可以射出威力巨大的箭矢。',Level=100,}",
  [41261] = "{id=41261,NameZh='魔器·列拉金',Icon='item_41261',Type=210,MaxNum=99,SellPrice=100,AdventureSort=100011,AdventureValue=1,Condition=8,Desc='梦罗克碎片打造的禁忌武器，对应着异世界恶魔No.14·列拉金，是一个手执长弓，腰悬箭袋，身穿绿衣的弓箭手。',LoadShowSize=1.1,LoadShowRotate=250,LoadShowPose={0,0.3,0},}",
  [41262] = "{id=41262,NameZh='赛博射手',Icon='item_41262',Type=210,MaxNum=99,SellPrice=100,AdventureSort=100013,AdventureValue=1,Condition=8,Desc='雷根贝勒公司的最新科技结晶，搭载夜视瞄准技术与风向重力修正系统的“未来”之弓，被喻为所有射手的梦想。',LoadShowSize=1.1,LoadShowRotate=250,LoadShowPose={0,0.3,0},}",
  [41263] = "{id=41263,NameZh='自由射手[1]',Icon='item_41263',Type=210,MaxNum=99,SellPrice=100,Desc='我可以让箭矢射中你身上任何一个地方，这就叫自由。',}",
  [41264] = "{id=41264,NameZh='科学救赎·之弓',Icon='item_41264',Type=210,MaxNum=99,SellPrice=100,AdventureSort=100014,AdventureValue=1,Condition=8,Desc='科学！科学！科学！为了科学一切的牺牲都是值得，蝼蚁们的生命本就毫无价值，因实验而死的他们应该觉得骄傲，这是他们的宿命！快了！就快了，我的小宝贝辛苦你了哦！记得刺穿那些反抗者的心脏哦！',Feature=1,LoadShowSize=1,LoadShowPose={0,0.4,0},}",
  [41267] = "{id=41267,NameZh='圣息崇聆·弓',Icon='item_41267',Type=210,MaxNum=99,SellPrice=100,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='光与天空，圣洁的飞鸟，神的双翼已然张开，吾虔诚的信徒，愿你在吾的庇佑下体验幸福与美好，你的灵魂之音，吾等已经听到，这把圣弓赐予你，神祇永远与你同在。',LoadShowSize=1.1,LoadShowRotate=250,LoadShowPose={0,0.3,0},}",
  [41268] = "{id=41268,NameZh='辉光十字·弓',Icon='item_41268',Type=210,MaxNum=99,SellPrice=2600,AdventureSort=100016,AdventureValue=1,Condition=8,Desc='这柄锐弓出自阿卢纳贝兹教国最有名的工匠——索罗克之手，他搜寻了整个教国寻找制作武器的材料，最终在圣域神殿的地下深处寻到了结果，吸取神灵信仰的矿石坚硬无比，制成的武器更是消灭黑暗的破晓之力。',Level=110,LoadShowSize=1.1,LoadShowRotate=250,LoadShowPose={0,0.3,0},}",
  [41269] = "{id=41269,NameZh='冰冻之弓[1]',Icon='item_41269',Type=210,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=28000,AdventureSort=6000,AdventureValue=1,Condition=8,Desc='冻成冷冰冰的弓,至于能不能拉是有点疑问。',LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0.2,0.1,0},}",
  [41270] = "{id=41270,NameZh='蔷薇灵语之弓',Icon='item_41270',Type=210,MaxNum=99,SellPrice=3200,AdventureSort=6000,AdventureValue=1,Condition=8,Desc='这把长弓被妖精一族的“灵语师”赋予了蔷薇的祝福，箭矢能够根据气味精准的追踪目标。',Level=110,LoadShowSize=1.2,LoadShowRotate=30,LoadShowPose={0,0.25,0},}",
  [41271] = "{id=41271,NameZh='红鱼花铃·弓',Icon='item_41271',Type=210,MaxNum=99,SellPrice=100,AdventureSort=100018,AdventureValue=1,Condition=8,Desc='长了一身红色鳞片的金鱼呀，喜欢在湖底的水草里悠闲地打瞌睡。有人投食的话，也会慢悠悠地钻到水面上，不紧不慢地吃鱼食。如果它会衔着弓游出水面，也不要惊讶，这是金鱼族的报答哟~',LoadShowSize=0.9,LoadShowRotate=250,LoadShowPose={-0.2,0.4,0},}",
  [41272] = "{id=41272,NameZh='埃布尔雷弓[1]',Icon='item_41272',Type=210,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=6000,AdventureValue=1,Condition=8,Desc='传说中的神射手所使用的弓，据说曾射杀过神。',LoadShowSize=1.5,LoadShowRotate=50,LoadShowPose={0,0.15,0},}",
  [41273] = "{id=41273,NameZh='湛蓝天光·弓',Icon='item_41273',Type=210,MaxNum=99,SellPrice=2800,AdventureValue=1,Condition=8,Desc='阔大的云海之上透出湛蓝天光，晴空下的战士们振作起了精神。战斗的号角即将吹响，握紧这把长弓吧，它印证着你的忠诚，勇敢与希望。',Level=110,LoadShowSize=0.9,LoadShowRotate=260,LoadShowPose={-0.2,0.4,0},}",
  [41274] = "{id=41274,NameZh='天虹圣遗·弓',Icon='item_41274',Type=210,MaxNum=99,SellPrice=100,AdventureSort=100019,AdventureValue=1,Condition=8,Desc='浮空精灵收集彩虹桥碎片制作的长弓，聚集虹光化为箭矢，贯穿你的敌人！',LoadShowSize=1.2,LoadShowPose={0,0.3,0},}",
  [41275] = "{id=41275,NameZh='月下祈者·弓',Icon='item_41275',Type=210,MaxNum=99,SellPrice=100,AdventureSort=6000,AdventureValue=1,Condition=8,Desc='冰封千年的陨铁，王国的工匠们用尽办法也无法将其熔铸，却因小学徒的一次失误暴露在月光下。那一刻奇迹发生，陨铁融化宛若水银般流转，在月光下散发耀眼星辉。\n此乃月光赐福之神弓，持弓者当以月光之力，击穿邪祟，照亮夜空！',LoadShowRotate=270,LoadShowPose={0.5,0,-2},}",
  [41276] = "{id=41276,NameZh='英灵起点·弓[2]',Icon='item_41276',Type=210,Quality=2,MaxNum=99,SellPrice=100,Desc='克里图拉新生领到的初心武器，致敬英灵而铸上蓝金涂装。据说设计者是个传承了斐扬古老技艺的工匠。这把弓原来用于月下狩猎，被誉为“第二轮下弦月”。',NoStorage=5,LoadShowSize=1,LoadShowPose={0,0.3,0},}",
  [41277] = "{id=41277,NameZh='英灵信标·弓[2]',Icon='item_41277',Type=210,Quality=3,MaxNum=99,SellPrice=100,Desc='这把弓是指引女武神降临、迎接英灵的道标。阵亡的勇士抱着它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,LoadShowSize=1,LoadShowPose={0,0.3,0},}",
  [41278] = "{id=41278,NameZh='英灵羽证·弓[2]',Icon='item_41278',Type=210,Quality=3,MaxNum=99,SellPrice=100,Desc='英灵的证明。潜入学院的女武神在弓中注入了奥丁领域的魔力。弓长出了羽翼，一瞬间后发先至，直击猎物的灵魂。',NoStorage=5,LoadShowSize=1,LoadShowPose={0,0.3,0},}",
  [41279] = "{id=41279,NameZh='波姬弓',Icon='item_41279',Type=210,Quality=3,MaxNum=99,SellPrice=100,}",
  [41280] = "{id=41280,NameZh='远古回音·弓',Icon='item_41280',Type=210,MaxNum=99,SellPrice=3200,AdventureSort=100020,AdventureValue=1,Condition=8,Desc='铭刻着神秘纹样的弓箭，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,LoadShowSize=1,LoadShowPose={0,0.3,0},}",
  [41282] = "{id=41282,NameZh='王国荣辉·弓',Icon='item_41282',Type=210,MaxNum=99,SellPrice=100,AdventureSort=100023,AdventureValue=1,Condition=8,Desc='效忠于王室的宫廷侍卫所持的长弓，其上绘有卢恩王家纹章。然而，繁复的纯金装饰极大地增加了长弓的重量，以至于它不适合拿在手中。',LoadShowSize=1,LoadShowRotate=90,LoadShowPose={0,0.2,0},}",
  [41286] = "{id=41286,NameZh='凛冬结晶·极限',Icon='item_41286',Type=454,Quality=4,MaxNum=1,SellPrice=100,Desc='霜之巨人中最强的战士名为赫朗格尼尔，他死后不屈的执念冰封了数万里的海洋，而许多年后人们才发现他的尸骸，居然化作了这把冰封的巨弓。',NoSale=1,NoStorage=7,TFValidDate='2022-03-10 05:00:00',ValidDate='2022-03-23 05:00:00',}",
  [41287] = "{id=41287,NameZh='英灵信标·弓[2]',Icon='item_41277',Type=210,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=100024,AdventureValue=1,Condition=8,Desc='这把弓是指引女武神降临、迎接英灵的道标。阵亡的勇士抱着它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,LoadShowSize=1,LoadShowPose={0,0.3,0},}",
  [41288] = "{id=41288,NameZh='英灵羽证·弓[2]',Icon='item_41278',Type=210,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=100025,AdventureValue=1,Condition=8,Desc='英灵的证明。潜入学院的女武神在弓中注入了奥丁领域的魔力。弓长出了羽翼，一瞬间后发先至，直击猎物的灵魂。',NoStorage=5,LoadShowSize=1,LoadShowPose={0,0.3,0},}",
  [41292] = "{id=41292,NameZh='毁灭者之弓[1]',Icon='item_41292',Type=210,Quality=4,MaxNum=99,SellPrice=100,Desc='没有人能直视它的锋芒，因为所有被瞄准的都已奔赴死亡，毁灭者是敌人所赋予它的称号。',}",
