  [41513] = "{id=41513,NameZh='痊愈光辉[2]',Icon='item_41504',Type=220,MaxNum=99,SellPrice=100,Desc='为将治愈能力提升至极致而开发的杖。强大的治愈能力的代价是会剧烈消耗使用者的精神力。',Level=10,Feature=4,}",
