  [41518] = "{id=41518,NameZh='恢复之杖[1]',Icon='item_41518',Type=190,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=75,AdventureSort=8000,AdventureValue=1,Condition=8,Desc='用被祝福的天地树树干制作的以治疗为目的的法杖。法杖上用古代语写着无病乃长寿之起源。',Feature=1,LoadShowSize=1.2,LoadShowRotate=160,LoadShowPose={0,0.45,0},}",
