  [41522] = "{id=41522,NameZh='卡尔加权杖[2]',Icon='item_41504',Type=220,MaxNum=99,SellPrice=100,Desc='在木巨人的语言中卡尔加的意思是“呐喊”，拥有尖刃的沉重的权杖。',Level=10,Feature=4,}",
