  [41532] = "{id=41532,NameZh='日记本',Icon='item_41504',Type=220,MaxNum=99,SellPrice=100,Desc='少女的日记本。内容上写的好像是日期天气以及当天生活内容的样子。因为是由未知的文字所写成的，因此无法阅读辨识。',Level=50,}",
