  [41536] = "{id=41536,NameZh='军用战锤',Icon='item_41536',Type=220,MaxNum=99,SellPrice=840,Desc='经历了多次战争不断修改设计并最终定型。重视实战效果的战锤',Level=70,}",
  [41537] = "{id=41537,NameZh='制式锤',Icon='item_41537',Type=220,MaxNum=99,SellPrice=960,Desc='专门为佣兵定制的作战用锤子。适应各种复杂环境。',Level=80,}",
  [41538] = "{id=41538,NameZh='阿斯加德之怒',Icon='item_41538',Type=220,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=100001,AdventureValue=1,Condition=8,Desc='这把大锤用阿萨神域的碎片打造，“诸神的黄昏”之战，它战胜了大蛇耶梦加得，也因此在瞬息之间造就了方圆几万公里的废墟。（建议作为武器外观使用）',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [41539] = "{id=41539,NameZh='星界·星辰暴怒',Icon='item_41539',Type=220,MaxNum=99,AuctionPrice=1,SellPrice=79600,AdventureSort=100002,AdventureValue=1,Condition=8,Desc='利用星辰中提炼出的珍贵矿石制作而成，反复的锤炼使得它的重量极大，使用起来能够造成巨大的伤害。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [41540] = "{id=41540,NameZh='英灵·古尔之狂怒',Icon='item_41540',Type=220,MaxNum=99,SellPrice=100,AdventureSort=100006,AdventureValue=1,Condition=8,Desc='战争神——诗嘉古尔，作为奥丁的倒酒侍女，古尔骨子里如同奥丁一般狂野，渴望战争，而古尔之狂怒就是最好的证明。这是只有最强大的勇士才能驾驭的神兵。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.12,0},}",
  [41541] = "{id=41541,NameZh='圣徒之锤[1]',Icon='item_41541',Type=220,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='商人协会委托“光明圣徒”安德鲁设计锻造的战锤，战锤非常沉重，使用起来杀伤力惊人，是最适合商人铁匠使用的武器，在某些时刻还可以当作锻造锤使用。受到光明圣徒的祝福，安全精炼时消耗的装备件数减少一半。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [41542] = "{id=41542,NameZh='衔尾者蛇锤',Icon='item_41542',Type=220,MaxNum=99,SellPrice=100,AdventureSort=100004,AdventureValue=1,Condition=8,Desc='锤身用黄金打造，攻击时震耳欲聋的锤声都能瞬间将敌人击晕。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.12,0},}",
  [41543] = "{id=41543,NameZh='羽毛权杖[1]',Icon='item_41543',Type=220,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=700,AdventureSort=8000,AdventureValue=1,Condition=8,Desc='用少量材料炼制出的羽翼权杖实验品，虽然能力有所欠缺，但手感反而更适合初学者呢~',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.12,0},}",
  [41544] = "{id=41544,NameZh='羽翼权杖[1]',Icon='item_41544',Type=220,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=850,AdventureSort=8000,AdventureValue=1,Condition=8,Desc='权杖顶部的宝珠是用巴尼米乐斯最喜欢的食物炼成的，所以使用这把杖会让巴尼米乐斯的状态格外兴奋。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.12,0},}",
