  [41551] = "{id=41551,NameZh='雷神之锤',Icon='item_41551',Type=455,Quality=4,MaxNum=1,SellPrice=100,Desc='传说雷神托尔为了向父亲证明自己的实力，竟徒手将一枚行星中心的星核剥离了出来，以炽热的星核为材料打造了这柄雷神之锤。',NoSale=1,NoStorage=7,}",
