  [41554] = "{id=41554,NameZh='月辉·瞳影之锤',Icon='item_41554',Type=220,MaxNum=99,SellPrice=100,AdventureSort=100008,AdventureValue=1,Condition=8,Desc='暗月马戏团标志性的武器，因其式样低调而华丽又非常稀有，成为了年轻冒险家追捧的热门武器',LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [41555] = "{id=41555,NameZh='日耀·金翼之锤',Icon='item_41555',Type=220,MaxNum=99,SellPrice=100,AdventureSort=100007,AdventureValue=1,Condition=8,Desc='太阳马戏团标志性的武器，耀眼的金光和精致的造型，是坚持爱与正义的冒险者所追寻的目标',LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.15,0},}",
  [41556] = "{id=41556,NameZh='工程扳手[1]',Icon='item_41556',Type=220,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=700,AdventureSort=8000,AdventureValue=1,Condition=8,Desc='“当你拿起它，你便选择了一种人生。它会是你最可靠的伙伴”——米德加尔特传奇机匠',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.15,0},}",
