  [41558] = "{id=41558,NameZh='碎雪·流霜镇狱',Icon='item_41558',Type=220,MaxNum=99,SellPrice=100,AdventureSort=100009,AdventureValue=1,Condition=8,Desc='充满冰霜之力的巨锤，每一次敲击都冰屑四溅，就算是千年冻土在它的力量面前也脆如纸薄。',LoadShowSize=1.5,LoadShowRotate=70,LoadShowPose={0,0.15,0},}",
  [41559] = "{id=41559,NameZh='炎魂·修罗炼狱',Icon='item_41559',Type=220,MaxNum=99,SellPrice=100,AdventureSort=100010,AdventureValue=1,Condition=8,Desc='充满火焰之力的巨锤，每一次敲击都火花四溅，就算是地狱之门在它的力量面前也脆如纸薄。',LoadShowSize=1.5,LoadShowRotate=70,LoadShowPose={0,0.15,0},}",
  [41560] = "{id=41560,NameZh='枫忆之锤',Icon='item_41560',Type=220,MaxNum=99,SellPrice=100,AdventureSort=100003,AdventureValue=1,Condition=8,Desc='一颗枫树不偏不倚的长在了路中间，附近的居民都决定铲除这颗碍眼的枫树，但是铁匠修尔却不这么认为，他觉得这颗枫树是小镇独特的风景，在修尔的阻拦下，枫树蓬勃的生长着，一直到修尔老去的那天，这颗枫树竟也神奇的消失了，不就知道，人们发现在修尔的家门口出现了一把枫叶图案的锤子…',LoadShowSize=1.5,LoadShowRotate=70,LoadShowPose={0,0.15,0},}",
  [41561] = "{id=41561,NameZh='信仰之锤',Icon='item_41561',Type=220,MaxNum=99,SellPrice=100,AdventureSort=100005,AdventureValue=1,Condition=8,Desc='巴风特曾带领手下对梦罗克进行过一次史无前例的大侵袭，这次的战争造成了数以万计的民众伤亡，在危难的关头有十四位勇士站了出来，他们牺牲了自己保护了梦罗克，死后的他们留下了自己的武器，这些武器被梦罗克的人们当做信仰的象征，这把锤便是十四把武器之一。',LoadShowSize=1.5,LoadShowRotate=70,LoadShowPose={0,0.15,0},}",
  [41562] = "{id=41562,NameZh='亡灵之锤',Icon='item_41562',Type=220,MaxNum=99,SellPrice=2100,AdventureValue=1,Condition=8,Desc='这把锤子轻如空气，但击打在敌人身上却会变得格外沉重。',Level=95,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,0.15,0},}",
  [41563] = "{id=41563,NameZh='埃琉德尼尔榔锤',Icon='item_41563',Type=220,MaxNum=99,SellPrice=100,AdventureSort=100012,AdventureValue=1,Condition=8,Desc='啊哈！又到了我最喜欢的“100t大锤砸脑袋”环节，下一位幸运儿会是谁！',TFValidDate='2019-10-28 05:00:00',ValidDate='2019-10-31 05:00:00',LoadShowSize=1.5,LoadShowRotate=70,LoadShowPose={0,0.15,0},}",
  [41564] = "{id=41564,NameZh='镇魂[1]',Icon='item_41564',Type=220,MaxNum=99,SellPrice=100,Feature=1,}",
  [41565] = "{id=41565,NameZh='审判之锤★[1]',Icon='item_41565',Type=220,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=8000,AdventureValue=1,Condition=8,Desc='拥有对恶魔下达裁决之力的钝器，这一锤子砸下去，估计连梦罗克都吃不消。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.15,0},}",
  [41566] = "{id=41566,NameZh='魔锤安魂曲★[1]',Icon='item_41566',Type=220,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=8000,AdventureValue=1,Condition=8,Desc='无坚不摧的钝器。',Feature=1,LoadShowSize=1.4,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [41567] = "{id=41567,NameZh='艾尔德之锤★[1]',Icon='item_41567',Type=220,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=8000,AdventureValue=1,Condition=8,Desc='这把锤的顶端镶嵌着以七种毒蛇的牙炼制出的宝珠，普通的盔甲只要碰到它就会受到腐蚀。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.02,0},}",
  [41568] = "{id=41568,NameZh='复仇女神★[1]',Icon='item_41568',Type=190,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=8000,AdventureValue=1,Condition=8,Desc='为驱魔而制造的纯银巨大权杖。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [41569] = "{id=41569,NameZh='暗服事权杖[1]',Icon='item_41503',Type=220,MaxNum=99,SellPrice=280,Desc='铁制的钝器，是一种可以给予对方痛击的钝器。',Level=20,Feature=4,}",
  [41570] = "{id=41570,NameZh='破旧的平底锅[1]',Icon='item_41570',Type=220,MaxNum=99,SellPrice=100,}",
  [41571] = "{id=41571,NameZh='生命体战锤',Icon='item_41571',Type=220,MaxNum=99,SellPrice=2400,Desc='雷根贝勒公司所开发的，以生命体为能量的战锤。两边的钻头型设计让它拥有极大的破坏力。',Level=100,}",
  [41572] = "{id=41572,NameZh='魔器·锡蒙利',Icon='item_41572',Type=220,MaxNum=99,SellPrice=100,AdventureSort=100011,AdventureValue=1,Condition=8,Desc='梦罗克碎片打造的禁忌武器，对应着异世界恶魔No.66·锡蒙利，他统率着异世界的地狱魂灵，是一名骑黑马上的战士。',LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [41573] = "{id=41573,NameZh='冲击战锤',Icon='item_41573',Type=220,MaxNum=99,SellPrice=100,AdventureSort=100013,AdventureValue=1,Condition=8,Desc='想象一下，用这把自带喷气式驱动力的战锤敲在敌人的脑袋上...啧啧！',LoadShowSize=1.4,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [41574] = "{id=41574,NameZh='负心人[1]',Icon='item_41574',Type=220,MaxNum=99,SellPrice=100,Desc='“相信我，这家伙会伤透他们的心。”——忽克连',}",
  [41575] = "{id=41575,NameZh='科学救赎·之锤',Icon='item_41575',Type=220,MaxNum=99,SellPrice=100,AdventureSort=100014,AdventureValue=1,Condition=8,Desc='科学！科学！科学！为了科学一切的牺牲都是值得，蝼蚁们的生命本就毫无价值，因实验而死的他们应该觉得骄傲，这是他们的宿命！快了！就快了，等我的战锤制作出来，那些反抗者就等着被战锤砸成肉泥吧…呵呵……哈哈哈',Feature=1,LoadShowSize=1.5,}",
  [41578] = "{id=41578,NameZh='圣息崇聆·锤',Icon='item_41578',Type=220,MaxNum=99,SellPrice=100,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='光与天空，圣洁的飞鸟，神的双翼已然张开，吾虔诚的信徒，愿你在吾的庇佑下体验幸福与美好，你的灵魂之音，吾等已经听到，这把圣锤赐予你，神祇永远与你同在。',LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.15,0},}",
  [41579] = "{id=41579,NameZh='辉光十字·锤',Icon='item_41579',Type=220,MaxNum=99,SellPrice=2600,AdventureSort=100016,AdventureValue=1,Condition=8,Desc='这把战锤出自阿卢纳贝兹教国最有名的工匠——索罗克之手，他搜寻了整个教国寻找制作武器的材料，最终在圣域神殿的地下深处寻到了结果，吸取神灵信仰的矿石坚硬无比，制成的武器更是消灭黑暗的破晓之力。',Level=110,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.15,0},}",
  [41580] = "{id=41580,NameZh='蔷薇灵语之锤',Icon='item_41580',Type=220,MaxNum=99,SellPrice=3200,AdventureSort=8000,AdventureValue=1,Condition=8,Desc='妖精一族的“神工匠”打造道具时使用的锤子，灵语师们觉得太过单调，用鲜花装饰了它。',Level=110,LoadShowSize=1.5,LoadShowRotate=90,}",
  [41581] = "{id=41581,NameZh='红鱼花铃·锤',Icon='item_41581',Type=220,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='长了一身红色鳞片的金鱼呀，喜欢在湖底的水草里悠闲地打瞌睡。有人投食的话，也会慢悠悠地钻到水面上，不紧不慢地吃鱼食。如果它会衔着锤游出水面，也不要惊讶，这是金鱼族的报答哟~',LoadShowSize=1.4,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [41582] = "{id=41582,NameZh='忽克连的精炼之锤[1]',Icon='item_41582',Type=220,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=8000,AdventureValue=1,Condition=8,Desc='忽克连做为精炼时爱用的锤子。看起来像个非常高级强力的装备却感觉到某种不安定的气息。',LoadShowSize=1.5,LoadShowRotate=50,LoadShowPose={0,0,0},}",
  [41583] = "{id=41583,NameZh='湛蓝天光·锤',Icon='item_41583',Type=220,MaxNum=99,SellPrice=2800,AdventureValue=1,Condition=8,Desc='阔大的云海之上透出湛蓝天光，晴空下的战士们振作起了精神。战斗的号角即将吹响，握紧这把战锤吧，它印证着你的忠诚，勇敢与希望。',Level=110,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.2,0},}",
  [41584] = "{id=41584,NameZh='天虹圣遗·锤',Icon='item_41584',Type=220,MaxNum=99,SellPrice=100,AdventureSort=100019,AdventureValue=1,Condition=8,Desc='浮空精灵收集彩虹桥碎片打造的重锤，强烈的冲击能激起炫目的虹光。',LoadShowSize=1.5,}",
  [41585] = "{id=41585,NameZh='月下祈者·锤',Icon='item_41585',Type=220,MaxNum=99,SellPrice=100,AdventureSort=8000,AdventureValue=1,Condition=8,Desc='冰封千年的陨铁，王国的工匠们用尽办法也无法将其熔铸，却因小学徒的一次失误暴露在月光下。那一刻奇迹发生，陨铁融化宛若水银般流转，在月光下散发耀眼星辉。\n此乃月光赐福之圣锤，持锤者当以月光之力，击碎虚妄，破除邪恶！',LoadShowRotate=80,LoadShowPose={0,-0.3,-1},}",
  [41586] = "{id=41586,NameZh='英灵起点·锤[2]',Icon='item_41586',Type=220,Quality=2,MaxNum=99,SellPrice=100,Desc='克里图拉新生领到的初心武器，致敬英灵而铸上蓝金涂装。据说设计者是来自校外的合作者忽克连。为了让大家别忘强化武器，他做了这把锤，但在精炼中这把锤便成了攻城锤的外形。',NoStorage=5,LoadShowSize=1.5,}",
  [41587] = "{id=41587,NameZh='英灵信标·锤[2]',Icon='item_41587',Type=220,Quality=3,MaxNum=99,SellPrice=100,Desc='这把锤子是指引女武神降临、迎接英灵的道标。阵亡的勇士抱着它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,LoadShowSize=1.5,}",
  [41588] = "{id=41588,NameZh='英灵羽证·锤[2]',Icon='item_41588',Type=220,Quality=3,MaxNum=99,SellPrice=100,Desc='英灵的证明。潜入学院的女武神在锤中注入了奥丁领域的魔力。巨锤长出了羽翼，拥有比奥丁和托尔的锤子更迅速的击打频率。',NoStorage=5,LoadShowSize=1.5,}",
  [41590] = "{id=41590,NameZh='远古回音·锤',Icon='item_41590',Type=220,MaxNum=99,SellPrice=3200,AdventureSort=100020,AdventureValue=1,Condition=8,Desc='铭刻着神秘纹样的锤子，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,LoadShowSize=1.5,}",
  [41592] = "{id=41592,NameZh='王国荣辉·锤',Icon='item_41592',Type=220,MaxNum=99,SellPrice=100,AdventureSort=100023,AdventureValue=1,Condition=8,Desc='效忠于王室的宫廷侍卫所持的重锤，其上绘有卢恩王家纹章。重锤的分量大部分来源于夸张的黄金装饰，这决定了它是一把礼器，而非趁手的兵器。',LoadShowSize=1.6,LoadShowRotate=90,}",
  [41596] = "{id=41596,NameZh='雷神之锤·极限',Icon='item_41596',Type=455,Quality=4,MaxNum=1,SellPrice=100,Desc='传说雷神托尔为了向父亲证明自己的实力，竟徒手将一枚行星中心的星核剥离了出来，以炽热的星核为材料打造了这柄雷神之锤。',NoSale=1,NoStorage=7,TFValidDate='2022-03-10 05:00:00',ValidDate='2022-03-23 05:00:00',}",
  [41597] = "{id=41597,NameZh='英灵信标·锤[2]',Icon='item_41587',Type=220,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=100024,AdventureValue=1,Condition=8,Desc='这把锤子是指引女武神降临、迎接英灵的道标。阵亡的勇士抱着它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,LoadShowSize=1.5,}",
  [41598] = "{id=41598,NameZh='英灵羽证·锤[2]',Icon='item_41588',Type=220,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=100025,AdventureValue=1,Condition=8,Desc='英灵的证明。潜入学院的女武神在锤中注入了奥丁领域的魔力。巨锤长出了羽翼，拥有比奥丁和托尔的锤子更迅速的击打频率。',NoStorage=5,LoadShowSize=1.5,}",
  [41599] = "{id=41599,NameZh='亡者祷告·破晓',Icon='item_41599',Type=190,Quality=3,MaxNum=99,SellPrice=100,Desc='死亡聆听了最多的祷告，尼夫海姆的每一寸土地都流淌过忏悔的泪水。',LoadShowSize=0.7,}",
