  [41604] = "{id=41604,NameZh='爆裂重锤[1]',Icon='item_41604',Type=220,Quality=3,MaxNum=99,SellPrice=100,Desc='传说唯有拥有巨人族的力量才能举起的重锤，拿在手中便是无言的威慑。',}",
  [41605] = "{id=41605,NameZh='索列姆之锤[1]',Icon='item_41605',Type=220,Quality=4,MaxNum=99,SellPrice=100,Desc='巨人索列姆曾盗走雷神之锤，并命侏儒中的神工匠对其进行仿制，最终成型的索列姆之锤拥有堪比雷神之锤的威力，能粉碎神的躯体。',}",
  [41606] = "{id=41606,NameZh='初心淬炼·碎星',Icon='item_41606',Type=220,Quality=4,MaxNum=99,SellPrice=100,Desc='铁匠锻造的不仅是武器，更是自己的心，在千百遍的淬炼中变得坚韧。',LoadShowSize=0.7,}",
