  [41610] = "{id=41610,NameZh='魔翼之杖[1]',Icon='item_40693',Type=190,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='据说法杖之上的羽毛来自于某位天使，拥有强大的魔力。',LoadShowSize=0.7,}",
  [41611] = "{id=41611,NameZh='死亡祈祷[1]',Icon='item_40694',Type=190,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='据说法杖之上的羽毛来自于某位堕天使，弥漫着死亡的气息。',LoadShowSize=0.7,}",
  [41616] = "{id=41616,NameZh='匠心之锤[1]',Icon='item_41613',Type=220,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='只有最纯粹的匠心才能握住这把被缠绕烈焰的锤而不被灼伤，因为他的心比钢铁更坚毅。',LoadShowSize=1.5,LoadShowRotate=50,LoadShowPose={0,0,0},}",
  [41617] = "{id=41617,NameZh='弧光扳手[1]',Icon='item_41617',Type=220,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=700,Desc='“当你拿起它，你便选择了一种人生。它会是你最可靠的伙伴”——米德加尔特传奇机匠',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.15,0},}",
  [41801] = "{id=41801,NameZh='斧',Icon='item_41801',Type=230,MaxNum=99,SellPrice=140,Desc='简单的使用方法，方便任何人使用的斧。',Level=10,Feature=4,}",
