  [41805] = "{id=41805,NameZh='切削之斧[1]',Icon='item_41805',Type=230,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=576,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='取动物的肉时所用的斧。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [41806] = "{id=41806,NameZh='毁灭之斧[1]',Icon='item_41806',Type=230,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=240,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='据说可以破坏一切的魔斧，吞噬持有者的灵魂增加力量，若过度依赖它，结局是成为没有灵魂只会肆意破坏的空壳。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.08,0},}",
  [41807] = "{id=41807,NameZh='兽人斧[1]',Icon='item_41807',Type=230,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=480,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='兽人使用的斧。',Feature=1,LoadShowSize=1.4,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [41808] = "{id=41808,NameZh='克莱伊特斧[1]',Icon='item_41808',Type=230,MaxNum=99,SellPrice=100,Desc='有相当大的锋刃，会让敌人看到时心存畏惧巨大双手斧。',Feature=4,}",
  [41809] = "{id=41809,NameZh='碎心斧[1]',Icon='item_41809',Type=230,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=2800,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='任何盔甲都无法抵挡的双手斧。 特殊加工的斧刃好像可以砍破任何盔甲似的锐利而沉重。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [41810] = "{id=41810,NameZh='斯勒特斧[1]',Icon='item_41810',Type=230,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=432,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='有很多刀刃的斧，看起来让人心惊胆跳。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.2,0},}",
  [41811] = "{id=41811,NameZh='斩首之斧[1]',Icon='item_41811',Type=230,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=840,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='角斗士为斩杀特制的双手剑。 在对人战斗中可发挥极大效果。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.2,0},}",
  [41812] = "{id=41812,NameZh='血腥战斧[1]',Icon='item_41812',Type=230,MaxNum=99,SellPrice=100,Desc='在战场上挥舞着斧沾满了血，呈现出可怕的杀气 用这残忍的斧刃对着敌人时，敌人会陷入死亡的恐惧中，是可怕的斧。',Feature=4,}",
  [41813] = "{id=41813,NameZh='希尔之斧[1]',Icon='item_41813',Type=230,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=720,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='传说中奥丁的侍女伯伦希尔曾经用过的斧子，然而对于人类似乎有些过于沉重了。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.2,0},}",
  [41814] = "{id=41814,NameZh='血斧[1]',Icon='item_41814',Type=230,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=864,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='蕴含着魔性的斧头，会变成兴奋嗜血的状态，去寻找敌人的斧。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [41815] = "{id=41815,NameZh='暗灵之斧[1]',Icon='item_41815',Type=230,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=2000,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='可令在九泉之下徘徊不去的灵魂安息的斧。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
