  [41817] = "{id=41817,NameZh='智天使之斧[1]',Icon='item_41817',Type=230,MaxNum=99,SellPrice=100,Desc='拥有神圣力量的斧。典礼上常常使用。',Feature=4,}",
  [41818] = "{id=41818,NameZh='急冻战斧[1]',Icon='item_41818',Type=230,MaxNum=99,SellPrice=100,Desc='用极地酷寒地区的矿石制作的斧头，有股寒风刺骨的感觉。',Feature=4,}",
  [41819] = "{id=41819,NameZh='老兵之斧[1]',Icon='item_41819',Type=230,MaxNum=99,SellPrice=100,Desc='太古的铁匠用神赐给人类的金属制作的斧子，懂得如何使用金属的人使用这把斧子，可以发挥出无法形容的力量。',Feature=4,}",
  [41820] = "{id=41820,NameZh='烈焰战斧[1]',Icon='item_41820',Type=230,MaxNum=99,SellPrice=100,Desc='据说是居住在火山的铁匠所制作的巨型双手斧，有股热气沸腾的感觉。',Feature=4,}",
  [41821] = "{id=41821,NameZh='合金之斧[1]',Icon='item_41821',Type=230,MaxNum=99,SellPrice=100,Desc='强大的斧头，会自我吸收天地灵气而成长。',Feature=4,}",
