  [41826] = "{id=41826,NameZh='狂怒_飓风[1]',Icon='item_41826',Type=230,MaxNum=99,SellPrice=100,Desc='飓风样式的巨大双手斧。斧子中心部分凝聚着飓风力量，武器越强大，凝聚的力量越强。',Feature=4,}",
  [41827] = "{id=41827,NameZh='神圣天国斧[1]',Icon='item_41827',Type=230,MaxNum=99,SellPrice=100,Desc='来自天国的神奇之斧。',Feature=4,}",
