  [41831] = "{id=41831,NameZh='战斧',Icon='item_41831',Type=230,MaxNum=99,SellPrice=420,Desc='轻便的适合挥砍的斧头。很受新兵们的欢迎',Level=30,}",
  [41832] = "{id=41832,NameZh='钢战斧',Icon='item_41832',Type=230,MaxNum=99,SellPrice=720,Desc='耐用的钢铁打造的军用斧。',Level=60,}",
  [41833] = "{id=41833,NameZh='巨型战斧',Icon='item_41833',Type=230,MaxNum=99,SellPrice=1080,Desc='对自己力气有信心的人爱用的武器。',Level=90,}",
  [41834] = "{id=41834,NameZh='毁灭手斧[1]',Icon='item_41834',Type=230,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=960,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='吞吃了足够灵魂的毁灭之斧会变成毁灭手斧，给与持有者的力量更加诱人，需要献出代价也更大，一旦握住它，似乎会听见某个声音在脑海里轻轻低语，“去劈开理智的枷锁，拥抱力量的深渊吧。”',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.08,0},}",
  [41835] = "{id=41835,NameZh='贝克之斧[1]',Icon='item_41835',Type=230,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1152,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='铁匠公会仿造著名的贝克战斧制作的量产型斧头。',Feature=1,LoadShowSize=1.35,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [41836] = "{id=41836,NameZh='斯勒特手斧[1]',Icon='item_41836',Type=230,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=1120,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='多刃斧。使用起来意外的轻巧。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.2,0},}",
  [41837] = "{id=41837,NameZh='冰火之心',Icon='item_41837',Type=230,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=100001,AdventureValue=1,Condition=8,Desc='由辛德里锻造的巨斧，华纳神族时期，洛基将它赠送给了巨人族最强悍的勇士艾契思汀，结果这位勇士在战斗时不慎被手持的巨斧砍伤了腿，然后再也站不起来了。因此，这把巨斧素有“诅咒之斧”的称号，传说持有它的人只要意志有所动摇，就会被它所伤。（建议作为武器外观使用）',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [41838] = "{id=41838,NameZh='风灵钢斧[1]',Icon='item_41838',Type=230,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1660,AdventureSort=9900,AdventureValue=1,Condition=8,Desc='运用最新工艺将风灵矿石配合符文法阵试作的蕴含风之力的斧头。',Feature=1,LoadShowSize=1.7,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [41839] = "{id=41839,NameZh='火灵钢斧[1]',Icon='item_41839',Type=230,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1660,AdventureSort=9900,AdventureValue=1,Condition=8,Desc='运用最新工艺将火灵矿石配合符文法阵试作的蕴含火之力的斧头。',Feature=1,LoadShowSize=1.7,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [41840] = "{id=41840,NameZh='地灵钢斧[1]',Icon='item_41840',Type=230,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1660,AdventureSort=9900,AdventureValue=1,Condition=8,Desc='运用最新工艺将地灵矿石配合符文法阵试作的蕴含地之力的斧头。',Feature=1,LoadShowSize=1.7,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [41841] = "{id=41841,NameZh='水灵钢斧[1]',Icon='item_41841',Type=230,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1660,AdventureSort=9900,AdventureValue=1,Condition=8,Desc='运用最新工艺将水灵矿石配合符文法阵试作的蕴含水之力的斧头。',Feature=1,LoadShowSize=1.7,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [41842] = "{id=41842,NameZh='星界·天命者',Icon='item_41842',Type=230,MaxNum=99,AuctionPrice=1,SellPrice=79600,AdventureSort=100002,AdventureValue=1,Condition=8,Desc='利用星辰中提炼出的珍贵矿石制作而成，星辰矿石使得这把武器锋锐无比，挥舞之间就可对敌人造成不可磨灭的重创。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.05,0},}",
  [41843] = "{id=41843,NameZh='斩击之斧[1]',Icon='item_41843',Type=230,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1152,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='特化斩击的重斧。有些剑士偶尔也会使用它。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.2,0},}",
  [41844] = "{id=41844,NameZh='追风之斧[1]',Icon='item_41844',Type=230,Quality=3,MaxNum=99,SellPrice=100,Desc='据使用者描述，该斧在挥砍的时候仿佛能感受到风的流动。',Feature=1,}",
  [41845] = "{id=41845,NameZh='英灵·斯克之意志',Icon='item_41845',Type=230,MaxNum=99,SellPrice=100,AdventureSort=100006,AdventureValue=1,Condition=8,Desc='战斧神——斯克嘉莉德的意志化身，斯克嘉莉德之斧，对英灵殿有重大贡献的人才能得到这神之意志的化身，违抗神之意志的人，必将遭到毁灭！',Feature=1,LoadShowSize=1.4,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [41846] = "{id=41846,NameZh='圣徒巨斧[1]',Icon='item_41846',Type=230,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='安德鲁立志要完成所有武器的研究，而巨斧是其中最难的武器之一，既要保持巨大的杀伤力，又要轻巧便于挥舞。所幸安德鲁成功的研究出了“圣徒巨斧”这一强力的武器。而安德鲁也因此闻名大陆。受到光明圣徒的祝福，安全精炼时消耗的装备件数减少一半。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [41847] = "{id=41847,NameZh='衔尾者战斧',Icon='item_41847',Type=230,MaxNum=99,SellPrice=100,AdventureSort=100004,AdventureValue=1,Condition=8,Desc='威力如同巨蛇一般强劲的战斧，在战斗中毫不费力的将敌手击碎。',Feature=1,LoadShowSize=1.4,LoadShowRotate=70,LoadShowPose={0,0.3,0},}",
  [41848] = "{id=41848,NameZh='鲜血斧[1]',Icon='item_41848',Type=230,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=840,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='暴躁的锻造大师金利设计的战斧，被砍伤的人会血流不止。',Feature=1,LoadShowSize=1.4,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
