  [41852] = "{id=41852,NameZh='高级乐园团大斧[1]',Icon='item_41803',Type=230,MaxNum=99,SellPrice=100,Level=1,NoStorage=5,}",
  [41853] = "{id=41853,NameZh='圣灵·斯克之坚定斧',Icon='item_41853',Type=230,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='战斧神——斯克嘉莉德的斧，一旦它被举起，那这一斩就必定会命中目标。',Feature=1,LoadShowSize=1.4,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [41854] = "{id=41854,NameZh='丹恩之斧',Icon='item_41833',Type=230,MaxNum=99,SellPrice=1140,Desc='矮人战王丹恩的随身战斧，伴随他经历了无数场惊心动魄的战争，象征着矮人坚韧的精神。',Level=95,}",
  [41855] = "{id=41855,NameZh='硝烟终结者',Icon='item_41855',Type=456,Quality=4,MaxNum=1,SellPrice=100,Desc='当诸神黄昏的硝烟蔓延到了侏儒王国时，侏儒兄弟辛德里和勃洛克以寿命为代价，铸造了这把世上最强的战斧，它仅一击就天崩地裂，瞬间便击溃了龙族的侵略者。',NoSale=1,NoStorage=7,}",
  [41856] = "{id=41856,NameZh='硝烟终结者·精锻',Icon='item_41856',Type=456,Quality=4,MaxNum=1,SellPrice=100,Desc='当诸神黄昏的硝烟蔓延到了侏儒王国时，侏儒兄弟辛德里和勃洛克以寿命为代价，铸造了这把世上最强的战斧，它仅一击就天崩地裂，瞬间便击溃了龙族的侵略者。',NoSale=1,NoStorage=7,}",
  [41857] = "{id=41857,NameZh='硝烟终结者·神铸',Icon='item_41857',Type=456,Quality=4,MaxNum=1,SellPrice=100,Desc='当诸神黄昏的硝烟蔓延到了侏儒王国时，侏儒兄弟辛德里和勃洛克以寿命为代价，铸造了这把世上最强的战斧，它仅一击就天崩地裂，瞬间便击溃了龙族的侵略者。',NoSale=1,NoStorage=7,}",
  [41858] = "{id=41858,NameZh='月辉·破风之斧',Icon='item_41858',Type=230,MaxNum=99,SellPrice=100,AdventureSort=100008,AdventureValue=1,Condition=8,Desc='暗月马戏团标志性的武器，因其式样低调而华丽又非常稀有，成为了年轻冒险家追捧的热门武器',LoadShowSize=1.4,LoadShowRotate=70,LoadShowPose={0,0.2,0},}",
  [41859] = "{id=41859,NameZh='日耀·霓光之斧',Icon='item_41859',Type=230,MaxNum=99,SellPrice=100,AdventureSort=100007,AdventureValue=1,Condition=8,Desc='太阳马戏团标志性的武器，耀眼的金光和精致的造型，是坚持爱与正义的冒险者所追寻的目标',LoadShowSize=1.4,LoadShowRotate=70,LoadShowPose={0,0.2,0},}",
  [41860] = "{id=41860,NameZh='守备军之斧',Icon='item_41833',Type=230,MaxNum=99,SellPrice=2000,Level=90,}",
  [41861] = "{id=41861,NameZh='碎雪·凛冬霸王',Icon='item_41861',Type=230,MaxNum=99,SellPrice=100,AdventureSort=100009,AdventureValue=1,Condition=8,Desc='诞生在冰晶中的利斧，拥有能劈开极地冰原的恐怖破坏力，在它面前连恶魔都能感受到仿佛血液被冻结的恐怖。',LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [41862] = "{id=41862,NameZh='炎魂·怒火战神',Icon='item_41862',Type=230,MaxNum=99,SellPrice=100,AdventureSort=100010,AdventureValue=1,Condition=8,Desc='诞生在火焰中的利斧，拥有能劈开地幔岩浆的恐怖破坏力，就算是来自地狱的恶魔，也会在它面前战栗。',LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [41863] = "{id=41863,NameZh='枫忆之斧',Icon='item_41863',Type=230,MaxNum=99,SellPrice=100,AdventureSort=100003,AdventureValue=1,Condition=8,Desc='斧柄是枫树的树干，斧头是稀有的矿石锋利无比，上面的枫叶图案似火焰一般燃烧着，跃动着，明亮甚至有些刺眼，当敌人见到它的时候，就像身陷火之炼狱一般被它吞噬…',LoadShowSize=1.4,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [41864] = "{id=41864,NameZh='信仰之斧',Icon='item_41864',Type=230,MaxNum=99,SellPrice=100,AdventureSort=100005,AdventureValue=1,Condition=8,Desc='巴风特曾带领手下对梦罗克进行过一次史无前例的大侵袭，这次的战争造成了数以万计的民众伤亡，在危难的关头有十四位勇士站了出来，他们牺牲了自己保护了梦罗克，死后的他们留下了自己的武器，这些武器被梦罗克的人们当做信仰的象征，这柄斧便是十四把武器之一。',LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [41865] = "{id=41865,NameZh='亡灵之斧',Icon='item_41865',Type=230,MaxNum=99,SellPrice=2100,AdventureValue=1,Condition=8,Desc='这把斧子的主人生前是个诚实的伐木工，他在湖边弄丢了自己的斧子，湖之仙女送了他一把金斧子。',Level=95,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [41866] = "{id=41866,NameZh='埃琉德尼尔暴怒斧',Icon='item_41866',Type=230,MaxNum=99,SellPrice=100,AdventureSort=100012,AdventureValue=1,Condition=8,Desc='“死者之都生存法则中最首要的一条：别惹那位大人生气，否则你就会知道她为什么被称为女王。”',TFValidDate='2019-10-28 05:00:00',ValidDate='2019-10-31 05:00:00',LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.25,0},}",
  [41867] = "{id=41867,NameZh='贝克之斧★[1]',Icon='item_41867',Type=230,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='铁匠公会仿造著名的贝克战斧制作的量产型斧头。',Feature=1,LoadShowSize=1.35,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [41868] = "{id=41868,NameZh='碎心斧★[1]',Icon='item_41868',Type=230,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='任何盔甲都无法抵挡的双手斧。 特殊加工的斧刃好像可以砍破任何盔甲似的锐利而沉重。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [41869] = "{id=41869,NameZh='毁灭手斧★[1]',Icon='item_41869',Type=230,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='吞吃了足够灵魂的毁灭之斧会变成毁灭手斧，给与持有者的力量更加诱人，需要献出代价也更大，一旦握住它，似乎会听见某个声音在脑海里轻轻低语，“去劈开理智的枷锁，拥抱力量的深渊吧。”',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.08,0},}",
  [41870] = "{id=41870,NameZh='鲜血斧★[1]',Icon='item_41870',Type=230,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='暴躁的锻造大师金利设计的战斧，被砍伤的人会血流不止。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [41871] = "{id=41871,NameZh='强袭双刃斧★[1]',Icon='item_41871',Type=230,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='克雷斯特汉姆山河破碎，幸存者拿起了这把斧子，心中只有复仇。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,-0.05,0},}",
  [41872] = "{id=41872,NameZh='暗商人之斧[1]',Icon='item_41801',Type=230,MaxNum=99,SellPrice=140,Desc='简单的使用方法，方便任何人使用的斧。',Level=10,Feature=4,}",
  [41873] = "{id=41873,NameZh='生命体战斧',Icon='item_41873',Type=230,MaxNum=99,SellPrice=2400,Desc='雷根贝勒公司所开发的，以生命体为能量的战斧。粒子组成的斧刃可以劈开大多数盾牌。',Level=100,}",
  [41874] = "{id=41874,NameZh='魔器·毕弗隆斯',Icon='item_41874',Type=230,MaxNum=99,SellPrice=100,AdventureSort=100011,AdventureValue=1,Condition=8,Desc='梦罗克碎片打造的禁忌武器，对应着异世界恶魔No.46·毕弗隆斯，状如怪兽，喜欢移动尸体或点亮坟墓上的蜡烛。',LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.1,0},}",
  [41875] = "{id=41875,NameZh='开辟者',Icon='item_41875',Type=230,MaxNum=99,SellPrice=100,AdventureSort=100013,AdventureValue=1,Condition=8,Desc='用它来开辟新的时代吧，属于你的时代。',Feature=1,LoadShowSize=1.3,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [41876] = "{id=41876,NameZh='老伙计[1]',Icon='item_41876',Type=230,MaxNum=99,SellPrice=100,Desc='说实话，谁都比不上我手里的这把结实的老伙计靠谱！',}",
  [41877] = "{id=41877,NameZh='首领之斧[1]',Icon='item_41877',Type=230,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=36000,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='只有强者中的强者才配得上这把拥有摧枯拉朽力量的大斧。',LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.05,0},}",
  [41878] = "{id=41878,NameZh='科学救赎·之斧',Icon='item_41878',Type=230,MaxNum=99,SellPrice=100,AdventureSort=100014,AdventureValue=1,Condition=8,Desc='科学！科学！科学！为了科学一切的牺牲都是值得，蝼蚁们的生命本就毫无价值，因实验而死的他们应该觉得骄傲，这是他们的宿命！快了！就快了，我知道你渴望鲜血，我可爱的战斧小宝贝，再等等……',Feature=1,LoadShowSize=1,}",
  [41880] = "{id=41880,NameZh='圣息崇聆·斧',Icon='item_41880',Type=230,MaxNum=99,SellPrice=100,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='光与天空，圣洁的飞鸟，神的双翼已然张开，吾虔诚的信徒，愿你在吾的庇佑下体验幸福与美好，你的灵魂之音，吾等已经听到，这把圣斧赐予你，神祇永远与你同在。',LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.05,0},}",
  [41881] = "{id=41881,NameZh='辉光十字·斧',Icon='item_41881',Type=230,MaxNum=99,SellPrice=2600,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='这柄战斧出自阿卢纳贝兹教国最有名的工匠——索罗克之手，他搜寻了整个教国寻找制作武器的材料，最终在圣域神殿的地下深处寻到了结果，吸取神灵信仰的矿石坚硬无比，制成的武器更是消灭黑暗的破晓之力。',Level=110,LoadShowSize=1.2,LoadShowRotate=70,LoadShowPose={0,-0.05,0},}",
  [41882] = "{id=41882,NameZh='狂暴飓风[1]',Icon='item_41882',Type=230,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=33000,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='复制飓风型态的巨大的双手斧，斧头中心隐藏着飓风般的力量, 据说武器越强时力量也会一起增强。',LoadShowSize=1.6,LoadShowRotate=70,LoadShowPose={0,-0.2,0},}",
  [41883] = "{id=41883,NameZh='蔷薇灵语之斧',Icon='item_41883',Type=230,MaxNum=99,SellPrice=3200,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='这把战斧被妖精一族的“灵语师”赋予了蔷薇的祝福。妖精认可的勇士将用它斩断拦路的荆棘。',Level=110,LoadShowRotate=90,}",
  [41884] = "{id=41884,NameZh='红鱼花铃·斧',Icon='item_41884',Type=230,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='长了一身红色鳞片的金鱼呀，喜欢在湖底的水草里悠闲地打瞌睡。有人投食的话，也会慢悠悠地钻到水面上，不紧不慢地吃鱼食。如果它会衔着斧游出水面，也不要惊讶，这是金鱼族的报答哟~',LoadShowSize=1.5,LoadShowRotate=70,LoadShowPose={0,0.1,0},}",
  [41885] = "{id=41885,NameZh='湛蓝天光·斧',Icon='item_41885',Type=230,MaxNum=99,SellPrice=2800,AdventureValue=1,Condition=8,Desc='阔大的云海之上透出湛蓝天光，晴空下的战士们振作起了精神。战斗的号角即将吹响，握紧这把战斧吧，它印证着你的忠诚，勇敢与希望。',Level=110,LoadShowSize=1.8,LoadShowRotate=70,LoadShowPose={0,0,0},}",
  [41886] = "{id=41886,NameZh='天虹圣遗·斧',Icon='item_41886',Type=230,MaxNum=99,SellPrice=100,AdventureSort=100019,AdventureValue=1,Condition=8,Desc='浮空精灵收集彩虹桥碎片打造的战斧，敌人常常会沉醉于它散发出的炫目光华，甚至感受不到死亡的痛楚。',LoadShowSize=1.5,}",
  [41887] = "{id=41887,NameZh='月下祈者·斧',Icon='item_41887',Type=230,MaxNum=99,SellPrice=100,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='冰封千年的陨铁，王国的工匠们用尽办法也无法将其熔铸，却因小学徒的一次失误暴露在月光下。那一刻奇迹发生，陨铁融化宛若水银般流转，在月光下散发耀眼星辉。\n此乃月光赐福之战斧，执斧者当以月光之力，斩断黑暗，开辟光明！',LoadShowRotate=90,LoadShowPose={0,-0.3,-1},}",
  [41888] = "{id=41888,NameZh='英灵起点·斧[2]',Icon='item_41888',Type=230,Quality=2,MaxNum=99,SellPrice=100,Desc='克里图拉新生领到的初心武器，致敬英灵而铸上蓝金涂装。据说作为贵族的设计者一气之下砍了父亲的樱花树，而被樱花之灵施下了真话诅咒。因祸得福，他终于抛下了贵族的重担，活出了自己的人生。',NoStorage=5,LoadShowSize=1.5,}",
  [41889] = "{id=41889,NameZh='英灵信标·斧[2]',Icon='item_41889',Type=230,Quality=3,MaxNum=99,SellPrice=100,Desc='这把斧是指引女武神降临、迎接英灵的道标。阵亡的勇士抱着它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,LoadShowSize=1.5,}",
  [41890] = "{id=41890,NameZh='英灵羽证·斧[2]',Icon='item_41890',Type=230,Quality=3,MaxNum=99,SellPrice=100,Desc='英灵的证明。潜入学院的女武神在斧中注入了奥丁领域的魔力。斧头长出了羽翼，连异变的诅咒都能劈砍而散。',NoStorage=5,LoadShowSize=1.5,}",
  [41892] = "{id=41892,NameZh='远古回音·斧',Icon='item_41892',Type=230,MaxNum=99,SellPrice=3200,AdventureSort=100020,AdventureValue=1,Condition=8,Desc='铭刻着神秘纹样的巨斧，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,LoadShowSize=1.5,}",
  [41894] = "{id=41894,NameZh='王国荣辉·斧',Icon='item_41894',Type=230,MaxNum=99,SellPrice=100,AdventureSort=100023,AdventureValue=1,Condition=8,Desc='效忠于王室的宫廷侍卫所持的大斧，其上绘有卢恩王家纹章。复杂的黄金装饰为大斧增添了不必要的重量，因而挥动起来相当不便。',LoadShowSize=1.8,LoadShowRotate=90,LoadShowPose={0,-0.25,0},}",
  [41898] = "{id=41898,NameZh='硝烟终结者·极限',Icon='item_41898',Type=456,Quality=4,MaxNum=1,SellPrice=100,Desc='当诸神黄昏的硝烟蔓延到了侏儒王国时，侏儒兄弟辛德里和勃洛克以寿命为代价，铸造了这把世上最强的战斧，它仅一击就天崩地裂，瞬间便击溃了龙族的侵略者。',NoSale=1,NoStorage=7,TFValidDate='2022-03-10 05:00:00',ValidDate='2022-03-23 05:00:00',}",
  [41899] = "{id=41899,NameZh='英灵信标·斧[2]',Icon='item_41889',Type=230,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=100024,AdventureValue=1,Condition=8,Desc='这把斧是指引女武神降临、迎接英灵的道标。阵亡的勇士抱着它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,LoadShowSize=1.5,}",
  [41900] = "{id=41900,NameZh='英灵羽证·斧[2]',Icon='item_41890',Type=230,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=100025,AdventureValue=1,Condition=8,Desc='英灵的证明。潜入学院的女武神在斧中注入了奥丁领域的魔力。斧头长出了羽翼，连异变的诅咒都能劈砍而散。',NoStorage=5,LoadShowSize=1.5,}",
  [42001] = "{id=42001,NameZh='乐园团训练服',Icon='item_42001',Type=500,MaxNum=99,SellPrice=20,Desc='乐园团为新人冒险者准备的衣服。方便实用。',Level=1,Feature=4,}",
  [42002] = "{id=42002,NameZh='火鳞铠甲',Icon='item_42002',Type=500,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1125,AdventureSort=10000,AdventureValue=-1,Desc='当穿上时会感觉到一股热气，快要把身体燃烧似的铠甲。 ',Feature=1,}",
