  [42014] = "{id=42014,NameZh='三角裤',Icon='item_42014',Type=500,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4900,AdventureSort=10000,AdventureValue=-1,Desc='三角形的贴身衣物。',Feature=1,}",
  [42015] = "{id=42015,NameZh='圣职之衣',Icon='item_42015',Type=500,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=121,AdventureSort=10000,AdventureValue=-1,Desc='蕴含着女神祝福的神圣衣服。',Feature=1,}",
