  [42019] = "{id=42019,NameZh='忍服血樱',Icon='item_42019',Type=500,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=121,AdventureSort=10000,AdventureValue=-1,Desc='在东方某一岛国传进来的轻便衣服。',Feature=1,}",
  [42020] = "{id=42020,NameZh='哥夫内的铠甲',Icon='item_42020',Type=500,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=6300,AdventureSort=10000,AdventureValue=-1,Desc='打铁匠人哥夫内在工作时喝的不老不死的麦酒，不小心掉在铠甲上所拥有特别能力的铠甲。',Feature=1,}",
  [42021] = "{id=42021,NameZh='天衣月舞',Icon='item_42021',Type=500,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=226,AdventureSort=10000,AdventureValue=-1,Desc='侍奉奥丁的 ＂战争姑娘＂的盔甲，穿了之后有时会发出白色的光芒。',Feature=1,}",
  [42022] = "{id=42022,NameZh='衬衫',Icon='item_42022',Type=520,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=210,AdventureSort=10000,AdventureValue=-1,Desc='让人可以全力奔跑的轻便盔甲。虽然看上去和奔跑衬衫很相似，但具有盔甲的防御力。',Feature=1,}",
