  [42100] = "{id=42100,NameZh='炼金合金装甲★',Icon='item_42100',Type=500,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=10000,AdventureValue=-1,Feature=1,}",
  [42101] = "{id=42101,NameZh='审判之袍★',Icon='item_42101',Type=500,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=10000,AdventureValue=-1,Desc='不仅是审判者的神圣身份的象征，还拥有抵挡恶魔诅咒的神圣祝福，当初魔剑士达纳托斯成为魔王梦罗克诅咒的牺牲者后，所有对抗恶魔者必须穿戴受祝福的衣装便成为了默认的守则。',Feature=1,}",
  [42102] = "{id=42102,NameZh='华丽演出服★',Icon='item_42102',Type=500,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=10000,AdventureValue=-1,Desc='一般会在名字中带上“华丽”两字的东西，都浮夸的可怕。',Feature=1,}",
  [42103] = "{id=42103,NameZh='哥夫内的铠甲★',Icon='item_42103',Type=500,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=10000,AdventureValue=-1,Desc='打铁匠人哥夫内在工作时喝的不老不死的麦酒，不小心掉在铠甲上所拥有特别能力的铠甲。',Feature=1,}",
  [42104] = "{id=42104,NameZh='优雅的制服★',Icon='item_42104',Type=500,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=10000,AdventureValue=-1,Desc='穿着制服是一种仪式感，象征着人类诚挚的礼节。',Feature=1,}",
  [42105] = "{id=42105,NameZh='陨石铠甲★',Icon='item_42105',Type=500,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=10000,AdventureValue=-1,Desc='疑似是用无法辨认成分的陨石来制作的强化盔甲。',Feature=1,}",
  [42106] = "{id=42106,NameZh='魔能涌动外袍★',Icon='item_42106',Type=500,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=10000,AdventureValue=-1,Desc='以充沛的魔能作为动力的长袍，在关键时刻能够给与穿戴者额外的能量补给。',Feature=1,}",
  [42107] = "{id=42107,NameZh='放浪者外套★',Icon='item_42107',Type=500,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=10000,AdventureValue=-1,Feature=1,}",
  [42108] = "{id=42108,NameZh='初心者盔甲',Icon='item_42108',Type=500,Quality=2,MaxNum=99,SellPrice=100,Desc='乐园团为下定决心的初心者们特意准备的盔甲，坚不可摧。',Feature=1,}",
  [42109] = "{id=42109,NameZh='巡守队盔甲',Icon='item_42109',Type=500,MaxNum=99,SellPrice=20,Desc='巡守队为下定决心的初心喵们特意准备的盔甲，坚不可摧。',Level=1,Feature=4,}",
  [42110] = "{id=42110,NameZh='乌鲁兹符文盔甲',Icon='item_42110',Type=500,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=7830,AdventureSort=10000,AdventureValue=-1,Desc='提炼乌鲁兹符文而制作的铠甲，据说可以保护使用者不受邪恶力量的侵蚀。',}",
  [42111] = "{id=42111,NameZh='喵族优雅斗篷',Icon='item_42111',Type=500,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=2400,Desc='无论刮风下雨，只要穿上它就可以放心的出门，为您节省大量时间。',}",
  [42112] = "{id=42112,NameZh='喵族优雅外套',Icon='item_42112',Type=500,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=6400,Desc='非常宽松的舒适外套，不论啤酒肚还是大象腿都可以优雅地遮起来。',}",
  [42113] = "{id=42113,NameZh='慵懒喵喵外套',Icon='item_42113',Type=500,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=4800,Desc='穿上之后会变懒...那不是外套的错啦！',}",
  [42121] = "{id=42121,NameZh='骷髅盔甲',Icon='item_42121',Type=500,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10000,AdventureValue=-1,Desc='周围缠绕着尖骨的钢铁铠甲，小心自己不要被刺伤。',}",
  [42122] = "{id=42122,NameZh='英灵起点·盔甲',Icon='item_42122',Type=500,Quality=2,MaxNum=99,SellPrice=100,Desc='克里图拉新生领到的初心防具，致敬英灵而铸上蓝金涂装。据说设计者是个关心学生的指导员，考虑学生还没从储物柜向冒险者背包毕业，牺牲了防御性，换来了青春轻灵的气息~',NoStorage=5,}",
  [42123] = "{id=42123,NameZh='英灵信标·盔甲[1]',Icon='item_42123',Type=500,Quality=3,MaxNum=99,SellPrice=100,Desc='它是指引女武神降临、迎接英灵的道标。阵亡的勇士抱穿上它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,}",
  [42124] = "{id=42124,NameZh='英灵羽证·盔甲',Icon='item_42124',Type=500,Quality=3,MaxNum=99,SellPrice=100,Desc='英灵的证明。潜入学院的女武神在盔甲中注入了奥丁领域的魔力。盔甲长出了羽翼，标志艰险的冒险旅途上，将会是自由的步伐。',NoStorage=5,}",
  [42125] = "{id=42125,NameZh='生命之环',Icon='item_42125',Type=500,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=12800,AdventureSort=10000,AdventureValue=-1,Desc='为了给受到女神选择的勇士们治疗伤口而制作的神圣盔甲。可以让穿著者的恢复速度实现飞跃。',Feature=1,}",
  [42126] = "{id=42126,NameZh='丝质外袍★',Icon='item_42126',Type=500,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=4800,Desc='用高级的布料制成的衣服，具有卓越的魔法防御力。',}",
  [42127] = "{id=42127,NameZh='古代皮甲',Icon='item_42127',Type=500,Quality=2,MaxNum=99,SellPrice=100,Desc='使用某种野兽的皮革制成的盔甲，表面有些风化，难以辨别出自何种野兽。',Feature=1,Delete=42127}",
  [42128] = "{id=42128,NameZh='龙鳞甲',Icon='item_42128',Type=500,Quality=3,MaxNum=99,SellPrice=100,Desc='使用龙皮与龙鳞缝制的铠甲，与防御力相比更为重要的是它代表着屠龙的无上荣耀。',Feature=1,Delete=42128}",
  [42129] = "{id=42129,NameZh='龙血之浴',Icon='item_42129',Type=500,Quality=4,MaxNum=99,SellPrice=100,Desc='龙血浸润的盔甲，防御力惊人。杀死巨龙时喷涌的龙血拥有强大的魔力，可以使盔甲坚固无比，但其中也包含着龙族临死前最怨毒的诅咒。“屠龙者终将迎来他的宿命。”',Feature=1,Delete=42129}",
  [42130] = "{id=42130,NameZh='鸦羽猎服',Icon='item_42130',Type=500,Quality=2,MaxNum=99,SellPrice=100,Desc='使用乌鸦羽毛装饰的皮甲，便于在森林与夜色中隐藏自己，很适合狩猎。',Feature=1,Delete=42130}",
  [42131] = "{id=42131,NameZh='鹰翎猎服',Icon='item_42131',Type=500,Quality=3,MaxNum=99,SellPrice=100,Desc='精英猎人身份的象征，只有那些经验老到、狩猎了许多强大野兽的猎人，才有资格用鹰的翎毛装饰自己的猎装。',Feature=1,Delete=42131}",
  [42132] = "{id=42132,NameZh='风暴之御',Icon='item_42132',Type=500,Quality=4,MaxNum=99,SellPrice=100,Desc='传说中可以操纵风暴的巨鹰被杀死后，猎人们使用它的羽毛打造了这件猎装。借助猎装中巨鹰残存的魔力操纵风元素，强化猎人的弓箭。',Feature=1,Delete=42132}",
  [42133] = "{id=42133,NameZh='耍蛇人之衣',Icon='item_42133',Type=500,Quality=2,MaxNum=99,SellPrice=100,Desc='克魔岛引进了许多新奇的游玩项目，蛇舞就是其中之一。据说耍蛇人是克魔岛最危险的职业之一。',Feature=1,Delete=42133}",
  [42134] = "{id=42134,NameZh='巫毒战甲',Icon='item_42134',Type=500,Quality=3,MaxNum=99,SellPrice=100,Desc='克魔岛上的巫师们通过秘法制成的外套，据说经过了九十九道巫术的加持。',Feature=1,Delete=42134}",
  [42135] = "{id=42135,NameZh='诅咒战甲',Icon='item_42135',Type=500,Quality=4,MaxNum=99,SellPrice=100,Desc='这件外套是一个疯狂巫师的实验品，他为这件外套施加了超过三百种强力诅咒。任何贸然触碰它的人都会被恶咒缠身。',Feature=1,Delete=42135}",
  [42136] = "{id=42136,NameZh='夜行者长袍',Icon='item_42136',Type=500,Quality=2,MaxNum=99,SellPrice=100,Desc='深色紧身皮衣，轻便灵活，适合在夜间“工作”的人群穿戴。',Feature=1,Delete=42136}",
  [42137] = "{id=42137,NameZh='送葬者长袍',Icon='item_42137',Type=500,Quality=3,MaxNum=99,SellPrice=100,Desc='“送葬者”从不认为自己是一名刺客，虽然他手上已沾染无数鲜血。他充满仪式感的进行着每一次刺杀，如他想的那样，将“死亡”这份礼物送给他的目标。',Feature=1,Delete=42137}",
  [42138] = "{id=42138,NameZh='恩赐解脱',Icon='item_42138',Type=500,Quality=4,MaxNum=99,SellPrice=100,Desc='这件长袍曾属于一位传奇刺客，他一生刺杀了无数权贵政要，却被自己最好的朋友出卖，死在幽暗的街巷中，他的真名已无人知晓，留在世上的只有他的遗言：“人生多苦难，死亡即是解脱……”',Feature=1,Delete=42138}",
  [42139] = "{id=42139,NameZh='勘探者套装',Icon='item_42139',Type=500,Quality=2,MaxNum=99,SellPrice=100,Desc='专为探险爱好者准备的外套，方便携带各种工具。',Feature=1,Delete=42139}",
  [42140] = "{id=42140,NameZh='真相勘探者',Icon='item_42140',Type=500,Quality=3,MaxNum=99,SellPrice=100,Desc='许多真相被掩埋在历史长河中，发掘这些真相是许多冒险者最大的乐趣。',Feature=1,Delete=42140}",
  [42141] = "{id=42141,NameZh='大地使者套装',Icon='item_42141',Type=500,Quality=4,MaxNum=99,SellPrice=100,Desc='受到大地祝福的冒险者，游历于米德加尔特，见证这片大陆的风土人情与岁月变迁。',Feature=1,Delete=42141}",
  [42142] = "{id=42142,NameZh='野性皮甲',Icon='item_42142',Type=500,Quality=2,MaxNum=99,SellPrice=100,Desc='仿照远古时代克魔岛勇士穿着铸造的战甲，造型复古，野性十足。',Feature=1,Delete=42142}",
  [42143] = "{id=42143,NameZh='角斗士战甲',Icon='item_42143',Type=500,Quality=3,MaxNum=99,SellPrice=100,Desc='为角斗士们准备的轻便铠甲，穿上它可以进行灵活的战斗。',Feature=1,Delete=42143}",
  [42144] = "{id=42144,NameZh='不屈战团甲胄',Icon='item_42144',Type=500,Quality=4,MaxNum=99,SellPrice=100,Desc='梦罗克入侵时期，一支战团在与魔王爪牙的战斗中血战至全军覆没，这身铠甲正是这些勇士的遗物，其中凝结着他们不屈的斗志，令每个穿戴这身盔甲的人振奋不已。',Feature=1,Delete=42144}",
  [42145] = "{id=42145,NameZh='神秘骸骨',Icon='item_42145',Type=500,Quality=2,MaxNum=99,SellPrice=100,Desc='神秘的骨质铠甲，不知道使用什么生物的骸骨制造而成，总之还是不要深究为好。',Feature=1,Delete=42145}",
  [42146] = "{id=42146,NameZh='白骨之惧战甲',Icon='item_42146',Type=500,Quality=3,MaxNum=99,SellPrice=100,Desc='一位巫师苦恼于人类短暂的寿命，为了拥有足够的时间研究魔法，他触碰了禁忌的领域。那种邪恶的秘法将他变成了灵魂近乎不灭的怪物，时间流逝，血肉腐坏，只留下一身白骨……',Feature=1,Delete=42146}",
  [42147] = "{id=42147,NameZh='灵魂的囚笼',Icon='item_42147',Type=500,Quality=4,MaxNum=99,SellPrice=100,Desc='当你触碰到这副骨质铠甲时，耳畔传来微弱却清晰的低语：“灵魂不应受到血肉的束缚，拥抱新生吧……”',Feature=1,Delete=42147}",
  [42148] = "{id=42148,NameZh='赤羽战甲',Icon='item_42148',Type=500,Quality=2,MaxNum=99,SellPrice=100,Desc='这件外套使用红色鸟羽做装饰，十分醒目。',Feature=1,Delete=42148}",
  [42149] = "{id=42149,NameZh='灰烬战甲',Icon='item_42149',Type=500,Quality=3,MaxNum=99,SellPrice=100,Desc='在清理熔炉时，工匠在灰烬中发现了几根羽毛，日夜燃烧的炉火没有令它们损伤分毫。这令工匠惊叹不已，用这些羽毛为材料铸造了这件战甲。',Feature=1,Delete=42149}",
  [42150] = "{id=42150,NameZh='不死鸟战铠',Icon='item_42150',Type=500,Quality=4,MaxNum=99,SellPrice=100,Desc='不死鸟于火焰中重生，它的旧羽被收集起来，织就这件战衣，其中蕴含着不死鸟强大的生命力，即便穿戴者受了再重的伤，也能在顷刻间复原。',Feature=1,Delete=42150}",
  [42151] = "{id=42151,NameZh='萨满祭服',Icon='item_42151',Type=500,Quality=2,MaxNum=99,SellPrice=100,Desc='民俗学家们复刻的克魔岛古代服饰，据说是在举行某些祭祀仪式时穿着的礼服。',Feature=1,Delete=42151}",
  [42152] = "{id=42152,NameZh='智慧祭服',Icon='item_42152',Type=500,Quality=3,MaxNum=99,SellPrice=100,Desc='远古时期祭司们穿着的祭典礼服，作为神明的使者，将智慧传播给世人。',Feature=1,Delete=42152}",
  [42153] = "{id=42153,NameZh='天神的指引',Icon='item_42153',Type=500,Quality=4,MaxNum=99,SellPrice=100,Desc='传说中克魔岛人的祖先是一群流浪者，家园被强大的魔物侵占，几近绝望时在耳畔听到了神明的指示，在神的指引下他们翻越群山，来到一片物产丰饶的土地，在此建立了新家园。',Feature=1,Delete=42153}",
  [42154] = "{id=42154,NameZh='欢笑人偶服',Icon='item_42154',Type=500,Quality=2,MaxNum=99,SellPrice=100,Desc='穿上这身人偶服就可以去广场发放传单了，没人能认出你来！',Feature=1,Delete=42154}",
  [42155] = "{id=42155,NameZh='食梦者的伪装',Icon='item_42155',Type=500,Quality=3,MaxNum=99,SellPrice=100,Desc='梦境世界中以梦为食的食梦者，常常以各种或是古怪、或是可爱的野兽形象出现。这些食梦者维持两个世界之间的能量平衡，防止梦境世界无限膨胀。',Feature=1,Delete=42155}",
  [42156] = "{id=42156,NameZh='彼岸巡行者',Icon='item_42156',Type=500,Quality=4,MaxNum=99,SellPrice=100,Desc='徘徊于梦境中的神秘身影，被面具遮盖难以窥见面容，他来自某次不期而遇，亦或是某个难以忘怀的人。',Feature=1,Delete=42156}",
  [42157] = "{id=42157,NameZh='魔纹皮衣',Icon='item_42157',Type=500,Quality=2,MaxNum=99,SellPrice=100,Desc='镌刻的魔法纹路的皮质战衣，可以有效抵挡魔法伤害。',Feature=1,Delete=42157}",
  [42158] = "{id=42158,NameZh='恶魔战衣',Icon='item_42158',Type=500,Quality=3,MaxNum=99,SellPrice=100,Desc='使用恶魔身上的部件缝制的连体战衣，拥有强大魔力的同时也包含着恶魔的诅咒，只有心智最为坚定的人才能压制恶魔的力量，成为这件战衣的主人。',Feature=1,Delete=42158}",
  [42159] = "{id=42159,NameZh='猎魔者的决意',Icon='item_42159',Type=500,Quality=4,MaxNum=99,SellPrice=100,Desc='他是世间最强大的猎魔人，他盯上的猎物无论多么强大都难逃被消灭的命运，但没有人知道他为何会走上这一条注定孤独的道路。”仇恨之火，会将这些渣滓焚烧殆尽，也终将吞噬我……“',Feature=1,Delete=42159}",
  [42160] = "{id=42160,NameZh='旧风衣',Icon='item_42160',Type=500,Quality=2,MaxNum=99,SellPrice=100,Desc='一件款式独特的破旧风衣，所以为什么还不把它丢了？',Feature=1,Delete=42160}",
  [42161] = "{id=42161,NameZh='引魂人的皮衣',Icon='item_42161',Type=500,Quality=3,MaxNum=99,SellPrice=100,Desc='身披斗篷的引魂者们在世间游荡，只有亡魂能够看到他们，在他们的指引下进入死亡国度尼夫海姆。',Feature=1,Delete=42161}",
  [42162] = "{id=42162,NameZh='迷雾行者',Icon='item_42162',Type=500,Quality=4,MaxNum=99,SellPrice=100,Desc='迷雾行者会庇护那些生前行善的亡魂，为他们拨开盘桓在冥河上的迷雾，防止他们迷失方向，堕入冥河中。',Feature=1,Delete=42162}",
  [42163] = "{id=42163,NameZh='学徒外套',Icon='item_42163',Type=500,Quality=2,MaxNum=99,SellPrice=100,Desc='克魔岛大祭司为学徒们准备的外套，据说兜帽的设计只是为了增加神秘感。',Feature=1,Delete=42163}",
  [42164] = "{id=42164,NameZh='魔女的盛筵',Icon='item_42164',Type=500,Quality=3,MaxNum=99,SellPrice=100,Desc='魔女在密林深处举办了一场狂欢派对，准备好盛装出席了吗？',Feature=1,Delete=42164}",
  [42165] = "{id=42165,NameZh='生息之袍',Icon='item_42165',Type=500,Quality=4,MaxNum=99,SellPrice=100,Desc='被森林之灵祝福过的长袍，磅礴的生命力抑制不住的向四周散发，甚至可以让草木加速生长，让枯木重发新芽。',Feature=1,Delete=42165}",
  [42166] = "{id=42166,NameZh='勇者铠甲·仿',Icon='item_42166',Type=500,Quality=2,MaxNum=99,SellPrice=100,Desc='传说中的英雄所穿着的战甲的仿制品，作为旅游纪念品很受游客们的喜欢。',Feature=1,Delete=42166}",
  [42167] = "{id=42167,NameZh='命运战甲',Icon='item_42167',Type=500,Quality=3,MaxNum=99,SellPrice=100,Desc='少年穿上盔甲，离开故乡，这一刻命运之轮开始转动，属于他的英雄史诗开始书写。',Feature=1,Delete=42167}",
  [42168] = "{id=42168,NameZh='全村最好的铠甲',Icon='item_42168',Type=500,Quality=4,MaxNum=99,SellPrice=100,Desc='有些盔甲，它未必有多么精良，未必拥有着多么强大的力量，或许只是某个村庄里最好的盔甲，却因为它的持有者而闻名于世。“这可是那位勇者穿过的盔甲！”',Feature=1,Delete=42168}",
  [42169] = "{id=42169,NameZh='渔人猎服',Icon='item_42169',Type=500,Quality=2,MaxNum=99,SellPrice=100,Desc='海边捕猎的渔民经常穿着的外套，使用鱼鳞、鱼皮制作，具有良好的防水性能。',Feature=1,Delete=42169}",
  [42170] = "{id=42170,NameZh='潮汐战甲',Icon='item_42170',Type=500,Quality=3,MaxNum=99,SellPrice=100,Desc='大海赐予海洋之民的礼物，相传穿戴这件盔甲的人能够获得操纵潮汐的力量。',Feature=1,Delete=42170}",
  [42171] = "{id=42171,NameZh='踏浪者战甲',Icon='item_42171',Type=500,Quality=4,MaxNum=99,SellPrice=100,Desc='这件战甲使用海兽皮制成，坚韧且光滑，穿上它可以像鱼一样在水中穿行。海洋中的生灵也会将穿戴者认为是同类。',Feature=1,Delete=42171}",
  [42175] = "{id=42175,NameZh='先祖战甲',Icon='item_42175',Type=500,Quality=2,MaxNum=99,SellPrice=100,Desc='代代相传的古旧铠甲，某位先祖曾穿着它与强敌作战。',Feature=1,Delete=42175}",
  [42176] = "{id=42176,NameZh='唤灵战甲',Icon='item_42176',Type=500,Quality=3,MaxNum=99,SellPrice=100,Desc='这件铠甲是一位祭司的遗物，穿上这件战甲便拥有了直接跟灵魂对话的能力。',Feature=1,Delete=42176}",
  [42177] = "{id=42177,NameZh='祖灵之羁',Icon='item_42177',Type=500,Quality=4,MaxNum=99,SellPrice=100,Desc='克魔岛远古时期某位首领的铠甲，被供奉在波纳佩岛的祭坛上。克魔岛人的信仰唤醒了铠甲中沉睡的力量，穿着它的勇士会如同英灵附身般强大。“现在，我们合为一体！”',Feature=1,Delete=42177}",
  [42178] = "{id=42178,NameZh='仪祭战甲',Icon='item_42178',Type=500,Quality=2,MaxNum=99,SellPrice=100,Desc='克魔岛大祭司在举行祭祀仪式时穿着的礼服，自从克魔岛成为旅游胜地后，这种服装多用于民俗表演。',Feature=1,Delete=42178}",
  [42179] = "{id=42179,NameZh='王权战甲',Icon='item_42179',Type=500,Quality=3,MaxNum=99,SellPrice=100,Desc='远古时期克魔岛上部族首领才有资格穿戴的战甲，在抵御入侵者时，身穿“王权战甲”的首领们也是冲在最前面的勇士。',Feature=1,Delete=42179}",
  [42180] = "{id=42180,NameZh='古圣之契',Icon='item_42180',Type=500,Quality=4,MaxNum=99,SellPrice=100,Desc='远古时期的英雄生前穿戴的铠甲，战死后灵魂寄宿于铠甲中。这身铠甲的穿戴者可以与英雄的灵魂缔结契约，获得来自远古的强大力量。“那么，代价是什么呢？”',Feature=1,Delete=42180}",
  [42181] = "{id=42181,NameZh='矿工背心',Icon='item_42181',Type=500,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=12800,Desc='矿工的工作制服，因轻便、耐磨、低调而受到暗杀者们的喜爱。“身为矿工，随身携带点炸药什么的很合理吧？”',Feature=1,}",
  [42182] = "{id=42182,NameZh='狙击手的大衣',Icon='item_42182',Type=500,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='由修发兹共和国制式军装改造成的大衣，拥有不俗防御力的同时，能够有效的适应各种恶劣环境的作战。',Feature=1,Delete=42182}",
  [42183] = "{id=42183,NameZh='猎兵作战服',Icon='item_42183',Type=500,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,Desc='使用雷根贝勒公司先进技术打造的特种作战服，看起来只是一件普通大衣，却可以抵御各种伤害，并保障枪手们灵活作战的能力。',Feature=1,Delete=42183}",
  [42184] = "{id=42184,NameZh='神话尘封·荒境铠甲',Icon='item_42184',Type=500,Quality=2,MaxNum=99,SellPrice=100,Desc='在荒境发掘出的铠甲，曾为传说中的洛阳勇士所穿戴。',Level=120,Delete=42184}",
  [42185] = "{id=42185,NameZh='辉煌再临·荒境圣铠',Icon='item_42185',Type=500,Quality=2,MaxNum=99,SellPrice=100,Desc='沉眠在荒境深处的传奇铠甲，可以为你增加物理、魔法伤害。因为新主人的出现，它褪去尘埃，重新焕发耀目的光彩。',Level=130,Delete=42185}",
  [42186] = "{id=42186,NameZh='辉煌再临·荒境圣铠',Icon='item_42185',Type=500,Quality=3,MaxNum=99,SellPrice=100,Desc='沉眠在荒境深处的传奇铠甲，可以为你增加物理伤害。因为新主人的出现，它褪去尘埃，重新焕发耀目的光彩。',Level=130,Delete=42186}",
  [42187] = "{id=42187,NameZh='辉煌再临·荒境圣铠',Icon='item_42185',Type=500,Quality=3,MaxNum=99,SellPrice=100,Desc='沉眠在荒境深处的传奇铠甲，可以为你增加魔法伤害。因为新主人的出现，它褪去尘埃，重新焕发耀目的光彩。',Level=130,Delete=42187}",
  [42188] = "{id=42188,NameZh='辉煌再临·荒境圣铠',Icon='item_42185',Type=500,Quality=3,MaxNum=99,SellPrice=100,Desc='沉眠在荒境深处的传奇铠甲，可以为你增加生命上限。因为新主人的出现，它褪去尘埃，重新焕发耀目的光彩。',Level=130,Delete=42188}",
