  [42506] = "{id=42506,NameZh='大天使之盾',Icon='item_42506',Type=510,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=3200,AdventureSort=11000,AdventureValue=1,Condition=8,Desc='拥有神的旨意，从神的传令那里神直接赐给他，具有象征性的盾牌。',Feature=1,LoadShowSize=1.3,LoadShowRotate=340,LoadShowPose={0,0.5,0},}",
