  [42513] = "{id=42513,NameZh='皇家之盾',Icon='item_42513',Type=510,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=7700,AdventureSort=11000,AdventureValue=1,Condition=8,Desc='刻有卢恩米德加尔特皇家纹章的华丽盾牌。',Feature=1,LoadShowSize=1.3,LoadShowRotate=340,LoadShowPose={0,0.38,0},}",
  [42514] = "{id=42514,NameZh='巨人护盾',Icon='item_42514',Type=510,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=16000,AdventureSort=11000,AdventureValue=1,Condition=8,Desc='据说是守护古代神殿的巨人曾用过的盾牌，是传说中伟大铁匠的杰作。',Feature=4,LoadShowSize=1.3,LoadShowRotate=340,LoadShowPose={0,0.44,0},}",
  [42515] = "{id=42515,NameZh='谎言纪录本',Icon='item_42515',Type=510,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=225,AdventureSort=11000,AdventureValue=-1,Desc='魔法师所使用的魔法书，因体积较大又厚实，可以足够当作盾牌使用。',Feature=1,}",
  [42516] = "{id=42516,NameZh='铂金盾[1]',Icon='item_42516',Type=510,MaxNum=99,SellPrice=100,Desc='用不容易冶炼的铂金作为原料的盾牌。 传说光滑的铂金表面会反射魔法。',Level=50,Feature=4,}",
