  [42539] = "{id=42539,NameZh='坚固盾牌',Icon='item_42539',Type=510,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=840,AdventureSort=11000,AdventureValue=1,Condition=8,Desc='经过魔法加固的盾牌，有着不菲的魔法防御能力。',Feature=1,LoadShowSize=1.3,LoadShowRotate=340,LoadShowPose={0,0.44,0},}",
  [42540] = "{id=42540,NameZh='英灵·兰蒂之坚壁',Icon='item_42540',Type=510,MaxNum=99,SellPrice=100,AdventureSort=100006,AdventureValue=1,Condition=8,Desc='盾牌破坏神——兰蒂格瑞丝的盾牌，虽然号称盾牌破坏神，但是兰蒂之坚壁是她永远也破坏不了的盾牌，只有心怀仁慈的人才配拥有这守护之盾。',Feature=1,LoadShowSize=1.4,LoadShowRotate=340,LoadShowPose={0,0.34,0},}",
  [42541] = "{id=42541,NameZh='光明圣徒之盾',Icon='item_42541',Type=510,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='圣歌教会的锻造神工匠，人称“光明圣徒”的安德鲁冕下为那些英勇善战的教会勇士所设计的一套制式服装，防御力极其优秀。起初这套制式服装没有名字，但其优秀的防御力让所有勇士们都爱不释手，他们用锻造这安德鲁的称号来为这制式服装命名。这就是“光明圣徒”套装。这件为“光明圣徒”套装的副手部分。受到光明圣徒的祝福，安全精炼时消耗的装备件数减少一半。',Feature=1,LoadShowSize=1.3,LoadShowRotate=340,LoadShowPose={0,0.4,0},}",
  [42542] = "{id=42542,NameZh='衔尾者鳞盾',Icon='item_42542',Type=510,MaxNum=99,SellPrice=100,AdventureSort=100004,AdventureValue=1,Condition=8,Desc='厚厚的红蛇鳞十分尖硬，能抵御强大的攻击力并将其弹开。',Feature=1,LoadShowSize=1.4,LoadShowRotate=340,LoadShowPose={0,0.35,0},}",
  [42544] = "{id=42544,NameZh='星界·恒星光壁',Icon='item_42544',Type=510,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=100002,AdventureValue=1,Condition=8,Desc='利用星辰中提炼出的珍贵矿石制作而成，重量只有普通盾牌的1/10，白天看上去漆黑一团，夜晚会跟天空中的星星产生共鸣，释放出辉煌的光壁，有效阻挡敌人的攻击。',Feature=1,LoadShowSize=1.4,LoadShowRotate=340,LoadShowPose={0,0.34,0},}",
  [42545] = "{id=42545,NameZh='和平使者',Icon='item_42545',Type=510,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=100001,AdventureValue=1,Condition=8,Desc='精灵大长老德库里的盾牌，传说中德库里是一名崇尚和平的长老，任何与他争斗的人都会被他热爱和平的精神感化。但也有另外的传说，因为德库里的盾牌有自然之神的祝福，只要他撑起盾牌，没有任何攻击可以伤害到他，所谓他无所畏惧，这块盾牌也被精灵们戏称为和平使者。（建议作为武器外观使用）',Feature=1,LoadShowSize=1.3,LoadShowRotate=340,LoadShowPose={0,0.44,0},}",
  [42546] = "{id=42546,NameZh='圣灵·兰蒂之山岳盾',Icon='item_42546',Type=510,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='盾牌破坏神——兰蒂格瑞丝的盾牌，这面盾解放后的形态巨大到就像是一座山脉。',Feature=1,LoadShowSize=1.4,LoadShowRotate=340,LoadShowPose={0,0.34,0},}",
  [42547] = "{id=42547,NameZh='狮心盾牌',Icon='item_42532',Type=510,MaxNum=99,SellPrice=1164,Desc='传说中的狮心军团特有的盾牌，具有极高的防御能力，甚至能够抵御巨龙的火焰。',Level=97,}",
  [42548] = "{id=42548,NameZh='龙火宝珠',Icon='item_42533',Type=511,MaxNum=99,SellPrice=1164,Desc='吸收了巨龙火焰能量的宝珠，能够释放巨大的屏障保护使用者的安全。',Level=97,}",
  [42549] = "{id=42549,NameZh='月辉·星罗之盾',Icon='item_42549',Type=510,MaxNum=99,SellPrice=100,AdventureSort=100008,AdventureValue=1,Condition=8,Desc='暗月马戏团标志性的武器，因其式样低调而华丽又非常稀有，成为了年轻冒险家追捧的热门武器',LoadShowSize=1.2,LoadShowRotate=340,LoadShowPose={0,0.32,0},}",
  [42550] = "{id=42550,NameZh='日耀·破晓之盾',Icon='item_42550',Type=510,MaxNum=99,SellPrice=100,AdventureSort=100007,AdventureValue=1,Condition=8,Desc='太阳马戏团标志性的武器，耀眼的金光和精致的造型，是坚持爱与正义的冒险者所追寻的目标',LoadShowSize=1.2,LoadShowRotate=340,LoadShowPose={0,0.32,0},}",
  [42551] = "{id=42551,NameZh='红色手提包',Icon='item_41547',Type=513,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureValue=-1,Desc='炼金术士公会正式指定的手提包，明艳的红色在女性中具有很高的人气。据说已经成为米德加尔特时尚界的新宠。',Feature=1,}",
  [42552] = "{id=42552,NameZh='碎雪·冰蓝守卫',Icon='item_42552',Type=510,MaxNum=99,SellPrice=100,AdventureSort=100009,AdventureValue=1,Condition=8,Desc='覆盖千年寒铁的重盾，不断散发着寒气与冷冽的蓝光。',LoadShowSize=1.3,LoadShowRotate=340,LoadShowPose={0,0.37,0},}",
  [42553] = "{id=42553,NameZh='炎魂·赤炎守卫',Icon='item_42553',Type=510,MaxNum=99,SellPrice=100,AdventureSort=100010,AdventureValue=1,Condition=8,Desc='覆盖灼热熔铁的重盾，不断散发着高温与赤红的火光。',LoadShowSize=1.3,LoadShowRotate=340,LoadShowPose={0,0.37,0},}",
  [42554] = "{id=42554,NameZh='枫忆之盾',Icon='item_42554',Type=510,MaxNum=99,SellPrice=100,AdventureSort=100003,AdventureValue=1,Condition=8,Desc='枫叶的生命是短暂的脆弱的，稍一用力就它就会消散，但是有的时候越是弱小的东西反而能爆发出无限的可能性，无数的枫叶堆积而成造就了这无坚不摧的巨盾。',LoadShowSize=1.3,LoadShowRotate=340,LoadShowPose={0,0.37,0},}",
  [42555] = "{id=42555,NameZh='信仰之盾',Icon='item_42555',Type=510,MaxNum=99,SellPrice=100,AdventureSort=100005,AdventureValue=1,Condition=8,Desc='巴风特曾带领手下对梦罗克进行过一次史无前例的大侵袭，这次的战争造成了数以万计的民众伤亡，在危难的关头有十四位勇士站了出来，他们牺牲了自己保护了梦罗克，死后的他们留下了自己的武器，这些武器被梦罗克的人们当做信仰的象征，这面盾牌便是十四把武器之一。',LoadShowSize=1.4,LoadShowRotate=340,LoadShowPose={0,0.37,0},}",
  [42556] = "{id=42556,NameZh='亡灵盾',Icon='item_42556',Type=510,MaxNum=99,SellPrice=2100,AdventureValue=1,Condition=8,Desc='你见过拿着盾牌的亡灵么？',Level=95,LoadShowSize=1.2,LoadShowRotate=340,LoadShowPose={0,0.32,0},}",
  [42557] = "{id=42557,NameZh='灵犀宝珠',Icon='item_42557',Type=510,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=11000,AdventureValue=-1,Desc='“心有灵犀一点通。”这句来自斐扬的古话说的是那些有缘人。',Feature=1,}",
  [42558] = "{id=42558,NameZh='埃琉德尼尔壁垒',Icon='item_42558',Type=510,MaxNum=99,SellPrice=100,AdventureSort=100012,AdventureValue=1,Condition=8,Desc='埃琉德尼尔是一座漂浮在冥河之上的城堡，它拥有坚实的城防，这面盾牌就是那位大人亲自布下的防御——下水道的井盖。',Feature=1,TFValidDate='2019-10-28 05:00:00',ValidDate='2019-10-31 05:00:00',LoadShowSize=1.4,LoadShowRotate=340,LoadShowPose={0,0.44,0},}",
  [42559] = "{id=42559,NameZh='极寒宝珠',Icon='item_42559',Type=510,MaxNum=99,AuctionPrice=1,SellPrice=4800,}",
  [42560] = "{id=42560,NameZh='生命体盾',Icon='item_42560',Type=510,MaxNum=99,SellPrice=2400,Desc='雷根贝勒公司所开发的，以生命体为能量的盾牌。能够阻挡大多数的攻击。',Level=100,}",
  [42561] = "{id=42561,NameZh='魔器·阿斯莫德',Icon='item_42561',Type=510,MaxNum=99,SellPrice=100,AdventureSort=100011,AdventureValue=1,Condition=8,Desc='梦罗克碎片打造的禁忌武器，对应着异世界恶魔No.32·阿斯莫德，他长着三个头，分别为牛头、人头、公羊头，且有一条蛇尾。',LoadShowSize=1.2,LoadShowRotate=340,LoadShowPose={0,0.32,0},}",
  [42562] = "{id=42562,NameZh='最终防线',Icon='item_42562',Type=510,MaxNum=99,SellPrice=100,AdventureSort=100013,AdventureValue=1,Condition=8,Desc='一旦这道防线也被破除，那么人类的希望还能寄托于何处呢？',Feature=1,LoadShowSize=1.3,LoadShowRotate=340,LoadShowPose={0,0.44,0},}",
  [42563] = "{id=42563,NameZh='璞玉手镯',Icon='item_42563',Type=510,MaxNum=99,SellPrice=100,Desc='真正的美无需雕琢，不是么？',}",
  [42564] = "{id=42564,NameZh='科学救赎·之盾',Icon='item_42564',Type=510,MaxNum=99,SellPrice=100,AdventureSort=100014,AdventureValue=1,Condition=8,Desc='科学！科学！科学！为了科学一切的牺牲都是值得，蝼蚁们的生命本就毫无价值，因实验而死的他们应该觉得骄傲，这是他们的宿命！快了！就快了！真想看看我的盾抵挡住所有反抗者的攻击时他们的表情~啧啧啧',Feature=1,LoadShowSize=1,LoadShowPose={0,0.4,0},}",
  [42566] = "{id=42566,NameZh='圣息崇聆·盾',Icon='item_42566',Type=510,MaxNum=99,SellPrice=100,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='光与天空，圣洁的飞鸟，神的双翼已然张开，吾虔诚的信徒，愿你在吾的庇佑下体验幸福与美好，你的灵魂之音，吾等已经听到，这副圣盾赐予你，神祇永远与你同在。',LoadShowSize=1.2,LoadShowRotate=340,LoadShowPose={0,0.32,0},}",
  [42567] = "{id=42567,NameZh='辉光十字·盾',Icon='item_42567',Type=510,MaxNum=99,SellPrice=2600,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='这块巨盾出自阿卢纳贝兹教国最有名的工匠——索罗克之手，他搜寻了整个教国寻找制作武器的材料，最终在圣域神殿的地下深处寻到了结果，吸取神灵信仰的矿石坚硬无比，制成的武器更是消灭黑暗的破晓之力。',Level=110,LoadShowSize=1.2,LoadShowRotate=340,LoadShowPose={0,0.32,0},}",
  [42568] = "{id=42568,NameZh='火焰喷射器',Icon='item_42568',Type=510,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=7200,AdventureSort=11000,AdventureValue=-1,Desc='喷出火焰瞬间让敌人着火，请小心使用。',}",
  [42569] = "{id=42569,NameZh='誓约之书第二卷',Icon='item_42569',Type=510,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=7200,AdventureSort=11000,AdventureValue=-1,Desc='记录着在大圣堂所流传下来的音乐古书，当时是以系列丛书出版且非常畅销。',}",
  [42577] = "{id=42577,NameZh='蔷薇灵语之盾',Icon='item_42577',Type=510,MaxNum=99,SellPrice=3200,AdventureSort=11000,AdventureValue=1,Condition=8,Desc='这面盾牌被妖精一族的“灵语师”赋予了蔷薇的祝福。据说它是由某位妖精的床改造成的。',Level=110,LoadShowSize=1.5,LoadShowPose={0,0.25,0},}",
  [42578] = "{id=42578,NameZh='红鱼花铃·盾牌',Icon='item_42578',Type=510,Quality=3,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='长了一身红色鳞片的金鱼呀，喜欢在湖底的水草里悠闲地打瞌睡。有人投食的话，也会慢悠悠地钻到水面上，不紧不慢地吃鱼食。如果它会衔着盾牌游出水面，也不要惊讶，这是金鱼族的报答哟~',LoadShowSize=1,LoadShowRotate=340,LoadShowPose={0,0.4,0},}",
  [42579] = "{id=42579,NameZh='大天使之盾★',Icon='item_42579',Type=510,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=11000,AdventureValue=-1,Condition=8,Desc='拥有神的旨意，从神的传令那里神直接赐给他，具有象征性的盾牌。',Feature=1,LoadShowSize=1,LoadShowRotate=340,LoadShowPose={0,0.4,0},}",
