  [42581] = "{id=42581,NameZh='镜盾★',Icon='item_42581',Type=510,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=11000,AdventureValue=-1,Condition=8,Desc='用镜子制成的防具，对物理有着相当高的防御力。',Feature=1,LoadShowSize=1,LoadShowRotate=340,LoadShowPose={0,0.4,0},}",
