  [42592] = "{id=42592,NameZh='化学防护手套★',Icon='item_42592',Type=513,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=11000,AdventureValue=-1,Desc='以七种毒蛇蜕下的皮合制成的手套，可以抵御几乎所有腐蚀性物质，唯一的缺点是非常闷热。',Feature=1,}",
  [42593] = "{id=42593,NameZh='尼罗的手环★',Icon='item_42593',Type=514,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=11000,AdventureValue=-1,Desc='海利翁宝石所封印的手镯，可以净化邪恶的力量。',Feature=1,}",
  [42594] = "{id=42594,NameZh='蔷薇姬的腕轮★',Icon='item_42594',Type=514,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=11000,AdventureValue=-1,Desc='朴实的手环，内侧刻着“P.L.K\"三个意义不明的字母。',Feature=1,}",
  [42595] = "{id=42595,NameZh='芬特克的手环★',Icon='item_42595',Type=514,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=11000,AdventureValue=-1,Desc='手环内部的文字已经磨损，只能辩认出“You shall not”三个单词',Feature=1,}",
  [42596] = "{id=42596,NameZh='湛蓝天光·盾',Icon='item_42596',Type=510,MaxNum=99,SellPrice=2800,AdventureValue=1,Condition=8,Desc='阔大的云海之上透出湛蓝天光，晴空下的战士们振作起了精神。握好这面盾牌吧，它印证着你的忠诚，勇敢与希望。',Level=110,LoadShowSize=1.3,LoadShowRotate=340,LoadShowPose={0,0.4,0},}",
  [42597] = "{id=42597,NameZh='天虹圣遗·盾',Icon='item_42597',Type=510,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=100019,AdventureValue=1,Condition=8,Desc='浮空精灵收集彩虹桥碎片打造的盾牌，反射的光芒过于绚烂，令人瞩目，因此嘲讽能力很强。',LoadShowSize=1.8,LoadShowPose={0,0.22,0},}",
  [42598] = "{id=42598,NameZh='月下祈者·盾',Icon='item_42598',Type=510,MaxNum=99,SellPrice=100,AdventureSort=11000,AdventureValue=1,Condition=8,Desc='冰封千年的陨铁，王国的工匠们用尽办法也无法将其熔铸，却因小学徒的一次失误暴露在月光下。那一刻奇迹发生，陨铁融化宛若水银般流转，在月光下散发耀眼星辉。\n此乃月光赐福之圣盾，掌盾者当以月光之力，坚定信念，守护正义！',LoadShowPose={0,0.3,-0.5},}",
  [42599] = "{id=42599,NameZh='英灵起点·盾',Icon='item_42599',Type=510,Quality=2,MaxNum=99,SellPrice=100,Desc='克里图拉新生领到的初心武器，致敬英灵而铸上蓝金涂装。据说它和矛出自同一位设计师。他想要跟战友进入英灵殿、盾中有股与宿命矛盾的忧伤。',NoStorage=5,}",
  [42600] = "{id=42600,NameZh='英灵信标·盾[1]',Icon='item_42600',Type=510,Quality=3,MaxNum=99,SellPrice=100,Desc='这件盾是指引女武神降临、迎接英灵的道标。阵亡的勇士抱着它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,}",
  [42601] = "{id=42601,NameZh='英灵羽证·盾',Icon='item_42601',Type=510,Quality=3,MaxNum=99,SellPrice=100,Desc='英灵的证明。潜入学院的女武神在盾中注入了奥丁领域的魔力。盾长出了羽翼，像在温柔地守护同伴最后的阵线。',NoStorage=5,}",
  [42602] = "{id=42602,NameZh='英灵起点·臂铠',Icon='item_42602',Type=514,Quality=2,MaxNum=99,SellPrice=100,Desc='克里图拉新生领到的初心臂铠。它致敬英灵而铸上蓝金涂装。这具臂铠从外观上让学生们联想到了大热剧\"假面符文骑士·金色\"里的招牌姿势。从此，把臂铠不规范地戴在腰上，并摆出奇特姿势的风气，开始在广场上流传开来。',NoStorage=5,}",
  [42603] = "{id=42603,NameZh='英灵信标·臂铠[1]',Icon='item_42603',Type=514,Quality=3,MaxNum=99,SellPrice=100,Desc='这具臂铠是指引女武神降临、迎接英灵的道标。阵亡的勇士穿戴它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,}",
  [42604] = "{id=42604,NameZh='英灵羽证·臂铠',Icon='item_42604',Type=514,Quality=3,MaxNum=99,SellPrice=100,Desc='英灵的证明。潜入学院的女武神在臂铠中注入了奥丁领域的魔力。臂铠长出了羽翼，让现在的它更像假面符文骑士的变身道具了。',NoStorage=5,}",
  [42605] = "{id=42605,NameZh='手臂防护具',Icon='item_42605',Type=510,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='天水之国忍者众的制式防具，灵活轻便，完全不会影响行动。',}",
  [42606] = "{id=42606,NameZh='改良型手臂防护具',Icon='item_42606',Type=510,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='天水之国忍者众的高级防具，只有精英忍者才能佩戴，比普通的手臂护具更加灵活，也更加坚韧。',}",
  [42608] = "{id=42608,NameZh='图腾木雕',Icon='item_42608',Type=512,Quality=2,MaxNum=99,SellPrice=100,Desc='一枚精致的图腾，雕刻着某位神明，也许能够给佩戴者带来好运。',Feature=1,Delete=42608}",
  [42609] = "{id=42609,NameZh='智慧图腾',Icon='item_42609',Type=512,Quality=3,MaxNum=99,SellPrice=100,Desc='上古时期的克魔岛人将图腾柱视为天神在人间的化身，他们参拜供奉这些图腾，认为这样能够带来救赎和指引。',Feature=1,Delete=42609}",
  [42610] = "{id=42610,NameZh='天神的启示',Icon='item_42610',Type=512,Quality=4,MaxNum=99,SellPrice=100,Desc='于蒙昧与灾祸之中，神明的化身将显现，为人们指出前行的道路。',Feature=1,Delete=42610}",
  [42624] = "{id=42624,NameZh='骨笛',Icon='item_42624',Type=513,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=11000,AdventureValue=-1,Desc='较为简陋的原始乐器，使用鸟类翅骨制成的笛子。',Feature=1,Delete=42624}",
  [42625] = "{id=42625,NameZh='唤鹰笛',Icon='item_42625',Type=513,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=11000,AdventureValue=-1,Desc='根据克魔岛的传说，用这支骨笛吹奏特定的曲子，可以召唤统御狂风与雷电的巨鹰。',Feature=1,Delete=42625}",
  [42626] = "{id=42626,NameZh='灵骨之音',Icon='item_42626',Type=513,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=11000,AdventureValue=-1,Desc='为祸克魔岛的巨鹰被猎人杀死，翅骨制成骨笛作为纪念。这只骨笛中寄居着巨鹰的怨念，一经吹奏便会引来呼啸的狂风。',Feature=1,Delete=42626}",
  [42627] = "{id=42627,NameZh='巨兽头骨',Icon='item_42627',Type=510,Quality=2,MaxNum=99,SellPrice=100,Desc='不知名巨兽的头骨，可能是上古时期生活在克魔岛野兽的遗骸。',Feature=1,Delete=42627}",
  [42628] = "{id=42628,NameZh='龙骨盾',Icon='item_42628',Type=510,Quality=3,MaxNum=99,SellPrice=100,Desc='传说上古时期的克魔岛曾有巨龙栖息，这面用龙的头骨制成的盾牌就是最好的证据。',Feature=1,Delete=42628}",
  [42629] = "{id=42629,NameZh='狩龙武勋',Icon='item_42629',Type=510,Quality=4,MaxNum=99,SellPrice=100,Desc='上古时期的克魔岛，狩猎一头巨龙是每个勇士都想达成的荣耀，勇士会将杀死的巨龙制成盾牌与武器，作为这无上功勋的证明。',Feature=1,Delete=42629}",
  [42630] = "{id=42630,NameZh='剥皮刀',Icon='item_42630',Type=513,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=11000,AdventureValue=-1,Desc='一把骨制小刀，猎人们可以用它剥取猎物的毛皮。',Feature=1,Delete=42630}",
  [42631] = "{id=42631,NameZh='巫毒之刃',Icon='item_42631',Type=513,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=11000,AdventureValue=-1,Desc='古老的骨质小刀，是上古时期克魔岛人的祭祀工具，他们会用这把刀杀死猎物，将它们作为献给天神的祭品。',Feature=1,Delete=42631}",
  [42632] = "{id=42632,NameZh='恶毒之伤',Icon='item_42632',Type=513,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=11000,AdventureValue=-1,Desc='这把刀上附着了这世上最恶毒的诅咒，它留下的伤口永远无法被治愈。”无法治愈的伤口，未必需要用刀留下……“',Feature=1,Delete=42632}",
  [42633] = "{id=42633,NameZh='水晶之颅',Icon='item_42633',Type=513,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=11000,AdventureValue=-1,Desc='一颗晶莹剔透的水晶头骨，从外形来看并非人类的骨骼。',Feature=1,Delete=42633}",
  [42634] = "{id=42634,NameZh='恶魔之颅',Icon='item_42634',Type=513,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=11000,AdventureValue=-1,Desc='上古时期为祸一方的恶魔，强大且凶残。被诛杀后的遗骸依然蕴含着强大的魔力。',Feature=1,Delete=42634}",
  [42635] = "{id=42635,NameZh='猎魔人的战利品',Icon='item_42635',Type=513,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=11000,AdventureValue=-1,Desc='当恶魔肆虐，人们呼唤猎魔人的名字，他便会如期出现，腰间挂着18枚恶魔的头颅——只有最强大的魔王，才有资格成为他的战利品。',Feature=1,Delete=42635}",
  [42636] = "{id=42636,NameZh='古代金币',Icon='item_42636',Type=510,Quality=2,MaxNum=99,SellPrice=100,Desc='雕刻着奇怪图案的古代金币，历史学者们推测这是克魔岛先民们使用的墓葬品。',Feature=1,Delete=42636}",
  [42637] = "{id=42637,NameZh='赦罪金',Icon='item_42637',Type=510,Quality=3,MaxNum=99,SellPrice=100,Desc='根据克魔岛的传说，亡者需要向死神支付足量的金币，以赦免他们生前犯下的罪孽。',Feature=1,Delete=42637}",
  [42638] = "{id=42638,NameZh='生者的罪孽',Icon='item_42638',Type=510,Quality=4,MaxNum=99,SellPrice=100,Desc='引渡亡者的小船摇摇晃晃，仿佛随时都会倾覆，生前的每一份罪孽都会化作一枚金币，为小船增添一分重量，让这场旅途愈加凶险。',Feature=1,Delete=42638}",
  [42639] = "{id=42639,NameZh='捕梦网',Icon='item_42639',Type=514,Quality=2,MaxNum=99,SellPrice=100,Desc='克魔岛传统的饰物，据说可以捕获美好的梦境，让噩梦消散。',Feature=1,Delete=42639}",
  [42640] = "{id=42640,NameZh='彼岸之网',Icon='item_42640',Type=514,Quality=3,MaxNum=99,SellPrice=100,Desc='将彼岸之网悬挂在床头，可以连通现实与梦境，与错失之人重逢。',Feature=1,Delete=42640}",
  [42641] = "{id=42641,NameZh='梦境守护者',Icon='item_42641',Type=514,Quality=4,MaxNum=99,SellPrice=100,Desc='梦境守护者的配饰，传说中梦境守护者只在夜间出现，他们游走于现实与梦境之间，捕杀梦魇，守护人们的安眠。',Feature=1,Delete=42641}",
  [42642] = "{id=42642,NameZh='赤羽毛笔',Icon='item_42642',Type=513,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=11000,AdventureValue=-1,Desc='使用鸟类翎毛制作的羽毛笔，书写非常顺畅。',Feature=1,Delete=42642}",
  [42643] = "{id=42643,NameZh='烈焰轻羽',Icon='item_42643',Type=513,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=11000,AdventureValue=-1,Desc='一根被火焰包裹着的羽毛，令人惊奇的是，火焰似乎完全没有将羽毛损伤分毫。',Feature=1,Delete=42643}",
  [42644] = "{id=42644,NameZh='不死鸟之羽',Icon='item_42644',Type=513,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=11000,AdventureValue=-1,Desc='传说中不死鸟的羽毛，饱含着象征新生的力量。“这不是第一次，也不会是最后一次……”',Feature=1,Delete=42644}",
  [42645] = "{id=42645,NameZh='古代旗帜',Icon='item_42645',Type=510,Quality=2,MaxNum=99,SellPrice=100,Desc='一面古老的战旗，残破的旗帜和满布斫痕的旗杆昭示着它见证过怎样惨烈的战斗。',Feature=1,Delete=42645}",
  [42646] = "{id=42646,NameZh='勇气之旗',Icon='item_42646',Type=510,Quality=3,MaxNum=99,SellPrice=100,Desc='上古时期的克魔岛魔物肆虐，骁勇的岛民在英雄的带领下组建鹰之团，击败魔物，才有了后世平静的克魔岛。这面旗帜便是鹰之团的勇士们勇气的象征。',Feature=1,Delete=42646}",
  [42647] = "{id=42647,NameZh='不屈战团的传承',Icon='item_42647',Type=510,Quality=4,MaxNum=99,SellPrice=100,Desc='梦罗克入侵时期，一支战团在与魔王爪牙的战斗中血战至全军覆没，战场中耸立的战旗将这些勇士的战意与勇气凝聚起来，走到旗帜附近，似乎能够听到那些勇士们的战吼。“身后即是家园，我们以无路可退！此旗是拒敌之盾，亦是任何人不可逾越之阵线，唯有死战！”',Feature=1,Delete=42647}",
  [42648] = "{id=42648,NameZh='船灯',Icon='item_42648',Type=513,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=11000,AdventureValue=-1,Desc='悬挂在船头的明灯，即使在迷雾中航行也不会迷失方向。',Feature=1,Delete=42648}",
  [42649] = "{id=42649,NameZh='引魂灯',Icon='item_42649',Type=513,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=11000,AdventureValue=-1,Desc='传说中能够吸引亡魂注意的灯火。人们将明灯悬挂在家门口，相传这样可以让那些迷失的亡灵穿越迷雾，回到家乡。',Feature=1,Delete=42649}",
  [42650] = "{id=42650,NameZh='万灵归途',Icon='item_42650',Type=513,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=11000,AdventureValue=-1,Desc='引渡人揺着小船，穿越漫布迷雾的冥河，伴着船头的灯火，带万千亡灵踏上往生之路。“命运自有定数，万灵皆有归途。”',Feature=1,Delete=42650}",
  [42651] = "{id=42651,NameZh='神秘石盘',Icon='item_42651',Type=510,Quality=2,MaxNum=99,SellPrice=100,Desc='一块雕刻着华丽纹路的石盘，令人惊叹它的精致做工。',Feature=1,Delete=42651}",
  [42652] = "{id=42652,NameZh='太阳轮盘',Icon='item_42652',Type=510,Quality=3,MaxNum=99,SellPrice=100,Desc='上古时期克魔岛先民用以记录历史的轮盘，每一个轮盘记录一次四季的轮回。',Feature=1,Delete=42652}",
  [42653] = "{id=42653,NameZh='历史见证者',Icon='item_42653',Type=510,Quality=4,MaxNum=99,SellPrice=100,Desc='蕴含着如同太阳般炽热魔力的盾牌，它的主人是传说中的勇者“太阳骑士”。勇者依靠它的力量剿灭魔物，播撒福音。“使用说明：在阳光下直射三小时可以让本盾牌完全充能……”',Feature=1,Delete=42653}",
  [42654] = "{id=42654,NameZh='传统秘药',Icon='item_42654',Type=513,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=11000,AdventureValue=-1,Desc='根据克魔岛古法制成的魔药，效用不明，最好不要轻易尝试。',Feature=1,Delete=42654}",
  [42655] = "{id=42655,NameZh='魔女的坩埚',Icon='item_42655',Type=513,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=11000,AdventureValue=-1,Desc='传说中灾厄魔女使用过的坩埚，邪恶的魔女用它炼制了什么魔药呢？',Feature=1,Delete=42655}",
  [42656] = "{id=42656,NameZh='生息之坛',Icon='item_42656',Type=513,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=11000,AdventureValue=-1,Desc='被森林之灵祝福过的宝物，即使是最普通的草药，也能炼制成强大的魔药。“魔药可以杀人，也可以救人，怎么使用全凭本心……”',Feature=1,Delete=42656}",
  [42657] = "{id=42657,NameZh='先祖面具',Icon='item_42657',Type=510,Quality=2,MaxNum=99,SellPrice=100,Desc='克魔岛传统风格的面具，但是从大小来看，它更像是一面盾牌。',Feature=1,Delete=42657}",
  [42658] = "{id=42658,NameZh='仪祭古面',Icon='item_42658',Type=510,Quality=3,MaxNum=99,SellPrice=100,Desc='远古时期，克魔岛的先民们祭拜先祖时戴在脸上的祭器，相传这种面目可憎的假面能够吓退邪祟，保佑部族的安定。',Feature=1,Delete=42658}",
  [42659] = "{id=42659,NameZh='祖灵之庇佑',Icon='item_42659',Type=510,Quality=4,MaxNum=99,SellPrice=100,Desc='常年供奉在祭坛中的鬼面具，上面附着了祖先的灵魂，能够祛除邪祟，用另一种方式庇护着自己的后裔。“那是我孙子的孙子的孙子的孙子……”',Feature=1,Delete=42659}",
  [42660] = "{id=42660,NameZh='龟甲盾',Icon='item_42660',Type=510,Quality=2,MaxNum=99,SellPrice=100,Desc='一面巨大的龟甲，可以用来装饰房间，或许也可以当作盾牌使用。',Feature=1,Delete=42660}",
  [42661] = "{id=42661,NameZh='海洋恩赐',Icon='item_42661',Type=510,Quality=3,MaxNum=99,SellPrice=100,Desc='每年都会有暮年海龟来到克魔岛，平静的迎来自己生命的终点。它们的骸骨被克魔岛岛民视作海洋的恩赐，是天然的锻造材料。',Feature=1,Delete=42661}",
  [42662] = "{id=42662,NameZh='海灵壁垒',Icon='item_42662',Type=510,Quality=4,MaxNum=99,SellPrice=100,Desc='克魔岛上居住着的是海洋之民，受到大海的庇护。圣洁的海洋之力会驱散邪恶，让他们免受侵害。“海洋可以包容一切，亦会吞噬一切……”',Feature=1,Delete=42662}",
  [42663] = "{id=42663,NameZh='古代石板',Icon='item_42663',Type=510,Quality=2,MaxNum=99,SellPrice=100,Desc='一块古老的石板，根据历史学家的研究，上面的文字与图案似乎讲述了一个英雄的故事。',Feature=1,Delete=42663}",
  [42664] = "{id=42664,NameZh='英雄丰碑',Icon='item_42664',Type=510,Quality=3,MaxNum=99,SellPrice=100,Desc='在英雄们的带领下，先民们击败强敌，迎来幸福和平的生活。先民们树立石碑记载此事，让后人也能歌颂英雄的功绩。',Feature=1,Delete=42664}",
  [42665] = "{id=42665,NameZh='末日箴言',Icon='item_42665',Type=510,Quality=4,MaxNum=99,SellPrice=100,Desc='火山爆发、恶魔肆虐，这块石碑上记载了诸神黄昏的末日景象。把手放在石碑上，甚至可以感觉到末日降临时人们的慌张与绝望。“毁灭之后，即是新生……”',Feature=1,Delete=42665}",
  [42666] = "{id=42666,NameZh='巫毒秘典',Icon='item_42666',Type=513,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=11000,AdventureValue=-1,Desc='记载了许多古怪巫术的秘典，也不知道有没有用，或许可以找谁试验一下？',Feature=1,Delete=42666}",
  [42667] = "{id=42667,NameZh='神秘抄本',Icon='item_42667',Type=513,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=11000,AdventureValue=-1,Desc='一本破旧的笔记，上面用难以辨别的文字记载着什么，或许是某种魔法咒语？当触碰这本书时感觉耳边回荡着一个声音，引诱你将这本笔记打开。',Feature=1,Delete=42667}",
  [42668] = "{id=42668,NameZh='噩梦原典',Icon='item_42668',Type=513,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=11000,AdventureValue=-1,Desc='一本危险的古老魔法书，上面的古代文字晦涩难懂。克魔岛的居民在岛上的一处洞穴中发现了这本书，但没有人知道上面书写的文字是什么意思，有人坚信这是某种秘密宗教信奉的圣典。“等等，好像有什么东西要钻出来了……”',Feature=1,Delete=42668}",
  [42669] = "{id=42669,NameZh='远古回音·盾',Icon='item_42669',Type=510,MaxNum=99,SellPrice=3200,Condition=8,Desc='铭刻着神秘纹样的盾，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,}",
  [42671] = "{id=42671,NameZh='王国荣辉·盾',Icon='item_42671',Type=510,MaxNum=99,SellPrice=100,Condition=8,Desc='效忠于王室的宫廷侍卫所持的盾牌，其上绘有卢恩王家纹章。尽管为了美观，盾牌的抗性被大幅削弱；但作为一件艺术品，它还是值得收藏的。',LoadShowSize=1.6,LoadShowPose={0,0.2,0},}",
  [42672] = "{id=42672,NameZh='神话尘封·荒境之盾',Icon='item_42672',Type=510,Quality=2,MaxNum=99,SellPrice=100,Desc='在荒境发掘出的盾牌，曾为传说中的洛阳勇士所持有。',Level=120,Delete=42672}",
  [42673] = "{id=42673,NameZh='辉煌再临·荒境圣盾',Icon='item_42673',Type=510,Quality=2,MaxNum=99,SellPrice=100,Desc='沉眠在荒境深处的传奇盾牌，可以为你增加物理、魔法伤害。因为新主人的出现，它褪去尘埃，重新焕发耀目的光彩。',Level=130,Delete=42673}",
  [42674] = "{id=42674,NameZh='辉煌再临·荒境圣盾',Icon='item_42673',Type=510,Quality=3,MaxNum=99,SellPrice=100,Desc='沉眠在荒境深处的传奇盾牌，可以为你增加忽视物理防御。因为新主人的出现，它褪去尘埃，重新焕发耀目的光彩。',Level=130,Delete=42674}",
  [42675] = "{id=42675,NameZh='辉煌再临·荒境圣盾',Icon='item_42673',Type=510,Quality=3,MaxNum=99,SellPrice=100,Desc='沉眠在荒境深处的传奇盾牌，可以为你增加忽视魔法防御。因为新主人的出现，它褪去尘埃，重新焕发耀目的光彩。',Level=130,Delete=42675}",
  [42676] = "{id=42676,NameZh='辉煌再临·荒境圣盾',Icon='item_42673',Type=510,Quality=3,MaxNum=99,SellPrice=100,Desc='沉眠在荒境深处的传奇盾牌，可以为你增加物理穿刺。因为新主人的出现，它褪去尘埃，重新焕发耀目的光彩。',Level=130,Delete=42676}",
  [42677] = "{id=42677,NameZh='辉煌再临·荒境圣盾',Icon='item_42673',Type=510,Quality=3,MaxNum=99,SellPrice=100,Desc='沉眠在荒境深处的传奇盾牌，可以为你增加生命上限。因为新主人的出现，它褪去尘埃，重新焕发耀目的光彩。',Level=130,Delete=42677}",
  [42679] = "{id=42679,NameZh='冒险新秀盾牌',Icon='item_42679',Type=510,Quality=2,MaxNum=99,SellPrice=100,Desc='冒险家公会为初出茅庐的冒险者们准备的制式盾牌，结实耐用，举起它，开辟出崭新的冒险之路吧！',Level=20,}",
