  [42684] = "{id=42684,NameZh='冒险精英盾牌',Icon='item_42680',Type=510,Quality=2,MaxNum=99,SellPrice=100,Desc='冒险家公会为娴熟的精英冒险家准备的制式盾牌，结实耐用，举起它，开辟更多精彩的冒险旅程吧！',Level=20,}",
  [42685] = "{id=42685,NameZh='冒险英雄盾牌',Icon='item_42685',Type=510,Quality=2,MaxNum=99,SellPrice=100,Desc='冒险家公会为名震一方的英雄冒险家准备的制式盾牌，结实耐用，举起它，大胆迈上传奇英雄之路吧！',Level=60,}",
  [42686] = "{id=42686,NameZh='冒险大师盾牌',Icon='item_42686',Type=510,Quality=3,MaxNum=99,SellPrice=100,Desc='冒险家公会为大陆最顶尖的冒险大师定制的盾牌，防御力不俗的同时也是身份的象征，可以为你增加物理、魔法伤害。举起它，开辟出属于自己的巅峰之路吧！',Level=60,}",
