  [42691] = "{id=42691,NameZh='陈旧的海利翁手环',Icon='item_42593',Type=514,Quality=4,MaxNum=99,SellPrice=100,Desc='有些陈旧的海利翁手环，已经不能发挥原本所有的能力了，铁匠们常常用它作为某些锻炼技术的实验材料。',NoSale=1,NoStorage=7,Feature=1,}",
  [42692] = "{id=42692,NameZh='陈旧的天神的启示',Icon='item_42610',Type=512,Quality=4,MaxNum=99,SellPrice=100,Desc='有些陈旧的天神启示，已经不能发挥原本所有的能力了，铁匠们常常用它作为某些锻炼技术的实验材料。',NoSale=1,NoStorage=7,Feature=1,}",
  [43001] = "{id=43001,NameZh='乐园团披风',Icon='item_43001',Type=520,MaxNum=99,SellPrice=168,Desc='发放给加入乐园团的人的披风。飘动的背影看上去很帅。',Level=12,Feature=4,}",
  [43002] = "{id=43002,NameZh='红色围巾',Icon='item_43002',Type=520,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=1680,Desc='围在脖子上可以保暖的红色布条。',Feature=1,}",
  [43003] = "{id=43003,NameZh='斗篷',Icon='item_43003',Type=520,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=80,AdventureSort=12000,AdventureValue=-1,Desc='用坚硬的布料做成，遮住脖子、肩膀和背部，有防御力的斗篷。',Feature=1,}",
  [43004] = "{id=43004,NameZh='抗魔斗篷',Icon='item_43004',Type=520,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=120,AdventureSort=12000,AdventureValue=-1,Desc='对魔法有优秀的防御力斗篷。',Feature=1,}",
  [43005] = "{id=43005,NameZh='迪斯凯特的披风',Icon='item_43005',Type=520,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=3360,AdventureSort=12000,AdventureValue=-1,Desc='据说是依照贤者迪斯凯特佣兵时代的穿着仿制的。虽然是仿制品，披风的做工却意外的精良。',Feature=1,}",
  [43006] = "{id=43006,NameZh='奔跑者徽章',Icon='item_43006',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=750,AdventureSort=12000,AdventureValue=-1,Desc='快速奔跑的人喜欢使用的徽章。只要佩戴就想奔跑。',Feature=1,}",
  [43007] = "{id=43007,NameZh='伯爵斗篷',Icon='item_43007',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=825,AdventureSort=12000,AdventureValue=-1,Desc='传说中某个村子的知名领主穿过的披肩类，最好在表现威风时穿戴。',Feature=1,}",
  [43008] = "{id=43008,NameZh='披肩[1]',Icon='item_43008',Type=520,MaxNum=99,SellPrice=100,Desc='对魔法有优秀的防御力斗篷。',Level=30,Feature=4,}",
  [43009] = "{id=43009,NameZh='护肩甲',Icon='item_43009',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=300,AdventureSort=12000,AdventureValue=-1,Desc='坚硬的圆形护甲片给肩部提供了额外的防御力。',Feature=1,}",
  [43010] = "{id=43010,NameZh='邪骸战士的斗篷[1]',Icon='item_43010',Type=520,MaxNum=99,SellPrice=100,Desc='据说邪骸战士爱用的斗篷。',Level=60,Feature=4,}",
  [43011] = "{id=43011,NameZh='贝利的斗篷[1]',Icon='2',Type=520,MaxNum=99,SellPrice=100,Desc='奥丁的一位儿子贝利所使用的斗篷，虽然是一位盲人却能把战士厚德杀死，有着贝利奋斗的痕迹。',Level=50,Feature=4,}",
  [43012] = "{id=43012,NameZh='摩菲斯披肩[1]',Icon='2',Type=520,MaxNum=99,SellPrice=100,Desc='为了要解开摩菲斯的封印三把钥匙其中之一的披肩，据说这披肩有记载着古代的咒文。',Level=10,Feature=4,}",
  [43013] = "{id=43013,NameZh='茉莉雅娜斗篷[1]',Icon='2',Type=520,MaxNum=99,SellPrice=100,Desc='有着灰色光芒乌鸦化身的茉莉雅娜权能，用乌鸦羽毛所做的灰色斗篷。',Level=10,Feature=4,}",
  [43014] = "{id=43014,NameZh='哥夫内肩饰',Icon='item_43014',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=211,AdventureSort=12000,AdventureValue=-1,Desc='哥夫内第一次做的防具， 据说他非常珍惜这肩饰。',Feature=1,}",
  [43015] = "{id=43015,NameZh='巴基力的披风[1]',Icon='2',Type=520,MaxNum=99,SellPrice=100,Desc='侍奉奥丁的战争少女的披风，华丽且轻巧。',Level=10,Feature=4,}",
  [43016] = "{id=43016,NameZh='生存斗篷',Icon='item_43016',Type=520,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=120,AdventureSort=12000,AdventureValue=-1,Desc='不管在什么情况，让生存的可能性，极度提高的斗蓬。',Feature=1,}",
  [43017] = "{id=43017,NameZh='龙纹外套',Icon='item_43017',Type=520,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=120,AdventureSort=12000,AdventureValue=-1,Desc='用300条龙皮制作的外套。传说可以抵抗魔龙的毒气。 ',Feature=1,}",
  [43018] = "{id=43018,NameZh='阿斯普利卡[1]',Icon='2',Type=520,MaxNum=99,SellPrice=100,Desc='将世界上所有的光收集起来做成的翅膀，拥有众神之光的意思。',Level=10,Feature=4,}",
  [43019] = "{id=43019,NameZh='三角兽之皮[1]',Icon='2',Type=520,MaxNum=99,SellPrice=100,Desc='皮毛之间长有植物茎干的三角兽之皮。',Level=10,Feature=4,}",
  [43020] = "{id=43020,NameZh='圣堂披风[1]',Icon='item_43020',Type=520,MaxNum=99,SellPrice=100,Desc='普隆德拉教堂为了保护圣职者而研发的牧师专用服装之一。',Level=70,Feature=4,}",
  [43021] = "{id=43021,NameZh='时间守护者披风[1]',Icon='2',Type=520,MaxNum=99,SellPrice=100,Desc='守护时间的披风，使用它可以免受时空撕扯的痛楚。',Level=10,Feature=4,}",
  [43022] = "{id=43022,NameZh='龙之披风[1]',Icon='2',Type=520,MaxNum=99,SellPrice=100,Desc='用飞龙的鬃毛制作而成的披风。',Level=10,Feature=4,}",
  [43023] = "{id=43023,NameZh='猎鹰披肩[1]',Icon='item_43023',Type=520,MaxNum=99,SellPrice=100,Desc='妙勒德的女儿菲依雅，经常借给洛奇的披肩，有猎鹰的敏捷性，可以躲过任何危险似的。',Level=70,}",
  [43024] = "{id=43024,NameZh='时之蓝披肩',Icon='item_43024',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=675,AdventureSort=12000,AdventureValue=-1,Desc='侠盗时之蓝“工作”时所穿的蓝色披肩。',Feature=1,}",
  [43025] = "{id=43025,NameZh='背德皇帝的斗篷',Icon='item_43025',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=675,AdventureSort=12000,AdventureValue=-1,Desc='据说该斗篷是大路王三世最喜欢的款式。',Feature=1,}",
  [43026] = "{id=43026,NameZh='棉衬衫',Icon='item_43026',Type=520,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=80,AdventureSort=12000,AdventureValue=-1,Desc='纯棉制成的衣服，穿着时非常舒服的衣物。',Feature=1,}",
  [43027] = "{id=43027,NameZh='坚定斗篷',Icon='item_43027',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=240,AdventureSort=12000,AdventureValue=-1,Desc='简约和有棱角的设计，让斗篷的使用者相信自己的意志似乎变得更坚定了。',Feature=1,}",
  [43028] = "{id=43028,NameZh='黑曜石斗篷',Icon='item_43028',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=372,AdventureSort=12000,AdventureValue=-1,Desc='披风镶嵌有黑曜石，能让穿戴着的魔法防御确实提升。',Feature=1,}",
  [43029] = "{id=43029,NameZh='言灵护甲',Icon='item_43029',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=254,AdventureSort=12000,AdventureValue=-1,Desc='在衣服上的符文是蕴含了魔力的古代文字。',Feature=1,}",
  [43030] = "{id=43030,NameZh='多芙的斗篷',Icon='item_43030',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=422,AdventureSort=12000,AdventureValue=-1,Desc='并不能把人好好裹住的斗篷。',Feature=1,}",
  [43031] = "{id=43031,NameZh='高等生存斗篷',Icon='item_43031',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=240,AdventureSort=12000,AdventureValue=-1,Desc='经过制作者多方面推敲，该斗篷进一步提了升装备者的生存能力。',Feature=1,}",
  [43032] = "{id=43032,NameZh='坚定魔法斗篷',Icon='item_43032',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=480,AdventureSort=12000,AdventureValue=-1,Desc='就算是外行人都能感受到斗篷上强力的魔法波动!据说穿上它让人遇事果决坚定。',Feature=1,}",
  [43033] = "{id=43033,NameZh='光明圣徒披风',Icon='item_43033',Type=520,Quality=3,MaxNum=99,SellPrice=100,Desc='圣歌教会的锻造神工匠，人称“光明圣徒”的安德鲁冕下为那些英勇善战的教会勇士所设计的一套制式服装，防御力极其优秀。起初这套制式服装没有名字，但其优秀的防御力让所有勇士们都爱不释手，他们用锻造这安德鲁的称号来为这制式服装命名。这就是“光明圣徒”套装。这件为“光明圣徒”套装的披风部分。受到光明圣徒的祝福，安全精炼时消耗的装备件数减少一半。',Feature=1,}",
  [43034] = "{id=43034,NameZh='风行者斗篷',Icon='item_43002',Type=520,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=3200,AdventureSort=12000,AdventureValue=-1,Desc='精灵莱利斯使用的斗篷，穿上的人步伐隐秘，让人难以察觉。据说使用者可以得到风的青睐。',Feature=1,}",
  [43035] = "{id=43035,NameZh='变色龙披风',Icon='item_43035',Type=520,MaxNum=99,SellPrice=100,}",
  [43036] = "{id=43036,NameZh='骷髅披风',Icon='item_43036',Type=520,MaxNum=99,SellPrice=100,}",
  [43037] = "{id=43037,NameZh='高级乐园团披风',Icon='item_43001',Type=520,MaxNum=99,SellPrice=100,Level=1,NoStorage=5,}",
  [43038] = "{id=43038,NameZh='预言者披风',Icon='item_43038',Type=520,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=380,AdventureSort=12000,AdventureValue=-1,Desc='“我预言你会买下这件预言者披风！”——冒充预言家的梦罗克商人',}",
  [43039] = "{id=43039,NameZh='纳户特基格的斗篷',Icon='item_43039',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=12000,AdventureValue=-1,Desc='古老的秘密，暗黑的历史。在纳户特基格的斗篷下，藏匿着那些阳光下见不到的东西。',Feature=1,}",
  [43040] = "{id=43040,NameZh='吟游诗人的披风',Icon='item_43040',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=12000,AdventureValue=-1,Desc='过路人请留步，且听我抚琴唱起古老的传说，这件披风下，到底藏着多少故事呢？',Feature=1,}",
  [43041] = "{id=43041,NameZh='末日斗篷',Icon='item_43041',Type=520,Quality=3,MaxNum=99,SellPrice=100,}",
  [43042] = "{id=43042,NameZh='浪人披风',Icon='item_43042',Type=520,MaxNum=99,SellPrice=100,Desc='你走以后，所到之处，皆是他乡。',}",
  [43043] = "{id=43043,NameZh='狙击手斗篷',Icon='item_43043',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=16000,AdventureSort=12000,AdventureValue=-1,Desc='为了狙击手设计的斗篷，隐蔽性极高。穿着它趴在草从中，能与环境融为一体。',}",
  [43044] = "{id=43044,NameZh='将军斗篷',Icon='item_43044',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=7000,AdventureSort=12000,AdventureValue=-1,Desc='高阶军官的象征，华丽浮夸的外表下，其实具有很强的实用性。',}",
  [43045] = "{id=43045,NameZh='初心者披风',Icon='item_43045',Type=520,Quality=2,MaxNum=99,SellPrice=100,Desc='乐园团为下定决心的初心者们特意准备的披风，非常实用。',Feature=1,}",
  [43046] = "{id=43046,NameZh='恐惧斗篷',Icon='item_43046',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=4000,AdventureSort=12000,AdventureValue=-1,Desc='无尽的黑暗笼罩在这件斗篷四周. 只有完全克服恐惧的人才可以使用。',}",
  [43047] = "{id=43047,NameZh='巡守队披风',Icon='item_43001',Type=520,MaxNum=99,SellPrice=168,Desc='发放给加入巡守队的人的披风。飘动的背影看上去很帅。',Level=12,Feature=4,}",
  [43055] = "{id=43055,NameZh='英灵起点·披风',Icon='item_43055',Type=520,Quality=2,MaxNum=99,SellPrice=100,Desc='克里图拉新生领到的初心衣物，致敬英灵而铸上蓝金涂装。据说设计者是位印象派画家，在披风的各个细节上融入了极光、彩虹与星空的特色。',NoStorage=5,}",
  [43056] = "{id=43056,NameZh='英灵信标·披风[1]',Icon='item_43056',Type=520,Quality=3,MaxNum=99,SellPrice=100,Desc='这件披风是指引女武神降临、迎接英灵的道标。阵亡的勇士盖好它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,}",
  [43057] = "{id=43057,NameZh='英灵羽证·披风',Icon='item_43057',Type=520,Quality=3,MaxNum=99,SellPrice=100,Desc='英灵的证明。潜入学院的女武神在披风中注入了奥丁领域的魔力。披风生出翎羽，可以有效过滤魔力中的有害波动。',NoStorage=5,}",
  [43058] = "{id=43058,NameZh='衬衫★',Icon='item_43058',Type=520,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=12000,AdventureValue=-1,Desc='让人可以全力奔跑的轻便盔甲。虽然看上去和奔跑衬衫很相似，但具有盔甲的防御力。',}",
  [43059] = "{id=43059,NameZh='伯爵斗篷★',Icon='item_43059',Type=520,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=12000,AdventureValue=-1,Desc='传说中某个村子的知名领主穿过的披肩类，最好在表现威风时穿戴。',}",
  [43060] = "{id=43060,NameZh='时之蓝披肩★',Icon='item_43060',Type=520,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=12000,AdventureValue=-1,Desc='侠盗时之蓝“工作”时所穿的蓝色披肩。',}",
  [43061] = "{id=43061,NameZh='高等生存斗篷★',Icon='item_43061',Type=520,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=12000,AdventureValue=-1,Desc='经过制作者多方面推敲，该斗篷进一步提了升装备者的生存能力。',}",
  [43062] = "{id=43062,NameZh='坚定魔法斗篷★',Icon='item_43062',Type=520,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=12000,AdventureValue=-1,Desc='就算是外行人都能感受到斗篷上强力的魔法波动!据说穿上它让人遇事果决坚定。',}",
  [43063] = "{id=43063,NameZh='纳户特基格的斗篷★',Icon='item_43063',Type=520,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=12000,AdventureValue=-1,Desc='古老的秘密，暗黑的历史。在纳户特基格的斗篷下，藏匿着那些阳光下见不到的东西。',}",
  [43064] = "{id=43064,NameZh='多芙的斗篷★',Icon='item_43064',Type=520,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=12000,AdventureValue=-1,Desc='并不能把人好好裹住的斗篷。',}",
  [43065] = "{id=43065,NameZh='幻影披风',Icon='item_43065',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='便于忍者们隐藏身份的披风，宽大的衣摆下藏匿着许多忍具。',}",
  [43066] = "{id=43066,NameZh='幻影伯爵披风',Icon='item_43066',Type=520,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='精英忍者们常用于乔装的服饰，看似华丽的披风下暗藏杀机，隐藏着许多威力巨大的忍具。',}",
  [43067] = "{id=43067,NameZh='秘银魔法斗篷',Icon='item_43067',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=12800,AdventureSort=12000,AdventureValue=-1,Desc='有着魔法保护的咒文施展的神秘的斗篷,隐藏着把自己的防御力转移成魔法防御力的能力。',}",
  [43068] = "{id=43068,NameZh='浪子斗篷',Icon='item_43068',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=12800,Desc='老练的射手们最喜欢选用的披风，可以在狙击时提供完美的掩护。“我想——我选它主要是因为够帅！”',Feature=1,}",
  [43070] = "{id=43070,NameZh='骑士披风',Icon='item_43009',Type=520,Quality=2,MaxNum=99,SellPrice=100,Desc='在披上这件披风的那一刻，他向自己的内心宣誓，他将会为了自己所追随的信仰献出一切。',Delete=43070}",
  [43071] = "{id=43071,NameZh='王室骑士披风',Icon='item_43071',Type=520,Quality=3,MaxNum=99,SellPrice=100,Desc='在披上这件披风的那一刻，他向自己的内心宣誓，他将会为了自己所追随的王室献出一切。',Delete=43071}",
  [43072] = "{id=43072,NameZh='皇家骑士披风',Icon='item_43072',Type=520,Quality=4,MaxNum=99,SellPrice=100,Desc='在披上这件披风的那一刻，他向自己的内心宣誓，他将会为了国王献出一切。',Delete=43072}",
  [43076] = "{id=43076,NameZh='战士肩甲',Icon='item_43014',Type=520,Quality=2,MaxNum=99,SellPrice=100,Desc='坚韧而厚重的肩甲，在保护着战士的同时，战士也在保护着他的家园与亲人。',Delete=43076}",
  [43077] = "{id=43077,NameZh='勇士肩甲',Icon='item_43077',Type=520,Quality=3,MaxNum=99,SellPrice=100,Desc='坚韧而厚重的肩甲，在保护着勇士的同时，勇士也在保护着他的信念与爱人。',Delete=43077}",
  [43078] = "{id=43078,NameZh='领袖肩甲',Icon='item_43078',Type=520,Quality=4,MaxNum=99,SellPrice=100,Desc='坚韧而厚重的肩甲，在保护着领袖的同时，领袖也在保护着他的国家与人民。',Delete=43078}",
  [43079] = "{id=43079,NameZh='丝绸流苏',Icon='item_43002',Type=520,Quality=2,MaxNum=99,SellPrice=100,Desc='丝绸的流苏像是流水一般地自肩头滑落，这并不是一般人能够拥有的饰物。',Delete=43079}",
  [43080] = "{id=43080,NameZh='铂金流苏',Icon='item_43080',Type=520,Quality=3,MaxNum=99,SellPrice=100,Desc='铂金的流苏像是流水一般地自肩头滑落，这并不是普通贵族能够拥有的饰物。',Delete=43080}",
  [43081] = "{id=43081,NameZh='钻石流苏',Icon='item_43081',Type=520,Quality=4,MaxNum=99,SellPrice=100,Desc='钻石的流苏像是流水一般地自肩头滑落，只有少数皇家成员才能够拥有这样的饰物。',Delete=43081}",
  [43082] = "{id=43082,NameZh='光芒肩章',Icon='item_43006',Type=520,Quality=2,MaxNum=99,SellPrice=100,Desc='小小的肩章，闪耀着光芒，那是付出努力之后所收获来的赞赏。',Delete=43082}",
  [43083] = "{id=43083,NameZh='荣光肩章',Icon='item_43083',Type=520,Quality=3,MaxNum=99,SellPrice=100,Desc='小小的肩章，闪耀着荣光，那是付出了汗水之后所收获来的敬佩。',Delete=43083}",
  [43084] = "{id=43084,NameZh='荣耀肩章',Icon='item_43084',Type=520,Quality=4,MaxNum=99,SellPrice=100,Desc='小小的肩章，闪耀着荣耀，那是付出了血泪之后所收获来的骄傲。',Delete=43084}",
  [43085] = "{id=43085,NameZh='旧式长袍',Icon='item_43040',Type=520,Quality=2,MaxNum=99,SellPrice=100,Desc='这是一件款式略显老旧的长袍，虽然不算好看，但是能够遮挡风尘。',Delete=43085}",
