  [43087] = "{id=43087,NameZh='经典长袍',Icon='item_43087',Type=520,Quality=4,MaxNum=99,SellPrice=100,Desc='这是一件经典款式的精致长袍，永不过时的设计，在任何场合都不会显得逊色。',Delete=43087}",
  [43088] = "{id=43088,NameZh='简款外套',Icon='item_43058',Type=520,Quality=2,MaxNum=99,SellPrice=100,Desc='在天气变化无常的日子里，你会需要这么一件款式简单的外套。',Delete=43088}",
  [43089] = "{id=43089,NameZh='舒适外套',Icon='item_43089',Type=520,Quality=3,MaxNum=99,SellPrice=100,Desc='在心情变化无常的日子里，你会需要这么一件穿着舒适的外套。',Delete=43089}",
  [43090] = "{id=43090,NameZh='定制外套',Icon='item_43090',Type=520,Quality=4,MaxNum=99,SellPrice=100,Desc='在宾客变化无常的日子里，你会需要这么一件高级定制的外套。',Delete=43090}",
  [43091] = "{id=43091,NameZh='粗制披肩',Icon='item_43028',Type=520,Quality=2,MaxNum=99,SellPrice=100,Desc='它并不是一件多么起眼的披肩，但是她还记得他为她披上时的笑脸。',Delete=43091}",
  [43092] = "{id=43092,NameZh='精工披肩',Icon='item_43092',Type=520,Quality=3,MaxNum=99,SellPrice=100,Desc='她仍然记得他为她披上这件披肩的那一天，那不是一个特别的日子，但她特别高兴。',Delete=43092}",
  [43093] = "{id=43093,NameZh='华丽披肩',Icon='item_43093',Type=520,Quality=4,MaxNum=99,SellPrice=100,Desc='他为她披上这件披肩的那一刻，王国百姓为他们欢呼，她明白，之后她需要肩负很多。',Delete=43093}",
  [43094] = "{id=43094,NameZh='棉麻风衣',Icon='item_43044',Type=520,Quality=2,MaxNum=99,SellPrice=100,Desc='你经常会在王城的街道上看到有人穿着这么一件棉麻风衣。',Delete=43094}",
  [43095] = "{id=43095,NameZh='皮革风衣',Icon='item_43095',Type=520,Quality=3,MaxNum=99,SellPrice=100,Desc='你可能会在王室的聚会上看到有人穿着这么一件皮革风衣。',Delete=43095}",
  [43096] = "{id=43096,NameZh='貂皮风衣',Icon='item_43096',Type=520,Quality=4,MaxNum=99,SellPrice=100,Desc='你大概会在王后的舞会上看到有人穿着这么一件貂皮风衣。',Delete=43096}",
  [43097] = "{id=43097,NameZh='战斗斗篷',Icon='item_43016',Type=520,Quality=2,MaxNum=99,SellPrice=100,Desc='一件设计巧妙的斗篷，能够让你在战斗中更加如鱼得水。',Delete=43097}",
  [43098] = "{id=43098,NameZh='战役斗篷',Icon='item_43098',Type=520,Quality=3,MaxNum=99,SellPrice=100,Desc='一件设计精妙的斗篷，能够让你在战役中能够全身而退。',Delete=43098}",
  [43099] = "{id=43099,NameZh='战争斗篷',Icon='item_43099',Type=520,Quality=4,MaxNum=99,SellPrice=100,Desc='一件设计绝妙的斗篷，能够让你在战争中杀敌制胜，立于不败之地。',Delete=43099}",
  [43100] = "{id=43100,NameZh='神话尘封·荒境斗篷',Icon='item_43100',Type=520,Quality=2,MaxNum=99,SellPrice=100,Desc='在荒境发掘出的斗篷，曾为传说中的洛阳勇士所穿戴。',Level=120,Delete=43100}",
  [43101] = "{id=43101,NameZh='辉煌再临·荒境披风',Icon='item_43101',Type=520,Quality=2,MaxNum=99,SellPrice=100,Desc='沉眠在荒境深处的传奇披风，可以为你增加技能伤害减免。因为新主人的出现，它褪去尘埃，重新焕发耀目的光彩。',Level=120,Delete=43101}",
