  [43105] = "{id=43105,NameZh='辉煌再临·荒境披风',Icon='item_43101',Type=520,Quality=3,MaxNum=99,SellPrice=100,Desc='沉眠在荒境深处的传奇披风，可以为你增加普攻伤害。因为新主人的出现，它褪去尘埃，重新焕发耀目的光彩。',Level=120,Delete=43105}",
  [43107] = "{id=43107,NameZh='冒险新秀披风',Icon='item_43107',Type=520,Quality=2,MaxNum=99,SellPrice=100,Desc='冒险家公会为初出茅庐的冒险者们准备的制式披风，在每一段冒险旅途中，它将为冒险者们遮风挡雨！',Level=20,}",
