  [43501] = "{id=43501,NameZh='乐园团靴子',Icon='item_43501',Type=530,MaxNum=99,SellPrice=20,Desc='发放给乐园团成员的靴子。走很长时间路也不会疲劳，专为冒险设计的鞋子。',Level=1,Feature=4,}",
  [43502] = "{id=43502,NameZh='凉鞋',Icon='item_43502',Type=530,MaxNum=99,SellPrice=588,Desc='轻便舒适的鞋子。不适合长途跋涉和剧烈运动。',Level=42,Feature=4,}",
  [43503] = "{id=43503,NameZh='长靴',Icon='item_43503',Type=530,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=120,AdventureSort=13000,AdventureValue=-1,Desc='保护到脚腕的长靴。',Feature=1,}",
  [43504] = "{id=43504,NameZh='古怪的靴子',Icon='item_43503',Type=530,MaxNum=99,SellPrice=100,Desc='设计古怪的靴子.可以感觉到制作者挑战神的意图，但未达成而改变了作用。',Level=10,Feature=4,}",
  [43505] = "{id=43505,NameZh='时间守护者靴子[1]',Icon='item_43503',Type=530,MaxNum=99,SellPrice=100,Desc='保护到脚腕的长靴。',Level=10,Feature=4,}",
  [43506] = "{id=43506,NameZh='战士长靴',Icon='item_43506',Type=530,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=120,AdventureSort=13000,AdventureValue=-1,Desc='用坚硬的布料做成的长靴。',Feature=1,}",
  [43507] = "{id=43507,NameZh='安全鞋',Icon='item_43507',Type=530,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=80,AdventureSort=13000,AdventureValue=-1,Desc='脚踝上附加一层铁片，对任何撞击都可以保护脚部，轻巧又坚固的靴子。',Feature=1,}",
  [43508] = "{id=43508,NameZh='史雷普尼尔之靴[1]',Icon='item_43503',Type=530,MaxNum=99,SellPrice=100,Desc='以奥丁驰骋战场的战马＂史雷普尼尔＂命名的靴子，由于效果强劲所有人都梦寐以求。',Level=10,Feature=4,}",
  [43509] = "{id=43509,NameZh='兔子拖鞋',Icon='item_43509',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=408,AdventureSort=13000,AdventureValue=-1,Desc='穿上后仿佛觉得自己也和兔子一样喜欢蹦蹦跳跳了。',Feature=1,}",
  [43510] = "{id=43510,NameZh='迪塔乐长靴[1]',Icon='item_43503',Type=530,MaxNum=99,SellPrice=100,Desc='奥丁的儿子迪塔乐，把狼菲力勒杀死时所穿的靴子，里面有菲力勒能承受的强烈的体力和精神力。',Level=50,Feature=4,}",
  [43511] = "{id=43511,NameZh='哥夫内军靴',Icon='item_43511',Type=530,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=3780,AdventureSort=13000,AdventureValue=-1,Desc='哥夫内为了和死对手多芙下赌注，所制作出来的靴子。',Feature=1,}",
  [43512] = "{id=43512,NameZh='天使的降临[1]',Icon='item_43503',Type=530,MaxNum=99,SellPrice=100,Desc='负责超级初学者天使的凉鞋，穿着这双凉鞋跳跃的话，感觉上可以跳到天空似的。',Level=10,Feature=4,}",
  [43513] = "{id=43513,NameZh='巴基力的长靴[1]',Icon='item_43503',Type=530,MaxNum=99,SellPrice=100,Desc='侍奉奥丁的战争姑娘的长靴，其功力与装备者一起成长。',Level=10,Feature=4,}",
  [43514] = "{id=43514,NameZh='恐惧战靴[1]',Icon='item_43503',Type=530,MaxNum=99,SellPrice=100,Desc='会根据使用者脚的大小进行自动调节的神秘长靴。像是活着的生物一般。',Level=10,Feature=4,}",
  [43515] = "{id=43515,NameZh='高级凉鞋',Icon='item_43515',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=241,AdventureSort=13000,AdventureValue=-1,Desc='用金色线和宝石来特殊处理的高级凉鞋，简便而好看。',Feature=1,}",
  [43516] = "{id=43516,NameZh='重靴',Icon='item_43516',Type=530,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=207,AdventureSort=13000,AdventureValue=-1,Desc='用钢铁制作而成，不考虑使用性和舒适感，先考虑到防御力所制作成的靴子。',Feature=1,}",
  [43517] = "{id=43517,NameZh='乐园团短靴[1]',Icon='item_43503',Type=530,MaxNum=99,SellPrice=100,Desc='乐园团必备的短靴，可以很好地保护脚踝。',Level=10,Feature=4,}",
  [43518] = "{id=43518,NameZh='乌鲁兹符文护胫[1]',Icon='item_43503',Type=530,MaxNum=99,SellPrice=100,Desc='提炼乌鲁兹符文石制成的的护胫。',Level=10,Feature=4,}",
  [43519] = "{id=43519,NameZh='玻璃鞋[1]',Icon='item_43503',Type=530,MaxNum=99,SellPrice=100,Desc='用玻璃制作的玻璃鞋，不考虑实用性，只考虑美观性的鞋子。',Level=10,Feature=4,}",
  [43520] = "{id=43520,NameZh='脚链[1]',Icon='item_43520',Type=530,MaxNum=99,SellPrice=100,Desc='为了防止罪犯以及奴隶逃跑用来铐在他们脚上的物品。双脚脚踝上还悬挂着重物，让他们行动不便。',Level=20,Feature=4,}",
  [43521] = "{id=43521,NameZh='傅里哥长靴[1]',Icon='item_43503',Type=530,MaxNum=99,SellPrice=100,Desc='妙勒德的儿子菲依，对大地赋予祝福的靴子，菲依的祝福好像可以让痛苦解放似的。',Level=50,Feature=4,}",
  [43522] = "{id=43522,NameZh='阴影之靴[1]',Icon='item_43503',Type=530,MaxNum=99,SellPrice=100,Desc='用黑暗法术制作的靴子，使装备者融入黑暗之中。制作这个靴子的魔法师让穿上这个靴子的人在碰到危机时自行发动保护佩戴者的效果。',Level=10,Feature=4,}",
  [43523] = "{id=43523,NameZh='轻便鞋',Icon='item_43523',Type=530,MaxNum=99,SellPrice=308,Desc='很方便着装的鞋子，不过没有什么防御力。',Level=22,}",
  [43524] = "{id=43524,NameZh='玻璃靴',Icon='item_43524',Type=530,MaxNum=99,SellPrice=624,Desc='用玻璃制作的玻璃鞋，不考虑实用性，只考虑美观性的鞋子。',Level=52,}",
  [43525] = "{id=43525,NameZh='防水靴',Icon='item_43525',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=375,AdventureSort=13000,AdventureValue=-1,Desc='鞋底进行特殊防水处理，在光滑的冰或潮湿的道路上行走最适合的靴子。',Feature=1,}",
  [43526] = "{id=43526,NameZh='黑皮靴[1]',Icon='item_43526',Type=530,MaxNum=99,SellPrice=100,Desc='用薄皮制作的坚固靴子。只要穿上就想奔跑起来。',Level=40,}",
  [43527] = "{id=43527,NameZh='抗魔靴',Icon='item_43527',Type=530,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=121,AdventureSort=13000,AdventureValue=-1,Desc='前方像刀子一样尖锐突起的皮鞋。',Feature=1,}",
  [43528] = "{id=43528,NameZh='狙击手的长靴[1]',Icon='item_43528',Type=530,MaxNum=99,SellPrice=100,Desc='虽与其他长靴看起来没有什么不一样，但是是神射手专用的。',Level=70,}",
  [43529] = "{id=43529,NameZh='奔跑长靴',Icon='item_43529',Type=530,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4620,AdventureSort=13000,AdventureValue=-1,Desc='让人可以快速奔跑的轻便长靴，用绳子捆绑，牢牢地固定在腿上。',Feature=1,}",
  [43530] = "{id=43530,NameZh='鹿皮靴',Icon='item_43530',Type=530,MaxNum=99,SellPrice=448,Desc='在森林中穿行的猎人们喜欢穿的靴子。',Level=32,}",
  [43531] = "{id=43531,NameZh='冒险家长靴',Icon='item_43531',Type=530,MaxNum=99,SellPrice=744,Desc='专为冒险者制作的长靴。',Level=62,}",
  [43532] = "{id=43532,NameZh='军用便靴',Icon='item_43532',Type=530,MaxNum=99,SellPrice=864,Desc='经历了多次战争不断修改设计并最终定型。重视实战效果的靴子。',Level=72,}",
  [43533] = "{id=43533,NameZh='制式便靴',Icon='item_43533',Type=530,MaxNum=99,SellPrice=984,Desc='专门为佣兵定制的多用途靴子。适应各种复杂环境。',Level=82,}",
  [43534] = "{id=43534,NameZh='附魔战靴',Icon='item_43534',Type=530,MaxNum=99,SellPrice=1104,Desc='靴子上的魔法符文储存有增强佩戴者属性的次级魔法。因为是魔法学徒的作品所以相对一般魔法道具要廉价得多。',Level=92,}",
  [43535] = "{id=43535,NameZh='坚定战靴',Icon='item_43535',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=600,AdventureSort=13000,AdventureValue=-1,Desc='简约和有棱角的设计，让靴子的使用者相信自己的意志似乎变得更坚定了。',Feature=1,}",
  [43536] = "{id=43536,NameZh='迪斯凯特的便靴',Icon='item_43536',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=75,AdventureSort=13000,AdventureValue=-1,Desc='据说是依照贤者迪斯凯特佣兵时代的穿着仿制的。虽然是仿制品，靴子的做工却意外的精良。',Feature=1,}",
  [43537] = "{id=43537,NameZh='布袋熊长靴',Icon='item_43537',Type=530,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=120,AdventureSort=13000,AdventureValue=-1,Desc='魔物布袋熊的皮毛经过特殊手段制成的长靴。注意!是布袋熊不是拉链熊！',Feature=1,}",
  [43538] = "{id=43538,NameZh='魔磨长靴',Icon='item_43538',Type=530,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=120,AdventureSort=13000,AdventureValue=-1,Desc='魔磨石粉末和特殊的凝胶混合成形的长靴。坚固却不失轻便。',Feature=1,}",
  [43539] = "{id=43539,NameZh='圣符长靴',Icon='item_43539',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=509,AdventureSort=13000,AdventureValue=-1,Desc='研究古代符文的魔法师们在近代试制的第一批镶嵌了魔法符文的靴子。',Feature=1,}",
  [43540] = "{id=43540,NameZh='历战长靴',Icon='item_43540',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=736,AdventureSort=13000,AdventureValue=-1,Desc='即使经历过残酷战争也还完好的耐用的靴子。',Feature=1,}",
  [43541] = "{id=43541,NameZh='多芙的战斗靴',Icon='item_43541',Type=530,Quality=4,MaxNum=99,SellPrice=100,Desc='锻造师多芙使用的靴子。非常的坚固。',Feature=1,}",
  [43542] = "{id=43542,NameZh='迪斯凯特的雨靴',Icon='item_43542',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=150,AdventureSort=13000,AdventureValue=-1,Desc='普通雨靴经过大贤者迪斯凯特加持也变成了强力的魔法装备。',Feature=1,}",
  [43543] = "{id=43543,NameZh='光明圣徒战靴',Icon='item_43543',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='圣歌教会的锻造神工匠，人称“光明圣徒”的安德鲁冕下为那些英勇善战的教会勇士所设计的一套制式服装，防御力极其优秀。起初这套制式服装没有名字，但其优秀的防御力让所有勇士们都爱不释手，他们用锻造这安德鲁的称号来为这制式服装命名。这就是“光明圣徒”套装。这件为“光明圣徒”套装的战靴部分。受到光明圣徒的祝福，安全精炼时消耗的装备件数减少一半。',Feature=1,}",
  [43544] = "{id=43544,NameZh='圣符重靴',Icon='item_43544',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=840,AdventureSort=13000,AdventureValue=-1,Desc='泛着古铜色的光芒，雕刻着神圣魔法阵法的靴子，拥有极大的防御能力。',Feature=1,}",
  [43545] = "{id=43545,NameZh='水晶靴',Icon='item_43524',Type=530,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=3200,AdventureSort=13000,AdventureValue=-1,Desc='使用稀有水晶精炼而成的靴子，精致而神秘，穿上能让人气质非凡。',Feature=1,}",
  [43546] = "{id=43546,NameZh='高等布袋熊长靴',Icon='item_43546',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=840,AdventureSort=13000,AdventureValue=-1,Desc='模仿布袋熊脚制成的靴子，看似可爱，实则可怕，可以让穿着者拥有布袋熊的移动速度。',Feature=1,}",
  [43547] = "{id=43547,NameZh='变色龙长靴',Icon='item_43547',Type=530,MaxNum=99,SellPrice=100,}",
  [43548] = "{id=43548,NameZh='骷髅战靴',Icon='item_43548',Type=530,MaxNum=99,SellPrice=100,}",
  [43549] = "{id=43549,NameZh='高级乐园团长靴',Icon='item_43501',Type=530,MaxNum=99,SellPrice=100,Level=1,NoStorage=5,}",
  [43550] = "{id=43550,NameZh='洗礼战靴',Icon='item_43534',Type=530,MaxNum=99,SellPrice=1164,Desc='经过高级牧师洗礼祝福的战靴，虽然看上去笨重，实际上非常轻盈，装备者能感受到来自天神的祝福。',Level=97,}",
  [43551] = "{id=43551,NameZh='援护者皮靴',Icon='item_43551',Type=530,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=280,AdventureSort=13000,AdventureValue=-1,Desc='经过高级牧师洗礼祝福的战靴，虽然看上去笨重，实际上非常轻盈，装备者能感受到来自天神的祝福。',Feature=1,}",
  [43552] = "{id=43552,NameZh='审判之靴',Icon='item_43552',Type=530,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=500,AdventureSort=13000,AdventureValue=-1,Desc='为了追捕恶魔，审判者必须前往许多地方，有时候甚至是异世界，所以这双靴子上拥有特殊魔法的祝福。',Feature=1,}",
  [43553] = "{id=43553,NameZh='白翼之靴',Icon='item_43553',Type=530,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=500,AdventureSort=13000,AdventureValue=-1,Desc='参照传说中赫尔墨斯的凉鞋设计而成的靴子，带有一对小翅膀，能让穿戴者步伐变得特别轻快。“别做梦了，要是穿着带翅膀的靴子就能随便飞起来的话，那还要飞空艇干嘛？”——某个飞空艇船长',Feature=1,}",
  [43554] = "{id=43554,NameZh='亡灵之靴',Icon='item_43533',Type=530,MaxNum=99,SellPrice=2100,Desc='亡魂没有脚？谁说的？它们脚上的亡魂之靴就是最好的证据！',Level=95,}",
  [43555] = "{id=43555,NameZh='法力风暴之靴',Icon='item_43555',Type=530,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=13000,AdventureValue=-1,Desc='名字很帅，但事实上，这只是那些吉芬魔法师的自我陶醉，你以为穿上它就能掀起法力风暴？雷藏穿狼外婆的拖鞋都比你强。',Feature=1,}",
  [43556] = "{id=43556,NameZh='狼外婆的拖鞋',Icon='item_43556',Type=530,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=13000,AdventureValue=-1,Desc='狼外婆也很想穿高跟鞋，但是它脚趾甲太长，只能穿这种拖鞋了。',Feature=1,}",
  [43557] = "{id=43557,NameZh='舞蹈鞋',Icon='item_43557',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=13000,AdventureValue=-1,Desc='嗒嗒嗒，她旋转又踮起脚尖，露出苍白的微笑。跳舞的人，注定一辈子跳舞。',Feature=1,}",
  [43558] = "{id=43558,NameZh='攀登者',Icon='item_43558',Type=530,MaxNum=99,SellPrice=100,Desc='我要一步一步往上爬，总有一天，我会到达天地树的顶点。那里会有怎样的风景呢？',}",
  [43559] = "{id=43559,NameZh='古怪的鞋子',Icon='item_43559',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=2880,AdventureSort=13000,AdventureValue=-1,Desc='如果不看紧这双鞋子，它会在你的眼皮底下溜走。',}",
  [43560] = "{id=43560,NameZh='初心者鞋子',Icon='item_43560',Type=530,Quality=2,MaxNum=99,SellPrice=100,Desc='乐园团为下定决心的初心者们特意准备的鞋子，脚下生风哦。',Feature=1,}",
  [43561] = "{id=43561,NameZh='恐惧战靴',Icon='item_43561',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=4000,AdventureSort=13000,AdventureValue=-1,Desc='可自动调整穿者大小的神秘长靴, 就好像有生命力一样。',}",
  [43562] = "{id=43562,NameZh='喵族优雅鞋子',Icon='item_43562',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=2400,Desc='鞋底柔软得让人难以置信，在各种地形上都能悄无声息地行走。',}",
  [43563] = "{id=43563,NameZh='巡守队靴子',Icon='item_43501',Type=530,MaxNum=99,SellPrice=20,Desc='发放给巡守队成员的靴子。走很长时间路也不会疲劳，专为冒险设计的鞋子。',Level=1,Feature=4,}",
  [43571] = "{id=43571,NameZh='脚链',Icon='item_43571',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=13000,AdventureValue=-1,Desc='为了防止罪犯以及奴隶逃跑用来铐在他们脚上的物品。双脚脚踝上还悬挂着重物,让他们行动不便。',}",
  [43572] = "{id=43572,NameZh='英灵起点·鞋子',Icon='item_43572',Type=530,Quality=2,MaxNum=99,SellPrice=100,Desc='克里图拉新生领到的初心衣物，致敬英灵而铸上蓝金涂装。在学园舞会上小心踩滑哦！',NoStorage=5,}",
  [43573] = "{id=43573,NameZh='英灵信标·鞋子[1]',Icon='item_43573',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='这双鞋子是指引女武神降临、迎接英灵的道标。阵亡的勇士穿着它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,}",
  [43574] = "{id=43574,NameZh='英灵羽证·鞋子',Icon='item_43574',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='英灵的证明。潜入学院的女武神在这双鞋中注入了奥丁领域的魔力。鞋跟长出了羽翼，轻飘飘地、适合毕业季的典礼上穿。',NoStorage=5,}",
  [43575] = "{id=43575,NameZh='小猫的脚踝铃铛',Icon='item_43575',Type=530,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,Desc='适合系在脚踝的铃铛，专门为了不喜欢穿鞋子的光脚一族设计。',}",
  [43576] = "{id=43576,NameZh='舞蹈鞋★',Icon='item_43576',Type=530,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=13000,AdventureValue=-1,Desc='嗒嗒嗒，她旋转又踮起脚尖，露出苍白的微笑。跳舞的人，注定一辈子跳舞。',}",
  [43577] = "{id=43577,NameZh='援护者皮靴★',Icon='item_43577',Type=530,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=13000,AdventureValue=-1,Desc='经过高级牧师洗礼祝福的战靴，虽然看上去笨重，实际上非常轻盈，装备者能感受到来自天神的祝福。',}",
  [43578] = "{id=43578,NameZh='审判之靴★',Icon='item_43578',Type=530,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=13000,AdventureValue=-1,Desc='为了追捕恶魔，审判者必须前往许多地方，有时候甚至是异世界，所以这双靴子上拥有特殊魔法的祝福。',}",
  [43579] = "{id=43579,NameZh='狼外婆的拖鞋★',Icon='item_43579',Type=530,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=13000,AdventureValue=-1,Desc='狼外婆也很想穿高跟鞋，但是它脚趾甲太长，只能穿这种拖鞋了。',}",
  [43580] = "{id=43580,NameZh='圣符重靴★',Icon='item_43580',Type=530,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=13000,AdventureValue=-1,Desc='泛着古铜色的光芒，雕刻着神圣魔法阵法的靴子，拥有极大的防御能力。',}",
  [43581] = "{id=43581,NameZh='水晶靴★',Icon='item_43581',Type=530,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=13000,AdventureValue=-1,Desc='使用稀有水晶精炼而成的靴子，精致而神秘，穿上能让人气质非凡。',}",
  [43582] = "{id=43582,NameZh='高等布袋熊长靴★',Icon='item_43582',Type=530,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=13000,AdventureValue=-1,Desc='模仿布袋熊脚制成的靴子，看似可爱，实则可怕，可以让穿着者拥有布袋熊的移动速度。',}",
  [43583] = "{id=43583,NameZh='历战长靴★',Icon='item_43583',Type=530,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=13000,AdventureValue=-1,Desc='即使经历过残酷战争也还完好的耐用的靴子。',}",
  [43584] = "{id=43584,NameZh='魔磨长靴★',Icon='item_43584',Type=530,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=13000,AdventureValue=-1,Desc='魔磨石粉末和特殊的凝胶混合成形的长靴。坚固却不失轻便。',}",
  [43585] = "{id=43585,NameZh='高级凉鞋★',Icon='item_43585',Type=530,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=13000,AdventureValue=-1,Desc='用金色线和宝石来特殊处理的高级凉鞋，简便而好看。 ',}",
  [43586] = "{id=43586,NameZh='生命树之靴',Icon='item_43586',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=12800,AdventureSort=13000,AdventureValue=-1,Desc='使用生命树枝编织而成的鞋子,不仅舒适全身又感到充满活力。',}",
  [43587] = "{id=43587,NameZh='防水靴★',Icon='item_43587',Type=530,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=13000,AdventureValue=-1,Desc='鞋底进行特殊防水处理，在光滑的冰或潮湿的道路上行走最适合的靴子。',}",
  [43588] = "{id=43588,NameZh='牧童马刺靴',Icon='item_43588',Type=530,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=30000,Desc='要不是这场战争，他可以在家悠闲的牧牛，与邻家的少女并肩躺在草地上，哼着歌度过无忧无虑的一天——“快了，等打完这一仗，就能回家了！”',Feature=1,}",
  [43589] = "{id=43589,NameZh='狙击手的长靴',Icon='item_43589',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='由修发兹共和国制式军靴改造成的鞋子，结实耐磨损，保障枪手在各种恶劣的地形都能高效战斗。',Feature=1,}",
  [43590] = "{id=43590,NameZh='游猎者之靴',Icon='item_43590',Type=530,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,Desc='使用雷根贝勒公司最新技术打造的高科技战靴，可以吸收冲击力、增强弹跳力，极大增强枪手们战斗的机动性。',Feature=1,}",
  [43591] = "{id=43591,NameZh='敏捷补充装置',Icon='item_43591',Type=530,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='鞋底安装了可以储存魔力的魔法装置，在危急时刻可以爆发魔力让使用者健步如飞，脱离危险。',}",
  [43592] = "{id=43592,NameZh='锻钢战靴',Icon='item_43516',Type=530,Quality=2,MaxNum=99,SellPrice=100,Desc='锻钢打造的战靴，虽然沉重，但防护性上佳。',Delete=43592}",
  [43593] = "{id=43593,NameZh='精炼战靴',Icon='item_43593',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='将锻钢反复精炼去除杂质，在保证了防护性的前提下大幅减轻了重量，是雷根弗莱格家族上流工艺的展现。',Delete=43593}",
  [43594] = "{id=43594,NameZh='超能机甲战靴',Icon='item_43594',Type=530,Quality=4,MaxNum=99,SellPrice=100,Desc='使用雷根弗莱格家族秘藏的超能机甲作为动力源打造的战靴，是米德加尔特无数匠人梦寐以求的超前工艺制品。',Delete=43594}",
  [43595] = "{id=43595,NameZh='羽毛鞋',Icon='item_43529',Type=530,Quality=2,MaxNum=99,SellPrice=100,Desc='装饰着羽毛的布靴，主要优点是轻便。',Delete=43595}",
  [43596] = "{id=43596,NameZh='轻灵之鞋',Icon='item_43596',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='穿上后感觉自己身轻如燕。奈利乌斯家族代代家主均为女性，这双鞋也是为她们量身打造的。',Delete=43596}",
  [43597] = "{id=43597,NameZh='天风飞羽',Icon='item_43597',Type=530,Quality=4,MaxNum=99,SellPrice=100,Desc='穿上这双鞋，就如同乘坐洁白的羽毛船在蔚蓝的天空中飞翔。',Delete=43597}",
  [43598] = "{id=43598,NameZh='龙皮靴',Icon='item_43538',Type=530,Quality=2,MaxNum=99,SellPrice=100,Desc='龙皮制成的靴子，坚硬无比。',Delete=43598}",
  [43599] = "{id=43599,NameZh='斩龙者战靴',Icon='item_43599',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='使用巨龙的头骨制成的靴子，是斩龙者荣耀的象征。',Delete=43599}",
  [43600] = "{id=43600,NameZh='卢恩的纪念',Icon='item_43600',Type=530,Quality=4,MaxNum=99,SellPrice=100,Desc='雕画着卢恩符文的龙骨靴，传说当年特里斯坦一世开国时曾将这双靴子赠送给最强的勇士，并代代流传。',Delete=43600}",
  [43601] = "{id=43601,NameZh='勇武战靴',Icon='item_43552',Type=530,Quality=2,MaxNum=99,SellPrice=100,Desc='对勇武者的尊崇，从上古时代便已经开始，这双战靴彰显了武者的光辉。',Delete=43601}",
  [43602] = "{id=43602,NameZh='统治者战靴',Icon='item_43602',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='精美的花纹展现出与平常士兵不同的等级，穿着它，其他人自然会高看一眼。',Delete=43602}",
  [43603] = "{id=43603,NameZh='霸主战靴',Icon='item_43603',Type=530,Quality=4,MaxNum=99,SellPrice=100,Desc='一代霸主才能驾驭的华丽战靴，每条纹路都是功勋的象征。',Delete=43603}",
  [43604] = "{id=43604,NameZh='传承之靴',Icon='item_43551',Type=530,Quality=2,MaxNum=99,SellPrice=100,Desc='韦格纳家族相信，勤勤恳恳的传承传统，就能维系贵族的太阳永不落幕。',Delete=43604}",
  [43605] = "{id=43605,NameZh='荣耀战靴',Icon='item_43605',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='历史的长河中，刻满了战碑与荣耀。',Delete=43605}",
  [43606] = "{id=43606,NameZh='特里斯坦的恩典',Icon='item_43606',Type=530,Quality=4,MaxNum=99,SellPrice=100,Desc='韦格纳家族相信，这片土地正是特里斯坦赐予韦格纳家族的恩典，即使今日风光不再，也依然能保持贵族的品格。',Delete=43606}",
  [43607] = "{id=43607,NameZh='天秤靴子',Icon='item_43559',Type=530,Quality=2,MaxNum=99,SellPrice=100,Desc='绣着天平花纹的布艺短靴，简洁轻便，是奈利乌斯家族平民常见的服饰。',Delete=43607}",
  [43608] = "{id=43608,NameZh='平衡之理靴子',Icon='item_43608',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='维系天平平衡的，并非两段承托之物的重量，而是执掌者心中的平衡之理。',Delete=43608}",
  [43609] = "{id=43609,NameZh='公正的审判',Icon='item_43609',Type=530,Quality=4,MaxNum=99,SellPrice=100,Desc='奈利乌斯的执掌者赐予人们公正的审判，这种公正之力化为家族的威信，寄托于造物之上。',Delete=43609}",
  [43610] = "{id=43610,NameZh='宗族皮靴',Icon='item_43577',Type=530,Quality=2,MaxNum=99,SellPrice=100,Desc='王室赠予宗族的皮靴，是家族的得力干将才能享有的。',Delete=43610}",
  [43611] = "{id=43611,NameZh='继承者皮靴',Icon='item_43611',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='家族继承者的皮靴，寄托着宗族对持有者的未来期待，也是家族地位的象征。',Delete=43611}",
  [43612] = "{id=43612,NameZh='血脉熔炉',Icon='item_43612',Type=530,Quality=4,MaxNum=99,SellPrice=100,Desc='血脉是最深刻的熔炉，人一生的命运都镌刻在血脉之上，而王室的血脉，则是后来者的光荣。',Delete=43612}",
  [43613] = "{id=43613,NameZh='彗星短靴',Icon='item_43586',Type=530,Quality=2,MaxNum=99,SellPrice=100,Desc='彗星坠落的夜晚，充盈的祝福能量让奈利乌斯家的巧匠们轻松制造出大量短靴，他们便以彗星为它们命名。',Delete=43613}",
  [43614] = "{id=43614,NameZh='启明星短靴',Icon='item_43614',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='在启明星升起的那一刻，奈利乌斯家族的鞋匠们恰巧赶制出这双短靴。',Delete=43614}",
  [43615] = "{id=43615,NameZh='永恒双子星',Icon='item_43615',Type=530,Quality=4,MaxNum=99,SellPrice=100,Desc='双子星的祝福，赐予奈利乌斯家族永恒的力量源泉。',Delete=43615}",
  [43616] = "{id=43616,NameZh='朴素短靴',Icon='item_43503',Type=530,Quality=2,MaxNum=99,SellPrice=100,Desc='一双规整的短靴，穿上去还算舒适。',Delete=43616}",
  [43617] = "{id=43617,NameZh='守序短靴',Icon='item_43617',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='雷根弗莱格家族笃信，只有遵循规则，才能实现家族永恒的繁荣昌盛，即使在打造短靴时，也力求严丝合缝。',Delete=43617}",
  [43618] = "{id=43618,NameZh='秩序守护者',Icon='item_43618',Type=530,Quality=4,MaxNum=99,SellPrice=100,Desc='守护米德加尔特的秩序，守护卢恩王国的秩序，七王室的规则不可更改，唯有守序者方能维系一族的宿命。',Delete=43618}",
  [43619] = "{id=43619,NameZh='深海战靴',Icon='item_43587',Type=530,Quality=2,MaxNum=99,SellPrice=100,Desc='深海之中，除了幽暗，还有更深的幽暗……',Delete=43619}",
  [43620] = "{id=43620,NameZh='远航者战靴',Icon='item_43620',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='巴尔特家族的先祖曾经穿着这样的战靴远赴修发兹共和国，带来了巴尔特家族的第一桶金。',Delete=43620}",
  [43621] = "{id=43621,NameZh='诸海之皇',Icon='item_43621',Type=530,Quality=4,MaxNum=99,SellPrice=100,Desc='掌握着巨额财富的海洋之王，巴尔特家族的航线遍布诸海，这双战靴正是海洋上的恶魔商人的象征。',Delete=43621}",
  [43622] = "{id=43622,NameZh='神话尘封·荒境腿甲',Icon='item_43622',Type=530,Quality=2,MaxNum=99,SellPrice=100,Desc='在荒境发掘出的腿甲，曾为传说中的洛阳勇士所穿戴。',Level=120,Delete=43622}",
  [43623] = "{id=43623,NameZh='辉煌再临·荒境战靴',Icon='item_43623',Type=530,Quality=2,MaxNum=99,SellPrice=100,Desc='沉眠在荒境深处的传奇战靴，可以为你增加物理、魔法伤害。因为新主人的出现，它褪去尘埃，重新焕发耀目的光彩。',Level=120,Delete=43623}",
  [43624] = "{id=43624,NameZh='辉煌再临·荒境战靴',Icon='item_43623',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='沉眠在荒境深处的传奇战靴，可以为你增加物理穿刺。因为新主人的出现，它褪去尘埃，重新焕发耀目的光彩。',Level=120,Delete=43624}",
  [43625] = "{id=43625,NameZh='辉煌再临·荒境战靴',Icon='item_43623',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='沉眠在荒境深处的传奇战靴，可以为你增加魔法穿刺。因为新主人的出现，它褪去尘埃，重新焕发耀目的光彩。',Level=120,Delete=43625}",
  [43626] = "{id=43626,NameZh='辉煌再临·荒境战靴',Icon='item_43623',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='沉眠在荒境深处的传奇战靴，可以为你增加物理穿刺。因为新主人的出现，它褪去尘埃，重新焕发耀目的光彩。',Level=120,Delete=43626}",
  [43627] = "{id=43627,NameZh='辉煌再临·荒境战靴',Icon='item_43623',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='沉眠在荒境深处的传奇战靴，可以为你增加生命上限。因为新主人的出现，它褪去尘埃，重新焕发耀目的光彩。',Level=120,Delete=43627}",
  [43629] = "{id=43629,NameZh='冒险新秀皮靴',Icon='item_43629',Type=530,Quality=2,MaxNum=99,SellPrice=100,Desc='冒险家公会为初出茅庐的冒险者们准备的制式皮靴，轻便耐用，穿上它，踏上崭新的冒险旅途吧！',Level=20,}",
  [43630] = "{id=43630,NameZh='冒险精英皮靴',Icon='item_43630',Type=530,Quality=2,MaxNum=99,SellPrice=100,Desc='冒险家公会为娴熟的精英冒险家准备的饰品，轻便耐用，可以为你增加物理攻击。穿上它，追寻精彩的冒险旅途吧！',Level=40,}",
