  [44060] = "{id=44060,NameZh='黑猫胸针★',Icon='item_44060',Type=540,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=14000,AdventureValue=-1,Desc='喵喵喵！鱼唇的人类，戴上这个胸针，你就是我的铲屎官啦！',}",
  [44061] = "{id=44061,NameZh='怀表★',Icon='item_44061',Type=540,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=14000,AdventureValue=-1,Desc='带有表链的银色怀表。在里希塔乐的贝勒区，这是贵族的象征。',}",
  [44062] = "{id=44062,NameZh='火忍西怒毕的腰带★',Icon='item_44062',Type=540,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=14000,AdventureValue=-1,Desc='著名的忍者所装备过的腰带, 高级的图样带有神秘的光芒,似乎带着魔力。',}",
  [44063] = "{id=44063,NameZh='潜能戒指★',Icon='item_44063',Type=540,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=14000,AdventureValue=-1,Desc='可激发使用者潜能的魔法戒指,同时具有寻找敌人弱点的能力。',}",
  [44064] = "{id=44064,NameZh='生存戒指',Icon='item_44064',Type=540,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=4000,AdventureSort=14000,AdventureValue=-1,Desc='为了提升冒险者在旅途中的生存几率，冒险家协会特地打造了这枚戒指。',}",
  [44065] = "{id=44065,NameZh='护符草项链',Icon='item_44065',Type=540,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=6400,Desc='使用一千棵草中才能找到一棵的护符草制成的项链，能给人带来意想不到的好运。',Delete=44065}",
  [44066] = "{id=44066,NameZh='四叶草项链',Icon='item_44066',Type=540,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,Desc='究竟是四叶草带来好运，还是拥有好运气才能找到四叶草呢？',Delete=44066}",
  [44067] = "{id=44067,NameZh='鲔鱼护符',Icon='item_44067',Type=540,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=8800,Desc='带着大海气息的护符，不建议在吃饭时佩戴。',Delete=44067}",
  [44068] = "{id=44068,NameZh='新鲜鲔鱼护符',Icon='item_44068',Type=540,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=28800,Desc='活蹦乱跳，还带着大海气息的护符，戴着它就永远不会失去梦想。',Delete=44068}",
  [44069] = "{id=44069,NameZh='不忘初心护符',Icon='item_44069',Type=540,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,Desc='人没有梦想，和鲔鱼有什么分别！',Delete=44069}",
  [44076] = "{id=44076,NameZh='辟邪香包',Icon='item_44076',Type=540,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=14000,AdventureValue=-1,Desc='带辟邪香包就得到好运。',}",
  [44077] = "{id=44077,NameZh='血迹铁球',Icon='item_44077',Type=540,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=14000,AdventureValue=-1,Desc='古时候对凶恶的罪人以控制他的行动,所做的脚镣铁球,不过那些罪人据说把那些铁球当做自己的武器使用。',}",
  [44078] = "{id=44078,NameZh='英灵起点·指环',Icon='item_44078',Type=540,Quality=2,MaxNum=99,SellPrice=100,Desc='它可以让你在教官面前超水平发挥，成功逃课。但一旦被抓到，可会被算成是作弊，罚去跑圈的哦！',NoStorage=5,}",
  [44079] = "{id=44079,NameZh='英灵信标·指环[1]',Icon='item_44079',Type=540,Quality=3,MaxNum=99,SellPrice=100,Desc='这枚指环是是指引女武神降临、迎接英灵的道标。阵亡的勇士佩戴它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,}",
  [44080] = "{id=44080,NameZh='英灵羽证·指环',Icon='item_44080',Type=540,Quality=3,MaxNum=99,SellPrice=100,Desc='英灵的证明。潜入学院的女武神在这双鞋中注入了奥丁领域的魔力。宝石中生出羽毛，不用担心它会飞走，因为戒指已经迷上了英雄的手指。',NoStorage=5,}",
  [44081] = "{id=44081,NameZh='英灵起点·项链',Icon='item_44081',Type=540,Quality=2,MaxNum=99,SellPrice=100,Desc='克里图拉新生领到的初心首饰，致敬英灵而铸上蓝金涂装。设计者是草药园导师伊兰。昏暗时它将闪烁出魔力的荧光，所以停电时不要和贵重品放一个包里哦。',NoStorage=5,}",
  [44082] = "{id=44082,NameZh='英灵信标·项链[1]',Icon='item_44082',Type=540,Quality=3,MaxNum=99,SellPrice=100,Desc='这串项链指引女武神降临、迎接英灵的道标。阵亡的勇士抱它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,}",
  [44083] = "{id=44083,NameZh='英灵羽证·项链',Icon='item_44083',Type=540,Quality=3,MaxNum=99,SellPrice=100,Desc='英灵的证明。潜入学院的女武神在项链中注入了奥丁领域的魔力。项链的宝石长出羽翼，不用担心它会飞走，因为它已经迷上了英雄的肩膀。',NoStorage=5,}",
  [44084] = "{id=44084,NameZh='忍者的入门手册',Icon='item_44084',Type=540,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='记载了忍法基本理论的书册，新人忍者的入门读物。',Delete=44084}",
  [44085] = "{id=44085,NameZh='忍者的进阶指南',Icon='item_44085',Type=540,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='古代流传下来的书卷，上面记载了许多高级忍法，是成为顶尖忍者的必修课。',Delete=44085}",
  [44086] = "{id=44086,NameZh='水滴胸针',Icon='item_44086',Type=540,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=30000,Desc='小巧的水滴形胸针，上面点缀着海蓝色的宝石，应该是少女送给从军爱人的信物。“哦对了，它是我的战利品，来自我的第七个猎物……”',Feature=1,}",
  [44087] = "{id=44087,NameZh='狙击手勋章',Icon='item_44087',Type=540,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='共和国颁发给精英狙击手的勋章，只有在战争中作出巨大贡献的狙击手才能享此殊荣。',Feature=1,Delete=44087}",
  [44088] = "{id=44088,NameZh='猎杀之证',Icon='item_44088',Type=540,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,Desc='这枚勋章的存在是一个传说，只有狙杀一千名敌人才有资格获得它，那些佩戴它的枪手，是游曳在战场上的死神。“那枚子弹离我的心脏只差一毫米，但这枚勋章帮我挡住了它！“',Feature=1,Delete=44088}",
  [44089] = "{id=44089,NameZh='诅咒之手',Icon='item_44089',Type=540,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='传闻是某位黑魔法师遗骨的一部分，常年使用邪恶魔法使他的身体充满各种诅咒，即使是一次触碰也会使人厄运缠身。',}",
  [44090] = "{id=44090,NameZh='回忆之戒',Icon='item_44003',Type=540,Quality=2,MaxNum=99,SellPrice=100,Desc='如果可以，希望能够将回忆刻在这枚戒指里，传达给你。',Delete=44090}",
  [44091] = "{id=44091,NameZh='光影之戒',Icon='item_44091',Type=540,Quality=3,MaxNum=99,SellPrice=100,Desc='如果可以，希望能够将光影印在这枚戒指里，传递给你。',Delete=44091}",
  [44092] = "{id=44092,NameZh='辉煌之戒',Icon='item_44092',Type=540,Quality=4,MaxNum=99,SellPrice=100,Desc='如果可以，希望能够将辉煌存在这枚戒指里，传承下去。',Delete=44092}",
  [44093] = "{id=44093,NameZh='信念项链',Icon='item_44019',Type=540,Quality=2,MaxNum=99,SellPrice=100,Desc='你是否能够感受这条项链主人的坚实信仰？',Delete=44093}",
  [44094] = "{id=44094,NameZh='誓约项链',Icon='item_44094',Type=540,Quality=3,MaxNum=99,SellPrice=100,Desc='你是否能够察觉这条项链主人曾经立下的誓约？',Delete=44094}",
  [44095] = "{id=44095,NameZh='殉道者项链',Icon='item_44095',Type=540,Quality=4,MaxNum=99,SellPrice=100,Desc='你是否能够发现这条项链所承载的殉道者的意志？',Delete=44095}",
  [44096] = "{id=44096,NameZh='珍珠戒指',Icon='item_44046',Type=540,Quality=2,MaxNum=99,SellPrice=100,Desc='一枚简简单单的珍珠戒指，并没有太多特殊含义，不过足够美丽。',Delete=44096}",
  [44097] = "{id=44097,NameZh='祝福手链',Icon='item_44097',Type=540,Quality=3,MaxNum=99,SellPrice=100,Desc='一条蕴涵祝福的珍珠手链，承载着前人的美好心愿，希望佩戴之人能够幸福。',Delete=44097}",
