  [44102] = "{id=44102,NameZh='淑女手套',Icon='item_44005',Type=540,Quality=2,MaxNum=99,SellPrice=100,Desc='一位淑女表达自己内敛情绪的方式，可能就是佩戴这样一副白手套。',Delete=44102}",
  [44103] = "{id=44103,NameZh='贵妇手套',Icon='item_44103',Type=540,Quality=3,MaxNum=99,SellPrice=100,Desc='一位贵妇表达自己高贵气质的方式，可能就是佩戴这样一副丝质手套。',Delete=44103}",
