  [44105] = "{id=44105,NameZh='纯情胸针',Icon='item_44086',Type=540,Quality=2,MaxNum=99,SellPrice=100,Desc='只敢在夜里偷偷地想念，握着手中的纯情胸针，说出那个熟悉的名字。',Delete=44105}",
