  [44112] = "{id=44112,NameZh='萤石纽扣',Icon='item_44112',Type=540,Quality=3,MaxNum=99,SellPrice=100,Desc='这是一枚由匠人所制的萤石纽扣，小巧而精致，实用性高。',Delete=44112}",
  [44113] = "{id=44113,NameZh='绿宝石纽扣',Icon='item_44113',Type=540,Quality=4,MaxNum=99,SellPrice=100,Desc='这是一枚由大师所制的绿宝石纽扣，造型优美，精致典雅，巧夺天工。',Delete=44113}",
  [44114] = "{id=44114,NameZh='火之吊坠',Icon='item_44027',Type=540,Quality=2,MaxNum=99,SellPrice=100,Desc='力哈尔特家族冶炼钢铁使用的高温火焰打造出的吊坠。',Delete=44114}",
  [44115] = "{id=44115,NameZh='灼炎之精',Icon='item_44115',Type=540,Quality=3,MaxNum=99,SellPrice=100,Desc='熔炼机甲的三千度高温凝结出的晶核，制造佩饰后能够迸发出强大的能量。',Delete=44115}",
  [44116] = "{id=44116,NameZh='熔火之心',Icon='item_44116',Type=540,Quality=4,MaxNum=99,SellPrice=100,Desc='传说中曾有机甲师耗费七天七夜，最终跃入熔炉中，以自身躯体为燃料，打造出流传千古的机甲。',Delete=44116}",
  [44117] = "{id=44117,NameZh='合金项链',Icon='item_44081',Type=540,Quality=2,MaxNum=99,SellPrice=100,Desc='合金打造的项链，造型别致。',Delete=44117}",
  [44118] = "{id=44118,NameZh='乌金之坠',Icon='item_44118',Type=540,Quality=3,MaxNum=99,SellPrice=100,Desc='力哈尔特家族使用常用做关键部位的珍贵乌金打造的项链坠。',Delete=44118}",
  [44119] = "{id=44119,NameZh='钢铁雄心',Icon='item_44119',Type=540,Quality=4,MaxNum=99,SellPrice=100,Desc='“用机甲守护力哈尔特家族！”精研机甲的雄心，也是守护家族的赤子之心。',Delete=44119}",
  [44120] = "{id=44120,NameZh='元素戒指',Icon='item_44016',Type=540,Quality=2,MaxNum=99,SellPrice=100,Desc='海涅家族的初级魔法师引导元素之力制成的戒指，练手的粗糙作品。',Delete=44120}",
  [44121] = "{id=44121,NameZh='引导者胸针',Icon='item_44121',Type=540,Quality=3,MaxNum=99,SellPrice=100,Desc='融汇四大元素形成的宝石胸针，能够引导出使用者的能量。',Delete=44121}",
  [44122] = "{id=44122,NameZh='贤者的使命',Icon='item_44122',Type=540,Quality=4,MaxNum=99,SellPrice=100,Desc='海涅家族的使命，海涅家族的传承，寄托于大贤者一身。',Delete=44122}",
  [44123] = "{id=44123,NameZh='银质戒指',Icon='item_44008',Type=540,Quality=2,MaxNum=99,SellPrice=100,Desc='银质的戒指，是流浪四方的吟游诗人的首选。',Delete=44123}",
  [44124] = "{id=44124,NameZh='镶金竖琴',Icon='item_44124',Type=540,Quality=3,MaxNum=99,SellPrice=100,Desc='镶金的银质竖琴，优雅大方，若是登上殿堂，搭配完美的歌喉，或许会受到贵族少女们的追捧吧。',Delete=44124}",
  [44125] = "{id=44125,NameZh='双子星之吻',Icon='item_44125',Type=540,Quality=4,MaxNum=99,SellPrice=100,Desc='双子星温柔地照耀在奈利乌斯家的土地上，极目远眺，双子星眨眼，被甜蜜的力量充盈。',Delete=44125}",
  [44126] = "{id=44126,NameZh='闪亮贝壳',Icon='item_44011',Type=540,Quality=2,MaxNum=99,SellPrice=100,Desc='曾被用作货币流通的贝壳，现在或许有一些收藏价值吧。',Delete=44126}",
  [44127] = "{id=44127,NameZh='远洋银币',Icon='item_44127',Type=540,Quality=3,MaxNum=99,SellPrice=100,Desc='来自远洋国度的银币，纯度很高，纹样精美。',Delete=44127}",
  [44128] = "{id=44128,NameZh='神铸银币',Icon='item_44128',Type=540,Quality=4,MaxNum=99,SellPrice=100,Desc='在神明的祝福下铸成的银币，散发着无穷的吸引力，给人价值连城的感觉。传说这枚银币护佑着巴尔特家族的海上贸易。',Delete=44128}",
  [44132] = "{id=44132,NameZh='祝福香囊',Icon='item_44076',Type=540,Quality=2,MaxNum=99,SellPrice=100,Desc='雷根弗莱格领域中生产的香囊，散发着沁人心脾的气味。',Delete=44132}",
  [44133] = "{id=44133,NameZh='传承灰石',Icon='item_44133',Type=540,Quality=3,MaxNum=99,SellPrice=100,Desc='雷根弗莱格家族家族传承的精密灰纹石，比通常的灰纹石更加坚硬耐磨。',Delete=44133}",
  [44134] = "{id=44134,NameZh='银灰圣痕',Icon='item_44134',Type=540,Quality=4,MaxNum=99,SellPrice=100,Desc='上古时，曾有一道雷光落在巨大的灰纹石上，形成了银灰色的圣痕。雷根弗莱格家族便将这块圣痕之石供奉了起来。',Delete=44134}",
  [44135] = "{id=44135,NameZh='透明晶块',Icon='item_44022',Type=540,Quality=2,MaxNum=99,SellPrice=100,Desc='内嵌完全透明的晶块，会根据周边环境改变颜色。',Delete=44135}",
  [44136] = "{id=44136,NameZh='虚无之晶',Icon='item_44136',Type=540,Quality=3,MaxNum=99,SellPrice=100,Desc='通透而纯净的晶块的内侧究竟是什么呢？是虚无的空洞吗？',Delete=44136}",
