  [44300] = "{id=44300,NameZh='精美狐尾草[1]',Icon='item_44300',Type=190,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=2400,Desc='以“魔法猫女的扫帚”为制作理念的手杖，深受多兰族年轻女孩追捧。',LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,0,0},Delete=44300}",
  [44301] = "{id=44301,NameZh='奇妙狐尾草[1]',Icon='item_44301',Type=190,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=2400,Desc='曾经，一位向往星空的多兰族前辈制作了这把法杖，想借此坠入天穹探险。',LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,0,0},Delete=44301}",
  [44302] = "{id=44302,NameZh='精工狐尾草[1]',Icon='item_44302',Type=190,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=6400,Desc='充满神圣气息的手杖，多被用于各类仪式中。',LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,0,0},Delete=44302}",
  [44303] = "{id=44303,NameZh='魔力狐尾草[1]',Icon='item_44303',Type=190,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=6400,Desc='本是一把普通的手杖，常年充盈魔力后渐渐变成了紫罗兰色。',LoadShowSize=1.1,LoadShowRotate=0,LoadShowPose={0,0,0},Delete=44303}",
  [44304] = "{id=44304,NameZh='新芽狐尾草[1]',Icon='item_44304',Type=190,MaxNum=99,SellPrice=100,Desc='不知从何时流传下来的手杖，写满了看不懂的语言，充满神秘气息。',Delete=44304}",
  [44305] = "{id=44305,NameZh='茂盛狐尾草[1]',Icon='item_44305',Type=190,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,Desc='以烤箱酒吧的热销品草莓香槟为设计概念的法杖，未成年的多兰族禁止使用。',LoadShowSize=1.1,LoadShowRotate=0,LoadShowPose={0,0,0},Delete=44305}",
  [44306] = "{id=44306,NameZh='细长狐尾草',Icon='item_44306',Type=190,MaxNum=99,SellPrice=200,Desc='多兰族用它来战斗、打扫卫生，还有逗小孩。',Level=10,LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,-0.15,0},Delete=44306}",
  [44307] = "{id=44307,NameZh='坐着蜻蜓的狐尾草',Icon='item_44307',Type=190,MaxNum=99,SellPrice=400,Desc='外挂香囊的手杖，意外引来了蜻蜓先生定居。',Level=20,LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,0,0},Delete=44307}",
  [44308] = "{id=44308,NameZh='巨大狐尾草[1]',Icon='item_44308',Type=190,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,Desc='用格外茂盛的狐尾草制成的手杖，打人很痛（物理意义上）',LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,-0.1,0},Delete=44308}",
  [44309] = "{id=44309,NameZh='魔力黄色狐尾草[1]',Icon='item_44309',Type=190,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,Desc='虽然外形宛如奶油香草冰激凌，但它是一把手杖，不可以吃哦。',LoadShowSize=1.1,LoadShowRotate=0,LoadShowPose={0,0,0},Delete=44309}",
  [44310] = "{id=44310,NameZh='精工粉色狐尾草[1]',Icon='item_44310',Type=190,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,Desc='风靡一时的魔法猫女系列手杖，多兰族的男女老幼都无法抗拒这种魅力。',LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,0,0},Delete=44310}",
  [44311] = "{id=44311,NameZh='枫叶狐尾草',Icon='item_44311',Type=190,MaxNum=99,SellPrice=100,Desc='如深秋枫叶般火红的狐尾草，带有令人心跳加快的奇妙魔力。',LoadShowSize=1.1,LoadShowRotate=0,LoadShowPose={0,0,0},Delete=44311}",
  [44312] = "{id=44312,NameZh='远星之花[1]',Icon='item_44312',Type=190,MaxNum=99,SellPrice=20,Desc='虽然名字很霸气，其实只是大陆上随处可见的，最普通的狐尾草。',Delete=44312}",
  [44313] = "{id=44313,NameZh='狐尾草苗苗',Icon='item_44313',Type=190,MaxNum=99,SellPrice=100,Desc='陪伴多兰族童年的玩具、工具和武器。',Delete=44313}",
  [44314] = "{id=44314,NameZh='萌新嫩芽',Icon='item_44314',Type=190,MaxNum=99,SellPrice=20,Desc='每一只初心喵咪正式踏上冒险之旅时，总会得到这一位伙伴。',Level=1,Feature=4,Delete=44314}",
  [44315] = "{id=44315,NameZh='蔷薇灵语狐尾草',Icon='item_44315',Type=190,MaxNum=99,SellPrice=3200,Desc='妖精一族的“灵语师”都是植物学专家，它们甚至能将蔷薇嫁接在狐尾草上！',Level=110,LoadShowSize=1.2,LoadShowPose={0,0.25,0},Delete=44315}",
  [44316] = "{id=44316,NameZh='红鱼花铃·狐尾草',Icon='item_44316',Type=190,MaxNum=99,SellPrice=100,Desc='长了一身红色鳞片的金鱼呀，喜欢在湖底的水草里悠闲地打瞌睡。有人投食的话，也会慢悠悠地钻到水面上，不紧不慢地吃鱼食。如果它会衔着狐尾草游出水面，也不要惊讶，这是金鱼族的报答哟~',LoadShowSize=1.2,LoadShowRotate=180,LoadShowPose={0.2},Delete=44316}",
  [44317] = "{id=44317,NameZh='湛蓝天光·狐尾草',Icon='item_44317',Type=190,MaxNum=99,SellPrice=2800,Desc='阔大的云海之上透出湛蓝天光，晴空下的战士们振作起了精神。蓝色狐尾草印证着你的忠诚，勇敢与希望。',Level=110,LoadShowSize=1.3,LoadShowRotate=90,LoadShowPose={0,0,0},Delete=44317}",
  [44318] = "{id=44318,NameZh='天虹圣遗·狐尾草',Icon='item_44318',Type=190,MaxNum=99,SellPrice=100,Desc='狐尾草受彩虹桥碎片魔力的影响晶体化，因为能够发光深受多兰族的喜爱。',LoadShowSize=1.2,Delete=44318}",
  [44319] = "{id=44319,NameZh='月下祈者·狐尾草',Icon='item_44319',Type=190,MaxNum=99,SellPrice=100,Desc='冰封千年的陨铁，王国的工匠们用尽办法也无法将其熔铸，却因小学徒的一次失误暴露在月光下。那一刻奇迹发生，陨铁融化宛若水银般流转，在月光下散发耀眼星辉。\n一部分陨铁溅落在旁边的狐尾草，令它拥有了驱散邪祟的圣洁之力。',LoadShowRotate=70,LoadShowPose={0.5,-0.5,-1},Delete=44319}",
  [44320] = "{id=44320,NameZh='英灵起点·狐尾草[2]',Icon='item_44320',Type=190,Quality=2,MaxNum=99,SellPrice=100,Desc='克里图拉新生领到的初心武器，致敬英灵而铸上蓝金涂装。据说设计者是第一个入学克里图拉的多兰新生，开学樱花下的喷嚏传染浪就是从她开始的。',NoStorage=5,LoadShowSize=1,Delete=44320}",
  [44321] = "{id=44321,NameZh='英灵信标·狐尾草[2]',Icon='item_44321',Type=190,Quality=3,MaxNum=99,SellPrice=100,Desc='这只狐尾草是指引女武神降临、迎接英灵的道标。它能召唤出来吃蓝莓冰淇淋的女武神哦（广告效果）。',NoStorage=5,LoadShowSize=1,Delete=44321}",
  [44322] = "{id=44322,NameZh='英灵羽证·狐尾草[2]',Icon='item_44322',Type=190,Quality=3,MaxNum=99,SellPrice=100,Desc='英灵的证明。潜入学院的女武神在狐尾草中注入了彩虹的魔力。狐尾草长出羽毛，新生回家后，连罗扎纳的护鼻药水都流行了起来。',NoStorage=5,LoadShowSize=1,Delete=44322}",
  [44323] = "{id=44323,NameZh='信仰狐尾草',Icon='item_44323',Type=190,MaxNum=99,SellPrice=100,Desc='巴风特曾带领手下对梦罗克进行过一次史无前例的大侵袭，这次的战争造成了数以万计的民众伤亡，在危难的关头有十四位勇士站了出来，他们牺牲了自己保护了梦罗克，死后的他们留下了自己的武器，这些武器被梦罗克的人们当做信仰的象征，这枝狐尾草便是十四把武器之一。',LoadShowSize=1.25,LoadShowRotate=-90,LoadShowPose={0,-0.2,0},Delete=44323}",
  [44324] = "{id=44324,NameZh='哀嚎的狐尾草',Icon='item_44324',Type=190,MaxNum=99,SellPrice=100,Desc='多兰族的狐尾草，千年以前，第一个多兰族冒险家路过克雷斯特汉姆古城的这片废墟时，它手里的狐尾草和这片土地产生了剧烈的共鸣，发出剧烈的哀嚎声。',LoadShowSize=1.25,LoadShowRotate=-90,LoadShowPose={0,-0.2,0},Delete=44324}",
  [44325] = "{id=44325,NameZh='衔尾者狐尾草',Icon='item_44325',Type=190,MaxNum=99,SellPrice=100,Desc='向黑暗与巨蛇借来的魔力，采用锋利的毒牙制成的狐尾草。',LoadShowSize=1.25,LoadShowRotate=-90,LoadShowPose={0,-0.2,0},Delete=44325}",
  [44326] = "{id=44326,NameZh='圣徒·狐尾草[1]',Icon='item_44326',Type=190,Quality=3,MaxNum=99,SellPrice=100,Desc='圣歌教会虔诚的多兰族信徒奥摩里使用的狐尾草，拥有极其优秀的攻击力，这个狐尾草还有个极其重要的特点：那就是信仰越虔诚，狐尾草能发挥的力量越强大。',LoadShowSize=1.25,LoadShowRotate=-90,LoadShowPose={0,-0.2,0},Delete=44326}",
  [44327] = "{id=44327,NameZh='圣息崇聆·狐尾草',Icon='item_44327',Type=190,MaxNum=99,SellPrice=100,Desc='光与天空，圣洁的飞鸟，神的双翼已然张开，吾虔诚的信徒，愿你在吾的庇佑下体验幸福与美好，你的灵魂之音，吾等已经听到，这根圣鞭赐予你，神祇永远与你同在。',LoadShowSize=1.25,LoadShowRotate=-90,LoadShowPose={0,-0.2,0},Delete=44327}",
  [44328] = "{id=44328,NameZh='科学救赎·狐尾草',Icon='item_44328',Type=190,MaxNum=99,SellPrice=100,Desc='科学！科学！科学！为了科学一切的牺牲都是值得，蝼蚁们的生命本就毫无意义，因实验而死的他们应该觉得骄傲，这是他们的宿命！快了！就快了，只要这把狐尾草制作出来，那些人就会知道我弗兰肯才是站在顶端的人！',LoadShowSize=1.25,LoadShowRotate=-90,LoadShowPose={0,-0.2,0},Delete=44328}",
  [44329] = "{id=44329,NameZh='英灵·狐尾草',Icon='item_44329',Type=190,MaxNum=99,SellPrice=100,Desc='多兰族战神的狐尾草，冠以神之名的狐尾草可以进行强力的攻击。',LoadShowSize=1.25,LoadShowRotate=-90,LoadShowPose={0,-0.2,0},Delete=44329}",
  [44330] = "{id=44330,NameZh='亡灵狐尾草',Icon='item_44330',Type=190,MaxNum=99,SellPrice=100,Desc='据说这根狐尾草可以让多兰族的行动变得跟亡灵一样，来无影去无踪。',LoadShowSize=1.25,LoadShowRotate=-90,LoadShowPose={0,-0.2,0},Delete=44330}",
  [44331] = "{id=44331,NameZh='魔器·莫丹桑',Icon='item_44331',Type=190,MaxNum=99,SellPrice=100,Desc='梦罗克碎片打造的禁忌武器，对应着异世界恶魔No.20·莫丹桑，是一个手执狐尾草，身姿潇洒的多兰族。',LoadShowSize=1.25,LoadShowRotate=-90,LoadShowPose={0,-0.2,0},Delete=44331}",
  [44332] = "{id=44332,NameZh='星界·流光',Icon='item_44332',Type=190,MaxNum=99,SellPrice=100,Desc='利用星辰中提炼出的珍贵矿石制作而成，狐尾草带着星光的力量，挥舞时流光四溢如同漫天的星辰。',LoadShowSize=1.25,LoadShowRotate=-90,LoadShowPose={0,-0.2,0},Delete=44332}",
  [44333] = "{id=44333,NameZh='日耀·苏尔狐尾草',Icon='item_44333',Type=190,MaxNum=99,SellPrice=100,Desc='太阳马戏团标志性的武器，耀眼的金光和精致的造型，是坚持爱与正义的冒险者所追寻的目标。',LoadShowSize=1.25,LoadShowRotate=-90,LoadShowPose={0,-0.2,0},Delete=44333}",
  [44334] = "{id=44334,NameZh='月辉·玛尼狐尾草',Icon='item_44334',Type=190,MaxNum=99,SellPrice=100,Desc='暗月马戏团标志性的武器，因其式样低调而华丽又非常稀有，成为了年轻冒险家追捧的热门武器。',LoadShowSize=1.25,LoadShowRotate=-90,LoadShowPose={0,-0.2,0},Delete=44334}",
  [44335] = "{id=44335,NameZh='炎魂·业火红莲',Icon='item_44335',Type=190,MaxNum=99,SellPrice=100,Desc='融合红龙的灼热吐息与火焰结晶制作的狐尾草，每次刺出都如同红龙吐出焚风龙焰般势不可挡。',LoadShowSize=1.25,LoadShowRotate=-90,LoadShowPose={0,-0.2,0},Delete=44335}",
  [44336] = "{id=44336,NameZh='碎雪·冰霜狐尾',Icon='item_44336',Type=190,MaxNum=99,SellPrice=100,Desc='融合冰龙的霜冻吐息与魔力冰晶制作的狐尾草，每次刺出都如同冰龙吐出刺骨霜焰般威力无比。',LoadShowSize=1.25,LoadShowRotate=-90,LoadShowPose={0,-0.2,0},Delete=44336}",
  [44337] = "{id=44337,NameZh='时间之尾',Icon='item_44337',Type=190,MaxNum=99,SellPrice=100,Desc='抓住时间的尾巴吧，这柄狐尾草武器是为了进入新纪元的多兰族准备的利器。',LoadShowSize=1.25,LoadShowRotate=-90,LoadShowPose={0,-0.2,0},Delete=44337}",
  [44338] = "{id=44338,NameZh='埃琉德尼尔狐尾草',Icon='item_44338',Type=190,MaxNum=99,SellPrice=100,Desc='“死者之都的女王海拉大人，请为我的狐尾草赐予力量吧！”',LoadShowSize=1.25,LoadShowRotate=-90,LoadShowPose={0,-0.2,0},Delete=44338}",
  [44339] = "{id=44339,NameZh='永夜·无尽黑暗',Icon='item_44339',Type=190,MaxNum=99,SellPrice=100,Desc='黑暗之中的黑暗，能够吸收所有光芒的黑，赐予这款狐尾草特别的力量。',Feature=1,LoadShowSize=1.25,LoadShowRotate=-90,LoadShowPose={0,-0.2,0},Delete=44339}",
  [44340] = "{id=44340,NameZh='天后的恸哭',Icon='item_44340',Type=452,Quality=4,MaxNum=1,SellPrice=100,Desc='巴德尔被槲寄生刺死，令天后弗丽嘉蒙受丧子之痛。这株沾染了巴德尔鲜血的植物也饱含着弗丽嘉的悲恸。',NoSale=1,NoStorage=7,Delete=44340}",
  [44341] = "{id=44341,NameZh='天后的恸哭·精锻',Icon='item_44341',Type=452,Quality=4,MaxNum=1,SellPrice=100,Desc='巴德尔被槲寄生刺死，令天后弗丽嘉蒙受丧子之痛。这株沾染了巴德尔鲜血的植物也饱含着弗丽嘉的悲恸。',NoSale=1,NoStorage=7,Delete=44341}",
  [44342] = "{id=44342,NameZh='天后的恸哭·神铸',Icon='item_44342',Type=452,Quality=4,MaxNum=1,SellPrice=100,Desc='巴德尔被槲寄生刺死，令天后弗丽嘉蒙受丧子之痛。这株沾染了巴德尔鲜血的植物也饱含着弗丽嘉的悲恸。',NoSale=1,NoStorage=7,Delete=44342}",
  [44344] = "{id=44344,NameZh='圣灵·络菲之希望狐尾草',Icon='item_44344',Type=190,MaxNum=99,SellPrice=100,Desc='多兰族战神的狐尾草，冠以神之名的狐尾草可以进行强力的攻击。',LoadShowSize=1.25,LoadShowRotate=-90,LoadShowPose={0,-0.2,0},Delete=44344}",
  [44345] = "{id=44345,NameZh='远古回音·狐尾草',Icon='item_44345',Type=190,MaxNum=99,SellPrice=3200,Desc='铭刻着神秘纹样的狐尾草，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,LoadShowSize=1.5,Delete=44345}",
  [44347] = "{id=44347,NameZh='王国荣辉·狐尾草',Icon='item_44347',Type=190,MaxNum=99,SellPrice=100,Desc='效忠于王室的宫廷侍卫所持的狐尾草，其上绘有卢恩王家纹章。连多兰族都能收入麾下，卢恩王室的影响力，真是不可估量呢。',LoadShowSize=1.5,LoadShowRotate=90,Delete=44347}",
  [44351] = "{id=44351,NameZh='天后的恸哭·极限',Icon='item_44351',Type=452,Quality=4,MaxNum=1,SellPrice=100,Desc='巴德尔被槲寄生刺死，令天后弗丽嘉蒙受丧子之痛。这株沾染了巴德尔鲜血的植物也饱含着弗丽嘉的悲恸。',NoSale=1,NoStorage=7,TFValidDate='2022-03-10 05:00:00',ValidDate='2022-03-23 05:00:00',Delete=44351}",
  [44352] = "{id=44352,NameZh='英灵信标·狐尾草[2]',Icon='item_44321',Type=190,Quality=2,MaxNum=99,SellPrice=100,Desc='这只狐尾草是指引女武神降临、迎接英灵的道标。它能召唤出来吃蓝莓冰淇淋的女武神哦（广告效果）。',NoStorage=5,LoadShowSize=1,Delete=44352}",
  [44353] = "{id=44353,NameZh='英灵羽证·狐尾草[2]',Icon='item_44322',Type=190,Quality=3,MaxNum=99,SellPrice=100,Desc='英灵的证明。潜入学院的女武神在狐尾草中注入了彩虹的魔力。狐尾草长出羽毛，新生回家后，连罗扎纳的护鼻药水都流行了起来。',NoStorage=5,LoadShowSize=1,Delete=44353}",
  [44600] = "{id=44600,NameZh='风魔轮飞镖[1]',Icon='item_44600',Type=300,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='经忍法大师“果心居士”改良的风魔手里剑，可以附着灵气，增强各种忍法的威力。',LoadShowPose={0,0.3,0},Delete=44600}",
  [44601] = "{id=44601,NameZh='风魔飞镖-启明星[1]',Icon='item_44601',Type=300,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='“果心居士”使用陨石碎片打造的风魔飞镖，借助星辰之力可以释放强大的忍法。',LoadShowPose={0,0.3,0},Delete=44601}",
  [44602] = "{id=44602,NameZh='名刀-村正[1]',Icon='item_44602',Type=180,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='由天水之国的刀匠世家“村正家族”打造的太刀。村正家族追求实用，只打造锋利坚韧、用于实战的刀具，而其中最顶尖的才能被冠以“名刀”之名。',LoadShowSize=1,Delete=44602}",
  [44603] = "{id=44603,NameZh='妖刀-村正[1]',Icon='item_44603',Type=180,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='刀匠世家“村正家族”初代家主亲手打造的名刀，由于斩杀了过多恶魔被邪恶的怨力侵蚀，意志薄弱者触碰此刀便会被怨力控制，失去神智，因此这把刀被人们称为“妖刀”。但若是能凭借强大的意志力驱散怨力，这把“妖刀”将成为斩妖除魔的利器！',LoadShowSize=1,Delete=44603}",
  [44604] = "{id=44604,NameZh='风魔手里剑[1]',Icon='item_44604',Type=300,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='忍者世家“风魔一族”的独门兵器，虽然威力巨大但是难以操控，需要长时间的训练否则容易划伤自己。',LoadShowPose={0,0.3,0},Delete=44604}",
  [44605] = "{id=44605,NameZh='风魔手里剑-疾影[1]',Icon='item_44605',Type=300,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='风魔小太郎斩杀了为祸天津町的巨蛇，在蛇腹中发现一块坚硬无比的巨石，最锋利的刀剑也无法在这块石头上留下丝毫痕迹，只有巨蛇的毒液能够将它融化。风魔小太郎将巨石打造为无坚不摧的风魔手里剑，用它消灭了无数侵犯天水之国的恶魔。',LoadShowPose={0,0.3,0},Delete=44605}",
  [44606] = "{id=44606,NameZh='枫忆风魔轮',Icon='item_44606',Type=300,MaxNum=99,SellPrice=100,Desc='如深秋枫叶般火红的风魔轮，带有令人心跳加快的奇妙魔力。',LoadShowSize=1.25,LoadShowRotate=80,LoadShowPose={0,0.2,0},Delete=44606}",
  [44607] = "{id=44607,NameZh='百鬼封尽',Icon='item_44607',Type=462,Quality=4,MaxNum=1,SellPrice=100,Desc='许多年前的天水之国，恶魔横行。家人被恶魔杀害的少年鬼斩八幡发誓要除尽世间诸魔，最终死于魔王之手。因其英勇被选召为英灵，但执念使他仍游荡于世间，不灭尽世界恶魔，誓不进入英灵殿。',NoSale=1,NoStorage=7,Delete=44607}",
  [44608] = "{id=44608,NameZh='百鬼封尽·精锻',Icon='item_44608',Type=462,Quality=4,MaxNum=1,SellPrice=100,Desc='许多年前的天水之国，恶魔横行。家人被恶魔杀害的少年鬼斩八幡发誓要除尽世间诸魔，最终死于魔王之手。因其英勇被选召为英灵，但执念使他仍游荡于世间，不灭尽世界恶魔，誓不进入英灵殿。',NoSale=1,NoStorage=7,Delete=44608}",
  [44609] = "{id=44609,NameZh='百鬼封尽·神铸',Icon='item_44609',Type=462,Quality=4,MaxNum=1,SellPrice=100,Desc='许多年前的天水之国，恶魔横行。家人被恶魔杀害的少年鬼斩八幡发誓要除尽世间诸魔，最终死于魔王之手。因其英勇被选召为英灵，但执念使他仍游荡于世间，不灭尽世界恶魔，誓不进入英灵殿。',NoSale=1,NoStorage=7,Delete=44609}",
  [44610] = "{id=44610,NameZh='尖啸风魔轮',Icon='item_44610',Type=300,MaxNum=99,SellPrice=100,Desc='忍者专用武器，千年以前，一个忍者大师路路过克雷斯特汉姆古城的这片废墟时，他用手里的风魔轮打败了古城附近的魔物，也让风魔轮沾染上魔物的气息，变成了尖啸风魔轮。',LoadShowSize=1.25,LoadShowRotate=80,LoadShowPose={0,0.2,0},Delete=44610}",
  [44611] = "{id=44611,NameZh='衔尾者鳞风魔轮',Icon='item_44611',Type=300,MaxNum=99,SellPrice=100,Desc='向黑暗与巨蛇借来的魔力，采用坚固的蛇鳞制成的风魔轮。',LoadShowSize=1.25,LoadShowRotate=80,LoadShowPose={0,0.2,0},Delete=44611}",
  [44612] = "{id=44612,NameZh='信仰风魔轮',Icon='item_44612',Type=300,MaxNum=99,SellPrice=100,Desc='巴风特曾带领手下对梦罗克进行过一次史无前例的大侵袭，这次的战争造成了数以万计的民众伤亡，在危难的关头有许多勇士站了出来，他们牺牲了自己保护了梦罗克，死后的他们留下了自己的武器，这些武器被梦罗克的人们当做信仰的象征，这把风魔轮就是其中之一。',LoadShowSize=1.25,LoadShowRotate=80,LoadShowPose={0,0.2,0},Delete=44612}",
  [44613] = "{id=44613,NameZh='英灵·风魔轮',Icon='item_44613',Type=300,MaxNum=99,SellPrice=100,Desc='忍者大师莹的风魔轮，冠以仙人之名的风魔轮可以进行迅猛有力的打击。',LoadShowSize=1.25,LoadShowRotate=80,LoadShowPose={0,0.2,0},Delete=44613}",
  [44614] = "{id=44614,NameZh='魔器·利维亚米特',Icon='item_44614',Type=300,MaxNum=99,SellPrice=100,Desc='梦罗克碎片打造的禁忌武器，一个漆黑的风魔轮，对应着异世界恶魔No.27·利维亚米特。',LoadShowSize=1.25,LoadShowRotate=80,LoadShowPose={0,0.2,0},Delete=44614}",
  [44615] = "{id=44615,NameZh='科学救赎·风魔轮',Icon='item_44615',Type=300,MaxNum=99,SellPrice=100,Desc='科学！科学！科学！为了科学一切的牺牲都是值得，蝼蚁们的生命本就毫无机制，因实验而死的他们应该觉得骄傲，这是他们的宿命！快了！就快了，只要这把风魔轮制作出来，那些人就会知道我弗兰肯才是站在顶端的人！',LoadShowSize=1.25,LoadShowRotate=80,LoadShowPose={0,0.2,0},Delete=44615}",
  [44616] = "{id=44616,NameZh='圣徒·风魔轮[1]',Icon='item_44616',Type=300,Quality=3,MaxNum=99,SellPrice=100,Desc='圣歌教会虔诚的信徒周里使用的风魔轮，拥有极其优秀的攻击力，这个风魔轮还有个极其重要的特点：那就是信仰越虔诚，风魔轮能发挥的力量越强大。',LoadShowSize=1.25,LoadShowRotate=80,LoadShowPose={0,0.2,0},Delete=44616}",
  [44617] = "{id=44617,NameZh='圣灵·周里之忍耐风魔轮',Icon='item_44617',Type=300,MaxNum=99,SellPrice=100,Desc='最早的天照所使用的武器，冠以神之名的风魔轮可以进行强力的攻击。',LoadShowSize=1.25,LoadShowRotate=80,LoadShowPose={0,0.2,0},Delete=44617}",
  [44618] = "{id=44618,NameZh='亡灵风魔轮',Icon='item_44618',Type=300,MaxNum=99,SellPrice=100,Desc='据说这把风魔轮可以让忍者进入隐匿状态，如同一个亡灵一样，很难让敌人发现。',LoadShowSize=1.25,LoadShowRotate=80,LoadShowPose={0,0.2,0},Delete=44618}",
  [44619] = "{id=44619,NameZh='星界·坠星',Icon='item_44619',Type=300,MaxNum=99,SellPrice=100,Desc='利用星辰中提炼出的珍贵矿石做制作而成，这把风魔轮带着星光的力量，挥舞时流光四溢如同漫天的星辰。',LoadShowSize=1.25,LoadShowRotate=80,LoadShowPose={0,0.2,0},Delete=44619}",
  [44620] = "{id=44620,NameZh='日耀·风魔轮',Icon='item_44620',Type=300,MaxNum=99,SellPrice=100,Desc='太阳马戏团标志性的武器，耀眼的金光和精致的造型，是坚持爱与正义的冒险者所追寻的目标。',LoadShowSize=1.25,LoadShowRotate=80,LoadShowPose={0,0.2,0},Delete=44620}",
  [44621] = "{id=44621,NameZh='月辉·风魔轮',Icon='item_44621',Type=300,MaxNum=99,SellPrice=100,Desc='暗月马戏团标志性的武器，因其式样低调而华丽又非常稀有，成为了年轻冒险家追捧的热门武器。',LoadShowSize=1.25,LoadShowRotate=80,LoadShowPose={0,0.2,0},Delete=44621}",
  [44622] = "{id=44622,NameZh='炎魂·烈火风魔轮',Icon='item_44622',Type=300,MaxNum=99,SellPrice=100,Desc='融合红龙的灼热吐息与火焰结晶制作的风魔轮，来回之间带着烈焰的气息。',LoadShowSize=1.25,LoadShowRotate=80,LoadShowPose={0,0.2,0},Delete=44622}",
  [44623] = "{id=44623,NameZh='碎雪·寒光风魔轮',Icon='item_44623',Type=300,MaxNum=99,SellPrice=100,Desc='融合冰龙的霜冻吐息与魔力冰晶制作的风魔轮，每次出手都能让敌人瞬间结冰。',LoadShowSize=1.25,LoadShowRotate=80,LoadShowPose={0,0.2,0},Delete=44623}",
  [44624] = "{id=44624,NameZh='时间之轮',Icon='item_44624',Type=300,MaxNum=99,SellPrice=100,Desc='时间是不会静止的，这把风魔轮却可以打破时间的禁锢，让持有者走入新纪元。',LoadShowSize=1.25,LoadShowRotate=80,LoadShowPose={0,0.2,0},Delete=44624}",
  [44625] = "{id=44625,NameZh='希尔布佳达风魔轮',Icon='item_44625',Type=300,MaxNum=99,SellPrice=100,Desc='“无知并不可怕，可怕的是人类的傲慢！”忍者大师希尔布佳达如此说。',LoadShowSize=1.25,LoadShowRotate=80,LoadShowPose={0,0.2,0},Delete=44625}",
  [44626] = "{id=44626,NameZh='永夜·黑暗降临',Icon='item_44626',Type=300,MaxNum=99,SellPrice=100,Desc='黑暗之中的黑暗，能够吸收所有光芒的黑，赐予这把风魔轮特别的力量。',LoadShowSize=1.25,LoadShowRotate=80,LoadShowPose={0,0.2,0},Delete=44626}",
  [44627] = "{id=44627,NameZh='名刀-村正的刀鞘',Icon='item_44627',Type=180,MaxNum=99,SellPrice=100,Delete=44627}",
  [44628] = "{id=44628,NameZh='妖刀-村正的刀鞘',Icon='item_44628',Type=180,MaxNum=99,SellPrice=100,Delete=44628}",
  [44629] = "{id=44629,NameZh='波姬风魔',Icon='item_44629',Type=300,MaxNum=99,SellPrice=100,Delete=44629}",
  [44630] = "{id=44630,NameZh='勇士风魔飞镖',Icon='item_44630',Type=300,MaxNum=99,SellPrice=100,Desc='一把适合新手使用的风魔，拿上他去战斗吧，期待你的成长哦！',Delete=44630}",
  [44631] = "{id=44631,NameZh='圣息崇聆风魔轮',Icon='item_44631',Type=300,MaxNum=99,SellPrice=100,Desc='光与天空，圣洁的飞鸟，神的双翼已然张开，吾虔诚的信徒，愿你在吾的庇佑下体验幸福与美好，你的灵魂之音，吾等已经听到，这根圣鞭赐予你，神祇永远与你同在。',LoadShowSize=1.25,LoadShowRotate=80,LoadShowPose={0,0.2,0},Delete=44631}",
  [44632] = "{id=44632,NameZh='天虹圣遗·风魔轮',Icon='item_44632',Type=300,MaxNum=99,SellPrice=100,Desc='天水之国的匠人们收集彩虹桥碎片锻造的风魔轮，转动时散发的虹光让敌人在梦幻中迎来死亡。',LoadShowPose={0,0.2,0},Delete=44632}",
  [44638] = "{id=44638,NameZh='远古回音·风魔轮',Icon='item_44638',Type=300,MaxNum=99,SellPrice=3200,Desc='铭刻着神秘纹样的风魔轮，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,LoadShowSize=1.5,LoadShowPose={0,0.3,0},Delete=44638}",
  [44639] = "{id=44639,NameZh='红鱼花铃·风魔轮',Icon='item_44639',Type=300,MaxNum=99,SellPrice=100,Desc='长了一身红色鳞片的金鱼呀，喜欢在湖底的水草里悠闲地打瞌睡。有人投食的话，也会慢悠悠地钻到水面上，不紧不慢地吃鱼食。如果它会衔着风魔轮游出水面，也不要惊讶，这是金鱼族的报答哟~',Delete=44639}",
  [44640] = "{id=44640,NameZh='月下祈者·风魔轮',Icon='item_44640',Type=300,MaxNum=99,SellPrice=100,Desc='冰封千年的陨铁，王国的工匠们用尽办法也无法将其熔铸，却因小学徒的一次失误暴露在月光下。那一刻奇迹发生，陨铁融化宛若水银般流转，在月光下散发耀眼星辉。\n一部分陨铁溅落在旁边的风魔轮，令它拥有了驱散邪祟的圣洁之力。',Delete=44640}",
  [44642] = "{id=44642,NameZh='王国荣辉·风魔轮',Icon='item_44642',Type=300,MaxNum=99,SellPrice=100,Desc='效忠于王室的宫廷侍卫所持的飞镖，其上绘有卢恩王家纹章。这些天水之国来的特殊武者，竟然也献出了自己的忠诚……是贵族们给的，实在太多了吗？',LoadShowSize=1.7,LoadShowRotate=-90,LoadShowPose={0,0.25,0},Delete=44642}",
  [44646] = "{id=44646,NameZh='百鬼封尽·极限',Icon='item_44646',Type=462,Quality=4,MaxNum=1,SellPrice=100,Desc='许多年前的天水之国，恶魔横行。家人被恶魔杀害的少年鬼斩八幡发誓要除尽世间诸魔，最终死于魔王之手。因其英勇被选召为英灵，但执念使他仍游荡于世间，不灭尽世界恶魔，誓不进入英灵殿。',NoSale=1,NoStorage=7,TFValidDate='2022-03-10 05:00:00',ValidDate='2022-03-23 05:00:00',Delete=44646}",
  [44647] = "{id=44647,NameZh='英灵信标·手里剑[2]',Icon='item_63481',Type=300,Quality=2,MaxNum=99,SellPrice=100,Desc='这把手里剑是指引女武神降临、迎接英灵的道标。阵亡的勇士抱着它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,LoadShowPose={0,0.3,0},Delete=44647}",
  [44648] = "{id=44648,NameZh='英灵羽证·手里剑[2]',Icon='item_63482',Type=300,Quality=3,MaxNum=99,SellPrice=100,Desc='英灵的证明。潜入学院的女武神在手里剑中注入了奥丁领域的魔力。手里剑生出羽毛，与风更为亲和。戾气消减，体现了不动之慈悲。',NoStorage=5,LoadShowPose={0,0.3,0},Delete=44648}",
