  [45193] = "{id=45193,NameZh='迪斯凯特的头盔',Icon='item_45193',Type=800,Quality=3,MaxNum=99,SellPrice=100,Desc='据说是依照贤者迪斯凯特佣兵时代的穿着仿制的。虽然是仿制品，头盔的做工却意外的精良。',Share=1,Feature=1,LoadShowSize=2,LoadShowPose={0,0.6,0},}",
  [45194] = "{id=45194,NameZh='融化中的雪糕',Icon='item_45194',Type=800,MaxNum=99,SellPrice=100,Desc='每当戴上就会想起那个舔着雪糕，和大家一起等待Summer Test的夏天。吃完雪糕，可以看见木棍上写着“2016·夏”。',Share=1,}",
  [45195] = "{id=45195,NameZh='乐园团圆帽',Icon='item_45195',Type=800,MaxNum=99,SellPrice=100,Desc='只发给乐园团成员的帽子，其设计感与制服相当搭配。',Share=1,}",
  [45196] = "{id=45196,NameZh='冷酷的棒球帽子',Icon='item_45196',Type=800,MaxNum=99,SellPrice=100,Desc='「聆听·爱与勇气的声音」主题音乐会纪念：一顶穿越时空、跨越次元、连接种族的冷酷帽子。至少哥布灵是这么认为的！',Share=1,}",
  [45197] = "{id=45197,NameZh='百万击破',Icon='item_45197',Type=800,MaxNum=99,SellPrice=100,AdventureSort=10000,AdventureValue=1,StorageReward={buffid={80011150}},Condition=8,Desc='跃动而出的魄力数字，不但饱含着人们的期待和盼望，更融合了超过上百万份的爱与信仰。独一无二的特殊工艺，只为参与这段新冒险路程的你而定做。初心者！冒险旅程就此开启！',Share=1,Feature=1,LoadShowSize=2,LoadShowRotate=0,LoadShowPose={0,0.2,0},}",
  [45198] = "{id=45198,NameZh='枫叶',Icon='item_45198',Type=800,MaxNum=99,SellPrice=100,AdventureSort=10004,AdventureValue=1,StorageReward={buffid={80011150}},Condition=8,Desc='散落一地的枫叶，是我们一起走过的秋日纪念，我拾起其中一片，顶在头上，想起大家温暖的脸。',Share=1,Feature=1,LoadShowSize=3,LoadShowRotate=0,LoadShowPose={0,0.3,0},}",
  [45199] = "{id=45199,NameZh='圣诞帽',Icon='item_45199',Type=800,MaxNum=99,AuctionPrice=1,SellPrice=20,AdventureSort=756,AdventureValue=60,AdventureReward={buffid={61000460}},StorageReward={buffid={80012680}},Condition=4,ComposeID=14199,Desc='爱在RO的雪季，美丽的圣诞季节，谨以此作为纪念。',Share=1,Feature=1,LoadShowSize=3,LoadShowRotate=50,LoadShowPose={0,0.7,0},}",
  [45200] = "{id=45200,NameZh='酉头巾',Icon='item_45200',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=20,AdventureSort=10005,AdventureValue=1,AdventureReward={buffid={60000030}},StorageReward={buffid={80011160}},Condition=4,ComposeID=14200,Desc='只有在酉年由特殊的材料和工艺才能制作而成的头饰，极其珍贵稀有。',Share=1,Feature=1,LoadShowSize=2,LoadShowRotate=0,LoadShowPose={0,0.7,0},}",
  [45202] = "{id=45202,NameZh='歉意头饰',Icon='item_45202',Type=800,MaxNum=99,SellPrice=100,Desc='创造着这个美丽冒险世界的B格猫们表示，谨以此特别的头饰来铭记所有点点滴滴的尊重宽容和理解。每天看到它的时候就提醒自己，还需要不停努力为这个世界创造更多更新更有爱的内容，只为支持我们的所有冒险者们！',Share=1,}",
