  [45232] = "{id=45232,NameZh='海军风贝雷帽',Icon='item_45232',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=20001,AdventureValue=110,StorageReward={buffid={80011781}},Condition=8,Desc='“你曾经聆听过来自迷雾中不可见的海妖的歌谣吗？”老船长抚摸着海军帽，“如果听过，你一定愿意将大海作为一生的追寻。”（非常感谢您的购买，这个美丽的饰品在活动贩售期间并不能在交易所流通，但在活动贩售结束后就能正常进入交易所啦~来自伊娜，于2017年7月）',Feature=1,LoadShowSize=2.5,LoadShowRotate=50,LoadShowPose={0,0.9,0},}",
  [45233] = "{id=45233,NameZh='美人蕉沙滩帽',Icon='item_45233',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=20002,AdventureValue=110,StorageReward={buffid={80011781}},Condition=8,Desc='喧闹的沙滩上，少女正在兜售自己编织的沙滩帽，哦，这似乎是一顶与众不同的帽子，白色丝缎和红色美人蕉让它格外引人注目。（非常感谢您的购买，这个美丽的饰品在活动贩售期间并不能在交易所流通，但在活动贩售结束后就能正常进入交易所啦~来自伊娜，于2017年7月）',Feature=1,LoadShowSize=2.5,LoadShowRotate=0,LoadShowPose={0,0.9,0},}",
  [45234] = "{id=45234,NameZh='珍珠贝壳发夹',Icon='item_45234',Type=800,Quality=3,MaxNum=99,SellPrice=100,Feature=1,LoadShowSize=4,LoadShowRotate=30,LoadShowPose={0,0.9,0},}",
  [45235] = "{id=45235,NameZh='趴趴初心者·女',Icon='item_45235',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=1020,AdventureSort=10014,AdventureValue=112,StorageReward={buffid={80011160}},Condition=4,ComposeID=14235,Desc='不管经历了多少冒险的旅程，时刻勿忘初心。为了纪念这一刻，由卡普拉公司的美少女小姐姐们手工亲手缝制的玩偶，充满了温暖和关怀。（虽然是女孩子造型的娃娃，但是男生也可以佩戴哦~）',Feature=1,LoadShowSize=2.5,LoadShowRotate=0,LoadShowPose={0,0.6,0},}",
  [45236] = "{id=45236,NameZh='趴趴初心者·男',Icon='item_45236',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=1020,AdventureSort=10013,AdventureValue=111,StorageReward={buffid={80011160}},Condition=4,ComposeID=14236,Desc='不管经历了多少冒险的旅程，时刻勿忘初心。为了纪念这一刻，由卡普拉公司的美少女小姐姐们手工亲手缝制的玩偶，充满了温暖和关怀。（虽然是男孩子造型的娃娃，但是女生也可以佩戴哦~）',Feature=1,LoadShowSize=2.5,LoadShowRotate=0,LoadShowPose={0,0.6,0},}",
