  [45239] = "{id=45239,NameZh='野浆果遮阳帽',Icon='item_45239',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=20004,AdventureValue=110,StorageReward={buffid={80011781}},Condition=8,Desc='踮着脚尖走进丛林，六月的浆果坠满了枝头，饱满得一戳就破，少女小心翼翼地摘下一捧，妆点祖母手制的遮阳帽。（非常感谢您的购买，这个美丽的饰品在活动贩售期间并不能在交易所流通，但在活动贩售结束后就能正常进入交易所啦~来自伊娜，于2017年7月）',Feature=1,LoadShowSize=2,LoadShowRotate=20,LoadShowPose={0,0.7,0},}",
