  [45274] = "{id=45274,NameZh='渴望朋友',Icon='item_45274',Type=800,Quality=2,MaxNum=99,SellPrice=100,}",
  [45275] = "{id=45275,NameZh='圣徒之冠',Icon='item_45275',Type=800,MaxNum=99,SellPrice=100,Desc='为了表彰安德鲁对武器防具制作的巨大贡献，圣歌教会特制了一个“圣徒之冠”赐予安德鲁，头戴“圣徒之冠”的安德鲁也被称为“光明圣徒”而闻名大陆。',}",
  [45276] = "{id=45276,NameZh='神·手',Icon='item_45276',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9503,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='从前，神从土中，创造了男人、又用男人的肋骨，创造了女人 。之后因为蛇的诱惑，人类失去了乐园，被流放到旷野。哥哥耕种土地，弟弟放牧羊群...一代又一代的诗人和哲学家在广场和礼堂的舞台上争论着：被称之为命运的事物是否存在。',Feature=1,LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,0.5,0},}",
  [45277] = "{id=45277,NameZh='笼子里的伊丽莎白',Icon='item_45277',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9505,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='“这是关于纯白少女的物语，也许部分被人遗忘，也许部分被人记得。提起他，每个人都有自己的回忆和想法，黑色和白色就像光与暗交织的童话，直到最后一个记录者也将其LOST的时候，物语本身还存在吗？”--------------《罪与罚的叹息》第九卷四十七章',Feature=1,LoadShowSize=2,LoadShowRotate=0,LoadShowPose={0,0.6,0},}",
  [45278] = "{id=45278,NameZh='疯帽子',Icon='item_45278',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9506,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='少女跟着兔子跳进去了洞中，在对面的那个世界，他遇到了一个重要的人，那位绅士正优雅地对着少女脱帽行礼。',Feature=1,LoadShowSize=2,LoadShowRotate=0,LoadShowPose={0,0.6,0},}",
  [45279] = "{id=45279,NameZh='学员帽',Icon='item_45279',Type=800,MaxNum=99,SellPrice=100,LoadShowSize=2,LoadShowRotate=0,LoadShowPose={0,0.9,0},}",
  [45280] = "{id=45280,NameZh='学士帽',Icon='item_45280',Type=800,MaxNum=99,SellPrice=100,AdventureSort=667,AdventureValue=90,StorageReward={buffid={80012390}},Condition=8,Desc='“时间过的真快，脸上显露出离别的神色，但新的邂逅很重要的对吧？所以只要看向前方轻松地出发吧！在宽广的道路上前进吧！”',Feature=1,LoadShowSize=2,LoadShowRotate=0,LoadShowPose={0,0.8,0},}",
  [45281] = "{id=45281,NameZh='黑魔女魔法帽',Icon='item_45281',Type=800,MaxNum=99,SellPrice=100,LoadShowSize=1,LoadShowRotate=-40,LoadShowPose={0,0.8,0},}",
  [45282] = "{id=45282,NameZh='蜂蜜蛋糕',Icon='item_45282',Type=800,MaxNum=99,SellPrice=100,LoadShowSize=2.5,LoadShowRotate=0,LoadShowPose={0,0.5,0},}",
  [45283] = "{id=45283,NameZh='金色的进行曲',Icon='item_45283',Type=840,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9507,AdventureValue=1,StorageReward={buffid={82000240}},Condition=8,Desc='时值初秋。贝尔佛第宫的仆人们正在忙着里外奔波，这里即将举行盛大的茶会。届时将有世界各地的贵妇人们身穿雍容华贵的服装佩戴着各种璀璨夺目的宝石前来参加这场盛宴，美学与美学的直接碰撞，在皇家仪仗队的鼓点声中，这场“演出”才刚开始。',Feature=1,LoadShowSize=1.5,LoadShowRotate=0,LoadShowPose={0,0.5,0},}",
  [45284] = "{id=45284,NameZh='致·爱丽丝',Icon='item_45284',Type=800,Quality=2,MaxNum=99,SellPrice=100,Desc='少年在整理曾祖母遗物的时候发现了一个尘封已久的小小古典木箱，时隔几个世纪后这部即将影响后人的作品再次沐浴在阳光下。世间人们早已无人知晓真正的故事，但是少年手上的那把钥匙依然刻着曾经的那段美丽的心愿。',LoadShowSize=1.5,LoadShowRotate=0,LoadShowPose={0,0.8,0},}",
  [45285] = "{id=45285,NameZh='夜后的咏叹调',Icon='item_45285',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9511,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='“亨切利~亨切利~哦，这小家伙又上哪里去了，让他好好整理乐谱书籍的事居然到现在都还没办！真是气死我了！”“亨切利，我和你说了多少次了，那个倒霉笨蛋音乐家的事你就别去管他了，见鬼~你有没有在听！这套叫《魔笛》的乐谱根本就没有销路，不要再练习了，回来搬书，我还有很多东西要你做！比如…”',Feature=1,LoadShowSize=2,LoadShowRotate=0,LoadShowPose={0,0.7,0},}",
  [45286] = "{id=45286,NameZh='月·光',Icon='item_45286',Type=800,Quality=2,MaxNum=99,SellPrice=100,Desc='【月光为桨，莲花作舟；皮埃罗向着南方顺风启程了。流水哼着深沉的曲调，摇晃着单薄的小船。月光为桨，莲花作舟。回贝加莫去，回故乡去，皮埃罗踏上了归途；看东方苍苍的地平线泛起了蒙蒙曙光。……月光为桨。】',LoadShowSize=1.5,LoadShowRotate=0,LoadShowPose={0,0.7,0},}",
  [45287] = "{id=45287,NameZh='小恶魔耳机',Icon='item_45287',Type=800,MaxNum=99,SellPrice=100,AdventureSort=9011,AdventureValue=80,StorageReward={buffid={80012430}},Condition=8,Desc='听说只有在每年特定的夜晚能从中听到来自某个恐怖派对的歌声。',Feature=1,LoadShowSize=2,LoadShowRotate=0,LoadShowPose={0,0.9,0},}",
  [45288] = "{id=45288,NameZh='南瓜发带',Icon='item_45288',Type=800,MaxNum=99,SellPrice=100,Feature=1,LoadShowSize=2.5,LoadShowRotate=0,LoadShowPose={0,0.6,0},}",
  [45289] = "{id=45289,NameZh='银月魔女的猫',Icon='item_45289',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9513,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='【“一年一度的恐怖盛宴，我们得以现身的夜晚；别遮遮藏藏，快把点心都拿出来，不然就等着我们的恶作剧吧~”----------最喜欢吃被子下露出的腿的德古拉】',Feature=1,LoadShowSize=2,LoadShowRotate=0,LoadShowPose={0,0.5,0},}",
  [45290] = "{id=45290,NameZh='不给糖就捣蛋',Icon='item_45290',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9515,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='糖果、饼干、马卡龙，果干、蛋糕、甜甜圈，草莓芭菲，蔷薇红茶，樱桃可乐...啊...等等...已经再也没有别的东西了...',Feature=1,LoadShowSize=2,LoadShowRotate=0,LoadShowPose={0,0.5,0},}",
  [45291] = "{id=45291,NameZh='勇者都怕我',Icon='item_45291',Type=800,Quality=2,MaxNum=99,SellPrice=100,Desc='经历了无数的辗转和颠簸，无数次的领土扩张，魔王终于拥有了自己的国度，以他的美学所定义的“自由”国度，即使没有了夜之少女的歌唱，依然有诗篇记录着这段历史-孑然一身独自君临着这个幻想国度的魔王。',LoadShowSize=3,LoadShowRotate=0,LoadShowPose={0.4,0.7,0},}",
  [45292] = "{id=45292,NameZh='甜蜜的死亡',Icon='item_45292',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9517,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='少女生前最爱的LOLIPOP，可爱而又甜蜜，直到47+18的闹（悲）剧发生，时间被定格3200000的最后一秒。“就是结束这一切，然后永别了”“一切都无法挽回了，感觉很不好。曾经快乐的事现在只觉得悲伤，我不会再爱了，我的末日已经来临““我希望能让一切都....”(最后几行字被策划抹去了。）',Feature=1,LoadShowSize=4,LoadShowRotate=0,LoadShowPose={0,1.2,0},}",
  [45293] = "{id=45293,NameZh='艾希头饰',Icon='item_45293',Type=800,MaxNum=99,SellPrice=100,Desc='艾希在无尽的轮回中，获得了真正的自我。时间空间流转，她，成为了旅人。',LoadShowSize=4,LoadShowRotate=0,LoadShowPose={0,1,0},}",
