  [45296] = "{id=45296,NameZh='英灵·亡者抉择（换色）(删除)',Icon='item_45296',Type=800,Quality=2,MaxNum=99,SellPrice=100,Desc='奥尔露恩代替英灵殿赐予冒险者的奖励，亡者抉择，象征着英灵殿之威严，同时也揭示着英灵殿的职责所在——为瓦尔哈拉殿堂挑选英勇的灵魂。',Feature=1,LoadShowSize=2,LoadShowRotate=-10,LoadShowPose={0,1,0},}",
