  [45299] = "{id=45299,NameZh='JingleBell',Icon='item_45299',Type=800,Quality=2,MaxNum=99,SellPrice=100,Desc='【叮叮当！叮叮当！铃儿响叮当，我们在敞篷雪橇上滑雪多快乐。冲破大风雪，我们坐在雪橇上。飞驰过田野，一直伴随着笑声。铃声儿响彻四方，我们情绪高涨，笑得多开心，雪橇之歌今夜唱。叮叮当，叮叮当，铃儿响叮当……】',LoadShowSize=1.5,LoadShowRotate=0,LoadShowPose={0,0.9,0},}",
  [45300] = "{id=45300,NameZh='宠物书包',Icon='item_47031',Type=810,MaxNum=99,SellPrice=100,ComposeID=14300,Desc='可以装任何东西的背包，装上物品后也可自由行动。',Feature=1,LoadShowSize=1.5,LoadShowRotate=130,LoadShowPose={0,0.9,0},}",
