  [45434] = "{id=45434,NameZh='普隆德拉的守护',Icon='item_45434',Type=800,MaxNum=99,SellPrice=100,Desc='“我真的很讨厌这里！”凯莉赌气地说道，“这里人声又嘈杂，每天到哪里都有穿着各种奇装异服的家伙假装要好心帮忙来勾搭！”，“…莫名其妙又把这个月探险经费都去购买了一堆没有用的帽子！每天都勾引我！每天都勾引我！”，“哼！我真的讨厌这里。”凯莉说着说着，生气的表情里流着眼泪开始笑了，她转过头去，此时一阵微风吹拂过首都广场中央的景观喷泉，将少女美丽的黑发悠然地抛向天空。嗯~这孩子，还真是喜欢这里呢！',LoadShowSize=1.5,LoadShowRotate=0,LoadShowPose={0,0.2,0},}",
  [45435] = "{id=45435,NameZh='爱的蛋糕',Icon='item_45435',Type=800,MaxNum=99,SellPrice=100,Desc='生日快乐，跟我一起闭上眼睛吧~然后在心中偷偷许下一个狡猾的心愿，也许你向我告白的那天，我会勉为其难地告诉你这个秘密呢~，然后，跟我一起蓄力3秒，“呼~~~”一起',LoadShowSize=2,LoadShowRotate=0,LoadShowPose={0,0.3,0},}",
