  [45466] = "{id=45466,NameZh='狐王的笑脸',Icon='item_45466',Type=800,MaxNum=99,SellPrice=100,ComposeID=14466,Desc='有一名樵夫曾在朔月的夜晚见过一只黝黑的狐狸，他看见那只狐狸对着月亮跪拜祈祷，他痴迷的看着这一幕，没注意到这只狐狸转头发现了他！那只狐狸满脸都是金色的花纹，咧着嘴巴对他嘻嘻地笑，眼睛里却是一片寒意……狐王的笑脸，看见的人会受到狐王的驱使，变为狐狸的奴隶！',LoadShowSize=3,LoadShowRotate=-50,LoadShowPose={-0.1,0.5,0},}",
  [45467] = "{id=45467,NameZh='汪汪上校',Icon='item_45467',Type=800,MaxNum=99,SellPrice=100,AdventureSort=10058,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,ComposeID=14467,Desc='非常帅气的上校制服帽！竖立的汪耳一看就威风凛凛英气十足的样子。',Feature=1,LoadShowSize=3,LoadShowRotate=0,LoadShowPose={0,0.6,0},}",
