  [45508] = "{id=45508,NameZh='冰镇企鹅',Icon='item_45508',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=20006,AdventureValue=110,StorageReward={buffid={80011850}},Condition=8,Desc='天气真是糟透了~！小企鹅吧唧跳到下一个人的头顶，努力吸取一丝新鲜的凉意。【设计者：殉情的夕阳】（非常感谢您的购买，这个美丽的饰品在活动贩售期间并不能在交易所流通，但在活动贩售结束后就能正常进入交易所啦~来自伊娜，于2017年8月）',Feature=1,LoadShowSize=3,LoadShowRotate=0,LoadShowPose={0,0.6,0},}",
