  [45534] = "{id=45534,NameZh='幻月樱·星光船',Icon='item_45534',Type=800,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={80012850}},Desc='“怀抱江中山河月，笑品世间朝午夜。”“花颜绝代 终飘零、现世何者 可长久。”浮世绘般的幻想月下，绽放的华丽画卷，风云怒涛海上舟，星光流连祈福世间，在这樱花之季降临。',Feature=1,LoadShowSize=2.8,LoadShowRotate=0,LoadShowPose={0,-0.5,0},}",
  [45535] = "{id=45535,NameZh='名物·千紫万红',Icon='item_45535',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012860}},Desc='遥远东方的天水之国，早在樱花城以及天津町落成前的时代，在传说中的歌舞伎所佩戴的头饰。因为饱含着千年风华的魅力，至今依然能感到佳人的芳踪。',Feature=1,LoadShowSize=3,LoadShowRotate=0,LoadShowPose={0.2,0.6,0},}",
