  [45543] = "{id=45543,NameZh='要迟到啦！',Icon='item_45543',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012860}},Desc='可以是魔咒，也可以是战歌，是最高神圣天庭的最终审判，也是向美好世界献上祝福的前奏曲。在这思考的24.07秒时间内，你最后还是决定起床，换上母亲新洗过的制服，那上面还有阳光的味道。',Feature=1,LoadShowSize=4,LoadShowRotate=0,LoadShowPose={0,-0.3,0},}",
