  [45582] = "{id=45582,NameZh='大地魔女帽',Icon='item_45582',Type=800,Quality=2,MaxNum=99,SellPrice=100,Desc='因散发着典雅的气息而在年轻魔女中颇受欢迎，流传着“要是戴上它，含苞欲放的花朵会在你身边提前绽放。”的传说',LoadShowSize=2,LoadShowRotate=10,LoadShowPose={-0.1,0.5,0},MainColor='56291eFF',}",
  [45583] = "{id=45583,NameZh='猩红巫师帽',Icon='item_45583',Type=800,Quality=2,MaxNum=99,SellPrice=100,Desc='宽大的帽檐下魔力暗流汹涌，戴上时仿佛有某个声音在耳畔轻轻低语，“来吧，用你的魔力让这猩红绽放...”',LoadShowSize=2.5,LoadShowRotate=10,LoadShowPose={-0.1,0.5,0},MainColor='870c0cFF',}",
