  [45587] = "{id=45587,NameZh='大吉大利桶',Icon='item_45587',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10067,AdventureValue=80,AdventureReward={buffid={61000760}},StorageReward={buffid={80012910}},Condition=4,ComposeID=14587,Desc='能一个人吃完整整一个大吉大利桶也是勇气的证明呢！亲爱的冒险者快戴上它吧！',Share=1,Feature=1,LoadShowSize=3,LoadShowRotate=10,LoadShowPose={0,0,0},}",
  [45588] = "{id=45588,NameZh='熊猫和波利的竹子',Icon='item_45588',Type=800,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80012870}},Desc='“出生于1997年的小菲，平常最喜欢做的事之一就是打开在航天局工作的父亲所赠送的小平板，看着童年时父亲一直带他去看的熊猫小盼，看着小盼优雅啃着竹子然后睡去再醒来，一个假日很快就度过了。真希望父亲能早日回来陪我玩~”',LoadShowSize=6,LoadShowRotate=10,LoadShowPose={0,0,0},}",
  [45589] = "{id=45589,NameZh='金字塔的谜题',Icon='item_45589',Type=800,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80012810}},Desc='将【生】与【死】编译成【幻想游戏】，承载着数千年的人之两面。见证着死灵之书、戏弄着俄狄浦斯王、迎接着迁徙者的面纱。这个蓝色星球上最大的魔方里究竟还富藏着多少深邃的奥秘呢？',LoadShowSize=4,LoadShowRotate=-15,LoadShowPose={0,0.3,0},}",
  [45590] = "{id=45590,NameZh='东京铁塔之恋',Icon='item_45590',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012660}},Desc='我爱上一盏街灯，我爱上一种余温。而我爱上某一个人，爱上那诱人的香氛。在异国铁塔的观光层，我痴情期待着你的吻。',LoadShowSize=4,LoadShowRotate=-15,LoadShowPose={0,-0.1,0},}",
  [45591] = "{id=45591,NameZh='冒险火车头',Icon='item_45591',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9020,AdventureValue=80,StorageReward={buffid={80012640}},Condition=8,Desc='蒸汽机的发明让承载的梦想可以更快地前往更多更遥远的地方。在这样的春分时节里，背着波利一起去旅行吧。沿途所见的美丽风景，若是能将那些写成诗篇记录下来，是否可以传达给最爱的你那里呢～～～',LoadShowSize=5,LoadShowRotate=-45,LoadShowPose={0,0.1,0},}",
  [45592] = "{id=45592,NameZh='愤怒的撒旦',Icon='item_45592',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=15021,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='这是恶魔之王的女儿朱莉安的皇冠，因为朱莉安长得太过天真无邪，恶魔之王担心她统领不了恶魔之国，特地派人为她打造了这个看起来很不好惹的皇冠，并给予了这个皇冠听起来也很不好惹的名字“愤怒的撒旦”。',LoadShowSize=3,LoadShowRotate=-18,LoadShowPose={0,0.6,0},}",
  [45593] = "{id=45593,NameZh='热带椰子',Icon='item_45593',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9023,AdventureValue=80,StorageReward={buffid={80012640}},Condition=8,Desc='海边的椰子小贩们相信，戴上这款头饰，会让人提升财运~~',LoadShowSize=3,LoadShowRotate=-18,LoadShowPose={0,0.5,0},}",
