  [45643] = "{id=45643,NameZh='飞天猫仔帽',Icon='item_45643',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=802,AdventureValue=80,AdventureReward={buffid={61001100}},StorageReward={buffid={80012920}},Condition=4,ComposeID=14643,Desc='伟大机匠察尔伊森养了一只调皮的猫，那只猫曾偷偷用他的机甲飞上了天空，为了纪念这件有趣的事情，察尔伊森托人制作了这款为猫订制的飞行帽。',LoadShowSize=2.5,LoadShowRotate=-15,LoadShowPose={0,0.8,0},}",
  [45644] = "{id=45644,NameZh='护林小队帽',Icon='item_45644',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=803,AdventureValue=80,AdventureReward={buffid={61001100}},StorageReward={buffid={80012920}},Condition=4,ComposeID=14644,Desc='斐扬护林队毕生致力于抓捕非法伐木者，而这顶帽子就是护林队成员自豪的象征。',LoadShowSize=2.5,LoadShowRotate=-90,LoadShowPose={0,0.4,0},}",
