  [45822] = "{id=45822,NameZh='控偶师之手',Icon='item_45276',Type=800,Quality=3,MaxNum=99,SellPrice=100,Desc='从前，神从土中，创造了男人、又用男人的肋骨，创造了女人 。之后因为蛇的诱惑，人类失去了乐园，被流放到旷野。哥哥耕种土地，弟弟放牧羊群...一代又一代的诗人和哲学家在广场和礼堂的舞台上争论着：被称之为命运的事物是否存在。',Feature=1,LoadShowSize=2,LoadShowRotate=0,LoadShowPose={0,0.1,0},}",
  [45823] = "{id=45823,NameZh='笼中的伊丽莎白',Icon='item_45277',Type=800,Quality=3,MaxNum=99,SellPrice=100,Desc='“这是关于纯白少女的物语，也许部分被人遗忘，也许部分被人记得。提起他，每个人都有自己的回忆和想法，黑色和白色就像光与暗交织的童话，直到最后一个记录者也将其LOST的时候，物语本身还存在吗？”--------------《罪与罚的叹息》第九卷四十七章',Feature=1,LoadShowSize=2.5,LoadShowPose={0,0.5,0},}",
  [45824] = "{id=45824,NameZh='疯帽子之礼',Icon='item_45278',Type=800,Quality=3,MaxNum=99,SellPrice=100,Desc='少女跟着兔子跳进去了洞中，在对面的那个世界，他遇到了一个重要的人，那位绅士正优雅地对着少女脱帽行礼。',Feature=1,LoadShowSize=3,LoadShowRotate=20,LoadShowPose={0,0.5,0},}",
