  [45837] = "{id=45837,NameZh='悲伤召唤师头饰',Icon='item_45837',Type=800,MaxNum=99,SellPrice=100,ComposeID=14837,Desc='用骷髅作为装饰的魔女尖帽，散发着悲伤的气息，这顶帽子的主人，究竟拥有着怎样的过往呢？',Feature=1,LoadShowSize=3,LoadShowPose={0,0.5,0},}",
  [45838] = "{id=45838,NameZh='血色红帽',Icon='item_45838',Type=800,MaxNum=99,SellPrice=100,ComposeID=14838,Desc='曾经有一名叫做罗夏薇拉的女孩惨遭狼外婆毒害，这顶血色红帽，是她曾经最喜欢的东西......',Feature=1,LoadShowSize=3,LoadShowRotate=20,LoadShowPose={0,1,0},}",
  [45839] = "{id=45839,NameZh='招魂蜡烛',Icon='item_45839',Type=800,MaxNum=99,SellPrice=100,ComposeID=14839,Desc='墓碑怪人头顶的蜡烛，散发着幽蓝的火光，据说只要把它顶在头上，就会招来一些不可名状的东西......',Feature=1,LoadShowSize=3.7,}",
  [45840] = "{id=45840,NameZh='乌鸦头饰',Icon='item_45840',Type=800,MaxNum=99,SellPrice=100,ComposeID=14840,Desc='戴上它，稻草人就会把你当作好朋友，甚至和你分享它的心路历程。',Feature=1,LoadShowSize=3.7,LoadShowRotate=20,LoadShowPose={0,0.4,0},}",
  [45841] = "{id=45841,NameZh='趴趴鬼娃',Icon='item_45841',Type=800,MaxNum=99,SellPrice=100,ComposeID=14841,Desc='这个坏脾气的小家伙可不好对付，要是你惹她生气了，她就会把你精心梳理一早上的发型毫不客气地弄乱，我新弄的移花接木发型就是这样被摧毁的！',Feature=1,LoadShowSize=3.7,LoadShowRotate=-20,LoadShowPose={0,0.4,0},}",
  [45842] = "{id=45842,NameZh='无颅武士头盔',Icon='item_45842',Type=800,MaxNum=99,SellPrice=100,ComposeID=14842,Desc='无颅武士所穿戴的头盔，不知道为何，一戴上它就感觉脑袋空空的，变得呆萌健忘。',Feature=1,LoadShowSize=2.5,LoadShowRotate=20,LoadShowPose={0,0.7,0},}",
  [45843] = "{id=45843,NameZh='万圣节灯笼',Icon='item_45843',Type=800,MaxNum=99,SellPrice=100,ComposeID=14843,Desc='用南瓜公爵庄园的优质南瓜制作而成，增添恐怖气氛的绝佳选择！',Feature=1,LoadShowSize=3,LoadShowRotate=10,LoadShowPose={0,0.3,0},}",
  [45844] = "{id=45844,NameZh='诅咒兔娃',Icon='item_45844',Type=800,MaxNum=99,SellPrice=100,ComposeID=14844,Desc='带着诡异气息的兔子玩偶，不知为何，每天早上它都不在原本的位置上......呋嘿嘿，兔兔这么可爱，怎么可能会做坏事呢？',Feature=1,LoadShowSize=3.2,LoadShowPose={0,0.4,0},}",
  [45845] = "{id=45845,NameZh='魔月发夹',Icon='item_45845',Type=800,MaxNum=99,SellPrice=100,ComposeID=14845,Desc='银月魔女的发卡，据说是古老月神的遗物之一，据说，要是在月光下戴上它，就能获得月之魔法的古老祈福。',Feature=1,LoadShowSize=5,LoadShowRotate=-80,LoadShowPose={0,1.2,0},}",
  [45846] = "{id=45846,NameZh='白骑士头盔',Icon='item_45846',Type=800,MaxNum=99,SellPrice=100,ComposeID=14846,Desc='在死灵骑士尚未疯狂前，他曾是克雷斯特汉姆白骑士团的一员，从这个白骑士头盔上，仿佛可以依稀窥见他辉煌的过往。人是会变的，不是么？',Feature=1,LoadShowSize=2.5,LoadShowPose={0,0.8,0},}",
  [45847] = "{id=45847,NameZh='喀秋莎缎带',Icon='item_45847',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=15054,AdventureValue=1,AdventureReward={buffid={61001110}},StorageReward={buffid={80012640}},Condition=8,Desc='米德加尔特少女偶像喀秋莎舞台表演时所用的头饰~！只有女孩子才可以戴哟！',LoadShowSize=4,LoadShowPose={0,0.7,0},}",
  [45848] = "{id=45848,NameZh='斯特里戈伊的预言',Icon='item_45848',Type=800,MaxNum=99,SellPrice=100,Desc='凶兆的预言者——斯特里戈伊的头冠。他曾在黄昏垂落之际，望着远方的阿斯加德流下泪水。',Feature=1,LoadShowSize=3,LoadShowPose={0,0.5,0},}",
  [45849] = "{id=45849,NameZh='超强力蚊香圈',Icon='item_45849',Type=800,MaxNum=99,SellPrice=100,AdventureSort=813,AdventureValue=60,AdventureReward={buffid={61001310}},StorageReward={buffid={80013070}},Condition=4,ComposeID=14849,Desc='普通的蚊香顶多只能毒死蚊子，但这盘蚊香连人都能毒死——所以至今也没人敢点着它睡觉。',Feature=1,LoadShowSize=3,}",
  [45850] = "{id=45850,NameZh='害羞咬咬鲨',Icon='item_45850',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=815,AdventureValue=150,AdventureReward={buffid={61000590}},StorageReward={buffid={80012630}},Condition=4,ComposeID=14850,Desc='“人家害羞啦~所以~你自己把头伸过来~就给人家咬一下好不好啦~”',Feature=1,LoadShowSize=3,LoadShowRotate=30,LoadShowPose={0,0.7,0},}",
  [45851] = "{id=45851,NameZh='万国预言书',Icon='item_45851',Type=800,MaxNum=99,SellPrice=100,Feature=1,LoadShowSize=3,LoadShowPose={0,0.2,0},}",
  [45852] = "{id=45852,NameZh='绿色头绳',Icon='item_45852',Type=800,MaxNum=99,SellPrice=100,AdventureSort=7060,AdventureValue=30,AdventureReward={buffid={61001310}},StorageReward={buffid={80013070}},Condition=4,ComposeID=14852,Desc='“我觉得这个发带很适合你。”“真的么？”微风拂过，女孩子头顶的蝴蝶结害羞的抖了抖翅膀。',Feature=1,LoadShowSize=3,LoadShowPose={0,0.7,0},}",
  [45853] = "{id=45853,NameZh='星夜蝴蝶发带',Icon='item_45853',Type=800,MaxNum=99,SellPrice=100,AdventureSort=817,AdventureValue=60,AdventureReward={buffid={61001310}},StorageReward={buffid={80013070}},Condition=4,ComposeID=14853,Desc='在繁星灿烂的夜晚，这枚发带会幻化为一只黑色的蝴蝶飞走，待到第二天清晨，它会回到主人的肩膀，变回黑色的发带。',Feature=1,LoadShowSize=3,LoadShowRotate=180,LoadShowPose={0,0.7,0},}",
  [45854] = "{id=45854,NameZh='梳子',Icon='item_45854',Type=800,MaxNum=99,SellPrice=100,AdventureSort=7061,AdventureValue=30,AdventureReward={buffid={61001310}},StorageReward={buffid={80013070}},Condition=4,ComposeID=14854,Desc='由百年红木所制，使用后可以防止脱发，是拼搏在一线的冒险者们的必备之梳。',Feature=1,LoadShowSize=4.5,LoadShowPose={-0.2,0.7,0},}",
  [45855] = "{id=45855,NameZh='天线头饰',Icon='item_45855',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7062,AdventureValue=80,AdventureReward={buffid={61000860}},StorageReward={buffid={80012640}},Condition=4,ComposeID=14855,Desc='“滋……滋滋……滋滋滋……”信号接收良好，天气情况正常，三，二，一，起飞！',Feature=1,LoadShowSize=4.5,LoadShowRotate=15,LoadShowPose={0,0.5,0},}",
  [45856] = "{id=45856,NameZh='风之旅人',Icon='item_45856',Type=800,MaxNum=99,SellPrice=100,Desc='据说是诗歌之神布莱奇佩戴过的帽子，蕴含着风的力量。戴上它，不管是多遥远的地方都能一夜之间到达。',Feature=1,LoadShowSize=2.8,LoadShowPose={0,0.5,0},}",
  [45857] = "{id=45857,NameZh='男友招募广告牌',Icon='item_45857',Type=800,MaxNum=99,SellPrice=100,Feature=1,LoadShowSize=1.7,}",
  [45858] = "{id=45858,NameZh='啵扭糖果袋',Icon='item_45858',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=812,AdventureValue=150,AdventureReward={buffid={61000590}},StorageReward={buffid={80012840}},Condition=4,ComposeID=14858,Desc='袋子里的糖果一边跳动一边发出啵扭啵扭的声音，死者之都的居民习惯叫它跳跳糖…等等，他们对跳跳糖是不是有什么误解？！',Feature=1,LoadShowSize=3.5,LoadShowPose={0,0.2,0},}",
  [45859] = "{id=45859,NameZh='星之轮·曜夜',Icon='item_45859',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52022,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='速度超越星光的魔法扫帚，骑上它就可以飞跃天际，是安黛拉的得意之作。这一把凝固着恶魔的紫，只有被选中的人才能拥有它。',Feature=1,}",
  [45860] = "{id=45860,NameZh='巫婆黑帽',Icon='item_45860',Type=800,MaxNum=99,SellPrice=100,Feature=1,LoadShowSize=2,LoadShowPose={0,0.4,0},}",
  [45861] = "{id=45861,NameZh='诅咒信件',Icon='item_45861',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7066,AdventureValue=120,AdventureReward={buffid={61001130}},StorageReward={buffid={80012660}},Condition=4,ComposeID=14861,Desc='“你的灵魂，就由我收下了！”看到这句话时千万不要以为它只是玩笑，毕竟信件的前几任主人都遭遇了不测，你能确定你就是那个幸运儿么？',Feature=1,LoadShowSize=3,LoadShowPose={0,0.5,0},}",
  [45862] = "{id=45862,NameZh='蝙蝠小礼帽',Icon='item_45862',Type=800,Quality=3,MaxNum=99,SellPrice=100,Desc='数万年前，蝙蝠一族被称[Fangire]，是十三魔族中的君临顶点的最强种族……然而现在这群小蝙蝠只能卖卖萌。',Feature=1,LoadShowSize=3.2,LoadShowRotate=-40,LoadShowPose={0,0.5,0},}",
  [45863] = "{id=45863,NameZh='丧气南瓜灯',Icon='item_45863',Type=800,Quality=3,MaxNum=99,SellPrice=100,Desc='看什么看？没看过忧郁系的南瓜么？',Feature=1,LoadShowSize=3.2,LoadShowPose={0,1,0},}",
  [45864] = "{id=45864,NameZh='通灵者头饰',Icon='item_45864',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=826,AdventureValue=210,AdventureReward={buffid={61001090}},StorageReward={buffid={80012930}},Condition=4,ComposeID=14864,Desc='无形的灵啊，飘逝的灵啊，请以你的方式回应我的呼唤吧，我知道你们就在这里，就在我的身边。',Feature=1,LoadShowSize=3.2,LoadShowPose={0,0.5,0},}",
  [45865] = "{id=45865,NameZh='宫廷乐师帽',Icon='item_45865',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=824,AdventureValue=210,AdventureReward={buffid={61001090}},StorageReward={buffid={80012930}},Condition=4,ComposeID=14865,Desc='“这位朋友，请你对我的帽子放尊重点，我可是高贵的宫廷乐师。”——被误认为是海盗的新人乐师',Feature=1,LoadShowSize=2.5,LoadShowPose={0,0.5,0},}",
  [45866] = "{id=45866,NameZh='濒死的天鹅',Icon='item_45866',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=825,AdventureValue=210,AdventureReward={buffid={61001090}},StorageReward={buffid={80012930}},Condition=4,ComposeID=14866,Desc='天鹅在死前的一刻，会用尽全身力气伸出脖子，张开美丽的双翼，舞者们从此获得灵感，将这个凄美的动作融入了名为芭蕾的舞蹈。',Feature=1,LoadShowSize=5,}",
  [45867] = "{id=45867,NameZh='海拉的翼盔',Icon='item_45867',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7020,AdventureValue=1,StorageReward={buffid={80012640}},Condition=4,ComposeID=14867,Desc='这个长着犄角的头盔是尼夫海姆的先锋产品之一，凶悍高冷的外形让人联想到令人敬畏的死亡女神海拉，一戴上它，你的周围就会出现一个冷冽的气场！',Feature=1,LoadShowSize=2.8,LoadShowPose={0,0.9,0},}",
  [45868] = "{id=45868,NameZh='假日企鹅',Icon='item_45507',Type=800,Quality=3,MaxNum=99,SellPrice=100,Desc='悠闲说的就是这个炎炎夏日中的这只企鹅，当你躺地板的时候，他当然不会只是傻傻地站着。',Feature=1,LoadShowSize=2.3,LoadShowPose={1,0.7,0},}",
