  [45881] = "{id=45881,NameZh='月骑士头盔',Icon='item_45881',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=15067,AdventureValue=1,AdventureReward={buffid={61000590}},StorageReward={buffid={80012640}},Condition=8,ComposeID=14881,Desc='暗月魔法团的守护者们会被赋予“月骑士”的称号，只要月骑士戴上这附有月之魔力的头盔，无论身处何方，温柔的月光总会映照在月骑士的身上。',Feature=1,LoadShowSize=2.5,LoadShowRotate=20,LoadShowPose={0,0.6,0},}",
  [45882] = "{id=45882,NameZh='为所欲为',Icon='item_45882',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012640}},Desc='一蹶不振，百口莫辯，千夫所指，萬念俱灰，當殘酷世界已容不下渺小的你，七彩霓虹的煞氣造型讓你看到彩色人生。By 設計師冒死推出的新作',Feature=1,LoadShowSize=3,LoadShowPose={0,0.3,0},}",
  [45883] = "{id=45883,NameZh='「cama cafe」Beano',Icon='item_45883',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012640}},Desc='圓潤微笑的Beano是咖啡豆精靈的化身，胸前別著象徵專業的領結，手上則端著新鮮現烘的飄香咖啡。',Feature=1,LoadShowSize=4,LoadShowRotate=20,LoadShowPose={0,0.3,0},}",
  [45884] = "{id=45884,NameZh='死灵头巾',Icon='item_45884',Type=800,MaxNum=99,SellPrice=100,Desc='死灵亲手设计的头巾，要不是他已经死了，艾尔帕兰的时尚杂志一定给他开一个头饰搭配专栏。',Feature=1,LoadShowSize=2.5,LoadShowPose={0,0.5,0},}",
  [45885] = "{id=45885,NameZh='凯美拉帽',Icon='item_45885',Type=800,MaxNum=99,SellPrice=100,Desc='知道凯美拉为啥面无表情么？因为它尾巴上的小蛇们帮他分担了所有表情，魔物们私下里都称呼凯美拉为行走的表情之王。',Feature=1,LoadShowSize=3,LoadShowPose={0,0.7,0},}",
  [45886] = "{id=45886,NameZh='绅士礼帽',Icon='item_45886',Type=800,MaxNum=99,SellPrice=100,Desc='戴上它然后让你的小伙伴们跟在你的身后，友谊的小火车就“逛吃逛吃”的开起来啦，呜呜呜~',Feature=1,LoadShowSize=4,LoadShowPose={0,0.3,0},}",
  [45887] = "{id=45887,NameZh='打更猫',Icon='item_45887',Type=800,MaxNum=99,SellPrice=100,Desc='天干物燥，小心火烛！不听话的孩子当心被月夜猫抓去做猫粮哦！',Feature=1,LoadShowSize=4,LoadShowPose={0,0.2,0},}",
  [45888] = "{id=45888,NameZh='传说翼盔',Icon='item_45888',Type=800,MaxNum=99,SellPrice=100,Desc='你的传说会留在米德加尔特的历史上，这顶翼盔便是传说级别强者的象征！',Feature=1,LoadShowSize=3.5,LoadShowRotate=20,LoadShowPose={0,0.7,0},}",
  [45889] = "{id=45889,NameZh='薇格的女巫帽',Icon='item_45889',Type=800,MaxNum=99,SellPrice=100,AdventureSort=7019,AdventureValue=1,AdventureReward={buffid={61000590}},StorageReward={buffid={80012640}},Condition=8,Desc='这顶女巫帽上有果汁和太妃糖的气味，看起来它的主人一定是个甜食爱好者。',Feature=1,LoadShowSize=2.5,LoadShowPose={0,0.6,0},}",
  [45890] = "{id=45890,NameZh='史汀指挥家',Icon='item_45890',Type=800,Quality=3,MaxNum=99,SellPrice=100,Desc='作为指挥家的史汀先生需要站得再高一点，嗯，你的头顶看起来视野不错！波利号手跟上节奏，溜溜猴乐团不许偷懒！大家都跟上史汀先生的指挥棒一起加入这场音乐狂欢！',Feature=1,LoadShowSize=2.5,LoadShowPose={0,-0.1,0},}",
  [45891] = "{id=45891,NameZh='兔兔耳机',Icon='item_45891',Type=800,Quality=2,MaxNum=99,SellPrice=100,Desc='来自里希塔乐的最新高科技耳机，外形采用了兔兔耳朵的设计，深受年轻女孩们的青睐，让我们戴上它一起咚次哒次胡萝卜！！！呜~不要在我听歌的时候捏我的耳朵啦~',Feature=1,LoadShowSize=2.5,LoadShowPose={0,0.5,0},}",
  [45892] = "{id=45892,NameZh='波利号手',Icon='item_45892',Type=800,Quality=2,MaxNum=99,SellPrice=100,Desc='波利也想来参加热闹的音乐节？随时欢迎！波利号手噗扭噗扭跳上了头顶，吹奏起呼朋唤友的集结号！',Feature=1,LoadShowSize=2.5,}",
