  [45942] = "{id=45942,NameZh='大象头饰',Icon='item_45942',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=15070,AdventureValue=1,AdventureReward={buffid={61000590}},StorageReward={buffid={80012640}},Condition=8,Desc='大象善解人意、勤劳能干、聪慧、富有灵性，是尊贵和力量的象征。',StageDisplay=0,LoadShowSize=3.2,LoadShowPose={0,0.6,0},}",
  [45943] = "{id=45943,NameZh='星球陨落',Icon='item_45518',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,ComposeID=14943,Desc='摘下月亮给你，摘下太阳给你，你想要我都给你，摘下星星给你，你想要我都给你。',Feature=1,LoadShowSize=3.2,LoadShowPose={0,-0.4,0},}",
  [45944] = "{id=45944,NameZh='亥头巾',Icon='item_45944',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10126,AdventureValue=80,AdventureReward={buffid={61000590}},StorageReward={buffid={80012640}},Condition=4,ComposeID=14944,Desc='可不要小看这个小猪头饰哦！只要戴上它，接下来的一整个亥年都会万事顺心哦！嘘！小声点，这个秘密我只告诉你一个人！',Feature=1,TFValidDate='2019-01-24 05:00:00',ValidDate='2019-01-31 05:00:00',}",
  [45945] = "{id=45945,NameZh='荆棘玫瑰',Icon='item_45945',Type=800,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='魔女摘下玫瑰变为礼帽，亲手为恋人戴上。“你若移情别恋，它便会化作荆棘，刺穿你心。”',TFValidDate='2018-10-16 05:00:00',ValidDate='2018-10-18 05:00:00',StageDisplay=1,}",
