  [45955] = "{id=45955,NameZh='圣诞之歌',Icon='item_45955',Type=800,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10099,AdventureValue=110,AdventureReward={buffid={61001170}},StorageReward={buffid={80013060}},Condition=4,ComposeID=14955,Desc='铃铃铛，铃铃铛，铃儿响叮当~寓意着幸福和美好的圣诞树永远沐浴在十二月的圣歌之中…',Feature=1,}",
  [45956] = "{id=45956,NameZh='萌萌驯鹿角',Icon='item_45956',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10100,AdventureValue=80,AdventureReward={buffid={61000590}},StorageReward={buffid={80012640}},Condition=4,ComposeID=14956,Desc='长长的鹿角，大大的眼，红红的鼻子，毛绒绒的脸，可爱小驯鹿永远是圣诞老公公的得力助手！',Feature=1,}",
