  [45959] = "{id=45959,NameZh='玉藻前之耳',Icon='item_45959',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15106,AdventureValue=1,StorageReward={buffid={80012930}},Condition=8,Desc='传说在天津町，有一座仙气环绕的灵山，山中住着一只名为玉藻前的大妖怪。她的本体是一只修行千年的白面金毛九尾狐。原本，玉藻前在灵山中过着饮酒赏樱的潇洒生活，直到一位人类婴儿的啼哭打破了这份平静。她决定收养这个被遗弃男孩作为养子，取名百鬼丸。',Feature=1,TFValidDate='2018-11-13 05:00:00',ValidDate='2018-11-15 05:00:00',}",
  [45960] = "{id=45960,NameZh='天狗假面',Icon='item_45960',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15107,AdventureValue=1,StorageReward={buffid={80012920}},Condition=8,Desc='在天津町的传说中，天狗长着长长的鼻子，穿着宽大的僧服，脚踏高齿木屐，手持团扇与宝槌。作为独霸一方的大妖怪，仙山的地盘逐渐不能满足他的贪婪，他带领着邪恶的妖怪爪牙入侵了天水之国。最终被伊达晴子与百鬼丸联手击败，封印了起来。在如今的天津町，能剧中的天狗面具象征着贪婪的丑角。',Feature=1,TFValidDate='2018-11-13 05:00:00',ValidDate='2018-11-15 05:00:00',}",
