  [47021] = "{id=47021,NameZh='黑猫雷蒙盖顿',Icon='item_47021',Type=810,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=2040,AdventureSort=5004,AdventureValue=200,AdventureReward={buffid={60000030}},StorageReward={buffid={80011170}},Condition=2,Desc='天哪！背上这个充满贵族皇家气质的玩偶，感觉整个人都升华了一样！这雍容华丽的手感，每天摸着它都能笑着睡去。',Share=1,Feature=1,LoadShowSize=1.8,LoadShowRotate=180,LoadShowPose={0,0.4,0},}",
  [47022] = "{id=47022,NameZh='喷射哥布灵背包',Icon='item_47022',Type=810,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=2040,AdventureSort=10009,AdventureValue=1,AdventureReward={buffid={60001960}},StorageReward={buffid={80011110}},Condition=4,ComposeID=16022,Desc='圈绕在条盒内的是发条，主传动齿轮采用了圆弧齿形，点火后动听的机械声轰轰作响，就是那么带感！就是那么科技！就是那么骄傲！',Feature=1,LoadShowSize=1.5,LoadShowRotate=180,}",
