  [47048] = "{id=47048,NameZh='琉璃雪人号角',Icon='item_47048',Type=810,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4060,AdventureSort=10041,AdventureValue=440,AdventureReward={buffid={61000490}},StorageReward={buffid={80012650}},Condition=4,ComposeID=16048,Share=1,Feature=1,LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,0,0},}",
  [47049] = "{id=47049,NameZh='勿忘初心·波利气球',Icon='item_47049',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9526,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='“这是我们作为冒险者踏上这片广袤幻想大陆所乘坐的第一个飞行仪器，在高空俯瞰整个【河滨】，是如此的宁静和绿意盎然，人们熙熙攘攘地穿梭着，如同沙盘上的旗帜，向着名为探索的彼岸前行。音乐再次响起，我们约定了，来年也要在这个时候一起鸟瞰风景，那用言语无法形容的景色，当然，我的身边依然有你，纯真的笑颜。”',Share=1,Feature=1,LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,0,0},}",
  [47050] = "{id=47050,NameZh='兔兔背包',Icon='item_47050',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9013,AdventureValue=80,StorageReward={buffid={80012800}},Condition=8,Desc='在遥远的东方国度，全新的一年到来之时父母会亲手制作一个送给自己的孩子们，不仅是祈求神明的庇佑，并且希望在少年少女们的未来航路上，能成为他们装载回忆的背包。',Share=1,Feature=1,LoadShowSize=1.5,LoadShowRotate=0,LoadShowPose={0,0.2,0},}",
  [47051] = "{id=47051,NameZh='米德加尔特行军背包',Icon='item_47051',Type=810,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=52004,AdventureValue=240,StorageReward={buffid={80012820}},Condition=8,Share=1,Feature=1,LoadShowSize=2,LoadShowRotate=0,LoadShowPose={0,0.4,0},}",
  [47052] = "{id=47052,NameZh='甜甜圈猫包',Icon='item_47052',Type=810,MaxNum=99,SellPrice=100,AdventureSort=10049,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='猫奴必备“背”带上主子和口粮出发去冒险！【作者：跌倒的西瓜汁】',Share=1,Feature=1,LoadShowSize=2,LoadShowRotate=0,LoadShowPose={0,0.3,0},}",
  [47053] = "{id=47053,NameZh='黑暗料理包裹',Icon='item_47053',Type=810,MaxNum=99,SellPrice=100,AdventureSort=10053,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='黑暗料理包裹是每一个黑暗料理师都梦寐以求的装备。铁匠运用尼伯龙根打造的黑暗炒锅，融合了炼金术师的秘药和刺客的毒药，插着那把传说中被称为“尾”的刀，还有一面代表黑暗料理的帆旗。【作者：CrazyRyo】',Share=1,Feature=1,LoadShowSize=1.5,LoadShowRotate=0,LoadShowPose={0,0,0},}",
  [47054] = "{id=47054,NameZh='恶兽腔膛',Icon='item_47054',Type=810,MaxNum=99,SellPrice=100,LoadShowSize=1.5,LoadShowRotate=0,LoadShowPose={0,0.2,0},}",
  [47055] = "{id=47055,NameZh='【年】',Icon='item_47055',Type=810,MaxNum=99,SellPrice=100,AdventureSort=10056,AdventureValue=1,AdventureReward={buffid={61000470}},StorageReward={buffid={80012810}},Condition=4,ComposeID=16055,Desc='仿造春节才会出现的年兽而制作的背包，栩栩如生。',Feature=1,LoadShowSize=1.5,LoadShowRotate=0,LoadShowPose={0,0.2,0},}",
  [47056] = "{id=47056,NameZh='守护爱的女神',Icon='item_47056',Type=810,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9531,AdventureValue=1,StorageReward={buffid={82000240}},Condition=8,Desc='爱神之箭在天空穿行，而真正串联起人与人之心的还是那纯洁无垢的思念和心意。春观夜樱、夏赏雨荷、秋望雏菊、冬守香梅。时光之轮转动不停，女神并没有刻意为人们链接上红色丝带，而是一直默默地守护着人们的善良美丽的心。',Feature=1,LoadShowSize=1.5,LoadShowRotate=0,LoadShowPose={0,0,0},}",
  [47057] = "{id=47057,NameZh='樱偶',Icon='item_47057',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=764,AdventureValue=310,AdventureReward={buffid={61000470}},StorageReward={buffid={80012810}},Condition=4,ComposeID=16057,Desc='天水之国有一个美丽的传说，一名善良的樱之灵爱上了一个普通的人类男孩。为了治疗男孩的疾病，樱之灵将自己的灵力输送给男孩，拯救了他的生命，而自己却失去所有的灵力，化为落樱，随风而去。可怜的男孩只能按照自己的记忆，将樱之灵的模样制作成玩偶……从此天水之国就多了一个可爱的娃娃，也多了一段凄美的爱情故事。',LoadShowSize=1.5,LoadShowRotate=0,LoadShowPose={0,0,0},}",
  [47058] = "{id=47058,NameZh='瑟瑟发抖·小恶魔',Icon='item_47058',Type=810,MaxNum=99,SellPrice=100,AdventureSort=10057,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='不……不好啦！为了对抗年兽，居然要把小恶魔绑在烟花上祭天，为了爱与正义的邪恶（？）救救小恶魔吧！',Feature=1,LoadShowSize=1.5,LoadShowRotate=0,LoadShowPose={0,0.3,0},}",
  [47059] = "{id=47059,NameZh='名刀·神宫雪&千夜樱',Icon='item_47059',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9538,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='传说中的东方知名工匠生前所锻造的优雅的双子太刀，不但拥有优美华丽的纹路，并且有目击者称：佩戴者本身的动作会变得宛如樱花般轻盈潇洒。',Feature=1,LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,0.3,0},}",
  [47060] = "{id=47060,NameZh='轻音社社长',Icon='item_47060',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9546,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='终于下课了！背起快有自己身高的琴包，用最醇熟的走位闪避过那些讨厌的辣妹，再绕开那些放学就要去现充的情侣，然后发动长久练习而得心应手的无声蹲步走潜过教导主任的办公室，前方就是少女的目的地了！那里是乐园！学妹们都在期待着我今天带领他们演奏的新曲目！没错，我，我就是轻音社社长呢~',Feature=1,LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,0.2,0},}",
  [47061] = "{id=47061,NameZh='学之霸者',Icon='item_47061',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9548,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='“好了，步野同学，事到如今，你还坚持认为你有机会击败我吗？”',Feature=1,LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,0.2,0},}",
