  [47076] = "{id=47076,NameZh='透明翅膀',Icon='item_47076',Type=810,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10069,AdventureValue=90,AdventureReward={buffid={61000580}},StorageReward={buffid={80012660}},Condition=8,ComposeID=16076,Desc='万千信念汇聚而成的翅膀，缺乏信念的人，是看不到的哦~',Share=1,Feature=1,LoadShowSize=1.5,LoadShowRotate=0,LoadShowPose={0,0.2,0},}",
