  [47078] = "{id=47078,NameZh='燃烧禁止',Icon='item_47078',Type=810,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10074,AdventureValue=220,AdventureReward={buffid={61001110}},StorageReward={buffid={80012640}},Condition=4,ComposeID=16078,Desc='自从上次厨房着火之后，忽克连就开始整天愁眉苦脸的……直到他发明了这个东西，好像叫做灭火器？！',Feature=1,LoadShowSize=1.5,LoadShowRotate=0,LoadShowPose={0,0.2,0},}",
