  [47080] = "{id=47080,NameZh='哔哔兔气球',Icon='item_47080',Type=810,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012640}},Feature=1,}",
  [47081] = "{id=47081,NameZh='自由的波利',Icon='item_47081',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9554,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='暮色苍茫时，一个年轻姑娘手持熊熊燃烧的火炬，跃过障碍物，高呼“前进”的口号向敌人冲去，波拿巴分子的枪声响了，姑娘倒在血泊中。巴托尔迪耳闻这一事实，心情久久不能平静。从此这位高擎火炬的勇敢姑娘就成为他心中自由的象征。',LoadShowSize=1.2,LoadShowRotate=0,LoadShowPose={0,0.2,0},}",
  [47082] = "{id=47082,NameZh='夜羽',Icon='item_47082',Type=810,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=15022,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='即使在漆黑的夜晚也能散发出神秘羽光的翅膀是恶魔们的骄傲，恶魔们为这对翅膀取了一个他们自己觉得还不错的名字“夜羽”。',LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,0.2,0},}",
  [47083] = "{id=47083,NameZh='六月扭蛋背饰2',Icon='item_47083',Type=810,MaxNum=99,SellPrice=100,Feature=1,Delete=47083}",
  [47084] = "{id=47084,NameZh='怪兽哥莫拉背饰',Icon='item_47084',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15029,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='哥莫拉是古代恐龙的幸存者，强大无比的地底怪兽。它的出现引发了人类的深思——为什么这些怪兽在与人类接触后才变得凶狠残暴？怪兽能否与人类和平共存？答案，恐怕就藏在人类自己的心里。',Feature=1,LoadShowSize=2,LoadShowRotate=180,LoadShowPose={0,0.2,0},Delete=47084}",
  [47085] = "{id=47085,NameZh='怪兽金古桥背饰',Icon='item_47085',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15030,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='机器人的实力是有目共睹的。经过无穷无尽的迭代进化，究竟能达到什么程度呢？',Feature=1,LoadShowSize=2,LoadShowRotate=180,LoadShowPose={0,0.2,0},Delete=47085}",
  [47086] = "{id=47086,NameZh='怪兽贝姆斯塔背饰',Icon='item_47086',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15031,AdventureValue=1,StorageReward={buffid={81000380}},Condition=8,Desc='来自蟹星云的浮游生物，以氢气、氮气、氦气作为能量来源，腹部的五边形，也是它的嘴巴哦~',Feature=1,LoadShowSize=2,LoadShowRotate=180,LoadShowPose={0,0.2,0},Delete=47086}",
  [47087] = "{id=47087,NameZh='怪兽哥尔赞背包',Icon='item_47087',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9556,AdventureValue=1,StorageReward={buffid={80012870}},Condition=8,Desc='哥尔赞可是能在火山岩浆中生存的怪兽，这个背包一定非常结实。',Feature=1,LoadShowSize=2,LoadShowRotate=180,LoadShowPose={0,0.2,0},Delete=47087}",
  [47088] = "{id=47088,NameZh='迪迦奥特曼背包',Icon='item_47088',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9557,AdventureValue=1,StorageReward={buffid={80012810}},Condition=8,Desc='为什么我有了奥特曼变身器还是不能变身？因为还差一个变身卷轴……',Feature=1,LoadShowSize=2,LoadShowRotate=180,LoadShowPose={0,0.2,0},Delete=47088}",
