  [47090] = "{id=47090,NameZh='执事公事包',Icon='item_47090',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15056,AdventureValue=1,AdventureReward={buffid={61001090}},StorageReward={buffid={80012970}},Condition=8,Desc='超一流执事克米莉娅存放资料用的手提包，贴心的她平时都提前帮主人把日程表都整理好了哟！',Feature=1,LoadShowSize=2,LoadShowRotate=180,LoadShowPose={0,0.2,0},}",
