  [47106] = "{id=47106,NameZh='糖果大使',Icon='item_47106',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9595,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='这个节日怎么能少了各式各样的糖果呢？波板糖，金平糖，枫糖浆，橡皮糖......还有最拉风的大糖棍！赶快背上糖果大使，让你周围的空气散发出甜蜜与快乐吧！',Feature=1,LoadShowSize=1,LoadShowRotate=180,LoadShowPose={0,0.2,0},}",
