  [47109] = "{id=47109,NameZh='天使之证',Icon='item_47109',Type=810,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=798,AdventureValue=440,AdventureReward={buffid={61000490}},StorageReward={buffid={80013020}},Condition=4,ComposeID=16109,Desc='只有心灵绝对纯洁，信仰无比坚定的人才能获得天使的认可，而一旦得到了天使的认可，这双羽翼便是属于你的证明，它将永生永世庇护你的灵魂。',Feature=1,LoadShowSize=1.5,LoadShowRotate=0,LoadShowPose={0,0.2,0},}",
  [47111] = "{id=47111,NameZh='暗星2000',Icon='item_47111',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9585,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='这款尼夫海姆最新式的魔法扫把，使用尼夫海姆天然稻草人全程手工制成！支持多语言魔咒识别系统和模式！无论施展魔法还是打扫卫生，暗星2000都是你的最佳选择！',Feature=1,LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,0.3,0},}",
