  [47114] = "{id=47114,NameZh='枫忆背包·红',Icon='item_47114',Type=810,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012640}},Desc='缓缓飘落的枫叶如思念温暖了岁末的秋天，行囊里装满了母亲准备的药水和食物，抚摸着红色的枫叶背包，想起了临行前那一句句的嘱托…',LoadShowSize=2,LoadShowRotate=180,LoadShowPose={0,0.3,0},}",
  [47115] = "{id=47115,NameZh='爱丽丝的洋伞',Icon='item_47033',Type=810,Quality=3,MaxNum=99,SellPrice=100,Desc='大陆最著名的香水世家：穆拉辛家族的第十四代目社长维特尔·穆拉辛的独生女儿：马蒂尔·穆拉辛小姐从小就在众星捧月般的环境中长大。为了抵抗盛夏的阳光直射，皮肤白皙的她令人制作了这把精致的魔导阳伞，据传言，打着这把伞的时候可以有效抵抗日照的影响，并且，仿佛可以将周围的空气温度恒久保持在24度。',Feature=1,LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,-0.1,0},}",
