  [47119] = "{id=47119,NameZh='万象月盘',Icon='item_47119',Type=810,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=15068,AdventureValue=1,AdventureReward={buffid={61001170}},StorageReward={buffid={80013050}},Condition=8,ComposeID=16119,Desc='“蕴藏着世间万物规律的月相之盘，请赐予我再次面对过去的勇气，当那晚的月光重新映照我的脸庞，希望这一次的轮回我能选对正确的道路。”——某个时空旅行者',LoadShowSize=1.2,LoadShowRotate=180,LoadShowPose={0,0.3,0},}",
