  [47135] = "{id=47135,NameZh='魅魔夜翼',Icon='item_47135',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15101,AdventureValue=1,StorageReward={buffid={80012930}},Condition=8,Desc='魅魔一族引以为傲的翅膀，你可以在上面看到人类的各种欲望如同繁星般点缀星空。',Feature=1,TFValidDate='2018-10-16 05:00:00',ValidDate='2018-10-18 05:00:00',}",
  [47136] = "{id=47136,NameZh='枫忆背包·黄',Icon='item_47136',Type=810,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012640}},Desc='缓缓飘落的枫叶如思念温暖了岁末的秋天，行囊里装满了母亲准备的药水和食物，抚摸着黄色的枫叶背包，想起了临行前那一句句的嘱托…',LoadShowSize=2,LoadShowRotate=180,LoadShowPose={0,0.3,0},}",
  [47137] = "{id=47137,NameZh='枫忆背包·绿',Icon='item_47137',Type=810,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012640}},Desc='缓缓飘落的枫叶如思念温暖了岁末的秋天，行囊里装满了母亲准备的药水和食物，抚摸着绿色的枫叶背包，想起了临行前那一句句的嘱托…',LoadShowSize=2,LoadShowRotate=180,LoadShowPose={0,0.3,0},}",
  [47138] = "{id=47138,NameZh='枫忆背包',Icon='item_47138',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7030,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='无论你在何处冒险，只要看到那满满的行囊就会想起母亲温暖的笑脸，给你无尽的力量..',LoadShowSize=2,LoadShowRotate=180,LoadShowPose={0,0.3,0},}",
  [47139] = "{id=47139,NameZh='和伞·紫苑',Icon='item_47139',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15108,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='在天津町的樱花林深处，你或许能见到一位撑着紫色油纸伞的女人。她便是思念着养子百鬼丸的大妖怪玉藻前。百鬼丸离开家后，找到了自己的使命与归宿。时隔千年，玉藻前在满月的夜晚仍会想起百鬼丸还是个婴儿时，纯真稚嫩的笑颜。',Feature=1,TFValidDate='2018-11-13 05:00:00',ValidDate='2018-11-15 05:00:00',}",
  [47140] = "{id=47140,NameZh='和太鼓',Icon='item_47140',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15109,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='咚咚！咚咚呛！据说敲打和太鼓发出的声音有驱赶邪魔的力量！伊达家在与天狗的战斗中就曾利用和太鼓摆出阵法。但是现在，和太鼓更多的作为一种乐器活跃在大家的视野里。',Feature=1,TFValidDate='2018-11-13 05:00:00',ValidDate='2018-11-15 05:00:00',}",
  [47141] = "{id=47141,NameZh='礼炮香槟',Icon='item_47141',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15118,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='庆祝圣诞节怎么能少了香槟呢？看我的！摇啊摇~摇啊摇~打开的时候请不要把瓶口对着人哟！',Feature=1,}",
  [47142] = "{id=47142,NameZh='吸血喵',Icon='item_47142',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9587,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='这个奇妙的小棺材里住着爱吸血的黑喵伯爵！要是随便打开的话……看到我脖子上的齿痕了吗？',LoadShowSize=1,LoadShowRotate=180,LoadShowPose={0,0.3,0},}",
  [47143] = "{id=47143,NameZh='曼陀罗竹蜻蜓',Icon='item_47143',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7055,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='神秘可爱的曼陀罗种子终于长大啦，炎炎夏日将它带在身边，不仅能多一个羞羞的跟班还能感受到来自迷藏森林的阵阵微风呢！',LoadShowSize=1.5,LoadShowRotate=0,LoadShowPose={0,0.3,0},}",
  [47144] = "{id=47144,NameZh='破旧旅行包',Icon='item_47144',Type=810,MaxNum=99,SellPrice=100,AdventureSort=7041,AdventureValue=1,StorageReward={buffid={80013070}},Condition=8,Desc='看上去是个破旧的旅行包，但据说是落魄的神使留下的珍贵财富，聪明的人才能看到它真正的样子。',LoadShowSize=1.5,LoadShowRotate=180,LoadShowPose={0,0.3,0},}",
  [47145] = "{id=47145,NameZh='高级收纳包',Icon='item_47145',Type=810,MaxNum=99,SellPrice=100,AdventureSort=7053,AdventureValue=1,StorageReward={buffid={80012630}},Condition=8,Desc='比普通的收纳包看上去高级了很多，但是卡罗尔觉得粉色实在与他的气质不搭，所以从来没有戴过它。',LoadShowSize=1.5,LoadShowRotate=180,LoadShowPose={0,0.3,0},}",
  [47146] = "{id=47146,NameZh='飞弹推进器',Icon='item_47146',Type=810,MaxNum=99,SellPrice=100,AdventureSort=159,AdventureValue=90,StorageReward={buffid={80013070}},Condition=8,Desc='据说制作它的灵感是B格猫飞碟上的武器系统。',LoadShowSize=1.5,LoadShowRotate=180,LoadShowPose={0,0.3,0},}",
  [47147] = "{id=47147,NameZh='我看见你了',Icon='item_47147',Type=810,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10104,AdventureValue=1,StorageReward={buffid={80012930}},Condition=8,Desc='“窥视之人呐，正视我的眼睛…我已经看见你了。”',Feature=1,LoadShowSize=1.5,LoadShowRotate=180,LoadShowPose={0,0.3,0},}",
  [47148] = "{id=47148,NameZh='监视者背包',Icon='item_47148',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10108,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='有如此恐怖的魔眼看着监视身后，从此任何小偷都不敢对你的背包下手了。',Feature=1,LoadShowSize=2,LoadShowRotate=180,LoadShowPose={0,0.3,0},}",
  [47149] = "{id=47149,NameZh='插入栓背包',Icon='item_47149',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15134,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='搭载着被选中的适格者，控制泛用人型决战陆上兵器EVANGELION的操作仓。',Feature=1,TFValidDate='2019-01-28 05:00:00',ValidDate='2019-01-31 05:00:00',LoadShowSize=1.5,LoadShowPose={0,0.3,0},}",
  [47150] = "{id=47150,NameZh='初号机光翼',Icon='item_47150',Type=800,MaxNum=99,SellPrice=100,Feature=1,}",
  [47151] = "{id=47151,NameZh='五号机头盔',Icon='item_47151',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=15138,AdventureValue=1,AdventureReward={buffid={61000590}},StorageReward={buffid={80012640}},Condition=8,ComposeID=16151,Desc='“幸福不会自己走过来，所以我要向他走过去，一日一步，三日三步......”——真希波·玛丽·伊兰崔亚斯',Feature=1,TFValidDate='2019-01-28 05:00:00',ValidDate='2019-01-31 05:00:00',LoadShowSize=2,LoadShowPose={0,0.75,0},}",
  [47152] = "{id=47152,NameZh='协奏发条',Icon='item_47152',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10113,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='转一圈，你就能唱音乐剧；转两圈，你就能跳古典舞；转三圈，你就能边跳边唱；转四圈…别，你可能会坏的。',LoadShowSize=1.5,LoadShowRotate=90,LoadShowPose={0,0.3,0},}",
  [47153] = "{id=47153,NameZh='女武神之翼',Icon='item_47153',Type=810,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=52012,AdventureValue=1,StorageReward={buffid={80012810}},Condition=8,LoadShowSize=1.2,LoadShowRotate=0,LoadShowPose={0,0,0},}",
  [47158] = "{id=47158,NameZh='无冕之王',Icon='item_47158',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52006,AdventureValue=170,StorageReward={buffid={80012930}},Condition=8,Desc='竞技场的王不需要浮夸的珠宝与华丽的皇冠，这把“无冕之王”就是你登上决斗者巅峰的最好证明。',LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,0.3,0},}",
  [47159] = "{id=47159,NameZh='霜槲寄生',Icon='item_47159',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9599,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='在童话中，这些生长在寒冰洞窟的霜槲寄生是一位爱上太阳神的魔女变成的。明明接触到阳光就会融化枯萎，但却仍努力生长，直到长出洞口的那一天，沐浴在温暖的阳光中死去。',LoadShowSize=2,LoadShowRotate=168.3,LoadShowPose={0,0.45,0},}",
  [47160] = "{id=47160,NameZh='圣羽',Icon='item_47160',Type=810,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=15128,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='羽翼连接着星河与大地，翱翔至天空的尽头。乘着翅膀流连于云端，弹指间回首，尘世已经过去了百年。',Feature=1,TFValidDate='2019-01-07 05:00:00',ValidDate='2019-01-10 05:00:00',LoadShowSize=1.8,LoadShowPose={0,0.4,-0.3},}",
  [47163] = "{id=47163,NameZh='狂脊',Icon='item_47163',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52016,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='猎人享受胜利，猎物成为战利品，这弱肉强食的世界，就是我的游乐场。',LoadShowSize=1,LoadShowRotate=180,LoadShowPose={0,0.4,0},}",
  [47164] = "{id=47164,NameZh='辟邪腰鼓',Icon='item_47164',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15146,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='具有古老历史的腰鼓，得名于来自东方的上古神兽，也和它一样具有远离灾厄的寓意。如果在入睡前敲三下，当晚一定会做个好梦。',Feature=1,TFValidDate='2019-01-28 05:00:00',ValidDate='2019-02-04 05:00:00',}",
  [47166] = "{id=47166,NameZh='叶池·鲤庭',Icon='item_47166',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9606,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='世界那么大，锦鲤也想去看看！把代表幸运的它带在身上，再装点上几株四叶草，新的一年必定美梦成真！',Feature=1,TFValidDate='2019-02-01 05:00:00',ValidDate='2019-02-01 05:00:00',LoadShowSize=1.5,LoadShowRotate=180,LoadShowPose={0,0.4,0},}",
  [47167] = "{id=47167,NameZh='牛首挂件',Icon='item_47167',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10269,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='凶蛮野牛的头颅，即便已经被砍下制作成挂件，眼中依旧燃烧着可怕的战意。',LoadShowSize=1.2,LoadShowRotate=180,LoadShowPose={0,0.3,0},}",
  [47168] = "{id=47168,NameZh='翡翠之心',Icon='item_47168',Type=810,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9609,AdventureValue=1,StorageReward={buffid={82000240}},Condition=8,Desc='根据汶巴拉雨檀族的传说，这个小家伙就是阿玛丝塔西雅——星之花的种子，蕴含生命奥秘的翡翠之心。',TFValidDate='2019-03-01 05:00:00',ValidDate='2019-03-01 05:00:00',LoadShowSize=1.2,LoadShowRotate=0,LoadShowPose={0,0.3,0},}",
  [47169] = "{id=47169,NameZh='兔兔彩蛋背包',Icon='item_47169',Type=810,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10132,AdventureValue=120,AdventureReward={buffid={61000520}},StorageReward={buffid={80012640}},Condition=4,ComposeID=16169,Desc='充满了复活节气息的背包，色彩交织间溢满了早春的欢喜。“不可以砸破彩蛋，否则兔子会溜走哦！”',Feature=1,TFValidDate='2019-04-18 05:00:00',ValidDate='2019-04-21 05:00:00',}",
  [47170] = "{id=47170,NameZh='驭海之戟',Icon='item_47170',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7034,AdventureValue=1,StorageReward={buffid={80013010}},Condition=8,Desc='传说中有了它便可以控制整片大海，海中的生物都听从它的驱使，得到它，你便是海中的王者！',Feature=1,LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,0.3,0},}",
  [47171] = "{id=47171,NameZh='湮灭者的诅咒',Icon='item_47171',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52023,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='“凋零之风啊，请记住：吾之愤怒，将永刻于此盾之上。”——《尼德霍格之影·其三》',LoadShowSize=1.2,LoadShowRotate=180,LoadShowPose={0,0.3,0},}",
  [47172] = "{id=47172,NameZh='铭刻时光之盾',Icon='item_47172',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52024,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='由永恒的时间凝固而成的盾牌，曾经保护着某位英雄在大陆征战。据说有了它的保护，可以抵抗人世间的一切灾厄。',LoadShowSize=1.2,LoadShowRotate=180,LoadShowPose={0,0.3,0},}",
  [47173] = "{id=47173,NameZh='破碎圣裁',Icon='item_47173',Type=810,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=52027,AdventureValue=1,StorageReward={buffid={80012810}},Condition=8,Desc='从奥术魔方中掉落的碎片，凝聚着不可思议的神力。如果不注意接触方式，其中隐藏的巨大魔法甚至会将触碰它的人类反噬。',LoadShowSize=1.3,LoadShowRotate=180,LoadShowPose={0,0.3,0},}",
  [47174] = "{id=47174,NameZh='龙熠',Icon='item_47174',Type=810,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=926,AdventureValue=440,AdventureReward={buffid={61001180}},StorageReward={buffid={80013050}},Condition=4,ComposeID=16174,Desc='迪塔勒泰晤勒身上最坚硬的一块鳞片，甚至可以抵挡魔王梦罗克的一击，是大陆上所有冒险者梦寐以求的珍宝！',Feature=1,LoadShowSize=1.3,LoadShowRotate=180,LoadShowPose={0,0.3,0},RefineStorageReward={{buffid={65000090},lv=6},{buffid={66000360},lv=8}},}",
  [47178] = "{id=47178,NameZh='黄金鬼翼',Icon='item_47178',Type=810,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=15189,AdventureValue=1,StorageReward={buffid={80012870}},Condition=8,Desc='据说灵魂不再纯粹的人会长出恶鬼一般的羽翼，而黄金色的鬼翼代表着持有者贪婪的罪行，上面的鬼脸似乎永远在嗤笑着什么。',Feature=1,TFValidDate='2023-07-17 05:00:00',ValidDate='2023-07-24 05:00:00',LoadShowSize=1,LoadShowRotate=180,LoadShowPose={0,0.3,0},}",
  [47180] = "{id=47180,NameZh='拉斯格瑞丝·羽落',Icon='item_47180',Type=810,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=52034,AdventureValue=1,StorageReward={buffid={80012870}},Condition=8,Desc='她将白雪融为羽刃，伴着月光斩断深渊，羽翼飘落之处，天幕银河流淌，圣歌吟咏之际，诸神恩赐晨曦。',Feature=1,StageDisplay=0,}",
  [47182] = "{id=47182,NameZh='铃音金翼',Icon='item_47182',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7074,AdventureValue=170,AdventureReward={buffid={61000500}},StorageReward={buffid={80012920}},Condition=4,ComposeID=16182,Desc='一铃摇曳生，神音庇左右，双铃叮咚响，圣光照四方。金铃轻摇，愿神祇永远守护你，远离一切黑暗与腐朽。',}",
  [47184] = "{id=47184,NameZh='夜幕凝视',Icon='item_47184',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10182,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='具有护主功能的十字架，夜幕中，床底下，转角处，它都在守护你，它都在...盯着你。',}",
  [47185] = "{id=47185,NameZh='国王波利的荣耀',Icon='item_47185',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=6999,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='波利岛寄来的奖章，这是国王波利对你的肯定，可不要辜负他的心意哦！',}",
  [47186] = "{id=47186,NameZh='冒险家的旅途',Icon='item_47186',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=835,AdventureValue=150,AdventureReward={buffid={61000460}},StorageReward={buffid={80012990}},Condition=4,ComposeID=16186,Desc='大冒险家多拉贡的背包。继承这个背包的人，也会继承他的睿智、聪慧……和冷笑话。',}",
  [47187] = "{id=47187,NameZh='祈灵双翼',Icon='item_47187',Type=810,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=7078,AdventureValue=1,StorageReward={buffid={80013020}},Condition=8,Desc='祈灵双翼：神之双翼，常伴你身，展其光辉，护你锋芒，神之力永伴你左右。',}",
  [47188] = "{id=47188,NameZh='绯色烛光',Icon='item_47188',Type=810,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=940,AdventureValue=200,AdventureReward={buffid={61001130}},StorageReward={buffid={80012970}},Condition=4,ComposeID=16188,Desc='上一任森林女巫留下的烛台，巴西里斯克吐出的魔法火焰可在其中永恒燃烧。',}",
  [47189] = "{id=47189,NameZh='甜心呱太',Icon='item_47189',Type=810,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=929,AdventureValue=120,AdventureReward={buffid={61000560}},StorageReward={buffid={80012640}},Condition=4,ComposeID=16189,Desc='“呱呱呱！所有可爱的东西都是我们哒！”甜心罗达蛙的背包。沉甸甸的，里面塞满了它们偷来的糖果。',}",
  [47190] = "{id=47190,NameZh='蜂蜜糖罐',Icon='item_47190',Type=810,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=933,AdventureValue=200,AdventureReward={buffid={61001090}},StorageReward={buffid={80012980}},Condition=4,ComposeID=16190,Desc='这罐蜂蜜诞生的那天，狂野蜂兵特意烫了新的发型，并请了十只摇滚蝗虫谱写了新歌以作纪念。',}",
  [47191] = "{id=47191,NameZh='呆呆鼬仔',Icon='item_47191',Type=810,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=942,AdventureValue=310,AdventureReward={buffid={61001130}},StorageReward={buffid={80012920}},Condition=4,ComposeID=16191,Desc='毛绒绒的鼬仔是大陆上的高人气萌物之一，黑豆一样的眼睛，粉嫩的爪爪，外加上卷卷的呆毛，没有人能抵挡的了它的卖萌攻击，只是被它简单的看一眼，你的心就会融化掉。',}",
  [47192] = "{id=47192,NameZh='雪球背包',Icon='item_47192',Type=810,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=943,AdventureValue=220,AdventureReward={buffid={61000460}},StorageReward={buffid={80012840}},Condition=4,ComposeID=16192,Desc='冰镐！冰锤！小雪兽！全部准备好！让我们一起向着未知的冰域出发，进行一场奇妙的冰域探险！',}",
  [47193] = "{id=47193,NameZh='珈利行囊',Icon='item_47193',Type=810,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=953,AdventureValue=310,AdventureReward={buffid={61001160}},StorageReward={buffid={80012930}},Condition=4,ComposeID=16193,Desc='鬣狗珈利永远会记得这个行囊，这是小主人最后一次见面留给它的东西，里面装着他们一起玩过的飞盘，珈利的磨牙棒，还有小主人最爱的机器玩偶，这些都是它们的美好回忆，可惜都只能永久的封存在这个行囊里。',}",
  [47194] = "{id=47194,NameZh='冰雪獠牙',Icon='item_47194',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52035,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='以冰狼的毛皮制作而成的披风，是雪原中最英勇战士的勋章。',}",
  [47195] = "{id=47195,NameZh='圣翼',Icon='item_49130',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9050,AdventureValue=80,StorageReward={buffid={80012660}},Condition=8,}",
  [47196] = "{id=47196,NameZh='喵星之王',Icon='item_47196',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=833,AdventureValue=310,AdventureReward={buffid={61001090}},StorageReward={buffid={80012930}},Condition=4,ComposeID=16196,Desc='据说是多兰族历经成长后的最终模样。圆溜溜的眼睛里闪烁着属于王者的光辉，就连原本毛茸茸的尾巴都变得气势非凡。',}",
  [47201] = "{id=47201,NameZh='凌宇星披',Icon='item_47201',Type=810,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=974,AdventureValue=440,AdventureReward={buffid={61000730}},StorageReward={buffid={80013050}},Condition=4,ComposeID=16201,Desc='一件穿在身上气势倍增的披风，天下尽在自己手中，无所畏惧！',}",
  [47202] = "{id=47202,NameZh='猩红梦魇',Icon='item_47202',Type=810,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=975,AdventureValue=440,AdventureReward={buffid={61000750}},StorageReward={buffid={80013060}},Condition=4,ComposeID=16202,Desc='赤红的剑身散发出魔性的气息，那一抹红色危险而美丽，让人欲罢不能。',}",
  [47203] = "{id=47203,NameZh='海之誓约',Icon='item_47203',Type=810,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=965,AdventureValue=310,AdventureReward={buffid={61001120}},StorageReward={buffid={80012660}},Condition=4,ComposeID=16203,Desc='晶莹珍珠点缀着琴弦，缓缓拨动时，无比美妙的声音编织成真挚的誓约。',Feature=1,}",
  [47204] = "{id=47204,NameZh='祖蛇妖剑',Icon='item_47204',Type=810,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=971,AdventureValue=440,AdventureReward={buffid={61000750}},StorageReward={buffid={80012590}},Condition=4,ComposeID=16204,Desc='将鲜血注入祭坛，用生命交换力量。祖蛇之灵在焰火中咆哮，淬炼出震颤天地的妖剑。',Feature=1,}",
  [47205] = "{id=47205,NameZh='碧浪游龙',Icon='item_47205',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7099,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='洛阳城主许仙的伞，也是一把趁手的武器。撑开时，伞面可以抵挡刀剑以及魔法攻击。',LoadShowSize=0.8,LoadShowPose={0,-0.1,0},}",
  [47206] = "{id=47206,NameZh='薄暮金辉',Icon='item_47206',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7087,AdventureValue=1,StorageReward={buffid={80012990}},Condition=8,Desc='极具仙气的设计，金色的叶子吊坠在彰显存在感的同时又不失高贵。',LoadShowSize=0.9,LoadShowRotate=180,LoadShowPose={0,0.4,0},}",
  [47207] = "{id=47207,NameZh='暗夜魅舞',Icon='item_47207',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7088,AdventureValue=1,StorageReward={buffid={80012600}},Condition=8,Desc='一把散发着凛然典雅气质的剑，剑鞘的金色雕刻栩栩如生。',}",
  [47208] = "{id=47208,NameZh='沉梦流光',Icon='item_47208',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10239,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='枝叶间凝聚的，是他无法释怀的思念，与跨越时间的羁绊。',}",
  [47210] = "{id=47210,NameZh='绯红玄翼',Icon='item_47210',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10218,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='梦中的奇兽，乘着绯红的霞云，化作轻盈的羽翼，飞遍天涯海角。',}",
  [47211] = "{id=47211,NameZh='可可奶喵糖',Icon='item_47211',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52043,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='香浓牛奶与醇厚可可交融，幸福感也是倍增呢喵˜',}",
  [47212] = "{id=47212,NameZh='灾厄莲华',Icon='item_47212',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10227,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='以灾厄炎龙的利爪锻造的刀具，因为太过稀有而一直被封存，装饰价值远远大于使用价值。',}",
  [47217] = "{id=47217,NameZh='星海幻城',Icon='item_47217',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7109,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='星河尽头，是极乐的幻想乡。我原以为那里遥不可及，直到遇见你。',}",
  [47218] = "{id=47218,NameZh='摩因盾',Icon='item_47218',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52048,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='盘踞着蛇形的盾牌，同时又兼具矛的攻击。',LoadShowSize=1.2,LoadShowRotate=180,}",
  [47219] = "{id=47219,NameZh='月话',Icon='item_47209',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7098,AdventureValue=1,StorageReward={buffid={80012990}},Condition=8,LoadShowPose={0,-0.5,0},}",
  [47220] = "{id=47220,NameZh='林中猛虎[1]',Icon='item_3000980',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7105,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,LoadShowSize=2,LoadShowPose={0,0.5,0},}",
  [47221] = "{id=47221,NameZh='圣者的行进',Icon='item_47221',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10279,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='十字架支撑着天使的双翼。这纯洁与正义合二为一的重量，唯有坚韧不拔的圣者才能背负得起。',TFValidDate='2020-09-05 05:00:00',ValidDate='2020-10-17 05:00:00',}",
  [47227] = "{id=47227,NameZh='夺宝奇包',Icon='item_47227',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52050,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='印第安纳琼斯强烈推荐，防水防盗防流沙！',LoadShowRotate=175,}",
  [47228] = "{id=47228,NameZh='浮空轻羽',Icon='item_47228',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7119,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='浮空精灵，这受到神明眷顾的种族天生便具有飞行的能力，真是令人羡慕！',}",
  [47229] = "{id=47229,NameZh='精灵守卫之翼',Icon='item_47229',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7120,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='守护艾卡拉奇的精灵守卫，他们的翅膀受到魔法加持更加强壮，能够飞上高空，搜寻隐藏的威胁。',}",
  [47230] = "{id=47230,NameZh='万灵颂唱',Icon='item_47230',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7124,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='这把琴注入了天地树的力量，当它奏响时，能听到世间万千生灵的心声。',LoadShowSize=1.5,}",
  [47232] = "{id=47232,NameZh='精灵国度翅膀',Icon='item_47232',Type=810,Quality=3,MaxNum=99,SellPrice=100,}",
  [47233] = "{id=47233,NameZh='新叶羽翼',Icon='item_47233',Type=810,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=986,AdventureValue=440,AdventureReward={buffid={61000730}},StorageReward={buffid={80013050}},Condition=4,ComposeID=16233,Desc='喷涌的魔力汇聚成天地树的叶片，在天地树的祝福下翱翔吧！',}",
  [47234] = "{id=47234,NameZh='魂音激奏',Icon='item_47234',Type=810,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=987,AdventureValue=440,AdventureReward={buffid={61000750}},StorageReward={buffid={80013060}},Condition=4,ComposeID=16234,Desc='去战斗，去歌唱，直至灵与肉消亡之刻。奏响吧，这令灵魂震颤的旋律！',}",
  [47235] = "{id=47235,NameZh='苗娃秋千',Icon='item_47235',Type=810,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=991,AdventureValue=310,AdventureReward={buffid={61001120}},StorageReward={buffid={80012660}},Condition=4,ComposeID=16235,Desc='荡秋千，荡秋千，荡到白云边~这个秋千可是苗娃的专座，谁都不许抢哦！',}",
  [47236] = "{id=47236,NameZh='精灵国度npc翅膀1',Icon='item_47236',Type=810,Quality=3,MaxNum=99,SellPrice=100,}",
