  [47246] = "{id=47246,NameZh='暴风雪之翼',Icon='item_47246',Type=810,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=993,AdventureValue=1,AdventureReward={buffid={61000750}},StorageReward={buffid={80013060}},Condition=4,ComposeID=16246,Desc='冰暴骑士的宝物，穿上后可以掌控暴风雪的力量！“在狂风之中颤抖吧，鲁道夫的敌人们！”',}",
  [47247] = "{id=47247,NameZh='星光祈愿杖',Icon='item_47247',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10307,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='据说只要拿着这根魔杖大声念出咒语就可以变身成魔女：“继承星光力量的魔杖啊，以契约之名，解放你真正的力量吧！永恒星光加护，星之魔女变身！”（请不要在人流密集处尝试）',LoadShowSize=1.6,LoadShowRotate=180,LoadShowPose={0,0.25,0},}",
  [47248] = "{id=47248,NameZh='女武神的嘉奖·传奇',Icon='item_47248',Type=810,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=10313,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='女武神被勇士驰骋的英姿折服，献上象征胜利的圣杯。“谨献给圣域之战杯赛中表现超凡的传奇勇士！”',LoadShowSize=1.5,LoadShowRotate=-14,}",
  [47249] = "{id=47249,NameZh='女武神的嘉奖·荣耀',Icon='item_47249',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10314,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='女武神满意于勇士的强大实力，奉上象征荣誉的圣杯。“谨献给圣域之战杯赛中表现优异的荣耀勇士！”',LoadShowSize=1.5,LoadShowRotate=-14,}",
  [47250] = "{id=47250,NameZh='女武神的嘉奖·无畏',Icon='item_47250',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10315,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='女武神认可勇士战斗时的不屈意志，赐予象征英勇的圣杯。“谨献给圣域之战杯赛中表现优秀的无畏勇士！”',LoadShowSize=1.5,LoadShowRotate=-14,}",
  [47251] = "{id=47251,NameZh='毕业歌',Icon='item_47251',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10316,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='歌声响起，新人们将离开学院，正式踏上冒险旅途。在这里学到的知识，将在未来帮助他们、保护他们，而他们的勇气，将让他们在更广阔的天空中翱翔！',Feature=1,TFValidDate='2020-12-30 05:00:00',ValidDate='2021-01-06 05:00:00',LoadShowSize=1.2,LoadShowRotate=180,LoadShowPose={0,0.25,0},}",
  [47252] = "{id=47252,NameZh='犬神龛',Icon='item_47252',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52053,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='供奉犬神的神龛，其实本质就是狗窝吧…',}",
  [47254] = "{id=47254,NameZh='梦想·天空',Icon='item_47254',Type=810,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=999,AdventureValue=220,AdventureReward={buffid={61001130}},StorageReward={buffid={80012920}},Condition=4,ComposeID=16254,Desc='每一只奈吉鸟都向往着天空，相传每一对奈吉鸟父母都会给自己的孩子准备一份礼物：一副护目镜和一根拐杖。护目镜用于飞行时看清前方，拐杖则保证摔断腿后仍能正常行走……\n“一个叫理想，一个叫现实！”',Feature=1,}",
  [47255] = "{id=47255,NameZh='海妖之触',Icon='item_47255',Type=810,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=1003,AdventureValue=440,AdventureReward={buffid={61000730}},StorageReward={buffid={80013050}},Condition=4,ComposeID=16255,Desc='利用魔鬼大乌贼的触须制作的法杖，据说拥有召唤海浪的能力。注意事项：请勿将该法杖靠近火源，否则会有可怕的事发生。\n“这……这是——碳烤鱿鱼丝！真香！”',Feature=1,}",
  [47256] = "{id=47256,NameZh='帝王大虾弓',Icon='item_47256',Type=810,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=1001,AdventureValue=310,AdventureReward={buffid={61000470}},StorageReward={buffid={80012620}},Condition=4,ComposeID=16256,Desc='霸王大蟹弓的远房表哥，觉得自己比霸王大蟹弓、喵喵大蟹弓更优秀——至少更好吃！',Feature=1,}",
  [47257] = "{id=47257,NameZh='蓝曜枪',Icon='item_47257',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10342,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='全盛期的波姬最爱用的武器。虽然外表看起来朴素又高贵，但实际上非常非常的重。波姬究竟是怎么挥动它的呢？',LoadShowSize=1.4,}",
  [47258] = "{id=47258,NameZh='回应之人',Icon='item_47258',Type=810,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=10348,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='“再见了，唯一回应我的人啊。”这是她留下的最后一句话。若这份思念，能以有形之物的姿态持续下去，她的存在也会成为永恒……',}",
  [47259] = "{id=47259,NameZh='地牢卫士',Icon='item_47259',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52056,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='传闻幽暗的地牢深处，藏匿着神秘的宝藏和它“可怕”的守护者。“我、我很凶的……你、你、你不要过来啊！”',}",
  [47261] = "{id=47261,NameZh='幻想波利摩天轮',Icon='item_47261',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10374,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='从高处俯瞰，整个大陆像一幅令人惊叹的拼贴画，带着不可思议的美丽景色，让人忍不住想出发寻找勇气、希望和无限可能！',Feature=1,}",
  [47262] = "{id=47262,NameZh='绿野奇遇',Icon='item_47262',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52059,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='传说在妙勒尼山脉深处，有一片神奇的“仙林”，那里的泉水充满魔力，能够赋予魔物智慧。',LoadShowRotate=330,LoadShowPose={0,-1,-0.5},}",
  [47263] = "{id=47263,NameZh='灾厄之翼',Icon='item_47263',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10460,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='使用魔龙加利厄隆坦的残骸锻造的翅膀，其中还残留着魔龙的力量。',LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,0,0},}",
  [47264] = "{id=47264,NameZh='疾风之翼',Icon='item_47264',Type=810,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=10466,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='天水之国的灵兽“红王”将这对羽翼赐予那些勇敢的冒险者，愿无羁之风的加护常伴他们的旅途。',LoadShowPose={0.5,0,-0.5},}",
  [47265] = "{id=47265,NameZh='公主茶会',Icon='item_47265',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10486,AdventureValue=1,StorageReward={buffid={80012630}},Condition=8,Desc='身为贵族，无论是言辞还是礼仪，都应该像这杯茶一样，滴水不漏——“嘶，好烫！”',}",
  [47266] = "{id=47266,NameZh='森之萤火',Icon='item_47266',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52067,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='流萤之火，汇聚成星光，在这闪烁的星光下许下愿望吧！',}",
  [47267] = "{id=47267,NameZh='幼鹿背包',Icon='item_47267',Type=810,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=1007,AdventureValue=310,AdventureReward={buffid={61000470}},StorageReward={buffid={80012980}},Condition=4,ComposeID=16267,Desc='参照绒绒鹿制成的背包，虽然十分可爱，却装不下多少东西。你问口袋在哪里的话……大概在小鹿的脑袋里吧？',}",
  [47269] = "{id=47269,NameZh='长夜晦明',Icon='item_47269',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7156,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='漫漫长夜之中，亦有人执掌灯火，为人引路前行。',Feature=1,TFValidDate='2021-12-22 05:00:00',ValidDate='2021-12-29 05:00:00',}",
  [47270] = "{id=47270,NameZh='法医背包',Icon='item_47270',Type=810,MaxNum=99,SellPrice=100,AdventureSort=7162,AdventureValue=1,StorageReward={buffid={80013070}},Condition=8,Desc='王室法医的同款背包，采用真皮材质，样式简洁轻巧。不过作为外行的你，就别期望从里面找到验尸工具啦~',}",
  [47271] = "{id=47271,NameZh='王室之耀',Icon='item_47271',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7158,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='承载着王室荣耀的羽翼。过往的荣光不会逝去，会一直闪耀！',}",
  [47272] = "{id=47272,NameZh='大航海之证',Icon='item_47272',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7170,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='海上贸易大亨老巴尔特专属的黄金火枪，过于奢华的外饰配合先进的火枪技术，彰显出巴尔特家族无人能及的海上霸主地位。',}",
  [47273] = "{id=47273,NameZh='命运的掌舵者',Icon='item_47273',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7172,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,ComposeID=16273,Desc='船舵就如同一艘船的大脑，指挥着船只在大海上前进的方向。航海时如果不提高警惕，时刻注意船舵的话，或许命运就掌握在了别人的手上……',}",
  [47274] = "{id=47274,NameZh='熔岩泡泡浴',Icon='item_47274',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10513,AdventureValue=1,StorageReward={buffid={80012920}},Condition=8,Desc='呃，你管这玩意儿叫温泉？！',}",
  [47275] = "{id=47275,NameZh='黏着系芽芽',Icon='item_47275',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52071,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='生长在泥土里的芽芽，也有环游世界的梦。为了搭便车，它们会悄悄扒在过路的旅行者身上。“抓、抓紧呀~芽芽快掉下来啦！”',}",
  [47276] = "{id=47276,NameZh='永恒的乐章',Icon='item_47276',Type=810,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=10509,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='RO第一张黑胶唱片及五周年生日的特别纪念。往日的时光里，感谢与你相伴的每个瞬间。所有沿途的欢笑与泪水，皆会凝聚成奇迹的音符，让我们继续谱写爱与勇气的旋律；共赴光与远方的约定；一起奏响冒险的崭新乐章。',LoadShowSize=1,LoadShowRotate=170,}",
  [47277] = "{id=47277,NameZh='稚嫩的誓言',Icon='item_47277',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7175,AdventureValue=1,StorageReward={buffid={80012840}},Condition=8,ComposeID=16277,Desc='马西米利安是现任雷根弗莱格家的家主，他对孙子们的教育十分的严苛。但大家都不知道的是，深夜里的他总是会打开一个盒子，露出慈祥的笑容。这里面就有这把玩具剑，是他给年幼时的海尔穆特的奖励。他轻轻的擦拭着剑身，想起海尔穆特稚嫩的声音：“恶魔都倒在了我的剑下！我会守护雷根弗莱格！守护米德加尔特！”',}",
  [47278] = "{id=47278,NameZh='尊崇羽麾',Icon='item_47278',Type=810,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=52074,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='极致华丽的羽翼饰以象征胜利的旌旗和绶带，女武神将它赠予在残酷竞赛中表现卓越的挑战者，期盼他们飞向新的巅峰。',}",
  [47279] = "{id=47279,NameZh='梦幻新星',Icon='item_47279',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52076,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='精彩将会持续上演,欢乐永不落幕！女士们先生们,接下来让我们有请梦幻园最受瞩目的明星，调动全身的激情，为大家呈现一场令人难忘的表演。',}",
  [47280] = "{id=47280,NameZh='凌宇星披·赛季',Icon='item_47280',Type=810,Quality=4,MaxNum=99,SellPrice=100,Desc='《注意》该装备属性及其卡片、附魔等效果仅在公会战相关地图生效，且升级后无法还原。赛季开始后将由不思议贩卖机进行回收。',NoStorage=5,}",
  [47281] = "{id=47281,NameZh='祈灵双翼·赛季',Icon='item_47281',Type=810,Quality=4,MaxNum=99,SellPrice=100,Desc='《注意》该装备属性及其卡片、附魔等效果仅在公会战相关地图生效，且升级后无法还原。赛季开始后将由不思议贩卖机进行回收。',NoStorage=5,}",
  [47282] = "{id=47282,NameZh='飞行的智慧·赛季',Icon='item_47282',Type=810,Quality=4,MaxNum=99,SellPrice=100,Desc='《注意》该装备属性及其卡片、附魔等效果仅在公会战相关地图生效，且升级后无法还原。赛季开始后将由不思议贩卖机进行回收。',NoStorage=5,}",
  [47283] = "{id=47283,NameZh='逐光羽翼',Icon='item_47283',Type=810,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=52078,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='在阳光下瞬息万变的羽翼，仿佛一面华丽的镜子，映照出内心深处一往无前的昂扬斗志。开创伟业的征途上，战斗的艰辛终将如浮云般逝去，胜利的记忆会永远在生命中流动。',}",
  [47284] = "{id=47284,NameZh='幽火',Icon='item_47284',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10524,AdventureValue=1,StorageReward={buffid={80012840}},Condition=8,Desc='由逝者执念汇聚而成的怨恨之火，有着蛊惑人心、令人疯狂的力量。冒着危险也要背负幽火的冒险者啊，你，是有什么无法忘怀的故人吗？',}",
  [47285] = "{id=47285,NameZh='初心永恒',Icon='item_47285',Type=810,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=10535,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='探索世界的初心将伴随你的冒险，一起守护永恒的爱吧！',Feature=1,}",
  [47286] = "{id=47286,NameZh='江湖一桶',Icon='item_47286',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10538,AdventureValue=1,StorageReward={buffid={80012930}},Condition=8,Desc='小熊猫将自己藏进竹筒里，嘻嘻，这样就能混进流星林学习武艺了吧！',}",
  [47287] = "{id=47287,NameZh='万里行',Icon='item_47287',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7177,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='读浮世万卷书，行红尘万里路。',}",
  [47288] = "{id=47288,NameZh='深渊骨袍·憎恨',Icon='item_47288',Type=810,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80012660}},Desc='“软弱使我苦恼，牺牲使我悲哀，杀戮使我憎恨……而真正令我绝望的，是这残酷的命运。”',}",
  [47289] = "{id=47289,NameZh='星之扉',Icon='item_47289',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52080,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='是否于匆忙的旅途中忘却了什么？譬如路旁的鲜花，或是今晚的星光。',}",
  [47290] = "{id=47290,NameZh='虚空撕裂剑',Icon='item_47290',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10555,AdventureValue=1,StorageReward={buffid={80012920}},Condition=8,Desc='虚空领域的典狱官持有的宝具，可以撕裂虚空，穿梭于各个时空。',}",
  [47291] = "{id=47291,NameZh='原初龙翼·凋零',Icon='item_47291',Type=810,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80012660}},Desc='最古老的龙族之翼，守护并见证着生命的诞生与凋零。',}",
