  [47294] = "{id=47294,NameZh='深渊骨袍·绝望',Icon='item_47294',Type=810,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80012660}},Desc='“软弱使我苦恼，牺牲使我悲哀，杀戮使我憎恨……而真正令我绝望的，是这残酷的命运。”',}",
