  [47296] = "{id=47296,NameZh='深渊骨袍·苦恼',Icon='item_47296',Type=810,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80012660}},Desc='“软弱使我苦恼，牺牲使我悲哀，杀戮使我憎恨……而真正令我绝望的，是这残酷的命运。”',}",
  [47297] = "{id=47297,NameZh='狐狐伞',Icon='item_47297',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10592,AdventureValue=1,StorageReward={buffid={80012930}},Condition=8,Desc='不知道为什么，带出来的时候总是容易下雨，但没关系，幸好你带伞了。',}",
  [47298] = "{id=47298,NameZh='闪耀的星之波利',Icon='item_47298',Type=810,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=52085,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='隐藏着闪耀力量的钥匙啊，在我面前展现波利的实力吧！',}",
  [47299] = "{id=47299,NameZh='波比背包',Icon='item_47299',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52083,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='水晶波比最喜欢的宠物小包，对其他宠物而言太冷啦，但对小波比而言却刚刚好。',}",
  [47300] = "{id=47300,NameZh='布伦希尔德·羽落',Icon='item_47300',Type=810,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=10565,AdventureValue=1,StorageReward={buffid={80012870}},Condition=8,Desc='她从火焰中苏醒，在谎言中失去挚爱，虚空为羽翼染上墨色，监牢是永恒的归所。',}",
  [47301] = "{id=47301,NameZh='披风之力·浮光',Icon='item_47301',Type=810,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80012660}},Desc='当超级英雄缓缓降落在人群中，电光火石的力量彰显了他们与众人的不同。',LoadShowSize=0.8,}",
