  [47316] = "{id=47316,NameZh='四翼圣羽系列',Icon='item_47316',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7206,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='四翼闪耀在战场之上，她的力量永不屈服，直到战斗的最后一刻。',}",
  [47317] = "{id=47317,NameZh='狱火之翼',Icon='item_47317',Type=810,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=52086,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='人人都对神灵忠诚祷告，可神灵太忙，无暇顾及你的哀求，来吧，将你的灵魂交给魔鬼，至少这是一次公平交易。',}",
  [47318] = "{id=47318,NameZh='咕咕之约',Icon='item_47318',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52088,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='泡澡是咕咕最喜欢的娱乐活动，它总是戴着大金链子，目光灼灼地看着你：约吗？一起泡澡啊。',}",
