  [48008] = "{id=48008,NameZh='雷蒙盖顿的尾巴',Icon='item_48008',Type=840,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=2040,AdventureSort=5002,AdventureValue=170,AdventureReward={buffid={60000030}},StorageReward={buffid={80011170}},Condition=4,ComposeID=17008,Desc='世间万物都需要讲究平衡，这条尾巴带来的微妙而又真实的平衡感让人觉得极度的安心。',Share=1,Feature=1,LoadShowSize=1,LoadShowRotate=180,LoadShowPose={0,0.5,0},}",
  [48009] = "{id=48009,NameZh='马加锡亚的尾巴',Icon='item_48009',Type=840,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=51002,AdventureValue=116,StorageReward={buffid={80011820}},Condition=8,Desc='如同拥有着捕猎者证明的尾巴，但是在<理>之中，谁是猎物，谁是猎人，会是绝对的吗？',Share=1,Feature=1,LoadShowSize=1,LoadShowRotate=180,LoadShowPose={0,0.5,0},}",
  [48010] = "{id=48010,NameZh='英灵·亡者引渡',Icon='item_48010',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=788,AdventureValue=280,AdventureReward={buffid={60002740}},StorageReward={buffid={80012450}},Condition=4,ComposeID=17010,Desc='奥尔露恩代替英灵殿赐予冒险者的奖励，亡者引渡，淡蓝色的灵魂火焰划过的路径，即是英灵们所要走的路，瓦尔哈拉殿堂的大门，也向见到火焰痕迹的人们敞开大门。',Share=1,Feature=1,LoadShowSize=1,LoadShowRotate=180,LoadShowPose={0,0.5,0},}",
  [48011] = "{id=48011,NameZh='爱丽丝的魔术兔',Icon='item_48011',Type=840,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9501,AdventureValue=1,StorageReward={buffid={82000240}},Condition=8,Desc='玩家佩戴后，在坐下时可以让兔兔表演魔术。“屏住呼吸，跳入黑暗，一阵晕眩，豁然开朗，眼前世界，如同梦境，时钟兔子，帽子茶会，扑克女王，镜中自己，少女迷失，忘却烦恼，直到镜碎，梦醒时分，归于虚无，望向窗口，三日月夜，初秋将至，披衣起身，俯瞰庭院，恍惚之间，又见白兔，亦如当初。”-----童话绘本第三卷第九十一章',Share=1,Feature=1,LoadShowSize=1.2,LoadShowRotate=0,LoadShowPose={0,0.3,0},}",
  [48012] = "{id=48012,NameZh='英灵·亡者引渡（换色）',Icon='item_48012',Type=840,Quality=2,MaxNum=99,SellPrice=100,Desc='奥尔露恩代替英灵殿赐予冒险者的奖励，亡者引渡，淡蓝色的灵魂火焰划过的路径，即是英灵们所要走的路，瓦尔哈拉殿堂的大门，也向见到火焰痕迹的人们敞开大门。',Share=1,Feature=1,StageDisplay=0,LoadShowSize=1,LoadShowRotate=180,LoadShowPose={0,0.5,0},}",
  [48013] = "{id=48013,NameZh='银·铃',Icon='item_48013',Type=840,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9519,AdventureValue=1,StorageReward={buffid={82000240}},Condition=8,Desc='【那年冬天，时值圣诞。一个美丽的幻想世界降临了，最早发现的人们极度兴奋地跑回自己的城市，将所见的极致景色告知自己的亲朋好友们，于是，渐渐地。这里成为了充满人气的温馨世界。】---纪念最初的RO开服季节以及米德加尔特人们发现异世界姜饼城',Share=1,Feature=1,LoadShowSize=2,LoadShowRotate=0,LoadShowPose={0,0.3,0},}",
  [48014] = "{id=48014,NameZh='卡普拉专属尾巴配色1',Icon='item_48014',Type=840,MaxNum=99,SellPrice=100,StorageReward={buffid={80012480}},Desc='【那年冬天，时值圣诞。一个美丽的幻想世界降临了，最早发现的人们极度兴奋地跑回自己的城市，将所见的极致景色告知自己的亲朋好友们，于是，渐渐地。这里成为了充满人气的温馨世界。】---纪念最初的RO开服季节以及米德加尔特人们发现异世界姜饼城',Share=1,Feature=1,LoadShowSize=1,LoadShowRotate=180,LoadShowPose={0,0.5,0},}",
  [48015] = "{id=48015,NameZh='卡普拉专属尾巴配色2',Icon='item_48015',Type=840,MaxNum=99,SellPrice=100,StorageReward={buffid={80012480}},Desc='【那年冬天，时值圣诞。一个美丽的幻想世界降临了，最早发现的人们极度兴奋地跑回自己的城市，将所见的极致景色告知自己的亲朋好友们，于是，渐渐地。这里成为了充满人气的温馨世界。】---纪念最初的RO开服季节以及米德加尔特人们发现异世界姜饼城',Share=1,Feature=1,LoadShowSize=1,LoadShowRotate=180,LoadShowPose={0,0.5,0},}",
  [48016] = "{id=48016,NameZh='卡普拉专属尾巴配色3',Icon='item_48016',Type=840,MaxNum=99,SellPrice=100,StorageReward={buffid={80012480}},Desc='【那年冬天，时值圣诞。一个美丽的幻想世界降临了，最早发现的人们极度兴奋地跑回自己的城市，将所见的极致景色告知自己的亲朋好友们，于是，渐渐地。这里成为了充满人气的温馨世界。】---纪念最初的RO开服季节以及米德加尔特人们发现异世界姜饼城',Share=1,Feature=1,LoadShowSize=1,LoadShowRotate=180,LoadShowPose={0,0.5,0},}",
  [48017] = "{id=48017,NameZh='幸运独角兽',Icon='item_48017',Type=840,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9525,AdventureValue=1,StorageReward={buffid={82000240}},Condition=8,Desc='“Merry-go-round，感谢你们依然在这里、Merry-go-round，一年的轮回又转到这里、我向你打着招呼，耀眼的光芒中你闪耀着最纯真的笑颜，音乐再次响起，我们约定明年这时这刻也依然要在这个【乐园】相聚，不管身处何方，不管是否独自一人。”',Share=1,Feature=1,LoadShowSize=1.5,LoadShowRotate=0,LoadShowPose={0,0,0},}",
  [48018] = "{id=48018,NameZh='魔法防御精灵',Icon='item_48018',Type=840,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=52005,AdventureValue=210,StorageReward={buffid={80012820}},Condition=8,Share=1,Feature=1,LoadShowSize=1.5,LoadShowRotate=0,LoadShowPose={0,0,0},}",
  [48019] = "{id=48019,NameZh='幸福的小鸟',Icon='item_48019',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9532,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='孩子们依然在银白色的雪地里嬉戏，不远处的教堂钟声清澈地传来，埃尔文轻轻拉起了丽安娜的小手，被冻得红灿灿的小手，放在嘴边呼出白色的云彩，“暖和一点了吗？”“嗯~只要在你身边，我一直很温暖呢~”，两人的身影渐渐消失在安静飘落的初春之雪中，屋檐上两只金色的小鸟唱着只有幸福的人们才能听到的歌谣~',Share=1,Feature=1,LoadShowSize=1.5,LoadShowRotate=0,LoadShowPose={0,0,0},}",
  [48020] = "{id=48020,NameZh='名伞·和之美',Icon='item_48020',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9539,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='天水之国的象征：天水之国·天津町的特产油纸伞，花纹华贵优美，在普隆德拉最近人气很高。',Feature=1,LoadShowSize=1,LoadShowRotate=-10,LoadShowPose={0,-0.4,0},}",
  [48021] = "{id=48021,NameZh='校园生活',Icon='item_48021',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9545,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='智美酱今天的日记一如既往地流水账，正符合了她这个无忧无虑的纯真年龄。例如，虽然早上睡过头，吊着面包片在母亲的责骂声中，可爱制服衬衫的一角从百褶裙中逃出来就在坂道上奔跑。例如，原本天真以为用书本架在面前就可以挡住老师的视线，但是却败在自己的白日春梦，叫出学长名字而成为全班一天的笑料~嘛~真是棒呢~这就是青春呀~（笑）',Feature=1,LoadShowSize=1.2,LoadShowPose={0,0.5,0},}",
  [48022] = "{id=48022,NameZh='至高王冠',Icon='item_48022',Type=800,Quality=5,MaxNum=99,SellPrice=100,StorageReward={buffid={80012900}},Desc='纯金打造的至高王之冠，内刻神文“献于人王”，由奥丁赠送给人类历史里超越国家与阶级的英雄领袖。上一位人选是魔剑士达纳托斯，他手持无名之剑，沐浴在黎明的辉光中，为了信任自己的所有人类，与魔王梦罗克决一死战，以超越常人的力量与博大宽广的胸怀向世人展现何为伟大。',Feature=1,LoadShowSize=2,LoadShowPose={0,0.5,0},}",
  [48023] = "{id=48023,NameZh='星光白冠',Icon='item_48023',Type=800,Quality=5,MaxNum=99,SellPrice=100,StorageReward={buffid={80012900}},Desc='摘取夜空里的冷星，云雾之神茉里美糅合白金与星光，为自己待嫁的女儿打造了无暇的星光白冠。佩戴白冠的云雾仙女远嫁精灵王，在末日来临之际带领精灵一族重获新生，她的壮举被精灵们铭记，而她也被精灵们尊称为星之神女。',Feature=1,LoadShowSize=2,LoadShowPose={0,0.5,0},}",
  [48024] = "{id=48024,NameZh='亡灵黑冠',Icon='item_48024',Type=800,Quality=5,MaxNum=99,SellPrice=100,StorageReward={buffid={80012900}},Desc='异星互相碰撞飞溅出的陨铁，经过无数摩擦从天空中落下，被好奇的矮人打造成一顶黑金王冠。相传拥有这个王冠的人能获得号令亡灵的力量，同时也会因为佩戴黑冠渐渐失去记忆。千年之前，圣战中一名英勇的牧师眼见人类将面临灭绝的危险，毅然戴上这顶黑冠，号令圣战中牺牲的战士灵魂，作为黑暗里的英雄带领人类走向光明。无名的牧师失去了记忆，也失去与主神的荣光，忘记一切，整日徘徊在亡灵之中，渐渐被重获繁荣的人类所遗忘，仅在吟游诗人的只言片语中能听见有关他与亡灵黑冠的事迹。',Feature=1,LoadShowSize=2,LoadShowPose={0,0.5,0},}",
  [48025] = "{id=48025,NameZh='王冠系列头饰',Icon='item_48025',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=15013,AdventureValue=1,StorageReward={buffid={80012900}},Condition=8,}",
  [48026] = "{id=48026,NameZh='火焰尾',Icon='item_48026',Type=840,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10075,AdventureValue=190,AdventureReward={buffid={61000460}},StorageReward={buffid={80012640}},Condition=4,ComposeID=17026,Desc='虽然看起来挺酷的，可是……啊啊啊，屁股好烫啊，裤子怎么又烧着了！',Feature=1,LoadShowSize=2,LoadShowRotate=50,LoadShowPose={0,0.5,0},}",
  [48027] = "{id=48027,NameZh='飞行椅子的幻想',Icon='item_48027',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9550,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='老人安静地躺在那张世人皆知的轮椅上沉睡而去。也许微笑祥和，也许严肃认真。他连接着我们的世界和未来的世界。散落在地的是来自遥远东方国度的某份来信，「不过，有人火星探察现在还是很不顺利呢。 真的有一天我们能够亲眼看到霍金脑子里呈现出的宇宙吗？」 「到现在，还没有能够超越霍金的物理学家也是个问题呢。」 「哎呀，莲子你去努力一下不就好了？你这个拥有着稀有能力的家伙。」',Feature=1,LoadShowSize=1,}",
  [48028] = "{id=48028,NameZh='小恶魔朱莉安',Icon='item_48028',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=15023,AdventureValue=1,StorageReward={buffid={80012830}},Condition=8,Desc='这是恶魔之王的女儿朱莉安，她从小就被告知天使是长着三只眼睛，五张嘴的丑八怪，直到她遇到了天使加利尔。',Feature=1,LoadShowSize=1.5,}",
  [48029] = "{id=48029,NameZh='开心的喷壶鲸',Icon='item_48029',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9563,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='任由波利在自己的头顶上嬉戏着，【52赫兹】这头孤独的鲸鱼很开心，因为他终于找到了自己的听众。“这里就是旅程的终点！”他这样想着，又喷出了一条长长的水柱~',Feature=1,LoadShowSize=1.5,}",
  [48030] = "{id=48030,NameZh='胜利飞燕1号',Icon='item_48030',Type=840,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9555,AdventureValue=1,StorageReward={buffid={80012850}},Condition=8,Desc='想驾驶激光战斗机在宇宙中穿梭吗？卡普拉公司新推出的这款迷你战机能满足你的一切幻想！',Feature=1,LoadShowSize=2,LoadShowPose={0,0.4,0},}",
  [48031] = "{id=48031,NameZh='闹哄哄的塔奥群卡',Icon='item_48031',Type=840,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9561,AdventureValue=1,StorageReward={buffid={80012850}},Condition=8,Desc='以克魔岛专属MVP——塔奥群卡的外型所仿制的玩具,带在身边会闹哄哄地制造音乐,让人不禁想要立刻前往那个美丽的海滩去度假。',Feature=1,LoadShowSize=1.5,}",
  [48032] = "{id=48032,NameZh='尼酱',Icon='item_48032',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15057,AdventureValue=1,AdventureReward={buffid={61001100}},StorageReward={buffid={80012980}},Condition=8,Desc='卢恩执事协会吉祥物——尼酱~虽然它是只不会说话的猫，但是它有着成为一名执事的梦想呀~！',Feature=1,LoadShowSize=1.5,}",
  [48033] = "{id=48033,NameZh='风栖幼龙',Icon='item_48033',Type=840,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9567,AdventureValue=1,StorageReward={buffid={82000240}},Condition=8,Desc='生活在天地树高处的迷你龙族，与浮空精灵有着古老的眷属关系 。最喜欢的食物是天地树叶露水，天生擅长魔法与卖萌，撒娇的时候会用卷尾巴缠住人，发出“嘤嘤嘤”的叫声。',Feature=1,LoadShowSize=1.5,LoadShowPose={0,0.2,0},}",
  [48034] = "{id=48034,NameZh='嘤嘤火焰鸟',Icon='item_48034',Type=840,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=731,AdventureValue=310,AdventureReward={buffid={61001090}},StorageReward={buffid={80012930}},Condition=4,ComposeID=17034,Desc='成年后的火焰鸟嚎叫一声连天地都为之震动，而幼年火焰鸟却只会嘤嘤嘤，没人知道这中间的成长发生了什么。',LoadShowSize=1.5,LoadShowPose={0,0.2,0},RefineStorageReward={{buffid={65000140},lv=6},{buffid={66000080},lv=8}},}",
  [48035] = "{id=48035,NameZh='海神冲浪板',Icon='item_48035',Type=840,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80012660}},Desc='印着保佑海上平安的萌萌海神，再加上今夏最流行的时尚配色，这样的冲浪板踏浪爱好者能不心动嘛！',LoadShowSize=1.2,LoadShowRotate=160,LoadShowPose={0,0.3,0},}",
  [48036] = "{id=48036,NameZh='惊魂南瓜',Icon='item_48036',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9588,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='这个精力旺盛的小家伙最喜欢往自己身上装点甜美可爱的东西——糖果，曲奇还有各种可爱的头饰！它最喜欢的就是假面狂欢节和幻想创造器I号。',Feature=1,LoadShowSize=2,LoadShowPose={0,0.3,0},}",
  [48037] = "{id=48037,NameZh='蛋黄哥漂浮中',Icon='item_48037',Type=840,Quality=3,MaxNum=99,Desc='就著樣飄著吧…游泳什麼的實在太累了…',Feature=1,LoadShowSize=1.2,}",
  [48038] = "{id=48038,NameZh='情谊千纸鹤',Icon='item_48038',Type=840,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10090,AdventureValue=1,AdventureReward={buffid={61000590}},StorageReward={buffid={80012640}},Condition=4,ComposeID=17038,Desc='将情书折叠成千纸鹤的过程，一定充满了憧憬、害羞与紧张吧！！',LoadShowSize=2.2,LoadShowPose={0,0.2,0},}",
  [48039] = "{id=48039,NameZh='爱丽丝的兔子',Icon='item_48011',Type=840,Quality=4,MaxNum=99,SellPrice=100,Desc='玩家佩戴后，在坐下时可以让兔兔表演魔术。“屏住呼吸，跳入黑暗，一阵晕眩，豁然开朗，眼前世界，如同梦境，时钟兔子，帽子茶会，扑克女王，镜中自己，少女迷失，忘却烦恼，直到镜碎，梦醒时分，归于虚无，望向窗口，三日月夜，初秋将至，披衣起身，俯瞰庭院，恍惚之间，又见白兔，亦如当初。”-----童话绘本第三卷第九十一章',Share=1,Feature=1,LoadShowSize=1.5,LoadShowPose={0,0.5,0},}",
  [48040] = "{id=48040,NameZh='和服尾饰',Icon='item_48040',Type=840,MaxNum=99,SellPrice=100,Feature=1,}",
  [48041] = "{id=48041,NameZh='金风玉露',Icon='item_48041',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15066,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='“金风玉露一相逢，便胜却人间无数。”',Feature=1,TFValidDate='2018-08-14 05:00:00',ValidDate='2018-08-16 05:00:00',LoadShowSize=1.5,LoadShowPose={0,0.2,0},}",
  [48042] = "{id=48042,NameZh='月亮尾饰',Icon='item_48042',Type=840,Quality=4,MaxNum=99,SellPrice=100,}",
  [48043] = "{id=48043,NameZh='传说之杯',Icon='item_48043',Type=840,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=51008,AdventureValue=117,StorageReward={buffid={80013100}},Condition=8,Desc='这是便是仙境最强者的证明，尽情享受大家羡煞的目光吧，决斗之王，你当之无愧！',Feature=1,LoadShowSize=1.5,LoadShowPose={0,0.2,0},}",
  [48044] = "{id=48044,NameZh='溜溜猴乐团',Icon='item_48044',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9573,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='叮叮咚咚~吹着香蕉进行曲的溜溜猴乐团前来报道！喂喂喂，舞台不是这个方向啊！你们这些家伙眼里只有餐桌上的魔物香蕉吗……（玩家坐下后，乐团就会开始演奏哦~）',LoadShowSize=1.5,LoadShowRotate=-20,}",
  [48045] = "{id=48045,NameZh='学霸鸭',Icon='item_48045',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9586,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='呱呱呱！一只黄色的小鸭子跃上了讲台。“在下学霸鸭，恕本鸭直言，课堂里在座的各位都是渣渣！”还是乖乖接受它的魔鬼补习吧！',Feature=1,TFValidDate='2018-09-11 05:00:00',ValidDate='2018-09-13 05:00:00',LoadShowSize=1.5,LoadShowRotate=-20,}",
  [48046] = "{id=48046,NameZh='星灯游鱼',Icon='item_48046',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9580,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='即使恒星燃尽，黑洞崩塌，小小的它依旧会点亮这盏星灯，在浩瀚的宇宙中为你指明回家的方向。',LoadShowSize=2,LoadShowRotate=-20,LoadShowPose={0,0.2,0},}",
  [48047] = "{id=48047,NameZh='机械尾巴',Icon='item_48047',Type=840,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=911,AdventureValue=270,AdventureReward={buffid={61001090}},StorageReward={buffid={80012660}},Condition=4,ComposeID=17047,LoadShowSize=2.5,LoadShowRotate=30,LoadShowPose={0,0.5,0},RefineStorageReward={{buffid={65000140},lv=6},{buffid={66000080},lv=8}},}",
  [48048] = "{id=48048,NameZh='厨神之魂',Icon='item_48048',Type=840,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=15071,AdventureValue=1,AdventureReward={buffid={61001130}},StorageReward={buffid={80012920}},Condition=4,ComposeID=17048,Desc='“初心者，你想跟我学做菜吗？？”——厨之精灵站在街口，对每一个路过的初心者发出邀请，身前的厨师帽中，还散落着几枚Zeny…',LoadShowSize=1.5,}",
  [48049] = "{id=48049,NameZh='恶兽之尾',Icon='item_48049',Type=840,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10127,AdventureValue=140,AdventureReward={buffid={61001130}},StorageReward={buffid={80012970}},Condition=4,ComposeID=17049,Desc='每年新年的时候，父母们都会给孩子戴上这个可爱的恶兽尾巴，这样当恶兽到来的时候就感受不到孩童们的气息，以此来保证孩子们的安全。',Feature=1,TFValidDate='2019-01-24 05:00:00',ValidDate='2019-01-31 05:00:00',}",
  [48050] = "{id=48050,NameZh='迷你梦魇',Icon='item_48050',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15104,AdventureValue=1,StorageReward={buffid={80012920}},Condition=8,Desc='这个小家伙对灵异的事物非常敏感，如果它头顶上的烛光摇曳，那么，要当心你的背后哟......',Feature=1,TFValidDate='2018-10-16 05:00:00',ValidDate='2018-10-18 05:00:00',}",
  [48051] = "{id=48051,NameZh='扫晴娘',Icon='item_48051',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15110,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='吸收了大家对晴天的美好期盼，这个小家伙每天都很努力的挂在元灵神社的屋檐下。但很少有人知道，她的第一位主人是当年对抗天狗的伊达晴子。“扫晴娘，扫晴娘，三天扫晴啦，给你穿花衣裳，三天扫不晴，扎你的光脊梁。”——止雨歌',TFValidDate='2018-11-13 05:00:00',ValidDate='2018-11-15 05:00:00',}",
  [48052] = "{id=48052,NameZh='白熊礼盒',Icon='item_48052',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15119,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='唔哇！！这个调皮的小家伙伪装成了惊吓礼盒！但是这么可爱，根本吓不倒人啊......让我把你带回家吧！',Feature=1,}",
  [48054] = "{id=48054,NameZh='飞翔的迪斯科',Icon='item_48054',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7058,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='传言DJ飞仔黄得了一种不听舞曲就会死的病，连在空中“飞翔”也要跟着复古旋律扭着屁屁，如果你问它最爱听什么类型的音乐，它那犀利的眼神就会穿透墨镜回应你——“迪斯科！怎么可能不知道！”',LoadShowSize=1.5,LoadShowPose={0,0.3,0},}",
  [48055] = "{id=48055,NameZh='囚犯的呢喃',Icon='item_48055',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7037,AdventureValue=1,StorageReward={buffid={80012990}},Condition=8,Desc='依稀能听见一些细碎的呢喃声：“放我出去...”“救命...”',}",
  [48056] = "{id=48056,NameZh='蜂尾',Icon='item_48056',Type=840,MaxNum=99,SellPrice=100,AdventureSort=160,AdventureValue=80,StorageReward={buffid={80013070}},Condition=8,Desc='“有只小蜂兵呀，飞在花丛中呀~”',LoadShowSize=2,LoadShowRotate=70,LoadShowPose={0.4,0.2,0},}",
  [48057] = "{id=48057,NameZh='梦眼崽',Icon='item_48057',Type=840,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10105,AdventureValue=1,StorageReward={buffid={80013020}},Condition=8,Desc='受到梦罗克气息影响而变异的魔物，全大陆的专家都不知道它算什么品种，不过目前看来不仅挺可爱的，还有点蠢~',Feature=1,LoadShowSize=2,LoadShowPose={0,0.5,0},}",
  [48058] = "{id=48058,NameZh='力天使',Icon='item_48058',Type=840,MaxNum=99,SellPrice=100,}",
  [48059] = "{id=48059,NameZh='第六使徒',Icon='item_48059',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15136,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='朋友，你喜欢玩蓝色的魔方吗？',Feature=1,TFValidDate='2019-01-28 05:00:00',ValidDate='2019-01-31 05:00:00',LoadShowSize=1.5,LoadShowPose={0,0.1,0},}",
  [48060] = "{id=48060,NameZh='古代逆鳞',Icon='item_48060',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10112,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='古代时期古龙族的尾巴，据说尾巴曾是古龙作战时的武器，一旦刺入敌人的身体，鳞片就会张开，随后释放出喷涌的毒液。',LoadShowSize=2,LoadShowRotate=50,LoadShowPose={0,0.5,0},}",
  [48061] = "{id=48061,NameZh='赤鳞斗士',Icon='item_48061',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52007,AdventureValue=140,StorageReward={buffid={80012920}},Condition=8,Desc='“把他们全部变成烤肉！就是这样！嘎噢！”这个好斗的小家伙脑子里只有一个字：战！！',LoadShowSize=2,LoadShowPose={0},}",
  [48062] = "{id=48062,NameZh='冰心之愿',Icon='item_48062',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9600,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='对神明许愿，对四叶草许愿，对着这颗传说中的冰雪之心许愿。我的足迹遍布整个米德加尔特大陆，寻觅能够实现愿望的圣物。我唯一的愿望，就是你。',LoadShowSize=1.5,LoadShowPose={0,-0.5,0},}",
  [48063] = "{id=48063,NameZh='西瓦诺诺',Icon='item_48063',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9601,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='生活在永久冻土的雪精灵被称为“西瓦诺诺”，传说中，它们是由冰之魔女用雪花创造出来的。虽然看起来很像姜饼城的魔法雪人，但西瓦诺诺们精通冰雪魔法并且不会融化，除非触碰到痴情人的炙热泪水。',LoadShowSize=1.5,LoadShowPose={0},}",
  [48064] = "{id=48064,NameZh='大天使加利尔',Icon='item_48064',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15129,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='天边响起温柔的回声，加利尔在云中低唱。“爱是静夜的风霜、清晨的雨露，是夏日第一朵玫瑰的蓓蕾，是恒久的等待与慈悲。”',Feature=1,TFValidDate='2019-01-07 05:00:00',ValidDate='2019-01-10 05:00:00',LoadShowSize=2,LoadShowPose={0,0.15,0},}",
  [48065] = "{id=48065,NameZh='福禄小猪',Icon='item_48065',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15147,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='憨态可掬的小猪，人见人爱，是新年里吉祥如意的象征。如果捏捏它的耳朵许下心愿，说不定会有好事发生哦！',Feature=1,TFValidDate='2019-01-28 05:00:00',ValidDate='2019-02-04 05:00:00',LoadShowPose={0,0.3,0},}",
  [48066] = "{id=48066,NameZh='锦宝',Icon='item_48066',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9604,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='这个小家伙能为它的主人带来用不完的好运与欢笑，看着它吐泡泡卖萌的模样，你难道不想把它带回家嘛！',Feature=1,TFValidDate='2019-02-01 05:00:00',ValidDate='2019-02-01 05:00:00',LoadShowSize=2,LoadShowPose={0,0.5,0},}",
  [48067] = "{id=48067,NameZh='斗牛鬼鬼',Icon='item_48067',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52011,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='这个顶着牛角帽的小家伙认真起来，可不是闹着玩的，小心你的屁股！',Feature=1,LoadShowSize=2,LoadShowPose={0},}",
  [48068] = "{id=48068,NameZh='蕊蕊',Icon='item_48068',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9611,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='作为可爱的花蕊精灵，蕊蕊只出现在誓约守护天地树的人类面前。白色的花瓣洋裙是她最喜欢的打扮，头顶的叶子能让她在琉璃森林中来回穿行。',TFValidDate='2019-03-01 05:00:00',ValidDate='2019-03-01 05:00:00',LoadShowSize=2,LoadShowPose={0,0.5,0},}",
  [48069] = "{id=48069,NameZh='冲刺哥布灵',Icon='item_48069',Type=840,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10131,AdventureValue=100,AdventureReward={buffid={61000860}},StorageReward={buffid={80012640}},Condition=4,ComposeID=17069,Desc='速度、热血与飞驰！这就是冲刺的人生！春日之光笼罩大地，而哥布灵的冒险永无止境！',Feature=1,TFValidDate='2019-03-29 05:00:00',ValidDate='2019-04-01 05:00:00',}",
  [48070] = "{id=48070,NameZh='英灵永寂',Icon='item_48070',Type=840,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=52026,AdventureValue=1,StorageReward={buffid={80013030}},Condition=8,Desc='“魔剑徘徊至深渊，孤寂的英雄沉眠于月光。往昔驰骋之影，遥忆星河之彼方。”——《勇者之诗·终章》',LoadShowSize=2,LoadShowPose={0},}",
  [48071] = "{id=48071,NameZh='小甜嗡',Icon='item_48071',Type=840,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=924,AdventureValue=390,AdventureReward={buffid={61000490}},StorageReward={buffid={80013030}},Condition=4,ComposeID=17071,Desc='辛勤劳作的小甜嗡最爱跟在主人身旁，如果它的脸上露出了小小的红晕，那可能是你的笑容让它想起了最美的蓝莓花。',LoadShowSize=2,LoadShowPose={0,0.5,0},}",
  [48072] = "{id=48072,NameZh='雷鸣号歼灭机',Icon='item_48072',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52029,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='“控制面板显示良好！”“燃油储备情况良好”“机翼及机身情况良好”“飞行前期准备完成！”“飞行员布鲁多！做好觉悟了么！”“做好觉悟了！上尉！为了所肩负的责任与希望！雷鸣号必将翱翔于蓝天之上！汪！”',LoadShowSize=1.5,LoadShowPose={0,0.4,0},}",
  [48073] = "{id=48073,NameZh='狮心王',Icon='item_48073',Type=840,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10167,AdventureValue=1,AdventureReward={buffid={62000040}},StorageReward={buffid={82000030}},Condition=8,Desc='狮心王的陪伴让你永远有一颗勇敢的心。',Feature=1,TFValidDate='2023-07-17 05:00:00',ValidDate='2023-07-24 05:00:00',}",
  [48076] = "{id=48076,NameZh='附灵卷轴',Icon='item_48076',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7072,AdventureValue=140,AdventureReward={buffid={61001160}},StorageReward={buffid={80012930}},Condition=4,ComposeID=17076,Desc='“迷途的人啊，你心中是否存有困惑与迷惘？将你的灵魂献祭于吾，将你的心愿在卷轴上书写，吾将传达神谕，为你指引真正的方向。”',}",
  [48077] = "{id=48077,NameZh='九尾猫尾巴',Icon='item_48077',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=837,AdventureValue=180,AdventureReward={buffid={61001090}},StorageReward={buffid={80012930}},Condition=4,ComposeID=17077,Desc='只存在于传说中的九尾猫灵，是远星大陆的丰收之神。多兰族的小猫咪们每年的狂欢节都会佩戴它的尾巴，以表敬仰。',}",
  [48078] = "{id=48078,NameZh='堕落辉光',Icon='item_48078',Type=840,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=52033,AdventureValue=1,StorageReward={buffid={80012810}},Condition=8,Desc='曾是某位剑士的随身佩剑，但随着死亡之塔的诅咒日益魔化。似乎是一缕执念，让它依旧闪烁着过去的光芒。',Feature=1,}",
  [48079] = "{id=48079,NameZh='慵懒假日',Icon='item_48079',Type=840,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=938,AdventureValue=180,AdventureReward={buffid={61001090}},StorageReward={buffid={80012930}},Condition=4,ComposeID=17079,Desc='杰克船长在某个晴朗的夏日，把多拉贡岛上最大的海螺改造成了自己的私人浴缸。',}",
  [48080] = "{id=48080,NameZh='夏日香蕉船',Icon='item_48080',Type=840,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=941,AdventureValue=260,AdventureReward={buffid={61000750}},StorageReward={buffid={80012590}},Condition=4,ComposeID=17080,Desc='塔妮小姐制作的香蕉船冰淇淋，据说把多拉贡岛上能用的糖果酱都浇上了，还赔上了一颗香蕉树。',}",
  [48081] = "{id=48081,NameZh='食人芽芽',Icon='item_48081',Type=840,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=944,AdventureValue=190,AdventureReward={buffid={61000870}},StorageReward={buffid={80012640}},Condition=4,ComposeID=17081,Desc='取自吃人草的根茎制成的小尾巴，大长的嘴和吃人草如出一辙，摆动的时候要千万小心，不要伤到别人哦~',}",
  [48082] = "{id=48082,NameZh='冰雕骨脊',Icon='item_48082',Type=840,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=952,AdventureValue=270,AdventureReward={buffid={61000470}},StorageReward={buffid={80012660}},Condition=4,ComposeID=17082,Desc='它是寒冰雕像的前身——骑士查尔斯的脊梁，它有着自主意识，并且与查尔斯生前的性格一样，强大而坚毅但又残暴嗜血，想要驯服它的人必须是真正的勇士。',}",
  [48083] = "{id=48083,NameZh='条纹喵尾',Icon='item_48083',Type=840,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=832,AdventureValue=240,AdventureReward={buffid={61000470}},StorageReward={buffid={80012940}},Condition=4,ComposeID=17083,Desc='手感很好的大猫尾巴，不过如果乱摸的话会被一爪子拍飞。',}",
  [48085] = "{id=48085,NameZh='坚毅之剑',Icon='item_48085',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52040,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='蓝宝石象征无所畏惧的意志，红宝石象征无坚不摧的力量。佩戴上它的勇士，将在黑暗中披荆斩棘，在阳光下熠熠生辉。',}",
  [48086] = "{id=48086,NameZh='海魂尾翼',Icon='item_48086',Type=840,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=967,AdventureValue=270,AdventureReward={buffid={61000500}},StorageReward={buffid={80012920}},Condition=4,ComposeID=17086,Desc='受到深海之魂眷顾的冒险者，将自由遨游于广阔的大洋，与万千生灵意念相通，永远得到祝福和庇护。',Feature=1,}",
  [48087] = "{id=48087,NameZh='白蛇风铃',Icon='item_48087',Type=840,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=970,AdventureValue=390,AdventureReward={buffid={61000730}},StorageReward={buffid={80012590}},Condition=4,ComposeID=17087,Desc='叮铃铃，叮铃铃……风铃声响起时抬头眺望，远行的故人是否也能听见风中的想念呢？',Feature=1,}",
  [48088] = "{id=48088,NameZh='流金龙吟',Icon='item_48088',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7085,AdventureValue=1,StorageReward={buffid={80013010}},Condition=8,Desc='将舞动的双龙作对称设计，尽显端庄大气。暖黄色的灯光让灯上的双龙更为迷人。',}",
  [48089] = "{id=48089,NameZh='欢跃青龙',Icon='item_48089',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7086,AdventureValue=1,StorageReward={buffid={80012610}},Condition=8,Desc='冷色调的小龙与暖色调的鼓交相辉映，美观与趣味性并存。',}",
  [48090] = "{id=48090,NameZh='钵昙摩花',Icon='item_48090',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7100,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='银鱼湖最常见的花，色作粉白，花型丰硕，寓意重生。别名唤作钵昙摩，据说城主特别喜欢。',}",
  [48092] = "{id=48092,NameZh='衔着花的蛇',Icon='item_48092',Type=840,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=7107,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='初春的蛇，刚经过了整个冬天的冬眠，拖着仍然有些僵硬的身体爬到灯笼上，就为了折一只带着露珠的桃花。',}",
  [48094] = "{id=48094,NameZh='爱与勇气的纪念',Icon='item_48094',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10204,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='冒险者，曾经的那些温暖而快乐的时光并没有离你远去呢，它们一定会乘上柔软的双翼，陪伴着你开启下一段难忘的旅程。冒险，永不会结束！',StageDisplay=0,}",
  [48095] = "{id=48095,NameZh='甜梦奶油喵',Icon='item_48095',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52044,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='呼呼大睡的猫猫总喜欢蜷成一团，不知为何看到它就想吃奶油了。',}",
  [48096] = "{id=48096,NameZh='灾厄之焰',Icon='item_48096',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10228,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='存有灾厄炎龙之息的灯笼，烈焰带来的光明，是划破黑暗的利器',}",
  [48098] = "{id=48098,NameZh='迷藏兔',Icon='item_48098',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7112,AdventureValue=1,StorageReward={buffid={80012600}},Condition=8,Desc='喜欢捉迷藏的小兔子，把自己藏在球中——“看不见我，看不见我……”',LoadShowPose={0,0.1,0},}",
  [48099] = "{id=48099,NameZh='精灵灯',Icon='item_48099',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52046,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='异域的造物，寄宿着精灵的神灯。',LoadShowSize=1.5,LoadShowPose={0,-0.39,0},}",
  [48101] = "{id=48101,NameZh='道德速记精灵',Icon='item_48101',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10280,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='人在做天在看，不仅在看还帮你统统记下来……不论是对是错，都会忠实地把主人的言行记录下来的小精灵，今天也在身后静静地守护着你哟。',TFValidDate='2020-09-05 05:00:00',ValidDate='2020-10-17 05:00:00',}",
  [48102] = "{id=48102,NameZh='绳文仔',Icon='item_48102',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52051,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='“你知道吗？绳文时代始于公元前12000年，直到公元前300年才结束噢~”',LoadShowPose={0,-0.4,0},}",
  [48103] = "{id=48103,NameZh='妖精灵探',Icon='item_48103',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7126,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='这个小家伙喜欢搜寻世间的秘闻——不过不要试图窥探他人的隐私哦！',LoadShowPose={0,-0.25,0},}",
  [48105] = "{id=48105,NameZh='紫晶伴生灵',Icon='item_48105',Type=840,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=985,AdventureValue=270,AdventureReward={buffid={61000470}},StorageReward={buffid={80012940}},Condition=4,ComposeID=17105,Desc='具有强大魔力的宝石会在各种机缘巧合中形成伴生灵。根据母体宝石的不同，伴生灵也拥有不同的力量，而紫水晶的伴生灵会帮助主人躲避不幸。',}",
  [48107] = "{id=48107,NameZh='偷星魔女',Icon='item_48107',Type=840,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10308,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='活跃在首都的怪盗団体，对各种传说中的秘宝有着浓厚兴趣，真实身份是一群热爱音乐的美少女。“说不定会顺便偷走你的心哦！”',LoadShowSize=3,LoadShowRotate=-15,LoadShowPose={0,0.5,-0.5},}",
  [48108] = "{id=48108,NameZh='校舍管理员',Icon='item_48108',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10317,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='王立克里图拉学院的校舍管理员休格，朱诺的贤者们研制的最新一代魔法造物，是个一丝不苟的“人”。在他上任以后，学生们的缺勤率大大降低了。',Feature=1,TFValidDate='2020-12-30 05:00:00',ValidDate='2021-01-06 05:00:00',}",
  [48109] = "{id=48109,NameZh='犬行灯',Icon='item_48109',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52054,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='既然这世上有灯笼鱼的存在，那有灯笼狗也很正常的吧？',}",
  [48110] = "{id=48110,NameZh='冰原来客',Icon='item_48110',Type=840,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=995,AdventureValue=270,AdventureReward={buffid={61001090}},StorageReward={buffid={80012660}},Condition=4,ComposeID=17110,Desc='小海豹在海中迷失了方向，待它看到陆地时，已经身处名叫“克魔岛”的陌生地域，在这里它遇到了自己的同类，令它惊奇的是，这里的海豹竟然连雪都没有见过！\n“这么热的地方，你们是怎么坚持下来的！”',Feature=1,LoadShowPose={0,-0.2,0},}",
  [48111] = "{id=48111,NameZh='提灯矿精',Icon='item_48111',Type=840,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=1002,AdventureValue=270,AdventureReward={buffid={61000470}},StorageReward={buffid={80012940}},Condition=4,ComposeID=17111,Desc='孤单的矿石精终于找到了它的第一个朋友，它会紧紧跟在朋友身边的！\n“只要拎着提灯，别人就能注意到我了哦！”',Feature=1,}",
  [48112] = "{id=48112,NameZh='波姬绒绒',Icon='item_48112',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10345,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='用白色毛线团成团子，摘一片树叶点缀，再用两颗蓝宝石做眼睛。好了，波姬绒绒就完成了！',LoadShowRotate=-15,LoadShowPose={0.4,-0.2,-1},}",
  [48113] = "{id=48113,NameZh='冥府之眼',Icon='item_48113',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52057,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='亡魂秩序官克里克借助冥府之眼审查死者生前的罪行，那些邪恶的灵魂会被他毫不犹豫的推入冥河，接受痛苦的审判。',LoadShowSize=1.5,LoadShowPose={0,-0.5,0},}",
  [48115] = "{id=48115,NameZh='冥界使者',Icon='item_48115',Type=840,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=1005,AdventureValue=390,AdventureReward={buffid={61000730}},StorageReward={buffid={80013050}},Condition=4,ComposeID=17115,Desc='海拉的使者，通过烛火和引魂铃指引亡者的灵魂进入尼夫海姆……等等，为什么你能看到它？！',}",
  [48116] = "{id=48116,NameZh='马戏之王',Icon='item_48116',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10375,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='“看我精致华丽的扮相、轻盈流畅的杂耍动作，还有什么烦恼是忘不掉的呢？先生小姐们赶快来赶快来！”',Feature=1,LoadShowPose={0,-0.5,0},}",
  [48117] = "{id=48117,NameZh='仙林之友',Icon='item_48117',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52060,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='生活在“仙林”深处的哗啦啦和喀拉拉是一对好朋友，他们最喜欢玩“一二三石头人”的游戏。',LoadShowPose={0,0,-0.3},}",
  [48118] = "{id=48118,NameZh='谜局之王',Icon='item_48118',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10461,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='他是执棋者，还是别人手中的棋子？',LoadShowSize=2,LoadShowPose={0,-0.5,0.6},}",
  [48119] = "{id=48119,NameZh='王室威仪',Icon='item_48119',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10483,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='身为贵族，要时刻保持如雄狮一般的威严，嗷呜~~',}",
  [48120] = "{id=48120,NameZh='呼喊草精',Icon='item_48120',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52068,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='一只精力过剩的草精，地龙骑士的好朋友，会在地龙骑士战斗时为它加油助威。',}",
  [48121] = "{id=48121,NameZh='小白鹫',Icon='item_48121',Type=840,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=1014,AdventureValue=270,AdventureReward={buffid={61000470}},StorageReward={buffid={80012620}},Condition=4,ComposeID=17121,Desc='幼年期的白鹫，因为身体虚弱，而被兄弟姐妹挤出了巢穴。为了让它活下去，只能拜托冒险者你收养它啦~',}",
  [48122] = "{id=48122,NameZh='恶魔锹型虫',Icon='item_48122',Type=840,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=1009,AdventureValue=190,AdventureReward={buffid={61001110}},StorageReward={buffid={80012640}},Condition=4,ComposeID=17122,Desc='究极进化的锹型虫，似乎受到了心灵猎场力量的感染。放任他乱跑太危险了，还请冒险者看住他吧~',LoadShowPose={0,0,0},}",
  [48123] = "{id=48123,NameZh='伞蜥气球',Icon='item_48123',Type=840,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=1012,AdventureValue=190,AdventureReward={buffid={61000460}},StorageReward={buffid={80012640}},Condition=4,ComposeID=17123,Desc='印着伞蜥头的气球，附加了跟踪魔法，所以能够跟着主人一起移动。然而，不知道是不是错觉……气球上的伞蜥，看起来更傻了呢！',}",
  [48124] = "{id=48124,NameZh='迷梦猫尾',Icon='item_48124',Type=840,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=1015,AdventureValue=390,AdventureReward={buffid={61000730}},StorageReward={buffid={80013050}},Condition=4,ComposeID=17124,Desc='虽然只是仿制的假体，但无论皮毛的色泽还是摇晃的动态，都与真正的尾巴无异。戴着这样的饰物走进夜色，恐怕会把胆小的旅人吓坏——“猫妖变成人类的形态了！他要把我抓走了！”',}",
  [48126] = "{id=48126,NameZh='雪鸮先生',Icon='item_48126',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7155,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='被宫廷贵妇们从小豢养的宠物，习性中已经看不到猛禽的彪悍与勇武。不过，其华美的外表与绝对的忠诚，还是值得称道的。',}",
  [48127] = "{id=48127,NameZh='力哈尔特的诅咒',Icon='item_48127',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10477,AdventureValue=100,AdventureReward={buffid={61000590}},StorageReward={buffid={80012840}},Condition=4,ComposeID=17127,Desc='施展于朽木之上的力哈尔特的诅咒，是何人所下？又有何目的？',}",
  [48128] = "{id=48128,NameZh='小白鸽',Icon='item_48128',Type=840,MaxNum=99,SellPrice=100,AdventureSort=7163,AdventureValue=1,StorageReward={buffid={82000110}},Condition=8,Desc='有着滚圆雪白的身躯，以及迷你豆豆眼的鸽子。但如果你夸奖它可爱的话，它是会生气的。“咕！人家是帅气的男孩子咕！”',}",
  [48129] = "{id=48129,NameZh='小黑鸽',Icon='item_48129',Type=840,MaxNum=99,SellPrice=100,AdventureSort=7164,AdventureValue=1,StorageReward={buffid={82000120}},Condition=8,Desc='暗恋着小白鸽的小黑鸽，总因为自己的外表感到自卑。“咕咕、咕咕……我也想变成白鸽子呀。”',}",
  [48130] = "{id=48130,NameZh='塔妮的香蕉船',Icon='item_48130',Type=840,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=1016,AdventureValue=390,AdventureReward={buffid={61000730}},StorageReward={buffid={80013050}},Condition=4,ComposeID=17130,Desc='以塔妮小姐为原型制作的装饰品，看起来完全没有威胁性。不过她手里的叉子，倒是挺尖锐的样子，小心别被戳中哦~',Feature=1,LoadShowPose={0,-0.5,0},}",
  [48131] = "{id=48131,NameZh='不屈的芽芽勇士',Icon='item_48131',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52072,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='头戴钢盔的芽芽勇士，即便后脑中箭，也能露出顽强而坚强的微笑。不过这小家伙，怎么看都不太聪明的样子，并不能与主人并肩战斗呢。',}",
  [48132] = "{id=48132,NameZh='雷根弗莱格的家训',Icon='item_48132',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7176,AdventureValue=1,StorageReward={buffid={80012630}},Condition=8,ComposeID=17132,Desc='雷根弗莱格家的家风严谨，对家族成员的管束也十分严苛。传闻，雷根弗莱格家的成员如果违反了家训，就会被关进小黑屋里，抄写家训，如果偷懒的话卷轴中会出现雷根弗莱格家的家养小恶魔出来给予人一生难忘的惩罚。',}",
  [48133] = "{id=48133,NameZh='百响礼炮',Icon='item_48133',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52077,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='“让我把世界上最绚烂缤纷的礼花带给你，因你生来独一无二，我们热情狂欢，为你闪闪发光的人生喝彩。”',}",
  [48134] = "{id=48134,NameZh='凤栖幼龙·赛季',Icon='item_48134',Type=840,Quality=4,MaxNum=99,SellPrice=100,Desc='《注意》该装备属性及其卡片、附魔等效果仅在公会战相关地图生效，且升级后无法还原。赛季开始后将由不思议贩卖机进行回收。',NoStorage=5,}",
  [48135] = "{id=48135,NameZh='星弦导航仪·赛季',Icon='item_48135',Type=840,Quality=4,MaxNum=99,SellPrice=100,Desc='《注意》该装备属性及其卡片、附魔等效果仅在公会战相关地图生效，且升级后无法还原。赛季开始后将由不思议贩卖机进行回收。',NoStorage=5,}",
  [48136] = "{id=48136,NameZh='流星·赛季',Icon='item_48136',Type=840,Quality=4,MaxNum=99,SellPrice=100,Desc='《注意》该装备属性及其卡片、附魔等效果仅在公会战相关地图生效，且升级后无法还原。赛季开始后将由不思议贩卖机进行回收。',NoStorage=5,}",
  [48137] = "{id=48137,NameZh='鳌龙之尾',Icon='item_48137',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10525,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='红岩鳌龙生活在浅海附近，全身覆盖着如同岩石般坚固的红色鳞片。唯有顶尖的勇士，才能斩断它的躯体，因此鳌龙之尾常被作为力量与勇气的证明。',}",
  [48138] = "{id=48138,NameZh='林隐飞侠',Icon='item_48138',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10539,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='栖息在流星林竹林中的小熊猫，向往着流星林弟子们行侠仗义的生活，渴望成为一代大侠。最讨厌的事是被误认为浣熊。',}",
