  [48567] = "{id=48567,NameZh='英灵·破灭雷纹',Icon='item_48567',Type=830,Quality=2,MaxNum=99,SellPrice=100,Desc='全知神——亚尔薇特赐予有重大贡献的人们破灭雷纹，这是英灵殿的象征之一，只有得到赐予的人才能在死后进入英灵殿，成为一名强大的英灵。',Feature=1,LoadShowSize=5,LoadShowPose={0,0.5,0},}",
