  [48581] = "{id=48581,NameZh='毒药伯爵面具',Icon='item_48581',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9504,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='公爵是教皇和不知名女性的私生子，由于从小的遭遇，年纪轻轻就成为了著名的野心家。不仅和自己的亲妹妹发生了禁断之恋，还将妹妹当工具不断地嫁出去，并在抢得男方的领地后将男方毒杀，手段极其的残忍，充满了一种变态的蔷薇美学。',Share=1,Feature=1,LoadShowSize=2,LoadShowPose={0,0.7,0},}",
  [48582] = "{id=48582,NameZh='爱心红晕',Icon='item_48582',Type=830,MaxNum=99,SellPrice=100,AdventureSort=9009,AdventureValue=90,StorageReward={buffid={80012060}},Condition=8,Desc='夏天是个美丽的季节，看着你微笑的脸充满着爱意，世界变成了爱心的形状。',Share=1,Feature=1,LoadShowSize=6,LoadShowPose={0,0.5,0},}",
  [48583] = "{id=48583,NameZh='梦中的婚礼',Icon='item_48583',Type=800,Quality=3,MaxNum=99,SellPrice=100,Desc='【不管未来变得如何艰难】，【我都会继续守护着你】，【如纯洁美丽的蔷薇般】，【这是送给你的爱之诗歌】',Share=1,LoadShowSize=2,LoadShowPose={0,1,0},}",
  [48584] = "{id=48584,NameZh='杰克南瓜·不是灯',Icon='item_48584',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9518,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='徘徊于暗夜，用惯了“六便士的把戏”，比起白萝卜找到了更适合的归宿，在即将天亮的时刻，小孩子摔倒了，那么，猜猜~在后面的那个人是谁？',Share=1,Feature=1,LoadShowSize=2,LoadShowPose={0,0.6,0},}",
  [48585] = "{id=48585,NameZh='艾希流苏',Icon='item_48585',Type=830,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10020,AdventureValue=90,StorageReward={buffid={80012360}},Condition=8,Desc='黑色的幕布已经降下，艾希继续着她的旅行，她有着必须与之重逢的人，直到找到与TA重逢的方法，她会一直旅行下去。',Share=1,Feature=1,LoadShowSize=2,LoadShowPose={0,0.7,0},}",
  [48586] = "{id=48586,NameZh='中秋月饼',Icon='item_48586',Type=830,MaxNum=99,SellPrice=100,Desc='每年农历8月15日的月亮是一年中最大最圆。据说向中秋月亮祈愿可以实现。',Share=1,}",
  [48587] = "{id=48587,NameZh='英灵·破灭雷纹（换色）',Icon='item_48587',Type=830,Quality=2,MaxNum=99,SellPrice=100,Desc='全知神——亚尔薇特赐予有重大贡献的人们破灭雷纹，这是英灵殿的象征之一，只有得到赐予的人才能在死后进入英灵殿，成为一名强大的英灵。',Feature=1,LoadShowSize=4,LoadShowPose={0,0.7,0},}",
  [48588] = "{id=48588,NameZh='英灵·雷霆之瞳（换色）',Icon='item_48588',Type=830,Quality=2,MaxNum=99,SellPrice=100,Desc='全知神——亚尔薇特赐予有重大贡献的人们雷霆之瞳，这是英灵殿的象征之一，只有得到赐予的人才能在死后进入英灵殿，成为一名强大的英灵。',Feature=1,}",
  [48589] = "{id=48589,NameZh='我心如雪',Icon='item_48589',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9523,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='“在雪地上奔跑，风在孩子们的身后，雪的精灵正在守护着孩子们。记得要来这里玩耍呦~记得要来呦~”你悄悄地合上了书本，其中所描绘的画面已经触动你的心弦，你围上围巾，推开了门，走向了银白的世界。笑的像个孩子。',Feature=1,LoadShowSize=4,LoadShowPose={0,1,0},}",
