  [48600] = "{id=48600,NameZh='望向未来镜',Icon='item_48600',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9530,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='“当你眺望着未来，未来也同时眺望着你。”',Feature=1,LoadShowSize=3,LoadShowPose={0,0.5,0},}",
  [48601] = "{id=48601,NameZh='米德加尔特护目镜',Icon='item_48601',Type=830,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=52002,AdventureValue=170,StorageReward={buffid={80012820}},Condition=8,Feature=1,LoadShowSize=3,LoadShowPose={0,0.5,0},}",
  [48602] = "{id=48602,NameZh='米德加尔特军用口罩',Icon='item_48602',Type=850,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=52003,AdventureValue=170,StorageReward={buffid={80012820}},Condition=8,Feature=1,LoadShowSize=4,LoadShowPose={0,0.5,0},}",
  [48603] = "{id=48603,NameZh='吃货的怨念',Icon='item_48603',Type=830,MaxNum=99,SellPrice=100,AdventureSort=10050,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='是电是光是那一道火花，那是爱恋的视线，是倾慕的汪洋，一道凝结的光射穿美食之国的门扉。【作者：兔女郎杰奎琳】',Feature=1,LoadShowSize=3,LoadShowPose={0,0.5,0},}",
  [48604] = "{id=48604,NameZh='恋之蝶',Icon='item_48604',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9533,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='“人们将那天称为节日、那不知从何时开始蔓延的热情，正如灼热的火焰越烧越旺。那如梦似幻的蝴蝶，闪耀着诱惑的光芒，将我引入那火焰，燃烧身躯，眼神迷离。啊~欧罗拉呦~亲爱的欧罗拉呀~你如今身在何方？”',Feature=1,LoadShowSize=3,LoadShowPose={0,0.5,0},}",
  [48605] = "{id=48605,NameZh='玫瑰花纱巾',Icon='item_48605',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9536,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='蔷薇隐藏起我的爱慕，这个还未开春的季节，脸上温热的红晕，正是因为你。焦虑踌躇着，盼望着那一天的到来。等着你的那句话。为了这个情景，我每天都在努力练习SAY YES。',Feature=1,LoadShowSize=3,LoadShowPose={0,0.7,0},}",
  [48606] = "{id=48606,NameZh='般若之面',Icon='item_48606',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=762,AdventureValue=160,AdventureReward={buffid={61000450}},StorageReward={buffid={80012880}},Condition=4,ComposeID=17606,Desc='因女人强烈的怨恨而形成的恶鬼般若，是普通鬼怪都害怕的恶灵。天水之国的巫女们将般若的面孔画在白色的面具之上，制作成般若之面，送给需要夜行的游人，保护他们不受野鬼的骚扰和袭击。',LoadShowSize=3,LoadShowPose={0,0.3,0},}",
  [48607] = "{id=48607,NameZh='富裕之窗',Icon='item_48607',Type=830,MaxNum=99,SellPrice=100,AdventureSort=10060,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='充满对财富渴望的眼神，据说财神会对这样的人“格外关照”哦。',Feature=1,LoadShowSize=4,LoadShowPose={0,0.5,0},}",
  [48608] = "{id=48608,NameZh='月夜樱·真恋',Icon='item_48608',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9541,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='早春料峭，夜樱夹道。“花下浪漫 ，君最美，以前你常对我说用这种害羞的话呢~是吧，五郎~”少女梅尔想起绘本上的这句话，慢慢将亲手织成想要送给最重要的少年的樱色围巾戴上。微风吹过，掌心捧着的花瓣扶摇而起，越过枝头，衬着月色飘向远方~',Feature=1,LoadShowSize=3,LoadShowPose={0,1,0},}",
  [48609] = "{id=48609,NameZh='樱花纹',Icon='item_48609',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9542,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='ka go me ka go me、ka go no na ka no to ri wa、i tsu i tsu de ya ru、yo a ke no ba n ni、tsu ru to ka me ga su be tta、u shi ro no syou me n da a re？',Feature=1,LoadShowSize=4,LoadShowPose={0,0.5,0},}",
  [48610] = "{id=48610,NameZh='樱之花嫁',Icon='item_48610',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10062,AdventureValue=110,AdventureReward={buffid={61000470}},StorageReward={buffid={80012660}},Condition=4,ComposeID=17610,Desc='继承了樱花城传统工艺的发饰，以樱花为造型，被八百万神灵所祝福的饰品。',Feature=1,LoadShowSize=3,LoadShowRotate=0,LoadShowPose={0,0.7,0},}",
  [48611] = "{id=48611,NameZh='贤者之书',Icon='item_48611',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9543,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='少年终于还是没有回来，翻阅完书本的他眼中绽放出的是如同神的制裁之光般的狂热，之后的几年间，少年所前往方向的国家都被战争和革命的战火所包围，记载先祖知识和睿智的大书库一个个被烧毁。几个世纪后，金发的洋装少女在废旧的公爵宅邸种再次翻开被重重灰尘所覆盖的残破老旧书本，那最后少年所没看到的一页写着：“哥哥，等你回来后，我要做你的新娘呢！，（铃铃铃铃铃~~~~~）“好了~今天的历史课就先到这里了~同学们下课，记得明天要把冒险实验作业交给阿尔维特君呦~”',Feature=1,LoadShowSize=2,LoadShowRotate=0,LoadShowPose={0,-0.4,0},}",
  [48612] = "{id=48612,NameZh='真的喜欢你哟',Icon='item_48612',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9544,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='这里是被称为蔷薇禁区的少女放课后时间，黄昏的课桌旁，脸红心跳交流着恋之心得，平时最拿手的各种算数和方程式，在这里完全用不上。在洁白的纸上要写上短短的国语老师并不会传授的话语，小心翼翼盖上玫瑰色火漆的时候还差点笨头笨脑地烫得眼泪如珍珠滴落，直到那个人收到前，心跳都是物理学无法解释的现象。“呐~放学后你会在操场后花园等我吗？”',Feature=1,LoadShowSize=6,LoadShowRotate=0,LoadShowPose={0,1.1,0},}",
  [48613] = "{id=48613,NameZh='SAKURA·SAKURA',Icon='item_48613',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9019,AdventureValue=90,StorageReward={buffid={80012640}},Condition=8,Desc='散落的花瓣，如同萦绕心中的思绪，琦啦啦~琦啦啦~地随着这4月的春风吹拂过，花期短暂，望君珍惜。',Feature=1,LoadShowSize=10,LoadShowRotate=0,LoadShowPose={-0.3,1.3,0},}",
  [48614] = "{id=48614,NameZh='鬼脸面具',Icon='item_48614',Type=830,MaxNum=99,SellPrice=100,Feature=1,LoadShowSize=3,LoadShowRotate=0,LoadShowPose={0,0.1,0},}",
  [48615] = "{id=48615,NameZh='黄金思维',Icon='item_48615',Type=830,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10071,AdventureValue=160,AdventureReward={buffid={61000590}},StorageReward={buffid={80012640}},Condition=4,ComposeID=17615,Desc='一位叫弗兰肯斯坦的科学家曾经说过，只要把螺丝装在脑袋上，思维运转的速度就会提高三倍噢。',Feature=1,LoadShowSize=4,LoadShowRotate=20,LoadShowPose={0.3,0.1,0},}",
  [48619] = "{id=48619,NameZh='北国的方块传说',Icon='item_48619',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9553,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='在莫斯科近郊的傍晚，厚厚的北国衣装包裹着赛尼亚的身体，初次到访旅行至此还不太习惯这里的气候。就在这时刻。圆曲别致的高耸建筑塔顶的上空升腾起五光十色的烟花。伴随【卖货郎】的广场演奏，赛尼亚回想起那有趣的游戏，让她消磨掉无数时光，简单而又快乐的游戏的最初。',Feature=1,LoadShowSize=4,LoadShowRotate=0,LoadShowPose={0.2,0.7,0},}",
  [48620] = "{id=48620,NameZh='魔王眼罩',Icon='item_48620',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=15024,AdventureValue=1,StorageReward={buffid={80012830}},Condition=8,Desc='从眼睛里泄露出去的信息往往会成为敌人击败你的致命武器，戴上魔王眼罩之后即使是微笑都会变得很邪恶，所以魔王眼罩在恶魔之国可是很热销的哦~',Feature=1,LoadShowSize=4,LoadShowRotate=0,LoadShowPose={0.2,0.2,0},}",
  [48621] = "{id=48621,NameZh='三兄弟·贝壳魔灵',Icon='item_48621',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9565,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='“这是我一个人的的漂亮围巾！除了我谁也不能戴上这条漂亮围巾！！”贝壳魔灵霸道的宣布。（用贝壳与珍珠装饰而成的热带风景围巾，围巾扣子的地方有一只大的贝壳魔灵。）',Feature=1,LoadShowSize=3,LoadShowRotate=0,LoadShowPose={0,0.7,0},}",
