  [48623] = "{id=48623,NameZh='三兄弟·海星星',Icon='item_48623',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9566,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='来自克魔岛的爆款旅游纪念品！！真是奇怪，为什么会有人喜欢把黏乎乎、软趴趴的海星顶在头上呢……',Feature=1,LoadShowSize=5,LoadShowRotate=0,LoadShowPose={0,0.2,0},}",
