  [48629] = "{id=48629,NameZh='炙热的眼眸',Icon='item_48629',Type=830,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=730,AdventureValue=160,AdventureReward={buffid={61001110}},StorageReward={buffid={80012640}},Condition=4,ComposeID=17629,Desc='听说所有火焰精灵从出生的那一刻就不会眨眼，久而久之，它们不小心全都练出了这种看起来很认真的眼神……',LoadShowSize=5,LoadShowRotate=0,LoadShowPose={0,0,0},RefineStorageReward={{buffid={65000070},lv=6},{buffid={66000160},lv=8}},}",
