  [48639] = "{id=48639,NameZh='怪人假面',Icon='item_48639',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9036,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='据说在斯凯领顿庄园里住着一位浑身疤痕的绿色怪人，他最喜欢做的事就是在夜里捉走稻草人做成魔法扫把，每当有小稻草人不肯睡觉时，稻草人妈妈就会说起这个可怕的故事……戴上它去参加假面狂欢节吧！',Feature=1,LoadShowSize=3,LoadShowRotate=0,LoadShowPose={0,0.8,0},}",
