  [48642] = "{id=48642,NameZh='毒伯爵面具',Icon='item_48581',Type=830,Quality=2,MaxNum=99,SellPrice=100,Desc='公爵是教皇和不知名女性的私生子，由于从小的遭遇，年纪轻轻就成为了著名的野心家。不仅和自己的亲妹妹发生了禁断之恋，还将妹妹当工具不断地嫁出去，并在抢得男方的领地后将男方毒杀，手段极其的残忍，充满了一种变态的蔷薇美学。',Share=1,Feature=1,LoadShowSize=3,LoadShowRotate=0,LoadShowPose={0,0.1,0},}",
