  [48652] = "{id=48652,NameZh='收割者匕首',Icon='item_48652',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=51010,AdventureValue=118,StorageReward={buffid={80012620}},Condition=8,Desc='这把匕首是竞技强者荣耀证明，当心！刀上有毒！',Feature=1,LoadShowSize=6,LoadShowRotate=0,LoadShowPose={0.1,0.8,0},}",
  [48653] = "{id=48653,NameZh='嘀嘀叭叭',Icon='item_48653',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9578,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='嘀嘀嘀叭叭叭~！！大家一起吹着嘀嘀叭叭才有音乐祭的热闹气氛呀！但不要凑近别人的耳朵吹哟，不然会……“喔啊啊啊啊啊！吵死了，要聋了啦，呜呜呜！”',LoadShowSize=5,LoadShowRotate=0,LoadShowPose={-0.7,0.6,0},}",
  [48654] = "{id=48654,NameZh='百叶镜',Icon='item_48654',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9026,AdventureValue=110,StorageReward={buffid={80012640}},Condition=8,Desc='出自朱诺夜莺剧院的复古设计！戴上它的瞬间似乎回到充满自由精神的建国时代！有些经典在时间长河的冲刷下反而愈发的闪耀，戴上它，重温那个冒险时代的自由浪潮吧！',LoadShowSize=5,LoadShowRotate=0,LoadShowPose={0,0.3,0},}",
  [48655] = "{id=48655,NameZh='面包加蛋',Icon='item_48655',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9584,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='啊啊啊！上学快迟到了，赶紧叼上加了煎蛋的面包出门吧！在路口的转角，说不定会撞上命中注定的邂逅哟~',TFValidDate='2018-09-11 05:00:00',ValidDate='2018-09-13 05:00:00',LoadShowSize=5,LoadShowRotate=0,LoadShowPose={0,1.2,0},}",
  [48656] = "{id=48656,NameZh='圈圈镜',Icon='item_48656',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9031,AdventureValue=1,StorageReward={buffid={80012920}},Condition=8,Desc='不知道为什么，一看到课本，我就头晕眼花！书上的字符转啊转，转啊转......呃，好像是我的圈圈镜在转~',TFValidDate='2018-09-11 05:00:00',ValidDate='2018-09-13 05:00:00',LoadShowSize=5,LoadShowRotate=0,LoadShowPose={0,0.3,-0.9},}",
  [48657] = "{id=48657,NameZh='阿斯特蕾娅的眷恋',Icon='item_48657',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9581,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='阿斯特蕾娅，你的眼睛里，藏着一个属于我的宇宙。当你眨眼时，日夜交替；当你流泪时，万象静谧。',Feature=1,LoadShowSize=5,LoadShowRotate=0,LoadShowPose={0,0.3,0},}",
