  [48663] = "{id=48663,NameZh='爱心太阳镜',Icon='item_45510',Type=830,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,ComposeID=17663,Desc='黄金假日，是时候带着自己最爱的小波利一起去旅行了~【设计者：LittlewhiteBAO】',Feature=1,LoadShowSize=6,LoadShowRotate=0,LoadShowPose={0.1,0.3,0},}",
  [48664] = "{id=48664,NameZh='纯棉眼罩',Icon='item_48664',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15099,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='纯棉透气并且干净卫生！最重要的是，它能遮住我藏在眼睛里不可诉说的秘密......',Feature=1,TFValidDate='2018-10-16 05:00:00',ValidDate='2018-10-18 05:00:00',}",
  [48665] = "{id=48665,NameZh='黑蝠眼罩',Icon='item_48665',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15100,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='这个充满神秘感的眼罩其实是一只被施了魔法的蝙蝠，如果主人不用鲜血把它喂饱，它就会气鼓鼓地飞走！',Feature=1,TFValidDate='2018-10-16 05:00:00',ValidDate='2018-10-18 05:00:00',}",
  [48666] = "{id=48666,NameZh='吸血尖牙',Icon='item_48666',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15102,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='“一个吸血鬼永远不会知道生活意味着什么，直到鲜血涌上你的双唇”——《夜访德古拉》',Feature=1,TFValidDate='2018-10-16 05:00:00',ValidDate='2018-10-18 05:00:00',}",
