  [48668] = "{id=48668,NameZh='面纹·红蝶',Icon='item_48668',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15111,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='天津町元灵神社的传统面纹，相传其有增强阴阳术的作用。如今的和平年代，常作为节日庆典的装饰用面纹出现在伊达家巫女的脸上。',Feature=1,TFValidDate='2018-11-13 05:00:00',ValidDate='2018-11-15 05:00:00',}",
  [48669] = "{id=48669,NameZh='鲷鱼烧',Icon='item_48669',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15112,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='什么？天津町的面包大叔又出新品了？！赶快去排队尝尝！捧着刚出炉的鲷鱼烧，啊呜~一口咬开它，浓郁香甜的红豆沙沁入口中......唔哇哇哇啊！！！这个味道，就算是大妖怪也无法抗拒吧？',Feature=1,TFValidDate='2018-11-13 05:00:00',ValidDate='2018-11-15 05:00:00',}",
  [48670] = "{id=48670,NameZh='姜饼仔',Icon='item_48670',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15117,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='姜饼这么可爱，为什么要吃姜饼仔！！',}",
