  [48672] = "{id=48672,NameZh='脏乱的胡须',Icon='item_48672',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7046,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='这……这不是吉拉德的胡子吗！？你从哪搞来的？？',LoadShowSize=6,LoadShowRotate=0,LoadShowPose={0.1,0.8,0},}",
