  [48675] = "{id=48675,NameZh='狗尾草',Icon='item_48675',Type=850,MaxNum=99,SellPrice=100,AdventureSort=7042,AdventureValue=1,StorageReward={buffid={80012840}},Condition=8,Desc='“只要5zeny，这个狗尾草卖给你！什么？太贵？那送你好了，反正我多的是。”，无聊的凯撒说。',LoadShowSize=6,LoadShowRotate=0,LoadShowPose={0,1.2,0},}",
