  [48686] = "{id=48686,NameZh='霜羽假面',Icon='item_48686',Type=830,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9597,AdventureValue=1,StorageReward={buffid={82000260}},Condition=8,Desc='寒冰魔女最喜爱的装饰之一，哈比的翎羽与霜槲寄生的露珠被西瓦诺诺的魔法融合为假面上的冰晶霜羽。戴上它，化身为白雪中的精灵吧！',LoadShowSize=2.5,LoadShowPose={0,0.3,0},}",
  [48687] = "{id=48687,NameZh='冰晶·蔷薇',Icon='item_48687',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9602,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='当眼泪从寒冰魔女的脸颊滑落，冰晶蔷薇便在这泪水中生长绽放。即使没有结果，也难忘曾与你牵手看雪。',LoadShowSize=3,LoadShowPose={0.2,0.9,-0.3},}",
