  [48702] = "{id=48702,NameZh='星烁',Icon='item_48702',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9041,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='繁星闪烁，哪一颗曾划过你的脸庞？',TFValidDate='2019-03-01 05:00:00',ValidDate='2019-03-01 05:00:00',LoadShowSize=4,LoadShowPose={0,0.4,0},}",
  [48703] = "{id=48703,NameZh='七彩防护镜',Icon='item_48703',Type=830,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10134,AdventureValue=80,AdventureReward={buffid={61000590}},StorageReward={buffid={80012640}},Condition=4,ComposeID=17703,Desc='戴上七彩防护镜，潇洒自如地参加泼水节吧！',Feature=1,TFValidDate='2019-03-29 05:00:00',ValidDate='2019-04-01 05:00:00',StageDisplay=0,LoadShowSize=3,LoadShowRotate=0,LoadShowPose={0,0.2,0},}",
  [48704] = "{id=48704,NameZh='深渊之凝望',Icon='item_48704',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52018,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='“英雄与魔剑一同倒下了。最后在塔深处涌动的，是站起来的尘埃，和未曾埋葬的死。”——《勇者之诗·终章》',LoadShowSize=3,LoadShowRotate=0,LoadShowPose={0,0,0},}",
  [48705] = "{id=48705,NameZh='缄默之荣光',Icon='item_48705',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=52017,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='由神之金属制成的面甲，曾属于某位传说中的英雄。随着岁月的流逝，往昔荣耀都凝刻其中。',LoadShowSize=4,LoadShowRotate=0,LoadShowPose={0.2,0.5,0},}",
  [48706] = "{id=48706,NameZh='炼金之喙',Icon='item_48706',Type=830,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=927,AdventureValue=330,AdventureReward={buffid={61001170}},StorageReward={buffid={80013060}},Condition=4,ComposeID=17706,Desc='只有知晓天理者才能窥探炼金术的奥秘，这是宇宙中至高无上的智慧所在，蝼蚁只能在陆地上仰视炼金术师的存在。',Feature=1,LoadShowSize=3,LoadShowRotate=0,LoadShowPose={0,0.3,0},}",
  [48707] = "{id=48707,NameZh='航空护目镜',Icon='item_48707',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52031,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='“嗷呜~汪！犬族永不为奴！上尉，派我去吧！我要让猫族看看谁才是强者！”布鲁多拿起了跟随自己多年的护目镜看向犬族的上尉，目光中满是坚毅与拒绝！',LoadShowSize=5,LoadShowRotate=0,LoadShowPose={0,0.3,0},}",
  [48708] = "{id=48708,NameZh='金面石雕',Icon='item_48708',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7073,AdventureValue=90,AdventureReward={buffid={61000520}},StorageReward={buffid={80012640}},Condition=4,ComposeID=17708,Desc='古老厚重的金纹雕刻在石雕之上，传说佩戴它之人可以与神明沟通，预测一切灾害与危险，但是宝物存在必定伴有纷争，石雕在被世人争夺之间，左耳的金饰不慎丢失，失去了它原有的神力。',}",
  [48709] = "{id=48709,NameZh='猫眼',Icon='item_48709',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=838,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='多年前罗扎纳健美大赛的舞台上，莱昂纳多先生在众星捧月中取走了冠军奖杯。“哦，他可真是个酷哥。”伊蕾塔小姐捂着心口说。',}",
  [48710] = "{id=48710,NameZh='衔叶松鼠',Icon='item_48710',Type=850,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=931,AdventureValue=140,AdventureReward={buffid={61001100}},StorageReward={buffid={80012970}},Condition=4,ComposeID=17710,Desc='一只悄悄溜出森林的小松鼠。它手中的叶片是罕见的四叶草，只送给被认可的冒险者。',}",
  [48711] = "{id=48711,NameZh='群叶猫的凝视',Icon='item_48711',Type=830,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=932,AdventureValue=100,AdventureReward={buffid={61001110}},StorageReward={buffid={80012640}},Condition=4,ComposeID=17711,Desc='模仿群叶猫造型制作的眼镜，镜片后的目光犀利又深沉。',}",
  [48712] = "{id=48712,NameZh='红翼魔镜',Icon='item_48712',Type=830,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=945,AdventureValue=230,AdventureReward={buffid={61001120}},StorageReward={buffid={80012930}},Condition=4,ComposeID=17712,Desc='一切的罪恶都逃不过这副恶魔的眼镜，所有堕落的灵魂都无处可藏，因为，恶魔会窥视到人类内心的欲望。',}",
  [48713] = "{id=48713,NameZh='冰霜龙首',Icon='item_48713',Type=830,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=955,AdventureValue=330,AdventureReward={buffid={61001680}},StorageReward={buffid={80013020}},Condition=4,ComposeID=17713,Desc='每个戴上它的人都会被尼格斯的意志所控制从而成为它的奴仆，想要彻底驾驭它，必须有极强的精神力，如果意志不坚，还是不要轻易触碰它。',}",
  [48714] = "{id=48714,NameZh='梦魇幽面',Icon='item_48714',Type=830,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=957,AdventureValue=330,AdventureReward={buffid={61000730}},StorageReward={buffid={80012590}},Condition=4,ComposeID=17714,Desc='“天惶惶，照月光 ，梦里见它莫惊慌，睁眼它不见，闭眼才出现。”这是幽灵梦魇身上遗落的面具，戴上它就可以窥视他人的梦境，发现他人隐藏心底的秘密。',}",
  [48715] = "{id=48715,NameZh='深渊低语',Icon='item_48715',Type=850,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=52038,AdventureValue=1,StorageReward={buffid={80012810}},Condition=8,Desc='“他迎着月光而来，隐匿于一片虚无。仰望星辰的指引，步入命运之深渊。”',}",
  [48716] = "{id=48716,NameZh='风之刻痕',Icon='item_48716',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52036,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='雪原战士瓦西里的短剑，以雪原上最坚硬的冰霜融炼而成。被赋予了北风的祝福，越是寒冷的地域，其威力越大。',}",
  [48717] = "{id=48717,NameZh='拉赫信徒男脸饰',Icon='item_48717',Type=830,MaxNum=99,SellPrice=100,}",
  [48718] = "{id=48718,NameZh='灵觉烟斗',Icon='item_48718',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52041,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='充满魔力的大烟斗，只要坚持每天抽上几口就能变得聪慧过人，遇上再棘手的问题也能迎刃而解。缺点是会让人经常咳嗽……',}",
  [48719] = "{id=48719,NameZh='王室威严',Icon='item_48719',Type=830,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=958,AdventureValue=330,AdventureReward={buffid={61001180}},StorageReward={buffid={80013050}},Condition=4,ComposeID=17719,Desc='来自地底，来自过去，那古老的王室财宝在沉睡，你可以拿走它们，只要你不怕那同样古老的王室威仪。',}",
  [48720] = "{id=48720,NameZh='魅惑之吻',Icon='item_48720',Type=850,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=964,AdventureValue=160,AdventureReward={buffid={61000560}},StorageReward={buffid={80012640}},Condition=4,ComposeID=17720,Desc='暗红色的蛇信吐出，空气随之变得暧昧起来。谁若难抵邪魅的诱惑，也便步入了危险的丛林。',Feature=1,}",
  [48722] = "{id=48722,NameZh='魔纹面罩',Icon='item_48722',Type=830,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=961,AdventureValue=230,AdventureReward={buffid={61001120}},StorageReward={buffid={80012930}},Condition=4,ComposeID=17722,Desc='远古的魔法在唇齿间环绕，话语于是成为了谶言。',Feature=1,}",
  [48723] = "{id=48723,NameZh='夜魅金瞳',Icon='item_48723',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7083,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='看着这双迷人的眼瞳，神秘而深邃，仿佛要被吸进去了。',}",
  [48724] = "{id=48724,NameZh='冰河游龙',Icon='item_48724',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7084,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='看着这纯净的冰晶石，仿佛感受到蛟龙畅游在冰河下的自由与不羁。',}",
  [48725] = "{id=48725,NameZh='星枝·梦',Icon='item_48725',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7095,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='“古老的传说从此沉淀于梦中。”神树的一节枝叶，来自某位法纳族首领的馈赠。',}",
  [48727] = "{id=48727,NameZh='最后的凝望',Icon='item_48727',Type=830,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=7093,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='如即逝的日暮，他伴随着世人悲叹，终将沉睡于云端。',}",
  [48728] = "{id=48728,NameZh='金鳞目隐',Icon='item_48728',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10220,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='飞扬动感的设计，结合金龙的鳞片意象，高贵与神秘感皆备。',}",
  [48729] = "{id=48729,NameZh='星枝·忆',Icon='item_48729',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7096,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='“遗落的记忆终会伴着风声归来。”神树的一截枝叶，来自某位毒牙族首领的馈赠。',}",
  [48730] = "{id=48730,NameZh='暮光之瞳',Icon='item_48730',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10241,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='千百的光阴，不及他回眸一瞬。',}",
  [48732] = "{id=48732,NameZh='炎龙之牙',Icon='item_48732',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10229,AdventureValue=1,StorageReward={buffid={80012930}},Condition=8,Desc='利用灾厄炎龙的皮甲所制成的口罩和发带，发带上嵌着的龙角还残有炎龙之息',}",
  [48733] = "{id=48733,NameZh='灾厄之眼',Icon='item_48733',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10230,AdventureValue=1,StorageReward={buffid={80012920}},Condition=8,Desc='灾厄炎龙的皮甲所制成的特殊眼罩',}",
  [48735] = "{id=48735,NameZh='笑影假面',Icon='item_48735',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012990}},Desc='在他笑容中掩盖的，是夕阳余晖下的阴影。',}",
  [48736] = "{id=48736,NameZh='缄默假面',Icon='item_48736',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012990}},Desc='面对消逝的真实与往昔，他终将不发一言。',}",
  [48737] = "{id=48737,NameZh='愤怒假面',Icon='item_48737',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012990}},Desc='无法遏制的愤怒。',}",
  [48738] = "{id=48738,NameZh='悲叹假面',Icon='item_48738',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012990}},Desc='百年时光流逝，所有孤寂与等待都化作一声叹息。',}",
  [48739] = "{id=48739,NameZh='鬼魅假面',Icon='item_48739',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012990}},Desc='他是黑暗的守夜人，死亡的歌颂者。',}",
  [48740] = "{id=48740,NameZh='假面系列',Icon='item_48740',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7091,AdventureValue=1,StorageReward={buffid={80012990}},Condition=8,}",
  [48741] = "{id=48741,NameZh='冰糖香菓菓',Icon='item_48741',Type=850,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012600}},Desc='洛阳街头的小零食，不管是谁都爱吃。不过若运气不好，会被没抹糖的山楂酸到牙疼。',}",
  [48742] = "{id=48742,NameZh='糖霜香菓菓',Icon='item_48742',Type=850,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012600}},Desc='涂满了糖霜和巧克力的香菓菓，很受女孩子的欢迎。不过已被列入洛阳减肥食谱黑名单。',}",
  [48743] = "{id=48743,NameZh='抹茶香菓菓',Icon='item_48743',Type=850,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012600}},Desc='常年滞销的香菓菓。由于颇为抽象的造型遭遇了外观党的质疑，其实味道还是很好的。绿色的外皮是抹茶特制，上面洒满了红豆。',}",
  [48744] = "{id=48744,NameZh='奶油香菓菓',Icon='item_48744',Type=850,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012600}},Desc='据说是手抖多加了半瓶奶油浇成的香菓菓，甜到你发慌。吃多了会长蛀牙，不建议小朋友食用。',}",
  [48745] = "{id=48745,NameZh='绵绵香菓菓',Icon='item_48745',Type=850,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012600}},Desc='参考了波利模样特制的香菓菓，里面包的是棉花糖。虽然格外受欢迎，但遭到了爱护波利人士的抗议。“波利那么可爱，怎么可以吃波利！”',}",
  [48746] = "{id=48746,NameZh='香菓菓系列',Icon='item_48746',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7092,AdventureValue=1,StorageReward={buffid={80012600}},Condition=8,}",
  [48747] = "{id=48747,NameZh='缺月水晶',Icon='item_48747',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7110,AdventureValue=1,StorageReward={buffid={80012990}},Condition=8,Desc='取月之湖最深处的水晶雕琢的饰品，在月光下璀璨的光华足以让世间最贵重的宝石黯然。',LoadShowPose={-0.3,0.4,1},}",
  [48748] = "{id=48748,NameZh='月亮猎犬的尾巴',Icon='item_48748',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7111,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='天上那个圆圆的亮亮的东西看上去好好吃~快追上去别让它跑了！',}",
  [48749] = "{id=48749,NameZh='神契印记',Icon='item_48749',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7115,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='众神与浮空精灵立下誓约：浮空精灵可以居住在天地树顶端，拥有漫长的生命，作为回报，他们要为诸神守护彩虹桥。眉心的铭文就是誓约的证明。',}",
  [48750] = "{id=48750,NameZh='无垢月光',Icon='item_48750',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7116,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='皎洁无暇的月光，在漫漫夜路中守护着你。',}",
  [48751] = "{id=48751,NameZh='蝶舞幔纱',Icon='item_48751',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7117,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='蝴蝶啊蝴蝶，你是神的使者吗？让我将秘密告诉你，请把我的心意传达给神明……',}",
  [48752] = "{id=48752,NameZh='新生元灵',Icon='item_48752',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7118,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='一片天地树的绿叶，庞大的魔力滋养出最原始的生命——假以时日说不定能孕育出完整的小世界呢~',}",
  [48753] = "{id=48753,NameZh='唤风者',Icon='item_48753',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7121,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='风永远不会停下脚步，我将随风前行。',}",
  [48754] = "{id=48754,NameZh='蝶之息',Icon='item_48754',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7123,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='蝴蝶飞，蝴蝶飞，轻轻地带来春天的消息~',}",
  [48756] = "{id=48756,NameZh='飞马（彩色）脸饰',Icon='item_48756',Type=830,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=979,AdventureValue=160,AdventureReward={buffid={61001110}},StorageReward={buffid={80012640}},Condition=4,ComposeID=17756,}",
  [48757] = "{id=48757,NameZh='摘星怪盗',Icon='item_48757',Type=830,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10309,AdventureValue=1,StorageReward={buffid={80012930}},Condition=8,Desc='偷星魔女们为了伪装身份使用的变装道具，虽然戴上它任何人都认不出你是谁，但夸张的造型或许会让所有人都注意到你！',LoadShowPose={0,0.25,0},}",
  [48758] = "{id=48758,NameZh='星之钥',Icon='item_48758',Type=850,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10310,AdventureValue=1,StorageReward={buffid={80012920}},Condition=8,Desc='偷星魔女的魔法钥匙，可以打开所有大门——包括你的心门哦！',}",
  [48759] = "{id=48759,NameZh='院长的眼镜',Icon='item_48759',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10318,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='不知道哪个调皮鬼拿走了院长的眼镜——他今天已经撞了三次墙了',Feature=1,TFValidDate='2020-12-30 05:00:00',ValidDate='2021-01-06 05:00:00',LoadShowSize=3,LoadShowPose={0,0.25,0},}",
  [48760] = "{id=48760,NameZh='考核前夜',Icon='item_48760',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10319,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='明天就是毕业考核的日子了，今晚的克里图拉学院，注定一夜无眠！',Feature=1,TFValidDate='2020-12-30 05:00:00',ValidDate='2021-01-06 05:00:00',}",
  [48761] = "{id=48761,NameZh='贪吃的代价',Icon='item_48761',Type=850,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=996,AdventureValue=160,AdventureReward={buffid={61000870}},StorageReward={buffid={80012640}},Condition=4,ComposeID=17761,Desc='看，有一只螃蟹——应该很好吃吧？是清蒸、还是爆炒呢？诶呦，痛痛痛、夹嘴了夹嘴了！',Feature=1,LoadShowSize=5,LoadShowPose={0,1,0},}",
  [48762] = "{id=48762,NameZh='壳中视界',Icon='item_48762',Type=830,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=998,AdventureValue=230,AdventureReward={buffid={61001120}},StorageReward={buffid={80012930}},Condition=4,ComposeID=17762,Desc='打开贝壳看到的不一定是亮闪闪的珍珠，也可能是亮闪闪的眼睛哦~',Feature=1,}",
  [48763] = "{id=48763,NameZh='怀念的面容',Icon='item_48763',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10343,AdventureValue=1,StorageReward={buffid={80012990}},Condition=8,Desc='年幼的波姬面容在此重现。……啊，得配上圆滚滚的脸颊才可爱！',}",
  [48764] = "{id=48764,NameZh='绿色生机',Icon='item_48764',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10344,AdventureValue=1,StorageReward={buffid={80012600}},Condition=8,Desc='波姬曾说过，她的衣物是她自己设计的。嗯，其实不过就是拿点叶子拼凑了一下对吧。',}",
  [48766] = "{id=48766,NameZh='先祖战纹',Icon='item_48766',Type=830,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=1006,AdventureValue=330,AdventureReward={buffid={61000750}},StorageReward={buffid={80013060}},Condition=4,ComposeID=17766,Desc='兽人们纹绘在面部的纹路，据说可以受到先祖的庇佑，获得勇气和力量。',}",
  [48767] = "{id=48767,NameZh='彩虹之轨迹',Icon='item_48767',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10376,AdventureValue=1,StorageReward={buffid={80012840}},Condition=8,Desc='嘀，嘀嘀滴！你就是我的梦幻宇宙，我会一直和你在一起，让光与彩虹围绕在你身边哒！',Feature=1,}",
  [48768] = "{id=48768,NameZh='小小阿波罗',Icon='item_48768',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10377,AdventureValue=1,StorageReward={buffid={80012630}},Condition=8,Desc='任何一个前往游乐场的人都抗拒不了的街头小玩具，用力吹气会发出呼呼地响声。不仅是童年回忆，更是炒热氛围的必备单品哦！',Feature=1,}",
  [48770] = "{id=48770,NameZh='贵族传统',Icon='item_48770',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10485,AdventureValue=1,StorageReward={buffid={80012840}},Condition=8,Desc='即使有了很多作为替代的魔法装置，王国的贵族们依旧喜欢使用书信传递信息，他们认为这是一种传统、正式而又优雅的方式，至于效率——谁在乎呢？',}",
  [48771] = "{id=48771,NameZh='王权永恒',Icon='item_48771',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10484,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='在卢恩王国的谚语中，常用“衔着金权杖出生”来形容那些出身高贵的人——“他们的牙齿真的不会痛吗？”',}",
  [48772] = "{id=48772,NameZh='夜魔之羽',Icon='item_48772',Type=850,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=1010,AdventureValue=230,AdventureReward={buffid={61001130}},StorageReward={buffid={80012920}},Condition=4,ComposeID=17772,Desc='以摄魂渡鸦的羽毛制成的嘴饰，是最杰出的猎人征服心灵猎场的证明。',}",
  [48775] = "{id=48775,NameZh='蝶翼假面',Icon='item_48775',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7161,AdventureValue=1,StorageReward={buffid={82000120}},Condition=8,Desc='仿照蝶翼制作的半面式假面，墨兰的蝶翼外勾勒着金丝，明艳而华丽。比起遮掩身份，更适合作为化装舞会上的装饰。',}",
  [48776] = "{id=48776,NameZh='竖琴的断弦',Icon='item_48776',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10478,AdventureValue=90,AdventureReward={buffid={61000590}},StorageReward={buffid={80012630}},Condition=4,ComposeID=17776,Desc='吟游诗人的琴声饱含对双子星的复杂感情，断裂的琴弦是否能修复如初呢？',}",
  [48778] = "{id=48778,NameZh='法医口罩',Icon='item_48778',Type=850,MaxNum=99,SellPrice=100,AdventureSort=7160,AdventureValue=1,StorageReward={buffid={82000110}},Condition=8,Desc='王室法医专用的口罩，严密地封住了嘴巴和鼻子。只有这样的设计，才能阻挡尸体上的病菌，以及亡者们散发出的腐败气味。',}",
  [48779] = "{id=48779,NameZh='巴尔特的弯刀',Icon='item_48779',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7173,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,ComposeID=17779,Desc='这把海盗弯刀是巴尔特家族强者的象征，曾经陪伴着巴尔特家族的先祖巴克萨成为海上传奇。虽然巴克萨在晚年退隐，但他仍然将这把弯刀交给了家族的后人，也是他希望海盗精神能够支撑着巴尔特家族继续强大。',}",
