  [48786] = "{id=48786,NameZh='遗忘者面具',Icon='item_48786',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10526,AdventureValue=1,StorageReward={buffid={80012630}},Condition=8,Desc='造型古朴、描绘着诡异花纹的面具。无人说得清它的来历，也不知道它的作用。”这面具的尺寸，简直是为我量身打造的……等等，我是谁……我要去做什么？“',}",
  [48787] = "{id=48787,NameZh='游侠领巾',Icon='item_48787',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10527,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='艳丽的红色领巾，是游侠的标志。它象征着如野火般迅疾的行动，以及永不熄灭的冒险之心。',}",
