  [49010] = "{id=49010,NameZh='kfc女仆发带',Icon='item_49010',Type=800,MaxNum=99,SellPrice=100,LoadShowSize=3,LoadShowRotate=0,LoadShowPose={0,0.5,0},}",
  [49011] = "{id=49011,NameZh='趴趴月夜猫',Icon='item_49011',Type=800,Quality=2,MaxNum=99,SellPrice=100,Desc='铃铃铃~喵！铃铛一声，月夜到！铃铛两声，幸福来! 铃铛三声！常相伴！大陆最可爱的月夜猫敬上！人家就是要趴在你头顶QWQ！',StageDisplay=0,LoadShowSize=2,LoadShowRotate=0,LoadShowPose={0,0.2,0},}",
  [49012] = "{id=49012,NameZh='祈福白狐',Icon='item_49012',Type=800,Quality=2,MaxNum=99,SellPrice=100,Desc='厄运消除，福气将至！嗷呜！我可不是普通的小狐狸！哼哼！我是在神社中长大的御守神白小狐！在本神的庇护下，任何的霉运都不能靠近你哦！',StageDisplay=0,LoadShowSize=2,LoadShowRotate=0,LoadShowPose={0,0.6,0},}",
  [49013] = "{id=49013,NameZh='角斗头冠',Icon='item_49013',Type=800,Quality=3,MaxNum=99,SellPrice=100,Desc='只有在无情的竞技场中存活下来的胜者，才配戴上它。不仅是华丽的装饰，更是强者无言的宣告。',LoadShowSize=2.5,LoadShowRotate=0,LoadShowPose={0,0.6,0},}",
  [49014] = "{id=49014,NameZh='雪之华发夹',Icon='item_49014',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9038,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='“这座城市飘落的纯白雪花，轻描淡写勾勒回忆。从今以后，就与你相伴一直走下去。”',LoadShowSize=3,LoadShowPose={0.2,0.9,-0.3},}",
  [49015] = "{id=49015,NameZh='冰晶·冬语结',Icon='item_49015',Type=800,Quality=3,MaxNum=99,SellPrice=100,Desc='你告诉我梦罗克从不会下雪，跨越沙漠与北国的爱恋总是后知后觉。每年的一月，我都会系上你最爱的冬语结。当你为我系上绳结，我总想抱你更紧些。',LoadShowSize=2,LoadShowRotate=0,LoadShowPose={0,0.5,0},}",
