  [49062] = "{id=49062,NameZh='年兽娃娃',Icon='item_49062',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15150,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='一只被施了魔法的年兽，原本是令人畏惧的生物，但现在竟然意外的可爱。只要把它戴在头上，就能平安度过除夕的夜晚。',Feature=1,TFValidDate='2019-01-28 05:00:00',ValidDate='2019-02-04 05:00:00',LoadShowSize=2,LoadShowPose={0,0.65,0},}",
