  [49066] = "{id=49066,NameZh='赤锦',Icon='item_49066',Type=800,MaxNum=99,SellPrice=100,Desc='辞旧迎新，“红”运当头！冒险旅程，锦鲤相伴！',TFValidDate='2019-02-01 05:00:00',ValidDate='2019-02-01 05:00:00',LoadShowSize=2.5,LoadShowRotate=0,LoadShowPose={0,0.6,0},}",
