  [49080] = "{id=49080,NameZh='能量棒球帽',Icon='item_49080',Type=800,MaxNum=99,SellPrice=100,StageDisplay=0,LoadShowSize=2,LoadShowRotate=0,LoadShowPose={0,0.4,0},}",
  [49081] = "{id=49081,NameZh='蛋壳啾啾',Icon='item_49081',Type=800,Quality=3,MaxNum=99,SellPrice=100,Desc='“啾啾！啾啾！”它好像把你认作妈妈了......',TFValidDate='2019-03-01 05:00:00',ValidDate='2019-03-01 05:00:00',LoadShowSize=3,LoadShowRotate=0,LoadShowPose={0,0.4,0},}",
  [49082] = "{id=49082,NameZh='森林之冠',Icon='item_49082',Type=800,Quality=2,MaxNum=99,SellPrice=100,Desc='被天地树选中之人，通过雨檀族考验之人，浮空精灵认可之人。戴上此冠，成为天地树的守护者吧。',TFValidDate='2019-03-01 05:00:00',ValidDate='2019-03-01 05:00:00',LoadShowSize=2,LoadShowRotate=0,LoadShowPose={0,0.8,0},}",
  [49083] = "{id=49083,NameZh='初见之印',Icon='item_49083',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10129,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='刚刚踏入这片大陆懵懂无知的你是那样的可爱，这是我赠予你的礼物，希望你可以永远保持这份初心，我会一直注视着你。——米德加尔特大陆赠予亲爱的你',LoadShowSize=3,LoadShowRotate=0,LoadShowPose={0,0.6,0},}",
  [49084] = "{id=49084,NameZh='往昔之书',Icon='item_49084',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10130,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='意气风发的勇士，人人颂歌的英雄，褪去了青涩的你如今是这般的耀眼，你做到了你想做的事，成为了你想成为的人，祝福你。最耀眼的星——米德加尔特大陆赠予亲爱的你',LoadShowSize=2.5,LoadShowRotate=0,LoadShowPose={0,0,0},}",
  [49085] = "{id=49085,NameZh='红莲头盔',Icon='item_49085',Type=800,MaxNum=99,SellPrice=100,AdventureSort=10149,AdventureValue=1,Condition=8,Desc='须佐·红莲丸的专属头盔。戴上它，化身为红莲的业火，燃烧你的敌人！',Feature=1,LoadShowSize=2,LoadShowRotate=0,LoadShowPose={0,0.6,0},}",
  [49086] = "{id=49086,NameZh='狱牙头盔',Icon='item_49086',Type=800,MaxNum=99,SellPrice=100,AdventureSort=10150,AdventureValue=1,Condition=8,Desc='须佐·狱牙丸的专属头盔。戴上它，化身为自地狱的使者，粉碎你的敌人！',Feature=1,LoadShowSize=2,LoadShowRotate=0,LoadShowPose={0,0.6,0},}",
  [49091] = "{id=49091,NameZh='皮里恩头饰',Icon='item_49091',Type=800,MaxNum=99,SellPrice=100,LoadShowSize=2.7,LoadShowPose={0,0.4,0},}",
  [49100] = "{id=49100,NameZh='ohsiesie',Icon='item_49100',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7035,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='我遇见谁会有怎样的对白~遇到你，我想我就是遇到了对的人，呼~累了，好想趴一会啊，嘿嘿，你的头顶还蛮舒服的嘛~',LoadShowSize=3.7,LoadShowRotate=25,LoadShowPose={0,0.3,0},}",
  [49102] = "{id=49102,NameZh='噬魂之誓言',Icon='item_49102',Type=800,MaxNum=99,SellPrice=100,Desc='由神之金属制成的头盔，曾伴随着它的主人走向生命的最后一刻。百年后的星光下，它诉说着的，是未曾逝去的勇气和信仰。',LoadShowSize=3,LoadShowRotate=20,LoadShowPose={0,0.6,0},}",
  [49104] = "{id=49104,NameZh='趴趴赛尼亚',Icon='item_49104',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7067,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='带着你一起去冒险，是我对你许下的承诺。',}",
  [49107] = "{id=49107,NameZh='英灵礼帽',Icon='item_49107',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7077,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='英灵不朽，神域不朽，聆听神之歌，颂扬神之威，为神祇献上最虔诚的灵魂者方可佩戴它。',}",
  [49108] = "{id=49108,NameZh='呆呆熊仔',Icon='item_49108',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7076,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='你是谁啊？我是呆呆熊，我是谁啊？你是呆呆熊。呆呆~最可爱的小熊~~',}",
  [49112] = "{id=49112,NameZh='信徒之冠',Icon='item_49112',Type=800,MaxNum=99,SellPrice=100,AdventureSort=7069,AdventureValue=30,AdventureReward={buffid={61001310}},StorageReward={buffid={80013070}},Condition=4,ComposeID=18112,Desc='在阿卢纳贝兹，所有的信徒都要向女神祈祷，歌颂女神的事迹，教国会根据信徒为神祇做出的贡献，为贡献最多的信徒赐予这顶礼冠。',}",
  [49113] = "{id=49113,NameZh='敬灵帽',Icon='item_49113',Type=800,MaxNum=99,SellPrice=100,AdventureSort=7070,AdventureValue=30,AdventureReward={buffid={61001310}},StorageReward={buffid={80013070}},Condition=4,ComposeID=18113,Desc='为了维护教国的权威，许多的勇士为女神献上了虔诚的灵魂，教国为了纪念这些勇士，将敬灵帽赐予了这些勇士的后人，佩戴这顶帽子的人在教国拥有特殊权利。',}",
  [49114] = "{id=49114,NameZh='自由圣鹰',Icon='item_49114',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7071,AdventureValue=80,AdventureReward={buffid={61000860}},StorageReward={buffid={80012640}},Condition=4,ComposeID=18114,Desc='女神的神迹照耀拉赫，拿起武器与深渊一战，赢得和平与美好，自由圣鹰张开羽翼，为吾等抗争之路护航，带领拉赫前往正确的方向。',}",
  [49118] = "{id=49118,NameZh='皎灵',Icon='item_49118',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7068,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='传言女神曾在大陆上遗留下了几颗皎洁的珍珠，其中蕴含着无数圣灵的力量，是拉赫人趋之若鹜的至宝。',}",
  [49121] = "{id=49121,NameZh='雪翎玫瑰',Icon='item_49121',Type=800,MaxNum=99,SellPrice=100,Desc='象征和平与希望的桂冠上结出了爱的花朵，愿你也一样。',}",
  [49127] = "{id=49127,NameZh='圣域推图头饰中',Icon='item_49127',Type=800,MaxNum=99,SellPrice=100,}",
  [49134] = "{id=49134,NameZh='星弦导航仪',Icon='item_49134',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10186,AdventureValue=1,StorageReward={buffid={80012930}},Condition=8,Desc='星之力驱散迷雾，星之力指引方向，星之力开拓前路。',}",
  [49135] = "{id=49135,NameZh='蕾丝蛋糕',Icon='item_49135',Type=800,MaxNum=99,SellPrice=100,Desc='罗扎纳最受欢迎的甜品之一，经常卖断货。是烤箱酒吧伊蕾塔小姐的拿手甜点。',}",
  [49137] = "{id=49137,NameZh='灵巧的羽毛帽',Icon='item_49137',Type=800,MaxNum=99,SellPrice=100,Desc='蝴蝶巡守队传令兵的帽子，佩戴后跑步时脚下生风。',}",
  [49158] = "{id=49158,NameZh='凛冬守望',Icon='item_49158',Type=800,MaxNum=99,SellPrice=100,Desc='“永恒之雪，赐予我无尽的勇气，与面对死亡的力量。”——雪原战士瓦西里的冠冕。许多年前，他曾跋涉至冰川的深处，独自一人平息了肆虐的风暴。',}",
  [49159] = "{id=49159,NameZh='拉赫信徒女头饰',Icon='item_49159',Type=800,MaxNum=99,SellPrice=100,}",
  [49179] = "{id=49179,NameZh='初心睡帽',Icon='item_49179',Type=800,MaxNum=99,SellPrice=100,Desc='冒险征途非常劳累，殴打波利也很疲惫，祝你拥有梦里一霎，那时仍是如花少年。',}",
  [49180] = "{id=49180,NameZh='妖灵独角',Icon='item_49180',Type=800,MaxNum=99,SellPrice=100,Desc='充满自然力量的独角，戴上之后将变成介于妖精和仙灵之间的奇妙生物。',}",
  [49186] = "{id=49186,NameZh='幽灵低语',Icon='item_49186',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7094,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='小兵小卒也曾是活生生的人，鲜活的生命却被残酷的战争吞噬。帽子上残破的痕迹与箭矢似乎在诉说着战事的惨烈......',}",
  [49187] = "{id=49187,NameZh='旋金蛇舞',Icon='item_49187',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7079,AdventureValue=1,StorageReward={buffid={80012990}},Condition=8,Desc='依照金蛇意象设计，非常具有灵动感。',}",
  [49188] = "{id=49188,NameZh='夕晖余梦',Icon='item_49188',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7080,AdventureValue=1,StorageReward={buffid={80012600}},Condition=8,Desc='帽子的底色是典雅的檀木色，金边的镶嵌是点睛之笔。帽带可以避免帽子滑落，美观与实用兼备。',}",
  [49196] = "{id=49196,NameZh='辉景春光',Icon='item_49196',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7090,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='微风拂动，面前是一抹飘动的红色，那是随风而逝的思念……',}",
  [49205] = "{id=49205,NameZh='福尔喵斯帽',Icon='item_49205',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9057,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='一阵急促的电话铃声，打断了惬意享受着美味下午茶的猫猫侦探的思绪，侦探戴好帽子：“本喵侦探的出场时间到了！ ”',}",
  [49211] = "{id=49211,NameZh='灼狱',Icon='item_49211',Type=800,MaxNum=99,SellPrice=100,Desc='他的足迹遍布之处，业火盛开。',}",
  [49212] = "{id=49212,NameZh='绯华',Icon='item_49212',Type=800,MaxNum=99,SellPrice=100,Desc='她的目光所及之地，红莲绽放。',}",
  [49225] = "{id=49225,NameZh='辉光守护·璨',Icon='item_49225',Type=800,MaxNum=99,SellPrice=100,Desc='沐浴过女武神荣耀之力的头盔，普通人无法佩戴，唯有能踏入瓦尔哈拉殿堂之人，方可承此殊荣。',}",
  [49251] = "{id=49251,NameZh='白蛇·凝灵',Icon='item_48091',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7089,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='远古的那场大战，以及之后洛阳的时空被割离，导致荒境的元素之力开始衰变。经年累月，这种衰变愈演愈烈，虽然荒境表面上还风平浪静，其实元素失调导致的混乱已经濒临极限，唯一勉强保持正常的水之元素也岌岌可危，荒境已经处于毁灭的边缘。一切的转机源自那场突然的暴雨，黑暗中唯一的烛火——水之元素。浸润万物的雨降下，元素的变异被洗刷，混乱被平息，水元素的精魄也因大雨耗尽了力量，消失无踪。而新的生命自雨中降生，白蛇·凝灵，带着水元素仅存的气息，来到了世上。',}",
  [49261] = "{id=49261,NameZh='星辉月冕',Icon='item_49261',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7108,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='沐浴星光与月光的圣冠，历代传承者都是身处黑暗，心向光明的圣徒。',}",
  [49500] = "{id=49500,NameZh='测试用头饰1（垃圾）',Icon='item_49500',Type=800,Quality=5,MaxNum=99,SellPrice=100,Delete=49500}",
