  [49513] = "{id=49513,NameZh='冒险家冠帽',Icon='item_49513',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10272,AdventureValue=1,StorageReward={buffid={80012920}},Condition=8,Desc='由冒险者公会出品的豪华冠帽，装饰有代表自由和远行的飞翼，用以奖励活跃在大陆上的精英冒险者。',}",
  [49514] = "{id=49514,NameZh='鸦杀尽',Icon='item_49514',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012640}},Desc='愿以此身为剑，斩尽夜间寒鸦，守护人们的安眠。',}",
  [49515] = "{id=49515,NameZh='御家人',Icon='item_49515',Type=800,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80012660}},Desc='守护天水之国的忍众头目，深受人民爱戴。除了执行各种隐秘任务，平时还担任天津町的警备工作。',}",
  [49521] = "{id=49521,NameZh='诗神的祝福',Icon='item_49521',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7128,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='这顶帽子受到了诗神布莱奇的祝福，它将伴你发现世界的真相。',}",
  [49522] = "{id=49522,NameZh='森之绮梦',Icon='item_49522',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7125,AdventureValue=1,StorageReward={buffid={80012920}},Condition=8,Desc='步入梦幻的森林，在花与蝶之间起舞吧！',}",
  [49524] = "{id=49524,NameZh='丛林之友',Icon='item_49524',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7122,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='啊，好奇怪~这个鸟巢晃得有些厉害~~',}",
  [49525] = "{id=49525,NameZh='启迪之环',Icon='item_49525',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7113,AdventureValue=1,StorageReward={buffid={80012990}},Condition=8,Desc='每一个浮空精灵在成年时都会被授予神明赐福的发箍，它象征着智慧与虔诚。',}",
  [49526] = "{id=49526,NameZh='四叶草睡帽',Icon='item_49526',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7114,AdventureValue=1,StorageReward={buffid={80012600}},Condition=8,Desc='一片送入安睡，一片隔绝寒冷，一片驱散恐惧，一片带来美梦，用四叶草装饰的睡帽，愿你的梦境永远美好！',}",
  [49534] = "{id=49534,NameZh='不知火',Icon='item_49534',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012640}},Desc='愿以此身为炬，驱散黑暗，为夜行者引路。',}",
  [49535] = "{id=49535,NameZh='姬武者',Icon='item_49535',Type=800,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80012660}},Desc='守护天水之国的忍众头目，深受人民爱戴。个性坚毅而内心温柔，是能在令敌人恐惧的罗刹和让民众拥戴的首领间切换的奇女子。',}",
  [49536] = "{id=49536,NameZh='忍者系列头饰',Icon='item_49536',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=854,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='思则睿，睿作圣',}",
  [49537] = "{id=49537,NameZh='影狼/胧系列头饰',Icon='item_49537',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=855,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='临兵斗者皆阵列在前。',}",
  [49539] = "{id=49539,NameZh='炎灵之眼[1]',Icon='item_49539',Type=800,Quality=3,MaxNum=99,SellPrice=100,Desc='炎之领主卡浩拥有能够燃烧的双眼，工匠大师埃德姆使用它的眼睛打造了一款永远燃烧的王冠。',}",
  [49540] = "{id=49540,NameZh='闪耀应援团',Icon='item_49540',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10311,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='偶像少女团体“闪耀少女”专属的应援道具，用以表达对于元气美少女的无尽热爱。',}",
  [49542] = "{id=49542,NameZh='安全第一',Icon='item_49542',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10320,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='学院为新生们定制的安全帽，以防止他们在各种实践课程中遭受不可预知的意外伤害。（呃，现在退学还来得及吗？）',Feature=1,TFValidDate='2020-12-30 05:00:00',ValidDate='2021-01-06 05:00:00',}",
  [49543] = "{id=49543,NameZh='犬阵笠',Icon='item_49543',Type=800,Quality=3,MaxNum=99,SellPrice=100,Desc='等一下！露出头的话根本保护不到头吧?再等一下！为什么连头也变了啊！',}",
  [49549] = "{id=49549,NameZh='传说的武神',Icon='item_49549',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10346,AdventureValue=1,StorageReward={buffid={80013010}},Condition=8,Desc='“我可是持有武神之冠的。——你那个不相信的眼神是什么意思？哼，只是我一直没机会给你展现出来罢了！”BY气愤的波姬',}",
  [49550] = "{id=49550,NameZh='武神的馈赠·英雄',Icon='item_49550',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012610}},Desc='这是（自称）有武神之冠的波姬专门打造的一个仿造品。简洁大方，美观时尚。不要在意实用度（重音）。',}",
  [49551] = "{id=49551,NameZh='武神的馈赠·女杰',Icon='item_49551',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012610}},Desc='这是（自称）有武神之冠的波姬专门打造的一个仿造品。简洁大方，美观时尚。不要在意实用度（重音）。',}",
  [49552] = "{id=49552,NameZh='波姬系列头饰',Icon='item_49552',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10347,AdventureValue=1,StorageReward={buffid={80012610}},Condition=8,}",
  [49554] = "{id=49554,NameZh='甜蜜彩虹波利茶',Icon='item_49554',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10378,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='由七彩棉花糖做成的雪顶，QQ弹弹的星星点缀在软糯的波利旁，让人忍不住就想咬一口！把这顶帽子戴在头上：嗯~~~是甜甜香香的一天呢！',Feature=1,}",
  [49561] = "{id=49561,NameZh='流光浮羽',Icon='item_49561',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9078,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='真相游离于虚妄间，唯有坚定的心灵能将它找寻。',}",
  [49562] = "{id=49562,NameZh='反叛之翼',Icon='item_49562',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=858,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='为了心中的正义信念，即使身负“反叛者”之名，也在所不惜。让我们大闹一场吧！',}",
  [49563] = "{id=49563,NameZh='时间法则',Icon='item_49563',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10482,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='我们的时间非常宝贵，所以贵族礼仪的第一条就是——绝对的守时！',}",
  [49564] = "{id=49564,NameZh='王国之鹰',Icon='item_49564',Type=800,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={82000070}},Desc='雄鹰昂扬于高空，守护王国的未来。',}",
  [49565] = "{id=49565,NameZh='宫廷之花',Icon='item_49565',Type=800,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={82000070}},Desc='美艳而娇柔的鲜花，是勇士们守护的意义。',}",
  [49566] = "{id=49566,NameZh='王国菁英系列头饰',Icon='item_49566',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10487,AdventureValue=1,StorageReward={buffid={82000070}},Condition=8,}",
  [49567] = "{id=49567,NameZh='荣耀波利帽',Icon='item_49567',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=52069,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='为嘉奖英勇战斗的勇者们而特制的限定款波利帽。',}",
  [49573] = "{id=49573,NameZh='古典王冠',Icon='item_49573',Type=800,MaxNum=99,SellPrice=100,AdventureSort=7151,AdventureValue=1,StorageReward={buffid={80013070}},Condition=8,Desc='曾经的王室头冠，以形制标准和简约庄重闻名。但随着王室财富的积累，这样的王冠已经无法满足上位者的虚荣心。于是，它被淘汰为了一种普通的饰品，连非王室成员都可以佩戴。',}",
  [49574] = "{id=49574,NameZh='星芒骑士发夹',Icon='item_49574',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7152,AdventureValue=1,StorageReward={buffid={80012840}},Condition=8,Desc='彰显贵族身份的发夹，也可以作为与卢恩王室友谊的象征。品性高洁的骑士，愿你的前途如星辉一般光耀。',}",
  [49575] = "{id=49575,NameZh='圣白淑女发夹',Icon='item_49575',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7154,AdventureValue=1,StorageReward={buffid={80012630}},Condition=8,Desc='彰显贵族身份的发夹，也可以作为与卢恩王室友谊的象征。美丽优雅的女士，愿你的心灵如圣花一般纯洁。',}",
  [49576] = "{id=49576,NameZh='女王花冠',Icon='item_49576',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7153,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='先代卢恩女王，享有“帝国宝珠”之名的梅欧娜的王冠。这位异常喜爱鲜花的女王，命人打造一顶盛开着花朵的王冠。工匠耗费无数珍贵宝石与附魔材料，才满足她的需求。女王的奢靡与荒诞，也随着花冠一起流传了下来……',}",
  [49577] = "{id=49577,NameZh='不朽之木',Icon='item_49577',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10479,AdventureValue=80,AdventureReward={buffid={61000590}},StorageReward={buffid={80012640}},Condition=4,ComposeID=18577,Desc='“这是秘密……不能告诉别人……”年轻的机甲师小心地藏起装有朽木的宝箱，希望有人能够帮助他度过难关。',}",
  [49578] = "{id=49578,NameZh='迷糊猫',Icon='item_49578',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7159,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='饲养在王宫内的猫猫，看起来不太聪明的样子。“咪呜咪呜~我想不起自己的窝在哪里了？你可以暂时收留下我吗？”',}",
  [49579] = "{id=49579,NameZh='水晶拨弦琴',Icon='item_49579',Type=840,MaxNum=99,SellPrice=100,AdventureSort=7165,AdventureValue=1,StorageReward={buffid={80013070}},Condition=8,Desc='宫廷样式的拨弦琴，优美的弧度，宛若天鹅的颈项。由于采用魔法水晶制作琴身，除了奏乐之外，还可以作为装饰品使用。',}",
  [49580] = "{id=49580,NameZh='御用扫帚',Icon='item_49580',Type=810,MaxNum=99,SellPrice=100,AdventureSort=7166,AdventureValue=1,StorageReward={buffid={80013070}},Condition=8,Desc='王室御用的扫帚，长柄的形状酷似法杖。“可惜，这扫帚并没有魔法呢。不然，还要这么多洒扫的侍人干嘛？”',LoadShowPose={0,0.25,0},}",
  [49581] = "{id=49581,NameZh='金边护目镜',Icon='item_49581',Type=800,MaxNum=99,SellPrice=100,AdventureSort=7167,AdventureValue=1,StorageReward={buffid={80013070}},Condition=8,Desc='看似平平无奇的护目镜，实则采用了修发兹共和国进口的透镜，并用黄金包裹镜框。不过，为一副护目镜大费周章，贵族们的爱好，还真是奇怪呢。',}",
  [49582] = "{id=49582,NameZh='绸缎软帽',Icon='item_49582',Type=800,MaxNum=99,SellPrice=100,AdventureSort=7168,AdventureValue=1,StorageReward={buffid={80013070}},Condition=8,Desc='用精致绸缎制成的软帽，点缀着娇俏的蝴蝶结。据说，这是普隆德拉贵族少女间非常流行的款式。',}",
  [49583] = "{id=49583,NameZh='夹鼻老花镜',Icon='item_49583',Type=830,MaxNum=99,SellPrice=100,AdventureSort=7169,AdventureValue=1,StorageReward={buffid={80013070}},Condition=8,Desc='看起来土里土气的老花镜，但在老年宫廷侍从中非常流行。“夹鼻才是好款式！只要一直挂在脸上，就不会出现忘记眼镜放哪儿的情况~”',}",
  [49584] = "{id=49584,NameZh='忧伤的雨',Icon='item_49584',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7171,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='来自情绪幽灵的恶作剧，只要淋到雨，心情就会变得忧伤……',}",
  [49585] = "{id=49585,NameZh='心灵猎者',Icon='item_49585',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=859,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='灵修会授予资深猎灵士的帽子，以表彰他们对于灵魂奥秘的探索。',}",
  [49588] = "{id=49588,NameZh='灵魂回响[1]',Icon='item_49588',Type=800,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={80012980}},Desc='仔细听，那是心灵的低语，那是灵魂的高歌！',}",
  [49589] = "{id=49589,NameZh='心籁之音[1]',Icon='item_49589',Type=800,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={80012980}},Desc='仔细听，那是心灵的低语，那是灵魂的高歌！',}",
  [49590] = "{id=49590,NameZh='灵魂回响系列头饰',Icon='item_49588',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=860,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='仔细听，那是心灵的低语，那是灵魂的高歌！',}",
  [49591] = "{id=49591,NameZh='海灵恩护',Icon='item_49591',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10512,AdventureValue=1,StorageReward={buffid={80012930}},Condition=8,Desc='海灵图腾的头部，带上它的那一刻——你感觉自己充满了智慧……',}",
  [49592] = "{id=49592,NameZh='暖心芽芽帽',Icon='item_49592',Type=800,Quality=4,MaxNum=99,SellPrice=100,Desc='用厚实毛线织成的帽子，顶端带有两片仿制的芽芽叶子。冬日的寒风固然凛冽，但芽芽会陪着你，一起守望春天~',}",
  [49593] = "{id=49593,NameZh='自恋日记',Icon='item_49593',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7174,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,ComposeID=18593,Desc='要问米德加尔特大陆上最美的男人，可能所有的少女都会不约而同的告诉你——尤尔根·韦格纳。作为韦格纳家的下一任家主，尤尔根过着众星捧月的生活，这也养成了他极度自恋的性格。他的日记里记载着关于他所有的赞美，是他的宝物之一。',}",
  [49595] = "{id=49595,NameZh='风车头饰·赛季[1]',Icon='item_49595',Type=800,Quality=4,MaxNum=99,SellPrice=100,Desc='《注意》该装备属性及其卡片、附魔等效果仅在公会战相关地图生效，且升级后无法还原。赛季开始后将由不思议贩卖机进行回收。',NoStorage=5,}",
  [49596] = "{id=49596,NameZh='鳄鱼头套·赛季[1]',Icon='item_49596',Type=800,Quality=4,MaxNum=99,SellPrice=100,Desc='《注意》该装备属性及其卡片、附魔等效果仅在公会战相关地图生效，且升级后无法还原。赛季开始后将由不思议贩卖机进行回收。',NoStorage=5,}",
  [49597] = "{id=49597,NameZh='会动的蝴蝶·赛季[1]',Icon='item_49597',Type=800,Quality=4,MaxNum=99,SellPrice=100,Desc='《注意》该装备属性及其卡片、附魔等效果仅在公会战相关地图生效，且升级后无法还原。赛季开始后将由不思议贩卖机进行回收。',NoStorage=5,}",
  [49598] = "{id=49598,NameZh='荧光蝶',Icon='item_49598',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10528,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='蝴蝶通常在白天活动，但荧光蝶是个例外。与月光睡莲伴生的它，需要在夜间采集花蜜，因此夜晚的水面上，时常倒映着它们美丽的身影。',}",
  [49599] = "{id=49599,NameZh='狐不语',Icon='item_49599',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=10529,AdventureValue=1,StorageReward={buffid={80012860}},Condition=8,Desc='微笑的狐狸面具，掩饰心底的千言万语。注视着烟花的少年，你在想着谁？',}",
  [49602] = "{id=49602,NameZh='竹隐斗笠',Icon='item_49602',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10542,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='以小熊猫为原型设计的斗笠，可爱的造型令人瞩目——这似乎偏离了设计的初衷。',}",
  [49603] = "{id=49603,NameZh='林间客',Icon='item_49603',Type=800,Quality=4,MaxNum=99,SellPrice=100,Desc='数百年前流星林强者们的常见装扮，他们以此装扮行侠仗义，这一头饰也因此成为侠客的象征。',}",
  [49604] = "{id=49604,NameZh='踏莎行',Icon='item_49604',Type=800,Quality=4,MaxNum=99,SellPrice=100,Desc='数百年前流星林强者们的常见装扮，他们以此装扮行侠仗义，这一头饰也因此成为侠客的象征。',}",
  [49605] = "{id=49605,NameZh='红尘浪客',Icon='item_49605',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=10543,AdventureValue=1,StorageReward={buffid={80012860}},Condition=8,}",
  [49606] = "{id=49606,NameZh='麟儿',Icon='item_49606',Type=800,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80012660}},Desc='天降麒麟儿，武道长夜既白。',}",
  [49607] = "{id=49607,NameZh='赤子',Icon='item_49607',Type=800,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80012660}},Desc='常怀赤子之心，方为武道坦途。',}",
  [49608] = "{id=49608,NameZh='侠隐无名[1]',Icon='item_49608',Type=800,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={80012970}},Desc='大道至简，侠隐无名。',}",
  [49609] = "{id=49609,NameZh='绝代天骄[1]',Icon='item_49609',Type=800,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={80012970}},Desc='傲立群雄，绝代天骄。',}",
  [49610] = "{id=49610,NameZh='魔剑士',Icon='item_49610',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7181,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='“执剑的意义不在于成为英雄，而是直面命运。”',}",
  [49611] = "{id=49611,NameZh='世界的守护者[1]',Icon='item_49611',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7183,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='“力量亦是责任，守护是世间众生是命运给予吾的使命。”',LoadShowPose={0,1,0},}",
  [49612] = "{id=49612,NameZh='星海守望',Icon='item_49612',Type=800,Quality=3,MaxNum=99,SellPrice=100,Desc='星之精灵漂浮在浩瀚的宇宙中，点亮微光，为畅游星海的旅人指引方向。',}",
  [49613] = "{id=49613,NameZh='巨魔角',Icon='item_49613',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10559,AdventureValue=1,StorageReward={buffid={80012840}},Condition=8,Desc='似乎是某种巨型生物的角，但“拾骨者”始终不肯说明它的来历。',}",
  [49614] = "{id=49614,NameZh='喵爪怀表',Icon='item_49614',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10596,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='分针每转一圈，就能听到一声温柔的“喵”，提醒你记得准时赴约。',LoadShowPose={0,0.3,0},}",
  [49615] = "{id=49615,NameZh='黑桃乌龙',Icon='item_49615',Type=800,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={82000070}},Desc='浓烈中带一丝苦涩，像那天没说完的告别，只留下挥手的影子。',}",
  [49616] = "{id=49616,NameZh='蜜桃汽水',Icon='item_49616',Type=800,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={82000070}},Desc='香香甜甜的味道，如同凉爽的汽水，每一口都沁人心脾。',}",
