  [49634] = "{id=49634,NameZh='水手宣言',Icon='item_49634',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7193,AdventureValue=1,StorageReward={buffid={80013010}},Condition=8,Desc='用青春灌满海风，以勇气执掌船舵，蔚蓝大海将赋予我生命的意义。',}",
  [49635] = "{id=49635,NameZh='愿力之证',Icon='item_49635',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7194,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='旧良族族长奎勒留下的纪念，还能感受到愿力带来的温暖。“当我们屏息凝神之时，便可看到事情的答案”。',}",
