  [49657] = "{id=49657,NameZh='尘世巨蟒',Icon='item_49657',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7208,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='懦弱者戴着镣铐随波逐流，唯有强者方能打碎命运的禁锢。',}",
