  [51019] = "{id=51019,NameZh='学院系列时装',Icon='item_51019',Type=501,MaxNum=99,SellPrice=100,Condition=8,Feature=1,}",
  [51021] = "{id=51021,NameZh='衣装·驯鹿的祝福',Icon='item_51021',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='“少女听着父亲念得故事再次甜蜜地进入了梦乡，失去了妻子的男人继续在摇曳的烛光照亮的工作桌前雕琢着那本绘本，撰写着歌词。时至今日，男人为女儿制作的绘本已经成为全世界小孩子们最喜欢的圣诞故事之一。童话故事依然持续发生在你我的身边。”',Feature=1,MainColor='d13935FF',}",
  [51031] = "{id=51031,NameZh='衣装·圣夜的王子',Icon='item_51031',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='“少年静静地躺在和玩具柜里，守护着少女的睡梦，经历无数次的艰难，少年明早终于可以以自己真正的模样去见少女了，他们约定了要再次去游离幻想王国的【牛奶河】、【玫瑰湖】、【巧克力城堡】…童话故事依然持续发生在你我的身边。”',Feature=1,MainColor='d13935FF',}",
  [51032] = "{id=51032,NameZh='圣诞系列时装',Icon='item_51032',Type=501,MaxNum=99,SellPrice=100,AdventureSort=15003,AdventureValue=1,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Condition=8,Feature=1,MainColor='d13935FF',}",
  [51041] = "{id=51041,NameZh='春节活动套-男',Icon='item_51041',Type=501,MaxNum=99,SellPrice=100,Desc='过新年，穿新衣！这是来自古老东方国度的民间习俗，新的衣服会带来新年的好运哦！',Feature=1,}",
  [51042] = "{id=51042,NameZh='春节活动套-女',Icon='item_51042',Type=501,MaxNum=99,SellPrice=100,Desc='过新年，穿新衣！这是来自古老东方国度的民间习俗，新的衣服会带来新年的好运哦！',Feature=1,}",
  [51043] = "{id=51043,NameZh='春节系列时装',Icon='item_51043',Type=501,MaxNum=99,SellPrice=100,Feature=1,}",
