  [51107] = "{id=51107,NameZh='樱之嫁衣',Icon='item_51107',Type=501,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='在这天空中飞舞着的，各种各样的幸福。为了能够永远闪耀，同样的思绪重合在一起。即使季节更替，樱花散落，回顾与你一同走过的道路，一路上充满笑容。回想起与你相见之时，樱花漫舞的街道上充满了光芒。心与心相通合而为一 那个瞬间，看见了你清澈的眼眸。',Feature=1,}",
  [51108] = "{id=51108,NameZh='樱之礼服',Icon='item_51108',Type=501,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='自那场精彩的冒险开始，便预感到会有让人心动的邂逅。心与心相连，将找到的那份热烈的思念埋藏于心中。心有灵犀，因为拥有现在，明日也将在某地，与你交谈。相信那一天的约定，鼓动的心跳化作刻在胸中的誓言。',Feature=1,}",
  [51109] = "{id=51109,NameZh='樱之系列时装',Icon='item_51109',Type=501,MaxNum=99,SellPrice=100,AdventureSort=15009,AdventureValue=1,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Condition=8,Desc='春光烂漫樱花飞舞，又是一年明媚的仲春时节',Feature=1,}",
