  [51134] = "{id=51134,NameZh='衣装·暗夜骑士·业火红',Icon='item_51134',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='曾经的古城骑士团在古城沦陷后秘密成立了暗夜骑士团，只为让邪恶付出应有的代价。穿上这身猩红暗夜铠甲之人，便化身为燃尽邪恶的地狱业火。暗夜降临，敌人将会因这鲜红的肆虐而战栗。“吾自此成为暗夜之子，为与恶龙缠斗，愿自身亦化作恶龙。”——《暗夜骑士团誓约》',Feature=1,MainColor='da2153FF',}",
  [51135] = "{id=51135,NameZh='衣装·暗夜骑士·幽冥绿',Icon='item_51134',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='曾经的古城骑士团在古城沦陷后秘密成立了暗夜骑士团，只为让邪恶付出应有的代价。穿上这身幽绿暗夜铠甲之人，便化身为葬送邪恶的幽冥之灯。暗夜降临，敌人将会因这幽绿的笼罩而哀嚎。“吾自此成为暗夜之子，为与恶龙缠斗，愿自身亦化作恶龙。”——《暗夜骑士团誓约》',Feature=1,MainColor='1d9661FF',}",
  [51136] = "{id=51136,NameZh='衣装·暗夜骑士·深渊蓝',Icon='item_51134',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='曾经的古城骑士团在古城沦陷后秘密成立了暗夜骑士团，只为让邪恶付出应有的代价。穿上这身深蓝暗夜铠甲之人，便化身为吞噬邪恶的无尽深渊。暗夜降临，敌人将会因这苍蓝的凝视而崩坏。“吾自此成为暗夜之子，为与恶龙缠斗，愿自身亦化作恶龙。”——《暗夜骑士团誓约》',Feature=1,MainColor='2a87ffFF',}",
  [51137] = "{id=51137,NameZh='衣装·暗夜骑士·日耀黄',Icon='item_51134',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='曾经的古城骑士团在古城沦陷后秘密成立了暗夜骑士团，只为让邪恶付出应有的代价。穿上这身耀黄暗夜铠甲之人，便化身为清洗邪恶的耀眼金刃。暗夜降临，敌人将会因这金黄的冲锋而溃逃。“吾自此成为暗夜之子，为与恶龙缠斗，愿自身亦化作恶龙。”——《暗夜骑士团誓约》',Feature=1,MainColor='f8cd56FF',}",
  [51138] = "{id=51138,NameZh='衣装·月夜蔷薇·玫红',Icon='item_51138',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='最初由古城女贵族们创立的女性社团——暗月蔷薇。特有的暗月武装由每代最强的女战士们传承。这身点缀着红色的暗月武装融合了热情与力量，在暗淡之月下，敌人一边沉醉于这份美丽一边被葬送。',Feature=1,MainColor='da2153FF',}",
