  [51162] = "{id=51162,NameZh='衣装·夏日扶桑·凤梨黄',Icon='item_51161',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000030}},Desc='夏天是什么，阳光！沙滩！冰激凌！穿上这套由艾尔帕兰的高级时装店限时限量专供给冒险家的沙滩走秀诚意巨作，下一秒你就会成为沙滩上的焦点。短袖外套加上独具海岛特色的黄色沙滩裤，和热带的凤梨一样耀眼夺目。今年的夏天你最酷！',Feature=1,TFValidDate='2019-07-29 05:00:00',ValidDate='2019-08-01 05:00:00',MainColor='f8cd56FF',}",
