  [51201] = "{id=51201,NameZh='枫之赠礼·红',Icon='item_51201',Type=501,MaxNum=99,SellPrice=100,StorageReward={buffid={82000060}},Desc='枫，是明艳的，热烈的，枫叶似火绽放出它的热情与活力，无数的枫叶汇聚而成了这套礼服，这是枫的赠礼…',}",
  [51202] = "{id=51202,NameZh='枫之赠礼·黄',Icon='item_51202',Type=501,MaxNum=99,SellPrice=100,StorageReward={buffid={82000060}},Desc='枫，是温暖的，内敛的，枯黄的枫叶却造就了另一番景色，生命凋零也绝不服输，无数的枫叶汇聚而成了这套礼服，这是枫的坚强…',}",
  [51203] = "{id=51203,NameZh='枫之赠礼·绿',Icon='item_51203',Type=501,MaxNum=99,SellPrice=100,StorageReward={buffid={82000060}},Desc='枫，是新生的，青涩的，它熬过了冬季的寒风凛冽才等到春季的花草重现，无数的枫叶汇聚而成了这套礼服，这是枫的希望…',}",
  [51211] = "{id=51211,NameZh='枫之赞歌·红',Icon='item_51211',Type=501,MaxNum=99,SellPrice=100,StorageReward={buffid={82000060}},Desc='红色的枫叶如花季的少女，在燃烧着，在跃动着，在旋舞着，这是红枫少女的赞歌。',}",
  [51212] = "{id=51212,NameZh='枫之赞歌·黄',Icon='item_51212',Type=501,MaxNum=99,SellPrice=100,StorageReward={buffid={82000060}},Desc='枯黄的枫叶正努力让自己的凋零也充满浪漫，这样会让下一次的轮回充满希望，成熟的黄枫如同战场上的女战士，懂得了牺牲与爱！',}",
  [51213] = "{id=51213,NameZh='枫之赞歌·绿',Icon='item_51213',Type=501,MaxNum=99,SellPrice=100,StorageReward={buffid={82000060}},Desc='青翠的枫叶仿若一个初生的婴儿，懵懂的看着这个世界，它是稚嫩的，青涩的是充满希望的，它孕育了这件礼服送给所有世间的美好。',}",
  [51214] = "{id=51214,NameZh='枫之碎片',Icon='item_51214',Type=121,MaxNum=99,SellPrice=100,Desc='残破的枫叶，不知是谁竟残忍地把如此美丽的枫叶撕碎，若是能把它拼凑成一片完成的枫叶，就能得到枫的赠礼。',}",
  [51215] = "{id=51215,NameZh='枫之忆',Icon='item_51215',Type=501,MaxNum=99,SellPrice=100,AdventureSort=7031,AdventureValue=1,StorageReward={buffid={82000060}},Condition=8,Desc='枫，它有着不同的形态，是青涩或是温暖的亦或是热烈。但是无论哪种形态的它都是坚强的，领略岁月的磨砺，淀积着生命的成熟，服饰不过是枫的另一种表达罢了…',}",
