  [51241] = "{id=51241,NameZh='海拉使者·夜鸦',Icon='item_51241',Type=501,MaxNum=99,SellPrice=100,StorageReward={buffid={82000070}},Desc='当夜鸦鸣泣，我会想念生前的一切，但总有一天，我的名字会被人遗忘吧？',}",
  [51251] = "{id=51251,NameZh='海拉使者·渊蝶',Icon='item_51251',Type=501,MaxNum=99,SellPrice=100,StorageReward={buffid={82000070}},Desc='飞舞于冥河之上的蝴蝶啊，一旦翅膀停下，等待你的便是无尽深渊。',}",
