  [51253] = "{id=51253,NameZh='雷根贝勒M-5防护服',Icon='item_51253',Type=501,MaxNum=99,SellPrice=100,StorageReward={buffid={82000070}},Desc='雷根贝勒公司研发的第五代全能防护服。可抵御低温、辐射等侵害，并可提供生存所需的大量氧气。唯一的缺点是穿脱不便……所以为了避免“尴尬”，建议穿上之前不要喝太多软饮哟！',}",
