  [51281] = "{id=51281,NameZh='英才水手服·香橙',Icon='item_51281',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='洋溢着青春气息的水手服，原本是天津町地区的特色校服，不知不觉在整个米德加尔特流行起来，香橙是普隆德拉的限定配色！',Feature=1,TFValidDate='2018-09-11 05:00:00',ValidDate='2018-09-13 05:00:00',MainColor='f8a334FF',}",
