  [51321] = "{id=51321,NameZh='衣装·魅魔宝贝·雾紫',Icon='item_51320',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='披上外套，拉紧丝袜，化身魅魔宝贝穿行于幻之紫雾中。无论人类还是亡魂，恶魔抑或诸神，一个眼神就能勾走他的心！',Feature=1,TFValidDate='2018-10-16 05:00:00',ValidDate='2018-10-18 05:00:00',MainColor='733f76FF',}",
  [51322] = "{id=51322,NameZh='衣装·魅魔宝贝·绯月',Icon='item_51320',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='披上外套，拉紧丝袜，化身魅魔宝贝漫步于绯红之月下。无论人类还是亡魂，恶魔抑或诸神，一个眼神就能勾走他的心！',Feature=1,TFValidDate='2018-10-16 05:00:00',ValidDate='2018-10-18 05:00:00',MainColor='9e3152FF',}",
