  [51330] = "{id=51330,NameZh='百鬼丸·落枫',Icon='item_51330',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='那个由善良的妖怪们抚养长大的孩子，被伊达家训练成了一位伟大的斩鬼剑士。名为百鬼丸的他，凭借养母玉藻前赠于的妖刀“杀生石”与伊达晴子一同从天狗手中守护了天津町。而这件用枫红浸染羽织正是伊达家赠于百鬼丸的戎装。',Feature=1,TFValidDate='2018-11-13 05:00:00',ValidDate='2018-11-15 05:00:00',MainColor='a70c40FF',}",
  [51331] = "{id=51331,NameZh='百鬼丸·赭石',Icon='item_51330',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='那个由善良的妖怪们抚养长大的孩子，被伊达家训练成了一位伟大的斩鬼剑士。名为百鬼丸的他，凭借养母玉藻前赠于的妖刀“杀生石”与伊达晴子一同从天狗手中守护了天津町。而这件赭石色的羽织是百鬼丸在神社中刻苦修行时所穿的装扮。',Feature=1,TFValidDate='2018-11-13 05:00:00',ValidDate='2018-11-15 05:00:00',MainColor='56291eFF',}",
  [51332] = "{id=51332,NameZh='百鬼丸·橙空',Icon='item_51330',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='那个由善良的妖怪们抚养长大的孩子，被伊达家训练成了一位伟大的斩鬼剑士。名为百鬼丸的他，凭借养母玉藻前赠于的妖刀“杀生石”与伊达晴子一同从天狗手中守护了天津町。而这件橙黄色的羽织，是天津町的居民们为了答谢百鬼丸亲手制作的。',Feature=1,TFValidDate='2018-11-13 05:00:00',ValidDate='2018-11-15 05:00:00',MainColor='f8a334FF',}",
  [51333] = "{id=51333,NameZh='百鬼丸·苍澈',Icon='item_51330',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='那个由善良的妖怪们抚养长大的孩子，被伊达家训练成了一位伟大的斩鬼剑士。名为百鬼丸的他，凭借养母玉藻前赠于的妖刀“杀生石”与伊达晴子一同从天狗手中守护了天津町。而这件蕴含灵力的苍蓝色羽织正是百鬼丸的养母——大妖怪玉藻前在他离开仙山时赠与的礼物。充斥着玉藻前对养子的思念。',Feature=1,TFValidDate='2018-11-13 05:00:00',ValidDate='2018-11-15 05:00:00',MainColor='3772f0FF',}",
  [51340] = "{id=51340,NameZh='散华弥羽·赤枫',Icon='item_51340',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='作为伊达家历史上著名的阴阳术师，伊达晴子与百鬼丸一同战胜天狗的故事在天水之国家喻户晓。这身如同枫叶般艳红的和式衣装，象征着热情与决绝。',Feature=1,TFValidDate='2018-11-13 05:00:00',ValidDate='2018-11-15 05:00:00',MainColor='a70c40FF',}",
  [51341] = "{id=51341,NameZh='散华弥羽·夕紫',Icon='item_51340',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='作为伊达家历史上著名的阴阳术师，伊达晴子与百鬼丸一同战胜天狗的故事在天水之国家喻户晓。这身如同夕霞般梦幻美丽的和式衣装，象征着浪漫与神秘。',Feature=1,TFValidDate='2018-11-13 05:00:00',ValidDate='2018-11-15 05:00:00',MainColor='8121caFF',}",
  [51342] = "{id=51342,NameZh='散华巫羽·梦樱',Icon='item_51340',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='作为伊达家历史上著名的阴阳术师，伊达晴子与百鬼丸一同战胜天狗的故事在天水之国家喻户晓。这身如同樱花般清新可爱的和式衣装，象征着纯情与梦幻。',Feature=1,TFValidDate='2018-11-13 05:00:00',ValidDate='2018-11-15 05:00:00',MainColor='cb25a6FF',}",
  [51343] = "{id=51343,NameZh='散华弥羽·天水',Icon='item_51340',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='作为伊达家历史上著名的阴阳术师，伊达晴子与百鬼丸一同战胜天狗的故事在天水之国家喻户晓。这身如同清空沧海般别致的和式衣装，象征着优雅与宁静。',Feature=1,TFValidDate='2018-11-13 05:00:00',ValidDate='2018-11-15 05:00:00',MainColor='3330dbFF',}",
