  [51370] = "{id=51370,NameZh='梦罗克·流沙之刃',Icon='item_51370',Type=501,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureReward={buffid={62000020}},StorageReward={buffid={82000010}},Desc='根据梦罗克当地传说中[大流士]的形象所设计的衣服，传说中[大流士]拥有飞檐走壁的高超武技，甚至能利用沙砾的魔力控制时间的流速。',}",
