  [51431] = "{id=51431,NameZh='衣装·辉夜圣颂·幽夜',Icon='item_51430',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='繁星缀满夜空，银河流向天际，遥远的云端处钟声响起，是赞美的乐章在奏响。幽暗的夜幕笼罩着他，天使长微微颔首，洒下星光。',Feature=1,TFValidDate='2019-01-07 05:00:00',ValidDate='2019-01-10 05:00:00',MainColor='383671FF',}",
  [51432] = "{id=51432,NameZh='衣装·辉夜圣颂·寂风',Icon='item_51430',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='繁星缀满夜空，银河流向天际，遥远的云端处钟声响起，是赞美的乐章在奏响。青空的誓言召唤着他，天使长默默遥望，陷入寂静。',Feature=1,TFValidDate='2019-01-07 05:00:00',ValidDate='2019-01-10 05:00:00',MainColor='4147edFF',}",
  [51433] = "{id=51433,NameZh='衣装·辉夜圣颂·苍宇',Icon='item_51430',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='繁星缀满夜空，银河流向天际，遥远的云端处钟声响起，是赞美的乐章在奏响。大地的赐福护佑着他，天使长轻轻闭眼，走向苍茫。',Feature=1,TFValidDate='2019-01-07 05:00:00',ValidDate='2019-01-10 05:00:00',MainColor='1d9661FF',}",
  [51440] = "{id=51440,NameZh='衣装·流光礼赞·朝阳',Icon='item_51440',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='她自薄暮中醒来，在大地的尽头凝望天际。远方的第一缕晨曦，是心之所爱映照的光辉。绯色的朝霞映满天幕，是清晨在苏醒。',Feature=1,TFValidDate='2019-01-07 05:00:00',ValidDate='2019-01-10 05:00:00',MainColor='d13935FF',}",
