  [51520] = "{id=51520,NameZh='辞岁令·曈日',Icon='item_51520',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='风雪吹散了旧日的尘埃，晨光微现，新的一年在希冀中到来。朝阳将冰川消融，璀璨之间，梦想的光芒熠熠生辉。',Feature=1,TFValidDate='2019-01-28 05:00:00',ValidDate='2019-02-04 05:00:00',MainColor='e31800FF',}",
  [51521] = "{id=51521,NameZh='辞岁令·裁云',Icon='item_51520',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='风雪吹散了旧日的尘埃，晨光微现，新的一年在希冀中到来。云朵将回忆贮藏空中，微风吹拂，荡漾起怀恋的歌声。',Feature=1,TFValidDate='2019-01-28 05:00:00',ValidDate='2019-02-04 05:00:00',MainColor='4ca3f6FF',}",
  [51522] = "{id=51522,NameZh='辞岁令·迎风',Icon='item_51520',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='风雪吹散了旧日的尘埃，晨光微现，新的一年在希冀中到来。微风吹过，将冬日的天空变得温暖，日暮交融，祈盼的花朵正在盛开。',Feature=1,TFValidDate='2019-01-28 05:00:00',ValidDate='2019-02-04 05:00:00',MainColor='35e7a1FF',}",
  [51523] = "{id=51523,NameZh='辞岁令·栖月',Icon='item_51520',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='风雪吹散了旧日的尘埃，晨光微现，新的一年在希冀中到来。月光播撒着爱的种子，星云交错，写下祝福的篇章。',Feature=1,TFValidDate='2019-01-28 05:00:00',ValidDate='2019-02-04 05:00:00',MainColor='dd57ddFF',}",
  [51530] = "{id=51530,NameZh='春夕谣·曈日',Icon='item_51530',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='灯花辉映，烟火烂漫，白雪皑皑间，新年的钟声如期敲响。冬日初升，阳光点燃了温暖的思绪，是希望在继续生长。',Feature=1,TFValidDate='2019-01-28 05:00:00',ValidDate='2019-02-04 05:00:00',MainColor='e31800FF',}",
  [51531] = "{id=51531,NameZh='春夕谣·裁云',Icon='item_51530',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='灯花辉映，烟火烂漫，白雪皑皑间，新年的钟声如期敲响。冬雨寂静飘散在江河，流水微澜，不知是谁又许下了心愿。',Feature=1,TFValidDate='2019-01-28 05:00:00',ValidDate='2019-02-04 05:00:00',MainColor='4ca3f6FF',}",
  [51532] = "{id=51532,NameZh='春夕谣·迎风',Icon='item_51530',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='灯花辉映，烟火烂漫，白雪皑皑间，新年的钟声如期敲响。暖风轻拂，心愿之花悄然盛放，静听人们的祈祷。',Feature=1,TFValidDate='2019-01-28 05:00:00',ValidDate='2019-02-04 05:00:00',MainColor='35e7a1FF',}",
  [51533] = "{id=51533,NameZh='春夕谣·栖月',Icon='item_51530',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='灯花辉映，烟火烂漫，白雪皑皑间，新年的钟声如期敲响。夜幕降临，星河流淌在月光中，闪烁着回应遥远的思念。',Feature=1,TFValidDate='2019-01-28 05:00:00',ValidDate='2019-02-04 05:00:00',MainColor='dd57ddFF',}",
