  [51590] = "{id=51590,NameZh='礼袍·清正福音',Icon='item_51590',Type=501,MaxNum=99,SellPrice=100,StorageReward={buffid={80012810}},Desc='以守卫世间的正义与和平为己任者，才不会辜负这身礼袍。从此以后，必将一生践行高尚准则，成为一个宽和而勇敢的人。',TFValidDate='2020-09-05 05:00:00',ValidDate='2020-10-17 05:00:00',}",
