  [51690] = "{id=51690,NameZh='王国新贵',Icon='item_51690',Type=501,MaxNum=99,SellPrice=100,StorageReward={buffid={80012810}},Desc='这是为了庆贺他的胜利举办的舞会，那位凯旋而归的年轻将军，聚焦了全场的目光，人们都知道一颗新星正在冉冉升起，在贵族们的瞩目中，他缓缓走向她——“这位美丽的小姐，可以请您跳一支舞吗？”',}",
  [51691] = "{id=51691,NameZh='胜利舞步',Icon='item_51691',Type=501,MaxNum=99,SellPrice=100,StorageReward={buffid={80012810}},Desc='这是为了庆贺他的胜利举办的舞会，她穿上最华丽的衣装，带着最精致的妆容，只希冀他能够看自己一眼，唉，或许只是自己的幻想吧，待回过神来，他已走到身前——“这位美丽的小姐，可以请您跳一支舞吗？”',}",
