  [52322] = "{id=52322,NameZh='卡仑之牙',Icon='item_52322',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=496,Desc='魔物卡仑的锐利牙齿，那尖锐的程度让人惊讶，收纳时一定要格外小心。',Feature=1,}",
  [52323] = "{id=52323,NameZh='冰之粉末',Icon='item_52323',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=416,Desc='拥有着谜一般冰魔法，会吐出寒气的冰冷粉末, 尽量小心不要得到冻伤。',Feature=1,}",
  [52324] = "{id=52324,NameZh='焰之余烬',Icon='item_52324',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=496,Desc='我们每个人都会在世界上留下一些痕迹，就像火焰燃烧后会留下灰烬，燃烧殆尽总好过黯然消逝，不是么？',Feature=1,}",
  [52325] = "{id=52325,NameZh='闪耀圣水',Icon='item_52325',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=416,Desc='你问我闪耀圣水能不能喝？拜托，这可是圣水！我不会告诉你，它喝起来像没气的碳酸饮料。',Feature=1,}",
  [52326] = "{id=52326,NameZh='破斗篷的碎片',Icon='item_52326',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=496,Desc='从上面能看到许多刀刃的痕迹，很难想象斗篷的主人经历了什么。',}",
  [52327] = "{id=52327,NameZh='盾牌的碎片',Icon='item_52327',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=416,Desc='这些盾牌碎片上的图案拼起来似乎是个骷髅的形状。',}",
  [52328] = "{id=52328,NameZh='小红帽',Icon='item_52328',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=496,Desc='“我是你外婆…快开门吧…咦嘿嘿嘿…”戴上它，每晚都会有人敲响你的房门。',}",
  [52329] = "{id=52329,NameZh='邪恶之心',Icon='item_52329',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=496,Desc='邪恶的气息窜升着, 如果继续的看着它的话会被那气息感染似的。',}",
  [52330] = "{id=52330,NameZh='混沌金属',Icon='item_52330',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=524,Desc='米德加尔特大陆上最坚硬的金属之一, 由于硬度过高不易精炼。',}",
  [52331] = "{id=52331,NameZh='勇士的意志',Icon='item_52331',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=548,Desc='变成实验对象的勇士们之意志集合体。',}",
  [52332] = "{id=52332,NameZh='梦魇气息',Icon='item_52332',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=496,Desc='这是来自深渊的生物，你的一举一动都逃不过它的感知，“嘘，这是它的气息，它来了。”',}",
  [52333] = "{id=52333,NameZh='希巴姆之怒',Icon='item_52333',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=524,Desc='神祇？只有愚蠢的人类才会信奉那些无用神祇？我希巴姆才是值得敬仰的人！低贱的蝼蚁们！',}",
  [52334] = "{id=52334,NameZh='希尔之翎',Icon='item_52334',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=548,Desc='希尔队长是伊达平原罕见的生物之一，传言它身上有一根羽毛拥有着强大的魔力，是世人梦寐以求的东西！',}",
  [52335] = "{id=52335,NameZh='宝石海星',Icon='item_52335',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=189,Desc='闪烁着不可思议光芒的海星，阳光中仿佛宝石一般闪闪发亮。',}",
  [52336] = "{id=52336,NameZh='蛇妖之瞳',Icon='item_52336',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=524,Desc='传说中蛇妖的眼睛，拥有特殊的魔力，但凡看见的人都将被石化。',}",
  [52337] = "{id=52337,NameZh='燃烧的蛇鳞',Icon='item_52337',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=548,Desc='燃烧着炙炎的巨蛇之鳞，即使是深海最冰冷的水，都无法使其冷却。',}",
  [52338] = "{id=52338,NameZh='冰晶琉璃',Icon='item_52338',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=548,Desc='凝聚了千年冰霜的魔法石，闪烁着不可思议的光芒。仔细观察，隐约能看见雪花在其中漂浮。',}",
  [52339] = "{id=52339,NameZh='虚无之骸',Icon='item_52339',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=548,Desc='从黑暗中走来的灵魂啊：自阳光洒落的那个瞬间，你拥有的一切将消散如烟。',}",
  [52340] = "{id=52340,NameZh='无色泪滴',Icon='item_52340',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=548,Desc='灵魂奏者的眼泪,诉说着过去尘封的秘密与真实。',}",
  [52341] = "{id=52341,NameZh='浮梦光子',Icon='item_52341',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=548,Desc='世界树之种散发出的魔法粉尘,蕴含着不可思议的力量。',}",
  [52342] = "{id=52342,NameZh='沉船宝藏',Icon='item_52342',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=548,Desc='海底深处的宝箱，被溺亡者的怨恨缠绕……',}",
  [52343] = "{id=52343,NameZh='神秘眼镜',Icon='item_52343',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=548,Desc='塔奥群卡佩戴的石质眼镜，透过它或许能看到不一样的世界？',}",
  [52344] = "{id=52344,NameZh='猫眼欧珀',Icon='item_52344',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=548,Desc='绿色的神秘宝石，光芒如同迷梦猫妖的眼眸。',}",
  [52345] = "{id=52345,NameZh='堕化水晶',Icon='item_52345',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=548,Desc='本应被纯洁的信仰之力所灌满的水晶，却萦绕着堕落与腐化，然而又是谁在定义信仰的纯洁与否？',}",
  [52346] = "{id=52346,NameZh='纯金齿钉',Icon='item_52346',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=548,Desc='用来制作齿轮的零件，到底多富有的人，才会以用纯金打造这样的小部件？',}",
  [52347] = "{id=52347,NameZh='焚厄之瞳',Icon='item_52347',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=548,Desc='瞳孔倒映着灾厄，欲望与火焰同燃，极度的疯狂何尝不是最后的挣扎？',}",
  [52348] = "{id=52348,NameZh='剧毒之心',Icon='item_52348',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=548,Desc='作为喷射毒液的动力源泉，相当危险！请小心保存！',}",
  [52349] = "{id=52349,NameZh='乌龟外壳',Icon='item_52349',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=548,Desc='乌龟背上的外壳，晒干后相当坚硬，加工后可以制成多种相当有用的道具。可向商人购买。',}",
  [52350] = "{id=52350,NameZh='虚空核心',Icon='item_52350',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=548,Desc='警告，使用时请轻拿轻放，不当的操作将会腐蚀所有线路，另外避免肉眼直视，必须佩戴护目镜才可安全使用。——摘自《虚空核心材料使用手册》',}",
  [52352] = "{id=52352,NameZh='空之鳞',Icon='item_52352',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=548,Desc='释放出紫色的光，取自墨蛇君首次脱落的鳞片。',}",
  [52353] = "{id=52353,NameZh='无垢宝石',Icon='item_52353',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=548,Desc='湛蓝而坚硬，深藏着巨大的能量。',}",
  [52354] = "{id=52354,NameZh='罪源之心',Icon='item_52354',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=548,Desc='只是想靠近一点…再靠近一点…可这世上的人太多，我们总是离得那样远，神啊，求求您了，让他只属于我一个人吧。',}",
  [52355] = "{id=52355,NameZh='暗影宝石',Icon='item_52355',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=548,Desc='黑暗中潜藏着引诱者，不要跟随它走入深渊。',}",
  [52356] = "{id=52356,NameZh='血月之光',Icon='item_52356',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=548,Desc='红色的晶石为极夜带来微弱的光。',}",
  [52358] = "{id=52358,NameZh='噩梦龙珠',Icon='item_52358',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=548,Desc='你会在这里看到一个意想不到的世界，那是来自古龙时代的噩梦。',}",
  [52401] = "{id=52401,NameZh='铁',Icon='item_52401',Type=70,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=32,Desc='除了硬度够，它也较为轻薄，与其它金属比较起来，加工较容易，可用于制作装备的材料。',}",
  [52402] = "{id=52402,NameZh='钢铁',Icon='item_52402',Type=70,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=32,Desc='将铁浸泡几次特殊药水后，可以使其强度更高，制造出来的武器或防具硬度更高。 ',}",
  [52403] = "{id=52403,NameZh='煤炭',Icon='item_52403',Type=70,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=32,Desc='含有很多碳成分的矿石，可用于制作装备的材料。',Feature=1,}",
  [52404] = "{id=52404,NameZh='沙金',Icon='item_52404',Type=70,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=32,Desc='将掩藏在泥沙中的杂质通过一系列方法剔除后，提纯出的粉末状黄金，可用于制作装备的材料。',Feature=1,}",
  [52405] = "{id=52405,NameZh='水银',Icon='item_52405',Type=70,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=32,Desc='炼金术师在炼制不老药水的时候意外制作出的液态金属，可用于制作装备的材料。',Feature=1,}",
  [52406] = "{id=52406,NameZh='铠甲碎片',Icon='item_52406',Type=70,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=32,Desc='即使遭到了如此强大的冲击也仅仅是化作碎片，非常坚硬，可用于制作装备的材料。',Feature=1,}",
  [52407] = "{id=52407,NameZh='猫尾草',Icon='item_52407',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=50,Desc='最近在喵星流行种植的经济作物，猫咪们相信携带在身边会遇到好运。（传言正在某处“休假的美羽”也在收集，交给她也许是个好主意，但是她在哪里休假呢？）',GetLimit={limit={[999]={60,0}},source={22},type=5},Feature=1,}",
  [52408] = "{id=52408,NameZh='雷蒙盖顿的眼泪',Icon='item_52408',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=50,Desc='喵星人留下的悔恨的眼泪。因为没有掺杂仇恨极其纯净所以格外珍贵。（传言正在某处“休假的美羽”也在收集，交给她也许是个好主意，但是她在哪里休假呢？）',GetLimit={limit={[999]={60,0}},source={22},type=5},Feature=1,}",
  [52409] = "{id=52409,NameZh='雷蒙盖顿的短毛',Icon='item_52409',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=50,Desc='高贵的喵星人偶尔会掉落的毛发，虽然只是一小簇，但是依然摸上去可以让人联想到那别致的手感。（传言正在某处“休假的美羽”也在收集，交给她也许是个好主意，但是她在哪里休假呢？）',GetLimit={limit={[999]={60,0}},source={22},type=5},Feature=1,}",
  [52410] = "{id=52410,NameZh='红色飘带',Icon='item_52410',Type=70,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=50,Desc='严选了精致上等的天鹅绒的飘带，精美的工艺仿佛并非这个星球可以制作。（传言正在某处“休假的美羽”也在收集，交给她也许是个好主意，但是她在哪里休假呢？）',GetLimit={limit={[999]={60,0}},source={22},type=5},Feature=1,}",
  [52411] = "{id=52411,NameZh='彩色外皮',Icon='item_52411',Type=70,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=32,Desc='色彩华丽鲜明的外皮，可向收集商人购买。 ',Feature=1,}",
  [52412] = "{id=52412,NameZh='圣诞花环',Icon='item_52412',Type=70,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=32,Desc='用四季青树枝编织的花圈。感觉从某处传来钟声。',Feature=1,}",
  [52413] = "{id=52413,NameZh='哈比的羽毛',Icon='item_52413',Type=70,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=32,Desc='鸟人哈比身上掉落的漂亮的翎羽，据说只要在背包里放上一根，就会让男孩子们对你心动，所以哈比的羽毛受到很多女孩子的青睐。如果男孩子拿着的话，会发生什么呢？',Feature=1,}",
  [52414] = "{id=52414,NameZh='安眠木',Icon='item_52414',Type=70,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=32,Desc='从枯萎的树上砍下的木材，摸起来透着一丝诡异的魔力。',}",
  [52415] = "{id=52415,NameZh='发霉的金币',Icon='item_52415',Type=70,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=32,Desc='金币原本是不会发霉的，但这上面，沾染了太多的鲜血。',}",
  [52416] = "{id=52416,NameZh='血腥祈祷',Icon='item_52416',Type=70,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=32,Desc='以鲜血绘制出复杂的法阵，用以召唤强大的魔神，愿您听从奴仆的呼唤，让黑暗降临人间！',}",
  [52417] = "{id=52417,NameZh='奶油榛果',Icon='item_52417',Type=70,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=32,Desc='吃起来甜滋滋的榛果，因为数量稀少，总是会被某种毛茸茸的小动物藏起来。',}",
  [52418] = "{id=52418,NameZh='鱼尾',Icon='item_52418',Type=70,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=32,Desc='湖底鱼人的尾鳍，饱含魔法的力量。',}",
  [52419] = "{id=52419,NameZh='风花铃铛',Icon='item_52419',Type=70,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=32,Desc='捕虫堇携头上装饰的小花。其实是可以听闻风声的铃铛,方便其行动。',}",
  [52420] = "{id=52420,NameZh='骨螺壳',Icon='item_52420',Type=70,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=32,Desc='被海浪冲刷上岸的螺壳，坚硬无比。',}",
  [52421] = "{id=52421,NameZh='惑光粉',Icon='item_52421',Type=70,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=32,Desc='来自闪蝶的磷粉，在阳光下会闪烁特殊的光泽。',}",
  [52422] = "{id=52422,NameZh='白宝石',Icon='item_52422',Type=70,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=32,Desc='呈现出白色光芒的宝石。',}",
  [52423] = "{id=52423,NameZh='信仰露珠',Icon='item_52423',Type=70,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=32,Desc='由信仰凝结而成，拥有希望的翠色。',}",
  [52425] = "{id=52425,NameZh='捕风龙爪',Icon='item_52425',Type=70,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=32,Desc='传说这只龙爪来自一头翱翔于天际的风之龙，能够赋予持有者驾驭风的力量。',}",
  [52501] = "{id=52501,NameZh='曼陀罗',Icon='item_52501',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='拿在手里久了，手会觉得麻麻的，是一种特殊材料，可用于制作头饰和装备。',Feature=1,}",
  [52502] = "{id=52502,NameZh='天蓝宝石',Icon='item_52502',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='呈现出天空蓝之光芒的宝石，是一种特殊材料，可用于制作头饰和装备。',Feature=1,}",
  [52503] = "{id=52503,NameZh='青绿宝石',Icon='item_52503',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='呈现出青绿色之光芒的宝石，是一种特殊材料，可用于制作头饰和装备。',Feature=1,}",
  [52504] = "{id=52504,NameZh='黄宝石',Icon='item_52504',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='呈现出黄色光芒的宝石，是一种特殊材料，可用于制作头饰和装备。',Feature=1,}",
  [52505] = "{id=52505,NameZh='死人遗骨',Icon='item_52505',Type=70,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='不死生物的胫骨，是一种特殊材料，可用于制作头饰和装备。',Feature=1,}",
  [52506] = "{id=52506,NameZh='紫宝石',Icon='item_52506',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='呈现出紫色神秘之光芒的宝石，是一种特殊材料，可用于制作头饰和装备。',Feature=1,}",
  [52507] = "{id=52507,NameZh='兽人战士之证',Icon='item_52507',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='代表兽人战士身份地位的雕刻品，是一种特殊材料，可用于制作头饰和装备。',Feature=1,}",
  [52508] = "{id=52508,NameZh='断柄之刃',Icon='item_52508',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='整把呈现黑色完全不透光的刀，虽然现在只剩下刀的部分而不见刀柄，但它仍旧锐利如昔，削铁如泥，是一种特殊材料，可用于制作头饰和装备。',Feature=1,}",
  [52509] = "{id=52509,NameZh='冰雕玫瑰',Icon='item_52509',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='用冰块雕刻而成的，是一位住在寒冷地方相当知名的雕刻家的作品，是具有异国风味的礼物，是一种制作饰品的稀有材料。',Feature=1,}",
  [52510] = "{id=52510,NameZh='红玛瑙',Icon='item_52510',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='呈现出火红之光芒的宝石，是一种制作饰品的材料。',Feature=1,}",
  [52511] = "{id=52511,NameZh='犬牙',Icon='item_52511',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='犬类魔物突出的锋利尖牙，是一种制作饰品的材料。',Feature=1,}",
  [52512] = "{id=52512,NameZh='炽焰',Icon='item_52512',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='炽热的火焰，是一种制作饰品的材料。',Feature=1,}",
  [52513] = "{id=52513,NameZh='黑翼',Icon='item_52513',Type=70,Quality=3,MaxNum=99999,AuctionPrice=0,SellPrice=60,Desc='不知道是什么生物遗留的翅膀。黑色如墨。',Feature=1,}",
  [52514] = "{id=52514,NameZh='回忆宝石',Icon='item_52514',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='如同将时间静止在这个结晶中，看久了就窥见其中刻印的某人的记忆，究竟是谁呢？',Feature=1,}",
  [52515] = "{id=52515,NameZh='强效剂',Icon='item_52515',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='大幅强化效果的辅助药剂，需要配合其他药剂使用。',Feature=1,}",
  [52516] = "{id=52516,NameZh='圣诞袜子',Icon='item_52516',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='破掉有洞口的红色袜子，究竟曾经用来装过什么样的礼物呢？',Feature=1,}",
  [52517] = "{id=52517,NameZh='圣诞红色转蛋',Icon='item_52517',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='被神明所祝福过的转蛋, 让你温暖度过圣诞夜。',Feature=1,}",
  [52518] = "{id=52518,NameZh='熔岩宝石',Icon='item_52518',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='哇，这宝石看起来就像流动的熔岩一样漂亮！哇啊啊啊，好烫！烫！烫！',Feature=1,}",
  [52519] = "{id=52519,NameZh='天空之石',Icon='item_52519',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='别傻了，这又不是动画电影，相信我，就算你在脖子里挂上99个这玩意儿，你也不会像朱诺一样飞起来！',Feature=1,}",
  [52520] = "{id=52520,NameZh='黯魂粉尘',Icon='item_52520',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='墓碑周围的魔力凝结后形成的粉末物质，沾染到的话会发生灵异的事情…',}",
  [52521] = "{id=52521,NameZh='彩色袜子',Icon='item_52521',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='看造型像是女孩子的品味，但这个奇怪的尺寸似乎男性的脚才能穿进去……',}",
  [52522] = "{id=52522,NameZh='腐化的吊坠',Icon='item_52522',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='信仰这种东西，在绝对的恐怖下，究竟能够坚持到什么程度？',}",
  [52523] = "{id=52523,NameZh='黯淡的魔石',Icon='item_52523',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='有些咒语念到一半就会断了，剩下的一半，下辈子再念完吧。',}",
  [52524] = "{id=52524,NameZh='残骸',Icon='item_52524',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='不幸丧生的信徒骸骨，上面似乎还残留着逝者生前的痕迹。',}",
  [52525] = "{id=52525,NameZh='骨牙',Icon='item_52525',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='骨制的锐利牙齿，可以穿透任何硬物，是淬炼武器的材料之一。',}",
  [52526] = "{id=52526,NameZh='黄金喵喵草',Icon='item_52526',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='罕见的金色猫草。散发着不可思议的香气，没有猫咪能拒绝它的诱惑。',}",
  [52527] = "{id=52527,NameZh='阳光椰果',Icon='item_52527',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='所有椰果中最大最香甜的一颗，据说是被太阳直射了九十九天才有这么迷人的香气。',Delete=52527}",
  [52528] = "{id=52528,NameZh='柔软的绸缎',Icon='item_52528',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='当皮肤触碰到时，会感觉非常柔软的绸缎布料。',}",
  [52529] = "{id=52529,NameZh='猫眼石',Icon='item_52529',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='像猫眼一样晶亮的装饰用宝石,散发珍贵美丽的光芒。',}",
  [52530] = "{id=52530,NameZh='雪覆花',Icon='item_52530',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='盛开在森林中,象征着不屈与纯洁的爱。',}",
  [52531] = "{id=52531,NameZh='泡泡蘑菇',Icon='item_52531',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='大贤者克莱尔培育的小蘑菇,在夜晚会闪着特殊的光芒。',}",
  [52532] = "{id=52532,NameZh='幻星沙',Icon='item_52532',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='奇特的海底沙砾，蕴含着幻想之力。',}",
  [52533] = "{id=52533,NameZh='魔焰石',Icon='item_52533',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='火山深处的黑色岩石，因能够自燃被岛民们视为灾厄魔女力量的象征。',}",
  [52534] = "{id=52534,NameZh='白叶熏香',Icon='item_52534',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='普隆德拉的流行香，在王室成员里也很受欢迎。',}",
  [52535] = "{id=52535,NameZh='发亮鳞片',Icon='item_52535',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='闪闪发亮的神秘麟片，可向商人购买。',}",
  [52536] = "{id=52536,NameZh='灵魂之花',Icon='item_52536',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='腐化之地开出的花，却比寻常更为艳丽。',}",
  [52538] = "{id=52538,NameZh='熔岩龙骨',Icon='item_52538',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=60,Desc='生于熔岩中的巨龙，在死后魂归熔岩，也许只有这里能让死亡变得不再冰冷。',}",
  [52601] = "{id=52601,NameZh='金苹果',Icon='item_52601',Type=70,Quality=5,MaxNum=99999,SellPrice=100,Feature=1,}",
  [52611] = "{id=52611,NameZh='1点钟',Icon='item_52611',Type=160,MaxNum=99999,SellPrice=45,Desc='一枚弯曲的齿轮，触碰到它的人能感知到时空的弯曲和流动，心底最痛苦的记忆会如同在襁褓中诞生的婴儿一般被唤醒。钟楼1层门口的卡拉多纳正在收集这个道具。',NoStorage=5,}",
  [52612] = "{id=52612,NameZh='2点钟',Icon='item_52612',Type=160,MaxNum=99999,SellPrice=45,Desc='痛苦的石英手，决不能被它抓到，这只手不会放过它抓住的任何东西，似乎像一只大手想扭动天体回退时空一般。钟楼1层门口的卡拉多纳正在收集这个道具。',NoStorage=5,}",
  [52613] = "{id=52613,NameZh='3点钟',Icon='item_52613',Type=160,MaxNum=99999,SellPrice=45,Desc='时来运转之匣，听名字以为是个带来好运的物件，恰恰相反，这玩意儿能吸收人类的幸运，给人带来不幸，据说只要知道方法，打开此物，便能得到之中的所有好运。钟楼1层门口的卡拉多纳正在收集这个道具。',NoStorage=5,}",
  [52614] = "{id=52614,NameZh='4点钟',Icon='item_52614',Type=160,MaxNum=99999,SellPrice=45,Desc='预知魔石，这块红的发亮的魔石上刻着一个四字，将它装置在任何物体上，都能预知此物体在四小时之内的命运。钟楼1层门口的卡拉多纳正在收集这个道具。',NoStorage=5,}",
  [52615] = "{id=52615,NameZh='5点钟',Icon='item_52615',Type=160,MaxNum=99999,SellPrice=45,Desc='回退指针，别致的镀银指针，没有人知道它实际用了什么材料，但装在任何一个钟表上，将指针回拨五个小时，就能看到五个小时之前的影像。钟楼1层门口的卡拉多纳正在收集这个道具。',NoStorage=5,}",
  [52616] = "{id=52616,NameZh='6点钟',Icon='item_52616',Type=160,MaxNum=99999,SellPrice=45,Desc='思考分针，一根六厘米的金瑞分针，自带剧毒，可当做小匕首使用。这根毒针自己具有思考能力，将其放在手心上就能够飞出去刺中六个它想攻击的对象。可谁知道它会不会想攻击它的所有者呢…钟楼1层门口的卡拉多纳正在收集这个道具。',NoStorage=5,}",
  [52617] = "{id=52617,NameZh='7点钟',Icon='item_52617',Type=160,MaxNum=99999,SellPrice=45,Desc='异时空的擒纵轮，表面只有七根刺，却能准确的计量时间和空间的距离。听到擒纵轮的振动千万要捂住耳朵，当擒纵轮振到第七下时，无论什么勇者，听到之后都会陷入异时空无尽的黑暗。钟楼1层门口的卡拉多纳正在收集这个道具。',NoStorage=5,}",
  [52618] = "{id=52618,NameZh='8点钟',Icon='item_52618',Type=160,MaxNum=99999,SellPrice=45,Desc='一只会咆哮的转速跨轮，似乎在诉说着对过去和未来所有的不满，咆哮声能制造幻觉，以为自己正在度过一段快乐美好的时光，等醒来时发现自己已白发苍苍时日不多。钟楼1层门口的卡拉多纳正在收集这个道具。',NoStorage=5,}",
  [52619] = "{id=52619,NameZh='9点钟',Icon='item_52619',Type=160,MaxNum=99999,SellPrice=45,Desc='复原机芯，装置在任何人或物上，能暂时的吸收在九个小时内造成的任何伤害，但在九个小时后，一切都会变回原样。钟楼1层门口的卡拉多纳正在收集这个道具。',NoStorage=5,}",
  [52620] = "{id=52620,NameZh='10点钟',Icon='item_52620',Type=160,MaxNum=99999,SellPrice=45,Desc='冰冷的发条，散出的冷气甚至能冻结时间，接近的人都能被瞬间冻结在一个异时空中，但冻结的时间只能维持十个小时。钟楼1层门口的卡拉多纳正在收集这个道具。',NoStorage=5,}",
  [52621] = "{id=52621,NameZh='11点钟',Icon='item_52621',Type=160,MaxNum=99999,SellPrice=45,Desc='记忆镜面，每当十一点的钟声响起，站在此镜面前就能看到人内心深处最邪恶和丑恶的欲望，据说看到的人从此会在此镜面中无法自拔。钟楼1层门口的卡拉多纳正在收集这个道具。',NoStorage=5,}",
  [52622] = "{id=52622,NameZh='12点钟',Icon='item_52622',Type=160,MaxNum=99999,SellPrice=45,Desc='制裁者的潮汐，一块外表没有任何特别之处的摆轮，但每当午夜的钟声响起，将此摆轮抛到空中，就会打开通向虫洞的通道，虫洞中异时空的魔物蜂拥而出的响声震彻钟楼。钟楼1层门口的卡拉多纳正在收集这个道具。',NoStorage=5,}",
  [52623] = "{id=52623,NameZh='时钟',Icon='item_52623',Type=70,Quality=3,MaxNum=99999,SellPrice=100,Desc='无名金属制造而成的时钟，里面似乎蕴含着时间的力量，可用于制作头饰。',NoStorage=5,Feature=1,Delete=52623}",
  [52624] = "{id=52624,NameZh='破碎时空指针',Icon='item_52624',Type=61,UseMode=4025,MaxNum=99999,SellPrice=1,Desc='指针断裂的碎片，光是碎片就能干扰周围时间空间的磁场，使躁动的空间变的愈发不稳固，非常危险。据说集齐后装置在特殊的罗盘上，指针指向的位置能带人找到他心中所想。可从钟楼门口的钟塔军需官处兑换喜欢的道具。',Delete=52624}",
  [52625] = "{id=52625,NameZh='雪人',Icon='item_52625',Type=70,Quality=3,MaxNum=99999,AuctionPrice=0,SellPrice=100,Desc='可爱的白色精灵，每年圣诞节的时候会聚集在姜饼城偷偷吃冒险者的姜饼哦，身体的一部分是特殊的材料。',NoStorage=5,Feature=1,Delete=52625}",
  [52626] = "{id=52626,NameZh='雪绒花',Icon='item_52626',Type=61,UseMode=4024,MaxNum=99999,SellPrice=5,Desc='晶莹剔透的雪花，只有在极寒之地才会飘落的自然产物，看上去很容易碎，实际上非常坚固。',Delete=52626}",
  [52627] = "{id=52627,NameZh='浮空币',Icon='item_52627',Type=70,Quality=3,MaxNum=99999,AuctionPrice=0,SellPrice=100,Desc='有着特殊用途的货币，看样子像是出自天空城，或许能交易到很多好东西也说不定呢。',NoStorage=5,Feature=1,Delete=52627}",
  [52628] = "{id=52628,NameZh='遗迹古币',Icon='item_52628',Type=61,UseMode=4029,MaxNum=99999,SellPrice=1,Desc='古老遗迹中发现的货币，蕴含着古朴的气息，十分珍贵，很多收藏家都会收集几个这样的古币，逢人便拿出来炫耀呢。',Delete=52628}",
  [52629] = "{id=52629,NameZh='秘银古币',Icon='item_52630',Type=70,Quality=3,MaxNum=99999,AuctionPrice=0,SellPrice=100,Desc='用纯银浇注制成的硬币，看起来像是某种驱邪魔法需要用的触媒。',NoStorage=5,Feature=1,Delete=52629}",
  [52630] = "{id=52630,NameZh='惊悚南瓜',Icon='item_52629',Type=61,UseMode=4052,MaxNum=99999,SellPrice=1,Desc='参考南瓜精的头制作的小型装饰物，据说在里面点上蜡烛就能做南瓜灯了。',Delete=52630}",
  [52631] = "{id=52631,NameZh='机械齿轮',Icon='item_52631',Type=61,UseMode=4091,MaxNum=99999,SellPrice=5,Desc='破损不堪的机械齿轮，曾经被用在什么精密的仪器上。',Delete=52631}",
  [52632] = "{id=52632,NameZh='玻璃试管',Icon='item_52632',Type=70,Quality=3,MaxNum=99999,AuctionPrice=0,SellPrice=100,Desc='像是用来做什么实验的道具，里面装满了诡异的液体。',NoStorage=5,Feature=1,Delete=52632}",
  [52633] = "{id=52633,NameZh='信仰之钉',Icon='item_52633',Type=70,Quality=3,MaxNum=99999,AuctionPrice=0,SellPrice=100,Desc='集拉赫所有信徒信仰所制的坚钉，尖端的锋芒可以刺穿魔物最强的防御，从而驱逐一切的黑暗。',NoStorage=5,Feature=1,Delete=52633}",
  [52634] = "{id=52634,NameZh='圣书残页',Icon='item_52634',Type=61,UseMode=4097,MaxNum=99999,SellPrice=1,Desc='传言是由芙蕾雅女神留下的圣书的一角，尽管上面记载的内容已经模糊不清，但是其中蕴含的神明之力仍是不能小觑。',Delete=52634}",
  [52635] = "{id=52635,NameZh='心跳甜甜圈',Icon='item_52635',Type=61,UseMode=4098,MaxNum=99999,AuctionPrice=0,SellPrice=1,Desc='味道和外表一样甜蜜的甜甜圈，是远星大陆第一可爱的象征。七彩飞龙们经常为了争夺它闹得不可开交。',Delete=52635}",
  [52636] = "{id=52636,NameZh='珍珠贝',Icon='item_52636',Type=70,Quality=3,MaxNum=99999,SellPrice=100,Desc='有着晶莹光泽的美丽珍珠，被海水冲刷后漂到了沙滩上，深受猫咪女孩们的喜爱。',NoStorage=5,Feature=1,Delete=52636}",
  [52701] = "{id=52701,NameZh='治愈之音符',Icon='item_52701',Type=64,MaxNum=99999,AuctionPrice=0,SellPrice=100,Desc='闪耀着如同彩虹般光芒的音符，放在耳边能倾听到来自少女的歌声，那歌声充满了温暖和治愈的力量，为路途中的旅行者拂去所有的伤痛。（仅限在情人节期间使用的特别收藏品，听说普隆德拉大教堂门口的恋之双子星正在收集。）',}",
  [52702] = "{id=52702,NameZh='冒险的地图',Icon='item_52703',Type=64,MaxNum=99999,AuctionPrice=0,SellPrice=100,Desc='幽静的古老图书馆，透过雕花玻璃射入的阳光照射在轻微浮动着的尘埃上，在这收藏着九十万零六百六十六册藏书的图书馆，有着先人智者们留下的智慧。不单有着冒险旅行的遗迹藏宝地图，还有描绘关于如果通往人类自身心理深处的地图。（仅限在情人节期间使用的特别收藏品，听说普隆德拉大教堂门口的恋之双子星正在收集。）',}",
  [52703] = "{id=52703,NameZh='爱情的预兆',Icon='item_52702',Type=64,MaxNum=99999,AuctionPrice=0,SellPrice=100,Desc='平淡无奇的日子，自从遇到你以后，整个世界如同春天的花海，每天天空中都飞舞着花瓣和那让人陶醉的香味，那味道，应该就是爱情吧。（仅限在情人节期间使用的特别收藏品，听说普隆德拉大教堂门口的恋之双子星正在收集。）',}",
  [52704] = "{id=52704,NameZh='守护的决意',Icon='item_52705',Type=64,MaxNum=99999,AuctionPrice=0,SellPrice=100,Desc='时钟的摆针滴答滴答，15年如一瞬，这名工匠的铁锤敲击声也伴随了15年，如今依然铿锵有力。如同那句约定：比起盔甲而言，更坚定的是来自同伴们的守护！可千万别小看了这份决意！”（仅限在情人节期间使用的特别收藏品，听说普隆德拉大教堂门口的恋之双子星正在收集。）',}",
  [52705] = "{id=52705,NameZh='勇气的纹章',Icon='item_52704',Type=64,MaxNum=99999,AuctionPrice=0,SellPrice=100,Desc='每个来自B格猫星的人都会佩戴着的朴素但制作精细的纹章，上面镶嵌着的5颗不同的典雅的水晶，据说是源自很久很久以前的一个传说。如今这纹章也被用于馈赠给这片大陆上真正的勇敢冒险者们。（仅限在情人节期间使用的特别收藏品，听说普隆德拉大教堂门口的恋之双子星正在收集。）',}",
  [52706] = "{id=52706,NameZh='永恒的梦幻',Icon='item_52706',Type=64,MaxNum=99999,AuctionPrice=0,SellPrice=100,Desc='总所周知，历史长河中，一代又一代的人们追寻着所谓的永恒。这个梦幻而又真实的米德加尔特大陆也是如此。关于这个观点最近人们得到的结论是：无限接近的旅程中得到的智慧和财富才是所有文明被赋予的终极至宝。（仅限在情人节期间使用的特别收藏品，听说普隆德拉大教堂门口的恋之双子星正在收集。）',}",
  [52707] = "{id=52707,NameZh='温柔之音符',Icon='item_52701',Type=64,MaxNum=99999,AuctionPrice=0,SellPrice=100,Desc='耀眼夺目的音符带来少女的歌声，温柔而治愈的力量能够抚平冒险途中的伤痛。（仅限在情人节期间使用的特别收藏品，听说普隆德拉大教堂门口的恋之双子星正在收集。）',}",
  [52708] = "{id=52708,NameZh='勇气的地图',Icon='item_52703',Type=64,MaxNum=99999,AuctionPrice=0,SellPrice=100,Desc='从普隆德拉图书馆藏品中发现的古老冒险地图，唯有兼具爱与勇气的勇士才能使用。勇气不仅仅是面对魔物，审视内心更需要勇气。（仅限在情人节期间使用的特别收藏品，听说普隆德拉大教堂门口的恋之双子星正在收集。）',}",
  [52709] = "{id=52709,NameZh='恋爱的讯号',Icon='item_52702',Type=64,MaxNum=99999,AuctionPrice=0,SellPrice=100,Desc='与你相遇后的点点滴滴，如同漫天花雨触动心扉，阳光下你身上闪耀的星芒，应该就是恋爱的讯号吧。（仅限在情人节期间使用的特别收藏品，听说普隆德拉大教堂门口的恋之双子星正在收集。）',}",
  [52710] = "{id=52710,NameZh='不变的守护',Icon='item_52705',Type=64,MaxNum=99999,AuctionPrice=0,SellPrice=100,Desc='弹指间时光匆匆而去，比起光阴易逝，不变的是伙伴坚定的守护与陪伴（仅限在情人节期间使用的特别收藏品，听说普隆德拉大教堂门口的恋之双子星正在收集。）',}",
  [52711] = "{id=52711,NameZh='坚毅的纹章',Icon='item_52704',Type=64,MaxNum=99999,AuctionPrice=0,SellPrice=100,Desc='传说中很久之前的诸神之战中，最勇敢的冒险者被授予无上荣耀，而这枚镶有5颗水晶的精工稳重，便是那颗坚毅的纹章。（仅限在情人节期间使用的特别收藏品，听说普隆德拉大教堂门口的恋之双子星正在收集。）',}",
  [52712] = "{id=52712,NameZh='人间的至宝',Icon='item_52706',Type=64,MaxNum=99999,AuctionPrice=0,SellPrice=100,Desc='在漫长的冒险旅途中，冒险者们总在寻找宝物，而人间的至宝，并非一颗宝石一座神像，唯有文明和智慧得以永久流传。（仅限在情人节期间使用的特别收藏品，听说普隆德拉大教堂门口的恋之双子星正在收集。）',}",
