  [52835] = "{id=52835,NameZh='古拉姆晶末',Icon='item_52835',Type=70,MaxNum=99999,SellPrice=100,Desc='封印在卡片中的灵魂，经过千百年的沉淀形成的灵魂结晶，是一种可以用于合成卡片的材料，通过卡片分解获得。',}",
  [52836] = "{id=52836,NameZh='诺伦卡片',Icon='item_52836',Type=70,Quality=5,MaxNum=99999,SellPrice=100,Desc='【命运合成】消耗材料。可以在普隆德拉的国王波利处合成稀有卡片。可通过【神谕副本】获取。\n这份恩赐来自命运女神诺伦……',}",
  [52837] = "{id=52837,NameZh='古拉姆结晶',Icon='item_52837',Type=70,UseMode=71,MaxNum=99999,SellPrice=100,Desc='封印在卡片中的灵魂，经过亿万年的沉淀形成的灵魂结晶，是一种可以用于合成MVP卡片的材料，通过分解Mini卡片获得。',}",
  [52838] = "{id=52838,NameZh='古拉姆晶核',Icon='item_52839',Type=70,UseMode=71,MaxNum=99999,SellPrice=100,Desc='封印在卡片中的灵魂，经过亿万年的沉淀形成的灵魂结晶，是一种可以用于升级MVP卡片的材料，通过分解MVP卡片获得。',}",
  [52901] = "{id=52901,NameZh='记忆余晖',Icon='item_52901',Type=70,Quality=2,MaxNum=99999,SellPrice=100,Desc='英雄记忆的余晖，偶尔闪着微光。',}",
  [52902] = "{id=52902,NameZh='记忆晶核',Icon='item_52902',Type=70,Quality=3,MaxNum=99999,SellPrice=100,Desc='英雄记忆的结晶，折射出瑰丽的瞬间。',Feature=1,}",
  [52910] = "{id=52910,NameZh='龙脊契刻',Icon='item_52910',Type=70,Quality=2,MaxNum=99999,SellPrice=100,Desc='可以用来突破能量格。每一个强大龙族在陨落之刻，会将力量以图腾的形式汇聚脊骨之上，而这样的力量便可以突破能量的上限。',NoStorage=5,}",
  [52911] = "{id=52911,NameZh='秘传龙脊契刻',Icon='item_52911',Type=70,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='可以用来突破能量格。秘密传承的龙脊契刻。由于极其稀有，仅以高昂的价格在市场上隐秘流通。',NoStorage=5,}",
  [52912] = "{id=52912,NameZh='龙脊残片',Icon='item_52912',Type=60,Quality=2,MaxNum=99999,SellPrice=100,ComposeID=80,Desc='龙脊契刻的残片，可以用来合成龙脊契刻，龙脊契刻可以用于突破能量格。未被发掘的潜能，正等待强者的唤醒。',NoStorage=5,}",
  [52913] = "{id=52913,NameZh='龙骨拓片·自选',Icon='item_52914',Type=61,Quality=2,UseMode=4197,MaxNum=99999,SellPrice=100,Desc='可以选择获得一个职业的龙骨拓片，可以用来传承和升级对应职业的传承技能。上面神秘的符文来自古龙时代，如今只有传承使者可以解读。',NoStorage=5,}",
