  [52951] = "{id=52951,NameZh='秘传龙骨拓片-炼金术士',Icon='item_52951',Type=70,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='可以用来传承和升级对应职业的传承技能。上面神秘的符文来自古龙时代，如今只有传承使者可以解读。',NoStorage=5,}",
  [53001] = "{id=53001,NameZh='贵人的方巾',Icon='item_50001',Type=160,MaxNum=99999,SellPrice=100,Desc='精美的绸缎制成的手巾，感觉有些年代了，据说是已经消亡的古代王国的公主所拥有的物品。',NoSale=1,NoStorage=5,}",
  [53002] = "{id=53002,NameZh='精美的发钗',Icon='item_50001',Type=160,MaxNum=99999,SellPrice=100,Desc='精美别致的款式，精雕细琢的细节和使用的琉璃宝石材质可以看出是从东方传过来的稀有品。',NoSale=1,NoStorage=5,}",
  [53003] = "{id=53003,NameZh='仿佛穿越时空的花',Icon='item_50001',Type=160,MaxNum=99999,SellPrice=100,Desc='这朵娇艳欲滴的绿色花朵仿佛就和依斯鲁得人们记忆中往昔里的翡翠蔷薇一样，已经断绝已久的花真的是从遥远的时空穿行而来的吗？',NoSale=1,NoStorage=5,}",
  [53004] = "{id=53004,NameZh='古代的水晶戒指盒',Icon='item_50001',Type=160,MaxNum=99999,SellPrice=100,Desc='即使空空如也，这个有些年头的戒指盒依然散发着古典贵族的气质。外盒都已如此，想必当初其中的戒指本身那就更加的华美了呢！',NoSale=1,NoStorage=5,}",
  [53005] = "{id=53005,NameZh='刻有蔷薇纹章的戒指',Icon='item_50001',Type=160,MaxNum=99999,SellPrice=100,Desc='刻有已经泯灭的古城克雷斯特汉姆的某个骑士团纹章的戒指，被包养的非常好，它的拥有着一定经常擦拭之。',NoSale=1,NoStorage=5,}",
  [53006] = "{id=53006,NameZh='古代卷轴',Icon='item_50001',Type=41,MaxNum=99999,SellPrice=100,Desc='？？？',NoSale=1,NoStorage=5,}",
  [53007] = "{id=53007,NameZh='古代卷轴（已阅读）',Icon='item_50001',Type=160,MaxNum=99999,SellPrice=100,Desc='？？？',NoSale=1,NoStorage=5,}",
  [53008] = "{id=53008,NameZh='导师资格证',Icon='task_certificate',Type=160,MaxNum=99999,SellPrice=1,Desc='由隶属于卢恩·米德加尔特王国的冒险者公会颁发，象征着责任和荣誉的导师资格证书，那么从今天起，可爱的初心者就交给你来教导了！',NoStorage=5,}",
  [53009] = "{id=53009,NameZh='特制勇士之帽',Icon='item_45089',Type=160,MaxNum=99999,SellPrice=100,Desc='这是一顶特制的勇士之帽，看上去比普通的勇士之帽小一些，在帽檐处有一行小字“加油，加达尔”。',NoSale=1,NoStorage=5,}",
  [53010] = "{id=53010,NameZh='弗里曼的勇气徽章',Icon='',Type=160,MaxNum=99999,SellPrice=100,Desc='终极决斗俱乐部的每一个成员都有属于自己的一块徽章，成员的实力越强，徽章的成色越高。',NoSale=1,NoStorage=5,}",
  [53011] = "{id=53011,NameZh='安德鲁的勇气徽章',Icon='',Type=160,MaxNum=99999,SellPrice=100,Desc='终极决斗俱乐部的每一个成员都有属于自己的一块徽章，成员的实力越强，徽章的成色越高。',NoSale=1,NoStorage=5,}",
  [53012] = "{id=53012,NameZh='布雷尔的勇气徽章',Icon='',Type=160,MaxNum=99999,SellPrice=100,Desc='终极决斗俱乐部的每一个成员都有属于自己的一块徽章，成员的实力越强，徽章的成色越高。',NoSale=1,NoStorage=5,}",
  [53013] = "{id=53013,NameZh='安格斯的勇气徽章',Icon='',Type=160,MaxNum=99999,SellPrice=100,Desc='终极决斗俱乐部的每一个成员都有属于自己的一块徽章，成员的实力越强，徽章的成色越高。',NoSale=1,NoStorage=5,}",
  [53014] = "{id=53014,NameZh='少女的发簪',Icon='item_45190',Type=160,MaxNum=99999,SellPrice=100,Desc='【古城末日“叛变者”调查档案1号】卡珊德拉公主的饰物，上面刻有她的名字缩写，是当时流行的款式。由欧律皮罗斯男爵赠送给公主作为定情信物。发簪有烧伤过的痕迹，传说公主曾经因一场大火而毁容，但男爵仍然承诺将娶她为妻。',NoSale=1,NoStorage=5,}",
  [53015] = "{id=53015,NameZh='损毁的头盔',Icon='item_task_29',Type=160,MaxNum=99999,SellPrice=100,Desc='【古城末日“叛变者”调查档案2号】俄思鲁将军的头盔，其上有一道深而长的刀痕，那是和某位男爵决斗时留下的耻辱。后来，这位将军因骁勇善战不苟言笑，被卡珊德拉公主赐予“寒冰锻造的利刃”之称，并拔剑在头盔上划下了另一道痕迹。不知公主是不是在开玩笑，不过这个头盔伴随着将军一生。',NoSale=1,NoStorage=5,}",
  [53016] = "{id=53016,NameZh='古旧的勋章',Icon='27',Type=160,MaxNum=99999,SellPrice=100,Desc='【古城末日“叛变者”调查档案3号】这是施密特王朝特制的战士勋章，徽纹代表着持有者为施密特家族的亲信，骑士团中只有极少数人会被国王授予这种勋章。它并非代表荣耀，而是成为施密特王家的影子，执行秘密的任务。在这枚勋章上，竟然刻着卢恩王国七大家族之一，鲁贝布勒格家族的姓氏。',NoSale=1,NoStorage=5,}",
  [53017] = "{id=53017,NameZh='深红的披风',Icon='item_43002',Type=160,MaxNum=99999,SellPrice=100,Desc='【古城末日“叛变者”调查档案4号】披风里衬上有伊多墨将军的名字，这位赫赫有名的施密特王朝大将，与俄思鲁将军并称“王国双璧”，生前两人亦是挚友。不过关于这位将军的死，传言却是扑朔迷离。据说将军并非战死，而是被暗杀。“俄思鲁将军秘密处死男爵家仆”的王家丑闻事件，被认为与伊多墨将军之死有关。',NoSale=1,NoStorage=5,}",
  [53018] = "{id=53018,NameZh='破碎的宝石',Icon='item_5102',Type=160,MaxNum=99999,SellPrice=100,Desc='【古城末日“叛变者”调查档案5号】这颗宝石曾被镶嵌在施密特国王的权杖上，世代相传。宝石的碎裂，映照着这个王族的末路。大贤者巴特蒙德曾警告过国王，将这颗宝石从权杖上取下并丢弃，否则王国必将迎来末日。于是，这颗宝石就被锁进了宝箱，国王称它为“恶魔的诱惑”。',NoSale=1,NoStorage=5,}",
  [53019] = "{id=53019,NameZh='残旧的匕首',Icon='item_40724',Type=160,MaxNum=99999,SellPrice=100,Desc='【古城末日“叛变者”调查档案6号】“阿芙洛忒的匕首”是它久违流传之名，刀柄上的纹章属于克雷霍尔伦家族，因此它被称为“弑君者匕首”。篡位者吉奥布罗克国王的王后阿芙洛忒命一位手艺精湛的工匠锻造了它，并赠送给丈夫。这把匕首后来一直被克雷霍尔伦家族保存，最后一位主人将它锁进了箱子里，如同想要将克雷霍尔伦家族那不能明言的过去藏起，渴望那沉重的负担从此被人遗忘。',NoSale=1,NoStorage=5,}",
  [53020] = "{id=53020,NameZh='祈祷的项链',Icon='item_44019',Type=160,MaxNum=99999,SellPrice=100,Desc='【古城末日“叛变者”调查档案7号】安德斯神父的十字架项链，过去，他常常握着它祈祷施密特王族的永久康盛，并祝福他的爱人幸福。谣传他过去是皇家宫廷乐师，因被某位伯爵诬陷暗中爱慕王后，为了王后的名誉而选择离开王庭，隐居在修道院中，除了祷告之外，又领养了许多贫苦孤儿。',NoSale=1,NoStorage=5,}",
  [53021] = "{id=53021,NameZh='罗娜的魔书',Icon='item_42518',Type=160,MaxNum=99999,SellPrice=100,Desc='【古城末日“叛变者”调查档案8号】罗娜的魔法书，记录着她抄录的那些失传的古魔法咒语。罗娜被认为是邪恶的巫师，她孤独地居住在一间偏僻小屋里，研究着在人们眼中被视为最邪恶禁忌的魔法，因此没有人愿意接近她的住处，只有安德斯神父愿意和她交谈。她送了神父一条项链，说是能带来幸福。这本书在她死后，被转交给安德斯神父保管。不久之后，安德斯神父又对一位来访者宣称，遗失了这本书……',NoSale=1,NoStorage=5,}",
  [53022] = "{id=53022,NameZh='士兵的日记',Icon='item_3002',Type=160,MaxNum=99999,SellPrice=100,Desc='【古城末日“叛变者”调查档案9号】古城守备士兵的日记，里面写满了枯燥的巡逻日常、成年人的深夜笑话、下水道的鬼怪传说、施密特王族的那些王家闹剧、流浪狗“小柯”的饲养日志、对修道院里传出的琴声品评……最后一篇日记停留在两百年前的那个夜晚，上面写道：恶魔来了，但海因里希将军会带领我们战胜恶魔。等我凯旋归来，我决定对那条流浪犬好一点……',NoSale=1,NoStorage=5,}",
  [53023] = "{id=53023,NameZh='腐蚀的头骨',Icon='item_task_30',Type=160,MaxNum=99999,SellPrice=100,Desc='【古城末日“叛变者”调查档案10号】据传是施密特王朝第一任国王的头骨，又相传是国王祖父的头骨，也有流传说是先代国王的战友大魔导士路西菲尔的头骨……总之，这颗神秘的头骨被封存在王族后花园地窖中很多年。触碰头骨，似乎能看到头骨上飘出一个白糊糊的鬼影……',NoSale=1,NoStorage=5,}",
  [53024] = "{id=53024,NameZh='残缺的石碑',Icon='item_5027',Type=160,MaxNum=99999,SellPrice=100,Desc='【古城末日“叛变者”调查档案11号】卡珊德拉公主的墓碑，这位公主死于一场传染病，临终前十分孤独凄惨，只有一名忠心的侍女照顾着她。石碑上写着她的墓志铭：愿宽容如烈火带来温暖，愿善良之人终得一切恩露之报。',NoSale=1,NoStorage=5,}",
  [53025] = "{id=53025,NameZh='骑士的羽穗',Icon='item_45089',Type=160,MaxNum=99999,SellPrice=100,Desc='【古城末日“叛变者”调查档案12号】欧律皮罗斯男爵家族特有的象征，它被拔下来，伴随着卡珊德拉公主度过了病患余生。男爵在破城之日，于公主墓碑前刎颈自杀，当时他手中握着这根羽穗，在墓碑前的地上用剑刻下了愧疚之言。男爵倒在血泊中时，羽穗随风飘远，爱意随风而逝。',NoSale=1,NoStorage=5,}",
  [53026] = "{id=53026,NameZh='宰相的怀表',Icon='item_task_31',Type=160,MaxNum=99999,SellPrice=100,Desc='【古城末日“叛变者”调查档案13号】奥德修斯宰相的怀表，是他非常珍爱之物。据说是妻子的遗物，宰相日理万机时总是打开它确认时间，从未让它离开过身边。但它现在却没有陪伴着宰相的遗体，是有人将它偷走了吗？怀表本身价值不菲，曾经有人向宰相高价收取这块怀表，当然被拒绝了。',NoSale=1,NoStorage=5,}",
  [53027] = "{id=53027,NameZh='贵妇的礼帽',Icon='item_task_32',Type=160,MaxNum=99999,SellPrice=100,Desc='【古城末日“叛变者”调查档案14号】海因里希执政期间，曾因为这顶礼帽而闹出过一段绯闻，它原先被摆放在海因里希的书房中，后来却出现在了一位贵妇的头上。不过严肃古板的执政官阁下，可不像是会偷偷赠送贵妇礼帽的那种男人啊，大家都认为他这辈子唯一的情人就是他的工作。',NoSale=1,NoStorage=5,}",
  [53028] = "{id=53028,NameZh='国王的宝剑',Icon='item_40332',Type=160,MaxNum=99999,SellPrice=100,Desc='【古城末日“叛变者”调查档案15号】初代施密特国王使用过的剑，此后，每一任国王都会在加冕仪式上接过它。它见证了施密特王族的兴衰。最后一任国王将它留在了克雷斯特汉姆古城，远赴他乡再也没有回来。海因里希执政官总是遥遥望着这把国王宝剑叹息。希默梅思用它斩下了海因里希的头颅，然后随手把它丢弃了，于是它所承载的一代王朝落下帷幕。',NoSale=1,NoStorage=5,}",
  [53029] = "{id=53029,NameZh='GLC.A031号档案',Icon='task_certificate',Type=160,Quality=4,MaxNum=99999,SellPrice=100,Desc='A.W800年，希默梅思带着不死军团攻入克雷斯特汉姆，皇家军团缚手难敌，王城一夜之间变为死城。有人认为，皇家中有“叛变者”向希默梅思泄露军情。一位秘密调查员根据仅存下来的皇家文献，锁定了十五个嫌疑人，并将这十五个人的资料编集为【古城末日“叛变者”档案】。档案中关于“叛变者”的真实身份并未明确提及，但从那些相关物品的信息中可寻得蛛丝马迹。档案详情在春楠那里可以复查。',NoSale=1,NoStorage=5,}",
  [53030] = "{id=53030,NameZh='破旧王冠',Icon='item_task_28',Type=160,MaxNum=99999,SellPrice=100,Desc='造型夸张的王冠，在岁月的侵蚀下变得破损不堪，上面隐约雕刻着三个模糊的字…',NoSale=1,NoStorage=5,}",
  [53031] = "{id=53031,NameZh='碧蓝宝石',Icon='item_task_27',Type=160,MaxNum=99999,SellPrice=100,Desc='碧蓝色的宝石，通体晶莹剔透，完全没有深埋地下的泥土气息…',NoSale=1,NoStorage=5,}",
  [53032] = "{id=53032,NameZh='赤红晶钻',Icon='item_task_26',Type=160,MaxNum=99999,SellPrice=100,Desc='赤红色的钻石，时不时地散发出妖异的红光，内部有着不知名的力量涌动…',NoSale=1,NoStorage=5,}",
  [53033] = "{id=53033,NameZh='休密兹的王冠',Icon='item_task_25',Type=160,Quality=3,MaxNum=99999,SellPrice=100,Desc='暴君休密兹在曾经被巨人族与诸神大战中毁灭的遗址上建立了克雷斯特汉姆。休密兹的威望越来越高最后掌握了无所不为的大权。随著王宫改建的开始，他花税金如流水，他那些善于阿谀奉承的心腹向他进言，为了彰显他的无上王权，休密兹需要一个世界上独一无二的王冠。很快，休密兹就搜集到了两颗珍惜无比的宝石，命令宝石工匠，日夜雕琢，又运来最珍贵的金属来打造王冠的底座。甚至有数名宝石工匠因为持续工作而暴毙，这才在加冕之时把王冠制作出来。这个王冠也被民众暗地里称之为“暴君之冠”。',NoSale=1,NoStorage=5,}",
  [53034] = "{id=53034,NameZh='虎蜥酒',Icon='item_task_10',Type=160,MaxNum=99999,SellPrice=100,Desc='布兰奇亲手制作的美酒。',NoSale=1,NoStorage=5,}",
  [53035] = "{id=53035,NameZh='毒药',Icon='item_5021',Type=160,Quality=2,MaxNum=99999,SellPrice=100,Desc='【楔子】许多故事的开始，都是伴随着阴谋、凶杀、冤情、争斗。那天晚上，莫里茨公爵冰冷地躺在床上，脚边倒着一瓶毒药。',NoSale=1,NoStorage=5,}",
  [53036] = "{id=53036,NameZh='魔眼',Icon='item_7337',Type=160,Quality=2,MaxNum=99999,SellPrice=100,Desc='【憎恶之书·公正】“是献出你的灵魂，还是让我夺走你朋友的生命，做出选择吧！”恶魔用它那似乎能洞察人类内心的眼睛，微笑着流露出狰狞的目光，对面前的驱魔人说道。卡伦赞德正是被这双魔眼所蛊惑。',NoSale=1,NoStorage=5,}",
  [53037] = "{id=53037,NameZh='符文',Icon='item_12004',Type=160,MaxNum=99999,SellPrice=100,Desc='【憎恶之书·真相】驱魔人的符上，狂乱的字迹流露出书写者内心的挣扎与不安，是用力量维护公正，还是用力量解救落难的生命？驱魔人明亮的眼睛能看透黑暗，却看不透世间的正义。',NoSale=1,NoStorage=5,}",
  [53038] = "{id=53038,NameZh='钥匙',Icon='item_40011',Type=160,MaxNum=99999,SellPrice=100,Desc='【恐惧之书·孤独】阴冷的监狱中，往往隐藏着禁忌、罪恶的故事。而用来开启它们的钥匙，就像是巫婆的苹果。至情至义的驱魔人知道这样做违背了法律与秩序，但他还是用钥匙打开了牢门，放走了他最好的朋友。',NoSale=1,NoStorage=5,}",
  [53039] = "{id=53039,NameZh='手铐',Icon='item_5042',Type=160,MaxNum=99999,SellPrice=100,Desc='【恐惧之书·真相】牢房狭小的窗洞漏进清冷的月光，当骄傲的驱魔人失去自由之时，仿佛也失去了所有，包括自己存在的价值。链铐的响动在提醒着他犯下的错误。他无法向任何人倾诉苦衷，因为是他自己将自己推进了孤独的深渊。',NoSale=1,NoStorage=5,}",
  [53040] = "{id=53040,NameZh='粮食',Icon='item_12305',Type=160,MaxNum=99999,SellPrice=100,Desc='【怯懦之书·仁慈】放置在我们眼前的普通食物，困苦的时候，它会比金子更珍贵渴求，而富裕之时，它却廉价得仿佛脚边的野草，随意可践踏忽视。',NoSale=1,NoStorage=5,}",
  [53041] = "{id=53041,NameZh='金币',Icon='item_105',Type=160,Quality=2,MaxNum=99999,SellPrice=100,Desc='【怯懦之书·真相】金钱就像是这世间的一切诱惑，过度纵容，就会导致极端的后果。为了满足逐渐贪得无厌的卡伦赞德的要求，驱魔人放弃了一切，而这并没有带来善果。',NoSale=1,NoStorage=5,}",
  [53042] = "{id=53042,NameZh='书卷',Icon='item_42519',Type=160,MaxNum=99999,SellPrice=100,Desc='【嫉妒之书·睿智】古列弗深爱书籍，他相信那是它最忠诚而值得信赖的朋友。因此，他有一颗博大精深的头脑，总是能想出绝妙的主意扭转乾坤。但这并没有给他带来好下场。智者千虑却必有一失。',NoSale=1,NoStorage=5,}",
  [53043] = "{id=53043,NameZh='冕冠',Icon='item_45046',Type=160,MaxNum=99999,SellPrice=100,Desc='【嫉妒之书·真相】卡伦赞德的野心愈加庞大，最后，他看向了那顶璀璨的冕冠。华丽的外表下，早已是枯朽的灵魂。他泯灭了一切良善，冷酷无情得就像一个真正的恶魔。欲望的终点，往往是穷途末路。',NoSale=1,NoStorage=5,}",
  [53044] = "{id=53044,NameZh='利刃',Icon='item_40305',Type=160,Quality=2,MaxNum=99999,SellPrice=100,Desc='【尾声】驱魔人行走在夜间，以狩猎魔鬼为职业的他，今晚要去狩猎一个真正的恶魔。他握着锋利的武器，内心默念：“卡伦赞德，你曾是我最重要的朋友，所以也必须由我来洗净你的罪孽。而我将背负罪孽，永生潜行在黑夜中。”',NoSale=1,NoStorage=5,}",
  [53045] = "{id=53045,NameZh='GLC.X114号档案',Icon='task_certificate',Type=160,Quality=4,MaxNum=99999,SellPrice=100,Desc='记录了四个互为挚友并深受国王恩宠的驱魔人互相间打了一个赌，然而谁也没有真正在意这场赌局。但命运的嘲讽却悄然降临在他们身上，为了挽救他们的好友卡伦赞德，四人使用了不同的方法，却酿成了一场惨痛悲剧。档案详情在影子驱魔人那里可以复查。',NoSale=1,NoStorage=5,}",
  [53046] = "{id=53046,NameZh='初见的华尔兹',Icon='item_48545',Type=160,Quality=2,MaxNum=99999,SellPrice=100,Desc='【第一乐章】假面舞会上的面具。它记录着桂瑟兰妮与加布里尔在假面之下开始的一段美丽华尔兹。初见之时，未知的一切，华丽的盛装，彼此的吸引，在富丽堂皇的舞池中相映生辉，童话一般的美好而浪漫。',NoSale=1,NoStorage=5,}",
  [53047] = "{id=53047,NameZh='玫瑰的踢踏舞',Icon='item_task_16',Type=160,Quality=2,MaxNum=99999,SellPrice=100,Desc='【第二乐章】凋零的荆棘玫瑰。它被收藏在加布里尔的书桌右手边第一格抽屉中，制成了精巧的干花，夹在一本名为《梦中婚礼》的书中。当死讯传来之时，桂瑟兰妮亲手将它放进了加布里尔的遗棺中。',NoSale=1,NoStorage=5,}",
  [53048] = "{id=53048,NameZh='爱情的圆舞曲',Icon='item_40331',Type=160,Quality=2,MaxNum=99999,SellPrice=100,Desc='【第三乐章】细长锋利的西洋剑。桂瑟兰妮收到这件礼物时，不知该夸赞将军心意别致还是叹息他不懂情调。很长一段时间，它都被挂在墙上当一件精致的装饰品，直到桂瑟兰妮把它拿下来，放到长眠的将军身边，并说：“谢谢你的守护。”',NoSale=1,NoStorage=5,}",
  [53049] = "{id=53049,NameZh='月光的小夜调',Icon='22',Type=160,Quality=2,MaxNum=99999,SellPrice=100,Desc='【第四乐章】远方而来的战讯。“血色胜利”之战，王国军于险恶重重中获得艰难的胜利，战讯传至王城，桂瑟兰妮在侯爵府邸落下悲伤的眼泪，懊悔凝结在无声泪水中。',NoSale=1,NoStorage=5,}",
  [53050] = "{id=53050,NameZh='教堂的圣福音',Icon='item_52304',Type=160,Quality=2,MaxNum=99999,SellPrice=100,Desc='【第五乐章】绅士的手帕。修道院中，忏悔的言语有谁在聆听？抑郁的容颜是为谁思念？绅士迈着轻轻的脚步靠近正在祈祷的女子身边，递出手帕款款温柔说：“请不要因为后悔而哭泣，它不适合你。我亲爱的桂瑟兰妮。”',NoSale=1,NoStorage=5,}",
  [53051] = "{id=53051,NameZh='王子的嘲笑声',Icon='item_52316',Type=160,Quality=2,MaxNum=99999,SellPrice=100,Desc='【第六乐章】碎裂的镜子。王子在富丽堂皇的舞池中央丢下假面，戏谑嘲笑道：“来不及了，你这个贪心势利的女人。破镜永不能恢复原貌。”璀璨迷人的水晶灯光下，童话似乎就在眼前破碎，再不会有浪漫的华尔兹。',NoSale=1,NoStorage=5,}",
  [53052] = "{id=53052,NameZh='梦中的婚礼章',Icon='item_45198',Type=160,Quality=2,MaxNum=99999,SellPrice=100,Desc='【第七乐章】枯黄的落叶。“如果，我不能在神父的面前吻你，幸福永不会降临在你我身上。”表达着如此爱意的人，在希默梅思的降临中，永远沉浸入梦中的婚礼。落叶带走生命的韵律。',NoSale=1,NoStorage=5,}",
  [53053] = "{id=53053,NameZh='GLC.E109号档案',Icon='task_certificate',Type=160,Quality=4,MaxNum=99999,SellPrice=100,Desc='记录了克雷斯特汉姆古城灭亡前夕举行的一场盛大婚礼。桂瑟兰妮与加布里尔王子因偏见产生重重误会，又因爱而最终携手，然而就在婚礼举行之时，希默梅思降临，将一切美好带入了永不会醒来的梦境中。档案详情在墓地守夜人那里可以复查。',NoSale=1,NoStorage=5,}",
  [53054] = "{id=53054,NameZh='商人的记账簿',Icon='item_3605',Type=160,MaxNum=99999,SellPrice=100,NoSale=1,NoStorage=5,}",
  [53055] = "{id=53055,NameZh='铁匠转职专用货物',Icon='item_111',Type=160,MaxNum=99999,SellPrice=100,NoSale=1,NoStorage=5,}",
  [53056] = "{id=53056,NameZh='鲜血宝石',Icon='dark_004',Type=48,MaxNum=99999,SellPrice=100,Desc='原本透明无瑕的月白宝石，因浸润过神族的血，而变得鲜红欲滴。将它镶嵌在剑上，能唤醒剑灵。开启骑士职业专属任务【骑士的起源】的重要道具。',Level=80,NoStorage=5,}",
  [53057] = "{id=53057,NameZh='古老的卷轴',Icon='14',Type=62,MaxNum=99999,SellPrice=100,Desc='充满着沧桑感的破旧羊皮书卷，光从它的外表根本看不出它的作用，但它却是古老的莱弥亚家族的传承之物，完成该区域主线任务可解锁克雷斯特汉姆古城微笑小姐处兑换皇家武器外观权限。',NoSale=1,NoStorage=5,}",
  [53058] = "{id=53058,NameZh='神秘气体',Icon='item_47018',Type=160,MaxNum=99999,SellPrice=10,Desc='一种不知名的雾状气体，收藏家皮克西正在收集这种物品，作为收藏品，他需要[c][ff7f00]25[-][/c]份气体充实他的库存。通过击杀邪骸浪人·天业云剑获得。',NoSale=1,NoStorage=5,}",
  [53059] = "{id=53059,NameZh='破损的鳞',Icon='item_52315',Type=160,MaxNum=99999,SellPrice=10,Desc='一片破损不知是什么动物身上的鳞片，收藏家皮克西正在收集这种物品，作为收藏品，他需要[c][ff7f00]20[-][/c]个鳞片充实他的库存。通过击杀邪骸浪人·村正获得。',NoSale=1,NoStorage=5,}",
  [53060] = "{id=53060,NameZh='不知名的印记',Type=160,MaxNum=99999,SellPrice=10,Desc='神秘的印记，有着微弱的魔力流动，收藏家皮克西正在收集这种物品，作为收藏品，他需要[c][ff7f00]20[-][/c]个印记充实他的库存。通过击杀邪骸浪人·鬼丸国纲获得。',NoSale=1,NoStorage=5,}",
  [53061] = "{id=53061,NameZh='神秘的眼泪',Icon='item_52408',Type=160,MaxNum=99999,SellPrice=10,Desc='一滴眼泪，在魔力的禁锢下保持着水滴形态，收藏家皮克西正在收集这种物品，作为收藏品，他需要[c][ff7f00]15[-][/c]个眼泪充实他的库存。通过击杀邪骸浪人·十握剑获得。',NoSale=1,NoStorage=5,}",
  [53062] = "{id=53062,NameZh='传说中的勇气',Icon='27',Type=160,MaxNum=99999,SellPrice=10,Desc='一种代表勇气的勋章，出处已经不可考，收藏家皮克西正在收集这种物品，他需要[c][ff7f00]20[-][/c]个。通过击杀邪骸浪人·村雨丸获得。',NoSale=1,NoStorage=5,}",
  [53063] = "{id=53063,NameZh='沾有血渍的权杖',Icon='item_40639',Type=160,MaxNum=99999,SellPrice=10,Desc='一截沾满血渍的权杖，可见它经历过何等惨烈的战斗。收藏家沃斯曼正在收集这种物品，他需要[c][ff7f00]20[-][/c]个权杖才能修复完好。通过击杀裘卡·权杖获得。',NoSale=1,NoStorage=5,}",
  [53064] = "{id=53064,NameZh='沾有污渍的硬币',Icon='item_task_22',Type=160,MaxNum=99999,SellPrice=10,Desc='一枚脏兮兮的硬币，收藏家沃斯曼正在收集这种物品，他需要[c][ff7f00]30[-][/c]个硬币研究这些硬币的来历。通过击杀裘卡·星币获得。',NoSale=1,NoStorage=5,}",
  [53065] = "{id=53065,NameZh='破损的金杯',Icon='item_12341',Type=160,MaxNum=99999,SellPrice=10,Desc='稀少而华美的金杯，可惜已经有所损坏，收藏家沃斯曼正在收集这种物品，他需要[c][ff7f00]20[-][/c]个才能修复这个金杯。通过击杀裘卡·圣杯获得。',NoSale=1,NoStorage=5,}",
  [53066] = "{id=53066,NameZh='断裂的剑身',Icon='item_40314',Type=160,MaxNum=99999,SellPrice=10,Desc='锋利无比的剑身已经从剑柄出断开，收藏家沃斯曼正在收集这种物品，他需要[c][ff7f00]30[-][/c]个才能修复这把断剑。通过击杀裘卡·宝剑获得。',NoSale=1,NoStorage=5,}",
  [53067] = "{id=53067,NameZh='破碎的四叶草',Icon='item_52302',Type=160,MaxNum=99999,SellPrice=10,Desc='象征幸福的四叶草已经破碎了，收藏家霍尔兹正在收集这种物品，他需要[c][ff7f00]40[-][/c]个四叶草用来研究。通过击杀艾琳娜丝获得。',NoSale=1,NoStorage=5,}",
  [53068] = "{id=53068,NameZh='入团日记残页',Icon='item_12004',Type=160,MaxNum=99999,SellPrice=10,Desc='某位骑士的入团日记中的残页，收藏家霍尔兹正在收集这种物品，他需要[c][ff7f00]40[-][/c]个残页才能得到整个日记。通过击杀亚米拉获得。',NoSale=1,NoStorage=5,}",
  [53069] = "{id=53069,NameZh='神秘的染料',Icon='item_12104',Type=160,MaxNum=99999,SellPrice=10,Desc='不知出处的染料，收藏家霍尔兹正在收集这种物品，他需要[c][ff7f00]40[-][/c]个染料才能研究出出处。通过击杀苏米娜获得。',NoSale=1,NoStorage=5,}",
  [53070] = "{id=53070,NameZh='神秘的徽章碎片',Icon='item_52319',Type=160,MaxNum=99999,SellPrice=10,Desc='一种华美的徽章，但现在已经四分五裂，收藏家霍尔兹正在收集这种物品，他需要[c][ff7f00]40[-][/c]个徽章碎片修复。通过击杀纳西·艾思丽获得。',NoSale=1,NoStorage=5,}",
  [53071] = "{id=53071,NameZh='破碎的灵魂印记',Icon='item_task_07',Type=160,MaxNum=99999,SellPrice=10,Desc='灵魂印记已经被某种力量击碎，收藏家格卡莱斯正在收集这种物品，他需要[c][ff7f00]40[-][/c]个灵魂印记用来研究。通过击杀疯剑士·艾里维奇获得。',NoSale=1,NoStorage=5,}",
  [53072] = "{id=53072,NameZh='看不清楚的情书',Icon='item_task_34',Type=160,MaxNum=99999,SellPrice=10,Desc='字迹模糊的残页，上面写着一段段情话，收藏家格卡莱斯正在收集这种物品，他需要[c][ff7f00]30[-][/c]个用来研究和收藏。通过击杀柯雷罗·狂热之弓获得。',NoSale=1,NoStorage=5,}",
  [53073] = "{id=53073,NameZh='土黄色的箭',Icon='item_task_35',Type=160,MaxNum=99999,SellPrice=10,Desc='锋利的弓箭，来历有待考证，收藏家格卡莱斯正在收集这种物品，他需要[c][ff7f00]30[-][/c]个用来研究和收藏。通过击杀金色箭矢获得。',NoSale=1,NoStorage=5,}",
  [53074] = "{id=53074,NameZh='破烂的弓',Icon='item_41217',Type=160,MaxNum=99999,SellPrice=10,Desc='从材质上看，是一把造价昂贵的弓，可惜已经损坏了，收藏家格卡莱斯正在收集这种物品，他需要[c][ff7f00]35[-][/c]个才能修复好这把弓。通过击杀艾克林·魔箭矢获得。',NoSale=1,NoStorage=5,}",
  [53075] = "{id=53075,NameZh='恶魔微笑',Icon='item_60009',Type=160,MaxNum=99999,SellPrice=10,Desc='一个神奇的宝珠，拥有将一切心智不坚定的人诱惑并且堕落黑暗的魔力，古城大厅的收藏家摩尔古正在寻找这个物品。通过击杀巨大的恶魔波利获得。',NoSale=1,NoStorage=5,}",
  [53076] = "{id=53076,NameZh='莫特利之剑',Icon='item_40736',Type=160,MaxNum=99999,SellPrice=10,Desc='传说勇者莫特利所持有的武器，跟随莫特利挑战过诸多魔物，古城大厅的收藏家摩尔古正在寻找这个物品。通过击杀凯美拉获得。',NoSale=1,NoStorage=5,}",
  [53077] = "{id=53077,NameZh='血咒',Icon='dark_004',Type=160,MaxNum=99999,SellPrice=10,Desc='如同血色一般，充满诅咒力量的宝石，是德古拉男爵最为喜爱的宝石。古城大厅的收藏家摩尔古正在寻找这个物品。通过击杀德古拉男爵获得。',NoSale=1,NoStorage=5,}",
  [53078] = "{id=53078,NameZh='天国之门',Icon='item_task_12',Type=160,MaxNum=99999,SellPrice=10,Desc='传说看守奥丁神殿之门的兰特克力斯所拥有，奥丁赐予他自由来往神殿与俗世的传送石，古城大厅的收藏家摩尔古正在寻找这个物品。通过击杀兰特克力斯获得。',NoSale=1,NoStorage=5,}",
  [53079] = "{id=53079,NameZh='利维坦的沙漏',Icon='item_task_49',Type=160,MaxNum=99999,SellPrice=10,Desc='利维坦是古今著名的大海盗，他利用一个别致的金沙漏来打开时空之门。轻松的穿梭回过去，解决改变未来将出现的麻烦。一天，利维坦的船在海上遇到风暴，嫉妒他的副手乘乱砸破了他的金沙漏，利维坦瞬间化作一缕金沙与沙漏中的沙随风暴飘散在无边无际的大海之中。后来陷害他的副手死于非命，但也没人再见过位大名鼎鼎的海盗。钟楼2F的钟表迷库马斯坦正在寻找这个物品。通过击杀时间管理者·过去获得。',NoSale=1,NoStorage=5,}",
  [53080] = "{id=53080,NameZh='明日水晶',Icon='item_task_46',Type=160,MaxNum=99999,SellPrice=10,Desc='艾尔帕兰城内曾有位通晓未来的魔女，通常是神秘地地罩在面网里，不示人以真面目，脸面向的方向 ，手里永远拿一颗用丝巾包住的水晶球，但是都不展开，仿佛喻世着未来不可知的神秘，没有人知道她叫什么，问她从哪里来，她便答“遥远的未来”。钟楼2F的钟表迷库马斯坦正在寻找这个物品。通过击杀时间管理者·未来获得。',NoSale=1,NoStorage=5,}",
  [53081] = "{id=53081,NameZh='马莱的指针',Icon='item_task_47',Type=160,MaxNum=99999,SellPrice=10,Desc='马莱不仅是位天才魔法师，还是很杰出的钟表师。凭着才华与天赋做出了一只能时间旅行的钟，只要将时针向前推或向后推，便可穿梭回时钟上的时间。可马莱的妻子贪得无厌，想永葆自身青春美貌，折断了马莱钟上的所有指针，于是这位天才魔法师与他的妻子永远的被困在了一个不再有时间流逝的封闭时空内。钟楼2F的钟表迷库马斯坦正在寻找这个物品。通过击杀时间管理者·今日获得。',NoSale=1,NoStorage=5,}",
  [53082] = "{id=53082,NameZh='魔女印记·年',Type=160,MaxNum=99999,SellPrice=100,Desc='黑魔女体内的关于时间法则的力量印记，蕴含部分“年”的力量，是所有时间研究者的无价之宝。时间学者诺德温正在寻找[c][ff7f00]10[-][/c]个这种印记。通过击杀时间魔女·世纪获得。',NoSale=1,NoStorage=5,}",
  [53083] = "{id=53083,NameZh='魔女印记·月',Type=160,MaxNum=99999,SellPrice=100,Desc='黑魔女体内的关于时间法则的力量印记，蕴含部分“月”的力量，是所有时间研究者的无价之宝。时间学者诺德温正在寻找[c][ff7f00]10[-][/c]个这种印记。通过击杀时间魔女·季度获得。',NoSale=1,NoStorage=5,}",
  [53084] = "{id=53084,NameZh='魔女印记·日',Type=160,MaxNum=99999,SellPrice=100,Desc='黑魔女体内的关于时间法则的力量印记，蕴含部分“日”的力量，是所有时间研究者的无价之宝。时间学者诺德温正在寻找[c][ff7f00]10[-][/c]个这种印记。通过击杀时间魔女·日耀获得。',NoSale=1,NoStorage=5,}",
  [53085] = "{id=53085,NameZh='魔女印记·时',Type=160,MaxNum=99999,SellPrice=100,Desc='黑魔女体内的关于时间法则的力量印记，蕴含部分“时”的力量，是所有时间研究者的无价之宝。时间学者诺德温正在寻找[c][ff7f00]10[-][/c]个这种印记。通过击杀时间魔女·时光获得。',NoSale=1,NoStorage=5,}",
  [53086] = "{id=53086,NameZh='魔女印记·分',Type=160,MaxNum=99999,SellPrice=100,Desc='黑魔女体内的关于时间法则的力量印记，蕴含部分“分”的力量，是所有时间研究者的无价之宝。时间学者诺德温正在寻找[c][ff7f00]10[-][/c]个这种印记。通过击杀时间魔女·时刻获得。',NoSale=1,NoStorage=5,}",
  [53087] = "{id=53087,NameZh='魔女印记·秒',Type=160,MaxNum=99999,SellPrice=100,Desc='黑魔女体内的关于时间法则的力量印记，蕴含部分“秒”的力量，是所有时间研究者的无价之宝。时间学者诺德温正在寻找[c][ff7f00]10[-][/c]个这种印记。通过击杀时间魔女·瞬间获得。',NoSale=1,NoStorage=5,}",
  [53088] = "{id=53088,NameZh='密码盘碎片',Icon='item_62001',Type=160,MaxNum=99999,SellPrice=100,Desc='刻满了符文般深奥难解的字符的金色碎片，边缘有着光滑的曲线，由此判定，这是某件圆盘的碎片，异世界调查员纳鲁正在寻找[c][ff7f00]12[-][/c]个这种碎片。通过击杀阴影之书获得。',NoSale=1,NoStorage=5,}",
  [53089] = "{id=53089,NameZh='碎骨',Icon='item_task_30',Type=160,MaxNum=99999,SellPrice=100,Desc='材质上是人骨的碎片，根据骨骼的坚硬程度与纹理分布，应该属于人类的头骨碎片。异世界调查员纳鲁正在寻找[c][ff7f00]18[-][/c]个这种碎片。通过击杀妖僧获得。',NoSale=1,NoStorage=5,}",
  [53090] = "{id=53090,NameZh='石质碎片',Icon='item_52508',Type=160,MaxNum=99999,SellPrice=100,Desc='某种石质的碎片，上面刻满了神秘的阵符，这些符文似乎是某个炼金阵的一部分。异世界调查员纳鲁正在寻找[c][ff7f00]10[-][/c]个这种碎片。通过击杀不死抄写员获得。',NoSale=1,NoStorage=5,}",
  [53091] = "{id=53091,NameZh='蓝色布料',Icon='item_5128',Type=160,MaxNum=99999,SellPrice=100,Desc='上面印着黄色星星的蓝色布条，这些星星似乎代表着某种深邃的含义。异世界调查员纳鲁正在寻找[c][ff7f00]15[-][/c]个这种布料。通过击杀灰袍巫师获得。',NoSale=1,NoStorage=5,}",
  [53092] = "{id=53092,NameZh='黄金刀刃',Icon='item_task_48',Type=160,MaxNum=99999,SellPrice=100,Desc='似乎由昂贵的黄金所铸造而成的利刃，但是延伸之处有明显断痕，也许它不仅仅是把利刃。异世界调查员纳鲁正在寻找[c][ff7f00]20[-][/c]个这种碎片。通过击杀野兽之王获得。',NoSale=1,NoStorage=5,}",
  [53093] = "{id=53093,NameZh='时之流沙',Icon='item_task_51',Type=48,MaxNum=99999,SellPrice=100,Desc='一瓶混着金箔的绵密白色细沙，在光的折射下发出闪闪金光。瓶体上贴着贝利兄弟的标签，是开启【时空罪恶】任务的重要道具。',Level=90,NoStorage=5,}",
  [53094] = "{id=53094,NameZh='艾波娜的旧相片',Icon='item_147',Type=160,MaxNum=99999,SellPrice=100,Desc='相片上艾波娜幸福的拥着一个丑陋的大块头，那便是时间魔物西罗诺。艾波娜丝毫不在意他的外表，眼神中满是爱意，嘴角微微的扬着，斜着眼看着西罗诺。',NoSale=1,NoStorage=5,}",
  [53095] = "{id=53095,NameZh='守护者勋章',Icon='item_47026',Type=160,MaxNum=99999,SellPrice=1,Desc='对时钟守护者有过帮助的冒险者才能得到的奖章，有此勋章的人会受到所有时钟守护者成员的尊重。',NoStorage=5,}",
  [53096] = "{id=53096,NameZh='时空碎片',Icon='16',Type=160,MaxNum=99999,SellPrice=1,Desc='对时钟守护者有过帮助的冒险者才能得到的特殊奖赏，收集到[c][ff7f00]20[-][/c]个碎片即可到默斯曼·岁月处换取高额奖励哦。',NoStorage=5,}",
  [53097] = "{id=53097,NameZh='金蛇之瞳',Icon='item_7337',Type=62,MaxNum=99999,SellPrice=100,Desc='传说中的金蛇之瞳可是历来弑蛇英雄的象征！珍奇瑰宝！冒险者完成该区域主线任务可解锁艾尔帕兰微笑小姐处珍贵的武器外观兑换权限。',NoSale=1,NoStorage=5,}",
  [53098] = "{id=53098,NameZh='没有装饰的铜镜',Icon='item_52316',Type=160,MaxNum=99999,SellPrice=10,Desc='奥莉薇亚有着一双灵气十足的大眼睛，麦斯是她的青梅竹马，一天麦斯带奥莉薇亚出城看星星，却遇到了雷雨天气，马车和人一同翻进了冰冷的湖水，夺走了麦斯年轻的生命，而奥莉薇亚却失明了。当她在医院醒来时，牧师告诉她运气很好，刚好有适合的眼睛能取代她失明的双目，在恢复视力的那天，牧师给奥莉薇亚拿来了一盏没有装饰的铜镜，望向镜中的自己时，奥莉维亚的眼泪却止不住的流了下来。如果你拥有这个物品，就去把它交给玩具工厂2F的奥莉薇亚吧。通过击杀魔灵娃娃·鸢尾获得。',NoSale=1,NoStorage=5,}",
  [53099] = "{id=53099,NameZh='羊皮箭筒',Icon='item_47020',Type=160,MaxNum=99999,SellPrice=10,Desc='蕾拉和她年仅六岁的妹妹正在参加婶婶的葬礼，在葬礼上，蕾拉对一个从未谋面的英俊的弓箭手一见钟情。蕾拉天生性格内向，并没有上前搭讪说话。年轻男子在葬礼上落下了一个羊皮箭筒，蕾拉看见后悄悄的收了起来。葬礼结束后，蕾拉借着箭筒的契机和城中的人打听这位年轻的弓箭手，可是怎么打听也打听不到男子的下落。一个月后，蕾拉的妹妹去世了，在妹妹的葬礼上她终于见到了那个让她魂牵梦萦的弓箭手。当蕾拉将箭筒还给男子时，蕾拉说：“抱歉，我很小心的收着，但还是弄丢了一只。”如果你拥有这个物品，就去把它交给玩具工厂2F的蕾拉吧。通过击杀魔灵娃娃·紫罗兰获得。',NoSale=1,NoStorage=5,}",
  [53100] = "{id=53100,NameZh='冰晶玫瑰',Icon='item_52509',Type=160,MaxNum=99999,SellPrice=10,Desc='妮可儿在一户富裕人家长大，妈妈却独宠哥哥十分排挤她，不仅虐待她，还让她为家中做许多苦力。倒是村口的一个穷苦妇人对她格外亲切，时常偷偷塞些小樱桃给她吃。一天，妇人交给妮可儿一朵冰晶玫瑰，说这朵玫瑰里住着雪精灵能满足人的一个愿望，妇人让妮可儿用这朵花许愿永远幸福。妮可儿因为回家晚了，被妈妈一顿毒打，泪水滴在了玫瑰上，一个雪精灵真的从花蕊中飞了出来，妮可儿忘记了妇人的叮嘱，仇恨已充斥了她的内心，她说她希望她的家人全死光。第二天清晨，妮可儿醒了，发现爸爸，妈妈，哥哥都在，妮可儿愣了楞，突然大哭起来，跑去问雪精灵可不可以收回愿望，可雪精灵说一切都太晚了。昨日妇人给的樱桃散落了一地，染红了白雪。如果你拥有这个物品，就去把它交给玩具工厂2F的妮可儿吧。通过击杀魔灵娃娃·洛丽玛丝获得。',NoSale=1,NoStorage=5,}",
  [53101] = "{id=53101,NameZh='金线兔玩偶·碎片',Icon='item_12343',Type=160,MaxNum=99999,SellPrice=100,Desc='唐纳的母亲是个穷苦的纺织工，随着圣诞节即将到来，唐纳要求母亲给自己买一个兔子玩偶。橱窗中的兔子玩偶十分昂贵，母亲并没有那么多钱，就告诉唐纳，她会给唐纳手工做一个同样可爱的玩偶。可唐纳就是想要商店里的那只，哭闹不止。母亲没有办法，母亲只好去偷隔壁商贩家的东西卖，不巧被商贩发现了。商贩没有将钱要回来，而是剁下了母亲一只手臂。平安夜的那天晚上，唐纳如愿以偿的得到了兔子玩偶，可他不知道母亲再也不能纺织了。玩具工厂1F的玩具设计师塔伦的学徒塞缪妮正在寻找[c][ff7f00]10[-][/c]个这种碎片。通过击杀坎卜斯的礼物·自私获得。',NoSale=1,NoStorage=5,}",
  [53102] = "{id=53102,NameZh='苦涩的糖豆·碎片',Icon='item_12121',Type=160,MaxNum=99999,SellPrice=100,Desc='格兰迪是领主家的小童工，领主很喜欢这个机灵的小家伙。每次格兰迪做完工，领主都会奖励格兰迪一把甜甜的糖豆。可格兰迪觉得做工太辛苦了，他宁可坐着都能得到奖励，于是他就派自己的影子去帮他做工。他的影子和格兰迪一模一样，连领主都没看出分别来。日复一日，影子渐渐取代了格兰迪的位置。那天，影子在交给领主给格兰迪的奖励中，偷偷的混入了一颗抹着毒药的糖豆。玩具工厂1F的玩具设计师塔伦的学徒塞缪妮正在寻找[c][ff7f00]10[-][/c]个这种碎片。通过击杀坎卜斯的礼物·懒惰获得。',NoSale=1,NoStorage=5,}",
  [53103] = "{id=53103,NameZh='旋转红鞋·碎片',Icon='item_43523',Type=160,MaxNum=99999,SellPrice=100,Desc='一个叫卡伦的农村女孩在她母亲死后被一个富有的老妇人收养了。从前，卡伦只有破旧的木鞋，可现在养母给她买了一双高级定制的红舞鞋。卡伦经常不顾礼数穿着红舞鞋去严肃的教堂，甚至，当她的养母生病时，她还穿着红舞鞋去参加派对。一天，一位教堂门口的老太太对她说了些奇怪的话后，卡伦便脱不下她的舞鞋，舞鞋自己疯狂的跳动，日日夜夜，晴雨不分，永不停歇。卡伦只好找到了一个刽子手，祈求他砍掉自己的脚。刽子手砍下了卡伦的脚，但是舞鞋依然在跳动，带着卡伦的脚消失在浓浓的夜色中。玩具工厂1F的玩具设计师塔伦的学徒塞缪妮正在寻找[c][ff7f00]10[-][/c]个这种碎片。通过击杀坎卜斯的礼物·虚荣获得。',NoSale=1,NoStorage=5,}",
  [53104] = "{id=53104,NameZh='恶魔金沙·碎片',Icon='item_52404',Type=160,MaxNum=99999,SellPrice=100,Desc='马克的爷爷卧床不起，病情严重，他绝望地唤出了恶魔，说若能使爷爷病愈，他便献给恶魔一千克金沙。恶魔用法术使马克的爷爷康复了。爷爷病好后，马克没用真正的金沙来酬谢恶魔，而是用黄沙代替，放在祭坛上烧，并念念有词的说：“恶魔啊恶魔，我已经履行了我的承诺。”恶魔便在晚上托梦告诉小马克，要他到海边去，说在那里可以找到真正的金沙。马克醒来后，高兴极了，直往海边跑去。结果在那里遇到了凶恶的海盗，马克被他们抓走并且卖掉，而他的售卖价格是…一千克金沙。玩具工厂1F的玩具设计师塔伦的学徒塞缪妮正在寻找[c][ff7f00]10[-][/c]个这种碎片。通过击杀坎卜斯的礼物·欺骗获得。',NoSale=1,NoStorage=5,}",
  [53105] = "{id=53105,NameZh='说话的鱼·碎片',Icon='item_550511',Type=160,MaxNum=99999,SellPrice=100,Desc='托尼跟着哥哥出海打渔，织了一张和桌子一般大的小网。出海一天只捕到了一条鱼，垂头丧气地回到了家。回家将鱼放进水中，鱼居然开口说了话。鱼对小托尼说：\"把网织得越大，捕到的鱼就越多。\" 托尼听了鱼的话，就认真地在家织网。哥哥劝托尼不要那么贪心，但托尼不理会。巨网织好后，小托尼就带着它和哥哥出海，花了好大的功夫才把巨网撒入大海。托尼想，这一定可以装满一船，想着想着，他乐得笑出了声。 但当托尼准备收网了，一拉网，觉得好沉好沉，连船带人一起翻入了深海之中。哥哥一人回到家，发现家中那条会说话的鱼也不见了。玩具工厂1F的玩具设计师塔伦的学徒科林正在寻找[c][ff7f00]10[-][/c]个这种碎片。通过击杀坎卜斯的礼物·贪婪获得。',NoSale=1,NoStorage=5,}",
  [53106] = "{id=53106,NameZh='冰冻的心脏·碎片',Icon='item_52203',Type=160,MaxNum=99999,SellPrice=100,Desc='南希是富有人家的孩子，他有一个属于自己的小花园。圣诞时，南希的父母给南希布置了一颗完美的圣诞树。别家的孩子都想来这里看一看南希的圣诞树，可南希太吝啬了，他不愿放任何人进自己的小花园。于是，当春天笼罩大地，唯独南希的花园还是冬天的天气，温暖的大地无法融化南希冷冰冰的心。南希抱着光秃秃毫无装饰的圣诞树，永远的睡在了雪里。多年后，人们从树底发现了一颗被冰冻的心脏。玩具工厂1F的玩具设计师塔伦的学徒科林正在寻找[c][ff7f00]10[-][/c]个这种碎片。通过击杀坎卜斯的礼物·吝啬获得。',NoSale=1,NoStorage=5,}",
  [53107] = "{id=53107,NameZh='小鬼四叶草·碎片',Icon='item_52302',Type=160,MaxNum=99999,SellPrice=100,Desc='艾玛是公爵的女儿，傲慢且盛气凌人。人们都爱围绕着她，因为公爵宠溺小艾玛。所有好吃的好玩的都属于她一人。艾玛想要一片四叶草，但这在市面上可买不到。于是公爵便命人将附近的草丛全部铲除，也要找到那片四叶草。住在草里的精灵，告诉艾玛这一带没有四叶草，并祈求她不要毁了他们的住所。艾玛不为所动，还是铲平了附近的所有草丛，但这惊扰了住在草丛中的小鬼。小鬼问艾玛是不是要四叶草，艾玛点头。于是小鬼取走了艾玛的舌头，双眼和头发，并给了艾玛一片四叶草。玩具工厂1F的玩具设计师塔伦的学徒科林正在寻找[c][ff7f00]10[-][/c]个这种碎片。通过击杀坎卜斯的礼物·傲慢获得。',NoSale=1,NoStorage=5,}",
  [53108] = "{id=53108,NameZh='托尼的眼球·碎片',Icon='dark_001',Type=160,MaxNum=99999,SellPrice=100,Desc='托尼和托塔是一对孪生兄弟。但哥哥托尼总是嫉妒父母对弟弟托塔的照顾。一天托尼遇到一只金鸟，金鸟告诉他，可以满足他任何一个愿望，但前提是他的弟弟托塔会得到双倍的报酬。托尼起先高兴不已。但他仔细一想：如果他想要一座糖果屋，弟弟就会有两座。如果他想要一车玩具，弟弟就会有两车。想来想去，托尼不知道该提什么要求才好，他实在不甘心又被弟弟白占了便宜。最后，托尼一咬牙，对金鸟说：“哎，你挖去我的一只眼珠吧。”玩具工厂1F的玩具设计师塔伦的学徒科林正在寻找[c][ff7f00]10[-][/c]个这种碎片。通过击杀坎卜斯的礼物·嫉妒获得。',NoSale=1,NoStorage=5,}",
  [53109] = "{id=53109,NameZh='陈旧的告示·碎片',Icon='item_5128',Type=160,MaxNum=99999,SellPrice=100,Desc='从布袋熊的布袋中滑出一封陈旧的告示，上面登记着十年前的一天，圣诞村的宝石商人贝尔摩被洗劫的新闻。贝尔摩身中数箭身亡，当时的抢匪一共有五个人，查理、曼逊、丹、里克和卡尔。因四人指认是腹语师查理杀了贝尔摩，所以腹语师查理被判绞刑，在平安夜的前一天被处决。玩具工厂2F的腹语师梅丽莎正在寻找[c][ff7f00]10[-][/c]个这种碎片。通过击杀布袋熊获得。',NoSale=1,NoStorage=5,}",
  [53110] = "{id=53110,NameZh='波利玩偶·碎片',Icon='item_12342',Type=160,MaxNum=99999,SellPrice=100,Desc='打开发条熊背后的暗门，里面藏着一只波利玩偶。这个玩偶属于死去的贝尔摩先生的小女儿。这个可怜的小女孩，那天正好是她的生日，当时受到了过多的惊吓，只知道重复着一句话：“他们中的首领把我和爸爸绑了起来，杀死我爸爸的人和卡尔多拿了两颗钻石”。玩具工厂2F的腹语师梅丽莎正在寻找[c][ff7f00]10[-][/c]个这种碎片。通过击杀布袋熊获得。',NoSale=1,NoStorage=5,}",
  [53111] = "{id=53111,NameZh='丹的密信·碎片',Icon='item_task_34',Type=160,MaxNum=99999,SellPrice=100,Desc='撕开毛绒熊的身体，从里面露出来一封被封住的信。信上写着：“首领，我与你的妻子还有卡尔可是手足关系，切记不可相信里克这个人，虽然他常拿好处巴结你，但毕竟不是一家人。我看得出你也不是很相信他，等风波过去了，我就和您碰头。丹。”玩具工厂2F的腹语师梅丽莎正在寻找[c][ff7f00]10[-][/c]个这种碎片。通过击杀布袋熊获得。',NoSale=1,NoStorage=5,}",
  [53112] = "{id=53112,NameZh='小女儿的画·碎片',Icon='item_555022',Type=160,MaxNum=99999,SellPrice=100,Desc='剥去纽扣熊的纽扣，从熊身体里探出来的是一张贝尔摩小女儿的画。上面有一行模糊的字：首领大人，我给您寄来了贝尔摩小女儿的画。我理解您现在一定不好受，因为您曾是这小姑娘的美术老师。我也理解您为了袒护真正凶手不得已的作为，毕竟那是您最要好的兄弟。玩具工厂2F的腹语师梅丽莎正在寻找[c][ff7f00]10[-][/c]个这种碎片。通过击杀布袋熊获得。',NoSale=1,NoStorage=5,}",
  [53113] = "{id=53113,NameZh='生锈的箭·碎片',Icon='item_12502',Type=160,MaxNum=99999,SellPrice=100,Desc='划开皮革熊的皮革，能从里面取出一只折断的箭。箭上虽然已经锈迹斑斑，但依旧能看出它当年的威力应该不小。这正是十年前杀死贝尔摩先生的箭。从贝尔摩身上拔下好几根这样的断箭，可以看出，这都是由同一把弓射出去的。玩具工厂2F的腹语师梅丽莎正在寻找[c][ff7f00]10[-][/c]个这种碎片。通过击杀布袋熊获得。',NoSale=1,NoStorage=5,}",
  [53114] = "{id=53114,NameZh='有钻石的肩包·碎片',Icon='item_47031',Type=160,MaxNum=99999,SellPrice=100,Desc='割开牵线熊的绳子，从牵线熊的肚中露出一只咖啡色的小包。这只包乍一看平淡无奇，却重的可疑。实际上里面有四个装着钻石的小布袋，每个小布袋上都缝着一个人名。首领的布袋和里克的布袋中只有一颗钻石，其余两人的布袋中则装着两颗钻石。玩具工厂2F的腹语师梅丽莎正在寻找[c][ff7f00]10[-][/c]个这种碎片。通过击杀布袋熊获得。',NoSale=1,NoStorage=5,}",
  [53115] = "{id=53115,NameZh='挚友同行BUFF',Icon='item_47031',Type=160,MaxNum=1,SellPrice=100,Desc='两人组队情况下MaxHp+3000,MaxSp+500,Atk+200,MAtk+200,无法叠加',NoSale=1,NoStorage=5,}",
  [53116] = "{id=53116,NameZh='破损的剑',Icon='item_40340',Type=160,MaxNum=99999,SellPrice=10,Desc='你的剑是为了什么而挥动呢？导师的话语在诺法的脑海中回荡。出身在普隆德拉的诺法从小在皇家士兵训练场边长大，当年幼的他第一次握起长剑时，他便被深深吸引住了。对于当时的他来说，长剑是骑士帅气的象征。当熔岩洞窟魔物暴乱时，与伙伴一同深入洞窟阻止灾难的诺法，陡然领悟到，其实长剑的背后是守护之心，你是为了什么而挥剑呢？导师的声音再次浮现，用尽气力的诺法用这把剑支撑起自己，我的剑为了拯救无辜的生命而挥动，为了守护同伴的笑容而挥动。牺牲自己也没关系么？没关系，我认为很值得。诺法微笑着闭上双眼。熔岩洞窟1F的追思者厄尔特正在寻找[c][ff7f00]10[-][/c]个这种物品，达到98级的冒险者可以前往兑换。通过击杀爆炎小恶魔·收藏家获得。',NoSale=1,NoStorage=5,}",
  [53117] = "{id=53117,NameZh='破损的盾',Icon='item_42536',Type=160,MaxNum=99999,SellPrice=10,Desc='诺法转职成骑士的那天起，他便背上了这块沉重的盾牌，他的导师说，你手上的盾牌不是为了保护你而存在的，诺法当时并不理解话中的含义，直到他离开普隆德拉，与三位性格迥异又意气相投的队友组成冒险小队。每当大家遇到危险，这面盾牌便是守护伙伴的坚固屏障，在朱诺的熔洞暴乱中，这面盾牌又化作为朱诺阻挡灾祸的壁垒。当诺法的心脏在熔岩洞窟停止跳动的那一刻，他依然紧握盾牌屹立不倒，身后是同样燃尽生命的伙伴，他们的嘴角带着安心的微笑。熔岩洞窟1F的追思者厄尔特正在寻找[c][ff7f00]10[-][/c]个这种物品，达到98级的冒险者可以前往兑换。通过击杀爆炎小恶魔·捣蛋鬼获得。',NoSale=1,NoStorage=5,}",
  [53118] = "{id=53118,NameZh='破损的弓',Icon='item_41234',Type=160,MaxNum=99999,SellPrice=10,Desc='这把斐扬古木制作的弓上，沁着淡淡的红色。即使岁月流逝它依然富有韧性，看得出来它的主人十分细心并且非常爱护它，但如今这把弓只剩下光秃秃的弓身，再没有谁会抚动它的心弦。无人知晓曾有一位名为桃丽的少女紧握着它射出了希望与勇气，如今故人已消逝，唯有桃丽之弓无言的诉说过去的故事。熔岩洞窟1F的追思者厄尔特正在寻找[c][ff7f00]10[-][/c]个这种物品，达到98级的冒险者可以前往兑换。通过击杀爆炎小恶魔·暴力狂获得。',NoSale=1,NoStorage=5,}",
  [53119] = "{id=53119,NameZh='破损的箭矢',Icon='item_12502',Type=160,MaxNum=99999,SellPrice=10,Desc='出生于斐扬的桃丽只是一个相貌平平的农家少女，直到某次她展显出非凡的射手天赋。成为猎人离开家乡游历的桃丽，在途中遇到了可靠的三个伙伴，行侠仗义的四人冒险小队就此诞生，途径朱诺的他们遭遇了熔岩洞窟的魔物暴动，这里生灵涂炭的惨象让桃丽想起了自己的家乡——斐扬曾经的悲剧。善良的桃丽决心与伙伴一同拯救朱诺。箭矢百步穿杨，不断狙击着狂化的魔物首领，桃丽的双手慢慢被磨出血泡，当四人踏入熔岩洞窟的深处，桃丽挽弓搭上这最后一只箭。弓箭之神大人，我恳求您让我射出神箭，封印熔岩洞窟的戾气与怨恨。少女闭眼祈祷，神箭脱手而出。桃丽成功了，但那双爱笑的眼眸却永远不会再睁开了。熔岩洞窟1F的追思者厄尔特正在寻找[c][ff7f00]10[-][/c]个这种物品，达到98级的冒险者可以前往兑换。通过击杀爆炎小恶魔·小讨厌获得。',NoSale=1,NoStorage=5,}",
  [53120] = "{id=53120,NameZh='破损的斧头',Icon='item_41845',Type=160,MaxNum=99999,SellPrice=10,Desc='你为什么喜欢斧子？曾有人这样问过瓦西里。他笑着回答。因为它很像我，一板一眼，劈下去就劈下去了，大开大合从不花里胡哨。梦罗克的沙漠男儿从不和人玩虚的。当瓦西里与伙伴们决定帮助朱诺时，他根本没想那么多，只是看到魔物在伤害无辜的人，只是看到有人需要我们的帮助，手中的斧子自己就动了起来呢。见到这把斧子，一下就能明白：这家伙的主人是个了不起的战士。熔岩洞窟1F的追思者卡嘉正在寻找[c][ff7f00]10[-][/c]个这种物品，达到98级的冒险者可以前往兑换。通过击杀爆炎小恶魔·臭脾气获得。',NoSale=1,NoStorage=5,}",
  [53121] = "{id=53121,NameZh='破损的头冠',Icon='item_45220',Type=160,MaxNum=99999,SellPrice=10,Desc='梦罗克出身的瓦西里从小就是孩子王，小时候，他的头上戴着风滚草编织的头环，多年后，取而代之的是坚硬的金属头冠。但在瓦西里骨子里，自己仍是当年那个路见不平出手相助的孩子王，作为四人冒险小队的老大，他与伙伴义无反顾的加入帮助朱诺击退魔物暴动的行动中，直到牺牲生命封住洞窟戾气的那刻，他仍笑得像个初心不改的顽童。熔岩洞窟1F的追思者卡嘉正在寻找[c][ff7f00]10[-][/c]个这种物品，达到98级的冒险者可以前往兑换。通过击杀爆炎小恶魔·顽皮蛋获得。',NoSale=1,NoStorage=5,}",
  [53122] = "{id=53122,NameZh='破损的杖',Icon='item_40613',Type=160,MaxNum=99999,SellPrice=10,Desc='作为一百年来首个被魔法学院提前录取的学生，斯曼玲·黎风天生就注定成为一位传奇女巫师，但出乎所有人意料的是，在她十九岁那年，她不顾导师的反对，与新的同伴组成了四人冒险小队，离开了养育自己的吉芬，在经过天空之城朱诺时，熔岩洞窟发生了前所未有的魔物暴动，魔物所到之处皆化作火海，冒险小队决定留下帮助朱诺的人们，而斯曼玲的强大魔法成为了压制魔物群的利器，亲眼目睹事件的朱诺老者回忆说，当斯曼玲吟唱魔法时，耀眼的光芒环绕着她，如同传说中的女神，嚣狂的魔物四散溃逃。当四人来到熔岩洞窟深处，斯曼玲的魔力已接近枯竭，少女用尽了最后的力量，封住了使魔物暴戾狂化的次元裂隙，紧握着这根陪伴自己短暂一生的魔杖，她永远安眠在了远离吉芬的异国他乡。熔岩洞窟1F的追思者卡嘉正在寻找[c][ff7f00]10[-][/c]个这种物品，达到98级的冒险者可以前往兑换。通过击杀爆炎小恶魔·撒谎精获得。',NoSale=1,NoStorage=5,}",
  [53123] = "{id=53123,NameZh='破损的典籍',Icon='item_3882',Type=160,MaxNum=99999,SellPrice=10,Desc='每位魔法师都拥有一本记录自己魔法的典籍，斯曼玲·黎风的典籍里除了咒语还有不少日记与涂鸦。第七页“一根筋瓦西里，呆萌妹桃丽，大笨蛋诺法！我的队友真是够了。”第四十页“没想到这帮家伙还挺能干的嘛。诺法这个笨骑士原来也有可靠的一面。”最后一页“谢谢你们，我并不后悔止步于此，笨蛋诺法，我爱…”熔岩洞窟1F的追思者卡嘉正在寻找[c][ff7f00]10[-][/c]个这种物品，达到98级的冒险者可以前往兑换。通过击杀爆炎小恶魔·懒惰虫获得。',NoSale=1,NoStorage=5,}",
  [53124] = "{id=53124,NameZh='鸟蛋碎片',Icon='item_45042',Type=160,MaxNum=99999,SellPrice=10,Desc='很久很久以前，鸟人一族出现了一颗黄金的鸟蛋。当时的鸟人王名为哈利，这颗鸟蛋是由它的王后产下的。一枚黄金的蛋啊，哈利欣喜若狂，这是上天赐予它们一族的天选王位继承人啊。于是它日日夜夜的守着它的王后孵化这颗黄金鸟蛋。时间一天又一天的过去了，没关系，天选继承人和别的鸟人不一样。时间一年又一年的过去了，王后你安心的去吧，我会代替你来孵化我们的王子。终于，哈利的时间走到了尽头，它垂下了它的双眼，安详的伏在黄金鸟蛋上——我会继续等你。艾因布洛克原野的历史学生奥玛正在寻找[c][ff7f00]10[-][/c]个这种物品，达到98级的冒险者可以前往兑换。通过击杀鸟人哈比·守护者获得。',NoSale=1,NoStorage=5,}",
  [53125] = "{id=53125,NameZh='破碎的头盔',Icon='item_45049',Type=160,MaxNum=99999,SellPrice=10,Desc='夜已深了，但在村落一处的木匠们还流着汗做着工。月光朦朦胧胧的洒在地面上，他们借着微弱的月光努力干活。在另一边的地上，整齐的放着好多个已经做好的成品，是木质的头盔。简简单单的的头盔，没有任何的装饰品的头盔，明天勇士们将要戴着它们去寻找黄金鸟蛋的头盔。木匠们不敢马虎，这些勇士们是村落里的希望，不管是那个天选勇士还是其它的年轻人。还差几个，还差几个就可以了，木匠们全然不觉疲惫，每个人的眼睛里都闪着比月光更亮的光芒。艾因布洛克原野的历史学生奥玛正在寻找[c][ff7f00]10[-][/c]个这种物品，达到98级的冒险者可以前往兑换。通过击杀鸟人哈比·拾荒者获得。',NoSale=1,NoStorage=5,}",
  [53126] = "{id=53126,NameZh='破损的刀刃',Icon='item_40715',Type=160,MaxNum=99999,SellPrice=10,Desc='铁匠端详着眼前的那把利刃，这也许是他这辈子做的最好的铁器了。怎么能不好呢？村长送来了镇村之宝，先祖们以前得到的一颗黑曜石，沉稳而又带着光泽的黑曜石一直都是村里的镇邪之宝。而现在，它被镶嵌在了一把利刃之上。而这把利刃将会赐予给天选勇士，而天选勇士将会在之后的祭祀过程中，从村里的年轻人中选出来。或许这样是最好的吧，天选勇士带着这样的利刃一定能将村子带出现在的困境。这样想着，铁匠粗狂的脸上露出了柔和的笑容。艾因布洛克原野的历史学生奥玛正在寻找[c][ff7f00]10[-][/c]个这种物品，达到98级的冒险者可以前往兑换。通过击杀鸟人哈比·寻宝者获得。',NoSale=1,NoStorage=5,}",
  [53127] = "{id=53127,NameZh='图腾陶器碎片',Icon='item_12528',Type=160,MaxNum=99999,SellPrice=10,Desc='在盛大的祭祀及加冕仪式之后，大祭司正在亲手制作一个陶器，回想着当日的场景——兴奋的孩子，祈祷的村民，咏唱的祭司，奋战的勇士和举着黄金鸟蛋满身是伤的天选勇者。从那日开始，村子将不再面对那么多危险，从那日开始，所有人都会在天选勇士的带领下前行。大祭司无法掩藏心中的振奋，他在陶器上刻画下了一幅图腾，祈求着自然会将他预见的一切赐予村落。我将终身侍奉你啊天神，死后我的灵魂也将属于你。图腾中的鸟儿与火焰交织在一起，承载着灵魂，满载着愿望。艾因布洛克原野的历史学生奥玛正在寻找[c][ff7f00]10[-][/c]个这种物品，达到98级的冒险者可以前往兑换。通过击杀鸟人哈比·崇拜者获得。',NoSale=1,NoStorage=5,}",
  [53128] = "{id=53128,NameZh='残存的面具',Icon='item_48569',Type=160,MaxNum=99999,SellPrice=10,Desc='祭司们带着面具安静又整齐的往祭台走去，一个村民抱着一个孩子低着头恭敬的让路给祭祀们。怀中的孩子睁着好奇的双眼看着祭祀，他们全都带着面具，带着十分令人害怕的面具，面具似乎凶狠的看着自己，孩子控制不住恐惧哇的一声哭了出来。村民连忙轻轻摇晃他，安抚着他。一个祭祀停住了脚步，伸出了手抚在了孩子的额头。孩子感受到手心的温度，哽咽着努力睁开了泪眼，看向祭司。还是那个令人害怕的面具，但却有一道温柔的目光从眼睛的地方透出来。不怕了，不怕了。艾因布洛克原野的历史学生奥玛正在寻找[c][ff7f00]10[-][/c]个这种物品，达到98级的冒险者可以前往兑换。通过击杀鸟人哈比·探查者获得。',NoSale=1,NoStorage=5,}",
  [53129] = "{id=53129,NameZh='遗失的白檀木',Icon='item_52018',Type=160,MaxNum=99999,SellPrice=10,Desc='老妇人接过丈夫递过来的木枝，短小的木枝的一头被打上了一个洞。她用手轻轻摩挲着，擦去上面的泥土与灰尘。她知道这个木枝是丈夫辛辛苦苦从外面折回来的，白檀的木枝。白檀木是镇邪安神的神物，只有离村子很远的地方才有这么一颗白檀。她拿起手边编好的红绳，穿过木枝上的洞，打了个牢固的结。她站起来，慢慢的走到屋外，看着自己正在砍柴的儿子，招了招手。儿子擦了擦汗，放下手中的东西走到母亲的面前。老妇人踮起脚为他挂上了红绳，愿你平安唷，愿你平安唷。艾因布洛克原野的历史学生奥玛正在寻找[c][ff7f00]10[-][/c]个这种物品，达到98级的冒险者可以前往兑换。通过击杀鸟人哈比·追念者获得。',NoSale=1,NoStorage=5,}",
  [53130] = "{id=53130,NameZh='火焰之弓',Icon='item_41239',Type=160,MaxNum=99999,SellPrice=10,Desc='弓箭手名为卡拉，它是火焰精灵一族最优秀的射手，可谓是百发百中。卡拉对自己的技艺很得意，经常拿着自己的弓在别的火焰精灵面前炫耀。这把弓是卡拉偷偷跑去人类的城镇，威胁武器工匠得来的。卡拉将抢来的弓箭带回来之后，为这把弓注入了火焰的元素力量，这把弓射出去的箭都会被火焰包围，从而威力倍增。它给这把弓取名为火羽弓。火羽弓通体燃烧着不会熄灭的黄色火焰，不会法术的人会被火焰灼烧双手，根本无法握住它。熔岩洞窟2F的小恶魔长老安吉尔正在寻找[c][ff7f00]10[-][/c]个这种物品，达到98级的冒险者可以前往兑换。通过击杀火焰精灵·弓箭手获得。',NoSale=1,NoStorage=5,}",
  [53131] = "{id=53131,NameZh='淬炼火晶',Icon='item_42533',Type=160,MaxNum=99999,SellPrice=10,Desc='火晶球是火焰精灵一族唯一的预言家希尔斯的所有物。火晶球的外形和人类巫师使用的水晶球很相似，这不是巧合，是因为火晶球本身就是希尔斯借鉴水晶球所制造的。火晶球的外壳是用一种特别的水晶制造，它能抵抗住世界上最精粹的火焰而不被融化。火晶球内部的火焰是希尔斯拜托精灵长老赐予的，精粹而又充满力量的火焰。希尔斯对这个自己创造的火晶球很满意，比那什么水晶球帅气多了。不过希尔斯的预言根本不需要用到这个火晶球，只是起到了一个装饰作用。熔岩洞窟2F的小恶魔长老安吉尔正在寻找[c][ff7f00]10[-][/c]个这种物品，达到98级的冒险者可以前往兑换。通过击杀火焰精灵·预言家获得。',NoSale=1,NoStorage=5,}",
  [53132] = "{id=53132,NameZh='炙热的剑',Icon='item_40335',Type=160,MaxNum=99999,SellPrice=10,Desc='说到火焰精灵最厉害的剑士，精灵们会一致认为是克里斯。也不是因为克里斯的剑术真的有多厉害，而是从他手下教出来的剑士就没有不厉害的。为了表彰他杰出的贡献，精灵长老将自己打造的火光剑交予了克里斯，这把剑让克里斯成为了名副其实的剑术大师。这把剑的剑刃上有流火缠绕着，克里斯挥出的每一剑都会在空中留下橙红色的残影，周围的空气都会因此灼热起来。即使拥有了这样一把剑，克里斯还是兢兢业业的教导着弟子们，希望有一天能将火光剑交予他认可的继承人。熔岩洞窟2F的小恶魔长老安吉尔正在寻找[c][ff7f00]10[-][/c]个这种物品，达到98级的冒险者可以前往兑换。通过击杀火焰精灵·剑术大师获得。',NoSale=1,NoStorage=5,}",
  [53133] = "{id=53133,NameZh='火灵晶石',Icon='item_5102',Type=160,MaxNum=99999,SellPrice=10,Desc='火焰精灵佩里是个自认为很有品味的收藏家，它执着于收集一些稀奇古怪的东西，比如它最喜欢的火灵眼。它总喜欢一个人在黑暗里欣赏散发着幽暗红光的火灵眼，暗自感叹它的美丽。火灵眼是佩里略施手段从别的精灵那边获得的，在佩里眼里别人都不能真正欣赏它的美。传说很久以前一个强大的火焰精灵，它修习了恶魔的魔法，使得自己体内的火焰力量失控爆体死亡。但是它的一双被失控火焰填满的眼球留下了，一只已经不知去向。佩里发誓总有一天会找到另一只火灵眼。熔岩洞窟2F的小恶魔长老安吉尔正在寻找[c][ff7f00]10[-][/c]个这种物品，达到98级的冒险者可以前往兑换。通过击杀火焰精灵·收藏家获得。',NoSale=1,NoStorage=5,}",
  [53134] = "{id=53134,NameZh='卷轴残页',Icon='task_53601',Type=160,MaxNum=99999,SellPrice=10,Desc='巫术师莱德是个不合群的火焰精灵。他整天捣鼓着人类的各式火系法术，因此他被大家孤立了。没办法，火焰精灵厌恶人类，厌恶人类对环境的污染，而火焰精灵又掌握着最精粹的火焰元素力量，怎么可以自甘堕落去学习人类法术呢？可是莱德不这么认为，他觉得人类的法术有特别之处，如果能把它们研究透彻，就可以提高火焰精灵的元素力量。它孜孜不倦的研读人类的火术，并将自己的研究成果写在卷轴上，命名为火术卷轴。他自己清楚的知道，他的力量早就比精灵长老还要强大了。熔岩洞窟2F的爆炎小恶魔长老伊桑正在寻找[c][ff7f00]10[-][/c]个这种物品，达到98级的冒险者可以前往兑换。通过击杀火焰精灵·巫术师获得。',NoSale=1,NoStorage=5,}",
  [53135] = "{id=53135,NameZh='宝石边角料',Icon='item_52314',Type=160,MaxNum=99999,SellPrice=10,Desc='火炎宝石是宝石工匠菲尔的得意作品。它将偶然得来的红宝石原石放在自己的体内，三年后才将它取出，再用充满火焰力量的切割刀将它切现在的形状。原石在菲尔体内慢慢吸收着元素力量，后来又注入了切割刀的元素力量，这颗宝石是名副其实的火炎宝石。它红的仿佛要燃烧，摸上去却有着红宝石的触感，坚硬而又清冷，人类只要握住它就能将法术转化为火属性。菲尔将原石切割出来的边角料偷偷卖给了人类商人，自己则将火炎宝石重新放回了体内，想让它变得更加强大。熔岩洞窟2F的爆炎小恶魔长老伊桑正在寻找[c][ff7f00]10[-][/c]个这种物品，达到98级的冒险者可以前往兑换。通过击杀火焰精灵·宝石工匠获得。',NoSale=1,NoStorage=5,}",
  [53136] = "{id=53136,NameZh='破损的鸟蛋',Icon='item_3776',Type=160,MaxNum=99999,SellPrice=10,Desc='鲁鲁的一生没有什么追求，就喜欢品尝各种美食，虽然火焰精灵不需要吃东西。普通的食物对鲁鲁来说已经没有吸引力了，它开始尝试吃不一样的东西，别人没有吃过的东西。它将目光投向了火焰精灵的邻居火焰鸟。鲁鲁暗自揣测着，鸡蛋能吃，那火焰鸟的蛋也能吃吧。它很快将自己的想法付诸于了行动，晚上偷偷摸摸的拿回来一只火焰鸟蛋。它将它放在清水里煮熟了，剥开壳，咬了一口。晶莹剔透的蛋白，在嘴里的滋味居然还有点甜甜的，鲁鲁觉得自己找到了一生中最爱的食物。熔岩洞窟2F的爆炎小恶魔长老伊桑正在寻找[c][ff7f00]10[-][/c]个这种物品，达到98级的冒险者可以前往兑换。通过击杀火焰精灵·美食家获得。',NoSale=1,NoStorage=5,}",
  [53137] = "{id=53137,NameZh='火种',Icon='item_44027',Type=160,MaxNum=99999,SellPrice=10,Desc='一条永远不会断的绳子和一团永远不会熄灭的火焰，宝藏猎手希尔在找到这两样神奇的东西之后，将火焰穿在了绳子上面做成了一条神奇的项链。永不熄灭的火焰那不就是天神赐予的火种吗？希尔虔诚的将火种项链挂在自己的胸口，它感觉到自己的火焰力量因为这条项链变得更加强大。它也不知道自己为什么会将这两样东西放在一起，这可能就是它多年寻宝练就的直觉吧。希尔用手轻轻拢住火种项链，感受它的温度，似乎能听到它在诉说的关于火焰的故事。熔岩洞窟2F的爆炎小恶魔长老伊桑正在寻找[c][ff7f00]10[-][/c]个这种物品，达到98级的冒险者可以前往兑换。通过击杀火焰精灵·宝藏猎手获得。',NoSale=1,NoStorage=5,}",
  [53138] = "{id=53138,NameZh='感染者日记',Icon='item_3605',Type=160,MaxNum=99999,SellPrice=10,Desc='在瘟疫爆发的第四天，村子里的大家出现了不同的症状。溃烂的脓腔与孢疹在我身上蔓延，有些抵抗力差的孩子从昨天起便呕吐不止，老人们卧倒在床，依靠意志支撑这愈发恶化的身体，哭喊声逐渐变成了呻吟，大家都被这该死的瘟疫折磨得没力气了吧？这样下去，用不了多久，整个村子就会笼罩在绝对的死寂中。我望向不远处冒着黑烟的机器叹气，神啊，为何我们要遭受这场无妄之灾？如果你拥有这个物品，就去把它交给艾因布洛克原野的调查员卡戴珊吧（达到99级的冒险者可以前往兑换哦）。通过击杀大天使波利获得。',NoSale=1,NoStorage=5,}",
  [53139] = "{id=53139,NameZh='长老的拐杖',Icon='item_40601',Type=160,MaxNum=99999,SellPrice=10,Desc='艾因布洛克某个村庄长老使用过的拐杖，上面满是岁月蹉跎的印记。长老作为艾因布洛克原野历史的见证者，他一直对大肆开发工业的某个公司充满敌意。曾经孩童嬉戏的溪流在污染中变得污臭不堪，原本温顺的生物异变为凶暴魔物，这次突如其来的瘟疫，难道不也是那些冒着黑烟的钢铁怪兽的杰作么？一阵剧痛在他的体内流窜，几乎令他踉跄倒地，这场瘟疫没有因他的年迈而网开一面，他咬住牙倚着拐杖撑起弯曲的脊背。难道这村子就要从原野的地图上永远消失了吗？回答他的只有原野的风声与人们的啜泣。如果你拥有这个物品，就去把它交给艾因布洛克原野的调查员卡戴珊吧（达到99级的冒险者可以前往兑换哦）。通过击杀能天使波利获得。',NoSale=1,NoStorage=5,}",
  [53140] = "{id=53140,NameZh='透明空瓶',Icon='item_5020',Type=160,MaxNum=99999,SellPrice=10,Desc='曾经装着25年前原野瘟疫解药的玻璃瓶，如今已经空空如也，瓶身布满了青苔与裂痕。据说在某个清晨，附带一张字条的它出现在村庄的神像旁，字条上只写了一行字：喝下它，瘟疫就会结束。长老自愿第一个服下作为试验者，在验证其功效后，所有患病的村民都服下了解药，不出一周村庄的瘟情就得到了控制。由于至今无人知晓到底是谁放置的，这瓶药水被村民们称为“神之怜悯”。如果你拥有这个物品，就去把它交给艾因布洛克原野的调查员卡戴珊吧（达到99级的冒险者可以前往兑换哦）。通过击杀智天使波利获得。',NoSale=1,NoStorage=5,}",
  [53141] = "{id=53141,NameZh='机器残片',Icon='item_62001',Type=160,MaxNum=99999,SellPrice=10,Desc='看起来像是某种机器的一部分，由于年代久远，表面早已锈迹斑斑，但是依稀可以辨识出雷根贝勒公司的标识。据说在25年前，艾因布洛克原野上矗立着一座每天排放黑烟的巨大机器。在瘟疫爆发后的某天，有人声称见到一个身穿雷根贝勒公司制服的人影徘徊在机器附近，那天过后，机器便停止了运转，公司多次派人前来修理，但都回天无力，最终不得不宣布放弃此机器。机器停转后的25年间，原野再无瘟疫。如果你拥有这个物品，就去把它交给艾因布洛克原野的调查员卡朋特吧（达到99级的冒险者可以前往兑换哦）。通过击杀力天使波利获得。',NoSale=1,NoStorage=5,}",
  [53142] = "{id=53142,NameZh='机密文件',Icon='task_53635',Type=160,MaxNum=99999,SellPrice=10,Desc='记载着雷根贝勒公司某个实验的机密文件，已经被某人毁坏到无法读取其中的内容。原野实验机排出的气体会引起让人体溃烂的瘟疫，这是早就通过试验确认的结论。但是我没想到情况会这么糟糕，公司与议会竟然封锁解药的消息！这是想用全村人做人体实验么？我必须为那些无辜的人做些力所能及的事。毕竟，我也是造成这场瘟疫的罪魁祸首之一。即使这么做远不足以用来赎罪，但我必须对此负责。对不起，我亲爱的宝贝女儿，爸爸从一开始就选错了道路。时间紧迫，我必须马上出发了！这份关于机器与实验的机密文件，不能留给公司。如果你拥有这个物品，就去把它交给艾因布洛克原野的调查员卡朋特吧（达到99级的冒险者可以前往兑换哦）。通过击杀权天使波利获得。',NoSale=1,NoStorage=5,}",
  [53143] = "{id=53143,NameZh='粉色发卡',Icon='item_45127',Type=160,MaxNum=99999,SellPrice=10,Desc='波利式样的粉色发卡，是20多年前流行的旧款。和往常一样，小女孩靠在窗边托着红扑扑的小脸蛋，双眼紧盯着朱诺人来人往的街道，她在等待忙碌的父亲工作归来抱抱她。咚咚！突然传来的敲门声让她欣喜地冲向门边。爸爸！带着稚气地呼喊却迎来两位高大的陌生人，请问艾恩·格林先生在家么？冷峻的语气让女孩不知所措，爸爸还没回来呢，你们有什么事？你的爸爸不会回来了，面无表情的陌生人淡然的宣告着。女孩的泪珠一下涌出眼眶，骗人！爸爸答应我今天会替我补过生日的！这个粉色发卡就是他送给我的礼物！陌生人一把推开女孩进入房间搜查，女孩的嚎啕湮没在天空之城的云间。如果你拥有这个物品，就去把它交给艾因布洛克原野的调查员卡朋特吧（达到99级的冒险者可以前往兑换哦）。通过击杀座天使波利获得。',NoSale=1,NoStorage=5,}",
  [53144] = "{id=53144,NameZh='矿工的铁镐',Icon='dark_005',Type=160,MaxNum=99999,SellPrice=10,Desc='这把铁镐是矿工欧尼斯特的物件，一直以来镐子都是他挖矿的唯一工具。挖矿是一件很辛苦的事情，而在熔岩洞窟里的高温更是令人苦不堪言。但欧尼斯特不怕苦，他甚至很喜欢与这些矿石打交道，每天都兴致勃勃的提着铁镐去工作。在他的认知里，这整个洞窟都是一个宝藏，有大量的上等矿石，有神奇的地质地貌，还有令人畏惧的炎之领主卡浩。他每天都通过自己的双手与双脚去感知这个地方，他了解这边的每一块地形，他也了解这个洞窟的物质构成，这一切都是通过他日积月累的观察而获得的。他觉得似乎他能听到洞窟的呼吸声，什么地方出矿，什么地方危险，他都能通过洞窟的呼吸声判断出来。不知从哪一天开始，传进耳朵里的呼吸声一天一天的变得沉重，到后来他甚至能听出声音中的痛苦。怎么了？为什么你如此的痛苦？他伸出手想要触摸石壁，但他眼前一黑，然后就什么都不知道了……如果你拥有这个物品，就去把它交给熔岩洞穴2F的矿工欧尼斯特吧（达到100级的冒险者可以前往兑换哦）。通过击杀炎之领主·星火获得。',NoSale=1,NoStorage=5,}",
  [53145] = "{id=53145,NameZh='残破的推车',Icon='item_25300',Type=160,MaxNum=99999,SellPrice=10,Desc='在一群青壮的矿工之中，有一个小小的身影，他推着只比他矮一个头的推车，将矿石运到洞窟外。男孩名叫莱尼尔，是不远处村庄里的孩子。妈妈常年卧病在床，全家依靠着爸爸的收入生活。后来爸爸在矿洞里出了意外，小小年纪的他为了担负起家里的开支，来到爸爸的矿洞想要谋一份工作。大家伙也都知道莱尼尔家的情况，他没有足够的身高和体力去挖矿，工头便给了他一辆推车。男孩小小的脸崩的紧紧的，牙床用力咬合着，额头上流着大颗大颗的汗，一步一步的推着这辆车。当他终于推着车走到洞口，外面的光线一下子刺的他眯起了眼，他深吸了一口外面的空气，空气里夹杂着些许金属的味道。工头向他招了招手，他将推车停放在一旁，双手在身侧的衣服上擦了两下，往回走去，伸手接过一个装着铜钱的袋子。就在此时，大块大块的石头从洞顶掉下，莱尼尔被砸晕在了地上，双手仍牢牢护着那袋铜钱。如果你拥有这个物品，就去把它交给熔岩洞穴2F的矿工莱尼尔吧（达到100级的冒险者可以前往兑换哦）。通过击杀炎之领主·流火获得。',NoSale=1,NoStorage=5,}",
  [53146] = "{id=53146,NameZh='古老的矿工帽',Icon='item_45025',Type=160,MaxNum=99999,SellPrice=10,Desc='瓦尔特是个很胆小的人，但是他仍然干了自己明知十分危险的职业，这是因为这里独一无二的火焰矿石使得在这里的矿工可以赚到远远高出其他工作的报酬。瓦尔特对所有的安全问题都十分在意，哪怕在这么炎热的洞窟里，他的矿工帽从来不会摘下，以至于闷的头发掉了很多，如此他就更不会摘下帽子了。矿洞里的矿工们都敬炎之领主卡浩为他们守护神，因为这里的财富全都来源于卡浩的力量，但是瓦尔特却从来不这么觉得，在他眼里，卡浩就是个可怕的火焰魔物，这么可怕怎么可能是守护神呢？瓦尔特就这样每天小心翼翼的挖着矿，别的矿工看他这副样子有些不顺眼，便联手趁他不注意摘下了他的矿工帽。看着他头上一块光秃秃的头皮，矿工们都笑出了声。瓦尔特突然感觉到了一阵不安，他连忙想要抢回自己的帽子，就在此时，洞窟内突然剧烈的摇晃了起来，瓦尔特在感觉到头顶的疼痛后，失去了意识……如果你拥有这个物品，就去把它交给熔岩洞穴2F的矿工瓦尔特吧（达到100级的冒险者可以前往兑换哦）。通过击杀炎之领主·雷火获得。',NoSale=1,NoStorage=5,}",
  [53147] = "{id=53147,NameZh='至宝的气息',Icon='item_47018',Type=160,MaxNum=99999,SellPrice=100,Desc='四海至宝所携带的神圣气息。',NoSale=1,NoStorage=5,}",
  [53148] = "{id=53148,NameZh='房客日记',Icon='item_3773',Type=160,MaxNum=99999,SellPrice=10,Desc='这就是传说中的低语山庄吗？独眼的贝茨克里夫男爵，缠着缎带的男爵夫人，带着疤痕的家仆，这一切都让人不安，但客房却意外的舒适，我刚合上眼睛准备美美睡上一觉，却听见“咣当”一声，一阵大风吹开了窗户，我走上前关窗，突然！一双冰冷的手拽住了我的手腕，我出于惊恐失声尖叫，那双手立马松开并消失在窗外的夜幕中。闻声而来的管家听闻了此事只敷衍的安抚了我几句，真的是幻觉嘛？我忍不住翻开日记想要写下这一切，关于这神秘的低语山庄……等等，窗户上好像留下了一行字！秘密在地下室。山庄的地下室藏着什么秘密呢？最后，好奇心战胜了恐惧，我决定前往地下室一探究竟！（字迹中断）……低语，低语，低语，地狱，地狱，地狱！如果你拥有这个物品，就去把它交给斯凯领顿的女仆齐拉吧（达到110级的冒险者可以前往兑换哦）。通过击杀怨恨兔斯拉获得。',NoSale=1,NoStorage=5,}",
  [53149] = "{id=53149,NameZh='红色缎带',Icon='item_52410',Type=160,MaxNum=99999,SellPrice=10,Desc='很久以前，有一位富豪在斯凯领顿一座避暑山庄。每年夏天他们一家都会带着仆人来到山庄度假。富翁有个野性未脱的女儿，十分喜爱冒险，某个夏天，女孩遇见了一位流浪的男孩，两人一见钟情，私定终身。得知此事的富翁暴跳如雷，派人捉来男孩亲自剜去他的右眼，并把他永远驱逐，女孩伤心过度，将自己锁在山庄的客房闭门不出，多年以后，一位异国的独眼医生拜访山庄，长大成人的女孩听到了熟悉的声音，狂喜地打开房门，在她面前的果然是往日的恋人，她向她递上一个大大的礼物，女孩欣然解开红色缎带，里面是她父亲新鲜的头颅。如果你拥有这个物品，就去把它交给斯凯领顿的女仆齐拉吧（达到110级的冒险者可以前往兑换哦）。通过击杀哀愁兔斯拉获得。',NoSale=1,NoStorage=5,}",
  [53150] = "{id=53150,NameZh='地下室钥匙',Icon='item_52321',Type=160,MaxNum=99999,SellPrice=10,Desc='据说在斯凯领顿有一座闹鬼的山庄，山庄的主人是一位异国的医生，他的爱人在某一天由于过度惊吓而猝死，悲痛的医生将爱人的尸体冷藏了起来，将自己没日没夜地锁在地下室，与此同时山庄突然开始欢迎宾客入住，但是房客们每晚都能听见山庄底下传出诡异的咀嚼声。终于在某一天，男爵打开了地下室的大门，带出一位浑身缠满红色缎带的女人。她是我的新夫人，医生欣喜若狂的宣布。随着新夫人的到来，入住的房客陆续失踪。没人知道山庄里发生了什么，直到今天地下室仍然每晚都会发出咯吱咯吱的咀嚼声。如果你拥有这个物品，就去把它交给斯凯领顿的女仆齐拉吧（达到110级的冒险者可以前往兑换哦）。通过击杀叹息兔斯拉获得。',NoSale=1,NoStorage=5,}",
  [53151] = "{id=53151,NameZh='17号档案',Icon='22',Type=160,MaxNum=99999,SellPrice=10,Desc='此份档案永不备份，永久封藏。犯人贝茨克里夫医生杀害低语山庄主人，并使其女过度惊吓而死。后利用异国邪道医术将她的身体与魔物融合，创造了一个会在晚上变为嗜血魔物的双面魔女。医生在夜晚将魔女锁于地下室，引诱拥有强健肉体者来访，杀害后作为强化魔女肉体的素材与饲料。这一举动触怒死亡女神海拉，她亲自歼灭了魔物与贝茨克里夫医生，并烧毁了低语庄园。但近来却出现传闻，原本已被毁灭的山庄，重新出现在斯凯领顿。如果你拥有这个物品，就去把它交给斯凯领顿的男仆约瑟夫吧（达到110级的冒险者可以前往兑换哦）。通过击杀绝望兔斯拉获得。',NoSale=1,NoStorage=5,}",
  [53152] = "{id=53152,NameZh='锋利的手术刀',Icon='item_40744',Type=160,MaxNum=99999,SellPrice=10,Desc='人到暮年的弗兰肯是一位著名的外科医生，某天他在墓地安葬死者时，发现了一位独眼的男孩。男孩衣衫褴褛，空洞的右眼眶流着脓血。膝下无子的老医生将男孩带回家治疗，并收他为养子。聪明的男孩很快学会了弗兰肯超凡的医术，老医生欣慰的感概后继有人。直到某天，弗兰肯发现男孩私自用患者进行人体实验，失望又愤怒的老医生把养子赶出了家门。这天深夜，悲痛欲绝的老弗兰肯在床上辗转反侧，他感到心里空空的，似乎少了什么。突然一个熟悉的声音响起，谢谢您教我的一切，我该回去复仇了。男孩穿着他的白大褂从他床边转身离开。弗兰肯低头看了一眼自己的胸口，只有一个血淋淋的窟窿，心脏早已被男孩挖去。如果你拥有这个物品，就去把它交给斯凯领顿的男仆约瑟夫吧（达到110级的冒险者可以前往兑换哦）。通过击杀血腥兔斯拉获得。',NoSale=1,NoStorage=5,}",
  [53153] = "{id=53153,NameZh='字迹潦草的信',Icon='item_task_34',Type=160,MaxNum=99999,SellPrice=10,Desc='救命，谁来救救我。这座低语山庄里到处都是魔物!医生夫人背后的红色缎带下还有另一张女人的脸！我亲眼看到医生把生肉喂给那第二张脸，还用别人的皮肤缝合他夫人的腐烂伤口！希望这封信能被人发现，我感觉医生已经察觉了我的不安，如果有谁捡到这封信的话，一定要把这座地狱山庄的秘密公之于众！如果你拥有这个物品，就去把它交给斯凯领顿的男仆约瑟夫吧（达到110级的冒险者可以前往兑换哦）。通过击杀癫狂兔斯拉获得。',NoSale=1,NoStorage=5,}",
  [53154] = "{id=53154,NameZh='外婆的披肩',Icon='item_task_19',Type=160,MaxNum=99999,SellPrice=10,Desc='因为最疼爱的孙女来探望自己了，老妇人即使身体不适依然披上了自己最喜欢的一条披肩。“笃笃笃！”传来了敲门声，虽说时间早了一些，她依旧满心欢喜的前去开门了。刚打开一条缝，一双巨大的尖爪便伸了进来……再次见到这条披肩，它的新主人变成了一只可怖的野兽，瞪着双眼披上伪装，静候着它的猎物。如果你拥有这个物品，就去把它交给雾之森林的女猎手玛丽亚·星辰吧（达到110级的冒险者可以前往兑换哦）。通过击杀暴虐狼获得。',NoSale=1,NoStorage=5,}",
  [53155] = "{id=53155,NameZh='格曼的猎枪',Icon='item_900018',Type=160,MaxNum=99999,SellPrice=10,Desc='作为猎人协会著名的魔物猎手，格曼对狩猎有着与生俱来的直觉，当他听到某种满足的嚎叫，他的心中便产生了一种不好的预感。他追踪着足迹来到那间小木屋，眼前的景象还是让他这位老猎人作呕不已。在一片狼藉中，狼外婆满足的睡在被鲜血染成猩红的床上做着美梦。格曼毫不犹豫地将枪口对准这只野兽，但是他没想到的是，这个魔物一下跃起握住了枪管，挺着肚子夺走了格曼的猎枪仓惶地消失在了树林地黑暗中，格曼对那只野兽的最后一个印象是，它那硕大的肚子里有什么在怪异的蠕动……如果你拥有这个物品，就去把它交给雾之森林的女猎手玛丽亚·星辰吧（达到110级的冒险者可以前往兑换哦）。通过击杀狡诈狼获得。',NoSale=1,NoStorage=5,}",
  [53156] = "{id=53156,NameZh='罗夏薇拉的日记',Icon='item_3684',Type=160,MaxNum=99999,SellPrice=10,Desc='这本日记的封面上工整的写着罗夏薇拉这个名字，它的主人应该是个花季少女，虽说偷看别人的日记并不是什么好的习惯的，但这本日记只写了一半便没了下文。有内容的最后一页上写着：“独自居住的外婆生病了，妈妈让我明天带上蛋糕，水果和葡萄酒去探望她。很久没见到疼爱我的外婆，我准备穿上我最喜欢的洋装，戴上外婆送给我的小红帽，打扮得漂漂亮亮得去见她，外婆一定会非常高兴吧，妈妈说不要走林间的小路，她可真是多虑，这个世界上哪来这么多吃人的野兽？”如果你拥有这个物品，就去把它交给雾之森林的女猎手玛丽亚·星辰吧（达到110级的冒险者可以前往兑换哦）。通过击杀嗜血狼获得。',NoSale=1,NoStorage=5,}",
  [53157] = "{id=53157,NameZh='可爱的提包',Icon='item_41547',Type=160,MaxNum=99999,SellPrice=10,Desc='这个可爱的女式提包里装了可口的水果，面包，还有一瓶似乎是自家酿的葡萄酒。那女孩提着包在林间穿行的场景就像一幅古老的油画，在我脑中逐渐清晰，缓缓浮现。提包的主人一定是去见她很珍视的人吧，我多么希望她只是躺在树荫底下，做了一个太长的美梦，醒来仍是豆蔻色的年华。如果你拥有这个物品，就去把它交给雾之森林的猎人学徒梅高吧（达到110级的冒险者可以前往兑换哦）。通过击杀邪恶狼获得。',NoSale=1,NoStorage=5,}",
  [53158] = "{id=53158,NameZh='猩红的洋装',Icon='item_52328',Type=160,MaxNum=99999,SellPrice=10,Desc='一件被鲜血浸透的红色洋装，诉说着它主人的悲惨命运。据说红帽女孩罗夏薇拉被狼外婆活生生的吃掉了，她最喜欢的洋装成了外婆狼的战利品。美好的事物总是容易被摧毁，无论在什么时代，邪恶总会披上各种各样的伪装，而善良总是一如既往的单纯与炽热。如果你拥有这个物品，就去把它交给雾之森林的猎人学徒梅高吧（达到110级的冒险者可以前往兑换哦）。通过击杀疯癫狼获得。',NoSale=1,NoStorage=5,}",
  [53159] = "{id=53159,NameZh='永生玫瑰',Icon='item_52012',Type=160,MaxNum=99999,SellPrice=10,Desc='“玫瑰啊玫瑰，你得快快长大。”威尔克将自己的手腕割开，让鲜血流入泥土里，他嘴里叨念着：“你长大了，我就能向艾米丽求婚了。”玫瑰沐雨在透过窗口洒进来的月光中，而他却将自己藏在阴影之中。“深蓝星辰……我的宝物……“他收回手，用手帕擦拭着自己的手腕，而伤口已经奇迹般的愈合了，而玫瑰在他的面前慢慢绽放。如果你拥有这个物品，就去把它交给雾之森林的威尔克吧（达到110级的冒险者可以前往兑换哦）。通过击杀墓碑怪人·倾慕获得。',NoSale=1,NoStorage=5,}",
  [53160] = "{id=53160,NameZh='洁白头纱',Icon='item_48583',Type=160,MaxNum=99999,SellPrice=10,Desc='卡森低头看向自己的胸口，手里还拿着艾米丽的头纱，一柄长剑从心口穿出。艾米丽就在他的面前，剑头差点就要伤到她。卡森后退了一步，让剑头远离艾米丽。“卡森，卡森……”艾米丽迷茫的看着发生的一切，眼里的惊恐涌了上来。然后她看到了，看到卡森背后的那个人，露着尖牙盯着自己。那人猛地拽过艾米丽的手，将她紧握的手指掰开，拿到了一把钥匙。如果你拥有这个物品，就去把它交给雾之森林的卡森吧（达到110级的冒险者可以前往兑换哦）。通过击杀墓碑怪人·纯洁获得。',NoSale=1,NoStorage=5,}",
  [53161] = "{id=53161,NameZh='礼服领带',Icon='item_45054',Type=160,MaxNum=99999,SellPrice=10,Desc='威尔克整理了一下领带，精神抖擞的站在城堡门口，看着一步一步走来的新娘。艾米丽的面容隐在头纱后，看不清表情，但威尔克认为她一定是很高兴。就在他要伸手去牵住艾米丽的时候，一个青年挡在了他的面前。青年牵住新娘的手向外跑去，而新娘似乎没有一丝的挣扎，在大家愣神的时候，两人已消失不见。威尔克深吸了一口气，提起一把长剑，向外追去……如果你拥有这个物品，就去把它交给雾之森林的威尔克吧（达到110级的冒险者可以前往兑换哦）。通过击杀墓碑怪人·永恒获得。',NoSale=1,NoStorage=5,}",
  [53162] = "{id=53162,NameZh='告白情书',Icon='item_task_34',Type=160,MaxNum=99999,SellPrice=10,Desc='一封卡森写的情书，上面写着——致亲爱的艾米丽：在上次舞会上的相遇后，我对你的思念一天比一天的强烈，强烈到让我快无法呼吸。即使知道你已有婚约，而婚礼将会在明天举行，但是这都不能阻挡你和我之间的爱恋。你还记得我们的约定吗？明天早上花园里见，我将履行我的承诺，我将为你戴上戒指，为了我爱的你。如果你拥有这个物品，就去把它交给雾之森林的卡森吧（达到110级的冒险者可以前往兑换哦）。通过击杀墓碑怪人·约定获得。',NoSale=1,NoStorage=5,}",
  [53163] = "{id=53163,NameZh='蓝星戒指',Icon='item_6059',Type=160,MaxNum=99999,SellPrice=10,Desc='“艾米丽，你愿意嫁给我吗？”“我愿意！”卡森小心翼翼的掀开艾米丽的头纱，两人四目相对，彼此都有许多话想要说。”卡森，我有东西想给你。“卡森温柔的抚摸着艾米丽的脸：“先让我把东西给你。”卡森拉起艾米丽的手，想要将蓝星戒指给艾米丽戴上。一阵刺痛从胸口传来，随之而来的是暖暖的热流。捏在手里的戒指叮当的一声，掉在了地上……如果你拥有这个物品，就去把它交给雾之森林的卡森吧（达到110级的冒险者可以前往兑换哦）。通过击杀墓碑怪人·誓言获得。',NoSale=1,NoStorage=5,}",
  [53164] = "{id=53164,NameZh='舞会假面',Icon='item_48545',Type=160,MaxNum=99999,SellPrice=10,Desc='小镇上有个城堡，主人是个优雅的绅士，他与镇上一个富裕家庭的小姐订了婚，为了宣布这个消息，他举办了一场假面舞会。卡森拿着自己制作的假面去城堡参加了这场舞会。他的双眼在假面的背后，漫不经心的打量着全场。一个姑娘的出现吸引了他的全部注意力，他踱步上前，邀请这位同样戴着假面的姑娘一起跳舞。随着音乐跳动的，是两颗年轻悸动的心。如果你拥有这个物品，就去把它交给雾之森林的卡森吧（达到110级的冒险者可以前往兑换哦）。通过击杀墓碑怪人·相遇获得。',NoSale=1,NoStorage=5,}",
  [53165] = "{id=53165,NameZh='宝箱钥匙',Icon='item_52321',Type=160,MaxNum=99999,SellPrice=10,Desc='一把精致的金色钥匙，能打开艾米丽家的宝箱。在婚礼前一天的晚上，艾米丽的父亲将这把钥匙亲手交给了她，告诉她宝箱里有一颗他们家族代代相传的宝物——一颗深蓝色的珍珠。父亲只有艾米丽一个女儿，这个钥匙是他给女儿的最重要的嫁妆，希望她能交给自己的丈夫，能一生幸福美满。艾米丽明白父亲的苦心，她一定会将这把钥匙交给自己未来的丈夫。如果你拥有这个物品，就去把它交给雾之森林的威尔克吧（达到110级的冒险者可以前往兑换哦）。通过击杀墓碑怪人·财富获得。',NoSale=1,NoStorage=5,}",
  [53166] = "{id=53166,NameZh='银质刺刀',Icon='item_900006',Type=160,MaxNum=99999,SellPrice=10,Desc='艾米丽的双手被鲜血染红。她拿出藏在裙底的刺刀，深吸了口气，整个人猛地向前冲去。威尔克此时正看着手中的金色钥匙，没有防备的被刺刀刺中了手臂。他毫不在意，因为这小伤口对他来说不值一提。但当他看清刺刀是银质的时候，他才惊觉：“你知道我是吸血鬼！”艾米丽没有回答，她拔出卡森胸口的长剑，将自己送向刀口。“威尔克，你活不久了……”如果你拥有这个物品，就去把它交给雾之森林的威尔克吧（达到110级的冒险者可以前往兑换哦）。通过击杀墓碑怪人·勇气获得。',NoSale=1,NoStorage=5,}",
  [53167] = "{id=53167,NameZh='米依花之思念',Icon='item_48613',Type=49,MaxNum=99999,SellPrice=1,Desc='原为长在沙漠中普通的米依花，被注入了思念的力量，献给梦罗克战斗甚至牺牲的勇士们再合适不过了。这份承载着记忆的思念将会永远燃烧在你的心中。从梦罗克雕像旁神秘的怪老头那可以购买获得。',NoStorage=5,}",
  [53168] = "{id=53168,NameZh='米依花之崇敬',Icon='item_48628',Type=49,MaxNum=99999,SellPrice=1,Desc='原为长在沙漠中普通的米依花，被注入了崇敬的力量，献给梦罗克战斗甚至牺牲的勇士们再合适不过了。这份承载着意志的崇敬将会永远燃烧在你的心中。从梦罗克雕像旁神秘的怪老头那可以购买获得。',NoStorage=5,}",
  [53169] = "{id=53169,NameZh='米依花之思念',Icon='item_48613',Type=165,MaxNum=99999,SellPrice=100,Desc='原为长在沙漠中普通的米依花，被注入了思念的力量，献给梦罗克战斗甚至牺牲的勇士们再合适不过了。这份承载着记忆的思念将会永远燃烧在你的心中。从梦罗克雕像旁神秘的怪老头那可以购买获得。',NoSale=1,NoStorage=5,}",
  [53170] = "{id=53170,NameZh='米依花之崇敬',Icon='item_48628',Type=165,MaxNum=99999,SellPrice=100,Desc='原为长在沙漠中普通的米依花，被注入了崇敬的力量，献给梦罗克战斗甚至牺牲的勇士们再合适不过了。这份承载着意志的崇敬将会永远燃烧在你的心中。从梦罗克雕像旁神秘的怪老头那可以购买获得。',NoSale=1,NoStorage=5,}",
  [53171] = "{id=53171,NameZh='康尼的指导手册',Icon='item_900005',Type=160,MaxNum=99999,SellPrice=10,Desc='指导员康尼是带领志愿生海拉米成为消防员的人，如今的他四十九岁了，原本还有一年时间，他就要退休了。然而教导过无数优秀消防员的他，怎么也不会想到，自己最后的归宿不是在消防局授勋，也不是葬身火场，而是……成为了火灾废墟游荡的魔物。如果你拥有这个物品，就去把它交给研究所地下1F入口处的卡格吧（达到121级的冒险者可以前往兑换哦）。通过击杀消防魔指导员康尼获得。',NoSale=1,NoStorage=5,}",
  [53172] = "{id=53172,NameZh='鲍恩的消防斧',Icon='item_41814',Type=160,MaxNum=99999,SellPrice=10,Desc='中队长鲍恩是一个鲁莽的人，虽然大队长莱克教育过他很多次要小心行事，但他依旧保持着他那我行我素的风格。鲍恩的消防斧上沾染了许多魔物留下的血迹，或许在失去意识的最后一刻前，他依然以他鲁莽的风格，拼命保护着火场的生还者吧。如果你拥有这个物品，就去把它交给研究所地下1F入口处的卡格吧（达到121级的冒险者可以前往兑换哦）。通过击杀消防魔中队长鲍恩获得。',NoSale=1,NoStorage=5,}",
  [53173] = "{id=53173,NameZh='莱克的手套',Icon='item_44023',Type=160,MaxNum=99999,SellPrice=10,Desc='大队长莱克是全消防局最出名的处女座，他对所有事情一丝不苟，哪怕是已经检查过一遍的装备，他都会再反复确认多次，然后带队执行行动。莱克的手套是他的消防员父亲留给他的，虽然旧了，但他每次任务后都会清洗打理，哪怕变成了魔物，他潜意识里最珍惜的，也是这副手套。如果你拥有这个物品，就去把它交给研究所地下1F入口处的卡格吧（达到121级的冒险者可以前往兑换哦）。通过击杀消防魔大队长莱克获得。',NoSale=1,NoStorage=5,}",
  [53174] = "{id=53174,NameZh='杰夫的氧气瓶',Icon='item_47154',Type=160,MaxNum=99999,SellPrice=10,Desc='装备部长杰夫是消防队所有人坚实的后盾，他背着厚厚的装备包，里面都是可以简易替换的装备和应急设备。这个氧气瓶是杰夫刚成为消防员的时候获得的，他让许多退休的前辈在上面签了名，觉得这样就像是能与前辈并肩作战一样荣幸……但这上面最后一道签名，是机械猎犬的牙印。如果你拥有这个物品，就去把它交给研究所地下1F入口处的贝姆吧（达到121级的冒险者可以前往兑换哦）。通过击杀消防魔装备部长杰夫获得。',NoSale=1,NoStorage=5,}",
  [53175] = "{id=53175,NameZh='拉瑞的救生皮带',Icon='item_44021',Type=160,MaxNum=99999,SellPrice=10,Desc='后勤部长拉瑞原本不应该参加这次行动，他是个胆小的人，整个消防局都知道，他连老鼠都怕，根本没办法参加危险的外勤行动。但是这一次，听说队员们都被困在火场，尤其是他的老朋友杰夫也在其中…他终于鼓起了勇气，穿上装备强硬的冲进了火海，想要救出杰夫。这条救生皮带被发现的时候，是拷在杰夫的身上的，但这上面刻的，却是拉瑞光荣的姓名。如果你拥有这个物品，就去把它交给研究所地下1F入口处的贝姆吧（达到121级的冒险者可以前往兑换哦）。通过击杀消防魔后勤部长拉瑞获得。',NoSale=1,NoStorage=5,}",
  [53176] = "{id=53176,NameZh='海拉米的毕业证',Icon='task_53635',Type=160,MaxNum=99999,SellPrice=10,Desc='志愿生海拉米来到消防局已经一周了，他还没从消防学校毕业，就急匆匆地通过申请成为了志愿消防员。这次行动是他第一次的正式行动，他激动极了，早上出门前，甚至告诉爸爸妈妈，他就要当救火英雄了。这张毕业证他一直放在裤子后面的口袋里，真傻，他也不怕在火场烧坏了……然而毕业证并没有烧毁，但海拉米他却不在了。如果你拥有这个物品，就去把它交给研究所地下1F入口处的贝姆吧（达到121级的冒险者可以前往兑换哦）。通过击杀消防魔志愿生海拉米获得。',NoSale=1,NoStorage=5,}",
  [53177] = "{id=53177,NameZh='飞行眼镜',Icon='item_45032',Type=160,MaxNum=99999,SellPrice=10,Desc='在娜乌西卡族的习俗中，13岁的男孩就会视为成年，在他们的成年礼上，族长会亲手将族内工匠制作的飞行眼镜送给他们，这副眼镜将伴随他们终身，他们的每一次飞行都将透过镜片面对未知的危险——“戴上它就不会害怕了，飞的再快也不会害怕的。”，族长总这样鼓励第一次飞行的孩子，但他们究竟能否活着回来，其实谁也说不清楚。如果你拥有这个物品，就去把它交给里希塔乐原野入口处风车旁的青年吧（达到120级的冒险者可以前往兑换哦）。通过击杀飓风魔·狂风获得。',NoSale=1,NoStorage=5,}",
  [53178] = "{id=53178,NameZh='喷气背包',Icon='item_47022',Type=160,MaxNum=99999,SellPrice=10,Desc='为了对抗盘踞在山谷外部的飓风魔，娜乌西卡族尝试过很多种飞出山谷的方法。比如最初他们用兽皮制作滑翔伞，也试过生火制作热气球，但无一例外都失败了。直到有一天山谷的飓风吹来了一群迷路的哥布灵，在一番战斗过后，工匠们从喷气哥布灵的装备上得到启发，设计了能够在强风环境下借着风力飞行的喷气背包。如果你拥有这个物品，就去把它交给里希塔乐原野入口处风车旁的青年吧（达到120级的冒险者可以前往兑换哦）。通过击杀飓风魔·逆风获得。',NoSale=1,NoStorage=5,}",
  [53179] = "{id=53179,NameZh='祈愿风车',Icon='item_45264',Type=160,MaxNum=99999,SellPrice=10,Desc='为了冲出山谷，娜乌西卡族年复一年日复一日地派遣飞行队对抗飓风魔，成年的飞行队员在起飞前，会收下家人制作的祈愿风车，如果遭遇不测，就要在最后一刻将风车放飞出去，因为山谷里的风总是向内盘旋，所以风车最后一定会飞回山谷。收到风车的家人会接受惨痛的事实，然后为族人立起墓碑，将风车置于墓碑的名字前。如果你拥有这个物品，就去把它交给里希塔乐原野入口处风车旁的青年吧（达到120级的冒险者可以前往兑换哦）。通过击杀飓风魔·黑风获得。',NoSale=1,NoStorage=5,}",
  [53180] = "{id=53180,NameZh='鼓风笛',Icon='item_48571',Type=160,MaxNum=99999,SellPrice=10,Desc='娜乌西卡族没见过山谷外的世界，所以鼓风笛是他们认知中唯一存在的乐器。鼓风笛演奏出的声音多是哀怨而悠长的，娜乌西卡族的音乐家总是会感叹道，风原本应该是美丽而温柔的东西，但飓风魔的存在让风囚禁了娜乌西卡族的世界，让风声也变得令人害怕起来。如果你拥有这个物品，就去把它交给里希塔乐原野入口处风车旁的少女吧（达到120级的冒险者可以前往兑换哦）。通过击杀飓风魔·疾风获得。',NoSale=1,NoStorage=5,}",
  [53181] = "{id=53181,NameZh='魔力测风仪',Icon='Task_MagicStaff',Type=160,MaxNum=99999,SellPrice=10,Desc='整个娜乌西卡族的魔力凝聚在一起，才制成了这柄可以感应风的魔力测风仪，它即是娜乌西卡族对抗飓风魔最大的依赖，也是娜乌西卡族所有族人的寄托和信仰。如今这柄保存了数百年的测风仪，已经失去了原本的作用了，但只要触摸着它沉重的质感，依然能够感受到当年娜乌西卡族的热血和悲伤。如果你拥有这个物品，就去把它交给里希塔乐原野入口处风车旁的少女吧（达到120级的冒险者可以前往兑换哦）。通过击杀飓风魔·朔风获得。',NoSale=1,NoStorage=5,}",
  [53182] = "{id=53182,NameZh='风中草',Icon='item_550529',Type=160,MaxNum=99999,SellPrice=10,Desc='娜乌西卡族的山谷里能种植的植物很少，饲养的牛羊也远远不够支撑整个族群的消耗，于是，这种顺着风被吹进山谷的风中草，成为了娜乌西卡族最为基本的口粮。据说这种风中草生长在山谷外侧的石壁上，除了冬天以外都生长茂盛，虽然吃起来口感非常糟糕，但在艰苦的环境下，有这样能果腹的食物，也算是些许的慰藉了。如果你拥有这个物品，就去把它交给里希塔乐原野入口处风车旁的少女吧。通过击杀飓风魔·阴风获得。',NoSale=1,NoStorage=5,}",
  [53183] = "{id=53183,NameZh='魔菇肉排',Icon='item_551000',Type=160,MaxNum=99999,SellPrice=10,Desc='用魔菇的肉做成的肉排，散发出诱人的香气，但是吃了会中毒吧？据说是下水道公主斯丽帕的宠物——妮妮喜欢的东西。',NoSale=1,NoStorage=5,}",
  [53184] = "{id=53184,NameZh='黏黏的网',Icon='item_53845',Type=160,MaxNum=99999,SellPrice=10,Desc='黏糊糊的网，会粘住所有接近的东西，据说是下水道公主斯丽帕的宠物——妮妮喜欢的东西。如果你拥有这个物品，就去把它交给下水道1F的斯丽帕吧（达到10级的冒险者可以前往兑换哦）。通过调查下水道1F奇怪的巢穴获得。',NoSale=1,NoStorage=5,}",
  [53185] = "{id=53185,NameZh='翻译装置',Icon='item_5753',Type=160,MaxNum=99999,SellPrice=10,Desc='雷根贝勒公司根据神工匠哈沃德的设计优化过的翻译装置，使用后，能翻译出部分魔物的叫声。如果你拥有这个物品，就去把它交给下水道1F的本斯特吧（达到10级的冒险者可以前往兑换哦）。通过调查下水道1F奇怪的巢穴获得。',NoSale=1,NoStorage=5,}",
  [53186] = "{id=53186,NameZh='热水晶',Icon='item_53728',Type=160,MaxNum=99999,SellPrice=10,Desc='雷根贝勒公司研发的能产生能源的水晶，似乎可以当作能源来启动隧道前的灯。如果你拥有这个物品，就去把它交给下水道1F的本斯特吧（达到10级的冒险者可以前往兑换哦）。通过调查下水道1F奇怪的巢穴获得。',NoSale=1,NoStorage=5,}",
  [53187] = "{id=53187,NameZh='水晶罗盘',Icon='item_53187',Type=48,MaxNum=99999,SellPrice=100,Desc='来自荒境的古老罗盘。遍布岁月的痕迹，但使用起来依旧灵敏。被神秘的魔力笼罩，跟随它的指引，或许会有意想不到的发现。',NoStorage=5,}",
  [53188] = "{id=53188,NameZh='遗落的指针',Icon='item_53188',Type=48,MaxNum=99999,SellPrice=100,Desc='从荒境某处发现的指针，已经锈迹斑斑。沿着它指向的方向探索，也许会发现不可思议的宝物。',NoStorage=5,}",
  [53189] = "{id=53189,NameZh='月光磁石',Icon='item_53189',Type=62,MaxNum=99999,SellPrice=100,NoStorage=5,}",
  [53190] = "{id=53190,NameZh='火之裂片',Icon='item_700138',Type=160,MaxNum=99999,SellPrice=10,Desc='受到荒境大地中奇妙魔力的影响，火之元素变得乖戾而冷漠，它们不再为世间带来光明与温暖。那些与火关系密切的魔物也被侵蚀，而它们体内稀少的纯净元素渐渐凝结成裂片，保留了让一切恢复正常的火种。击败荒境中的冷冷冰焰而获得，听说荒境东北部的孟卡拉正在寻找这种物品。',NoStorage=5,}",
  [53191] = "{id=53191,NameZh='雷之裂片',Icon='item_700137',Type=160,MaxNum=99999,SellPrice=10,Desc='历经数不尽的岁月，以及远古的那场大战后，荒境的大地中积累了庞大的魔力。受此影响，荒境的元素之力也逐渐发生变异，就连最不稳定的雷之元素都被迫凝聚出实体，并附身于魔物之中，从此消失于天际。击败荒境中的的斧王霍德尼而获得，听说荒境东北部的孟卡拉正在寻找这种物品。',NoStorage=5,}",
  [53192] = "{id=53192,NameZh='水之裂片',Icon='item_700139',Type=160,MaxNum=99999,SellPrice=10,Desc='荒境所有的元素之力中，只有水之元素没有受到大地中魔力的影响，保持了原本的性质。但天地间的一切都已变化，其他元素的异样日益加重，只有一场浸润万物的静雨才能使一切恢复原状，而蕴含了水元素精魄的水之裂片就是关键。击败荒境中的厄查斯而获得，听说荒境东北部的孟卡拉正在寻找这种物品。',NoStorage=5,}",
  [53193] = "{id=53193,NameZh='风之裂片',Icon='item_700141',Type=160,MaxNum=99999,SellPrice=10,Desc='自远古的那场大战后，风元素的力量便逐渐衰竭，这个本来最具生机与活力的元素变得虚弱而疲惫，最终被魔物瓜分吸收，而仅存的精魄则在风之裂片中静静沉睡，等待苏醒的契机。击败荒境中的“大口”莱瑞而获得，听说荒境东北部的孟卡拉正在寻找这种物品。',NoStorage=5,}",
  [53194] = "{id=53194,NameZh='地之裂片',Icon='item_700140',Type=160,MaxNum=99999,SellPrice=10,Desc='荒境陷入了危机。只有大地知道，现在的荒境面临怎样的危机。常人眼中只是有些干旱，其实荒境元素的混乱已然非常严重，若不能让一切恢复正常，灾难就将来到。击败荒境中的噩梦魔菇而获得，听说荒境东北部的孟卡拉正在寻找这种物品。',NoStorage=5,}",
  [53195] = "{id=53195,NameZh='黄昏罗盘',Icon='item_53187',Type=48,MaxNum=99999,SellPrice=100,Desc='来自枫叶彼岸的古老罗盘。遍布岁月的痕迹，但使用起来依旧灵敏。被神秘的魔力笼罩，跟随它的指引，或许会有意想不到的发现。',NoStorage=5,}",
  [53196] = "{id=53196,NameZh='古旧的指针',Icon='item_53188',Type=48,MaxNum=99999,SellPrice=100,Desc='从枫叶彼岸某处发现的指针，已经锈迹斑斑。沿着它指向的方向探索，也许会发现不可思议的宝物。',NoStorage=5,}",
  [53197] = "{id=53197,NameZh='宝石',Icon='zhengju_icon_30',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='掉落在密室里的宝石，看上去十分昂贵。形状有些眼熟，似乎在哪里见过。',Feature=1,}",
  [53198] = "{id=53198,NameZh='收纳盒钥匙',Icon='zhengju_icon_31',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='在王后的收纳盒边摆放着的一把钥匙。',Feature=1,}",
  [53199] = "{id=53199,NameZh='去污剂',Icon='zhengju_icon_32',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='一瓶在仓库中找到的药剂，标签上写着去污剂。',Feature=1,}",
  [53200] = "{id=53200,NameZh='水晶灯饰I',Icon='item_53988',Type=160,Quality=2,MaxNum=99999,SellPrice=10,Desc='玫瑰剧院的巨大水晶灯上拆下来的部件，用于连接天花板与水晶灯。',}",
  [53201] = "{id=53201,NameZh='水晶灯饰II',Icon='item_12526',Type=160,Quality=2,MaxNum=99999,SellPrice=10,Desc='玫瑰剧院的巨大水晶灯上拆下来的部件，用于放置照明的蜡烛。',}",
  [53202] = "{id=53202,NameZh='水晶灯饰III',Icon='item_3004980',Type=160,Quality=2,MaxNum=99999,SellPrice=10,Desc='玫瑰剧院的巨大水晶灯上拆下来的部件，是灯罩的一部分。',}",
  [53203] = "{id=53203,NameZh='水晶灯饰IV',Icon='item_12532',Type=160,Quality=2,MaxNum=99999,SellPrice=10,Desc='玫瑰剧院的巨大水晶灯上拆下来的部件，上面雕刻着精美的纹理。',}",
  [53204] = "{id=53204,NameZh='水晶灯饰V',Icon='item_49123',Type=160,Quality=2,MaxNum=99999,SellPrice=10,Desc='玫瑰剧院的巨大水晶灯上拆下来的部件，是用水晶串联而成的。',}",
  [53205] = "{id=53205,NameZh='流星林腰牌',Icon='item_44072',Type=160,Quality=2,MaxNum=99999,SellPrice=10,Desc='流星林弟子特有的令牌，获得它代表它的主人认可了你的实力。',}",
  [53206] = "{id=53206,NameZh='门主谕令',Icon='item_53206',Type=160,Quality=2,MaxNum=99999,SellPrice=10,}",
