  [53211] = "{id=53211,NameZh='料理兑换券',Icon='item_5899',Type=160,Quality=2,MaxNum=99999,SellPrice=1,Desc='这是厨娘希尔为了感谢朋友维诺奇支持她的烹饪梦想而赠送的兑换券。',}",
  [53212] = "{id=53212,NameZh='多兰族画像',Icon='item_5914',Type=160,Quality=2,MaxNum=99999,SellPrice=1,Desc='上面是一个敏捷的多兰族男性小偷画像，如果他将天赋用在正道而不是偷窃就好了。',}",
  [53213] = "{id=53213,NameZh='笛子',Icon='item_7014',Type=160,Quality=2,MaxNum=99999,SellPrice=1,Desc='破旧的笛子，似乎陪伴持有者度过了漫长的岁月。',}",
  [53214] = "{id=53214,NameZh='绿叶精华',Icon='item_13329',Type=160,Quality=2,MaxNum=99999,SellPrice=1,Desc='充溢着魔力的绿叶精华，有醒酒的功效。',}",
  [53215] = "{id=53215,NameZh='克魔岛啤酒',Icon='item_6137',Type=160,Quality=2,MaxNum=99999,SellPrice=1,Desc='写着“克魔岛特产”的啤酒，可惜被喝到只剩一半。',}",
  [53216] = "{id=53216,NameZh='望远镜',Icon='item_3004865',Type=160,Quality=2,MaxNum=99999,SellPrice=1,Desc='最新科技研发的望远镜头饰，将美观和功能结合一体。',}",
  [53217] = "{id=53217,NameZh='远洋围巾',Icon='item_3001910',Type=160,Quality=2,MaxNum=99999,SellPrice=1,Desc='温暖又时尚的围巾，可以有效抗击严寒。',}",
  [53218] = "{id=53218,NameZh='艾尔贝塔诗集',Icon='item_63405',Type=160,Quality=2,MaxNum=99999,SellPrice=1,Desc='艾尔贝塔的古老诗集，记载了当地的传说。',}",
