  [53500] = "{id=53500,NameZh='少女的发簪',Icon='item_45190',Type=63,MaxNum=9999,SellPrice=100,AdventureSort=23101,AdventureValue=85,AdventureReward={rewardid={870001}},Condition=64,Desc='【古城末日“叛变者”调查档案1号】卡珊德拉公主的饰物，上面刻有她的名字缩写，是当时流行的款式。由欧律皮罗斯男爵赠送给公主作为定情信物。发簪有烧伤过的痕迹，传说公主曾经因一场大火而毁容，但男爵仍然承诺将娶她为妻。',NoSale=1,NoStorage=5,}",
  [53501] = "{id=53501,NameZh='损毁的头盔',Icon='item_task_29',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23102,AdventureValue=85,AdventureReward={rewardid={870002}},Condition=64,Desc='【古城末日“叛变者”调查档案2号】俄思鲁将军的头盔，其上有一道深而长的刀痕，那是和某位男爵决斗时留下的耻辱。后来，这位将军因骁勇善战不苟言笑，被卡珊德拉公主赐予“寒冰锻造的利刃”之称，并拔剑在头盔上划下了另一道痕迹。不知公主是不是在开玩笑，不过这个头盔伴随着将军一生。',NoSale=1,NoStorage=5,}",
  [53502] = "{id=53502,NameZh='古旧的勋章',Icon='27',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23103,AdventureValue=85,AdventureReward={rewardid={870003}},Condition=64,Desc='【古城末日“叛变者”调查档案3号】这是施密特王朝特制的战士勋章，徽纹代表着持有者为施密特家族的亲信，骑士团中只有极少数人会被国王授予这种勋章。它并非代表荣耀，而是成为施密特王家的影子，执行秘密的任务。在这枚勋章上，竟然刻着卢恩王国七大家族之一，鲁贝布勒格家族的姓氏。',NoSale=1,NoStorage=5,}",
  [53503] = "{id=53503,NameZh='深红的披风',Icon='item_43002',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23104,AdventureValue=85,AdventureReward={rewardid={870004}},Condition=64,Desc='【古城末日“叛变者”调查档案4号】披风里衬上有伊多墨将军的名字，这位赫赫有名的施密特王朝大将，与俄思鲁将军并称“王国双璧”，生前两人亦是挚友。不过关于这位将军的死，传言却是扑朔迷离。据说将军并非战死，而是被暗杀。“俄思鲁将军秘密处死男爵家仆”的王家丑闻事件，被认为与伊多墨将军之死有关。',NoSale=1,NoStorage=5,}",
  [53504] = "{id=53504,NameZh='破碎的宝石',Icon='item_5102',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23105,AdventureValue=85,AdventureReward={rewardid={870005}},Condition=64,Desc='【古城末日“叛变者”调查档案5号】这颗宝石曾被镶嵌在施密特国王的权杖上，世代相传。宝石的碎裂，映照着这个王族的末路。大贤者巴特蒙德曾警告过国王，将这颗宝石从权杖上取下并丢弃，否则王国必将迎来末日。于是，这颗宝石就被锁进了宝箱，国王称它为“恶魔的诱惑”。',NoSale=1,NoStorage=5,}",
  [53505] = "{id=53505,NameZh='残旧的匕首',Icon='item_40724',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23106,AdventureValue=85,AdventureReward={rewardid={870006}},Condition=64,Desc='【古城末日“叛变者”调查档案6号】“阿芙洛忒的匕首”是它久违流传之名，刀柄上的纹章属于克雷霍尔伦家族，因此它被称为“弑君者匕首”。篡位者吉奥布罗克国王的王后阿芙洛忒命一位手艺精湛的工匠锻造了它，并赠送给丈夫。这把匕首后来一直被克雷霍尔伦家族保存，最后一位主人将它锁进了箱子里，如同想要将克雷霍尔伦家族那不能明言的过去藏起，渴望那沉重的负担从此被人遗忘。',NoSale=1,NoStorage=5,}",
  [53506] = "{id=53506,NameZh='祈祷的项链',Icon='item_44019',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23107,AdventureValue=85,AdventureReward={rewardid={870007}},Condition=64,Desc='【古城末日“叛变者”调查档案7号】安德斯神父的十字架项链，过去，他常常握着它祈祷施密特王族的永久康盛，并祝福他的爱人幸福。谣传他过去是皇家宫廷乐师，因被某位伯爵诬陷暗中爱慕王后，为了王后的名誉而选择离开王庭，隐居在修道院中，除了祷告之外，又领养了许多贫苦孤儿。',NoSale=1,NoStorage=5,}",
  [53507] = "{id=53507,NameZh='罗娜的魔书',Icon='item_42518',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23108,AdventureValue=85,AdventureReward={rewardid={870008}},Condition=64,Desc='【古城末日“叛变者”调查档案8号】罗娜的魔法书，记录着她抄录的那些失传的古魔法咒语。罗娜被认为是邪恶的巫师，她孤独地居住在一间偏僻小屋里，研究着在人们眼中被视为最邪恶禁忌的魔法，因此没有人愿意接近她的住处，只有安德斯神父愿意和她交谈。她送了神父一条项链，说是能带来幸福。这本书在她死后，被转交给安德斯神父保管。不久之后，安德斯神父又对一位来访者宣称，遗失了这本书……',NoSale=1,NoStorage=5,}",
  [53508] = "{id=53508,NameZh='士兵的日记',Icon='item_3002',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23109,AdventureValue=85,AdventureReward={rewardid={870009}},Condition=64,Desc='【古城末日“叛变者”调查档案9号】古城守备士兵的日记，里面写满了枯燥的巡逻日常、成年人的深夜笑话、下水道的鬼怪传说、施密特王族的那些王家闹剧、流浪狗“小柯”的饲养日志、对修道院里传出的琴声品评……最后一篇日记停留在两百年前的那个夜晚，上面写道：恶魔来了，但海因里希将军会带领我们战胜恶魔。等我凯旋归来，我决定对那条流浪犬好一点……',NoSale=1,NoStorage=5,}",
  [53509] = "{id=53509,NameZh='腐蚀的头骨',Icon='item_task_30',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23110,AdventureValue=85,AdventureReward={rewardid={870010}},Condition=64,Desc='【古城末日“叛变者”调查档案10号】据传是施密特王朝第一任国王的头骨，又相传是国王祖父的头骨，也有流传说是先代国王的战友大魔导士路西菲尔的头骨……总之，这颗神秘的头骨被封存在王族后花园地窖中很多年。触碰头骨，似乎能看到头骨上飘出一个白糊糊的鬼影……',NoSale=1,NoStorage=5,}",
  [53510] = "{id=53510,NameZh='残缺的石碑',Icon='item_5027',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23111,AdventureValue=85,AdventureReward={rewardid={870011}},Condition=64,Desc='【古城末日“叛变者”调查档案11号】卡珊德拉公主的墓碑，这位公主死于一场传染病，临终前十分孤独凄惨，只有一名忠心的侍女照顾着她。石碑上写着她的墓志铭：愿宽容如烈火带来温暖，愿善良之人终得一切恩露之报。',NoSale=1,NoStorage=5,}",
  [53511] = "{id=53511,NameZh='骑士的羽穗',Icon='item_45089',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23112,AdventureValue=85,AdventureReward={rewardid={870012}},Condition=64,Desc='【古城末日“叛变者”调查档案12号】欧律皮罗斯男爵家族特有的象征，它被拔下来，伴随着卡珊德拉公主度过了病患余生。男爵在破城之日，于公主墓碑前刎颈自杀，当时他手中握着这根羽穗，在墓碑前的地上用剑刻下了愧疚之言。男爵倒在血泊中时，羽穗随风飘远，爱意随风而逝。',NoSale=1,NoStorage=5,}",
  [53512] = "{id=53512,NameZh='宰相的怀表',Icon='item_task_31',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23113,AdventureValue=85,AdventureReward={rewardid={870013}},Condition=64,Desc='【古城末日“叛变者”调查档案13号】奥德修斯宰相的怀表，是他非常珍爱之物。据说是妻子的遗物，宰相日理万机时总是打开它确认时间，从未让它离开过身边。但它现在却没有陪伴着宰相的遗体，是有人将它偷走了吗？怀表本身价值不菲，曾经有人向宰相高价收取这块怀表，当然被拒绝了。',NoSale=1,NoStorage=5,}",
  [53513] = "{id=53513,NameZh='贵妇的礼帽',Icon='item_task_32',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23114,AdventureValue=85,AdventureReward={rewardid={870014}},Condition=64,Desc='【古城末日“叛变者”调查档案14号】海因里希执政期间，曾因为这顶礼帽而闹出过一段绯闻，它原先被摆放在海因里希的书房中，后来却出现在了一位贵妇的头上。不过严肃古板的执政官阁下，可不像是会偷偷赠送贵妇礼帽的那种男人啊，大家都认为他这辈子唯一的情人就是他的工作。',NoSale=1,NoStorage=5,}",
  [53514] = "{id=53514,NameZh='国王的宝剑',Icon='item_40332',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23115,AdventureValue=85,AdventureReward={rewardid={870015}},Condition=64,Desc='【古城末日“叛变者”调查档案15号】初代施密特国王使用过的剑，此后，每一任国王都会在加冕仪式上接过它。它见证了施密特王族的兴衰。最后一任国王将它留在了克雷斯特汉姆古城，远赴他乡再也没有回来。海因里希执政官总是遥遥望着这把国王宝剑叹息。希默梅思用它斩下了海因里希的头颅，然后随手把它丢弃了，于是它所承载的一代王朝落下帷幕。',NoSale=1,NoStorage=5,}",
  [53515] = "{id=53515,NameZh='GLC.A031号档案',Icon='task_certificate',Type=63,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=23116,AdventureValue=143,AdventureReward={rewardid={870016}},Condition=64,Desc='A.W800年，希默梅思带着不死军团攻入克雷斯特汉姆，皇家军团缚手难敌，王城一夜之间变为死城。有人认为，皇家中有“叛变者”向希默梅思泄露军情。一位秘密调查员根据仅存下来的皇家文献，锁定了十五个嫌疑人，并将这十五个人的资料编集为【古城末日“叛变者”档案】。档案中关于“叛变者”的真实身份并未明确提及，但从那些相关物品的信息中可寻得蛛丝马迹。档案详情在春楠那里可以复查。',NoSale=1,NoStorage=5,}",
  [53516] = "{id=53516,NameZh='毒药',Icon='item_5021',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23201,AdventureValue=98,AdventureReward={rewardid={870017}},Condition=64,Desc='【楔子】许多故事的开始，都是伴随着阴谋、凶杀、冤情、争斗。那天晚上，莫里茨公爵冰冷地躺在床上，脚边倒着一瓶毒药。',NoSale=1,NoStorage=5,}",
  [53517] = "{id=53517,NameZh='魔眼',Icon='item_7337',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23202,AdventureValue=98,AdventureReward={rewardid={870018}},Condition=64,Desc='【憎恶之书·公正】“是献出你的灵魂，还是让我夺走你朋友的生命，做出选择吧！”恶魔用它那似乎能洞察人类内心的眼睛，微笑着流露出狰狞的目光，对面前的驱魔人说道。卡伦赞德正是被这双魔眼所蛊惑。',NoSale=1,NoStorage=5,}",
  [53518] = "{id=53518,NameZh='符文',Icon='item_12004',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23203,AdventureValue=85,AdventureReward={rewardid={870019}},Condition=64,Desc='【憎恶之书·真相】驱魔人的符上，狂乱的字迹流露出书写者内心的挣扎与不安，是用力量维护公正，还是用力量解救落难的生命？驱魔人明亮的眼睛能看透黑暗，却看不透世间的正义。',NoSale=1,NoStorage=5,}",
  [53519] = "{id=53519,NameZh='钥匙',Icon='item_40011',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23204,AdventureValue=85,AdventureReward={rewardid={870020}},Condition=64,Desc='【恐惧之书·孤独】阴冷的监狱中，往往隐藏着禁忌、罪恶的故事。而用来开启它们的钥匙，就像是巫婆的苹果。至情至义的驱魔人知道这样做违背了法律与秩序，但他还是用钥匙打开了牢门，放走了他最好的朋友。',NoSale=1,NoStorage=5,}",
  [53520] = "{id=53520,NameZh='手铐',Icon='item_5042',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23205,AdventureValue=85,AdventureReward={rewardid={870021}},Condition=64,Desc='【恐惧之书·真相】牢房狭小的窗洞漏进清冷的月光，当骄傲的驱魔人失去自由之时，仿佛也失去了所有，包括自己存在的价值。链铐的响动在提醒着他犯下的错误。他无法向任何人倾诉苦衷，因为是他自己将自己推进了孤独的深渊。',NoSale=1,NoStorage=5,}",
  [53521] = "{id=53521,NameZh='粮食',Icon='item_12305',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23206,AdventureValue=85,AdventureReward={rewardid={870022}},Condition=64,Desc='【怯懦之书·仁慈】放置在我们眼前的普通食物，困苦的时候，它会比金子更珍贵渴求，而富裕之时，它却廉价得仿佛脚边的野草，随意可践踏忽视。',NoSale=1,NoStorage=5,}",
  [53522] = "{id=53522,NameZh='金币',Icon='item_105',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23207,AdventureValue=98,AdventureReward={rewardid={870023}},Condition=64,Desc='【怯懦之书·真相】金钱就像是这世间的一切诱惑，过度纵容，就会导致极端的后果。为了满足逐渐贪得无厌的卡伦赞德的要求，驱魔人放弃了一切，而这并没有带来善果。',NoSale=1,NoStorage=5,}",
  [53523] = "{id=53523,NameZh='书卷',Icon='item_42519',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23208,AdventureValue=85,AdventureReward={rewardid={870024}},Condition=64,Desc='【嫉妒之书·睿智】古列弗深爱书籍，他相信那是它最忠诚而值得信赖的朋友。因此，他有一颗博大精深的头脑，总是能想出绝妙的主意扭转乾坤。但这并没有给他带来好下场。智者千虑却必有一失。',NoSale=1,NoStorage=5,}",
  [53524] = "{id=53524,NameZh='冕冠',Icon='item_45046',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23209,AdventureValue=85,AdventureReward={rewardid={870025}},Condition=64,Desc='【嫉妒之书·真相】卡伦赞德的野心愈加庞大，最后，他看向了那顶璀璨的冕冠。华丽的外表下，早已是枯朽的灵魂。他泯灭了一切良善，冷酷无情得就像一个真正的恶魔。欲望的终点，往往是穷途末路。',NoSale=1,NoStorage=5,}",
  [53525] = "{id=53525,NameZh='利刃',Icon='item_40305',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23210,AdventureValue=98,AdventureReward={rewardid={870026}},Condition=64,Desc='【尾声】驱魔人行走在夜间，以狩猎魔鬼为职业的他，今晚要去狩猎一个真正的恶魔。他握着锋利的武器，内心默念：“卡伦赞德，你曾是我最重要的朋友，所以也必须由我来洗净你的罪孽。而我将背负罪孽，永生潜行在黑夜中。”',NoSale=1,NoStorage=5,}",
  [53526] = "{id=53526,NameZh='GLC.X114号档案',Icon='task_certificate',Type=63,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=23211,AdventureValue=143,AdventureReward={rewardid={870027}},Condition=64,Desc='记录了四个互为挚友并深受国王恩宠的驱魔人互相间打了一个赌，然而谁也没有真正在意这场赌局。但命运的嘲讽却悄然降临在他们身上，为了挽救他们的好友卡伦赞德，四人使用了不同的方法，却酿成了一场惨痛悲剧。档案详情在影子驱魔人那里可以复查。',NoSale=1,NoStorage=5,}",
  [53527] = "{id=53527,NameZh='初见的华尔兹',Icon='item_48545',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23301,AdventureValue=98,AdventureReward={rewardid={870028}},Condition=64,Desc='【第一乐章】假面舞会上的面具。它记录着桂瑟兰妮与加布里尔在假面之下开始的一段美丽华尔兹。初见之时，未知的一切，华丽的盛装，彼此的吸引，在富丽堂皇的舞池中相映生辉，童话一般的美好而浪漫。',NoSale=1,NoStorage=5,}",
  [53528] = "{id=53528,NameZh='玫瑰的踢踏舞',Icon='item_task_16',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23302,AdventureValue=98,AdventureReward={rewardid={870029}},Condition=64,Desc='【第二乐章】凋零的荆棘玫瑰。它被收藏在加布里尔的书桌右手边第一格抽屉中，制成了精巧的干花，夹在一本名为《梦中婚礼》的书中。当死讯传来之时，桂瑟兰妮亲手将它放进了加布里尔的遗棺中。',NoSale=1,NoStorage=5,}",
  [53529] = "{id=53529,NameZh='爱情的圆舞曲',Icon='item_40331',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23303,AdventureValue=98,AdventureReward={rewardid={870030}},Condition=64,Desc='【第三乐章】细长锋利的西洋剑。桂瑟兰妮收到这件礼物时，不知该夸赞将军心意别致还是叹息他不懂情调。很长一段时间，它都被挂在墙上当一件精致的装饰品，直到桂瑟兰妮把它拿下来，放到长眠的将军身边，并说：“谢谢你的守护。”',NoSale=1,NoStorage=5,}",
  [53530] = "{id=53530,NameZh='月光的小夜调',Icon='22',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23304,AdventureValue=98,AdventureReward={rewardid={870031}},Condition=64,Desc='【第四乐章】远方而来的战讯。“血色胜利”之战，王国军于险恶重重中获得艰难的胜利，战讯传至王城，桂瑟兰妮在侯爵府邸落下悲伤的眼泪，懊悔凝结在无声泪水中。',NoSale=1,NoStorage=5,}",
  [53531] = "{id=53531,NameZh='教堂的圣福音',Icon='item_52304',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23305,AdventureValue=98,AdventureReward={rewardid={870032}},Condition=64,Desc='【第五乐章】绅士的手帕。修道院中，忏悔的言语有谁在聆听？抑郁的容颜是为谁思念？绅士迈着轻轻的脚步靠近正在祈祷的女子身边，递出手帕款款温柔说：“请不要因为后悔而哭泣，它不适合你。我亲爱的桂瑟兰妮。”',NoSale=1,NoStorage=5,}",
  [53532] = "{id=53532,NameZh='王子的嘲笑声',Icon='item_52316',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23306,AdventureValue=98,AdventureReward={rewardid={870033}},Condition=64,Desc='【第六乐章】碎裂的镜子。王子在富丽堂皇的舞池中央丢下假面，戏谑嘲笑道：“来不及了，你这个贪心势利的女人。破镜永不能恢复原貌。”璀璨迷人的水晶灯光下，童话似乎就在眼前破碎，再不会有浪漫的华尔兹。',NoSale=1,NoStorage=5,}",
  [53533] = "{id=53533,NameZh='梦中的婚礼章',Icon='item_45198',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23307,AdventureValue=98,AdventureReward={rewardid={870034}},Condition=64,Desc='【第七乐章】枯黄的落叶。“如果，我不能在神父的面前吻你，幸福永不会降临在你我身上。”表达着如此爱意的人，在希默梅思的降临中，永远沉浸入梦中的婚礼。落叶带走生命的韵律。',NoSale=1,NoStorage=5,}",
  [53534] = "{id=53534,NameZh='GLC.E109号档案',Icon='task_certificate',Type=63,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=23308,AdventureValue=143,AdventureReward={rewardid={870035}},Condition=64,Desc='记录了克雷斯特汉姆古城灭亡前夕举行的一场盛大婚礼。桂瑟兰妮与加布里尔王子因偏见产生重重误会，又因爱而最终携手，然而就在婚礼举行之时，希默梅思降临，将一切美好带入了永不会醒来的梦境中。档案详情在墓地守夜人那里可以复查。',NoSale=1,NoStorage=5,}",
  [53535] = "{id=53535,NameZh='休密兹的王冠',Icon='item_task_25',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=23309,AdventureValue=117,AdventureReward={rewardid={870036}},Condition=64,Desc='暴君休密兹花费巨资打造的王冠，上面镶嵌着两种顶级的宝石，更有符文大师在其上铭刻符文，是无价之宝。',NoSale=1,NoStorage=5,}",
  [53536] = "{id=53536,NameZh='水晶残片',Icon='item_5026',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23117,AdventureValue=98,AdventureReward={rewardid={870037}},Condition=64,Desc='寄托着莫里森与盖妮爱情的留影水晶，随着盖妮的逝去，留影水晶中的能量也流逝殆尽，成为一片华贵的水晶残片。',NoSale=1,NoStorage=5,}",
  [53537] = "{id=53537,NameZh='导师资格证',Icon='task_certificate',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=22001,AdventureValue=108,AdventureReward={rewardid={870039}},Condition=64,Desc='由隶属于卢恩·米特加尔德王国的冒险者公会颁发，象征着责任和荣誉的导师资格证书，那么从今天起，可爱的初心者就交给你来教导了！',NoSale=1,NoStorage=5,}",
  [53538] = "{id=53538,NameZh='来自B格猫的贺卡',Icon='item_500510',Type=63,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=20201,AdventureValue=90,AdventureReward={rewardid={870038}},Condition=64,Desc='一份来自B格猫的新年贺卡嘿，冒险者们。新年的钟声敲响了，B格猫星人集体祝福大家新年快乐，鸡年大吉！ 这是我们一起过的第一个农历春节，2017年我们还想和大家一起过很多很多的节日。目前我们仍有很多不足，我们也在努力，努力与大家一同构筑这美好的大世界呀！感谢大家的支持与包容，送上一份小小心意，给你拜年啦！-----------<B格猫星球住民联名书写>',NoSale=1,NoStorage=5,}",
  [53539] = "{id=53539,NameZh='伏尔松格家徽',Icon='16',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=22901,AdventureValue=82,AdventureReward={rewardid={870040}},Condition=64,Desc='【星尘之光·晓】这是一个伟大的家族，它开启了史诗传奇，书写了英雄之歌，世间传唱着这个家族成员无数的美誉佳绩。然而就像创世神给这个世界定下的法则：没有任何东西是不会衰亡的。奥丁神给了这个家族启示，从此也在这个家族中埋下了火种，致使她一步步走向了灭亡。',NoSale=1,NoStorage=5,}",
  [53540] = "{id=53540,NameZh='希格尼的计谋',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=22902,AdventureValue=82,AdventureReward={rewardid={870041}},Condition=64,Desc='【星尘之光·暗】伏尔松格家族中最明亮的星，她的诞生仿佛就是为了给这个家族带来希望与变化。当家破人亡，她和哥哥沦陷于苦难中时，她不惜触犯不可原谅的禁忌罪恶，只为替深爱的家族手刃仇敌。美丽的外表下，她拥有一颗精于计算的头脑和坚贞的心，连她的哥哥西格蒙德也被她计算了。',NoSale=1,NoStorage=5,}",
  [53541] = "{id=53541,NameZh='辛菲奥特利之勇',Icon='item_42030',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=22903,AdventureValue=82,AdventureReward={rewardid={870042}},Condition=64,Desc='【星尘之光·耀】希格尼触犯禁忌生下的孩子，她期待着这个孩子长大成人后为家族复仇。尽管生来便背负着沉重的命运，但在母亲精心的教养下，他拥有人们穷尽想象力所能赋予的美好品格，是星尘之中最耀眼的那颗星。世间没有一种苦难，能令他感到害怕。',NoSale=1,NoStorage=5,}",
  [53542] = "{id=53542,NameZh='格拉姆神剑',Icon='item_40716',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=22904,AdventureValue=82,AdventureReward={rewardid={870043}},Condition=64,Desc='【星尘之光·武】奥丁留下的启示之剑。它的剑刃两面，一面刻着“博爱之仁”，相传由它的第一任主人西格蒙德所刻，它帮助伏尔松格家族手刃了仇敌，使这个家族在绝境中重生；另一面刻着“正义之威”，相传由它的第二任主人希格尔德重铸这把剑时所刻，但这一次，它却为它的主人招来了厄运。希格尔德在睡觉时将它置于自己和爱人之间，令他的爱人布伦希尔德产生了误会。',NoSale=1,NoStorage=5,}",
  [53543] = "{id=53543,NameZh='古德露恩的爱意',Icon='item_52702',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=22905,AdventureValue=82,AdventureReward={rewardid={870044}},Condition=64,Desc='【星尘之光·爱】古德露恩的出现让希格尔德开始走向悲剧的命运。在魔法药水的控制下，她得到了希格尔德的妻子之名，却始终没有得到希格尔德的真心。虚幻的爱情，注定了他们的婚姻不会有好结局。',NoSale=1,NoStorage=5,}",
  [53544] = "{id=53544,NameZh='布伦希尔德火焰',Icon='item_47018',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=22906,AdventureValue=82,AdventureReward={rewardid={870045}},Condition=64,Desc='【星尘之光·焰】布伦希尔德是一名瓦尔基里。世间有许多歌谣传唱着她与希格尔德的凄美爱情，那些歌词叙述了即便奥丁在布伦希尔德身周设下烈火，也无法阻止希格尔德冲破火焰与布伦希尔德相爱。只是爱情的开端虽浪漫美好，终敌不过岁月的磨砺。',NoSale=1,NoStorage=5,}",
  [53545] = "{id=53545,NameZh='希格尔德之死',Icon='item_task_20',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=22907,AdventureValue=82,AdventureReward={rewardid={870046}},Condition=64,Desc='【星尘之光·陨】死于暗杀者之手的希格尔德，恐怕没有想到自己会因爱情而引来杀身之祸。在临终前，他终于醒悟到了布伦希尔德的自私。他用微弱的气息安慰着在他身边哭泣的妻子古德露恩，然后咽下了最后一口气。生与死，从来无法做第二次选择。伏尔松格家族因爱而崛起，也因爱而陨落。',NoSale=1,NoStorage=5,}",
  [53546] = "{id=53546,NameZh='尼伯龙根指环',Icon='item_40017',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=22908,AdventureValue=82,AdventureReward={rewardid={870047}},Condition=64,Desc='【星尘之光·惑】佩戴在漆黑部队首领左手食指上的指环，它曾经是希格尔德与古德露恩的订婚戒指。从英灵殿归来，它将追随它的主人统御龙族。',NoSale=1,NoStorage=5,}",
  [53547] = "{id=53547,NameZh='GLC.A014号档案',Icon='task_certificate',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=22909,AdventureValue=113,AdventureReward={rewardid={870048}},Condition=64,Desc='又名“星尘档案”。它记录着隐匿于龙谷中的神秘组织“漆黑部队”的来历。这些以女武神头盔为标识的战士，曾经都是《尼伯龙根指环》史诗中的英雄人物，他们从英灵殿返回人间，守护着龙谷，行踪神秘。犹如星尘，用微光照亮黑暗。',NoSale=1,NoStorage=5,}",
  [53548] = "{id=53548,NameZh='腐烂的骨骼',Icon='item_53548',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23516,AdventureValue=85,AdventureReward={rewardid={870074}},Condition=64,Desc='古尔顿有着令人羡慕的体质，他丝毫不受瘟疫的影响，国王得知后，请求古尔顿能够舍生取义，成为救王国于瘟疫之中的大英雄，古尔顿答应了。数名大魔法师用魔法抽取瘟疫，尽数注入到古尔顿的身体之中。',Level=0,NoSale=1,NoStorage=5,}",
  [53549] = "{id=53549,NameZh='肮脏的花冠',Icon='item_53549',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23517,AdventureValue=85,AdventureReward={rewardid={870075}},Condition=64,Desc='在古尔顿被王国赶出城市后，卡丽莎不辞辛苦的找到古尔顿，质问古尔顿是否抛弃了她，当他看到古尔顿身上令人作呕的瘟疫时，才明白了一切。',Level=0,NoSale=1,NoStorage=5,}",
  [53550] = "{id=53550,NameZh='国王的权杖',Icon='item_53550',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23519,AdventureValue=98,AdventureReward={rewardid={870077}},Condition=64,Desc='国王的反应让古尔顿失望透顶，他摘下了自己的面具，瘟疫瞬间夺取了国王与事务官的生命，他知道他的好友凯莱尔就在他身边，他的仇已经报了，卡丽莎的死去对他打击很大，他哀求着凯莱尔给予他致命的一击…',Level=0,NoSale=1,NoStorage=5,}",
  [53551] = "{id=53551,NameZh='破损的绞绳',Icon='item_53551',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23518,AdventureValue=85,AdventureReward={rewardid={870076}},Condition=64,Desc='卡丽莎从古尔顿的小屋中离开，没想到王国事务官已经在门口等待着她，事务官以怀疑她身上携带着瘟疫为由，对卡丽莎实施了绞刑。',Level=0,NoSale=1,NoStorage=5,}",
  [53552] = "{id=53552,NameZh='GLC.X157号档案',Icon='task_certificate',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=23520,AdventureValue=117,AdventureReward={rewardid={870078}},Condition=64,Desc='一场突如其来的瘟疫，改变了古尔顿的一生。古尔顿拥有对瘟疫的超强抵抗力，这使得他成为解决这次灾难的唯一人选，于是王国利用超魔导士的力量，把几乎所有的瘟疫都集中在古尔顿身上。古尔顿攒钱给卡丽莎制作了花冠，古尔顿的心情无疑是非常开心的。但是好景不长，古尔顿身患瘟疫，不得不从人口密集的城市中搬出来。卡丽莎锲而不舍得找寻着古尔顿，终于在城外的密林处找到了他。古尔顿惊恐着，让卡丽莎不要过来，但是卡丽莎却毫不在意…好人难得好报，古尔顿看错了人心。当危险过后，人们会把所有危险都扼杀在摇篮里，生怕自己再受到伤害，人就是这样的生物。当卡丽莎在绞刑架上大声斥责时，这些冷漠的人对此毫无羞愧之心。而大部分民众也是在冷眼旁观，甚至拍手称快。卡丽莎的逝去对古尔顿造成了相当大的打击。古尔顿选择了报复，而这报复又在情理之中。他释放了自己瘟疫，经过压抑的瘟疫爆发起来更加凶残。顷刻之间国王与王国事务官便双双毙命。事情的最后他让他的挚友凯莱尔带走了他的生命，使瘟疫从此消失。',Level=0,NoSale=1,NoStorage=5,}",
  [53553] = "{id=53553,NameZh='古尔顿的日记[1]',Icon='item_3002',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23512,AdventureValue=98,AdventureReward={rewardid={870070}},Condition=64,Desc='一个名叫古尔顿的日记，短短几页的纸张记载着骇人听闻的瘟疫爆发事件。古尔顿的友人在这场瘟疫中去世，古尔顿怀疑这次瘟疫的爆发是因为他们曾在下水道工作，被蓝鼠袭击造成的。',Level=0,NoSale=1,NoStorage=5,}",
  [53554] = "{id=53554,NameZh='古尔顿的日记[2]',Icon='item_3002',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23513,AdventureValue=98,AdventureReward={rewardid={870071}},Condition=64,Desc='一个名叫古尔顿的日记，短短几页的纸张记录着与一位名叫卡丽莎的女孩在一起的愉快时光，在卡丽莎的生日到来之际，他精心准备着自己的礼物，想象着未来两人的幸福生活，而愉快的时光总是短暂的……',Level=0,NoSale=1,NoStorage=5,}",
  [53555] = "{id=53555,NameZh='古尔顿的日记[3]',Icon='item_3002',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23514,AdventureValue=98,AdventureReward={rewardid={870072}},Condition=64,Desc='卡丽莎已经很久没有来看望城外的古尔顿了，这使得古尔顿异常伤心，古尔顿决心去质问卡丽莎究竟发生了什么，却得到了一个令他无法接受的消息。',Level=0,NoSale=1,NoStorage=5,}",
  [53556] = "{id=53556,NameZh='古尔顿的日记[4]',Icon='item_3002',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23515,AdventureValue=85,AdventureReward={rewardid={870073}},Condition=64,Desc='古尔顿决心要报复，他放弃携带友人送给他可以抑制瘟疫的面具，他决心要让那些恶毒的伪善者尝尝死亡的恐惧。',Level=0,NoSale=1,NoStorage=5,}",
  [53557] = "{id=53557,NameZh='皇室徽章（暴食者）',Icon='item_60002',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23521,AdventureValue=98,AdventureReward={rewardid={870079}},Condition=64,Desc='二王子殿下失踪之后，王宫附近出现了一个诅咒魔人，与他近距离接触的人们都遭受到了诅咒，那些民众变成了暴食的魔物，这让大王子下定了决心，无论这个诅咒魔人与二王子殿下有什么联系，都一定要消灭他！大王子的最忠贞的骑士代顿带着命令出发…',Level=0,NoSale=1,NoStorage=5,}",
  [53558] = "{id=53558,NameZh='皇室徽章（腐朽者）',Icon='item_60003',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23522,AdventureValue=98,AdventureReward={rewardid={870080}},Condition=64,Desc='三王子殿下失踪了，于此同时，王宫附近出现了一个诅咒魔人，任何他去过的地方，所有物品都将腐朽，民众们的血汗钱从此化为尘埃，爱民如子的大王子当然不会允许这种事情发生，他命令骑士代顿一定要解除民众的苦痛…',Level=0,NoSale=1,NoStorage=5,}",
  [53559] = "{id=53559,NameZh='皇室徽章（争斗者）',Icon='item_60005',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23523,AdventureValue=98,AdventureReward={rewardid={870081}},Condition=64,Desc='诅咒魔人出现了，他的诅咒带来了一次次争斗，王都因为魔人的诅咒，流血事件不断发生，大王子决定让骑士代顿惩治这个邪恶的魔人，而大王子才发现，自己的四弟出门狩猎已经许久没有消息传出来了…',Level=0,NoSale=1,NoStorage=5,}",
  [53560] = "{id=53560,NameZh='伪善者的假面',Icon='item_48554',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23524,AdventureValue=85,AdventureReward={rewardid={870082}},Condition=64,Desc='当仅剩的五王子逃出了皇宫，大王子对外宣称发现第四位诅咒魔人，再次命令骑士代顿前往消灭五王子，然而对大王子产生疑心的代顿并没有第一时间消灭所谓的诅咒魔人。五王子告知代顿，他的三位哥哥都是死于大王子的阴谋。代顿曾经手刃三位王子，代顿已经违背了自己的骑士精神，他决定要为自己的罪行负责，但是再此之前，他还有事情要做…',Level=0,NoSale=1,NoStorage=5,}",
  [53561] = "{id=53561,NameZh='心中的魔鬼',Icon='item_52507',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23525,AdventureValue=98,AdventureReward={rewardid={870083}},Condition=64,Desc='权力是魔鬼，大王子被魔鬼所诱惑，陷害了三位王子，而他的恶行终于被自诩正义的骑士代顿发现了，代顿无法原谅这样的自己，也无法理解效忠的王子，他明白，大王子一旦继承王位，这对国家来说并不是好事，他决定违背骑士精神的最后一条——忠诚！大王子死后，代顿带回被他藏起来的五王子，告诫五王子，权力是每人心中的恶魔，一定要战胜这个魔鬼！得到五王子承诺的代顿在这大厅自刎结束了自己的一生。',Level=0,NoSale=1,NoStorage=5,}",
  [53562] = "{id=53562,NameZh='GLC.X163号档案',Icon='task_certificate',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=23526,AdventureValue=117,AdventureReward={rewardid={870084}},Condition=64,Desc='王宫的二王子离奇失踪后，王都出现了一个名为“暴食者”的诅咒魔人。骑士代顿奉大王子的命令前去讨伐。不久后，三王子殿下失踪了，与此同时，王宫附近出现了一个诅咒魔人，名为“腐朽者”。爱民如子的大王子绝对不会允许他为祸王都，骑士代顿再次奉命讨伐。接着诅咒魔人“争斗者”出现了，他的诅咒带来了一次次争斗，王都因为魔人的诅咒，流血事件不断发生。大王子决定让骑士代顿惩治这个邪恶的魔人，而与此同时，四王子出门狩猎已经许久没有消息传出来了。大王子对外宣称发现第四位诅咒魔人，再次命令骑士代顿前往消灭诅咒魔人。代顿这才知道，这一切，都是大王子为了继承王位所使的阴谋。对大王子产生疑心的代顿并没有第一时间消灭所谓的诅咒魔人。五王子告知代顿，他的三位哥哥都是死于大王子的阴谋。权力是魔鬼，大王子被魔鬼所诱惑，陷害了三位王子，代顿作为大王子手中的利剑，自然有着无法推卸的责任。代顿决定背叛自己所信奉的骑士精神——忠诚！为了维护自己心中的正义，他要杀死大王子！大王子死后，代顿带回被他藏起来的五王子，告诫五王子，权力是每个人心中的恶魔，一定要战胜这个魔鬼！五王子含泪答应了代顿的请求，而代顿在这大厅自刎结束了自己的一生。',Level=0,NoSale=1,NoStorage=5,}",
  [53563] = "{id=53563,NameZh='米莫斯的战袍',Icon='item_43020',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=23401,AdventureValue=117,AdventureReward={rewardid={870049}},Condition=64,Desc='“米莫斯知道为了守护自己重要的人，只有做好恶性结局的打算，不沮丧逃避，以自己的力量勇往直前，战斗不止！”',Level=80,NoSale=1,NoStorage=5,}",
  [53564] = "{id=53564,NameZh='艾琳娜丝的四叶草',Icon='item_52302',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23402,AdventureValue=98,AdventureReward={rewardid={870050}},Condition=64,Desc='“没想到在这里也能找到四叶草，我上一次见到还是在家乡的南部森林里找到的，真的超兴奋呢！对了，我今天看到苏米娜偷偷的买了紫色的染料，难道她也想把头发染成和我一样的颜色？真讨厌呢，我最不喜欢别人学我了”-艾琳娜丝',Level=80,NoSale=1,NoStorage=5,}",
  [53565] = "{id=53565,NameZh='亚米拉的入团日记',Icon='item_3608',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23403,AdventureValue=98,AdventureReward={rewardid={870051}},Condition=64,Desc='“这些盔甲虽然看上去很笨重，但是我还是相信它会保护我，保护这座城堡，那么亚米拉，加油吧！”-亚米拉',Level=80,NoSale=1,NoStorage=5,}",
  [53566] = "{id=53566,NameZh='苏米娜的染料',Icon='item_12104',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23404,AdventureValue=98,AdventureReward={rewardid={870052}},Condition=64,Desc='“训练时站在我前排的艾琳娜丝真特别，尤其是她的紫色头发，虽然平日里天天需要带着头盔，不过我还是想找个时间把头发也染成紫色”-苏米娜',Level=80,NoSale=1,NoStorage=5,}",
  [53567] = "{id=53567,NameZh='艾思丽的徽章',Icon='item_52319',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23405,AdventureValue=98,AdventureReward={rewardid={870053}},Condition=64,Desc='“白骑士团的哈维队长昨天送了这个徽章给我，有点小兴奋呢，虽然我料到他会有所表示，但是这突如其来的惊喜还是有点让我手足无措呢”。',Level=80,NoSale=1,NoStorage=5,}",
  [53568] = "{id=53568,NameZh='灵魂印记',Icon='item_task_07',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23406,AdventureValue=98,AdventureReward={rewardid={870054}},Condition=64,Desc='在神使现身克雷斯特汉姆之前就有一些神智奇特的战士陷入了疯狂，艾里维奇便是其中之一，在众人协力击溃了他的时候，有一位炼金术师使用贤者之石将他的灵魂捆绑在了他的盔甲里，从此后“艾里维奇”成了一副只会守卫城堡的疯剑士。',Level=80,NoSale=1,NoStorage=5,}",
  [53569] = "{id=53569,NameZh='未送出手的情书',Icon='item_task_34',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23407,AdventureValue=98,AdventureReward={rewardid={870055}},Condition=64,Desc='柯雷罗在刚刚来到克雷斯特汉姆时就爱上了一位姑娘，在得知了她是一名皇室公主后，放下了表白的念头，而手中的书信似乎也永远送不出手了。',Level=80,NoSale=1,NoStorage=5,}",
  [53570] = "{id=53570,NameZh='金箭',Icon='item_task_35',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23408,AdventureValue=98,AdventureReward={rewardid={870056}},Condition=64,Desc='克雷斯特汉姆中有名的工匠设计出的金色箭矢，在著名游侠奥兹玛手中大放光彩。在黑暗魔物侵袭之战中，奥茨玛带着他心爱的金箭，深入黑暗魔物的领地寻找魔物头领，从此再也没有他的消息。',Level=80,NoSale=1,NoStorage=5,}",
  [53571] = "{id=53571,NameZh='诅咒魔弓',Icon='item_41217',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23409,AdventureValue=98,AdventureReward={rewardid={870057}},Condition=64,Desc='艾克林曾经希望自己成为一名真正的魔法师，他并没有天赋，所幸艾克林有一手好箭术，日子还算过得下去。直到某次探险，艾克林得到了一把魔弓，可以在弓箭上施加强大的魔法，艾克林欣喜若狂。每次使用魔弓的力量，艾克林的灵魂就会被魔弓吸取一点，直到某天艾克林成为了没有灵魂的行尸走肉，诅咒魔弓之名也随着艾克林的逝去而流传开来。',Level=80,NoSale=1,NoStorage=5,}",
  [53572] = "{id=53572,NameZh='无形箭',Icon='item_12503',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=23410,AdventureValue=117,AdventureReward={rewardid={870058}},Condition=64,Desc='此箭早已存在，只是无形、无迹，箭矢早已存于天地间，只等待时机凝聚起来，只到国难当头的那一刻，任何勇士只要心中有勇气都能射出此箭。',Level=80,NoSale=1,NoStorage=5,}",
  [53573] = "{id=53573,NameZh='妖气',Icon='item_47018',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23501,AdventureValue=98,AdventureReward={rewardid={870059}},Condition=64,Desc='村正曾在名师手下学习剑道，却因为师傅偏爱自己的师兄嫉火中烧，误入歧途亲手杀害了自己的师傅和师兄后，因为愧疚切腹，含恨化作一股凌冽的妖气。',Level=80,NoSale=1,NoStorage=5,}",
  [53574] = "{id=53574,NameZh='蛇鳞',Icon='item_52315',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23502,AdventureValue=98,AdventureReward={rewardid={870060}},Condition=64,Desc='古城中曾有一条无恶不作的八歧大蛇，在城中掳走妇女和儿童作为它的口中食粮，终于触犯了天神，天神赐给城中最勇敢的战士一把天业云剑去讨伐这条大蛇，将其削皮拔骨，并取其蛇鳞来祭奠被大蛇迫害的无辜的城民们。',Level=80,NoSale=1,NoStorage=5,}",
  [53575] = "{id=53575,NameZh='国纲的印记',Icon='item_task_07',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23503,AdventureValue=98,AdventureReward={rewardid={870061}},Condition=64,Desc='古时，有个有名的盗贼拥有一件神奇的羽衣，披上羽毛即变成鸟，脱下羽毛就能现身。如果那个富豪的家庭的防卫没做到位。，那么一旦被他所发现，就会在窗台上留下两滴血作为目标印记。',Level=80,NoSale=1,NoStorage=5,}",
  [53576] = "{id=53576,NameZh='须佐之男的思念',Icon='item_52408',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23504,AdventureValue=98,AdventureReward={rewardid={870062}},Condition=64,Desc='古城战火四溢时，须佐之男将一把十握剑交给妻子防身后便出门从军去了，战后回到家中发现妻子因为重病还是去世了，一想到自己在妻子病重时不能守护在左右后悔莫及，只留下当初那帮十握剑孤独的靠在房角。',Level=80,NoSale=1,NoStorage=5,}",
  [53577] = "{id=53577,NameZh='八犬士的勇气',Icon='27',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23505,AdventureValue=98,AdventureReward={rewardid={870063}},Condition=64,Desc='灾难之神降下灾祸，使古城生灵涂炭，提出要求将八位壮汉的灵魂交出才能平息灾难，国王发下昭示派了城中八位威武勇猛的士兵，这八位士兵明知自己将会有去无回，还是毅然决然的决定为了城中的百姓牺牲自己。国王为了纪念他们修建了八座雄伟的石碑取名为八犬士的勇气。',Level=80,NoSale=1,NoStorage=5,}",
  [53578] = "{id=53578,NameZh='生命魔剑',Icon='item_40736',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=23506,AdventureValue=117,AdventureReward={rewardid={870064}},Condition=64,Desc='生命魔剑是一柄有战斗欲望的剑，剑拔出来之后如果不沾血就不可以入鞘。剑 的拥有者必须尊重剑的意愿，不然魔剑就会背叛主人、任意杀戮。',Level=0,NoSale=1,NoStorage=5,}",
  [53579] = "{id=53579,NameZh='权利',Icon='item_task_25',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23507,AdventureValue=98,AdventureReward={rewardid={870065}},Condition=64,Desc='代表元素火，象征激情、能量和创造。',Level=80,NoSale=1,NoStorage=5,}",
  [53580] = "{id=53580,NameZh='星币',Icon='item_task_22',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23508,AdventureValue=98,AdventureReward={rewardid={870066}},Condition=64,Desc='代表元素土，象征金钱、物质和享受。',Level=80,NoSale=1,NoStorage=5,}",
  [53581] = "{id=53581,NameZh='圣杯',Icon='item_12328',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23509,AdventureValue=98,AdventureReward={rewardid={870067}},Condition=64,Desc='代表元素水，象征情感、关系、爱和灵感。',Level=80,NoSale=1,NoStorage=5,}",
  [53582] = "{id=53582,NameZh='宝剑',Icon='item_40336',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23510,AdventureValue=98,AdventureReward={rewardid={870068}},Condition=64,Desc='代表元素风，象征思想、智慧、交流和冲突。',Level=80,NoSale=1,NoStorage=5,}",
  [53583] = "{id=53583,NameZh='命运纸牌',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=23511,AdventureValue=117,AdventureReward={rewardid={870069}},Condition=64,Desc='过去有位通晓过去未来的魔法师，却得不到国王的器重，预言了古城的毁灭后居然还惨遭王国的追杀，他悲愤的留下一张命运的纸牌后就消失了，再也没人见过他的行踪。',Level=80,NoSale=1,NoStorage=5,}",
  [53584] = "{id=53584,NameZh='《古城轶事》',Icon='item_42519',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23527,AdventureValue=98,AdventureReward={rewardid={870085}},Condition=64,Desc='一位名叫切尔西的人撰写的书籍，上面详细的记载了切尔西和女伴妮卡在受到魔物袭击时，一位“黑武士”出面救下了他的全过程。后来被切尔西记载，“黑武士”之名由此广为传播。',Level=0,NoSale=1,NoStorage=5,}",
  [53585] = "{id=53585,NameZh='生锈的铁戒',Icon='item_44012',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23528,AdventureValue=98,AdventureReward={rewardid={870086}},Condition=64,Desc='仰慕“黑武士”之名的战斗狂人阿尔顿斯带着他心爱的剑戒——铁牙挑战“黑武士”，在“黑武士”的进攻之下，阿尔顿斯毫无还手之力，剑戒铁牙也在战斗中分离。',Level=0,NoSale=1,NoStorage=5,}",
  [53586] = "{id=53586,NameZh='断裂的项链',Icon='item_44004',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23529,AdventureValue=98,AdventureReward={rewardid={870087}},Condition=64,Desc='爱德华送给妮卡的项链，在一次魔物袭击中断裂，爱德华独自引开魔物，使得妮卡成功逃离了魔物的包围，但是爱德华再也没有回来。',Level=0,NoSale=1,NoStorage=5,}",
  [53587] = "{id=53587,NameZh='黑暗心核',Icon='dark_001',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23530,AdventureValue=85,AdventureReward={rewardid={870088}},Condition=64,Desc='慌不择路逃命的爱德华来到了一处洞穴，洞穴中似乎有什么在威慑着那些魔物，它们不敢靠近洞穴。爱德华不断深入洞穴，发现了一具巨大的尸体，在尸体中找到了一颗散发着迷人香气的心核，爱德华在饥饿的煎熬下，吃下了这颗心核，整个人发生了巨大的变化。成为了拥有神秘黑暗力量的人类。',Level=0,NoSale=1,NoStorage=5,}",
  [53588] = "{id=53588,NameZh='黑武士徽章',Icon='item_42512',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23531,AdventureValue=85,AdventureReward={rewardid={870089}},Condition=64,Desc='爱德华成为了黑武士后，妮卡的项链在他的黑暗力量浸染下成为了他独特的黑暗武士徽章。他认为光明与黑暗只在一念之间，他拥有黑暗力量，但他的心却向往着光明。在黑暗生物的进攻战役中完成了他的使命，而黑暗武士徽章成为了他唯一存在过的证据。',Level=0,NoSale=1,NoStorage=5,}",
  [53589] = "{id=53589,NameZh='GLC.X185号档案',Icon='task_certificate',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=23532,AdventureValue=117,AdventureReward={rewardid={870090}},Condition=64,Desc='遭遇袭击的爱德华带着不死的魔物来到了一处隐蔽的洞穴，在这里，他找到了一个黑暗心核，借此他脱离了险境，代价是失去了自己的容貌，以及寿命。他是骑士，尽管他身上充斥着黑暗的力量，但是他坚持认为，光明与黑暗只在一念之间。只有邪恶的人，没有邪恶的力量。他决定用这股力量去帮助需要帮助的人，以及…暗中守护着他的爱人。在黑暗魔物大举入侵的最终时刻，黑骑士爱德华用自己所有的力量以及生命，消灭了魔物的头领。他的爱人妮卡最后认出了他的身份，但是逝去的，终究是逝去了…',Level=0,NoSale=1,NoStorage=5,}",
  [53590] = "{id=53590,NameZh='恶魔微笑',Icon='item_60009',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23533,AdventureValue=98,AdventureReward={rewardid={870091}},Condition=64,Desc='一个神奇的宝珠，拥有将一切心智不坚定的人诱惑并且堕落黑暗的魔力，经过恶魔长时间的孕育，威力越来越强大，但是在没有黑暗力量却又心智坚定的人手中却只能被当作珍藏品。',Level=80,NoSale=1,NoStorage=5,}",
  [53591] = "{id=53591,NameZh='莫特利之剑',Icon='item_40736',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23534,AdventureValue=98,AdventureReward={rewardid={870092}},Condition=64,Desc='传说勇者莫特利所持有的武器，跟随莫特利挑战过诸多魔物，根据关于莫特利的记载，莫特利最后一次前往挑战了强大的凯美拉。',Level=80,NoSale=1,NoStorage=5,}",
  [53592] = "{id=53592,NameZh='血咒',Icon='dark_004',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23535,AdventureValue=98,AdventureReward={rewardid={870093}},Condition=64,Desc='如同血色一般，充满诅咒力量的宝石，是德古拉男爵最为喜爱的宝石。通常德古拉男爵在吸完血液后，会滴上一滴人血浸染宝石，日积月累之下，这颗名为血咒的宝石显得更加妖邪。',Level=80,NoSale=1,NoStorage=5,}",
  [53593] = "{id=53593,NameZh='天国之门',Icon='item_task_12',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23536,AdventureValue=98,AdventureReward={rewardid={870094}},Condition=64,Desc='传说看守奥丁神殿之门的兰特克力斯所拥有，奥丁赐予他自由来往神殿与俗世的传送石，但是在诸神的黄昏之后，这天国之门失去了往日的魔力。',Level=80,NoSale=1,NoStorage=5,}",
  [53594] = "{id=53594,NameZh='永恒之翼',Icon='item_47004',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=23537,AdventureValue=117,AdventureReward={rewardid={870095}},Condition=64,Desc='传说是由诸神黄昏中战死的女武神背后双翼所化，象征着永恒以及神话，直到今日，上面还存着些许女武神圣洁的魔力。',Level=80,NoSale=1,NoStorage=5,}",
  [53595] = "{id=53595,NameZh='陈旧的手札',Icon='item_task_45',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23701,AdventureValue=85,AdventureReward={rewardid={870096}},Condition=64,Desc='不知名的古老手札，封面的纸张已经有些泛黄，好像在诉说着它的久远年代。翻开手札，里面有这样一段文字：“亚尔林这个小子最近可真是卖力啊，就连骑士团的奥德里奇队长都对他另眼相看，不过他的脾气确实好得出奇，无论我们怎么捉弄他都不会生气，看来我们以后要对他好一点了。哎，钟楼终于快要建成了，这个时候千万别出什么意外才好”。',NoSale=1,NoStorage=5,}",
  [53596] = "{id=53596,NameZh='破裂的铠甲',Icon='item_task_43',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23702,AdventureValue=98,AdventureReward={rewardid={870097}},Condition=64,Desc='当邪恶的死灵军团从天而降，奥德里奇队长指挥着骑士们列阵迎敌，激烈的战斗席卷了钟楼里的每个角落，英勇的王国勇士们不断倒在了血泊里，又不断从恶魔们的身上碾压了过去。',NoSale=1,NoStorage=5,}",
  [53597] = "{id=53597,NameZh='亡者的号角',Icon='item_task_40',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23703,AdventureValue=85,AdventureReward={rewardid={870098}},Condition=64,Desc='一道迅捷的身影在凄美的夜色下，悄悄潜入了黑暗的深渊，深渊里的恶魔争相向他咆哮着，亡者的灵魂视他为腹中的美餐，但他却旁若无人地行走着，口中的言语响彻云表：“亡者的女武神啊，我愿意做你最忠心的仆人，如果你正感到踌躇不决，那么我可以为你指明方向。”',NoSale=1,NoStorage=5,}",
  [53598] = "{id=53598,NameZh='锈蚀的铁锤',Icon='item_task_41',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23704,AdventureValue=98,AdventureReward={rewardid={870099}},Condition=64,Desc='当工人们在钟楼的地下发现一块伊米尔之心碎片后，扩散的巨人力量带来了异变的强大魔物，善良的亚尔林为了拯救同伴倒在了魔物的爪牙之下，所幸随行的骑士团卫队及时赶来消灭了魔物，这才避免了更大的伤亡。骑士团取走了伊米尔之心碎片，看样子他们是准备把它进献给王国，可背地里工人们都带着扼腕的语气说这块古怪的碎片将会带来更大的灾难，亚尔林的死亡是白白便宜了其他人。',NoSale=1,NoStorage=5,}",
  [53599] = "{id=53599,NameZh='锋利的匕首',Icon='item_task_42',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=23705,AdventureValue=117,AdventureReward={rewardid={870100}},Condition=64,Desc='嗜血的锋利匕首。当年轻的亚尔林被嘲笑是没用的废物和被遗弃的野种时，他感到了莫大的耻辱，而这耻辱必须以鲜血来洗净。在一个平静的夜晚，他用自己磨制多时的锋利匕首结束了辱人者的生命，从此在大陆上到处流浪，没人知道他的来历，也从没人真正地了解他。',NoSale=1,NoStorage=5,}",
  [53600] = "{id=53600,NameZh='隐匿的面具',Icon='item_task_44',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=23706,AdventureValue=117,AdventureReward={rewardid={870101}},Condition=64,Desc='当所有人都以为亚尔林死于狂暴的魔物之手时，他却神鬼不知地出现在惨烈的战场上，趁着胶着的战斗悄悄取走了伊米尔之心碎片。他渴望成为万众瞩目的强者，而伊米尔之心蕴含的强大能量正是他需要的。',NoSale=1,NoStorage=5,}",
  [53601] = "{id=53601,NameZh='钟楼异闻录·毁灭卷',Icon='task_53601',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=23707,AdventureValue=117,AdventureReward={rewardid={870102}},Condition=64,Desc='亚尔林无疑是一个悲惨的小人物，过去无情的嘲笑和无尽的羞辱使他变得沉默阴狠，他渴望得到强大的力量来改变现状，这种急切的渴望驱使着他做出了一些不可思议的事情。当建筑工人们在钟楼里挖掘出一块伊米尔之心碎片时，古怪的碎片带来了强大的异变魔物，也带给了亚尔林心中无尽的希望。亚尔林精心设计了一个骗局，当工人们都以为他是一个被魔物杀死的悲惨家伙时，他却死而复生地戴上隐匿的面具，行走在黑暗的深渊里。深渊里的恶魔争相向他咆哮着，亡者的灵魂视他为腹中的美餐，但他却旁若无人地行走着，从他口中传出的声音清晰可闻，“亡者的女武神啊，我愿意做你最忠心的仆人，如果你正感到踌躇不决，那么我可以为你指明方向。”他利用了精明的希默梅思，当亡者的大军在黑夜里出征，亚尔林则脱下隐匿的面具安静地等待着即将收获的果实。自私的奥德里奇和贪婪的希默梅思被欲望蒙蔽了双眼，他们只看到眼前的对手，却忽略了隐藏的敌人。潜伏的亚尔林轻易混入了激斗的人群，在混乱中神鬼不知地取走了伊米尔之心碎片，这不仅让愤怒的希默梅思无功而返，也让奥德里奇陷入了无尽的自责之中。这真是一个完美的计划，亚尔林的隐忍和毒辣终于使他如愿以偿。但令人惋惜的是，亚尔林并没有成为最后的赢家。当他面对梦寐以求的神奇碎片时，他的内心并没有感到安稳，反而强大的巨人力量使他慢慢产生异变，这让他备受煎熬。他在内心质问自己，如果变成了一个人人唾弃的魔物，这一切的努力还有什么意义？沉重的压力和心理的落差使他不堪重负，他可以为了强大的力量变得冷漠阴狠，也可以为了强大的力量毁灭一切。当磅礴的力量从指尖划过，这一刻他彻底释放了心中的压抑。狂暴的巨人力量席卷了钟楼的每个角落，也给每个彷徨的生命画上了句点。这是一个悲惨的故事，当那块古怪的碎片被工人们发现时，他们的命运就已经无法改变了。',NoSale=1,NoStorage=5,}",
  [53602] = "{id=53602,NameZh='损坏的怀表',Icon='item_task_31',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=23804,AdventureValue=117,AdventureReward={rewardid={870106}},Condition=64,Desc='耶梦加得使钟楼内的魔物变得更加强大，它们不断逼迫着守护者远离黄金时钟，只有这样耶梦加得才能利用黄金时钟内的伊米尔之心来加速产生时空的异变。此刻这神秘的空间里，激烈碰撞的时空乱流在伊米尔之心的支配下不断塑造着时空的规则，任何陷入这片时空的人都会不由自主地被卷入时间的漩涡，从而永远地从这个世界消失。吉伯特看了看手里已经停止转动的怀表，他终于明白，如果要离开这片平行的空间，那就只能去阻止耶梦加得的阴谋！',NoSale=1,NoStorage=5,}",
  [53603] = "{id=53603,NameZh='失灵的指针',Icon='item_task_36',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23803,AdventureValue=85,AdventureReward={rewardid={870105}},Condition=64,Desc='平行的时空里，吉伯特和探险队找遍了钟楼的每个角落，但令人疑惑的是，这里没有嗜血的魔物，也没有扭曲的时空力量，一切都是那么正常，所谓的异变似乎只是一场失控的谣传。吉伯特看了看手中紧握的指针，此刻的他已经有了决定，艾尔帕兰的人们需要知道事情的真相！',NoSale=1,NoStorage=5,}",
  [53604] = "{id=53604,NameZh='破旧的皮衣',Icon='item_42017',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23802,AdventureValue=85,AdventureReward={rewardid={870104}},Condition=64,Desc='平行的时空里，吉伯特惊恐地看着一个又一个的队友倒在自己的身旁，他没想到仅仅是因为自己的一个疏忽竟然引起了成群魔物的围攻，此刻的他已经精疲力竭，望着身上皮衣上的斑驳血迹，心中的无力感尤为强烈，而最令他震惊的却是那些从血泊里爬起来的同伴们，此刻已经变成了狰狞的魔物，正争相向他咆哮着……',NoSale=1,NoStorage=5,}",
  [53605] = "{id=53605,NameZh='恶魔的头盔',Icon='item_45210',Type=63,MaxNum=99999,SellPrice=100,AdventureSort=23801,AdventureValue=85,AdventureReward={rewardid={870103}},Condition=64,Desc='平行的时空里，吉伯特和同伴们顺利地进入了钟楼的深处，凶残的魔物试图阻挡他们的步伐，但一切都是徒劳的。看着钟楼内扭曲的时空和肆虐的能量波动，吉伯特无所畏惧。探险队的行动很快引起了耶梦加得的警觉，苏醒的魔头为了心中的欲望驱使着异空间的魔物向探险队发起了进攻……战斗中的吉伯特和同伴们完美配合，他们斩下了所有恶魔的头颅，完成了探索的任务。',NoSale=1,NoStorage=5,}",
  [53606] = "{id=53606,NameZh='钟楼异闻录·噩梦卷',Icon='task_53606',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=23805,AdventureValue=117,AdventureReward={rewardid={870107}},Condition=64,Desc='在漫长的岁月里，围绕着钟楼的种种诡异现象，曾经有无数勇敢的探险者先后进入钟楼，然而所有的探索都是毫无结果的，因为进入钟楼的探险者从没有人能活着走出来。吉伯特和他的伙伴们与其他的探险者一样，他们怀揣着对艾尔帕兰的热爱和无所畏惧的勇气，踏上了前途未知的发现之旅。他们不知道在前面等待着的会是多么严峻的考验，他们也不知道，此刻的钟楼早已在恶魔耶梦加得的掌控下变得冷酷血腥。恶魔的眼神里没有丝毫怜悯，他利用了伊米尔之心的力量，甚至连大贤者留下的黄金时钟也成为他加速时空异变的工具，而吉伯特他们对此竟然毫不知情。一时间，钟楼内混乱的时空里形成了无数可怕的时间漩涡，任何踏入时间漩涡的人将永远从这个世界上消失。吉伯特和所有的探险者一样，遭遇了裂变时空的吞噬。但他是幸运的，机智灵活的反应使他幸免于难，然而他的伙伴们却永远离开了他，他永远记得那些熟悉的身影通过时空甬道的传送消失在无数个平行世界的尽头。明白一切的吉伯特并没有畏缩地逃跑，他将探险的任务坚持到了最后。当他看着面前有些惊讶的恶魔，这个冷血的杀手，他以自己最无畏的灵魂向恶魔发出了最后一击……',NoSale=1,NoStorage=5,}",
  [53607] = "{id=53607,NameZh='利维坦的沙漏',Icon='item_task_49',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23806,AdventureValue=98,AdventureReward={rewardid={870108}},Condition=64,Desc='利维坦是古今著名的大海盗，他利用一个别致的金沙漏来打开时空之门。轻松的穿梭回过去，解决改变未来将出现的麻烦。一天，利维坦的船在海上遇到风暴，嫉妒他的副手乘乱砸破了他的金沙漏，利维坦瞬间化作一缕金沙与沙漏中的沙随风暴飘散在无边无际的大海之中。后来陷害他的副手死于非命，但也没人再见过位大名鼎鼎的海盗。',NoSale=1,NoStorage=5,}",
  [53608] = "{id=53608,NameZh='明日水晶',Icon='item_task_46',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23807,AdventureValue=98,AdventureReward={rewardid={870109}},Condition=64,Desc='艾尔帕兰城内曾有位通晓未来的魔女，通常是神秘地地罩在面网里，不示人以真面目，脸面向的方向 ，手里永远拿一颗用丝巾包住的水晶球，但是都不展开，仿佛喻世着未来不可知的神秘，没有人知道她叫什么，问她从哪里来，她便答“遥远的未来”',NoSale=1,NoStorage=5,}",
  [53609] = "{id=53609,NameZh='马莱的指针',Icon='item_task_47',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23808,AdventureValue=98,AdventureReward={rewardid={870110}},Condition=64,Desc='马莱不仅是位天才魔法师，还是很杰出的钟表师。凭着才华与天赋做出了一只能时间旅行的钟，只要将时针向前推或向后推，便可穿梭回时钟上的时间。可马莱的妻子贪得无厌，想永葆自身青春美貌，折断了马莱钟上的所有指针，于是这位天才魔法师与他的妻子永远的被困在了一个不再有时间流逝的封闭时空内。',NoSale=1,NoStorage=5,}",
  [53610] = "{id=53610,NameZh='时光匕首',Icon='item_task_48',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=23809,AdventureValue=117,AdventureReward={rewardid={870111}},Condition=64,Desc='百年前，艾尔帕兰城外有块能让人忘记时间的石头，歇脚的路人只要一坐在此块石头上便忘记了所有时间和烦恼，不肯再走一步路，城里的一个年轻盗贼请工匠将石头打造成一把匕首，用于行刺。据说用这把匕首靠近敌人，敌人连反抗的意愿都没有，只会乖乖伏降。',NoSale=1,NoStorage=5,}",
  [53611] = "{id=53611,NameZh='时间碎片·年',Icon='item_12549',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23708,AdventureValue=98,AdventureReward={rewardid={870112}},Condition=64,Desc='研究了黑魔女身体里的魔女印记，诺德温构筑了时间的等级阶层，并研究出时间理论——《永恒维度》，根据研究的结果，他发现时间是一个较为抽象的概念，是物质的演变、运动的表现。于是他写了《时间碎片·年》的研究报告，里面蕴含着时间的部分奥秘。',NoSale=1,NoStorage=5,}",
  [53612] = "{id=53612,NameZh='时间碎片·月',Icon='item_12549',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23709,AdventureValue=98,AdventureReward={rewardid={870113}},Condition=64,Desc='研究了黑魔女身体里的魔女印记，诺德温构筑了时间的等级阶层，并研究出时间理论——《永恒维度》，根据研究的结果，他发现时间是一切事物构成的保证，并且空间与时间不能分开解析，因此拥有“时空”一说，他写了《时间碎片·月》的研究报告，里面蕴含着时间的部分奥秘。',NoSale=1,NoStorage=5,}",
  [53613] = "{id=53613,NameZh='时间碎片·日',Icon='item_12549',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23710,AdventureValue=98,AdventureReward={rewardid={870114}},Condition=64,Desc='研究了黑魔女身体里的魔女印记，诺德温构筑了时间的等级阶层，并研究出时间理论——《永恒维度》，根据研究的结果，他发现现在、过去和将来之间的差别只是一种错觉。他写了《时间碎片·日》的研究报告，里面蕴含着时间的部分奥秘。',NoSale=1,NoStorage=5,}",
  [53614] = "{id=53614,NameZh='时间碎片·时',Icon='item_12549',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23711,AdventureValue=98,AdventureReward={rewardid={870115}},Condition=64,Desc='研究了黑魔女身体里的魔女印记，诺德温构筑了时间的等级阶层，并研究出时间理论——《永恒维度》，根据研究的结果，时间倒流或回到过去，其实是建立在一个不存在的逻辑基础上的。那么又引出一个问题，魔力的存在可以回到过去，那么那时历史又会发生什么变化？他写了《时间碎片·时》的研究报告，里面蕴含着时间的部分奥秘。',NoSale=1,NoStorage=5,}",
  [53615] = "{id=53615,NameZh='时间碎片·分',Icon='item_12549',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23712,AdventureValue=98,AdventureReward={rewardid={870116}},Condition=64,Desc='研究了黑魔女身体里的魔女印记，诺德温构筑了时间的等级阶层，并研究出时间理论——《永恒维度》，根据研究的结果，魔法的力量可以使人看到过去与未来的事件，在某些超凡的魔法力的影响下，人们可以看到更多，但是，人们无法改变过去既定的事实，那么人类可以通过预言改写未来吗？他写了《时间碎片·分》的研究报告，里面蕴含着时间的部分奥秘。',NoSale=1,NoStorage=5,}",
  [53616] = "{id=53616,NameZh='时间碎片·秒',Icon='item_12549',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23713,AdventureValue=98,AdventureReward={rewardid={870117}},Condition=64,Desc='研究了黑魔女身体里的魔女印记，诺德温构筑了时间的等级阶层，并研究出时间理论——《永恒维度》，根据研究的结果，时间是一种客观存在。时间的概念是人类认识、归纳、描述自然的结果。魔力的存在促使时间可以在一定程度被人类掌控，但是要想改变历史，改变未来，理论上是可行的，但是实施起来，非常艰难，甚至根本不可能实现。他写了《时间碎片·秒》的研究报告，里面蕴含着时间的部分奥秘。',NoSale=1,NoStorage=5,}",
  [53617] = "{id=53617,NameZh='时间轮盘',Icon='item_task_31',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=23714,AdventureValue=117,AdventureReward={rewardid={870118}},Condition=64,Desc='根据诺德温的描述，他曾经在某个磁场活跃的洞穴里看到了一角未来，那是天崩地裂，山河破碎的末日场景，他看到了依斯鲁得倒下的剑士雕像，看到了吉芬损坏的吉芬高塔，那角未来消失之后，他得到了这个发着光的轮盘，他至今不知道开启轮盘的方法。',NoSale=1,NoStorage=5,}",
  [53618] = "{id=53618,NameZh='凯撒密码盘',Icon='item_task_47',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23810,AdventureValue=98,AdventureReward={rewardid={870119}},Condition=64,Desc='这是一面刻满了符文般深奥难解的字符的金色圆盘，盘面上有一些方孔，孔中也有字符，仔细观察会发现它其实是由两面金盘拼接而成，带方孔的金盘可以旋转，使方孔显示不同的字符。若非如此，它容易被误认为是一件魔法物品，然而事实上这是一件用来编译密码的工具。',NoSale=1,NoStorage=5,}",
  [53619] = "{id=53619,NameZh='骷髅吊坠',Icon='item_52155',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23811,AdventureValue=98,AdventureReward={rewardid={870120}},Condition=64,Desc='这串纤细的金链，连接着一枚黑曜石雕成的骷髅头吊坠，吊坠上透出猫眼般的纹理，似乎有种摄人心魄的能量。拉斯普廷就是借助这枚吊坠来施展他神奇的催眠术。',NoSale=1,NoStorage=5,}",
  [53620] = "{id=53620,NameZh='炼金阵石',Icon='item_task_46',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23812,AdventureValue=98,AdventureReward={rewardid={870121}},Condition=64,Desc='这是一块残缺的石板，刻满了深奥难解的炼金阵符，这些符文似乎是某个炼金阵的一部分，但现在已经很难根据这部分残缺的符文，推测出整个炼金阵的全貌了。这块石板应该是来自尼古拉的墓室。',NoSale=1,NoStorage=5,}",
  [53621] = "{id=53621,NameZh='蓝色尖帽',Icon='item_45067',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23813,AdventureValue=98,AdventureReward={rewardid={870122}},Condition=64,Desc='这是一顶深蓝色的尖帽，上面印着许多黄色的明星，象征着魔法师来自星空的深邃魔力，它是灰袍巫师身份的象征之一。',NoSale=1,NoStorage=5,}",
  [53622] = "{id=53622,NameZh='黄金镰刀',Icon='item_41815',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23814,AdventureValue=98,AdventureReward={rewardid={870123}},Condition=64,Desc='这把黄金锻造的镰刀是大德鲁伊用来采集神圣的槲寄生的圣物，阿莱斯特˙克劳利曾经极度仰慕德鲁伊，他为了制作黄金镰刀，甚至无视禁令肆意掠夺，对他来说，德鲁伊就是他的信仰。',NoSale=1,NoStorage=5,}",
  [53623] = "{id=53623,NameZh='星界棱晶',Icon='item_52821',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=23815,AdventureValue=117,AdventureReward={rewardid={870124}},Condition=64,Desc='来自神秘时空乱流的特殊晶体，通体紫色光泽，四周还包裹着一阵氤氲的淡紫色雾气，纳鲁认为他是来自神秘星空，是星空的馈赠，其中蕴含不知名的力量，似乎与那些异世界来客身上的力量一样……',NoSale=1,}",
  [53624] = "{id=53624,NameZh='溯回指针',Icon='item_task_37',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23715,AdventureValue=98,AdventureReward={rewardid={870125}},Condition=64,Desc='任何事物都无法抗拒吞食一切的时间，这天伯纳德、尼克西、雷萨吉、海廷斯、黑鲁携手闯入钟楼，却遭遇了时间支配者，他们应该如何选择？',NoSale=1,NoStorage=5,}",
  [53625] = "{id=53625,NameZh='破败钟表·六点',Icon='item_task_38',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23716,AdventureValue=98,AdventureReward={rewardid={870126}},Condition=64,Desc='贪婪而好占便宜的人，容易被收买。尼克西就是这样的人。尼克西带着三个木箱踏上了逃亡之路，三个沉重的木箱是他活命的掣肘。但是他不愿意放手，他总是心怀侥幸，那个梦魇会追上其他人，伯纳德也好，海廷斯也好。只要不先来找自己，自己就可以凭借对钟楼的熟悉率先逃出去，然后享用这数不尽的财富。魔鬼追上来，魔鬼的魔法使得三个木箱越来越重，最后尼克西无法负担木箱的重负，被生生压死。魔鬼放下一个破败的钟表，此刻，钟表的时间指向六点。',NoSale=1,NoStorage=5,}",
  [53626] = "{id=53626,NameZh='破败钟表·三点',Icon='item_task_38',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23717,AdventureValue=98,AdventureReward={rewardid={870127}},Condition=64,Desc='傲慢而刚愎自负的人，容易被利用，雷萨吉就是这样的人。如果他肯与伯纳德一同上路，如果他肯向魔鬼求饶道歉，如果他愿意与其他死人联手对抗时间支配者。也许结局不会变成受尽折磨而死。他的傲慢与自负导致了他的死亡。魔鬼放下了一个破败的钟表，此刻，钟表的时间指向三点。',NoSale=1,NoStorage=5,}",
  [53627] = "{id=53627,NameZh='破败钟表·九点',Icon='item_task_38',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23718,AdventureValue=98,AdventureReward={rewardid={870128}},Condition=64,Desc='暴躁而崇尚暴力的人，容易被拖垮，海廷斯就是这样的人。暴躁的人永远都是这样，自以为暴力可以解决一切。但是实际上，暴力只会产生暴力，滥用暴力的人终究会倒在更强的暴力之下。魔鬼召唤出近乎无尽的魔物，海廷斯虽然力量不凡，但终究还是倒在了魔物手中。魔鬼放下了一个破败的钟表，此刻，钟表的时间指向九点。',NoSale=1,NoStorage=5,}",
  [53628] = "{id=53628,NameZh='破败钟表·十二点',Icon='item_task_38',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23719,AdventureValue=98,AdventureReward={rewardid={870129}},Condition=64,Desc='奸诈而做事刁钻的人，容易被舍弃，伯纳德就是这样的。为了增强自己的力量来到钟楼，在时钟支配者的干预下，只能迎来自己的死亡。魔鬼亲手用魔法的力量把这位追寻力量的魔法师送入地狱。看着魔法师被魔法冰封的遗体，魔鬼放下了一个破败的钟表，此刻，钟表的时间指向十二点。',NoSale=1,NoStorage=5,}",
  [53629] = "{id=53629,NameZh='死亡丧钟',Icon='item_task_39',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=23720,AdventureValue=117,AdventureReward={rewardid={870130}},Condition=64,Desc='懦弱而依赖他人的人，容易被欺骗，黑鲁就是这样的人。尽管在时间支配者的帮忙下，黑鲁完成了自己的复仇。但骨子里，黑鲁依然是个懦弱的人，走到时间支配者面前也好，报仇也好，都不是依靠自己的力量。在死亡丧钟的面前，他没有选择的余地。只能按照丧钟的时间，给予他们死亡。钟声响起，人魂尽丧，这就是死亡丧钟。',NoSale=1,NoStorage=5,}",
  [53630] = "{id=53630,NameZh='钟楼异闻录·丧钟卷',Icon='task_53630',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=23721,AdventureValue=117,AdventureReward={rewardid={870131}},Condition=64,Desc='尼克西为人贪婪而好占便宜，因此他被伯纳德所收买。雷萨吉为人傲慢且刚愎自负，因此他被伯纳德所利用。海廷斯暴躁且崇尚暴力，因此他最终被无尽魔物拖死。伯纳德奸诈且做事刁钻，不留余地，因此遭到其余三人在事情发生后无情地舍弃。至于黑鲁，他从未改变过，懦弱且依赖他人，因此最终他的灵魂被魔鬼吞噬。黑鲁死去，遗留的死亡丧钟给予人们警示，傲慢、贪婪、暴躁、奸诈、懦弱，这些人性的弱点，将在时间的流逝之下逐渐暴露。而到了那时，死亡丧钟将会再一次敲响。',NoSale=1,NoStorage=5,}",
  [53631] = "{id=53631,NameZh='德斯黎的指环',Icon='item_44003',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23816,AdventureValue=98,AdventureReward={rewardid={870132}},Condition=64,Desc='时间的力量变幻莫测，时间黑洞却告知了过往。他们三人的至交好友斯科特突然在这钟楼二层失踪。而没过几天，钟楼就传出了关于鬼魅的传说，阿奇索伦认为，那个鬼魅就是斯科特。但是蒙妮卡和德斯黎却不置可否，但是耐不住阿奇索伦的软磨硬泡，三人还是决定前往钟楼一探究竟，结果他们却遭遇了魔物的袭击…',NoSale=1,NoStorage=5,}",
  [53632] = "{id=53632,NameZh='时间魔石·过往',Icon='item_12536',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23817,AdventureValue=98,AdventureReward={rewardid={870133}},Condition=64,Desc='斯科特与德斯黎显然是一对好朋友。在黑洞出现的那刻，他想抓住斯科特，时间黑洞吞噬着周围的一切，在这场拉锯战中，人最终是失败者，斯科特狠狠的推开德斯黎，自己却因为反作用力被黑洞吞噬。',NoSale=1,NoStorage=5,}",
  [53633] = "{id=53633,NameZh='时间魔石·未来',Icon='item_12536',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23818,AdventureValue=98,AdventureReward={rewardid={870134}},Condition=64,Desc='时间，捉摸不透，人们无法看到未来究竟发生了什么。阿奇索伦坚持认为德斯黎与斯科特的逝去与神秘的鬼影有关。蒙妮卡劝他不要再去那个诡异的地方了，但是阿奇索伦却毫不在意。经过许久的等待，他终于等到了那个鬼影，一番激烈的战斗后阿奇索伦摘下了鬼影的面具，却发现鬼影竟然是蒙妮卡！',NoSale=1,NoStorage=5,}",
  [53634] = "{id=53634,NameZh='时间魔石·现在',Icon='item_12536',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=23819,AdventureValue=117,AdventureReward={rewardid={870135}},Condition=64,Desc='时间是世界上一切成就的土壤。时间给空想者痛苦，给创造者幸福。在斯科特于黑洞中消失之后，他决定扮成鬼影，驱逐那些误入这里的人们。当德斯黎为了救阿奇索伦深陷黑暗，他临死前的最后一句话，让蒙妮卡接替了他的工作。于是，每晚十二点过后的，总有一双阴森的双眼注视着钟楼二层。',NoSale=1,NoStorage=5,}",
  [53635] = "{id=53635,NameZh='钟楼异闻录·魅影卷',Icon='task_53635',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=23820,AdventureValue=117,AdventureReward={rewardid={870136}},Condition=64,Desc='时间是世界上一切成就的土壤。时间给空想者痛苦，给创造者幸福。德斯黎便是创造者，他在创造一个通向安全的方向牌。他决定扮成鬼影，驱逐那些误入这里的人们。同时他又是勇敢的，他为了救阿奇索伦永陷黑暗，即使在这个时候，他也没有忘记让蒙妮卡接替了他的工作。在这世界上并不缺少创造者，区别在于，一个创造出真正的幸福，而另一个只是幻想罢了。',NoSale=1,NoStorage=5,}",
  [53636] = "{id=53636,NameZh='褪色的木灵',Icon='item_12547',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23601,AdventureValue=75,AdventureReward={rewardid={870137}},Condition=64,Desc='森灵一族守护的三种灵石之一，代表生机与自然的力量，但是因为人类肆意研究破坏环境，环境的污染影响了秘境中的木灵，在污染物的侵蚀下，木灵变得不再纯净，在它的影响下，树林、植被以及以这些为生的生物都发生了巨大的变化。',NoSale=1,NoStorage=5,}",
  [53637] = "{id=53637,NameZh='褪色的水灵',Icon='item_12545',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23602,AdventureValue=75,AdventureReward={rewardid={870138}},Condition=64,Desc='森灵一族守护的三种灵石之一，代表生命与滋养的力量，但是因为人类肆意研究破坏环境，环境的污染影响了秘境中的水灵，在污染物的侵蚀下，水灵变得不再纯净，在它的影响下，山川、湖泊以及以这些为生的生物都发生了巨大的变化。',NoSale=1,NoStorage=5,}",
  [53638] = "{id=53638,NameZh='褪色的土灵',Icon='item_12546',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23603,AdventureValue=75,AdventureReward={rewardid={870139}},Condition=64,Desc='森灵一族守护的三种灵石之一，代表厚重与生长的力量，但是因为人类肆意研究破坏环境，环境的污染影响了秘境中的土灵，在污染物的侵蚀下，土灵变得不再纯净，在它的影响下，土地、生长在土地上的植被以及以这些为生的生物都发生了巨大的变化。',NoSale=1,NoStorage=5,}",
  [53639] = "{id=53639,NameZh='森灵之心',Icon='item_60003',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=23604,AdventureValue=90,AdventureReward={rewardid={870140}},Condition=64,Desc='森灵一族的至宝，木、水、土三灵石被伊米尔之心的力量所污染，三灵石滋养下的森灵之心即将受到污染的时候，森灵王果断切断了森灵之心与灵石的联系，虽然森灵之心没有遭受污染，但是失去了三灵石的供养，森灵之心逐渐失去了力量，现在森灵王正在寻找让森灵之心重新恢复活力的方法。',NoSale=1,NoStorage=5,}",
  [53640] = "{id=53640,NameZh='破碎的刀刃',Icon='item_40016',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23901,AdventureValue=98,AdventureReward={rewardid={870141}},Condition=64,Desc='经过吉芬法师们的调查，女神之手的阴谋渐渐被揭露出来，希默梅斯聚集了一批邪恶的魔物在克雷斯特汉姆，试图献祭法师庞德的灵魂，召唤出黑暗之王毁灭整个大陆。为了阻止他们的阴谋，全大陆的各势力：高傲的法师、轻盈的弓箭手、英武的皇家骑士团，团结起来组成了古城同盟军。这支全大陆最精锐的部队集结在古城之中，与克雷斯特汉姆嗜血的魔物决战，至死方休。同盟军在进入古城时碰见了一件棘手的事情，这片区域被阴影和浓雾笼罩，许多魔物蛰伏在浓雾之中，随时准备攻击误入他们领地的人类。女法师莉莎使用冒险者从古城中找到的破碎的刀刃，建立了通向古城下水道的传送阵，帮助同盟军进入古城下水道寻找庞德的踪影。这些同盟军战士在下水道误入大魔物迷幻之王的陷阱，迷幻之王吞噬了庞德部分的灵魂，躲藏在古城下水道想要继续吞噬更多的灵魂，危急时刻英雄法师莉莎使用魔法把众人传送回安全区域。',NoSale=1,NoStorage=5,}",
  [53641] = "{id=53641,NameZh='暗黑手札',Icon='item_task_45',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23902,AdventureValue=98,AdventureReward={rewardid={870142}},Condition=64,Desc='同盟军的先锋部队在古城调查时发现了一对误入暗黑手札的恋人，他们被封印在这本暗神官的手札中无法解脱。先锋部队立刻对他们开展了解救行动，被解救的二人为同盟军带来古城最深处的信息，他们在手札里挣扎时得以窥视到一群绝望祭祀在古城墓地的深处举行献祭仪式。法师莉莎立刻利用暗黑手札，帮助同盟军建立了通向古城墓地的传送阵。同盟军的先锋部队前往古城墓地调查，在阴森的墓地里艰难的前行，终于找到了正在举行献祭仪式的绝望祭祀。先锋部队合力击破绝望祭祀的仪式，阻止他们继续献祭，但也惊动了迷幻之王。发现仪式被破坏的迷幻之王大发雷霆，要毁灭先锋部队，幸好大法师雷藏及时赶到挡住迷幻之王的攻击。莉莎也顺利完成构建传送阵的任务，大家得以撤退，保留实力，为最终的决战做准备。',NoSale=1,NoStorage=5,}",
  [53642] = "{id=53642,NameZh='黑暗锁链',Icon='item_5039',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23903,AdventureValue=98,AdventureReward={rewardid={870143}},Condition=64,Desc='虽然阻止了绝望祭祀的献祭，但庞德的灵魂依然在黑暗之王的掌控之中，黑暗之王利用庞德的弱点，把他的灵魂分裂成几部分。大法师摩根调查到庞德灵魂在他不稳定的精神世界里，先锋部队成员冒着生命危险进入了庞德的精神世界。了解到这位普通的法师，在学习过程中碰见的挫折和绝望，正是这股绝望，让黑暗之王有机可趁。先锋部队的成员在庞德的精神世界不停给庞德鼓舞，帮助这位并不出众的法师一部分灵魂脱离了黑暗之王的掌控。成功夺回庞德部分的灵魂之后，先锋部队一鼓作气进入迷幻之王的死亡空间，在这个乌烟瘴气的空间解救出庞德的另外一部分灵魂，胜利在望！死亡空间的深处是黑暗之王的所在地，他企图占据庞德的身体，以古城为据点率领他的魔物军团进攻整个人类世界。尽管黑暗之王并没有被完全召唤，但是他凌驾在人类之上的实力，让同盟军对他无计可施。正当人类的明天将会走向灰暗之时，女武神的英灵们及时赶到，配合人类的精英部队一起对抗黑暗之王，把这个魔头赶回了深渊。',NoSale=1,NoStorage=5,}",
  [53643] = "{id=53643,NameZh='灵魂静谧',Icon='item_44002',Type=41,Quality=3,MaxNum=99999,SellPrice=100,Desc='法师协会专门打造的项链灵魂静谧。\n使用后HP上限永久 + 15',NoSale=1,NoStorage=5,}",
  [53644] = "{id=53644,NameZh='默斯曼的感谢信',Icon='item_5032',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=24001,AdventureValue=98,AdventureReward={rewardid={870145}},Condition=64,Desc='默斯曼为了感谢冒险者的帮助赠送给冒险者的谢礼。冒险者们受邀参加艾尔帕兰一场盛大的婚礼，婚礼的现场新郎意外遇害，冒险者义不容辞调查事件真相。与此同时，记录黄金时钟使用方法的“秘法典籍”失窃。冒险者追踪窃贼之时，却被时钟守护者霍兰干扰，冒险者对霍兰心起疑问。通过跟踪霍兰，发现他确实是内贼，霍兰不仅帮助窃贼盗取“秘法典籍”，还准备煽动守护者内部爆发叛乱，夺取默斯曼的性命。冒险者透过霍兰继续调查，得知原来指挥霍兰的幕后黑手是三瘟神之一的耶梦加德，他试图利用黄金时钟的力量，解救自己被锁在月亮上的哥哥魔狼芬里尔，如果让他的阴谋得逞，不仅是艾尔帕兰，整个大陆都会陷入危险之中。',NoSale=1,NoStorage=5,}",
  [53645] = "{id=53645,NameZh='诺曼的怀表',Icon='item_task_31',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=24002,AdventureValue=98,AdventureReward={rewardid={870146}},Condition=64,Desc='时钟守护者诺曼的怀表。耶梦加德为了获得黄金时钟的力量，伪装成守护者诺曼的弟弟。他在艾尔帕兰经营多年，了解到许多有关黄金时钟的秘密，他指使霍兰煽动时钟守护者们，利用他们爆发内部叛乱，导致默斯曼受了重伤，趁着默斯曼受伤的时机，盗取奇点球。耶梦加德在钟楼里利用奇点球，召唤出古代巴风特，他妄想着古代巴风特会帮助他杀死时钟守护者的领袖默斯曼·岁月。没想到巴风特觊觎他的神躯，不听从他的命令，反而倒戈相向，妄图吞噬耶梦加德。危急时刻，诺曼舍命相救，诺曼的行为唤醒他内心的良善，耶梦加德与冒险者合作击败了古代巴风特。',NoSale=1,NoStorage=5,}",
  [53646] = "{id=53646,NameZh='黄金蛇眼',Icon='item_7337',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=24003,AdventureValue=98,AdventureReward={rewardid={870147}},Condition=64,Desc='轮回梦魇的眼球。因为耶梦加德过度使用奇点球和黄金时钟的力量，导致黄金时钟内部产生了时空裂隙。另外一条时间线的耶梦加德穿越黑洞而来，而那个世界的耶梦加德没有选择使用黄金时钟拯救哥哥，反而选择自己吞噬了这股的力量，也因为这股力量心智全失，变成了一个嗜血的魔物，他给自己起名为轮回梦魇，流窜于不同世界。耶梦加德联合冒险者，打败另一个世界的自己——轮回梦魇，帮助人类封印了黑洞，并承诺不再使用黄金时钟就悄然离去。',NoSale=1,NoStorage=5,}",
  [53647] = "{id=53647,NameZh='时钟守卫者勋章',Icon='item_5261',Type=41,Quality=3,MaxNum=99999,SellPrice=100,Desc='默斯曼为英勇的冒险者颁发的时钟守卫者勋章。\n使用后HP上限永久 + 15',NoSale=1,NoStorage=5,}",
  [53648] = "{id=53648,NameZh='红鼻子入场券',Icon='item_12317',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=25001,AdventureValue=98,AdventureReward={rewardid={870149}},Condition=64,Desc='今年的圣诞节，姜饼城来了一个神秘小丑，他特别喜欢糖果和孩子，免费为姜饼城的小孩子发放马戏团的入场券——巧克力饼干。持有这种巧克力饼干的小孩可以观看红鼻子马戏团的表演，令人担忧的是很多看完表演的小孩都失踪了。圣诞老人委托前来姜饼城游玩的冒险者调查小丑，接受委托的冒险者，伪装成小孩子的模样混入马戏团里，陪伴一位名叫珍妮的女孩观看红鼻子马戏团的表演，前两场表演都顺利的演完，冒险者也找到了一些调查线索。据线索可知，一位叫做毕尤的傀儡巫师指示小丑把姜饼城的孩子们制作成玩偶，圣诞老人非常气愤，姜饼城的所有居民都团结起来一起对抗毕尤和小丑。',NoSale=1,NoStorage=5,}",
  [53649] = "{id=53649,NameZh='圣诞节快乐',Icon='item_12121',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=25002,AdventureValue=98,AdventureReward={rewardid={870150}},Condition=64,Desc='名字叫做圣诞节快乐的糖果，糖果商人贝蒂的祖传配方，许多年来一直被评选为最受孩子欢迎的糖果，只在圣诞节限量供应。贝蒂小时候，每年的圣诞节爸爸妈妈会带她到白雪纷飞的姜饼城度假，在这里她认识了一个可爱的小丑加尔，她把爸爸熬制的糖果“圣诞节快乐”送给了加尔，与加尔成为了好朋友。贝蒂与加尔约定，每年圣诞节都会在姜饼城相聚，贝蒂将学会熬制糖果，亲手为加尔制作出”圣诞节快乐“，而加尔也会好好锻炼自己的演出技艺专门为贝蒂表演。然而，一些意外发生，让贝蒂没能实现与加尔的约定，加尔也因为贝蒂的失约变成了疯狂的魔物。几十年后，贝蒂和加尔重新在圣诞村相遇，一颗”圣诞节快乐“解开了他们的心结。',NoSale=1,NoStorage=5,}",
  [53650] = "{id=53650,NameZh='圣诞树的铃铛',Icon='item_52312',Type=41,Quality=3,MaxNum=99999,SellPrice=100,Desc='帮助圣诞老人赶走傀儡巫师毕尤后，圣诞老人给予的奖励，象征了姜饼城的小铃铛。\n使用后HP上限永久 + 15',NoSale=1,NoStorage=5,}",
  [53651] = "{id=53651,NameZh='波利留声器',Icon='item_12342',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=26001,AdventureValue=98,AdventureReward={rewardid={870152}},Condition=64,Desc='炼金大师飞利浦的发明的波利形状的留声器，里面记载了他给学生阿克米的留言：亲爱的阿克米，进来无恙？老师碰见了一件麻烦的事情需要你帮助，希望你可以尽快来一趟姜饼城，越快越好。对了，这是我的新发明——波利留声器，可以录音和播放，你觉得有趣吗？',NoSale=1,NoStorage=5,}",
  [53652] = "{id=53652,NameZh='阿克米的礼品盒',Icon='item_3664',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=26002,AdventureValue=98,AdventureReward={rewardid={870153}},Condition=64,Desc='阿克米制作的礼品盒，打开时会播放清脆的音乐。虽然心中有些怨恨自己收养的两个小孩，阿克米还是按照老师的吩咐为他们制作了玩具和盛放玩具的礼品盒。',NoSale=1,NoStorage=5,}",
  [53653] = "{id=53653,NameZh='阿克米的饼干人',Icon='item_45408',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=26003,AdventureValue=98,AdventureReward={rewardid={870154}},Condition=64,Desc='阿克米制作的饼干人，看上去非常像真正的饼干，上面还有许多小孩子的牙印。阿克米为自己的养子养女制作的玩具，被小孩们当成了真正的饼干。',NoSale=1,NoStorage=5,}",
  [53654] = "{id=53654,NameZh='阿克米的玩具士兵',Icon='Cruiser',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=26004,AdventureValue=98,AdventureReward={rewardid={870155}},Condition=64,Desc='阿克米制作的玩具士兵，看上去神气又威武。炼金术士阿克米为养子养女制作的玩具，被保存的非常完美。',NoSale=1,NoStorage=5,}",
  [53655] = "{id=53655,NameZh='茉莉香水',Icon='item_12341',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=26005,AdventureValue=98,AdventureReward={rewardid={870156}},Condition=64,Desc='使用东方神秘植物茉莉精炼而成的香水。炼金术士阿克米为自己的养女小幸运制作的结婚礼物，饱含了他对女儿的爱意。连瓶身都是小巧的留声器，按下按钮会播放阿克米对女儿的祝福。',NoSale=1,NoStorage=5,}",
  [53656] = "{id=53656,NameZh='地龙皮手套',Icon='item_44023',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=26006,AdventureValue=98,AdventureReward={rewardid={870157}},Condition=64,Desc='使用稀有的地龙皮制作的手套，最适合刚入行不熟练的炼金术士。有效的保护炼金术士的双手不被强酸和强碱的腐蚀，阿克米买个自己的养子小勇气的礼物。',NoSale=1,NoStorage=5,}",
  [53657] = "{id=53657,NameZh='炼金术士的日记本',Icon='item_3605',Type=165,Quality=3,MaxNum=99999,SellPrice=100,NoSale=1,NoStorage=5,}",
  [53658] = "{id=53658,NameZh='没有装饰的铜镜',Icon='item_52316',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=27001,AdventureValue=98,AdventureReward={rewardid={870159}},Condition=64,Desc='奥莉薇亚有着一双灵气十足的大眼睛，麦斯是她的青梅竹马，一天麦斯带奥莉薇亚出城看星星，却遇到了雷雨天气，马车和人一同翻进了冰冷的湖水，夺走了麦斯年轻的生命，而奥莉薇亚却失明了。当她在医院醒来时，牧师告诉她运气很好，刚好有适合的眼睛能取代她失明的双目，在恢复视力的那天，牧师给奥莉薇亚拿来了一盏没有装饰的铜镜，望向镜中的自己时，奥莉维亚的眼泪却止不住的流了下来。',NoSale=1,NoStorage=5,}",
  [53659] = "{id=53659,NameZh='羊皮箭筒',Icon='item_47020',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=27002,AdventureValue=98,AdventureReward={rewardid={870160}},Condition=64,Desc='蕾拉和她年仅六岁的妹妹正在参加婶婶的葬礼，在葬礼上，蕾拉对一个从未谋面的英俊的弓箭手一见钟情。蕾拉天生性格内向，并没有上前搭讪说话。年轻男子在葬礼上落下了一个羊皮箭筒，蕾拉看见后悄悄的收了起来。葬礼结束后，蕾拉借着箭筒的契机和城中的人打听这位年轻的弓箭手，可是怎么打听也打听不到男子的下落。一个月后，蕾拉的妹妹去世了，在妹妹的葬礼上她终于见到了那个让她魂牵梦萦的弓箭手。当蕾拉将箭筒还给男子时，蕾拉说：“抱歉，我很小心的收着，但还是弄丢了一只。”',NoSale=1,NoStorage=5,}",
  [53660] = "{id=53660,NameZh='冰晶玫瑰',Icon='item_52509',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=27003,AdventureValue=98,AdventureReward={rewardid={870161}},Condition=64,Desc='妮可儿在一户富裕人家长大，妈妈却独宠哥哥十分排挤她，不仅虐待她，还让她为家中做许多苦力。倒是村口的一个穷苦妇人对她格外亲切，时常偷偷塞些小樱桃给她吃。一天，妇人交给妮可儿一朵冰晶玫瑰，说这朵玫瑰里住着雪精灵能满足人的一个愿望，妇人让妮可儿用这朵花许愿永远幸福。妮可儿因为回家晚了，被妈妈一顿毒打，泪水滴在了玫瑰上，一个雪精灵真的从花蕊中飞了出来，妮可儿忘记了妇人的叮嘱，仇恨已充斥了她的内心，她说她希望她的家人全死光。第二天清晨，妮可儿醒了，发现爸爸，妈妈，哥哥都在，妮可儿愣了楞，突然大哭起来，跑去问雪精灵可不可以收回愿望，可雪精灵说一切都太晚了。昨日妇人给的樱桃散落了一地，染红了白雪。',NoSale=1,NoStorage=5,}",
  [53661] = "{id=53661,NameZh='灵偶发带',Icon='item_45261',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=27004,AdventureValue=98,AdventureReward={rewardid={870162}},Condition=64,Desc='这三个被诅咒的娃娃诞生于一个怪异的玩具工人之手，这位工人在制作完这些娃娃的第三天就离奇的去世了。一个魔女在每个娃娃的头发上都绑上了一根淡蓝色的发带。从此之后，人们就时常会在玩具工厂看到这三只到处游荡的娃娃。她们靠夺取少女的心灵，来获得自由活动的能力，所以常找些精神状态不稳定的少女下手。悄悄潜入少女们的房间，将蓝色的灵偶发带解下系在她们的头上。便搭建了，进入少女心灵的桥梁。鸢尾喜欢少女的绝望，所以选中了奥莉薇亚，她的恋人牺牲了自己将双眼给了失明的奥莉薇亚，让奥莉薇亚悲伤欲绝；紫罗兰爱少女的恐惧，蕾拉为了再次在葬礼上见到心仪的男子不惜亲手杀死自己的妹妹，回到家后的蕾拉并没注意到她床上多了一只漂亮精致的人偶；洛丽玛丝看到妮可儿因为仇恨蒙蔽了她的双眼，因此误杀了自己的亲生母亲而感到痛苦不堪。而这种痛苦，正是洛丽玛丝所需要的。三个命运多舛的少女就这样被诅咒的娃娃戴上了灵偶发带，成了她们的傀儡。',NoSale=1,NoStorage=5,}",
  [53662] = "{id=53662,NameZh='金线兔玩偶',Icon='item_12343',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=26007,AdventureValue=98,AdventureReward={rewardid={870163}},Condition=64,Desc='唐纳的母亲是个穷苦的纺织工，随着圣诞节即将到来，唐纳要求母亲给自己买一个兔子玩偶。橱窗中的兔子玩偶十分昂贵，母亲并没有那么多钱，就告诉唐纳，她会给唐纳手工做一个同样可爱的玩偶。可唐纳就是想要商店里的那只，哭闹不止。母亲没有办法，母亲只好去偷隔壁商贩家的东西卖，不巧被商贩发现了。商贩没有将钱要回来，而是剁下了母亲一只手臂。平安夜的那天晚上，唐纳如愿以偿的得到了兔子玩偶，可他不知道母亲再也不能纺织了。',NoSale=1,NoStorage=5,}",
  [53663] = "{id=53663,NameZh='苦涩的糖豆',Icon='item_12121',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=26008,AdventureValue=98,AdventureReward={rewardid={870164}},Condition=64,Desc='格兰迪是领主家的小童工，领主很喜欢这个机灵的小家伙。每次格兰迪做完工，领主都会奖励格兰迪一把甜甜的糖豆。可格兰迪觉得做工太辛苦了，他宁可坐着都能得到奖励，于是他就派自己的影子去帮他做工。他的影子和格兰迪一模一样，连领主都没看出分别来。日复一日，影子渐渐取代了格兰迪的位置。那天，影子在交给领主给格兰迪的奖励中，偷偷的混入了一颗抹着毒药的糖豆。',NoSale=1,NoStorage=5,}",
  [53664] = "{id=53664,NameZh='旋转红鞋',Icon='item_43523',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=26009,AdventureValue=98,AdventureReward={rewardid={870165}},Condition=64,Desc='一个叫卡伦的农村女孩在她母亲死后被一个富有的老妇人收养了。从前，卡伦只有破旧的木鞋，可现在养母给她买了一双高级定制的红舞鞋。卡伦经常不顾礼数穿着红舞鞋去严肃的教堂，甚至，当她的养母生病时，她还穿着红舞鞋去参加派对。一天，一位教堂门口的老太太对她说了些奇怪的话后，卡伦便脱不下她的舞鞋，舞鞋自己疯狂的跳动，日日夜夜，晴雨不分，永不停歇。卡伦只好找到了一个刽子手，祈求他砍掉自己的脚。刽子手砍下了卡伦的脚，但是舞鞋依然在跳动，带着卡伦的脚消失在浓浓的夜色中。',NoSale=1,NoStorage=5,}",
  [53665] = "{id=53665,NameZh='恶魔金沙',Icon='item_52404',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=26010,AdventureValue=98,AdventureReward={rewardid={870166}},Condition=64,Desc='马克的爷爷卧床不起，病情严重，他绝望地唤出了恶魔，说若能使爷爷病愈，他便献给恶魔一千克金沙。恶魔用法术使马克的爷爷康复了。爷爷病好后，马克没用真正的金沙来酬谢恶魔，而是用黄沙代替，放在祭坛上烧，并念念有词的说：“恶魔啊恶魔，我已经履行了我的承诺。”恶魔便在晚上托梦告诉小马克，要他到海边去，说在那里可以找到真正的金沙。马克醒来后，高兴极了，直往海边跑去。结果在那里遇到了凶恶的海盗，马克被他们抓走并且卖掉，而他的售卖价格是…一千克金沙。',NoSale=1,NoStorage=5,}",
  [53666] = "{id=53666,NameZh='说话的鱼',Icon='item_550511',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=26011,AdventureValue=98,AdventureReward={rewardid={870167}},Condition=64,Desc='托尼跟着哥哥出海打渔，织了一张和桌子一般大的小网。出海一天只捕到了一条鱼，垂头丧气地回到了家。回家将鱼放进水中，鱼居然开口说了话。鱼对小托尼说：\"把网织得越大，捕到的鱼就越多。\" 托尼听了鱼的话，就认真地在家织网。哥哥劝托尼不要那么贪心，但托尼不理会。巨网织好后，小托尼就带着它和哥哥出海，花了好大的功夫才把巨网撒入大海。托尼想，这一定可以装满一船，想着想着，他乐得笑出了声。 但当托尼准备收网了，一拉网，觉得好沉好沉，连船带人一起翻入了深海之中。哥哥一人回到家，发现家中那条会说话的鱼也不见了。',NoSale=1,NoStorage=5,}",
  [53667] = "{id=53667,NameZh='冰冻的心脏',Icon='item_52203',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=26012,AdventureValue=98,AdventureReward={rewardid={870168}},Condition=64,Desc='南希是富有人家的孩子，他有一个属于自己的小花园。圣诞时，南希的父母给南希布置了一颗完美的圣诞树。别家的孩子都想来这里看一看南希的圣诞树，可南希太吝啬了，他不愿放任何人进自己的小花园。于是，当春天笼罩大地，唯独南希的花园还是冬天的天气，温暖的大地无法融化南希冷冰冰的心。南希抱着光秃秃毫无装饰的圣诞树，永远的睡在了雪里。多年后，人们从树底发现了一颗被冰冻的心脏。',NoSale=1,NoStorage=5,}",
  [53668] = "{id=53668,NameZh='小鬼四叶草',Icon='item_52302',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=26013,AdventureValue=98,AdventureReward={rewardid={870169}},Condition=64,Desc='艾玛是公爵的女儿，傲慢且盛气凌人。人们都爱围绕着她，因为公爵宠溺小艾玛。所有好吃的好玩的都属于她一人。艾玛想要一片四叶草，但这在市面上可买不到。于是公爵便命人将附近的草丛全部铲除，也要找到那片四叶草。住在草里的精灵，告诉艾玛这一带没有四叶草，并祈求她不要毁了他们的住所。艾玛不为所动，还是铲平了附近的所有草丛，但这惊扰了住在草丛中的小鬼。小鬼问艾玛是不是要四叶草，艾玛点头。于是小鬼取走了艾玛的舌头，双眼和头发，并给了艾玛一片四叶草。',NoSale=1,NoStorage=5,}",
  [53669] = "{id=53669,NameZh='托尼的眼球',Icon='dark_001',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=26014,AdventureValue=98,AdventureReward={rewardid={870170}},Condition=64,Desc='托尼和托塔是一对孪生兄弟。但哥哥托尼总是嫉妒父母对弟弟托塔的照顾。一天托尼遇到一只金鸟，金鸟告诉他，可以满足他任何一个愿望，但前提是他的弟弟托塔会得到双倍的报酬。托尼起先高兴不已。但他仔细一想：如果他想要一座糖果屋，弟弟就会有两座。如果他想要一车玩具，弟弟就会有两车。想来想去，托尼不知道该提什么要求才好，他实在不甘心又被弟弟白占了便宜。最后，托尼一咬牙，对金鸟说：“哎，你挖去我的一只眼珠吧。”',NoSale=1,NoStorage=5,}",
  [53670] = "{id=53670,NameZh='坎卜斯的桦树枝',Icon='item_12021',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=26015,AdventureValue=98,AdventureReward={rewardid={870171}},Condition=64,Desc='坎卜斯是个半羊半魔的魔物，常在平安夜现身，他将考察圣诞村的每一个孩子，并在坏孩子的门口放上桦树枝。这天晚上，孩子们会胆战心惊的查看，摆在门外的鞋子或靴子中装的是圣诞老公公给的馈赠，还是坎卜斯给坏孩子的树枝。被放上树枝的人家，代表着被他盯上的坏孩子，会被坎卜斯拿桦树枝抽打，再把他们带回自己的巢穴。在巢穴中等着他们的，永远是坎卜斯为坏孩子们准备的那份特殊的惩罚礼物。',NoSale=1,NoStorage=5,}",
  [53671] = "{id=53671,NameZh='陈旧的告示',Icon='item_5128',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=27005,AdventureValue=98,AdventureReward={rewardid={870172}},Condition=64,Desc='从布袋熊的布袋中滑出一封陈旧的告示，上面登记着十年前的一天，圣诞村的宝石商人贝尔摩被洗劫的新闻。贝尔摩身中数箭身亡，当时的抢匪一共有五个人，查理、曼逊、丹、里克和卡尔。因四人指认是腹语师查理杀了贝尔摩，所以腹语师查理被判绞刑，在平安夜的前一天被处决。',NoSale=1,NoStorage=5,}",
  [53672] = "{id=53672,NameZh='波利玩偶',Icon='item_12342',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=27006,AdventureValue=98,AdventureReward={rewardid={870173}},Condition=64,Desc='打开发条熊背后的暗门，里面藏着一只波利玩偶。这个玩偶属于死去的贝尔摩先生的小女儿。这个可怜的小女孩，那天正好是她的生日，当时受到了过多的惊吓，只知道重复着一句话：“他们中的首领把我和爸爸绑了起来，杀死我爸爸的人和卡尔多拿了两颗钻石”。',NoSale=1,NoStorage=5,}",
  [53673] = "{id=53673,NameZh='丹的密信',Icon='item_task_34',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=27007,AdventureValue=98,AdventureReward={rewardid={870174}},Condition=64,Desc='撕开毛绒熊的身体，从里面露出来一封被封住的信。信上写着：“首领，我与你的妻子还有卡尔可是手足关系，切记不可相信里克这个人，虽然他常拿好处巴结你，但毕竟不是一家人。我看得出你也不是很相信他，等风波过去了，我就和您碰头。丹。”',NoSale=1,NoStorage=5,}",
  [53674] = "{id=53674,NameZh='小女儿的画',Icon='item_555022',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=27008,AdventureValue=98,AdventureReward={rewardid={870175}},Condition=64,Desc='剥去纽扣熊的纽扣，从熊身体里探出来的是一张贝尔摩小女儿的画。上面有一行模糊的字：首领大人，我给您寄来了贝尔摩小女儿的画。我理解您现在一定不好受，因为您曾是这小姑娘的美术老师。我也理解您为了袒护真正凶手不得已的作为，毕竟那是您最要好的兄弟。',NoSale=1,NoStorage=5,}",
  [53675] = "{id=53675,NameZh='生锈的箭',Icon='item_12502',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=27009,AdventureValue=98,AdventureReward={rewardid={870176}},Condition=64,Desc='划开皮革熊的皮革，能从里面取出一只折断的箭。箭上虽然已经锈迹斑斑，但依旧能看出它当年的威力应该不小。这正是十年前杀死贝尔摩先生的箭。从贝尔摩身上拔下好几根这样的断箭，可以看出，这都是由同一把弓射出去的。',NoSale=1,NoStorage=5,}",
  [53676] = "{id=53676,NameZh='有钻石的肩包',Icon='item_47031',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=27010,AdventureValue=98,AdventureReward={rewardid={870177}},Condition=64,Desc='割开牵线熊的绳子，从牵线熊的肚中露出一只咖啡色的小包。这只包乍一看平淡无奇，却重的可疑。实际上里面有四个装着钻石的小布袋，每个小布袋上都缝着一个人名。首领的布袋和里克的布袋中只有一颗钻石，其余两人的布袋中则装着两颗钻石。',NoSale=1,NoStorage=5,}",
  [53677] = "{id=53677,NameZh='腹语师陶板',Icon='item_12528',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=27011,AdventureValue=98,AdventureReward={rewardid={870178}},Condition=64,Desc='腹语师在被处死前，用指甲刻字在陶板上，陈述了十年前富商惨案的真相。十年前腹语师查理被钻石商贝尔摩请到家中，帮他的小女儿庆祝生日，为其表演腹语节目。曼逊是抢匪四人的首领，带着三人来家中抢夺贝尔摩的宝石。丹射箭杀死了贝尔摩先生，因为卡尔出力多，所以两人多分到了一颗钻石。里克很慌张，并不想承担任何责任，所以四人指正查理为真正的凶手。',NoSale=1,NoStorage=5,}",
  [53678] = "{id=53678,NameZh='圣诞金铃',Icon='item_52312',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=27012,AdventureValue=98,AdventureReward={rewardid={870179}},Condition=64,Desc='姜饼城的小孩胖熊从圣诞树附近捡到的精致铃铛，摇晃时会发出清脆悦耳的铃声，如果跳舞时佩戴在身上会随着舞步叮叮当当作响。',NoSale=1,NoStorage=5,}",
  [53679] = "{id=53679,NameZh='蝴蝶磷光水晶',Icon='item_900008',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=27013,AdventureValue=98,AdventureReward={rewardid={870180}},Condition=64,Desc='混合了暗夜蝴蝶磷粉的水晶，在黑夜里熠熠发光。美丽的舞娘请热心的冒险者，在午夜时刻捕捉到圣诞村特有的暗夜蝴蝶，制作出带着蝴蝶磷光的水晶。',NoSale=1,NoStorage=5,}",
  [53680] = "{id=53680,NameZh='金苹果',Icon='item_157',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=27014,AdventureValue=98,AdventureReward={rewardid={870181}},Condition=64,Desc='漂亮的金苹果，黑夜之中会发出金灿灿的光芒，是黑天鹅舞蹈团的舞娘们亲手制作的舞蹈道具。',NoSale=1,NoStorage=5,Feature=1,}",
  [53681] = "{id=53681,NameZh='迷之树叶',Icon='item_task_54',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=27015,AdventureValue=98,AdventureReward={rewardid={870182}},Condition=64,Desc='画有各种神秘箭头和符号，隐隐约约之中可以发现好像是一个什么奇怪地形的地图，上面还标有一些宝藏样子的符号。',NoSale=1,NoStorage=5,}",
  [53682] = "{id=53682,NameZh='圣诞香包',Icon='item_3708',Type=165,Quality=3,MaxNum=99999,SellPrice=100,Desc='黑天鹅舞蹈团的舞娘们为了游客制作的圣诞纪念品，存放了各种珍贵香料，拿在手上可以闻到迷人的香味。舞娘珂莲安为了感谢冒险者的帮助，将自己亲手制作的圣诞香包赠送给热心的冒险者。',NoSale=1,NoStorage=5,}",
  [53683] = "{id=53683,NameZh='吉尔达的金发',Icon='item_task_53',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=27016,AdventureValue=98,AdventureReward={rewardid={870184}},Condition=64,Desc='吉尔达女神的一缕头发，太阳神弗雷曾偷偷坐在奥丁的宝座上观察远方，他看见北国有一位美丽的女神，长了一头秀丽的金发，从此就爱上了那位女神。',NoSale=1,NoStorage=5,}",
  [53684] = "{id=53684,NameZh='聚金戒指',Icon='item_44017',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=27017,AdventureValue=98,AdventureReward={rewardid={870185}},Condition=64,Desc='太阳神弗雷的定情信物，爱上吉尔达的太阳神请求史基尔尼的帮助，撮合他跟吉尔达女神。史基尔尼答应了太阳神的请求，带着他的定情信物聚金戒指来到了北国。',NoSale=1,NoStorage=5,}",
  [53685] = "{id=53685,NameZh='永恒之花',Icon='item_task_16',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=27018,AdventureValue=98,AdventureReward={rewardid={870186}},Condition=64,Desc='精灵之国亚尔夫海姆的花朵，被太阳神制作成了不会凋谢的瓶中花，送给吉尔达女神，作为第一次见面的礼物。',NoSale=1,NoStorage=5,}",
  [53686] = "{id=53686,NameZh='胜利之剑',Icon='item_40335',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=27019,AdventureValue=98,AdventureReward={rewardid={870187}},Condition=64,Desc='盛放了太阳神的武器——胜利之剑的盒子，弗雷为了感谢史基尔尼撮合他跟吉尔达，把诸神送给他的胜利之剑送给了史基尔尼，只留下了神剑的剑盒。',NoSale=1,NoStorage=5,}",
  [53687] = "{id=53687,NameZh='鹿角的碎片',Icon='item_5002',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=27020,AdventureValue=98,AdventureReward={rewardid={870188}},Condition=64,Desc='巨鹿之角的碎片，失去了胜利之剑的太阳神弗雷在诸神黄昏之时，临时用于与火焰巨人战斗的巨鹿角的碎片，蕴含了太阳神的微弱神力。',NoSale=1,NoStorage=5,}",
  [53688] = "{id=53688,NameZh='吉尔达之泪',Icon='item_52029',Type=165,Quality=3,MaxNum=99999,SellPrice=100,Desc='吉尔达女神泪水化作的泪滴状水晶，吉尔达在丈夫弗雷死去之后，悲痛欲绝，她流下最后一滴眼泪，化为极光飞回北国，从此消失世间。',NoSale=1,NoStorage=5,}",
  [53689] = "{id=53689,NameZh='碎水晶',Icon='',Type=165,Quality=3,MaxNum=99999,SellPrice=100,NoSale=1,NoStorage=5,}",
  [53690] = "{id=53690,NameZh='咒法卷轴',Icon='task_53606',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=28001,AdventureValue=98,AdventureReward={rewardid={870190}},Condition=64,Desc='冒险者来到了天水之国，这里有满城的樱花在初春微冷的阳光下，一层压着一层盛开。樱花之中有一对奇特的情侣，男子是天水之国巫术家族伊达家的子裔，女子是一位温柔善良的灵。这位温柔的灵，灵力变弱无法维持自己的灵体，而她的心上人伊达秀明为了拯救她，不惜盗取自己姐姐保管的家传咒法书——咒法卷轴。这本书记载了伊达家族所领悟的巫术，伊达秀明想要通过聚集咒法卷轴里的巫术聚集全城的灵，补救小樱脆弱的灵魂。',NoSale=1,NoStorage=5,}",
  [53691] = "{id=53691,NameZh='樱灵之爱',Icon='item_52314',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=28002,AdventureValue=98,AdventureReward={rewardid={870191}},Condition=64,Desc='为了阻止伊达秀明的聚灵巫术，小樱私自与冒险者联系，通过小樱的回忆，冒险者了解到他们过去的故事。他们因一支花枝相识，被对方所吸引，在漫长的相处过程中慢慢爱上了对方。在秀明年幼的时候，生了一场重病，小樱为了救他将自己的灵力偷偷输送到秀明的身体里。失去了灵力的小樱即将消失……',NoSale=1,NoStorage=5,}",
  [53692] = "{id=53692,NameZh='樱城的故事',Icon='item_task_55',Type=165,Quality=3,MaxNum=99999,SellPrice=100,NoSale=1,NoStorage=5,}",
  [53693] = "{id=53693,NameZh='狐狸的宝玉',Icon='item_task_03',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=28003,AdventureValue=98,AdventureReward={rewardid={870193}},Condition=64,Desc='小狐狸下仙山的时候，神明担心它的安危，为它制作了能让它安然回家的宝玉。而小狐狸将宝玉送给善良的巫女，与巫女成为了好朋友。',NoSale=1,NoStorage=5,}",
  [53694] = "{id=53694,NameZh='伊达的符咒',Icon='task_53635',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=28004,AdventureValue=98,AdventureReward={rewardid={870194}},Condition=64,Desc='伊达家族的巫女希望捕获小狐狸成为家族的守护神，而小狐狸只想在大陆上游历，然后回到神仙的居住的仙山。身兼伊达家族的巫女与小狐狸的朋友，伊达杏夹在两边不知道自己能够做些什么。',NoSale=1,NoStorage=5,}",
  [53695] = "{id=53695,NameZh='樱花露珠',Icon='item_52029',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=28005,AdventureValue=98,AdventureReward={rewardid={870195}},Condition=64,Desc='伊达杏向小狐狸表达她希望小狐狸能够留下来陪她，却被思念故乡的小狐狸拒绝了！樱花上有一滴晶莹的露珠，不知道是雾气凝结的露珠，还是巫女伤心的眼泪？',NoSale=1,NoStorage=5,}",
  [53696] = "{id=53696,NameZh='狐狸和神明',Icon='item_52107',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=28006,AdventureValue=98,AdventureReward={rewardid={870196}},Condition=64,Desc='为了复活自己养的小狐狸，神明不惜触犯了仙山的规定，在天水之国使用了法术，被除去了天籍。神明和狐狸，虽然失去了回到仙山的资格，却最终找回了对方，开始了新的旅程。',NoSale=1,NoStorage=5,}",
  [53697] = "{id=53697,NameZh='狐之火',Icon='item_48574',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=28007,AdventureValue=98,AdventureReward={rewardid={870197}},Condition=64,Desc='巫女伊达杏带着小狐狸回自己的神社，却看见了一团恶灵，两人非常惊讶为什么圣洁的伊达神社会有恶灵。实际上，这些恶灵是伊达家族的其他巫女释放出来，为了试探小狐狸身份的诱饵。',NoSale=1,NoStorage=5,}",
  [53698] = "{id=53698,NameZh='狐狸旧事',Icon='',Type=165,Quality=3,MaxNum=99999,SellPrice=100,NoSale=1,NoStorage=5,}",
  [53699] = "{id=53699,NameZh='智慧残卷',Icon='22',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29001,AdventureValue=105,AdventureReward={rewardid={870199}},Condition=64,Desc='千年前原本是智慧卷轴的一部分，智慧巨人密米尔故意将其破坏成了几十份智慧残卷，封存在了世界的各个角落。',NoSale=1,NoStorage=5,}",
  [53700] = "{id=53700,NameZh='密米尔之花',Icon='item_45022',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29002,AdventureValue=105,AdventureReward={rewardid={870200}},Condition=64,Desc='智慧巨人密米尔混合了几种珍稀花卉杂交诞生，自发芽开始便具有魔力，据说是智慧井的酒所用的原材料之一。',NoSale=1,NoStorage=5,}",
  [53701] = "{id=53701,NameZh='密米尔宝石',Icon='item_5100',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29003,AdventureValue=105,AdventureReward={rewardid={870201}},Condition=64,Desc='人类很难想象这样强大的魔法宝石，千年前仅仅是智慧巨人密米尔用来制作锁芯的材料，巨人族的实力真是可怕。',NoSale=1,NoStorage=5,}",
  [53702] = "{id=53702,NameZh='智慧井的蜂蜜酒',Icon='item_12117',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29004,AdventureValue=105,AdventureReward={rewardid={870202}},Condition=64,Desc='智慧井是智慧巨人密米尔从奥丁手里打赌赢来的宝物，至于为何里面会源源不断地产出具有魔力的蜂蜜酒，人们至今无从得知。',NoSale=1,NoStorage=5,}",
  [53703] = "{id=53703,NameZh='密米尔号角',Icon='item_52406',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29005,AdventureValue=126,AdventureReward={rewardid={870203}},Condition=64,Desc='杰拉德家族世代相传并信奉的宝物，与神族的加拉尔号角齐名。从使用痕迹来看，这曾经可能是智慧巨人密米尔用来喝酒的器皿，不过很多研究者也认为，器皿只是假象，密米尔号角真正的用途是武器或魔法器具。',NoSale=1,NoStorage=5,}",
  [53704] = "{id=53704,NameZh='密米尔传说',Icon='',Type=165,Quality=3,MaxNum=99999,SellPrice=100,NoSale=1,NoStorage=5,}",
  [53705] = "{id=53705,NameZh='花边发夹',Icon='item_44009',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29006,AdventureValue=105,AdventureReward={rewardid={870204}},Condition=64,Desc='这枚发夹似乎用特殊的香料熏过，戴在头上会散发出宜人的清香，应该很受女孩子喜欢吧。',NoSale=1,NoStorage=5,}",
  [53706] = "{id=53706,NameZh='高档牛漆皮革',Icon='item_45039',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29007,AdventureValue=105,AdventureReward={rewardid={870205}},Condition=64,Desc='牛漆皮革俗称油皮，是一种涂层极薄，吸附渗透性强的皮料，用它制作的防具，家具，甚至乐器，都会拥有极好的质感。',NoSale=1,NoStorage=5,}",
  [53707] = "{id=53707,NameZh='祖母绿戒指',Icon='item_44003',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29008,AdventureValue=105,AdventureReward={rewardid={870206}},Condition=64,Desc='祖母绿被人们视为爱和生命的象征，所以拥有这枚戒指的人，想必也是个追求爱与和平的人呢。',NoSale=1,NoStorage=5,}",
  [53708] = "{id=53708,NameZh='精致的羽毛笔',Icon='item_52310',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29009,AdventureValue=105,AdventureReward={rewardid={870207}},Condition=64,Desc='用鸟人哈比脱落的羽毛制作的笔，柔软的手感让人在用它写字的时候根本感觉不到疲惫。',NoSale=1,NoStorage=5,}",
  [53709] = "{id=53709,NameZh='国境边防奖章',Icon='item_task_24',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29010,AdventureValue=126,AdventureReward={rewardid={870208}},Condition=64,Desc='为感谢你对国境检查站做出的巨大贡献，国境警卫队代表两国的人民颁发这枚荣誉奖章，希望你能带着他帮助更多的人，让奖章的光芒永远闪耀。',NoSale=1,NoStorage=5,}",
  [53710] = "{id=53710,NameZh='魔物怪盗团',Icon='',Type=165,Quality=3,MaxNum=99999,SellPrice=100,NoSale=1,NoStorage=5,}",
  [53711] = "{id=53711,NameZh='斑驳的家徽',Icon='27',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29011,AdventureValue=105,AdventureReward={rewardid={870209}},Condition=64,Desc='老旧斑驳的家徽，是过去某个家族的象征，据说这个家族的最后一位传人来到熔岩洞窟寻求火鸟之泪的力量，最后不知所踪。',NoSale=1,NoStorage=5,}",
  [53712] = "{id=53712,NameZh='熔洞蔷薇',Icon='item_52012',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29012,AdventureValue=105,AdventureReward={rewardid={870210}},Condition=64,Desc='只生长在熔岩洞窟的特殊蔷薇，据说是为了所爱之人牺牲的少年幻化而成，他的灵魂变成蔷薇永远留在这里，无论什么时代，爱情总是甜蜜又痛苦。',NoSale=1,NoStorage=5,}",
  [53713] = "{id=53713,NameZh='无名剑柄',Icon='item_41851',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29013,AdventureValue=105,AdventureReward={rewardid={870211}},Condition=64,Desc='属于某个狮鹫骑士的宝剑之柄，剑刃已经被岩浆融化，只有这寄宿了主人执念的剑柄默默诉说那位骑士曾经的辉煌传奇。',NoSale=1,NoStorage=5,}",
  [53714] = "{id=53714,NameZh='神秘的日记',Icon='item_5524',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29014,AdventureValue=105,AdventureReward={rewardid={870212}},Condition=64,Desc='非常厚的一本日记，里面的内容却十分诡异，似乎写日记的人已经活了几百年的岁月，这是否证明了火鸟之泪的传说呢？',NoSale=1,NoStorage=5,}",
  [53715] = "{id=53715,NameZh='瓶装岩浆',Icon='item_12522',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29015,AdventureValue=105,AdventureReward={rewardid={870213}},Condition=64,Desc='装有奇怪岩浆的瓶子，自己会晃动，被关在里面的东西似乎蠢蠢欲动。',NoSale=1,NoStorage=5,}",
  [53716] = "{id=53716,NameZh='猩红符咒',Icon='task_53601',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29016,AdventureValue=105,AdventureReward={rewardid={870214}},Condition=64,Desc='用高级魔法制作的猩红色符咒，散发着躁动的气息，似乎封印了什么不祥的东西。',NoSale=1,NoStorage=5,}",
  [53717] = "{id=53717,NameZh='炙热羽毛',Icon='item_5028',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29017,AdventureValue=105,AdventureReward={rewardid={870215}},Condition=64,Desc='散发生命火焰的神奇羽毛，似乎和传说中的火鸟有关，只要握着它似乎身体就充满了活力。',NoSale=1,NoStorage=5,}",
  [53718] = "{id=53718,NameZh='火鸟之泪',Icon='item_52835',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29018,AdventureValue=126,AdventureReward={rewardid={870216}},Condition=64,Desc='传说中可以赋予喝下之人永恒生命的火鸟之泪，可传说并没有提及得到永生需要付出的巨大代价，要是你会喝下它吗？',NoSale=1,NoStorage=5,}",
  [53719] = "{id=53719,NameZh='火鸟传说',Icon='',Type=165,Quality=3,MaxNum=99999,SellPrice=100,NoSale=1,NoStorage=5,}",
  [53736] = "{id=53736,NameZh='诺法之剑',Icon='item_40340',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29019,AdventureValue=105,AdventureReward={rewardid={870217}},Condition=64,Desc='你的剑是为了什么而挥动呢？导师的话语在诺法的脑海中回荡。出身在普隆德拉的诺法从小在皇家士兵训练场边长大，当年幼的他第一次握起长剑时，他便被深深吸引住了。对于当时的他来说，长剑是骑士帅气的象征。当熔岩洞窟魔物暴乱时，与伙伴一同深入洞窟阻止灾难的诺法，陡然领悟到，其实长剑的背后是守护之心，你是为了什么而挥剑呢？导师的声音再次浮现，用尽气力的诺法用这把剑支撑起自己，我的剑为了拯救无辜的生命而挥动，为了守护同伴的笑容而挥动。牺牲自己也没关系么？没关系，我认为很值得。诺法微笑着闭上双眼。',NoSale=1,NoStorage=5,}",
  [53737] = "{id=53737,NameZh='诺法之盾',Icon='item_42536',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29020,AdventureValue=105,AdventureReward={rewardid={870218}},Condition=64,Desc='诺法转职成骑士的那天起，他便背上了这块沉重的盾牌，他的导师说，你手上的盾牌不是为了保护你而存在的，诺法当时并不理解话中的含义，直到他离开普隆德拉，与三位性格迥异又意气相投的队友组成冒险小队。每当大家遇到危险，这面盾牌便是守护伙伴的坚固屏障，在朱诺的熔洞暴乱中，这面盾牌又化作为朱诺阻挡灾祸的壁垒。当诺法的心脏在熔岩洞窟停止跳动的那一刻，他依然紧握盾牌屹立不倒，身后是同样燃尽生命的伙伴，他们的嘴角带着安心的微笑。',NoSale=1,NoStorage=5,}",
  [53738] = "{id=53738,NameZh='桃丽之弓',Icon='item_41234',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29021,AdventureValue=105,AdventureReward={rewardid={870219}},Condition=64,Desc='这把斐扬古木制作的弓上，沁着淡淡的红色。即使岁月流逝它依然富有韧性，看得出来它的主人十分细心并且非常爱护它，但如今这把弓只剩下光秃秃的弓身，再没有谁会抚动它的心弦。无人知晓曾有一位名为桃丽的少女紧握着它射出了希望与勇气，如今故人已消逝，唯有桃丽之弓无言的诉说过去的故事。',NoSale=1,NoStorage=5,}",
  [53739] = "{id=53739,NameZh='桃丽之箭',Icon='item_12502',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29022,AdventureValue=105,AdventureReward={rewardid={870220}},Condition=64,Desc='出生于斐扬的桃丽只是一个相貌平平的农家少女，直到某次她展显出非凡的射手天赋。成为猎人离开家乡游历的桃丽，在途中遇到了可靠的三个伙伴，行侠仗义的四人冒险小队就此诞生，途径朱诺的他们遭遇了熔岩洞窟的魔物暴动，这里生灵涂炭的惨象让桃丽想起了自己的家乡——斐扬曾经的悲剧。善良的桃丽决心与伙伴一同拯救朱诺。箭矢百步穿杨，不断狙击着狂化的魔物首领，桃丽的双手慢慢被磨出血泡，当四人踏入熔岩洞窟的深处，桃丽挽弓搭上这最后一只箭。弓箭之神大人，我恳求您让我射出神箭，封印熔岩洞窟的戾气与怨恨。少女闭眼祈祷，神箭脱手而出。桃丽成功了，但那双爱笑的眼眸却永远不会再睁开了。',NoSale=1,NoStorage=5,}",
  [53740] = "{id=53740,NameZh='瓦西里之斧',Icon='item_41845',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29023,AdventureValue=105,AdventureReward={rewardid={870221}},Condition=64,Desc='你为什么喜欢斧子？曾有人这样问过瓦西里。他笑着回答。因为它很像我，一板一眼，劈下去就劈下去了，大开大合从不花里胡哨。梦罗克的沙漠男儿从不和人玩虚的。当瓦西里与伙伴们决定帮助朱诺时，他根本没想那么多，只是看到魔物在伤害无辜的人，只是看到有人需要我们的帮助，手中的斧子自己就动了起来呢。见到这把斧子，一下就能明白：这家伙的主人是个了不起的战士。',NoSale=1,NoStorage=5,}",
  [53741] = "{id=53741,NameZh='瓦西里之冠',Icon='item_45220',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29024,AdventureValue=105,AdventureReward={rewardid={870222}},Condition=64,Desc='梦罗克出身的瓦西里从小就是孩子王，小时候，他的头上戴着风滚草编织的头环，多年后，取而代之的是坚硬的金属头冠。但在瓦西里骨子里，自己仍是当年那个路见不平出手相助的孩子王，作为四人冒险小队的老大，他与伙伴义无反顾的加入帮助朱诺击退魔物暴动的行动中，直到牺牲生命封住洞窟戾气的那刻，他仍笑得像个初心不改的顽童。',NoSale=1,NoStorage=5,}",
  [53742] = "{id=53742,NameZh='黎风之杖',Icon='item_40613',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29025,AdventureValue=105,AdventureReward={rewardid={870223}},Condition=64,Desc='作为一百年来首个被魔法学院提前录取的学生，斯曼玲·黎风天生就注定成为一位传奇女巫师，但出乎所有人意料的是，在她十九岁那年，她不顾导师的反对，与新的同伴组成了四人冒险小队，离开了养育自己的吉芬，在经过天空之城朱诺时，熔岩洞窟发生了前所未有的魔物暴动，魔物所到之处皆化作火海，冒险小队决定留下帮助朱诺的人们，而斯曼玲的强大魔法成为了压制魔物群的利器，亲眼目睹事件的朱诺老者回忆说，当斯曼玲吟唱魔法时，耀眼的光芒环绕着她，如同传说中的女神，嚣狂的魔物四散溃逃。当四人来到熔岩洞窟深处，斯曼玲的魔力已接近枯竭，少女用尽了最后的力量，封住了使魔物暴戾狂化的次元裂隙，紧握着这根陪伴自己短暂一生的魔杖，她永远安眠在了远离吉芬的异国他乡。',NoSale=1,NoStorage=5,}",
  [53743] = "{id=53743,NameZh='黎风典籍',Icon='item_3882',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29026,AdventureValue=105,AdventureReward={rewardid={870224}},Condition=64,Desc='每位魔法师都拥有一本记录自己魔法的典籍，斯曼玲·黎风的典籍里除了咒语还有不少日记与涂鸦。第七页“一根筋瓦西里，呆萌妹桃丽，大笨蛋诺法！我的队友真是够了。”第四十页“没想到这帮家伙还挺能干的嘛。诺法这个笨骑士原来也有可靠的一面。”最后一页“谢谢你们，我并不后悔止步于此，笨蛋诺法，我爱…”',NoSale=1,NoStorage=5,}",
  [53744] = "{id=53744,NameZh='英雄之名',Icon='item_5250',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29027,AdventureValue=126,AdventureReward={rewardid={870225}},Condition=64,Desc='为了纪念曾经在熔岩洞窟魔物暴动中解救朱诺的勇者，朱诺皇家颁发的纪念勋章，背面刻着四个名字：诺法，崔桃丽，瓦西里，斯曼玲·黎风。',NoSale=1,NoStorage=5,}",
  [53745] = "{id=53745,NameZh='黄金鸟蛋',Icon='item_900117',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29028,AdventureValue=105,AdventureReward={rewardid={870226}},Condition=64,Desc='很久很久以前，鸟人一族出现了一颗黄金的鸟蛋。当时的鸟人王名为哈利，这颗鸟蛋是由它的王后产下的。一枚黄金的蛋啊，哈利欣喜若狂，这是上天赐予它们一族的天选王位继承人啊。于是它日日夜夜的守着它的王后孵化这颗黄金鸟蛋。时间一天又一天的过去了，没关系，天选继承人和别的鸟人不一样。时间一年又一年的过去了，王后你安心的去吧，我会代替你来孵化我们的王子。终于，哈利的时间走到了尽头，它垂下了它的双眼，安详的伏在黄金鸟蛋上——我会继续等你。',NoSale=1,NoStorage=5,}",
  [53746] = "{id=53746,NameZh='木质头盔',Icon='item_45068',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29029,AdventureValue=105,AdventureReward={rewardid={870227}},Condition=64,Desc='夜已深了，但在村落一处的木匠们还流着汗做着工。月光朦朦胧胧的洒在地面上，他们借着微弱的月光努力干活。在另一边的地上，整齐的放着好多个已经做好的成品，是木质的头盔。简简单单的的头盔，没有任何的装饰品的头盔，明天勇士们将要戴着它们去寻找黄金鸟蛋的头盔。木匠们不敢马虎，这些勇士们是村落里的希望，不管是那个天选勇士还是其它的年轻人。还差几个，还差几个就可以了，木匠们全然不觉疲惫，每个人的眼睛里都闪着比月光更亮的光芒。',NoSale=1,NoStorage=5,}",
  [53747] = "{id=53747,NameZh='黑曜石之刃',Icon='item_40342',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29030,AdventureValue=105,AdventureReward={rewardid={870228}},Condition=64,Desc='铁匠端详着眼前的那把利刃，这也许是他这辈子做的最好的铁器了。怎么能不好呢？村长送来了镇村之宝，先祖们以前得到的一颗黑曜石，沉稳而又带着光泽的黑曜石一直都是村里的镇邪之宝。而现在，它被镶嵌在了一把利刃之上。而这把利刃将会赐予给天选勇士，而天选勇士将会在之后的祭祀过程中，从村里的年轻人中选出来。或许这样是最好的吧，天选勇士带着这样的利刃一定能将村子带出现在的困境。这样想着，铁匠粗狂的脸上露出了柔和的笑容。',NoSale=1,NoStorage=5,}",
  [53748] = "{id=53748,NameZh='图腾陶器',Icon='item_45407',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29031,AdventureValue=105,AdventureReward={rewardid={870229}},Condition=64,Desc='在盛大的祭祀及加冕仪式之后，大祭司正在亲手制作一个陶器，回想着当日的场景——兴奋的孩子，祈祷的村民，咏唱的祭司，奋战的勇士和举着黄金鸟蛋满身是伤的天选勇者。从那日开始，村子将不再面对那么多危险，从那日开始，所有人都会在天选勇士的带领下前行。大祭司无法掩藏心中的振奋，他在陶器上刻画下了一幅图腾，祈求着自然会将他预见的一切赐予村落。我将终身侍奉你啊天神，死后我的灵魂也将属于你。图腾中的鸟儿与火焰交织在一起，承载着灵魂，满载着愿望。',NoSale=1,NoStorage=5,}",
  [53749] = "{id=53749,NameZh='祭司的面具',Icon='item_48606',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29032,AdventureValue=105,AdventureReward={rewardid={870230}},Condition=64,Desc='祭司们带着面具安静又整齐的往祭台走去，一个村民抱着一个孩子低着头恭敬的让路给祭祀们。怀中的孩子睁着好奇的双眼看着祭祀，他们全都带着面具，带着十分令人害怕的面具，面具似乎凶狠的看着自己，孩子控制不住恐惧哇的一声哭了出来。村民连忙轻轻摇晃他，安抚着他。一个祭祀停住了脚步，伸出了手抚在了孩子的额头。孩子感受到手心的温度，哽咽着努力睁开了泪眼，看向祭司。还是那个令人害怕的面具，但却有一道温柔的目光从眼睛的地方透出来。不怕了，不怕了。',NoSale=1,NoStorage=5,}",
  [53750] = "{id=53750,NameZh='白檀木吊坠',Icon='item_52018',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29033,AdventureValue=105,AdventureReward={rewardid={870231}},Condition=64,Desc='老妇人接过丈夫递过来的木枝，短小的木枝的一头被打上了一个洞。她用手轻轻摩挲着，擦去上面的泥土与灰尘。她知道这个木枝是丈夫辛辛苦苦从外面折回来的，白檀的木枝。白檀木是镇邪安神的神物，只有离村子很远的地方才有这么一颗白檀。她拿起手边编好的红绳，穿过木枝上的洞，打了个牢固的结。她站起来，慢慢的走到屋外，看着自己正在砍柴的儿子，招了招手。儿子擦了擦汗，放下手中的东西走到母亲的面前。老妇人踮起脚为他挂上了红绳，愿你平安唷，愿你平安唷。',NoSale=1,NoStorage=5,}",
  [53751] = "{id=53751,NameZh='勇者之冠',Icon='item_45147',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29034,AdventureValue=126,AdventureReward={rewardid={870232}},Condition=64,Desc='青年人举着黄金鸟蛋，一步一步的走上祭台。这是我们村的希望啊，这是大祭司梦里可以守护我们的圣物啊。台下的村民们眼含期待的看着这个满身是伤的青年，这些伤都是他的功勋，没有人质疑他会倒下，他也不会倒下。青年将圣物轻轻的放在祭台中央的台子上，大祭司手拿着勇者之冠向他走来。青年下意识的用手握住了胸前的白檀木，轻轻的摩挲着，眼中闪烁着对未来的期盼。这就是勇者之冠啊，青年看着满是羽毛的冠冕，这些羽毛都是历代勇者从鸟人王身上获取的，它们随着风轻轻的荡着。青年感觉到头上的重量，这份重量仿佛从头传到了肩部，沉甸甸的重量。会更好的，生活会更好的，我会带领着大家前行。',NoSale=1,NoStorage=5,}",
  [53752] = "{id=53752,NameZh='火羽弓',Icon='item_41239',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29035,AdventureValue=105,AdventureReward={rewardid={870233}},Condition=64,Desc='弓箭手名为卡拉，它是火焰精灵一族最优秀的射手，可谓是百发百中。卡拉对自己的技艺很得意，经常拿着自己的弓在别的火焰精灵面前炫耀。这把弓是卡拉偷偷跑去人类的城镇，威胁武器工匠得来的。卡拉将抢来的弓箭带回来之后，为这把弓注入了火焰的元素力量，这把弓射出去的箭都会被火焰包围，从而威力倍增。它给这把弓取名为火羽弓。火羽弓通体燃烧着不会熄灭的黄色火焰，不会法术的人会被火焰灼烧双手，根本无法握住它。',NoSale=1,NoStorage=5,}",
  [53753] = "{id=53753,NameZh='火晶球',Icon='item_42533',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29036,AdventureValue=105,AdventureReward={rewardid={870234}},Condition=64,Desc='火晶球是火焰精灵一族唯一的预言家希尔斯的所有物。火晶球的外形和人类巫师使用的水晶球很相似，这不是巧合，是因为火晶球本身就是希尔斯借鉴水晶球所制造的。火晶球的外壳是用一种特别的水晶制造，它能抵抗住世界上最精粹的火焰而不被融化。火晶球内部的火焰是希尔斯拜托精灵长老赐予的，精粹而又充满力量的火焰。希尔斯对这个自己创造的火晶球很满意，比那什么水晶球帅气多了。不过希尔斯的预言根本不需要用到这个火晶球，只是起到了一个装饰作用。',NoSale=1,NoStorage=5,}",
  [53754] = "{id=53754,NameZh='火光剑',Icon='item_40335',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29037,AdventureValue=105,AdventureReward={rewardid={870235}},Condition=64,Desc='说到火焰精灵最厉害的剑士，精灵们会一致认为是克里斯。也不是因为克里斯的剑术真的有多厉害，而是从他手下教出来的剑士就没有不厉害的。为了表彰他杰出的贡献，精灵长老将自己打造的火光剑交予了克里斯，这把剑让克里斯成为了名副其实的剑术大师。这把剑的剑刃上有流火缠绕着，克里斯挥出的每一剑都会在空中留下橙红色的残影，周围的空气都会因此灼热起来。即使拥有了这样一把剑，克里斯还是兢兢业业的教导着弟子们，希望有一天能将火光剑交予他认可的继承人。',NoSale=1,NoStorage=5,}",
  [53755] = "{id=53755,NameZh='火灵眼',Icon='item_5102',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29038,AdventureValue=105,AdventureReward={rewardid={870236}},Condition=64,Desc='火焰精灵佩里是个自认为很有品味的收藏家，它执着于收集一些稀奇古怪的东西，比如它最喜欢的火灵眼。它总喜欢一个人在黑暗里欣赏散发着幽暗红光的火灵眼，暗自感叹它的美丽。火灵眼是佩里略施手段从别的精灵那边获得的，在佩里眼里别人都不能真正欣赏它的美。传说很久以前一个强大的火焰精灵，它修习了恶魔的魔法，使得自己体内的火焰力量失控爆体死亡。但是它的一双被失控火焰填满的眼球留下了，一只已经不知去向。佩里发誓总有一天会找到另一只火灵眼。',NoSale=1,NoStorage=5,}",
  [53756] = "{id=53756,NameZh='火术卷轴',Icon='task_53601',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29039,AdventureValue=105,AdventureReward={rewardid={870237}},Condition=64,Desc='巫术师莱德是个不合群的火焰精灵。他整天捣鼓着人类的各式火系法术，因此他被大家孤立了。没办法，火焰精灵厌恶人类，厌恶人类对环境的污染，而火焰精灵又掌握着最精粹的火焰元素力量，怎么可以自甘堕落去学习人类法术呢？可是莱德不这么认为，他觉得人类的法术有特别之处，如果能把它们研究透彻，就可以提高火焰精灵的元素力量。它孜孜不倦的研读人类的火术，并将自己的研究成果写在卷轴上，命名为火术卷轴。他自己清楚的知道，他的力量早就比精灵长老还要强大了。',NoSale=1,NoStorage=5,}",
  [53757] = "{id=53757,NameZh='火炎宝石',Icon='item_52314',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29040,AdventureValue=105,AdventureReward={rewardid={870238}},Condition=64,Desc='火炎宝石是宝石工匠菲尔的得意作品。它将偶然得来的红宝石原石放在自己的体内，三年后才将它取出，再用充满火焰力量的切割刀将它切现在的形状。原石在菲尔体内慢慢吸收着元素力量，后来又注入了切割刀的元素力量，这颗宝石是名副其实的火炎宝石。它红的仿佛要燃烧，摸上去却有着红宝石的触感，坚硬而又清冷，人类只要握住它就能将法术转化为火属性。菲尔将原石切割出来的边角料偷偷卖给了人类商人，自己则将火炎宝石重新放回了体内，想让它变得更加强大。',NoSale=1,NoStorage=5,}",
  [53758] = "{id=53758,NameZh='火焰鸟蛋',Icon='item_900102',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29041,AdventureValue=105,AdventureReward={rewardid={870239}},Condition=64,Desc='鲁鲁的一生没有什么追求，就喜欢品尝各种美食，虽然火焰精灵不需要吃东西。普通的食物对鲁鲁来说已经没有吸引力了，它开始尝试吃不一样的东西，别人没有吃过的东西。它将目光投向了火焰精灵的邻居火焰鸟。鲁鲁暗自揣测着，鸡蛋能吃，那火焰鸟的蛋也能吃吧。它很快将自己的想法付诸于了行动，晚上偷偷摸摸的拿回来一只火焰鸟蛋。它将它放在清水里煮熟了，剥开壳，咬了一口。晶莹剔透的蛋白，在嘴里的滋味居然还有点甜甜的，鲁鲁觉得自己找到了一生中最爱的食物。',NoSale=1,NoStorage=5,}",
  [53759] = "{id=53759,NameZh='火种项链',Icon='item_44027',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29042,AdventureValue=105,AdventureReward={rewardid={870240}},Condition=64,Desc='一条永远不会断的绳子和一团永远不会熄灭的火焰，宝藏猎手希尔在找到这两样神奇的东西之后，将火焰穿在了绳子上面做成了一条神奇的项链。永不熄灭的火焰那不就是天神赐予的火种吗？希尔虔诚的将火种项链挂在自己的胸口，它感觉到自己的火焰力量因为这条项链变得更加强大。它也不知道自己为什么会将这两样东西放在一起，这可能就是它多年寻宝练就的直觉吧。希尔用手轻轻拢住火种项链，感受它的温度，似乎能听到它在诉说的关于火焰的故事。',NoSale=1,NoStorage=5,}",
  [53760] = "{id=53760,NameZh='火纹徽章',Icon='item_6244',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29043,AdventureValue=126,AdventureReward={rewardid={870241}},Condition=64,Desc='这枚徽章原本是小恶魔一族给予每一个小恶魔的护身符，内含着黑暗力量。这一枚火纹徽章是在原来徽章的基础上，被注入了火焰力量，使其改变了原本的属性，但仍具有守护之力。火纹徽章上包裹着橙黄色的火焰，但是火焰的温度很低，人类拿着它会有一点温暖，但是又不会灼烧手心。据改造这枚徽章的爆炎小恶魔所说，它是为了感谢一位人类冒险者而改造了徽章，目的是让自己的火焰能让这位冒险家不会在自己的居住地感受到灼热。而这个爆炎小恶魔，是小恶魔历史上第一个主动将自己变身成为爆炎小恶魔的探路者。这枚徽章可以说是十分的特别了。',NoSale=1,NoStorage=5,}",
  [53761] = "{id=53761,NameZh='感染者日记',Icon='item_3605',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29044,AdventureValue=126,AdventureReward={rewardid={870242}},Condition=64,Desc='在瘟疫爆发的第四天，村子里的大家出现了不同的症状。溃烂的脓腔与孢疹在我身上蔓延，有些抵抗力差的孩子从昨天起便呕吐不止，老人们卧倒在床，依靠意志支撑这愈发恶化的身体，哭喊声逐渐变成了呻吟，大家都被这该死的瘟疫折磨得没力气了吧？这样下去，用不了多久，整个村子就会笼罩在绝对的死寂中。我望向不远处冒着黑烟的机器叹气，神啊，为何我们要遭受这场无妄之灾？',NoSale=1,NoStorage=5,}",
  [53762] = "{id=53762,NameZh='长老的拐杖',Icon='item_40601',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29045,AdventureValue=126,AdventureReward={rewardid={870243}},Condition=64,Desc='艾因布洛克某个村庄长老使用过的拐杖，上面满是岁月蹉跎的印记。长老作为艾因布洛克原野历史的见证者，他一直对大肆开发工业的某个公司充满敌意。曾经孩童嬉戏的溪流在污染中变得污臭不堪，原本温顺的生物异变为凶暴魔物，这次突如其来的瘟疫，难道不也是那些冒着黑烟的钢铁怪兽的杰作么？一阵剧痛在他的体内流窜，几乎令他踉跄倒地，这场瘟疫没有因他的年迈而网开一面，他咬住牙倚着拐杖撑起弯曲的脊背。难道这村子就要从原野的地图上永远消失了吗？回答他的只有原野的风声与人们的啜泣。',NoSale=1,NoStorage=5,}",
  [53763] = "{id=53763,NameZh='透明空瓶',Icon='item_5020',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29046,AdventureValue=126,AdventureReward={rewardid={870244}},Condition=64,Desc='曾经装着25年前原野瘟疫解药的玻璃瓶，如今已经空空如也，瓶身布满了青苔与裂痕。据说在某个清晨，附带一张字条的它出现在村庄的神像旁，字条上只写了一行字：喝下它，瘟疫就会结束。长老自愿第一个服下作为试验者，在验证其功效后，所有患病的村民都服下了解药，不出一周村庄的瘟情就得到了控制。由于至今无人知晓到底是谁放置的，这瓶药水被村民们称为“神之怜悯”。',NoSale=1,NoStorage=5,}",
  [53764] = "{id=53764,NameZh='机器残片',Icon='item_62001',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29047,AdventureValue=126,AdventureReward={rewardid={870245}},Condition=64,Desc='看起来像是某种机器的一部分，由于年代久远，表面早已锈迹斑斑，但是依稀可以辨识出雷根贝勒公司的标识。据说在25年前，艾因布洛克原野上矗立着一座每天排放黑烟的巨大机器。在瘟疫爆发后的某天，有人声称见到一个身穿雷根贝勒公司制服的人影徘徊在机器附近，那天过后，机器便停止了运转，公司多次派人前来修理，但都回天无力，最终不得不宣布放弃此机器。机器停转后的25年间，原野再无瘟疫。',NoSale=1,NoStorage=5,}",
  [53765] = "{id=53765,NameZh='机密文件',Icon='task_53635',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29048,AdventureValue=126,AdventureReward={rewardid={870246}},Condition=64,Desc='记载着雷根贝勒公司某个实验的机密文件，已经被某人毁坏到无法读取其中的内容。原野实验机排出的气体会引起让人体溃烂的瘟疫，这是早就通过试验确认的结论。但是我没想到情况会这么糟糕，公司与议会竟然封锁解药的消息！这是想用全村人做人体实验么？我必须为那些无辜的人做些力所能及的事。毕竟，我也是造成这场瘟疫的罪魁祸首之一。即使这么做远不足以用来赎罪，但我必须对此负责。对不起，我亲爱的宝贝女儿，爸爸从一开始就选错了道路。时间紧迫，我必须马上出发了！这份关于机器与实验的机密文件，不能留给公司。',NoSale=1,NoStorage=5,}",
  [53766] = "{id=53766,NameZh='粉色发卡',Icon='item_45127',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29049,AdventureValue=126,AdventureReward={rewardid={870247}},Condition=64,Desc='波利式样的粉色发卡，是20多年前流行的旧款。和往常一样，小女孩靠在窗边托着红扑扑的小脸蛋，双眼紧盯着朱诺人来人往的街道，她在等待忙碌的父亲工作归来抱抱她。咚咚！突然传来的敲门声让她欣喜地冲向门边。爸爸！带着稚气地呼喊却迎来两位高大的陌生人，请问艾恩·格林先生在家么？冷峻的语气让女孩不知所措，爸爸还没回来呢，你们有什么事？你的爸爸不会回来了，面无表情的陌生人淡然的宣告着。女孩的泪珠一下涌出眼眶，骗人！爸爸答应我今天会替我补过生日的！这个粉色发卡就是他送给我的礼物！陌生人一把推开女孩进入房间搜查，女孩的嚎啕湮没在天空之城的云间。',NoSale=1,NoStorage=5,}",
  [53767] = "{id=53767,NameZh='尘封的真相',Icon='item_3882',Type=63,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=29050,AdventureValue=154,AdventureReward={rewardid={870248}},Condition=64,Desc='25年前，艾因布洛克的某个村庄突然爆发了一场致命瘟疫。与此同时，雷根贝勒公司的执行部长艾恩·格林带着一份机密文件离奇失踪，令人啧啧称奇的是，一瓶解药与神秘字条突然出现在村庄的神像旁，解药让疫情在短时间内得到了控制，疑似污染源的机器也由雷根贝勒公司宣布永久损坏。至于杳无音信的艾恩部长，有人说他带着充斥罪证的机密文件畏罪潜逃到了异国他乡；有人说见到他感染了瘟疫，死在了原野的林间，恶有恶报。但无论真相如何，原野的伤痕尚未完全愈合，卡尔总统任职后将治理原野的污染放在了朱诺政府的最高优先级。',NoSale=1,NoStorage=5,}",
  [53768] = "{id=53768,NameZh='矿工的铁镐',Icon='dark_005',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29051,AdventureValue=126,AdventureReward={rewardid={870249}},Condition=64,Desc='这把铁镐是矿工欧尼斯特的物件，一直以来镐子都是他挖矿的唯一工具。挖矿是一件很辛苦的事情，而在熔岩洞窟里的高温更是令人苦不堪言。但欧尼斯特不怕苦，他甚至很喜欢与这些矿石打交道，每天都兴致勃勃的提着铁镐去工作。在他的认知里，这整个洞窟都是一个宝藏，有大量的上等矿石，有神奇的地质地貌，还有令人畏惧的炎之领主卡浩。他每天都通过自己的双手与双脚去感知这个地方，他了解这边的每一块地形，他也了解这个洞窟的物质构成，这一切都是通过他日积月累的观察而获得的。他觉得似乎他能听到洞窟的呼吸声，什么地方出矿，什么地方危险，他都能通过洞窟的呼吸声判断出来。不知从哪一天开始，传进耳朵里的呼吸声一天一天的变得沉重，到后来他甚至能听出声音中的痛苦。怎么了？为什么你如此的痛苦？他伸出手想要触摸石壁，但他眼前一黑，然后就什么都不知道了……',NoSale=1,NoStorage=5,}",
  [53769] = "{id=53769,NameZh='残破的推车',Icon='item_25300',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29052,AdventureValue=126,AdventureReward={rewardid={870250}},Condition=64,Desc='在一群青壮的矿工之中，有一个小小的身影，他推着只比他矮一个头的推车，将矿石运到洞窟外。男孩名叫莱尼尔，是不远处村庄里的孩子。妈妈常年卧病在床，全家依靠着爸爸的收入生活。后来爸爸在矿洞里出了意外，小小年纪的他为了担负起家里的开支，来到爸爸的矿洞想要谋一份工作。大家伙也都知道莱尼尔家的情况，他没有足够的身高和体力去挖矿，工头便给了他一辆推车。男孩小小的脸崩的紧紧的，牙床用力咬合着，额头上流着大颗大颗的汗，一步一步的推着这辆车。当他终于推着车走到洞口，外面的光线一下子刺的他眯起了眼，他深吸了一口外面的空气，空气里夹杂着些许金属的味道。工头向他招了招手，他将推车停放在一旁，双手在身侧的衣服上擦了两下，往回走去，伸手接过一个装着铜钱的袋子。就在此时，大块大块的石头从洞顶掉下，莱尼尔被砸晕在了地上，双手仍牢牢护着那袋铜钱。',NoSale=1,NoStorage=5,}",
  [53770] = "{id=53770,NameZh='古老的矿工帽',Icon='item_45025',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29053,AdventureValue=126,AdventureReward={rewardid={870251}},Condition=64,Desc='瓦尔特是个很胆小的人，但是他仍然干了自己明知十分危险的职业，这是因为这里独一无二的火焰矿石使得在这里的矿工可以赚到远远高出其他工作的报酬。瓦尔特对所有的安全问题都十分在意，哪怕在这么炎热的洞窟里，他的矿工帽从来不会摘下，以至于闷的头发掉了很多，如此他就更不会摘下帽子了。矿洞里的矿工们都敬炎之领主卡浩为他们守护神，因为这里的财富全都来源于卡浩的力量，但是瓦尔特却从来不这么觉得，在他眼里，卡浩就是个可怕的火焰魔物，这么可怕怎么可能是守护神呢？瓦尔特就这样每天小心翼翼的挖着矿，别的矿工看他这副样子有些不顺眼，便联手趁他不注意摘下了他的矿工帽。看着他头上一块光秃秃的头皮，矿工们都笑出了声。瓦尔特突然感觉到了一阵不安，他连忙想要抢回自己的帽子，就在此时，洞窟内突然剧烈的摇晃了起来，瓦尔特在感觉到头顶的疼痛后，失去了意识……',NoSale=1,NoStorage=5,}",
  [53771] = "{id=53771,NameZh='火焰矿石',Icon='item_12550',Type=63,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=29054,AdventureValue=154,AdventureReward={rewardid={870252}},Condition=64,Desc='火焰矿石是由熔岩洞窟里的矿石吸收了炎之领主卡浩散发出来的火焰力量，在高温的环境下产生的一种独一无二的矿石。由于采矿的环境极其恶劣，而矿石又深受魔法师们的欢迎，价格自然是水涨船高。熔岩洞窟里的矿工们十分感激为他们带来这种矿石的炎之领主，因为矿石的存在，他们虽然自己辛苦了一些，但是家里人的日子都比以往好上许多。这些矿工们将卡浩敬为守护神，希望他能庇佑大家。卡浩也并不在意人类的这些行为，他甚至觉得能帮助到他们一些也是他所愿意的。但是渐渐的卡浩觉得事情有点不对劲，熔岩洞窟里的火焰传达给他的信息是洞窟受到了严重的破坏。卡浩发现是人类的过度采矿导致了洞窟的基脉发生了变化。他通过各种手段警告人类，但是人类却无动于衷。直到有一天，洞窟发生了一次巨大的震动，人类死伤惨重，洞窟的基脉也发生了严重的变形。卡浩愤怒异常，他认为是人类的贪婪与不知进退导致洞窟的环境受到了破坏与污染。卡浩将所有的矿工们都赶出了洞窟，从此火焰矿石失去了产出，市面上留存的矿石都成为了稀世珍宝。',NoSale=1,NoStorage=5,}",
  [53772] = "{id=53772,NameZh='粟米糖',Icon='item_6134',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29055,AdventureValue=105,AdventureReward={rewardid={870253}},Condition=64,Desc='不给糖就捣蛋！不给糖就捣蛋！孩子们对糖果的执念有时候是大人无法理解的。如果在半夜里有孩子敲门问你要糖，还是乖乖的拿出来吧。不然谁也无法保证这个夜晚你还能安然入睡……',NoSale=1,NoStorage=5,}",
  [53773] = "{id=53773,NameZh='南瓜灯',Icon='item_3713',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29056,AdventureValue=105,AdventureReward={rewardid={870254}},Condition=64,Desc='南瓜灯保护你回家，南瓜灯保护你回家。精心雕刻的南瓜配上点燃的蜡烛，照亮着回家的路。如果随意熄灭点燃的南瓜灯，南瓜先生的报复可不是随便说说的，准备好付出代价吧！',NoSale=1,NoStorage=5,}",
  [53774] = "{id=53774,NameZh='太妃糖苹果',Icon='item_157',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29057,AdventureValue=105,AdventureReward={rewardid={870255}},Condition=64,Desc='镜子啊镜子，我未来的丈夫是什么样子？少女们在寂静的黑夜里，对着镜子，点燃蜡烛，手里拿着苹果。她们的心中都有着相同的悸动，镜中的影像又是否和她们梦中所想的一样呢？',NoSale=1,NoStorage=5,}",
  [53775] = "{id=53775,NameZh='神奇扫帚',Icon='item_900029',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29058,AdventureValue=105,AdventureReward={rewardid={870256}},Condition=64,Desc='快扫干净吧！快扫干净吧！女仆嘴里呢喃着，心无旁骛的拿着扫帚扫着地。这可是魔女的扫帚啊，一定可以把这里打扫的干干净净的。只要扫干净了，主人就不会责难我了，只要扫干净了，我就解脱了……',NoSale=1,NoStorage=5,}",
  [53776] = "{id=53776,NameZh='黑猫铃铛',Icon='item_52312',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29059,AdventureValue=126,AdventureReward={rewardid={870257}},Condition=64,Desc='铃铃铃~铃铃铃~铃铛发出清脆的声音，魔女知道是她的小黑猫来了。黑猫轻盈的跳上她的肩膀，亲昵的蹭了蹭她的脸颊。魔女开心的笑了，她推开门想要去看看外面的月光，却不知道等着她们的是厄运。',NoSale=1,NoStorage=5,}",
  [53777] = "{id=53777,NameZh='森林之心',Icon='item_53777',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29060,AdventureValue=126,AdventureReward={rewardid={870258}},Condition=64,Desc='森林的至宝，只有哥布灵国王才会制作，是需要融合森林的四大宝物——森之虹、森之音、森之泪和森之花中蕴含的力量，才能造就的宝石。其中蕴含着森林的力量，只有真正获得哥布灵王认可的人才能获得它的祝福。',NoSale=1,NoStorage=5,}",
  [53778] = "{id=53778,NameZh='森之虹',Icon='item_53778',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29061,AdventureValue=105,AdventureReward={rewardid={870259}},Condition=64,Desc='森林四大宝物之一，是只有来自森林里的水在森林气息的包围下，才能产生的独特彩虹，通过祈祷就能转化为食物。本身充满了森林的力量，听说还能食用，味道甜甜的，是小哥布灵们最喜欢零食之一。',NoSale=1,NoStorage=5,}",
  [53779] = "{id=53779,NameZh='森之音',Icon='item_53779',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29062,AdventureValue=105,AdventureReward={rewardid={870260}},Condition=64,Desc='森林的四大宝物之一，是森林中的魔物用树叶吹出的音乐，通过神奇的木片可以实体化。将森之音放在耳边，就能听到这段美妙的音乐。传说中将森之音放在枕边有助于安眠，还能有机会在梦中与吹奏者相遇。',NoSale=1,NoStorage=5,}",
  [53780] = "{id=53780,NameZh='森之泪',Icon='item_53780',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29063,AdventureValue=105,AdventureReward={rewardid={870261}},Condition=64,Desc='森林的四大宝物之一，其本身是吸收着森林气息自然产生的露珠，当然极少的露珠才能成为森之泪。而且森之泪的保存十分困难，必须用森林中的木材制作的器皿才能完好的保存它。得到这个宝物之后，可要万分小心了。',NoSale=1,NoStorage=5,}",
  [53781] = "{id=53781,NameZh='森之花',Icon='item_53781',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29064,AdventureValue=105,AdventureReward={rewardid={870262}},Condition=64,Desc='森林的四大宝物之一，是由森林精灵赋予森林中的野花力量，从而造就的宝物。森林精灵特别喜欢食用花蜜，听说只要花蜜的香味足够美味，就能引她现身。总体来说森林精灵对人是很友好的，但如果你破坏森林的环境，她也会变得很恐怖。',NoSale=1,NoStorage=5,}",
  [53782] = "{id=53782,NameZh='湛蓝者之心',Icon='item_53735',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29065,AdventureValue=126,AdventureReward={rewardid={870263}},Condition=64,Desc='海底皇室世代相传的宝物，若是海底族群拥有它便可以获得永生，若是人类拥有它便可以受到大海的保佑和庇护。',NoSale=1,NoStorage=5,}",
  [53783] = "{id=53783,NameZh='梦幻海藻',Icon='item_53726',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29066,AdventureValue=105,AdventureReward={rewardid={870264}},Condition=64,Desc='在四海至宝之中象征坚忍，拥有天然的防护能力，可抵御大部分的魔法和冲击，但惧怕海盐。',NoSale=1,NoStorage=5,}",
  [53784] = "{id=53784,NameZh='闪光珊瑚',Icon='item_53727',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29067,AdventureValue=105,AdventureReward={rewardid={870265}},Condition=64,Desc='在四海至宝之中象征璀璨，能永恒不灭地发散光芒，无论多么黑暗的地方，都能被它照亮。',NoSale=1,NoStorage=5,}",
  [53785] = "{id=53785,NameZh='玲珑水晶',Icon='item_53728',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29068,AdventureValue=105,AdventureReward={rewardid={870266}},Condition=64,Desc='在四海至宝之中象征透彻，能驱散大海深处的污浊，若长久随身携带，携带者的内心也会逐渐被净化。',NoSale=1,NoStorage=5,}",
  [53786] = "{id=53786,NameZh='千年鳞片',Icon='item_53729',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29069,AdventureValue=105,AdventureReward={rewardid={870267}},Condition=64,Desc='在四海至宝之中象征沉稳，能平息大海暴乱的洋流，鳞片上的图腾，蕴含着千年来所有海洋魔法的奥秘。',NoSale=1,NoStorage=5,}",
  [53787] = "{id=53787,NameZh='毛线球',Icon='item_53730',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29070,AdventureValue=105,AdventureReward={rewardid={870268}},Condition=64,Desc='一个软绵绵的毛线球，手感非常的舒服！作为猫咪们的最爱之一，要是把它带回猫咪之家，那些喵喵喵的小可爱就会回来吧？在收集了足够的绒毛作为原料后，梅丽大婶帮助冒险者编织了专属猫咪之家的毛线球，看来那些小猫咪还真是深受南门居民的喜爱呢！',NoSale=1,NoStorage=5,}",
  [53788] = "{id=53788,NameZh='小鱼干',Icon='item_53732',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29071,AdventureValue=105,AdventureReward={rewardid={870269}},Condition=64,Desc='由普隆德拉南门的渔夫比尔森制作的小鱼干，散发出香喷喷的气味，深受猫咪们的喜爱。原本渔业富饶的南门海岸突然抓不到鱼了，冒险者答应比尔森调查真相原来是跑来了一只贪吃的海怪！战胜海怪后，南门的鱼群再次回归，比尔森答应为猫咪之家供应鱼干，这下，公告栏上的愿望就完成了一个，会不会有小可爱回到猫咪之家呢？',NoSale=1,NoStorage=5,}",
  [53789] = "{id=53789,NameZh='发条吱吱',Icon='item_53733',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29072,AdventureValue=105,AdventureReward={rewardid={870270}},Condition=64,Desc='不知道是谁制作的发条玩具老鼠，只要拧上发条，就会吱吱吱的快速移动。原本作为猫咪之家最受喜爱的玩具，却被小男孩汤米拾到占为己有。汤米说，只要冒险者陪自己捉迷藏，就归还发条吱吱。但捉迷藏途中汤米却发生了意外，在解救出被荆棘困住的汤米后，这个调皮又孤单的男孩总算露出了开朗的笑容。',NoSale=1,NoStorage=5,}",
  [53790] = "{id=53790,NameZh='肉球印章',Icon='item_53734',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29073,AdventureValue=105,AdventureReward={rewardid={870271}},Condition=64,Desc='来自猫咪们友情的证明，“谢谢你帮助猫咪之家的重建工作！喵！”在完成了猫咪之家所有的任务后，那些可爱的猫咪们总算是愿意回来啦！猫咪之家也恢复了往日的热闹，在往后的冒险中，感到疲惫的话，欢迎回来看看这些闹腾的猫咪噢！',NoSale=1,NoStorage=5,}",
  [53791] = "{id=53791,NameZh='房客日记',Icon='item_3773',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29074,AdventureValue=105,AdventureReward={rewardid={870273}},Condition=64,Desc='这就是传说中的低语山庄吗？独眼的贝茨克里夫男爵，缠着缎带的男爵夫人，带着疤痕的家仆，这一切都让人不安，但客房却意外的舒适，我刚合上眼睛准备美美睡上一觉，却听见“咣当”一声，一阵大风吹开了窗户，我走上前关窗，突然！一双冰冷的手拽住了我的手腕，我出于惊恐失声尖叫，那双手立马松开并消失在窗外的夜幕中。闻声而来的管家听闻了此事只敷衍的安抚了我几句，真的是幻觉嘛？我忍不住翻开日记想要写下这一切，关于这神秘的低语山庄……等等，窗户上好像留下了一行字！秘密在地下室。山庄的地下室藏着什么秘密呢？最后，好奇心战胜了恐惧，我决定前往地下室一探究竟！（字迹中断）……低语，低语，低语，地狱，地狱，地狱！',NoSale=1,NoStorage=5,}",
  [53792] = "{id=53792,NameZh='红色缎带',Icon='item_52410',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29075,AdventureValue=105,AdventureReward={rewardid={870274}},Condition=64,Desc='很久以前，有一位富豪在斯凯领顿一座避暑山庄。每年夏天他们一家都会带着仆人来到山庄度假。富翁有个野性未脱的女儿，十分喜爱冒险，某个夏天，女孩遇见了一位流浪的男孩，两人一见钟情，私定终身。得知此事的富翁暴跳如雷，派人捉来男孩亲自剜去他的右眼，并把他永远驱逐，女孩伤心过度，将自己锁在山庄的客房闭门不出，多年以后，一位异国的独眼医生拜访山庄，长大成人的女孩听到了熟悉的声音，狂喜地打开房门，在她面前的果然是往日的恋人，她向她递上一个大大的礼物，女孩欣然解开红色缎带，里面是她父亲新鲜的头颅。',NoSale=1,NoStorage=5,}",
  [53793] = "{id=53793,NameZh='地下室钥匙',Icon='item_52321',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29076,AdventureValue=105,AdventureReward={rewardid={870275}},Condition=64,Desc='据说在斯凯领顿有一座闹鬼的山庄，山庄的主人是一位异国的医生，他的爱人在某一天由于过度惊吓而猝死，悲痛的医生将爱人的尸体冷藏了起来，将自己没日没夜地锁在地下室，与此同时山庄突然开始欢迎宾客入住，但是房客们每晚都能听见山庄底下传出诡异的咀嚼声。终于在某一天，男爵打开了地下室的大门，带出一位浑身缠满红色缎带的女人。她是我的新夫人，医生欣喜若狂的宣布。随着新夫人的到来，入住的房客陆续失踪。没人知道山庄里发生了什么，直到今天地下室仍然每晚都会发出咯吱咯吱的咀嚼声。',NoSale=1,NoStorage=5,}",
  [53794] = "{id=53794,NameZh='17号档案',Icon='22',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29077,AdventureValue=105,AdventureReward={rewardid={870276}},Condition=64,Desc='此份档案永不备份，永久封藏。犯人贝茨克里夫医生杀害低语山庄主人，并使其女过度惊吓而死。后利用异国邪道医术将她的身体与魔物融合，创造了一个会在晚上变为嗜血魔物的双面魔女。医生在夜晚将魔女锁于地下室，引诱拥有强健肉体者来访，杀害后作为强化魔女肉体的素材与饲料。这一举动触怒死亡女神海拉，她亲自歼灭了魔物与贝茨克里夫医生，并烧毁了低语庄园。但近来却出现传闻，原本已被毁灭的山庄，重新出现在斯凯领顿。',NoSale=1,NoStorage=5,}",
  [53795] = "{id=53795,NameZh='锋利的手术刀',Icon='item_40744',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29078,AdventureValue=105,AdventureReward={rewardid={870277}},Condition=64,Desc='人到暮年的弗兰肯是一位著名的外科医生，某天他在墓地安葬死者时，发现了一位独眼的男孩。男孩衣衫褴褛，空洞的右眼眶流着脓血。膝下无子的老医生将男孩带回家治疗，并收他为养子。聪明的男孩很快学会了弗兰肯超凡的医术，老医生欣慰的感概后继有人。直到某天，弗兰肯发现男孩私自用患者进行人体实验，失望又愤怒的老医生把养子赶出了家门。这天深夜，悲痛欲绝的老弗兰肯在床上辗转反侧，他感到心里空空的，似乎少了什么。突然一个熟悉的声音响起，谢谢您教我的一切，我该回去复仇了。男孩穿着他的白大褂从他床边转身离开。弗兰肯低头看了一眼自己的胸口，只有一个血淋淋的窟窿，心脏早已被男孩挖去。',NoSale=1,NoStorage=5,}",
  [53796] = "{id=53796,NameZh='字迹潦草的信',Icon='item_task_34',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29079,AdventureValue=105,AdventureReward={rewardid={870278}},Condition=64,Desc='救命，谁来救救我。这座低语山庄里到处都是魔物!医生夫人背后的红色缎带下还有另一张女人的脸！我亲眼看到医生把生肉喂给那第二张脸，还用别人的皮肤缝合他夫人的腐烂伤口！希望这封信能被人发现，我感觉医生已经察觉了我的不安，如果有谁捡到这封信的话，一定要把这座地狱山庄的秘密公之于众！',NoSale=1,NoStorage=5,}",
  [53797] = "{id=53797,NameZh='低语山庄邀请函',Icon='task_certificate',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29080,AdventureValue=126,AdventureReward={rewardid={870279}},Condition=64,Desc='由低语山庄的主人——贝茨克里夫医生亲笔书写的邀请函，据说独眼的男爵在山庄里藏着不可告人的秘密，只要拿着邀请函在斯凯领顿的某个石碑旁等待，迎接客人的马车从浓雾中出现。到访山庄的房客几乎没人能平安归来，至于是否要去，决定权在于你自己。',NoSale=1,NoStorage=5,}",
  [53798] = "{id=53798,NameZh='外婆的披肩',Icon='item_task_19',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29081,AdventureValue=126,AdventureReward={rewardid={870280}},Condition=64,Desc='因为最疼爱的孙女来探望自己了，老妇人即使身体不适依然披上了自己最喜欢的一条披肩。“笃笃笃！”传来了敲门声，虽说时间早了一些，她依旧满心欢喜的前去开门了。刚打开一条缝，一双巨大的尖爪便伸了进来……再次见到这条披肩，它的新主人变成了一只可怖的野兽，瞪着双眼披上伪装，静候着它的猎物。',NoSale=1,NoStorage=5,}",
  [53799] = "{id=53799,NameZh='格曼的猎枪',Icon='item_900018',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29082,AdventureValue=126,AdventureReward={rewardid={870281}},Condition=64,Desc='作为猎人协会著名的魔物猎手，格曼对狩猎有着与生俱来的直觉，当他听到某种满足的嚎叫，他的心中便产生了一种不好的预感。他追踪着足迹来到那间小木屋，眼前的景象还是让他这位老猎人作呕不已。在一片狼藉中，狼外婆满足的睡在被鲜血染成猩红的床上做着美梦。格曼毫不犹豫地将枪口对准这只野兽，但是他没想到的是，这个魔物一下跃起握住了枪管，挺着肚子夺走了格曼的猎枪仓惶地消失在了树林地黑暗中，格曼对那只野兽的最后一个印象是，它那硕大的肚子里有什么在怪异的蠕动……',NoSale=1,NoStorage=5,}",
  [53800] = "{id=53800,NameZh='罗夏薇拉的日记',Icon='item_3684',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29083,AdventureValue=126,AdventureReward={rewardid={870282}},Condition=64,Desc='这本日记的封面上工整的写着罗夏薇拉这个名字，它的主人应该是个花季少女，虽说偷看别人的日记并不是什么好的习惯的，但这本日记只写了一半便没了下文。有内容的最后一页上写着：“独自居住的外婆生病了，妈妈让我明天带上蛋糕，水果和葡萄酒去探望她。很久没见到疼爱我的外婆，我准备穿上我最喜欢的洋装，戴上外婆送给我的小红帽，打扮得漂漂亮亮得去见她，外婆一定会非常高兴吧，妈妈说不要走林间的小路，她可真是多虑，这个世界上哪来这么多吃人的野兽？”',NoSale=1,NoStorage=5,}",
  [53801] = "{id=53801,NameZh='可爱的提包',Icon='item_41547',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29084,AdventureValue=126,AdventureReward={rewardid={870283}},Condition=64,Desc='这个可爱的女式提包里装了可口的水果，面包，还有一瓶似乎是自家酿的葡萄酒。那女孩提着包在林间穿行的场景就像一幅古老的油画，在我脑中逐渐清晰，缓缓浮现。提包的主人一定是去见她很珍视的人吧，我多么希望她只是躺在树荫底下，做了一个太长的美梦，醒来仍是豆蔻色的年华。',NoSale=1,NoStorage=5,}",
  [53802] = "{id=53802,NameZh='猩红的洋装',Icon='item_52328',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29085,AdventureValue=126,AdventureReward={rewardid={870284}},Condition=64,Desc='一件被鲜血浸透的红色洋装，诉说着它主人的悲惨命运。据说红帽女孩罗夏薇拉被狼外婆活生生的吃掉了，她最喜欢的洋装成了外婆狼的战利品。美好的事物总是容易被摧毁，无论在什么时代，邪恶总会披上各种各样的伪装，而善良总是一如既往的单纯与炽热。',NoSale=1,NoStorage=5,}",
  [53803] = "{id=53803,NameZh='染血的红帽',Icon='item_45413',Type=63,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=29086,AdventureValue=154,AdventureReward={rewardid={870285}},Condition=64,Desc='这顶帽子因为主人的血液而变得更加鲜红。世界并不会因为你的纯真与闪亮而变得柔软。黑暗中的野兽随时蛰伏着等待下一个猎物。而猎人与猎物在这片古老的雾之森林中并不是绝对的身份。不想被猎杀的话，就成为强大的猎杀者吧。生存的残酷法则中，只有活下去，才是唯一的真理。',NoSale=1,NoStorage=5,}",
  [53804] = "{id=53804,NameZh='永生玫瑰',Icon='item_52012',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29087,AdventureValue=105,AdventureReward={rewardid={870286}},Condition=64,Desc='“玫瑰啊玫瑰，你得快快长大。”威尔克将自己的手腕割开，让鲜血流入泥土里，他嘴里叨念着：“你长大了，我就能向艾米丽求婚了。”玫瑰沐雨在透过窗口洒进来的月光中，而他却将自己藏在阴影之中。“深蓝星辰……我的宝物……“他收回手，用手帕擦拭着自己的手腕，而伤口已经奇迹般的愈合了，而玫瑰在他的面前慢慢绽放。',NoSale=1,NoStorage=5,}",
  [53805] = "{id=53805,NameZh='洁白头纱',Icon='item_48583',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29088,AdventureValue=105,AdventureReward={rewardid={870287}},Condition=64,Desc='卡森低头看向自己的胸口，手里还拿着艾米丽的头纱，一柄长剑从心口穿出。艾米丽就在他的面前，剑头差点就要伤到她。卡森后退了一步，让剑头远离艾米丽。“卡森，卡森……”艾米丽迷茫的看着发生的一切，眼里的惊恐涌了上来。然后她看到了，看到卡森背后的那个人，露着尖牙盯着自己。那人猛地拽过艾米丽的手，将她紧握的手指掰开，拿到了一把钥匙。',NoSale=1,NoStorage=5,}",
  [53806] = "{id=53806,NameZh='礼服领带',Icon='item_45054',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29089,AdventureValue=105,AdventureReward={rewardid={870288}},Condition=64,Desc='威尔克整理了一下领带，精神抖擞的站在城堡门口，看着一步一步走来的新娘。艾米丽的面容隐在头纱后，看不清表情，但威尔克认为她一定是很高兴。就在他要伸手去牵住艾米丽的时候，一个青年挡在了他的面前。青年牵住新娘的手向外跑去，而新娘似乎没有一丝的挣扎，在大家愣神的时候，两人已消失不见。威尔克深吸了一口气，提起一把长剑，向外追去……',NoSale=1,NoStorage=5,}",
  [53807] = "{id=53807,NameZh='告白情书',Icon='item_task_34',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29090,AdventureValue=105,AdventureReward={rewardid={870289}},Condition=64,Desc='一封卡森写的情书，上面写着——致亲爱的艾米丽：在上次舞会上的相遇后，我对你的思念一天比一天的强烈，强烈到让我快无法呼吸。即使知道你已有婚约，而婚礼将会在明天举行，但是这都不能阻挡你和我之间的爱恋。你还记得我们的约定吗？明天早上花园里见，我将履行我的承诺，我将为你戴上戒指，为了我爱的你。',NoSale=1,NoStorage=5,}",
  [53808] = "{id=53808,NameZh='蓝星戒指',Icon='item_6059',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29091,AdventureValue=105,AdventureReward={rewardid={870290}},Condition=64,Desc='“艾米丽，你愿意嫁给我吗？”“我愿意！”卡森小心翼翼的掀开艾米丽的头纱，两人四目相对，彼此都有许多话想要说。”卡森，我有东西想给你。“卡森温柔的抚摸着艾米丽的脸：“先让我把东西给你。”卡森拉起艾米丽的手，想要将蓝星戒指给艾米丽戴上。一阵刺痛从胸口传来，随之而来的是暖暖的热流。捏在手里的戒指叮当的一声，掉在了地上……',NoSale=1,NoStorage=5,}",
  [53809] = "{id=53809,NameZh='舞会假面',Icon='item_48545',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29092,AdventureValue=105,AdventureReward={rewardid={870291}},Condition=64,Desc='小镇上有个城堡，主人是个优雅的绅士，他与镇上一个富裕家庭的小姐订了婚，为了宣布这个消息，他举办了一场假面舞会。卡森拿着自己制作的假面去城堡参加了这场舞会。他的双眼在假面的背后，漫不经心的打量着全场。一个姑娘的出现吸引了他的全部注意力，他踱步上前，邀请这位同样戴着假面的姑娘一起跳舞。随着音乐跳动的，是两颗年轻悸动的心。',NoSale=1,NoStorage=5,}",
  [53810] = "{id=53810,NameZh='宝箱钥匙',Icon='item_52321',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29093,AdventureValue=105,AdventureReward={rewardid={870292}},Condition=64,Desc='一把精致的金色钥匙，能打开艾米丽家的宝箱。在婚礼前一天的晚上，艾米丽的父亲将这把钥匙亲手交给了她，告诉她宝箱里有一颗他们家族代代相传的宝物——一颗深蓝色的珍珠。父亲只有艾米丽一个女儿，这个钥匙是他给女儿的最重要的嫁妆，希望她能交给自己的丈夫，能一生幸福美满。艾米丽明白父亲的苦心，她一定会将这把钥匙交给自己未来的丈夫。',NoSale=1,NoStorage=5,}",
  [53811] = "{id=53811,NameZh='银质刺刀',Icon='item_900006',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29094,AdventureValue=105,AdventureReward={rewardid={870293}},Condition=64,Desc='艾米丽的双手被鲜血染红。她拿出藏在裙底的刺刀，深吸了口气，整个人猛地向前冲去。威尔克此时正看着手中的金色钥匙，没有防备的被刺刀刺中了手臂。他毫不在意，因为这小伤口对他来说不值一提。但当他看清刺刀是银质的时候，他才惊觉：“你知道我是吸血鬼！”艾米丽没有回答，她拔出卡森胸口的长剑，将自己送向刀口。“威尔克，你活不久了……”',NoSale=1,NoStorage=5,}",
  [53812] = "{id=53812,NameZh='深蓝星辰',Icon='item_3851',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29095,AdventureValue=126,AdventureReward={rewardid={870294}},Condition=64,Desc='一颗散发着幽蓝色光泽的珍珠，有着深海般的蓝色和星辰般的光芒。听说拥有这颗珍珠的人可以得到大海里的宝藏。艾米丽的先祖得到这颗珍珠后，也不知道发现了什么，将它锁在宝箱里，世世代代的传了下来。吸血鬼威尔克在在艾米丽父亲喝醉后得知了深蓝星辰的存在，他假意对艾米丽十分爱慕，获取了她父亲的信任，与艾米丽定了婚。而他的目的一直都只是这颗宝石背后传说中的宝藏。',NoSale=1,NoStorage=5,}",
  [53813] = "{id=53813,NameZh='黄金钥匙',Icon='item_task_67',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29096,AdventureValue=105,AdventureReward={rewardid={870295}},Condition=64,Desc='守财奴巴哈洛金库的钥匙，他曾向精灵神灯许愿，用黄金填满他的金库，但他的花销也变得越来越大。很快金子便被挥霍一空。被贪念蒙蔽双眼得巴哈洛再次寻求神灯精灵的帮助，却被精灵施加贪婪的诅咒变为一只黑狐。即使这样，他仍疯狂的渴求着金钱，其实，真正的诅咒是人心中的贪念，不是么？',NoSale=1,NoStorage=5,}",
  [53814] = "{id=53814,NameZh='龙骨魔笛',Icon='item_task_66',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29097,AdventureValue=105,AdventureReward={rewardid={870296}},Condition=64,Desc='用古老的龙族骸骨雕琢而成的笛子，吹奏出的乐曲被古老的魔法加持。在梦罗克，曾有一位贫穷的诗人，他暗恋着他的搭档——美丽的舞娘玛拉。为了玛拉，他找到了传说中可以实现任何愿望的精灵神灯。深爱玛拉的诗人许下愿望，希望玛拉得到幸福。愿望实现了，玛拉与梦罗克的富商波图过上了幸福的生活。诗人化为孤魂将思念寄宿在古老神灯中。感情是两个人的事，而所谓的幸福远比诗歌中臆想的残酷得多。',NoSale=1,NoStorage=5,}",
  [53815] = "{id=53815,NameZh='蓝宝石扳指',Icon='item_task_69',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29098,AdventureValue=105,AdventureReward={rewardid={870297}},Condition=64,Desc='镶嵌了蓝色宝石的扳指，戴上它后，触碰的一切都会变作黄金。这枚带着诅咒的扳指无法被本人脱下，据说只有拥有初心之人才能解开诅咒。在梦罗克，有位名叫波图的人向精灵神灯许愿想要无尽的财富。神灯精灵给了他这枚扳指，他戴上后，所接触的一切都变成了黄金！虽然他变成了梦罗克的富人，但他这辈子都不能在触碰他人。纵使有黄金，也买不到一个温暖的拥抱！',NoSale=1,NoStorage=5,}",
  [53816] = "{id=53816,NameZh='沙海之心',Icon='item_52208',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29099,AdventureValue=105,AdventureReward={rewardid={870298}},Condition=64,Desc='曾经有一位梦罗克出身的年轻水手，在一次航行中，恋上了搁浅的人鱼，为了与人鱼恋人长相厮守，他找到神灯精灵许愿，在梦罗克的沙漠中创造了一片海水绿洲，欣喜若狂的水手将长着鱼尾的新娘接回了梦罗克，并养育了一名女儿。但好景不长，水手的家族找上门来，将这对禁忌结合的夫妻带走。年幼的混血儿名为玛娅拉，她的双腿一旦接触到水，便会化作人鱼的尾巴，玛娅拉在绿洲中离群索居，在对人类的不信任中长大……童话终究事童话，并不是所有故事都拥有一个美好的结局。',NoSale=1,NoStorage=5,}",
  [53817] = "{id=53817,NameZh='精灵神灯',Icon='item_task_68',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29100,AdventureValue=126,AdventureReward={rewardid={870299}},Condition=64,Desc='梦罗克传说中的古老神灯，里面寄宿的神灯精灵，可以满足使用者的一个愿望。讲述故事的哈克鲁迪曾是个梦罗克的吟游诗人，得了不治之症的他为了延续生命，请求神灯精灵的帮助。哈克鲁迪唯一的愿望就是能一直给孩子们讲述故事。神灯精灵实现了的愿望，但代价是哈克鲁迪的灵魂永远会被束缚在这片土地，不断诉说着故事直到时间的终焉……他眼看着那些听他故事的孩子长大，不断有人为了追求自己的欲望而向神灯许下那些需要巨大代价的愿望，看着梦罗克中发生的欢笑与悲伤。哈克鲁迪曾以为一切都不会变，但孩子们会长大，会离开，故事会被遗忘。只有梦罗克的沙漠仍旧呼啸着，就像神灯精灵的嗤笑，嗤笑人类短浅的目光。',NoSale=1,NoStorage=5,}",
  [53818] = "{id=53818,NameZh='人面礼葬瓮',Icon='item_53818',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29101,AdventureValue=105,AdventureReward={rewardid={870300}},Condition=64,Desc='人面样式的礼葬瓮，里面存放了法老王的肝脏，作为复活仪式的一部分被存放在金字塔中。法老王对死灵祭司许诺，如果他能协助自己的重生仪式，死灵祭司也将被赐予重生的权利。但法老王欺骗了他，死灵祭司的灵魂被困在人面礼葬瓮中成为了冤魂。几百年过去，冤魂不改生前恶毒狡诈的本性，妄图借助献祭复生。人的本性究竟藏着多少的恶？',NoSale=1,NoStorage=5,}",
  [53819] = "{id=53819,NameZh='胡狼礼葬瓮',Icon='item_53819',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29102,AdventureValue=105,AdventureReward={rewardid={870301}},Condition=64,Desc='胡狼头样式的礼葬瓮，里面存放了法老王的胃脏，作为复活仪式的一部分被存放在金字塔中。死灵祭司对反对父亲的王子安毕斯施加了诅咒，使他成为了胡狼头的嗜血魔物徘徊在胡狼礼葬瓮的附近。某些时候相比起魔物，人类的欲望更加可怕呢。',NoSale=1,NoStorage=5,}",
  [53820] = "{id=53820,NameZh='猿猴礼葬瓮',Icon='item_53820',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29103,AdventureValue=105,AdventureReward={rewardid={870302}},Condition=64,Desc='猿猴头样式的礼葬瓮，里面存放了法老王的肺脏，作为复活仪式的一部分被存放在金字塔中。死灵祭司饲养的亡灵溜溜猴看守着这件遗物，不过对于溜溜猴来说，没有什么是一根魔物香蕉不能解决的，不行的话就两根。',NoSale=1,NoStorage=5,}",
  [53821] = "{id=53821,NameZh='鹰隼礼葬瓮',Icon='item_53821',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29104,AdventureValue=105,AdventureReward={rewardid={870303}},Condition=64,Desc='鹰头式样的礼葬瓮，里面存放了法老王的肠子，作为复活仪式的一部分被存放在金字塔中。法老王施加了邪术让他的亲卫队化作邪骸军队保卫着这件礼器，不知是狂热的忠诚还是诅咒的效果，百年间他们对法老王依旧忠心耿耿。',NoSale=1,NoStorage=5,}",
  [53822] = "{id=53822,NameZh='重生十字架',Icon='item_53822',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29105,AdventureValue=105,AdventureReward={rewardid={870304}},Condition=64,Desc='曾经是法老王后伊西斯塔的护声符，为了死而复生而癫狂的法老王亲手杀害了想要阻止他的王后，没想到重生十字架却给了她第二条生命，代价是变为人身蛇尾的魔物，永远不能再离开金字塔。据说这件来历不明的圣物与神域有关。',NoSale=1,NoStorage=5,}",
  [53823] = "{id=53823,NameZh='俄赛里斯之泪',Icon='item_53823',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29106,AdventureValue=126,AdventureReward={rewardid={870305}},Condition=64,Desc='得到了永生就能得到一切吗？每个人都有自己的答案，俄赛里斯为了永恒的生命，牺牲了自己的爱人，孩子与心。最后他的夙愿却沦为束缚他的枷锁。不老不死的俄赛里斯，失去了生而为人的资格成为魔物。他的泪水到底是因为被死亡女神惩罚而不甘还是对自己犯下错误感到悔恨呢，恐怕只有他自己才知道了。',NoSale=1,NoStorage=5,}",
  [53824] = "{id=53824,NameZh='香蕉奶油',Icon='item_53720',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29107,AdventureValue=105,AdventureReward={rewardid={870306}},Condition=64,Desc='虽然名字叫做奶油，其实是用香蕉做成的牛奶水果酱，不知溜溜猴用了什么办法，让这奶香与香蕉完美结合，是不可多得的上等甜品材料。西门的苍蝇一直是香蕉的头号威胁，而消灭苍蝇是与溜溜猴拉近关系的最好方式。',NoSale=1,NoStorage=5,}",
  [53825] = "{id=53825,NameZh='露珠果酱',Icon='item_53721',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29108,AdventureValue=105,AdventureReward={rewardid={870307}},Condition=64,Desc='使用普隆德拉西门的清晨露珠制作出的果酱，因为露珠很快就会在晨曦中蒸发，所以想要收集露珠制作果酱非常困难。据说有4位露珠仙子在西门收集露珠，只有通过仙子的考验才能得到她们珍藏的露珠果酱。',NoSale=1,NoStorage=5,}",
  [53826] = "{id=53826,NameZh='云朵酥',Icon='item_53722',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29109,AdventureValue=105,AdventureReward={rewardid={870308}},Condition=64,Desc='在普隆德拉西门从天而降的神奇酥饼，由于长得很像云朵，被取名为云朵酥，一口咬下去，蓬松清爽，满嘴都是甘甜的回味。发现云朵酥的追云少年——热埃尔一直喜欢着《国家地理》西门特派员：奥斯卡·王尔德。但他却始终没有勇气亲口说出这份情感，年轻时的情愫就像云朵，看起来很近，却无法触及。',NoSale=1,NoStorage=5,}",
  [53827] = "{id=53827,NameZh='松果布丁',Icon='item_53723',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29110,AdventureValue=105,AdventureReward={rewardid={870309}},Condition=64,Desc='把松果磨成粉末，然后打入大嘴鸟的蛋，加入牛奶充分搅拌后，用特殊的办法蒸煮，一颗爽滑的松果布丁就诞生了。虽然食材都非常简单，但实际上，很难有人能像格鲁多一样欣赏松果，并开发它的潜力。每个人都需要遇上一位懂得欣赏你的人，不然你可能永远不知道自己的潜力有多大。',NoSale=1,NoStorage=5,}",
  [53828] = "{id=53828,NameZh='彩虹西米露',Icon='item_53724',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29111,AdventureValue=105,AdventureReward={rewardid={870310}},Condition=64,Desc='沾染了彩虹气息的西米露，只有了解彩虹的人才知道制作它的方法。追逐彩虹的芮恩伯虽然拥有吃不完的彩虹西米露，但却怀念着西门的传统甜点——蛋黄糕。我从芭芭拉那里得到了热乎乎蛋黄糕，并用它与芮恩伯交换了彩虹西米露。珍馐虽好，但某些普通的食物却让人更加垂涎。可能是因为那些小吃都带着回忆的温度吧。',NoSale=1,NoStorage=5,}",
  [53829] = "{id=53829,NameZh='仙境蛋糕',Icon='item_53725',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29112,AdventureValue=126,AdventureReward={rewardid={870311}},Condition=64,Desc='由普隆德拉西门传说中的5种食材制作出的梦幻甜点：香滑的香蕉奶油，爽口的露珠果酱，入口即化的云朵酥，弹牙香浓的松果布丁，口感缤纷的彩虹西米露。这些食材的优点被淋漓尽致的结合并体现在了仙境蛋糕上，只要吃上一口，或许就能明白幸福的滋味了！',NoSale=1,NoStorage=5,}",
  [53869] = "{id=53869,NameZh='黑白琴键',Icon='item_53869',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29113,AdventureValue=105,AdventureReward={rewardid={870312}},Condition=64,Desc='燕姿人生中第一台钢琴上的黑白琴键，已经有些发黄了，但燕姿视它为珍宝。没有任何舞台上的光芒不需要台下的努力。燕姿深爱音乐，从小练习钢琴，在父母亲人的鼓励下一步一步地努力到今天。燕姿将这几枚黑白琴键留在身边，提醒着自己不忘热爱音乐的初心。',NoSale=1,NoStorage=5,}",
  [53870] = "{id=53870,NameZh='野雏菊',Icon='item_53781',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29114,AdventureValue=105,AdventureReward={rewardid={870313}},Condition=64,Desc='被做成小小干花的野雏菊，是孩子们送给母亲的礼物。燕姿无论有多忙，也总是会抽出时间陪伴自己的孩子，对她来说，孩子是她世界上最重要的人。两个孩子也深爱着自己的母亲，小小的他们用眼里最美丽的东西表达对母亲的爱。燕姿将这朵雏菊做成了干花，一直带在身边。',NoSale=1,NoStorage=5,}",
  [53871] = "{id=53871,NameZh='旧唱片',Icon='item_4001',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29115,AdventureValue=105,AdventureReward={rewardid={870314}},Condition=64,Desc='这张旧唱片是燕姿最早出的一张专辑，是她一个忠实的歌迷十多年来最宝贵的收藏。燕姿在一次演出时意外受伤后，歌迷将这张唱片送给了燕姿，令她勇敢的面对伤痛。从此之后，这张唱片一直激励着燕姿，她相信永远有爱她的歌迷在等着她。',NoSale=1,NoStorage=5,}",
  [53872] = "{id=53872,NameZh='金色奖杯',Icon='item_60512',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29116,AdventureValue=126,AdventureReward={rewardid={870315}},Condition=64,Desc='米德加尔特大陆音乐权威的最高奖项——安吉尔奖的奖杯。这代表了整个大陆对音乐人的认可。燕姿来到这个陌生的世界，凭借自己的热爱与才能，获得了这个奖项。这个奖杯见证了燕姿冒险生活新的开始，也见证米德加尔特大陆新一代歌姬的出现。',NoSale=1,NoStorage=5,}",
  [53873] = "{id=53873,NameZh='骑士团徽章',Icon='item_47098',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29117,AdventureValue=105,AdventureReward={rewardid={870316}},Condition=64,Desc='原本遭遇追捕的赛依连，利力，玛嘉雷特三人，趁着凯特莉娜引发的大火得到了逃离的机会，但赛依连为了阻止追兵独自留在了研究所。赛依连独自留在了生体研究所。',NoSale=1,NoStorage=5,}",
  [53874] = "{id=53874,NameZh='十字架吊坠',Icon='item_44019',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29118,AdventureValue=105,AdventureReward={rewardid={870317}},Condition=64,Desc='遭遇追捕的赛依连，利力，玛嘉雷特三人，趁着凯特莉娜引发的大火得到了逃离的机会，但赛依连为了阻止追兵独自留在了研究所。玛嘉雷特被大嘴鸟利力带出了生体研究所。',NoSale=1,NoStorage=5,}",
  [53875] = "{id=53875,NameZh='魔导护符',Icon='item_44031',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29119,AdventureValue=105,AdventureReward={rewardid={870318}},Condition=64,Desc='凯特莉娜苏醒后面前是疯狂的研究员们，他们继续对她进行着实验。由于负面情绪而暴走的凯特莉娜引发了魔导回路与人造心脏的共鸣，制造出了大爆炸，导致了研究所发生大火。而她现在下落不明……',NoSale=1,NoStorage=5,}",
  [53876] = "{id=53876,NameZh='手工八音盒',Icon='item_3977',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29120,AdventureValue=105,AdventureReward={rewardid={870319}},Condition=64,Desc='哈沃德在苏醒后第一时间开始寻找伙伴，不知为何没有警备队来追捕他。他遇到了正在异变的迪文，却通过音乐盒阻止了迪文的异变进程。',NoSale=1,NoStorage=5,}",
  [53877] = "{id=53877,NameZh='折断的箭矢',Icon='item_12503',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29121,AdventureValue=105,AdventureReward={rewardid={870320}},Condition=64,Desc='迪文苏醒后展示了她冷静的一面，并找到了雷根贝勒公司的机密档案，似乎记载着某种实验的进行。迪文记忆的最后一部分显示，她似乎由于某种影响，变得狂暴而嗜杀。',NoSale=1,NoStorage=5,}",
  [53878] = "{id=53878,NameZh='赤色围巾',Icon='item_43002',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29122,AdventureValue=105,AdventureReward={rewardid={870321}},Condition=64,Desc='艾勒梅斯在被抓入生体研究所后苏醒较早，他凭借强大的实力与刺客的隐匿技术逃离了追捕，但此时在他面前出现了一位谜之剑士，那位剑士的身份是……',NoSale=1,NoStorage=5,}",
  [53879] = "{id=53879,NameZh='研究所调查报告',Icon='item_63408',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29123,AdventureValue=126,AdventureReward={rewardid={870322}},Condition=64,Desc='六人小队在被抓入生体研究所后，部分成员被植入了所谓“人造心脏”的东西。迪文找到了部分机密文件，并发生异变；哈沃德遇见暴走的迪文，并成功将她唤醒；艾勒梅斯战胜雷根贝勒警备队后遇见了“谜之剑士”；凯特莉娜的暴走导致了生体研究所的大火。而原本遭遇追捕的赛依连，利力，玛嘉雷特三人，趁着凯特莉娜引发的大火得到了逃离的机会，但赛依连为了阻止追兵独自留在了研究所。六人小队成员的身上到底发生了什么？而“人造心脏”会让实验对象变成什么呢 ……',NoSale=1,NoStorage=5,}",
  [53880] = "{id=53880,NameZh='女武神的悲叹',Icon='item_60503',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29124,AdventureValue=105,AdventureReward={rewardid={870323}},Condition=64,Desc='A.W400年，魔王梦罗克入侵米德加尔特。大陆的毁灭危在旦夕，神王奥丁派遣了女武神与英灵战士前来支援。但梦罗克在死亡之塔的顶端建立了法阵，极大削弱了神族在人间的力量。神族败退，战争的结局似乎无法逆转。危急时刻，人类剑士达纳托斯出现在了战场上。为了与梦罗克决战，达纳托斯将灵魂与魔剑融为一体，只身前往死亡之塔。目睹了一切的女武神无力地叹息道：“人类为何总是执着改变于无法逆转的未来呢……”',NoSale=1,NoStorage=5,}",
  [53881] = "{id=53881,NameZh='枷锁核心',Icon='item_6201',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29125,AdventureValue=105,AdventureReward={rewardid={870324}},Condition=64,Desc='达纳托斯打败了魔王梦罗克后，自身的灵魂也逐渐被魔剑吞噬。二者终将融为一体，为了预防这股巨大的魔力再次给大陆带来灾难，达纳托斯便请求诸神，将自己和魔剑一同封印在死亡之塔里。奥丁理解他的深意，最终接受了这份请求。最后，在智慧巨人密米尔的帮助下，众神召集了九界中的各类生灵主持封印仪式，最终完成了封印塔的神器——奥术魔方。',NoSale=1,NoStorage=5,}",
  [53882] = "{id=53882,NameZh='混沌眼泪',Icon='item_task_04',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29126,AdventureValue=105,AdventureReward={rewardid={870325}},Condition=64,Desc='希尔斯——这位如月光般皎洁的少女，是达纳托斯一生所爱。她与达纳托斯从小一起长大，两人本该携手幸福共度余生，希尔斯却被魔王梦罗克的手下杀害。恋人去世后，达纳托斯决心向梦罗克复仇。他从占卜师那里得到了关于魔剑的线索，孤身一人毅然前往深渊之湖……',NoSale=1,NoStorage=5,}",
  [53884] = "{id=53884,NameZh='达纳托斯的追忆',Icon='item_6249',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29128,AdventureValue=105,AdventureReward={rewardid={870327}},Condition=64,Desc='战胜梦罗克之后，达纳托斯知道自己的灵魂被魔剑诅咒，灵魂终将与其相融。为了不让魔剑的诅咒扩散，达纳托斯选择进入塔中自刎。在生命的最后，他对着空旷的死亡之塔回想起自己的过往，最终微笑着举起了剑……',NoSale=1,NoStorage=5,}",
  [53885] = "{id=53885,NameZh='往日之剑',Icon='item_40356',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29129,AdventureValue=105,AdventureReward={rewardid={870328}},Condition=64,Desc='这把剑是达纳托斯尚未取得魔剑时所用的，见证了他所有的美好回忆。在步入塔中自刎前，达纳托斯不愿这把爱剑陪着自己一同腐化，便将它插在了塔前的空地上。但他不知道，这把剑早就与他的灵魂相连接，成为了其灵魂的一部分。它能感受到主人的痛苦，即使在塔外，这把剑也因共鸣而腐化。许多年后，大贤者巴特蒙德在发掘塔之遗迹的时候，发现了这把开始腐化的剑，并为剑制造了祭坛将它封印。只有结合5份力量，将诅咒消灭，才能解开剑的封印。',NoSale=1,NoStorage=5,}",
  [53886] = "{id=53886,NameZh='英魂挽歌',Icon='item_47098',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29130,AdventureValue=126,AdventureReward={rewardid={870329}},Condition=64,Desc='无数的英雄在米德加尔特大陆留下传说，时代造就了英雄，英雄改变了时代。达纳托斯的故事随着时间的沉淀，被记载在光辉的岁月里。而百年后，随着塞壬的陨落，英雄的接力棒交给了每一位见证历史的冒险者，宣告着这片大陆进入了英雄时代。“他们总伴随着黑暗而生，经历无数次的挣扎、绝望与抗争后，终会以自身为火，点燃米德加尔特的曙光。”',NoSale=1,NoStorage=5,}",
  [53887] = "{id=53887,NameZh='时光碎片·Ⅰ',Icon='item_12638',Type=48,Quality=2,MaxNum=99999,SellPrice=100,Desc='凝聚着某人记忆的碎片，能感觉到时光在其中静谧地流淌。如果能找到精通历史的学者询问，也许会知道它特殊的用途……',NoSale=1,NoStorage=5,}",
  [53888] = "{id=53888,NameZh='时光碎片·Ⅱ',Icon='item_12638',Type=48,Quality=2,MaxNum=99999,SellPrice=100,Desc='凝聚着某人记忆的碎片，能感觉到时光在其中静谧地流淌。如果能找到精通历史的学者询问，也许会知道它特殊的用途……',NoSale=1,NoStorage=5,}",
  [53889] = "{id=53889,NameZh='时光碎片·Ⅲ',Icon='item_12638',Type=48,Quality=2,MaxNum=99999,SellPrice=100,Desc='凝聚着某人记忆的碎片，能感觉到时光在其中静谧地流淌。如果能找到精通历史的学者询问，也许会知道它特殊的用途……',NoSale=1,NoStorage=5,}",
  [53891] = "{id=53891,NameZh='时光碎片·Ⅳ',Icon='item_12638',Type=48,Quality=2,MaxNum=99999,SellPrice=100,Desc='凝聚着某人记忆的碎片，能感觉到时光在其中静谧地流淌。如果能找到精通历史的学者询问，也许会知道它特殊的用途……',NoSale=1,NoStorage=5,}",
  [53892] = "{id=53892,NameZh='康尼的指导手册',Icon='item_900005',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29131,AdventureValue=105,AdventureReward={rewardid={870330}},Condition=64,Desc='指导员康尼是带领志愿生海拉米成为消防员的人，如今的他四十九岁了，原本还有一年时间，他就要退休了。然而教导过无数优秀消防员的他，怎么也不会想到，自己最后的归宿不是在消防局授勋，也不是葬身火场，而是……成为了火灾废墟游荡的魔物。',NoSale=1,NoStorage=5,}",
  [53893] = "{id=53893,NameZh='鲍恩的消防斧',Icon='item_41814',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29132,AdventureValue=105,AdventureReward={rewardid={870331}},Condition=64,Desc='中队长鲍恩是一个鲁莽的人，虽然大队长莱克教育过他很多次要小心行事，但他依旧保持着他那我行我素的风格。鲍恩的消防斧上沾染了许多魔物留下的血迹，或许在失去意识的最后一刻前，他依然以他鲁莽的风格，拼命保护着火场的生还者吧。',NoSale=1,NoStorage=5,}",
  [53894] = "{id=53894,NameZh='莱克的手套',Icon='item_44023',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29133,AdventureValue=105,AdventureReward={rewardid={870332}},Condition=64,Desc='大队长莱克是全消防局最出名的处女座，他对所有事情一丝不苟，哪怕是已经检查过一遍的装备，他都会再反复确认多次，然后带队执行行动。莱克的手套是他的消防员父亲留给他的，虽然旧了，但他每次任务后都会清洗打理，哪怕变成了魔物，他潜意识里最珍惜的，也是这副手套。',NoSale=1,NoStorage=5,}",
  [53895] = "{id=53895,NameZh='杰夫的氧气瓶',Icon='item_47154',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29134,AdventureValue=105,AdventureReward={rewardid={870333}},Condition=64,Desc='装备部长杰夫是消防队所有人坚实的后盾，他背着厚厚的装备包，里面都是可以简易替换的装备和应急设备。这个氧气瓶是杰夫刚成为消防员的时候获得的，他让许多退休的前辈在上面签了名，觉得这样就像是能与前辈并肩作战一样荣幸……但这上面最后一道签名，是机械猎犬的牙印。',NoSale=1,NoStorage=5,}",
  [53896] = "{id=53896,NameZh='拉瑞的救生皮带',Icon='item_44021',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29135,AdventureValue=105,AdventureReward={rewardid={870334}},Condition=64,Desc='后勤部长拉瑞原本不应该参加这次行动，他是个胆小的人，整个消防局都知道，他连老鼠都怕，根本没办法参加危险的外勤行动。但是这一次，听说队员们都被困在火场，尤其是他的老朋友杰夫也在其中…他终于鼓起了勇气，穿上装备强硬的冲进了火海，想要救出杰夫。这条救生皮带被发现的时候，是拷在杰夫的身上的，但这上面刻的，却是拉瑞光荣的姓名。',NoSale=1,NoStorage=5,}",
  [53897] = "{id=53897,NameZh='海拉米的毕业证',Icon='task_53635',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29136,AdventureValue=105,AdventureReward={rewardid={870335}},Condition=64,Desc='志愿生海拉米来到消防局已经一周了，他还没从消防学校毕业，就急匆匆地通过申请成为了志愿消防员。这次行动是他第一次的正式行动，他激动极了，早上出门前，甚至告诉爸爸妈妈，他就要当救火英雄了。这张毕业证他一直放在裤子后面的口袋里，真傻，他也不怕在火场烧坏了……然而毕业证并没有烧毁，但海拉米他却不在了。',NoSale=1,NoStorage=5,}",
  [53898] = "{id=53898,NameZh='总队长汉克的录音',Icon='item_52211',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29137,AdventureValue=126,AdventureReward={rewardid={870336}},Condition=64,Desc='火灾熄灭后，人们从火场发现了总队长汉克的录音笔，但是大部分的零件都被烧化了，只有里面保存的录音的内存装置还在，经过解析后，能从汉克的录音中听到……“魔鬼！黑色的魔鬼，这里的人都疯了！这些根本不是冒险者，他们都是恶魔，是傀儡，啊啊啊！”',NoSale=1,NoStorage=5,}",
  [53899] = "{id=53899,NameZh='飞行眼镜',Icon='item_45032',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29138,AdventureValue=105,AdventureReward={rewardid={870337}},Condition=64,Desc='在娜乌西卡族的习俗中，13岁的男孩就会视为成年，在他们的成年礼上，族长会亲手将族内工匠制作的飞行眼镜送给他们，这副眼镜将伴随他们终身，他们的每一次飞行都将透过镜片面对未知的危险——“戴上它就不会害怕了，飞的再快也不会害怕的。”，族长总这样鼓励第一次飞行的孩子，但他们究竟能否活着回来，其实谁也说不清楚。',NoSale=1,NoStorage=5,}",
  [53900] = "{id=53900,NameZh='喷气背包',Icon='item_47022',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29139,AdventureValue=105,AdventureReward={rewardid={870338}},Condition=64,Desc='为了对抗盘踞在山谷外部的飓风魔，娜乌西卡族尝试过很多种飞出山谷的方法。比如最初他们用兽皮制作滑翔伞，也试过生火制作热气球，但无一例外都失败了。直到有一天山谷的飓风吹来了一群迷路的哥布灵，在一番战斗过后，工匠们从喷气哥布灵的装备上得到启发，设计了能够在强风环境下借着风力飞行的喷气背包。',NoSale=1,NoStorage=5,}",
  [53901] = "{id=53901,NameZh='祈愿风车',Icon='item_45264',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29140,AdventureValue=105,AdventureReward={rewardid={870339}},Condition=64,Desc='为了冲出山谷，娜乌西卡族年复一年日复一日地派遣飞行队对抗飓风魔，成年的飞行队员在起飞前，会收下家人制作的祈愿风车，如果遭遇不测，就要在最后一刻将风车放飞出去，因为山谷里的风总是向内盘旋，所以风车最后一定会飞回山谷。收到风车的家人会接受惨痛的事实，然后为族人立起墓碑，将风车置于墓碑的名字前。',NoSale=1,NoStorage=5,}",
  [53902] = "{id=53902,NameZh='鼓风笛',Icon='item_48571',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29141,AdventureValue=105,AdventureReward={rewardid={870340}},Condition=64,Desc='娜乌西卡族没见过山谷外的世界，所以鼓风笛是他们认知中唯一存在的乐器。鼓风笛演奏出的声音多是哀怨而悠长的，娜乌西卡族的音乐家总是会感叹道，风原本应该是美丽而温柔的东西，但飓风魔的存在让风囚禁了娜乌西卡族的世界，让风声也变得令人害怕起来。',NoSale=1,NoStorage=5,}",
  [53903] = "{id=53903,NameZh='魔力测风仪',Icon='Task_MagicStaff',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29142,AdventureValue=105,AdventureReward={rewardid={870341}},Condition=64,Desc='整个娜乌西卡族的魔力凝聚在一起，才制成了这柄可以感应风的魔力测风仪，它即是娜乌西卡族对抗飓风魔最大的依赖，也是娜乌西卡族所有族人的寄托和信仰。如今这柄保存了数百年的测风仪，已经失去了原本的作用了，但只要触摸着它沉重的质感，依然能够感受到当年娜乌西卡族的热血和悲伤。',NoSale=1,NoStorage=5,}",
  [53904] = "{id=53904,NameZh='风中草',Icon='item_550529',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29143,AdventureValue=105,AdventureReward={rewardid={870342}},Condition=64,Desc='娜乌西卡族的山谷里能种植的植物很少，饲养的牛羊也远远不够支撑整个族群的消耗，于是，这种顺着风被吹进山谷的风中草，成为了娜乌西卡族最为基本的口粮。据说这种风中草生长在山谷外侧的石壁上，除了冬天以外都生长茂盛，虽然吃起来口感非常糟糕，但在艰苦的环境下，有这样能果腹的食物，也算是些许的慰藉了。',NoSale=1,NoStorage=5,}",
  [53905] = "{id=53905,NameZh='赠给外界的石板',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29144,AdventureValue=126,AdventureReward={rewardid={870343}},Condition=64,Desc='“你好，我们是娜乌西卡族的山谷居民，如果你收到了这块石板，那说明我们的飞行队终于突破了飓风魔的囚牢，飞到了山谷以外的世界。我们并不奢望收到石板的你能看得懂我们的文字，甚至前来山谷营救我们出去，我们只请求一件事，如果你们和我们一样是人类，请好好珍惜在山谷外自由的生活……如果来生有机会的话，真希望像你们一样，能享受风原本的样子啊。”——娜乌西卡族 族长·书写于A.W.830',NoSale=1,NoStorage=5,}",
  [53906] = "{id=53906,NameZh='财富之杖',Icon='item_53830',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29145,AdventureValue=105,AdventureReward={rewardid={870344}},Condition=64,Desc='在初代法老发现了千年魔法的同时，这柄权杖就与其它三柄一起被命运赐予了他。权杖顶端镶满宝石的皇冠象征着财富。在他离世之前，他将这柄权杖传给了他最疼爱的小女儿奈菲尔。他希望这柄象征着财富的权杖能保佑奈菲尔一生无忧无虑。',NoSale=1,NoStorage=5,}",
  [53907] = "{id=53907,NameZh='权力之杖',Icon='item_53831',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29146,AdventureValue=105,AdventureReward={rewardid={870345}},Condition=64,Desc='在初代法老发现了千年魔法的同时，这柄权杖就与其它三柄一起被命运赐予了他。权杖顶端雕刻精致的太阳象征着权力。在他离世之前，他将这柄权杖传给了王国的继承人，他的儿子艾哈迈德。他希望这柄象征着权力的权杖能时刻警醒着艾哈迈德权力背后的义务。',NoSale=1,NoStorage=5,}",
  [53908] = "{id=53908,NameZh='智慧之杖',Icon='item_53832',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29147,AdventureValue=105,AdventureReward={rewardid={870346}},Condition=64,Desc='在初代法老发现了千年魔法的同时，这柄权杖就与其它三柄一起被命运赐予了他。权杖顶端栩栩如生的眼睛象征着智慧。在他离世之前，他将这柄权杖传给了心爱的大女儿克莱奥。他希望这柄象征着智慧的权杖能给克莱奥带来无尽的智慧，让她实现自己的梦想。',NoSale=1,NoStorage=5,}",
  [53909] = "{id=53909,NameZh='永生之杖',Icon='item_53833',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29148,AdventureValue=105,AdventureReward={rewardid={870347}},Condition=64,Desc='在初代法老发现了千年魔法的同时，这柄权杖就与其它三柄一起被命运赐予了他。权杖顶端幽暗隐晦的蛇头象征着永生。在他离世之前，他留下遗嘱，要这柄权杖作为他的陪葬品，永不见天日。世人相传他心里尚存着对永生的期望，想要在死后获得真正的永生。无论如何，这种人类的贪念随他一起封入了棺具之中。',NoSale=1,NoStorage=5,}",
  [53910] = "{id=53910,NameZh='封印钥匙',Icon='item_52321',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29149,AdventureValue=105,AdventureReward={rewardid={870348}},Condition=64,Desc='法老艾哈迈德在继任后没多久便下令建造金字塔，将千年魔法封印，并与初代法老的棺具一起沉睡在金字塔的内部。为了在未来的某个重要时刻解封千年魔方，艾哈迈德留下了一把钥匙，拥有强大力量的人用这把钥匙可以解放这古老的封印。据说这把钥匙，被某种怪物看守着，在时光的流逝中，被人渐渐遗忘……',NoSale=1,NoStorage=5,}",
  [53911] = "{id=53911,NameZh='千年魔方',Icon='item_53835',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29150,AdventureValue=126,AdventureReward={rewardid={870349}},Condition=64,Desc='伴随着流星砸落在古老的梦罗克土地上的神器，传说中众神赐予法老的神器，只要拥有四把作为“钥匙”的权杖，就能通过它知晓一切。初代法老在它的帮助下，在梦罗克的土地上创建了国家。在他死后，下一任法老艾哈迈德却建造了金字塔，将这个神器与初代法老的棺具一起封印在了里面。这个神器也渐渐成为了人们口中不存在的传说……',NoSale=1,NoStorage=5,}",
  [53912] = "{id=53912,NameZh='尖啸血瓶',Icon='item_12001',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29151,AdventureValue=105,AdventureReward={rewardid={870350}},Condition=64,Desc='打开就会发出尖叫的血瓶，原本属于月精灵瓦莱丽。打开血瓶会增进任何魔物的力量，是难得一见的宝物。',NoSale=1,NoStorage=5,}",
  [53913] = "{id=53913,NameZh='月光花环',Icon='item_48610',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29152,AdventureValue=105,AdventureReward={rewardid={870351}},Condition=64,Desc='月精灵瓦莱丽的花环，在光的照射下会闪淡淡的幽光，且让周围的花草跟着一起绽放。',NoSale=1,NoStorage=5,}",
  [53914] = "{id=53914,NameZh='月牙金币',Icon='item_48590',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29153,AdventureValue=105,AdventureReward={rewardid={870352}},Condition=64,Desc='月牙形状的一枚小金币，虽然不起眼，可这枚金币能吸收月光的精华，原本属于月精灵瓦莱丽。',NoSale=1,NoStorage=5,}",
  [53915] = "{id=53915,NameZh='蓝火蜡烛',Icon='item_45839',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29154,AdventureValue=105,AdventureReward={rewardid={870353}},Condition=64,Desc='闪着蓝色的幽光，原本属于月精灵瓦莱丽。盈盈之光虽然微弱但仍然很坚强的燃烧着，会招来守护烛火的月光梦魇。',NoSale=1,NoStorage=5,}",
  [53916] = "{id=53916,NameZh='月精灵之吻',Icon='item_45257',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29155,AdventureValue=126,AdventureReward={rewardid={870354}},Condition=64,Desc='百年前，吉芬城内发生了一起骇人听闻的屠杀事件，是狼人少年斯蒂芬斯无法控制力量酿成的灾祸。月精灵瓦莱丽为了保护斯蒂芬斯，自愿顶下所有罪名。她被魔术师们囚禁在红月中，封印于吉芬塔之下。斯蒂芬斯不愿瓦莱丽独自背受这般痛苦，在塔下守护百年，已然到了垂暮之时。最终，封印被解开了。瓦莱丽重获自由，给了斯蒂芬斯最后的吻。而斯蒂芬斯沐浴在她的月光下，微笑着离开了世界。',NoSale=1,NoStorage=5,}",
  [53917] = "{id=53917,NameZh='魔菇肉排',Icon='item_551000',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29156,AdventureValue=105,AdventureReward={rewardid={870355}},Condition=64,Desc='用魔菇的肉做成的肉排，散发出诱人的香气，但是吃了会中毒吧？据说是下水道公主斯丽帕的宠物——妮妮喜欢的东西。',NoSale=1,NoStorage=5,}",
  [53918] = "{id=53918,NameZh='黏黏的网',Icon='item_53845',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29157,AdventureValue=105,AdventureReward={rewardid={870356}},Condition=64,Desc='黏糊糊的网，会粘住所有接近的东西，据说是下水道公主斯丽帕的宠物——妮妮喜欢的东西。',NoSale=1,NoStorage=5,}",
  [53919] = "{id=53919,NameZh='翻译装置',Icon='item_5753',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29158,AdventureValue=105,AdventureReward={rewardid={870357}},Condition=64,Desc='雷根贝勒公司根据神工匠哈沃德的设计优化过的翻译装置，使用后，能翻译出部分魔物的叫声。',NoSale=1,NoStorage=5,}",
  [53920] = "{id=53920,NameZh='热水晶',Icon='item_53728',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29159,AdventureValue=105,AdventureReward={rewardid={870358}},Condition=64,Desc='雷根贝勒公司研发的能产生能源的水晶，似乎可以当作能源来启动隧道前的灯。',NoSale=1,NoStorage=5,}",
  [53921] = "{id=53921,NameZh='奥拉克妮档案',Icon='item_53847',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29160,AdventureValue=126,AdventureReward={rewardid={870359}},Condition=64,Desc='已捕获目标，斯丽帕的宠物蜘蛛，开始人造伊米尔之心提取物实验阶段一，代号奥拉克妮。经历了一周的变异，被称为奥拉克妮的实验体体型明显变大，其他指标正常。两周后，目标仍在变大，我们已经更换了好几次容器。三周后，目标的变异似乎失控了！它变得，太过巨大，我们试着将它安置于隧道。一个月后...计划失败！我们创造了一只怪物，救命...',NoSale=1,NoStorage=5,}",
  [53922] = "{id=53922,NameZh='鹰之图腾',Icon='item_53864',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29161,AdventureValue=105,AdventureReward={rewardid={870360}},Condition=64,Desc='鹰，是兽人战士们最好的伙伴，它们可以跟随着战士们出生入死地战斗，也可以和战士们一起为村落狩猎回粮食。兽人的勇士们从尼夫海姆拼死带回了不会腐朽的木头，将它们雕刻成图腾，供奉在村落的图腾祭坛上。他们向这个鹰之图腾祈祷着，如鹰一般的勇气，可以永远伴随着兽人一族。',NoSale=1,NoStorage=5,}",
  [53923] = "{id=53923,NameZh='鹿之图腾',Icon='item_53865',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29162,AdventureValue=105,AdventureReward={rewardid={870361}},Condition=64,Desc='鹿，是兽人村落神圣的象征，据说兽人村落曾经一场瘟疫就是被鹿治愈的。兽人的勇士们从尼夫海姆拼死带回了不会腐朽的木头，将它们雕刻成图腾，供奉在村落的图腾祭坛上。他们向这个鹿之图腾祈祷着，希望兽人一族们，远离灾祸，健康长寿。',NoSale=1,NoStorage=5,}",
  [53924] = "{id=53924,NameZh='枭之图腾',Icon='item_53866',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29163,AdventureValue=105,AdventureReward={rewardid={870362}},Condition=64,Desc='枭，是兽人村落里口口相传的智慧之鸟，可以预示未来发生的事情。兽人的勇士们从尼夫海姆拼死带回了不会腐朽的木头，将它们雕刻成图腾，供奉在村落的图腾祭坛上。他们向这个枭之图腾祈祷着，能将智慧世世代代传递下去，这样兽人一族才能在这个动乱的大陆上生存繁衍下去。',NoSale=1,NoStorage=5,}",
  [53925] = "{id=53925,NameZh='牛之图腾',Icon='item_53867',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29164,AdventureValue=105,AdventureReward={rewardid={870363}},Condition=64,Desc='牛，是兽人村落里最常见的动物，它们帮助着兽人一族耕作，甚至还是重要的交通工具。兽人的勇士们从尼夫海姆拼死带回了不会腐朽的木头，将它们雕刻成图腾，供奉在村落的图腾祭坛上。他们向这个牛之图腾祈祷着，可以种出更多的粮食。',NoSale=1,NoStorage=5,}",
  [53926] = "{id=53926,NameZh='信仰火种',Icon='item_52512',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29165,AdventureValue=126,AdventureReward={rewardid={870364}},Condition=64,Desc='传说中，神族赐予兽人一族的火种，只要兽人们的信仰不熄，这个火种就无法被熄灭。兽人们将它放在村落里的图腾祭坛上，照耀着四根重要的图腾柱子。愿兽人一族能长久地存在下去，如同这个火种一般不会熄灭。这是所有兽人们心中永不会熄灭的美好的愿景。',NoSale=1,NoStorage=5,}",
  [53927] = "{id=53927,NameZh='眷恋花',Icon='item_53930',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29161,AdventureValue=105,AdventureReward={rewardid={870365}},Condition=64,Desc='眷恋花寄宿着青春女神伊多娜的无限眷恋，遥远的过去，她与诗人之神布拉吉在妙勒尼度过了一段非常美妙难忘的时光，直到诸神黄昏降临……',NoSale=1,NoStorage=5,}",
  [53928] = "{id=53928,NameZh='誓言花',Icon='item_53928',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29162,AdventureValue=105,AdventureReward={rewardid={870366}},Condition=64,Desc='誓言花寄宿着青春女神伊多娜与布拉吉许下的坚定誓言，伊多娜发誓会在妙勒尼等待布拉吉回来，而参与诸神黄昏之战的布拉吉却再也没有回来，苦苦等待的伊多娜化作花叶，将布拉吉留在妙勒尼的黄金竖琴变为了花语竖琴。',NoSale=1,NoStorage=5,}",
  [53929] = "{id=53929,NameZh='孤寂花',Icon='item_53929',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29163,AdventureValue=105,AdventureReward={rewardid={870367}},Condition=64,Desc='孤寂花寄宿着青春女神伊多娜的千年来的叹息与孤寂，独自等待布拉吉的岁月变得窒息而冗长，她心中的一部分情感因长久的孤独而变得消沉。',NoSale=1,NoStorage=5,}",
  [53930] = "{id=53930,NameZh='思念花',Icon='item_53927',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29164,AdventureValue=105,AdventureReward={rewardid={870368}},Condition=64,Desc='思念花寄宿着青春女神伊多娜对布拉吉的日夜思念，“如果他还爱我，就算是经历轮回，他也一定会回到我的身边，我深深相信着我们的爱。”伊多娜抚摸着花语竖琴的琴弦，却不愿拨动它一下，竖琴的每一个音符，都会让她的思念与泪水汹涌决堤。',NoSale=1,NoStorage=5,}",
  [53931] = "{id=53931,NameZh='布拉吉的乐谱',Icon='item_53840',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29165,AdventureValue=126,AdventureReward={rewardid={870369}},Condition=64,Desc='“我也曾年少轻狂不听人言，直到与你相见。你是春风，也是雨露，是命运三女神赐予我的礼物。我的爱人啊，我就要前往战场，不要为我哭泣，不要因离别悲伤。直到艾尔帕兰的时钟停摆，梦罗克的黄沙扬尽，我依然深爱着你。就算迟到千年，我也一定会回到你身边 ……”',NoSale=1,NoStorage=5,}",
  [53932] = "{id=53932,NameZh='紫藤花',Icon='item_53856',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29166,AdventureValue=105,AdventureReward={rewardid={870370}},Condition=64,Desc='佩姬去山中偶然获得的紫藤花，温柔的紫色间点缀着着美丽的光芒。它蕴含着大地的祝福，是梦想与希望的祈愿之花。传说中世间只有一朵，由斐扬树林的守护精灵保管。',NoSale=1,NoStorage=5,}",
  [53933] = "{id=53933,NameZh='彩虹洒水壶',Icon='item_53854',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29167,AdventureValue=105,AdventureReward={rewardid={870371}},Condition=64,Desc='佩姬和哥哥平时浇花用的水壶，许多年前被人施过魔法。使用它的时候，上方会出现美妙的彩虹，同时被它浇过的花永远也不会枯萎。哥哥离去后，洒水壶的魔力好像就失效了。',NoSale=1,NoStorage=5,}",
  [53934] = "{id=53934,NameZh='白熊布娃娃',Icon='item_53855',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29168,AdventureValue=105,AdventureReward={rewardid={870372}},Condition=64,Desc='佩姬送给哥哥的礼物，一只憨态可掬的白色小熊。布料和针线是从村长约翰那里借来的，佩姬用了一周才把它缝制成型。哥哥收到以后非常高兴，将它放在床头悉心收藏了起来。',NoSale=1,NoStorage=5,}",
  [53935] = "{id=53935,NameZh='闪光竹叶',Icon='item_53853',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29169,AdventureValue=105,AdventureReward={rewardid={870373}},Condition=64,Desc='一片闪闪发光的竹叶，脉络之间能清晰看见魔力的流淌。这是佩姬放弃了自己的身躯，牺牲了灵魂和所有魔法制作而成的。将它种在地上，不久之后就会长出葱郁的竹林。',NoSale=1,NoStorage=5,}",
  [53936] = "{id=53936,NameZh='白糖甜糕',Icon='item_53857',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29170,AdventureValue=126,AdventureReward={rewardid={870374}},Condition=64,Desc='雪白清甜的糯米糕，是佩姬最喜欢的食物。小时候，每当她伤心流泪，温柔的哥哥总会准备好白糖糕给她。有了糖糕和哥哥，小佩姬就会忘记烦恼。“佩姬不要怕，我永远会陪在你身边。”哥哥对于她来说，就是无所不能的。',NoSale=1,NoStorage=5,}",
  [53937] = "{id=53937,NameZh='束缚之弓',Icon='item_53858',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29171,AdventureValue=105,AdventureReward={rewardid={870375}},Condition=64,Desc='达尔村是远近闻名的狩猎村庄，弓箭是当地村民的信仰。这把弓箭上朴素的花纹一看就是出自达尔村之手，弓箭的主人不知道哪里去了，箭上似乎刻印着主人的名字，不过应该是放置时间过长的原因，文字早已被锈迹侵蚀掉看不清楚了…',NoSale=1,NoStorage=5,}",
  [53938] = "{id=53938,NameZh='漆黑之羽',Icon='item_53859',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29172,AdventureValue=105,AdventureReward={rewardid={870376}},Condition=64,Desc='羽毛是如同深渊一般浓烈的黑色，不难看出这是来自乌鸦身上的。乌鸦被称作诅咒之鸟，食腐，叫声粗厉，所有人见到乌鸦都避之不及，但是有个人却不一样，他的名字叫佩洛，天生就喜欢和这些乌鸦打交道，他用乌鸦去报复那些他憎恨的人，然而他不知道的是诅咒的种子早已扎根在他的身上…',NoSale=1,NoStorage=5,}",
  [53939] = "{id=53939,NameZh='复仇者的面具',Icon='item_53860',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29173,AdventureValue=105,AdventureReward={rewardid={870377}},Condition=64,Desc='被鲜血浸染过的面具，面具上的表情如同来恶鬼的咆哮，面具下隐藏着事情的真相，被反噬的驯鸦人，枉死的守林人，一切的一切只有面具下的人知晓。',NoSale=1,NoStorage=5,}",
  [53940] = "{id=53940,NameZh='失落的草帽',Icon='item_53861',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29174,AdventureValue=105,AdventureReward={rewardid={870378}},Condition=64,Desc='一根根的稻草编织而成的不仅仅是草帽，还有守林人与知更鸟的回忆，猎人手下的及时相救，为了回报化作稻草人为他守护麦田，因果交错编织而成了这一顶记忆的草帽。',NoSale=1,NoStorage=5,}",
  [53941] = "{id=53941,NameZh='微笑的面具',Icon='item_53862',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29175,AdventureValue=126,AdventureReward={rewardid={870379}},Condition=64,Desc='在爱与感动之下，复仇的面具终将破碎，“它”被战胜，知更鸟永远会记得，爷爷，麦田，与那些幸福的时光，带着爷爷的愿望，它会带着微笑永远守护这片森林。',NoSale=1,NoStorage=5,}",
  [53942] = "{id=53942,NameZh='甜点精灵',Icon='item_3000025',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29176,AdventureValue=105,AdventureReward={rewardid={870380}},Condition=64,Desc='诞生于罗扎纳的甜点精灵，以甜食为生。对充满着甜品与喜爱甜品的猫咪们的远星大陆，它打心底里热爱着。虽然自己也能用魔力制造出不少美味的甜点，但是似乎还是更喜欢远星大陆上自然产生的甜品。',}",
  [53943] = "{id=53943,NameZh='花酿宝宝',Icon='item_48071',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29177,AdventureValue=105,AdventureReward={rewardid={870381}},Condition=64,Desc='嗡嗡嗡——嗡嗡嗡——花酿宝宝每天都勤劳地采着最清甜的花蜜，再用最清澈的湖水酿制世间独一无二的花酿酒。它用来酿酒的那池湖水旁，总是躺着许多因贪食美味花酿而晕倒在一旁的猫咪与奇怪的魔物。',}",
  [53944] = "{id=53944,NameZh='厨师之魂',Icon='item_48048',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29178,AdventureValue=105,AdventureReward={rewardid={870382}},Condition=64,Desc='寄生于厨房的魂魄，目前扎根在罗扎纳的烤箱酒吧，那里的约翰厨师是它喜爱的对象，它总是帮助他制作出更美味的菜式。更重要的是，他最喜欢的是在酒吧里看着来来往往的喵咪们在品尝到美味后，那可爱的要命的表情。',}",
  [53945] = "{id=53945,NameZh='金灿灿的钟',Icon='item_53945',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29179,AdventureValue=126,AdventureReward={rewardid={870383}},Condition=64,Desc='这是一口充满魔力的钟，是宴会之钟最重要的灵魂部件。传说中，是多兰族的先祖们在航海过程中获得的奇特材料制造而成。它清脆而又悠远的钟声，可以传遍罗扎纳的角角落落。然而一场百年一遇的台风将宴会之钟破坏，这口魔力之钟也失去了踪影。时间一天天的过去了，人们逐渐忘却了这个曾经带来无限快乐的魔力之钟，但仍然有些人，在梦里，仍然期待着再次听到钟声敲响的那一天……',}",
  [53946] = "{id=53946,NameZh='小雪人',Icon='item_31109',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29180,AdventureValue=105,AdventureReward={rewardid={870384}},Condition=64,Desc='阿卢纳贝兹教国下起了罕见的大雪，从来没有见过雪的阿露什与阿娜雅姐妹两一起在圣域的角落，参照着书本上雪人的模样堆起了雪人。她们为它戴上阿露什最喜欢的帽子，围上阿娜雅最心爱的围巾，做出了属于她们二人的小雪人。想要一直一直在一起，就像现在这样……',}",
  [53947] = "{id=53947,NameZh='双生花',Icon='item_31106',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29181,AdventureValue=105,AdventureReward={rewardid={870385}},Condition=64,Desc='神官西丽丝在阿露什与阿娜雅两姐妹出生后就一直培育着罕见的双生花。双生花会结出两花朵，它们同根同生，交缠在一起。她将培育成功的双生花带到了祈祷之泉，祈求着女神能眷顾两位殿下，让她们能健康成长，带领阿卢纳贝兹的子民们走向未来……',}",
  [53948] = "{id=53948,NameZh='星之冰雕',Icon='item_700158',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29182,AdventureValue=105,AdventureReward={rewardid={870386}},Condition=64,Desc='星星可真好看，要是能摘下星星就好了。阿娜雅无意的一句话让阿露什记在了心中。在看到一位信徒用冰块雕刻成的女神像后，她请求这位信徒教给她冰雕的技艺。在日复一日的练习后，阿露什终于完美雕刻出了一个星之冰雕。她冻得发红的手捧着这颗星星，希望妹妹能够永远快乐……',}",
  [53949] = "{id=53949,NameZh='女神戒指',Icon='item_6058',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29183,AdventureValue=105,AdventureReward={rewardid={870387}},Condition=64,Desc='圣域中有个传说，女神降临圣域这片土地之后，将一枚戒指交给了当时的教皇。这枚戒指蕴含着女神的力量，可以让拥有者拥有强大的魔力。这枚戒指从历任的教皇手上代代流传，却最终在一场寒灾之中，消失了踪影。逐渐地，这枚戒指被世人所遗忘……',}",
  [53950] = "{id=53950,NameZh='冰雪之心',Icon='item_3000264',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29184,AdventureValue=126,AdventureReward={rewardid={870388}},Condition=64,Desc='阿露什看着那张和自己一模一样的脸庞，用如同天空般清澈的眼睛注视着阿娜雅那如晚霞般的红瞳。她从女神戒指中汲取了女神之力，将自己从书籍中学会的冰雪魔法施展了出来。皮肤上传来了如同针扎般疼痛，四肢渐渐失去了知觉，阿露什感觉到自己的血液似乎已经停止了流动，唯一只有她的一颗心脏，她还能感觉到跳动……阿娜雅，活下去，为了阿卢纳贝兹……我会永远在这里……永远……陪伴着你……',}",
  [53951] = "{id=53951,NameZh='雨之灵',Icon='Rain_Doll',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29185,AdventureValue=105,AdventureReward={rewardid={870389}},Condition=64,Desc='森林女巫嘉莉提取雨的元素，使用青叶草固定形态后，制作而成的守护灵。雨之灵的力量会使周围降雨，因融合了柔软的青叶草，雨丝细致轻柔，就像被森林之风温柔的抚摸着。森林里的群叶猫族围绕这场雨狂欢，祈祷森林异变的天气能早日恢复。',}",
  [53952] = "{id=53952,NameZh='雪之灵',Icon='Snow_Doll',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29186,AdventureValue=105,AdventureReward={rewardid={870390}},Condition=64,Desc='森林女巫嘉莉提取雪的元素，使用紫蕊花固定形态后，制作而成的守护灵。雪之灵的力量会使周围降雪，因融合了清新的紫蕊花，雪中有轻微的香味。难得一见的降雪吸引了罗扎纳猫猫们的注意，学者赛恩斯带着学生们用相机记录下了这罕见的景色。',}",
  [53953] = "{id=53953,NameZh='风之灵',Icon='Cloudy_Doll',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29187,AdventureValue=105,AdventureReward={rewardid={870391}},Condition=64,Desc='森林女巫嘉莉提取风的元素，使用兰翎枝固定形态后，制作而成的守护灵。风之灵的力量会使周围吹拂轻风，因融合了特制的兰翎枝，风的力量并不会太大。狂野蜂兵们因突起的风而兴奋，在风之灵附近进行了招式比赛。',}",
  [53954] = "{id=53954,NameZh='雾之灵',Icon='Fog_doll',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29188,AdventureValue=105,AdventureReward={rewardid={870392}},Condition=64,Desc='森林女巫嘉莉提取雾的元素，使用黄金喵喵草固定形态后，制作而成的守护灵。雾之灵的力量会使周围云雾缭绕，因融合了亮闪闪的黄金喵喵草，雾中会有微微光芒照亮周围。第29届勇敢者挑战在雾之灵附近举行，将雾中探险作为最终考核。',}",
  [53955] = "{id=53955,NameZh='暖洋洋的晴天',Icon='Sunny_Doll',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29189,AdventureValue=126,AdventureReward={rewardid={870393}},Condition=64,Desc='森林女巫嘉莉提取了巨蛋中不稳定的火焰能量，在幼龙穆穆的帮助下，借助四个守护灵的力量，将再次爆发的火焰能量彻底引导了出来。带着这个用穆穆褪下的龙麟固定形态，制作而成的守护灵，就能确信明天一定是一个暖洋洋的晴天！',}",
  [53956] = "{id=53956,NameZh='被遗弃的护身符',Icon='item_53956',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29190,AdventureValue=105,AdventureReward={rewardid={870394}},Condition=64,Desc='浪漫的克魔岛上，从不缺乏有情人。伊奥与戈罗，便是其中的一对。他们从小一起玩耍，长大后结成夫妻。伊奥擅长纺织和酿造，戈罗则是一个出色的水手。所有人都觉得，他们会恩爱而富足地生活下去，到儿孙满堂、到两人终老……然而，命运是如此飘忽不定。一次例行的出海，戈罗居然再没有回来。唯有他佩戴的护身符，被浪花冲上了海滩。“我明明亲手为他佩戴上护身符，为什么他还是遇到了风暴！我不相信，戈罗他一定没死，他一定在哪儿等着我！”悲痛的伊奥不肯接受这个现实，她终日徘徊在海岸边，等待她的丈夫归来……不过最后，这个女人，应当从可怜的幻想里清醒过来了。否则，这块象征着祝福与爱情的护身符，也不会被遗弃在海潮里。',}",
  [53957] = "{id=53957,NameZh='伊奥的绝笔信',Icon='item_53957',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29192,AdventureValue=126,AdventureReward={rewardid={870395}},Condition=64,Desc='爱女涅拉亲启：如果你看到这封信，希望你不要恨我。有些秘密，我想在死前告诉你：是我固执地想复活你的父亲，才害你背负诅咒而生……（此处笔记突然凌乱起来）都怪那个老女人！是她给了我恶魔之书！！！！我才、我才按着书上，找到了那个地方，遇到了恶——不、是我们伟大的主人！哈哈哈，主人、主人，是谁打破了你的肉身，让你只有一丝神念，附着在残躯上。我愿意献上我的一切，换取您回归，只要您，复活我的爱人……（此处有大片划痕）可您为什么要骗我！！！为什么祭品是我的女儿，她还没有出生、她才那么小……呜呜呜，你是戈罗的孩子，我爱你啊涅拉，我是爱你的呀！不，不对，我又被骗了……你不是我的女儿，你是恶魔的孩子，你是“不祥之子”！骗子、无赖、孽种！啊啊啊——神明大人啊，你都已经拿去了她的肉体，为什么没有践行诺言……我、我要的是活着的戈罗啊……（此处有泪水氤氲的痕迹）才不是、一具被冲上海滩的白骨啊……',}",
  [53958] = "{id=53958,NameZh='无名手册',Icon='item_53958',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29191,AdventureValue=105,AdventureReward={rewardid={870396}},Condition=64,Desc='如同阳光照射的地方必有阴影，宁静美丽的克魔岛，也有着自己的恐怖故事。相传，在幽暗的火山溶洞深处，活跃着一群异端信徒。他们崇拜伺长灾厄与毁灭的“真神”，用各种邪恶又血腥的方式，尝试唤醒沉睡的主人。岛上许多的人口失踪案、谋杀案，都与他们有关。在过去的数百年里，历任克魔岛村长，曾不止一次地清理这些异端。但一段时间后，他们总会卷土重来——再度崇拜强大而邪恶的神灵，渴求她以超越现实的力量，实现某些不切实际的愿望……“呵呵呵~~小姑娘，你还想再见到你的情郎吗？人类的力量，可无法与死亡女神争锋啊。”漆黑的斗篷里，伸出一双枯瘦的手；低垂的帽檐下，陌生的老妪目光狂热，说着蛊惑人心的话。“来，收下这本手册，成为吾等的姊妹，崇拜伟大的灾厄之神吧~她将给予你实现愿望的力量！”',}",
  [53959] = "{id=53959,NameZh='王宫闹鬼事件',Icon='zhengju_icon_01',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='来自侍女们的证词，自从老国王失踪后，王宫总是出现闹鬼事件，似乎在暗示老国王已经遭遇不测。',Feature=1,}",
  [53960] = "{id=53960,NameZh='国王的画像',Icon='zhengju_icon_02',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='一副挂在正厅的画像，上面的人头戴王冠手拿权杖，应该是某一任的国王。',Feature=1,}",
  [53961] = "{id=53961,NameZh='验尸报告',Icon='zhengju_icon_03',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='死者姓名：奈特·乔治 \n死亡时间：上午10:40 \n尸体情况：黑紫色血液从口腔流出，右手首先沾有紫色毒药。\n死亡原因：右手手心接触到致死的剧毒，毒性通过皮肤渗入，导致中毒而亡。\n报告人：卡尔·罗伯特',Feature=1,}",
  [53962] = "{id=53962,NameZh='毒药',Icon='zhengju_icon_04',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='从爱丽丝身上掉落的毒药，和王子身上检测出的毒药一致。这种毒药十分烈性，液体呈紫色，可以通过接触后的皮肤渗入，发作时间极快。',Feature=1,}",
  [53963] = "{id=53963,NameZh='国王的权杖',Icon='zhengju_icon_05',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='代表王权的权杖，陪伴着历代国王执掌着卢恩王国的政权。在继位仪式上，由主教亲自赐予继位者，而继位者接过并高举权杖则意味着他成为了新一任的国王。',Feature=1,}",
  [53964] = "{id=53964,NameZh='密室的钥匙',Icon='zhengju_icon_06',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='存放权杖的密室钥匙，一直由王后保管着，在案发前一晚交给了爱丽丝让她能够进入密室拿取权杖。在案发当天的早上由爱丽丝还给了王后。',Feature=1,}",
  [53965] = "{id=53965,NameZh='继位仪式的照片II',Icon='zhengju_icon_07',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='由国家地理杂志的特约记者弗兰克拍摄的继位仪式现场的照片，记录了王子生前的影像。',Feature=1,}",
  [53966] = "{id=53966,NameZh='继位仪式的照片III',Icon='zhengju_icon_08',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='由国家地理杂志的特约记者弗兰克拍摄的继位仪式现场的照片，记录了王子生前的影像。',Feature=1,}",
  [53967] = "{id=53967,NameZh='继位仪式的照片IV',Icon='zhengju_icon_09',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='由国家地理杂志的特约记者弗兰克拍摄的继位仪式现场的照片，记录了王子生前的影像。',Feature=1,}",
  [53968] = "{id=53968,NameZh='继位仪式的照片V',Icon='zhengju_icon_10',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='由国家地理杂志的特约记者弗兰克拍摄的继位仪式现场的照片，记录了王子生前的影像。',Feature=1,}",
  [53969] = "{id=53969,NameZh='密室的脚印',Icon='zhengju_icon_11',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='案发后在密室中发现的尖头脚印，脚印很大，不可能是爱丽丝留下的。',Feature=1,}",
  [53970] = "{id=53970,NameZh='密室的脚印',Icon='zhengju_icon_11',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='案发后在密室中发现的尖头脚印，脚印很大，可能是某一个侍卫留下的。',Feature=1,}",
  [53971] = "{id=53971,NameZh='密室的脚印',Icon='zhengju_icon_11',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='案发后在密室中发现的尖头脚印，脚印很大，经比对，脚印是由侍卫长马丁留下的。',Feature=1,}",
  [53972] = "{id=53972,NameZh='侍卫的证词',Icon='zhengju_icon_01',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='密室每天晚餐后都会有侍女进行打扫，这位侍女每天都会把密室打扫的干干净净。但在中毒事件后，王后命令守卫日夜守在密室门口，没有人有机会踏入密室一步，连打扫的侍女都没进来过。',Feature=1,}",
  [53973] = "{id=53973,NameZh='值班表',Icon='zhengju_icon_13',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='这是记录侍卫们排班计划的表格，被贴在入口的墙面上。',Feature=1,}",
  [53974] = "{id=53974,NameZh='王宫出入记录',Icon='zhengju_icon_14',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='这是一份登记人员出入王宫日期和时间的表格。',}",
  [53975] = "{id=53975,NameZh='马丁的钢靴',Icon='zhengju_icon_16',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='这是一双侍卫长马丁执勤时会穿的钢靴，是王宫后勤部为侍卫们统一定制的款式。',}",
  [53976] = "{id=53976,NameZh='马丁的钢靴',Icon='zhengju_icon_16',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='这是一双侍卫长马丁执勤时会穿的钢靴，是王宫后勤部为侍卫们统一定制的款式。经比对，密室里的脚印与马丁的钢靴吻合，脚印是由马丁留下的。',}",
  [53977] = "{id=53977,NameZh='麦克的钢靴',Icon='zhengju_icon_15',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='这是一双侍卫麦克执勤时会穿的钢靴，是王宫后勤部为侍卫们统一定制的款式。',}",
  [53978] = "{id=53978,NameZh='罗恩的钢靴',Icon='zhengju_icon_15',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='这是一双侍卫罗恩执勤时会穿的钢靴，是王宫后勤部为侍卫们统一定制的款式。',}",
  [53979] = "{id=53979,NameZh='王后的收纳盒',Icon='zhengju_icon_18',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='在王后寝宫中找到的收纳盒，继位仪式的照片似乎收纳在其中。',}",
  [53980] = "{id=53980,NameZh='老旧的照片',Icon='zhengju_icon_19',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='遗落在王宫花园里的照片，照片已经泛黄，上面是两个男性的合照，其中一位身穿着国王礼服的长者，另一个男性的脸被钢笔划花，无法辨认。',}",
  [53981] = "{id=53981,NameZh='镜面地板',Icon='zhengju_icon_20',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='王座之间门口的走廊地面是由大理石制成的，表面光滑且能像镜子一般照出上方的物体。爱丽丝站在地面上时，能从地面上看到她的身影。',}",
  [53982] = "{id=53982,NameZh='教会的银盒',Icon='zhengju_icon_21',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='用于继位仪式上放置国王权杖的盒子，隶属于教会。',}",
  [53983] = "{id=53983,NameZh='案发后的王座之间',Icon='zhengju_icon_22',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='爱葛妮斯在案发后拍摄下王座之间的照片。',}",
  [53984] = "{id=53984,NameZh='17年前的老旧报纸',Icon='zhengju_icon_23',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='一份17年前的报纸，刊登着当年的新闻。',}",
  [53985] = "{id=53985,NameZh='沾毒的手套',Icon='zhengju_icon_24',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='珀的手套，上面沾染着毒杀王子的毒药。在王子毒发后，他将手套戴在了王座之间的雕像手上，躲避了侍卫的搜身。',}",
