  [54000] = "{id=54000,NameZh='继位仪式的安排',Icon='zhengju_icon_14',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='由王室管家拟定的继位仪式的安排，盖有王后确认的印象。\n王位继承人入场→王位继承人与王室成员握手合影→王位继承人宣誓并接受主教的祝福→王位继承人拿取权杖并坐上王座→仪式结束',Feature=1,}",
