  [54051] = "{id=54051,NameZh='水晶灯饰I',Icon='item_53988',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29193,AdventureValue=105,AdventureReward={rewardid={870397}},Condition=64,Desc='玫瑰剧院的巨大水晶灯上拆下来的部件，用于连接天花板与水晶灯。',Feature=1,}",
