  [54053] = "{id=54053,NameZh='水晶灯饰III',Icon='item_3004980',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29195,AdventureValue=105,AdventureReward={rewardid={870399}},Condition=64,Desc='玫瑰剧院的巨大水晶灯上拆下来的部件，是灯罩的一部分。',}",
  [54054] = "{id=54054,NameZh='水晶灯饰IV',Icon='item_12532',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29196,AdventureValue=105,AdventureReward={rewardid={870400}},Condition=64,Desc='玫瑰剧院的巨大水晶灯上拆下来的部件，上面雕刻着精美的纹理。',}",
  [54055] = "{id=54055,NameZh='水晶灯饰V',Icon='item_49123',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29197,AdventureValue=105,AdventureReward={rewardid={870401}},Condition=64,Desc='玫瑰剧院的巨大水晶灯上拆下来的部件，是用水晶串联而成的。',}",
  [54056] = "{id=54056,NameZh='水晶吊灯',Icon='item_53987',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29198,AdventureValue=126,AdventureReward={rewardid={870402}},Condition=64,Desc='玫瑰剧院中的巨大水晶吊灯，在普隆德拉王宫初见时就被制造而成，距今已有几百年的历史了。',}",
  [54057] = "{id=54057,NameZh='匿名仆从的口供',Icon='zhengju_icon_01',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='一位不愿透露姓名的仆从作证：三天前的晚上，王后与王子发生激烈争执，甚至传出打动的动静。同时，王后房间内有着第三个人的声音。',}",
  [54058] = "{id=54058,NameZh='石柱上的血迹',Icon='zhengju_icon_104',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='永恒之宫阳台的石柱上，残留着一串血迹。有人曾磕碰在石柱上，且伤势不轻。',}",
  [54059] = "{id=54059,NameZh='王后的诊疗记录',Icon='zhengju_icon_89',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='不久前，宫廷医师进入过永恒之宫。这是他留下的诊疗记录。',}",
  [54060] = "{id=54060,NameZh='王子的诊疗记录',Icon='zhengju_icon_90',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='不久前，宫廷医师进入过永恒之宫。这是他留下的诊疗记录。',}",
  [54061] = "{id=54061,NameZh='男性衣物',Icon='zhengju_icon_95',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='被随手悬挂在椅背上的衣物，看尺寸与成色，应该属于身份高贵的成年男性。',}",
  [54062] = "{id=54062,NameZh='食物残渣的照片',Icon='zhengju_icon_109',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='永恒之宫的密室里，留存着一份刚刚变质的食物。这说明有人使用过这间密室，直到近期才离开。',}",
  [54063] = "{id=54063,NameZh='可疑的信纸',Icon='zhengju_icon_96',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='被钉在一起的信纸，乍一看似乎没有字迹，但表面隐隐反射着微光……还是先收纳起来吧！',}",
  [54064] = "{id=54064,NameZh='床单拼接的长绳',Icon='zhengju_icon_97',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='由床单拼接而成的长绳，在联结处打上了死结，十分坚固，可以支撑一个成年人的重量。',}",
  [54065] = "{id=54065,NameZh='王后口供',Icon='zhengju_icon_01',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='王后承认自己曾在房间里藏匿一名“情夫”。王子发现此事后，他们三人发生了争执与打斗，以“情夫”离开王宫、王子和解告终。但“情夫”的身份，以及去向，目前还存在疑点。',}",
  [54066] = "{id=54066,NameZh='传讯简报',Icon='zhengju_icon_96',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='经水打湿后显露字迹的信纸，上面写着针对王选候选人的计划与情报。',}",
  [54067] = "{id=54067,NameZh='伪造的通行证',Icon='zhengju_icon_94',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='用于卢恩王国与修发兹共和国之间的通行证，附有凯瑟琳王后的照片。但令人意外的是，通行证上的名字，却不是凯瑟琳王后的真名，而是伪造的假名。',}",
  [54068] = "{id=54068,NameZh='园丁喷壶',Icon='zhengju_icon_81',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='用于浇灌绿植的喷壶，里面残留着少量清水。',}",
  [54069] = "{id=54069,NameZh='染血地砖照片',Icon='zhengju_icon_110',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='王后阳台的地砖上，有一大滩干涸的血迹。曾有人将花盆拖到此处，掩盖血迹。',}",
  [54070] = "{id=54070,NameZh='墙面血迹照片',Icon='zhengju_icon_105',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='王后阳台的墙面上，残留着少许血迹。这是沾血的事物被拖拽而留下的痕迹。',}",
  [54071] = "{id=54071,NameZh='至尊徽戒',Icon='zhengju_icon_98',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='一枚造型特殊的男款戒指，戒面上雕刻着繁复的徽记。',}",
  [54072] = "{id=54072,NameZh='速成照片',Icon='zhengju_icon_100',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='一张由声控相机抓拍到的照片，可以看见有人将另一人从王后房间的阳台推落。但因为天色昏暗，无法辨认两人究竟是谁。',}",
  [54073] = "{id=54073,NameZh='染血衣物',Icon='zhengju_icon_99',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='被藏在草丛中的男性内衫，外形与王后房间密室发现的衣物一致。',}",
  [54074] = "{id=54074,NameZh='荒野鼠尾',Icon='',Type=165,Quality=2,MaxNum=1,SellPrice=100,}",
