  [54081] = "{id=54081,NameZh='国王的诊疗记录',Icon='zhengju_icon_91',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='国王医疗信息的记录，然而随着他的失踪，上面的内容已经停止了更新。',}",
  [54082] = "{id=54082,NameZh='国王档案',Icon='zhengju_icon_57',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='记录着国王信息的档案，然而随着他的失踪，上面的内容已经停止了更新。',}",
  [54083] = "{id=54083,NameZh='国王的验尸报告',Icon='zhengju_icon_03',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='死者姓名：特里斯坦·乔治\n死亡时间：\n尸体情况：后颅破裂，存在直径约1.5厘米的缺损；肺部保存较完整，未吸入烟尘；双腿胫骨长度不一，右腿胫骨比左腿胫骨短2寸。\n死亡原因：颅骨受撞击破裂，随后出现大出血而亡。\n报告人：卡尔·罗伯特',}",
  [54084] = "{id=54084,NameZh='日光神镜',Icon='item_54084',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29204,AdventureValue=105,AdventureReward={rewardid={870408}},Condition=64,Desc='传说中流星林散落了四面神镜，它们拥有着镌刻光影，回溯光阴的力量。',}",
