  [54087] = "{id=54087,NameZh='虹光神镜',Icon='item_54087',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29207,AdventureValue=105,AdventureReward={rewardid={870411}},Condition=64,Desc='传说中流星林散落了四面神镜，它们拥有着镌刻光影，回溯光阴的力量。',}",
  [54088] = "{id=54088,NameZh='天衍轮',Icon='item_54088',Type=63,Quality=3,MaxNum=99999,SellPrice=100,AdventureSort=29208,AdventureValue=105,AdventureReward={rewardid={870412}},Condition=64,Desc=' 模拟日月星辰轮转的仪器，其核心为伊米尔之心碎片与太阳、月亮、星星三种力量。',}",
  [54089] = "{id=54089,NameZh='勇气之心',Icon='item_6945',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29199,AdventureValue=105,AdventureReward={rewardid={870403}},Condition=64,Desc='伊米尔之心的碎片，蕴含着勇气的力量，就此交于命运之风。',}",
