  [54091] = "{id=54091,NameZh='纯洁之心',Icon='item_6947',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29201,AdventureValue=105,AdventureReward={rewardid={870405}},Condition=64,Desc='伊米尔之心的碎片，蕴含着纯洁的力量，就此交于命运之风。',}",
  [54092] = "{id=54092,NameZh='忠贞之心',Icon='item_6948',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29202,AdventureValue=105,AdventureReward={rewardid={870406}},Condition=64,Desc='伊米尔之心的碎片，蕴含着忠贞的力量，就此交于命运之风。',}",
  [54093] = "{id=54093,NameZh='守护之心',Icon='item_6949',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29203,AdventureValue=105,AdventureReward={rewardid={870407}},Condition=64,Desc='伊米尔之心的碎片，蕴含着守护的力量，就此交于命运之风。',}",
  [54094] = "{id=54094,NameZh='死灵之酒',Icon='item_7021',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='华莱士调制的酒，可以让人的气息变得和死灵一样。',}",
  [54095] = "{id=54095,NameZh='南瓜种子',Icon='item_12381',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='约姆家定期供奉给海拉，送往埃琉德尼尔宫的高品质南瓜的种子。',}",
  [54096] = "{id=54096,NameZh='朗姆酒',Icon='item_5952',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='两个吊死鬼常规售卖的酒，深受很多死灵的喜爱。',}",
  [54097] = "{id=54097,NameZh='赫尔饼',Icon='item_551015',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='尼夫海姆的特色食物，是海拉的宠物加尔姆最喜欢的食物。',}",
  [54098] = "{id=54098,NameZh='神秘料理',Icon='item_551019',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='不知道是谁做的料理，散发着黑暗的气息，无人问津。',}",
  [54099] = "{id=54099,NameZh='揉皱的纸团',Icon='zhengju_icon_49',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='被偷偷传阅多次导致褶皱严重的纸团，里面提到了一个藏有无数珍宝的岛屿。',}",
  [54100] = "{id=54100,NameZh='迷药',Icon='zhengju_icon_04',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='有人找狸猫商人利姆购买过这款迷药，而且极有可能用迷药把一些人绑上了远航的船只。',}",
  [54101] = "{id=54101,NameZh='三流小报',Icon='zhengju_icon_26',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='城市怪谈三流小报， 描述了一座满是会吃人的乌龟的……恐怖岛屿。',}",
  [54102] = "{id=54102,NameZh='契克的信',Icon='zhengju_icon_92',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='脱险淘金客契克在精神失常前写下的信件，描述了那座岛屿的一切都变成了……乌龟？',}",
  [54103] = "{id=54103,NameZh='出航水手的记录',Icon='zhengju_icon_96',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='水手的航海日记，记载了藏在一团炎热迷雾后面的乌龟岛',}",
  [54104] = "{id=54104,NameZh='吟游诗的唱本',Icon='zhengju_icon_57',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='吟游诗人的唱本，传说一直在海上飘来飘去会移动的，不是迷雾，而是乌龟岛本身。',}",
  [54105] = "{id=54105,NameZh='航船信息表',Icon='zhengju_icon_14',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='作为航线最多的港口城市，艾尔贝塔的航线通往全世界几乎所有的港口。但唯独没有任何一条航线，前往或者途径乌龟岛。',}",
  [54106] = "{id=54106,NameZh='阿依登的告诫',Icon='zhengju_icon_75',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='看似狡诈的商人，却提供了关键信息： 地狱里拥有一个宝物，能带领大家前往乌龟岛。',}",
  [54107] = "{id=54107,NameZh='铁矿石',Icon='item_52111',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='烧一烧可以锻造的矿石，虽然杂质看起来多了些。',}",
  [54108] = "{id=54108,NameZh='熔炉',Icon='item_6830',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='这燃烧的炉火，让周围更显灼热，是铁矿丢进去都会融化的程度。',}",
  [54109] = "{id=54109,NameZh='冷萃水',Icon='item_5020',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='冰川下的过冷水，放入其他物体后易凝结成冰',}",
  [54110] = "{id=54110,NameZh='人类的尸骸',Icon='item_52505',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='身上有绳索捆绑，头部有断痕的尸骸！应该是被绑着殴打致死。在乌龟岛高温的作用下很快散发出腐坏的味道。',}",
  [54111] = "{id=54111,NameZh='公告牌信息',Icon='14',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='圆圆圈圈，圈圈圆圆的，有点像人类的文字，又更像是乌龟背上的图样。',}",
  [54112] = "{id=54112,NameZh='破碎的照片',Icon='item_54112',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='失踪者们被绑架，登录乌龟岛的场景。绑架者身着黑袍看不清长相。照片的拍摄者恐怕也已遭遇不测。',}",
  [54113] = "{id=54113,NameZh='陌生人的遗言 ',Icon='zhengju_icon_49',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='奄奄一息的淘金者，死前嘴里重复的“大人”让人很在意。水晶、失踪人口和鹰派的人之间肯定有某种联系。',}",
  [54114] = "{id=54114,NameZh='混乱的脚印',Icon='zhengju_icon_11',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='混乱的脚印通往森林深处，虽然印记很快消失在草丛里，无法追寻更多，但至少指出了大致的方向。',}",
  [54115] = "{id=54115,NameZh='碎掉的水晶',Icon='item_54115',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='奇怪的水晶矿石的碎片，握在手中有时冷时热的感觉。和周围的石头并非同类，似乎是在搬运过程中落下的。',}",
  [54116] = "{id=54116,NameZh='万能钥匙的信息 ',Icon='14',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='密穴的牢笼需要钥匙打开，但每一个牢笼都对应了不同的钥匙。',}",
  [54117] = "{id=54117,NameZh='秘术操控的信息',Icon='zhengju_icon_96',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='老铁匠告知的重要信息，所有人都受到秘术操控，不得不工作下去直至死亡。',}",
  [54118] = "{id=54118,NameZh='断裂的鞭子',Icon='zhengju_icon_97',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='鞭子断口是因为用力太大导致断裂，血迹斑斑。',}",
  [54119] = "{id=54119,NameZh='被撕下的纸',Icon='zhengju_icon_49',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='\"我将我的一切奉献于女神，为女神工作本是荣耀，这些卑劣的贱民竟胆敢反抗，绝不饶恕。\"',}",
  [54120] = "{id=54120,NameZh='黑鹰雕像',Icon='item_54120',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='拥有秘术操控力量的黑影雕塑，是昆迪口中的魔法控制装置。需要用附近的开关解开，矿工们就能获得自由。',}",
  [54121] = "{id=54121,NameZh='酒瓶',Icon='zhengju_icon_69',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='来自遥远国度酿造的酒水，在内陆难得一见',}",
  [54122] = "{id=54122,NameZh='《店铺传单》',Icon='item_5802',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='抓住冬天的尾巴！暖炉清仓只需8000ZENY！',}",
  [54123] = "{id=54123,NameZh='《紧急文件》',Icon='item_5032',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='艾尔贝塔遭遇极端低温，严控市场经济，启用物资紧急预案。',}",
  [54124] = "{id=54124,NameZh='《卢恩律法》',Icon='item_42515',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='物资紧急预案启动后，禁止哄抬物价，违令者吊销营业执照。',}",
  [54125] = "{id=54125,NameZh='古老的龟甲',Icon='aebt_icon_05',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='刻着不知名的文字以及各种图案，似乎记录着文献，这里应该曾有过文明。',}",
  [54126] = "{id=54126,NameZh='祭祀器皿',Icon='item_31223',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='祭祀用的器皿，上面刻着乌龟形状的的图腾，还有一些看不懂的文字。',}",
  [54127] = "{id=54127,NameZh='穆奇的讲述信息',Icon='item_13408',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='巨大的海浪掀翻了船只,，众人落水后被被水流带至此处。',}",
  [54128] = "{id=54128,NameZh='赛尔的讲述信息',Icon='item_13409',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='船上的所有人一个不少地出现在这未知之地。',}",
  [54129] = "{id=54129,NameZh='粘液',Icon='item_6142',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='难闻的气味，诡异的颜色，让人产生不好的联想。',}",
  [54130] = "{id=54130,NameZh='天神古籍',Icon='item_12981',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='安格尔伯达的冰霜之杖的意外坠落，导致了人类历史上罕见的寒潮，这对人类而言是一场灾难。',}",
  [54131] = "{id=54131,NameZh='远航者的日记',Icon='item_5032',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='阿卡蕾娅亲眼见证了空无一物的海面上，一只巨型乌龟的突然出现。',}",
  [54132] = "{id=54132,NameZh='《远航者回忆录》',Icon='item_5524',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='巨型乌龟出现后，就开始在海面上缓慢的游动，并且在那之后从未停止。',}",
  [54133] = "{id=54133,NameZh='《灯塔观测日志》',Icon='item_12977',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='根据长期观察，乌龟岛的移动存在一定的规律，它的移动路线永远围绕着冰霜之杖。',}",
  [54134] = "{id=54134,NameZh='阿伦的调查报告',Icon='item_13413',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='根据阿伦的调查，乌龟岛周围的雾气是由于岛屿内部的高温导致冰块的融化而造成的。',}",
  [54137] = "{id=54137,NameZh='剩余的饭菜',Icon='item_12334',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='还冒着热气的饭菜，显然刚刚出锅不久，却等不到被装进肚子的时候。',}",
  [54138] = "{id=54138,NameZh='暗淡的光球',Icon='dark_001',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='给人一种不祥的预感，触摸时会有种要被腐蚀的可怕感觉。',}",
  [54139] = "{id=54139,NameZh='枯萎的农作物',Icon='item_38009',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='原本收获季节的作物，却像是失去了生命力，呈现枯萎状态。',}",
  [54140] = "{id=54140,NameZh='倒在地上的人',Icon='General_action',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='保持完整但毫无生机的尸体，仿佛被吸取了所有生命力。',}",
  [54141] = "{id=54141,NameZh='突然变异的狗',Icon='zhengju_icon_115',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='突然间发狂，从温驯变得狂躁，样子也发生了变化。',}",
  [54142] = "{id=54142,NameZh='鹿角木雕',Icon='item_45406',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29209,AdventureValue=105,AdventureReward={rewardid={870413}},Condition=64,Desc='拙劣的材质不配被摆在贵族老爷的桌上，真诚的心总被泥土覆盖，毕竟它难以被价值衡量',}",
  [54143] = "{id=54143,NameZh='贵族手记',Icon='zhengju_icon_56',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29210,AdventureValue=105,AdventureReward={rewardid={870414}},Condition=64,Desc='密密麻麻写满了名字和特殊符号，这上面的每一个图案都代表着血雨腥风，却是寻常人难以破解的贵族密语',}",
  [54144] = "{id=54144,NameZh='矢车菊',Icon='zhengju_icon_66',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29211,AdventureValue=105,AdventureReward={rewardid={870415}},Condition=64,Desc='如此明媚的花朵，它的生长需要和周围的植物争夺阳光、水和养分，美丽的外表可不是靠施舍得来。',}",
  [54145] = "{id=54145,NameZh='纯金盾牌',Icon='item_42505',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29212,AdventureValue=105,AdventureReward={rewardid={870416}},Condition=64,Desc='耀眼的金子沾上了看不见的血迹，可它的价值却无法被抹去，让世人趋之若鹜，仿佛比信仰更沉重。',}",
  [54146] = "{id=54146,NameZh='神圣十字架',Icon='item_42511',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29213,AdventureValue=105,AdventureReward={rewardid={870417}},Condition=64,Desc='美丽的芙蕾雅朝人间投来高高在上的悲悯一瞥，而祂的信徒则贯彻着她的意志',}",
  [54147] = "{id=54147,NameZh='和平鸟之翼',Icon='item_3001913',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29214,AdventureValue=105,AdventureReward={rewardid={870418}},Condition=64,Desc='和平的愿景如天边的云和振翅的飞翼，隐隐约约能看见美好的轮廓，却难以触摸',}",
  [54148] = "{id=54148,NameZh='交换的密信',Icon='item_3031176',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29215,AdventureValue=105,AdventureReward={rewardid={870419}},Condition=64,Desc='美丽的花纹字体，光明磊落的用词，可那些不见血的利益交换却潜藏在未能写出的字句中，信件的最后总是祝您安康顺心，如同最诚挚的好友',}",
  [54149] = "{id=54149,NameZh='刻字的石碑',Icon='item_38057',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29216,AdventureValue=105,AdventureReward={rewardid={870420}},Condition=64,Desc='上面的字迹早已模糊，可他们的名字却名列在史书上，任何人也无法抹去，随口说出话语仿佛玩笑，可风听到了他们的诺言。',}",
  [54150] = "{id=54150,NameZh='洁白的手帕',Icon='zhengju_icon_41',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29217,AdventureValue=105,AdventureReward={rewardid={870421}},Condition=64,Desc='年轻的国王立下战功，他如一头雄狮俯瞰着被纳入帝国的土地，可他的总司令官却破天荒地没能履行职责，而是第一时间看到了国王那被染红的衣袖。',}",
  [54151] = "{id=54151,NameZh='仿冒王国之剑',Icon='item_3003434',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29218,AdventureValue=105,AdventureReward={rewardid={870422}},Condition=64,Desc='幼年的执着早已被忘在脑后，但你的心意我从未忘记，你说我是国王，这便是我的王国之剑，但现在我想要的不是这把剑，而是和你一起并肩走下去的王国。',}",
  [54152] = "{id=54152,NameZh='陈旧的罐子',Icon='item_12117',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29219,AdventureValue=105,AdventureReward={rewardid={870423}},Condition=64,Desc='真正填满罐子的不是魔法，是耐心的陪伴，看着沮丧的少年，海因里希无奈皱眉，默默坐到施密特的身边，为他算好风力和鱼群的位置，替他作弊吗？一贯如此，无论是钓鱼还是统治王国。',}",
  [54153] = "{id=54153,NameZh='一张旧照',Icon='pic_36',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29220,AdventureValue=105,AdventureReward={rewardid={870424}},Condition=64,Desc='海因里希讨厌拍照，不明白这种执着于留下影像的行为有什么意义，施密特却总是笑着用镜头对准他，“喂喂，笑一笑嘛。”海因里希冷哼一声，却朝镜头凑近了点。',}",
  [54154] = "{id=54154,NameZh='白星手套',Icon='zhengju_icon_24',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=29221,AdventureValue=105,AdventureReward={rewardid={870425}},Condition=64,Desc='总司令官与国王究竟是什么关系？在贵族口中两人似有奸情，在侍从眼里也是颇多暧昧。而真实的他们自幼一起长大，当施密特走向王位时，海因里希陪伴在侧，胜利时他们一同庆贺，施密特迷茫时，海因里希也能将他拉出泥潭。是朋友、是知己，是形影不离的伙伴，外人满怀恶意的流言又如何能形容他们的情谊？无论何时，我将与你相伴，白星将悬于王位，为他照亮前路，哪怕燃烧自己。',}",
  [54180] = "{id=54180,NameZh='土俄希托斯之眼',Icon='item_7124',Type=69,Quality=2,MaxNum=1,SellPrice=100,}",
