  [54869] = "{id=54869,NameZh='遗失的胸针',Icon='item_42554',Type=160,MaxNum=99999,SellPrice=100,Desc='枫叶模样的胸针，似乎是什么人丢失的物品。如果遇到一位寻找它的精灵少女，别忘了把这件东西还给她。',GetLimit={limit_count=1,source={10,19,54,97},type=3},}",
  [54870] = "{id=54870,NameZh='佩瑞丝的雨珠',Icon='item_52029',Type=160,MaxNum=99999,SellPrice=100,Desc='荒野佩瑞丝在雨天欢歌时会向周围散发出强烈的魔力波动，从而将落在身旁的雨水凝结成闪亮的雨珠。这些魔力雨珠凝结着荒野佩瑞丝的欢乐和善意，是荒境巡守队的药剂师制作疗伤药剂的重要原料。',}",
  [54871] = "{id=54871,NameZh='森之种',Icon='',Type=165,MaxNum=99999,SellPrice=100,}",
  [54872] = "{id=54872,NameZh='日光琥珀',Icon='',Type=165,MaxNum=99999,SellPrice=100,}",
  [54873] = "{id=54873,NameZh='彩虹鳞片',Icon='',Type=165,MaxNum=99999,SellPrice=100,}",
  [54874] = "{id=54874,NameZh='灯笼',Icon='',Type=165,MaxNum=99999,SellPrice=100,}",
  [54875] = "{id=54875,NameZh='魔法符石',Icon='',Type=165,MaxNum=99999,SellPrice=100,}",
  [54876] = "{id=54876,NameZh='蛇皮',Icon='',Type=165,MaxNum=99999,SellPrice=100,}",
  [54877] = "{id=54877,NameZh='棒棒糖',Icon='',Type=165,MaxNum=99999,SellPrice=100,}",
  [54878] = "{id=54878,NameZh='友情的证明',Icon='item_700173',Type=160,MaxNum=99999,SellPrice=100,}",
  [54879] = "{id=54879,NameZh='邪龙残角',Icon='item_54879',Type=62,MaxNum=99999,SellPrice=100,Desc='深渊龙骸的角，是战胜龙骸的证明。只有最勇敢的人才能获得。它似乎和月光岩洞的水晶灵树产生了强烈的共鸣，去找月光岩洞水晶灵树旁的卡修忒询问一下吧。（每周一5:00清除）',}",
  [54880] = "{id=54880,NameZh='灵灯之力',Icon='',Type=165,MaxNum=99999,SellPrice=100,}",
  [54881] = "{id=54881,NameZh='贡德利之刃',Icon='item_40303',Type=62,MaxNum=99999,SellPrice=100,Desc='工匠贡德利耗尽心血锻造的刀刃，后被元灵武士抢夺，残留着战士生前的遗憾与怨念。虽然已经年代久远，但其上的刀铭仍依晰可见：“赠予我的友人……祝他武运昌隆。”（每周一5:00清除）',}",
  [54882] = "{id=54882,NameZh='隐藏用的树枝',Icon='item_61',Type=165,MaxNum=99999,SellPrice=100,}",
  [54883] = "{id=54883,NameZh='桂枝',Icon='item_6096',Type=160,MaxNum=99999,SellPrice=100,Desc='星宫里，有一颗长青的桂树长满了散发幽香的白花。桂树下有个可爱的月兔，月兔每天都会将桂树的树枝捣成药浆，用药浆制作不死灵药。此或许是辉夜正在寻找之物，她正在枫叶彼岸西侧等你。',}",
  [54884] = "{id=54884,NameZh='黄金杯',Icon='item_12568',Type=160,MaxNum=99999,SellPrice=100,Desc='星宫的侍女斟酒的杯子，泛着迷人的黄金光芒。传说中星宫里的天女，尚未飞去星宫时，曾经喜欢跟自己的恋人一起用黄金杯饮酒。此或许是辉夜正在寻找之物，她正在枫叶彼岸西侧等你。',}",
  [54885] = "{id=54885,NameZh='堕日',Icon='item_41239',Type=160,MaxNum=99999,SellPrice=100,Desc='法纳族战士宗布的武器，宗布是法纳族有名的射手，他可以看清千里外的东西，可以拉动最沉的弓。诸神创世时期，法纳族曾经遭遇魔物不死鸟的袭击，宗布使用堕日将不死鸟驱逐离开。此或许是辉夜正在寻找之物，她正在枫叶彼岸西侧等你。',}",
  [54886] = "{id=54886,NameZh='不死灵药',Icon='item_12392',Type=160,MaxNum=99999,SellPrice=100,Desc='不死鸟的力量之源，如果吞入可以获得长生不老的力量。宗布射下不死鸟，获得了不死灵药，他和自己的妻子辉夜一同服下不死灵药。但是，等待着他们的，却是永恒的别离。此或许是辉夜正在寻找之物，她正在枫叶彼岸西侧等你。',}",
  [54887] = "{id=54887,NameZh='蛇胆',Icon='',Type=165,MaxNum=99999,SellPrice=100,}",
