  [54927] = "{id=54927,NameZh='闪光宝石',Icon='item_44136',Type=160,MaxNum=99999,SellPrice=100,Desc='象征着坚毅精神的宝石。好像某个徘徊的灵魂很喜欢它。',}",
  [54928] = "{id=54928,NameZh='彩色珍珠',Icon='item_53778',Type=160,MaxNum=99999,SellPrice=100,Desc='凝聚着爱情气息，散发不可思议光泽的珍珠……',}",
  [54929] = "{id=54929,NameZh='神秘纸条',Icon='item_900009',Type=160,MaxNum=99999,SellPrice=100,Desc='“西洋棋盘上，注视之人的正前方，掩埋半队兵士的遗物。“',}",
  [54930] = "{id=54930,NameZh='苍星玫瑰',Icon='item_48682',Type=160,MaxNum=99999,SellPrice=100,Desc='非常珍贵的蓝玫瑰，好像很受贵族小姐的喜爱。',}",
  [54931] = "{id=54931,NameZh='王子遗像',Icon='zhengju_icon_59',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='摆放在棺木上的王子的遗像，居然成为了王宫里唯一还能看到王子面容的地方。',}",
  [54932] = "{id=54932,NameZh='王宫传言',Icon='zhengju_icon_87',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='王宫内一直有传言，乐师艾伦斯特和王后的感情很是暧昧。王后准备在王子的追悼会结束后，就带着艾伦斯特去花园散心',}",
  [54933] = "{id=54933,NameZh='邀请函',Icon='zhengju_icon_37',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='尊敬的朋友：\n诚挚邀请您明日参加巴尔特现任家主伊安·巴尔特在王室剧院举办的五十五岁生日宴。做为王室忠诚的守护者，伊安·巴尔特会一如既往将生命与荣耀献给七王室，永远效忠于初始的荣光。\n愿诸位在宴会上获得快乐。\n附：请在宴会当天将邀请函递交给大厅门口的侍从，方可进入。\n                                      您真诚的\n                                   伊安·巴尔特',}",
  [54934] = "{id=54934,NameZh='花园里的照片',Icon='zhengju_icon_42',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='伊安·巴尔特和乐师艾伦在花园中起了争执，这个画面被弗兰克记录了下来。',}",
  [54935] = "{id=54935,NameZh='海尔穆特的照片',Icon='zhengju_icon_44',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='几乎是在海尔穆特的威胁下拍下的合影，照片里爱葛妮斯对哥哥很是嫌弃。',}",
  [54936] = "{id=54936,NameZh='调查王令',Icon='zhengju_icon_23',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='一份2前的报纸，刊登着当年的新闻，没什么特别的内容。',}",
  [54937] = "{id=54937,NameZh='案发现场照片',Icon='zhengju_icon_111',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='由获得调查王令的冒险者拍摄下的现场照片。',}",
  [54938] = "{id=54938,NameZh='阿伦的验尸报告',Icon='zhengju_icon_03',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='死者姓名：阿伦· 巴尔特 \n死亡时间：中午11:10 \n尸体情况：胸口插有锋利的匕首，无额外伤，无中毒症状。  \n死亡原因：被人用锋利的匕首刺伤心脏， 造成失血性休克，当场死亡。 \n报告人：卡尔·罗伯特',}",
  [54939] = "{id=54939,NameZh='杀手的验尸报告',Icon='zhengju_icon_03',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='死者姓名：不知 \n死亡时间：中午11:10 \n尸体情况：口中渗出大量鲜血，血液里散发出异味，无其它额外伤口。  \n死亡原因：死者服用了包括乌头毒草、苦杏仁、砒霜在内的致命毒药。 \n报告人：卡尔·罗伯特',}",
  [54940] = "{id=54940,NameZh='匕首',Icon='zhengju_icon_45',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='镶嵌了珠宝、制作精良的匕首，是绝非平常人家能使用的贵重贴身兵器。 刀身锋利，足以造成致命的损伤。',}",
  [54941] = "{id=54941,NameZh='杀手的徽章',Icon='zhengju_icon_46',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='从杀手身上拿到的徽章，徽章的标示证明此人应该曾经是某王室的侍从。',}",
  [54942] = "{id=54942,NameZh='金弦琴',Icon='zhengju_icon_36',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='纯金打造的古典乐器，为巴尔特家族的珍宝。',}",
  [54943] = "{id=54943,NameZh='马丁的证词',Icon='zhengju_icon_01',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='马丁在两天前亲眼见到海尔穆特鬼鬼祟祟离开了王宫，还在王宫外不远处和陌生人接头。',}",
  [54944] = "{id=54944,NameZh='爱葛妮斯的决绝',Icon='zhengju_icon_01',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='哥哥如果不说实话，我就再也不要理哥哥了！',}",
  [54945] = "{id=54945,NameZh='阴森的戒指',Icon='zhengju_icon_47',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='带有骷髅和毒药元素的戒指，感觉很是危险。把这个交给魔药商人波娜，就能获得对方的信任。',}",
  [54946] = "{id=54946,NameZh='揉皱的纸张',Icon='zhengju_icon_49',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='被大力揉皱的纸团，能看到有书写的痕迹。',}",
  [54947] = "{id=54947,NameZh='揉皱的纸张',Icon='zhengju_icon_49',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='被大力揉皱的纸团，能看到有书写的痕迹。\n纸团打开变成了海尔穆特部队的失物申报表，笔记力道强劲但混乱，感觉是在很愤怒的情况下填写的。',}",
  [54948] = "{id=54948,NameZh='揉皱的纸张',Icon='zhengju_icon_49',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='被大力揉皱的纸团，能看到有书写的痕迹。\n纸团打开变成了海尔穆特部队的失物申报表，笔记力道强劲但混乱，感觉是在很愤怒的情况下填写的。',}",
  [54949] = "{id=54949,NameZh='药品收据',Icon='zhengju_icon_50',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='魔药商人波娜家的收据单，上面会写明病人购买或委托制作的药品名称。',}",
  [54950] = "{id=54950,NameZh='曼德拉草',Icon='zhengju_icon_48',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='类似人形样子的珍贵草药，极其难得，提炼后得药剂可以治疗非常严重的疾病。',}",
  [54951] = "{id=54951,NameZh='海尔穆特的证词',Icon='zhengju_icon_01',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='海尔穆特在解决曼德拉草失窃事件时遭黑市商人陷害，争执中导致匕首丢失。匕首丢失时间远在阿伦死亡案件发生之前。',}",
  [54952] = "{id=54952,NameZh='金弦琴的画',Icon='zhengju_icon_51',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='乔伊画出的，居然是那把独一无二的巴尔特金弦琴，一个作为平民完全不可能接触或者知道的东西。',}",
  [54953] = "{id=54953,NameZh='巧克力',Icon='zhengju_icon_52',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='乔伊一直珍藏的糖果，她说是父亲送给她的礼物。看包装这颗糖就应该很昂贵。',}",
  [54954] = "{id=54954,NameZh='有印章的巧克力',Icon='zhengju_icon_52',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='这是来自巴尔特家族的糖果。',}",
  [54955] = "{id=54955,NameZh='酒精纱布',Icon='zhengju_icon_62',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='浸润了酒精的纱布，可以快速擦拭掉物品上血迹',}",
  [54956] = "{id=54956,NameZh='被封印的银盒',Icon='zhengju_icon_21',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='用于继位仪式上放置国王权杖的盒子，隶属于教会。盒身被施加了封印，只有主教才能开启。',}",
  [54957] = "{id=54957,NameZh='凯沃宝乐格家族家徽',Icon='zhengju_icon_54',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='目前执政的家族：凯沃宝乐格的家徽。象征最高权力的权杖是整个家徽最亮眼的部分。',}",
  [54958] = "{id=54958,NameZh='巴尔特家族家徽',Icon='zhengju_icon_55',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='从事海上贸易的家族：巴尔特的家徽。乘风破浪的皇家远洋舰队一直是巴尔特的骄傲。',}",
  [54959] = "{id=54959,NameZh='奈利乌斯家族家徽',Icon='zhengju_icon_53',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='由女性掌权的家族：奈利乌斯家族的家徽。蓝色的双生玫瑰，用来保卫“能包容世上万物的心”。',}",
  [54960] = "{id=54960,NameZh='恐吓信',Icon='zhengju_icon_75',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='威胁艾瑞希·奈利乌斯退出王选的恐吓信。既没有落款，也没法从通用字体上推断寄信人的身份。',}",
  [54961] = "{id=54961,NameZh='艾伦斯特的验尸报告',Icon='zhengju_icon_03',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='死者姓名：艾伦斯特·乔治\n尸体情况：被重度焚烧、面目模糊；尸体呈蜷缩状。\n死亡原因：烈火灼烧而亡\n死亡时间：参考起火时间，应为零点三刻。\n报告人：卡尔·罗伯特',}",
  [54962] = "{id=54962,NameZh='焦黑金属残片',Icon='zhengju_icon_77',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='四片焦黑金属片，上面残存着一些花纹，看起来像某种器物的残骸。',}",
  [54963] = "{id=54963,NameZh='小瓷瓶',Icon='zhengju_icon_79',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='看上去非常普通的小瓷瓶，为什么会出现在尸体附近呢？',}",
  [54964] = "{id=54964,NameZh='空桶',Icon='zhengju_icon_81',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='外表肮脏陈旧的铁皮桶，王子的房间，可不该出现这样的东西。曾经容纳的东西已经倒空，只留下刺鼻的气味。',}",
  [54965] = "{id=54965,NameZh='神秘鞋印的照片',Icon='zhengju_icon_106',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='王子房间的后窗前有一副鞋印，说明曾有人来到过窗边。鞋印的花纹相当特殊。',}",
  [54966] = "{id=54966,NameZh='储物箱的照片',Icon='zhengju_icon_107',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='从王后房间运出的储物箱，其中的物件已经被搬空，隐隐散发着一股陈腐的味道。',}",
  [54967] = "{id=54967,NameZh='受损房门的照片',Icon='zhengju_icon_108',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='王子房间的房门锁舌断裂，门板上也有着被魔法火炎轰击后留下的焦痕。',}",
  [54968] = "{id=54968,NameZh='小锤子',Icon='item_13602',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='用于砸开坚果的金属小锤，也可以派别的用处。',}",
  [54969] = "{id=54969,NameZh='铜钥匙',Icon='zhengju_icon_82',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='王子房间内找到的铜钥匙，外表平平无奇，不知能打开什么东西。',}",
  [54970] = "{id=54970,NameZh='绘本：金弦琴',Icon='item_500620',Type=65,Quality=3,UseMode=31180,MaxNum=1,SellPrice=100,Desc='以「金弦琴」为主题的漫画。打开后冒险家可以进行自由填色哦！',}",
  [54971] = "{id=54971,NameZh='乐师的病历本',Icon='zhengju_icon_56',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='乐师艾伦斯特的病历本，平平无奇，与其它王室侍从的病历本并没有区别。',}",
  [54972] = "{id=54972,NameZh='王后的档案',Icon='zhengju_icon_57',Type=69,Quality=2,MaxNum=1,SellPrice=100,}",
  [54973] = "{id=54973,NameZh='书籍',Icon='item_6700',Type=69,Quality=2,MaxNum=1,SellPrice=100,}",
  [54974] = "{id=54974,NameZh='王子的档案',Icon='zhengju_icon_57',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='往年都会固定更新信息的王子档案。可惜从今以后，这本档案再也不会拿来书写，只能用作缅怀。',}",
  [54975] = "{id=54975,NameZh='王后的宝箱',Icon='zhengju_icon_18',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='王后的私人宝箱，需要钥匙才能打开。',}",
  [54976] = "{id=54976,NameZh='宝箱钥匙',Icon='zhengju_icon_31',Type=69,Quality=2,MaxNum=1,SellPrice=100,}",
  [54977] = "{id=54977,NameZh='手帕',Icon='zhengju_icon_41',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='王室御用匠人制作的手帕，看得出从制作完工后就被小心收藏，从未真正意义上的使用过。2、手帕上的缩写代表的是艾伦斯特。',}",
  [54978] = "{id=54978,NameZh='王后日记本',Icon='zhengju_icon_58',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='装帧精美的小日记本。',}",
  [54980] = "{id=54980,NameZh='已故王子的照片',Icon='zhengju_icon_112',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='卡尔和弗兰克打开王子棺木拍下的照片。虽说是为了真相，这个行动也确实太大胆了。',}",
  [54981] = "{id=54981,NameZh='苹果醋',Icon='zhengju_icon_102',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='用妙勒尼高山苹果酿成的果醋，味道酸甜、色泽透亮。',}",
  [54982] = "{id=54982,NameZh='芹菜汁',Icon='zhengju_icon_103',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='碧油油的芹菜汁，隔着瓶子，都能想象出浓郁的苦涩味道。',}",
  [54983] = "{id=54983,NameZh='大罐红燧石粉',Icon='zhengju_icon_83',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='名为红燧石粉的物质，被当做珍贵香料使用的，将它加入炭火，可以让食物染上刺激的口感。',}",
  [54984] = "{id=54984,NameZh='餐厅侍从的皮鞋',Icon='zhengju_icon_84',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='餐厅侍从专用的黑皮鞋，材质精良、款式实用。',}",
  [54985] = "{id=54985,NameZh='宫廷总管的口供',Icon='zhengju_icon_01',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='王子被害的前一天晚上，有一名窃贼在宴会厅行窃。对方盗走了一桶煤油、部分红燧石粉，与一套宴会厅侍从的制服和皮鞋。',}",
  [54986] = "{id=54986,NameZh='瓶中的红色粉末',Icon='zhengju_icon_80',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='从小瓶子中获取的红色粉末，成分无法识别。嗅起来带有辛辣刺激的味道，感觉像是……某种佐料。',}",
  [54987] = "{id=54987,NameZh='开瓶的葡萄酒',Icon='zhengju_icon_21',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='一瓶已经被开启的葡萄酒，被喝掉了一部分。但这一点酒液，不至于使人醉酒昏睡。',}",
  [54988] = "{id=54988,NameZh='书中的信笺',Icon='zhengju_icon_85',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='散发着特殊香味的信纸，用娟秀而独特的字迹书写着：“期待与你午夜相会，派特阁下。”',}",
  [54989] = "{id=54989,NameZh='客房内的空桶',Icon='zhengju_icon_81',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='本该放置在厨房，却出现在王子房间的煤油桶，其中的煤油，已经全部被人使用掉了。',}",
  [54990] = "{id=54990,NameZh='瓶中的红色粉末',Icon='zhengju_icon_80',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='从小瓶子中获取的红色粉末，成分无法识别。嗅起来带有辛辣刺激的味道，感觉像是……某种佐料。',}",
  [54991] = "{id=54991,NameZh='暖手炉',Icon='zhengju_icon_78',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='宫廷标配的暖手炉，核心由魔法结晶构成，可以加热到40℃。',}",
  [54992] = "{id=54992,NameZh='餐厅访客名单',Icon='zhengju_icon_21',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='小瓷瓶底残留着些许红色粉末，嗅起来带有辛辣刺激的味道。但究竟是什么物质，尚无线索。',}",
  [54993] = "{id=54993,NameZh='关于香气的情报',Icon='zhengju_icon_96',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='信笺上的香水名为“白色罗莎”，只有奈利乌斯家主、韦格纳夫人和凯瑟琳王后有资格使用。但是奈利乌斯家主远离普隆德拉，韦格纳夫人讨厌香水——因此，目前宫廷中“白色罗莎”的使用者，只能是凯瑟琳。',}",
  [54994] = "{id=54994,NameZh='韦格纳家的投诉信',Icon='zhengju_icon_92',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='致王室剧院：\n     虽然你们为我提供了精彩的演出，但我不得不抱怨演员身上刺鼻的香气。它们不仅损坏我的健康，还对自然中的花草极不友好。我希望剧院乃至整个王宫，都应该减少对香料的使用。\n                                                        贝拉·韦格纳',}",
  [54995] = "{id=54995,NameZh='剧院油画',Icon='zhengju_icon_86',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='名为《火焰之舞》的巨型油画，画面是一个正在跳舞的金发女性，相貌有几分眼熟。',}",
  [54996] = "{id=54996,NameZh='小毛刷',Icon='zhengju_icon_113',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='用于清洁的小毛刷，可以刷去陈年的顽固积灰。',}",
  [54997] = "{id=54997,NameZh='香水使用者名单',Icon='zhengju_icon_87',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='宝格丽夫人认出信笺上的香水名为“白色罗莎”，宫廷中只有个别贵妇有资格使用它。',}",
  [54998] = "{id=54998,NameZh='被袭击的艺人',Icon='zhengju_icon_01',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='一名“假面歌舞团”的艺人遭受袭击，并被扒光了一身道具服装。他没看见袭击者的面目，但记得对方身着铠甲。',}",
  [54999] = "{id=54999,NameZh='骑士伊柏的口供',Icon='zhengju_icon_01',Type=69,Quality=2,MaxNum=1,SellPrice=100,Desc='伊柏受一个神秘女人的贿赂，在案发当晚放派特离开贵宾室。据他回忆，派特归来的时间是凌晨一点整。',}",
