  [55123] = "{id=55123,NameZh='手推车',Icon='item_25300',Type=91,MaxNum=1,SellPrice=0,Desc='初级手推车，转职成为商人后可使用',}",
  [55124] = "{id=55124,NameZh='照明手推车',Icon='item_25302',Type=91,MaxNum=1,SellPrice=0,Desc='木匠伍德设计的手推车，使用百年椴木作为原材料，坚固耐用适合长途奔波的冒险者，减轻行路上的负重哦。习得技能【改装手推车】Lv.5可使用',}",
  [55125] = "{id=55125,NameZh='五郎',Icon='SoldierCat1',Type=1200,MaxNum=1,SellPrice=0,Desc='天生活泼好动的五郎，也选择了最适合自己性格的职业，外卖猫！成为了外卖猫的五郎是最受欢迎的佣兵之一，对雇主悉心照顾，他不会允许自己的雇主受伤！',}",
  [55126] = "{id=55126,NameZh='阿宝',Icon='SoldierCat2',Type=1200,MaxNum=1,SellPrice=0,Desc='以一身厉害的功夫武道闻名，神秘的猫猫佣兵团成员！阿宝是以武力著称的佣兵，深得雇主们的信任，因为有阿宝在，他们的安危就不会受到威胁！',}",
  [55127] = "{id=55127,NameZh='山葵',Icon='SoldierCat4',Type=1200,MaxNum=1,SellPrice=0,Desc='以佣兵团的盾牌自称，神秘的猫猫佣兵团成员！山葵是以坚固的防御闻名于世的佣兵，在关键时刻敢于为雇主抵挡致命一击，深得雇主们的信任，有山葵在，雇主们从来不担心自己的生命是否收到威胁！',}",
  [55128] = "{id=55128,NameZh='美莎',Icon='SoldierCat3',Type=1200,MaxNum=1,SellPrice=0,Desc='优雅的舞步，高傲神秘的猫猫佣兵团成员！美莎是以魔法攻击著称的佣兵猫，一切在危险在美莎的魔法下都不堪一击，敌人们沉迷于美莎的舞姿，倒在了美莎的魔法之下。雇主们很乐意雇佣美莎这个多才多艺的佣兵猫。',}",
  [55129] = "{id=55129,NameZh='神秘礼物',Icon='item_710045',Type=90,MaxNum=1,SellPrice=0,Desc='任务中根据不同选择可以获得不一样的礼物哟！',}",
