  [62509] = "{id=62509,NameZh='巨灵拳套[1]',Icon='item_62509',Type=290,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=3200,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='附着了巨灵魔力的拳套，挥舞时会形成巨大的气流，让敌人闻风丧胆。',Feature=1,LoadShowSize=2.6,LoadShowRotate=250,LoadShowPose={-0.2,0.44,0},}",
