  [62511] = "{id=62511,NameZh='卡仑的指甲[1]',Icon='item_62511',Type=290,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=30000,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='被它刺中并不会流血，那是因为刺中的瞬间，血就已经结冰了。',Feature=1,LoadShowRotate=-120,LoadShowPose={0,0.25,0},}",
  [62512] = "{id=62512,NameZh='冰晶拳套[1]',Icon='item_62512',Type=290,Quality=3,MaxNum=99,SellPrice=100,Feature=1,}",
