  [62515] = "{id=62515,NameZh='霸王乱舞[1]',Icon='item_62515',Type=290,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='寄宿着古老英魂的拳套，戴上它之后，每一招都变得更加迅猛有力，攻击缭乱如舞让敌人无从招架。“我要打十个。”——某位武术宗师',Feature=1,LoadShowSize=2.6,LoadShowRotate=250,LoadShowPose={-0.3,0.44,0},}",
  [62516] = "{id=62516,NameZh='英灵·古丝之战拳',Icon='item_62516',Type=290,MaxNum=99,SellPrice=100,AdventureSort=100006,AdventureValue=1,Condition=8,Desc='战斗之神——古丝的拳套，没有人能在古丝的双拳之下毫发无伤，而她的拳套只有真正强大的战斗者才能驾驭，得到这个拳套的人，都是当世最强大的战士。',Feature=1,LoadShowSize=2.6,LoadShowRotate=250,LoadShowPose={-0.3,0.44,0},}",
