  [62520] = "{id=62520,NameZh='战斗拳套',Icon='item_62502',Type=290,MaxNum=99,SellPrice=1080,Level=90,}",
  [62521] = "{id=62521,NameZh='圣徒拳套[1]',Icon='item_62521',Type=290,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='作为圣歌教会中强大的暴力机构，“光明圣徒”安德鲁受到大主教的命令为武僧订做一对拳套。特制的拳套材料甚至能够加速气的流动，这对拳套制作出来之后就迅速装备了教会中的所有武僧。受到光明圣徒的祝福，安全精炼时消耗的装备件数减少一半。',Feature=1,LoadShowSize=2.4,LoadShowRotate=250,LoadShowPose={-0.2,0.4,0},}",
  [62522] = "{id=62522,NameZh='衔尾者拳套',Icon='item_62522',Type=290,MaxNum=99,SellPrice=100,AdventureSort=100004,AdventureValue=1,Condition=8,Desc='赤色大蛇的鳞片赋予拳套疯狂暴击的力量',Feature=1,LoadShowSize=2.4,LoadShowRotate=250,LoadShowPose={-0.3,0.44,0},}",
  [62523] = "{id=62523,NameZh='星界·破击印',Icon='item_62523',Type=290,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=100002,AdventureValue=1,Condition=8,Desc='利用星辰中提炼出的珍贵矿石制作而成，与手掌融为一体，即使身处于不同相位，也可能击中敌人。',Feature=1,LoadShowSize=2.2,LoadShowRotate=250,LoadShowPose={-0.3,0.44,0},}",
  [62524] = "{id=62524,NameZh='高级乐园团拳套[1]',Icon='item_62501',Type=290,MaxNum=99,SellPrice=100,Level=1,NoStorage=5,}",
  [62525] = "{id=62525,NameZh='裂风者',Icon='item_62525',Type=290,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=100001,AdventureValue=1,Condition=8,Desc='侏儒和罗姆使用了神秘铸铁打造的拳套，可配合使用者的手掌大小自由伸缩，相传和罗姆曾与大魔导师加里奥战斗时曾使用过自己打造的拳套，他仅轻轻挥舞就撕裂了加里奥的狂风魔法，他自己都被拳套的威力所震撼，这个拳套也被后人尊称为裂风者。（建议作为武器外观使用）',Feature=1,LoadShowSize=2.4,LoadShowRotate=250,LoadShowPose={-0.3,0.44,0},}",
  [62526] = "{id=62526,NameZh='圣灵·古丝之沉影拳',Icon='item_62526',Type=290,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='战斗之神——古丝的拳套，这双拳打出的拳影重叠在一起，看起来仿佛身前的影子都被扭曲了。',Feature=1,LoadShowSize=2.6,LoadShowRotate=250,LoadShowPose={-0.3,0.44,0},}",
  [62527] = "{id=62527,NameZh='狂战拳套',Icon='item_62502',Type=290,MaxNum=99,SellPrice=1140,Desc='特有的蓝白花纹说明了它的来历，著名武器家族诺格罗德的代表作品，曾荣获王国年度武器设计最佳。',Level=95,}",
  [62528] = "{id=62528,NameZh='湮灭者',Icon='item_62528',Type=458,Quality=4,MaxNum=1,SellPrice=100,Desc='传说风之精灵迦楼罗了解大气魔法的真理，他铸造的这双拳套，轻轻一拳就能掀起狂风，若是连续出拳，方圆百尺都会被爆裂的飓风夷为平地。',NoSale=1,NoStorage=7,}",
  [62529] = "{id=62529,NameZh='湮灭者·精锻',Icon='item_62529',Type=458,Quality=4,MaxNum=1,SellPrice=100,Desc='传说风之精灵迦楼罗了解大气魔法的真理，他铸造的这双拳套，轻轻一拳就能掀起狂风，若是连续出拳，方圆百尺都会被爆裂的飓风夷为平地。',NoSale=1,NoStorage=7,}",
  [62530] = "{id=62530,NameZh='湮灭者·神铸',Icon='item_62530',Type=458,Quality=4,MaxNum=1,SellPrice=100,Desc='传说风之精灵迦楼罗了解大气魔法的真理，他铸造的这双拳套，轻轻一拳就能掀起狂风，若是连续出拳，方圆百尺都会被爆裂的飓风夷为平地。',NoSale=1,NoStorage=7,}",
  [62531] = "{id=62531,NameZh='月辉·极星拳套',Icon='item_62531',Type=290,MaxNum=99,SellPrice=100,AdventureSort=100008,AdventureValue=1,Condition=8,Desc='暗月马戏团标志性的武器，因其式样低调而华丽又非常稀有，成为了年轻冒险家追捧的热门武器',LoadShowSize=2.2,LoadShowRotate=250,LoadShowPose={-0.3,0.44,0},}",
  [62532] = "{id=62532,NameZh='日耀·赤羽拳套',Icon='item_62532',Type=290,MaxNum=99,SellPrice=100,AdventureSort=100007,AdventureValue=1,Condition=8,Desc='太阳马戏团标志性的武器，耀眼的金光和精致的造型，是坚持爱与正义的冒险者所追寻的目标',LoadShowSize=2.2,LoadShowRotate=250,LoadShowPose={-0.3,0.44,0},}",
  [62533] = "{id=62533,NameZh='守备军拳套',Icon='item_62522',Type=290,MaxNum=99,SellPrice=2000,Level=90,}",
  [62534] = "{id=62534,NameZh='碎雪·狮王之怒',Icon='item_62534',Type=290,MaxNum=99,SellPrice=100,AdventureSort=100009,AdventureValue=1,Condition=8,Desc='参照传说中的冰原雪狮子打造的古老拳套，蕴藏着冰霜的力量，打出的每一拳都能让敌人感受到穿透灵魂的寒意。',LoadShowSize=2.2,LoadShowRotate=250,LoadShowPose={-0.15,0.44,0},}",
  [62535] = "{id=62535,NameZh='炎魂·恶犬修罗',Icon='item_62535',Type=290,MaxNum=99,SellPrice=100,AdventureSort=100010,AdventureValue=1,Condition=8,Desc='参照传说中的地狱三头犬打造的古老拳套，蕴藏着火炎的力量，打出的每一拳都能让敌人感受到灵魂燃烧的炽热。',LoadShowSize=2.2,LoadShowRotate=250,LoadShowPose={-0.15,0.44,0},}",
  [62536] = "{id=62536,NameZh='枫忆拳套',Icon='item_62536',Type=290,MaxNum=99,SellPrice=100,AdventureSort=100003,AdventureValue=1,Condition=8,Desc='我有一个特别讨厌的朋友，他总是和我作对，举个例子吧，树下有一对在吵架的情侣，我认为是男孩子的错，他却非要说是女孩子的错，我们每次都吵得不可开交，这样的日子一直持续到我们的身体变成了鲜艳的红色，生命即将终结的时刻，我说这是我们生命结束之前的灿烂，这一次他却没有反驳我，看来是我赢了呢，可是我为什么却高兴不起来呢。再次醒来的时候，我变成了一只拳套，神奇的是另一只拳套我的那个朋友，啧，真是冤家路窄呢！',LoadShowSize=2.2,LoadShowRotate=250,LoadShowPose={0,0.44,0},}",
  [62537] = "{id=62537,NameZh='信仰拳套',Icon='item_62537',Type=290,MaxNum=99,SellPrice=100,AdventureSort=100005,AdventureValue=1,Condition=8,Desc='巴风特曾带领手下对梦罗克进行过一次史无前例的大侵袭，这次的战争造成了数以万计的民众伤亡，在危难的关头有十四位勇士站了出来，他们牺牲了自己保护了梦罗克，死后的他们留下了自己的武器，这些武器被梦罗克的人们当做信仰的象征，这对拳套便是十四把武器的复制品之一。',LoadShowSize=2.2,LoadShowRotate=250,LoadShowPose={-0.3,0.44,0},}",
  [62538] = "{id=62538,NameZh='亡灵拳套',Icon='item_62538',Type=290,MaxNum=99,SellPrice=2100,AdventureValue=1,Condition=8,Desc='“这一拳下去，我可以把你的灵魂都打出窍”——狂妄的武僧',Level=95,LoadShowSize=2,LoadShowRotate=250,LoadShowPose={-0.1,0.42,0},}",
  [62539] = "{id=62539,NameZh='埃琉德尼尔之握',Icon='item_62539',Type=290,MaxNum=99,SellPrice=100,AdventureSort=100012,AdventureValue=1,Condition=8,Desc='你以为你手中握住了一个拳套，其实你握住的是未来与希望。',TFValidDate='2019-10-28 05:00:00',ValidDate='2019-10-31 05:00:00',LoadShowSize=2.4,LoadShowRotate=250,LoadShowPose={0,0.44,0},}",
