  [62541] = "{id=62541,NameZh='霸王乱舞★[1]',Icon='item_62541',Type=290,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='寄宿着古老英魂的拳套，戴上它之后，每一招都变得更加迅猛有力，攻击缭乱如舞让敌人无从招架。“我要打十个。”——某位武术宗师',Feature=1,LoadShowSize=2.6,LoadShowRotate=250,LoadShowPose={-0.3,0.44,0},}",
  [62542] = "{id=62542,NameZh='巨灵拳套★[1]',Icon='item_62542',Type=290,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='附着了巨灵魔力的拳套，挥舞时会形成巨大的气流，让敌人闻风丧胆。',LoadShowSize=2.6,LoadShowRotate=250,LoadShowPose={-0.2,0.44,0},}",
  [62543] = "{id=62543,NameZh='生命体拳套',Icon='item_62543',Type=290,MaxNum=99,SellPrice=2400,Desc='雷根贝勒公司所开发的，以生命体为能量的拳套。可以击打出威力巨大的拳击。',Level=100,}",
  [62544] = "{id=62544,NameZh='魔器·菲尼克斯',Icon='item_62544',Type=290,MaxNum=99,SellPrice=100,AdventureSort=100011,AdventureValue=1,Condition=8,Desc='梦罗克碎片打造的禁忌武器，对应着异世界恶魔No.37·菲尼克斯，俗称不死鸟，叫声似孩童，拥有无穷的生命力。',LoadShowSize=2.6,LoadShowRotate=250,LoadShowPose={0,0.44,0},}",
  [62545] = "{id=62545,NameZh='驱动拳套',Icon='item_62545',Type=290,MaxNum=99,SellPrice=100,AdventureSort=100013,AdventureValue=1,Condition=8,Desc='我能保证，它自带的动力核心能让你的每一拳都发出强大的冲击。',Feature=1,LoadShowSize=2.6,LoadShowRotate=250,LoadShowPose={0,0.44,0},}",
  [62546] = "{id=62546,NameZh='碎牙[1]',Icon='item_62546',Type=290,Quality=4,MaxNum=99,SellPrice=100,Desc='我不是故意打碎你的门牙的！戴上这个拳套以后，我怎么就管不住我这破手呢？',}",
  [62547] = "{id=62547,NameZh='科学救赎·拳套',Icon='item_62547',Type=290,MaxNum=99,SellPrice=100,AdventureSort=100014,AdventureValue=1,Condition=8,Desc='科学！科学！科学！为了科学一切的牺牲都是值得，蝼蚁们的生命本就毫无价值，因实验而死的他们应该觉得骄傲，这是他们的宿命！快了！就快了，只要这副拳刃制作出来，这片大陆就再也没有人敢反抗我了！',Feature=1,}",
  [62549] = "{id=62549,NameZh='圣息崇聆·拳套',Icon='item_62549',Type=290,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='光与天空，圣洁的飞鸟，神的双翼已然张开，吾虔诚的信徒，愿你在吾的庇佑下体验幸福与美好，你的灵魂之音，吾等已经听到，这副拳套赐予你，神祇永远与你同在。',}",
  [62550] = "{id=62550,NameZh='辉光十字·拳套',Icon='item_62550',Type=290,MaxNum=99,SellPrice=2600,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='这副拳套出自阿卢纳贝兹教国最有名的工匠——索罗克之手，他搜寻了整个教国寻找制作武器的材料，最终在圣域神殿的地下深处寻到了结果，吸取神灵信仰的矿石坚硬无比，制成的武器更是消灭黑暗的破晓之力。',Level=110,}",
  [62551] = "{id=62551,NameZh='龙爪拳套★[1]',Icon='item_62551',Type=290,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='除了有出色的拳击伤害，也可以抓伤和砍杀敌人，武器大师铜丁的杰作。',Feature=1,LoadShowSize=3,LoadShowRotate=250,LoadShowPose={-0.2,0.44,0},}",
  [62552] = "{id=62552,NameZh='蔷薇灵语拳套',Icon='item_62552',Type=290,MaxNum=99,SellPrice=3200,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='这副拳套被妖精一族的“灵语师”赋予了蔷薇的祝福。佩戴它采摘蔷薇永远不会被花刺所伤。',Level=110,LoadShowRotate=-90,}",
  [62553] = "{id=62553,NameZh='红鱼花铃·拳套',Icon='item_62553',Type=290,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='长了一身红色鳞片的金鱼呀，喜欢在湖底的水草里悠闲地打瞌睡。有人投食的话，也会慢悠悠地钻到水面上，不紧不慢地吃鱼食。如果它会衔着拳套游出水面，也不要惊讶，这是金鱼族的报答哟~',LoadShowSize=2.4,LoadShowRotate=70,LoadShowPose={0.3,0.4,0},}",
  [62554] = "{id=62554,NameZh='湛蓝天光·拳套',Icon='item_62554',Type=290,MaxNum=99,SellPrice=2800,AdventureValue=1,Condition=8,Desc='阔大的云海之上透出湛蓝天光，晴空下的战士们振作起了精神。戴上这副拳套吧，它印证着你的忠诚，勇敢与希望。',Level=110,LoadShowSize=2.5,LoadShowRotate=-120,LoadShowPose={-0.2,0.4,0},}",
  [62555] = "{id=62555,NameZh='天虹圣遗·拳套',Icon='item_62555',Type=290,MaxNum=99,SellPrice=100,AdventureSort=100019,AdventureValue=1,Condition=8,Desc='使用彩虹桥碎片镶嵌的拳套，可能拥有异常强大的力量。“警告：佩戴时请不要打响指！”',LoadShowPose={0,0.3,0},}",
  [62556] = "{id=62556,NameZh='月下祈者·拳套',Icon='item_62556',Type=290,MaxNum=99,SellPrice=100,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='冰封千年的陨铁，王国的工匠们用尽办法也无法将其熔铸，却因小学徒的一次失误暴露在月光下。那一刻奇迹发生，陨铁融化宛若水银般流转，在月光下散发耀眼星辉。\n此乃月光赐福之拳套，执掌者当以月光之力，扫清障壁，重击邪恶！',LoadShowRotate=270,LoadShowPose={-0.4,0.4,0.2},}",
  [62557] = "{id=62557,NameZh='英灵起点·拳套[2]',Icon='item_62557',Type=290,Quality=2,MaxNum=99,SellPrice=100,Desc='克里图拉新生领到的初心武器，致敬英灵而铸上蓝金涂装。据说设计者是个追求拳击不倒不破奥秘的修罗达人。',NoStorage=5,LoadShowPose={0,0.3,0},}",
  [62558] = "{id=62558,NameZh='英灵信标·拳套[2]',Icon='item_62558',Type=290,Quality=3,MaxNum=99,SellPrice=100,Desc='这件拳套是指引女武神降临、迎接英灵的道标。阵亡的勇士穿着它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,LoadShowPose={0,0.3,0},}",
  [62559] = "{id=62559,NameZh='英灵羽证·拳套[2]',Icon='item_62559',Type=290,Quality=3,MaxNum=99,SellPrice=100,Desc='英灵的证明。潜入学院的女武神在拳套中注入了奥丁领域的魔力。上勾拳、下勾拳、升龙……它就像在海面上钻孔的鲣鸟。',NoStorage=5,LoadShowPose={0,0.3,0},}",
  [62561] = "{id=62561,NameZh='远古回音·拳套',Icon='item_62561',Type=290,MaxNum=99,SellPrice=3200,AdventureSort=100020,AdventureValue=1,Condition=8,Desc='铭刻着神秘纹样的拳套，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,LoadShowPose={0,0.3,0},}",
  [62563] = "{id=62563,NameZh='王国荣辉·拳套',Icon='item_62563',Type=290,MaxNum=99,SellPrice=100,AdventureSort=100023,AdventureValue=1,Condition=8,Desc='效忠于王室的宫廷侍卫所持的拳套，其上有卢恩王家纹章。虽然杀伤不高，但十分舒适华美，适合牵起美丽少女的手。',LoadShowRotate=-90,}",
  [62567] = "{id=62567,NameZh='湮灭者·极限',Icon='item_62567',Type=458,Quality=4,MaxNum=1,SellPrice=100,Desc='传说风之精灵迦楼罗了解大气魔法的真理，他铸造的这双拳套，轻轻一拳就能掀起狂风，若是连续出拳，方圆百尺都会被爆裂的飓风夷为平地。',NoSale=1,NoStorage=7,TFValidDate='2022-03-10 05:00:00',ValidDate='2022-03-23 05:00:00',}",
  [62568] = "{id=62568,NameZh='英灵信标·拳套[2]',Icon='item_62558',Type=290,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=100024,AdventureValue=1,Condition=8,Desc='这件拳套是指引女武神降临、迎接英灵的道标。阵亡的勇士穿着它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,LoadShowPose={0,0.3,0},}",
  [62569] = "{id=62569,NameZh='英灵羽证·拳套[2]',Icon='item_62559',Type=290,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=100025,AdventureValue=1,Condition=8,Desc='英灵的证明。潜入学院的女武神在拳套中注入了奥丁领域的魔力。上勾拳、下勾拳、升龙……它就像在海面上钻孔的鲣鸟。',NoStorage=5,LoadShowPose={0,0.3,0},}",
  [62570] = "{id=62570,NameZh='荣耀之拳[1]',Icon='item_62570',Type=290,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='荣耀的拳套，让拥有者变得强大，去对抗世界上的邪恶。',Feature=1,}",
