  [62572] = "{id=62572,NameZh='电光之拳[1]',Icon='item_62572',Type=230,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9000,AdventureValue=1,Condition=8,Desc='历经无数试炼获得的电光之拳，让电气之力撕破拂晓前的黑暗，迎接光辉与黎明。',Feature=1,}",
