  [62801] = "{id=62801,NameZh='普通鞭子',Icon='item_62801',Type=270,MaxNum=99,SellPrice=560,Desc='你没看到它的名字吗？它就是一条普通鞭子而已。',Level=40,}",
  [62802] = "{id=62802,NameZh='守备军鞭子',Icon='item_62802',Type=270,MaxNum=99,SellPrice=100,Level=100,}",
  [62803] = "{id=62803,NameZh='拂晓之光',Icon='item_62803',Type=460,Quality=4,MaxNum=1,SellPrice=100,Desc='精灵族长老使用绝密的仪式从天空中摘取拂晓最明亮的星，将星星的力量封印在精灵特制的容器里，当挥舞容器时，晨星发出的光芒会像丝带一样扭动，并击碎碰到的一切事物。在圣战之中精灵长老曾用这光鞭击碎魔物的黑暗封印，为精灵族带来黎明，所以精灵族将这光鞭称为拂晓之光。',NoSale=1,NoStorage=7,}",
  [62804] = "{id=62804,NameZh='拂晓之光·精锻',Icon='item_62804',Type=460,Quality=4,MaxNum=1,SellPrice=100,Desc='精灵族长老使用绝密的仪式从天空中摘取拂晓最明亮的星，将星星的力量封印在精灵特制的容器里，当挥舞容器时，晨星发出的光芒会像丝带一样扭动，并击碎碰到的一切事物。在圣战之中精灵长老曾用这光鞭击碎魔物的黑暗封印，为精灵族带来黎明，所以精灵族将这光鞭称为拂晓之光。',NoSale=1,NoStorage=7,}",
  [62805] = "{id=62805,NameZh='拂晓之光·神铸',Icon='item_62805',Type=460,Quality=4,MaxNum=1,SellPrice=100,Desc='精灵族长老使用绝密的仪式从天空中摘取拂晓最明亮的星，将星星的力量封印在精灵特制的容器里，当挥舞容器时，晨星发出的光芒会像丝带一样扭动，并击碎碰到的一切事物。在圣战之中精灵长老曾用这光鞭击碎魔物的黑暗封印，为精灵族带来黎明，所以精灵族将这光鞭称为拂晓之光。',NoSale=1,NoStorage=7,}",
