  [62819] = "{id=62819,NameZh='毒鞭 蔷薇[1]',Icon='item_62819',Type=270,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=30000,AdventureSort=6600,AdventureValue=1,Condition=8,Desc='用蔷薇的梗制作而成的鞭子,中间有许多小刺。',LoadShowRotate=90,LoadShowPose={0,0,-0.5},}",
  [62820] = "{id=62820,NameZh='秘鞭 眷恋[1]',Icon='item_62820',Type=270,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=6600,AdventureValue=1,Condition=8,Desc='“我心甘情愿被它缠绕，鞭挞，只因心中对你的眷恋与缱绻。”——恋上艾斯恩魔女的男子',Feature=1,LoadShowSize=2.2,LoadShowRotate=250,LoadShowPose={0.3,0.4,0},}",
  [62821] = "{id=62821,NameZh='英灵·荷瑞丝特之风灵鞭',Icon='item_62821',Type=270,MaxNum=99,SellPrice=100,AdventureSort=100006,AdventureValue=1,Condition=8,Desc='激励之神荷瑞丝特的鞭子，柔软但充满力量。挥舞它时，耳畔会响起风的歌声。',Feature=1,LoadShowSize=2,LoadShowRotate=250,LoadShowPose={0,0.25,0},}",
  [62822] = "{id=62822,NameZh='炎魂·淬火之吻',Icon='item_62822',Type=270,MaxNum=99,SellPrice=100,AdventureSort=100010,AdventureValue=1,Condition=8,Desc='她会在你的敌人身上留下难以磨灭的灼热吻痕。',LoadShowSize=2.2,LoadShowRotate=250,LoadShowPose={0.3,0.4,0},}",
  [62823] = "{id=62823,NameZh='碎雪·晶棱锁链',Icon='item_62823',Type=270,MaxNum=99,SellPrice=100,AdventureSort=100009,AdventureValue=1,Condition=8,Desc='附着极寒气息的鞭子，它接触到的一切都会长出尖锐的冰凌。',LoadShowSize=2.2,LoadShowRotate=250,LoadShowPose={0.3,0.4,0},}",
  [62824] = "{id=62824,NameZh='月辉·月华之触',Icon='item_62824',Type=270,MaxNum=99,SellPrice=100,AdventureSort=100008,AdventureValue=1,Condition=8,Desc='她的触感就像温柔的月光，将你的敌人绞杀在温柔乡。',LoadShowSize=2,LoadShowRotate=250,LoadShowPose={0.3,0.32,0},}",
  [62825] = "{id=62825,NameZh='日耀·日冕光鞭',Icon='item_62825',Type=270,MaxNum=99,SellPrice=100,AdventureSort=100007,AdventureValue=1,Condition=8,Desc='如同日冕的般闪耀的光晕，灼烧黑暗，孕育光明。',LoadShowSize=2,LoadShowRotate=250,LoadShowPose={0.3,0.32,0},}",
  [62826] = "{id=62826,NameZh='星界·束星锁链',Icon='item_62826',Type=270,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=100002,AdventureValue=1,Condition=8,Desc='古老的过去，诸神用它来从群星中连接出一个个星座。',LoadShowSize=2.2,LoadShowRotate=250,LoadShowPose={0.3,0.4,0},}",
  [62827] = "{id=62827,NameZh='红星界鞭子',Icon='item_62827',Type=270,MaxNum=99,SellPrice=100,}",
  [62828] = "{id=62828,NameZh='魔女之鞭',Icon='item_62828',Type=270,MaxNum=99,SellPrice=100,AdventureSort=100001,AdventureValue=1,Condition=8,Desc='据说是艾斯恩魔女使用过的鞭子，握住它就会变成施虐狂的性格。',Feature=1,LoadShowSize=2.2,LoadShowRotate=250,LoadShowPose={0.3,0.4,0},}",
  [62829] = "{id=62829,NameZh='衔尾者之鞭',Icon='item_62829',Type=270,MaxNum=99,SellPrice=100,AdventureSort=100004,AdventureValue=1,Condition=8,Desc='使用耶梦加得蜕下的蛇皮做成的鞭子，力量之强足以扼杀梦境。',Feature=1,LoadShowSize=2.2,LoadShowRotate=250,LoadShowPose={0.3,0.4,0},}",
  [62830] = "{id=62830,NameZh='信仰之鞭',Icon='item_62830',Type=270,MaxNum=99,SellPrice=100,AdventureSort=100005,AdventureValue=1,Condition=8,Desc='巴风特曾带领手下对梦罗克进行过一次史无前例的大侵袭，这次的战争造成了数以万计的民众伤亡，在危难的关头有十四位勇士站了出来，他们牺牲了自己保护了梦罗克，死后的他们留下了自己的武器，这些武器被梦罗克的人们当做信仰的象征，这条长鞭便是十四把武器之一。',LoadShowSize=2.2,LoadShowRotate=250,LoadShowPose={0.3,0.4,0},}",
  [62831] = "{id=62831,NameZh='枫忆之鞭',Icon='item_62831',Type=270,MaxNum=99,SellPrice=100,AdventureSort=100003,AdventureValue=1,Condition=8,Desc='贝尔质问父亲为什么别的女孩子在玩着洋娃娃，而她却要听从父亲每天练习着鞭子，父亲把贝尔的鞭子做成了枫叶的样式摸了摸她的头，“现在鞭子可爱了吧，告诉他们，你是可爱而且强大的女孩子。”那时的贝尔还不懂其中的含义，如今战场上的贝尔看着枫叶鞭思绪良久…',LoadShowSize=2.2,LoadShowRotate=250,LoadShowPose={0.3,0.4,0},}",
  [62832] = "{id=62832,NameZh='亡灵鞭子',Icon='item_62832',Type=270,MaxNum=99,SellPrice=2100,AdventureValue=1,Condition=8,Desc='扬起，抽落，鞭挞着灵魂。这条鞭子代表着审判与责难。',Level=95,LoadShowSize=2,LoadShowRotate=250,LoadShowPose={0.3,0.35,0},}",
  [62833] = "{id=62833,NameZh='埃琉德尼尔悔罪鞭',Icon='item_62833',Type=270,MaxNum=99,SellPrice=100,AdventureSort=100012,AdventureValue=1,Condition=8,Desc='尼夫海姆法令第三章第六条：在万圣夜没有捣蛋也没有要到糖的人，要接受悔罪鞭的惩罚。',TFValidDate='2019-10-28 05:00:00',ValidDate='2019-10-31 05:00:00',LoadShowSize=2,LoadShowRotate=250,LoadShowPose={0.3,0.32,0},}",
  [62834] = "{id=62834,NameZh='圣灵·荷瑞丝特之舞踏鞭',Icon='item_62834',Type=270,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='激励神——荷瑞丝特的鞭，被这鞭子抽打的人会感到剧烈的疼痛，但只要坚持过去，内心就会迸发强烈的热情。',LoadShowSize=2.2,LoadShowRotate=250,LoadShowPose={0.3,0.4,0},}",
  [62835] = "{id=62835,NameZh='圣徒鞭子[1]',Icon='item_62835',Type=270,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='它会给予不洁者鞭挞，给予圣洁者拥抱。当你挥舞它时，能感受到某个意志的祝福。',LoadShowSize=2.2,LoadShowRotate=250,LoadShowPose={0.3,0.4,0},}",
  [62836] = "{id=62836,NameZh='生命体长鞭',Icon='item_62836',Type=270,MaxNum=99,SellPrice=2400,Desc='雷根贝勒公司所开发的，以生命体为能量的长鞭。每次抽打都可以摧毁敌人的身体组织。',Level=100,}",
  [62837] = "{id=62837,NameZh='魔器·布松',Icon='item_62837',Type=270,MaxNum=99,SellPrice=100,AdventureSort=100011,AdventureValue=1,Condition=8,Desc='梦罗克碎片打造的禁忌武器，对应着异世界恶魔No.20·布松，手持毒蛇，驾驭着暴戾的战熊。',LoadShowSize=2,LoadShowRotate=250,LoadShowPose={0.3,0.32,0},}",
  [62838] = "{id=62838,NameZh='原罪之鞭',Icon='item_62838',Type=270,MaxNum=99,SellPrice=100,AdventureSort=100013,AdventureValue=1,Condition=8,Desc='它的诞生，是为了鞭挞那些携带原罪之人。',Feature=1,LoadShowSize=2.2,LoadShowRotate=250,LoadShowPose={0.3,0.4,0},}",
  [62839] = "{id=62839,NameZh='荆棘蔷薇[1]',Icon='item_62839',Type=270,MaxNum=99,SellPrice=100,Desc='越是漂亮的东西越是危险，呐…你觉得我漂亮吗？',}",
  [62840] = "{id=62840,NameZh='流星鞭子★[1]',Icon='item_62840',Type=270,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=6600,AdventureValue=1,Condition=8,Desc='不要再对着它许愿了，它只是条好看的鞭子罢了。',LoadShowSize=2.2,LoadShowRotate=250,LoadShowPose={0.3,0.4,0},}",
  [62841] = "{id=62841,NameZh='科学救赎·鞭子',Icon='item_62841',Type=270,MaxNum=99,SellPrice=100,AdventureSort=100014,AdventureValue=1,Condition=8,Desc='科学！科学！科学！为了科学一切的牺牲都是值得，蝼蚁们的生命本就毫无价值，因实验而死的他们应该觉得骄傲，这是他们的宿命！快了！就快了，那些人都等着成为我鞭下的亡魂吧……嘻嘻……',Feature=1,}",
  [62842] = "{id=62842,NameZh='圣息崇聆·鞭',Icon='item_62842',Type=270,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='光与天空，圣洁的飞鸟，神的双翼已然张开，吾虔诚的信徒，愿你在吾的庇佑下体验幸福与美好，你的灵魂之音，吾等已经听到，这根圣鞭赐予你，神祇永远与你同在。',}",
  [62843] = "{id=62843,NameZh='辉光十字·鞭',Icon='item_62843',Type=270,MaxNum=99,SellPrice=2600,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='这根长鞭出自阿卢纳贝兹教国最有名的工匠——索罗克之手，他搜寻了整个教国寻找制作武器的材料，最终在圣域神殿的地下深处寻到了结果，吸取神灵信仰的矿石坚硬无比，制成的武器更是消灭黑暗的破晓之力。',Level=110,}",
  [62844] = "{id=62844,NameZh='秘鞭 眷恋★[1]',Icon='item_62844',Type=270,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=6600,AdventureValue=1,Condition=8,Desc='“我心甘情愿被它缠绕，鞭挞，只因心中对你的眷恋与缱绻。”——恋上艾斯恩魔女的男子',Feature=1,LoadShowSize=2.2,LoadShowRotate=250,LoadShowPose={0.3,0.4,0},}",
  [62845] = "{id=62845,NameZh='蔷薇灵语之鞭',Icon='item_62845',Type=270,MaxNum=99,SellPrice=3200,AdventureSort=6600,AdventureValue=1,Condition=8,Desc='这条鞭子被妖精一族的“灵语师”赋予了蔷薇的祝福，拥有着与植物沟通的能力。挥动时周围的植物会竞相起舞。',Level=110,LoadShowPose={0,0.25,0},}",
  [62846] = "{id=62846,NameZh='红鱼花铃·鞭',Icon='item_62846',Type=270,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='长了一身红色鳞片的金鱼呀，喜欢在湖底的水草里悠闲地打瞌睡。有人投食的话，也会慢悠悠地钻到水面上，不紧不慢地吃鱼食。如果它会衔着鞭游出水面，也不要惊讶，这是金鱼族的报答哟~',LoadShowSize=2.2,LoadShowRotate=250,LoadShowPose={0.3,0.4,0},}",
  [62847] = "{id=62847,NameZh='湛蓝天光·鞭',Icon='item_62847',Type=270,MaxNum=99,SellPrice=2800,AdventureValue=1,Condition=8,Desc='阔大的云海之上透出湛蓝天光，晴空下的战士们振作起了精神。战斗的号角即将吹响，握紧这柄长鞭吧，它印证着你的忠诚，勇敢与希望。',Level=110,LoadShowSize=1.6,LoadShowRotate=250,LoadShowPose={0.2,0.2,0},}",
  [62848] = "{id=62848,NameZh='天虹圣遗·鞭子',Icon='item_62848',Type=270,MaxNum=99,SellPrice=100,AdventureSort=100019,AdventureValue=1,Condition=8,Desc='浮空精灵收集彩虹桥碎片制作的长鞭，舞动时的虹光会令舞姿更显曼妙，是每一位舞者梦寐以求的武器。',}",
  [62849] = "{id=62849,NameZh='月下祈者·鞭',Icon='item_62849',Type=270,MaxNum=99,SellPrice=100,AdventureSort=6600,AdventureValue=1,Condition=8,Desc='冰封千年的陨铁，王国的工匠们用尽办法也无法将其熔铸，却因小学徒的一次失误暴露在月光下。那一刻奇迹发生，陨铁融化宛若水银般流转，在月光下散发耀眼星辉。\n此乃月光赐福之神鞭，持鞭者当以月光之力，保护弱者，鞭笞不公！',LoadShowRotate=90,LoadShowPose={0,0.1,0},}",
  [62850] = "{id=62850,NameZh='英灵起点·鞭[2]',Icon='item_62850',Type=270,Quality=2,MaxNum=99,SellPrice=100,Desc='克里图拉新生领到的初心武器，致敬英灵而铸上蓝金涂装。据说设计者是个宠物训练课的老师。在领到第一只可爱的波利前，先学会管教自己，老师挥舞着鞭子说。',NoStorage=5,}",
  [62851] = "{id=62851,NameZh='英灵信标·鞭[2]',Icon='item_62851',Type=270,Quality=3,MaxNum=99,SellPrice=100,Desc='这条鞭是指引女武神降临、迎接英灵的道标。阵亡的勇士抱着它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,}",
  [62852] = "{id=62852,NameZh='英灵羽证·鞭[2]',Icon='item_62852',Type=270,Quality=3,MaxNum=99,SellPrice=100,Desc='英灵的证明。潜入学院的女武神在这把刃鞭注入了奥丁领域的魔力。鞭子长出了羽翼，使它像土元素里也能盎然乱舞的羽蛇。',NoStorage=5,}",
  [62854] = "{id=62854,NameZh='远古回音·鞭',Icon='item_62854',Type=270,MaxNum=99,SellPrice=3200,AdventureSort=100020,AdventureValue=1,Condition=8,Desc='铭刻着神秘纹样的鞭子，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,}",
  [62856] = "{id=62856,NameZh='王国荣辉·鞭',Icon='item_62856',Type=270,MaxNum=99,SellPrice=100,AdventureSort=100023,AdventureValue=1,Condition=8,Desc='效忠于王室的宫廷侍卫所持的鞭子，其上绘有卢恩王家纹章。可惜，它挥打在目标上的破坏力，并不如它的外观一般令人满意。',}",
  [62860] = "{id=62860,NameZh='拂晓之光·极限',Icon='item_62860',Type=460,Quality=4,MaxNum=1,SellPrice=100,Desc='精灵族长老使用绝密的仪式从天空中摘取拂晓最明亮的星，将星星的力量封印在精灵特制的容器里，当挥舞容器时，晨星发出的光芒会像丝带一样扭动，并击碎碰到的一切事物。在圣战之中精灵长老曾用这光鞭击碎魔物的黑暗封印，为精灵族带来黎明，所以精灵族将这光鞭称为拂晓之光。',NoSale=1,NoStorage=7,TFValidDate='2022-03-10 05:00:00',ValidDate='2022-03-23 05:00:00',}",
  [62861] = "{id=62861,NameZh='英灵信标·鞭[2]',Icon='item_62851',Type=270,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=100024,AdventureValue=1,Condition=8,Desc='这条鞭是指引女武神降临、迎接英灵的道标。阵亡的勇士抱着它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,}",
  [62862] = "{id=62862,NameZh='英灵羽证·鞭[2]',Icon='item_62852',Type=270,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=100025,AdventureValue=1,Condition=8,Desc='英灵的证明。潜入学院的女武神在这把刃鞭注入了奥丁领域的魔力。鞭子长出了羽翼，使它像土元素里也能盎然乱舞的羽蛇。',NoStorage=5,}",
  [63101] = "{id=63101,NameZh='新手练习琴',Icon='item_63101',Type=260,MaxNum=99,SellPrice=560,Desc='每个传奇诗人的第一把琴，都是新手练习琴。',Level=40,}",
  [63102] = "{id=63102,NameZh='守备军琴',Icon='item_63102',Type=260,MaxNum=99,SellPrice=100,Level=100,}",
  [63103] = "{id=63103,NameZh='月神的呢喃',Icon='item_63103',Type=459,Quality=4,MaxNum=1,SellPrice=100,Desc='千年前，每到月圆之日，月神曼尼会驾车从夜空中走过并观察睡梦中的人类，当他看见正在噩梦中的人类，他会为梦中之人弹琴，温柔琴音带来心灵的慰藉，而这柄琴也被当时的人类尊称为月神的呢喃。',NoSale=1,NoStorage=7,}",
  [63104] = "{id=63104,NameZh='月神的呢喃·精锻',Icon='item_63104',Type=459,Quality=4,MaxNum=1,SellPrice=100,Desc='千年前，每到月圆之日，月神曼尼会驾车从夜空中走过并观察睡梦中的人类，当他看见正在噩梦中的人类，他会为梦中之人弹琴，温柔琴音带来心灵的慰藉，而这柄琴也被当时的人类尊称为月神的呢喃。',NoSale=1,NoStorage=7,}",
  [63105] = "{id=63105,NameZh='月神的呢喃·神铸',Icon='item_63105',Type=459,Quality=4,MaxNum=1,SellPrice=100,Desc='千年前，每到月圆之日，月神曼尼会驾车从夜空中走过并观察睡梦中的人类，当他看见正在噩梦中的人类，他会为梦中之人弹琴，温柔琴音带来心灵的慰藉，而这柄琴也被当时的人类尊称为月神的呢喃。',NoSale=1,NoStorage=7,}",
  [63106] = "{id=63106,NameZh='小提琴',Icon='item_63106',Type=260,MaxNum=99,SellPrice=100,}",
  [63107] = "{id=63107,NameZh='曼陀林',Icon='item_63107',Type=260,MaxNum=99,SellPrice=100,}",
  [63108] = "{id=63108,NameZh='吉他(删除)',Icon='item_63108',Type=260,MaxNum=99,SellPrice=100,}",
  [63109] = "{id=63109,NameZh='贝斯[1]',Icon='item_63109',Type=260,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=6300,AdventureValue=1,Condition=8,Desc='有人说它没有吉他的浪漫，也没有尤克里里的讨喜，但你一旦握住它，你就会被它别具一格的魅力征服！',Feature=1,LoadShowSize=1.5,LoadShowRotate=250,LoadShowPose={0,0.72,0},}",
  [63110] = "{id=63110,NameZh='鲁特琴',Icon='item_63110',Type=260,MaxNum=99,SellPrice=100,}",
