  [63113] = "{id=63113,NameZh='琵琶[1]',Icon='item_63113',Type=260,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=6300,AdventureValue=1,Condition=8,Desc='来自东方的古老乐器，音色轻柔婉转。',Feature=1,LoadShowSize=1.5,LoadShowRotate=250,LoadShowPose={0,0.64,0},}",
  [63114] = "{id=63114,NameZh='大地吉他',Icon='item_63114',Type=260,MaxNum=99,SellPrice=100,}",
