  [63118] = "{id=63118,NameZh='冬不拉',Icon='item_63118',Type=260,MaxNum=99,SellPrice=100,}",
  [63119] = "{id=63119,NameZh='电吉他',Icon='item_63119',Type=260,MaxNum=99,SellPrice=100,}",
  [63120] = "{id=63120,NameZh='西塔琴',Icon='item_63120',Type=260,MaxNum=99,SellPrice=100,}",
  [63121] = "{id=63121,NameZh='炎魂·音魂狂热',Icon='item_63121',Type=260,MaxNum=99,SellPrice=100,AdventureSort=100010,AdventureValue=1,Condition=8,Desc='让现场的气氛再热烈一些！让你的敌人在火焰中哀嚎！',LoadShowSize=1.5,LoadShowRotate=250,LoadShowPose={0,0.64,0},}",
  [63122] = "{id=63122,NameZh='碎雪·凛冬颂歌',Icon='item_63122',Type=260,MaxNum=99,SellPrice=100,AdventureSort=100009,AdventureValue=1,Condition=8,Desc='为了在寒冬中弹奏而特制的魔法乐器，它的弦永远不会冻上。“即使万物冰封，我对你的爱仍炽热如火。”——《夜莺诗集》',LoadShowSize=1.5,LoadShowRotate=250,LoadShowPose={0,0.64,0},}",
  [63123] = "{id=63123,NameZh='月辉·月下奏者',Icon='item_63123',Type=260,MaxNum=99,SellPrice=100,AdventureSort=100008,AdventureValue=1,Condition=8,Desc='一琴，一酒，一地月光；独奏，独饮，独自神伤。',LoadShowSize=1.4,LoadShowRotate=250,LoadShowPose={0,0.55,0},}",
  [63124] = "{id=63124,NameZh='日耀·圣耀之琴',Icon='item_63124',Type=260,MaxNum=99,SellPrice=100,AdventureSort=100007,AdventureValue=1,Condition=8,Desc='当你听见用它弹出的乐曲，你便会明白音乐之神是真的存在的。',LoadShowSize=1.4,LoadShowRotate=250,LoadShowPose={0,0.55,0},}",
  [63125] = "{id=63125,NameZh='星界·宙宇歌者',Icon='item_63125',Type=260,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=100002,AdventureValue=1,Condition=8,Desc='只有它才能将星辰之美化作曲调弹奏。',LoadShowSize=1.4,LoadShowRotate=250,LoadShowPose={0,0.55,0},}",
  [63126] = "{id=63126,NameZh='红星界琴',Icon='item_63126',Type=260,MaxNum=99,SellPrice=100,}",
  [63127] = "{id=63127,NameZh='噩梦音符',Icon='item_63127',Type=260,MaxNum=99,SellPrice=100,AdventureSort=100001,AdventureValue=1,Condition=8,Desc='拿住它就止不住的想要眼走，直到死去。',Feature=1,LoadShowSize=1.4,LoadShowRotate=250,LoadShowPose={0,0.55,0},}",
  [63128] = "{id=63128,NameZh='衔尾者之琴',Icon='item_63128',Type=260,MaxNum=99,SellPrice=100,AdventureSort=100004,AdventureValue=1,Condition=8,Desc='弹奏它的时候，你的猎物会想被蛇的目光瞪住一样，无法动弹。',Feature=1,LoadShowSize=1.5,LoadShowRotate=250,LoadShowPose={0,0.72,0},}",
  [63129] = "{id=63129,NameZh='英灵·格蕾之颂歌',Icon='item_63129',Type=260,MaxNum=99,SellPrice=100,AdventureSort=100006,AdventureValue=1,Condition=8,Desc='格蕾在白昼时演奏的鲁特琴，只有最纯洁的心灵能听到它的吟唱。',Feature=1,LoadShowSize=1.4,LoadShowRotate=250,LoadShowPose={0,0.55,0},}",
  [63130] = "{id=63130,NameZh='信仰之琴',Icon='item_63130',Type=260,MaxNum=99,SellPrice=100,AdventureSort=100005,AdventureValue=1,Condition=8,Desc='巴风特曾带领手下对梦罗克进行过一次史无前例的大侵袭，这次的战争造成了数以万计的民众伤亡，在危难的关头有十四位勇士站了出来，他们牺牲了自己保护了梦罗克，死后的他们留下了自己的武器，这些武器被梦罗克的人们当做信仰的象征，这把琴便是十四把武器之一。',LoadShowSize=1.4,LoadShowRotate=250,LoadShowPose={0,0.55,0},}",
  [63131] = "{id=63131,NameZh='枫忆之琴',Icon='item_63131',Type=260,MaxNum=99,SellPrice=100,AdventureSort=100003,AdventureValue=1,Condition=8,Desc='有一个古老的传说，每到月圆之夜枫叶树下都会有一位魔女弹奏着悦耳的琴声，过往的男子听后都会驻足为这琴声沉沦，最终成为这位魔女的盘中餐，“不是这样的，她不是魔女而是…我的爱人…”青年在枫树下抚摸着琴弦如是说',LoadShowSize=1.5,LoadShowRotate=250,LoadShowPose={0,0.64,0},}",
  [63132] = "{id=63132,NameZh='亡灵琴',Icon='item_63132',Type=260,MaxNum=99,SellPrice=2100,AdventureValue=1,Condition=8,Desc='散发着哀伤气息的琴，只要拨弄琴弦，似乎能听见某人幽怨的哭泣。',Level=95,LoadShowSize=1.5,LoadShowRotate=250,LoadShowPose={0,0.64,0},}",
  [63133] = "{id=63133,NameZh='埃琉德尼尔欢愉琴',Icon='item_63133',Type=260,MaxNum=99,SellPrice=100,AdventureSort=100012,AdventureValue=1,Condition=8,Desc='死者之都的生活是苦寂、无聊的...才怪啦！电音！重金属！欢迎来到真正的地狱！',TFValidDate='2019-10-28 05:00:00',ValidDate='2019-10-31 05:00:00',LoadShowSize=1.4,LoadShowRotate=250,LoadShowPose={0,0.55,0},}",
  [63134] = "{id=63134,NameZh='圣灵·格蕾之不休琴',Icon='item_63134',Type=260,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='格蕾的鲁特琴，即使没有演奏者，这把琴也会在每天的凌晨和正午自己演奏出高亢的音乐。',LoadShowSize=1.5,LoadShowRotate=250,LoadShowPose={0,0.64,0},}",
  [63135] = "{id=63135,NameZh='圣徒之琴[1]',Icon='item_63135',Type=260,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='虔诚的信徒拨弄琴时，圣歌便会在心中悠远的回响，让人感到心神宁静。',LoadShowSize=1.4,LoadShowRotate=250,LoadShowPose={0,0.55,0},}",
  [63136] = "{id=63136,NameZh='生命体贝斯',Icon='item_63136',Type=260,MaxNum=99,SellPrice=2400,Desc='雷根贝勒公司所开发的，以生命体为能量的贝斯。据说用它弹奏出的声色，是生化聚合体的悲鸣组成的。',Level=100,}",
  [63137] = "{id=63137,NameZh='魔器·安洛先',Icon='item_63137',Type=260,MaxNum=99,SellPrice=100,AdventureSort=100011,AdventureValue=1,Condition=8,Desc='梦罗克碎片打造的禁忌武器，对应着异世界恶魔No.52·安洛先，凡人若直视其眼睛，将会看到自己的死相从而失明。',LoadShowSize=1.4,LoadShowRotate=250,LoadShowPose={0,0.55,0},}",
  [63138] = "{id=63138,NameZh='绝响',Icon='item_63138',Type=260,MaxNum=99,SellPrice=100,AdventureSort=100013,AdventureValue=1,Condition=8,Desc='聆听吧，这缅怀旧世界终焉的绝响，颂唱新世纪的赞歌。',Feature=1,LoadShowSize=1.5,LoadShowRotate=250,LoadShowPose={0,0.64,0},}",
  [63139] = "{id=63139,NameZh='回想者[1]',Icon='item_63139',Type=260,MaxNum=99,SellPrice=100,Desc='当琴声响起，我撩拨你的回忆。',}",
  [63140] = "{id=63140,NameZh='琵琶★[1]',Icon='item_63140',Type=260,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=6300,AdventureValue=1,Condition=8,Desc='来自东方的古老乐器，音色轻柔婉转。',LoadShowSize=1.5,LoadShowRotate=250,LoadShowPose={0,0.64,0},}",
  [63141] = "{id=63141,NameZh='科学救赎·琴',Icon='item_63141',Type=260,MaxNum=99,SellPrice=100,AdventureSort=100014,AdventureValue=1,Condition=8,Desc='科学！科学！科学！为了科学一切的牺牲都是值得，蝼蚁们的生命本就毫无价值，因实验而死的他们应该觉得骄傲，这是他们的宿命！快了！就快了，等这把琴做出来，他们就会知道科学的神奇之处，会臣服于我，把我当成他们的神明！',Feature=1,LoadShowSize=1.5,LoadShowPose={0,0.6,0},}",
  [63142] = "{id=63142,NameZh='圣息崇聆·琴',Icon='item_63142',Type=260,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='光与天空，圣洁的飞鸟，神的双翼已然张开，吾虔诚的信徒，愿你在吾的庇佑下体验幸福与美好，你的灵魂之音，吾等已经听到，这把圣琴赐予你，神祇永远与你同在。',LoadShowSize=1.5,LoadShowRotate=250,LoadShowPose={0,0.5,0},}",
  [63143] = "{id=63143,NameZh='辉光十字·琴',Icon='item_63143',Type=260,MaxNum=99,SellPrice=2600,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='这架圣琴出自阿卢纳贝兹教国最有名的工匠——索罗克之手，他搜寻了整个教国寻找制作武器的材料，最终在圣域神殿的地下深处寻到了结果，吸取神灵信仰的矿石坚硬无比，制成的武器更是消灭黑暗的破晓之力。',Level=110,LoadShowSize=1.5,LoadShowRotate=250,LoadShowPose={0,0.5,0},}",
  [63144] = "{id=63144,NameZh='贝斯★[1]',Icon='item_63144',Type=260,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=6300,AdventureValue=1,Condition=8,Desc='有人说它没有吉他的浪漫，也没有尤克里里的讨喜，但你一旦握住它，你就会被它别具一格的魅力征服！',Feature=1,LoadShowSize=1.5,LoadShowRotate=250,LoadShowPose={0,0.72,0},}",
  [63145] = "{id=63145,NameZh='蔷薇灵语之琴',Icon='item_63145',Type=260,MaxNum=99,SellPrice=3200,AdventureSort=6300,AdventureValue=1,Condition=8,Desc='这把琴被妖精一族的“灵语师”赋予了蔷薇的祝福，拥有着与植物沟通的能力。琴声所至，百花盛放。',Level=110,LoadShowSize=1.5,LoadShowRotate=-90,LoadShowPose={0,0.5,0},}",
  [63146] = "{id=63146,NameZh='红鱼花铃·琴',Icon='item_63146',Type=260,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='长了一身红色鳞片的金鱼呀，喜欢在湖底的水草里悠闲地打瞌睡。有人投食的话，也会慢悠悠地钻到水面上，不紧不慢地吃鱼食。如果它会衔着琴游出水面，也不要惊讶，这是金鱼族的报答哟~',LoadShowSize=1.2,LoadShowRotate=250,LoadShowPose={0,0.6,0},}",
  [63147] = "{id=63147,NameZh='湛蓝天光·琴',Icon='item_63147',Type=260,MaxNum=99,SellPrice=2800,AdventureValue=1,Condition=8,Desc='阔大的云海之上透出湛蓝天光，晴空下的战士们振作起了精神。这张圣琴会演奏出你的忠诚，勇敢与希望。',Level=110,LoadShowSize=1.4,LoadShowRotate=250,LoadShowPose={0,0.5,0},}",
  [63148] = "{id=63148,NameZh='天虹圣遗·琴',Icon='item_63148',Type=260,MaxNum=99,SellPrice=100,AdventureSort=100019,AdventureValue=1,Condition=8,Desc='浮空精灵收集彩虹桥碎片制作的乐器，演奏时自带绚烂的灯光，让你成为全场瞩目的焦点。',LoadShowSize=1.8,LoadShowPose={0,0.4,0},}",
  [63149] = "{id=63149,NameZh='月下祈者·琴',Icon='item_63149',Type=260,MaxNum=99,SellPrice=100,AdventureSort=6300,AdventureValue=1,Condition=8,Desc='冰封千年的陨铁，王国的工匠们用尽办法也无法将其熔铸，却因小学徒的一次失误暴露在月光下。那一刻奇迹发生，陨铁融化宛若水银般流转，在月光下散发耀眼星辉。\n此乃月光赐福之圣琴，演奏者当以月光之力，祛除恐惧，播撒福音！',LoadShowRotate=100,LoadShowPose={0,0.8,-0.8},}",
  [63150] = "{id=63150,NameZh='英灵起点·琴[2]',Icon='item_63150',Type=260,Quality=2,MaxNum=99,SellPrice=100,Desc='克里图拉新生领到的初心武器，致敬英灵而铸上蓝金涂装。由电力供应，媲美指甲刮黑板的音色，对早上犯困的学生很有用，所以它有时被教导主任当上课铃。',NoStorage=5,LoadShowSize=1.5,LoadShowPose={0,0.5,0},}",
  [63151] = "{id=63151,NameZh='英灵信标·琴[2]',Icon='item_63151',Type=260,Quality=3,MaxNum=99,SellPrice=100,Desc='这把琴是指引女武神降临、迎接英灵的道标。阵亡的勇士躺在冥舟里，随送葬人的拨弦，女武神将会一边摇摆，一边把勇士亲自拥入英灵殿。',NoStorage=5,LoadShowSize=1.5,LoadShowPose={0,0.5,0},}",
  [63152] = "{id=63152,NameZh='英灵羽证·琴[2]',Icon='item_63152',Type=260,Quality=3,MaxNum=99,SellPrice=100,Desc='英灵的证明。潜入学院的女武神在琴中注入了奥丁领域的魔力。激荡的琴声可以割裂一个半径内的植物型魔物。',NoStorage=5,LoadShowSize=1.5,LoadShowPose={0,0.5,0},}",
  [63153] = "{id=63153,NameZh='猪笼草竖琴[1]',Icon='item_63153',Type=260,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=30000,AdventureSort=6300,AdventureValue=1,Condition=8,Desc='使用忘忧草骇虫的坚韧触须当作琴弦而做的竖琴。',LoadShowSize=1.5,LoadShowRotate=60,LoadShowPose={0,0.75,0},}",
  [63156] = "{id=63156,NameZh='远古回音·琴',Icon='item_63156',Type=260,MaxNum=99,SellPrice=3200,AdventureSort=100020,AdventureValue=1,Condition=8,Desc='铭刻着神秘纹样的琴，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,LoadShowSize=1.5,LoadShowPose={0,0.8,0},}",
  [63158] = "{id=63158,NameZh='王国荣辉·琴',Icon='item_63158',Type=260,MaxNum=99,SellPrice=100,AdventureSort=100023,AdventureValue=1,Condition=8,Desc='效忠于王室的宫廷侍卫所持的琴，其上绘有卢恩王家纹章。不过，比起用于作战，这把琴更适合在正式场合中，演奏激昂的军乐。',LoadShowSize=1.5,LoadShowRotate=90,LoadShowPose={0,0.5,0},}",
  [63162] = "{id=63162,NameZh='月神的呢喃·极限',Icon='item_63162',Type=459,Quality=4,MaxNum=1,SellPrice=100,Desc='千年前，每到月圆之日，月神曼尼会驾车从夜空中走过并观察睡梦中的人类，当他看见正在噩梦中的人类，他会为梦中之人弹琴，温柔琴音带来心灵的慰藉，而这柄琴也被当时的人类尊称为月神的呢喃。',NoSale=1,NoStorage=7,TFValidDate='2022-03-10 05:00:00',ValidDate='2022-03-23 05:00:00',}",
  [63163] = "{id=63163,NameZh='英灵信标·琴[2]',Icon='item_63151',Type=260,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=100024,AdventureValue=1,Condition=8,Desc='这把琴是指引女武神降临、迎接英灵的道标。阵亡的勇士躺在冥舟里，随送葬人的拨弦，女武神将会一边摇摆，一边把勇士亲自拥入英灵殿。',NoStorage=5,LoadShowSize=1.5,LoadShowPose={0,0.5,0},}",
  [63164] = "{id=63164,NameZh='英灵羽证·琴[2]',Icon='item_63152',Type=260,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=100025,AdventureValue=1,Condition=8,Desc='英灵的证明。潜入学院的女武神在琴中注入了奥丁领域的魔力。激荡的琴声可以割裂一个半径内的植物型魔物。',NoStorage=5,LoadShowSize=1.5,LoadShowPose={0,0.5,0},}",
  [63401] = "{id=63401,NameZh='守备军魔法书',Icon='item_63401',Type=240,MaxNum=99,SellPrice=100,Level=100,}",
  [63402] = "{id=63402,NameZh='全知魔神书',Icon='item_63402',Type=461,Quality=4,MaxNum=1,SellPrice=100,Desc='巨人密米尔最珍贵的藏书之一，外部被施加了智慧神的封印，只有足够渊博之人才能翻开书页。全知魔神书的内容全部以卢恩文字书写，记载了创世神留下的超古代魔法，若能将书中的魔法全部学会，就能获得足以创世的力量。',NoSale=1,NoStorage=7,}",
  [63403] = "{id=63403,NameZh='全知魔神书·精锻',Icon='item_63403',Type=461,Quality=4,MaxNum=1,SellPrice=100,Desc='巨人密米尔最珍贵的藏书之一，外部被施加了智慧神的封印，只有足够渊博之人才能翻开书页。全知魔神书的内容全部以卢恩文字书写，记载了创世神留下的超古代魔法，若能将书中的魔法全部学会，就能获得足以创世的力量。',NoSale=1,NoStorage=7,}",
  [63404] = "{id=63404,NameZh='全知魔神书·神铸',Icon='item_63404',Type=461,Quality=4,MaxNum=1,SellPrice=100,Desc='巨人密米尔最珍贵的藏书之一，外部被施加了智慧神的封印，只有足够渊博之人才能翻开书页。全知魔神书的内容全部以卢恩文字书写，记载了创世神留下的超古代魔法，若能将书中的魔法全部学会，就能获得足以创世的力量。',NoSale=1,NoStorage=7,}",
