  [63417] = "{id=63417,NameZh='贤者日记[1]',Icon='item_63417',Type=240,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=3500,AdventureValue=1,Condition=8,Desc='请不要随便翻看别人的日记！贤者也是有小秘密的。',Feature=1,LoadShowSize=3,LoadShowRotate=70,LoadShowPose={0,0.5,0},}",
