  [63419] = "{id=63419,NameZh='启示录',Icon='item_63419',Type=240,MaxNum=99,SellPrice=100,}",
  [63420] = "{id=63420,NameZh='英灵·亚尔薇特之预言书',Icon='item_63420',Type=240,MaxNum=99,SellPrice=100,AdventureSort=100006,AdventureValue=1,Condition=8,Desc='全知神——亚尔薇特的预言之书。全篇记录着人类未知的文字，凝聚了超然的魔力。',Feature=1,LoadShowSize=3,LoadShowRotate=70,LoadShowPose={0,0.3,0},}",
  [63421] = "{id=63421,NameZh='炎魂·灰烬魔典',Icon='item_63421',Type=240,MaxNum=99,SellPrice=100,AdventureSort=100010,AdventureValue=1,Condition=8,Desc='里面记载了把敌人变成灰烬的326种办法。',LoadShowSize=3,LoadShowRotate=70,LoadShowPose={0,0.5,0},}",
  [63422] = "{id=63422,NameZh='碎雪·冰封魔典',Icon='item_63422',Type=240,MaxNum=99,SellPrice=100,AdventureSort=100009,AdventureValue=1,Condition=8,Desc='“这本魔典记载着禁忌的咒语，必须将它永久封存。”——雷藏',LoadShowSize=3,LoadShowRotate=70,LoadShowPose={0,0.5,0},}",
  [63423] = "{id=63423,NameZh='月辉·月光低语',Icon='item_63423',Type=240,MaxNum=99,SellPrice=100,AdventureSort=100008,AdventureValue=1,Condition=8,Desc='“那书页的翻动声美妙得就像是月光女神在你耳边低语。”——西芙',LoadShowSize=3,LoadShowRotate=70,LoadShowPose={0,0.5,0},}",
  [63424] = "{id=63424,NameZh='日耀·沐光圣典',Icon='item_63424',Type=240,MaxNum=99,SellPrice=100,AdventureSort=100007,AdventureValue=1,Condition=8,Desc='翻开它，沐浴在圣洁的祝福中吧。',LoadShowSize=3,LoadShowRotate=70,LoadShowPose={0,0.5,0},}",
  [63425] = "{id=63425,NameZh='星界·无限法则',Icon='item_63425',Type=240,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=100002,AdventureValue=1,Condition=8,Desc='书中充满了未知符号，据说记载着万物的绝对法则。',LoadShowSize=3,LoadShowRotate=70,LoadShowPose={0,0.5,0},}",
  [63426] = "{id=63426,NameZh='红星界魔法书',Icon='item_63426',Type=240,MaxNum=99,SellPrice=100,}",
  [63427] = "{id=63427,NameZh='黑暗秘典',Icon='item_63427',Type=240,MaxNum=99,SellPrice=100,AdventureSort=100001,AdventureValue=1,Condition=8,Desc='使用者注意！这本法典极度黑暗，极度禁忌',Feature=1,LoadShowSize=3,LoadShowRotate=70,LoadShowPose={0,0.5,0},}",
  [63428] = "{id=63428,NameZh='衔尾者法典',Icon='item_63428',Type=240,MaxNum=99,SellPrice=100,AdventureSort=100004,AdventureValue=1,Condition=8,Desc='里面的咒文全是难以理解的嘶鸣，据说是蛇语。',Feature=1,LoadShowSize=3,LoadShowRotate=70,LoadShowPose={0,0.5,0},}",
  [63429] = "{id=63429,NameZh='信仰之书',Icon='item_63429',Type=240,MaxNum=99,SellPrice=100,AdventureSort=100005,AdventureValue=1,Condition=8,Desc='巴风特曾带领手下对梦罗克进行过一次史无前例的大侵袭，这次的战争造成了数以万计的民众伤亡，在危难的关头有十四位勇士站了出来，他们牺牲了自己保护了梦罗克，死后的他们留下了自己的武器，这些武器被梦罗克的人们当做信仰的象征，这本魔法书便是十四把武器的复制品之一。',LoadShowSize=3,LoadShowRotate=70,LoadShowPose={0,0.5,0},}",
  [63430] = "{id=63430,NameZh='枫忆之书',Icon='item_63430',Type=240,MaxNum=99,SellPrice=100,AdventureSort=100003,AdventureValue=1,Condition=8,Desc='这是一本讲述着枫叶故事的书，里面书写着枫叶见证过的所有事，爱情，亲情，友情一切的一切都逃不过枫的眼睛，但是不要以为它只是一本普通的书籍。当你打开的那一刻，你就已经陷入了枫之领域…',LoadShowSize=3.2,LoadShowRotate=70,LoadShowPose={0,0.5,0},}",
  [63431] = "{id=63431,NameZh='亡灵魔法书',Icon='item_63431',Type=240,MaxNum=99,SellPrice=2100,AdventureValue=1,Condition=8,Desc='记载着诡异咒语的魔法书，翻开它的时候，仿佛能听见某人的低语。',Level=95,LoadShowSize=2.8,LoadShowRotate=70,LoadShowPose={0,0.5,0},}",
  [63432] = "{id=63432,NameZh='埃琉德尼尔备忘录',Icon='item_63432',Type=240,MaxNum=99,SellPrice=100,AdventureSort=100012,AdventureValue=1,Condition=8,Desc='那位大人每天都会在本子上写写画画，对外声称是管理死者之都的手账，其实大家都清楚那只是小女孩的日记。',TFValidDate='2019-10-28 05:00:00',ValidDate='2019-10-31 05:00:00',LoadShowSize=3,LoadShowRotate=70,LoadShowPose={0,0.5,0},}",
  [63433] = "{id=63433,NameZh='冷澈之魔法书[1]',Icon='item_63433',Type=240,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=3500,AdventureValue=1,Condition=8,Desc='这本魔法书与众不同，字里行间带着一种没有感情的冷峻。',Feature=1,LoadShowSize=3,LoadShowRotate=70,LoadShowPose={0,0.5,0},}",
  [63434] = "{id=63434,NameZh='圣灵·亚尔薇特之神识书',Icon='item_63434',Type=240,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='全知神——亚尔薇特的书，传言智慧巨人密米尔窃取了这本书的内容，但作为人类，这件事的真实性已经无法考证了。',LoadShowSize=3,LoadShowRotate=70,LoadShowPose={0,0.5,0},}",
  [63435] = "{id=63435,NameZh='圣徒魔书[1]',Icon='item_63435',Type=240,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='据说只有内心坚定，善良虔诚的人才能发挥它真正的力量——驱赶黑暗，带来希望。',LoadShowSize=3,LoadShowRotate=70,LoadShowPose={0,0.5,0},}",
  [63436] = "{id=63436,NameZh='生命体法典',Icon='item_63436',Type=240,MaxNum=99,SellPrice=2400,Desc='里面记载了雷根贝勒生命体实验的部分生命体合成法则。',Level=100,}",
  [63437] = "{id=63437,NameZh='魔器·嘉波',Icon='item_63437',Type=240,MaxNum=99,SellPrice=100,AdventureSort=100011,AdventureValue=1,Condition=8,Desc='梦罗克碎片打造的禁忌武器，对应着异世界恶魔No.33·嘉波，可以剥夺的人的知识，也可以使人睿智，解答人们关于过去与未来的问题。',LoadShowSize=3,LoadShowRotate=70,LoadShowPose={0,0.5,0},}",
  [63438] = "{id=63438,NameZh='觉醒福音',Icon='item_63438',Type=240,MaxNum=99,SellPrice=100,AdventureSort=100013,AdventureValue=1,Condition=8,Desc='勇敢的少年啊，这是赐予你的奇迹之书。',Feature=1,LoadShowSize=3.2,LoadShowRotate=70,LoadShowPose={0,0.5,0},}",
  [63439] = "{id=63439,NameZh='妙勒尼魔典[1]',Icon='item_63439',Type=240,MaxNum=99,SellPrice=100,Desc='翻开它的第一页，上面写着一句训诫“克己守心”。',}",
  [63440] = "{id=63440,NameZh='贤者日记★[1]',Icon='item_63440',Type=240,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,AdventureSort=3500,AdventureValue=1,Condition=8,Desc='请不要随便翻看别人的日记！贤者也是有小秘密的。',LoadShowSize=3,LoadShowRotate=70,LoadShowPose={0,0.5,0},}",
  [63441] = "{id=63441,NameZh='科学救赎·书',Icon='item_63441',Type=240,MaxNum=99,SellPrice=100,AdventureSort=100014,AdventureValue=1,Condition=8,Desc='科学！科学！科学！为了科学一切的牺牲都是值得，蝼蚁们的生命本就毫无价值，因实验而死的他们应该觉得骄傲，这是他们的宿命！快了！就快了，只要这本死亡之书制作出来，我会在上面写满那些反抗者的名字……',Feature=1,}",
  [63442] = "{id=63442,NameZh='圣息崇聆·书',Icon='item_63442',Type=240,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='光与天空，圣洁的飞鸟，神的双翼已然张开，吾虔诚的信徒，愿你在吾的庇佑下体验幸福与美好，你的灵魂之音，吾等已经听到，这本圣书赐予你，神祇永远与你同在。',}",
  [63443] = "{id=63443,NameZh='辉光十字·书',Icon='item_63443',Type=240,MaxNum=99,SellPrice=2600,AdventureSort=100015,AdventureValue=1,Condition=8,Desc='这本古书出自阿卢纳贝兹教国最有名的工匠——索罗克之手，他搜寻了整个教国寻找制作武器的材料，最终在圣域神殿的地下深处寻到了结果，吸取神灵信仰的矿石坚硬无比，制成的武器更是消灭黑暗的破晓之力。',Level=110,}",
  [63444] = "{id=63444,NameZh='冷澈之魔法书★[1]',Icon='item_63444',Type=240,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=3500,AdventureValue=1,Condition=8,Desc='这本魔法书与众不同，字里行间带着一种没有感情的冷峻。',Feature=1,LoadShowSize=3,LoadShowRotate=70,LoadShowPose={0,0.5,0},}",
  [63445] = "{id=63445,NameZh='蔷薇灵语之书',Icon='item_63445',Type=240,MaxNum=99,SellPrice=3200,AdventureSort=3500,AdventureValue=1,Condition=8,Desc='妖精一族的“灵语师”代代相传的秘典，上面似乎记载了一些妖精的秘法——不过字实在太小了！',Level=110,LoadShowSize=2.5,LoadShowRotate=-60,LoadShowPose={0,0.25,0},}",
  [63446] = "{id=63446,NameZh='红鱼花铃·书',Icon='item_63446',Type=240,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='长了一身红色鳞片的金鱼呀，喜欢在湖底的水草里悠闲地打瞌睡。有人投食的话，也会慢悠悠地钻到水面上，不紧不慢地吃鱼食。如果它会衔着书游出水面，也不要惊讶，这是金鱼族的报答哟~',LoadShowSize=3,LoadShowRotate=70,LoadShowPose={0,0.4,0},}",
  [63447] = "{id=63447,NameZh='死亡笔记[1]',Icon='item_63447',Type=240,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=3500,AdventureValue=1,Condition=8,Desc='死神所使用的名簿。死神所掉落的名簿有时候就这样在现世上流传。写的密密麻麻的人的姓名,好像看到有些熟悉的名字似的。',LoadShowSize=3,LoadShowRotate=15,LoadShowPose={0,0.3,0},}",
  [63448] = "{id=63448,NameZh='湛蓝天光·书',Icon='item_63448',Type=240,MaxNum=99,SellPrice=2800,AdventureValue=1,Condition=8,Desc='阔大的云海之上透出湛蓝天光，晴空下的战士们振作起了精神。守护好这本圣书吧，它印证着你的忠诚，勇敢与希望。',Level=110,LoadShowSize=2.8,LoadShowRotate=70,LoadShowPose={0,0.5,0},}",
  [63449] = "{id=63449,NameZh='天虹圣遗·书',Icon='item_63449',Type=240,MaxNum=99,SellPrice=100,AdventureSort=100019,AdventureValue=1,Condition=8,Desc='这本魔法书的封面由彩虹桥碎片制成，翻开时炫目的虹光让人无法看到书上的内容，因此这本书写了什么至今仍是一个谜。',LoadShowSize=3,LoadShowPose={0,0.5,0},}",
  [63450] = "{id=63450,NameZh='月下祈者·书',Icon='item_63450',Type=240,MaxNum=99,SellPrice=100,AdventureSort=3500,AdventureValue=1,Condition=8,Desc='冰封千年的陨铁，王国的工匠们用尽办法也无法将其熔铸，却因小学徒的一次失误暴露在月光下。那一刻奇迹发生，陨铁融化宛若水银般流转，在月光下散发耀眼星辉。\n此乃月光赐福之圣典，执书者当以月光之力，传播正道，驱散阴霾！',LoadShowRotate=75,LoadShowPose={0,0.4,0.5},}",
  [63451] = "{id=63451,NameZh='英灵起点·书[2]',Icon='item_63451',Type=240,Quality=2,MaxNum=99,SellPrice=100,Desc='克里图拉新生领到的初心武器，致敬英灵而铸上蓝金涂装。据说设计者是个热衷传播卢恩的书虫。他把卢恩文字写得像被妈妈偷看的日记一样，好懂又不好懂。',NoStorage=5,LoadShowPose={0,0.4,0},}",
  [63452] = "{id=63452,NameZh='英灵信标·书[2]',Icon='item_63452',Type=240,Quality=3,MaxNum=99,SellPrice=100,Desc='这本书是指引女武神降临、迎接英灵的道标。阵亡的勇士抱着它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,LoadShowPose={0,0.4,0},}",
  [63453] = "{id=63453,NameZh='英灵羽证·书[2]',Icon='item_63453',Type=240,Quality=3,MaxNum=99,SellPrice=100,Desc='英灵的证明。潜入学院的女武神在书中注入了奥丁领域的魔力。书本上写满了女武神的注记，还夹着一只羽毛书签。',NoStorage=5,LoadShowPose={0,0.4,0},}",
  [63455] = "{id=63455,NameZh='远古回音·书',Icon='item_63455',Type=240,MaxNum=99,SellPrice=3200,AdventureSort=100020,AdventureValue=1,Condition=8,Desc='铭刻着神秘纹样的书，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,LoadShowPose={0,0.35,0},}",
  [63457] = "{id=63457,NameZh='王国荣辉·书',Icon='item_63457',Type=240,MaxNum=99,SellPrice=100,AdventureSort=100023,AdventureValue=1,Condition=8,Desc='效忠于王室的宫廷侍卫所持的书册，其上绘有卢恩王家纹章。与华丽的封面相反，书册的内部空空如也……毕竟，它只是件装饰品。',}",
  [63480] = "{id=63480,NameZh='英灵起点·手里剑[2]',Icon='item_63480',Type=300,Quality=2,MaxNum=99,SellPrice=100,Desc='克里图拉新生领到的初心武器，致敬英灵而铸上蓝金涂装。据说设计者是胧月夜。她与尊崇不动明王的忍者在天津町对决，记下了对方武器的大致形态。',NoStorage=5,LoadShowPose={0,0.3,0},Delete=63480}",
  [63481] = "{id=63481,NameZh='英灵信标·手里剑[2]',Icon='item_63481',Type=300,Quality=3,MaxNum=99,SellPrice=100,Desc='这把手里剑是指引女武神降临、迎接英灵的道标。阵亡的勇士抱着它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,LoadShowPose={0,0.3,0},Delete=63481}",
  [63482] = "{id=63482,NameZh='英灵羽证·手里剑[2]',Icon='item_63482',Type=300,Quality=3,MaxNum=99,SellPrice=100,Desc='英灵的证明。潜入学院的女武神在手里剑中注入了奥丁领域的魔力。手里剑生出羽毛，与风更为亲和。戾气消减，体现了不动之慈悲。',NoStorage=5,LoadShowPose={0,0.3,0},Delete=63482}",
  [63483] = "{id=63483,NameZh='全知魔神书·极限',Icon='item_63483',Type=461,Quality=4,MaxNum=1,SellPrice=100,Desc='巨人密米尔最珍贵的藏书之一，外部被施加了智慧神的封印，只有足够渊博之人才能翻开书页。全知魔神书的内容全部以卢恩文字书写，记载了创世神留下的超古代魔法，若能将书中的魔法全部学会，就能获得足以创世的力量。',NoSale=1,NoStorage=7,TFValidDate='2022-03-10 05:00:00',ValidDate='2022-03-23 05:00:00',}",
  [63484] = "{id=63484,NameZh='英灵信标·书[2]',Icon='item_63452',Type=240,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=100024,AdventureValue=1,Condition=8,Desc='这本书是指引女武神降临、迎接英灵的道标。阵亡的勇士抱着它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,LoadShowPose={0,0.4,0},}",
  [63485] = "{id=63485,NameZh='英灵羽证·书[2]',Icon='item_63453',Type=240,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=100025,AdventureValue=1,Condition=8,Desc='英灵的证明。潜入学院的女武神在书中注入了奥丁领域的魔力。书本上写满了女武神的注记，还夹着一只羽毛书签。',NoStorage=5,LoadShowPose={0,0.4,0},}",
  [63486] = "{id=63486,NameZh='星宫图[1]',Icon='item_63488',Type=240,Quality=3,MaxNum=99,SellPrice=100,Desc='记录着星座图案与传说的魔法书，凭借它或许能够借用星空的力量。',LoadShowSize=2,LoadShowPose={0,0.4,0},Delete=63486}",
  [63487] = "{id=63487,NameZh='诸天星图[1]',Icon='item_63489',Type=240,Quality=4,MaxNum=99,SellPrice=100,Desc='绘制着宇宙中群星轨迹的古老星图，许多记录超越了凡人的认知，亦无人知晓它的作者是谁。',LoadShowSize=2,LoadShowPose={0,0.4,0},Delete=63487}",
  [63488] = "{id=63488,NameZh='天衍录[1]',Icon='item_63486',Type=240,Quality=3,MaxNum=99,SellPrice=100,Desc='记载着宇宙运行之道的魔法书，或许无人能够参悟其中的奥秘。',LoadShowSize=2,LoadShowPose={0,0.4,0},Delete=63488}",
  [63489] = "{id=63489,NameZh='万象天书[1]',Icon='item_63487',Type=240,Quality=4,MaxNum=99,SellPrice=100,Desc='在没有获得认可的人眼中，书上的内容如同鬼画符一般。但对于那些被选中的人来说，书中所记载的是凌驾于世间万物的至理。',LoadShowSize=2,LoadShowPose={0,0.4,0},Delete=63489}",
  [63490] = "{id=63490,NameZh='灭世之书[1]',Icon='item_63490',Type=240,Quality=4,MaxNum=99,SellPrice=100,Desc='记录着晦涩难懂的符号，曾有人想要破解，然而在念出咒语的一瞬，灾祸便从天而降……',LoadShowSize=2,}",
  [63491] = "{id=63491,NameZh='狱火魔典[1]',Icon='item_40598',Type=240,Quality=3,MaxNum=99,SellPrice=100,Desc='从深海中走出的毁灭者，要让这世界被地狱吞噬。',LoadShowSize=2,LoadShowPose={0,0.4,0},Delete=63491}",
  [63492] = "{id=63492,NameZh='血鳞魔典[1]',Icon='item_40599',Type=240,Quality=4,MaxNum=99,SellPrice=100,Desc='从深海中走出的毁灭者，要让这世界被地狱吞噬。',LoadShowSize=2,LoadShowPose={0,0.4,0},Delete=63492}",
  [63600] = "{id=63600,NameZh='希望之星·手枪',Icon='item_63600',Type=310,Quality=3,MaxNum=99,SellPrice=100,Desc='使用“羽斯缇卡之戒”的力量塑造的手枪，播下生命的种子，于绝境中守望希望之花的绽放。',Feature=1,LoadShowPose={0,0.2,0},Delete=63600}",
  [63601] = "{id=63601,NameZh='英灵起点·手枪[2]',Icon='item_63601',Type=310,Quality=2,MaxNum=99,SellPrice=100,Desc='克里图拉新生领到的初心武器，致敬英灵而铸上蓝金涂装。据说设计者是一名百战余生的枪手，他的一生见证了无数人的死亡，也见证了无数面对死亡时的勇气，于是他设计此枪，缅怀逝者，传承英灵的气魄。',NoStorage=5,Feature=1,LoadShowPose={0,0.2,0},Delete=63601}",
  [63602] = "{id=63602,NameZh='英灵信标·手枪[2]',Icon='item_63602',Type=310,Quality=3,MaxNum=99,SellPrice=100,Desc='这支手枪是指引女武神降临、迎接英灵的道标。阵亡的勇士抱着它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,Feature=1,LoadShowPose={0,0.2,0},Delete=63602}",
  [63603] = "{id=63603,NameZh='英灵羽证·手枪[2]',Icon='item_63603',Type=310,Quality=3,MaxNum=99,SellPrice=100,Desc='英灵的证明。潜入学院的女武神在这支手枪中注入了奥丁领域的魔力。枪管长出了羽翼，好像翱翔于天际的白鸽。',NoStorage=5,Feature=1,LoadShowPose={0,0.2,0},Delete=63603}",
  [63604] = "{id=63604,NameZh='英灵·希露德之号令',Icon='item_63604',Type=310,Quality=3,MaxNum=99,SellPrice=100,Desc='掌管决斗的女武神希露德佩戴的发令枪，枪声响起便是一场决斗开启之时。',Feature=1,LoadShowPose={0,0.2,0},Delete=63604}",
  [63605] = "{id=63605,NameZh='圣灵·希露德捍卫者',Icon='item_63605',Type=310,Quality=3,MaxNum=99,SellPrice=100,Desc='掌管决斗的女武神希露德佩戴的枪械，她用这把手枪捍卫着世间每一场对决的公平。',Feature=1,LoadShowPose={0,0.2,0},Delete=63605}",
  [63606] = "{id=63606,NameZh='银啸',Icon='item_63607',Type=310,Quality=3,MaxNum=99,SellPrice=100,Desc='活跃于克雷斯特汉姆古城的魔物猎人所用的配枪，用呼啸而过的白银子弹抹杀这世间的罪恶。（建议作为武器外观使用）',Feature=1,LoadShowPose={0,0.2,0},Delete=63606}",
  [63607] = "{id=63607,NameZh='圣徒手枪[1]',Icon='item_63606',Type=310,Quality=3,MaxNum=99,SellPrice=100,Desc='由“光明圣徒”安德鲁设计、可以发射子弹的远程武器，是世界上最早的火枪，受制于当时的技术难以铸造出成品，直到如今技术成熟才投入生产。受到光明圣徒的祝福，安全精炼时消耗的装备件数减少一半。',Feature=1,LoadShowPose={0,0.2,0},Delete=63607}",
  [63608] = "{id=63608,NameZh='远古回音·手枪',Icon='item_63608',Type=310,MaxNum=99,SellPrice=3200,Desc='铭刻着神秘纹样的手枪，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,Feature=1,LoadShowPose={0,0.2,0},Delete=63608}",
  [63609] = "{id=63609,NameZh='白银凶星',Icon='item_63609',Type=463,Quality=4,MaxNum=1,SellPrice=100,Desc='超古代文明尤佩雷斯的遗产，在诸神黄昏之战中为对抗恶魔而研制的新型兵器。用光子能量击发秘银弹丸，能够对一切邪恶存在造成恐怖的伤害。这把枪的使用者也因此成为了恶魔们首要击杀的目标，这把枪的历任主人无不牺牲于战场上，这也是这把枪“凶星”之名的由来。',NoSale=1,NoStorage=7,LoadShowPose={0,0.2,0},Delete=63609}",
  [63610] = "{id=63610,NameZh='白银凶星·精锻',Icon='item_63610',Type=463,Quality=4,MaxNum=1,SellPrice=100,Desc='超古代文明尤佩雷斯的遗产，在诸神黄昏之战中为对抗恶魔而研制的新型兵器。用光子能量击发秘银弹丸，能够对一切邪恶存在造成恐怖的伤害。这把枪的使用者也因此成为了恶魔们首要击杀的目标，这把枪的历任主人无不牺牲于战场上，这也是这把枪“凶星”之名的由来。',NoSale=1,NoStorage=7,LoadShowPose={0,0.2,0},Delete=63610}",
  [63611] = "{id=63611,NameZh='白银凶星·神铸',Icon='item_63611',Type=463,Quality=4,MaxNum=1,SellPrice=100,Desc='超古代文明尤佩雷斯的遗产，在诸神黄昏之战中为对抗恶魔而研制的新型兵器。用光子能量击发秘银弹丸，能够对一切邪恶存在造成恐怖的伤害。这把枪的使用者也因此成为了恶魔们首要击杀的目标，这把枪的历任主人无不牺牲于战场上，这也是这把枪“凶星”之名的由来。',NoSale=1,NoStorage=7,LoadShowPose={0,0.2,0},Delete=63611}",
  [63612] = "{id=63612,NameZh='黄金勒克斯手枪[1]',Icon='item_63612',Type=310,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='全大陆限量款手枪，枪身整体由黄金打造，造价惊人，三大国的许多权贵都将这把枪作为收藏品。“确认过眼神，是招惹不起的人……”',Feature=1,LoadShowPose={0,0.2,0},Delete=63612}",
  [63613] = "{id=63613,NameZh='黄金执法者[1]',Icon='item_63613',Type=310,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,Desc='当艾因布洛克的枪械师们打造出这样一款亮闪闪的手枪时，人们以为这是一款华而不实的工艺品。但令人惊诧的是这把枪的使用者在决斗中保持着超高的胜率——毕竟是一把自带“致盲”效果的枪呢！',Feature=1,LoadShowPose={0,0.2,0},Delete=63613}",
  [63614] = "{id=63614,NameZh='红翼左轮手枪[1]',Icon='item_63614',Type=310,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='专为快速连射设计的手枪，缩短的枪管更加轻便，搭配厚重的红色枪身，持握与射击手感极佳。',Feature=1,LoadShowPose={0,0.2,0},Delete=63614}",
  [63615] = "{id=63615,NameZh='地狱火手枪[1]',Icon='item_63615',Type=310,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,Desc='一位疯狂的枪械师设计出的疯狂的作品，在保留短管左轮枪射速的同时大胆的将枪管口径扩大，让这把枪可以尽情敌人倾泄弹雨。“谢天谢地，它没炸膛！”',Feature=1,LoadShowPose={0,0.2,0},Delete=63615}",
  [63616] = "{id=63616,NameZh='近卫手枪[1]',Icon='item_63614',Type=310,MaxNum=99,SellPrice=100,Desc='修发兹共和国出产的便携式手枪，虽然威力一般却方便携带。',Feature=1,LoadShowPose={0,0.2,0},Delete=63616}",
  [63617] = "{id=63617,NameZh='圣息崇聆·手枪',Icon='item_63617',Type=310,Quality=3,MaxNum=99,SellPrice=100,Desc='光与天空，圣洁的飞鸟，神的双翼已然张开，吾虔诚的信徒，愿你在吾的庇佑下体验幸福与美好，你的灵魂之音，吾等已经听到，这把手枪赐予你，神祇永远与你同在。',Feature=1,LoadShowPose={0,0.2,0},Delete=63617}",
  [63618] = "{id=63618,NameZh='天虹圣遗·手枪',Icon='item_63618',Type=310,Quality=3,MaxNum=99,SellPrice=100,Desc='浮空精灵收集彩虹桥碎片打造的手枪，敌人常常会沉醉于它散发出的炫目光华，甚至感受不到死亡的痛楚。',Feature=1,LoadShowPose={0,0.2,0},Delete=63618}",
  [63619] = "{id=63619,NameZh='信仰手枪',Icon='item_63619',Type=310,Quality=3,MaxNum=99,SellPrice=100,Desc='巴风特曾带领手下对梦罗克进行过一次史无前例的大侵袭，这次的战争造成了数以万计的民众伤亡，在危难的关头有十四位勇士站了出来，他们牺牲了自己保护了梦罗克，死后的他们留下了自己的武器，这些武器被梦罗克的人们当做信仰的象征，这枝把手枪便是十四把武器之一。',Feature=1,LoadShowPose={0,0.2,0},Delete=63619}",
  [63620] = "{id=63620,NameZh='衔尾者手枪',Icon='item_63620',Type=310,Quality=3,MaxNum=99,SellPrice=100,Desc='向黑暗与巨蛇借来的魔力，采用坚固的蛇鳞制成的手枪。',Feature=1,LoadShowPose={0,0.2,0},Delete=63620}",
  [63621] = "{id=63621,NameZh='魔器·瓦拉克',Icon='item_63621',Type=310,Quality=3,MaxNum=99,SellPrice=100,Desc='梦罗克碎片打造的禁忌武器，对应着异世界恶魔No.62·瓦拉克，其身上长有天使的翅膀。擅长给人真知，告知隐藏宝物的位置，也可以告诉召唤者在哪里可以看见地狱大蛇。',Feature=1,LoadShowPose={0,0.2,0},Delete=63621}",
  [63622] = "{id=63622,NameZh='星界·烁芒',Icon='item_63622',Type=310,Quality=3,MaxNum=99,SellPrice=100,Desc='利用星辰中提炼出的珍贵矿石做制作而成，这把手枪带着星光的力量，射击时流光四溢如同漫天的星辰。',Feature=1,LoadShowPose={0,0.2,0},Delete=63622}",
  [63623] = "{id=63623,NameZh='日耀·日轮裁决',Icon='item_63623',Type=310,Quality=3,MaxNum=99,SellPrice=100,Desc='太阳马戏团标志性的武器，耀眼的金光和精致的造型，是坚持爱与正义的冒险者所追寻的目标。',Feature=1,LoadShowPose={0,0.2,0},Delete=63623}",
  [63624] = "{id=63624,NameZh='月辉·星光裁决',Icon='item_63624',Type=310,Quality=3,MaxNum=99,SellPrice=100,Desc='暗月马戏团标志性的武器，因其式样低调而华丽又非常稀有，成为了年轻冒险家追捧的热门武器。',Feature=1,LoadShowPose={0,0.2,0},Delete=63624}",
  [63625] = "{id=63625,NameZh='炎魂·炽焰裁决',Icon='item_63625',Type=310,Quality=3,MaxNum=99,SellPrice=100,Desc='融合红龙的灼热吐息与火焰结晶制作的手枪，射出的子弹带着烈焰的气息。',Feature=1,LoadShowPose={0,0.2,0},Delete=63625}",
  [63626] = "{id=63626,NameZh='碎雪·永冬裁决',Icon='item_63626',Type=310,Quality=3,MaxNum=99,SellPrice=100,Desc='融合冰龙的霜冻吐息与魔力冰晶制作的手枪，每次出手都能让敌人瞬间结冰。',Feature=1,LoadShowPose={0,0.2,0},Delete=63626}",
  [63627] = "{id=63627,NameZh='时间裁决',Icon='item_63627',Type=310,Quality=3,MaxNum=99,SellPrice=100,Desc='时间是不会静止的，这把手枪却可以打破时间的禁锢，让持有者走入新纪元。',Feature=1,LoadShowPose={0,0.2,0},Delete=63627}",
  [63628] = "{id=63628,NameZh='埃琉德尼尔裁决',Icon='item_63628',Type=310,Quality=3,MaxNum=99,SellPrice=100,Desc='死者之都的亡魂们都害怕这把枪下封印着的东西。',Feature=1,LoadShowPose={0,0.2,0},Delete=63628}",
  [63629] = "{id=63629,NameZh='永夜·黎明前夕',Icon='item_63629',Type=310,Quality=3,MaxNum=99,SellPrice=100,Desc='黑暗之中的黑暗，能够吸收所有光芒的黑，赐予这把手枪特别的力量。',Feature=1,LoadShowPose={0,0.2,0},Delete=63629}",
  [63630] = "{id=63630,NameZh='红鱼花铃·手枪',Icon='item_63630',Type=310,Quality=3,MaxNum=99,SellPrice=100,Desc='长了一身红色鳞片的金鱼呀，喜欢在湖底的水草里悠闲地打瞌睡。有人投食的话，也会慢悠悠地钻到水面上，不紧不慢地吃鱼食。如果它会衔着手枪游出水面，也不要惊讶，这是金鱼族的报答哟~',Feature=1,LoadShowPose={0,0.2,0},Delete=63630}",
  [63631] = "{id=63631,NameZh='枫忆手枪',Icon='item_63631',Type=310,Quality=3,MaxNum=99,SellPrice=100,Desc='如深秋枫叶般火红的手枪，带有令人心跳加快的奇妙魔力。',Feature=1,LoadShowPose={0,0.2,0},Delete=63631}",
  [63632] = "{id=63632,NameZh='月下祈者·手枪',Icon='item_63632',Type=310,Quality=3,MaxNum=99,SellPrice=100,Desc='冰封千年的陨铁，王国的工匠们用尽办法也无法将其熔铸，却因小学徒的一次失误暴露在月光下。那一刻奇迹发生，陨铁融化宛若水银般流转，在月光下散发耀眼星辉。\n一部分陨铁溅落在旁边的手枪，令它拥有了驱散邪祟的圣洁之力。',Feature=1,LoadShowPose={0,0.2,0},Delete=63632}",
  [63633] = "{id=63633,NameZh='科学救赎·手枪',Icon='item_63633',Type=310,Quality=3,MaxNum=99,SellPrice=100,Desc='科学！科学！科学！为了科学一切的牺牲都是值得，蝼蚁们的生命本就毫无价值，因实验而死的他们应该觉得骄傲，这是他们的宿命！快了！就快了，只要把手枪制作出来，我就能让那些反抗者成为我下一批的实验品……哈哈哈……',Feature=1,Delete=63633}",
  [63635] = "{id=63635,NameZh='王国荣辉·手枪',Icon='item_63635',Type=310,Quality=3,MaxNum=99,SellPrice=100,Desc='效忠于王室的宫廷侍卫所持的手枪，其上绘有卢恩王家纹章。一位来自朱诺的流亡者，带来了手枪的研发技术。他厌倦了没有尽头的抗争，彻底抛弃了自己的故乡……',LoadShowRotate=90,Delete=63635}",
  [63639] = "{id=63639,NameZh='白银凶星·极限',Icon='item_63639',Type=463,Quality=4,MaxNum=1,SellPrice=100,Desc='超古代文明尤佩雷斯的遗产，在诸神黄昏之战中为对抗恶魔而研制的新型兵器。用光子能量击发秘银弹丸，能够对一切邪恶存在造成恐怖的伤害。这把枪的使用者也因此成为了恶魔们首要击杀的目标，这把枪的历任主人无不牺牲于战场上，这也是这把枪“凶星”之名的由来。',NoSale=1,NoStorage=7,TFValidDate='2022-03-10 05:00:00',ValidDate='2022-03-23 05:00:00',LoadShowPose={0,0.2,0},Delete=63639}",
  [63640] = "{id=63640,NameZh='英灵信标·手枪[2]',Icon='item_63602',Type=310,Quality=2,MaxNum=99,SellPrice=100,Desc='这支手枪是指引女武神降临、迎接英灵的道标。阵亡的勇士抱着它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,Feature=1,LoadShowPose={0,0.2,0},Delete=63640}",
  [63641] = "{id=63641,NameZh='英灵羽证·手枪[2]',Icon='item_63603',Type=310,Quality=3,MaxNum=99,SellPrice=100,Desc='英灵的证明。潜入学院的女武神在这支手枪中注入了奥丁领域的魔力。枪管长出了羽翼，好像翱翔于天际的白鸽。',NoStorage=5,Feature=1,LoadShowPose={0,0.2,0},Delete=63641}",
  [63900] = "{id=63900,NameZh='希望之星·步枪',Icon='item_63900',Type=320,Quality=3,MaxNum=99,SellPrice=100,Desc='使用“羽斯缇卡之戒”的力量塑造的来福枪，即使在黑夜中，也有希望之星指引方向。',Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63900}",
  [63901] = "{id=63901,NameZh='英灵起点·步枪[2]',Icon='item_63901',Type=320,Quality=2,MaxNum=99,SellPrice=100,Desc='克里图拉新生领到的初心武器，致敬英灵而铸上蓝金涂装。据说设计者是一名百战余生的老兵，他在战争岁月见证了无数战友的牺牲，于是他设计此枪，缅怀逝者，传承英灵的气魄。',NoStorage=5,Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63901}",
  [63902] = "{id=63902,NameZh='英灵信标·步枪[2]',Icon='item_63902',Type=320,Quality=3,MaxNum=99,SellPrice=100,Desc='这杆步枪是指引女武神降临、迎接英灵的道标。阵亡的勇士抱着它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63902}",
  [63903] = "{id=63903,NameZh='英灵羽证·步枪[2]',Icon='item_63903',Type=320,Quality=3,MaxNum=99,SellPrice=100,Desc='英灵的证明。潜入学院的女武神在这杆步枪中注入了奥丁领域的魔力。枪身长出了羽翼，好像穿梭于晴空中的雄鹰。',NoStorage=5,Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63903}",
  [63904] = "{id=63904,NameZh='英灵·希格露恩之觉醒',Icon='item_63904',Type=320,Quality=3,MaxNum=99,SellPrice=100,Desc='骁勇善战的女武神希格露恩手中的火枪，被这把枪械的魔力子弹击中会迸发出强大的勇气。',Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63904}",
  [63905] = "{id=63905,NameZh='圣灵·希格露恩爆裂枪',Icon='item_63905',Type=320,Quality=3,MaxNum=99,SellPrice=100,Desc='骁勇善战的女武神希格露恩佩戴的火枪，这把枪械击发时声音如同雷鸣，令人心生胆怯。',Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63905}",
  [63906] = "{id=63906,NameZh='无名宿卫',Icon='item_63907',Type=320,Quality=3,MaxNum=99,SellPrice=100,Desc='守护托利斯坦大帝的宿卫配备的武器，这支军队对大帝绝对忠诚，每一个加入宿卫的士兵都要舍弃自己的名字，余生以代号的身份活着，并且履行守护大帝的使命直到死亡的那一刻。（建议作为武器外观使用）',Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63906}",
  [63907] = "{id=63907,NameZh='圣徒步枪[1]',Icon='item_63906',Type=320,Quality=3,MaxNum=99,SellPrice=100,Desc='由“光明圣徒”安德鲁设计可以发射子弹的远程武器，受制于当时的技术难以铸造出成品，据说雷根贝勒公司出产的步枪都是以它为原型。受到光明圣徒的祝福，安全精炼时消耗的装备件数减少一半。',Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63907}",
  [63908] = "{id=63908,NameZh='远古回音·来复枪',Icon='item_63908',Type=320,MaxNum=99,SellPrice=3200,Desc='铭刻着神秘纹样的来复枪，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,Feature=1,LoadShowSize=1.7,LoadShowPose={0,0.3,-0.35},Delete=63908}",
  [63909] = "{id=63909,NameZh='尤佩雷斯灭龙炮',Icon='item_63909',Type=464,Quality=4,MaxNum=1,SellPrice=100,Desc='超古代文明尤佩雷斯的遗产，机械大师阿尔米隆倾注半生心血制成的杰作。时至今日我们已不知道这位大师与龙族之间有何仇怨，但在诸神黄昏的大战中，这把枪收割的巨龙灵魂数以千计。',NoSale=1,NoStorage=7,LoadShowPose={0,0.3,-0.35},Delete=63909}",
  [63910] = "{id=63910,NameZh='尤佩雷斯灭龙炮·精锻',Icon='item_63910',Type=464,Quality=4,MaxNum=1,SellPrice=100,Desc='超古代文明尤佩雷斯的遗产，机械大师阿尔米隆倾注半生心血制成的杰作。时至今日我们已不知道这位大师与龙族之间有何仇怨，但在诸神黄昏的大战中，这把枪收割的巨龙灵魂数以千计。',NoSale=1,NoStorage=7,LoadShowPose={0,0.3,-0.35},Delete=63910}",
  [63911] = "{id=63911,NameZh='尤佩雷斯灭龙炮·神铸',Icon='item_63911',Type=464,Quality=4,MaxNum=1,SellPrice=100,Desc='超古代文明尤佩雷斯的遗产，机械大师阿尔米隆倾注半生心血制成的杰作。时至今日我们已不知道这位大师与龙族之间有何仇怨，但在诸神黄昏的大战中，这把枪收割的巨龙灵魂数以千计。',NoSale=1,NoStorage=7,LoadShowPose={0,0.3,-0.35},Delete=63911}",
  [63912] = "{id=63912,NameZh='终结者狙击步枪[1]',Icon='item_63912',Type=320,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='配备大口径弹药的重型狙击枪，威力巨大可以轻松击穿骑士的重铠，也正因如此，只有那些经受过专业训练的神枪手才能驾驭它。',Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63912}",
  [63913] = "{id=63913,NameZh='强袭型终结者[1]',Icon='item_63913',Type=320,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,Desc='经过枪械大师改装的终结者狙击步枪，与通常型相比，强袭型终结者拥有更强的火力，配备的高倍率瞄准镜协助射手精准索敌，是每一个狙击手梦寐以求的完美武器。“看看那个弹坑！你管这玩意儿叫枪？”',Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63913}",
  [63914] = "{id=63914,NameZh='制式步枪[1]',Icon='item_63914',Type=320,MaxNum=99,SellPrice=100,Desc='修发兹共和国出产，配发给士兵的制式枪械，拥有着不错的射程和精准度。',Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63914}",
  [63915] = "{id=63915,NameZh='布尔其来复枪（未投放）',Icon='item_63915',Type=320,Quality=3,MaxNum=99,SellPrice=100,Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63915}",
  [63916] = "{id=63916,NameZh='布尔其来复枪灌注（未投放）',Icon='item_63916',Type=320,Quality=4,MaxNum=99,SellPrice=100,Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63916}",
  [63917] = "{id=63917,NameZh='圣息崇聆·来复枪',Icon='item_63917',Type=320,Quality=3,MaxNum=99,SellPrice=100,Desc='光与天空，圣洁的飞鸟，神的双翼已然张开，吾虔诚的信徒，愿你在吾的庇佑下体验幸福与美好，你的灵魂之音，吾等已经听到，这把来复枪赐予你，神祇永远与你同在。',Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63917}",
  [63918] = "{id=63918,NameZh='天虹圣遗·来复枪',Icon='item_63918',Type=320,Quality=3,MaxNum=99,SellPrice=100,Desc='浮空精灵收集彩虹桥碎片打造的来复枪，拥有着绚丽的枪身以及无语伦比的精准度。',Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63918}",
  [63919] = "{id=63919,NameZh='信仰来复枪',Icon='item_63919',Type=320,Quality=3,MaxNum=99,SellPrice=100,Desc='巴风特曾带领手下对梦罗克进行过一次史无前例的大侵袭，这次的战争造成了数以万计的民众伤亡，在危难的关头有十四位勇士站了出来，他们牺牲了自己保护了梦罗克，死后的他们留下了自己的武器，这些武器被梦罗克的人们当做信仰的象征，这把来复枪便是十四把武器之一。',Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63919}",
  [63920] = "{id=63920,NameZh='衔尾者来复枪',Icon='item_63920',Type=320,Quality=3,MaxNum=99,SellPrice=100,Desc='向黑暗与巨蛇借来的魔力，采用坚固的蛇鳞制成的来复枪。',Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63920}",
  [63921] = "{id=63921,NameZh='魔器·安杜马里',Icon='item_63921',Type=320,Quality=3,MaxNum=99,SellPrice=100,Desc='梦罗克碎片打造的禁忌武器，对应着异世界恶魔No.72·安杜马里，常以手中持有一条地狱大蛇的男子形象出现。',Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63921}",
  [63922] = "{id=63922,NameZh='星界·死亡谢幕',Icon='item_63922',Type=320,Quality=3,MaxNum=99,SellPrice=100,Desc='利用星辰中提炼出的珍贵矿石做制作而成，这把来复枪带着星光的力量，射击时流光四溢如同漫天的星辰。',Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63922}",
  [63923] = "{id=63923,NameZh='日耀·日轮谢幕',Icon='item_63923',Type=320,Quality=3,MaxNum=99,SellPrice=100,Desc='太阳马戏团标志性的武器，耀眼的金光和精致的造型，是坚持爱与正义的冒险者所追寻的目标',Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63923}",
  [63924] = "{id=63924,NameZh='月辉·星光谢幕',Icon='item_63924',Type=320,Quality=3,MaxNum=99,SellPrice=100,Desc='暗月马戏团标志性的武器，因其式样低调而华丽又非常稀有，成为了年轻冒险家追捧的热门武器。',Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63924}",
  [63925] = "{id=63925,NameZh='炎魂·炽焰谢幕',Icon='item_63925',Type=320,Quality=3,MaxNum=99,SellPrice=100,Desc='融合红龙的灼热吐息与火焰结晶制作的来复枪，射出的子弹带着烈焰的气息。',Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63925}",
  [63926] = "{id=63926,NameZh='碎雪·永冬谢幕',Icon='item_63926',Type=320,Quality=3,MaxNum=99,SellPrice=100,Desc='融合冰龙的霜冻吐息与魔力冰晶制作的来复枪，每次出手都能让敌人瞬间结冰。',Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63926}",
  [63927] = "{id=63927,NameZh='时间谢幕',Icon='item_63927',Type=320,Quality=3,MaxNum=99,SellPrice=100,Desc='时间是不会静止的，这把来复枪却可以打破时间的禁锢，让持有者走入新纪元。',Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63927}",
  [63928] = "{id=63928,NameZh='埃琉德尼尔谢幕',Icon='item_63928',Type=320,Quality=3,MaxNum=99,SellPrice=100,Desc='“不要怕，不会感受到痛苦的。”',Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63928}",
  [63929] = "{id=63929,NameZh='永夜·破晓黄昏',Icon='item_63929',Type=320,Quality=3,MaxNum=99,SellPrice=100,Desc='黑暗之中的黑暗，能够吸收所有光芒的黑，赐予这把来复枪特别的力量。',Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63929}",
  [63930] = "{id=63930,NameZh='红鱼花铃·来复枪',Icon='item_63930',Type=320,Quality=3,MaxNum=99,SellPrice=100,Desc='长了一身红色鳞片的金鱼呀，喜欢在湖底的水草里悠闲地打瞌睡。有人投食的话，也会慢悠悠地钻到水面上，不紧不慢地吃鱼食。如果它会衔着来复枪游出水面，也不要惊讶，这是金鱼族的报答哟~',Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63930}",
  [63931] = "{id=63931,NameZh='枫忆来复枪',Icon='item_63931',Type=320,Quality=3,MaxNum=99,SellPrice=100,Desc='如深秋枫叶般火红的来复枪，带有令人心跳加快的奇妙魔力。',Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63931}",
  [63932] = "{id=63932,NameZh='月下祈者·来复枪',Icon='item_63932',Type=320,Quality=3,MaxNum=99,SellPrice=100,Desc='冰封千年的陨铁，王国的工匠们用尽办法也无法将其熔铸，却因小学徒的一次失误暴露在月光下。那一刻奇迹发生，陨铁融化宛若水银般流转，在月光下散发耀眼星辉。\n一部分陨铁溅落在旁边的来复枪，令它拥有了驱散邪祟的圣洁之力。',Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63932}",
  [63933] = "{id=63933,NameZh='科学救赎·来复枪',Icon='item_63933',Type=320,Quality=3,MaxNum=99,SellPrice=100,Desc='科学！科学！科学！为了科学一切的牺牲都是值得，蝼蚁们的生命本就毫无价值，因实验而死的他们应该觉得骄傲，这是他们的宿命！快了！就快了，只要把来复枪制作出来，我就能让那些反抗者成为我下一批的实验品……哈哈哈……',Feature=1,LoadShowSize=1,Delete=63933}",
  [63935] = "{id=63935,NameZh='王国荣辉·来复枪',Icon='item_63935',Type=320,Quality=3,MaxNum=99,SellPrice=100,Desc='效忠于王室的宫廷侍卫所持的来复枪，其上绘有卢恩王家纹章。不过，这明明是朱诺反抗军所持有的武器……为什么会流入普隆德拉呢？',LoadShowSize=1.6,LoadShowRotate=90,Delete=63935}",
  [63939] = "{id=63939,NameZh='尤佩雷斯灭龙炮·极限',Icon='item_63939',Type=464,Quality=4,MaxNum=1,SellPrice=100,Desc='超古代文明尤佩雷斯的遗产，机械大师阿尔米隆倾注半生心血制成的杰作。时至今日我们已不知道这位大师与龙族之间有何仇怨，但在诸神黄昏的大战中，这把枪收割的巨龙灵魂数以千计。',NoSale=1,NoStorage=7,TFValidDate='2022-03-10 05:00:00',ValidDate='2022-03-23 05:00:00',LoadShowPose={0,0.3,-0.35},Delete=63939}",
  [63940] = "{id=63940,NameZh='英灵信标·步枪[2]',Icon='item_63902',Type=320,Quality=2,MaxNum=99,SellPrice=100,Desc='这杆步枪是指引女武神降临、迎接英灵的道标。阵亡的勇士抱着它躺在冥舟里，就能得到女武神的垂青，被她们亲自拥入英灵殿。',NoStorage=5,Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63940}",
  [63941] = "{id=63941,NameZh='英灵羽证·步枪[2]',Icon='item_63903',Type=320,Quality=3,MaxNum=99,SellPrice=100,Desc='英灵的证明。潜入学院的女武神在这杆步枪中注入了奥丁领域的魔力。枪身长出了羽翼，好像穿梭于晴空中的雄鹰。',NoStorage=5,Feature=1,LoadShowPose={0,0.3,-0.35},Delete=63941}",
  [64200] = "{id=64200,NameZh='暴噬之刃[1]',Icon='item_64200',Type=190,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='传说是冥界主人海拉的两把镰刀之一。用于处决那些罪大恶极的亡灵，将它们的灵魂吞噬殆尽。',LoadShowSize=1,Delete=64200}",
  [64201] = "{id=64201,NameZh='万灵渊噬[1]',Icon='item_64201',Type=190,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,Desc='于冥河中淬炼千年的凶器，拥有着斩裂、吞噬一切生魂的欲望，唯有意志足够坚定的人方能驾驭，否则也将成为这柄镰刀的祭品。“给我……给我更多的灵魂！！”',LoadShowSize=1,Delete=64201}",
  [64202] = "{id=64202,NameZh='往生之刃[1]',Icon='item_64202',Type=190,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='传说是冥界主人海拉的两把镰刀之一。那些生性善良的亡灵会得到海拉的宽恕，这把镰刀将斩断他们与现世的羁绊，送他们进入轮回。',LoadShowSize=1,Delete=64202}",
  [64203] = "{id=64203,NameZh='彼岸之钥[1]',Icon='item_64203',Type=190,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,Desc='即使对于冥界的主人海拉而言，这柄镰刀也颇为神秘，它可以联结现世与冥界，为现世的灵魂提供庇护。“冥界具现，守护我的同伴——开启吧，彼岸之门！”',LoadShowSize=1,Delete=64203}",
  [64204] = "{id=64204,NameZh='夺魂镰刀[1]',Icon='item_64204',Type=190,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='可以勾取魂魄的镰刀，适合新手悟灵士使用。',LoadShowSize=1,Delete=64204}",
