  [112953] = "{id=112953,NameZh='忆之留声机·锻造典册',Icon='item_12953',Type=41,MaxNum=99,SellPrice=1,Desc='使用后解锁枫叶彼岸异宝：[忆之留声机]的制作配方',NoStorage=5,GetLimit={limit_count=1,source={10,19,54,97},type=3},Delete=112953}",
  [130000] = "{id=130000,NameZh='书架·秘藏图纸',Icon='item_30000',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130000,Desc='对于克拉拉来说，书籍就是最珍贵的宝藏。',}",
  [130001] = "{id=130001,NameZh='壁炉·流火图纸',Icon='item_30001',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=130001,Desc='克拉拉引以为傲的壁炉，透露着与小屋格格不入的华丽。似乎可以产出一些额外的材料，“低调，这叫低调的优雅。”',}",
  [130002] = "{id=130002,NameZh='沙发·时光摇椅图纸',Icon='item_30002',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130002,Desc='很多年以前，克拉拉的奶奶曾坐在这里，为她织下空中的第一朵云彩。',}",
  [130003] = "{id=130003,NameZh='柜·悠扬图纸',Icon='item_30003',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130003,Desc='上方雕有波利样式的简约长柜，优雅中又有着居家气息。',}",
  [130004] = "{id=130004,NameZh='壁灯·微光图纸',Icon='item_30004',Type=55,MaxNum=99,SellPrice=100,ComposeID=130004,Desc='黑猫给某位半夜失眠的少女制作的小灯。“怕黑就直说嘛……”',}",
  [130005] = "{id=130005,NameZh='地毯·圆溜溜绒绒图纸',Icon='item_30005',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130005,Desc='毛乎乎的地毯，经常被黑猫踩出一个个小脚印。',}",
  [130006] = "{id=130006,NameZh='地毯·“欢迎回家”图纸',Icon='item_30006',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130006,Desc='绣着字母的手工地垫，看起来有些陈旧，不知出自何人之手。密密的针脚间，满满都是缝制者的心意。',}",
  [130007] = "{id=130007,NameZh='椅·素秋图纸',Icon='item_30007',Type=55,MaxNum=99,SellPrice=100,ComposeID=130007,Desc='棉麻质地的沙发椅，在白与咖色的交错中，依稀能感到秋意。至于上面的抓痕，克拉拉说她并不知情。',}",
  [130008] = "{id=130008,NameZh='屏风·林间私语图纸',Icon='item_30008',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130008,Desc='典雅精巧的木质屏风，是克拉拉很喜欢的装饰。',}",
  [130009] = "{id=130009,NameZh='床头柜·葱葱图纸',Icon='item_30009',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130009,Desc='克拉拉和黑猫共同浇灌的小绿植，放在床头柜上，每天都有好心情~',}",
  [130010] = "{id=130010,NameZh='桌·雕刻时光图纸',Icon='item_30010',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130010,Desc='造型十分典雅的桌子，上面摆着克拉拉心爱的花瓶，精巧又优雅。',}",
  [130011] = "{id=130011,NameZh='床·沉梦图纸',Icon='item_30011',Type=55,MaxNum=99,SellPrice=100,ComposeID=130011,Desc='温暖质朴的大床。每当月亮升起，黑猫总会翘着尾巴来到床边，悄悄守护她入睡。',}",
  [130012] = "{id=130012,NameZh='窗·晨辉图纸',Icon='item_30012',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130012,Desc='无论何时都溢满了阳光的窗户，让屋内充满了生机。',}",
  [130013] = "{id=130013,NameZh='衣橱·漆夜图纸',Icon='item_30013',Type=55,MaxNum=99,SellPrice=100,ComposeID=130013,Desc='充满了古典色彩的衣橱。据说黑猫曾经窜到里面被关了一夜，所以当开关门时，衣橱会发出喵呜喵呜的声音。',}",
  [130014] = "{id=130014,NameZh='储物柜·古檀图纸',Icon='item_30014',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130014,Desc='古色古香的储物柜，看起来有些年代了。里面藏着上一任主人留下的珍宝，克拉拉怎么也打不开。',}",
  [130015] = "{id=130015,NameZh='餐桌·秋森图纸',Icon='item_30015',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=130015,Desc='圆木做成的的桌椅，被人整整齐齐摆成了一套，简洁中带着独有的清新感。',}",
  [130016] = "{id=130016,NameZh='桌·清雅图纸',Icon='item_30016',Type=55,MaxNum=99,SellPrice=100,ComposeID=130016,Desc='某个洁癖的少女每天都要把它打扫的整整齐齐，但是总会很快被黑猫弄乱。',}",
  [130017] = "{id=130017,NameZh='桌·微漾图纸',Icon='item_30017',Type=55,MaxNum=99,SellPrice=100,ComposeID=130017,Desc='整洁干净的小桌子，不过使用了光洁的木料，黑猫经常抱怨这会让他的脚底打滑……',}",
  [130018] = "{id=130018,NameZh='书桌·黄梨木图纸',Icon='item_30018',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130018,Desc='黄梨木制作成的纤细书桌，和它的主人十分相称。克拉拉经常在这里打发时间，一待就是一下午。',}",
  [130100] = "{id=130100,NameZh='床·枕梦子图纸',Icon='item_30100',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=130100,Desc='用美梦编织出的被褥，枕上就会得到一夜好眠。',}",
  [130101] = "{id=130101,NameZh='窗·照夜图纸',Icon='item_30101',Type=55,Quality=4,MaxNum=99,SellPrice=100,ComposeID=130101,Desc='倚窗凭栏处，照影夜归人。',}",
  [130102] = "{id=130102,NameZh='衣橱·绀夜图纸',Icon='item_30102',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=130102,Desc='充满日式风情的衣橱，由黄木制成。简洁大方的外表下，在保证足够空间的同时又不失巧思。',}",
  [130103] = "{id=130103,NameZh='床头柜·盎然图纸',Icon='item_30103',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130103,Desc='有了温馨的绿植点缀，让空气多了一丝自然的宁静。',}",
  [130104] = "{id=130104,NameZh='储物柜·藏心图纸',Icon='item_30104',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=130104,Desc='看起来就深不可测的储物柜。横竖纵斜之间，它到底隐藏了多少秘密呢？',}",
  [130105] = "{id=130105,NameZh='餐桌·日食录图纸',Icon='item_30105',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=130105,Desc='精致优雅的日式餐桌，好像在这里用餐，整个人的心情都会平和许多。',}",
  [130106] = "{id=130106,NameZh='壁炉·萦花火图纸',Icon='item_30106',Type=55,Quality=4,MaxNum=99,SellPrice=100,ComposeID=130106,Desc='满是日式风情的壁炉。火光跳跃间，原本冰冷的剑刃也显得温柔了起来。',}",
  [130107] = "{id=130107,NameZh='灯·胧夜明图纸',Icon='item_30107',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=130107,Desc='灯火胧夜，映路归家。挂在墙上的小壁灯，柔光间满是家人温暖的思念。',}",
  [130108] = "{id=130108,NameZh='毯·逐浪图纸',Icon='item_30108',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=130108,Desc='白与蓝交织的波浪纹地毯，触感柔软，令人如同置身于大海之上。',}",
  [130112] = "{id=130112,NameZh='椅·絮白图纸',Icon='item_30112',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130112,Desc='褐与白，直与方，最简洁的设计，也是最极致的优雅。',}",
  [130113] = "{id=130113,NameZh='屏风·月夜樱图纸',Icon='item_30113',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=130113,Desc='月落樱之瓣，遥忆梦中影。',}",
  [130114] = "{id=130114,NameZh='壁纸·远川之汐图纸',Icon='item_30114',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130114,Desc='蓝色的浪花拍打着岸边，诉说着遥远的思念。',}",
  [130115] = "{id=130115,NameZh='天花板·远空图纸',Icon='item_30115',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130115,Desc='交错于上的蓝与白，是天空的投影与海浪的回响。',}",
  [130116] = "{id=130116,NameZh='地面·行川图纸',Icon='item_30116',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130116,Desc='素雅的蓝映着纯粹之白，行走于上，如同步入了川流。',}",
  [130117] = "{id=130117,NameZh='楼梯·流云图纸',Icon='item_30117',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130117,Desc='层层回旋的阶梯仿佛云朵一般，踩在上方就像抵达了天空。',}",
  [130118] = "{id=130118,NameZh='门·展颜图纸',Icon='item_30118',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130118,Desc='风儿吹过门扉，是浪花在微笑。',}",
  [130119] = "{id=130119,NameZh='沙发·月海图纸',Icon='item_30119',Type=55,Quality=4,MaxNum=99,SellPrice=100,ComposeID=130119,Desc='以海中浪花为灵感设计的沙发，白色的靠垫如同云朵，柔软舒适且充满了静谧的气息。',}",
  [130120] = "{id=130120,NameZh='书桌·修雅图纸',Icon='item_30120',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=130120,Desc='沏一壶热茶，画一卷山水，万物尽在方寸之上。',}",
  [130121] = "{id=130121,NameZh='桌·盏茶图纸',Icon='item_30121',Type=55,Quality=4,MaxNum=99,SellPrice=100,ComposeID=130121,Desc='清新的茶香萦绕着古朴沉木，一同构成了这份古典与优雅。',}",
  [130122] = "{id=130122,NameZh='装饰·喵太郎图纸',Icon='item_30122',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=130122,Desc='“叮叮咚咚，福缘来到！”传说只要每天摇一摇喵太郎的铃铛，好运就会来到家中。',}",
  [130200] = "{id=130200,NameZh='衣柜·少女的裙摆图纸',Icon='item_30200',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=130200,Desc='虽然已经是个很大的衣柜，但是完全不够塞。不要再问她为什么有这么多衣服了，以后只会越来越多……',}",
  [130201] = "{id=130201,NameZh='柜·舒芙蕾泡沫图纸',Icon='item_30201',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=130201,Desc='“兔先生说了，抽屉里并没有藏着甜点！”',}",
  [130202] = "{id=130202,NameZh='储物柜·糖霜图纸',Icon='item_30202',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=130202,Desc='精巧优雅的储物柜，里面藏满了她收集来的小东西。“老实交代，你究竟买了多少毛绒娃娃？”',}",
  [130203] = "{id=130203,NameZh='餐桌·浪漫回忆图纸',Icon='item_30203',Type=55,Quality=4,MaxNum=99,SellPrice=100,ComposeID=130203,Desc='虽然这个餐桌很可爱，但是在这里吃饭是不会让你瘦下去的！',}",
  [130204] = "{id=130204,NameZh='壁炉·爱恋心跳图纸',Icon='item_30204',Type=55,Quality=4,MaxNum=99,SellPrice=100,ComposeID=130204,Desc='寒冷的冬夜怎么能缺少壁炉呢？暖暖的火苗映着跳跃的爱心，是心动的讯号。',}",
  [130205] = "{id=130205,NameZh='书架·少女的心事图纸',Icon='item_30205',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=130205,Desc='她的心事和这里的书一样多，数也数不完……',}",
