  [130705] = "{id=130705,NameZh='优等生课桌图纸',Icon='item_30705',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130705,Desc='干净、整洁的课桌，看来他的主人是一位优等生，可是为什么一本书都没有呢...',Feature=1,}",
  [130706] = "{id=130706,NameZh='落寞讲台图纸',Icon='item_30706',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=130706,Desc='入学后从来没有发挥过作用，只被当作涂鸦板的可怜讲台。',Feature=1,}",
