  [130710] = "{id=130710,NameZh='违禁品收纳柜图纸',Icon='item_30710',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130710,Desc='只要被认定为“违禁”之物，那么必然无法逃脱被关入其中的命运。',Feature=1,}",
  [130711] = "{id=130711,NameZh='班级护卫图纸',Icon='item_30711',Type=55,MaxNum=99,SellPrice=100,ComposeID=130711,Desc='默默守护班级的扫帚，平常清洁卫生，偶尔被抡起来当作武器。',Feature=1,}",
  [130712] = "{id=130712,NameZh='泡泡水壶图纸',Icon='item_30712',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130712,Desc='负责浇花的值日生迷上涂鸦后，它就变得五颜六色了起来。',Feature=1,}",
  [130713] = "{id=130713,NameZh='超精准红外探测仪图纸',Icon='item_30713',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=130713,Desc='本来是学园的下课铃，后来被改造成侦察班主任动向的探测仪。',Feature=1,}",
  [130714] = "{id=130714,NameZh='知心哥哥木桩图纸',Icon='item_30714',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130714,Desc='学园中人气很高的大哥哥，温柔地接纳你所有的负面情绪。',Feature=1,}",
  [130715] = "{id=130715,NameZh='教导主任的画像图纸',Icon='item_30715',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130715,Desc='虽然本人不怎么受学员欢迎，但他的画像意外拥有与知心哥哥不相上下的人气。',Feature=1,}",
  [130716] = "{id=130716,NameZh='永久缺席画像图纸',Icon='item_30716',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130716,Desc='学园七大不可思议之一，出现在画像上的人必定会缺席毕业典礼。',Feature=1,}",
  [130717] = "{id=130717,NameZh='神秘转学生的课桌图纸',Icon='item_30717',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=130717,Desc='在第二学期突然转学过来的神秘人物用的课桌，至今没人见过它的主人。',Feature=1,}",
  [130718] = "{id=130718,NameZh='番长杂物柜图纸',Icon='item_30718',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130718,Desc='学园最强不良生的储物柜，总是塞满了情书和挑战书。',Feature=1,}",
  [130719] = "{id=130719,NameZh='寂寞的课桌图纸',Icon='item_30719',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130719,Desc='虽然学员们总是不爱惜课桌，但在假期时它总会想念那些年轻的主人。',Feature=1,}",
  [130720] = "{id=130720,NameZh='学园情报交流中心图纸',Icon='item_30720',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130720,Desc='不论有多少消息都能写得下的神奇便签板。',Feature=1,}",
  [130721] = "{id=130721,NameZh='自由牢笼图纸',Icon='item_30721',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130721,Desc='“隔着这扇窗户看向外面，感觉自己就像被锁在这学园的囚徒。”',Feature=1,}",
  [130722] = "{id=130722,NameZh='大嗓门叭叭图纸',Icon='item_30722',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=130722,Desc='教师讲课、不良生宣战、爱的告白都会麻烦这位大忙人，导致它最近一直在寻找喉宝片。',Feature=1,}",
  [130723] = "{id=130723,NameZh='无上荣誉奖状图纸',Icon='item_30723',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=130723,Desc='被教导主任视为学园最高荣誉的奖状，叠出的纸飞机比一般货色飞得更高。',Feature=1,}",
  [130724] = "{id=130724,NameZh='勇气垃圾桶图纸',Icon='item_30724',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=130724,Desc='曾经那些未能传达的感情都被揉成一团丢了进去，或许叫缺乏勇气垃圾桶更合适...',Feature=1,}",
  [131100] = "{id=131100,NameZh='积雪覆盖的楼梯图纸',Icon='item_31100',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=131100,Feature=1,}",
  [131101] = "{id=131101,NameZh='冰凌星窗图纸',Icon='item_31101',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=131101,Desc='冰星与梦编织而成这剔透的星窗，愿你可以透过它看望向美好。',Feature=1,}",
  [131102] = "{id=131102,NameZh='冰凌星架图纸',Icon='item_31102',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131102,Desc='你可曾阅读过关于冰雪的故事，拿起书架上的书籍，进入到冰雪的世界中，享受这场关于冰雪的梦。',Feature=1,}",
  [131103] = "{id=131103,NameZh='冰凌星栏图纸',Icon='item_31103',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=131103,Desc='冰霜与星梦遮挡不住你的美好，透过这屏风，又会有怎样怡人的景色呢？',Feature=1,}",
  [131104] = "{id=131104,NameZh='绒绒雪怪沙发图纸',Icon='item_31104',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=131104,Desc='毛绒绒的雪怪为你在这充斥寒意的日子里增添一丝温暖，躺在上面不由得让你深陷其中，冒险什么的，明天再说啦~',Feature=1,}",
  [131105] = "{id=131105,NameZh='盛开的冰泉图纸',Icon='item_31105',Type=55,Quality=4,MaxNum=99,SellPrice=100,ComposeID=131105,Desc='不同于湍流不息的泉水一样活泼而美好，停驻雕花的冰泉有着异样的风情，冰雪的美丽与泉水交织缠绕，诉说着一首冬季恋歌。',Feature=1,}",
  [131106] = "{id=131106,NameZh='冰星花·铃图纸',Icon='item_31106',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131106,Desc='生长，发芽，艳丽的绽放在这冬日这种，不似温室的娇花，冰霜中的花朵有着特有的芬芳，那是坚韧的味道。',Feature=1,}",
  [131107] = "{id=131107,NameZh='冰星花·兰图纸',Icon='item_31107',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131107,Desc='淡雅而内敛，芳香清远而悠长，让 人在若有若无之间沉溺其中不能自拔。',Feature=1,}",
  [131108] = "{id=131108,NameZh='冰翼星梯图纸',Icon='item_31108',Type=55,Quality=5,MaxNum=99,SellPrice=100,ComposeID=131108,Desc='冰雪的魅力在滑梯体现到极致，松软的白雪构成滑梯的羽翼，冰霜为滑梯的表面镀上了一层星光，滑梯承载的不仅是欢笑，还是那段难忘的回忆。',Feature=1,}",
  [131109] = "{id=131109,NameZh='雪人哈恩图纸',Icon='item_31109',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=131109,Desc='在寒冷的冬季，雪人哈恩在大雪中奔波着，一直寻找着真正的朋友，因为他相信，只要在真正的朋友身边，他就永远都不会融化。',Feature=1,}",
  [131110] = "{id=131110,NameZh='雪花制造机图纸',Icon='item_31110',Type=55,Quality=5,MaxNum=99,SellPrice=100,ComposeID=131110,Desc='一份冰霜一份星光，两种东西混合在一起，加上最美好的心意，在机器的带动下缠绕交织，制造出一份份璀璨的冰晶雪花。',Feature=1,}",
  [131200] = "{id=131200,NameZh='隐夕图纸',Icon='item_31200',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=131200,Desc='赏心悦目的对称设计，上等的用料，还有风雅的梅兰竹菊四君子图，可谓美观与实用兼备。',}",
  [131201] = "{id=131201,NameZh='椅·悠霞图纸',Icon='item_31201',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131201,Desc='云淡风轻间，闲适的时光缓缓流淌，意识也随着轻柔的摇曳开始漫游。',}",
  [131203] = "{id=131203,NameZh='居游图纸',Icon='item_31203',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131203,Desc='小桥流水，茂林修竹的景色都在这扇窗中成为最动人的画作。',}",
  [131204] = "{id=131204,NameZh='灯·烛夜图纸',Icon='item_31204',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131204,Desc='纸帐中摇曳的烛火，是那未有归期的漂泊者的心之所向。',}",
  [131205] = "{id=131205,NameZh='星眠图纸',Icon='item_31205',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131205,Desc='夜深了，静谧中是昏暗的烛光，映出思念的形状。',}",
  [131206] = "{id=131206,NameZh='桌·茶韵图纸',Icon='item_31206',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131206,Desc='岭云间甘醇清香的新芽，只为最交心的友人奉上。典雅的茶桌上，茗香沁人心脾。',}",
  [131207] = "{id=131207,NameZh='夕照图纸',Icon='item_31207',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131207,Desc='主打暖色系的地毯，加入花与叶的元素，触感舒适，华贵而不失大气。',}",
  [131208] = "{id=131208,NameZh='桌·团圆图纸',Icon='item_31208',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=131208,Desc='沉稳低调的设计，上等的木材，花纹精致的桌布配上丰盛可口的佳肴，家人团聚的幸福尽在这里。',}",
  [131210] = "{id=131210,NameZh='床·橙空图纸',Icon='item_31210',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=131210,Desc='整体采用夕阳的意象，床灯宛如西沉的落日，床体选用高级红木，床褥松软有弹性，温柔地包裹身体，带给人一个好梦。',}",
  [131211] = "{id=131211,NameZh='福语·上图纸',Icon='item_31211',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131211,Desc='用最迷人的金色，一笔一划写下最诚挚的祝福。',}",
  [131212] = "{id=131212,NameZh='福语·下图纸',Icon='item_31212',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131212,Desc='用最迷人的金色，一笔一划写下最诚挚的祝福。',}",
  [131213] = "{id=131213,NameZh='灯·暖枫图纸',Icon='item_31213',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131213,Desc='灯罩上的枫叶装饰富有季节感，吊垂的流苏平添几分秀丽。暖黄色的灯光，照亮了脚下的路，也温暖了行路者的心。',}",
  [131215] = "{id=131215,NameZh='游龙图纸',Icon='item_31215',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131215,Desc='流畅的整体造型，精致的雕花，将自己心爱的宝物陈列在此，室内雅趣又多几分。',}",
  [131216] = "{id=131216,NameZh='花舞图纸',Icon='item_31216',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131216,Desc='温婉的曲线，自然的木色，与摆放的盆景一同为观者带来平静的心情。',}",
  [131217] = "{id=131217,NameZh='椅·闲梦图纸',Icon='item_31217',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131217,Desc='椅背的造型灵动富有神采，舒适的的坐垫与脚垫，让人不禁想躺上去小憩一阵。',}",
  [131218] = "{id=131218,NameZh='椅·食逸图纸',Icon='item_31218',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131218,Desc='椅背完美贴合身体，扶手的大曲线富有美感。坐在这样的椅子上就餐，想必十分愉快。',}",
  [131219] = "{id=131219,NameZh='相伴图纸',Icon='item_31219',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131219,Desc='展开画卷，映入眼帘的是庄严的国王波利和可爱的天使波利，两只相伴的温馨一幕感染着看到这幅画作的每个人。',}",
  [131220] = "{id=131220,NameZh='椅·正心图纸',Icon='item_31220',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=131220,Desc='椅子透出一种庄重感，坐在上面似乎感到自己气势如虹。',}",
  [131221] = "{id=131221,NameZh='留锋图纸',Icon='item_31221',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131221,Desc='贵重的武器怎能随意放置？当然要妥善保管。此架体阶梯式的设计让武器陈列显得气势十足。',}",
  [131222] = "{id=131222,NameZh='墨明图纸',Icon='item_31222',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131222,Desc='造型匠心独具的书卷缸。因为常年装满书画而留下怡人的墨香，与缸本身的木香结合，散发出一种奇妙的芬芳。',}",
  [131223] = "{id=131223,NameZh='青浪图纸',Icon='item_31223',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131223,Desc='釉彩素雅怡人，附上浪花与波利花纹，是一只十分别致的花瓶。',}",
  [131224] = "{id=131224,NameZh='桌·展墨图纸',Icon='item_31224',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=131224,Desc='方寸间的黑白世界，在平整的桌面上丰富起来。',}",
  [131225] = "{id=131225,NameZh='清影图纸',Icon='item_31225',Type=55,Quality=4,MaxNum=99,SellPrice=100,ComposeID=131225,Desc='水池与盘龙的造型巧妙结合，潺潺流水，浮云飘动，闲适心情自在此。',}",
  [131226] = "{id=131226,NameZh='竹趣图纸',Icon='item_31226',Type=55,Quality=4,MaxNum=99,SellPrice=100,ComposeID=131226,Desc='微风拂来，竹海涛声四起。那憨态可掬的生灵在竹海中畅游，好不惬意。',}",
  [131227] = "{id=131227,NameZh='暗香图纸',Icon='item_31227',Type=55,Quality=4,MaxNum=99,SellPrice=100,ComposeID=131227,Desc='傲骨的花朵俏丽绽放，严寒中一阵幽然暗香。飞舞的花瓣不以己悲，因为山花烂漫的美好春光即将来临。',}",
  [131228] = "{id=131228,NameZh='香炉·紫烟图纸',Icon='item_31228',Type=55,Quality=4,MaxNum=99,SellPrice=100,ComposeID=131228,Desc='熠熠生辉的金色香炉，配上造型沉稳流畅的檀木底座，紫烟氤氲，尽显高贵气质。',}",
  [131229] = "{id=131229,NameZh='飞焰图纸',Icon='item_31229',Type=55,Quality=4,MaxNum=99,SellPrice=100,ComposeID=131229,Desc='烟花宛如飞龙衔珠，升空的宝珠在夜空绽放，燃尽自己，只为那转瞬即逝的美。',}",
  [131230] = "{id=131230,NameZh='金枫图纸',Icon='item_31230',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131230,Desc='对称的墙柱与雕花营造出古典之美，摇曳的烛光从镂空烛台透出，墙柱上的金漆绽放出迷人的光彩。',}",
  [131231] = "{id=131231,NameZh='地板·方寸之间图纸',Icon='item_31231',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131231,Desc='将规律之美发挥到极致，在脚下拼接出一幅精美的画作。',}",
  [131232] = "{id=131232,NameZh='枫语木心图纸',Icon='item_31232',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131232,Desc='木料的选用充分考虑了防潮防腐，坚实耐用，缓缓登上楼梯，沉稳的声音带来一种安心感。',}",
  [131233] = "{id=131233,NameZh='天花板·木穹图纸',Icon='item_31233',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131233,Desc='橙黄渐变的门帘，犹如夕阳西下的天空。门板上是古朴的线条花纹，方与圆之间达到了最和谐的平衡。',}",
  [131234] = "{id=131234,NameZh='落日长影图纸',Icon='item_31234',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131234,Desc='充满自然气息的木材上，几笔金线勾勒出规整的美，搭配地板，营造出一个沉静安详的美妙空间。',}",
  [131301] = "{id=131301,NameZh='床·金色暖夜图纸',Icon='item_31301',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=131301,Desc='松软的床垫，实木用料配上暖色系的寝具，充裕的空间足够舒展身体，满满的都是安心感。',}",
  [131302] = "{id=131302,NameZh='沙发·遐思图纸',Icon='item_31302',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131302,Desc='将身体沉入轻柔的守护中，一天的疲劳与不快就此烟消云散。难得的闲适时光,让心灵得到平静。',}",
  [131303] = "{id=131303,NameZh='椅·雅正图纸',Icon='item_31303',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131303,Desc='中正而有棱有角的设计，让这把椅子带上一种浑然天成的威严，不由得让人正襟危坐。',}",
  [131304] = "{id=131304,NameZh='桌·墨雅图纸',Icon='item_31304',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=131304,Desc='笔下是一片清香的墨迹，思绪却早已随着笔墨飞往了远方。',}",
  [131305] = "{id=131305,NameZh='墨宇图纸',Icon='item_31305',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=131305,Desc='古朴的木色，典雅的设计，书卷的墨香为房间平添一份情趣。',}",
  [131306] = "{id=131306,NameZh='秘景图纸',Icon='item_31306',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131306,Desc='幽幽夜幕下，屏风前出现的人影勾起无限的遐想——那熟悉的身影究竟是谁？',}",
  [131307] = "{id=131307,NameZh='弈趣图纸',Icon='item_31307',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=131307,Desc='方寸之间，黑与白构成世间最深邃的哲理，徜徉在无限的可能性中，那是无尽的宇宙。',}",
  [131308] = "{id=131308,NameZh='灯·伴明图纸',Icon='item_31308',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131308,Desc='夜已深，摇曳的灯火撒满了整个房间。朦胧的光亮中，是自己映在墙上的是自己孤独的身影。',}",
  [131309] = "{id=131309,NameZh='秋爽图纸',Icon='item_31309',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=131309,Desc='秋日澄澈的天空下，金灿灿的叶为这个时节添上一笔耀眼的色彩。',}",
  [131310] = "{id=131310,NameZh='窗·夕影图纸',Icon='item_31310',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131310,Desc='窗外眩目的橙色光芒，透过朦胧的窗，微微染红了窗边人的脸颊。窗栏将外界的景色做了一次精心的装裱。',}",
  [131311] = "{id=131311,NameZh='画·青山龙境图纸',Icon='item_31311',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131311,Desc='神龙的力量滋养了山川大地，画中的龙目光炯炯有神，仿佛下一秒就要跑出画卷，现身于此。',}",
  [131312] = "{id=131312,NameZh='心源图纸',Icon='item_31312',Type=55,MaxNum=99,SellPrice=100,ComposeID=131312,Desc='装载着香醇的美酒，在岁月的沉淀中留下了沧桑的痕迹，但也有了愈发宽广的胸怀。',}",
  [131313] = "{id=131313,NameZh='竹歌图纸',Icon='item_31313',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131313,Desc='素雅的色彩，舒适的面料，富有规则性的拼接，简朴而充满情调。',}",
  [131314] = "{id=131314,NameZh='纳忆图纸',Icon='item_31314',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=131314,Desc='合理美观的布局设计，最大化创造收纳空间，蕴藏美好回忆的宝贝都在这里安睡着呢。',}",
  [131315] = "{id=131315,NameZh='夕海图纸',Icon='item_31315',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131315,Desc='温柔的浅色打底，加上精美的镂花装饰，让人产生一种在海边凭栏观海的遐想。',}",
  [131316] = "{id=131316,NameZh='夕照之花图纸',Icon='item_31316',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131316,Desc='与地板相呼应的配色和花纹，为房间带来完美的一体感。',}",
  [131317] = "{id=131317,NameZh='雅步图纸',Icon='item_31317',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=131317,Desc='精致的雕花，迷人的花纹点缀，辅之以上等的木料，连脚步声都是美妙的鼓点。',}",
  [131318] = "{id=131318,NameZh='木暖图纸',Icon='item_31318',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=131318,Desc='不经意间抬头一望，对称的花纹与温柔的木色让整个房间充满了温馨。',}",
  [131319] = "{id=131319,NameZh='门·暮忧图纸',Icon='item_31319',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131319,Desc='典雅的线条，温暖的色调。轻轻推开门扉，那个人会在吗？',}",
  [131400] = "{id=131400,NameZh='墙纸·静夜图纸',Icon='item_31400',Type=55,MaxNum=99,SellPrice=100,ComposeID=131400,Desc='幽蓝的墙壁，镶嵌白银装饰的镂花装饰，令人快速进入沉静的梦乡。',}",
  [131401] = "{id=131401,NameZh='地板·月光蝶图纸',Icon='item_31401',Type=55,MaxNum=99,SellPrice=100,ComposeID=131401,Desc='经过附魔的特殊地板，华丽的魔纹在夜晚吸收月光，在白天释放，增强室内光照。',}",
  [131402] = "{id=131402,NameZh='楼梯·摘星图纸',Icon='item_31402',Type=55,MaxNum=99,SellPrice=100,ComposeID=131402,Desc='拾阶而上，步入星空，与群星为伴。',}",
  [131403] = "{id=131403,NameZh='门·星森之风图纸',Icon='item_31403',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131403,Desc='打开门扉，让风儿吹进来，带来森林的低语。',}",
  [131404] = "{id=131404,NameZh='窗·花萦小筑图纸',Icon='item_31404',Type=55,MaxNum=99,SellPrice=100,ComposeID=131404,Desc='将小屋修建在林间，在鲜花绿草的萦绕间，安闲地度过悠长假期！',}",
  [131405] = "{id=131405,NameZh='床·林荫之梦图纸',Icon='item_31405',Type=55,Quality=4,MaxNum=99,SellPrice=100,ComposeID=131405,Desc='躺在树荫下，让花香、月色与虫鸣带你进入美妙的梦乡。',}",
  [131406] = "{id=131406,NameZh='灯·星炬图纸',Icon='item_31406',Type=55,MaxNum=99,SellPrice=100,ComposeID=131406,Desc='能够聚集星光的灯具，一颗星星的光芒或许很微弱，但无数颗星星聚集起来，就能点亮整片夜空。',}",
  [131407] = "{id=131407,NameZh='桌·书海探秘图纸',Icon='item_31407',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131407,Desc='为什么有四季交替？秋叶为何飘落？天空中有多少星星？它们白天又去了哪里？这世间有那么多问题等待着我们探索——到知识的海洋中寻找答案吧！',}",
  [131408] = "{id=131408,NameZh='沙发·沉思者图纸',Icon='item_31408',Type=55,MaxNum=99,SellPrice=100,ComposeID=131408,Desc='倚在躺椅上，与星辰共鸣，化身沉思者，探索关于世界最深邃的哲理。',}",
  [131409] = "{id=131409,NameZh='餐桌·森林的馈赠图纸',Icon='item_31409',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=131409,Desc='野果、清泉与果酒，这是森林的馈赠——在星空之下享用原生态的美食吧！',}",
  [131410] = "{id=131410,NameZh='地毯·仲夏夜空图纸',Icon='item_31410',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131410,Desc='使用时间花园的稀有植物纤维织造的高档地毯，触感宛如夏夜拂面的晚风。',}",
  [131411] = "{id=131411,NameZh='浴缸·星海图纸',Icon='item_31411',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131411,Desc='畅游在星海之中，让星辰之力涤清你的疲劳。',}",
  [131412] = "{id=131412,NameZh='雕像·星愿图纸',Icon='item_31412',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=131412,Desc='传说对着流星许愿，愿望就会成真——而这尊手捧陨星的雕像完美解决了流星消逝太快来不及许愿的问题。',}",
  [131413] = "{id=131413,NameZh='墙饰·鹿灵图纸',Icon='item_31413',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=131413,Desc='以森林的守护者鹿灵为原型制作的壁挂，传说能够保护家宅平安。',}",
  [131901] = "{id=131901,NameZh='沙发·会客沙发图纸',Icon='item_31901',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131901,Desc='皇宫会客室同款沙发，从浮夸的装饰来看——确实是那些贵族们会喜欢的风格呢！',}",
  [131902] = "{id=131902,NameZh='柜·私家珍藏图纸',Icon='item_31902',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131902,Desc='听说那些平日里光鲜亮丽的贵族们总有些不为人知的小癖好，不知这个柜子里会藏着些什么呢？',}",
  [131903] = "{id=131903,NameZh='灯·宫廷壁灯图纸',Icon='item_31903',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131903,Desc='黄金打造的奢华壁灯，连作为点缀的水晶都价值不菲，或许够平民家庭好几年的日常开销。',}",
  [131904] = "{id=131904,NameZh='桌·欢宴图纸',Icon='item_31904',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131904,Desc='盛宴开始，宾主尽欢——要时刻记得贵族的进餐礼仪哦！',}",
  [131905] = "{id=131905,NameZh='桌·勤政图纸',Icon='item_31905',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131905,Desc='使用优质木材打造的华丽书桌，用它办公会大大提高效率。（或许吧！）',}",
  [131906] = "{id=131906,NameZh='地毯·君临之地图纸',Icon='item_31906',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131906,Desc='立足之地，即是王国的疆土！',}",
  [131907] = "{id=131907,NameZh='摆件·骑士摇摇乐图纸',Icon='item_31907',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131907,Desc='为了王国，冲锋！！“嘎吱……嘎吱……”',}",
  [131908] = "{id=131908,NameZh='植物·波斯菊盆景图纸',Icon='item_31908',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131908,Desc='用紫罗兰妆点的华丽盆景，彰显着王室的高贵。',}",
  [131909] = "{id=131909,NameZh='植物·紫罗兰盆景图纸',Icon='item_31909',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131909,Desc='用波斯菊妆点的华丽盆景，彰显着王室的高贵。',}",
  [131910] = "{id=131910,NameZh='壁挂·荣耀盾徽图纸',Icon='item_31910',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131910,Desc='国王授予的盾形家徽，象征着贵族的荣誉。',}",
  [131911] = "{id=131911,NameZh='壁挂·国王波利画像图纸',Icon='item_31911',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131911,Desc='据说只要把国王波利的画像挂在家里，命运合成的时候会有好运加持。',}",
  [131912] = "{id=131912,NameZh='藏品·最高机密图纸',Icon='item_31912',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131912,Desc='上一个想要窥探其中秘密的人已经杳无音讯了……',}",
  [131913] = "{id=131913,NameZh='藏品·微缩城堡图纸',Icon='item_31913',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131913,Desc='一座精致的城堡模型，样式是典型的王国贵族庄园。',}",
  [131914] = "{id=131914,NameZh='藏品·王权永恒图纸',Icon='item_31914',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131914,Desc='展柜中陈列着王冠与权杖的仿制品。最好不要让其他人看到这些藏品，否则很可能面临“意图篡位谋反”的指控。',}",
  [131915] = "{id=131915,NameZh='藏品·典礼竖琴图纸',Icon='item_31915',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131915,Desc='宫廷乐团使用的竖琴，常在典礼时作为伴奏使用。',}",
  [131916] = "{id=131916,NameZh='窗·高阁之雀图纸',Icon='item_31916',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=131916,Desc='推开这扇窗户，会不会遇到唱着歌、渴望自由的公主呢？',}",
