  [138000] = "{id=138000,NameZh='猫头鹰烛台图纸',Icon='item_38000',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=138000,Desc='猫头鹰先生给您端蜡烛啦~可爱满分，明亮加倍！',}",
  [138001] = "{id=138001,NameZh='烛台·心焰图纸',Icon='item_38001',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=138001,Desc='它知道，自己的使命只是无尽的燃烧。',}",
  [138002] = "{id=138002,NameZh='喷泉·甜蜜布丁图纸',Icon='item_38002',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=138002,Desc='造型神似布丁的小喷泉，上方的爱心装饰更显甜蜜。真的不可以吃吗？',}",
  [138003] = "{id=138003,NameZh='喷泉·波利下午茶图纸',Icon='item_38003',Type=55,Quality=4,MaxNum=99,SellPrice=100,ComposeID=138003,Desc='糟糕，茶杯里怎么跑进去一只波利？你以为是下午茶，其实我是喷泉哒！',}",
  [138004] = "{id=138004,NameZh='意念之靶图纸',Icon='item_38004',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=138004,Desc='你已经是个成熟的靶子了，应该可以用意念打出十环才对。',}",
  [138005] = "{id=138005,NameZh='乘风起航图纸',Icon='item_38005',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=138005,Desc='虽然只是雕像，但已经能想象它在海上扬帆破浪的气势了。“教练，我想学开船！”，试着去祈祷，可能会出现神奇的事情！',}",
  [138006] = "{id=138006,NameZh='盆景·云青图纸',Icon='item_38006',Type=55,MaxNum=99,SellPrice=100,ComposeID=138006,Desc='幽静生长的绿叶，给空气中带来一丝禅意。',}",
  [138007] = "{id=138007,NameZh='盆景·葱茏图纸',Icon='item_38007',Type=55,MaxNum=99,SellPrice=100,ComposeID=138007,Desc='青翠可爱的绿叶，一呼一吸尽是清新！',}",
  [138008] = "{id=138008,NameZh='盆景·向阳图纸',Icon='item_38008',Type=55,MaxNum=99,SellPrice=100,ComposeID=138008,Desc='开满了向阳花的盆景，充满了活力与朝气。',}",
  [138009] = "{id=138009,NameZh='盆景·扇叶图纸',Icon='item_38009',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=138009,Desc='扇叶随风微荡，繁茂青葱，惹人喜爱。',}",
  [138010] = "{id=138010,NameZh='花簇·金色幻想图纸',Icon='item_38010',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=138010,Desc='非常珍贵的金色玫瑰花，象征着充满希望的晨曦。',}",
  [138011] = "{id=138011,NameZh='花簇·月下美人图纸',Icon='item_38011',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=138011,Desc='由黄与紫月季组成的花束，仿佛月中等待恋人的纯洁少女。',}",
  [138012] = "{id=138012,NameZh='花簇·粉白情书图纸',Icon='item_38012',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=138012,Desc='粉与白的蔷薇就像年少时的心事，怀恋间满是甜蜜。',}",
  [138013] = "{id=138013,NameZh='花簇·星空紫罗兰图纸',Icon='item_38013',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=138013,Desc='月色星空下那一束紫罗兰的低语，是被谁放在了她的窗前？',}",
  [138014] = "{id=138014,NameZh='绿植·清微图纸',Icon='item_38014',Type=55,Quality=3,MaxNum=99,SellPrice=100,ComposeID=138014,Desc='一盆看起来很普通的盆栽，但散发着不可思议的清新气息，能让接近它的人心情舒畅。',}",
