  [138016] = "{id=138016,NameZh='俯瞰风景图纸',Icon='item_38016',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=138016,Desc='由著名的画师德兰·克雷斯坦绘制的一组壁画，记录了米德加尔特大陆上各处迷人的景象。据说曾在拍卖行被拍出天价，但一夜之间被怪盗团窃走了。无人知道为何它会出现在这里……',}",
  [138018] = "{id=138018,NameZh='回忆相框图纸',Icon='item_38018',Type=55,Quality=2,MaxNum=99,SellPrice=100,ComposeID=138018,Desc='充满了回忆的朴素相框。看起来很久都没有人替换过相片。',}",
