  [139000] = "{id=139000,NameZh='莱茵河之畔图纸',Icon='item_39000',Type=55,Quality=5,MaxNum=99,SellPrice=100,ComposeID=139000,Desc='天鹅绒夫人精心设计，欧洲复古造型的大理石浴缸。精致中带着骄傲的慵懒感，单是看着，都能感觉到铺面而来的玫瑰香气……',}",
  [139001] = "{id=139001,NameZh='贝壳喵秘藏图纸',Icon='item_39001',Type=55,Quality=5,MaxNum=99,SellPrice=100,ComposeID=139001,Desc='宝箱边上为什么会有游泳圈？！愤怒的黑猫探出头说明了一切：这里原是它的藏宝地，却被贪玩的小魔女据为己有，原本玩耍的地盘也被改造成了泡澡圣地……',}",
  [139002] = "{id=139002,NameZh='心想事成镜图纸',Icon='item_39002',Type=55,Quality=5,MaxNum=99,SellPrice=100,ComposeID=139002,Desc='“由伟大的魔法精灵黄金波利看守的魔镜，包含了可以实现一切愿望的魔法。开启之时，也许就是世界毁灭的伊始……喂！喂！！不要随便拉开门把手！！！”',}",
  [139003] = "{id=139003,NameZh='晃悠悠秋千图纸',Icon='item_39003',Type=55,Quality=5,MaxNum=99,SellPrice=100,ComposeID=139003,Desc='精致可爱的秋千架，一到午后就会有很多波利前来休息，有时他们也会和冒险者一起玩耍。“晃悠悠的波利晃悠悠的心，晃悠悠的秋千坐着你和我！”',}",
  [139004] = "{id=139004,NameZh='噼啪锅炉图纸',Icon='item_39004',Type=55,Quality=5,MaxNum=99,SellPrice=100,ComposeID=139004,Desc='普隆德拉皇家料理师的专用锅炉，可以做出蒸羊羔蒸熊掌蒸鹿尾和……蒸馒头等美味！',}",
