  [140027] = "{id=140027,NameZh='击龙枪[2]',Icon='item_40027',Type=170,Quality=3,MaxNum=99,SellPrice=100,Desc='能够轻松破除地龙坚硬鳞甲的长矛。',Feature=1,}",
