  [140034] = "{id=140034,NameZh='锥骑枪[2]',Icon='item_40034',Type=170,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1176,Desc='骑兵最喜欢使用的长柄枪，可活用于长距离冲刺攻击，造成巨大的伤害。',Feature=1,}",
  [140036] = "{id=140036,NameZh='圣徒之矛[2]',Icon='item_40036',Type=170,Quality=3,MaxNum=99,SellPrice=100,Desc='圣歌教会曾经的荣耀，神圣骑士卡德罗的长矛。在卡德罗叛出圣歌教会后，而这柄长矛被封存在教会的地下兵器库之中，直到最近才被作为样品大量制造，用于装备日趋强大的教会骑士团。受到光明圣徒的祝福，安全精炼时消耗的装备件数减少一半。',Feature=1,}",
  [140038] = "{id=140038,NameZh='青铁柱枪[2]',Icon='item_40038',Type=170,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1176,Desc='精铁打造的双手矛，短小易持却威力强大，搭配枪筒也可做长矛使用。',Feature=1,}",
  [140040] = "{id=140040,NameZh='皇家刺枪[2]',Icon='item_40009',Type=170,MaxNum=99,SellPrice=1140,Desc='普隆德拉皇家卫兵专用的刺枪，采用了最顶级的红铜枪柄和雪花白银枪尖，十分锋利。',Level=95,}",
  [140041] = "{id=140041,NameZh='风暴之枪[2]',Icon='item_40041',Type=170,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=11520,Desc='通晓大气流动之理的风之精灵啊，撕裂敌人吧！',Feature=1,}",
  [140042] = "{id=140042,NameZh='永恒之枪[2]',Icon='item_40042',Type=170,MaxNum=99,SellPrice=100,Desc='主神奥丁曾使用过的武器，全名冈格尼尔，意为贯穿一切。它本身具有神性，任何对枪尖所发的誓言，都永不可反悔且必定实现。',Feature=1,}",
  [140043] = "{id=140043,NameZh='永恒之枪2[2]',Icon='item_40043',Type=170,MaxNum=99,SellPrice=100,Desc='主神奥丁曾使用过的武器，全名冈格尼尔，意为贯穿一切。它本身具有神性，任何对枪尖所发的誓言，都永不可反悔且必定实现。',Feature=1,}",
  [140044] = "{id=140044,NameZh='永恒之枪3[2]',Icon='item_40044',Type=170,MaxNum=99,SellPrice=100,Desc='主神奥丁曾使用过的武器，全名冈格尼尔，意为贯穿一切。它本身具有神性，任何对枪尖所发的誓言，都永不可反悔且必定实现。',Feature=1,}",
  [140047] = "{id=140047,NameZh='驯龙者长枪[2]',Icon='item_40047',Type=170,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4800,Desc='以传说中的龙骑士持有的长枪为原型而诞生武器，所以被冠上“驯龙者”的称谓。适合迅猛的突击，手感沉稳结实，是武器中不可多得的精品。“年轻人，拿上它去创造新的传说吧！”——某个传奇铁匠',Feature=1,}",
  [140048] = "{id=140048,NameZh='守备军长矛[2]',Icon='item_40048',Type=170,MaxNum=99,SellPrice=2000,Level=90,}",
  [140053] = "{id=140053,NameZh='亡灵长矛[2]',Icon='item_40053',Type=170,MaxNum=99,SellPrice=2100,Desc='这把长矛带着亡灵的怨念，请戴上手套使用它。',Level=95,}",
  [140055] = "{id=140055,NameZh='斧锤长矛★[2]',Icon='item_40055',Type=170,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='可以挥舞各式各样的动作，非常顺手的双手矛，在狭小的地方不好使用为缺点。',Feature=1,}",
