  [140058] = "{id=140058,NameZh='旗鱼枪★[2]',Icon='item_40058',Type=170,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='剑旗鱼科海鱼，肉质鲜美柔嫩，可作生鱼片，经济价值高，因冷冻的关系非常坚硬。',Feature=1,}",
