  [140061] = "{id=140061,NameZh='生命体长矛[2]',Icon='item_40061',Type=170,MaxNum=99,SellPrice=2400,Desc='雷根贝勒公司所开发的，以生命体为能量的长矛。攻击时会剥夺敌人的生命力。',Level=100,}",
