  [140066] = "{id=140066,NameZh='修尔特长矛★[2]',Icon='item_40066',Type=170,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='上头有着弯刃的长矛，除了刺击之外也可以砍杀的长矛。',}",
  [140070] = "{id=140070,NameZh='辉光十字·长矛[2]',Icon='item_40070',Type=170,MaxNum=99,SellPrice=2600,Desc='这根长矛出自阿卢纳贝兹教国最有名的工匠——索罗克之手，他搜寻了整个教国寻找制作武器的材料，最终在圣域神殿的地下深处寻到了结果，吸取神灵信仰的矿石坚硬无比，制成的武器更是消灭黑暗的破晓之力。',Level=110,}",
  [140071] = "{id=140071,NameZh='蔷薇灵语之矛[2]',Icon='item_40071',Type=170,MaxNum=99,SellPrice=3200,Desc='这杆长矛被妖精一族的“灵语师”赋予了蔷薇的祝福。持有它的勇者将被视作守护妖精一族的骑士，受到妖精的尊重。',Level=110,LoadShowSize=1,LoadShowRotate=-90,LoadShowPose={0,-0.25,0},}",
  [140073] = "{id=140073,NameZh='湛蓝天光·长矛[2]',Icon='item_40073',Type=170,MaxNum=99,SellPrice=2800,Desc='阔大的云海之上透出湛蓝天光，晴空下的战士们振作起了精神。战斗的号角即将吹响，握紧这根长矛吧，它印证着你的忠诚，勇敢与希望。',Level=110,}",
  [140080] = "{id=140080,NameZh='远古回音·矛[2]',Icon='item_40080',Type=170,MaxNum=99,SellPrice=3200,Desc='铭刻着神秘纹样的矛，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,}",
