  [140341] = "{id=140341,NameZh='圣徒长剑[2]',Icon='item_40341',Type=180,Quality=3,MaxNum=99,SellPrice=100,Desc='圣歌教会著名的骑士团——神之光辉骑士团所配备的制式长剑，拥有极其优秀的攻击力，这个长剑还有个极其重要的特点：那就是信仰越虔诚，长剑就会越锋利。受到光明圣徒的祝福，安全精炼时消耗的装备件数减少一半。',Feature=1,}",
