  [140347] = "{id=140347,NameZh='提尔锋[2]',Icon='item_40347',Type=180,MaxNum=99,SellPrice=100,Desc='主神奥丁的孙子斯瓦弗尔，以杀死侏儒威胁他们打造了这柄旷世魔剑，然而侏儒怨恨斯瓦弗尔的霸道，悄悄在剑上刻下了致命的诅咒…',Level=95,Feature=1,}",
