  [140361] = "{id=140361,NameZh='水纹之剑★[2]',Icon='item_40361',Type=180,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='剑刃上有着美丽水波花纹的剑。尽管有着美丽的外观，这把剑的杀伤力却出乎意料的强劲。',Feature=1,}",
  [140362] = "{id=140362,NameZh='暗剑士长剑[2]',Icon='item_40332',Type=180,MaxNum=99,SellPrice=720,Desc='用特殊的炼金配方将好几种常规金属融合而成的新型材质制成的剑。',Level=60,}",
  [140363] = "{id=140363,NameZh='生命体长剑[2]',Icon='item_40363',Type=180,MaxNum=99,SellPrice=2400,Desc='雷根贝勒公司所开发的，以生命体为能量的长剑。能量粒子组成的剑刃十分锋利。',Level=100,}",
  [140364] = "{id=140364,NameZh='魔王长剑[2]',Icon='item_40364',Type=180,MaxNum=99,SellPrice=100,}",
  [140372] = "{id=140372,NameZh='辉光十字·长剑[2]',Icon='item_40372',Type=180,MaxNum=99,SellPrice=2600,Desc='这柄长剑出自阿卢纳贝兹教国最有名的工匠——索罗克之手，他搜寻了整个教国寻找制作武器的材料，最终在圣域神殿的地下深处寻到了结果，吸取神灵信仰的矿石坚硬无比，制成的武器更是消灭黑暗的破晓之力。',Level=110,}",
  [140373] = "{id=140373,NameZh='红莲[2]',Icon='item_40373',Type=180,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=187200,Desc='日出东方之国利用日落之石与寒天之冰所打造之祭奉天神之剑。',}",
  [140374] = "{id=140374,NameZh='蔷薇灵语之剑[2]',Icon='item_40374',Type=180,MaxNum=99,SellPrice=3200,Desc='这柄宝剑被妖精一族的“灵语师”赋予了蔷薇的祝福。唯有妖精们认可的高贵之人才能发挥它的力量。',Level=110,LoadShowSize=1.2,LoadShowRotate=90,LoadShowPose={0,-0.25,0},}",
  [140376] = "{id=140376,NameZh='黑炎剑[2]',Icon='item_40376',Type=180,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='漆黑剑士所使用的武器，蕴含着无尽的黑暗力量，使用者是否会被吞噬仍是个未知数。',LoadShowSize=1.5,LoadShowRotate=50,LoadShowPose={0,-0.36,0},}",
  [140380] = "{id=140380,NameZh='湛蓝天光·长剑[2]',Icon='item_40380',Type=180,MaxNum=99,SellPrice=2800,Desc='阔大的云海之上透出湛蓝天光，晴空下的战士们振作起了精神。战斗的号角即将吹响，握紧这把长剑吧，它印证着你的忠诚，勇敢与希望。',Level=110,}",
  [140382] = "{id=140382,NameZh='烈焰剑[2]',Icon='item_40382',Type=180,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='据说这把剑中潜藏着烈火的力量，使用它的人会获得火焰的祝福。',}",
