  [140389] = "{id=140389,NameZh='龙神之剑[2]',Icon='item_40371',Type=180,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='龙神之力，与米德加尔特大陆的高端工艺完美结合，最终铸成了这把如同艺术品般的宝剑。',}",
