  [140394] = "{id=140394,NameZh='远古回音·长剑[2]',Icon='item_40394',Type=180,MaxNum=99,SellPrice=3200,Desc='铭刻着神秘纹样的长剑，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,}",
