  [140634] = "{id=140634,NameZh='仲裁者[2]',Icon='item_40634',Type=190,MaxNum=99,SellPrice=100,Desc='以中古时代某位大法师的名号命名的法杖。',}",
  [140638] = "{id=140638,NameZh='圣徒之杖[2]',Icon='item_40638',Type=190,Quality=3,MaxNum=99,SellPrice=100,Desc='吉芬魔法研究所与圣歌教会联合研究而出的新一代法杖，法杖拥有良好的魔导性，适合各个层面的魔法师。现在已经广泛装备于教会与吉芬魔法部队。受到光明圣徒的祝福，安全精炼时消耗的装备件数减少一半。',Feature=1,}",
  [140643] = "{id=140643,NameZh='古树法杖[2]',Icon='item_40631',Type=190,MaxNum=99,SellPrice=1140,Desc='使用黑暗密林里最年长的神树枝干制成的法杖，看起来很像普通的木棍，实际上蕴含了充沛的魔法能量。',Level=95,}",
  [140644] = "{id=140644,NameZh='万神的注视[2]',Icon='item_40644',Type=190,MaxNum=99,SellPrice=100,Desc='瓦尔哈拉神殿的长廊前，一万位女武神祈祷了千个昼夜，终于将四大元素的魔力完美糅合在一起，铸造出了这柄至高无上的法杖。',Level=95,Feature=1,}",
