  [140782] = "{id=140782,NameZh='湛蓝天光·短剑[2]',Icon='item_40782',Type=250,MaxNum=99,SellPrice=2800,Desc='阔大的云海之上透出湛蓝天光，晴空下的战士们振作起了精神。战斗的号角即将吹响，握紧这把短剑吧，它印证着你的忠诚，勇敢与希望。',Level=110,}",
  [140784] = "{id=140784,NameZh='易燃短剑[2]',Icon='item_40784',Type=250,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,LoadShowSize=1.8,LoadShowRotate=90,LoadShowPose={0,-0.4,0},}",
  [140790] = "{id=140790,NameZh='远古回音·短剑[2]',Icon='item_40790',Type=250,MaxNum=99,SellPrice=3200,Desc='铭刻着神秘纹样的短剑，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,}",
