  [141240] = "{id=141240,NameZh='精钢连弩[2]',Icon='item_41212',Type=210,MaxNum=99,SellPrice=1140,Desc='历经高温反复锻造制成的精钢打造而成的短弩，可以连续发箭，最适合战场上近距离作战。',Level=95,}",
  [141241] = "{id=141241,NameZh='凛冬结晶[2]',Icon='item_41241',Type=210,MaxNum=99,SellPrice=100,Desc='霜之巨人中最强的战士名为赫朗格尼尔，他死后不屈的执念冰封了数万里的海洋，而许多年后人们才发现他的尸骸，居然化作了这把冰封的巨弓。',Level=95,Feature=1,}",
