  [141243] = "{id=141243,NameZh='凛冬结晶3[2]',Icon='item_41243',Type=210,MaxNum=99,SellPrice=100,Desc='霜之巨人中最强的战士名为赫朗格尼尔，他死后不屈的执念冰封了数万里的海洋，而许多年后人们才发现他的尸骸，居然化作了这把冰封的巨弓。',Level=95,Feature=1,}",
  [141246] = "{id=141246,NameZh='森林猎手[2]',Icon='item_41246',Type=210,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='最初为了在森林中作战而被设计出的装备，就算地形再复杂也丝毫不影响使用者发挥实力。“它就像我身体的一部分。”——某个老猎人',Feature=1,}",
