  [141252] = "{id=141252,NameZh='亡灵之弓[2]',Icon='item_41252',Type=210,MaxNum=99,SellPrice=2100,Desc='这把弓射出的箭矢，穿透了灵魂，直达内心。但它还是会收到物理反伤的影响。',Level=95,}",
