  [141273] = "{id=141273,NameZh='湛蓝天光·弓[2]',Icon='item_41273',Type=210,MaxNum=99,SellPrice=2800,Desc='阔大的云海之上透出湛蓝天光，晴空下的战士们振作起了精神。战斗的号角即将吹响，握紧这把长弓吧，它印证着你的忠诚，勇敢与希望。',Level=110,}",
  [141280] = "{id=141280,NameZh='远古回音·弓[2]',Icon='item_41280',Type=210,MaxNum=99,SellPrice=3200,Desc='铭刻着神秘纹样的弓箭，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,}",
