  [141536] = "{id=141536,NameZh='军用战锤[2]',Icon='item_41536',Type=220,MaxNum=99,SellPrice=840,Desc='经历了多次战争不断修改设计并最终定型。重视实战效果的战锤。',Level=70,}",
  [141537] = "{id=141537,NameZh='制式锤[2]',Icon='item_41537',Type=220,MaxNum=99,SellPrice=960,Desc='专门为佣兵定制的作战用锤子。适应各种复杂环境。',Level=80,}",
  [141541] = "{id=141541,NameZh='圣徒之锤[2]',Icon='item_41541',Type=220,Quality=3,MaxNum=99,SellPrice=100,Desc='商人协会委托“光明圣徒”安德鲁设计锻造的战锤，战锤非常沉重，使用起来杀伤力惊人，是最适合商人铁匠使用的武器，在某些时刻还可以当作锻造锤使用。受到光明圣徒的祝福，安全精炼时消耗的装备件数减少一半。',Feature=1,}",
  [141543] = "{id=141543,NameZh='羽毛权杖[2]',Icon='item_41543',Type=220,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1680,Desc='用少量材料炼制出的羽翼权杖实验品，虽然能力有所欠缺，但手感反而更适合初学者呢~',Feature=1,}",
