  [141580] = "{id=141580,NameZh='蔷薇灵语之锤[2]',Icon='item_41580',Type=220,MaxNum=99,SellPrice=3200,Desc='妖精一族的“神工匠”打造道具时使用的锤子，灵语师们觉得太过单调，用鲜花装饰了它。',Level=110,LoadShowSize=1.5,LoadShowRotate=90,}",
  [141582] = "{id=141582,NameZh='忽克连的精炼之锤[2]',Icon='item_41582',Type=220,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='忽克连做为精炼时爱用的锤子。看起来像个非常高级强力的装备却感觉到某种不安定的气息。',LoadShowSize=1.5,LoadShowRotate=50,LoadShowPose={0,0,0},}",
  [141583] = "{id=141583,NameZh='湛蓝天光·锤[2]',Icon='item_41583',Type=220,MaxNum=99,SellPrice=2800,Desc='阔大的云海之上透出湛蓝天光，晴空下的战士们振作起了精神。战斗的号角即将吹响，握紧这把战锤吧，它印证着你的忠诚，勇敢与希望。',Level=110,}",
  [141590] = "{id=141590,NameZh='远古回音·锤[2]',Icon='item_41590',Type=220,MaxNum=99,SellPrice=3200,Desc='铭刻着神秘纹样的锤子，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,}",
  [141604] = "{id=141604,NameZh='爆裂重锤[2]',Icon='item_41604',Type=220,Quality=3,MaxNum=99,SellPrice=100,Desc='传说唯有拥有巨人族的力量才能举起的重锤，拿在手中便是无言的威慑。',}",
