  [141610] = "{id=141610,NameZh='魔翼之杖[2]',Icon='item_40693',Type=190,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='据说法杖之上的羽毛来自于某位天使，拥有强大的魔力。',}",
