  [141616] = "{id=141616,NameZh='匠心之锤[2]',Icon='item_41613',Type=220,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='只有最纯粹的匠心才能握住这把被缠绕烈焰的锤而不被灼伤，因为他的心比钢铁更坚毅。',LoadShowSize=1.5,LoadShowRotate=50,LoadShowPose={0,0,0},}",
