  [141832] = "{id=141832,NameZh='钢战斧[2]',Icon='item_41832',Type=230,MaxNum=99,SellPrice=720,Desc='耐用的钢铁打造的军用斧。',Level=60,}",
  [141833] = "{id=141833,NameZh='巨型战斧[2]',Icon='item_41833',Type=230,MaxNum=99,SellPrice=1080,Desc='对自己力气有信心的人爱用的武器。',Level=90,}",
  [141834] = "{id=141834,NameZh='毁灭手斧[2]',Icon='item_41834',Type=230,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=2880,Desc='吞吃了足够灵魂的毁灭之斧会变成毁灭手斧，给与持有者的力量更加诱人，需要献出代价也更大，一旦握住它，似乎会听见某个声音在脑海里轻轻低语，“去劈开理智的枷锁，拥抱力量的深渊吧。”',Feature=1,}",
  [141835] = "{id=141835,NameZh='贝克之斧[2]',Icon='item_41835',Type=230,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=3456,Desc='铁匠公会仿造著名的贝克战斧制作的量产型斧头。',Feature=1,}",
  [141836] = "{id=141836,NameZh='斯勒特手斧[2]',Icon='item_41836',Type=230,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=3360,Desc='多刃斧。使用起来意外的轻巧。',Feature=1,}",
  [141838] = "{id=141838,NameZh='风灵钢斧[2]',Icon='item_41838',Type=230,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1660,Desc='运用最新工艺将风灵矿石配合符文法阵试作的蕴含风之力的斧头。',Feature=1,}",
