  [141841] = "{id=141841,NameZh='水灵钢斧[2]',Icon='item_41841',Type=230,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1660,Desc='运用最新工艺将水灵矿石配合符文法阵试作的蕴含水之力的斧头。',Feature=1,}",
  [141843] = "{id=141843,NameZh='斩击之斧[2]',Icon='item_41843',Type=230,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=3456,Desc='特化斩击的重斧。有些剑士偶尔也会使用它。',Feature=1,}",
  [141844] = "{id=141844,NameZh='追风之斧[2]',Icon='item_41844',Type=230,Quality=3,MaxNum=99,SellPrice=100,Desc='据使用者描述，该斧在挥砍的时候仿佛能感受到风的流动。',Feature=1,}",
  [141846] = "{id=141846,NameZh='圣徒巨斧[2]',Icon='item_41846',Type=230,Quality=3,MaxNum=99,SellPrice=100,Desc='安德鲁立志要完成所有武器的研究，而巨斧是其中最难的武器之一，既要保持巨大的杀伤力，又要轻巧便于挥舞。所幸安德鲁成功的研究出了“圣徒巨斧”这一强力的武器。而安德鲁也因此闻名大陆。受到光明圣徒的祝福，安全精炼时消耗的装备件数减少一半。',Feature=1,}",
  [141848] = "{id=141848,NameZh='鲜血斧[2]',Icon='item_41848',Type=230,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1176,Desc='暴躁的锻造大师金利设计的战斧，被砍伤的人会血流不止。',Feature=1,}",
  [141849] = "{id=141849,NameZh='聚合金巨斧[2]',Icon='item_41849',Type=230,MaxNum=99,SellPrice=100,}",
  [141850] = "{id=141850,NameZh='强袭战斧[2]',Icon='item_41850',Type=230,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1560,Feature=1,}",
  [141851] = "{id=141851,NameZh='强袭双刃斧[2]',Icon='item_41851',Type=230,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1920,Feature=1,}",
  [141854] = "{id=141854,NameZh='丹恩之斧[2]',Icon='item_41833',Type=230,MaxNum=99,SellPrice=1140,Desc='矮人战王丹恩的随身战斧，伴随他经历了无数场惊心动魄的战争，象征着矮人坚韧的精神。',Level=95,}",
  [141855] = "{id=141855,NameZh='硝烟终结者[2]',Icon='item_41855',Type=230,MaxNum=99,SellPrice=100,Desc='当诸神黄昏的硝烟蔓延到了侏儒王国时，侏儒兄弟辛德里和勃洛克以寿命为代价，铸造了这把世上最强的战斧，它仅一击就天崩地裂，瞬间便击溃了龙族的侵略者。',Level=95,Feature=1,}",
  [141856] = "{id=141856,NameZh='硝烟终结者2[2]',Icon='item_41856',Type=230,MaxNum=99,SellPrice=100,Desc='当诸神黄昏的硝烟蔓延到了侏儒王国时，侏儒兄弟辛德里和勃洛克以寿命为代价，铸造了这把世上最强的战斧，它仅一击就天崩地裂，瞬间便击溃了龙族的侵略者。',Level=95,Feature=1,}",
  [141857] = "{id=141857,NameZh='硝烟终结者3[2]',Icon='item_41857',Type=230,MaxNum=99,SellPrice=100,Desc='当诸神黄昏的硝烟蔓延到了侏儒王国时，侏儒兄弟辛德里和勃洛克以寿命为代价，铸造了这把世上最强的战斧，它仅一击就天崩地裂，瞬间便击溃了龙族的侵略者。',Level=95,Feature=1,}",
  [141860] = "{id=141860,NameZh='守备军之斧[2]',Icon='item_41833',Type=230,MaxNum=99,SellPrice=2000,Level=90,}",
  [141865] = "{id=141865,NameZh='亡灵之斧[2]',Icon='item_41865',Type=230,MaxNum=99,SellPrice=2100,Desc='这把斧子的主人生前是个诚实的伐木工，他在湖边弄丢了自己的斧子，湖之仙女送了他一把金斧子。',Level=95,}",
  [141867] = "{id=141867,NameZh='贝克之斧★[2]',Icon='item_41867',Type=230,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='铁匠公会仿造著名的贝克战斧制作的量产型斧头。',Feature=1,}",
  [141868] = "{id=141868,NameZh='碎心斧★[2]',Icon='item_41868',Type=230,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='任何盔甲都无法抵挡的双手斧。 特殊加工的斧刃好像可以砍破任何盔甲似的锐利而沉重。',Feature=1,}",
  [141869] = "{id=141869,NameZh='毁灭手斧★[2]',Icon='item_41869',Type=230,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='吞吃了足够灵魂的毁灭之斧会变成毁灭手斧，给与持有者的力量更加诱人，需要献出代价也更大，一旦握住它，似乎会听见某个声音在脑海里轻轻低语，“去劈开理智的枷锁，拥抱力量的深渊吧。”',Feature=1,}",
  [141870] = "{id=141870,NameZh='鲜血斧★[2]',Icon='item_41870',Type=230,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='暴躁的锻造大师金利设计的战斧，被砍伤的人会血流不止。',Feature=1,}",
  [141871] = "{id=141871,NameZh='强袭双刃斧★[2]',Icon='item_41871',Type=230,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='克雷斯特汉姆山河破碎，幸存者拿起了这把斧子，心中只有复仇。',Feature=1,}",
  [141872] = "{id=141872,NameZh='暗商人之斧[2]',Icon='item_41801',Type=230,MaxNum=99,SellPrice=140,Desc='简单的使用方法，方便任何人使用的斧。',Level=10,Feature=4,}",
  [141873] = "{id=141873,NameZh='生命体战斧[2]',Icon='item_41873',Type=230,MaxNum=99,SellPrice=2400,Desc='雷根贝勒公司所开发的，以生命体为能量的战斧。粒子组成的斧刃可以劈开大多数盾牌。',Level=100,}",
  [141874] = "{id=141874,NameZh='魔王之斧[2]',Icon='item_41874',Type=230,MaxNum=99,SellPrice=100,}",
  [141877] = "{id=141877,NameZh='首领之斧[2]',Icon='item_41877',Type=230,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=108000,Desc='只有强者中的强者才配得上这把拥有摧枯拉朽力量的大斧。',}",
  [141881] = "{id=141881,NameZh='辉光十字·斧[2]',Icon='item_41881',Type=230,MaxNum=99,SellPrice=2600,Desc='这柄战斧出自阿卢纳贝兹教国最有名的工匠——索罗克之手，他搜寻了整个教国寻找制作武器的材料，最终在圣域神殿的地下深处寻到了结果，吸取神灵信仰的矿石坚硬无比，制成的武器更是消灭黑暗的破晓之力。',Level=110,}",
  [141882] = "{id=141882,NameZh='狂暴飓风[2]',Icon='item_41882',Type=230,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='复制飓风型态的巨大的双手斧，斧头中心隐藏着飓风般的力量, 据说武器越强时力量也会一起增强。',}",
  [141883] = "{id=141883,NameZh='蔷薇灵语之斧[2]',Icon='item_41883',Type=230,MaxNum=99,SellPrice=3200,Desc='这把战斧被妖精一族的“灵语师”赋予了蔷薇的祝福。妖精认可的勇士将用它斩断拦路的荆棘。',Level=110,LoadShowRotate=90,}",
  [141885] = "{id=141885,NameZh='湛蓝天光·斧[2]',Icon='item_41885',Type=230,MaxNum=99,SellPrice=2800,Desc='阔大的云海之上透出湛蓝天光，晴空下的战士们振作起了精神。战斗的号角即将吹响，握紧这把战斧吧，它印证着你的忠诚，勇敢与希望。',Level=110,}",
  [141892] = "{id=141892,NameZh='远古回音·斧[2]',Icon='item_41892',Type=230,MaxNum=99,SellPrice=3200,Desc='铭刻着神秘纹样的巨斧，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,}",
