  [142034] = "{id=142034,NameZh='附魔铠甲[1]',Icon='item_42034',Type=500,MaxNum=99,SellPrice=1104,Desc='铠甲上的魔法符文储存有增强佩戴者属性的次级魔法。因为是魔法学徒的作品所以相对一般魔法道具要廉价得多。',Level=92,}",
