  [142039] = "{id=142039,NameZh='天使的加护[1]',Icon='item_42039',Type=500,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=5600,Desc='负责超级初学者天使的外袍，把全身轻柔包围的试穿感最棒了！',Feature=1,}",
  [142040] = "{id=142040,NameZh='陨石铠甲[1]',Icon='item_42040',Type=500,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=5600,Desc='疑似是用无法辨认成分的陨石来制作的强化盔甲。',Feature=1,}",
  [142041] = "{id=142041,NameZh='大猫的祝福[1]',Icon='item_42041',Type=500,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=8000,Desc='饱含家人祝福的轻便铠甲。穿上后就算经历了上万里的旅行，也能感觉到家人的思念。',Feature=1,}",
