  [142111] = "{id=142111,NameZh='喵族优雅斗篷[1]',Icon='item_42111',Type=500,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=7200,Desc='无论刮风下雨，只要穿上它就可以放心的出门，为您节省大量时间。',}",
  [142112] = "{id=142112,NameZh='喵族优雅外套[1]',Icon='item_42112',Type=500,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=19200,Desc='非常宽松的舒适外套，不论啤酒肚还是大象腿都可以优雅地遮起来。',}",
