  [142541] = "{id=142541,NameZh='光明圣徒之盾[1]',Icon='item_42541',Type=510,Quality=3,MaxNum=99,SellPrice=100,Desc='圣歌教会的锻造神工匠，人称“光明圣徒”的安德鲁冕下为那些英勇善战的教会勇士所设计的一套制式服装，防御力极其优秀。起初这套制式服装没有名字，但其优秀的防御力让所有勇士们都爱不释手，他们用锻造这安德鲁的称号来为这制式服装命名。这就是“光明圣徒”套装。这件为“光明圣徒”套装的副手部分。受到光明圣徒的祝福，安全精炼时消耗的装备件数减少一半。',Feature=1,}",
  [142547] = "{id=142547,NameZh='狮心盾牌[1]',Icon='item_42532',Type=510,MaxNum=99,SellPrice=1164,Desc='传说中的狮心军团特有的盾牌，具有极高的防御能力，甚至能够抵御巨龙的火焰。',Level=97,}",
