  [142568] = "{id=142568,NameZh='火焰喷射器[1]',Icon='item_42568',Type=510,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=21600,Desc='喷出火焰瞬间让敌人着火，请小心使用。',}",
