  [142585] = "{id=142585,NameZh='奥尔里昂的铁盘★[1]',Icon='item_42585',Type=510,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='端料理的圆形铁盘。异常光滑。',}",
  [142586] = "{id=142586,NameZh='献祭之书★[1]',Icon='item_42586',Type=510,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='曾经某位牺牲自己封印魔物的牧师用过的圣典。',}",
  [142587] = "{id=142587,NameZh='生命魔法书★[1]',Icon='item_42587',Type=510,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='一本厚重的魔法书，据说是魔法大师玛吉玛特毕生的笔记。',}",
  [142588] = "{id=142588,NameZh='灵犀宝珠★[1]',Icon='item_42588',Type=510,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='“心有灵犀一点通。”这句来自斐扬的古话说的是那些有缘人。',}",
  [142589] = "{id=142589,NameZh='圣母圣像★[2]',Icon='item_42589',Type=512,Quality=4,MaxNum=99,SellPrice=9600,Desc='随身携带的雕刻着教会圣母的小雕像。',}",
  [142590] = "{id=142590,NameZh='华贵腕甲★[1]',Icon='item_42590',Type=513,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='贵气十足的手甲。上层的大佬们根本不会懂什么叫实用性。',}",
  [142591] = "{id=142591,NameZh='邪骨腕甲★[1]',Icon='item_42591',Type=513,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='邪气十足的手甲。',}",
  [142592] = "{id=142592,NameZh='化学防护手套★[1]',Icon='item_42592',Type=513,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='以七种毒蛇蜕下的皮合制成的手套，可以抵御几乎所有腐蚀性物质，唯一的缺点是非常闷热。',}",
  [142593] = "{id=142593,NameZh='尼罗的手环★[1]',Icon='item_42593',Type=514,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='海利翁宝石所封印的手镯，可以净化邪恶的力量。',}",
  [142594] = "{id=142594,NameZh='蔷薇姬的腕轮★[1]',Icon='item_42594',Type=514,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='朴实的手环，内侧刻着“P.L.K\"三个意义不明的字母。',}",
  [142595] = "{id=142595,NameZh='芬特克的手环★[1]',Icon='item_42595',Type=514,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='手环内部的文字已经磨损，只能辩认出“You shall not”三个单词',}",
  [142596] = "{id=142596,NameZh='湛蓝天光·盾[1]',Icon='item_42596',Type=510,MaxNum=99,SellPrice=2800,Desc='阔大的云海之上透出湛蓝天光，晴空下的战士们振作起了精神。握好这面盾牌吧，它印证着你的忠诚，勇敢与希望。',Level=110,}",
  [142605] = "{id=142605,NameZh='手臂防护具[1]',Icon='item_42605',Type=510,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='天水之国忍者众的制式防具，灵活轻便，完全不会影响行动。',Delete=142605}",
  [142606] = "{id=142606,NameZh='改良型手臂防护具[1]',Icon='item_42606',Type=510,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='天水之国忍者众的高级防具，只有精英忍者才能佩戴，比普通的手臂护具更加灵活，也更加坚韧。',Delete=142606}",
  [142608] = "{id=142608,NameZh='图腾木雕[1]',Icon='item_42608',Type=512,Quality=2,MaxNum=99,SellPrice=100,Desc='一枚精致的图腾，雕刻着某位神明，也许能够给佩戴者带来好运。',Feature=1,Delete=142608}",
  [142609] = "{id=142609,NameZh='智慧图腾[1]',Icon='item_42609',Type=512,Quality=3,MaxNum=99,SellPrice=100,Desc='上古时期的克魔岛人将图腾柱视为天神在人间的化身，他们参拜供奉这些图腾，认为这样能够带来救赎和指引。',Feature=1,Delete=142609}",
  [142610] = "{id=142610,NameZh='天神的启示[1]',Icon='item_42610',Type=512,Quality=4,MaxNum=99,SellPrice=100,Desc='于蒙昧与灾祸之中，神明的化身将显现，为人们指出前行的道路。',Feature=1,Delete=142610}",
  [142624] = "{id=142624,NameZh='骨笛[1]',Icon='item_42624',Type=513,Quality=2,MaxNum=99,SellPrice=100,Desc='较为简陋的原始乐器，使用鸟类翅骨制成的笛子。',Feature=1,Delete=142624}",
  [142625] = "{id=142625,NameZh='唤鹰笛[1]',Icon='item_42625',Type=513,Quality=3,MaxNum=99,SellPrice=100,Desc='根据克魔岛的传说，用这支骨笛吹奏特定的曲子，可以召唤统御狂风与雷电的巨鹰。',Feature=1,Delete=142625}",
  [142626] = "{id=142626,NameZh='灵骨之音[1]',Icon='item_42626',Type=513,Quality=4,MaxNum=99,SellPrice=100,Desc='为祸克魔岛的巨鹰被猎人杀死，翅骨制成骨笛作为纪念。这只骨笛中寄居着巨鹰的怨念，一经吹奏便会引来呼啸的狂风。',Feature=1,Delete=142626}",
  [142627] = "{id=142627,NameZh='巨兽头骨[1]',Icon='item_42627',Type=510,Quality=2,MaxNum=99,SellPrice=100,Desc='不知名巨兽的头骨，可能是上古时期生活在克魔岛野兽的遗骸。',Feature=1,Delete=142627}",
  [142628] = "{id=142628,NameZh='龙骨盾[1]',Icon='item_42628',Type=510,Quality=3,MaxNum=99,SellPrice=100,Desc='传说上古时期的克魔岛曾有巨龙栖息，这面用龙的头骨制成的盾牌就是最好的证据。',Feature=1,Delete=142628}",
  [142629] = "{id=142629,NameZh='狩龙武勋[1]',Icon='item_42629',Type=510,Quality=4,MaxNum=99,SellPrice=100,Desc='上古时期的克魔岛，狩猎一头巨龙是每个勇士都想达成的荣耀，勇士会将杀死的巨龙制成盾牌与武器，作为这无上功勋的证明。',Feature=1,Delete=142629}",
  [142630] = "{id=142630,NameZh='剥皮刀[1]',Icon='item_42630',Type=513,Quality=2,MaxNum=99,SellPrice=100,Desc='一把骨制小刀，猎人们可以用它剥取猎物的毛皮。',Feature=1,Delete=142630}",
  [142631] = "{id=142631,NameZh='巫毒之刃[1]',Icon='item_42631',Type=513,Quality=3,MaxNum=99,SellPrice=100,Desc='古老的骨质小刀，是上古时期克魔岛人的祭祀工具，他们会用这把刀杀死猎物，将它们作为献给天神的祭品。',Feature=1,Delete=142631}",
  [142632] = "{id=142632,NameZh='恶毒之伤[1]',Icon='item_42632',Type=513,Quality=4,MaxNum=99,SellPrice=100,Desc='这把刀上附着了这世上最恶毒的诅咒，它留下的伤口永远无法被治愈。”无法治愈的伤口，未必需要用刀留下……“',Feature=1,Delete=142632}",
  [142633] = "{id=142633,NameZh='水晶之颅[1]',Icon='item_42633',Type=513,Quality=2,MaxNum=99,SellPrice=100,Desc='一颗晶莹剔透的水晶头骨，从外形来看并非人类的骨骼。',Feature=1,Delete=142633}",
  [142634] = "{id=142634,NameZh='恶魔之颅[1]',Icon='item_42634',Type=513,Quality=3,MaxNum=99,SellPrice=100,Desc='上古时期为祸一方的恶魔，强大且凶残。被诛杀后的遗骸依然蕴含着强大的魔力。',Feature=1,Delete=142634}",
  [142635] = "{id=142635,NameZh='猎魔人的战利品[1]',Icon='item_42635',Type=513,Quality=4,MaxNum=99,SellPrice=100,Desc='当恶魔肆虐，人们呼唤猎魔人的名字，他便会如期出现，腰间挂着18枚恶魔的头颅——只有最强大的魔王，才有资格成为他的战利品。',Feature=1,Delete=142635}",
  [142636] = "{id=142636,NameZh='古代金币[1]',Icon='item_42636',Type=510,Quality=2,MaxNum=99,SellPrice=100,Desc='雕刻着奇怪图案的古代金币，历史学者们推测这是克魔岛先民们使用的墓葬品。',Feature=1,Delete=142636}",
  [142637] = "{id=142637,NameZh='赦罪金[1]',Icon='item_42637',Type=510,Quality=3,MaxNum=99,SellPrice=100,Desc='根据克魔岛的传说，亡者需要向死神支付足量的金币，以赦免他们生前犯下的罪孽。',Feature=1,Delete=142637}",
  [142638] = "{id=142638,NameZh='生者的罪孽[1]',Icon='item_42638',Type=510,Quality=4,MaxNum=99,SellPrice=100,Desc='引渡亡者的小船摇摇晃晃，仿佛随时都会倾覆，生前的每一份罪孽都会化作一枚金币，为小船增添一分重量，让这场旅途愈加凶险。',Feature=1,Delete=142638}",
  [142639] = "{id=142639,NameZh='捕梦网[1]',Icon='item_42639',Type=514,Quality=2,MaxNum=99,SellPrice=100,Desc='克魔岛传统的饰物，据说可以捕获美好的梦境，让噩梦消散。',Feature=1,Delete=142639}",
  [142640] = "{id=142640,NameZh='彼岸之网[1]',Icon='item_42640',Type=514,Quality=3,MaxNum=99,SellPrice=100,Desc='将彼岸之网悬挂在床头，可以连通现实与梦境，与错失之人重逢。',Feature=1,Delete=142640}",
  [142641] = "{id=142641,NameZh='梦境守护者[1]',Icon='item_42641',Type=514,Quality=4,MaxNum=99,SellPrice=100,Desc='梦境守护者的配饰，传说中梦境守护者只在夜间出现，他们游走于现实与梦境之间，捕杀梦魇，守护人们的安眠。',Feature=1,Delete=142641}",
  [142642] = "{id=142642,NameZh='赤羽毛笔[1]',Icon='item_42642',Type=513,Quality=2,MaxNum=99,SellPrice=100,Desc='使用鸟类翎毛制作的羽毛笔，书写非常顺畅。',Feature=1,Delete=142642}",
  [142643] = "{id=142643,NameZh='烈焰轻羽[1]',Icon='item_42643',Type=513,Quality=3,MaxNum=99,SellPrice=100,Desc='一根被火焰包裹着的羽毛，令人惊奇的是，火焰似乎完全没有将羽毛损伤分毫。',Feature=1,Delete=142643}",
  [142644] = "{id=142644,NameZh='不死鸟之羽[1]',Icon='item_42644',Type=513,Quality=4,MaxNum=99,SellPrice=100,Desc='传说中不死鸟的羽毛，饱含着象征新生的力量。“这不是第一次，也不会是最后一次……”',Feature=1,Delete=142644}",
  [142645] = "{id=142645,NameZh='古代旗帜[1]',Icon='item_42645',Type=510,Quality=2,MaxNum=99,SellPrice=100,Desc='一面古老的战旗，残破的旗帜和满布斫痕的旗杆昭示着它见证过怎样惨烈的战斗。',Feature=1,Delete=142645}",
  [142646] = "{id=142646,NameZh='勇气之旗[1]',Icon='item_42646',Type=510,Quality=3,MaxNum=99,SellPrice=100,Desc='上古时期的克魔岛魔物肆虐，骁勇的岛民在英雄的带领下组建鹰之团，击败魔物，才有了后世平静的克魔岛。这面旗帜便是鹰之团的勇士们勇气的象征。',Feature=1,Delete=142646}",
  [142647] = "{id=142647,NameZh='不屈战团的传承[1]',Icon='item_42647',Type=510,Quality=4,MaxNum=99,SellPrice=100,Desc='梦罗克入侵时期，一支战团在与魔王爪牙的战斗中血战至全军覆没，战场中耸立的战旗将这些勇士的战意与勇气凝聚起来，走到旗帜附近，似乎能够听到那些勇士们的战吼。“身后即是家园，我们以无路可退！此旗是拒敌之盾，亦是任何人不可逾越之阵线，唯有死战！”',Feature=1,Delete=142647}",
  [142648] = "{id=142648,NameZh='船灯[1]',Icon='item_42648',Type=513,Quality=2,MaxNum=99,SellPrice=100,Desc='悬挂在船头的明灯，即使在迷雾中航行也不会迷失方向。',Feature=1,Delete=142648}",
  [142649] = "{id=142649,NameZh='引魂灯[1]',Icon='item_42649',Type=513,Quality=3,MaxNum=99,SellPrice=100,Desc='传说中能够吸引亡魂注意的灯火。人们将明灯悬挂在家门口，相传这样可以让那些迷失的亡灵穿越迷雾，回到家乡。',Feature=1,Delete=142649}",
  [142650] = "{id=142650,NameZh='万灵归途[1]',Icon='item_42650',Type=513,Quality=4,MaxNum=99,SellPrice=100,Desc='引渡人揺着小船，穿越漫布迷雾的冥河，伴着船头的灯火，带万千亡灵踏上往生之路。“命运自有定数，万灵皆有归途。”',Feature=1,Delete=142650}",
  [142651] = "{id=142651,NameZh='神秘石盘[1]',Icon='item_42651',Type=510,Quality=2,MaxNum=99,SellPrice=100,Desc='一块雕刻着华丽纹路的石盘，令人惊叹它的精致做工。',Feature=1,Delete=142651}",
  [142652] = "{id=142652,NameZh='太阳轮盘[1]',Icon='item_42652',Type=510,Quality=3,MaxNum=99,SellPrice=100,Desc='上古时期克魔岛先民用以记录历史的轮盘，每一个轮盘记录一次四季的轮回。',Feature=1,Delete=142652}",
  [142653] = "{id=142653,NameZh='历史见证者[1]',Icon='item_42653',Type=510,Quality=4,MaxNum=99,SellPrice=100,Desc='蕴含着如同太阳般炽热魔力的盾牌，它的主人是传说中的勇者“太阳骑士”。勇者依靠它的力量剿灭魔物，播撒福音。“使用说明：在阳光下直射三小时可以让本盾牌完全充能……”',Feature=1,Delete=142653}",
  [142654] = "{id=142654,NameZh='传统秘药[1]',Icon='item_42654',Type=513,Quality=2,MaxNum=99,SellPrice=100,Desc='根据克魔岛古法制成的魔药，效用不明，最好不要轻易尝试。',Feature=1,Delete=142654}",
  [142655] = "{id=142655,NameZh='魔女的坩埚[1]',Icon='item_42655',Type=513,Quality=3,MaxNum=99,SellPrice=100,Desc='传说中灾厄魔女使用过的坩埚，邪恶的魔女用它炼制了什么魔药呢？',Feature=1,Delete=142655}",
  [142656] = "{id=142656,NameZh='生息之坛[1]',Icon='item_42656',Type=513,Quality=4,MaxNum=99,SellPrice=100,Desc='被森林之灵祝福过的宝物，即使是最普通的草药，也能炼制成强大的魔药。“魔药可以杀人，也可以救人，怎么使用全凭本心……”',Feature=1,Delete=142656}",
  [142657] = "{id=142657,NameZh='先祖面具[1]',Icon='item_42657',Type=510,Quality=2,MaxNum=99,SellPrice=100,Desc='克魔岛传统风格的面具，但是从大小来看，它更像是一面盾牌。',Feature=1,Delete=142657}",
  [142658] = "{id=142658,NameZh='仪祭古面[1]',Icon='item_42658',Type=510,Quality=3,MaxNum=99,SellPrice=100,Desc='远古时期，克魔岛的先民们祭拜先祖时戴在脸上的祭器，相传这种面目可憎的假面能够吓退邪祟，保佑部族的安定。',Feature=1,Delete=142658}",
  [142659] = "{id=142659,NameZh='祖灵之庇佑[1]',Icon='item_42659',Type=510,Quality=4,MaxNum=99,SellPrice=100,Desc='常年供奉在祭坛中的鬼面具，上面附着了祖先的灵魂，能够祛除邪祟，用另一种方式庇护着自己的后裔。“那是我孙子的孙子的孙子的孙子……”',Feature=1,Delete=142659}",
  [142660] = "{id=142660,NameZh='龟甲盾[1]',Icon='item_42660',Type=510,Quality=2,MaxNum=99,SellPrice=100,Desc='一面巨大的龟甲，可以用来装饰房间，或许也可以当作盾牌使用。',Feature=1,Delete=142660}",
  [142661] = "{id=142661,NameZh='海洋恩赐[1]',Icon='item_42661',Type=510,Quality=3,MaxNum=99,SellPrice=100,Desc='每年都会有暮年海龟来到克魔岛，平静的迎来自己生命的终点。它们的骸骨被克魔岛岛民视作海洋的恩赐，是天然的锻造材料。',Feature=1,Delete=142661}",
  [142662] = "{id=142662,NameZh='海灵壁垒[1]',Icon='item_42662',Type=510,Quality=4,MaxNum=99,SellPrice=100,Desc='克魔岛上居住着的是海洋之民，受到大海的庇护。圣洁的海洋之力会驱散邪恶，让他们免受侵害。“海洋可以包容一切，亦会吞噬一切……”',Feature=1,Delete=142662}",
  [142663] = "{id=142663,NameZh='古代石板[1]',Icon='item_42663',Type=510,Quality=2,MaxNum=99,SellPrice=100,Desc='一块古老的石板，根据历史学家的研究，上面的文字与图案似乎讲述了一个英雄的故事。',Feature=1,Delete=142663}",
  [142664] = "{id=142664,NameZh='英雄丰碑[1]',Icon='item_42664',Type=510,Quality=3,MaxNum=99,SellPrice=100,Desc='在英雄们的带领下，先民们击败强敌，迎来幸福和平的生活。先民们树立石碑记载此事，让后人也能歌颂英雄的功绩。',Feature=1,Delete=142664}",
  [142665] = "{id=142665,NameZh='末日箴言[1]',Icon='item_42665',Type=510,Quality=4,MaxNum=99,SellPrice=100,Desc='火山爆发、恶魔肆虐，这块石碑上记载了诸神黄昏的末日景象。把手放在石碑上，甚至可以感觉到末日降临时人们的慌张与绝望。“毁灭之后，即是新生……”',Feature=1,Delete=142665}",
  [142666] = "{id=142666,NameZh='巫毒秘典[1]',Icon='item_42666',Type=513,Quality=2,MaxNum=99,SellPrice=100,Desc='记载了许多古怪巫术的秘典，也不知道有没有用，或许可以找谁试验一下？',Feature=1,Delete=142666}",
  [142667] = "{id=142667,NameZh='神秘抄本[1]',Icon='item_42667',Type=513,Quality=3,MaxNum=99,SellPrice=100,Desc='一本破旧的笔记，上面用难以辨别的文字记载着什么，或许是某种魔法咒语？当触碰这本书时感觉耳边回荡着一个声音，引诱你将这本笔记打开。',Feature=1,Delete=142667}",
  [142668] = "{id=142668,NameZh='噩梦原典[1]',Icon='item_42668',Type=513,Quality=4,MaxNum=99,SellPrice=100,Desc='一本危险的古老魔法书，上面的古代文字晦涩难懂。克魔岛的居民在岛上的一处洞穴中发现了这本书，但没有人知道上面书写的文字是什么意思，有人坚信这是某种秘密宗教信奉的圣典。“等等，好像有什么东西要钻出来了……”',Feature=1,Delete=142668}",
  [142669] = "{id=142669,NameZh='远古回音·盾[1]',Icon='item_42669',Type=510,MaxNum=99,SellPrice=3200,Desc='铭刻着神秘纹样的盾，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,}",
  [142672] = "{id=142672,NameZh='神话尘封·荒境之盾[1]',Icon='item_42672',Type=510,Quality=2,MaxNum=99,SellPrice=100,Desc='在荒境发掘出的盾牌，曾为传说中的洛阳勇士所持有。',Level=120,Delete=142672}",
  [142673] = "{id=142673,NameZh='辉煌再临·荒境圣盾[1]',Icon='item_42673',Type=510,Quality=2,MaxNum=99,SellPrice=100,Desc='沉眠在荒境深处的传奇盾牌，可以为你增加物理、魔法伤害。因为新主人的出现，它褪去尘埃，重新焕发耀目的光彩。',Level=130,Delete=142673}",
