  [143010] = "{id=143010,NameZh='护肩甲[2]',Icon='2',Type=520,MaxNum=99,SellPrice=100,Desc='只把铠甲肩膀部份拆下来，做为套肩膀的保护袋，拥有相当的保护力。',Level=10,Feature=4,}",
  [143011] = "{id=143011,NameZh='贝利的斗篷[2]',Icon='2',Type=520,MaxNum=99,SellPrice=100,Desc='奥丁的一位儿子贝利所使用的斗篷，虽然是一位盲人却能把战士厚德杀死，有着贝利奋斗的痕迹。',Level=40,Feature=4,}",
  [143012] = "{id=143012,NameZh='摩菲斯披肩[2]',Icon='2',Type=520,MaxNum=99,SellPrice=100,Desc='为了要解开摩菲斯的封印三把钥匙其中之一的披肩，据说这披肩有记载着古代的咒文。',Level=10,Feature=4,}",
  [143013] = "{id=143013,NameZh='茉莉雅娜斗篷[2]',Icon='2',Type=520,MaxNum=99,SellPrice=100,Desc='有着灰色光芒乌鸦化身的茉莉雅娜权能，用乌鸦羽毛所做的灰色斗篷。',Level=10,Feature=4,}",
  [143014] = "{id=143014,NameZh='哥夫内肩饰[1]',Icon='item_43014',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=602,Desc='哥夫内第一次做的防具， 据说他非常珍惜这肩饰。',Feature=1,}",
  [143015] = "{id=143015,NameZh='巴基力的披风[2]',Icon='2',Type=520,MaxNum=99,SellPrice=100,Desc='侍奉奥丁的战争姑娘的披风，华丽且轻巧。',Level=10,Feature=4,}",
  [143016] = "{id=143016,NameZh='生存斗篷[1]',Icon='item_43016',Type=520,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=480,Desc='不管在什么情况，让生存的可能性，极度提高的斗蓬。',Feature=1,}",
  [143017] = "{id=143017,NameZh='龙纹外套[1]',Icon='item_43017',Type=520,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=480,Desc='用300条龙皮制作的外套。传说可以抵抗魔龙的毒气。',Feature=1,}",
  [143018] = "{id=143018,NameZh='阿斯普利卡[2]',Icon='2',Type=520,MaxNum=99,SellPrice=100,Desc='将世界上所有的光收集起来做成的翅膀，拥有众神之光的意思。',Level=10,Feature=4,}",
  [143019] = "{id=143019,NameZh='三角兽之皮[2]',Icon='2',Type=520,MaxNum=99,SellPrice=100,Desc='皮毛之间长有植物茎干的三角兽之皮。',Level=10,Feature=4,}",
  [143020] = "{id=143020,NameZh='圣堂长袍[2]',Icon='2',Type=520,MaxNum=99,SellPrice=100,Desc='普隆德拉教堂为了保护圣职者而研发的牧师专用服装之一。',Level=10,Feature=4,}",
  [143021] = "{id=143021,NameZh='时间守护者披风[2]',Icon='2',Type=520,MaxNum=99,SellPrice=100,Desc='守护时间的披风，使用它可以免受时空撕扯的痛楚。',Level=10,Feature=4,}",
  [143022] = "{id=143022,NameZh='龙之披风[2]',Icon='2',Type=520,MaxNum=99,SellPrice=100,Desc='用飞龙的鬃毛制作而成的披风。',Level=10,Feature=4,}",
  [143024] = "{id=143024,NameZh='时之蓝披肩[1]',Icon='item_43024',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=540,Desc='侠盗时之蓝“工作”时所穿的蓝色披肩。',Feature=1,}",
  [143025] = "{id=143025,NameZh='背德皇帝的斗篷[1]',Icon='item_43025',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=540,Desc='据说该斗篷是大路王三世最喜欢的款式。',Feature=1,}",
  [143026] = "{id=143026,NameZh='棉衬衫[1]',Icon='item_43026',Type=520,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=320,Desc='纯棉制成的衣服，穿着时非常舒服的衣物。',Feature=1,}",
  [143027] = "{id=143027,NameZh='坚定斗篷[1]',Icon='item_43027',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=800,Desc='简约和有棱角的设计，让斗篷的使用者相信自己的意志似乎变得更坚定了。',Feature=1,}",
  [143028] = "{id=143028,NameZh='黑曜石斗篷[1]',Icon='item_43028',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=743,Desc='披风镶嵌有黑曜石，能让穿戴着的魔法防御确实提升。',Feature=1,}",
  [143029] = "{id=143029,NameZh='言灵护甲[1]',Icon='item_43029',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=507,Desc='在衣服上的符文是蕴含了魔力的古代文字。',Feature=1,}",
  [143030] = "{id=143030,NameZh='多芙的斗篷[1]',Icon='item_43030',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1204,Desc='看上去平平无奇的斗篷，只有穿上去才能感觉到与众不同。',Feature=1,}",
  [143031] = "{id=143031,NameZh='高等生存斗篷[1]',Icon='item_43031',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=960,Desc='把生存能力提高到极限的斗篷，可以对抗各种恶劣环境。',Feature=1,}",
  [143032] = "{id=143032,NameZh='坚定魔法斗篷[1]',Icon='item_43032',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1599,Desc='据说能让人的意志坚定斗篷，闪动着迷人的光芒。',Feature=1,}",
  [143033] = "{id=143033,NameZh='光明圣徒披风[1]',Icon='item_43033',Type=520,Quality=3,MaxNum=99,SellPrice=100,Desc='圣歌教会的锻造神工匠，人称“光明圣徒”的安德鲁冕下为那些英勇善战的教会勇士所设计的一套制式服装，防御力极其优秀。起初这套制式服装没有名字，但其优秀的防御力让所有勇士们都爱不释手，他们用锻造这安德鲁的称号来为这制式服装命名。这就是“光明圣徒”套装。这件为“光明圣徒”套装的披风部分。受到光明圣徒的祝福，安全精炼时消耗的装备件数减少一半。',Feature=1,}",
  [143034] = "{id=143034,NameZh='风行者斗篷[1]',Icon='item_43002',Type=520,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4480,Desc='精灵莱利斯使用的斗篷，穿上的人步伐隐秘，让人难以察觉。据说使用者可以得到风的青睐。',Feature=1,}",
  [143035] = "{id=143035,NameZh='变色龙披风[1]',Icon='item_43035',Type=520,MaxNum=99,SellPrice=100,}",
  [143036] = "{id=143036,NameZh='骷髅披风[1]',Icon='item_43036',Type=520,MaxNum=99,SellPrice=100,}",
  [143038] = "{id=143038,NameZh='预言者披风[1]',Icon='item_43038',Type=520,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=912,Desc='“我预言你会买下这件预言者披风！”——冒充预言家的梦罗克商人',}",
  [143039] = "{id=143039,NameZh='纳户特基格的斗篷[1]',Icon='item_43039',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='古老的秘密，暗黑的历史。在纳户特基格的斗篷下，藏匿着那些阳光下见不到的东西。',Feature=1,}",
  [143040] = "{id=143040,NameZh='吟游诗人的披风[1]',Icon='item_43040',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='过路人请留步，且听我抚琴唱起古老的传说，这件披风下，到底藏着多少故事呢？',Feature=1,}",
  [143041] = "{id=143041,NameZh='末日斗篷[1]',Icon='item_43041',Type=520,Quality=3,MaxNum=99,SellPrice=100,}",
  [143043] = "{id=143043,NameZh='狙击手斗篷[1]',Icon='item_43043',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=96000,Desc='为了狙击手设计的斗篷，隐蔽性极高。穿着它趴在草从中，能与环境融为一体。',}",
  [143044] = "{id=143044,NameZh='将军斗篷[1]',Icon='item_43044',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=42000,Desc='高阶军官的象征，华丽浮夸的外表下，其实具有很强的实用性。',}",
  [143046] = "{id=143046,NameZh='恐惧斗篷[1]',Icon='item_43046',Type=520,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=12000,Desc='无尽的黑暗笼罩在这件斗篷四周. 只有完全克服恐惧的人才可以使用。',}",
  [143047] = "{id=143047,NameZh='巡守队披风[1]',Icon='item_43001',Type=520,MaxNum=99,SellPrice=168,Desc='发放给加入巡守队的人的披风。飘动的背影看上去很帅。',Level=12,Feature=4,}",
  [143058] = "{id=143058,NameZh='衬衫★[1]',Icon='item_43058',Type=520,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='让人可以全力奔跑的轻便盔甲。虽然看上去和奔跑衬衫很相似，但具有盔甲的防御力。',}",
