  [143520] = "{id=143520,NameZh='脚链[2]',Icon='item_43503',Type=530,MaxNum=99,SellPrice=100,Desc='为了防止罪犯以及奴隶逃跑用来铐在他们脚上的物品。双脚脚踝上还悬挂着重物，让他们行动不便。',Level=15,Feature=4,}",
  [143521] = "{id=143521,NameZh='傅里哥长靴[2]',Icon='item_43503',Type=530,MaxNum=99,SellPrice=100,Desc='妙勒德的儿子菲依，对大地赋予祝福的靴子，菲依的祝福好像可以让痛苦解放似的。',Level=30,Feature=4,}",
  [143522] = "{id=143522,NameZh='阴影之靴[2]',Icon='item_43503',Type=530,MaxNum=99,SellPrice=100,Desc='用黑暗法术制作的靴子，使装备者融入黑暗之中。制作这个靴子的魔法师让穿上这个靴子的人在碰到危机时自行发动保护佩戴者的效果。',Level=10,Feature=4,}",
  [143523] = "{id=143523,NameZh='轻便鞋[1]',Icon='item_43523',Type=530,MaxNum=99,SellPrice=308,Desc='很方便着装的鞋子，不过没有什么防御力。',Level=22,}",
  [143524] = "{id=143524,NameZh='玻璃靴[1]',Icon='item_43524',Type=530,MaxNum=99,SellPrice=624,Desc='用玻璃制作的玻璃鞋，不考虑实用性，只考虑美观性的鞋子。',Level=52,}",
