  [143532] = "{id=143532,NameZh='军用便靴[1]',Icon='item_43532',Type=530,MaxNum=99,SellPrice=864,Desc='经历了多次战争不断修改设计并最终定型。重视实战效果的靴子。',Level=72,}",
  [143533] = "{id=143533,NameZh='制式便靴[1]',Icon='item_43533',Type=530,MaxNum=99,SellPrice=984,Desc='专门为佣兵定制的多用途靴子。适应各种复杂环境。',Level=82,}",
  [143534] = "{id=143534,NameZh='附魔战靴[1]',Icon='item_43534',Type=530,MaxNum=99,SellPrice=1104,Desc='靴子上的魔法符文储存有增强佩戴者属性的次级魔法。因为是魔法学徒的作品所以相对一般魔法道具要廉价得多。',Level=92,}",
  [143535] = "{id=143535,NameZh='坚定战靴[1]',Icon='item_43535',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=480,Desc='简约和有棱角的设计，让靴子的使用者相信自己的意志似乎变得更坚定了。',Feature=1,}",
  [143536] = "{id=143536,NameZh='迪斯凯特的便靴[1]',Icon='item_43536',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=300,Desc='据说是依照贤者迪斯凯特佣兵时代的穿着仿制的。虽然是仿制品，靴子的做工却意外的精良。',Feature=1,}",
  [143537] = "{id=143537,NameZh='布袋熊长靴[1]',Icon='item_43537',Type=530,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=480,Desc='魔物布袋熊的皮毛经过特殊手段制成的长靴。注意!是布袋熊不是拉链熊！',Feature=1,}",
  [143538] = "{id=143538,NameZh='魔磨长靴[1]',Icon='item_43538',Type=530,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=480,Desc='魔磨石粉末和特殊的凝胶混合成形的长靴。坚固却不失轻便。',Feature=1,}",
  [143539] = "{id=143539,NameZh='圣符长靴[1]',Icon='item_43539',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1018,Desc='研究古代符文的魔法师们在近代试制的第一批镶嵌了魔法符文的靴子。',Feature=1,}",
  [143540] = "{id=143540,NameZh='历战长靴[1]',Icon='item_43540',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1472,Desc='即使经历过残酷战争也还完好的耐用的靴子。',Feature=1,}",
  [143541] = "{id=143541,NameZh='多芙的战斗靴[1]',Icon='item_43541',Type=530,Quality=4,MaxNum=99,SellPrice=100,Feature=1,}",
  [143542] = "{id=143542,NameZh='迪斯凯特的雨靴[1]',Icon='item_43542',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=600,Desc='普通雨鞋，经过大贤者迪斯凯特的锻造后，拥有了惊人的效果。',Feature=1,}",
  [143543] = "{id=143543,NameZh='光明圣徒战靴[1]',Icon='item_43543',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='圣歌教会的锻造神工匠，人称“光明圣徒”的安德鲁冕下为那些英勇善战的教会勇士所设计的一套制式服装，防御力极其优秀。起初这套制式服装没有名字，但其优秀的防御力让所有勇士们都爱不释手，他们用锻造这安德鲁的称号来为这制式服装命名。这就是“光明圣徒”套装。这件为“光明圣徒”套装的战靴部分。受到光明圣徒的祝福，安全精炼时消耗的装备件数减少一半。',Feature=1,}",
  [143544] = "{id=143544,NameZh='圣符重靴[1]',Icon='item_43544',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1176,Desc='泛着古铜色的光芒，雕刻着神圣魔法阵法的靴子，拥有极大的防御能力。',Feature=1,}",
  [143545] = "{id=143545,NameZh='水晶靴[1]',Icon='item_43524',Type=530,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4480,Desc='使用稀有水晶精炼而成的靴子，精致而神秘，穿上能让人气质非凡。',Feature=1,}",
  [143546] = "{id=143546,NameZh='高等布袋熊长靴[1]',Icon='item_43546',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=1176,Desc='模仿布袋熊脚制成的靴子，看似可爱，实则可怕，可以让穿着者拥有布袋熊的移动速度。',Feature=1,}",
  [143547] = "{id=143547,NameZh='变色龙长靴[1]',Icon='item_43547',Type=530,MaxNum=99,SellPrice=100,}",
  [143548] = "{id=143548,NameZh='骷髅战靴[1]',Icon='item_43548',Type=530,MaxNum=99,SellPrice=100,}",
  [143550] = "{id=143550,NameZh='洗礼战靴[1]',Icon='item_43534',Type=530,MaxNum=99,SellPrice=1164,Desc='经过高级牧师洗礼祝福的战靴，虽然看上去笨重，实际上非常轻盈，装备者能感受到来自天神的祝福。',Level=97,}",
  [143551] = "{id=143551,NameZh='援护者皮靴[1]',Icon='item_43551',Type=530,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=672,Desc='经过高级牧师洗礼祝福的战靴，虽然看上去笨重，实际上非常轻盈，装备者能感受到来自天神的祝福。',Feature=1,}",
  [143552] = "{id=143552,NameZh='审判之靴[1]',Icon='item_43552',Type=530,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=1000,Desc='为了追捕恶魔，审判者必须前往许多地方，有时候甚至是异世界，所以这双靴子上拥有特殊魔法的祝福。',Feature=1,}",
  [143553] = "{id=143553,NameZh='白翼之靴[1]',Icon='item_43553',Type=530,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=1000,Desc='参照传说中赫尔墨斯的凉鞋设计而成的靴子，带有一对小翅膀，能让穿戴者步伐变得特别轻快。“别做梦了，要是穿着带翅膀的靴子就能随便飞起来的话，那还要飞空艇干嘛？”——某个飞空艇船长',Feature=1,}",
  [143554] = "{id=143554,NameZh='亡灵之靴[1]',Icon='item_43533',Type=530,MaxNum=99,SellPrice=2100,Desc='亡魂没有脚？谁说的？它们脚上的亡魂之靴就是最好的证据！',Level=95,}",
  [143555] = "{id=143555,NameZh='法力风暴之靴[1]',Icon='item_43555',Type=530,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='名字很帅，但事实上，这只是那些吉芬魔法师的自我陶醉，你以为穿上它就能掀起法力风暴？雷藏穿狼外婆的拖鞋都比你强。',Feature=1,}",
  [143556] = "{id=143556,NameZh='狼外婆的拖鞋[1]',Icon='item_43556',Type=530,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='狼外婆也很想穿高跟鞋，但是它脚趾甲太长，只能穿这种拖鞋了。',Feature=1,}",
  [143557] = "{id=143557,NameZh='舞蹈鞋[1]',Icon='item_43557',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='嗒嗒嗒，她旋转又踮起脚尖，露出苍白的微笑。跳舞的人，注定一辈子跳舞。',Feature=1,}",
  [143559] = "{id=143559,NameZh='古怪的鞋子[1]',Icon='item_43559',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=17280,Desc='如果不看紧这双鞋子，它会在你的眼皮底下溜走。',}",
  [143561] = "{id=143561,NameZh='恐惧战靴[1]',Icon='item_43561',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=12000,Desc='可自动调整穿者大小的神秘长靴, 就好像有生命力一样。',}",
  [143562] = "{id=143562,NameZh='喵族优雅鞋子[1]',Icon='item_43562',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=7200,Desc='鞋底柔软得让人难以置信，在各种地形上都能悄无声息地行走。',}",
  [143563] = "{id=143563,NameZh='巡守队靴子[1]',Icon='item_43501',Type=530,MaxNum=99,SellPrice=20,Desc='发放给巡守队成员的靴子。走很长时间路也不会疲劳，专为冒险设计的鞋子。',Level=1,Feature=4,}",
