  [143588] = "{id=143588,NameZh='牧童马刺靴[1]',Icon='item_43588',Type=530,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=90000,Desc='要不是这场战争，他可以在家悠闲的牧牛，与邻家的少女并肩躺在草地上，哼着歌度过无忧无虑的一天——“快了，等打完这一仗，就能回家了！”',Feature=1,}",
  [143589] = "{id=143589,NameZh='狙击手的长靴[1]',Icon='item_43589',Type=530,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='由修发兹共和国制式军靴改造成的鞋子，结实耐磨损，保障枪手在各种恶劣的地形都能高效战斗。',Feature=1,Delete=143589}",
  [143590] = "{id=143590,NameZh='游猎者之靴[1]',Icon='item_43590',Type=530,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='使用雷根贝勒公司最新技术打造的高科技战靴，可以吸收冲击力、增强弹跳力，极大增强枪手们战斗的机动性。',Feature=1,Delete=143590}",
  [143591] = "{id=143591,NameZh='敏捷补充装置[1]',Icon='item_43591',Type=530,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='鞋底安装了可以储存魔力的魔法装置，在危急时刻可以爆发魔力让使用者健步如飞，脱离危险。',}",
  [143592] = "{id=143592,NameZh='锻钢战靴[1]',Icon='item_43516',Type=530,Quality=2,MaxNum=99,SellPrice=100,Desc='锻钢打造的战靴，虽然沉重，但防护性上佳。',Delete=143592}",
  [143593] = "{id=143593,NameZh='精炼战靴[1]',Icon='item_43593',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='将锻钢反复精炼去除杂质，在保证了防护性的前提下大幅减轻了重量，是雷根弗莱格家族上流工艺的展现。',Delete=143593}",
  [143594] = "{id=143594,NameZh='超能机甲战靴[1]',Icon='item_43594',Type=530,Quality=4,MaxNum=99,SellPrice=100,Desc='使用雷根弗莱格家族秘藏的超能机甲作为动力源打造的战靴，是米德加尔特无数匠人梦寐以求的超前工艺制品。',Delete=143594}",
  [143595] = "{id=143595,NameZh='羽毛鞋[1]',Icon='item_43529',Type=530,Quality=2,MaxNum=99,SellPrice=100,Desc='装饰着羽毛的布靴，主要优点是轻便。',Delete=143595}",
  [143596] = "{id=143596,NameZh='轻灵之鞋[1]',Icon='item_43596',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='穿上后感觉自己身轻如燕。奈利乌斯家族代代家主均为女性，这双鞋也是为她们量身打造的。',Delete=143596}",
  [143597] = "{id=143597,NameZh='天风飞羽[1]',Icon='item_43597',Type=530,Quality=4,MaxNum=99,SellPrice=100,Desc='穿上这双鞋，就如同乘坐洁白的羽毛船在蔚蓝的天空中飞翔。',Delete=143597}",
  [143598] = "{id=143598,NameZh='龙皮靴[1]',Icon='item_43538',Type=530,Quality=2,MaxNum=99,SellPrice=100,Desc='龙皮制成的靴子，坚硬无比。',Delete=143598}",
  [143599] = "{id=143599,NameZh='斩龙者战靴[1]',Icon='item_43599',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='使用巨龙的头骨制成的靴子，是斩龙者荣耀的象征。',Delete=143599}",
  [143600] = "{id=143600,NameZh='卢恩的纪念[1]',Icon='item_43600',Type=530,Quality=4,MaxNum=99,SellPrice=100,Desc='雕画着卢恩符文的龙骨靴，传说当年特里斯坦一世开国时曾将这双靴子赠送给最强的勇士，并代代流传。',Delete=143600}",
  [143601] = "{id=143601,NameZh='勇武战靴[1]',Icon='item_43552',Type=530,Quality=2,MaxNum=99,SellPrice=100,Desc='对勇武者的尊崇，从上古时代便已经开始，这双战靴彰显了武者的光辉。',Delete=143601}",
  [143602] = "{id=143602,NameZh='统治者战靴[1]',Icon='item_43602',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='精美的花纹展现出与平常士兵不同的等级，穿着它，其他人自然会高看一眼。',Delete=143602}",
  [143603] = "{id=143603,NameZh='霸主战靴[1]',Icon='item_43603',Type=530,Quality=4,MaxNum=99,SellPrice=100,Desc='一代霸主才能驾驭的华丽战靴，每条纹路都是功勋的象征。',Delete=143603}",
  [143604] = "{id=143604,NameZh='传承之靴[1]',Icon='item_43551',Type=530,Quality=2,MaxNum=99,SellPrice=100,Desc='韦格纳家族相信，勤勤恳恳的传承传统，就能维系贵族的太阳永不落幕。',Delete=143604}",
  [143605] = "{id=143605,NameZh='荣耀战靴[1]',Icon='item_43605',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='历史的长河中，刻满了战碑与荣耀。',Delete=143605}",
  [143606] = "{id=143606,NameZh='特里斯坦的恩典[1]',Icon='item_43606',Type=530,Quality=4,MaxNum=99,SellPrice=100,Desc='韦格纳家族相信，这片土地正是特里斯坦赐予韦格纳家族的恩典，即使今日风光不再，也依然能保持贵族的品格。',Delete=143606}",
  [143607] = "{id=143607,NameZh='天秤靴子[1]',Icon='item_43559',Type=530,Quality=2,MaxNum=99,SellPrice=100,Desc='绣着天平花纹的布艺短靴，简洁轻便，是奈利乌斯家族平民常见的服饰。',Delete=143607}",
  [143608] = "{id=143608,NameZh='平衡之理靴子[1]',Icon='item_43608',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='维系天平平衡的，并非两段承托之物的重量，而是执掌者心中的平衡之理。',Delete=143608}",
  [143609] = "{id=143609,NameZh='公正的审判[1]',Icon='item_43609',Type=530,Quality=4,MaxNum=99,SellPrice=100,Desc='奈利乌斯的执掌者赐予人们公正的审判，这种公正之力化为家族的威信，寄托于造物之上。',Delete=143609}",
  [143610] = "{id=143610,NameZh='宗族皮靴[1]',Icon='item_43577',Type=530,Quality=2,MaxNum=99,SellPrice=100,Desc='王室赠予宗族的皮靴，是家族的得力干将才能享有的。',Delete=143610}",
  [143611] = "{id=143611,NameZh='继承者皮靴[1]',Icon='item_43611',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='家族继承者的皮靴，寄托着宗族对持有者的未来期待，也是家族地位的象征。',Delete=143611}",
  [143612] = "{id=143612,NameZh='血脉熔炉[1]',Icon='item_43612',Type=530,Quality=4,MaxNum=99,SellPrice=100,Desc='血脉是最深刻的熔炉，人一生的命运都镌刻在血脉之上，而王室的血脉，则是后来者的光荣。',Delete=143612}",
  [143613] = "{id=143613,NameZh='彗星短靴[1]',Icon='item_43586',Type=530,Quality=2,MaxNum=99,SellPrice=100,Desc='彗星坠落的夜晚，充盈的祝福能量让奈利乌斯家的巧匠们轻松制造出大量短靴，他们便以彗星为它们命名。',Delete=143613}",
  [143614] = "{id=143614,NameZh='启明星短靴[1]',Icon='item_43614',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='在启明星升起的那一刻，奈利乌斯家族的鞋匠们恰巧赶制出这双短靴。',Delete=143614}",
  [143615] = "{id=143615,NameZh='永恒双子星[1]',Icon='item_43615',Type=530,Quality=4,MaxNum=99,SellPrice=100,Desc='双子星的祝福，赐予奈利乌斯家族永恒的力量源泉。',Delete=143615}",
  [143616] = "{id=143616,NameZh='朴素短靴[1]',Icon='item_43503',Type=530,Quality=2,MaxNum=99,SellPrice=100,Desc='一双规整的短靴，穿上去还算舒适。',Delete=143616}",
  [143617] = "{id=143617,NameZh='守序短靴[1]',Icon='item_43617',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='雷根弗莱格家族笃信，只有遵循规则，才能实现家族永恒的繁荣昌盛，即使在打造短靴时，也力求严丝合缝。',Delete=143617}",
  [143618] = "{id=143618,NameZh='秩序守护者[1]',Icon='item_43618',Type=530,Quality=4,MaxNum=99,SellPrice=100,Desc='守护米德加尔特的秩序，守护卢恩王国的秩序，七王室的规则不可更改，唯有守序者方能维系一族的宿命。',Delete=143618}",
  [143619] = "{id=143619,NameZh='深海战靴[1]',Icon='item_43587',Type=530,Quality=2,MaxNum=99,SellPrice=100,Desc='深海之中，除了幽暗，还有更深的幽暗……',Delete=143619}",
  [143620] = "{id=143620,NameZh='远航者战靴[1]',Icon='item_43620',Type=530,Quality=3,MaxNum=99,SellPrice=100,Desc='巴尔特家族的先祖曾经穿着这样的战靴远赴修发兹共和国，带来了巴尔特家族的第一桶金。',Delete=143620}",
  [143621] = "{id=143621,NameZh='诸海之皇[1]',Icon='item_43621',Type=530,Quality=4,MaxNum=99,SellPrice=100,Desc='掌握着巨额财富的海洋之王，巴尔特家族的航线遍布诸海，这双战靴正是海洋上的恶魔商人的象征。',Delete=143621}",
