  [144315] = "{id=144315,NameZh='蔷薇灵语狐尾草[2]',Icon='item_44315',Type=190,MaxNum=99,SellPrice=3200,Desc='妖精一族的“灵语师”都是植物学专家，它们甚至能将蔷薇嫁接在狐尾草上！',Level=110,LoadShowSize=1.2,LoadShowPose={0,0.25,0},Delete=144315}",
  [144317] = "{id=144317,NameZh='湛蓝天光·狐尾草[2]',Icon='item_44317',Type=190,MaxNum=99,SellPrice=2800,Desc='阔大的云海之上透出湛蓝天光，晴空下的战士们振作起了精神。蓝色狐尾草印证着你的忠诚，勇敢与希望。',Level=110,Delete=144317}",
  [144326] = "{id=144326,NameZh='圣徒·狐尾草[2]',Icon='item_44326',Type=190,Quality=3,MaxNum=99,SellPrice=100,Desc='圣歌教会虔诚的多兰族信徒奥摩里使用的狐尾草，拥有极其优秀的攻击力，这个狐尾草还有个极其重要的特点：那就是信仰越虔诚，狐尾草能发挥的力量越强大。',Delete=144326}",
  [144345] = "{id=144345,NameZh='远古回音·狐尾草[2]',Icon='item_44345',Type=190,MaxNum=99,SellPrice=3200,Desc='铭刻着神秘纹样的狐尾草，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,Delete=144345}",
  [144600] = "{id=144600,NameZh='风魔轮飞镖[2]',Icon='item_44600',Type=300,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='经忍法大师“果心居士”改良的风魔手里剑，可以附着灵气，增强各种忍法的威力。',Delete=144600}",
  [144601] = "{id=144601,NameZh='风魔飞镖-启明星[2]',Icon='item_44601',Type=300,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='“果心居士”使用陨石碎片打造的风魔飞镖，借助星辰之力可以释放强大的忍法。',Delete=144601}",
  [144602] = "{id=144602,NameZh='名刀-村正[2]',Icon='item_44602',Type=180,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='由天水之国的刀匠世家“村正家族”打造的太刀。村正家族追求实用，只打造锋利坚韧、用于实战的刀具，而其中最顶尖的才能被冠以“名刀”之名。',Delete=144602}",
  [144603] = "{id=144603,NameZh='妖刀-村正[2]',Icon='item_44603',Type=180,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='刀匠世家“村正家族”初代家主亲手打造的名刀，由于斩杀了过多恶魔被邪恶的怨力侵蚀，意志薄弱者触碰此刀便会被怨力控制，失去神智，因此这把刀被人们称为“妖刀”。但若是能凭借强大的意志力驱散怨力，这把“妖刀”将成为斩妖除魔的利器！',Delete=144603}",
  [144604] = "{id=144604,NameZh='风魔手里剑[2]',Icon='item_44604',Type=300,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='忍者世家“风魔一族”的独门兵器，虽然威力巨大但是难以操控，需要长时间的训练否则容易划伤自己。',Delete=144604}",
  [144605] = "{id=144605,NameZh='风魔手里剑-疾影[2]',Icon='item_44605',Type=300,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='风魔小太郎斩杀了为祸天津町的巨蛇，在蛇腹中发现一块坚硬无比的巨石，最锋利的刀剑也无法在这块石头上留下丝毫痕迹，只有巨蛇的毒液能够将它融化。风魔小太郎将巨石打造为无坚不摧的风魔手里剑，用它消灭了无数侵犯天水之国的恶魔。',Delete=144605}",
  [144616] = "{id=144616,NameZh='圣徒风魔轮[2]',Icon='item_44616',Type=300,Quality=3,MaxNum=99,SellPrice=100,Desc='圣歌教会虔诚的信徒周里使用的风魔轮，拥有极其优秀的攻击力，这个风魔轮还有个极其重要的特点：那就是信仰越虔诚，风魔轮能发挥的力量越强大。',Delete=144616}",
  [144638] = "{id=144638,NameZh='远古回音·风魔轮[2]',Icon='item_44638',Type=300,MaxNum=99,SellPrice=3200,Desc='铭刻着神秘纹样的风魔轮，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,Delete=144638}",
