  [145173] = "{id=145173,NameZh='盲目的斗篷[1]',Icon='item_45173',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=2040,AdventureSort=633,AdventureValue=210,AdventureReward={buffid={60002230}},StorageReward={buffid={80011170}},Condition=4,ComposeID=14173,Desc='用布制作的紫色斗篷，好像适合于遮盖阴暗的脸。在黑暗的纱布遮挡下，红色眼睛散发着阴暗的气息。',Share=1,Feature=1,RefineStorageReward={{buffid={65000140},lv=6},{buffid={66000380},lv=8}},}",
