  [145193] = "{id=145193,NameZh='迪斯凯特的头盔[1]',Icon='item_45193',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=2040,AdventureSort=110,AdventureValue=140,AdventureReward={buffid={60000260}},StorageReward={buffid={80011170}},Condition=4,ComposeID=14193,Desc='据说是依照贤者迪斯凯特佣兵时代的穿着仿制的。虽然是仿制品，头盔的做工却意外的精良。',Share=1,Feature=1,LoadShowSize=2,LoadShowPose={0,0.6,0},}",
  [145194] = "{id=145194,NameZh='融化中的雪糕[1]',Icon='item_45194',Type=800,MaxNum=99,SellPrice=100,AdventureSort=10001,AdventureValue=1,StorageReward={buffid={80011150}},Condition=8,Desc='每当戴上就会想起那个舔着雪糕，和大家一起等待Summer Test的夏天。吃完雪糕，可以看见木棍上写着“RO 2016·夏”。',Share=1,Feature=1,}",
  [145195] = "{id=145195,NameZh='乐园团圆帽[1]',Icon='item_45195',Type=800,MaxNum=99,AuctionPrice=1,SellPrice=200,AdventureSort=104,AdventureValue=40,AdventureReward={buffid={60000260}},StorageReward={buffid={80011150}},Condition=4,ComposeID=14195,Desc='只发给乐园团成员的帽子，其设计感与制服相当搭配。',Share=1,Feature=1,}",
  [145196] = "{id=145196,NameZh='冷酷的棒球帽子[1]',Icon='item_45196',Type=800,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10002,AdventureValue=1,StorageReward={buffid={80011150}},Condition=8,Desc='「聆听·爱与勇气的声音」主题音乐会纪念：一顶穿越时空、跨越次元、连接种族的冷酷帽子。至少哥布灵是这么认为的！',Share=1,Feature=1,}",
  [145197] = "{id=145197,NameZh='百万击破[1]',Icon='item_45197',Type=800,MaxNum=99,SellPrice=100,Desc='跃动而出的魄力数字，不但饱含着人们的期待和盼望，更融合了超过上百万份的爱与信仰。独一无二的特殊工艺，只为参与这段新冒险路程的你而定做。初心者！冒险旅程就此开启！',Share=1,}",
  [145198] = "{id=145198,NameZh='枫叶[1]',Icon='item_45198',Type=800,MaxNum=99,SellPrice=100,Desc='散落一地的枫叶，是我们一起走过的秋日纪念，我拾起其中一片，顶在头上，想起大家温暖的脸。',Share=1,}",
  [145199] = "{id=145199,NameZh='圣诞帽[1]',Icon='item_45199',Type=800,MaxNum=99,SellPrice=100,Desc='爱在RO的雪季，美丽的圣诞季节，谨以此作为纪念。',Share=1,}",
  [145201] = "{id=145201,NameZh='恶兽头冠[1]',Icon='item_45201',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=2040,AdventureSort=10006,AdventureValue=1,AdventureReward={buffid={60000260}},StorageReward={buffid={80011170}},Condition=4,ComposeID=14201,Desc='仿造春节才会出现的年兽而制作的头饰，栩栩如生。',Share=1,Feature=1,}",
  [145202] = "{id=145202,NameZh='歉意头饰[1]',Icon='item_45202',Type=800,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10008,AdventureValue=1,AdventureReward={buffid={60000030}},StorageReward={buffid={80011150}},Condition=4,ComposeID=14202,Desc='创造着这个美丽冒险世界的B格猫们表示，谨以此特别的头饰来铭记所有点点滴滴的尊重宽容和理解。每天看到它的时候就提醒自己，还需要不停努力为这个世界创造更多更新更有爱的内容，只为支持我们的所有冒险者们！',Share=1,Feature=1,}",
  [145203] = "{id=145203,NameZh='修女的帽子[1]',Icon='item_45203',Type=800,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=4060,AdventureSort=634,AdventureValue=300,AdventureReward={buffid={60001980}},StorageReward={buffid={80011260}},Condition=4,ComposeID=14203,Desc='大教堂里修女们所带的帽子，可以遮掩住头发有点自律意义的内涵。',Share=1,Feature=1,RefineStorageReward={{buffid={65000270},lv=6},{buffid={66000060},lv=8}},}",
