  [145280] = "{id=145280,NameZh='学士帽[1]',Icon='item_45280',Type=800,MaxNum=99,SellPrice=100,}",
  [145281] = "{id=145281,NameZh='黑魔女魔法帽[1]',Icon='item_45281',Type=800,MaxNum=99,SellPrice=100,}",
  [145282] = "{id=145282,NameZh='蜂蜜蛋糕[1]',Icon='item_45282',Type=800,MaxNum=99,SellPrice=100,}",
  [145283] = "{id=145283,NameZh='金色的进行曲[1]',Icon='item_45283',Type=840,MaxNum=99,SellPrice=100,Desc='时值初秋。贝尔佛第宫的仆人们正在忙着里外奔波，这里即将举行盛大的茶会。届时将有世界各地的贵妇人们身穿雍容华贵的服装佩戴着各种璀璨夺目的宝石前来参加这场盛宴，美学与美学的直接碰撞，在皇家仪仗队的鼓点声中，这场“演出”才刚开始。',}",
  [145284] = "{id=145284,NameZh='致·爱丽丝[1]',Icon='item_45284',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9510,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='少年在整理曾祖母遗物的时候发现了一个尘封已久的小小古典木箱，时隔几个世纪后这部即将影响后人的作品再次沐浴在阳光下。世间人们早已无人知晓真正的故事，但是少年手上的那把钥匙依然刻着曾经的那段美丽的心愿。',Feature=1,}",
  [145285] = "{id=145285,NameZh='夜后的咏叹调[1]',Icon='item_45285',Type=830,Quality=2,MaxNum=99,SellPrice=100,Desc='“亨切利~亨切利~哦，这小家伙又上哪里去了，让他好好整理乐谱书籍的事居然到现在都还没办！真是气死我了！”“亨切利，我和你说了多少次了，那个倒霉笨蛋音乐家的事你就别去管他了，见鬼~你有没有在听！这套叫《魔笛》的乐谱根本就没有销路，不要再练习了，回来搬书，我还有很多东西要你做！比如…”',}",
  [145286] = "{id=145286,NameZh='月·光[1]',Icon='item_45286',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9512,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='【月光为桨，莲花作舟；皮埃罗向着南方顺风启程了。流水哼着深沉的曲调，摇晃着单薄的小船。月光为桨，莲花作舟。回贝加莫去，回故乡去，皮埃罗踏上了归途；看东方苍苍的地平线泛起了蒙蒙曙光。……月光为桨。】',Feature=1,}",
  [145287] = "{id=145287,NameZh='小恶魔耳机[1]',Icon='item_45287',Type=800,MaxNum=99,SellPrice=100,}",
  [145288] = "{id=145288,NameZh='南瓜发带[1]',Icon='item_45288',Type=800,MaxNum=99,SellPrice=100,}",
  [145291] = "{id=145291,NameZh='勇者都怕我[1]',Icon='item_45291',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9516,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='经历了无数的辗转和颠簸，无数次的领土扩张，魔王终于拥有了自己的国度，以他的美学所定义的“自由”国度，即使没有了夜之少女的歌唱，依然有诗篇记录着这段历史-孑然一身独自君临着这个幻想国度的魔王。',Feature=1,}",
  [145293] = "{id=145293,NameZh='艾希头饰[1]',Icon='item_45293',Type=800,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10019,AdventureValue=90,StorageReward={buffid={80012350}},Condition=8,Desc='艾希在无尽的轮回中，获得了真正的自我。时间空间流转，她，成为了旅人。',Feature=1,}",
  [145294] = "{id=145294,NameZh='卡普拉女仆头带[1]',Icon='item_45294',Type=800,MaxNum=99,SellPrice=100,}",
  [145295] = "{id=145295,NameZh='卡普拉头饰[1]',Icon='item_45295',Type=800,MaxNum=99,SellPrice=100,}",
  [145297] = "{id=145297,NameZh='白色圣诞[1]',Icon='item_45297',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9521,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='“祖母躺在吱呀吱呀如同钟摆节奏般的老旧木质躺椅上，一针一线纺织着鲜艳色彩的袜子，父亲挂在壁炉上的冬青花环在噼里啪啦的火光中照耀显得更加鲜艳。母亲正在忙碌的厨房里飘出了各种孩子们根本无法忍受的诱惑香味。呼口气就能变成水晶的玻璃外，银色正在悄然地包裹着城市，映照出红彤彤的可爱脸颊和清澈如阿瓦隆湖水一样的眼瞳。”“啊~我们在此许愿~”',Feature=1,}",
  [145298] = "{id=145298,NameZh='加油小鹿[1]',Icon='item_45298',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9522,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='“打开天窗等待着他，床边放着袜子等待着他，虚掩着门扉等待着他，兴奋又想偷看结果还是睡着的夜晚~啦啦啦~啦啦啦啦~红鼻子的鲁道夫今晚就要飞过我的窗口，今年他也会停留吧？啦啦啦~啦啦啦~红鼻子的鲁道夫驮着那个人，在长大前好想见他一面。”',Feature=1,}",
  [145299] = "{id=145299,NameZh='JingleBell[1]',Icon='item_45299',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9524,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='【叮叮当！叮叮当！铃儿响叮当，我们在敞篷雪橇上滑雪多快乐。冲破大风雪，我们坐在雪橇上。飞驰过田野，一直伴随着笑声。铃声儿响彻四方，我们情绪高涨，笑得多开心，雪橇之歌今夜唱。叮叮当，叮叮当，铃儿响叮当……】',Feature=1,}",
  [145400] = "{id=145400,NameZh='冰苹果[1]',Icon='item_45400',Type=800,Quality=3,MaxNum=99,SellPrice=2040,AdventureSort=795,AdventureValue=210,AdventureReward={buffid={61000470}},StorageReward={buffid={80012620}},Condition=8,ComposeID=14400,Feature=1,}",
