  [145425] = "{id=145425,NameZh='恶魔趴趴猫[1]',Icon='item_45425',Type=800,MaxNum=99,SellPrice=100,AdventureReward={buffid={61000510}},StorageReward={buffid={80012680}},Feature=1,StageDisplay=0,}",
  [145426] = "{id=145426,NameZh='金色三连星[1]',Icon='item_45426',Type=800,MaxNum=99,SellPrice=100,AdventureReward={buffid={61000480}},StorageReward={buffid={80012660}},Feature=1,StageDisplay=0,}",
  [145427] = "{id=145427,NameZh='生命药瓶[1]',Icon='item_45427',Type=800,MaxNum=99,SellPrice=100,AdventureReward={buffid={61000470}},StorageReward={buffid={80012660}},Feature=1,LoadShowSize=2,LoadShowPose={0,0.35,0},}",
  [145431] = "{id=145431,NameZh='神隐拉面（旧）[1]',Icon='item_45431',Type=800,Quality=2,MaxNum=99,SellPrice=100,Desc='【AORI酱走遍千山万水，只为了找到自己的父亲】',}",
  [145432] = "{id=145432,NameZh='神隐拉面[1]',Icon='item_45432',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10044,AdventureValue=1,StorageReward={buffid={80012720}},Condition=4,ComposeID=14431,Desc='【AORI酱走遍千山万水，只为了找到自己的父亲】',Feature=1,}",
  [145433] = "{id=145433,NameZh='莎蔓芭亚帽[1]',Icon='item_45433',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=2040,AdventureSort=757,AdventureValue=210,AdventureReward={buffid={61000480}},StorageReward={buffid={80012660}},Condition=4,ComposeID=14433,Feature=1,}",
  [145434] = "{id=145434,NameZh='普隆德拉的守护[1]',Icon='item_45434',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9527,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='“我真的很讨厌这里！”凯莉赌气地说道，“这里人声又嘈杂，每天到哪里都有穿着各种奇装异服的家伙假装要好心帮忙来勾搭！”，“…莫名其妙又把这个月探险经费都去购买了一堆没有用的帽子！每天都勾引我！每天都勾引我！”，“哼！我真的讨厌这里。”凯莉说着说着，生气的表情里流着眼泪开始笑了，她转过头去，此时一阵微风吹拂过首都广场中央的景观喷泉，将少女美丽的黑发悠然地抛向天空。嗯~这孩子，还真是喜欢这里呢！',Feature=1,}",
  [145435] = "{id=145435,NameZh='爱的蛋糕[1]',Icon='item_45435',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9528,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='生日快乐，跟我一起闭上眼睛吧~然后在心中偷偷许下一个狡猾的心愿，也许你向我告白的那天，我会勉为其难地告诉你这个秘密呢~，然后，跟我一起蓄力3秒，“呼~~~”一起',Feature=1,}",
  [145436] = "{id=145436,NameZh='波利花环[1]',Icon='item_45436',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9529,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='“嘿~伙计，听说了吗。休整了超久的波利岛国家野生生态乐园又对外开放了呢！”“哇哦~OAO~真的么？！安娜小姐姐一直非常喜欢各种颜色的波利呢！看来这次的约会稳了。嘻嘻嘻嘻….”，“哦喂…你小子那么得意干嘛，我诅咒你约会当天就遇到幽灵波利！！！！”，“…你，你这还算是死党吗！可恶！”（打闹声响彻整个冒险公会的休息室…并且看来还要好一会儿…）',Feature=1,}",
  [145437] = "{id=145437,NameZh='梦想的纸飞机[1]',Icon='item_45437',Type=800,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80012730}},Feature=1,}",
  [145438] = "{id=145438,NameZh='米德加尔特护卫头盔[1]',Icon='item_45438',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=52001,AdventureValue=160,StorageReward={buffid={80012820}},Condition=8,Feature=1,}",
  [145447] = "{id=145447,NameZh='草莓布丁大作战[1]',Icon='item_45447',Type=800,MaxNum=99,SellPrice=100,}",
  [145448] = "{id=145448,NameZh='流金四溢[1]',Icon='item_45448',Type=800,MaxNum=99,SellPrice=100,}",
  [145449] = "{id=145449,NameZh='猫猫棉花糖[1]',Icon='item_45449',Type=800,MaxNum=99,SellPrice=100,}",
  [145451] = "{id=145451,NameZh='黄金大巴帽[1]',Icon='item_45451',Type=800,Quality=4,MaxNum=99,SellPrice=100,Feature=1,}",
  [145452] = "{id=145452,NameZh='戌头巾[1]',Icon='',Type=800,MaxNum=99,SellPrice=100,AdventureReward={buffid={61000450}},StorageReward={buffid={80012640}},Condition=4,ComposeID=14452,Feature=1,}",
  [145464] = "{id=145464,NameZh='王子的冠冕[1]',Icon='item_145464',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9534,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='“童话故事的最后，王子和公主幸福地生活在了一起。合上绘本的最后一页。天空中浮现着这个送给认真读完故事的孩子的图纸，并在很短的时间，由故事书里的文字碎片组成了这个头饰。在淡淡的光晕中，这个天降之物来来到了你的手中',Feature=1,}",
  [145465] = "{id=145465,NameZh='公主的冠冕[1]',Icon='item_145465',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9535,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='“童话故事的最后，王子和公主幸福地生活在了一起。合上绘本的最后一页。天空中浮现着这个送给认真读完故事的孩子的图纸，并在很短的时间，由故事书里的文字碎片组成了这个头饰。在淡淡的光晕中，这个天降之物来来到了你的手中',Feature=1,}",
  [145466] = "{id=145466,NameZh='狐王的笑脸[1]',Icon='item_45466',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=763,AdventureValue=210,AdventureReward={buffid={61000550}},StorageReward={buffid={80012640}},Condition=4,ComposeID=14466,Desc='有一名樵夫曾在朔月的夜晚见过一只黝黑的狐狸，他看见那只狐狸对着月亮跪拜祈祷，他痴迷的看着这一幕，没注意到这只狐狸转头发现了他！那只狐狸满脸都是金色的花纹，咧着嘴巴对他嘻嘻地笑，眼睛里却是一片寒意……狐王的笑脸，看见的人会受到狐王的驱使，变为狐狸的奴隶！',Feature=1,}",
  [145467] = "{id=145467,NameZh='汪汪上校[1]',Icon='item_45467',Type=800,MaxNum=99,SellPrice=100,StorageReward={buffid={80012660}},ComposeID=14467,Desc='非常帅气的上校制服帽！竖立的汪耳一看就威风凛凛英气十足的样子',Feature=1,}",
  [145468] = "{id=145468,NameZh='好痛！犬妖趴趴[1]',Icon='item_45468',Type=800,MaxNum=99,SellPrice=100,StorageReward={buffid={80012660}},ComposeID=14468,Feature=1,}",
  [145469] = "{id=145469,NameZh='火鸡头饰[1]',Icon='item_45469',Type=800,MaxNum=99,SellPrice=100,}",
  [145534] = "{id=145534,NameZh='幻月樱·星光船[1]',Icon='item_45534',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9537,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='“怀抱江中山河月，笑品世间朝午夜。”“花颜绝代 终飘零、现世何者 可长久。”浮世绘般的幻想月下，绽放的华丽画卷，风云怒涛海上舟，星光流连祈福世间，在这樱花之季降临。',Feature=1,LoadShowPose={0,0,0},}",
  [145535] = "{id=145535,NameZh='名物·千紫万红[1]',Icon='item_45535',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9540,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='遥远东方的天水之国，早在樱花城以及天津町落成前的时代，在传说中的歌舞伎所佩戴的头饰。因为饱含着千年风华的魅力，至今依然能感到佳人的芳踪。',Feature=1,}",
  [145543] = "{id=145543,NameZh='要迟到啦！[1]',Icon='item_45543',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9547,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='可以是魔咒，也可以是战歌，是最高神圣天庭的最终审判，也是向美好世界献上祝福的前奏曲。在这思考的24.07秒时间内，你最后还是决定起床，换上母亲新洗过的制服，那上面还有阳光的味道。',Feature=1,}",
  [145544] = "{id=145544,NameZh='头饰-头饰 配色1[1]',Icon='item_45544',Type=800,MaxNum=99,SellPrice=100,}",
  [145545] = "{id=145545,NameZh='头饰-头饰 配色2[1]',Icon='item_45545',Type=800,MaxNum=99,SellPrice=100,}",
  [145546] = "{id=145546,NameZh='头饰-头饰 配色3[1]',Icon='item_45546',Type=800,MaxNum=99,SellPrice=100,}",
  [145547] = "{id=145547,NameZh='头饰-头饰 配色4[1]',Icon='item_45547',Type=800,MaxNum=99,SellPrice=100,}",
  [145548] = "{id=145548,NameZh='大吉大利桶[1]',Icon='item_45548',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureReward={buffid={61000560}},StorageReward={buffid={80012610}},}",
  [145549] = "{id=145549,NameZh='炸鸡勇者[1]',Icon='item_45549',Type=800,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10064,AdventureValue=160,StorageReward={buffid={80012850}},Condition=8,Desc='由米德加尔特大陆的能工巧匠和异世界的神秘白胡子爷爷联合打造的超高级华丽冠羽。绝无仅有的绝版头饰，只属于真正的炸鸡勇者！',Feature=1,}",
  [145574] = "{id=145574,NameZh='金苹果的秘密[1]',Icon='item_45574',Type=800,Quality=3,MaxNum=99,SellPrice=100,Desc='传说神族之间的婚礼有一项习俗，用箭矢射中天地树上的金苹果，就能保佑婚姻美满，永远和睦…至于为什么会这样，恐怕人类是无法搞懂了。',Feature=1,}",
  [145575] = "{id=145575,NameZh='朱诺守备官[1]',Icon='item_45575',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=767,AdventureValue=80,AdventureReward={buffid={61001140}},StorageReward={buffid={80012660}},Condition=8,Desc='被朱诺市民评为最让人有安全感的帽子，只要看到戴着它的人来了，那正义也就来了。',Feature=1,}",
  [145588] = "{id=145588,NameZh='熊猫和波利的竹子[1]',Icon='item_45588',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9549,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='“出生于1997年的小菲，平常最喜欢做的事之一就是打开在航天局工作的父亲所赠送的小平板，看着童年时父亲一直带他去看的熊猫小盼，看着小盼优雅啃着竹子然后睡去再醒来，一个假日很快就度过了。真希望父亲能早日回来陪我玩~”',Feature=1,}",
  [145589] = "{id=145589,NameZh='金字塔的谜题[1]',Icon='item_45589',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9551,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='将【生】与【死】编译成【幻想游戏】，承载着数千年的人之两面。见证着死灵之书、戏弄着俄狄浦斯王、迎接着迁徙者的面纱。这个蓝色星球上最大的魔方里究竟还富藏着多少深邃的奥秘呢？',Feature=1,}",
  [145590] = "{id=145590,NameZh='东京铁塔之恋[1]',Icon='item_45590',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9552,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='我爱上一盏街灯，我爱上一种余温。而我爱上某一个人，爱上那诱人的香氛。在异国铁塔的观光层，我痴情期待着你的吻。',Feature=1,}",
  [145591] = "{id=145591,NameZh='冒险火车头[1]',Icon='item_45591',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012640}},Feature=1,}",
  [145592] = "{id=145592,NameZh='愤怒的撒旦[1]',Icon='item_45592',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012660}},Feature=1,}",
  [145593] = "{id=145593,NameZh='六月扭蛋头饰2[1]',Icon='item_45593',Type=800,MaxNum=99,SellPrice=100,Feature=1,Delete=145593}",
  [145600] = "{id=145600,NameZh='趴趴迪迦[1]',Icon='item_45600',Type=800,Quality=3,MaxNum=99,SellPrice=100,Desc='趴在头上的迪迦奥特曼，怪兽见了会害怕哟~',Feature=1,Delete=145600}",
  [145601] = "{id=145601,NameZh='趴趴赛罗[1]',Icon='item_45601',Type=800,Quality=3,MaxNum=99,SellPrice=100,Desc='趴在头上的赛罗奥特曼，戴上之后内心的力量会变得更加强大！',Feature=1,Delete=145601}",
  [145602] = "{id=145602,NameZh='趴趴欧布[1]',Icon='item_45602',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureReward={buffid={61000870}},StorageReward={buffid={80012840}},Desc='趴在头上的欧布奥特曼，对待邪恶的力量，要敢于说出“哦~不！”',Feature=1,Delete=145602}",
  [145603] = "{id=145603,NameZh='趴趴巴尔坦[1]',Icon='item_45603',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9558,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='自从故乡毁灭于核武器后，拥有高度智慧文明的巴尔坦星人就展开了无穷无尽的漂泊之旅……尝试着对他们友好一些吧。',Feature=1,Delete=145603}",
  [145604] = "{id=145604,NameZh='趴趴贝姆斯塔[1]',Icon='item_45604',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9559,AdventureValue=1,StorageReward={buffid={80012860}},Condition=8,Desc='贝姆斯塔是以彗星尘埃为食的小怪兽，戴在头上说不定就能吸收天地精华~',Feature=1,Delete=145604}",
  [145605] = "{id=145605,NameZh='趴趴金古桥[1]',Icon='item_45605',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9560,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='把一个机器人顶在头上……咳，也许能在脑袋里接收卫星电视了。',Feature=1,Delete=145605}",
  [145620] = "{id=145620,NameZh='三兄弟·卡拉蟹[1]',Icon='item_45620',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9564,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='当我还是一个螃蟹仔的时候，一个美丽的僵尸姑娘来到了海滩上，她告诉我，初心者的大脑是这个世界上最美味的食物！！~~',Feature=1,}",
  [145622] = "{id=145622,NameZh='七月扭蛋头饰1（台湾）[1]',Icon='item_45622',Type=800,Quality=2,MaxNum=99,SellPrice=100,Delete=145622}",
  [145623] = "{id=145623,NameZh='七月扭蛋头饰2（台湾）[1]',Icon='item_45623',Type=800,Quality=2,MaxNum=99,SellPrice=100,Delete=145623}",
  [145624] = "{id=145624,NameZh='七月扭蛋头饰3（台湾）[1]',Icon='item_45624',Type=800,Quality=2,MaxNum=99,SellPrice=100,Delete=145624}",
  [145626] = "{id=145626,NameZh='苍穹之角[1]',Icon='item_45626',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9569,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='在天地树高处的某根枝叶上，隐居着神秘的浮空精灵族，穹苍之角则是这一族男性力量的象征。传说中，当持有者的力量越强，角的光芒就会越明亮。“无论身处何处，天地树永在心房。”——浮空精灵歌谣',}",
  [145627] = "{id=145627,NameZh='风栖之冠[1]',Icon='item_45627',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9570,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='浮空精灵族中历代公主所配戴的皇冠，由天地树之巅凝结生长的高空石英制作而成。“无论身居何地，天地树仍是故乡。”——浮空精灵歌谣',}",
  [145628] = "{id=145628,NameZh='鹡鸰头冠[1]',Icon='item_45628',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=727,AdventureValue=230,AdventureReward={buffid={61000820}},StorageReward={buffid={80012920}},Condition=4,ComposeID=14628,Desc='以鸟人哈比翅膀内侧的羽毛所制作出的头冠，据说长期佩戴后，头发会在无风的环境下也能向后飘散。',Feature=1,RefineStorageReward={{buffid={65000260},lv=6},{buffid={66000200},lv=8}},}",
  [145629] = "{id=145629,NameZh='土拨土拨帽[1]',Icon='item_45629',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=725,AdventureValue=150,AdventureReward={buffid={61000830}},StorageReward={buffid={80012640}},Condition=4,ComposeID=14629,Desc='据说土拨鼠之间夸赞同类很厉害，就会发出“土拨土拨”的叫声，所以戴上这顶帽子后，说不定冒险家也会变得厉害起来呢！',}",
  [145630] = "{id=145630,NameZh='炎之小魔帽[1]',Icon='item_45630',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=733,AdventureValue=230,AdventureReward={buffid={61001090}},StorageReward={buffid={80012940}},Condition=4,ComposeID=14630,Desc='最近在女性冒险家中最受欢迎的帽子款式——据说还有部分男性冒险家也为这款帽子沦陷了？',RefineStorageReward={{buffid={65000200},lv=6},{buffid={66000140},lv=8}},}",
  [145631] = "{id=145631,NameZh='高原花发夹[1]',Icon='item_45631',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=728,AdventureValue=150,AdventureReward={buffid={61000830}},StorageReward={buffid={80012910}},Condition=4,ComposeID=14631,Desc='震惊！把这个发夹送给心爱的姑娘，表白成功率高达99%……她不喜欢你的情况属于那1%。',}",
  [145632] = "{id=145632,NameZh='懒懒波利[1]',Icon='item_45632',Type=800,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=735,AdventureValue=300,AdventureReward={buffid={61000750}},StorageReward={buffid={80012960}},Condition=4,ComposeID=14632,Desc='连续三届全大陆最受欢迎的魔物，摸起来的手感甚至比撸猫还要舒服哟！-所有波利心中都有一个疑惑：吃饭睡觉之后…你们为什么总要打我？',RefineStorageReward={{buffid={65000030},lv=6},{buffid={66000090},lv=8}},}",
  [145633] = "{id=145633,NameZh='天兽角[1]',Icon='item_45633',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='据说在神界阿斯加德居住着一种凶猛的天兽，它们每年都要脱落自己的双角，等新的双角生产出来后，会比旧的角更为锋利坚硬。',}",
  [145634] = "{id=145634,NameZh='羽毛发卡[1]',Icon='item_45634',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=770,AdventureValue=80,AdventureReward={buffid={61001100}},StorageReward={buffid={80012970}},Condition=8,ComposeID=14634,}",
  [145635] = "{id=145635,NameZh='天空护卫头盔[1]',Icon='item_45635',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=766,AdventureValue=80,AdventureReward={buffid={61000830}},StorageReward={buffid={80012630}},Condition=8,ComposeID=14635,Desc='只有朱诺最高阶层的护卫官才有机会使用的头盔，它闪耀的金色光芒能让一切罪恶都无所遁形。',}",
  [145637] = "{id=145637,NameZh='天空之城公主帽[1]',Icon='item_45637',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,}",
  [145640] = "{id=145640,NameZh='独角兽盔[1]',Icon='item_45640',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='独角兽是能带来幸运的神兽，用它的角和鬃毛制作的头盔，想必戴上了运气一定会超厉害的吧！',}",
  [145655] = "{id=145655,NameZh='暖心熊妹妹[1]',Icon='item_45655',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=15048,AdventureValue=1,StorageReward={buffid={80012810}},Condition=8,Desc='暖心熊妹妹，是用于儿童玩耍的填充玩具熊。常被用来安慰儿童的难过情绪，拥有熊妹妹将给你带来温馨的幸福感。设计者：渡边执美',Feature=1,}",
  [145673] = "{id=145673,NameZh='姜饼捣蛋鬼[1]',Icon='item_45673',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9594,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='这些小家伙才不在乎你为这个节日准备了许久的漂亮发型，他们只想在你的头上狂欢，跳上一整天的舞！',}",
  [145674] = "{id=145674,NameZh='冻僵的红鼻头[1]',Icon='item_45674',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9593,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='这个小家伙诞生于姜饼城大魔导师卡莱娜的魔法，鼻子是根装了弹簧的胡萝卜。虽然是雪人但是非常怕冷，喜欢窝在人类暖暖的头顶上。“吸溜吸溜~鼻涕流出来了~啊，阿嚏！嗯？我的胡萝卜鼻头弹出来了！？喂喂，快帮我塞回去！！”',}",
  [145690] = "{id=145690,NameZh='黄金触角[1]',Icon='item_45690',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=772,AdventureValue=80,AdventureReward={buffid={61001140}},StorageReward={buffid={80012660}},Condition=8,ComposeID=14690,Desc='以昆虫触角的原理为基础打造的超级环境探测装置，虽然看起来不太严肃，但其实是非常先进的科学产物。',}",
  [145691] = "{id=145691,NameZh='四翼天使',Icon='item_45691',Type=830,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=797,AdventureValue=300,AdventureReward={buffid={61000490}},StorageReward={buffid={80013030}},Condition=4,ComposeID=14691,Desc='施加着四翼天使·拉法叶的魔力的头冠，拥有治愈佩戴者心灵的神奇力量。',Feature=1,}",
  [145692] = "{id=145692,NameZh='安毕斯假面[1]',Icon='item_45692',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9586,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='据说艾勒梅斯曾戴上它捉弄无名，那一次，他尝到了整个米德加尔特最疼的音速投掷。',}",
  [145693] = "{id=145693,NameZh='女巫假面[1]',Icon='item_45693',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9590,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='这款产品在尼夫海姆的假面狂欢节中广受好评，就连真正的巫师与魔女也对它的时髦设计赞不绝口！唯一的缺点就是你需要管束好头上的咬人帽，不然它会把你的派对点心吃得一干二净。',}",
  [145812] = "{id=145812,NameZh='古城头饰[1]',Icon='item_45812',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureReward={buffid={61001110}},StorageReward={buffid={80012640}},}",
  [145815] = "{id=145815,NameZh='樱花城头饰[1]',Icon='item_45815',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureReward={buffid={61000590}},StorageReward={buffid={80012640}},}",
  [145837] = "{id=145837,NameZh='悲伤召唤师头饰[1]',Icon='item_45837',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=744,AdventureValue=210,AdventureReward={buffid={61001120}},StorageReward={buffid={80012920}},Condition=4,ComposeID=14837,Desc='用骷髅作为装饰的魔女尖帽，散发着悲伤的气息，这顶帽子的主人，究竟拥有着怎样的过往呢？',RefineStorageReward={{buffid={65000260},lv=6},{buffid={66000050},lv=8}},}",
