  [145883] = "{id=145883,NameZh='「cama cafe」Beano[1]',Icon='item_45883',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012640}},Desc='圓潤微笑的Beano是咖啡豆精靈的化身，胸前別著象徵專業的領結，手上則端著新鮮現烘的飄香咖啡。',Feature=1,}",
