  [145885] = "{id=145885,NameZh='凯美拉帽[1]',Icon='item_45885',Type=800,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=749,AdventureValue=300,AdventureReward={buffid={61000750}},StorageReward={buffid={80013060}},Condition=4,ComposeID=14885,Desc='知道凯美拉为啥面无表情么？因为它尾巴上的小蛇们帮他分担了所有表情，魔物们私下里都称呼凯美拉为行走的表情之王。',RefineStorageReward={{buffid={65000500},lv=6},{buffid={66000400},lv=8}},}",
  [145886] = "{id=145886,NameZh='绅士礼帽[1]',Icon='item_45886',Type=800,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=904,AdventureValue=300,AdventureReward={buffid={61001170}},StorageReward={buffid={80012590}},Condition=4,ComposeID=14886,Desc='戴上它然后让你的小伙伴们跟在你的身后，友谊的小火车就“逛吃逛吃”的开起来啦，呜呜呜~',RefineStorageReward={{buffid={65000240},lv=6},{buffid={66000030},lv=8}},}",
