  [145888] = "{id=145888,NameZh='传说翼盔[1]',Icon='item_45888',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=51006,AdventureValue=115,StorageReward={buffid={80013090}},Condition=8,Desc='你的传说会留在米德加尔特的历史上，这顶翼盔便是传说级别强者的象征！',Feature=1,}",
  [145890] = "{id=145890,NameZh='史汀指挥家[1]',Icon='item_45890',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9575,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='作为指挥家的史汀先生需要站得再高一点，嗯，你的头顶看起来视野不错！波利号手跟上节奏，溜溜猴乐团不许偷懒！大家都跟上史汀先生的指挥棒一起加入这场音乐狂欢！',}",
  [145891] = "{id=145891,NameZh='兔兔耳机[1]',Icon='item_45891',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9576,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='来自里希塔乐的最新高科技耳机，外形采用了兔兔耳朵的设计，深受年轻女孩们的青睐，让我们戴上它一起咚次哒次胡萝卜！！！“呜~不要在我听歌的时候捏我的耳朵啦~”',}",
  [145892] = "{id=145892,NameZh='波利号手[1]',Icon='item_45892',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9577,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='波利也想来参加热闹的音乐节？随时欢迎！波利号手噗扭噗扭跳上了头顶，吹奏起呼朋唤友的集结号！',}",
