  [145907] = "{id=145907,NameZh='星屑结[1]',Icon='item_45907',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9583,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='你将星屑系于发间，只一个回眸，便令我痴恋千年。',}",
