  [145957] = "{id=145957,NameZh='纯洁的棒球帽[1]',Icon='item_45957',Type=800,MaxNum=99,SellPrice=100,AdventureSort=10123,AdventureValue=1,StorageReward={buffid={80011150}},Condition=8,Desc='象征着“爱与勇气”的棒球帽，与「冷酷的棒球帽」相比较，更多了一份平易近人的亲切感。',TFValidDate='2019-01-15 05:00:00',ValidDate='2019-01-15 05:00:00',}",
  [145969] = "{id=145969,NameZh='魔女汤锅[1]',Icon='item_45969',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9589,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='来自尼夫海姆66号的全自动魔女汤锅！只要丢入魔法素材，一股甜腻的香味就飘了出来，它的主人是多喜欢甜食啊……等等！别往我头上倒魔女汤！烫烫烫~！',}",
  [145971] = "{id=145971,NameZh='幸运投掷[1]',Icon='item_45971',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7056,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='出名的“强运”神器，佩戴之后玩飞行棋能一六到底，跟人划拳永远喝不到罚酒，每天会有一群无聊之人在你身边喊着“吸吸吸吸吸吸吸”……唉~好运是多么的寂寞，真怀念那逢赌必输的金色时光……',LoadShowSize=4,LoadShowPose={0,0.5,0},}",
  [145973] = "{id=145973,NameZh='矿灯帽[1]',Icon='item_45973',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7049,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='孤儿院的杂物间里堆着各种各样被人遗弃的物品，说不定这是哪个可怜孩子的家属留下的。',LoadShowSize=2.5,LoadShowPose={0,0.5,0},}",
  [145974] = "{id=145974,NameZh='怪盗骨盔[1]',Icon='item_45974',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7050,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='著名的怪盗绮罗曾经用过的骨盔，象征着勇气与坚韧，在怪盗绮罗把这个骨盔交给他的女儿苏拉后，苏拉表示：“天呐！这可真是太丑了！”',LoadShowSize=2.5,LoadShowPose={0,0.5,0},}",
  [145976] = "{id=145976,NameZh='草根发夹[1]',Icon='item_45976',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7040,AdventureValue=1,StorageReward={buffid={80012930}},Condition=8,Desc='说是发夹，实际上只是个草根，自从有人看见莱特给他的妹妹戴上了这个发夹以后，草根发夹便在梅尔区风靡了起来。',LoadShowSize=4,LoadShowPose={0,0.5,0},}",
  [145979] = "{id=145979,NameZh='小金盔[1]',Icon='item_45979',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7043,AdventureValue=1,StorageReward={buffid={80012920}},Condition=8,Desc='著名的戏剧艺术家老帕特有一只小乌龟，叫作葵葵，在葵葵不小心淹死后，老帕特找到了有名的金匠打造了这样一只小金盔用来纪念葵葵。',LoadShowSize=3,LoadShowRotate=20,LoadShowPose={0,0.3,0},}",
  [145998] = "{id=145998,NameZh='烛光不倒翁[1]',Icon='item_45998',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9596,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='哟霍霍！今年的孩子们会喜欢什么礼物呢？让我的脑筋转起来~转起来！唔噢噢噢噢！好晕好晕！我老了我老了......',}",
