  [149081] = "{id=149081,NameZh='蛋壳啾啾[1]',Icon='item_49081',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9610,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='“啾啾！啾啾！”它好像把你认作妈妈了......',TFValidDate='2019-03-01 05:00:00',ValidDate='2019-03-01 05:00:00',}",
  [149082] = "{id=149082,NameZh='森林之冠[1]',Icon='item_49082',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9613,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='被天地树选中之人，通过雨檀族考验之人，浮空精灵认可之人。戴上此冠，成为天地树的守护者吧。',TFValidDate='2019-03-01 05:00:00',ValidDate='2019-03-01 05:00:00',}",
  [149090] = "{id=149090,NameZh='慧光之钥[1]',Icon='item_49090',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=52028,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='巨人密米尔在设计奥术魔方时，专门为其打造的封锁神钥。它凝聚了九界中最高级的智慧，只有命定之人才能持有。',}",
  [149091] = "{id=149091,NameZh='梦中的皮里恩[1]',Icon='item_49091',Type=800,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=925,AdventureValue=300,AdventureReward={buffid={61000490}},StorageReward={buffid={80013020}},Condition=4,ComposeID=18091,Desc='据说皮里恩睡觉时会留一只眼睛盯梢，只有在初生时才会在母亲的怀里闭上全部六只眼睛，戴上它闭上眼，你感受到了那份如棉花糖般温柔的梦乡了吗？',}",
  [149102] = "{id=149102,NameZh='噬魂之誓言[1]',Icon='item_49102',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52020,AdventureValue=1,StorageReward={buffid={80012930}},Condition=8,Desc='由神之金属制成的头盔，曾伴随着它的主人走向生命的最后一刻。百年后的星光下，它诉说着的，是未曾逝去的勇气和信仰。',}",
  [149103] = "{id=149103,NameZh='上将军帽[1]',Icon='item_49103',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52030,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='星星在苍窜闪耀，雄鹰翱翔蓝天，树木枝叶茂盛，树干连着大地，我将这最高的荣誉授予你，我们的英雄，愿你永远铭记肩负的责任，保护弱小，守卫自己的国家！汪！',}",
  [149105] = "{id=149105,NameZh='天秤之冠[1]',Icon='item_49105',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10165,AdventureValue=1,AdventureReward={buffid={64000360}},StorageReward={buffid={80012810}},Condition=8,Desc='让佩戴者能够保持公正的神奇头饰',Feature=1,TFValidDate='2022-09-01 05:00:00',ValidDate='2022-09-01 05:00:00',}",
  [149106] = "{id=149106,NameZh='室女祝福[1]',Icon='item_49106',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10166,AdventureValue=1,AdventureReward={buffid={63000090}},StorageReward={buffid={80012870}},Condition=8,Desc='圣洁的祝福伴随其中，据说有劝人向善的功效',Feature=1,}",
  [149121] = "{id=149121,NameZh='雪翎玫瑰[1]',Icon='item_49121',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10183,AdventureValue=1,StorageReward={buffid={80012990}},Condition=8,Desc='象征和平与希望的桂冠上结出了爱的花朵，愿你也一样。',}",
  [149135] = "{id=149135,NameZh='蕾丝蛋糕[1]',Icon='item_49135',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=829,AdventureValue=90,AdventureReward={buffid={61000510}},StorageReward={buffid={80012630}},Condition=4,ComposeID=18135,Desc='罗扎纳最受欢迎的甜品之一，经常卖断货。是烤箱酒吧伊蕾塔小姐的拿手甜点。',}",
  [149136] = "{id=149136,NameZh='帅气的巡逻帽[1]',Icon='item_49136',Type=800,MaxNum=99,SellPrice=100,AdventureSort=834,AdventureValue=40,AdventureReward={buffid={61001310}},StorageReward={buffid={80013070}},Condition=4,ComposeID=18136,Desc='蝴蝶巡守队队员的帽子，戴上以后英俊值上升二十个百分点。',}",
  [149137] = "{id=149137,NameZh='灵巧的羽毛帽[1]',Icon='item_49137',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=830,AdventureValue=90,AdventureReward={buffid={61000510}},StorageReward={buffid={80012840}},Condition=4,ComposeID=18137,Desc='蝴蝶巡守队传令兵的帽子，佩戴后跑步时脚下生风。',}",
  [149138] = "{id=149138,NameZh='冒险家的荣光[1]',Icon='item_49138',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=836,AdventureValue=100,AdventureReward={buffid={61000560}},StorageReward={buffid={80012600}},Condition=4,ComposeID=18138,Desc='大冒险家多拉贡的帽子。继承这顶帽子的人，也会继承他的勇气、信念……和小肚子。',}",
  [149139] = "{id=149139,NameZh='飞跃彩虹[1]',Icon='item_49139',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7000,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='小猫咪艾比花了很大功夫制作的手工彩虹，据说是他给森林小女巫的告白礼物。后者收到后，用魔法把它挂到了天上。',}",
  [149141] = "{id=149141,NameZh='诅咒戾痕[1]',Icon='item_49141',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=52032,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='时间流逝，魔剑的诅咒蔓延了整座高塔，从中诞生了死亡的虚影。“绝望吧！怨恨吧！一旦踏入此处，你的灵魂便会逐渐腐朽……”',Feature=1,}",
  [149142] = "{id=149142,NameZh='飞龙的情歌[1]',Icon='item_49142',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=934,AdventureValue=120,AdventureReward={buffid={61000470}},StorageReward={buffid={80012660}},Condition=4,ComposeID=18142,Desc='七彩飞龙大王罗密欧的耳机，24小时不间断播放着浪漫爱情歌曲。',}",
  [149143] = "{id=149143,NameZh='七彩魔女帽[1]',Icon='item_49143',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=935,AdventureValue=130,AdventureReward={buffid={61000500}},StorageReward={buffid={80012660}},Condition=4,ComposeID=18143,Desc='七彩地龙公主茱莉叶的头饰，参考了森林小女巫的造型设计而成。',}",
  [149144] = "{id=149144,NameZh='寂寞的龙蛋[1]',Icon='item_49144',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=936,AdventureValue=130,AdventureReward={buffid={61001160}},StorageReward={buffid={80012660}},Condition=4,ComposeID=18144,Desc='一颗龙蛋，原本住在里面的小龙闻到甜品的香气飞走了，这让它变得非常寂寞。',}",
  [149145] = "{id=149145,NameZh='趴趴小海獭[1]',Icon='item_49145',Type=800,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=937,AdventureValue=40,AdventureReward={buffid={61000870}},StorageReward={buffid={80012680}},Condition=4,ComposeID=18145,Desc='“哔叽~哔叽~我是不是多拉贡岛上最可爱的小动物？”',}",
  [149146] = "{id=149146,NameZh='椰果沙滩[1]',Icon='item_49146',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=939,AdventureValue=100,AdventureReward={buffid={61000590}},StorageReward={buffid={80012640}},Condition=4,ComposeID=18146,Desc='在附近藏着的鲨鱼大哥总在思考，什么时候能吃到掉下来的椰果。',}",
  [149147] = "{id=149147,NameZh='微笑蛋黄帽[1]',Icon='item_49147',Type=800,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=928,AdventureValue=30,AdventureReward={buffid={61000510}},StorageReward={buffid={80012840}},Condition=4,ComposeID=18147,Desc='以蛋黄波利为造型的棒球帽。除了绝佳的遮阳效果外，还散发着蛋糕的香味，只要闻到就会露出笑容。',}",
  [149148] = "{id=149148,NameZh='羽状叶发带[1]',Icon='item_49148',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=930,AdventureValue=80,AdventureReward={buffid={61000460}},StorageReward={buffid={80012640}},Condition=4,ComposeID=18148,Desc='富有森林气息的发带，由希希娅小姐的专用裁缝使用了9999根群叶疯兔绒毛制成。',}",
  [149149] = "{id=149149,NameZh='石头波利帽[1]',Icon='item_49149',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=946,AdventureValue=150,AdventureReward={buffid={61000590}},StorageReward={buffid={80012640}},Condition=4,ComposeID=18149,Desc='波利！波利！不要因为我是石头就嫌弃我，我会乖乖的呆在你的头顶的，只对你展现我最柔软的一面！',}",
  [149150] = "{id=149150,NameZh='恶魔牙冠[1]',Icon='item_49150',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=947,AdventureValue=150,AdventureReward={buffid={61001110}},StorageReward={buffid={80012640}},Condition=4,ComposeID=18150,Desc='“嗷呜，这是本恶魔大人赐予你的东西，乖乖的收好，如果有人敢欺负你，就用我的尖牙吓他们！”',}",
  [149151] = "{id=149151,NameZh='妖之角[1]',Icon='item_49151',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=948,AdventureValue=210,AdventureReward={buffid={61000470}},StorageReward={buffid={80012670}},Condition=4,ComposeID=18151,Desc='妖精一族的力量源泉就在双角之中，强大而尖锐，充满着无尽的魔力，同时角也是所有妖精的禁区，任何生物都不得触碰。',}",
  [149152] = "{id=149152,NameZh='趴趴雪球[1]',Icon='item_49152',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=949,AdventureValue=210,AdventureReward={buffid={61000470}},StorageReward={buffid={80013000}},Condition=4,ComposeID=18152,Desc='米德加尔特大陆的特大新闻，“雪兽一族最萌的雪兽宝宝——球球，竟然离家出走，雪兽一族已经陷入了巨大的恐慌之中” “嗷呜~嗷呜~”哎？这是什么声音？球球怎么在你头上!!!',}",
  [149153] = "{id=149153,NameZh='冰波利帽[1]',Icon='item_49153',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=950,AdventureValue=150,AdventureReward={buffid={61000560}},StorageReward={buffid={80012630}},Condition=4,ComposeID=18153,Desc='“波利！波利！不要因为我的外表就嫌弃我，虽然我看起来冷冰冰的，但是我的内心却是一片火热的爱着主人呢！请快把我戴上！主人！”',}",
  [149154] = "{id=149154,NameZh='傀儡幽灵冠[1]',Icon='item_49154',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=954,AdventureValue=210,AdventureReward={buffid={61000500}},StorageReward={buffid={80012920}},Condition=4,ComposeID=18154,Desc='“既然神不能在我痛苦的时候帮助我逃离深渊，那么我便背离神灵，堕落入深渊，沉睡于暗处的幽灵啊，请听从我的差遣，将那些人变为我的傀儡吧！”',}",
  [149155] = "{id=149155,NameZh='希尔金冠[1]',Icon='item_49155',Type=800,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=956,AdventureValue=300,AdventureReward={buffid={61001690}},StorageReward={buffid={80013030}},Condition=4,ComposeID=18155,Desc='这是希尔一族最高的荣耀，能佩戴它的只有族内最强大的战士，当希尔队长离开族内后，这只金冠就下落不明，不知什么原因才重现于世。',}",
  [149157] = "{id=149157,NameZh='腐朽沉眠[1]',Icon='item_49157',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=52039,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='“他随着月光而去，溺于寂静的高塔。伴着星辰的哀叹，陷入最后的沉眠。”',}",
  [149158] = "{id=149158,NameZh='凛冬守望[1]',Icon='item_49158',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52037,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='“永恒之雪，赐予我无尽的勇气，与面对死亡的力量。”——雪原战士瓦西里的冠冕。许多年前，他曾跋涉至冰川的深处，独自一人平息了肆虐的风暴。',}",
  [149160] = "{id=149160,NameZh='嗷呜绒帽[1]',Icon='item_49160',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=831,AdventureValue=110,AdventureReward={buffid={61000470}},StorageReward={buffid={80013070}},Condition=4,ComposeID=18160,Desc='由疯兔绒毛织成，可爱又非常保暖的喵喵帽。据说是参考了多兰族先祖的模样设计的。',}",
  [149161] = "{id=149161,NameZh='羁绊之盔[1]',Icon='item_49161',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52042,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='“看在你这么可爱的份上就让你上来吧。给你戴上小头盔，一定要抓稳我哦，如果你受伤了，我可是会心疼……心疼我的头盔的！”',}",
  [149163] = "{id=149163,NameZh='深渊骨角·寂[1]',Icon='item_49163',Type=800,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={80012970}},Desc='以被深渊侵蚀的魔物遗骸打磨而成的角饰，残留的深渊之力能够让佩戴者与魔剑更加契合。',}",
  [149164] = "{id=149164,NameZh='辉光守护·耀[1]',Icon='item_49164',Type=800,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={80012970}},Desc='沐浴过女武神荣耀之力的头盔，普通人无法佩戴，唯有能踏入瓦尔哈拉殿堂之人，方可承此殊荣。',}",
  [149165] = "{id=149165,NameZh='原初咏唱·虚[1]',Icon='item_49165',Type=800,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={80012980}},Desc='遗落在本源走廊的奇特头饰，能够帮助佩戴者掌握元素融合的奥秘。但，只有心智坚定之人，才能驾驭这份力量。',}",
  [149166] = "{id=149166,NameZh='遥望时空·归[1]',Icon='item_49166',Type=800,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={80012980}},Desc='跨越时间的阻隔，凝视未来的一切可能。',}",
  [149167] = "{id=149167,NameZh='幽邃之视·暗[1]',Icon='item_49167',Type=800,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={80012970}},Desc='寄宿着死亡女神海拉祝福之力的发饰，似乎可以对充满恶意的灵魂造成影响。',}",
  [149168] = "{id=149168,NameZh='流影之歌·隐[1]',Icon='item_49168',Type=800,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={80012970}},Desc='由暗影界与现实的交汇处获得的神秘矿石锻造而成，能够散发出有如星辉般的光芒。',}",
  [149169] = "{id=149169,NameZh='追逐星辰·溯[1]',Icon='item_49169',Type=800,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={80012970}},Desc='星星守护纯洁的灵魂，星星照耀无垢的旅程。',}",
  [149170] = "{id=149170,NameZh='日轮冠冕[1]',Icon='item_49170',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=846,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='歌颂太阳吧，祈愿白昼和新的希望。',}",
  [149171] = "{id=149171,NameZh='月光咏叹[1]',Icon='item_49171',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=847,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='沐浴月光吧，赞美夜晚与每一个梦。',}",
  [149172] = "{id=149172,NameZh='神赐恩典·昼[1]',Icon='item_49172',Type=800,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={80012980}},Desc='由诸神赐下的冠冕，拥有治愈万物的力量。怀抱救赎之心者，神明将与其永在。',}",
  [149173] = "{id=149173,NameZh='传承之冠·辉[1]',Icon='item_49173',Type=800,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={80012970}},Desc='宝珠内流淌着与主人内心同等坚韧的辉光，龙族传承的血脉将照亮一切阴霾。',}",
  [149174] = "{id=149174,NameZh='光子护目镜·风[1]',Icon='item_49174',Type=800,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={80012970}},Desc='运用光子技术制造而成的战术护目镜，能帮助佩戴者更为精准的发现敌人的弱点。',}",
  [149175] = "{id=149175,NameZh='探究者发带·逐[1]',Icon='item_49175',Type=800,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={80012970}},Desc='结合部分伊米尔之石的力量制作出的发饰，能让使用者在尚未掌握恢复技术的情况下远离生命体结合带来的风险。',}",
  [149176] = "{id=149176,NameZh='羽之桂冠·梦[1]',Icon='item_49176',Type=800,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={80012970}},Desc='形似羽翼的黄金桂冠，蕴藏着温暖人心的力量。只要心存善念，就能听见天使温柔的教诲。',}",
  [149177] = "{id=149177,NameZh='友谊之绊·灵[1]',Icon='item_49177',Type=800,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={80012970}},Desc='获得叛逆的召唤灵真心认可后被赠予的帽子，是友谊与契约牢不可破的象征。',}",
  [149179] = "{id=149179,NameZh='初心睡帽[1]',Icon='item_49179',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10184,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='冒险征途劳累，沧桑辛苦疲惫，只有梦里一霎，仍是如花少年。',}",
  [149180] = "{id=149180,NameZh='妖灵独角[1]',Icon='item_49180',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=10185,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='充满自然力量的独角，戴上之后将变成介于妖精和仙灵之间的奇妙生物。',}",
  [149181] = "{id=149181,NameZh='疯表匠礼帽[1]',Icon='item_49181',Type=800,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=959,AdventureValue=330,AdventureReward={buffid={61001170}},StorageReward={buffid={80013060}},Condition=8,ComposeID=18181,Desc='一动不动的秒针，疯狂旋转的分针，以及倒着走的时针！什么人做出了这样的钟表？',}",
  [149182] = "{id=149182,NameZh='鱼潜灵灯[1]',Icon='item_49183',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=960,AdventureValue=210,AdventureReward={buffid={61001130}},StorageReward={buffid={80012920}},Condition=4,ComposeID=18182,Desc='挚友的祝福化为一盏温暖的灯火，黑暗的前路变得通明，一切未来美好的可能都在眼前展开。',Feature=1,}",
  [149183] = "{id=149183,NameZh='深海灵触[1]',Icon='item_49182',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=963,AdventureValue=150,AdventureReward={buffid={61001110}},StorageReward={buffid={80012640}},Condition=4,ComposeID=18183,Desc='夜晚躺在水中做了一个梦，在梦里将窥探深海的秘密，群鱼涌来，古老的海底宫殿显露真容。',Feature=1,}",
  [149184] = "{id=149184,NameZh='狐仙之聆[1]',Icon='item_49184',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=966,AdventureValue=210,AdventureReward={buffid={61001160}},StorageReward={buffid={80012930}},Condition=4,ComposeID=18184,Desc='一切声响都无法逃脱狐仙之耳，包括那些梦中呢喃的思念。',Feature=1,}",
  [149185] = "{id=149185,NameZh='熊猫轻语[1]',Icon='item_49185',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=962,AdventureValue=150,AdventureReward={buffid={61000870}},StorageReward={buffid={80012640}},Condition=4,ComposeID=18185,Desc='快跟我一起说：‘熊猫是最可爱的动物’！说完了我就在你头上多呆一会儿~',Feature=1,}",
  [149189] = "{id=149189,NameZh='夕叶情思[1]',Icon='item_49189',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7081,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='设计巧妙、做工精致，金色的叶片散发着迷人的光芒，戴上它的人会有一种温婉可人的气质。',}",
  [149190] = "{id=149190,NameZh='拂晓温情[1]',Icon='item_49190',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7082,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='散发着宛如日出前的天空般温柔的光泽，戴着它的人会在凛然的气质中兼备一丝柔情。',}",
  [149191] = "{id=149191,NameZh='古恩瞳[1]',Icon='item_49191',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7101,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='如翡如翠，清澈若许。仿自古恩之眼，取其可洞穿万千世事之意。',}",
  [149192] = "{id=149192,NameZh='法纳角[1]',Icon='item_49192',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7102,AdventureValue=1,StorageReward={buffid={80012990}},Condition=8,Desc='模仿法纳族的角型饰品。干净剔透，虽然是角型但毫无戾气，充满了可爱的萌感。',}",
  [149193] = "{id=149193,NameZh='小法纳角[1]',Icon='item_49193',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7103,AdventureValue=1,StorageReward={buffid={80012600}},Condition=8,Desc='模仿法纳族的角型饰品。干净剔透，虽然是角型但毫无戾气，充满了可爱的萌感。迷你版。',}",
  [149195] = "{id=149195,NameZh='青梅鬟[1]',Icon='item_49195',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7104,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='洛阳女儿最爱的发式，圆润小巧，稚气中透出俏皮。梳着青梅鬟的姑娘都期待着，终会等到一个骑着竹马来的少年。',}",
