  [149241] = "{id=149241,NameZh='羽之桂冠·爱[1]',Icon='item_49241',Type=800,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={80012970}},Desc='形似羽翼的黄金桂冠，蕴藏着温暖人心的力量。只要心存善念，就能听见天使温柔的教诲。',}",
  [149242] = "{id=149242,NameZh='羽之桂冠',Icon='item_49176',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=852,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='形似羽翼的黄金桂冠，蕴藏着温暖人心的力量。只要心存善念，就能听见天使温柔的教诲。',}",
  [149243] = "{id=149243,NameZh='原初咏唱·空[1]',Icon='item_49243',Type=800,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={80012980}},Desc='遗落在本源走廊的奇特头饰，能够帮助佩戴者掌握元素融合的奥秘。但，只有心智坚定之人，才能驾驭这份力量。',}",
  [149244] = "{id=149244,NameZh='原初咏唱',Icon='item_49165',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=841,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='遗落在本源走廊的奇特头饰，能够帮助佩戴者掌握元素融合的奥秘。但，只有心智坚定之人，才能驾驭这份力量。',}",
