  [149246] = "{id=149246,NameZh='遥望时空',Icon='item_49166',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=842,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='跨越时间的阻隔，凝视未来的一切可能。',}",
  [149247] = "{id=149247,NameZh='月光咏叹',Icon='item_49171',Type=800,Quality=4,MaxNum=99,SellPrice=100,}",
  [149248] = "{id=149248,NameZh='日轮冠冕',Icon='item_49170',Type=800,Quality=4,MaxNum=99,SellPrice=100,}",
  [149249] = "{id=149249,NameZh='追逐星辰·流[1]',Icon='item_49249',Type=800,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={80012970}},Desc='星星守护纯洁的灵魂，星星照耀无垢的旅程。',}",
  [149250] = "{id=149250,NameZh='追逐星辰',Icon='item_49169',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=845,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='星星守护纯洁的灵魂，星星照耀无垢的旅程。',}",
  [149251] = "{id=149251,NameZh='白蛇·凝灵[1]',Icon='item_49251',Type=800,MaxNum=99,SellPrice=100,Desc='远古的那场大战，以及之后洛阳的时空被割离，导致荒境的元素之力开始衰变。经年累月，这种衰变愈演愈烈，虽然荒境表面上还风平浪静，其实元素失调导致的混乱已经濒临极限，唯一勉强保持正常的水之元素也岌岌可危，荒境已经处于毁灭的边缘。一切的转机源自那场突然的暴雨，黑暗中唯一的烛火——水之元素。浸润万物的雨降下，元素的变异被洗刷，混乱被平息，水元素的精魄也因大雨耗尽了力量，消失无踪。而新的生命自雨中降生，白蛇·凝灵，带着水元素仅存的气息，来到了世上。',}",
  [149260] = "{id=149260,NameZh='灾厄炎龙系列头饰',Icon='item_49211',Type=800,MaxNum=99,SellPrice=100,AdventureSort=10232,AdventureValue=1,StorageReward={buffid={82000070}},Condition=8,}",
  [149511] = "{id=149511,NameZh='阿努比斯之角[1]',Icon='item_49511',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52047,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='模仿胡狼的耳朵，据说戴上后可得到冥界的保佑。但女神海拉似乎不认同这种说法。',}",
  [149512] = "{id=149512,NameZh='教宗冠冕[1]',Icon='item_49512',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10278,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='充满威严的礼冠，代表着无上光荣。当承载着高尚理想的它被戴在头顶之后，就千万不可再向任何人低头——因为会掉下来。',TFValidDate='2020-09-05 05:00:00',ValidDate='2020-10-17 05:00:00',}",
  [149516] = "{id=149516,NameZh='祸崇·大天狗[1]',Icon='item_49516',Type=800,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={80012970}},Desc='“我愿以生命偿还我的罪孽，却不被理解，只得以此身堕入恶道。待我归来时，曾经由我创造、我所守护的一切，将由我亲手毁灭……”',}",
  [149517] = "{id=149517,NameZh='惑心·玉藻前[1]',Icon='item_49517',Type=800,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={80012970}},Desc='“你说爱我时，我信了。如今你说我是恶魔，我也信——便以此身化作杀生石，用你的国，你的民，做我成魔的祭品……”',}",
  [149518] = "{id=149518,NameZh='八岐/天照系列头饰',Icon='item_49518',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=856,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='愿你的信仰如同御神樱的樱花，永不凋零。',}",
  [149519] = "{id=149519,NameZh='尖尖碰碰头[1]',Icon='item_49519',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52049,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='不好意思，请问有人想摸摸我的头么？',}",
  [149527] = "{id=149527,NameZh='虫语者[1]',Icon='item_49527',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=980,AdventureValue=150,AdventureReward={buffid={61000560}},StorageReward={buffid={80012640}},Condition=4,ComposeID=18527,Desc='模仿昆虫触角制作成的魔法装置，戴上它就能与昆虫交流了。',}",
  [149528] = "{id=149528,NameZh='日光兽角[1]',Icon='item_49528',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=981,AdventureValue=210,AdventureReward={buffid={61001130}},StorageReward={buffid={80012920}},Condition=4,ComposeID=18528,Desc='以三角兽兽角为原型制作的护额，用日光石打磨而成，并非动物制品哦！',}",
  [149529] = "{id=149529,NameZh='月光兽角[1]',Icon='item_49529',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=982,AdventureValue=210,AdventureReward={buffid={61001120}},StorageReward={buffid={80012930}},Condition=4,ComposeID=18529,Desc='以月光三角兽兽角为原型制作的护额，用月光石打磨而成，并非动物制品哦！',}",
  [149530] = "{id=149530,NameZh='灼金羽冠[1]',Icon='item_49530',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=983,AdventureValue=210,AdventureReward={buffid={61001120}},StorageReward={buffid={80012660}},Condition=4,ComposeID=18530,Desc='使用金灿灿的羽毛制成的羽冠，野性与时尚的完美结合。',}",
  [149531] = "{id=149531,NameZh='莉姆露的魂龛[1]',Icon='item_49531',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=984,AdventureValue=210,AdventureReward={buffid={61000470}},StorageReward={buffid={80012620}},Condition=4,ComposeID=18531,Desc='被芙蕾雅杀死后，莉姆露的灵魂因诅咒封印在了这顶王冠中，永远无法离开。即使受尽折磨，莉姆露依旧没有向芙蕾雅屈服。',LoadShowSize=3,LoadShowPose={0,0.25,0},}",
  [149532] = "{id=149532,NameZh='啃啃魔妖帽[1]',Icon='item_49532',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=988,AdventureValue=150,AdventureReward={buffid={61000590}},StorageReward={buffid={80012610}},Condition=4,ComposeID=18532,Desc='以玩偶魔妖为造型的帽子，深受搞笑艺人们的喜爱。据说带上这顶帽子能变得像玩偶魔妖一样“聪明”。',}",
  [149539] = "{id=149539,NameZh='炎灵之眼[1]',Icon='item_49539',Type=800,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=992,AdventureValue=300,AdventureReward={buffid={61000730}},StorageReward={buffid={80013050}},Condition=4,ComposeID=18539,}",
  [149541] = "{id=149541,NameZh='星辉圣杯[1]',Icon='item_49541',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=10306,AdventureValue=1,StorageReward={buffid={80012860}},Condition=8,Desc='承载着亿万颗流星光芒的圣杯，拥有着令人愿望成真的魔力，但只有灵魂圣洁无暇者的许愿，才能得到它的回应。',LoadShowSize=3,LoadShowPose={0,-0.5,0},}",
  [149543] = "{id=149543,NameZh='犬阵笠[1]',Icon='item_49543',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52052,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='等一下！露出头的话根本保护不到头吧?再等一下！为什么连头也变了啊！',}",
  [149545] = "{id=149545,NameZh='啤酒推销员[1]',Icon='item_49545',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=994,AdventureValue=210,AdventureReward={buffid={61001130}},StorageReward={buffid={80012920}},Condition=4,ComposeID=18545,Desc='在这炎热的夏天，要来一杯清凉可口的啤酒吗？企鹅工坊出品的啤酒，你值得拥有！',Feature=1,}",
  [149546] = "{id=149546,NameZh='时尚前沿[1]',Icon='item_49546',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=997,AdventureValue=150,AdventureReward={buffid={61001110}},StorageReward={buffid={80012640}},Condition=4,ComposeID=18546,Desc='美男团首席发型师托尼老师的全新力作，只要剪了这个发型，你就能成为引领潮流的时尚圈先锋！',Feature=1,}",
  [149547] = "{id=149547,NameZh='鳄鱼头套[1]',Icon='item_49547',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=1000,AdventureValue=210,AdventureReward={buffid={61001120}},StorageReward={buffid={80012660}},Condition=4,ComposeID=18547,Desc='原本想做成巨龙造型的头套，由于设计图的不严谨制成了鳄鱼造型，没想到意外的受到大家的喜爱。\n“救命救命，我被鳄鱼吞掉了！”',Feature=1,}",
  [149548] = "{id=149548,NameZh='转转石假面[1]',Icon='item_49548',Type=800,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=1004,AdventureValue=300,AdventureReward={buffid={61000750}},StorageReward={buffid={80013060}},Condition=4,ComposeID=18548,Desc='克魔岛特色工艺品，可以转动的石雕四面雕刻着象征各种厄运的假面，只要转动石雕，就能转走厄运，带来好运气！喂，等等！你怎么把它戴在头上了！',Feature=1,}",
  [149553] = "{id=149553,NameZh='提灯男爵[1]',Icon='item_49553',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52055,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='提灯男爵对于尼夫海姆最大的贡献在于，他发明了鬼火照明技术。',}",
  [149555] = "{id=149555,NameZh='回转马戏城[1]',Icon='item_49555',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=10379,AdventureValue=1,StorageReward={buffid={80012860}},Condition=8,Desc='华丽耀眼的中世纪帐篷设计，周围的球形旋转木马会随着热闹的经典乐曲旋转并上下摆动，脑海中的梦幻童话世界在这一刻成为了现实。',Feature=1,}",
  [149556] = "{id=149556,NameZh='雷火子弹[1]',Icon='item_49556',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=857,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='代表了反叛者组织最高荣誉，只有暴君才能拥有的帽子。',}",
  [149560] = "{id=149560,NameZh='好运魔菇[1]',Icon='item_49560',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52058,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='作为一只蘑菇，存在了数百年还没有被人采摘，因此成为了好运的象征。',}",
  [149568] = "{id=149568,NameZh='龙骑士之盔[1]',Icon='item_49568',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52066,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='地龙骑士最珍爱的头盔，是你们之间羁绊的证明。',}",
  [149569] = "{id=149569,NameZh='闪蝶发夹[1]',Icon='item_49569',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=1011,AdventureValue=210,AdventureReward={buffid={61001090}},StorageReward={buffid={80012660}},Condition=4,ComposeID=18569,Desc='标本化的蝴蝶，最大限度地保留了它生前的魔魅与闪耀。不过为了消除具有致幻效果的鳞粉，炼金术师们可没少费工夫。',}",
  [149570] = "{id=149570,NameZh='精灵狐耳[1]',Icon='item_49570',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=1008,AdventureValue=150,AdventureReward={buffid={61000870}},StorageReward={buffid={80012640}},Condition=4,ComposeID=18570,Desc='王室狩猎场的周边，一经推出便受到王都少女们的哄抢。然而，每出售一个狐耳发饰，就有一只精灵狐惨遭杀害。',}",
  [149571] = "{id=149571,NameZh='趴趴游魂[1]',Icon='item_49571',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=1013,AdventureValue=210,AdventureReward={buffid={61001120}},StorageReward={buffid={80012930}},Condition=4,ComposeID=18571,Desc='尾随冒险者离开心灵猎场的游魂，似乎是在对方身上找到了家乡的味道。既然它没有害人的心思，就暂且带着它吧。或许在将来，当你踏上某一片土地时，他会获得解脱。',}",
  [149592] = "{id=149592,NameZh='暖心芽芽帽[1]',Icon='item_49592',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52070,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='用厚实毛线织成的帽子，顶端带有两片仿制的芽芽叶子。冬日的寒风固然凛冽，但芽芽会陪着你，一起守望春天~',}",
  [149594] = "{id=149594,NameZh='海的圆舞曲[1]',Icon='item_49594',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52075,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='送你一截海浪，无需暴风，不伴大雨；只有纯粹的快乐旋转跳跃，冲破海平面，来到你的面前。',LoadShowSize=3,LoadShowPose={0,-0.25,0},}",
  [149612] = "{id=149612,NameZh='星海守望[1]',Icon='item_49612',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52079,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='星之精灵漂浮在浩瀚的宇宙中，点亮微光，为畅游星海的旅人指引方向。',}",
  [149620] = "{id=149620,NameZh='波比帽[1]',Icon='item_49620',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52082,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='和水晶波比同款的滑雪帽，拥有漂亮的水晶角，但要小心被猎人当成水晶波比哟。',}",
  [149626] = "{id=149626,NameZh='金边墨镜[1]',Icon='item_49626',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52087,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='纯金打造的太阳镜，不但可以防晒，还能当装饰，让人一目了然知道你的身份地位。',}",
  [149627] = "{id=149627,NameZh='神使之证[1]',Icon='item_49627',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=1017,AdventureValue=300,AdventureReward={buffid={61001180}},StorageReward={buffid={80013050}},Condition=4,ComposeID=18627,Desc='为女神献上忠诚与勇敢。',}",
  [149632] = "{id=149632,NameZh='趴趴火焰龟[1]',Icon='item_49632',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=1023,AdventureValue=150,AdventureReward={buffid={61000870}},StorageReward={buffid={80012640}},Condition=4,ComposeID=18632,Desc='小乌龟也想去冒险',}",
  [149648] = "{id=149648,NameZh='魔女誓约[1]',Icon='item_49648',Type=800,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=1019,AdventureValue=300,AdventureReward={buffid={61001170}},StorageReward={buffid={80012590}},Condition=4,ComposeID=18648,Desc='戴上它，与魔女签订誓约，无惧世俗，从此生命只为自己绽放，深夜的月空成了游乐场，谁又能定义你的正义与邪恶？',}",
  [149650] = "{id=149650,NameZh='深海诱光[1]',Icon='item_49650',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=52091,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='一闪一闪的亮光出现在深海，乖巧的灯笼鱼说要为你照亮前路，可你把它戴到脑袋上时，它会露出狰狞利齿。',}",
