  [162521] = "{id=162521,NameZh='圣徒拳套[2]',Icon='item_62521',Type=290,Quality=3,MaxNum=99,SellPrice=100,Desc='作为圣歌教会中强大的暴力机构，“光明圣徒”安德鲁受到大主教的命令为武僧订做一对拳套。特制的拳套材料甚至能够加速气的流动，这对拳套制作出来之后就迅速装备了教会中的所有武僧。受到光明圣徒的祝福，安全精炼时消耗的装备件数减少一半。',Feature=1,}",
  [162527] = "{id=162527,NameZh='狂战拳套[2]',Icon='item_62502',Type=290,MaxNum=99,SellPrice=1140,Desc='特有的蓝白花纹说明了它的来历，著名武器家族诺格罗德的代表作品，曾荣获王国年度武器设计最佳。',Level=95,}",
