  [163447] = "{id=163447,NameZh='死亡笔记[2]',Icon='item_63447',Type=240,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='死神所使用的名簿。死神所掉落的名簿有时候就这样在现世上流传。写的密密麻麻的人的姓名,好像看到有些熟悉的名字似的。',LoadShowSize=3,LoadShowRotate=15,LoadShowPose={0,0.3,0},}",
  [163448] = "{id=163448,NameZh='湛蓝天光·书[2]',Icon='item_63448',Type=240,MaxNum=99,SellPrice=2800,Desc='阔大的云海之上透出湛蓝天光，晴空下的战士们振作起了精神。守护好这本圣书吧，它印证着你的忠诚，勇敢与希望。',Level=110,}",
