  [163486] = "{id=163486,NameZh='星宫图[2]',Icon='item_63488',Type=240,Quality=3,MaxNum=99,SellPrice=100,Desc='记录着星座图案与传说的魔法书，凭借它或许能够借用星空的力量。',LoadShowSize=2,LoadShowPose={0,0.4,0},Delete=163486}",
  [163487] = "{id=163487,NameZh='诸天星图[2]',Icon='item_63489',Type=240,Quality=4,MaxNum=99,SellPrice=100,Desc='绘制着宇宙中群星轨迹的古老星图，许多记录超越了凡人的认知，亦无人知晓它的作者是谁。',LoadShowSize=2,LoadShowPose={0,0.4,0},Delete=163487}",
  [163488] = "{id=163488,NameZh='天衍录[2]',Icon='item_63486',Type=240,Quality=3,MaxNum=99,SellPrice=100,Desc='记载着宇宙运行之道的魔法书，或许无人能够参悟其中的奥秘。',LoadShowSize=2,LoadShowPose={0,0.4,0},Delete=163488}",
  [163489] = "{id=163489,NameZh='万象天书[2]',Icon='item_63487',Type=240,Quality=4,MaxNum=99,SellPrice=100,Desc='在没有获得认可的人眼中，书上的内容如同鬼画符一般。但对于那些被选中的人来说，书中所记载的是凌驾于世间万物的至理。',LoadShowSize=2,LoadShowPose={0,0.4,0},Delete=163489}",
