  [163491] = "{id=163491,NameZh='狱火魔典[2]',Icon='item_40598',Type=240,Quality=3,MaxNum=99,SellPrice=100,Desc='从深海中走出的毁灭者，要让这世界被地狱吞噬。',Delete=163491}",
  [163492] = "{id=163492,NameZh='血鳞魔典[2]',Icon='item_40599',Type=240,Quality=4,MaxNum=99,SellPrice=100,Desc='从深海中走出的毁灭者，要让这世界被地狱吞噬。',Delete=163492}",
  [163607] = "{id=163607,NameZh='圣徒手枪[2]',Icon='item_63606',Type=310,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='由“光明圣徒”安德鲁设计、可以发射子弹的远程武器，是世界上最早的火枪，受制于当时的技术难以铸造出成品，直到如今技术成熟才投入生产。受到光明圣徒的祝福，安全精炼时消耗的装备件数减少一半。',Feature=1,Delete=163607}",
  [163608] = "{id=163608,NameZh='远古回音·手枪[2]',Icon='item_63608',Type=310,MaxNum=99,SellPrice=3200,Desc='铭刻着神秘纹样的手枪，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,Delete=163608}",
  [163612] = "{id=163612,NameZh='黄金勒克斯手枪[2]',Icon='item_63612',Type=310,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='全大陆限量款手枪，枪身整体由黄金打造，造价惊人，三大国的许多权贵都将这把枪作为收藏品。“确认过眼神，是招惹不起的人……”',Feature=1,Delete=163612}",
  [163613] = "{id=163613,NameZh='黄金执法者[2]',Icon='item_63613',Type=310,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='当艾因布洛克的枪械师们打造出这样一款亮闪闪的手枪时，人们以为这是一款华而不实的工艺品。但令人惊诧的是这把枪的使用者在决斗中保持着超高的胜率——毕竟是一把自带“致盲”效果的枪呢！',Feature=1,Delete=163613}",
  [163614] = "{id=163614,NameZh='红翼左轮手枪[2]',Icon='item_63614',Type=310,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='专为快速连射设计的手枪，缩短的枪管更加轻便，搭配厚重的红色枪身，持握与射击手感极佳。',Feature=1,Delete=163614}",
  [163615] = "{id=163615,NameZh='地狱火手枪[2]',Icon='item_63615',Type=310,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='一位疯狂的枪械师设计出的疯狂的作品，在保留短管左轮枪射速的同时大胆的将枪管口径扩大，让这把枪可以尽情敌人倾泄弹雨。“谢天谢地，它没炸膛！”',Feature=1,Delete=163615}",
  [163907] = "{id=163907,NameZh='圣徒步枪[2]',Icon='item_63906',Type=320,Quality=3,MaxNum=99,SellPrice=100,Desc='由“光明圣徒”安德鲁设计可以发射子弹的远程武器，受制于当时的技术难以铸造出成品，据说雷根贝勒公司出产的步枪都是以它为原型。受到光明圣徒的祝福，安全精炼时消耗的装备件数减少一半。',Delete=163907}",
  [163908] = "{id=163908,NameZh='远古回音·来复枪[2]',Icon='item_63908',Type=320,MaxNum=99,SellPrice=3200,Desc='铭刻着神秘纹样的来复枪，是来自远古时代的宝藏。除了被选中的冒险者，其他人都无法掌控它的力量。',Level=160,Delete=163908}",
  [163912] = "{id=163912,NameZh='终结者狙击步枪[2]',Icon='item_63912',Type=320,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='配备大口径弹药的重型狙击枪，威力巨大可以轻松击穿骑士的重铠，也正因如此，只有那些经受过专业训练的神枪手才能驾驭它。',Feature=1,Delete=163912}",
  [163913] = "{id=163913,NameZh='强袭型终结者[2]',Icon='item_63913',Type=320,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='经过枪械大师改装的终结者狙击步枪，与通常型相比，强袭型终结者拥有更强的火力，配备的高倍率瞄准镜协助射手精准索敌，是每一个狙击手梦寐以求的完美武器。“看看那个弹坑！你管这玩意儿叫枪？”',Feature=1,Delete=163913}",
  [164200] = "{id=164200,NameZh='暴噬之刃[2]',Icon='item_64200',Type=190,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='传说是冥界主人海拉的两把镰刀之一。用于处决那些罪大恶极的亡灵，将它们的灵魂吞噬殆尽。',Delete=164200}",
  [164201] = "{id=164201,NameZh='万灵渊噬[2]',Icon='item_64201',Type=190,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='于冥河中淬炼千年的凶器，拥有着斩裂、吞噬一切生魂的欲望，唯有意志足够坚定的人方能驾驭，否则也将成为这柄镰刀的祭品。“给我……给我更多的灵魂！！”',Delete=164201}",
  [164202] = "{id=164202,NameZh='往生之刃[2]',Icon='item_64202',Type=190,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='传说是冥界主人海拉的两把镰刀之一。那些生性善良的亡灵会得到海拉的宽恕，这把镰刀将斩断他们与现世的羁绊，送他们进入轮回。',Delete=164202}",
  [164203] = "{id=164203,NameZh='彼岸之钥[2]',Icon='item_64203',Type=190,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=9600,Desc='即使对于冥界的主人海拉而言，这柄镰刀也颇为神秘，它可以联结现世与冥界，为现世的灵魂提供庇护。“冥界具现，守护我的同伴——开启吧，彼岸之门！”',Delete=164203}",
