  [380000] = "{id=380000,NameZh='蒙尘的符文石',Icon='item_380000',Type=56,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='外表掩盖了一层灰尘，被时光沉淀的符文石。它究竟隐藏着什么秘密？使用放大镜鉴定后，可能获得一枚A级或B级符文。',Delete=380000}",
  [380001] = "{id=380001,NameZh='放大镜',Icon='item_380001',Type=41,MaxNum=99999,SellPrice=100,Desc='看似平平无奇的放大镜，其实是符文专家贝恩的研究道具。使用后，可以鉴定出符文的品质。',Delete=380001}",
  [380010] = "{id=380010,NameZh='黯淡的符文石',Icon='item_380010',Type=56,MaxNum=99999,SellPrice=100,Desc='鉴定后可以随机获得一枚B级技能符文，在【符文之匣】中消耗放大镜进行鉴定。\n由于年代久远，看起来有些黯淡的符文石，隐约能感受到其中有魔力的涌动。',Delete=380010}",
  [380020] = "{id=380020,NameZh='光洁的符文石',Icon='item_380020',Type=56,MaxNum=99999,SellPrice=100,Desc='鉴定后可以随机获得一枚A级技能符文，在【符文之匣】中消耗放大镜进行鉴定。\n外表光滑无暇的符文石，随着时间的流逝，其中蕴含的魔力也愈发强烈。',Delete=380020}",
  [380030] = "{id=380030,NameZh='闪耀的符文石',Icon='item_380030',Type=56,MaxNum=99999,SellPrice=100,Desc='鉴定后可以随机获得一枚S级技能符文，在【符文之匣】中消耗放大镜进行鉴定。\n闪烁着强烈光芒的符文石，让人根本无法移开视线。光是看着，就能感受到其中隐含的巨大魔力。',Delete=380030}",
  [380040] = "{id=380040,NameZh='神奇的符文箱',Icon='item_3663',Type=30,MaxNum=99999,SellPrice=100,Desc='一个神奇的箱子，打开后可以获得若干技能符文或属性符文',Delete=380040}",
  [380050] = "{id=380050,NameZh='闪耀的符文石·星',Icon='item_380050',Type=56,MaxNum=99999,SellPrice=100,Desc='鉴定后可随机获得一枚全新的S级星·技能符文，在【符文之匣】中消耗放大镜进行鉴定。\n闪烁着星之光芒的符文石，隐隐能感受到其中陌生的能量。也许经过鉴定能看出它的本质。',Delete=380050}",
  [380060] = "{id=380060,NameZh='缚能之印',Icon='item_380000',Type=61,UseMode=4131,MaxNum=99999,SellPrice=100,Desc='蕴含魔力的原石，可用于兑换特定的符文石与符文袋（待“符文”功能开启后可以进行兑换）',Delete=380060}",
  [381000] = "{id=381000,NameZh='尘封的符文袋·Ⅰ',Icon='item_381000',Type=30,MaxNum=99999,SellPrice=100,Desc='开启后随机获得一枚1级属性符文。\n历经了岁月的洗礼，有些破旧泛黄的符文袋。没有人知道它承载的秘密。',Delete=381000}",
  [381010] = "{id=381010,NameZh='尘封的符文袋·Ⅱ',Icon='item_381010',Type=30,MaxNum=99999,SellPrice=100,Desc='开启后随机获得一枚2级属性符文。\n历经了岁月的洗礼，有些破旧泛黄的符文袋。没有人知道它承载的秘密。',Delete=381010}",
  [381020] = "{id=381020,NameZh='尘封的符文袋·Ⅲ',Icon='item_381020',Type=30,MaxNum=99999,SellPrice=100,Desc='开启后随机获得一枚3级属性符文。\n历经了岁月的洗礼，有些破旧泛黄的符文袋。没有人知道它承载的秘密。',Delete=381020}",
  [381030] = "{id=381030,NameZh='尘封的符文袋·Ⅳ',Icon='item_381030',Type=30,MaxNum=99999,SellPrice=100,Desc='开启后随机获得一枚4级属性符文。\n历经了岁月的洗礼，有些破旧泛黄的符文袋。没有人知道它承载的秘密。',Delete=381030}",
  [381040] = "{id=381040,NameZh='尘封的符文袋·Ⅴ',Icon='item_381040',Type=30,MaxNum=99999,SellPrice=100,Desc='开启后随机获得一枚5级属性符文。\n历经了岁月的洗礼，有些破旧泛黄的符文袋。没有人知道它承载的秘密。',Delete=381040}",
  [383001] = "{id=383001,NameZh='古旧的符文箱',Icon='item_383001',Type=61,UseMode=4089,MaxNum=99999,SellPrice=100,Desc='开启后可以选择获取一枚1级属性符文。\n从贝恩先生的地下室里偶然发现的老箱子，里面用法术存储着各种符文。',Delete=383001}",
