  [390000] = "{id=390000,NameZh='神之怜悯宝箱',Icon='item_390000',Type=30,MaxNum=99999,SellPrice=100,Desc='从达纳托斯之塔中找到的，女武神使用过的宝箱。隐约能感觉到一股轻微的魔力，打开后也许会有什么新发现。',Delete=390000}",
  [390001] = "{id=390001,NameZh='神之允诺宝箱',Icon='item_390001',Type=30,MaxNum=99999,SellPrice=100,Desc='从达纳托斯之塔中找到的，女武神使用过的宝箱。能感受到强烈的光明魔法波动，打开后可能有什么意外收获。',Delete=390001}",
  [390002] = "{id=390002,NameZh='神之恩赐宝箱',Icon='item_390002',Type=30,MaxNum=99999,SellPrice=100,Desc='从达纳托斯之塔中找到的，女武神使用过的宝箱。宝箱外部便有剧烈的女神之力在流动，开启后可能会有特别惊喜……',Delete=390002}",
  [390010] = "{id=390010,NameZh='奥术古匣',Icon='item_390000',Type=30,MaxNum=99999,SellPrice=100,Desc='从奥术魔方中的衍生出的宝匣，仔细观察能感受到缥缈的魔力。看起来不是很牢固，打开时要小心。',Delete=390010}",
  [390011] = "{id=390011,NameZh='奥术秘藏',Icon='item_390001',Type=30,MaxNum=99999,SellPrice=100,Desc='从奥术魔方中的衍生出的宝匣，被不小的魔力包裹着。由秘银制成，十分坚固，不知里面藏着什么宝物。',Delete=390011}",
  [390012] = "{id=390012,NameZh='奥术至宝',Icon='item_390002',Type=30,MaxNum=99999,SellPrice=100,Desc='从奥术魔方中的衍生出的宝匣，蕴含着巨大的神力。由纯金制成，装着来自神域的珍藏，只有最强大的冒险者能够拥有。',Delete=390012}",
  [390020] = "{id=390020,NameZh='沉沦之匣',Icon='item_390000',Type=30,MaxNum=99999,SellPrice=100,Desc='从达纳托斯之塔里的意念聚合体中掉落的神秘匣子。被淡淡的黑气笼罩，能察觉到其中微弱的魔力。',Delete=390020}",
  [390021] = "{id=390021,NameZh='混沌之匣',Icon='item_390001',Type=30,MaxNum=99999,SellPrice=100,Desc='从达纳托斯之塔里的意念聚合体中掉落的神秘匣子。外侧有轻微的腐蚀痕迹，触摸便能感受到魔力的涌动。',Delete=390021}",
  [390022] = "{id=390022,NameZh='深渊之匣',Icon='item_390002',Type=30,MaxNum=99999,SellPrice=100,Desc='从达纳托斯之塔里的意念聚合体中掉落的神秘匣子。整体被严重腐蚀，看起来非常破旧，但依旧能发现有强大的魔力即将冲破而出。',Delete=390022}",
  [390030] = "{id=390030,NameZh='迷失的岁月之匣',Icon='item_390000',Type=30,MaxNum=99999,SellPrice=100,Desc='散发着浓郁黑暗力量的古匣，似乎存储着达纳托斯使用过的宝物。不知怎的，望着它便会感到一阵悲伤。',Delete=390030}",
  [390031] = "{id=390031,NameZh='沉默的回忆之匣',Icon='item_390001',Type=30,MaxNum=99999,SellPrice=100,Desc='随着时间流逝有些破碎的古匣，隐约有光芒从中透出。似乎存储着达纳托斯使用过的宝物，有着令人怀念的气息。',Delete=390031}",
  [390032] = "{id=390032,NameZh='逝去的荣光之匣',Icon='item_390002',Type=30,MaxNum=99999,SellPrice=100,Desc='外形古老的精致木匣，被一股温暖的魔力包裹着。似乎存储着达纳托斯使用过的宝物，捧着它便能感受到时间的重量。',Delete=390032}",
