  [391000] = "{id=391000,NameZh='圣雪羽',Icon='item_391000',Type=41,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='拉斯格瑞丝将白雪融为羽刃，赠送给薇薇莉亚的护身羽毛，散发着雪白色的辉光。集齐6个可接取任务圣羽礼赞，已获得拉斯格瑞丝·羽落的玩家，可以在达纳托斯之塔地图东部找安立路再次兑换。',Feature=1,}",
  [391001] = "{id=391001,NameZh='女神之羽',Icon='item_391001',Type=61,UseMode=4092,MaxNum=99999,SellPrice=100,Desc='拉斯格瑞丝将神赐的羽刃赠与其认可的最强的冒险者。使用后可兑换商店内的任一道具。',NoSale=1,}",
