  [391004] = "{id=391004,NameZh='英雄之铠',Icon='item_391004',Type=61,UseMode=4095,MaxNum=99999,SellPrice=100,Desc='沉沦的英雄达纳托斯身着的铠甲之角，仿佛可以由此看到昔日的光辉岁月。使用后可兑换商店内的任一道具。',NoSale=1,}",
