  [500000] = "{id=500000,NameZh='我中意你',Icon='item_500000',Type=41,Quality=5,MaxNum=99999,SellPrice=10,AdventureSort=100,AdventureValue=-1,Desc='选择一名玩家并对其使用，将在您与他之间产生一条爱慕的热情连线。（如果对方也回应的话，将会…）',ItemTarget={range=10,type=3},Feature=4,}",
  [500200] = "{id=500200,NameZh='月之低语',Icon='item_500200',Type=41,Quality=5,MaxNum=99999,SellPrice=20,AdventureSort=101,AdventureValue=-1,Desc='大陆最著名的香水世家：穆拉辛家族的第十四代目社长维特尔·穆拉辛的最新得意之作：【月之低语】。据说某个夜晚社长得到了月神的祝福于是才研制出这个极其魅惑人心的香味。',Feature=4,}",
  [500201] = "{id=500201,NameZh='威尼斯之夏',Icon='item_500200',Type=41,Quality=5,MaxNum=99999,SellPrice=20,AdventureSort=102,AdventureValue=-1,Desc='大陆最著名的香水世家：穆拉辛家族的第十四代目社长维特尔·穆拉辛的经典款作品：【威尼斯之夏】。即使再炎热的盛夏，马蒂尔·穆拉辛小姐依然可以身着厚重华丽的洋装并保持庄严和优雅。',Feature=4,}",
  [500400] = "{id=500400,NameZh='恶作剧魔棒-波利',Icon='item_500400',Type=41,Quality=5,MaxNum=99999,SellPrice=30,AdventureSort=103,AdventureValue=-1,Desc='古老的魔女一族非常喜欢捉弄那些胆敢擅闯他们领地的家伙。这个魔棒可以将那些可怜的家伙变成一只小青蛙或者…',ItemTarget={range=10,type=1},}",
  [500401] = "{id=500401,NameZh='恶作剧魔棒-土波利',Icon='item_500400',Type=41,Quality=5,MaxNum=99999,SellPrice=30,AdventureSort=104,Desc='古老的魔女一族非常喜欢捉弄那些胆敢擅闯他们领地的家伙。这个魔棒可以将那些可怜的家伙变成一只小青蛙或者…',ItemTarget={range=10,type=1},}",
  [500402] = "{id=500402,NameZh='恶作剧魔棒-波波利',Icon='item_500400',Type=41,Quality=5,MaxNum=99999,SellPrice=30,AdventureSort=105,Desc='古老的魔女一族非常喜欢捉弄那些胆敢擅闯他们领地的家伙。这个魔棒可以将那些可怜的家伙变成一只小青蛙或者…',ItemTarget={range=10,type=1},}",
  [500403] = "{id=500403,NameZh='恶作剧魔棒-冰波利',Icon='item_500400',Type=41,Quality=5,MaxNum=99999,SellPrice=20,AdventureSort=106,AdventureValue=-1,Desc='古老的魔女一族非常喜欢捉弄那些胆敢擅闯他们领地的家伙。这个魔棒可以将那些可怜的家伙变成一只小青蛙或者…',ItemTarget={range=10,type=1},}",
  [500500] = "{id=500500,NameZh='温婉月光',Icon='item_500500',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=1,AdventureValue=1,StorageReward={buffid={82000110}},Condition=8,Desc='散发着海洋气息的香水，混着柑橘和木头的清香，喷后身上会披上一层月光，仿佛月光布满的蓝丝绒水面般温柔却带着少许忧伤。',NoSale=1,}",
  [500501] = "{id=500501,NameZh='变傻光线枪',Icon='toy_501',Type=44,Quality=3,MaxNum=99999,SellPrice=60,AdventureSort=107,AdventureValue=-1,Desc='只要用这把枪对着其他玩家轻轻一BIU~对方大概就会变傻了吧！（对其他玩家使用，可随机将其变成巨人或者小矮子）',ItemTarget={range=10,type=3},}",
  [500502] = "{id=500502,NameZh='艾娃',Icon='toy_502',Type=41,Quality=5,MaxNum=99999,SellPrice=80,AdventureSort=108,AdventureValue=-1,Desc='Evanglic Dream，简称是EV娃娃，是由里希塔乐的玩具公司：沃尔金最新研制开发的拟真球型人偶娃娃。希望广大消费者们能够喜欢！',}",
  [500503] = "{id=500503,NameZh='绝对领域',Icon='toy_503',Type=41,Quality=5,MaxNum=99999,SellPrice=80,AdventureSort=109,AdventureValue=-1,Desc='使用后创造一个高纬度的空间，这里是只属于你们的乐园。尽情玩耍吧！（每天限制使用次数：3）',}",
  [500504] = "{id=500504,NameZh='伪装卷轴',Icon='toy_504',Type=41,MaxNum=99999,AuctionPrice=0,SellPrice=40,AdventureSort=110,AdventureValue=-1,Desc='大家好，我是你们的新朋友：告示牌。（使用后可以完美地伪装成一个…告示牌？…）',}",
  [500505] = "{id=500505,NameZh='嘎嘎嘎！',Icon='toy_505',Type=41,Quality=2,MaxNum=99999,SellPrice=40,AdventureSort=111,AdventureValue=-1,Desc='这个酷极了的蝗虫乐队让你安静的生活不再无聊。随时带上他们吧！(使用后召唤一个蝗虫乐队）',}",
  [500506] = "{id=500506,NameZh='痒痒棒',Icon='toy_506',Type=41,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,AdventureSort=112,AdventureValue=-1,Desc='站住！别跑！（对其他玩家使用后可以让自己和对方一起哈哈大笑，停止目前的一切动作。）',ItemTarget={range=10,type=1},}",
  [500507] = "{id=500507,NameZh='鞭炮',Icon='toy_507',Type=64,Quality=5,MaxNum=99999,AuctionPrice=0,SellPrice=100,Desc='传说中东方国度，为了庆祝新年的习俗之一，用古老的配方制作的小纸管，点燃可以在夜空绽放出五彩斑斓的花火。习俗的来源据说是为了驱赶某些邪恶事物。使用时请注意安全！请勿对着其他冒险者点燃！（使用效果：如果对某种特定的魔物，仿佛可以起到效果拔群的奇效！）',Feature=1,}",
  [500508] = "{id=500508,NameZh='月之兔·白玉',Icon='toy_508',Type=41,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=1001,AdventureValue=-1,Desc='“童年的回忆中，每到那个围着围巾，嘴里呼着白气的季节，就盼望着爷爷冒险归来，那时他都会和奶奶一起手工编织好多好多的可爱兔子灯送给我。幼年的我，和邻家小伙伴一起拖着这些摇曳温馨光芒的兔子灯奔跑在雪地上，欢笑着，冻得脸颊都通红。这是至今不曾被遗忘的宝贵记忆。”------《爷爷的故事》第三卷第二十七章（使用后可以牵起一只被点亮烛光的白色兔子灯，那光芒是如此的温暖，会让人回想其很多往事。）',Feature=1,}",
  [500509] = "{id=500509,NameZh='月之兔·碧海',Icon='toy_509',Type=41,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=1002,AdventureValue=-1,Desc='“童年的回忆中，每到那个围着围巾，嘴里呼着白气的季节，就盼望着爷爷冒险归来，那时他都会和奶奶一起手工编织好多好多的可爱兔子灯送给我。幼年的我，和邻家小伙伴一起拖着这些摇曳温馨光芒的兔子灯奔跑在雪地上，欢笑着，冻得脸颊都通红。这是至今不曾被遗忘的宝贵记忆。”------《爷爷的故事》第三卷第二十七章（使用后可以牵起一只被点亮烛光的蓝色兔子灯，那光芒是如此的温暖，会让人回想其很多往事。）',Feature=1,}",
  [500510] = "{id=500510,NameZh='来自B格猫的贺卡',Icon='item_500510',Type=63,Quality=5,MaxNum=1,SellPrice=100,Desc='一份来自B格猫的新年贺卡嘿，冒险者们。新年的钟声敲响了，B格猫星人集体祝福大家新年快乐，鸡年大吉！ 这是我们一起过的第一个农历春节，2017年我们还想和大家一起过很多很多的节日。目前我们仍有很多不足，我们也在努力，努力与大家一同构筑这美好的大世界呀！感谢大家的支持与包容，送上一份小小心意，给你拜年啦！-----------<B格猫星球住民联名书写>',}",
  [500511] = "{id=500511,NameZh='小野猪的体检报告Ⅰ',Icon='item_500511',Type=62,MaxNum=1,SellPrice=100,Desc='根据咿维的身体状况得到的体检报告：第一天，身体健康，体型与力量较弱。',}",
  [500512] = "{id=500512,NameZh='小野猪的体检报告Ⅱ',Icon='item_500511',Type=62,MaxNum=1,SellPrice=200,Desc='根据咿维的身体状况得到的体检报告：第二天，身体逐渐变强，体型与力量也在缓慢增强。',}",
  [500513] = "{id=500513,NameZh='小野猪的体检报告Ⅲ',Icon='item_500511',Type=62,MaxNum=1,SellPrice=300,Desc='根据咿维的身体状况得到的体检报告：第三天，身体愈发结实，力量开始飞速增长。',}",
  [500514] = "{id=500514,NameZh='小野猪的体检报告Ⅳ',Icon='item_500511',Type=62,MaxNum=1,SellPrice=400,Desc='根据咿维的身体状况得到的体检报告：第四天，身体结实无比，体型开始趋于稳定，力量缓慢增长。',}",
  [500515] = "{id=500515,NameZh='小野猪的体检报告Ⅴ',Icon='item_500511',Type=62,MaxNum=1,SellPrice=500,Desc='根据咿维的身体状况得到的体检报告：第五天，身体健康，体型暴增，力量急速增长。',}",
  [500516] = "{id=500516,NameZh='绝对领域·星',Icon='toy_510',Type=41,MaxNum=99999,SellPrice=16,Desc='“对星星的向往并不只是孩子们的特权”。使用后创造一个高纬度的空间，这里是只属于你们的乐园。尽情玩耍吧！（每天限制使用次数：3）',}",
  [500517] = "{id=500517,NameZh='花火',Icon='toy_511',Type=41,MaxNum=99999,SellPrice=16,Desc='“孩子们依然不会忘记在妈妈的怀抱里期盼着夜空中闪耀的花朵”。使用后可以升起一个耀眼的烟花。',}",
  [500518] = "{id=500518,NameZh='烟花·回家的温暖',Icon='toy_512',Type=41,MaxNum=99999,SellPrice=100,Desc='“孩子们依然不会忘记在妈妈的怀抱里期盼着夜空中闪耀的花朵”。使用后可以升起一个耀眼的烟花。',}",
  [500519] = "{id=500519,NameZh='艾娃·ATF握手券',Icon='toy_502',Type=41,Quality=5,MaxNum=99999,SellPrice=80,Desc='Evanglic Dream，简称是EV娃娃，是由里希塔乐的玩具公司：沃尔金最新研制开发的拟真球型人偶娃娃。希望广大消费者们能够喜欢！',Feature=1,}",
  [500520] = "{id=500520,NameZh='新春鞭炮',Icon='toy_507',Type=64,Quality=5,MaxNum=99999,AuctionPrice=0,SellPrice=100,Desc='传说中东方国度，为了庆祝新年的习俗之一，用古老的配方制作的小纸管，点燃可以在夜空绽放出五彩斑斓的花火。习俗的来源据说是为了驱赶某些邪恶事物。使用时请注意安全！请勿对着其他冒险者点燃！（使用效果：如果对某种特定的魔物，仿佛可以起到效果拔群的奇效！）',Feature=1,}",
  [500521] = "{id=500521,NameZh='猫猫沙发椅',Icon='toy_513',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=110,AdventureValue=1,StorageReward={buffid={82000090}},Condition=8,Desc='最新款猫猫牌沙发椅，造型可爱，质量上乘，绝对经久耐用！休憩、乘凉、自拍……还可以拉上小伙伴们一起喝茶聊天！',Feature=1,TFValidDate='2019-07-29 05:00:00',ValidDate='2019-08-01 05:00:00',}",
  [500522] = "{id=500522,NameZh='月之兔·天涯',Icon='toy_508',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=104,AdventureValue=1,StorageReward={buffid={82000110}},Condition=8,Desc='玩具公司最新研发的永久型兔子灯，使用后可以牵起一只被点亮烛光的白色兔子灯，那光芒是如此的温暖，会让人回想其很多往事……“童年的回忆中，每到那个围着围巾，嘴里呼着白气的季节，就盼望着爷爷冒险归来，那时他都会和奶奶一起手工编织好多好多的可爱兔子灯送给我。幼年的我，和邻家小伙伴一起拖着这些摇曳温馨光芒的兔子灯奔跑在雪地上，欢笑着，冻得脸颊都通红。这是至今不曾被遗忘的宝贵记忆。”——《爷爷的故事》第三卷第二十七章',GetLimit={limit={[999]={1,0}},source={10,19,54,97},type=1},Feature=1,TFValidDate='2019-02-16 05:00:00',ValidDate='2019-02-19 05:00:00',}",
  [500523] = "{id=500523,NameZh='月之兔·海角',Icon='toy_509',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=105,AdventureValue=1,StorageReward={buffid={82000120}},Condition=8,Desc='玩具公司最新研发的永久型兔子灯，使用后可以牵起一只被点亮烛光的蓝色兔子灯，那光芒是如此的温暖，会让人回想其很多往事……“童年的回忆中，每到那个围着围巾，嘴里呼着白气的季节，就盼望着爷爷冒险归来，那时他都会和奶奶一起手工编织好多好多的可爱兔子灯送给我。幼年的我，和邻家小伙伴一起拖着这些摇曳温馨光芒的兔子灯奔跑在雪地上，欢笑着，冻得脸颊都通红。这是至今不曾被遗忘的宝贵记忆。”——《爷爷的故事》第三卷第二十七章',GetLimit={limit={[999]={1,0}},source={10,19,54,97},type=1},Feature=1,TFValidDate='2019-02-16 05:00:00',ValidDate='2019-02-19 05:00:00',}",
  [500524] = "{id=500524,NameZh='梦罗克之影',Icon='item_500524',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=103,AdventureValue=1,StorageReward={buffid={82000080}},Condition=8,Desc='可以召唤出魔王梦罗克的神奇玩具，没有人知道魔王梦罗克是怎么被塞进这个小玩具里的。',Feature=1,}",
  [500525] = "{id=500525,NameZh='梦罗克气息',Icon='item_500525',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=102,AdventureValue=1,StorageReward={buffid={82000100}},Condition=8,Desc='可以使自己被梦罗克的气息围绕的玩具，万一被别的冒险者当作是入侵者可怎么办？',Feature=1,}",
  [500526] = "{id=500526,NameZh='迷你时空裂隙',Icon='item_500526',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=101,AdventureValue=1,StorageReward={buffid={82000100}},Condition=8,Desc='一件精致的工艺品，用来纪念那个被时空裂隙侵蚀的年代！',Feature=1,}",
  [500538] = "{id=500538,NameZh='残破噩梦',Icon='item_500538',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=5,AdventureValue=1,StorageReward={buffid={80012860}},Condition=8,Desc='达纳托斯之塔中的幻影凝聚而成的残像。它附身于进出于塔的冒险者之上，所经之处皆会燃起邪恶的火焰。而那双凝视深渊的眼眸中，隐约能看见昔日魔王的影子……',Feature=1,}",
  [500592] = "{id=500592,NameZh='炽热符文之影',Icon='item_500592',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=4,AdventureValue=1,StorageReward={buffid={80012860}},Condition=8,Desc='“翻涌吧，无上的魔力将在天际间咆哮！”古炼金术师使用秘咒制作的道具，让使用之人可以将符文化作身边的光影。',Feature=1,}",
  [500593] = "{id=500593,NameZh='神秘召唤彩蛋',Icon='item_500593',Type=77,MaxNum=99999,SellPrice=100,AdventureSort=106,AdventureValue=1,StorageReward={buffid={82000090}},Condition=8,Desc='颜色绚丽，充满神秘气息的彩蛋。仔细看还在微微晃动，好像有什么即将破壳而出……\n使用后召唤一个彩蛋，敲破彩蛋后会被神秘气息笼罩一段时间，蛋内破出的小家伙会被这股气息吸引而跟随你哦~\n注：每天限制使用3次。',Feature=1,TFValidDate='2019-04-18 05:00:00',ValidDate='2019-04-21 05:00:00',}",
  [500594] = "{id=500594,NameZh='永远的赛尼亚',Icon='item_500594',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=3,AdventureValue=1,StorageReward={buffid={82000110}},Condition=8,Desc='我们约定好了的，要一起去冒险…',Feature=1,}",
  [500600] = "{id=500600,NameZh='琥珀光尘',Icon='item_500600',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=2,AdventureValue=1,StorageReward={buffid={82000110}},Condition=8,Desc='散发着琥珀石味道的香水，混着甘草和蜡菊的清香，喷后身上会有烟粉尘围绕，仿佛飘起的石尘被午后的阳光披撒。',NoSale=1,}",
  [500601] = "{id=500601,NameZh='呼噜之家',Icon='item_500601',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=201,AdventureValue=1,StorageReward={buffid={82000110}},Condition=8,Desc='流浪猫寄宿的纸箱子，能听见猫咪睡着时的呼噜声。使用后能召唤一个“奇妙快递箱”。',Feature=1,}",
  [500602] = "{id=500602,NameZh='进击的火鸟',Icon='item_500602',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=202,AdventureValue=1,StorageReward={buffid={82000120}},Condition=8,Desc='“别看我小，我长大会喷火”。使用后能召唤一个火焰幼鸟。',Feature=1,}",
  [500603] = "{id=500603,NameZh='夏日幻想',Icon='item_500603',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=203,AdventureValue=1,StorageReward={buffid={82000110}},Condition=8,Desc='充满夏日气息的幻想礼，能召唤出夏日气泡。使用后可以使当前天气发生变化。',Feature=1,}",
  [500604] = "{id=500604,NameZh='森灵呓语',Icon='item_500604',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=204,AdventureValue=1,StorageReward={buffid={82000120}},Condition=8,Desc='森灵之力凝聚的核心，据说使用后能听见精灵呓语，并带来好运哦。使用后可以随机获得四种元素精灵的祝福。',Feature=1,}",
  [500605] = "{id=500605,NameZh='盛夏幽梦',Icon='item_500605',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=205,AdventureValue=1,StorageReward={buffid={82000110}},Condition=8,Desc='“嘿，要来一起玩吗！”使用后会感到头上有阵阵凉风哦。',Feature=1,}",
  [500606] = "{id=500606,NameZh='背叛书页',Icon='item_500606',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=206,AdventureValue=1,StorageReward={buffid={82000120}},Condition=8,Desc='有着言灵秘术的书页，寄宿背叛言灵，使用后的效果未知，据说是用来整蛊的魔法道具。可以对一名玩家使用，他是叛徒！',ItemTarget={range=10,type=1},Feature=1,}",
  [500607] = "{id=500607,NameZh='恶魔谎言',Icon='item_500607',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=207,AdventureValue=1,StorageReward={buffid={82000110}},Condition=8,Desc='“请终止你的危险言论！”可以对一名玩家使用，揭露他的谎言！',ItemTarget={range=10,type=1},Feature=1,}",
  [500608] = "{id=500608,NameZh='甜蜜气泡',Icon='item_500608',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=208,AdventureValue=1,StorageReward={buffid={82000120}},Condition=8,Desc='被爱心包围的时候，一定是相当甜蜜的吧！',Feature=1,}",
  [500609] = "{id=500609,NameZh='朗月之约',Icon='item_500609',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=209,AdventureValue=1,StorageReward={buffid={82000110}},Condition=8,Desc='“今晚月色真美！”',Feature=1,}",
  [500610] = "{id=500610,NameZh='黯影之纱',Icon='item_500610',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=210,AdventureValue=1,StorageReward={buffid={82000120}},Condition=8,Desc='用稀有星砂制成的纱，据说戴上后能够获得隐身效果！',Feature=1,}",
  [500611] = "{id=500611,NameZh='黄金星盘',Icon='item_500611',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=211,AdventureValue=1,StorageReward={buffid={82000110}},Condition=8,Desc='蕴含时空力量的黄金星盘，能带你去世界任何一处地方遨游。（每日只能使用一次）',Feature=1,}",
  [500612] = "{id=500612,NameZh='命运时钟',Icon='item_500612',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=212,AdventureValue=1,StorageReward={buffid={82000120}},Condition=8,Desc='命运的时钟开始的转动，你渴望遇见谁呢？',Feature=1,}",
  [500613] = "{id=500613,NameZh='通行禁止',Icon='item_500613',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=213,AdventureValue=1,StorageReward={buffid={82000110}},Condition=8,Desc='前方危险，禁止通行！（每日只能使用两次）',Feature=1,}",
  [500614] = "{id=500614,NameZh='言灵宝箱',Icon='item_500614',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=214,AdventureValue=1,StorageReward={buffid={82000120}},Condition=8,Desc='“我说什么，你就给什么嘛？”（每日只能使用两次）',Feature=1,}",
  [500615] = "{id=500615,NameZh='樱色誓约',Icon='item_500615',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=215,AdventureValue=1,StorageReward={buffid={82000110}},Condition=8,Desc='“天空树的樱花真的很好看！”',Feature=1,}",
  [500616] = "{id=500616,NameZh='樱花蛋糕',Icon='item_500616',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=216,AdventureValue=1,StorageReward={buffid={82000120}},Condition=8,Desc='狐灵赠送的樱花蛋糕，据说能吸引神奇的生物到来……',Feature=1,}",
  [500617] = "{id=500617,NameZh='萤灵之戒',Icon='item_500617',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=217,AdventureValue=1,StorageReward={buffid={82000110}},Condition=8,Desc='萤之精灵的赠礼，仲夏之夜，能召唤出漂亮的萤火虫。',Feature=1,}",
  [500618] = "{id=500618,NameZh='珍珠贝',Icon='item_500618',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=218,AdventureValue=1,StorageReward={buffid={82000120}},Condition=8,Desc='“到我嘴里来！”',Feature=1,}",
  [500619] = "{id=500619,NameZh='王者归来',Icon='item_500619',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=219,AdventureValue=1,StorageReward={buffid={82000110}},Condition=8,Desc='哥布灵之王的塑像，传说中在它的身上有着哥布灵一族的秘宝！',Feature=1,}",
  [500620] = "{id=500620,NameZh='第五号实验笔记',Icon='item_500620',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=220,AdventureValue=1,StorageReward={buffid={82000120}},Condition=8,Desc='记录第五号实验的笔记本！快对朋友试试！前方危险！',ItemTarget={range=10,type=1},Feature=1,}",
  [500621] = "{id=500621,NameZh='美食手记',Icon='item_500621',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=221,AdventureValue=1,StorageReward={buffid={82000110}},Condition=8,Desc='美食精灵们制作的手记！里面记录着各类美食的做法！（每日只能使用一次）',Feature=1,}",
  [500622] = "{id=500622,NameZh='珍品食匣',Icon='item_500622',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=222,AdventureValue=1,StorageReward={buffid={82000120}},Condition=8,Desc='“呀！是糖果积木！”（每日只能使用一次）',Feature=1,}",
  [500623] = "{id=500623,NameZh='整蛊魔法试剂',Icon='item_500623',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=223,AdventureValue=1,StorageReward={buffid={82000110}},Condition=8,Desc='用来整蛊他人的魔法试剂，一起来恶作剧吧！',ItemTarget={range=10,type=1},Feature=1,}",
  [500624] = "{id=500624,NameZh='安娜的宝藏卡',Icon='item_500624',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=224,AdventureValue=1,StorageReward={buffid={82000120}},Condition=8,Desc='安娜用魔法制成的魔法卡，使用后就能找到她存放私房钱的零钱罐。（每日只能使用两次）',Feature=1,}",
  [500625] = "{id=500625,NameZh='胜利金苹果',Icon='item_500625',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=225,AdventureValue=1,StorageReward={buffid={82000110}},Condition=8,Desc='庆祝胜利的黄金苹果，一起大喊“胜利”吧！',Feature=1,}",
  [500626] = "{id=500626,NameZh='死灵之柩',Icon='item_500626',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=226,AdventureValue=1,StorageReward={buffid={82000120}},Condition=8,Desc='蕴含死灵魔法的木柩模型，使用后能短暂时间变成幽灵。',Feature=1,}",
  [500627] = "{id=500627,NameZh='黄金铃铛',Icon='item_500627',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=227,AdventureValue=1,StorageReward={buffid={82000110}},Condition=8,Desc='“叮叮当，叮叮当”摇响铃铛，圣诞老人就会来哦。',Feature=1,}",
  [500628] = "{id=500628,NameZh='深渊骑士之旗',Icon='item_500628',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=228,AdventureValue=1,StorageReward={buffid={82000120}},Condition=8,Desc='蕴含深渊魔法的旗帜，使用后能获得深渊骑士的力量！（每日只能使用一次）',Feature=1,}",
  [500629] = "{id=500629,NameZh='灵魄之匣',Icon='item_500629',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=229,AdventureValue=1,StorageReward={buffid={82000110}},Condition=8,Desc='封存灵魄的灵魄之匣，开启后能获得灵魄的力量！（每日只能使用一次）',Feature=1,}",
  [500630] = "{id=500630,NameZh='俄赛里斯之泪',Icon='item_500630',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=230,AdventureValue=1,StorageReward={buffid={82000120}},Condition=8,Desc='蕴含俄赛里斯精魂的眼泪，使用后，能伪装成俄赛里斯的样子！不过，慎用哦！（每日只能使用一次）',Feature=1,}",
  [500631] = "{id=500631,NameZh='龙卷气流号',Icon='item_500631',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=231,AdventureValue=1,StorageReward={buffid={82000100}},Condition=8,Desc='划破长空，风雨无阻，所过之处卷起乱流，撩拨少年的心弦......嗨，其实只是架纸飞机。',}",
  [500632] = "{id=500632,NameZh='永恒的月光',Icon='item_500632',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=232,AdventureValue=1,StorageReward={buffid={82000080}},Condition=8,Desc='温柔的月光永恒不变，正如狼人少年守候的决心，和月精灵送别的吻。',NoSale=1,}",
  [500633] = "{id=500633,NameZh='竹林旧事',Icon='item_500633',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=233,AdventureValue=1,StorageReward={buffid={82000090}},Condition=8,Desc='火焰燃尽曾经的家乡，竹林又在灰烬上重生。水车旁的白熊递出竹叶：旅人，且听一段陈旧的过往。',NoSale=1,}",
  [500634] = "{id=500634,NameZh='虹之歌',Icon='item_500634',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=234,AdventureValue=1,StorageReward={buffid={82000090}},Condition=8,Desc='“森林阴云笼罩，幼龙带来雷鸣和火光。勇士和冒险者平息风暴，久违的彩虹撑起罗比奥的晴天。”',NoSale=1,}",
  [500635] = "{id=500635,NameZh='花神竖琴',Icon='item_500635',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=235,AdventureValue=1,StorageReward={buffid={82000080}},Condition=8,Desc='时光或许会令回忆褪色，但爱将重新唤醒有情人的灵魂。拨动琴弦，与我一起重温布拉吉和伊多娜的传奇。',NoSale=1,}",
  [500636] = "{id=500636,NameZh='致命联结',Icon='item_500636',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=236,AdventureValue=1,StorageReward={buffid={82000100}},Condition=8,Desc='你无法挣脱的我的感情，就像猎物撞进蜘蛛的网里——别紧张，我又不会吃、了、你。',ItemTarget={range=10,type=3},NoSale=1,}",
  [500637] = "{id=500637,NameZh='知更鸟',Icon='item_500637',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=237,AdventureValue=1,StorageReward={buffid={82000090}},Condition=8,Desc='知更鸟永远在歌唱，用爱守护一方水土。“爷爷的愿望，我会继承下去的，啾！”',NoSale=1,}",
  [500638] = "{id=500638,NameZh='人造伊米尔之心',Icon='item_500638',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=238,AdventureValue=1,StorageReward={buffid={82000120}},Condition=8,Desc='研究所中发现的人造伊米尔之心，经过处理已经不再具备使人异变的能力。但假装实验体吓人的话，还是非常好用的。',NoSale=1,}",
  [500639] = "{id=500639,NameZh='宴会之钟',Icon='item_500639',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=239,AdventureValue=1,StorageReward={buffid={82000080}},Condition=8,Desc='铛铛铛——宴会的黄金大钟已经敲响，精灵摆上甜品、美食和珍酿。“客人们，敞开肚皮、尽情享用吧！”',NoSale=1,}",
  [500640] = "{id=500640,NameZh='祈祷之泉',Icon='item_500640',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=240,AdventureValue=1,StorageReward={buffid={82000100}},Condition=8,Desc='真相终会揭露，正如坚冰也会消融。“阿娜雅，我会陪着你的。从今往后，阳光是我，风雪是我……”',NoSale=1,}",
  [500641] = "{id=500641,NameZh='迷你金字塔',Icon='item_500641',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=241,AdventureValue=1,StorageReward={buffid={82000110}},Condition=8,Desc='托雷娜制作的礼物，答谢你帮助她探寻出俄赛里斯的秘密。“我这个金字塔可不是简单的纪念品——诶诶诶，小心激光啊！”',NoSale=1,}",
  [500642] = "{id=500642,NameZh='图腾篝火',Icon='item_500642',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=242,AdventureValue=1,StorageReward={buffid={82000100}},Condition=8,Desc='兽人一族为答谢冒险者修复祭坛、寻回火种而制作的礼物。“无论何时何地，愿神火的光辉总能照耀你。”',NoSale=1,}",
  [500643] = "{id=500643,NameZh='惊喜魔盒',Icon='item_500643',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=243,AdventureValue=1,StorageReward={buffid={82000100}},Condition=8,Desc='猜猜里面有什么？我不告诉你！告诉你了那还叫惊喜吗？',NoSale=1,}",
  [500644] = "{id=500644,NameZh='奇异魔法阵',Icon='item_500572',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=244,AdventureValue=1,StorageReward={buffid={82000120}},Condition=8,Desc='一个奇异的魔法阵，盯着他看了好久，并没有什么奇怪的事情发生。',NoSale=1,}",
  [500645] = "{id=500645,NameZh='吸血鬼之夜',Icon='item_500528',Type=77,Quality=5,MaxNum=99999,SellPrice=100,AdventureSort=245,AdventureValue=1,StorageReward={buffid={82000110}},Condition=8,Desc='夜幕降临，传说中的伯爵开始出来觅食了。',NoSale=1,}",
  [500646] = "{id=500646,NameZh='玩具奖杯',Icon='item_500646',Type=77,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=246,AdventureValue=1,Condition=8,Desc='%s在公会战S1赛季中凭借优秀的表现，脱颖而出成为被女武神眷顾的王者。特以此奖杯作为纪念，纪念这永久的荣光！',NoSale=1,NoStorage=5,}",
