  [500648] = "{id=500648,NameZh='公会战S3赛季奖杯',Icon='item_500648',Type=77,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=248,AdventureValue=1,Condition=8,Desc='%s在公会战S3赛季中凭借优秀的表现，脱颖而出成为被女武神眷顾的王者。特以此奖杯作为纪念，纪念这永久的荣光！',NoSale=1,NoStorage=5,}",
  [500649] = "{id=500649,NameZh='公会战S4赛季奖杯',Icon='item_500649',Type=77,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=249,AdventureValue=1,Condition=8,Desc='%s在公会战S4赛季中凭借优秀的表现，脱颖而出成为被女武神眷顾的王者。特以此奖杯作为纪念，纪念这永久的荣光！',NoSale=1,NoStorage=5,}",
  [500650] = "{id=500650,NameZh='公会战S5赛季奖杯',Icon='item_500650',Type=77,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=250,AdventureValue=1,Condition=8,Desc='%s在公会战S5赛季中凭借优秀的表现，脱颖而出成为被女武神眷顾的王者。特以此奖杯作为纪念，纪念这永久的荣光！',NoSale=1,NoStorage=5,}",
  [500651] = "{id=500651,NameZh='公会战S6赛季奖杯',Icon='item_500651',Type=77,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=251,AdventureValue=1,Condition=8,Desc='%s在公会战S6赛季中凭借优秀的表现，脱颖而出成为被女武神眷顾的王者。特以此奖杯作为纪念，纪念这永久的荣光！',NoSale=1,NoStorage=5,}",
  [500652] = "{id=500652,NameZh='公会战S7赛季奖杯',Icon='item_500652',Type=77,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=252,AdventureValue=1,Condition=8,Desc='%s在公会战S7赛季中凭借优秀的表现，脱颖而出成为被女武神眷顾的王者。特以此奖杯作为纪念，纪念这永久的荣光！',NoSale=1,NoStorage=5,}",
  [550000] = "{id=550000,NameZh='厨神的鹰眼',Icon='item_550000',Type=41,Quality=4,MaxNum=99999,SellPrice=100,Desc='狩猎之神·乌勒尔本是众神中极受人类爱戴的神明，在那个时代，人们总会为下一顿吃什么犯愁，若是遇到暴雨干旱，往往一家人将整年都在饥荒中度过，漫长的冰封雪季，想要出门捕猎往往是件将生命拿去赌博的事。但当乌勒尔将狩猎的手段教于人类，新鲜美味的肉渐渐经常出现在人类的餐桌上。（但是似乎随着时间流逝，渐渐失去了原有的功效）',Feature=1,}",
  [550001] = "{id=550001,NameZh='厨师帽',Icon='item_550001',Type=800,Quality=4,MaxNum=1,SellPrice=100,AdventureSort=7013,AdventureValue=1,StorageReward={buffid={80011890}},Condition=8,Desc='洁白高耸的厨师帽，是作为一名厨师的证明，所有拥有匠心的厨师都把她作为自己身体不可缺少的部分，比起实用性，其中的含义更加重要。',Feature=1,}",
  [550002] = "{id=550002,NameZh='初心料理书',Icon='item_550002',Type=65,Quality=4,UseMode=2054,MaxNum=1,SellPrice=100,Desc='这本干净并且空无一字的手册，是专门赠送给刚入行的初心之人。梦想着有朝一日，上面密密麻麻记录着心血和经验所换的的纹章。那是名为成长的纪念。书皮由于容易损伤，在成功进入下个修行阶段的时候，别忘了去找资深料理人：【胡雷特】换新哦。',NoSale=1,NoStorage=7,}",
  [550003] = "{id=550003,NameZh='料理书Ⅱ',Icon='item_550004',Type=65,Quality=4,UseMode=2054,MaxNum=1,SellPrice=100,Desc='歪歪扭扭记录着好几页大概持有人本人才能看懂的“秘籍”，是修行初步的见证，名为成长的纪念。书皮由于容易损伤，在成功进入下个修行阶段的时候，别忘了去找资深料理人：【胡雷特】换新哦。',NoSale=1,NoStorage=7,}",
