  [551029] = "{id=551029,NameZh='素之味',Icon='item_551005',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=210,AdventureValue=60,Condition=4,Desc='据说最早是从东方传来，已经有大概200多年的历史了。',Feature=4,}",
  [551030] = "{id=551030,NameZh='妈妈的菜汤',Icon='item_551006',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=211,AdventureValue=60,Condition=4,Desc='好吃的让你回想起小时候在外面撒野，饥肠辘辘滚回家后，母亲端上来的一碗肉汤…那味道，这辈子都无法忘记吧。',Feature=4,}",
  [551031] = "{id=551031,NameZh='小狸猫饼干',Icon='item_551015',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=212,AdventureValue=60,Condition=4,Desc='经典的儿童饼干品牌，因为物美价廉风靡整个大陆。',Feature=4,}",
  [551032] = "{id=551032,NameZh='口水流流肉排',Icon='item_551000',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=302,AdventureValue=80,Condition=4,Desc='呵呵，你看看，光看了下这排肉串就已经口水流成瀑布了。',Feature=4,}",
  [551033] = "{id=551033,NameZh='饿汉肉串',Icon='item_551001',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=303,AdventureValue=80,Condition=4,Desc='有个传说，千里送给皇宫的紧急的信的信使，跑到城外小镇快要累趴了。路边好心的大婶递上了一份这个肉串还有水，这人狼吞虎咽立马用最快的速度跑向了皇宫，使得一场本来即将爆发的战争得到的和平解决。',Feature=4,}",
  [551034] = "{id=551034,NameZh='八音盒肉汤',Icon='item_551002',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=304,AdventureValue=80,Condition=4,Desc='喝着这碗汤的时候，仿佛能听到美妙的音乐在心中回旋升空~~',Feature=4,}",
  [551035] = "{id=551035,NameZh='海风红茶',Icon='item_551017',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=305,AdventureValue=80,Condition=4,Desc='这是海滨城市的人们最喜欢的一种带有大海感觉的红茶，据说使用了大海对面很远的国家运来的红茶作为素材。',Feature=4,}",
  [551036] = "{id=551036,NameZh='海鲜焗饭',Icon='item_551008',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=306,AdventureValue=80,Condition=4,Desc='一种特别制作的充满海洋风味的焗饭，听说在发源地相当受旅行者的欢迎。',Feature=4,}",
  [551037] = "{id=551037,NameZh='依斯鲁得的骄傲',Icon='item_551009',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=307,AdventureValue=80,Condition=4,Desc='作为海港的骄傲，她拥有着别致的味道。',Feature=4,}",
  [551038] = "{id=551038,NameZh='温暖的洋流',Icon='item_551010',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=308,AdventureValue=80,Condition=4,Desc='有古代的贤者声称，大海是一切生命的起源。',Feature=4,}",
  [551039] = "{id=551039,NameZh='香甜芝士蛋糕',Icon='item_551014',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=309,AdventureValue=80,Condition=4,Desc='在高中女生中拥有相当高人气的美味蛋糕。',Feature=4,}",
