  [551080] = "{id=551080,NameZh='吉芬特产肉排',Icon='item_551000',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=701,AdventureValue=160,Condition=4,Desc='象征这吉芬城市的代表性美食，所有品尝过的客人都对其赞不绝口，如今已经开始风靡整个国家。',Feature=4,}",
  [551081] = "{id=551081,NameZh='黄金十字肉串',Icon='item_551001',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=702,AdventureValue=160,Condition=4,Desc='用特殊的刀法在烤制前切割出十字痕迹，让这肉串充满了符号感，男女老少都不能抵抗着美味的吸引。',Feature=4,}",
  [551082] = "{id=551082,NameZh='母亲的怀抱',Icon='item_551002',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=703,AdventureValue=160,Condition=4,Desc='如同在沙漠中的绿洲般的口感，在梦罗克的住民中很有人气。',Feature=4,}",
  [551083] = "{id=551083,NameZh='贵公子的红茶',Icon='item_551017',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=704,AdventureValue=160,Condition=4,Desc='传说中的夜之血族的贵公子，为了拯救人类世界，而背叛自己一族，而后在漫长时光中被人们遗忘，只是偶尔有人在凄冷的月下城堡废墟钟楼窗口看到他依然优雅地喝着红茶。',Feature=4,}",
  [551084] = "{id=551084,NameZh='海德拉',Icon='item_551008',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=705,AdventureValue=160,Condition=4,Desc='神话中的海洋霸者一般的存在，你正在考虑该如何吃下它…',Feature=1,}",
  [551085] = "{id=551085,NameZh='来自海洋的呼唤',Icon='item_551009',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=706,AdventureValue=160,Condition=4,Desc='宛如深海中升起的巨浪，你被这份食物深深吸引了。',Feature=4,}",
  [551086] = "{id=551086,NameZh='艾尔帕兰香鱼汤',Icon='item_551010',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=707,AdventureValue=160,Condition=4,Desc='美丽的水之都市，从很久以前便是卡普拉公司的总部，而以卡普拉餐饮部研发的这款鱼汤得到了皇室的肯定，现在是作为贵族的人气菜品。',Feature=4,}",
  [551087] = "{id=551087,NameZh='商人之城特产蛋糕',Icon='item_551014',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=708,AdventureValue=160,Condition=4,Desc='在遥远的商人之城流行着的特产蛋糕，非常的华丽，一看就是价格极高的东西。',Feature=4,}",
  [551088] = "{id=551088,NameZh='丛林之宝',Icon='item_551004',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=709,AdventureValue=160,Condition=4,Desc='被密林包围的古老都市中的幻之料理之一，据说尝过的人会开心好几天。',Feature=4,}",
  [551089] = "{id=551089,NameZh='斐扬特产蔬菜串',Icon='item_551005',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=710,AdventureValue=160,Condition=4,Desc='被密林包围的古老都市中的幻之料理之一，据说尝过的人会开心好几天。',Feature=4,}",
  [551090] = "{id=551090,NameZh='大小姐的优雅',Icon='item_551017',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=711,AdventureValue=160,Condition=4,Desc='大陆最著名的香水世家：穆拉辛家族的第十四代目社长维特尔·穆拉辛的女儿马蒂尔·穆拉辛小姐在喜欢的红茶，在贵族中被誉为一种身份的象征。',Feature=4,}",
  [551091] = "{id=551091,NameZh='大脚熊森林饼干',Icon='item_551015',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=712,AdventureValue=160,Condition=4,Desc='经典的儿童饼干品牌，只有在节日才限定特供的款式！！！',Feature=4,}",
  [551092] = "{id=551092,NameZh='精制沙漠呼呼肉排',Icon='item_551000',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=801,AdventureValue=180,Condition=4,Desc='梦罗克宫廷古法秘制的肉排，是招待贵宾的不二选择。',Feature=4,}",
  [551093] = "{id=551093,NameZh='巨塔',Icon='item_551003',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=802,AdventureValue=180,Condition=4,Desc='象征着吉芬塔般的料理，庄严而威猛。',Feature=4,}",
  [551094] = "{id=551094,NameZh='博朗迪进行曲',Icon='item_551002',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=803,AdventureValue=180,Condition=4,Desc='拥有如同迷一般的口感，制作方式一度是某公司的最高机密。',Feature=4,}",
  [551095] = "{id=551095,NameZh='夏日之星',Icon='item_551016',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=804,AdventureValue=180,Condition=4,Desc='夏日之神的祝福料理，因为卡普拉服务员出演的某部话剧而知名。',Feature=4,}",
  [551096] = "{id=551096,NameZh='渔夫之魂',Icon='item_551008',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=805,AdventureValue=180,Condition=4,Desc='融入了捕鱼人灵魂的料理，因为制作的时候充满匠心，所以口味极其细腻有层次感。',Feature=4,}",
  [551097] = "{id=551097,NameZh='特鲁毕修斯海鲜串',Icon='item_551009',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=806,AdventureValue=180,Condition=4,Desc='古老的圣典里传诵这一位贫苦的修道士，他游历整个大陆，拯救民众并传诵神的故事，有一天人神被感动了，派自己的女儿下凡人间为修道士做了这份美食。',Feature=4,}",
  [551098] = "{id=551098,NameZh='香颂之歌',Icon='item_551013',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=807,AdventureValue=180,Condition=4,Desc='吃下后如同置身圣堂音乐大厅，整个管弦乐队都在为你一人而演奏。',Feature=4,}",
  [551099] = "{id=551099,NameZh='公主的下午茶',Icon='item_551018',Type=610,MaxNum=99999,SellPrice=100,AdventureSort=808,AdventureValue=180,Condition=4,Desc='皇家公主的御用料理，能得知配方的人少之又少。',Feature=4,}",
