  [700003] = "{id=700003,NameZh='红色开心糖果',Icon='item_12121',Type=40,MaxNum=99999,SellPrice=100,Desc='万圣节最常见的水果味硬糖，被红色包装纸牢牢包住，很受小朋友们的喜爱。 恢复50%的HP',}",
  [700004] = "{id=700004,NameZh='橙色梦幻果汁',Icon='item_700004',Type=40,MaxNum=99999,SellPrice=100,Desc='赋予新年祝福意义的橙色梦幻糖果! 应该会有一个快乐的新年。 （恢复20%的SP）',}",
  [700005] = "{id=700005,NameZh='情谊巧克力',Icon='item_700005',Type=44,Quality=3,MaxNum=99999,AuctionPrice=0,SellPrice=100,Desc='由B格猫星球的恋之神在特定日子到来时才在人间进行出售的拥有独特口味的巧克力，是这个节日赠送亲朋好友的最佳礼物。（效果：可以送给某些NPC。或对其他冒险者使用，使其获得全能力+5，持续5分钟，死亡下线不清除。）',ItemTarget={range=10,type=1},Feature=1,}",
  [700006] = "{id=700006,NameZh='本命巧克力',Icon='item_700006',Type=44,Quality=5,MaxNum=1,SellPrice=100,Desc='充满纯洁美丽爱意的巧克力，只有通过特殊的素材并借由来自B格猫星球的恋之神的祝福才能制作成的特别巧克力，因为是本命，所以只能赠送给最特别的那个人！（选择你心中最心仪的那个人，即使脸红心跳也勇敢地赠送给他（她）吧！效果：对其他冒险者使用，使其获得高级香水效果和每30秒恢复520HP的效果，持续12小时，效果不可叠加，死亡下线不清除。）',ItemTarget={range=10,type=1},Feature=1,}",
  [700007] = "{id=700007,NameZh='B格猫的可可豆',Icon='item_700007',Type=64,Quality=3,MaxNum=99999,AuctionPrice=0,SellPrice=100,Desc='这个整条街道正在处于幸福的节日中，不管你在哪里，和谁在一起，还是孤独一人。来自B格猫的这份祝福材料。听说交给正在普隆德拉大教堂门口的恋之双子星可以亲手制作节日特别的巧克力！',Feature=1,}",
  [700008] = "{id=700008,NameZh='玛丝黛拉种子',Icon='item_700008',Type=70,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=180,Desc='神奇的发着光的种子，据说是一种稀有的果实的种子，传言。女神贝露丹迪在黄昏种下，第二天清晨发现居然已经长成了参天大树，并且结出了无数的饱满的果实，这到底是谁的思念才能创造的奇迹呢？',Feature=1,}",
  [700009] = "{id=700009,NameZh='心有灵犀',Icon='item_700009',Type=62,Quality=5,MaxNum=99999,SellPrice=520,Desc='这个白色的恋之季节，恋神悄悄地降临在这片大陆，如果能将这份来自双方的手心握手心形成的结晶交给她，也许可以经历一场特别的心之旅行。那么两人最终将到达的彼岸将是？',NoStorage=5,Feature=1,}",
  [700010] = "{id=700010,NameZh='白色本命巧克力',Icon='item_700010',Type=44,Quality=4,MaxNum=1,SellPrice=1314,Desc='充满纯洁美丽爱意的纯洁白色巧克力，只有通过特殊的素材并借由来自B格猫星球的恋之神的祝福才能制作成的特别巧克力，因为是本命，所以只能赠送给最特别的那个人！（选择你心中最心仪的那个人，即使脸红心跳也勇敢地赠送给他（她）吧！效果：对其他冒险者使用，12小时内持续获得生命回复效果，效果不可叠加，死亡下线不清除。）',ItemTarget={range=10,type=1},NoStorage=5,Feature=1,}",
  [700011] = "{id=700011,NameZh='纯洁的白纸',Icon='item_700011',Type=70,Quality=2,MaxNum=99999,SellPrice=10,Desc='纯白的纸张，仿佛正在微微闪着温柔的光芒，也许可以用来写些特别的东西。',}",
  [700012] = "{id=700012,NameZh='恋人絮语',Icon='item_700012',Type=75,Quality=5,MaxNum=99999,SellPrice=100,Desc='充满少年少女纯纯的恋之心的寄语纸条。看看今天能送给对方一个怎么样的运势呢？（对其他玩家使用，可以送给其一份写着心意的便签）',ItemTarget={range=10,type=1},Feature=1,}",
