  [700148] = "{id=700148,NameZh='水手服礼券',Icon='item_700148',Type=61,UseMode=4033,MaxNum=99999,SellPrice=100,Desc='学园心动社推出的制服兑换券，使用之后可以打开兑换商店，挑选一个自己最喜欢的配色，加入学园心动社的大家庭吧~',Feature=1,}",
