  [700150] = "{id=700150,NameZh='学园头饰礼券',Icon='item_700150',Type=61,UseMode=4034,MaxNum=99999,SellPrice=100,Desc='学园心动社推出的通用头饰兑换券，零分考卷、眩晕小鸟、圈圈镜、面包加蛋、课堂背包、学霸鸭，总有一款能让你想起学生时代哟~',Feature=1,}",
  [700151] = "{id=700151,NameZh='รางวัลแบบสอบถาม',Icon='item_900009',Type=41,UseMode=10002,MaxNum=99999,SellPrice=100,Desc='ผู้เล่นในประเทศไทยมีรางวัลแบบสอบถาม',}",
  [700153] = "{id=700153,NameZh='恶兽之息',Icon='item_700153',Type=64,MaxNum=99999,SellPrice=100,Desc='愤怒着，咆哮着，这是恶兽的气息，不要被新年和平的假象所蒙骗。恶兽一直在暗处伺机而动，一旦你松懈下来，它便会张开血盆大口向你扑来！\n本品是定制「新年如意卡片」的必要材料，请务必妥善保管。',Feature=1,}",
  [700154] = "{id=700154,NameZh='恶兽之鬃',Icon='item_700154',Type=64,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='传说新年到来之际，那只恶兽就会出现，它的头部似龙，身体却像虎一样雄壮，它所到之处都会发生灾难，人们苦不堪言。直到有位勇士出现，才制服了这头凶兽。勇士拔掉了它的鬃毛，让它不能再作恶，至此之后恶兽才远离了人们的生活。\n本品是定制「新年如意卡片」的必要材料，请务必妥善保管。',Feature=1,}",
  [700155] = "{id=700155,NameZh='贺岁鞭炮',Icon='toy_507',Type=61,MaxNum=99999,AuctionPrice=1,SellPrice=10,Desc='火苗燃起，火花四射！所有的鞭炮都释放开来，你听！噼里啪啦！噼里啪啦！这是新年的声音。\n使用后打开亥神巡礼商店，兑换「亥头巾图纸」 、「年卡片」 以及各类实用道具。',ExistTimeType=2,ExistTime='2020-08-10 05:00:00',}",
  [700156] = "{id=700156,NameZh='祥瑞赐福',Icon='item_700156',Type=61,UseMode=4063,MaxNum=99999,SellPrice=100,Desc='新的一年承载新的喜悦。拂去岁月之尘，接受祥瑞的赐予，让我们一起沐浴在这祝福的光芒之下。\n使用后可选择兑换：「异兽·年魔物蛋」、「异兽·年系列皮肤」、「瑞兽·春兆魔物蛋」、「瑞兽·春兆系列皮肤」。',Feature=1,}",
  [700157] = "{id=700157,NameZh='圣诞祈愿礼盒',Icon='item_700157',Type=30,MaxNum=99999,SellPrice=100,Desc='这是圣诞老公公听到人们的祈愿后，为大家准备的圣诞礼物哦！其中包含着「圣诞星辰」*10个、「七彩贝壳」300个，并有10%概率获得圣诞限定宠物「红鼻子鲁道夫」',}",
  [700158] = "{id=700158,NameZh='圣诞星辰',Icon='item_700158',Type=61,MaxNum=99999,SellPrice=100,Desc='圣诞老人拜托红鼻子鲁道夫准备用于圣诞庆典的圣诞星辰被邪恶老公公抢走啦，如果有好心的冒险者帮忙寻回，鲁道夫会送给你小礼物表示感谢哒！',}",
  [700159] = "{id=700159,NameZh='庆典魔法棒',Icon='item_700159',Type=44,MaxNum=99999,SellPrice=100,Desc='古老的魔女一族非常喜欢在庆典的时候与冒险者开一些善意的玩笑。这个魔棒可以将那些可怜的家伙变成一只什么呢？被变身的玩家还可以获得持续30分钟的双倍经验buff哦~',ItemTarget={range=6,type=1},}",
  [700160] = "{id=700160,NameZh='特制酱油',Icon='item_550530',Type=103,Quality=4,MaxNum=99999,SellPrice=100,Desc='用来烹饪的特制酱油，也是蛋黄哥最喜欢的物品。',ItemTarget={range=6,type=2},Feature=1,}",
  [700162] = "{id=700162,NameZh='黑猫徽章',Icon='item_700162',Type=61,Quality=3,UseMode=4039,MaxNum=99999,SellPrice=100,Desc='感谢您守护了喵星的安定，使用后可以选择兑换：「黑猫·K魔物蛋」、「甜心萌喵」（黑猫·K限定皮肤）、「七彩贝壳」*1800',}",
  [700163] = "{id=700163,NameZh='白犬徽章',Icon='item_700163',Type=61,Quality=3,UseMode=4039,MaxNum=99999,SellPrice=100,Desc='感谢您守护了汪星的安定，使用后可以选择兑换：「白犬·天照魔物蛋」、「秋意暖汪」（白犬·天照限定皮肤）、「七彩贝壳」*1800',}",
  [700167] = "{id=700167,NameZh='泰依琳的心意',Icon='item_700167',Type=61,UseMode=4053,MaxNum=99999,SellPrice=100,Desc='卡普拉公司的泰依琳小姐为热爱冒险的你准备了一份特别的礼物，快去选一件心仪的头饰来打扮自己吧！',}",
  [700168] = "{id=700168,NameZh='暖冬头饰图纸券',Icon='item_700168',Type=61,UseMode=4054,MaxNum=99999,SellPrice=100,Desc='这是一张头饰图纸的兑换券！那么多头饰到底制作哪件好呢……才不做选择题，我全都要~',}",
  [700169] = "{id=700169,NameZh='秘制生肉',Icon='item_550504',Type=103,Quality=4,MaxNum=99999,SellPrice=100,Desc='不知道是什么动物身上的肉，反正白虎最喜欢吃这种生肉了。',ItemTarget={range=6,type=2},Feature=1,}",
  [700170] = "{id=700170,NameZh='吮指原味鸡美食券',Icon='item_700170',Type=4200,MaxNum=1,SellPrice=100,Desc='快别吮吸手指了，我知道原味鸡很美味啦！快拿着美食券去肯德基吧！原味鸡虽好，可不要贪心哦，每单只能用一张~（12月10日-1月6日[10点-22点]期间，使用此券进行点餐后，将为您额外赠送一份「吮指原味鸡」~）',NoStorage=5,}",
  [700171] = "{id=700171,NameZh='极速小旋风24小时体验券',Icon='item_700171',Type=41,MaxNum=99999,SellPrice=100,Desc='征服疾风般的巨鸟，你也可以的！使用后获得一只限时24小时的「极速小旋风」坐骑，时间不可叠加。本券将于1月7日活动结束后被回收。',ExistTimeType=2,ExistTime='2019-01-10 05:00:00',}",
  [700172] = "{id=700172,NameZh='劲爆鸡米花美食券',Icon='item_6081',Type=4200,MaxNum=1,SellPrice=100,Desc='触动你的味蕾，劲爆鸡米花——美食家的挚爱！拿着券去肯德基尽享美味的鸡米花吧！鸡米花虽好，可不要贪心哦，每单只能用一张~（12月10日-1月6日[10点-22点]期间，使用此券进行点餐后，将为您额外赠送一份「劲爆鸡米花·小」~）',NoStorage=5,}",
