  [700182] = "{id=700182,NameZh='波利的庆典',Icon='item_700182',Type=64,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='阳光，果汁和派对——波利们的狂欢节正式开始！这是随着庆典附赠的纪念品，也许有什么特别的用处哦。',}",
  [700183] = "{id=700183,NameZh='波利的阴谋',Icon='item_700183',Type=64,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='造型古怪的纪念品，和快乐的庆典格格不入。即使是在波利王国，阴影也伴随着阳光存在……',}",
  [700184] = "{id=700184,NameZh='波利庆典奖章',Icon='item_700184',Type=61,UseMode=4069,MaxNum=99999,SellPrice=100,Desc='一枚精致的奖章，颁发给在庆典中表现杰出的参与者。拥有国王波利的认证，非常珍贵。',}",
  [700185] = "{id=700185,NameZh='春日乐章',Icon='item_700185',Type=61,UseMode=4071,MaxNum=99999,SellPrice=10,Desc='流动的音符奏响了节日的喜悦，收集一定的乐章可以兑换特别礼物哦！使用后可打开兑换商店，兑换限定卡片和各类实用道具。',ExistTimeType=3,ExistTime='2019-05-15 05:00:00',}",
  [700186] = "{id=700186,NameZh='彩蛋·幸运',Icon='item_700186',Type=61,UseMode=4072,MaxNum=99999,AuctionPrice=1,SellPrice=10,Desc='只有运气最好的人才能拥有的彩蛋~收集到一定数量可以兑换特别礼物哦！\n使用后可打开兑换商店，兑换复活节限定背饰、珍藏玩具和福利券等。',ExistTimeType=3,ExistTime='2019-05-15 05:00:00',}",
  [700187] = "{id=700187,NameZh='新世界战斗药水',Icon='item_700187',Type=41,MaxNum=99999,SellPrice=10,Desc='平行世界里由迷之科技研制而成的药水，喝下它就能获得意想不到的力量。\n使用后1小时内，野外击杀魔物获得的Base经验和Job经验翻倍！（死亡及非战斗状态下消耗Buff时长，离线状态不消耗Buff时长）',}",
  [710001] = "{id=710001,NameZh='银河的结晶',Icon='item_710001',Type=62,MaxNum=99999,SellPrice=10,Desc='“没有尽头的苍穹，这片星海潜藏着千亿颗星星，闭上双眼就能看见，真实，就在这里。”（人们对星星祈求从而得到的证明，虽然如同幻想一般，但确实可以捧在手心中。如果交给某个女神的话，说不定能换到不错的东西。）',NoStorage=5,}",
