  [710027] = "{id=710027,NameZh='来自星星的邀请',Icon='item_710027',Type=41,MaxNum=99999,SellPrice=8000,Desc='星星的力量愈加强大了，已经不需要再使用「来自星星的邀请」，就可以进行每天两次的占卜哦~所以， 现在这个道具唯一的作用，就是卖给商店，回收一些Zeny啦~',NoStorage=5,}",
  [710028] = "{id=710028,NameZh='来自公会的馈赠',Icon='item_710028',Type=30,MaxNum=99999,SellPrice=5,Desc='就是团结的力量！（使用后获得公会贡献：25点）',NoStorage=5,Feature=1,}",
  [710029] = "{id=710029,NameZh='美发体验券·自由',Icon='item_710029',Type=30,MaxNum=99999,SellPrice=20000,Desc='热爱美丽的你这下可以更加自由和随心所欲地去改变自己了！（听说理发店已经不再接受体验券，不妨使用或出售掉吧，可以获得20000zeny哦~）',NoStorage=5,}",
  [710030] = "{id=710030,NameZh='染发剂·极彩',Icon='item_710030',Type=70,MaxNum=99999,SellPrice=10000,Desc='本来是在更换发色时，用来免收取染料一次的道具；但是现在染发已经不需要染料了哦，可以卖到商店里换成小钱钱~',NoStorage=5,}",
