  [760000] = "{id=760000,NameZh='闪烁满天星',Icon='allstar',Type=93,MaxNum=99999,SellPrice=100,Desc='被阳光镀上温柔光泽的雪白满天星，单是看着就能感到幸福。是人见人爱的美丽花朵，同时也是绝不会出错的礼物。',NoSale=1,}",
  [760060] = "{id=760060,NameZh='伊登的金苹果',Icon='ivy_apple',Type=93,MaxNum=99999,SellPrice=100,Desc='传说中可以让青春永驻的金苹果，没有谁能抵挡住它的诱惑，绝对是送给女神希芙的不二之选！',NoSale=1,}",
  [760070] = "{id=760070,NameZh='黄昏徽记',Icon='item_760070',Type=93,MaxNum=99999,SellPrice=100,Desc='铭刻了落日瞬间的古老徽记，只属于荒境那段最遥远的时光。',NoSale=1,}",
  [760080] = "{id=760080,NameZh='锦衣卫的勋章',Icon='item_760080',Type=93,MaxNum=99999,SellPrice=100,Desc='影枫司锦衣卫的勋章，擅长制作银器的匠人卡罗拉用银鱼湖的黑珍珠和荒境的碎银打造而成。黑珍珠的光辉和白银的光芒交辉，象征了影枫司的庄严与神圣。',NoSale=1,}",
  [760090] = "{id=760090,NameZh='2.0声望道具',Icon='item_760090',Type=93,MaxNum=99999,SellPrice=100,}",
  [800101] = "{id=800101,NameZh='限定特典初心号',Icon='item_800101',Type=47,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,AdventureSort=1,AdventureValue=100,Condition=64,Desc='“一切都以此为起点。孩子们的梦想也好、大人们的梦想也好、还有我们要守护的爱！”著名的卡普拉公司为答谢长久以来支持本社的冒险者的厚爱，特别推出以月刊形式发售的特别小卡片，拿在手里仿佛能感受到充满神奇的魔力，实用和珍藏价值极高。每次使用均可获得限定头饰[itemid]45505[/itemid]x1。',Feature=1,}",
  [800102] = "{id=800102,NameZh='2017.2月限定特典',Icon='item_800102',Type=47,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,AdventureSort=2,AdventureValue=100,Condition=64,Desc='“幸福的日子，沐浴在由花朵组成的春之圆舞曲中的男男女女，如今也互相支持鼓励着一起来守护这份永恒的爱！”著名的卡普拉公司为答谢长久以来支持本社的冒险者的厚爱，特别推出以月刊形式发售的特别小卡片，拿在手里仿佛能感受到充满神奇的魔力，实用和珍藏价值极高。每次使用均可获得限定头饰[itemid]45501[/itemid]x1。',Feature=1,}",
  [800103] = "{id=800103,NameZh='2017.3月限定特典',Icon='item_800103',Type=47,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,AdventureSort=3,AdventureValue=100,Condition=64,Desc='“这可是个值得纪念的节日！经历了如此多的风风雨雨，终于到了这个乐园正式为各位冒险者们敞开大门的这一刻！欢迎来到米德加尔特大陆！这片幻想的世界因为有你们变得充满生命力和希望。”著名的卡普拉公司为答谢长久以来支持本社的冒险者的厚爱，特别推出以月刊形式发售的特别小卡片，拿在手里仿佛能感受到充满神奇的魔力，实用和珍藏价值极高。每次使用均可获得限定头饰[itemid]45503[/itemid]x1。',Feature=1,}",
  [800104] = "{id=800104,NameZh='2017.4月限定特典',Icon='item_800104',Type=47,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,AdventureSort=4,AdventureValue=100,Condition=64,Desc='“据传说只有聪明的人才能听懂平时吵吵闹闹的哥布灵在说些什么。嗯？你说也你听懂了？”著名的卡普拉公司为答谢长久以来支持本社的冒险者的厚爱，特别推出以月刊形式发售的特别小卡片，拿在手里仿佛能感受到充满神奇的魔力，实用和珍藏价值极高。每次使用均可获得限定头饰[itemid]45504[/itemid]x1。',Feature=1,}",
  [800105] = "{id=800105,NameZh='2017.5月限定特典',Icon='item_800105',Type=47,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,AdventureSort=5,AdventureValue=100,Condition=64,Desc='“翻过充满龙族魔物的密林，旅行的第六天，我们来到了传说中的古城·克雷斯特汉姆。夜空中围绕着邪恶不祥的气息。但是我们不会退缩，同伴的友情和牵绊是我们力量的源泉，手中讨伐魔物的斧锤已经握紧。”著名的卡普拉公司为答谢长久以来支持本社的冒险者的厚爱，特别推出以月刊形式发售的特别小卡片，拿在手里仿佛能感受到充满神奇的魔力，实用和珍藏价值极高。每次使用均可获得限定头饰[itemid]45500[/itemid]x1。',Feature=1,}",
  [800106] = "{id=800106,NameZh='2017.6月限定特典',Icon='item_800106',Type=47,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,AdventureSort=6,AdventureValue=100,Condition=64,Desc='“是幻想吗，是空中楼阁吗。在黎明前，这场梦，蝴蝶之梦；孩子们至今尚未忘记伸出手向着天空的彼端。那里有被许愿的金色大地和梦想中的幻之世界【乐园】。”著名的卡普拉公司为答谢长久以来支持本社的冒险者的厚爱，特别推出以月刊形式发售的特别小卡片，拿在手里仿佛能感受到充满神奇的魔力，实用和珍藏价值极高。每次使用均可获得限定头饰[itemid]45502[/itemid]x1。',Feature=1,}",
  [800107] = "{id=800107,NameZh='2017.7月限定特典',Icon='item_800107',Type=47,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,AdventureSort=7,AdventureValue=100,Condition=64,Desc='“带着梦想与信念负重而行的心，是我一人所无法守护的，所以啊，请跟我一起战斗吧，亲爱的同伴。”著名的卡普拉公司为答谢长久以来支持本社的冒险者的厚爱，特别推出以月刊形式发售的特别小卡片，拿在手里仿佛能感受到充满神奇的魔力，实用和珍藏价值极高。每次使用均可获得限定头饰[itemid]45506[/itemid]x1。',Feature=1,}",
  [800108] = "{id=800108,NameZh='2017.8月限定特典',Icon='item_800108',Type=47,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,AdventureSort=8,AdventureValue=100,Condition=64,Desc='“盛夏！沙滩！比基尼！卡普拉！杀必死！哦！这里！就！是！天~~~~~~~~~~~~~~~~~~~堂！！！”著名的卡普拉公司为答谢长久以来支持本社的冒险者的厚爱，特别推出以月刊形式发售的特别小卡片，拿在手里仿佛能感受到充满神奇的魔力，实用和珍藏价值极高。每次使用均可获得限定头饰[itemid]45509[/itemid]x1。',Feature=1,}",
  [800109] = "{id=800109,NameZh='2017.9月限定特典',Icon='item_800109',Type=47,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,AdventureSort=9,AdventureValue=100,Condition=64,Desc='“值得纪念的一天，我们终于有宠物可以养了！”著名的卡普拉公司为答谢长久以来支持本社的冒险者的厚爱，特别推出以月刊形式发售的特别小卡片，拿在手里仿佛能感受到充满神奇的魔力，实用和珍藏价值极高。每次使用均可获得限定头饰[itemid]48582[/itemid]x1。',Feature=1,}",
  [800110] = "{id=800110,NameZh='2017.10月限定特典',Icon='item_800110',Type=47,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,AdventureSort=10,AdventureValue=100,Condition=64,Desc='“整个国家都在庆祝这个节日，真是个让人期待的黄金之月。”著名的卡普拉公司为答谢长久以来支持本社的冒险者的厚爱，特别推出以月刊形式发售的特别小卡片，拿在手里仿佛能感受到充满神奇的魔力，实用和珍藏价值极高。每次使用均可获得限定头饰[itemid]45510[/itemid]x1。',Feature=1,}",
  [800111] = "{id=800111,NameZh='2017.11月限定特典',Icon='item_800111',Type=47,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,AdventureSort=11,AdventureValue=100,Condition=64,Desc='“直到天亮为止，这场华丽优雅恐怖惊悚的派对才会结束呢。”著名的卡普拉公司为答谢长久以来支持本社的冒险者的厚爱，特别推出以月刊形式发售的特别小卡片，拿在手里仿佛能感受到充满神奇的魔力，实用和珍藏价值极高。每次使用均可获得限定头饰[itemid]45287[/itemid]x1。',Feature=1,}",
  [800112] = "{id=800112,NameZh='2017.12月限定特典',Icon='item_800112',Type=47,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,AdventureSort=12,AdventureValue=100,Condition=64,Desc='“终于到了这天~孩子们兴奋地期待着礼物，从被子里探头看着窗外，看着壁炉，看着装礼物用的袜子，兴奋到连自己不小心就睡着了都没发现。”著名的卡普拉公司为答谢长久以来支持本社的冒险者的厚爱，特别推出以月刊形式发售的特别小卡片，拿在手里仿佛能感受到充满神奇的魔力，实用和珍藏价值极高。每次使用均可获得限定头饰[itemid]45519[/itemid]x1。',Feature=1,}",
  [800201] = "{id=800201,NameZh='2018.1月限定特典',Icon='item_800201',Type=47,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,AdventureSort=13,AdventureValue=100,Condition=64,Desc='“1th Anniversary纪念！我们就用一场轰轰烈烈的GVG来让这次宴会走向高潮吧！”著名的卡普拉公司为答谢长久以来支持本社的冒险者的厚爱，特别推出以月刊形式发售的特别小卡片，拿在手里仿佛能感受到充满神奇的魔力，实用和珍藏价值极高。每次使用均可获得限定头饰[itemid]47050[/itemid]x1。',Feature=1,}",
  [800202] = "{id=800202,NameZh='2018.2月限定特典',Icon='item_800202',Type=47,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,AdventureSort=14,AdventureValue=100,Condition=64,Desc='“幸福的日子再临，去年许下的按个心愿是否有实现呢？那最纯洁美丽的心意是否有传达到呢？呐~粉红色雪花飘落的街道上的你，依然幸福着吗？”著名的卡普拉公司为答谢长久以来支持本社的冒险者的厚爱，特别推出以月刊形式发售的特别小卡片，拿在手里仿佛能感受到充满神奇的魔力，实用和珍藏价值极高。每次使用均可获得限定头饰[itemid]45521[/itemid]x1。',Feature=1,}",
