  [810001] = "{id=810001,NameZh='歉意&感恩特典',Icon='item_810001',Type=47,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=10000,AdventureValue=1,Condition=64,Desc='为了感谢所有在“不限号测试”期间给予我们帮助、鼓励、宽容的冒险者们，我们准备了一份特别的「限定特典」给大家，这将是在常规自然月限定特典以外的一个独立纪念版，只有你们才会获得，感恩！',Feature=1,}",
  [810002] = "{id=810002,NameZh='招行特典',Icon='item_810002',Type=47,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=10001,AdventureValue=1,Condition=64,Desc='在招行信用卡发卡15周年之际，正值《仙境传说RO》手游半年庆典，二者跨界合作不仅意义非凡，也为玩家带来了超值专享福利。',Feature=1,}",
