  [810005] = "{id=810005,NameZh='冒险之旅特典',Icon='item_810005',Type=47,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=10004,AdventureValue=1,Condition=64,Desc='“钟声响起，又到了新的一年啦！不知今年的愿望清单写了什么内容呢？让我们去共同实现吧！”著名的卡普拉公司为答谢长久以来支持本社的冒险者的厚爱，特别推出以月刊形式发售的特别小卡片，拿在手里仿佛能感受到充满神奇的魔力，实用和珍藏价值极高，忘了说这是半月刊哦~',Feature=1,}",
