  [810007] = "{id=810007,NameZh='EVA联动特典',Icon='item_810007',Type=47,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=10006,AdventureValue=1,Condition=64,Desc='米德加尔特大陆英勇的冒险者们，这一次将驾驶EVA，与使徒展开最终决战！',Feature=1,Delete=810007}",
  [810008] = "{id=810008,NameZh='台湾周年庆特典',Icon='item_810008',Type=47,Quality=4,MaxNum=99999,SellPrice=100,AdventureSort=10007,AdventureValue=1,Condition=64,Desc='一周年了，还有哪件衣服没有入手？水水们快穿上最自豪的时装上街shopping吧！\n-设计者：西太',Feature=1,Delete=810008}",
