  [900081] = "{id=900081,NameZh='年年有鱼',Icon='item_900081',Type=103,Quality=4,MaxNum=99999,SellPrice=100,Desc='此鱼是生长于极寒之地湖泊中的鱼类，肉质鲜美不可多得，是大陆上的美食爱好者可望不可求的食材，宠物瑞兽·春兆最喜爱的食物。\n（据说小瑞兽和小年兽关系特别好，小瑞兽经常跑去吃小年兽的鱼，一边吃还一边叫着：“年年有鱼！”于是这个词就这么流传了下来。）',ItemTarget={range=6,type=2},Feature=1,}",
  [900082] = "{id=900082,NameZh='鲜嫩树芽',Icon='item_900082',Type=103,MaxNum=99999,SellPrice=100,Desc='鲜嫩的树芽在终年白雪皑皑的姜饼城可是非常少见的，宠物红鼻子鲁道夫最喜欢的食物',ItemTarget={range=6,type=2},Feature=1,}",
  [900083] = "{id=900083,NameZh='鲣鱼罐头',Icon='item_900083',Type=103,MaxNum=99999,SellPrice=100,Desc='以鲣鱼为原料的速食罐头，是宠物PENPEN最喜欢的物品。',Feature=1,}",
  [900084] = "{id=900084,NameZh='禁忌果实',Icon='item_900084',Type=103,MaxNum=99999,SellPrice=100,Desc='禁忌的果实，要是吃下去的话，总觉得会发生什么不得了的大事。是宠物第四使徒最喜欢的物品。',Feature=1,}",
  [900085] = "{id=900085,NameZh='东方榛果',Icon='item_900085',Type=103,MaxNum=99999,SellPrice=100,Desc='玛库朵松鼠的饭量其实很小，但它们却喜欢囤积大量的榛果以获得满足感，这种习惯也被称为“松鼠症状”。',Feature=1,}",
  [900086] = "{id=900086,NameZh='光辉晶石',Icon='item_900086',Type=103,MaxNum=99999,SellPrice=100,Desc='散发着夺目光芒的水晶，是魔物迷你狮鹫最喜爱的物品。',Feature=1,}",
