  [901410] = "{id=901410,NameZh='星灵女巫',Icon='item_901410',Type=41,Quality=3,MaxNum=99999,SellPrice=100,Desc='由于扫帚飞行技术不佳而在夜间偷偷练习的见习女巫，由于个头太小，常常被人误认为流星。使用后解锁小魔女的星灵女巫装扮。',}",
  [901420] = "{id=901420,NameZh='兽人顽童',Icon='item_901420',Type=41,Quality=3,MaxNum=99999,SellPrice=100,Desc='兽人婴儿迫不及待的想要长大，为部落战斗。不过精力无处发泄四处捣乱的他令长辈们非常头疼。使用后解锁兽人婴儿的顽童装扮。',}",
  [901430] = "{id=901430,NameZh='虹光精灵魔物蛋',Icon='item_901430',Type=101,Quality=3,MaxNum=1,SellPrice=100,Desc='一颗神奇的魔物蛋，里面可以孵化出魔物虹光精灵。',}",
  [901440] = "{id=901440,NameZh='虹光波利魔物蛋',Icon='item_901440',Type=101,Quality=3,MaxNum=1,SellPrice=100,Desc='一颗神奇的魔物蛋，里面可以孵化出魔物虹光波利。',}",
  [901442] = "{id=901442,NameZh='兽人婴儿宠物皮肤',Icon='item_901442',Type=41,Quality=3,MaxNum=99999,SellPrice=100,Desc='卡普拉特供，使用后可以为兽人婴儿更换一个新造型。',Feature=1,}",
  [901443] = "{id=901443,NameZh='嗜糖团团长',Icon='item_901443',Type=41,Quality=3,MaxNum=99999,SellPrice=100,Desc='弑神者虽然嘴上说着一点都不喜欢游乐场这种“幼稚”的地方，但实际上早就偷偷把自己打扮成草莓奶油夹心饼干的样子，期待着和主人一起去玩耍，口嫌体正直实锤了！',Feature=1,}",
  [901444] = "{id=901444,NameZh='盲盲绷带熊',Icon='item_901444',Type=41,Quality=3,MaxNum=99999,SellPrice=100,Desc='卡普拉特供，使用后可以为俄赛里斯更换一个新造型。绷带缠绕下的俄赛里斯，内心对“可爱”一词的理解也是有些不太一样呢。',Feature=1,}",
  [901445] = "{id=901445,NameZh='爱丽丝女仆·皇家',Icon='item_901445',Type=41,Quality=3,MaxNum=99999,SellPrice=100,Desc='卡普拉特供，使用后为宠物爱丽丝女仆解锁皇家女仆造型。',}",
  [901446] = "{id=901446,NameZh='玩具熊·皇家',Icon='item_901446',Type=41,Quality=3,MaxNum=99999,SellPrice=100,Desc='卡普拉特供，使用后为宠物玩具熊解锁皇家执事造型。',}",
  [901447] = "{id=901447,NameZh='山地雪兽',Icon='item_901447',Type=41,Quality=3,MaxNum=99999,SellPrice=100,Desc='卡普拉特供，使用后可以为雪兽更换一个新造型。生活在低纬山林地区的雪兽，为了适应无积雪的环境，长出了棕色的长毛。',}",
  [901448] = "{id=901448,NameZh='狸猫学徒',Icon='item_901448',Type=41,Quality=3,MaxNum=99999,SellPrice=100,Desc='卡普拉特供，使用后可以为狸猫更换一个新造型。屡屡被冒险者暴揍的狸猫也想拜入流星林门下，有朝一日学艺归来向冒险者复仇！',}",
  [901449] = "{id=901449,NameZh='流星灵鸾',Icon='item_901449',Type=41,Quality=3,MaxNum=99999,SellPrice=100,Desc='卡普拉特供，使用后可以为鸟人哈比更换一个新造型。受到坠星湖下神秘力量的影响，鸟人哈比绽放出流星般的光辉。',}",
  [901450] = "{id=901450,NameZh='\t田园土拨鼠',Icon='item_901450',Type=41,Quality=3,MaxNum=99999,SellPrice=100,Desc='卡普拉特供，使用后可以为土拨鼠更换一个新造型。乡下的土拨鼠终于决定来到大城市，身上绑着的苹果核与鱼骨道明了这一路走来的艰辛。',}",
  [902000] = "{id=902000,NameZh='魔法莴苣',Icon='item_902000',Type=103,MaxNum=99999,SellPrice=100,Desc='爽脆可口的魔法莴苣，闪烁着奇怪的绿色光芒，是魔物海獭最喜爱的食物。',}",
  [902001] = "{id=902001,NameZh='鲜嫩竹子',Icon='item_902001',Type=103,MaxNum=99999,SellPrice=100,Desc='翠绿的新竹，散发着泥土的气息和诱人的清新香味。是魔物剑侍小熊猫最喜爱的食物。',}",
  [902002] = "{id=902002,NameZh='美味竹笋',Icon='item_902002',Type=103,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='鲜嫩多汁的竹笋，是魔物熊猫波利最喜爱的食物。',ItemTarget={range=6,type=2},}",
  [902003] = "{id=902003,NameZh='鲜美活虾',Icon='item_902003',Type=103,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='活蹦乱跳的小虾，是魔物灯笼鱼人最喜爱的食物。',ItemTarget={range=6,type=2},}",
  [902004] = "{id=902004,NameZh='三文鱼罐头',Icon='item_902004',Type=103,MaxNum=99999,SellPrice=100,Desc='以新鲜的三文鱼为原料加工制成的猫咪罐头，是魔物喵咪骑士、喵咪女爵和喵咪男爵最喜爱的食物。',}",
  [902005] = "{id=902005,NameZh='新鲜奶酪',Icon='item_902005',Type=103,MaxNum=99999,SellPrice=100,Desc='质感柔软湿润的新鲜奶酪，散发出浓浓的奶香，是魔物奶酪小仓鼠最喜爱的食物。',}",
  [902006] = "{id=902006,NameZh='樱魅折扇',Icon='item_902006',Type=103,MaxNum=99999,SellPrice=100,Desc='粉色扇面配上纯白的樱花花纹，似乎蕴藏着对小白猫的美好祝福。',}",
  [902007] = "{id=902007,NameZh='夕烧团子',Icon='item_902007',Type=103,MaxNum=99999,SellPrice=100,Desc='凝聚火焰能量的秘制饭团，看似普通其实有着不可思议的魔力。是烈焰灵童最喜欢的食物。',}",
  [902008] = "{id=902008,NameZh='御吉金铃',Icon='item_902008',Type=103,MaxNum=99999,SellPrice=100,Desc='金灿灿的铃铛，随着金铃福宝身体的摆动，发出清脆动听的声音。隐隐约约感觉得到一种神奇的守护之力。',}",
  [902009] = "{id=902009,NameZh='无花仙人掌',Icon='item_902009',Type=103,MaxNum=99999,SellPrice=100,Desc='尖刺下蕴含着丰富水分的仙人掌是运财骆驼最爱的食物。注意，开了花的仙人掌它们是绝对不吃的。',}",
  [902010] = "{id=902010,NameZh='软金元宝',Icon='item_902010',Type=103,MaxNum=99999,SellPrice=100,Desc='散金猫鼬用来抛撒钱币的来源，也是它们最爱的食物。软金才容易消化哦。',}",
  [902011] = "{id=902011,NameZh='彩虹棒棒糖',Icon='item_902023',Type=103,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='玩偶魔妖喜欢的彩虹棒棒糖，送给它可能会有很好的效果哦~',ItemTarget={range=6,type=2},}",
  [902012] = "{id=902012,NameZh='香草布丁',Icon='item_902012',Type=103,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='香草口味的布丁，是米米怪最喜爱的食物。',ItemTarget={range=6,type=2},}",
