  [902027] = "{id=902027,NameZh='冷藏小鱼干',Icon='item_902027',Type=103,MaxNum=99999,SellPrice=100,Desc='Miao先森在泡咖啡时会加入冷藏小鱼干。这是从多兰顾客那儿学到的咖啡伴侣秘方，可以让咖啡品起来更清爽。',}",
  [902028] = "{id=902028,NameZh='节庆爆竹',Icon='item_902028',Type=103,MaxNum=99999,SellPrice=100,Desc='法纳族为了庆祝节日制作的爆竹，爆炸的声音对幼年年兽来说很具有吸引力。',TFValidDate='2021-01-25 05:00:00',ValidDate='2021-02-01 05:00:00',}",
  [902029] = "{id=902029,NameZh='冥水杓',Icon='item_902029',Type=103,MaxNum=99999,SellPrice=100,Desc='冥河水怪极爱泡澡，对它们来说，能浇水的大勺子是最趁手的洗浴道具。',}",
  [902030] = "{id=902030,NameZh='幽灵冰激凌',Icon='item_902030',Type=103,MaxNum=99999,SellPrice=100,Desc='完全符合亡者口味的冰激凌。请生者不要轻易尝试，可能会吐出来。',}",
  [902032] = "{id=902032,NameZh='迷你桶装啤酒',Icon='item_902032',Type=103,Quality=4,MaxNum=99999,SellPrice=100,Desc='清凉解渴的啤酒。注意，如果偷喝了它，啤酒企鹅可是要揍你的。暂时无法使用',}",
  [902033] = "{id=902033,NameZh='甜梦粉尾鱼',Icon='item_902033',Type=103,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='深海鱼类是海豹宝宝的可口食物，注意，冰冻鱼可是不行的。',ItemTarget={range=6,type=2},}",
  [902034] = "{id=902034,NameZh='助行手杖',Icon='item_902034',Type=103,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='走路对于奈吉鸟来说是一件辛苦事。所以放下一根拐杖，你将有可能收到一只……',ItemTarget={range=6,type=2},}",
  [902035] = "{id=902035,NameZh='爱米粒',Icon='item_902035',Type=103,Quality=3,MaxNum=99999,SellPrice=100,Desc='心里都是你，连小米都是爱你的形状！外形奇特的谷物，是爱心小雀最爱的食物。',}",
  [902036] = "{id=902036,NameZh='永生之骨',Icon='item_902036',Type=103,MaxNum=99999,SellPrice=100,Desc='蕴含着强大魔力的骨制祭品，传说拥有着让死者复生的能力，深受古老守卫们的喜爱。',}",
  [902037] = "{id=902037,NameZh='猩红汁液',Icon='item_902037',Type=103,MaxNum=99999,SellPrice=100,Desc='多么血腥的名字也无法掩盖这是一杯葡萄汁的事实。是无牙男爵最喜欢的鲜红液体。',}",
  [902038] = "{id=902038,NameZh='怪奇蛋',Icon='item_902038',Type=103,MaxNum=99999,SellPrice=100,Desc='表面有着可爱图案的蛋，不知来自何种生物。是地龙骑士最喜欢的食物。',}",
  [902039] = "{id=902039,NameZh='深海鲑鱼',Icon='item_902039',Type=103,MaxNum=99999,SellPrice=100,Desc='出产自天水之国附近海域的鱼类，富含让毛发顺滑油亮的物质，是赤焰兽最喜欢的食物。',}",
  [902040] = "{id=902040,NameZh='宠物牛奶',Icon='item_902040',Type=103,MaxNum=99999,SellPrice=100,Desc='皇家特供版，只需一滴就可以唤醒沉睡的皇家猎犬',}",
  [902041] = "{id=902041,NameZh='鲜果圣代',Icon='item_902041',Type=103,MaxNum=99999,SellPrice=100,Desc='在奶油中加入大料新鲜果汁而制成的圣代，虽然没有胡萝卜，但意外符合仙灵兔女王的口味。',}",
  [902042] = "{id=902042,NameZh='糖渍甜甜圈',Icon='item_902042',Type=103,MaxNum=99999,SellPrice=100,Desc='旅行小熊猫的必备口粮，夸张的糖分不止可以提供能量，还能带来振奋人心的满足感。',}",
  [902043] = "{id=902043,NameZh='妖火灵玉',Icon='item_902043',Type=103,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='天水之国出产的奇艺矿石，据说能强化狐族的力量，是精灵狐最喜欢的食物。',ItemTarget={range=6,type=2},}",
  [902044] = "{id=902044,NameZh='荆棘之心',Icon='item_902044',Type=103,MaxNum=99999,SellPrice=100,Desc='被荆棘包裹的神奇宝石，是爆钻伞蜥最喜欢的食物。',ItemTarget={range=6,type=2},}",
  [902045] = "{id=902045,NameZh='脆筒冰淇淋球',Icon='item_902045',Type=103,MaxNum=99999,SellPrice=100,Desc='由新鲜奶油和果酱制成的冰淇淋球，搭配锥形的脆筒，是幼独角兽最爱的零食。',}",
  [902047] = "{id=902047,NameZh='黄金鲷鱼烧',Icon='item_902047',Type=103,MaxNum=99999,SellPrice=100,Desc='将金黄的外皮做出小鱼的形状后烤至酥软，配上各式馅料，一口下去，绝对疗愈身心。是最能让伊露维琪感到快乐的食物。',}",
  [902048] = "{id=902048,NameZh='彩虹糖奶酥',Icon='item_902048',Type=103,MaxNum=99999,SellPrice=100,Desc='将黄油软化后加入糖粉香草粉，烤制出香气四溢的金黄饼干底，撒上了梦幻的彩虹糖霜，是小小乔克最喜欢的食物。',}",
  [902049] = "{id=902049,NameZh='肉骨头',Icon='item_13321',Type=103,MaxNum=99999,SellPrice=100,Desc='极为干净的肉骨头，真的还有啃的价值吗……？',}",
  [902050] = "{id=902050,NameZh='鲜榨苹果汁',Icon='77',Type=103,MaxNum=99999,SellPrice=100,Desc='鲜榨的苹果汁，酸酸甜甜的，是宠物圣天使波利最喜爱的物品。',Feature=1,}",
  [902051] = "{id=902051,NameZh='胡萝卜馅饼',Icon='item_902051',Type=103,MaxNum=99999,SellPrice=100,Desc='流星林厨娘大婶的拿手菜，用胡萝卜作为馅料的面点，是兔拉拉最喜欢的食物。',}",
  [902052] = "{id=902052,NameZh='巨大肉骨头',Icon='item_902052',Type=103,MaxNum=99999,SellPrice=100,Desc='超大规格的肉骨头，是幽狼、追夜、逐星最喜欢的食物。',}",
  [902053] = "{id=902053,NameZh='午餐食罐头',Icon='item_902053',Type=103,MaxNum=99999,SellPrice=100,Desc='原材料全是肉的罐头，是大犬座最喜欢的食物。',}",
  [902054] = "{id=902054,NameZh='原味烤肉',Icon='item_902054',Type=103,MaxNum=99999,SellPrice=100,Desc='风息魔灵对烤肉情有独钟，把肉放在烧热的石头上，听见呲啦一声，直到边缘变得焦脆，这时候的烤肉才是最好吃的！',}",
  [902055] = "{id=902055,NameZh='雷霆树莓',Icon='item_902055',Type=103,MaxNum=99999,SellPrice=100,Desc='蕴含着雷电之力的神奇果实，品尝后有一种流窜在舌尖的酥麻感，电量大小全凭运气，被普隆德拉王国标注不适合寻常人食用，但每年都有人尝试，浑然不顾这是库尔奇的专属美食。',}",
  [902056] = "{id=902056,NameZh='水晶蜜果',Icon='item_902056',Type=103,MaxNum=99999,SellPrice=100,Desc='生长在矿藏丰富的地方，寻常宠物难以消化，却是水晶波比的最爱，一口一个嘎嘣脆！',}",
  [902057] = "{id=902057,NameZh='黄金麦粒',Icon='item_902057',Type=103,MaxNum=99999,SellPrice=100,Desc='颗粒饱满的黄金麦粒，蕴含丰富营养，是酷奇拉力大无穷的源动力。',}",
  [902058] = "{id=902058,NameZh='青青蜜草',Icon='item_902058',Type=103,MaxNum=99999,SellPrice=100,Desc='清脆爽口，有蜂蜜的甘甜味道，是狐小羊最喜欢的食物，根本停不下来。',}",
  [902059] = "{id=902059,NameZh='果树草',Icon='item_902059',Type=103,MaxNum=99999,SellPrice=100,Desc='有水果甜甜的味道，是超越胡萝卜被可可兔喜欢的食物，只可惜不易储存。',}",
  [902060] = "{id=902060,NameZh='环礁红虾',Icon='item_902060',Type=103,MaxNum=99999,SellPrice=100,Desc='藏在礁石缝隙的虾，营养丰富有弹性，是愤怒梦想家最喜欢的食物，适合各种烹饪方式，但新鲜的才是最好吃的！',}",
  [902063] = "{id=902063,NameZh='搁浅小鱼干',Icon='item_902063',Type=103,MaxNum=99999,SellPrice=100,Desc='抬头看向海上的世界却被巨浪卷向沙滩，阳光和我是最美好的搭配，一些油润一丝干香。',}",
  [902064] = "{id=902064,NameZh='火山度假虾',Icon='item_902064',Type=103,MaxNum=99999,SellPrice=100,Desc='那股无畏的精神，让它散发着焦香的味道，在深海无名不如在火山爆发！再撒点椒盐。',}",
  [902070] = "{id=902070,NameZh='鸭梨',Icon='item_902071',Type=103,MaxNum=99999,SellPrice=100,Desc='有压力吗？来颗鸭梨吧！是大眼泡泡鸭最喜欢的食物。',}",
  [902080] = "{id=902080,NameZh='成堆金币',Icon='item_902080',Type=103,MaxNum=99999,SellPrice=100,Desc='堆成小山的金币！是狂暴邪恶箱最喜欢的食物。',}",
  [913000] = "{id=913000,NameZh='卓越值',Icon='item_913000',Type=4300,MaxNum=99999,SellPrice=100,Desc='参与公会战，完成公会战目标获得的卓越值。卓越值达到一定进度时，可以获得卓越值进度奖励',}",
  [913001] = "{id=913001,NameZh='星座祝福石·白',Icon='item_913001',Type=62,MaxNum=99999,SellPrice=100,Desc='在【炽焰炉】中，可使用星座祝福石·白1:1抵扣白色材料（每个星座祝福石·白可替代1个白色材料）',ExistTimeType=10,}",
