  [3000026] = "{id=3000026,NameZh='小夜曲',Icon='item_3000026',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15155,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='取一抹最甜美的黑色，为你编织出一首最梦幻的小夜曲。',Feature=1,TFValidDate='2019-03-11 05:00:00',ValidDate='2019-03-14 05:00:00',LoadShowSize=3,}",
  [3000027] = "{id=3000027,NameZh='星尾蝶·煌',Icon='item_3000027',Type=810,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012660}},Desc='你是山风，你是烈火，你是那只在舞台上飞舞的星尾蝶。',Feature=1,TFValidDate='2019-03-11 05:00:00',ValidDate='2019-03-14 05:00:00',LoadShowSize=2,LoadShowPose={0,0.7,0},MainColor='da2153FF',}",
  [3000028] = "{id=3000028,NameZh='星尾蝶·谣',Icon='item_3000027',Type=810,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012660}},Desc='你是白云，你是童谣，你是那只在舞台上飞舞的星尾蝶。',Feature=1,TFValidDate='2019-03-11 05:00:00',ValidDate='2019-03-14 05:00:00',MainColor='3772f0FF',}",
  [3000029] = "{id=3000029,NameZh='星尾蝶·弦',Icon='item_3000027',Type=810,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012660}},Desc='你是月光，你是海洋，你是那只在舞台上飞舞的星尾蝶。',Feature=1,TFValidDate='2019-03-11 05:00:00',ValidDate='2019-03-14 05:00:00',MainColor='22d6d0FF',}",
  [3000030] = "{id=3000030,NameZh='星尾蝶·霞',Icon='item_3000027',Type=810,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012660}},Desc='你是夕霞，你是迷梦，你是那只在舞台上飞舞的星尾蝶。',Feature=1,TFValidDate='2019-03-11 05:00:00',ValidDate='2019-03-14 05:00:00',MainColor='8c58edFF',}",
  [3000031] = "{id=3000031,NameZh='星尾蝶系列背饰',Icon='item_3000031',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15154,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Feature=1,TFValidDate='2019-03-11 05:00:00',ValidDate='2019-03-14 05:00:00',MainColor='X',}",
  [3000032] = "{id=3000032,NameZh='蜜语甜心',Icon='item_3000032',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15156,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='前奏牛奶红豆，主歌糖拌草莓，副歌是可可配布蕾，这首为你而唱的情歌，够甜嘛？',Feature=1,TFValidDate='2019-03-11 05:00:00',ValidDate='2019-03-14 05:00:00',LoadShowSize=3,LoadShowPose={0.1,0.4,0},}",
  [3000033] = "{id=3000033,NameZh='敛梦星纱',Icon='item_3000033',Type=850,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9615,AdventureValue=1,StorageReward={buffid={82000260}},Condition=8,Desc='纱网轻柔似雾，点缀以星辰璀璨。回眸一笑的瞬间，便陷入永无止境的迷梦。',Feature=1,TFValidDate='2019-04-01 05:00:00',ValidDate='2019-04-01 05:00:00',}",
  [3000034] = "{id=3000034,NameZh='浮光之冠[1]',Icon='item_3000034',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9616,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='圣洁而华丽，浮空精灵王族的冠翎。是纯真和祈愿的象征，只有怀着至诚之心的人才能够佩戴。',Feature=1,TFValidDate='2019-04-01 05:00:00',ValidDate='2019-04-01 05:00:00',}",
  [3000035] = "{id=3000035,NameZh='苍穹泪滴',Icon='item_3000035',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9617,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='她将最后的祝福化为一滴泪，在寂静中流淌至永恒。',Feature=1,TFValidDate='2019-04-01 05:00:00',ValidDate='2019-04-01 05:00:00',}",
  [3000036] = "{id=3000036,NameZh='月之露比',Icon='item_3000036',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9618,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='露比是诞生于月光之中的食梦兽。夜色降临时它便会出现，悄悄进入熟睡之人的心海。“咦，她今天又梦到那个人了吗……”',Feature=1,TFValidDate='2019-04-01 05:00:00',ValidDate='2019-04-01 05:00:00',}",
  [3000037] = "{id=3000037,NameZh='风汐回响',Icon='item_3000037',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9619,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='以天地树的灵气幻化而成的竖琴，是浮空精灵一族的珍藏。它流淌出的音色如同微风的轻语，总能拨动人们的心弦。',Feature=1,TFValidDate='2019-04-01 05:00:00',ValidDate='2019-04-01 05:00:00',}",
  [3000038] = "{id=3000038,NameZh='月萤流羽[1]',Icon='item_3000038',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9620,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='深受浮空精灵们喜爱的发饰，据说其中蕴藏着爱之魔法。由雪翼鸟的侧翎制作而成，摇曳时会闪烁月亮般的光辉。',Feature=1,TFValidDate='2019-04-01 05:00:00',ValidDate='2019-04-01 05:00:00',}",
  [3000039] = "{id=3000039,NameZh='星屑蔷薇',Icon='item_3000039',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9042,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='以星河凝成花瓣，回忆化作枝芽。蔷薇绽放之际，便是梦境苏醒时分。',Feature=1,TFValidDate='2019-04-01 05:00:00',ValidDate='2019-04-01 05:00:00',}",
  [3000040] = "{id=3000040,NameZh='彩虹许愿鲸',Icon='item_3000040',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9621,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='水手们常说，在海上有时能看到神秘的七色浪花，见到它的人能实现所有的愿望。鲸鱼王子知道这件事后，带着周围的鱼儿甩甩尾巴，微笑着晃出一个彩虹喷泉来。',Feature=1,TFValidDate='2019-05-01 05:00:00',ValidDate='2019-05-01 05:00:00',}",
  [3000041] = "{id=3000041,NameZh='潘罗的秘藏',Icon='item_3000041',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9622,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='传说在海底深处，有一个令无数海盗疯狂的宝箱。章鱼潘罗守卫着它，每当有东西靠近，潘罗就会挥舞手中的三叉戟大喊：“快走快走！我超凶的！',Feature=1,TFValidDate='2019-05-01 05:00:00',ValidDate='2019-05-01 05:00:00',}",
  [3000042] = "{id=3000042,NameZh='回旋情诗[1]',Icon='item_3000042',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9623,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='海葵安娜本以为自己会是月之海最寂寞的生物，直到小丑鱼托尼出现了。不管曾去往何方，托尼总会游回到她的身边。“我与你生来就为一体，死亡也不能令我们分离。”',Feature=1,TFValidDate='2019-05-01 05:00:00',ValidDate='2019-05-01 05:00:00',}",
  [3000043] = "{id=3000043,NameZh='深海眷恋',Icon='item_3000043',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9624,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='克拉拉是一只浅蓝的小鱼，孤独的生活在海底。迷路的小女孩误入了她的领域，却收获了一个温柔的吻：“可以留下来当我的朋友吗？',Feature=1,TFValidDate='2019-05-01 05:00:00',ValidDate='2019-05-01 05:00:00',}",
  [3000044] = "{id=3000044,NameZh='泡沫感应',Icon='item_3000044',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9625,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='海螺发明家托马斯的得意之作。他将自己的造型做成了传感器的模样，戴上便可以洞悉一切水下生物的活动。使用的时候会冒出泡泡，常常被误认为是一条小鱼。',Feature=1,TFValidDate='2019-05-01 05:00:00',ValidDate='2019-05-01 05:00:00',}",
  [3000045] = "{id=3000045,NameZh='星光水母[1]',Icon='item_3000045',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9626,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='水母小姐非常神秘。她从不和人说话，永远安静地凝视着水面，像在期待什么降临。“今天会不会有星星掉下来呢……”',Feature=1,TFValidDate='2019-05-01 05:00:00',ValidDate='2019-05-01 05:00:00',}",
  [3000046] = "{id=3000046,NameZh='趴趴小乌贼',Icon='item_3000046',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9043,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='琪琪是一只软乎乎的乌贼妹妹，最喜欢粘在人的脑袋上蹦蹦跶跶。“嗨呀！嗨呀！不要赶我走嘛，我不会喷墨的！”',Feature=1,TFValidDate='2019-05-01 05:00:00',ValidDate='2019-05-01 05:00:00',}",
  [3000047] = "{id=3000047,NameZh='尼德霍格的毒牙[1]',Icon='item_3000047',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9627,AdventureValue=1,StorageReward={buffid={82000240}},Condition=8,Desc='“毒液染红了鳞片，待巨龙苏醒吐息时，世界之树即将凋零。”——《布莱奇之诗·Ⅸ》',Feature=1,TFValidDate='2019-06-01 05:00:00',ValidDate='2019-06-01 05:00:00',}",
  [3000048] = "{id=3000048,NameZh='瓦尔哈拉之盾',Icon='item_3000048',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9628,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='“夕阳之中，失落神殿里尘埃散去，破碎之盾恢复原貌，闪耀出往昔幻影。”——《布莱奇之诗·Ⅱ》',Feature=1,TFValidDate='2019-06-01 05:00:00',ValidDate='2019-06-01 05:00:00',LoadShowSize=2.5,LoadShowPose={0,0.3,0},}",
  [3000049] = "{id=3000049,NameZh='永渡黄昏之音',Icon='item_3000049',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9629,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='“阿斯加德迎来终焉，诸神化作天际流星，就此陨落。黄昏中，那落幕时响起的挽歌，依然在云中回响。”——《布莱奇之诗·Ⅺ》',Feature=1,TFValidDate='2019-06-01 05:00:00',ValidDate='2019-06-01 05:00:00',}",
  [3000050] = "{id=3000050,NameZh='幼龙斯库尔',Icon='item_3000050',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9630,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='“百年后，它将化作一道月光，刻入永恒的黑暗。”————《布莱奇之诗·Ⅷ》',Feature=1,TFValidDate='2019-06-01 05:00:00',ValidDate='2019-06-01 05:00:00',LoadShowPose={0,0,0},}",
  [3000051] = "{id=3000051,NameZh='密米尔神钥',Icon='item_3000051',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9631,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='“智慧泉水寂静流淌，众神之王为汲一饮，留下右眼作为见证。泉水的主人将神王之眼做成秘钥，永世看守这无上的荣光。”——《布莱奇之诗·V》',Feature=1,TFValidDate='2019-06-01 05:00:00',ValidDate='2019-06-01 05:00:00',LoadShowSize=3,LoadShowPose={0,0.6,0},}",
  [3000052] = "{id=3000052,NameZh='邪神魔盔[1]',Icon='item_3000052',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9632,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='“火光肆虐间，天地为之哀鸣。邪神的目光所至，万物皆为焦土。”——《布莱奇之诗·Ⅹ》',Feature=1,TFValidDate='2019-06-01 05:00:00',ValidDate='2019-06-01 05:00:00',}",
  [3000053] = "{id=3000053,NameZh='神谕号角',Icon='item_3000053',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9044,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='“黄昏将至。风中飘散的悲怆之音，是诸神最后的号令。”————《布莱奇之诗·Ⅳ》',Feature=1,TFValidDate='2019-06-01 05:00:00',ValidDate='2019-06-01 05:00:00',LoadShowPose={0,0.3,0},}",
  [3000054] = "{id=3000054,NameZh='奇多豹专属头饰',Icon='item_3000054',Type=800,Quality=2,MaxNum=99,SellPrice=100,Desc='奇多豹来拉！独门奇多家常起司，融化在刚出炉的奇多香脆玉米棒上，边走边洒落的饼乾，那浓郁香味和脆脆口感绝美搭配，令人难以抗拒！',StageDisplay=0,Delete=3000054}",
  [3000060] = "{id=3000060,NameZh='嗷呜小怪兽·薰',Icon='item_3000060',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='嗷呜~我是你心里最甜的小怪兽！不喜欢我的家伙，一口把你吃掉哦！',Feature=1,TFValidDate='2019-05-13 05:00:00',ValidDate='2019-05-16 05:00:00',MainColor='f08c7fFF',}",
