  [3000126] = "{id=3000126,NameZh='睡龙宝宝',Icon='item_3000126',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10209,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='传说中，巨龙曾经给人类带来过短暂的安宁，虽然巨龙早已销声匿迹，但人们依然缅怀着曾经带来安宁的巨龙，他们制作和巨龙相关的饰品，寄托自己对巨龙归来的渴望，也寄托着对安宁的期盼。',Feature=1,LoadShowSize=2,LoadShowPose={0,0,0},}",
  [3000130] = "{id=3000130,NameZh='旋风可可猫·柠檬',Icon='item_3000130',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='阳光与汗水挥洒在球场上，耳边传来心仪之人的欢呼，可能这就是青春的悸动吧。“今天的幸运色是黄色，和她的鼓励一样温暖……嗯，如果拿下冠军，就去和她告白吧！”将对猫小姐的心意化作勇气和力量，他在欢呼声中投下了制胜一球。',Feature=1,TFValidDate='2019-04-20 05:00:00',ValidDate='2019-04-18 05:00:00',MainColor='f8cd56FF',}",
  [3000131] = "{id=3000131,NameZh='旋风可可猫·可可',Icon='item_3000130',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='阳光与汗水挥洒在球场上，耳边传来心仪之人的欢呼，可能这就是青春的悸动吧。“今天的幸运色是巧克力色，我记得她最喜欢的巧克力了……嗯，如果拿下冠军，就去和她告白吧！”将对猫小姐的心意化作勇气和力量，他在欢呼声中投下了制胜一球。',Feature=1,TFValidDate='2019-04-20 05:00:00',ValidDate='2019-04-18 05:00:00',MainColor='56291eFF',}",
  [3000132] = "{id=3000132,NameZh='旋风可可猫·纯雪',Icon='item_3000130',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='阳光与汗水挥洒在球场上，耳边传来心仪之人的欢呼，可能这就是青春的悸动吧。“今天的幸运色是白色，像她的笑容一样纯洁。嗯，如果拿下冠军，就去和她告白吧！”将对猫小姐的心意化作勇气和力量，他在欢呼声中投下了制胜一球。',Feature=1,TFValidDate='2019-04-20 05:00:00',ValidDate='2019-04-18 05:00:00',MainColor='dbbc86FF',}",
  [3000133] = "{id=3000133,NameZh='旋风可可猫·抹茶',Icon='item_3000130',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='阳光与汗水挥洒在球场上，耳边传来心仪之人的欢呼，可能这就是青春的悸动吧。“今天的幸运色是青色，和她包里的糖果一模一样。嗯，如果拿下冠军，就去和她告白吧！”将对猫小姐的心意化作勇气和力量，他在欢呼声中投下了制胜一球。',Feature=1,TFValidDate='2019-04-20 05:00:00',ValidDate='2019-04-18 05:00:00',MainColor='5cc6acFF',}",
  [3000140] = "{id=3000140,NameZh='布蕾喵小姐·柠檬',Icon='item_3000140',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='学园祭的前夕，她把亲手制作的布蕾放在少年的课桌上，许下了甜蜜的心愿。几只猫咪老师看见了，悄悄将注入了魔法的裙子放在了她的枕边。“有了梦想的色彩点缀，愿爱恋永远与你相伴！”',Feature=1,TFValidDate='2019-04-20 05:00:00',ValidDate='2019-04-18 05:00:00',MainColor='f8cd56FF',}",
  [3000141] = "{id=3000141,NameZh='布蕾喵小姐·可可',Icon='item_3000140',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='学园祭的前夕，她把亲手制作的布蕾放在少年的课桌上，许下了甜蜜的心愿。几只猫咪老师看见了，悄悄将注入了魔法的裙子放在了她的枕边。“这里面藏着晚风的祝福，要幸福呀，喵小姐！”',Feature=1,TFValidDate='2019-04-20 05:00:00',ValidDate='2019-04-18 05:00:00',MainColor='56291eFF',}",
  [3000142] = "{id=3000142,NameZh='布蕾喵小姐·纯雪',Icon='item_3000140',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='学园祭的前夕，她把亲手制作的布蕾放在少年的课桌上，许下了甜蜜的心愿。几只猫咪老师看见了，悄悄将注入了魔法的裙子放在了她的枕边。“所有的祝愿化作了这道温柔的白，好好睡吧，明天要加油呀！”',Feature=1,TFValidDate='2019-04-20 05:00:00',ValidDate='2019-04-18 05:00:00',MainColor='dbbc86FF',}",
