  [3000156] = "{id=3000156,NameZh='舒芙蕾缎带·可可',Icon='item_3000155',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='糖果猫老师的最新杰作：浪漫又富有少女气息的舒芙蕾缎带！仔细闻闻还散发着甜品的芳香。只要戴上它，就会化身学园中最可爱的猫咪女孩，收获一操场的爱心哦！这一条有着神秘的黑色。',Feature=1,TFValidDate='2019-04-20 05:00:00',ValidDate='2019-04-18 05:00:00',MainColor='56291eFF',}",
  [3000157] = "{id=3000157,NameZh='舒芙蕾缎带·纯雪',Icon='item_3000155',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='糖果猫老师的最新杰作：浪漫又富有少女气息的舒芙蕾缎带！仔细闻闻还散发着甜品的芳香。只要戴上它，就会化身学园中最可爱的猫咪女孩，收获一操场的爱心哦！这一条有着纤细的白色。',Feature=1,TFValidDate='2019-04-20 05:00:00',ValidDate='2019-04-18 05:00:00',MainColor='faf0d5FF',}",
  [3000158] = "{id=3000158,NameZh='舒芙蕾缎带·抹茶',Icon='item_3000155',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='糖果猫老师的最新杰作：浪漫又富有少女气息的舒芙蕾缎带！仔细闻闻还散发着甜品的芳香。只要戴上它，就会化身学园中最可爱的猫咪女孩，收获一操场的爱心哦！这一条有着清新的茶色。',Feature=1,TFValidDate='2019-04-20 05:00:00',ValidDate='2019-04-18 05:00:00',MainColor='5cc6acFF',}",
  [3000159] = "{id=3000159,NameZh='舒芙蕾缎带系列头饰',Icon='item_3000159',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15162,AdventureValue=1,StorageReward={buffid={80012920}},Condition=8,Feature=1,TFValidDate='2019-04-20 05:00:00',ValidDate='2019-04-18 05:00:00',MainColor='X',}",
  [3000160] = "{id=3000160,NameZh='喵喵先生',Icon='item_3000160',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15163,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='叮咚~恭喜咖啡猫老师当选心动学园的年度喵喵先生！“有什么不懂的都可以问我哦，恋爱问题也可以解答！”',Feature=1,TFValidDate='2019-04-20 05:00:00',ValidDate='2019-04-18 05:00:00',}",
  [3000161] = "{id=3000161,NameZh='心跳魔法',Icon='item_3000161',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15164,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='《猫咪魔法小课堂5.0》：将此法术施予爱慕之人，如果TA也对你心动，就会在其脸上显现出心形印记。',Feature=1,TFValidDate='2019-04-20 05:00:00',ValidDate='2019-04-18 05:00:00',}",
  [3000162] = "{id=3000162,NameZh='甜心猫尾',Icon='item_3000162',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15165,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='不知为什么，猫尾巴逐渐成了心动学园里最受学生欢迎的装扮。“悄悄告诉你，穿的和猫咪老师们一样的话，迟到就不会被罚站了！”',Feature=1,TFValidDate='2019-04-20 05:00:00',ValidDate='2019-04-18 05:00:00',}",
  [3000163] = "{id=3000163,NameZh='蓬松松星云',Icon='item_3000163',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15166,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='学园里流传着一则奇怪的故事：夜晚的天空中总会飘着一朵雪白的云，仔细听还会发出呼噜噜的声音。牛奶猫老师闻言苦恼地抖了抖耳朵：那只是我在睡觉而已啦！',Feature=1,TFValidDate='2019-04-20 05:00:00',ValidDate='2019-04-18 05:00:00',}",
  [3000164] = "{id=3000164,NameZh='蜜语巧克力',Icon='item_3000164',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15167,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='“牛奶、咖啡和榛子！哪个味道是你最喜欢的呢？”据说在学园祭的那天，糖果猫老师会随机在课桌里塞巧克力，收到的学生会有一整年的好运气！',Feature=1,TFValidDate='2019-04-20 05:00:00',ValidDate='2019-04-18 05:00:00',}",
  [3000165] = "{id=3000165,NameZh='卡普拉祝福礼盒',Icon='item_3000165',Type=30,MaxNum=99999,SellPrice=100,Desc='为了感谢冒险者的帮助，卡普拉小姐姐们精心准备的小礼物~都是很实用的东西哦！开启后必定获得以下物品：「卡普拉印章」×10，有概率获得「莫拉硬币」×2、「祈祷晶片包」×1、「茜色回忆图纸」×1',Feature=1,}",
  [3000166] = "{id=3000166,NameZh='卡普拉印章',Icon='item_3000166',Type=61,MaxNum=99999,AuctionPrice=1,SellPrice=10,Desc='一枚印章，上方刻印着卡普拉公司的标记。是卡普拉给做出特殊贡献之人的奖励，收集一定数量可以兑换惊喜！(每日上限仅限野外活动魔物获取)',GetLimit={limit={[999]={400,0}},source={22},type=1},ExistTimeType=2,ExistTime='2023-02-01 05:00:00',Feature=1,}",
  [3000167] = "{id=3000167,NameZh='闪耀的收获图纸',Icon='item_3031167',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=3000167,Desc='阳光与汗水洒满了金色的五月，而收获之日来临时，过往的辛劳都会化为喜悦的笑容。“愿你的付出总有回报！”',Feature=1,}",
  [3000168] = "{id=3000168,NameZh='茜色回忆图纸',Icon='item_3031168',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=3000168,Desc='波利造型的可爱头巾，见证了努力和付出的每一个瞬间。此刻所有的勤恳与辛劳，在未来都会化作回忆的珍藏。',Feature=1,}",
  [3000170] = "{id=3000170,NameZh='告白礼盒',Icon='item_3000170',Type=30,MaxNum=99999,SellPrice=100,Desc='不知是谁把它悄悄放在了你的包里，里面还贴着一张爱心小纸条：“喜欢你很久啦~”，开启后必定获得以下物品：「甜蜜心愿」×1、「冒险丸子」×520，有概率获赠「我中意你」×2、「绝对领域」×1、「变傻光线枪」×1',Feature=1,}",
  [3000171] = "{id=3000171,NameZh='甜蜜心愿',Icon='item_3000171',Type=77,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=108,AdventureValue=1,StorageReward={buffid={82000080}},Condition=8,Desc='想要大声将心意告诉全世界，画下了粉色的爱诉说着思念。浪漫之梦绽放于此，这一次，定会迎来爱恋的奇迹吧！',Feature=1,}",
  [3000172] = "{id=3000172,NameZh='铁匠联盟心意礼盒',Icon='item_3000172',Type=30,MaxNum=99999,SellPrice=100,Desc='一份小巧的礼盒，是铁匠联盟特意为冒险者准备的。“祝你次次精炼成功！”，开启后必定获得以下物品：「神之金属」15~30个、「铝」15~30个、zeny100000',Feature=1,}",
  [3000173] = "{id=3000173,NameZh='猫管家的珍藏礼盒',Icon='item_3000173',Type=30,MaxNum=99999,SellPrice=100,Desc='据说是猫管家偷偷藏在床下的礼物，不知为什么被提前发现了，里面塞满了各种新奇的小东西。开启后必定获得以下物品：「秘银」15~30个、zeny150000，有概率获赠「精致的维修碎片」×1',Feature=1,}",
  [3000174] = "{id=3000174,NameZh='音乐会应援礼盒',Icon='item_3000174',Type=30,MaxNum=99999,SellPrice=100,Desc='为感谢观众们的热情，音乐会主办方赠送的礼物。虽然不大，但载着满满诚挚的心意。\n开启后随机获赠以下道具中的一种：「玛丝黛拉种子」×1、「莫拉硬币」×2、「锁链雷锭」×2、「金质勋章」×1、「女武神的馈赠」×1、「乐园币」×200。',Feature=1,}",
  [3000175] = "{id=3000175,NameZh='音乐会门票抽奖券',Icon='item_3000175',Type=4201,MaxNum=1,SellPrice=50000,Desc='一张神秘的奖券。只此一份，得到它也许能收获意外惊喜。只有等音乐会结束后才可以出售哦。',NoStorage=3,Feature=1,}",
  [3000176] = "{id=3000176,NameZh='音乐会邀请函图纸',Icon='item_3031176',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=3000176,Desc='将我的心愿写在信间，寄往有你的方向。企盼在梦想的音符中，与你再次相逢。',Feature=1,}",
  [3000177] = "{id=3000177,NameZh='风栖灵龙·辉夜',Icon='item_3000177',Type=90,MaxNum=1,AuctionPrice=1,SellPrice=100,AdventureSort=1003,AdventureValue=100,AdventureReward={buffid={63000250}},Condition=8,Desc='风栖幼龙的成年体，性格温驯亲切，十分稀有。这一只是雌性，身边笼罩着闪耀的光屑，传说中那便是星辰的色彩。',Feature=1,LoadShowSize=0.9,LoadShowRotate=0,LoadShowPose={0,-0.05,0},}",
  [3000178] = "{id=3000178,NameZh='风栖灵龙·流光',Icon='item_3000178',Type=90,MaxNum=1,AuctionPrice=1,SellPrice=100,AdventureSort=1004,AdventureValue=100,AdventureReward={buffid={63000250}},Condition=8,Desc='风栖幼龙的成年体，性格温驯亲切，十分稀有。这一只是雄性，每当它飞翔时，羽翼闪烁的光芒便照亮了整个天空。',Feature=1,LoadShowSize=0.9,LoadShowRotate=0,LoadShowPose={0,-0.05,0},}",
  [3000179] = "{id=3000179,NameZh='闪烁的棒球帽[1]',Icon='item_3000179',Type=800,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10136,AdventureValue=1,StorageReward={buffid={80011150}},Condition=8,Desc='颜色醒目的棒球帽，戴上它就会成为人群中的焦点。“怎么样，像不像个大明星？”',Feature=1,TFValidDate='2019-04-04 05:00:00',ValidDate='2019-04-04 05:00:00',}",
  [3000182] = "{id=3000182,NameZh='小猪徽章',Icon='item_3000182',Type=61,UseMode=30002,MaxNum=99999,AuctionPrice=1,SellPrice=10,Desc='刻有小猪图样的徽章，十分精巧可爱。收集到一定数量的话，也许会有什么特别的用途。\n使用后打开小猪感恩商店，兑换「大梦想家卡片」等道具。',ExistTimeType=2,ExistTime='2019-07-15 05:00:00',}",
  [3000183] = "{id=3000183,NameZh='奥依珍藏礼盒',Icon='item_3000183',Type=30,MaxNum=99999,SellPrice=100,Desc='据说是小野猪奥依为了离家冒险，偷偷藏起来的宝贝。只有被奥依认可的冒险者才能够拥有。\n打开必定获得15~35个「古拉姆晶末」、35~50个「诺伦卡片」，必定获得「卡册残页」*2、「精装卡册残页」*2、「华丽卡册」*1、「远古魔力卡册」*1中的一种，有概率获赠稀有神谕专属卡片*1',}",
  [3000184] = "{id=3000184,NameZh='奥依的藏宝图',Icon='item_3000184',Type=48,MaxNum=1,SellPrice=100,Desc='为了隐藏宝物的秘密，小野猪奥依把它们悄悄塞到了床底，差一点被老父亲咿唯当成废纸丢掉。\n使用后，可得知一处普隆德拉北部的藏宝地点呦~',ExistTimeType=2,ExistTime='2019-07-15 05:00:00',}",
  [3000185] = "{id=3000185,NameZh='魔力粽子',Icon='item_3000185',Type=41,MaxNum=99999,SellPrice=100,Desc='蕴含着神秘力量的粽子，吃下去会得到端午节的祝福。在某些地方使用的话，会有意想不到的收获。\n使用后30分钟内击杀粽子怪，获得「小猪徽章」数量翻倍',}",
  [3000186] = "{id=3000186,NameZh='趴趴小猪图纸',Icon='item_3031186',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=3000186,Desc='一直趴在冒险者头上的迷你小猪，憨态可掬，惹人喜爱。头顶的四叶草是幸运的象征，注意不要被风吹掉啦！',}",
  [3000187] = "{id=3000187,NameZh='粽子宝宝图纸',Icon='item_3031187',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=3000187,Desc='被芦苇叶包裹的粽子宝宝，软软糯糯还散发着糯米的清香……“等、等等！不可以吃啊！”',}",
  [3000188] = "{id=3000188,NameZh='奥依感恩礼盒',Icon='item_3000188',Type=30,MaxNum=99999,SellPrice=100,Desc='“人类有时候还是挺厉害的！”小野猪奥依一边小声嘀咕，一边把这个礼盒塞给了你。\n使用后可获得「小猪徽章」*30、「七彩贝壳」*300，并有10%概率获赠「奥依勋章」*1',}",
  [3000189] = "{id=3000189,NameZh='奥依勋章',Icon='item_3000189',Type=61,UseMode=30003,MaxNum=99999,SellPrice=100,Desc='“收下它我们就是朋友了！——英俊潇洒的小野猪之星奥依”\n使用后打开猪猪商店，兑换「幸运嘟嘟宠物蛋」或幸运嘟嘟的限定皮肤「精致嘟嘟」',}",
  [3000190] = "{id=3000190,NameZh='幸运嘟嘟魔物蛋',Icon='item_3000190',Type=101,MaxNum=1,SellPrice=100,Desc='一颗神奇的魔物蛋，里面可以孵化出宠物幸运嘟嘟。',}",
  [3000191] = "{id=3000191,NameZh='精致嘟嘟',Icon='item_3000191',Type=41,MaxNum=1,SellPrice=100,Desc='新时代猪猪的准则：时刻保持优雅，不会收拾打扮的猪猪不是好猪猪~！\n使用后可解锁幸运嘟嘟的精致嘟嘟外观',}",
  [3000192] = "{id=3000192,NameZh='晨露稻草',Icon='item_3000192',Type=103,MaxNum=99999,SellPrice=100,Desc='滴着露水的稻草，蓬松柔软，散发着阳光的香气。是魔物幸运嘟嘟最喜爱的食物。',}",
  [3000193] = "{id=3000193,NameZh='光影交织礼盒',Icon='item_3000193',Type=30,MaxNum=99999,SellPrice=100,Desc='卡普拉公司为冒险者们准备了神秘的惊喜~开启后获得随机6.0版本普通材料*50或6.0版本稀有材料*1。\n（此礼盒被封印在了生命体研究所，只能在6.0版本正式服上线后才能打开哦~）',Level=60,}",
  [3000194] = "{id=3000194,NameZh='趴趴Puriku',Icon='item_3000194',Type=840,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,Desc='不管走到哪里，都有Puriku的陪伴~',Feature=1,StageDisplay=0,Delete=3000194}",
  [3000195] = "{id=3000195,NameZh='Puriku饮料',Icon='item_3000195',Type=41,MaxNum=99999,SellPrice=100,Desc='喝下Puriku饮料，在接下来的30分钟内，野外击杀魔物获得的Base经验和Job经验翻倍~（死亡及非战斗状态下消耗Buff时长，离线状态不消耗Buff时长）',Delete=3000195}",
  [3000196] = "{id=3000196,NameZh='辅佐使',Icon='',Type=10,MaxNum=1,Desc='海神成长的辅佐人，功不可没！',Delete=3000196}",
  [3000197] = "{id=3000197,NameZh='闪电绅士魔物蛋',Icon='item_3000197',Type=101,MaxNum=1,SellPrice=100,Desc='一颗神奇的魔物蛋，里面可以孵化出魔物闪电绅士。',TFValidDate='2019-06-03 05:00:00',ValidDate='2019-06-10 05:00:00',}",
