  [3000230] = "{id=3000230,NameZh='摇曳星河',Icon='item_3000230',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15179,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='洋伞转一圈，银铃敲响，聆听爱之声，洋伞转两圈，繁星满天，仰望星河夜，洋伞转三圈，星月流转，牵引你至所爱之人的身旁。',Feature=1,TFValidDate='2019-06-24 05:00:00',ValidDate='2019-06-27 05:00:00',LoadShowSize=1.7,LoadShowPose={-0.3,-0.1,0},}",
  [3000231] = "{id=3000231,NameZh='相伴终生',Icon='item_3000231',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15180,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='“无论富贵贫穷，无论生老病死，无论任何艰难险阻，你都愿意对你眼前之人不离不弃直到永远么？”“我愿意”',Feature=1,TFValidDate='2019-06-24 05:00:00',ValidDate='2019-06-27 05:00:00',}",
  [3000232] = "{id=3000232,NameZh='驯龙魔杖',Icon='item_3000232',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15181,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='恶龙不知道从哪得到了一把据说能控制所有龙族的法杖，思考了一下后，恶龙把法杖交给了公主，公主略带疑惑的看着恶龙，恶龙单膝下跪说道 “被你驯服，我心甘情愿”。',Feature=1,TFValidDate='2019-06-24 05:00:00',ValidDate='2019-06-27 05:00:00',LoadShowPose={0,0,-0.7},}",
  [3000233] = "{id=3000233,NameZh='蓬蓬绒雪猫',Icon='item_3000233',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15182,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='公主殿下最近被一只白色的小猫崽俘获了芳心，这个结果让恶龙很生气，虽然小猫崽很可爱，但是公主殿下只能是他一个人的！',Feature=1,TFValidDate='2019-06-24 05:00:00',ValidDate='2019-06-27 05:00:00',LoadShowPose={0,0,0},}",
  [3000234] = "{id=3000234,NameZh='夜莺先生',Icon='item_3000234',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15183,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='踮起脚尖，提起裙边，夜莺先生注视到了那舞池中跳动的身影，或许只是一眼，但是夜莺先生确定，那个人就是你要找的那个她。',Feature=1,TFValidDate='2019-06-24 05:00:00',ValidDate='2019-06-27 05:00:00',LoadShowSize=2.5,LoadShowPose={0,0.45,0},}",
  [3000235] = "{id=3000235,NameZh='奥依的藏宝图',Icon='item_3000184',Type=48,MaxNum=1,SellPrice=100,Desc='为了隐藏宝物的秘密，小野猪奥依把它们悄悄塞到了床底，差一点被老父亲咿唯当成废纸丢掉。\n使用后，可得知一处克特森林的藏宝地点呦~',ExistTimeType=2,ExistTime='2019-07-15 05:00:00',}",
  [3000236] = "{id=3000236,NameZh='奥依的藏宝图',Icon='item_3000184',Type=48,MaxNum=1,SellPrice=100,Desc='为了隐藏宝物的秘密，小野猪奥依把它们悄悄塞到了床底，差一点被老父亲咿唯当成废纸丢掉。\n使用后，可得知一处哥布灵森林的藏宝地点呦~',ExistTimeType=2,ExistTime='2019-07-15 05:00:00',}",
