  [3000239] = "{id=3000239,NameZh='奥依的藏宝图',Icon='item_3000184',Type=48,MaxNum=1,SellPrice=100,Desc='为了隐藏宝物的秘密，小野猪奥依把它们悄悄塞到了床底，差一点被老父亲咿唯当成废纸丢掉。\n使用后，可得知一处兽人村落的藏宝地点呦~',ExistTimeType=2,ExistTime='2019-07-15 05:00:00',}",
  [3000240] = "{id=3000240,NameZh='乌拉的珍藏宝盒',Icon='item_3658',Type=30,MaxNum=99999,SellPrice=100,Desc='“感谢您对被劫走的哥布灵们出手相救！我想请您看看这个，本巫师珍藏多年的宝物……”大巫师乌拉悄悄把你叫到一边，然后从储藏室深处翻出了这个宝盒。\n（开启后随机获得20~40个「古拉姆晶末」，30～50个「诺伦卡片」，并随机获赠以下道具中的一种：「卡册残页」*1、「精装卡册残页」*1、「华丽卡册」*1，还有5%概率获赠远古魔力卡册*1。）',Feature=1,}",
  [3000241] = "{id=3000241,NameZh='舞火假面',Icon='item_3000241',Type=830,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9633,AdventureValue=1,StorageReward={buffid={82000250}},Condition=8,Desc='“那个带着假面的身影在火焰中翩翩起舞，比昼日之光更绚烂，比红莲之炎更炙热。”——《炎之回忆录》',Feature=1,TFValidDate='2019-07-01 05:00:00',ValidDate='2019-07-01 05:00:00',LoadShowPose={0,0.25,0},}",
  [3000242] = "{id=3000242,NameZh='昼光',Icon='item_3000242',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9634,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='古老的魔法刻印，上面的法阵记录着人类对征服火之元素做出的不懈努力。在昼光诞生的那一天，人类打开了掌握火焰元素的大门。',Feature=1,TFValidDate='2019-07-01 05:00:00',ValidDate='2019-07-01 05:00:00',LoadShowPose={0,0.1,0},}",
  [3000243] = "{id=3000243,NameZh='煌印[1]',Icon='item_3000243',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9635,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='统御火之元素者才能戴上的皇冠，象征着使用最高级火焰魔法的绝对权。',Feature=1,TFValidDate='2019-07-01 05:00:00',ValidDate='2019-07-01 05:00:00',}",
  [3000244] = "{id=3000244,NameZh='炎魔之尾',Icon='item_3000244',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9636,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='爆炎小恶魔生气的时候，尾巴的末端会冒出火花，但他/她生气的时候，比爆炎小恶魔还可怕一万倍！',Feature=1,TFValidDate='2019-07-01 05:00:00',ValidDate='2019-07-01 05:00:00',}",
  [3000245] = "{id=3000245,NameZh='焰之探索者[1]',Icon='item_3000245',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9637,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='小火马皮革束带，火山灰溶制的红色挡风镜，焰之探索者是深入火焰之地探索的必备品！',Feature=1,TFValidDate='2019-07-01 05:00:00',ValidDate='2019-07-01 05:00:00',LoadShowPose={0,0.9,0},}",
  [3000246] = "{id=3000246,NameZh='焰歌',Icon='item_3000246',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9638,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='火焰中传来的歌声，诉说着我们最炽热的曾经。',Feature=1,TFValidDate='2019-07-01 05:00:00',ValidDate='2019-07-01 05:00:00',LoadShowSize=2.5,LoadShowPose={0,0.4,0},}",
  [3000247] = "{id=3000247,NameZh='圈圈晕',Icon='item_3000247',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9045,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='被你在脸颊上亲上一口，幸福到露出圈圈晕！',Feature=1,TFValidDate='2019-07-01 05:00:00',ValidDate='2019-07-01 05:00:00',LoadShowSize=3.5,LoadShowPose={0,0.6,0},}",
  [3000248] = "{id=3000248,NameZh='波利拉杆箱',Icon='item_3000248',Type=77,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=107,AdventureValue=1,StorageReward={buffid={82000130}},Condition=8,Desc='拉着波利拉杆箱，风骚地走在普隆德拉街头，回头率200%！',Feature=1,TFValidDate='2019-04-04 05:00:00',ValidDate='2019-04-04 05:00:00',}",
  [3000249] = "{id=3000249,NameZh='奥依祝福礼盒',Icon='item_3711',Type=30,MaxNum=99999,SellPrice=100,Desc='一个小巧的礼盒，拿到手却意外的沉，里面存放着小野猪奥依的私藏。因为被奥依承认了实力，冒险者意外得到了这份礼物。\n开启后必定获得「小猪徽章」*30，并可随机获得以下道具的一种：「神谕之尘」*2、「神谕之晶」*2、「祈祷晶片包」*1、「玛丝黛拉种子」*1、「金质勋章」*1、「来自女武神的馈赠」*1',Feature=1,}",
  [3000250] = "{id=3000250,NameZh='心愿蛋糕',Icon='item_3000250',Type=41,MaxNum=99999,SellPrice=100,Desc='被赋予了神秘魔法的蛋糕，散发着甜蜜的诱人香气，据传是某个魔女无意间发现的配方。“吃下去吧，所有的愿望都会被实现……”（特殊外观效果并获得全能力+15，持续15分钟，时长可叠加，死亡下线不清除）',Feature=1,}",
  [3000251] = "{id=3000251,NameZh='缤纷时光礼盒',Icon='item_3867',Type=30,MaxNum=99999,SellPrice=100,Desc='一份镶嵌着回忆的礼盒，所有沉淀的美好都化作其中的宝物，随着时光的流淌熠熠生辉。开启后必定获得「来自公会的馈赠」*5、「心愿蛋糕」*1、「祈祷晶片包」*1，并可概率获得「金质勋章」*1',Feature=1,}",
  [3000252] = "{id=3000252,NameZh='新世界庆典礼包',Icon='item_6606',Type=30,MaxNum=99999,SellPrice=100,Desc='初遇你，仿若微风拂过一般温暖绵长，期待着我们的未来会拥有更美好的篇章。开启后获得「B格猫福利券·I」×30、「B格猫福利券·Ⅱ」×30、「B格猫福利券·宴」×60、「冒险家硬币」×5、「金质勋章」×2、「七彩贝壳」×300、「来自公会的馈赠」×10、「冒险丸子」×100、「暖心料理」×5。',Feature=1,}",
  [3000253] = "{id=3000253,NameZh='奥依珍藏礼盒',Icon='item_3000183',Type=30,MaxNum=99999,SellPrice=100,Desc='据说是小野猪奥依为了离家冒险，偷偷藏起来的宝贝。只有被奥依认可的冒险者才能够拥有。\n打开必定获得15~35个「古拉姆晶末」、Zeny×300000，必定获得「卡册残页」*2、「精装卡册残页」*2、「华丽卡册」*1、「远古魔力卡册」*1中的一种，有概率获赠稀有神谕专属卡片*1',}",
  [3000260] = "{id=3000260,NameZh='清爽遮阳帽图纸',Icon='item_3031260',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=3000260,Desc='充满了夏日风情的遮阳帽，光是看着就能感受到一丝凉意。“怎么样，想好和谁一起去海边度假了吗？”',Feature=1,}",
  [3000261] = "{id=3000261,NameZh='炎炎夏日补给包',Icon='item_6606',Type=30,MaxNum=99999,SellPrice=100,Desc='猛烈的高温席卷了米德加尔特大陆，在烈日的笼罩下，这份补给包里的小东西也许能派上用场。\n开启后必定获得「清爽冰晶」×20、「夏日冰饮」×5、「料理兑换券」×1。',Feature=1,}",
  [3000262] = "{id=3000262,NameZh='清爽冰晶',Icon='item_3000262',Type=61,MaxNum=99999,AuctionPrice=1,SellPrice=10,Desc='外表光洁剔透，稍微一触碰竟然能感受到强烈的凉意……据说是巫师们为了避暑，特意提炼出来的魔力水晶。\n使用后可打开夏日清凉商店，兑换各类实用道具。',ExistTimeType=2,ExistTime='2020-08-10 05:00:00',}",
  [3000263] = "{id=3000263,NameZh='清爽夏日冰饮',Icon='item_3000263',Type=41,MaxNum=99999,SellPrice=100,Desc='烈日炎炎的夏季，没有什么比清清凉凉的冰饮更振奋人心了！想要尝一口吗~\n使用后提升20%水属性伤害，持续1小时。',}",
  [3000264] = "{id=3000264,NameZh='清凉之心',Icon='item_3000264',Type=64,MaxNum=99999,SellPrice=100,Desc='合成「清凉夏日卡片」的必备材料~\n蕴含着冰之力量的神秘结晶，如果凑太近会被铺面而来的冷气冻伤。只要拿一小块放在包里，全天都会很凉爽。',Feature=1,}",
  [3000265] = "{id=3000265,NameZh='水之力结晶',Icon='item_3000265',Type=64,MaxNum=99999,AuctionPrice=1,SellPrice=10,Desc='合成「清凉夏日卡片」的必备材料~\n蕴含着水之力量的神秘结晶，轻轻一触碰居然能看到水珠飞溅……但是气温太高，水滴很快就蒸发了，好像并不怎么凉快呢。',Feature=1,}",
  [3000266] = "{id=3000266,NameZh='超高温裂隙',Icon='item_3000266',Type=77,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=109,AdventureValue=1,StorageReward={buffid={82000100}},Condition=8,Desc='超高温下的扭曲时空，不知会通往何处……\n使用后召唤一个裂隙，触摸裂隙后触发随机事件。\n*总计10种随机事件\n*账号下每日限制使用1次，可永久使用不消耗~',Feature=1,TFValidDate='2019-06-28 05:00:00',ValidDate='2019-07-01 05:00:00',}",
  [3000267] = "{id=3000267,NameZh='清凉一夏礼包',Icon='item_3945',Type=30,MaxNum=99999,SellPrice=100,Desc='吉芬魔法学院为了应对夏日，特意准备的凉爽礼包，适合所有在大热天不爱出远门的冒险者！\n“洛马斯，我觉得你也要一个。”\n“求你别说了……”\n（开启后获得随机MVP材料*2、随机稀有材料*2、公会贡献*500）',Feature=1,}",
  [3000268] = "{id=3000268,NameZh='假日成长礼包',Icon='item_3000268',Type=30,MaxNum=99999,SellPrice=100,Desc='根据贝露老师的调查报告，冒险者们在暑假的倦怠指数上升了2000%……为了让这群人恢复干劲，她制作了这个礼包。里面塞满了实用的道具，就算是最懒的人，使用后也会进步飞快。\n（开启后随机获得「莫拉硬币」*20~40，还有概率获赠「魔力提取器」*1。）',Feature=1,}",
  [3000269] = "{id=3000269,NameZh='假日学习礼包',Icon='item_3994',Type=30,MaxNum=99999,SellPrice=100,Desc='假日既要尽情玩耍，又要好好学习哦~\n（开启后随机获得「神谕之尘」*8~15、「神谕之晶」*6~12，还有概率获赠「魔力提取器」*1。）',Feature=1,}",
  [3000280] = "{id=3000280,NameZh='爱的气息',Icon='item_3000280',Type=61,MaxNum=99999,SellPrice=520,Desc='感觉自己被满满的爱包围着，每一分每一秒都觉得温暖哦~\n19.08.01--19.08.31可以在国王波利处合成活动限定卡片「恋之双子星卡片」。\n也可以在「宝石公爵」处兑换惊喜礼盒。\n（该道具将在19.09.01之后失效，请尽快使用哦~）',ExistTimeType=2,ExistTime='2019-09-01 05:00:00',Feature=1,}",
  [3000281] = "{id=3000281,NameZh='爱神的祝福',Icon='item_3000281',Type=30,MaxNum=99999,SellPrice=100,Desc='来自爱神菲尔的祝福，打开之后必定获得「爱的气息」*20，并且获得以下奖励的一种：「神秘箱子6.0」*1、「秘银」*3、「金质勋章」*1、「料理兑换券」*1、「锁链雷锭」*2、「莫拉硬币」*4、「神谕之晶」*1、「神谕之尘」*2、Zeny*51020，还有概率获赠活动限定背饰图纸「闪闪惹人爱图纸」*1。',Feature=1,}",
  [3000282] = "{id=3000282,NameZh='爱神的谢礼',Icon='item_6566',Type=30,MaxNum=99999,SellPrice=100,Desc='来自爱神菲尔的谢礼，打开之后必定获得「恋之心意」*1、「B格猫福利券·Ⅰ」*1、「B格猫福利券·宴」*2，并且可以随机获得特殊含义金额的Zeny。',Feature=1,}",
  [3000283] = "{id=3000283,NameZh='闪闪惹人爱图纸',Icon='item_3031283',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=3000283,Feature=1,}",
  [3000285] = "{id=3000285,NameZh='恋之心意',Icon='item_6065',Type=64,MaxNum=99999,SellPrice=51020,Desc='要怎么样才能让你明白我的心意呢？\n19.08.01--19.08.31可以在国王波利处合成活动限定卡片「恋之双子星卡片」。\n（该道具将在19.09.01之后失效，请尽快使用哦~）',ExistTimeType=2,ExistTime='2019-09-01 05:00:00',Feature=1,}",
  [3000286] = "{id=3000286,NameZh='天蓝的祈祷',Icon='item_700101',Type=30,MaxNum=99999,SellPrice=100,Desc='打开可以获得「B格猫福利券·Ⅰ」*1、「秘银」*3、「神秘箱子6.0」*1。',Feature=1,}",
  [3000287] = "{id=3000287,NameZh='青绿的祝福',Icon='item_700141',Type=30,MaxNum=99999,SellPrice=100,Desc='打开可以获得「爱的气息」*20、「金质勋章」*1、「锁链雷锭」*2。',Feature=1,}",
  [3000288] = "{id=3000288,NameZh='明黄的喜悦',Icon='item_5502',Type=30,MaxNum=99999,SellPrice=100,Desc='打开可以获得「B格猫福利券·宴」*1、「料理兑换券」*1、「莫拉硬币」*4。',Feature=1,}",
  [3000289] = "{id=3000289,NameZh='淡紫的神秘',Icon='item_550000',Type=30,MaxNum=99999,SellPrice=100,Desc='打开可以获得「B格猫福利券·Ⅱ」*1、「神谕之尘」*2、「神谕之晶」*1。',Feature=1,}",
  [3000290] = "{id=3000290,NameZh='永夜武器兑换券',Icon='item_3000290',Type=61,Quality=4,UseMode=30006,MaxNum=99999,SellPrice=100,Desc='哇！恭喜你唷，赶紧去兑换自己心仪的永夜系列的武器外观吧!',Feature=1,}",
  [3000291] = "{id=3000291,NameZh='永夜·星之光棱',Icon='item_3000291',Type=170,MaxNum=99,SellPrice=100,AdventureSort=100013,AdventureValue=1,Condition=8,Desc='“光棱之枪闪耀之时，吾将予天繁星。”——晨曦之子格拉斯尼尔的爱枪。百年前，他用枪尖击落月食后，伴着漫天星河的光芒消散于天际。',Feature=1,StageDisplay=0,LoadShowRotate=260,LoadShowPose={0.4,-1,-1.1},}",
  [3000292] = "{id=3000292,NameZh='永夜·破碎星陨',Icon='item_3000292',Type=180,MaxNum=99,SellPrice=100,AdventureSort=100013,AdventureValue=1,Condition=8,Desc='“悲叹星辰之人，永不得见黎明的晨光。”——预言者罗兰被囚于恒星之中，不堪忍受孤寂，将自身的灵魂铸成此剑。',Feature=1,LoadShowRotate=80,LoadShowPose={0.4,-0.8,-0.8},}",
  [3000293] = "{id=3000293,NameZh='永夜·失落星轨',Icon='item_3000293',Type=190,MaxNum=99,SellPrice=100,AdventureSort=100013,AdventureValue=1,Condition=8,Desc='“点点星辰的轨迹，刻印着命运的方向。”——智慧的大法师，安特蕾娅的魔杖。身为世间唯一掌握夜之魔法的术士，安特蕾娅每日都会前往观星台，沉默地观察每一颗流星的滑落。',Feature=1,StageDisplay=0,LoadShowPose={0.3,-0.2,-1.2},}",
  [3000294] = "{id=3000294,NameZh='永夜·幻影制裁',Icon='item_3000294',Type=250,MaxNum=99,SellPrice=100,AdventureSort=100013,AdventureValue=1,Condition=8,Desc='“银河流淌间，幻夜交叠去往未来的光影。”——此剑由遗落的神殿碎片制成，可以劈开星辰，唤醒编织光阴的魔法。',Feature=1,StageDisplay=0,LoadShowRotate=90,LoadShowPose={0,-0.2,0},}",
  [3000295] = "{id=3000295,NameZh='永夜·缄默彗星',Icon='item_3000295',Type=200,MaxNum=99,SellPrice=100,AdventureSort=100013,AdventureValue=1,Condition=8,Desc='“白昼沉默之际，星与月于混沌中诞生。”——星夜的瞭望者珍藏的宝物，有着温柔明亮的光辉。吸收了月影与星光制作而成的神器，也终将于夜幕中消散。',Feature=1,StageDisplay=0,LoadShowRotate=260,LoadShowPose={0,0.3,0},}",
  [3000296] = "{id=3000296,NameZh='永夜·沉寂月光',Icon='item_3000296',Type=210,MaxNum=99,SellPrice=100,AdventureSort=100013,AdventureValue=1,Condition=8,Desc='“黑暗降临时，唯一的光芒将照亮转换时空之门。”——传说中，此弓来自一位异世界的勇者。每当残月之时，他便会从天幕的彼端射下银箭，击穿吞食月光的夜狼。',Feature=1,StageDisplay=0,LoadShowRotate=270,LoadShowPose={0.2,0,-0.8},}",
  [3000297] = "{id=3000297,NameZh='永夜·放逐星辰',Icon='item_3000297',Type=220,MaxNum=99,SellPrice=100,AdventureSort=100013,AdventureValue=1,Condition=8,Desc='“流浪夜空下的旅人，终将化为天幕下的渺渺星辰。”——凝聚了夜之魔法，传说中由流星碎片打造而成的武器。它静静躺在森林深处的某地，等待有旅人经过将其唤醒。',Feature=1,StageDisplay=0,LoadShowRotate=80,LoadShowPose={0.2,-0.3,-0.4},}",
  [3000298] = "{id=3000298,NameZh='永夜·逐月之牙',Icon='item_3000298',Type=230,MaxNum=99,SellPrice=100,AdventureSort=100013,AdventureValue=1,Condition=8,Desc='“风中飘散的哀鸣，是月光奏响的静谧丧钟。”——以月光为熔料，风之贤者乔安亲手铸造而成的武器，最终他也丧身于这道寒光之下。',Feature=1,StageDisplay=0,LoadShowRotate=260,LoadShowPose={0.1,-0.3,-0.3},}",
  [3000299] = "{id=3000299,NameZh='永夜·流光祈祷',Icon='item_3000299',Type=510,MaxNum=99,SellPrice=100,AdventureSort=100013,AdventureValue=1,Condition=8,Desc='“夜天之下，月与繁星给予虔诚者祝福。”——每个月圆之夜，夜神的女儿亚斯兰娜都会在云端听取祷告，将星辉洒满整个大陆。某位铁匠将她散落的光芒收集，制作了这面盾牌。',Feature=1,StageDisplay=0,LoadShowRotate=350,LoadShowPose={0.2,0.1,-0.6},}",
  [3000300] = "{id=3000300,NameZh='永夜·天际遥望',Icon='item_3000300',Type=290,MaxNum=99,SellPrice=100,AdventureSort=100013,AdventureValue=1,Condition=8,Desc='“月光低喃之时，流星滑落天界，那是神的泪水。”——天空的守护者所拥有的武器。每当挥动它时，迸发出的能量可以击碎月光。',Feature=1,StageDisplay=0,LoadShowRotate=270,LoadShowPose={0,0.3,0},}",
  [3000301] = "{id=3000301,NameZh='永夜·璀璨银河',Icon='item_3000301',Type=270,MaxNum=99,SellPrice=100,AdventureSort=100013,AdventureValue=1,Condition=8,Desc='“星光所闪耀的，是被月亮潜藏的秘密。”——传奇的舞娘奥尔薇拉使用过的鞭子。相传她曾在月亮上起舞，足尖踏过之处皆成漫天繁星。',Feature=1,StageDisplay=0,LoadShowRotate=90,LoadShowPose={0,0.2,-0.2},}",
  [3000302] = "{id=3000302,NameZh='永夜·辉月咏叹',Icon='item_3000302',Type=260,MaxNum=99,SellPrice=100,AdventureSort=100013,AdventureValue=1,Condition=8,Desc='“闪耀天际的星辉，是月光恒久的礼赞。”——大祭司琳德亲手制作的乐器。以星屑为弦，弹奏出的乐音能让月色与星河流淌。',Feature=1,StageDisplay=0,LoadShowRotate=260,LoadShowPose={0.2,0.8,-0.4},}",
  [3000303] = "{id=3000303,NameZh='永夜·繁星颂歌',Icon='item_3000303',Type=240,MaxNum=99,SellPrice=100,AdventureSort=100013,AdventureValue=1,Condition=8,Desc='“祝福之音响彻夜空，荣耀属于碎星者。”——多年前，英雄泰瑞斯将偏离轨迹的流星击落，拯救了大陆。人们为了赞美他，以月光为墨记录了他的颂歌。',Feature=1,StageDisplay=0,LoadShowRotate=80,LoadShowPose={0,0.4,0.3},}",
  [3000304] = "{id=3000304,NameZh='大喵的祝福',Icon='item_3780',Type=30,MaxNum=99999,SellPrice=100,Desc='来自大喵的祝福，打开之后获得以下奖励的一种：「神秘箱子6.0」*1、「秘银」*3、「金质勋章」*1、「料理兑换券」*1、「锁链雷锭」*2、「莫拉硬币」*4、「神谕之晶」*1、「神谕之尘」*2、Zeny*51020，还有概率获赠活动限定面饰「一吻定情」*1。',Feature=1,}",
  [3000305] = "{id=3000305,NameZh='夏日甜蜜礼',Icon='item_12386',Type=61,UseMode=30012,MaxNum=99999,SellPrice=100,Desc='米德加尔特大陆的夏天，怎么能少的了清凉的夏装呢！使用之后可以打开「夏日甜蜜礼特别商店」，兑换清凉夏装！',Feature=1,}",
  [3000314] = "{id=3000314,NameZh='公主斗恶龙头饰兑换券·塔罗',Icon='item_3000314',Type=61,UseMode=30007,MaxNum=99999,SellPrice=100,Desc='使用之后可以兑换任意一件公主斗恶龙系列头饰哦~',Feature=1,}",
  [3000315] = "{id=3000315,NameZh='仲夏星之梦',Icon='item_3000315',Type=90,Quality=4,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000240}},Desc='它是来自遥远宝石之星的灵鸮，额上镶嵌着的每一颗欧泊都是神明的馈赠。羽翼划过云端的瞬间，远方的天幕便会有星辰闪烁。',Feature=1,TFValidDate='2019-06-24 05:00:00',ValidDate='2019-06-27 05:00:00',}",
  [3000316] = "{id=3000316,NameZh='仲夏月之光',Icon='item_3000316',Type=90,Quality=4,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000240}},Desc='绒雪般纯净洁白的羽翼，映照着月色飞往天空的彼岸。而随着风飘落的翎羽，将落入湖泊化作时光的珍珠。',Feature=1,TFValidDate='2019-06-24 05:00:00',ValidDate='2019-06-27 05:00:00',}",
  [3000317] = "{id=3000317,NameZh='蔷薇叙情诗',Icon='item_3000317',Type=800,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=15191,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='夜色中低语的蔷薇，沐浴着星屑点亮回忆的灯火。蝴蝶翩跹的刹那，原本寂静的时间再次流淌。',Feature=1,TFValidDate='2019-06-24 05:00:00',ValidDate='2019-06-27 05:00:00',LoadShowPose={0,0.4,0},}",
  [3000318] = "{id=3000318,NameZh='星月童话系列坐骑',Icon='item_3000315',Type=90,Quality=4,MaxNum=1,SellPrice=100,AdventureSort=1005,AdventureValue=100,AdventureReward={buffid={63000240}},Condition=8,Desc='绒雪般纯净洁白的羽翼，映照着月色飞往天空的彼岸。而随着风飘落的翎羽，将落入湖泊化作时光的珍珠。',NoStorage=1,Feature=1,TFValidDate='2019-06-24 05:00:00',ValidDate='2019-06-27 05:00:00',}",
  [3000320] = "{id=3000320,NameZh='流光独角兽[1]',Icon='item_3000320',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9639,AdventureValue=1,StorageReward={buffid={82000240}},Condition=8,Desc='踏着彩虹而来，象征着梦想和祝福的独角兽诺玛，在梦幻岛上是人见人爱的吉祥物。“每天在彩虹上走来走去，也是很冷的……阿、阿嚏！”',Feature=1,TFValidDate='2019-08-01 05:00:00',ValidDate='2019-08-01 05:00:00',}",
  [3000321] = "{id=3000321,NameZh='星月甜梦',Icon='item_3000321',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9640,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='由小女巫手工缝制，和独角兽诺玛一模一样的布娃娃抱枕。一经面世就深受梦幻岛少女们的喜爱，只要抱着它入睡，整个人的心情都会变好呢~',Feature=1,TFValidDate='2019-08-01 05:00:00',ValidDate='2019-08-01 05:00:00',}",
  [3000322] = "{id=3000322,NameZh='风铃叮当',Icon='item_3000322',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9641,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='“咦，秋莉，这个风铃好可爱，可以送给我吗？”“抱歉不行呢……”看到小女巫为难的模样，贴在墙上装作铃铛的小精灵叹了口气。',Feature=1,TFValidDate='2019-08-01 05:00:00',ValidDate='2019-08-01 05:00:00',}",
  [3000323] = "{id=3000323,NameZh='七彩心愿[1]',Icon='item_3000323',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9642,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='由彩虹编织而成，月光照耀出的独角兽头饰。蕴含着夜晚的力量，戴上它，心中思念的人就会出现在眼前。',Feature=1,TFValidDate='2019-08-01 05:00:00',ValidDate='2019-08-01 05:00:00',}",
  [3000324] = "{id=3000324,NameZh='光棱之翼',Icon='item_3000324',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9643,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='许多年前，岛的上空有一面巨大的棱镜，将天空的光芒折射成七色，这才有了彩虹。在彩虹的影响下，所有鸟儿的羽毛都变成了七彩的……',Feature=1,TFValidDate='2019-08-01 05:00:00',ValidDate='2019-08-01 05:00:00',}",
  [3000325] = "{id=3000325,NameZh='睡梦泡泡',Icon='item_3000325',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9644,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='存储着人们梦话的泡泡，一直藏在小女巫秋莉枕边的罐子里。结果有一天，罐子碎了……',Feature=1,TFValidDate='2019-08-01 05:00:00',ValidDate='2019-08-01 05:00:00',}",
  [3000326] = "{id=3000326,NameZh='恶作剧涂鸦',Icon='item_3000326',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9046,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='秋莉一觉醒来，照镜子时发现了脸上的奇怪涂鸦。小精灵啾啾扭捏再三后承认：“是我干的！谁让昨天某人说我胖了，还不给我肉吃！”',Feature=1,TFValidDate='2019-08-01 05:00:00',ValidDate='2019-08-01 05:00:00',}",
  [3000330] = "{id=3000330,NameZh='蔷薇夜曲·风',Icon='item_3000330',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000010}},Desc='在他的眼眸里，藏着无尽的夜色与月光的低语。',Feature=1,StageDisplay=0,MainColor='696ed8FF',}",
