  [3000350] = "{id=3000350,NameZh='夜之蔷的舞曲',Icon='item_3000350',Type=501,MaxNum=99,SellPrice=100,Desc='时光伴随着花瓣的凋零渐渐流逝，如今的花园里只剩下微风，在荒芜中讲述着百年前的故事。',Feature=1,StageDisplay=0,MainColor='56291eFF',}",
