  [3000379] = "{id=3000379,NameZh='刺玫心语系列头饰',Icon='item_3000379',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15193,AdventureValue=1,StorageReward={buffid={80012920}},Condition=8,Feature=1,StageDisplay=0,MainColor='X',}",
  [3000380] = "{id=3000380,NameZh='漆黑星辰',Icon='item_3000380',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15194,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='镶嵌着名贵黑曜石的华丽头冠，是伯爵家的祖传之物。如果将它戴在头上，所爱之人的身影便会出现在眼前。',Feature=1,StageDisplay=0,}",
  [3000381] = "{id=3000381,NameZh='月亮熊先生',Icon='item_3000381',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15195,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='熊先生本是个不会说话的布偶，少女用月光赋予了它生命。但在许多年后，它却望着伯爵窗前的玫瑰流下了泪水。',Feature=1,StageDisplay=0,}",
  [3000382] = "{id=3000382,NameZh='猫头鹰执事',Icon='item_3000382',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15196,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='猫头鹰海德威是古堡的管家，从伯爵记事起就陪伴在他身边。“伯爵大人很温柔，但也很孤独。除了那朵玫瑰花，他什么也不喜欢……”',Feature=1,StageDisplay=0,}",
  [3000383] = "{id=3000383,NameZh='迷梦之蝶',Icon='item_3000383',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15197,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='夜晚的森林里，蝴蝶的羽翼指引着迷路的旅人，将他引入下一个失落的梦境。',Feature=1,StageDisplay=0,}",
  [3000384] = "{id=3000384,NameZh='荆棘之爱',Icon='item_3000384',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15198,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='在黎明来临前，她将变回园中唯一的一朵玫瑰，将寂静的爱埋入星光。',Feature=1,StageDisplay=0,}",
  [3000385] = "{id=3000385,NameZh='星夜蔷薇头饰兑换券',Icon='item_3000385',Type=61,UseMode=30008,MaxNum=99999,SellPrice=100,Desc='使用之后可以兑换任意一件星夜蔷薇系列头饰哦~',Feature=1,}",
  [3000390] = "{id=3000390,NameZh='星音淼淼·清泉',Icon='item_3000390',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='“唔——唔——”“我都这么用力的吹号角了，可是为什么人鱼还是没有出现呢，难道妈妈是骗我的么？”“哇！那是……人鱼！”“你别走！！我我我……对着星星发誓，我不会伤害你的。”“你你…你叫什么名字？”“阿…多…尼…斯”“你可真漂亮，我可以亲亲你么？”星空下，人鱼看着小男孩期待的眼神点了点头。',Feature=1,TFValidDate='2019-10-14 05:00:00',ValidDate='2019-10-17 05:00:00',MainColor='20c7e5FF',}",
  [3000391] = "{id=3000391,NameZh='星音淼淼·响流',Icon='item_3000390',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='“唔——唔——”“我都这么用力的吹号角了，可是为什么人鱼还是没有出现呢，难道妈妈是骗我的么？”“哇！那是……人鱼！”“你别走！！我我我……对着星星发誓，我不会伤害你的。”“你你…你叫什么名字？”“阿…多…尼…斯”“你可真漂亮，我可以亲亲你么？”星空下，人鱼看着小男孩期待的眼神点了点头。',Feature=1,TFValidDate='2019-10-14 05:00:00',ValidDate='2019-10-17 05:00:00',MainColor='f8aad5FF',}",
