  [3000400] = "{id=3000400,NameZh='月光鳞鳞·清泉',Icon='item_3000400',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='年幼的小人鱼被好奇心唆使，一个人偷偷的游到了岸边，借着月光他看到了一个卖力吹着号角的人类小孩，或许是小男孩的样子太过滑稽，小人鱼一时竟忘记了父母的告诫主动靠近了小男孩，小男孩发现了小人鱼，紧张兮兮的说了一大堆话，小人鱼看着小男孩清澈的双眼，不自觉的同意了他的亲吻请求，月光下，小人鱼的尾巴似乎变成了粉色。',Feature=1,TFValidDate='2019-10-14 05:00:00',ValidDate='2019-10-17 05:00:00',MainColor='20c7e5FF',}",
  [3000401] = "{id=3000401,NameZh='月光鳞鳞·响流',Icon='item_3000400',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='年幼的小人鱼被好奇心唆使，一个人偷偷的游到了岸边，借着月光他看到了一个卖力吹着号角的人类小孩，或许是小男孩的样子太过滑稽，小人鱼一时竟忘记了父母的告诫主动靠近了小男孩，小男孩发现了小人鱼，紧张兮兮的说了一大堆话，小人鱼看着小男孩清澈的双眼，不自觉的同意了他的亲吻请求，月光下，小人鱼的尾巴似乎变成了粉色。',Feature=1,TFValidDate='2019-10-14 05:00:00',ValidDate='2019-10-17 05:00:00',MainColor='f8aad5FF',}",
