  [3000403] = "{id=3000403,NameZh='月光鳞鳞·暖阳',Icon='item_3000400',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='年幼的小人鱼被好奇心唆使，一个人偷偷的游到了岸边，借着月光他看到了一个卖力吹着号角的人类小孩，或许是小男孩的样子太过滑稽，小人鱼一时竟忘记了父母的告诫主动靠近了小男孩，小男孩发现了小人鱼，紧张兮兮的说了一大堆话，小人鱼看着小男孩清澈的双眼，不自觉的同意了他的亲吻请求，月光下，小人鱼的尾巴似乎变成了粉色。',Feature=1,TFValidDate='2019-10-14 05:00:00',ValidDate='2019-10-17 05:00:00',MainColor='221c19FF',}",
  [3000404] = "{id=3000404,NameZh='深海恋歌系列时装',Icon='item_3000404',Type=501,MaxNum=99,SellPrice=100,AdventureSort=15209,AdventureValue=1,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Condition=8,Feature=1,TFValidDate='2019-10-14 05:00:00',ValidDate='2019-10-17 05:00:00',MainColor='X',}",
  [3000405] = "{id=3000405,NameZh='深海恋歌时装碎片',Icon='item_3000405',Type=61,UseMode=4027,MaxNum=99999,SellPrice=100,Desc='5个深海恋歌时装碎片可以在弗雷硬币商店兑换深海恋歌系列时装哦~',Feature=1,}",
  [3000406] = "{id=3000406,NameZh='深海恋歌时装兑换券',Icon='item_3000406',Type=121,MaxNum=99999,SellPrice=100,ComposeID=4000014,Desc='使用之后可以获得一件对应阁下性别的深海恋歌系列时装哦~',Feature=1,}",
  [3000430] = "{id=3000430,NameZh='聆音岚星',Icon='item_3000430',Type=90,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000240}},Desc='在海洋深处的裂缝中居住着一种十分强大的生物，它有着锋利的独角和强有力的尾鳍，所到之处连海妖都要避让，强大的种族总会引来人类的觊觎，许多贪婪的水手都妄想捕获它，只不过下场嘛……',Feature=1,TFValidDate='2019-10-14 05:00:00',ValidDate='2019-10-17 05:00:00',}",
  [3000431] = "{id=3000431,NameZh='听风皎月',Icon='item_3000431',Type=90,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000240}},Desc='在深海中，万年才能孕育出一只听风皎月，它是深海的宠儿，一出生就象征着王权和力量，是海洋中食物链顶端的存在，传说，在满月之夜，曾有水手看到一独角巨兽，踏浪而上直冲云霄，跨越海洋和天空，它是真正的王者。',Feature=1,TFValidDate='2019-10-14 05:00:00',ValidDate='2019-10-17 05:00:00',}",
  [3000432] = "{id=3000432,NameZh='驭海蛟龙系列坐骑',Icon='item_3000430',Type=90,Quality=4,MaxNum=1,SellPrice=100,AdventureSort=1009,AdventureValue=100,AdventureReward={buffid={63000240}},Condition=8,Desc='是海的宠儿，是王的象征，是星与月的化身，是踏浪而上直冲云霄的光影！',NoStorage=1,Feature=1,TFValidDate='2019-10-14 05:00:00',ValidDate='2019-10-17 05:00:00',}",
  [3000440] = "{id=3000440,NameZh='无垠星河·清泉',Icon='item_3000440',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='小人鱼想下次见面的时候送小男孩一个礼物，可是，送什么好呢？小人鱼抬头看着浩瀚的星空，随即像是想到了什么，潜入到深海取来了许多星空石，星辰交织的王冠，他一定会喜欢。小人鱼信心满满的想着。',Feature=1,TFValidDate='2019-10-14 05:00:00',ValidDate='2019-10-17 05:00:00',LoadShowSize=2,LoadShowPose={0,0.5,0},MainColor='20c7e5FF',}",
  [3000441] = "{id=3000441,NameZh='无垠星河·响流',Icon='item_3000440',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='小人鱼想下次见面的时候送小男孩一个礼物，可是，送什么好呢？小人鱼抬头看着浩瀚的星空，随即像是想到了什么，潜入到深海取来了许多星空石，星辰交织的王冠，他一定会喜欢。小人鱼信心满满的想着。',Feature=1,TFValidDate='2019-10-14 05:00:00',ValidDate='2019-10-17 05:00:00',LoadShowSize=2,LoadShowPose={0,0.5,0},MainColor='f8aad5FF',}",
