  [3000444] = "{id=3000444,NameZh='无垠星河系列头饰',Icon='item_3000444',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15201,AdventureValue=1,StorageReward={buffid={80012930}},Condition=8,Feature=1,TFValidDate='2019-10-14 05:00:00',ValidDate='2019-10-17 05:00:00',MainColor='X',}",
  [3000445] = "{id=3000445,NameZh='皎月礼赞·清泉',Icon='item_3000445',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='小男孩一直念念不忘小人鱼，但是之后小人鱼却再也没有出现。他可能是被我吓到了，下次见面我要送他一个礼物，这样他就不会害怕我了，小男孩一边弯腰捡着礁石上的月光石一边小声嘟囔着。',Feature=1,TFValidDate='2019-10-14 05:00:00',ValidDate='2019-10-17 05:00:00',LoadShowSize=2,LoadShowPose={0,0.5,0},MainColor='20c7e5FF',}",
  [3000446] = "{id=3000446,NameZh='皎月礼赞·响流',Icon='item_3000445',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='小男孩一直念念不忘小人鱼，但是之后小人鱼却再也没有出现。他可能是被我吓到了，下次见面我要送他一个礼物，这样他就不会害怕我了，小男孩一边弯腰捡着礁石上的月光石一边小声嘟囔着。',Feature=1,TFValidDate='2019-10-14 05:00:00',ValidDate='2019-10-17 05:00:00',LoadShowSize=2,LoadShowPose={0,0.5,0},MainColor='f8aad5FF',}",
  [3000447] = "{id=3000447,NameZh='皎月礼赞·涟漪',Icon='item_3000445',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='小男孩一直念念不忘小人鱼，但是之后小人鱼却再也没有出现。他可能是被我吓到了，下次见面我要送他一个礼物，这样他就不会害怕我了，小男孩一边弯腰捡着礁石上的月光石一边小声嘟囔着。',Feature=1,TFValidDate='2019-10-14 05:00:00',ValidDate='2019-10-17 05:00:00',LoadShowSize=2,LoadShowPose={0,0.5,0},MainColor='696ed8FF',}",
  [3000448] = "{id=3000448,NameZh='皎月礼赞·暖阳',Icon='item_3000445',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='小男孩一直念念不忘小人鱼，但是之后小人鱼却再也没有出现。他可能是被我吓到了，下次见面我要送他一个礼物，这样他就不会害怕我了，小男孩一边弯腰捡着礁石上的月光石一边小声嘟囔着。',Feature=1,TFValidDate='2019-10-14 05:00:00',ValidDate='2019-10-17 05:00:00',LoadShowSize=2,LoadShowPose={0,0.5,0},MainColor='d9942eFF',}",
  [3000449] = "{id=3000449,NameZh='皎月礼赞系列头饰',Icon='item_3000449',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15202,AdventureValue=1,StorageReward={buffid={80012920}},Condition=8,Feature=1,TFValidDate='2019-10-14 05:00:00',ValidDate='2019-10-17 05:00:00',MainColor='X',}",
  [3000450] = "{id=3000450,NameZh='忆海冰冠',Icon='item_3000450',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15203,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='海洋是有记忆的，海洋中漂浮的蓝色晶末都是它的记忆碎片，晶末汇聚凝结，最终形成了这个冰冠，它记录了小男孩和小人鱼的初遇，记录了少年和鲛人的誓言，记录了…海洋中所有发生的故事。',Feature=1,TFValidDate='2019-10-14 05:00:00',ValidDate='2019-10-17 05:00:00',LoadShowSize=2,LoadShowPose={0,0.7,0},}",
  [3000451] = "{id=3000451,NameZh='眷海之声',Icon='item_3000451',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15204,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='小男孩拿着妈妈给他的海螺号角，期待的跑到海边卖力的吹响，声音虽然不大，但是却跨越了千里，跨越了陆地和海洋的距离，是的，小人鱼听到了。',Feature=1,TFValidDate='2019-10-14 05:00:00',ValidDate='2019-10-17 05:00:00',LoadShowSize=4,LoadShowPose={0,0.7,0},}",
  [3000452] = "{id=3000452,NameZh='潮汐冰戟',Icon='item_3000452',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15205,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='潮起潮落，波涛翻转，所有的海域都受冰戟的控制，它是人鱼一族代代相传的王权的象征。不过，海中的王者又怎样，和你相比，它只不过是一把冷冰冰的武器罢了。',Feature=1,TFValidDate='2019-10-14 05:00:00',ValidDate='2019-10-17 05:00:00',LoadShowSize=1.2,LoadShowPose={0,0.2,0},}",
  [3000453] = "{id=3000453,NameZh='鲛人泪',Icon='item_3000453',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15206,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='鲛人的眼泪会化成价值连城的珍珠，但是，我却舍不得你哭泣，我只想看到你如花般的笑颜。不顾数量众多的敌人，少年毅然的挡在鲛人的面前，眼神坚定的说道。',Feature=1,TFValidDate='2019-10-14 05:00:00',ValidDate='2019-10-17 05:00:00',LoadShowSize=3,LoadShowPose={0,0.2,0},}",
  [3000454] = "{id=3000454,NameZh='月夜鲛姬',Icon='item_3000454',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15207,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='传说在月圆之夜，美丽的鲛人会出现在礁石边歌唱，美妙的声音会迷惑路过的谁说，但这些只是人类的讹传罢了，实际上，鲛人是想给自己心爱的人引路，希望对方能跟随歌声找到自己，继续抒写那段爱的篇章。',Feature=1,TFValidDate='2019-10-14 05:00:00',ValidDate='2019-10-17 05:00:00',LoadShowSize=2,}",
  [3000455] = "{id=3000455,NameZh='驭海小白蛟',Icon='item_3000455',Type=840,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=15208,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='“嗷呜，嗷呜，别看我个子小就觉得我好欺负！小白蛟我可是海中的王者，就连凶猛的海怪见到我都要躲起来！……哎……那…那是什么？！海怪啊！！！嗷呜~嗷呜~救命啊！！！”',Feature=1,TFValidDate='2019-10-14 05:00:00',ValidDate='2019-10-17 05:00:00',LoadShowSize=2,}",
  [3000456] = "{id=3000456,NameZh='深海恋歌头饰兑换券·塔罗',Icon='item_3000456',Type=61,UseMode=30018,MaxNum=99999,SellPrice=100,Desc='使用之后可以兑换任意一件深海恋歌系列头饰哦~',Feature=1,}",
  [3000460] = "{id=3000460,NameZh='迷离星途',Icon='item_3000460',Type=810,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9645,AdventureValue=1,StorageReward={buffid={82000250}},Condition=8,Desc='以灵魂为烛火，月石雕刻而成的宝石灯。里面燃烧着的紫色星辰，是无数生灵命运的指针。',Feature=1,TFValidDate='2019-09-01 05:00:00',ValidDate='2019-09-01 05:00:00',}",
  [3000461] = "{id=3000461,NameZh='时光欧珀[1]',Icon='item_3000461',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9646,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='占星师莱欧娜的宝石头冠，用魔法凝聚着闪闪发光的欧珀。这都是被占卜的人们给她的谢礼，凝聚了无数魂魄的时间。',Feature=1,TFValidDate='2019-09-01 05:00:00',ValidDate='2019-09-01 05:00:00',}",
  [3000462] = "{id=3000462,NameZh='月光预言[1]',Icon='item_3000462',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9647,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='“要信仰月亮。月的光芒照耀不到的地方，是灵魂的归所。”',Feature=1,TFValidDate='2019-09-01 05:00:00',ValidDate='2019-09-01 05:00:00',}",
  [3000463] = "{id=3000463,NameZh='铭刻时光之印',Icon='item_3000463',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9648,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='“时光凝刻于我的额间。对于通晓未来之人，没有什么是永恒。”',Feature=1,TFValidDate='2019-09-01 05:00:00',ValidDate='2019-09-01 05:00:00',}",
  [3000464] = "{id=3000464,NameZh='灵魂塔罗',Icon='item_3000464',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9649,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='莱欧娜用水晶制作成的塔罗牌。由于她的占卜已接近于神谕，每使用一次，都会加剧她生命的消逝。',Feature=1,TFValidDate='2019-09-01 05:00:00',ValidDate='2019-09-01 05:00:00',}",
  [3000465] = "{id=3000465,NameZh='幻梦占星师',Icon='item_3000465',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9650,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='“不必悲伤。人类的命运都是天上的星辰，陨落与闪耀都早已既定。”',Feature=1,TFValidDate='2019-09-01 05:00:00',ValidDate='2019-09-01 05:00:00',}",
  [3000466] = "{id=3000466,NameZh='黑曜星辰',Icon='item_3000466',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9047,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='星星是逃避者。它们躲开云和太阳，与月光拥抱黑暗。',Feature=1,TFValidDate='2019-09-01 05:00:00',ValidDate='2019-09-01 05:00:00',}",
  [3000470] = "{id=3000470,NameZh='丘林潇客·凝神',Icon='item_3000470',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='丘林中，葱白的鹿角尖含着温暖的呼气出现在晨曦中，一只白尾鹿悄然地出现在林间小路中，青年猎手的身影犹如迅捷的野兽，目光灼灼的盯着前方的白尾鹿，屏住呼吸，起手拉弓，动作一气呵成，作为斐扬城最优秀的猎手，青年射出的每一支箭都是百发百中，但是，他不知道的是，这支箭将会是开启那段尘封记忆的钥匙……',Feature=1,TFValidDate='2019-08-12 05:00:00',ValidDate='2019-08-15 05:00:00',MainColor='395923FF',}",
  [3000471] = "{id=3000471,NameZh='丘林潇客·搭箭',Icon='item_3000470',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='丘林中，葱白的鹿角尖含着温暖的呼气出现在晨曦中，一只白尾鹿悄然地出现在林间小路中，青年猎手的身影犹如迅捷的野兽，目光灼灼的盯着前方的白尾鹿，屏住呼吸，起手拉弓，动作一气呵成，作为斐扬城最优秀的猎手，青年射出的每一支箭都是百发百中，但是，他不知道的是，这支箭将会是开启那段尘封记忆的钥匙……',Feature=1,TFValidDate='2019-08-12 05:00:00',ValidDate='2019-08-15 05:00:00',MainColor='870c0cFF',}",
