  [3000480] = "{id=3000480,NameZh='林深见鹿·馥郁',Icon='item_3000480',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='林深时见鹿，海深时见鲸，梦醒时见你，我是白鹿你为清泉，我愿为你许下最好的愿景，即使童年的记忆你早已忘却，但是我却仍然记得你，记得你身上淡淡的青草香，记得你笑起来弯弯的眉眼，记得你温柔的对我诉说着你对未来的憧憬，记得所有我们在一起的时光……',Feature=1,TFValidDate='2019-08-12 05:00:00',ValidDate='2019-08-15 05:00:00',MainColor='395923FF',}",
