  [3000500] = "{id=3000500,NameZh='枭鹰羽冠·凝神',Icon='item_3000500',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='在斐扬城，只有最优秀的猎手才有资格佩戴的枭鹰羽冠，它是荣耀和实力的象征，是所有斐扬青年都梦寐以求的东西，但同时它也是枷锁，戴上它就要肩负支撑整个斐扬城的责任。',Feature=1,TFValidDate='2019-08-12 05:00:00',ValidDate='2019-08-15 05:00:00',LoadShowSize=2,LoadShowPose={0,0.4,0},MainColor='395923FF',}",
