  [3000505] = "{id=3000505,NameZh='鹿角吟吟·馥郁',Icon='item_3000505',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='少年与白鹿一同靠坐在树下欣赏着夕阳的余韵，白鹿放松的合上了双眼，少年以为白鹿睡着了，伸出手指偷偷的摸了摸白鹿的身子，见白鹿没有反应，少年便胆子大了起来伸手抚上了白鹿的鹿角，得偿所愿的少年偏过头窃喜的笑着，在少年看不到的地方，白鹿轻轻眨了眨双眼……',Feature=1,TFValidDate='2019-08-12 05:00:00',ValidDate='2019-08-15 05:00:00',LoadShowSize=2,LoadShowPose={0,0.5,0},MainColor='a86b12FF',}",
