  [3000509] = "{id=3000509,NameZh='鹿角吟吟系列头饰',Icon='item_3000509',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15212,AdventureValue=1,StorageReward={buffid={80012920}},Condition=8,Feature=1,TFValidDate='2019-08-12 05:00:00',ValidDate='2019-08-15 05:00:00',MainColor='X',}",
  [3000510] = "{id=3000510,NameZh='森之魂',Icon='item_3000510',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15213,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='“不要再伤害我的孩子们了，它们什么都没有做错，求求你救救它们，它们只是想活下去”“你是？”“我是这片森林，求求你阻止那些人类不要再肆意狩猎了，我愿意把全部的力量交给你，只要你能救救那些孩子……”“好…我一定会代替你守护这片森林”',Feature=1,TFValidDate='2019-08-12 05:00:00',ValidDate='2019-08-15 05:00:00',LoadShowSize=2,LoadShowPose={0,0.6,0},}",
  [3000511] = "{id=3000511,NameZh='枭鹰星翼',Icon='item_3000511',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15214,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='“儿子，父亲把这个交给你，从今天开始，你就是所有狩猎者的领袖！你要肩负起这个责任啊”“父亲……我们可不可以不打猎了…”“狩猎是我们斐扬的传统！我们是雄鹰的后人，是天生的狩猎者！这种话我不想再听到！！！”“…我明白了，父亲”',Feature=1,StageDisplay=0,LoadShowSize=2,LoadShowPose={0.4,0.2,-0.5},}",
  [3000512] = "{id=3000512,NameZh='爬娜娜',Icon='item_3000512',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15215,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='“爬娜娜！爬娜娜！爬娜娜万岁！”“！”“爬！爬娜娜！我要爬娜娜！！！”',Feature=1,TFValidDate='2019-08-12 05:00:00',ValidDate='2019-08-15 05:00:00',LoadShowSize=2,LoadShowRotate=180,LoadShowPose={0,0.5,0},}",
  [3000513] = "{id=3000513,NameZh='虎虎生威',Icon='item_3000513',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15216,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='“嗷呜！嗷呜！我虎宝是这片山林的王者！什么狩猎者，什么斐扬城，你们都给本大王让开！”“喂喂喂！你你……你别揪我耳朵，疼疼疼……”',Feature=1,TFValidDate='2019-08-12 05:00:00',ValidDate='2019-08-15 05:00:00',LoadShowSize=2,LoadShowPose={0,0.1,0},}",
  [3000514] = "{id=3000514,NameZh='鹿尾鸢',Icon='item_3000514',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15217,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='“这…这个…是给我的么？”少年看着眼前的白鹿受宠若惊的说道，白鹿颔首把花朵放在了少年的手心，随后伸出头舌头轻轻舔抵着少年的脸颊，少年害羞的红了脸，微风拂过，嗯……是春天的味道。',Feature=1,TFValidDate='2019-08-12 05:00:00',ValidDate='2019-08-15 05:00:00',LoadShowSize=3,LoadShowPose={0,0.7,0},}",
  [3000515] = "{id=3000515,NameZh='森空鹿谣头饰兑换券·塔罗',Icon='item_3000515',Type=61,UseMode=30010,MaxNum=99999,SellPrice=100,Desc='使用之后可以兑换任意一件森空鹿谣系列头饰哦~',Feature=1,}",
  [3000516] = "{id=3000516,NameZh='熠光白枭',Icon='item_3000516',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15220,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='白玉般骨制的弓身，抚上去时会带有丝丝的凉意，在阳光下，弓身和箭羽会折射出异样的光芒，它是所有猎手们的梦寐以求之物。',Feature=1,TFValidDate='2019-08-12 05:00:00',ValidDate='2019-08-15 05:00:00',LoadShowSize=1.5,LoadShowPose={0,0.5,0},}",
  [3000517] = "{id=3000517,NameZh='耀光',Icon='item_3000517',Type=90,Quality=4,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000240}},Desc='传说中光明之神巴德尔的爱宠耀光，它是光辉与美丽的化身，为人类带来春天与喜悦，它热爱万物，其中最热爱人类，时常与人类的少女嬉戏玩耍而忘记了回到神殿的时间，这点让巴德尔很头疼，但是无辜的外表和爱撒娇的品性总是让它可以逃过巴德尔的责骂。',Feature=1,TFValidDate='2019-08-12 05:00:00',ValidDate='2019-08-15 05:00:00',LoadShowSize=0.6,LoadShowPose={0,-0.4,0},}",
  [3000518] = "{id=3000518,NameZh='月影',Icon='item_3000518',Type=90,Quality=4,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000240}},Desc='黑暗之神霍尔德尔和光明之神巴德尔是一对兄弟，不同于光辉圣洁的兄长，霍尔德尔是一个阴沉，忧郁而寡言的人，至始至终他的身边都只有月影陪伴着它，只有在看见月影的时候，这位伟大的黑暗之神才会展露出一丝难得的笑意。',Feature=1,TFValidDate='2019-08-12 05:00:00',ValidDate='2019-08-15 05:00:00',LoadShowSize=0.6,LoadShowPose={0,-0.4,0},}",
  [3000519] = "{id=3000519,NameZh='鹿骨翎羽',Icon='item_3000519',Type=210,Quality=4,MaxNum=99,SellPrice=100,Desc='鹿骨弓是所有的斐扬猎手都梦寐以求的东西，以白鹿骨作弓身，以鹿尾毛作弓弦，弓弦微动，箭羽如流星般射出直击猎物的心脏一击毙命，猎物没有任何逃脱的可能。',Feature=1,TFValidDate='2019-08-12 05:00:00',ValidDate='2019-08-15 05:00:00',LoadShowSize=1,LoadShowRotate=50,LoadShowPose={0,0.2,0},}",
  [3000520] = "{id=3000520,NameZh='逃学大王帽图纸',Icon='item_3031520',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=3000520,Desc='“哟，想和我们一起搞点大事吗？来加入逃学社吧！”逃学社社长卡卡亲手设计的帽子，只赠送给被他认可的人类。但被多咪施加了整蛊魔法，佩戴时需要小心哦。',Feature=1,}",
  [3000521] = "{id=3000521,NameZh='飞行的智慧图纸',Icon='item_3031521',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=3000521,Desc='“感受它们的凝视，让你的上课效率提高99%。”——最光辉伟大的狸猫校长 奥利姆·冯·沃泰利海勒',Feature=1,}",
  [3000522] = "{id=3000522,NameZh='狸猫典藏宝箱',Icon='item_3000522',Type=30,MaxNum=99999,SellPrice=100,Desc='逃学社社长卡卡从校长那里偷来的大箱子。据说校长知道后，气得罚他洗了一个月臭袜子。里头除了期末考试的答案之外，还装了很多实用的宝贝。\n开启后获得「狸猫校徽」*80，并随机获赠以下道具中的一种：「祈祷晶片包」*2、「莫拉硬币」*4、「玛斯黛拉种子」*1、「金质勋章」*2、「来自女武神的馈赠」*2。',Feature=1,}",
  [3000523] = "{id=3000523,NameZh='狸猫校徽',Icon='item_3000523',Type=61,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='（注：只有野外掉落的徽章计入获取上限）\n小小一枚校徽，浓缩了幻术学园的百年历史，是狸猫们骄傲与荣誉的象征。收集到一定数量也许会发生什么好事……\n使用后开启狸猫幻术学校卖品部商店，兑换各类实用道具！',GetLimit={limit={[999]={200,0}},source={22},type=1},ExistTimeType=2,ExistTime='2020-08-10 05:00:00',}",
  [3000524] = "{id=3000524,NameZh='狸猫幻术药水',Icon='item_3000524',Type=41,MaxNum=99999,SellPrice=100,Desc='学园里每只小狸猫都需要会制作的魔力药水，如果把它们交给幻术老师弗兰，没准可以抵消违反校规的次数。\n使用后在1小时内野外击杀魔物获得的Base经验和Job经验翻倍~（死亡及非战斗状态下消耗Buff时长，离线状态不消耗Buff时长）',}",
  [3000525] = "{id=3000525,NameZh='幻术大作战礼包',Icon='item_3000525',Type=30,MaxNum=99999,SellPrice=100,Feature=1,}",
  [3000526] = "{id=3000526,NameZh='放课补助礼包',Icon='item_3000526',Type=30,MaxNum=99999,SellPrice=100,Feature=1,}",
  [3000527] = "{id=3000527,NameZh='狸猫校舍',Icon='item_3000527',Type=610,MaxNum=99999,SellPrice=100,Desc='狸猫学生们的校舍，外形可爱有趣，但其实是见证了许多历史的古老建筑物。',Feature=4,}",
  [3000528] = "{id=3000528,NameZh='损坏的狸猫校舍',Icon='item_3000528',Type=610,MaxNum=99999,SellPrice=100,Desc='被顽皮的逃学社学生和狸猫猎人们破坏掉的校舍。校长奥利姆急得团团转，委托学生会长布鲁鲁四处募资修复校舍。',Feature=4,}",
  [3000530] = "{id=3000530,NameZh='星璇夜曲',Icon='item_3000530',Type=850,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9651,AdventureValue=1,StorageReward={buffid={82000250}},Condition=8,Desc='以星与月亮为原型制造的珐琅耳机，是黑猫露露最喜爱的物品。佩戴后会听到神秘的歌谣，据说这就是星空的旋律。',Feature=1,TFValidDate='2019-11-01 05:00:00',ValidDate='2019-11-01 05:00:00',LoadShowSize=3,LoadShowPose={0,0.4,0},}",
  [3000531] = "{id=3000531,NameZh='摇曳月光',Icon='item_3000531',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9652,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='月亮哼着歌睡在天上，夜晚来临了。她的影子随着星星落在人间，便幻化成了一只小黑猫。每当白昼将至，黑猫便会踏着月光回到云端，等待新的夜晚来临。',Feature=1,TFValidDate='2019-11-01 05:00:00',ValidDate='2019-11-01 05:00:00',LoadShowSize=2,LoadShowPose={0,0.4,0},}",
  [3000532] = "{id=3000532,NameZh='旋转梦境[1]',Icon='item_3000532',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9653,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='“一只、两只、三只……数了这么久，为什么还是睡不着啦！”其实每次失眠数羊的时候，真的会有小羊在头上转圈圈哦！只是普通人看不到而已……',Feature=1,TFValidDate='2019-11-01 05:00:00',ValidDate='2019-11-01 05:00:00',LoadShowSize=2,LoadShowPose={0,0.4,0},}",
  [3000533] = "{id=3000533,NameZh='沉梦编织[1]',Icon='item_3000533',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9654,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='梦精灵安琪用云朵与棉花糖织成的睡帽，绣上的每一颗小星星都会变成一个美梦。“愿你每天都能梦见思念的人！”',Feature=1,TFValidDate='2019-11-01 05:00:00',ValidDate='2019-11-01 05:00:00',LoadShowSize=2,LoadShowPose={0,0.8,0},}",
  [3000534] = "{id=3000534,NameZh='瞌睡喵的呼噜',Icon='item_3000534',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9655,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='依照黑猫露露为原型设计的睡眠眼罩。只要一戴上就会陷入沉睡，是治疗失眠的不二之选。',Feature=1,TFValidDate='2019-11-01 05:00:00',ValidDate='2019-11-01 05:00:00',LoadShowSize=3,LoadShowPose={0,0.4,0},}",
  [3000535] = "{id=3000535,NameZh='银河梦游',Icon='item_3000535',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9656,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='每个夜晚，兔先生都会划着月亮船出行，在天幕的最东边洒下星尘。每粒星尘都是孩子们梦想的化身，而它们汇集在一起，就成了漫漫银河。',Feature=1,TFValidDate='2019-11-01 05:00:00',ValidDate='2019-11-01 05:00:00',LoadShowSize=2,LoadShowPose={0,0.4,0},}",
  [3000536] = "{id=3000536,NameZh='夜光魔法',Icon='item_3000536',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9048,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='黑猫露露用月亮和星辰的碎片做出的小夜灯，闪烁着温柔的光辉。安琪每天会点着它在孩子们的枕边守候，直到他们一一入眠。',Feature=1,TFValidDate='2019-11-01 05:00:00',ValidDate='2019-11-01 05:00:00',LoadShowSize=2,}",
  [3000540] = "{id=3000540,NameZh='符文礼盒',Icon='item_3681',Type=30,MaxNum=99999,SellPrice=100,Desc='打开之后必定获得「黯淡的符文石」*2，有概率获赠「光洁的符文石」*1，需要在6.0上线之后才可以打开哦~',Feature=1,}",
  [3000541] = "{id=3000541,NameZh='真命之爱福袋',Icon='item_3707',Type=30,MaxNum=99999,SellPrice=100,Desc='打开之后必定获得「来自公会的馈赠」*10、「祈祷晶片包」*2、「金质勋章」*2',Feature=1,}",
  [3000542] = "{id=3000542,NameZh='幸福之心礼包',Icon='item_6076',Type=30,MaxNum=99999,SellPrice=100,Desc='打开之后必定获得「放大镜」*3、「黯淡的符文石」*1、「光洁的符文石」*1、「闪耀的符文石」*1、「古旧的符文箱」*2，有概率获赠本职业S级符文。仅限二转以上职业开启。',Feature=1,}",
  [3000543] = "{id=3000543,NameZh='爱神的献礼',Icon='item_700012',Type=75,MaxNum=99999,SellPrice=100,Desc='爱神菲尔带给米德加尔特大陆的礼物~将它赠送给你喜欢的人，你和TA都可以获得「爱神的祝福」*10以及「甜蜜心意」增益效果。因为爱神的力量有限，所以只可以对同世界线的好友使用哦~',ItemTarget={range=10,type=1},Feature=1,}",
  [3000544] = "{id=3000544,NameZh='爱神的礼物',Icon='item_700012',Type=30,MaxNum=99999,SellPrice=100,Desc='特殊的人送给你的礼物，打开可以获得「爱神的祝福」*10以及「甜蜜心意」增益效果。',}",
  [3000545] = "{id=3000545,NameZh='坐骑折扣券',Icon='item_3000545',Type=61,UseMode=30011,MaxNum=99999,SellPrice=100,Desc='使用之后可以打开「特惠坐骑商城」，以更低的价格购入心仪的坐骑哦~',Feature=1,}",
  [3000550] = "{id=3000550,NameZh='希莎娅的感谢礼盒',Icon='item_3877',Type=30,MaxNum=99999,SellPrice=100,Desc='为感谢你对料理大赛顺利举行所作出的帮助，希莎娅决定赠送这份礼物给你。\n开启后必定获得「庆典美食券」*50，并随机获赠以下道具中的一种：「尘封的符文袋·Ⅰ」*2、「祈祷晶片包」*2、「金质勋章」*2、「来自女武神的馈赠」*2、「玛斯黛拉种子」*1、「料理兑换券」*2。',Feature=1,}",
  [3000551] = "{id=3000551,NameZh='庆典美食券',Icon='item_3000551',Type=61,MaxNum=99999,AuctionPrice=1,SellPrice=10,Desc='料理协会在大赛期间向全民发放的礼券，请冒险者们纵享美食福利！\n使用后可打开本期活动兑换商店。',ExistTimeType=2,ExistTime='2020-08-10 05:00:00',}",
  [3000552] = "{id=3000552,NameZh='鱼子酱寿司图纸',Icon='item_3031552',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=3000552,Desc='河豚老板料理店的招牌美食！松软的米饭外加满满的鱼子酱，一口下去让你绝对的满足。咕噜噜~咕噜噜~完了！我的肚子在叫嚣了！',Feature=1,}",
  [3000553] = "{id=3000553,NameZh='河豚料理师图纸',Icon='item_3031553',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=3000553,Desc='河豚老板是大陆上最有名的日式料理师，每个尝过它料理的人再吃别的食物都觉得索然无味，不过，要记住千万不要在他面前提到河豚刺身，否则……',Feature=1,}",
  [3000554] = "{id=3000554,NameZh='B型能量装置',Icon='item_3000554',Type=77,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=111,AdventureValue=1,StorageReward={buffid={82000110}},Condition=8,Desc='沃尔金玩具公司最新研发的玩具，据说浓缩了18种食材的精华，使用后让你的美食小宇宙熊熊燃烧！',Feature=1,TFValidDate='2019-09-28 05:00:00',ValidDate='2019-10-01 05:00:00',}",
  [3000555] = "{id=3000555,NameZh='食魂大礼包',Icon='item_3000555',Type=30,MaxNum=99999,SellPrice=100,Desc='来到料理大赛激烈的比赛现场，内心的美食之魂忍不住熊熊燃烧！\n开启后必定获得「庆典美食券」*30、「七彩贝壳」*300，并有10%额外概率获得「团子串串烧兑换券」*1。\n「团子串串烧兑换券」可兑换活动限定宠物及皮肤，宠物「团子串串烧」可在宠物手册中融合为宠物「凶恶幽灵」。',Feature=1,}",
  [3000556] = "{id=3000556,NameZh='希莎娅的珍藏礼盒',Icon='item_3866',Type=30,MaxNum=99999,SellPrice=100,Desc='料理大赛期间推出的特卖礼包，打开必定获得「古拉姆晶末」*15~35、「诺伦卡片」*35~50，并随机获赠以下道具中的一种：「卡册残页」*2、「精装卡册残页」*2、「华丽卡册」*1、「远古魔力卡册」*1，还有概率额外获赠稀有神谕专属卡片*1。',Feature=1,}",
  [3000557] = "{id=3000557,NameZh='团子串串烧魔物蛋',Icon='item_3000557',Type=101,MaxNum=1,SellPrice=100,Desc='一颗神奇的魔物蛋，里面可以孵化出魔物团子串串烧。\n面团揉啊揉，煎锅滚一滚，撒上最爱的酱汁，串上干净的竹签，噔噔噔！！串串烧完成！',Feature=1,TFValidDate='2019-09-28 05:00:00',ValidDate='2019-10-01 05:00:00',}",
  [3000558] = "{id=3000558,NameZh='凶恶幽灵魔物蛋',Icon='item_3000558',Type=101,MaxNum=1,SellPrice=100,Desc='一颗神奇的魔物蛋，里面可以孵化出魔物凶恶幽灵。\n“喂~可爱的朋友，你饿不饿啊~想不想吃点团子啊……”夜晚一个人走路的时候听到这句话千万不要答应，要不然就要被它们盯上了哦~嘘，它们来了。',Feature=1,TFValidDate='2019-09-28 05:00:00',ValidDate='2019-10-01 05:00:00',}",
  [3000559] = "{id=3000559,NameZh='红豆麻薯',Icon='item_3000559',Type=103,MaxNum=99999,SellPrice=100,Desc='清甜美味，香糯可口，是宠物团子串串烧最喜爱的物品。',Feature=1,}",
  [3000560] = "{id=3000560,NameZh='饿鬼的盛宴',Icon='item_551019',Type=610,MaxNum=99999,SellPrice=100,Desc='饿鬼身上掉落的神秘料理，看起来相当黑暗……但为了帮助料理协会找回顶级食材，也只能捏着鼻子往肚子里咽了！',GetLimit={limit={[999]={3,0}},source={22},type=1},Feature=4,}",
  [3000561] = "{id=3000561,NameZh='顶级食材',Icon='item_3000561',Type=41,MaxNum=99999,SellPrice=100,Desc='整个米德加尔特大陆上绝无仅有的豪华食材，料理大赛的工作人员们正在四处奔走寻找它们。\n请前往普隆德拉广场找到相关工作人员进行上交，可获取丰厚回报奖励哦~\n（注：这些食材只能存放一段时间，否则就不新鲜啦，请尽快上交给工作人员~）',ExistTimeType=2,ExistTime='2019-10-17 05:00:00',Feature=1,}",
  [3000563] = "{id=3000563,NameZh='团子幽灵·饿',Icon='item_3000563',Type=41,MaxNum=99999,SellPrice=100,Desc='乍看是一团白色的麻薯，其实是胃口巨大无比的饿鬼！\n使用后解锁宠物团子串串烧的饿鬼外观。',Feature=1,TFValidDate='2019-09-28 05:00:00',ValidDate='2019-10-01 05:00:00',}",
  [3000564] = "{id=3000564,NameZh='不射猎的赠礼',Icon='item_6074',Type=30,MaxNum=99999,SellPrice=100,Desc='不会射箭的猎人给大家献上祝福啦！\n开启后必定获得限定头饰「卷纸猫」×1、「远古魔力卡册」×1。',Feature=1,}",
  [3000565] = "{id=3000565,NameZh='团子串串烧兑换券',Icon='item_700147',Type=61,UseMode=30015,MaxNum=99999,SellPrice=100,Desc='料理协会于大赛期间发布的限定特礼，使用后可兑换活动限定宠物「团子串串烧」和宠物皮肤「团子串串烧·饿鬼」~',Feature=1,}",
  [3000566] = "{id=3000566,NameZh='特里手工爱心烤肉',Icon='item_551000',Type=610,MaxNum=99999,SellPrice=100,Desc='特里用心烤制的肉排，快来感受满满的爱吧！',Feature=4,}",
  [3000567] = "{id=3000567,NameZh='奥尔里昂肉食拼盘',Icon='item_551003',Type=610,MaxNum=99999,SellPrice=100,Desc='料理协会为大众免费提供的肉食拼盘，其中包括会长奥尔里昂的最新作品——新奥尔里昂烤翅！',Feature=4,}",
