  [3000620] = "{id=3000620,NameZh='浮光跃金',Icon='item_3000620',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15229,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='白蔷薇骑士团的礼仪头盔，专门用于重大场合，采用黄金与磷叶石打造，阳光下犹如波光粼粼的水面闪烁着细碎的光芒。',Feature=1,TFValidDate='2019-09-09 05:00:00',ValidDate='2019-09-12 05:00:00',}",
  [3000621] = "{id=3000621,NameZh='蔷薇礼仪',Icon='item_3000621',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15230,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='白蔷薇骑士团的战斗头盔，密度最高的钢金千锤百炼而成，刀枪不入，能够抵御巨魔奋力一击而不碎裂。',Feature=1,TFValidDate='2019-09-09 05:00:00',ValidDate='2019-09-12 05:00:00',}",
  [3000622] = "{id=3000622,NameZh='天鹅的敬意',Icon='item_3000622',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15231,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='极北之境有一种优雅的动物雪天鹅，它有纯白的羽毛和纤细的颈脖，只有当遇见善良勇敢的人时，它们才会低下骄傲的脖子。此剑如雪天鹅，只愿意臣服于真正的主人。',Feature=1,TFValidDate='2019-09-09 05:00:00',ValidDate='2019-09-12 05:00:00',}",
  [3000623] = "{id=3000623,NameZh='白金之眼',Icon='item_3000623',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15232,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='居住在北方的白蔷薇骑士团，有一种独特的修行方式，带上白金面具遮住眼睛，以心代眼，聆听风声，感受气流，无需肉眼即可见十方世界。这种用以修行的面具，也被白蔷薇骑士团称为白金之眼。',Feature=1,TFValidDate='2019-09-09 05:00:00',ValidDate='2019-09-12 05:00:00',}",
  [3000624] = "{id=3000624,NameZh='白之火',Icon='item_3000624',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15233,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='白蔷薇骑士团的徽章，每个徽章上都会刻上骑士的代号，也因为徽章上飘着一股白色的火焰，被骑士团亲切的称呼为白之火。',Feature=1,TFValidDate='2019-09-09 05:00:00',ValidDate='2019-09-12 05:00:00',}",
  [3000625] = "{id=3000625,NameZh='雪国明镜',Icon='item_3000625',Type=810,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=15234,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='永远不会沾染任何灰尘的翅膀，被北国的王称之为不染尘，犹如佩戴者明镜一样的心灵，像大雪过后的天空一样，澄净又明亮。',Feature=1,TFValidDate='2019-09-09 05:00:00',ValidDate='2019-09-12 05:00:00',}",
  [3000626] = "{id=3000626,NameZh='骑士的沉默',Icon='item_3000626',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15235,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='沉默被誉为骑士的美德，用行动代替语言，用无声代替恬燥，才是骑士真正的精神。',Feature=1,TFValidDate='2019-09-09 05:00:00',ValidDate='2019-09-12 05:00:00',}",
