  [3000628] = "{id=3000628,NameZh='夏日时装兑换券',Icon='item_51175',Type=121,MaxNum=99999,SellPrice=100,ComposeID=4000013,Desc='使用之后可以获得一件对应阁下性别的夏日系列时装哦~',Feature=1,}",
  [3000630] = "{id=3000630,NameZh='领主荣光·谦恭',Icon='item_3000630',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='“你现在可是一方的领主了？还有什么不满意的么？”男子看着自己一望无际的领土沉默不语。权利，地位，这些真的是他想要的么？所谓骑士，守护了人民和国家，却没能守护自己最重要的人……',Feature=1,TFValidDate='2019-11-11 05:00:00',ValidDate='2019-11-14 05:00:00',MainColor='4147edFF',}",
