  [3000640] = "{id=3000640,NameZh='圣骑星耀·怜悯',Icon='item_3000640',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='“女孩子？你怎么会出现在骑士团！”“为了公平正义战胜邪恶，热爱自己的祖国，坚定自己的内心，保护弱者不畏强权，这些骑士的准则我都能做到，为什么要在乎我的性别呢？”“……你叫什么名字”“狄安娜，未来圣骑团最耀眼的存在！”',Feature=1,TFValidDate='2019-11-11 05:00:00',ValidDate='2019-11-14 05:00:00',MainColor='4147edFF',}",
