  [3000680] = "{id=3000680,NameZh='无冕之冠',Icon='item_3000680',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15242,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='王冠并不能代表权利，身为王要被人民所信服，所敬仰，愿为国家付出一切，将人民的利益摆在最前面，这才是真正的无冕之王。',Feature=1,TFValidDate='2019-11-11 05:00:00',ValidDate='2019-11-14 05:00:00',LoadShowSize=2.5,LoadShowPose={0,0.8,0},}",
  [3000681] = "{id=3000681,NameZh='金聆',Icon='item_3000681',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15243,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='“可以不去战场么？”少女看着少年眼里充满着期许。 “我可是骑士啊！”少女听闻少年的回答沉默不语，少年轻吻了一下少女的额头“不过，我答应你，铃兰花开之时，我就回来。”',Feature=1,TFValidDate='2019-11-11 05:00:00',ValidDate='2019-11-14 05:00:00',}",
  [3000682] = "{id=3000682,NameZh='封地卷轴',Icon='item_3000682',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15244,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='此地封土赏于优秀的骑士长，赞誉骑士之英勇，歌颂骑士之谦恭，表率骑士的之荣光，愿你的铠甲成为所有人民的护盾，愿你的利剑刺入敌人的心脏，愿骑士的精神永远传承。',Feature=1,TFValidDate='2019-11-11 05:00:00',ValidDate='2019-11-14 05:00:00',LoadShowSize=1.5,LoadShowRotate=150,LoadShowPose={0,0.5,0},}",
  [3000683] = "{id=3000683,NameZh='鎏金纹章·蔚',Icon='item_3000683',Type=810,Quality=5,MaxNum=99,SellPrice=100,StorageReward={buffid={80012590}},Desc='“八翼羽翅，象征着骑士的八大品格，谦恭，荣誉，牺牲，英勇，怜悯，诚实，精神，公正，佩戴它，就肩负它的责任，你准备好接受这一切了么”青年目光坚定，单膝下跪表明了自己的决心。',Feature=1,TFValidDate='2019-11-11 05:00:00',ValidDate='2019-11-14 05:00:00',LoadShowSize=1,LoadShowRotate=150,LoadShowPose={0,0.5,0},}",
  [3000684] = "{id=3000684,NameZh='亚瑟王',Icon='item_3000684',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15246,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='传奇而不朽，吾是至高无上的存在，勇敢和真实的骑士请加入我的麾下，照顾被剥夺权利之人，直面应对强敌保护弱者，我们是这片大陆最英勇的军队！——亚瑟王，亲喻。',Feature=1,TFValidDate='2019-11-11 05:00:00',ValidDate='2019-11-14 05:00:00',LoadShowSize=1,LoadShowRotate=0,LoadShowPose={0,0.5,0},}",
