  [3000701] = "{id=3000701,NameZh='熊本熊的谢礼',Icon='item_3000701',Type=30,MaxNum=99999,SellPrice=100,Desc='人气偶像熊本熊的谢礼，使用之后必定获得「熊本熊的心意」x20，还可以随机获得以下道具中的一种：「神秘箱子SP」x1、「秘银」x3、「金质勋章」x1、「料理兑换券」x1、「锁链雷锭」x2、「莫拉硬币」x4、「神谕之尘」x2、「神谕之晶」x1、「玛丝黛拉种子」x1，如果被熊本熊的好运砸中，还能额外获得限定头饰图纸「我是熊本熊图纸」x1!',Delete=3000701}",
  [3000702] = "{id=3000702,NameZh='熊本熊感动得哭了礼包',Icon='item_3000702',Type=30,MaxNum=99999,SellPrice=100,Desc='熊本熊被你的所作所为感动得哭泣，使用之后可以获得「熊本熊的心意」x50、「熊本熊扭蛋币」x10',Delete=3000702}",
  [3000703] = "{id=3000703,NameZh='熊本熊并不是很想理你礼包',Icon='item_3000703',Type=30,MaxNum=99999,SellPrice=100,Desc='熊本熊并不是很想理你，留下一个礼包就走了，使用之后可以获得「熊本熊的心意」x20、「熊本熊扭蛋币」x10',Delete=3000703}",
  [3000704] = "{id=3000704,NameZh='熊本熊扭蛋币',Icon='item_3000704',Type=41,MaxNum=99999,SellPrice=100,Desc='为了欢迎熊本熊的到来特意发行的扭蛋币，冒险者可以使用它去参与熊本熊异次元扭蛋机~但是在熊本熊离开了之后，这个扭蛋币也就没什么用啦，所以各位冒险者请注意使用期限哦~',ExistTimeType=2,ExistTime='2020-01-31 05:00:00',Feature=1,Delete=3000704}",
  [3000706] = "{id=3000706,NameZh='熊本熊腮红',Icon='item_3000706',Type=830,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10157,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='熊本熊同款腮红，戴上它，你也能成为充满爱的人气偶像！',Feature=1,TFValidDate='2019-12-29 05:00:00',ValidDate='2020-01-01 05:00:00',Delete=3000706}",
