  [3000710] = "{id=3000710,NameZh='熊本熊的心意',Icon='item_170',Type=61,UseMode=30017,MaxNum=99999,SellPrice=100,Desc='熊本熊赠送给各位冒险者的礼物，使用之后可以打开熊本熊的商店，兑换各类限定稀有道具。一旦熊本熊离开了，该道具就会被回收哦~所以请各位冒险者注意使用期限！',ExistTimeType=2,ExistTime='2020-01-31 05:00:00',Feature=1,Delete=3000710}",
