  [3000810] = "{id=3000810,NameZh='雷鸣三重奏',Icon='item_3000810',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9657,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='一曲，天骤暗，二曲，雷云现，三曲，惊雷落。',Feature=1,TFValidDate='2019-10-01 05:00:00',ValidDate='2019-10-01 05:00:00',LoadShowSize=1,LoadShowPose={0},}",
  [3000811] = "{id=3000811,NameZh='雷鸣之子',Icon='item_3000811',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9658,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='唔呼~唔呼~父亲竟然让我到人类的世界历练，可恶！渺小的人类怎么配合本神子一起战斗！我要把你们全部劈成灰烬！',Feature=1,TFValidDate='2019-10-01 05:00:00',ValidDate='2019-10-01 05:00:00',LoadShowSize=2,LoadShowPose={0,-0.2,0},}",
  [3000812] = "{id=3000812,NameZh='万雷[1]',Icon='item_3000812',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9659,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='吾，愿为雷鸣之神献出己身，借由神之力，引惊雷降世，护我族一世安定！',Feature=1,TFValidDate='2019-10-01 05:00:00',ValidDate='2019-10-01 05:00:00',LoadShowSize=1.5,LoadShowPose={0,0.3,0},}",
  [3000813] = "{id=3000813,NameZh='狡齿',Icon='item_3000813',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9660,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='祭礼神鬼非神鬼，不露凶芒亦凶芒。',Feature=1,TFValidDate='2019-10-01 05:00:00',ValidDate='2019-10-01 05:00:00',LoadShowSize=4,LoadShowPose={0,0.5,0},}",
  [3000814] = "{id=3000814,NameZh='流星银蛟[1]',Icon='item_3000814',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9661,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='身已死，魂犹在。银翼龙的双角蕴含着召唤雷电的力量，只有得到它认可的勇士才能使用它。',Feature=1,TFValidDate='2019-10-01 05:00:00',ValidDate='2019-10-01 05:00:00',LoadShowSize=2,LoadShowPose={0,0.7,0},}",
  [3000815] = "{id=3000815,NameZh='制裁弓矢',Icon='item_3000815',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9662,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='赠予吾虔诚的信徒，制裁的弓矢必将助你消除一切黑暗！',Feature=1,TFValidDate='2019-10-01 05:00:00',ValidDate='2019-10-01 05:00:00',LoadShowSize=2,LoadShowPose={0,0.7,0},}",
  [3000816] = "{id=3000816,NameZh='星雷遗礼',Icon='item_3000816',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9049,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='银月初升，星云流转，曼妙的少女在篝火旁舞动着身躯，为雷鸣之神献上最美好的礼物！',Feature=1,TFValidDate='2019-10-01 05:00:00',ValidDate='2019-10-01 05:00:00',LoadShowSize=2,LoadShowPose={0,0.7,0},}",
  [3000820] = "{id=3000820,NameZh='我不是咸鱼[1]',Icon='item_3000820',Type=800,MaxNum=99,SellPrice=100,AdventureSort=10158,AdventureValue=1,StorageReward={buffid={80013070}},Condition=8,Desc='冲呀！咸鱼王！我要成为第一个在陆地行走的咸鱼！让海里那些呆瓜看看，咸鱼也可以实现梦想！',Feature=1,}",
  [3000830] = "{id=3000830,NameZh='噩梦鬼翼',Icon='item_3000830',Type=810,Quality=4,MaxNum=99,SellPrice=100,Desc='据说灵魂不再纯粹的人会长出恶鬼一般的羽翼，而暗紫色的鬼翼代表着持有者内心最深处的黑暗，上面的鬼脸似乎永远在嗤笑着什么。',Feature=1,StageDisplay=0,Delete=3000830}",
  [3000831] = "{id=3000831,NameZh='幽冥鬼翼',Icon='item_3000831',Type=810,Quality=4,MaxNum=99,SellPrice=100,Desc='据说灵魂不再纯粹的人会长出恶鬼一般的羽翼，而幽绿色的鬼翼代表着持有者内心最深处的邪恶，上面的鬼脸似乎永远在嗤笑着什么。',Feature=1,StageDisplay=0,Delete=3000831}",
