  [3000834] = "{id=3000834,NameZh='表情-熊本熊大吃一惊',Icon='item_3000834',Type=41,MaxNum=1,SellPrice=100,Desc='使用该道具后解锁一个冒险者的新表情。',TFValidDate='2019-12-29 05:00:00',ValidDate='2020-01-01 05:00:00',Delete=3000834}",
  [3000840] = "{id=3000840,NameZh='初心守候',Icon='item_3000840',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10159,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='天使波利以自己为原型制作的纪念品，会赠予被认可的冒险者，以见证彼此的相遇。“无论身在何方，愿勇气与梦想始终与你相伴。”',Feature=1,TFValidDate='2019-10-01 05:00:00',ValidDate='2019-10-01 05:00:00',}",
  [3000841] = "{id=3000841,NameZh='永恒的爱',Icon='',Type=10,SellPrice=100,Desc='无论身在何方，愿你不忘初心，守护这永恒的爱~！',Feature=1,TFValidDate='2019-10-01 05:00:00',ValidDate='2019-10-01 05:00:00',}",
  [3000842] = "{id=3000842,NameZh='初心守候礼盒',Icon='item_3994',Type=30,MaxNum=99999,SellPrice=100,Desc='这一份最诚挚的初心，这一份最真挚的守候，都汇聚在这个小小的礼盒中，打开可以获得限定头饰「初心守候」x1、「魔力卡册」x1、「B格猫福利券Ⅰ」x30。在这个特殊的日子里，让我们共同祝愿，明天会更好~！',Feature=1,}",
  [3000843] = "{id=3000843,NameZh='幻术大作战礼包',Icon='item_3896',Type=30,MaxNum=99999,SellPrice=100,Desc='狸猫学院最新巨献！经过幻术加成的礼盒，打开之后随机获得一枚全新属性的S级符文！',Feature=1,}",
  [3000850] = "{id=3000850,NameZh='策划自制活动币',Icon='item_700184',Type=61,UseMode=30016,MaxNum=99999,AuctionPrice=1,SellPrice=10,Desc='策划们在某个大雨倾盆的夜晚，被窗外的闪电劈中了良心，决定献祭自己的头发创造一种崭新的红色货币。使用后可以兑换某些有趣的小玩意儿，同时有概率会让策划们的一根头发脱落。“看看，我的Jennifer，掉了……”“你居然还给头发起名字？！”',GetLimit={limit={[999]={100,0}},source={22},type=1},ExistTimeType=2,ExistTime='2020-08-10 05:00:00',Feature=1,}",
  [3000851] = "{id=3000851,NameZh='我不是bug图纸',Icon='item_3031851',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=3000851,Desc='“警报！警报！loading图陷入了死循环，波利跳不动了！！”“根据调查这是来自异次元的虫子搞的鬼，交给我们吧！不过，事后你们需要提供一些绿色的硬币作为补偿……”一群头顶光辉的年轻人如是说。',Feature=1,}",
  [3000852] = "{id=3000852,NameZh='Ep卡典藏礼盒',Icon='item_700190',Type=30,MaxNum=99999,SellPrice=100,Desc='打开之后可获得EP1.0卡-EP6.0卡各1张。',Feature=1,}",
  [3000853] = "{id=3000853,NameZh='绝版时装礼盒',Icon='item_3994',Type=30,UseMode=30022,MaxNum=99999,SellPrice=100,Desc='打开之后可选择一套往期时装（除联动时装）。',Feature=1,}",
  [3000854] = "{id=3000854,NameZh='架金符文宝箱',Icon='item_3838',Type=30,MaxNum=99999,SellPrice=100,Desc='精致奢华的宝箱，里面装着一个随机职业的新符文，无需鉴定，即开即用，助你随时随地踏上新的旅途！',Feature=1,}",
  [3000855] = "{id=3000855,NameZh='脱单大礼盒',Icon='item_3000170',Type=30,MaxNum=99999,SellPrice=100,Desc='打开之后获得以下奖励的一种：「祈祷晶片包」*2、「金质勋章」*2、「尘封的符文袋·Ⅰ」*2、「来自女武神的馈赠」*2、「玛丝黛拉种子」*1、「料理兑换券」*2、必定获得「策划自制活动币」*50',Feature=1,}",
  [3000857] = "{id=3000857,NameZh='星星石的碎片',Icon='item_12578',Type=30,MaxNum=99999,SellPrice=100,Desc='流星的碎片，蕴含着不可思议的魔法。是制作锁链雷锭与坠星陨铁的必要材料。使用后可以得到策划的感恩礼物一份。',Feature=1,}",
  [3000858] = "{id=3000858,NameZh='Bug虫的礼物',Icon='item_12574',Type=30,MaxNum=99999,SellPrice=100,Desc='异世界的bug虫最喜欢的宝石，闪耀着神秘的绿色光芒。每次消灭一个bug虫就会掉落，被策划们用来制作冒险家硬币。使用后可以得到策划的感恩礼物一份。',Feature=1,}",
  [3000859] = "{id=3000859,NameZh='未加工的猫币',Icon='item_12573',Type=30,MaxNum=99999,SellPrice=100,Desc='是制作B格猫金币的基础材料，本质为一种金色的铜矿。并没有经过加工，想要变成真正的猫币还要经过代码魔法的锤炼。使用后可以得到策划的感恩礼物一份。',Feature=1,}",
  [3000860] = "{id=3000860,NameZh='国王波利的水晶',Icon='item_12576',Type=30,MaxNum=99999,SellPrice=100,Desc='所有多余的神谕之尘，都会被国王波利偷偷做成水晶。最后在某个月黑风高的夜晚，被严谨的策划没收了。使用后可以得到策划的感恩礼物一份。',Feature=1,}",
  [3000870] = "{id=3000870,NameZh='冰风之祭[1]',Icon='item_3000870',Type=800,Quality=2,MaxNum=99,SellPrice=100,Desc='“古老预言指引的勇者，终将以风为翼，斩落星辰。”——人类勇者赛拉迪斯的冠冕。相传百年前，他曾乘苍鹭飞向雪原的最高处，迎风击落了即将破碎的彗星。',StageDisplay=0,}",
  [3000871] = "{id=3000871,NameZh='埃琉德尼尔武器兑换券',Icon='item_3000871',Type=61,UseMode=30019,MaxNum=99999,SellPrice=100,Desc='可打开埃琉德尼尔武器兑换商店，兑换你喜欢的武器外观吧！',Feature=1,}",
  [3000880] = "{id=3000880,NameZh='机械漫游',Icon='item_3000880',Type=501,MaxNum=99,SellPrice=100,StorageReward={buffid={82000010}},Desc='远方传来机械的轰鸣，伴着齿轮的滴答声，他陷入时间的迷雾，跌入那场时代的落幕。',Feature=1,StageDisplay=0,}",
  [3000881] = "{id=3000881,NameZh='蒸汽狂想',Icon='item_3000881',Type=501,MaxNum=99,SellPrice=100,StorageReward={buffid={82000010}},Desc='雾中弥漫着铁锈的气息，她将指针回溯至工业时代，等待那场机械与魔法的狂欢。',Feature=1,StageDisplay=0,}",
  [3000882] = "{id=3000882,NameZh='蒸汽朋克系列衣装',Icon='item_3000882',Type=501,MaxNum=99,SellPrice=100,StorageReward={buffid={82000010}},Feature=1,StageDisplay=0,}",
  [3000883] = "{id=3000883,NameZh='浪漫齿轮[1]',Icon='item_3000883',Type=800,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80012860}},Desc='机械师常备的优雅高帽，以柔韧皮革制成，配以特殊的齿轮护目镜，每一处都显示着精致与高雅。',Feature=1,StageDisplay=0,}",
  [3000884] = "{id=3000884,NameZh='古典金属[1]',Icon='item_3000884',Type=800,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80012860}},Desc='风靡一时的精巧圆帽，除了圆镜外还有着隆重的发带拖尾。戴上它，不论何时都是人群的焦点。',StageDisplay=0,}",
  [3000885] = "{id=3000885,NameZh='蒸汽朋克系列头饰',Icon='item_3000885',Type=800,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80012860}},StageDisplay=0,}",
  [3000890] = "{id=3000890,NameZh='星风使者·波普',Icon='item_3000890',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='“我是凛冽的寒风，斜掠姜饼城的雪原；我是温柔的初雪，抚摸普隆德拉的麦田；我是清幽的黎明，弥漫在斐扬的林间；我是午夜的歌声，鼓舞旅人的冒险；我是深空的群星，闪耀艾尔帕兰的天幕。我是星风使者，我带来圣诞的乐章。”',Feature=1,TFValidDate='2019-12-09 05:00:00',ValidDate='2019-12-12 05:00:00',MainColor='d13935FF',}",
  [3000891] = "{id=3000891,NameZh='星风使者·古典',Icon='item_3000890',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='“我是凛冽的寒风，斜掠姜饼城的雪原；我是温柔的初雪，抚摸普隆德拉的麦田；我是清幽的黎明，弥漫在斐扬的林间；我是午夜的歌声，鼓舞旅人的冒险；我是深空的群星，闪耀艾尔帕兰的天幕。我是星风使者，我带来圣诞的乐章。”',Feature=1,TFValidDate='2019-12-09 05:00:00',ValidDate='2019-12-12 05:00:00',MainColor='e2e6f8FF',}",
