  [3000900] = "{id=3000900,NameZh='雪羽妖精· 桑巴',Icon='item_3000900',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='对姜饼城的孩童来说，圣诞节是幸福的狂欢夜；对那位白胡子老爷爷来说，圣诞节是忙碌的工作日；对我来说，圣诞节是与你奏响的每一个音符，是与你走过的每一条街道，是为你拂去的每一片雪花，感谢圣诞老人，让我得到了全世界最完美的礼物。',Feature=1,TFValidDate='2019-12-09 05:00:00',ValidDate='2019-12-12 05:00:00',MainColor='d13935FF',}",
