  [3000910] = "{id=3000910,NameZh='风岚绅士',Icon='item_3000890',Type=501,MaxNum=99,SellPrice=100,Desc='“士兵们！听我命令！呼啸起来，席卷大地，卷走每一片雪花！这个冬季属于狂风！今年一定要赢过那个冷漠的女人，出发！”',Feature=1,TFValidDate='2019-12-09 05:00:00',ValidDate='2019-12-12 05:00:00',MainColor='e79f35FF',}",
  [3000911] = "{id=3000911,NameZh='冰雪女郎',Icon='item_3000900',Type=501,MaxNum=99,SellPrice=100,Desc='“执事们！听我命令！扩散出去，铺天盖地，压倒每一缕细风！这个冬季属于冰雪！今年一定要赢过那个聒噪的男人，出发！”',Feature=1,TFValidDate='2019-12-09 05:00:00',ValidDate='2019-12-12 05:00:00',MainColor='e79f35FF',}",
