  [3000925] = "{id=3000925,NameZh='雪落星冠·桑巴',Icon='item_3000925',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='雪羽妖精的魔法帽，带有神奇的魔力，戴起它，即使晴空万里也会即刻飘起雪花，戴起它，漫天飞雪都会与你共舞，为你开路，戴起它，你也可以成为雪羽妖精。',Feature=1,TFValidDate='2019-12-01 05:00:00',ValidDate='2019-12-01 05:00:00',LoadShowSize=2,LoadShowPose={0,0.7,0},MainColor='d13935FF',}",
