  [3000930] = "{id=3000930,NameZh='冬灵幻境头饰兑换券·塔罗',Icon='item_3000930',Type=61,UseMode=30023,MaxNum=99999,SellPrice=100,Desc='使用之后可以兑换任意一件冬灵幻境系列头饰哦~',Feature=1,}",
  [3000931] = "{id=3000931,NameZh='仙灵鹿冠',Icon='item_3000931',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15251,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='对没有驯鹿雪橇的尼克娅，仙灵赠予了带有魔力的霓虹鹿角，以助她在夜空中飞行。',Feature=1,TFValidDate='2019-12-01 05:00:00',ValidDate='2019-12-01 05:00:00',LoadShowSize=2,LoadShowPose={0,0.7,0},}",
  [3000932] = "{id=3000932,NameZh='雪灵的馈赠',Icon='item_3000932',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15252,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='“没有雪花飘散的冬天是不完整的，带上我的祝福，为每个孩子送去一场白色圣诞节吧。”',Feature=1,TFValidDate='2019-12-01 05:00:00',ValidDate='2019-12-01 05:00:00',LoadShowSize=3,LoadShowPose={0,0.5,0},}",
  [3000933] = "{id=3000933,NameZh='月下星途',Icon='item_3000933',Type=800,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=15253,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='为什么每次圣诞老人的身影划过天际时总伴随着又大又圆的月亮呢？也许这顶帽子能给你答案。',Feature=1,TFValidDate='2019-12-09 05:00:00',ValidDate='2019-12-12 05:00:00',LoadShowSize=2,LoadShowPose={0,0.7,0},}",
  [3000934] = "{id=3000934,NameZh='圆脸托尼',Icon='item_3000934',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15254,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='一个会说话的神奇包包，由仙灵、妖精和雪灵联手为尼克娅打造，可以装下堆成小山的礼物，绝不会逊色于圣诞老人的大口袋。',Feature=1,TFValidDate='2019-12-01 05:00:00',ValidDate='2019-12-01 05:00:00',LoadShowSize=1.5,LoadShowRotate=180,LoadShowPose={0,0.4,0},}",
  [3000935] = "{id=3000935,NameZh='雪之印象',Icon='item_3000935',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15255,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='跟其他种族不同，雪灵认为雪是有容貌的，但它们无法形容出那种印象。“简单来说，就像照镜子一样！”',Feature=1,TFValidDate='2019-12-01 05:00:00',ValidDate='2019-12-01 05:00:00',LoadShowSize=4,LoadShowPose={0,0.4,0},}",
  [3000936] = "{id=3000936,NameZh='妖精之加护',Icon='item_3000936',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15256,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='“叮叮当~叮叮当~冬日的暖阳~星光的衣裳~叮叮当~叮叮当~月下的倩影~妖精之加护~”',Feature=1,TFValidDate='2019-12-01 05:00:00',ValidDate='2019-12-01 05:00:00',LoadShowSize=2,LoadShowPose={0,0.4,0},}",
  [3000940] = "{id=3000940,NameZh='驯鹿波利',Icon='item_3000940',Type=90,Quality=4,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000240}},Desc='受到圣诞节的热烈气氛和神秘魔力影响，波利们变身成了疑似驯鹿的生物！它们火急火燎的希望你上车呢，快去吧冒险者！哦别担心，车上的礼物都是你的，不用发给别人~',Feature=1,TFValidDate='2019-12-09 05:00:00',ValidDate='2019-12-12 05:00:00',LoadShowSize=0.5,LoadShowPose={0,-0.2,0},}",
  [3000941] = "{id=3000941,NameZh='星途雪橇',Icon='item_3000941',Type=90,Quality=4,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000240}},Desc='圣诞老人真正的座驾！的复制品！曾跨过山河大海，穿过人山人海的雪橇界老前辈，平稳而迅捷，能以最优雅的姿态将礼物送去每一个家庭。',Feature=1,TFValidDate='2019-12-09 05:00:00',ValidDate='2019-12-12 05:00:00',LoadShowSize=0.5,LoadShowPose={0,-0.2,0},}",
  [3000942] = "{id=3000942,NameZh='星途雪橇系列',Icon='item_3000940',Type=90,Quality=4,MaxNum=1,SellPrice=100,AdventureSort=1010,AdventureValue=100,AdventureReward={buffid={63000240}},Condition=8,TFValidDate='2019-12-09 05:00:00',ValidDate='2019-12-12 05:00:00',}",
  [3000950] = "{id=3000950,NameZh='黄金纪元·凯旋',Icon='item_3000950',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='武器大师拉兹菲罗斯专门为狮心王精锐部队打造的盔甲，象征了狮子的骄傲和冷静。选择沉稳的蓝色作为配色，身穿此件盔甲就意味着向敌人宣告自己不惧怕一切。',Feature=1,TFValidDate='2020-01-20 05:00:00',ValidDate='2020-01-23 05:00:00',MainColor='3330dbFF',}",
