  [3000991] = "{id=3000991,NameZh='金铸蝴蝶',Icon='item_3000991',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15261,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='大妖精蒙罗莉亚最喜欢的饰品，能够使佩戴者荣光焕发，提升魅力的神奇发饰。',Feature=1,TFValidDate='2020-01-20 05:00:00',ValidDate='2020-01-23 05:00:00',LoadShowSize=3,LoadShowPose={0,0.7,0},}",
  [3000992] = "{id=3000992,NameZh='狮心剑',Icon='item_3000992',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15262,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='黄铜铸造成剑身镶嵌着燃烧宝石，这柄剑是狮心王最爱惜的宝剑，曾经伴随他赢得无数场战役。',Feature=1,TFValidDate='2020-01-20 05:00:00',ValidDate='2020-01-23 05:00:00',LoadShowSize=1.5,LoadShowPose={0,0.6,0},}",
  [3000993] = "{id=3000993,NameZh='太阳桂冠',Icon='item_3000993',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15263,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='传说中太阳神爱上月桂女神，用她的树枝做装点制作成自己头盔。后世崇拜太阳神的骑士们也会用月桂花纹装点自己的头盔，借以获得太阳神的力量。',Feature=1,TFValidDate='2020-01-20 05:00:00',ValidDate='2020-01-23 05:00:00',LoadShowSize=3,}",
  [3000994] = "{id=3000994,NameZh='路易十六伯爵',Icon='item_3000994',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15264,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='玩具大师卡普西路的得意之作，拥有自主思想的玩具狮子。看上去满脸写着嫌弃，偶尔心情很好的时候也会发出“嗷”的声音。',Feature=1,TFValidDate='2020-01-20 05:00:00',ValidDate='2020-01-23 05:00:00',LoadShowSize=1.5,LoadShowPose={0,0.1,0},}",
  [3000995] = "{id=3000995,NameZh='圣灵',Icon='item_3000995',Type=810,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=15265,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='有一种神秘的生物，只存在梦境里，以捕食美梦为生。月光之下，这生物会显露出自己的身形，映照着月光的白蝴蝶，美丽而脆弱，却拥有能够直入人心的力量。',Feature=1,TFValidDate='2020-01-20 05:00:00',ValidDate='2020-01-23 05:00:00',LoadShowSize=1.5,LoadShowPose={0,0.4,0},}",
  [3001000] = "{id=3001000,NameZh='惊喜波利',Icon='item_3001000',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10172,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='一只被装在礼物盒里的波利，它似乎知道有什么好事将要发生，总是想跳出礼盒看看~！',Feature=1,TFValidDate='2019-12-27 05:00:00',ValidDate='2020-01-01 05:00:00',}",
  [3001001] = "{id=3001001,NameZh='千日纪念信笺',Icon='item_3001001',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10168,AdventureValue=1,StorageReward={buffid={80013080}},Condition=8,Desc='千日之花，结成硕果；千日之旅，汇于信笺。这是我们的1000天纪念，冒险快乐，祝你快乐！',TFValidDate='2019-10-13 05:00:00',ValidDate='2019-10-16 05:00:00',}",
  [3001002] = "{id=3001002,NameZh='1000天冒险快乐！',Icon='item_3001001',Type=63,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=23117,AdventureValue=98,AdventureReward={rewardid={870037}},Condition=64,Desc='2017年1月19日，一场爱与勇气的冒险扬帆起航；1000天冒险之旅，我们在这个大陆相遇相知；现在，千日时光都汇聚在这封信笺之中，带着这份心意，我们一起继续未来的冒险！',NoSale=1,NoStorage=1,}",
  [3001010] = "{id=3001010,NameZh='缀星恋曲',Icon='item_3001010',Type=830,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9663,AdventureValue=1,StorageReward={buffid={82000260}},Condition=8,Desc='小魔女用魔导器变出来的特制耳机，里面存储了当下最流行的小情歌。莉莉娜听着听着走了神，经常就会不小心撞在云上。',Feature=1,TFValidDate='2019-12-01 05:00:00',ValidDate='2019-12-01 05:00:00',LoadShowSize=2,LoadShowPose={0,0.5,0},}",
  [3001011] = "{id=3001011,NameZh='璀璨之爱',Icon='item_3001011',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9664,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='浪漫闪耀的爱心装饰，是莉莉娜引以为傲的设计。曾被别的小魔女吐槽太过华丽，但少女的梦想不就该闪闪发光吗？',Feature=1,TFValidDate='2019-12-01 05:00:00',ValidDate='2019-12-01 05:00:00',LoadShowSize=2,LoadShowPose={0,0.6,0},}",
  [3001012] = "{id=3001012,NameZh='梦与星虹[1]',Icon='item_3001012',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9665,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='莉莉娜的标志性发型。据说她曾躲在彩虹上休息了一晚，醒来后头发就变成了这个样子。',Feature=1,TFValidDate='2019-12-01 05:00:00',ValidDate='2019-12-01 05:00:00',LoadShowSize=2,LoadShowPose={0,0.7,0},}",
  [3001013] = "{id=3001013,NameZh='琉光絮语',Icon='item_3001013',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9666,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='彩虹编织而成的围巾，雪白的爱心都是云朵的点缀。每当莉莉娜将它围在颈间，就说明恋之小魔女又要出发了。',Feature=1,TFValidDate='2019-12-01 05:00:00',ValidDate='2019-12-01 05:00:00',LoadShowSize=3,LoadShowPose={0,0.7,0},}",
  [3001014] = "{id=3001014,NameZh='心跳契约',Icon='item_3001014',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9667,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='莉莉娜的魔导器，可以听到人类的心声。若是茫茫中两道心声彼此回应，小魔女便会让它们的主人缔结爱的契约。',Feature=1,TFValidDate='2019-12-01 05:00:00',ValidDate='2019-12-01 05:00:00',LoadShowSize=3,LoadShowPose={0,0.5,0},}",
  [3001015] = "{id=3001015,NameZh='恋之小魔女[1]',Icon='item_3001015',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9668,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='爱心、缎带与梦幻的星光，恋之小魔女莉莉娜闪亮登场！“没有人能拒绝心跳的魔法，让爱恋的光辉洒满每一个角落吧！”',Feature=1,TFValidDate='2019-12-01 05:00:00',ValidDate='2019-12-01 05:00:00',LoadShowSize=3,LoadShowPose={0,0.8,0},}",
  [3001016] = "{id=3001016,NameZh='梦幻憧憬',Icon='item_3001016',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9051,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='莉莉娜的魔法视讯器，通过它可以看到思念之人的模样。本来其中只有一片雾气，但最近却出现了一个人类的身影……',Feature=1,TFValidDate='2019-12-01 05:00:00',ValidDate='2019-12-01 05:00:00',LoadShowSize=3,LoadShowPose={0,0.4,0},}",
  [3001020] = "{id=3001020,NameZh='《守护永恒的爱-孙燕姿》黑胶礼盒',Icon='item_3849',Type=30,MaxNum=99999,SellPrice=100,Desc='《守护永恒的爱-孙燕姿）》特制黑胶礼盒，开启后获得「守护永恒的爱（孙燕姿）」游戏CD一张、「天蓝宝石」*10、「黄宝石」*3、「青绿宝石」*1、「紫宝石」*1，还有概率获得珍贵的黑胶VIP兑换道具！（礼盒的使用时间为2019年9月27日5点 - 2019年10月2日5点）',ExistTimeType=2,ExistTime='2019-10-02 05:00:00',Feature=1,Delete=3001020}",
  [3001021] = "{id=3001021,NameZh='黑胶VIP',Icon='item_4001',Type=64,MaxNum=99999,SellPrice=100,Desc='网易云黑胶VIP兑换道具，获得「黑胶VIP」道具的玩家在活动结束后会通过邮件收到网易云音乐黑胶VIP（30天）兑换码，该道具会在10月10日后系统自动删除。',NoSale=1,NoStorage=1,ExistTimeType=2,ExistTime='2019-10-10 05:00:00',Feature=1,Delete=3001021}",
  [3001030] = "{id=3001030,NameZh='圣诞老人的怨念',Icon='item_3977',Type=30,MaxNum=99999,SellPrice=100,Desc='虽然圣诞老人很不开心，但是他依旧留下了圣诞礼物，这或许就是职业习惯吧。开启后随机获得以下道具中的一种：「莫拉硬币」x4、「祈祷晶片包」x2、「金质勋章」x2、「尘封的符文袋·Ⅰ」x2、「来自女武神的馈赠」x2、「玛丝黛拉种子」x1。',Feature=1,}",
  [3001031] = "{id=3001031,NameZh='驯鹿的私藏',Icon='item_6600',Type=30,MaxNum=99999,SellPrice=100,Desc='驯鹿珍藏了多年的礼物。开启后随机获得以下道具中的一种：「金质勋章」x2、「神谕之尘」x4、「祈祷晶片包」x2、「莫拉硬币」x4、「光洁的符文石」x1。',Feature=1,}",
  [3001032] = "{id=3001032,NameZh='驯鹿的珍藏',Icon='item_6601',Type=30,MaxNum=99999,SellPrice=100,Desc='驯鹿在珍藏了多年的礼物中偷偷地塞进一些更加珍贵的礼物。开启后必定获得以下道具：「金质勋章」x2、「神谕之尘」x4、「祈祷晶片包」x2、「莫拉硬币」x4、「光洁的符文石」x1，被驯鹿青睐的冒险者还有概率获得「驯鹿的头饰券」x1。',Feature=1,}",
  [3001033] = "{id=3001033,NameZh='圣诞礼物',Icon='item_6606',Type=30,MaxNum=99999,SellPrice=100,Desc='这是今年的圣诞礼物哟~打开之后必定可以获得「家居提货券」x2、「B格猫福利券·Ⅰ」x1、「阿斯特蕾亚的善意」x2、「B格猫福利券·宴」x1中的一种，还将获得「冒险丸子」x100、「锁链雷锭」x2、「料理兑换券」x1、「七彩贝壳」x100中的一种，如果受到圣诞老人的青睐，更可以随机获得一件圣诞风格的头饰哦~',GetLimit={limit={[999]={1,0}},source={22},type=1},Feature=1,}",
  [3001034] = "{id=3001034,NameZh='豪华圣诞礼物',Icon='item_6607',Type=30,MaxNum=99999,SellPrice=100,Desc='金光闪闪的圣诞礼物，看起来似乎藏着些什么价值不菲的宝贝~！开启后随机获得以下道具中的一种：「绝版圣诞时装兑换券」x1、「圣诞风格头饰」x1、「女武神成长礼盒」x1、「忽克连祝福礼盒」x1、「闪耀的符文石」x1。',GetLimit={limit={[999]={1,0}},source={22},type=1},Feature=1,}",
  [3001035] = "{id=3001035,NameZh='不射猎出气娃娃',Icon='item_3001035',Type=77,MaxNum=99999,SellPrice=100,AdventureSort=112,AdventureValue=1,StorageReward={buffid={82000120}},Condition=8,Desc='把对RO的所有不满，都发泄在这个出气娃娃身上吧！（但是这个造型那么可爱，你真的下得了手吗？）',Feature=1,TFValidDate='2019-12-01 05:00:00',ValidDate='2019-12-01 05:00:00',}",
  [3001036] = "{id=3001036,NameZh='庆典邀请函',Icon='item_6590',Type=30,MaxNum=99999,SellPrice=100,Feature=1,}",
  [3001039] = "{id=3001039,NameZh='圣诞老人的谢礼',Icon='item_5752',Type=30,MaxNum=99999,SellPrice=100,Feature=1,}",
  [3001040] = "{id=3001040,NameZh='驯鹿的头饰券',Icon='item_6544',Type=30,MaxNum=99999,SellPrice=100,Desc='驯鹿跟随圣诞老人多年的时间里偷偷积攒下来的宝贝~使用之后可以随机获得一件圣诞风格的头饰哦~',Feature=1,}",
  [3001041] = "{id=3001041,NameZh='庆典邀请函',Icon='item_5820',Type=30,MaxNum=99999,SellPrice=100,Desc='不射猎亲手写下的邀请函，虽然因为字迹潦草无法看清所有内容，但是依稀可以看到1月10日的字样。可能等到1月10日之后再打开会有意外的惊喜。',Feature=1,}",
  [3001042] = "{id=3001042,NameZh='暖冬强化礼包',Icon='item_3900',Type=30,MaxNum=99999,SellPrice=100,Desc='姜饼城在这个冬天推出的最新礼包，打开礼包可以获得Zeny x 100000，还可获得「强化精华Ⅰ」x4~6个、「强化精华Ⅱ」x4~6个、「强化精华Ⅲ」x4~6个。',}",
  [3001043] = "{id=3001043,NameZh='圣诞头饰币',Icon='item_5543',Type=61,UseMode=30025,MaxNum=99999,SellPrice=100,Desc='姜饼城发行的特殊代币，使用之后可以兑换圣诞专属头饰~',}",
  [3001050] = "{id=3001050,NameZh='远星的礼物',Icon='item_3665',Type=30,MaxNum=99999,SellPrice=100,Desc='“喵喵~期待我们正式相遇的那一天！”来自遥远星辰的礼物，但是被泛着彩虹光晕的异世界魔力笼罩着。暂时还不能开启，要等待SP版本正式服上线后才能打开喵~',Level=60,}",
  [3001051] = "{id=3001051,NameZh='神祈之箱',Icon='item_3711',Type=30,MaxNum=99999,SellPrice=100,Desc='听闻神之声，遵循神之意者方可开启它。打开之后获得以下奖励的一种：「祈祷晶片包」*1、「金质勋章」*1、「巅峰碎片」*1',}",
  [3001110] = "{id=3001110,NameZh='衫德尔的遗产',Icon='item_3001110',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9669,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='自导师从世上消失后，衫德尔的万灵们也一天天衰落，为了保存火种，万灵们都献出了自身最精华的一片灵魂，凝聚成希望之灵，以期衫德尔的延续。',Feature=1,TFValidDate='2020-01-01 05:00:00',ValidDate='2020-01-01 05:00:00',LoadShowSize=2,LoadShowPose={0,0.5,0},}",
  [3001111] = "{id=3001111,NameZh='聚灵冠冕[1]',Icon='item_3001111',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9670,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='起初，万灵们的身形都巨大无比，擎立于天地之间，每当他们学会凝聚灵魂，化身为动物时，导师就会为他们戴上这顶冠冕。',Feature=1,TFValidDate='2020-01-01 05:00:00',ValidDate='2020-01-01 05:00:00',LoadShowSize=1.5,LoadShowPose={0,0.3,0},}",
  [3001112] = "{id=3001112,NameZh='翡翠助教·欧沃尔',Icon='item_3001112',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9671,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='没人知道欧沃尔是何时存在的，当导师在万灵们面前现身之初，这只翡翠猫头鹰就蹲在他的肩头，协助导师完成知识的传承。',Feature=1,TFValidDate='2020-01-01 05:00:00',ValidDate='2020-01-01 05:00:00',LoadShowSize=1.5,}",
  [3001113] = "{id=3001113,NameZh='导师的面容',Icon='item_3001113',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9672,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='衫德尔成立之初，自然之灵们还处于懵懵懂懂的状态，就在那时，一个神秘的生命教会了他们如何与万物和谐共生，万灵们为了纪念这个神秘的生命制作了这面面具。',Feature=1,TFValidDate='2020-01-01 05:00:00',ValidDate='2020-01-01 05:00:00',LoadShowSize=3,LoadShowPose={0,0.2,0},}",
  [3001114] = "{id=3001114,NameZh='山岳融熔',Icon='item_3001114',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9673,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='每种灵体都有一种对应的动物化身，而生性最散（lan）漫（duo）的山岳之灵，其化身就是可以冬眠的熊，带在身上有保暖效果，不要在夏天用哦。',Feature=1,TFValidDate='2020-01-01 05:00:00',ValidDate='2020-01-01 05:00:00',LoadShowSize=1.2,LoadShowRotate=180,LoadShowPose={0,0.5,0},}",
  [3001115] = "{id=3001115,NameZh='雪祭恩赐[1]',Icon='item_3001115',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9674,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='为祈求雪之灵的恩赐，衫德尔中部的人们每年都会举办祭祀活动，久而久之，那里的人们长出了代表好运的雪兽耳朵。',Feature=1,TFValidDate='2020-01-01 05:00:00',ValidDate='2020-01-01 05:00:00',LoadShowSize=2,LoadShowPose={0,0.5,0},}",
  [3001116] = "{id=3001116,NameZh='安宁薄荷叶',Icon='item_3001116',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9052,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='精力最为旺盛、时刻充满活力的生命之灵是大家拥戴也嫌弃的对象，他健康，他善良，他强大又优雅！可是他实在太话痨了，为此万灵们发明了这种可以让他闭嘴的甜点，以求片刻宁静。',Feature=1,TFValidDate='2020-01-01 05:00:00',ValidDate='2020-01-01 05:00:00',LoadShowSize=4,LoadShowPose={0,0.7,0},}",
  [3001130] = "{id=3001130,NameZh='天穹咏叹·光羽',Icon='item_3001130',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000010}},Desc='阳光洒在少年青涩的脸庞上，恢弘的咏叹调上达天穹。“快看空中的那只飞鸟，真希望有一天，我也能拥有属于自己的羽翼……”',Feature=1,TFValidDate='2020-02-10 05:00:00',ValidDate='2020-02-13 05:00:00',MainColor='3772f0FF',}",
  [3001131] = "{id=3001131,NameZh='天穹咏叹·云雾',Icon='item_3001130',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000010}},Desc='阳光洒在少年青涩的脸庞上，恢弘的咏叹调上达天穹。“据说人们每多唱一首动听的歌，世界树的某处就会多一朵鲜花盛放。而那些看不见的精灵们，就沐浴在成片的花海中。”',Feature=1,TFValidDate='2020-02-10 05:00:00',ValidDate='2020-02-13 05:00:00',MainColor='f283e0FF',}",
  [3001132] = "{id=3001132,NameZh='天穹咏叹·夜影',Icon='item_3001130',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000010}},Desc='阳光洒在少年青涩的脸庞上，恢弘的咏叹调上达天穹。“置身于黑暗时，才会明白光明弥足珍贵。一定要跳出影子，去追寻永恒的光亮。”',Feature=1,TFValidDate='2020-02-10 05:00:00',ValidDate='2020-02-13 05:00:00',MainColor='221c19FF',}",
  [3001133] = "{id=3001133,NameZh='天穹咏叹·暖阳',Icon='item_3001130',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000010}},Desc='阳光洒在少年青涩的脸庞上，恢弘的咏叹调上达天穹。“我不知道是不是真的有神灵在倾听我的歌声。如果有的话，拜托赐予她更热烈的幸福吧！”',Feature=1,TFValidDate='2020-02-10 05:00:00',ValidDate='2020-02-13 05:00:00',MainColor='c53a07FF',}",
  [3001140] = "{id=3001140,NameZh='晴空祈愿·光羽',Icon='item_3001140',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000010}},Desc='少女眉眼低垂，手心有点点散落的光芒汇聚，那是彼此心意相通的轻语。“你发现了吗？歌声响起时，空气中会有魔法的波动。音符们就这样乘风飞往更远的地方。”',Feature=1,TFValidDate='2020-02-10 05:00:00',ValidDate='2020-02-13 05:00:00',MainColor='3772f0FF',}",
  [3001141] = "{id=3001141,NameZh='晴空祈愿·云雾',Icon='item_3001140',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000010}},Desc='少女眉眼低垂，手心有点点散落的光芒汇聚，那是彼此心意相通的轻语。“其实这是我第一次来到普隆德拉……”“不要紧张，用歌声为整片大陆送去祝福吧！”',Feature=1,TFValidDate='2020-02-10 05:00:00',ValidDate='2020-02-13 05:00:00',MainColor='f283e0FF',}",
  [3001142] = "{id=3001142,NameZh='晴空祈愿·夜影',Icon='item_3001140',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000010}},Desc='少女眉眼低垂，手心有点点散落的光芒汇聚，那是彼此心意相通的轻语。“我好像直到今天，才突然明白了‘爱’是什么感觉……”',Feature=1,TFValidDate='2020-02-10 05:00:00',ValidDate='2020-02-13 05:00:00',MainColor='221c19FF',}",
  [3001143] = "{id=3001143,NameZh='晴空祈愿·暖阳',Icon='item_3001140',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000010}},Desc='少女眉眼低垂，手心有点点散落的光芒汇聚，那是彼此心意相通的轻语。“今天有绚烂的晚霞呢，明天一定又会是个美好的晴天吧！”',Feature=1,TFValidDate='2020-02-10 05:00:00',ValidDate='2020-02-13 05:00:00',MainColor='c53a07FF',}",
