  [3001150] = "{id=3001150,NameZh='晴空轻语·璨星',Icon='item_3001140',Type=501,MaxNum=99,SellPrice=100,Desc='少女的嗓音彷佛被精灵祝福，眼神中也有星光闪烁。“就算是只有一个人说喜欢我的歌声，我也会开心上一整天的！”',Feature=1,TFValidDate='2020-02-10 05:00:00',ValidDate='2020-02-13 05:00:00',MainColor='f8cd56FF',}",
  [3001151] = "{id=3001151,NameZh='天穹颂歌·璨星',Icon='item_3001130',Type=501,MaxNum=99,SellPrice=100,Desc='少年小心整理衣装，用袖口遮挡手臂的伤痕。“袖子好像有些短呢……当然没有关系啦！为了大家，付出再多都是值得的！”',Feature=1,TFValidDate='2020-02-10 05:00:00',ValidDate='2020-02-13 05:00:00',MainColor='f8cd56FF',}",
