  [3001171] = "{id=3001171,NameZh='圣堂之歌',Icon='item_3001171',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15270,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='“啦啦啦~”幸运的冒险者，恭喜得到了唱诗班的眷顾，这是一首专属于你的赞歌哦。打起精神，向着无限可能的明天前进吧！',Feature=1,TFValidDate='2020-02-10 05:00:00',ValidDate='2020-02-13 05:00:00',}",
  [3001172] = "{id=3001172,NameZh='星辰之谕',Icon='item_3001172',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15271,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='“很多很多年前，你的爷爷取下星辰放在我发梢间。等到有一天你长大了，也要亲手为你爱的人戴上它哦。”',Feature=1,TFValidDate='2020-02-10 05:00:00',ValidDate='2020-02-13 05:00:00',}",
  [3001173] = "{id=3001173,NameZh='布莱奇之翼',Icon='item_3001173',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15272,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='嘘~看那些闪烁着的光芒，悄悄告诉你，它们都是诗歌之神拨动琴弦时抖落在人间的精灵！',Feature=1,TFValidDate='2020-02-10 05:00:00',ValidDate='2020-02-13 05:00:00',}",
  [3001174] = "{id=3001174,NameZh='云端乐章',Icon='item_3001174',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15273,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='一年一度的《米德加尔特赞美诗》演奏就要开始了。千万不要眨眼，听说云端会浮现金色的音符，看到的人就会实现心愿呢！',Feature=1,TFValidDate='2020-02-10 05:00:00',ValidDate='2020-02-13 05:00:00',}",
  [3001175] = "{id=3001175,NameZh='真视之镜',Icon='item_3001175',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15274,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='戴上它才不是为了耍帅！可以看见魔法的痕迹，还可以看见……别人的心意呢……',Feature=1,TFValidDate='2020-02-10 05:00:00',ValidDate='2020-02-13 05:00:00',}",
  [3001176] = "{id=3001176,NameZh='圣歌的祝福',Icon='item_3001176',Type=810,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=15275,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='天籁之音划破天际，圣歌的祝福便加诸于勇敢的冒险者。未来的路上一定会有好运相伴吧！',Feature=1,TFValidDate='2020-02-10 05:00:00',ValidDate='2020-02-13 05:00:00',}",
  [3001177] = "{id=3001177,NameZh='赞咏之灵',Icon='item_3001177',Type=90,Quality=5,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000240}},Desc='我是不是最可爱的宠物？说“是”的话，就允许你蹭一蹭我的绒毛，里面藏满了阳光的味道~',Feature=1,TFValidDate='2020-02-10 05:00:00',ValidDate='2020-02-13 05:00:00',}",
  [3001178] = "{id=3001178,NameZh='叹息之灵',Icon='item_3001178',Type=90,Quality=5,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000240}},Desc='要永远葆有一颗少年的心，善良，无畏，真诚。不要掉下眼泪，那些散落天地的灵魂，我一定会替你照顾好他们的。',Feature=1,TFValidDate='2020-02-10 05:00:00',ValidDate='2020-02-13 05:00:00',}",
