  [3001193] = "{id=3001193,NameZh='皇家庆典时装兑换券',Icon='item_3001193',Type=121,MaxNum=99999,SellPrice=100,ComposeID=4000023,Desc='使用之后可以获得一件对应阁下性别的皇家庆典系列时装哦~',Feature=1,}",
  [3001200] = "{id=3001200,NameZh='皇家庆典纪念章',Icon='item_750020',Type=61,UseMode=30026,MaxNum=99999,SellPrice=100,Desc='B格猫星人在皇家庆典期间发行的特殊货币，使用之后可以打开「庆典商城」，兑换各类特殊道具。该道具将在庆典结束后回收，请各位冒险者抓紧使用哦~',ExistTimeType=2,ExistTime='2020-02-08 05:00:00',Feature=1,}",
  [3001201] = "{id=3001201,NameZh='皇家庆典自选礼盒',Icon='item_3000183',Type=30,MaxNum=99999,SellPrice=100,Desc='B格猫星人在这次皇家庆典期间研发的最新礼盒，冒险者可以自行选择获得「皇家庆典解锁卡册」x1，或者是「皇家庆典头饰精炼券」x1。',ExistTimeType=2,ExistTime='2020-05-01 05:00:00',Feature=1,}",
  [3001202] = "{id=3001202,NameZh='皇家庆典头饰精炼券',Icon='item_3032039',Type=41,MaxNum=99999,SellPrice=100,Desc='B格猫星人在一次偶然中发现了魔法缝纫机的秘密，于是就研发出了这个特别的道具，使用之后可以将精炼等级小于10的不可交易的头饰（包括头部、背部、嘴部、尾部、脸部）精炼至10！',ItemTarget={type=4},ExistTimeType=2,ExistTime='2020-05-01 05:00:00',Feature=1,}",
  [3001203] = "{id=3001203,NameZh='皇家庆典头饰毕业券',Icon='item_3032040',Type=41,MaxNum=99999,SellPrice=100,Desc='这个道具包含了B格猫星人对精炼的终极理解，使用之后可以将精炼等级小于15的不可交易的头饰（包括头部、背部、嘴部、尾部、脸部）精炼至15！',ItemTarget={type=4},ExistTimeType=2,ExistTime='2020-05-01 05:00:00',Feature=1,}",
  [3001205] = "{id=3001205,NameZh='皇家庆典解锁卡册',Icon='item_3883',Type=41,MaxNum=99999,SellPrice=100,Desc='B格猫星人的最新科技，使用之后可以解锁一张未解锁的Mini卡片，由于研究还没到位，因此只能解锁，并不能获得对应卡片。如果符合条件的所有卡片均已解锁，那么将可以获得「冒险家硬币」x30。',Feature=1,Delete=3001205}",
  [3001206] = "{id=3001206,NameZh='B格猫的感恩大礼·2020',Icon='item_3961',Type=30,MaxNum=99999,SellPrice=100,Desc='B格猫星人再一次跪着将大礼送到了你的面前，使用之后可以获得2020年2月份幻想创造器Ⅰ号的所有头饰各1个。（需要在2020.02.01之后才可使用）',Feature=1,Delete=3001206}",
  [3001207] = "{id=3001207,NameZh='微笑小姐感恩礼·2020',Icon='item_6068',Type=30,MaxNum=99999,SellPrice=100,Desc='微笑小姐一年一度对冒险者的回馈，打开可以获得随机的绝版头饰图纸。',Feature=1,Delete=3001207}",
  [3001208] = "{id=3001208,NameZh='萌宠感恩礼·2020',Icon='item_6079',Type=30,MaxNum=99999,SellPrice=100,Desc='宠物商人为了感谢各位冒险者这一年来的照顾，特意推出的礼物，打开可以获得1个随机2星及以上品质的宠物蛋（联动宠物不包含在内）。',Feature=1,Delete=3001208}",
  [3001209] = "{id=3001209,NameZh='幻想创造机Ⅰ号的感恩礼·2020',Icon='item_6069',Type=30,MaxNum=99999,SellPrice=100,Desc='幻想创造器Ⅰ号为了感谢各位冒险者这一年来的付出，特意推出的礼物，打开可以随机获得1个在2020年1月以前发行的蓝色品质及以上的头饰。',Feature=1,Delete=3001209}",
  [3001210] = "{id=3001210,NameZh='幻想创造机Ⅲ号的感恩礼·2020',Icon='item_6071',Type=30,MaxNum=99999,SellPrice=100,Desc='幻想创造器Ⅰ号为了感谢各位冒险者这一年来的付出，特意推出的礼物，打开可以获得1张幻想创造机Ⅲ号中的卡片。',Feature=1,Delete=3001210}",
  [3001211] = "{id=3001211,NameZh='2020的第一个礼盒',Icon='item_3000170',Type=30,MaxNum=99999,SellPrice=100,Desc='新一年的第一个礼盒，当然承载了满满的爱意！打开之后可以获得「皇家庆典纪念章」x1、「神秘箱子SP」x2、「金质勋章」x1、「莫拉硬币」x4、「神谕之尘」x2、「神谕之晶」x1，还有概率获得「玛丝黛拉果实」x1。新的一年，也要勇敢地去冒险哟~',Feature=1,Delete=3001211}",
  [3001212] = "{id=3001212,NameZh='皇家庆典礼盒',Icon='item_3838',Type=30,MaxNum=99999,SellPrice=100,Desc='B格猫星人在皇家庆典期间推出的豪华礼盒，打开之后必定获得「B格猫皇家可乐」x5、「B格猫皇家炸鸡」x5、「坠星陨铁」x1，随机获得「B格猫福利券·宴」x5、「B格猫福利券·Ⅰ」x5、「阿斯特蕾亚的善意」x5、「家居提货券」x5、「弗雷硬币」x1~5，还有概率获得超级大奖「B格猫的感恩大礼·2020」x1。',GetLimit={limit={[999]={1,0}},source={22},type=1},Feature=1,Delete=3001212}",
  [3001213] = "{id=3001213,NameZh='一千零一夜的纪念',Icon='item_3900',Type=30,MaxNum=99999,SellPrice=100,Desc='魔女七七给冒险者准备的礼物，打开之后可以获得随机获得以下奖励：「金质勋章」x2、「祈祷晶片包」x2、「神谕之尘」x4、「神谕之晶」x2、「玛丝黛拉种子」x1、「光洁的符文石」x1。',Feature=1,Delete=3001213}",
