  [3001246] = "{id=3001246,NameZh='宅急送异界通讯玩具',Icon='item_3001246',Type=77,MaxNum=99999,SellPrice=100,AdventureSort=113,AdventureValue=1,StorageReward={buffid={82000100}},Condition=8,Desc='传说K上校和KFC炸鸡来自于一个无人知晓的神秘异世界，直到某天，一位冒险者发现了可以与异界通讯的玩具……',Feature=1,TFValidDate='2020-04-22 05:00:00',ValidDate='2020-04-29 05:00:00',Delete=3001246}",
