  [3001248] = "{id=3001248,NameZh='炸鸡之魂图纸',Icon='item_3032248',Type=50,MaxNum=99999,SellPrice=100,ComposeID=3001248,Desc='不要小看美食的力量，味蕾间的每一次绽放都是整个世界对食客的拥抱。对炸鸡怀着虔诚的心，终有一天，炸鸡之魂会降临在身边，让冒险者充满无尽的活力。',Feature=1,Delete=3001248}",
  [3001250] = "{id=3001250,NameZh='KFC能量礼盒',Icon='item_3001250',Type=30,MaxNum=99999,SellPrice=100,Desc='装满了炸鸡料理的KFC能量礼盒，最适合和伙伴们并肩作战时享用了。',Feature=1,Delete=3001250}",
  [3001251] = "{id=3001251,NameZh='指定产品买一送一券',Icon='item_700170',Type=4200,MaxNum=1,SellPrice=100,Desc='拥有这张券，指定产品可以买一送一哦。不过如果只有一个人的话，可要担心一下体重呢……',Feature=1,Delete=3001251}",
  [3001252] = "{id=3001252,NameZh='能量补给料理',Icon='item_3001252',Type=40,MaxNum=99999,AuctionPrice=0,SellPrice=1000,Desc='KFC农场为冒险者们特别准备的补给料理，吃下以后可以获得随机B级料理的增益哦~',Feature=1,Delete=3001252}",
  [3001253] = "{id=3001253,NameZh='游戏渠道专享点餐优惠券',Icon='item_5810',Type=4200,MaxNum=1,SellPrice=100,Desc='为了让所有人都能吃上美味的炸鸡，K上校为冒险者们送上了专享优惠券。',Feature=1,Delete=3001253}",
  [3001254] = "{id=3001254,NameZh='KFC美味礼盒',Icon='item_6519',Type=30,MaxNum=99999,SellPrice=100,Desc='炸鸡大会期间的专属礼盒，奖赏给热心助人的冒险者，还没打开就能闻到香喷喷的味道。',Feature=1,Delete=3001254}",
  [3001255] = "{id=3001255,NameZh='摄影达人礼包',Icon='item_3001255',Type=30,MaxNum=99999,SellPrice=100,Desc='冒险时除了打怪升级，也不要忘记拍下沿途的风景。奖励给摄影爱好者的礼包，打开后会有惊喜哦。',Feature=1,Delete=3001255}",
  [3001261] = "{id=3001261,NameZh='宅急送时装兑换券',Icon='item_3001260',Type=121,MaxNum=99999,SellPrice=100,ComposeID=4000025,Desc='使用之后可以获得一件符合阁下性别的宅急送时装哦~',Feature=1,Delete=3001261}",
  [3001270] = "{id=3001270,NameZh='独眼馆长',Icon='item_3001270',Type=810,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9681,AdventureValue=1,StorageReward={buffid={82000260}},Condition=8,Desc='猎奇藏馆的馆长，沉迷于奇怪事物的他用药剂将自己融化，只留下了一颗眼球，他认为自己是整个藏馆最杰出的作品。每当夜晚来临之时，他都会拿着烛火从三脚框架上滚落，啪嗒啪嗒地在藏馆中巡视着，以免有人觊觎他珍藏的这些猎奇宝物。',Feature=1,TFValidDate='2020-03-01 05:00:00',ValidDate='2020-03-01 05:00:00',LoadShowSize=1.3,LoadShowRotate=180,LoadShowPose={0,0.2,0},}",
  [3001271] = "{id=3001271,NameZh='海怪宝匙',Icon='item_3001271',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9682,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='海怪克拉肯的一节触手，触手上缠绕着一把黄金制的钥匙，匙柄上的红宝石闪耀的让人堕落而沉迷，当不设防备的人触碰这把钥匙的时候，就是海怪克拉肯饱餐的时候。',Feature=1,TFValidDate='2020-03-01 05:00:00',ValidDate='2020-03-01 05:00:00',}",
  [3001272] = "{id=3001272,NameZh='眺望筒',Icon='item_3001272',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9683,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='沉船蓝色菲力号上发现的金属制眺望筒，一旦戴到脸上就再也难以摘下，它的触手会渗入你的血管，吸食你的血液，最终与你融为一体，不过相对的，你可以看见的范围会变得极其广阔，这样看来也是一桩不错的交易。',Feature=1,TFValidDate='2020-03-01 05:00:00',ValidDate='2020-03-01 05:00:00',LoadShowSize=2,LoadShowPose={0,0.3,0},}",
  [3001273] = "{id=3001273,NameZh='希尔的伯爵帽[1]',Icon='item_3001273',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9684,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='希尔大人是血统最高鬼的血族，而我身为希尔大人的帽子，也是至高无上的存在，我是希尔大人权利与地位的象征，人类，沦为我的口粮吧！',Feature=1,TFValidDate='2020-03-01 05:00:00',ValidDate='2020-03-01 05:00:00',}",
  [3001274] = "{id=3001274,NameZh='小克拉肯[1]',Icon='item_3001274',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9685,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='水手维恩斯在出海的时候发现的魔物，航海数十年的他从未见过如此凶猛奇特的魔物，他称它为小克拉肯，在牺牲了一条手臂的代价后将它捕获，现今它的标本收藏在猎奇藏馆中。',Feature=1,TFValidDate='2020-03-01 05:00:00',ValidDate='2020-03-01 05:00:00',}",
  [3001275] = "{id=3001275,NameZh='塔卡沙之书',Icon='item_3001275',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9686,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='“这本书里藏着所有你想知道的秘密哦，来，快点打开它！”“这些触手是什么？”“这是我可爱的小宠物瑞恩，它会吃掉那些怀揣着不好心思的家伙，不过不要害怕，你看起来并不是它喜欢的味道~”',Feature=1,TFValidDate='2020-03-01 05:00:00',ValidDate='2020-03-01 05:00:00',}",
  [3001276] = "{id=3001276,NameZh='沉默者',Icon='item_3001276',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9054,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='名画《沉默者》，出自米德加尔特大陆最有名的画师——洛丁芬·修尔。不过洛丁芬大师在绘制完这幅画之后就神秘失踪了，没有人能找到他的下落，有人说在夜晚的时候在画中看到了洛丁芬的脸，有人说洛丁芬就是画中的人，众说纷纭之下，真相又有谁知晓呢？',Feature=1,TFValidDate='2020-03-01 05:00:00',ValidDate='2020-03-01 05:00:00',LoadShowSize=4,LoadShowRotate=-15,LoadShowPose={0,0.5,0},}",
  [3001301] = "{id=3001301,NameZh='丝尾天蝎',Icon='item_3001301',Type=810,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10175,AdventureValue=1,AdventureReward={buffid={64000360}},StorageReward={buffid={80012810}},Condition=8,Desc='长长的尾巴镌刻着星辰大海，天蝎走过的路即是星河。',Feature=1,TFValidDate='2022-10-19 05:00:00',ValidDate='2022-10-26 05:00:00',}",
  [3001303] = "{id=3001303,NameZh='永恒射手',Icon='item_3001303',Type=840,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10176,AdventureValue=1,AdventureReward={buffid={63000090}},StorageReward={buffid={80012870}},Condition=8,Desc='星辰不灭，射手的征程就不会停歇，下一个目标会是谁？',}",
  [3001304] = "{id=3001304,NameZh='绅士魔羯',Icon='item_3001304',Type=810,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10177,AdventureValue=1,AdventureReward={buffid={62000040}},StorageReward={buffid={82000030}},Condition=8,Desc='如诗人般注视着满天星宇，没人知道他在想什么，就像没人知道他的礼服下藏着什么。',Feature=1,TFValidDate='2022-12-01 05:00:00',ValidDate='2022-12-01 05:00:00',LoadShowRotate=160,LoadShowPose={0,0.3,0},}",
  [3001306] = "{id=3001306,NameZh='铃角白羊',Icon='item_3001306',Type=810,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10180,AdventureValue=1,AdventureReward={buffid={62000040}},StorageReward={buffid={82000030}},Condition=8,Desc='性情似火，快意星辰，不论走到哪都叮叮当当，大家，请注视我吧！',Feature=1,TFValidDate='2023-03-02 05:00:00',ValidDate='2023-03-09 05:00:00',}",
  [3001307] = "{id=3001307,NameZh='曳光双鱼',Icon='item_3001307',Type=840,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10179,AdventureValue=1,AdventureReward={buffid={63000090}},StorageReward={buffid={80012870}},Condition=8,Desc='虚幻飘渺，若即若离，无从查起，无处不在。',Feature=1,TFValidDate='2023-02-16 05:00:00',ValidDate='2023-02-23 05:00:00',}",
  [3001308] = "{id=3001308,NameZh='星河水瓶',Icon='item_3001308',Type=840,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10178,AdventureValue=1,AdventureReward={buffid={64000360}},StorageReward={buffid={80012810}},Condition=8,Desc='瓶身上铭刻着他的星辰，星河中流淌着他的光阴。',Feature=1,TFValidDate='2022-12-29 05:00:00',ValidDate='2023-01-05 05:00:00',}",
  [3001320] = "{id=3001320,NameZh='地渊悲鸣[1]',Icon='item_3001320',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9675,AdventureValue=1,StorageReward={buffid={82000260}},Condition=8,Desc='鬼女在哀嚎，九尾狐在咆哮，但地渊的枷锁永世不破。',TFValidDate='2020-02-01 05:00:00',ValidDate='2020-02-01 05:00:00',}",
  [3001321] = "{id=3001321,NameZh='永恒奴役',Icon='item_3001321',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9676,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='这里没有是非善恶，没有正邪强弱，只有日复一日的囚禁与奴役。',TFValidDate='2020-02-01 05:00:00',ValidDate='2020-02-01 05:00:00',}",
  [3001322] = "{id=3001322,NameZh='结云铃扇',Icon='item_3001322',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9677,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='纠缠繁杂的命运之线，牢牢锁着世间万物，即使是天上的流云也不能逃脱它的束缚。',TFValidDate='2020-02-01 05:00:00',ValidDate='2020-02-01 05:00:00',}",
  [3001323] = "{id=3001323,NameZh='诗菊短册',Icon='item_3001323',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9678,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='写满了密密麻麻的小字，都是被囚禁之人的愿望，上面充满了对光明的向往与希冀。',TFValidDate='2020-02-01 05:00:00',ValidDate='2020-02-01 05:00:00',}",
  [3001324] = "{id=3001324,NameZh='武魂信仰',Icon='item_3001324',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9679,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='纵然肉身死亡，灵魂腐朽，但武士的信仰始终如刀刃般锋锐。',TFValidDate='2020-02-01 05:00:00',ValidDate='2020-02-01 05:00:00',}",
  [3001325] = "{id=3001325,NameZh='虞眉姬',Icon='item_3001325',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9680,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='“光明消逝，希望破碎，她随之流干了血泪。”',TFValidDate='2020-02-01 05:00:00',ValidDate='2020-02-01 05:00:00',}",
  [3001326] = "{id=3001326,NameZh='怨毒的面容',Icon='item_3001326',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9053,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='般若，幽怨和嫉妒的具象化，即使被符咒镇压，也仍保持着一副狰狞的恐怖面孔。',TFValidDate='2020-02-01 05:00:00',ValidDate='2020-02-01 05:00:00',}",
