  [3001340] = "{id=3001340,NameZh='十方柱人·仁',Icon='item_3001340',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='吾等不懂何为胜利，只懂得绝不落后，吾等会预知危险，将黑暗扼杀于萌芽，舍吾等生命，护我所爱之人，人生短暂，吾等必将负重而前行，此为柱人之本源。',Feature=1,TFValidDate='2020-03-16 05:00:00',ValidDate='2020-03-19 05:00:00',MainColor='4b3f5dFF',}",
