  [3001375] = "{id=3001375,NameZh='舞姬·乱',Icon='item_3001375',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='少女用精致的花簪将秀发束起，微风轻拂，一片两片的花瓣飘落飞散，少女随着芬芳起舞，相会与别离，人生总是这样的轮转，只因如此，那段与你共同度过的岁月才会刻骨铭心，一曲终了，脚步声渐近，少女看着来人笑颜如花，我知道，你我终会再次相遇。',Feature=1,TFValidDate='2020-03-16 05:00:00',ValidDate='2020-03-19 05:00:00',MainColor='56291eFF',}",
