  [3001381] = "{id=3001381,NameZh='繁樱·不知名',Icon='item_3001381',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15280,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='散尽繁樱不知归处，花开花落终成过往。',Feature=1,TFValidDate='2020-03-16 05:00:00',ValidDate='2020-03-19 05:00:00',LoadShowSize=1.3,LoadShowPose={0,0.4,0},}",
  [3001382] = "{id=3001382,NameZh='祈鹤',Icon='item_3001382',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15281,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='纸鹤是爱的守护神，承载了一个又一个爱的期许，无论恋人相聚多远，只要这纸鹤在彼此身边，爱人就终会相遇。',Feature=1,TFValidDate='2020-03-16 05:00:00',ValidDate='2020-03-19 05:00:00',LoadShowSize=1.5,LoadShowPose={0,0.1,0},}",
  [3001383] = "{id=3001383,NameZh='望川樱',Icon='item_3001383',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15282,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='年少时樱花树下一起许下了誓言，你说你要守护所热爱的疆土成为真正的英雄，我说我也是如此，可是你不知道的是，我想守护的只有你。',Feature=1,TFValidDate='2020-03-16 05:00:00',ValidDate='2020-03-19 05:00:00',LoadShowSize=3.6,LoadShowPose={0,0.4,0},}",
  [3001384] = "{id=3001384,NameZh='樱鬼',Icon='item_3001384',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15283,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='“传言樱花之灵落泪便会变为樱鬼，会伤害路过樱花树的人类。”少女疑惑地看向粉色头发的少年，少年摘下脸上的狐狸面具戴到少女头上，宠溺地摸了摸少女的头顶“有时候，书上说的也不一定是真的，要亲眼看到才知道哦~”',Feature=1,TFValidDate='2020-03-16 05:00:00',ValidDate='2020-03-19 05:00:00',LoadShowSize=2,LoadShowPose={0,0,0},}",
  [3001385] = "{id=3001385,NameZh='樱纹舞翼',Icon='item_3001385',Type=810,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=15284,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='一瓣，两瓣，花飞散，三瓣，四瓣，樱缭乱。月夜寂寥，哀歌鸣响，希望之丘，遥远彼端，繁华世界，终将覆灭，绽放之花，唯有樱之舞可乱繁华。',Feature=1,TFValidDate='2020-03-16 05:00:00',ValidDate='2020-03-19 05:00:00',LoadShowSize=1.3,LoadShowRotate=-15,LoadShowPose={0,0,0},}",
  [3001386] = "{id=3001386,NameZh='花嫁·枫落',Icon='item_3001386',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15285,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='红枫飘落，少年拾起最灿烂的一朵，轻轻的夹在少女的发间，热烈的红枫映着少女绯红的脸颊，这是世间最青涩的告白。',Feature=1,TFValidDate='2020-03-16 05:00:00',ValidDate='2020-03-19 05:00:00',}",
  [3001387] = "{id=3001387,NameZh='花嫁·樱散',Icon='item_3001387',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15286,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='落樱缤纷，少女踮起脚尖轻轻拂去少年头顶嫩色的花瓣，少年恰好转身，四目相对转颜一笑，樱花在这氛围中都黯然失色。',Feature=1,TFValidDate='2020-03-16 05:00:00',ValidDate='2020-03-19 05:00:00',}",
  [3001390] = "{id=3001390,NameZh='庆典王冠',Icon='item_3001390',Type=800,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80012660}},Desc='从这一场盛大的庆典开始，成为王、成为唯一、成为能够照亮你的光！',Feature=1,TFValidDate='2019-12-27 05:00:00',ValidDate='2020-01-01 05:00:00',}",
