  [3001392] = "{id=3001392,NameZh='庆典王冠系列头饰',Icon='item_3001392',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10195,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,TFValidDate='2019-12-27 05:00:00',ValidDate='2020-01-01 05:00:00',}",
  [3001400] = "{id=3001400,NameZh='傀儡之心',Icon='item_3001400',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10198,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='将你对我的爱融入这颗宝石，如果是真心，宝石便会闪烁出璀璨的光芒，那么你便可以拥有这顶王冠，当然，如果爱意是虚假的，那么你将会成为的傀儡，永远的失去自由，你想要做这场赌博么？',Feature=1,TFValidDate='2020-02-23 05:00:00',ValidDate='2020-03-01 05:00:00',LoadShowSize=3,LoadShowPose={0.2,0.2,0},}",
  [3001401] = "{id=3001401,NameZh='心芽芽图纸',Icon='item_3001401',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=3001401,Desc='传说来自爱之国度的种子，将它埋入土壤细心浇灌，在阳光的沐浴下，爱的枝芽便会破土而出，为你带来温暖与幸福',}",
  [3001420] = "{id=3001420,NameZh='恶兽假面图纸',Icon='item_3032420',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=3001420,Desc='“你知道吗？恶兽并不邪恶，之所以被称为恶兽，是因为它想亲近人类，却把人类吓坏了。说这个其实是想告诉你，很抱歉戴着面具恶作剧，但我只是想要亲近你……”',}",
  [3001421] = "{id=3001421,NameZh='年兽徽章',Icon='item_3001421',Type=61,UseMode=30027,MaxNum=99999,SellPrice=100,Desc='藏在年兽身上的精致徽章，证明冒险者拥有打败年兽的实力，似乎还有一些特殊的用途？',ExistTimeType=2,ExistTime='2023-02-01 05:00:00',Delete=3001421}",
  [3001422] = "{id=3001422,NameZh='新春鞭炮',Icon='item_3001422',Type=64,MaxNum=99999,AuctionPrice=1,SellPrice=10,Desc='传说中东方国度，为了庆祝新年的习俗之一，用古老的配方制作的小纸管，点燃可以在夜空绽放出五彩斑斓的花火。习俗的来源据说是为了驱赶某些邪恶事物。使用时请注意安全！请勿对着其他冒险者点燃！',GetLimit={limit={[999]={800,0}},source={22},type=1},Delete=3001422}",
  [3001423] = "{id=3001423,NameZh='B格猫守岁红包·2020',Icon='item_6504',Type=30,MaxNum=99999,SellPrice=100,Desc='新的一年，作为大陆上最有钱的喵星人，本喵要给你们每个人都发守岁红包~喵呜~\n开启后获得「B格猫福利券·I」×30、「B格猫福利券·宴」×60，并随机获赠以下道具中的一种：「莫拉硬币」×10、「神谕之尘」×10、「神谕之晶」×10、「金质勋章」×5、「玛丝黛拉果实」×1、「祈祷晶片包」×5',Delete=3001423}",
  [3001424] = "{id=3001424,NameZh='子神的祝福',Icon='item_3001424',Type=30,MaxNum=99999,SellPrice=100,Desc='来自于子神的新年祝福礼盒，据说只有心怀善意的冒险者才会得到，使用后必定获得「B格猫福利券·Ⅰ」x3、「B格猫福利券·宴」x3、并随机获赠「祈祷晶片包」x2、「光洁的符文石」x1、「玛丝黛拉种子」x1、「尘封的符文袋·Ⅱ」x1、「荣誉之证」x1000 哦！',Delete=3001424}",
  [3001426] = "{id=3001426,NameZh='子神赐福',Icon='item_3001426',Type=30,MaxNum=99999,SellPrice=100,Desc='子神的谢礼，使用后必定获得「B格猫皇家红包·2020」x1、「七彩贝壳」x100、「新春鞭炮」x50，有10%概率获赠「年兽徽章」x1哦！',Delete=3001426}",
  [3001427] = "{id=3001427,NameZh='鎏金闹闹鱼魔物蛋',Icon='item_3001427',Type=101,MaxNum=1,SellPrice=100,Desc='活泼好动的异兽，总是充满激情而有些神经兮兮的，想要蹭它好运的人都要忍受它过于旺盛的精力。',TFValidDate='2020-01-17 5:00:00',ValidDate='2020-01-24 5:00:00',}",
  [3001428] = "{id=3001428,NameZh='玛瑙闹闹鱼',Icon='item_3001428',Type=41,MaxNum=99999,SellPrice=100,Desc='新春期间流行的宠物染色剂，看起来可以给鎏金闹闹鱼使用。',}",
  [3001429] = "{id=3001429,NameZh='珍珠闹闹鱼',Icon='item_3001429',Type=41,MaxNum=99999,SellPrice=100,Desc='新春期间流行的宠物染色剂，看起来可以给鎏金闹闹鱼使用。',}",
  [3001430] = "{id=3001430,NameZh='白玉闹闹鱼',Icon='item_3001430',Type=41,MaxNum=99999,SellPrice=100,Desc='新春期间流行的宠物染色剂，看起来可以给鎏金闹闹鱼使用。',}",
  [3001431] = "{id=3001431,NameZh='万家灯火·金',Icon='item_3001431',Type=30,MaxNum=99999,SellPrice=100,Desc='世界上最美好的画面，莫过于在万家灯火中，看到她的蓦然回首。\n开启后必定获得「元宵料理」×10、「金质勋章」×1、「祈祷晶片包」×1、「冒险丸子」×200、「料理兑换券」×1，并随机获赠「璀璨星灯图纸」×1',}",
  [3001432] = "{id=3001432,NameZh='万家灯火·银',Icon='item_3001432',Type=30,MaxNum=99999,SellPrice=100,Desc='世界上最美好的画面，莫过于在万家灯火中，看到她的蓦然回首。\n开启后必定获得「元宵料理」×10、「秘银」×1、「祈祷晶片包」×1、「冒险丸子」×200、「料理兑换券」×1，并随机获赠「璀璨星灯图纸」×1',}",
  [3001433] = "{id=3001433,NameZh='甜蜜礼物盒',Icon='item_3844',Type=30,MaxNum=99999,SellPrice=100,Desc='包装精美的甜蜜礼盒，就像是在少女梦中出现过的那样。光是看着就让人不禁赞叹造物的美好，打开之后还会得到丰厚的礼物。',}",
  [3001434] = "{id=3001434,NameZh='爱的电灯泡图纸',Icon='item_3032434',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=3001434,Desc='“你们看起来好甜蜜呀，我可以和你们一起玩吗？哎呀呀，别跑嘛……”据说只要戴上，就会成为人群中最闪亮的电灯泡。虽然似乎会遭到一些情侣的嫌弃，但也能吸引更多人的目光，增加找到自己理想伴侣的几率哦！',}",
  [3001435] = "{id=3001435,NameZh='爱之代理人的赠礼',Icon='item_3001435',Type=64,MaxNum=99999,SellPrice=100,Desc='爱之代理人赠予冒险者的礼物，蕴含着温暖的爱意，可以用来合成情人节限定卡片「爱之代理人」。',ExistTimeType=2,ExistTime='2020-02-21 05:00:00',}",
  [3001437] = "{id=3001437,NameZh='璀璨星灯图纸',Icon='item_3032437',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=3001437,Desc='一盏盏星灯是人间的心愿，升到空中汇聚成了星河。灯火点燃时，孩子们都欢呼雀跃，踮起脚来抬头仰望。仿佛灯火飞得越高，他们的愿望就离实现更近了一些。',}",
  [3001438] = "{id=3001438,NameZh='静水云露',Icon='item_3001438',Type=103,MaxNum=99999,SellPrice=100,Desc='不知是天上云还是湖中水的神奇物质，是魔物鎏金闹闹鱼最喜爱的食物。',}",
  [3001439] = "{id=3001439,NameZh='B格猫皇家红包·2020',Icon='item_3001439',Type=30,MaxNum=99999,SellPrice=100,Desc='来自B格猫的皇家红包，是非常珍贵的新年礼物呢！',Delete=3001439}",
  [3001450] = "{id=3001450,NameZh='守护之翼',Icon='item_3001450',Type=810,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012640}},Desc='左手的盾，将因守护挚爱之人而坚持；右手的剑，将为斩尽邪恶之灵而紧握。冒险者的一生，将与汗水和勇气同行，也会在伤痛褪尽后，与同伴一起沐浴在和煦的阳光之下，漫步于缤纷的花海之中。',StageDisplay=0,LoadShowSize=1,}",
  [3001451] = "{id=3001451,NameZh='永恒之羽',Icon='item_3001451',Type=810,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012640}},Desc='漫天的星辰汇聚成璀璨的银河，森林中的虫鸣编织成悠扬的交响曲。冒险之路铺成坦途，通向光荣铸就的未来。前行吧！永远不要舍弃并肩携手的伙伴，也永远不要忘记曾经约定的誓言。',StageDisplay=0,LoadShowSize=1,}",
  [3001452] = "{id=3001452,NameZh='天使羽翼系列背饰',Icon='item_3001452',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10188,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,StageDisplay=0,LoadShowSize=1,}",
  [3001453] = "{id=3001453,NameZh='守护之星',Icon='27',Type=10,SellPrice=100,Desc='左手的盾，将因守护挚爱之人而坚持；右手的剑，将为斩尽邪恶之灵而紧握。',}",
  [3001454] = "{id=3001454,NameZh='永恒之星',Icon='27',Type=10,SellPrice=100,Desc='永远不要舍弃并肩携手的伙伴，也永远不要忘记曾经约定的誓言。',}",
  [3001460] = "{id=3001460,NameZh='彼得温蒂',Icon='item_3001460',Type=840,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9687,AdventureValue=1,StorageReward={buffid={82000250}},Condition=8,Desc='彼得温蒂是这只提线垂耳兔的名字，同时也是幻想马戏团团长的名字，有人说团长是个可爱的少女，也有人说团长是个垂暮的老人，但是其具体的样子从未被外人见过，他每次都是以提线垂耳兔的样子出现，软萌的垂耳兔看似可爱无害，瞳孔却有着神奇的魔力，可以轻易的窥探所有人的内心。',Feature=1,TFValidDate='2020-04-01 05:00:00',ValidDate='2020-04-01 05:00:00',LoadShowSize=1.5,LoadShowPose={0,0.1,0},}",
  [3001461] = "{id=3001461,NameZh='杂耍天后',Icon='item_3001461',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9688,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='杂耍天后碧斯特的专属面具，作为幻想马戏团的人气明星，碧斯特高超的杂技技巧令所有慕名而来的观众折服，刻画着繁复花纹的面具更是她的标志处所在，传言这幅面具来源于大陆上最古老的杂耍家族，具有着使人沉迷的魔力。',Feature=1,TFValidDate='2020-04-01 05:00:00',ValidDate='2020-04-01 05:00:00',LoadShowSize=2,LoadShowPose={0,0,0},}",
  [3001462] = "{id=3001462,NameZh='约翰逊的帽子[1]',Icon='item_3001462',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9689,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='约翰逊是幻想马戏团的魔术师，不过很少有人见识过他的演出，他只在每年的月圆之日才会出现演出，传言所有看过他演出的人很久都不能从那场演出中脱离出来，并且嘴里还会不停地呢喃着“那不是魔术，那是奇迹的存在！”',Feature=1,TFValidDate='2020-04-01 05:00:00',ValidDate='2020-04-01 05:00:00',}",
  [3001463] = "{id=3001463,NameZh='逆转时钟',Icon='item_3001463',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9690,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='逆转时钟挂在幻想马戏团的正中心，与其它时钟不同的是，这座时钟的指针是逆时针流转的，马戏团针对时钟对外宣称，这样可以让观众忘记时间的流逝，全身心的去体会马戏团的演出，不过这其中真正的用意，只有去观看演出才能知晓了吧。',Feature=1,TFValidDate='2020-04-01 05:00:00',ValidDate='2020-04-01 05:00:00',LoadShowSize=1.5,LoadShowRotate=180,LoadShowPose={0,0.5,0},}",
  [3001464] = "{id=3001464,NameZh='命运卡牌',Icon='item_3001464',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9691,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='这是幻像马戏团为所有观众派发的入场券，其造型与扑克牌相似，每场演出结束后，马戏团都会挑选一种花色的数字的作为特殊卡牌，而拥有这位特殊卡牌的观众将会欣赏到一场从不对外公开的演出，不过所有看完特别演出的观众都会逐渐的被人们遗忘，变成“从未存在的人”。',Feature=1,TFValidDate='2020-04-01 05:00:00',ValidDate='2020-04-01 05:00:00',}",
  [3001465] = "{id=3001465,NameZh='月亮与骰子[1]',Icon='item_3001465',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9692,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='“欢迎光临幻想马戏团，我是马戏团的王牌——小丑杰克，今天的演出会是什么呢？一切请让骰子来决定吧！”小丑旋转着帽子右侧的红宝石骰子，旋转的骰子在月光下折射出梦幻的光芒，小丑的嘴角咧到了极致“让我们看看今天的数字是几呢？”',Feature=1,TFValidDate='2020-04-01 05:00:00',ValidDate='2020-04-01 05:00:00',}",
  [3001466] = "{id=3001466,NameZh='多格的谢幕礼',Icon='item_3001466',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9055,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='幻想马戏团的飞刀师多格是所有女性观众的梦中情人，英俊帅气的外表和完美的绅士礼仪让多格的每场飞刀秀都是人气爆棚，尤其是每场的谢幕之时，多格都会抛出一把软质飞刀，接到的观众会被邀请与多格共舞，这是所有的女性观众都梦寐以求的时刻。',Feature=1,TFValidDate='2020-04-01 05:00:00',ValidDate='2020-04-01 05:00:00',}",
  [3001470] = "{id=3001470,NameZh='恩德勒斯塔双倍奖励',Icon='item_3952',Type=74,Quality=2,MaxNum=1,SellPrice=100,Desc='卡普拉给予回归玩家的特殊奖励，在「卡普拉的指引」状态下，挑战恩德勒斯塔可以获得双倍奖励！（通关时直接获得双倍奖励收益）',Delete=3001470}",
