  [3001560] = "{id=3001560,NameZh='仪礼使者·彗星',Icon='item_3001550',Type=501,MaxNum=99,SellPrice=100,Desc='作为仪礼的使者，时时在旅途中的少女总是希望每次要去的目的地她都能快快到达，“而我的梦想就是骑上彗星，疾驰在美丽的星空之上！”',Feature=1,TFValidDate='2020-04-13 05:00:00',ValidDate='2020-04-16 05:00:00',MainColor='2b799cFF',}",
  [3001561] = "{id=3001561,NameZh='秩序卫士·彗星',Icon='item_3001520',Type=501,MaxNum=99,SellPrice=100,Desc='维护星空下的祥和秩序是少年的使命所在，而现在，他已整装待发。“相信我们这场征程的最后，也一定会如同彗星一般，有一个明亮闪耀的尾巴！”',Feature=1,TFValidDate='2020-04-13 05:00:00',ValidDate='2020-04-16 05:00:00',MainColor='2b799cFF',}",
