  [3001581] = "{id=3001581,NameZh='星海之漏',Icon='item_3001581',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15291,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='万千星辰在沙漏间缓缓流转，收下它吧，瞧，现在你已经拥有了一片小小的星空。',Feature=1,TFValidDate='2020-04-13 05:00:00',ValidDate='2020-04-16 05:00:00',}",
  [3001582] = "{id=3001582,NameZh='紫耀之眼',Icon='item_3001582',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15292,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='可以借给我一颗星星吗？我可以用它来观量整个世界！',Feature=1,TFValidDate='2020-04-13 05:00:00',ValidDate='2020-04-16 05:00:00',}",
  [3001583] = "{id=3001583,NameZh='紫耀之灵',Icon='item_3001583',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15293,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='什么，我才不是把自己涂抹成一颗星星的小仓鼠呢……我可是，从那片星空之上远道而来的精灵！',Feature=1,TFValidDate='2020-04-13 05:00:00',ValidDate='2020-04-16 05:00:00',}",
  [3001584] = "{id=3001584,NameZh='永夜流光',Icon='item_3001584',Type=810,Quality=5,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=15294,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='划破黑夜的，是一颗颗流星，是闪亮的你。向夜空飞去吧，你也会成为一道流光。',Feature=1,TFValidDate='2020-04-24 05:00:00',ValidDate='2020-05-01 05:00:00',}",
  [3001585] = "{id=3001585,NameZh='星河王冠',Icon='item_3001585',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15295,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='群星环绕在你的威严之下，仁慈和公正是作为君主的你所应有的品德。',Feature=1,TFValidDate='2020-04-13 05:00:00',ValidDate='2020-04-16 05:00:00',}",
  [3001586] = "{id=3001586,NameZh='星河之魅',Icon='item_3001586',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15296,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='星河在你的眉眼间流淌，这份优雅的魅力独一无二。',Feature=1,TFValidDate='2020-04-13 05:00:00',ValidDate='2020-04-16 05:00:00',}",
  [3001590] = "{id=3001590,NameZh='月落破晓',Icon='item_3001590',Type=90,Quality=5,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000240}},Desc='月亮落下去了，天色将明的时分，它像一道曙光掠过广阔的原野。“应着你的呼唤而来，我的主人。从黑夜出发，我将为您带来破晓！”',Feature=1,TFValidDate='2020-04-13 05:00:00',ValidDate='2020-04-16 05:00:00',}",
  [3001591] = "{id=3001591,NameZh='暗夜星沉',Icon='item_3001591',Type=90,Quality=5,MaxNum=1,SellPrice=100,AdventureReward={buffid={63000240}},Desc='令天上的群星也敬畏地隐去它们的光辉的，是你吗，暗夜的君王？“应着你的呼唤而来，我的主人。不必畏惧黑夜，我将为您指引前路！”',Feature=1,TFValidDate='2020-04-13 05:00:00',ValidDate='2020-04-16 05:00:00',}",
  [3001592] = "{id=3001592,NameZh='月落星沉系列坐骑',Icon='item_3001590',Type=90,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=1014,AdventureValue=100,AdventureReward={buffid={63000240}},Condition=8,Feature=1,TFValidDate='2020-04-13 05:00:00',ValidDate='2020-04-16 05:00:00',}",
  [3001600] = "{id=3001600,NameZh='温暖的棒球帽[1]',Icon='item_3001600',Type=800,MaxNum=99,SellPrice=100,AdventureSort=10200,AdventureValue=1,StorageReward={buffid={80011150}},Condition=8,Desc='这一抹鲜艳的粉，像极了我第一次遇见的你，在那个大雪纷飞的午后，你毫无征兆地就闯进了我的世界。',Feature=1,TFValidDate='2020-01-15 05:00:00',ValidDate='2020-01-15 05:00:00',}",
  [3001601] = "{id=3001601,NameZh='耀金晶石',Icon='item_6204',Type=30,MaxNum=99999,SellPrice=100,Desc='散发着金色的流光，蕴含着无比强大的力量，这是女王大人赐予你的礼物。打开后可获得「B格猫福利券·宴」x2、「金质勋章」x1、「尘封的符文石Ⅰ」x2。',Feature=1,}",
  [3001603] = "{id=3001603,NameZh='蔚蓝晶石',Icon='item_6207',Type=30,MaxNum=99999,SellPrice=100,Desc='散发着蓝色的流光，蕴含着无比强大的力量，这是女王大人赐予你的礼物。打开后可获得「B格猫福利券·Ⅰ」x2、「坠星陨铁」x1、「神谕之晶」x2。',Feature=1,}",
  [3001604] = "{id=3001604,NameZh='星紫晶石',Icon='item_6225',Type=30,MaxNum=99999,SellPrice=100,Desc='散发着紫色的流光，蕴含着无比强大的力量，这是女王大人赐予你的礼物。打开后可获得「B格猫福利券·Ⅱ」x2、「光洁的符文石」x1、「神秘箱子SP」x3。',Feature=1,}",
  [3001605] = "{id=3001605,NameZh='女王大人的恩赐',Icon='item_6632',Type=30,MaxNum=99999,SellPrice=100,Desc='屈服于本女王的实力，沉迷于本女王的美貌，本女王的追随者，这是本女王给你的恩赐。使用后有概率获得「神谕之晶」x6、「神谕之尘」x8、「光洁的符文石」x1、「闪耀的符文石」x1、「玛斯黛拉果实」x1、「金质勋章」x4、「祈祷晶片包」x4中的一种。',Feature=1,}",
  [3001606] = "{id=3001606,NameZh='女王大人的嘉奖',Icon='item_3961',Type=30,MaxNum=99999,SellPrice=100,Desc='哼，你的行为到是让本女王对你刮目相看，这是给你的礼物，拿去珍藏好不要让其他人看到！使用后有概率获得「金质勋章」x2、「莫拉硬币」x4、「祈祷晶片包」x2、「玛丝黛拉种子」x1、「坠星陨铁」x1、「来自女武神的馈赠」x2中的一种。',Feature=1,}",
  [3001607] = "{id=3001607,NameZh='黑猫徽章',Icon='item_700162',Type=61,Quality=3,UseMode=30029,MaxNum=99999,SellPrice=100,Desc='感谢您守护了喵星的安定，使用后可以选择兑换：「黑猫·K魔物蛋」、「甜心萌喵」（黑猫·K限定皮肤）、「布偶布偶」（黑猫·K限定皮肤）',ExistTimeType=2,ExistTime='2023-02-01 05:00:00',Feature=1,}",
  [3001608] = "{id=3001608,NameZh='布偶布偶',Icon='item_900189',Type=41,MaxNum=1,SellPrice=100,Desc='来自异世界珍贵的品种，呆萌可爱~虽然我本质还是黑猫啦~喵~使用后将解锁黑猫·K的布偶布偶外观。',Feature=1,}",
  [3001609] = "{id=3001609,NameZh='KFC萌芽礼盒',Icon='item_3725',Type=30,MaxNum=99999,SellPrice=100,Desc='KFC为你送来最真挚的祝福，与心爱的人一起度过这浪漫的季节。打开后可获得「料理兑换券」x1、「冒险丸子」x300、「阿斯特蕾亚的善意」x5、「九界原石」x1。',Feature=1,}",
  [3001610] = "{id=3001610,NameZh='爱之礼包',Icon='item_6568',Type=30,MaxNum=99999,SellPrice=100,Desc='与爱同行，最重要的就是不忘初心，打开可以获得「B格猫福利券·Ⅰ」x30、「B格猫福利券·宴」x30、「萌宠感恩礼·2020」x1',Delete=3001610}",
  [3001611] = "{id=3001611,NameZh='与爱同行',Icon='item_6568',Type=10,MaxNum=1,SellPrice=100,Desc='在冒险的过程中，只有与爱同行，才能成就永恒！',Feature=1,TFValidDate='2020-01-15 05:00:00',ValidDate='2020-01-15 05:00:00',Delete=3001611}",
