  [3001743] = "{id=3001743,NameZh='黑猫礼盒',Icon='item_3000193',Type=30,MaxNum=9999,SellPrice=100,Desc='蕴藏神秘魔力的盒子，据说拿着对鱼干许愿就可以召唤莫奇哦~打开后有概率获得「七彩贝壳」250~550个、「七级天赋果实」3~6个，有10%概率额外获得「黑猫徽章」x1。',Feature=1,Delete=3001743}",
  [3001744] = "{id=3001744,NameZh='女王祝福礼盒',Icon='item_1000009',Type=30,MaxNum=9999,SellPrice=100,Desc='\"每天都要开开心心哦~\"早起的安娜对着镜子里的自己如是说道。打开后必定获得「血迹树枝SP」x2，「魔力树枝SP」x2。',Feature=1,Delete=3001744}",
  [3001760] = "{id=3001760,NameZh='破损的卡普拉服务券',Icon='item_3001760',Type=61,UseMode=30032,MaxNum=9999,SellPrice=10,Desc='不知什么原因破损的卡普拉服务券，也许拼凑完整还能够使用？不如问问当地的卡普拉服务人员吧。',GetLimit={limit={[999]={800,0}},source={22},type=1},ExistTimeType=2,ExistTime='2020-06-01 05:00:00',}",
