  [3001765] = "{id=3001765,NameZh='罗伯特的环游礼盒',Icon='item_3001765',Type=30,MaxNum=9999,SellPrice=100,Desc='瞧一瞧看一看啦，吉芬的魔法杖，古城的风化头盔，还有梦罗克的狼毛~什么？你不想要！那好吧，剩下的只有这些了……',}",
