  [3001866] = "{id=3001866,NameZh='维德的神秘礼盒',Icon='item_3977',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='维德奉上的祝愿礼盒，祝愿陪伴旅行的冒险者事事顺遂。打开后有概率获得「神谕之晶」x2、「神谕之尘」x4、「光洁的符文石」x1、「来自女武神的馈赠」x2、「祈祷晶片包」x2、「玛丝黛拉种子」x1。',Feature=1,}",
  [3001867] = "{id=3001867,NameZh='维德的谢礼',Icon='item_3976',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='维德奉上的答谢礼盒，馈赠陪伴旅行的冒险者，感谢冒险者的努力。打开后可获得「神谕之晶」x6、「神谕之尘」x8、「光洁的符文石」x2、「来自女武神的馈赠」x4、「祈祷晶片包」x4、「玛丝黛拉种子」x2。',Feature=1,}",
  [3001868] = "{id=3001868,NameZh='布兰登的歉意',Icon='item_6500',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='宝石商人布兰登的赠礼，沉甸甸的礼盒似乎有不少好东西。打开后可获得「金质勋章」x2、「莫拉硬币」x10、「乐园币」x300、「超大型JOB药水」x50。',Feature=1,}",
