  [3001873] = "{id=3001873,NameZh='神谕晶石',Icon='item_700137',Type=30,MaxNum=99999,SellPrice=100,Desc='珍贵罕见、蕴含有神谕之力的奇特宝石，传说中是神之力的精粹之物。打开后可获得「B格猫福利券·宴」x2、「金质勋章」x1、「尘封的符文袋Ⅰ」x2。',Feature=1,}",
  [3001874] = "{id=3001874,NameZh='天空晶石',Icon='item_700142',Type=30,MaxNum=99999,SellPrice=100,Desc='璀璨夺目蕴含天空之力的奇特宝石，传说中拥有风语之力。打开后可获得「B格猫福利券·Ⅰ」x2、「坠星陨铁」x1、「神谕之晶」x2。',Feature=1,}",
  [3001875] = "{id=3001875,NameZh='星语晶石',Icon='item_700135',Type=30,MaxNum=99999,SellPrice=100,Desc='蕴含星空之力的奇特宝石，据说有神秘的力量。打开后可获得「B格猫福利券·Ⅱ」x2、「光洁的符文石」x1、「神秘箱子SP」x3。',Feature=1,}",
  [3001876] = "{id=3001876,NameZh='不作不死',Icon='',Type=10,SellPrice=100,Desc='一个月总会有那么几天情绪不正常，不作一下怎么才能在枯燥生活中感到一丝愉快？所以珍惜周围带给你欢乐的朋友吧~',}",
  [3001880] = "{id=3001880,NameZh='起源结晶',Icon='item_6209',Type=61,Quality=2,UseMode=30035,MaxNum=99999,SellPrice=100,Desc='起源之力凝聚而成的结晶，打开之后可以兑换各类道具。该道具将在2020.07.01后失效，请各位冒险者抓紧兑换。',ExistTimeType=2,ExistTime='2020-07-01 05:00:00',Feature=1,}",
