  [3001882] = "{id=3001882,NameZh='助力礼盒',Icon='item_3681',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='打开后可获得「来自女武神的馈赠」*2、「祈祷晶片包」*1、「金质勋章」*1。',Feature=1,}",
  [3001883] = "{id=3001883,NameZh='职业兑换券',Icon='item_6553',Type=61,Quality=3,UseMode=30036,MaxNum=99999,SellPrice=100,Desc='由职业管理中心发放，使用后可选择一张人类指定职业的角色兑换券。该道具将在2020.07.01后失效，请各位冒险者抓紧兑换。',ExistTimeType=2,ExistTime='2020-07-01 05:00:00',Feature=1,}",
  [3001884] = "{id=3001884,NameZh='捣蛋礼盒',Icon='item_3658',Type=30,MaxNum=99,SellPrice=100,Desc='送给喜欢调皮捣蛋的你，使用之后可以获得「虚空刻刀」x1、「闪耀的符文石」x1、「光洁的符文石」x2、「黯淡的符文石」x3、「祈祷晶片包」x5',}",
  [3001889] = "{id=3001889,NameZh='小木锤',Icon='item_3001889',Type=30,UseMode=31043,MaxNum=99999,SellPrice=100,Desc='虽然是普通木制小锤，但是却能发挥巨大威力，真是惊人！“喂！这个不可以用来打人！”',ExistTimeType=2,ExistTime='2020-09-05 05:00:00',Feature=1,}",
  [3001890] = "{id=3001890,NameZh='关键情报',Icon='item_53847',Type=30,MaxNum=99,SellPrice=100,Desc='通过仔细阅读后，能基本掌握了高额悬赏的相关信息。打开后可获得「小木锤」x2、「神秘箱子7.0」 x3。',Feature=1,}",
  [3001893] = "{id=3001893,NameZh='残缺情报I',Icon='item_12625',Type=30,MaxNum=99999,SellPrice=100,Desc='未能提供有用的线索，有一种被骗了的感觉？打开后可获得「B格猫福利券·宴」x5、「金质勋章」x2、「尘封的符文袋Ⅰ」x4。',Feature=1,}",
  [3001894] = "{id=3001894,NameZh='残缺情报II',Icon='item_12626',Type=30,MaxNum=99999,SellPrice=100,Desc='能看到一些模糊的线索，或许多收集几个能整理出线索！打开后可获得「B格猫福利券·Ⅰ」x4、「坠星陨铁」x2、「神谕之晶」x4。',Feature=1,}",
  [3001895] = "{id=3001895,NameZh='残缺情报III',Icon='item_12627',Type=30,MaxNum=99999,SellPrice=100,Desc='似乎是有用的线索，但是却不知道如何使用。打开后可获得「B格猫福利券·Ⅱ」x4、「光洁的符文石」x2、「神秘箱子7.0」x3。',Feature=1,}",
  [3001896] = "{id=3001896,NameZh='黄金眼礼包',Icon='item_1000094',Type=30,MaxNum=99,SellPrice=100,Desc='来自普隆德拉首富沃雷特的委托报酬。既然是大富翁，一定会有不错的东西吧。使用后，可获得「小木锤」x1，必得以下材料其中2件：「鱼尾」x5、「柔软的绸缎」x1、「蛇妖之瞳」x1、「燃烧的蛇鳞」x1、「冰晶琉璃」x1、「虚无之骸」x1',Feature=1,}",
  [3001897] = "{id=3001897,NameZh='空白的支票',Icon='item_700011',Type=30,MaxNum=99,SellPrice=100,Desc='写有沃雷特签名的空白支票，可以无限制地报销委托活动中必需的费用。委托结束后，多余的支票就留下来了……有钱真好啊。使用后可获得「小木锤」x1、「B格猫福利券·I」x3。',Feature=1,}",
  [3001898] = "{id=3001898,NameZh='彩蛋',Icon='item_700186',Type=30,MaxNum=99,SellPrice=100,Desc='「伊丽莎」奉上的答谢彩蛋，不知道藏有什么奇怪的东西。使用后可获得「小木锤」x1、「随机宠物捕捉道具」x2。',Feature=1,}",
  [3001899] = "{id=3001899,NameZh='流星宝箱',Icon='item_3977',Type=30,MaxNum=99,SellPrice=100,Desc='奇异波利携带的宝箱，蕴含着不可思议的魔法。使用后可以概率获得限定尾饰「流星」、「小木锤」x1。必定获得以下奖励其中1件：「九界原石」x1、「玛丝黛拉种子」x1、「料理兑换券」x1、「坠星陨铁」x1、「光洁的符文石」x1。',GetLimit={limit={[999]={5,0}},source={22},type=1},Feature=1,}",
  [3001900] = "{id=3001900,NameZh='盛典·旋转甜梦',Icon='item_3001900',Type=850,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9699,AdventureValue=1,StorageReward={buffid={82000250}},Condition=8,Desc='用蜂蜜和糖霜制成的奇妙糖果，拥有让品尝者变开心的魔力！“真是太不可思议了，我眼前出现了一个巧克力天国！”',TFValidDate='2020-06-01 05:00:00',ValidDate='2020-06-01 05:00:00',}",
  [3001901] = "{id=3001901,NameZh='盛典·糖色太妃[1]',Icon='item_3001901',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9700,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='原本是糖果艺术家们用奶油太妃混合糖果巧克力制成的糖色发饰，盛典之后，掀起了一股流行热潮。',TFValidDate='2020-06-01 05:00:00',ValidDate='2020-06-01 05:00:00',}",
  [3001902] = "{id=3001902,NameZh='盛典·糖果乐园',Icon='item_3001902',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9701,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='“华夫饼、蛋卷、巧克力……我全都要！”模仿糖果乐园里，孩子们最喜欢的华夫巧克力伞制成的特殊背饰，因为太过逼真总是会让人忍不住想咬一口！',TFValidDate='2020-06-01 05:00:00',ValidDate='2020-06-01 05:00:00',LoadShowPose={-0.2,-0.7,0},}",
  [3001903] = "{id=3001903,NameZh='礼赞·缤纷弥漫',Icon='item_3001903',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9702,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='“你也要一口把我吃掉吗？”',TFValidDate='2020-06-01 05:00:00',ValidDate='2020-06-01 05:00:00',LoadShowSize=3.5,LoadShowPose={0,0.9,0},}",
  [3001904] = "{id=3001904,NameZh='礼赞·棕角马的守望[1]',Icon='item_3001904',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9703,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='黑巧克力糖色和白巧克力糖色混搭的角马头饰，童话里，美丽的角马会带着孩子们走向梦幻之乡。',TFValidDate='2020-06-01 05:00:00',ValidDate='2020-06-01 05:00:00',LoadShowPose={0,0.1,0},}",
  [3001905] = "{id=3001905,NameZh='礼赞·甜晕了',Icon='item_3001905',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9704,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='“啊，一不小心把甜巧克力糊在脸上了！”模仿着巧克力酱糊脸的样式制成的眼罩脸饰，看起来和真的一样。',TFValidDate='2020-06-01 05:00:00',ValidDate='2020-06-01 05:00:00',LoadShowSize=3,LoadShowPose={0,0.1,0},}",
  [3001906] = "{id=3001906,NameZh='礼赞·仪仗熊赞礼',Icon='item_3001906',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9058,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='棕巧克力糖色的礼赞熊，童年时，大街上的糖果车上常常会印着它的造型，甜点师们希望用礼赞熊来唤醒大家属于童年的甜味回忆。',TFValidDate='2020-06-01 05:00:00',ValidDate='2020-06-01 05:00:00',LoadShowSize=1.2,LoadShowRotate=180,LoadShowPose={-0.15,0.3,0},}",
  [3001915] = "{id=3001915,NameZh='起源之力礼盒',Icon='item_3001201',Type=30,Quality=3,MaxNum=99,SellPrice=100,Desc='恭喜你领悟了起源之力，接下来的冒险中，你会面对更强大的挑战，这份礼物希望可以冒险道路上助你一臂之力，打开可以获得「远古魔力卡册」x1、「龙之宝箱」x5、「枫色玛瑙」x5、「时光流沙」x2000',}",
  [3001920] = "{id=3001920,NameZh='豪富金牛',Icon='item_3001920',Type=810,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10261,AdventureValue=1,AdventureReward={buffid={61000980}},StorageReward={buffid={80012810}},Condition=8,Desc='手握金喇叭的金牛不仅忠诚可靠，而且非常擅长打理财富，虽然有时候会显得有些抠门。如果它被一个豪爽大气的主人所持有，那就会中和成最稳重的有钱人啦。',Feature=1,TFValidDate='2023-03-25 05:00:00',ValidDate='2023-04-01 05:00:00',StageDisplay=0,LoadShowRotate=180,LoadShowPose={0,0.5,-0.5},}",
  [3001921] = "{id=3001921,NameZh='宠爱双子',Icon='item_3001921',Type=840,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10262,AdventureValue=1,AdventureReward={buffid={61000980}},StorageReward={buffid={80012810}},Condition=8,Desc='当精灵淘气遇上软萌可爱，就是最招人喜欢的组合！双子猫咪以自身最大的萌力，赋予持有者极高的魅力，请千万仔细保管不要丢失它们，然后享受它们所带来的好运吧！',Feature=1,TFValidDate='2023-04-24 05:00:00',ValidDate='2023-05-01 05:00:00',StageDisplay=0,LoadShowPose={0,0,0},}",
  [3001922] = "{id=3001922,NameZh='慕情巨蟹',Icon='item_3001922',Type=810,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10263,AdventureValue=1,AdventureReward={buffid={61000980}},StorageReward={buffid={80012810}},Condition=8,Desc='最最温柔的少女心隐藏在坚硬的蟹壳里，却悄悄地用恋慕织成一片网，无声息地套住对方的心。如果想要让自己的思念得到回应，就记得让巨蟹小姐姐助你一臂之力吧。',Feature=1,StageDisplay=0,}",
