  [3002000] = "{id=3002000,NameZh='Q的八音盒',Icon='item_3002000',Type=30,MaxNum=99999,SellPrice=100,Desc='神秘小女孩「Q」的八音盒，似乎里面还藏了一些奇奇怪怪的东西。打开后可获得以下道具中的一种：「神谕之晶」x2、「神谕之尘」x4、「光洁的符文石」x1、「来自女武神的馈赠」x2、「祈祷晶片包」x2、「玛丝黛拉种子」x1。',Feature=1,}",
  [3002001] = "{id=3002001,NameZh='Q的玩具箱',Icon='item_500577',Type=30,MaxNum=99999,SellPrice=100,Desc='神秘小女孩「Q」的玩具箱，沉甸甸的似乎装满了宝贝。打开后必定获得以下所有道具：「神谕之晶」x6、「神谕之尘」x8、「光洁的符文石」x2、「来自女武神的馈赠」x4、「祈祷晶片包」x4、「玛丝黛拉种子」x1。',Feature=1,}",
  [3002002] = "{id=3002002,NameZh='天蓝晶石',Icon='item_12577',Type=30,MaxNum=99999,SellPrice=100,Desc='由天蓝宝石凝结而成的晶石。打开后可获得「B格猫福利券·Ⅰ」x2、「坠星陨铁」x1、「神谕之晶」x2。',Feature=1,}",
  [3002003] = "{id=3002003,NameZh='明黄晶石',Icon='item_12573',Type=30,MaxNum=99999,SellPrice=100,Desc='由黄宝石凝结而成的晶石。打开后可获得「B格猫福利券·宴」x2、「金质勋章」x1、「尘封的符文袋·Ⅰ」x2。',Feature=1,}",
  [3002004] = "{id=3002004,NameZh='淡紫晶石',Icon='item_12576',Type=30,MaxNum=99999,SellPrice=100,Desc='由紫宝石凝结而成的晶石。打开后可获得「B格猫福利券·Ⅱ」x2、「光洁的符文石」x1、「神秘箱子7.0」x3。',Feature=1,}",
  [3002005] = "{id=3002005,NameZh='Queen的行李',Icon='item_3000248',Type=30,MaxNum=99999,SellPrice=100,Desc='Queen从遥远的时空中带过来的行李箱，打开后可获得以下道具中的一种：「神谕之晶」x6、「神谕之尘」x8、「光洁的符文石」x2、「来自女武神的馈赠」x4、「祈祷晶片包」x4、「玛丝黛拉种子」x2。还有10%的概率获赠限定头饰「粽叶蝴蝶结」x1。',GetLimit={limit={[999]={1,0}},source={22},type=1},Feature=1,}",
  [3002006] = "{id=3002006,NameZh='爱做梦的木马图纸',Icon='item_3002006',Type=50,Quality=2,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=3002006,Desc='陪伴在女王身边的木马，大多数时间都在睡觉，梦里似乎有什么开心的事情发生。',Feature=1,TFValidDate='2020-05-25 05:00:00',ValidDate='2020-06-01 05:00:00',}",
