  [3002009] = "{id=3002009,NameZh='旅行特惠福袋',Icon='item_6508',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='B格猫星人推出的特惠礼包，使用之后必定获得「7.0Boss材料」x5、「7.0稀有材料」x10、Zeny x 20万。',}",
