  [3002039] = "{id=3002039,NameZh='熊本熊的心意',Icon='item_170',Type=61,UseMode=30042,MaxNum=99999,SellPrice=100,Desc='熊本熊赠送给各位冒险者的礼物，使用之后可以打开熊本熊的商店，兑换各类限定稀有道具。一旦熊本熊离开了，该道具就会被回收哦~所以请各位冒险者注意使用期限！',ExistTimeType=2,ExistTime='2020-07-01 05:00:00',Feature=1,TFValidDate='2020-05-25 05:00:00',ValidDate='2020-06-01 05:00:00',Delete=3002039}",
  [3002040] = "{id=3002040,NameZh='永夜的馈赠',Icon='item_3682',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='有白天的地方就有黑夜，生命不过是光暗交替中的一场轮回。打开后可必定获得「祈祷晶片包」*2、「心愿蛋糕」*1、zeny*150000、另有0.25%几率获得羽翼「永夜流光」。',Delete=3002040}",
  [3002041] = "{id=3002041,NameZh='熊本熊的感恩礼',Icon='item_3000710',Type=30,MaxNum=99999,SellPrice=100,Desc='熊本熊送给各位冒险者的礼物，打开之后必定获得「熊本熊的心意」x50、「熊本熊扭蛋币」x5、「料理兑换券」x1，还能随机获得以下道具中的一种：「莫拉硬币」x5、「神谕之尘」x4、「神谕之晶」x2、「玛丝黛拉种子」x1',Feature=1,TFValidDate='2020-05-25 05:00:00',ValidDate='2020-06-01 05:00:00',Delete=3002041}",
  [3002042] = "{id=3002042,NameZh='熊本熊扭蛋币',Icon='item_3000704',Type=41,MaxNum=99999,SellPrice=100,Desc='为了欢迎熊本熊的到来特意发行的扭蛋币，冒险者可以使用它去参与熊本熊异次元扭蛋机~但是在熊本熊离开了之后，这个扭蛋币也就没什么用啦，所以各位冒险者请注意使用期限哦~',ExistTimeType=2,ExistTime='2020-06-15 05:00:00',Feature=1,TFValidDate='2020-05-25 05:00:00',ValidDate='2020-06-01 05:00:00',Delete=3002042}",
  [3002043] = "{id=3002043,NameZh='熊本熊感恩徽章',Icon='item_3001200',Type=61,UseMode=30043,MaxNum=99999,SellPrice=100,Desc='熊本熊有些纠结，不知道冒险者会更喜欢「熊本熊召唤器」呢，还是更喜欢「初心熊本熊」，所以，索性就让冒险者自己去兑换吧~',Feature=1,TFValidDate='2020-05-25 05:00:00',ValidDate='2020-06-01 05:00:00',Delete=3002043}",
