  [3002071] = "{id=3002071,NameZh='暗魔将头盔',Icon='item_3002071',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10251,AdventureValue=1,StorageReward={buffid={80012600}},Condition=8,Desc='暗魔将的头盔，曾陪伴着受阿罗格役使的暗魔将恶奴弥守四处征战—漆黑的头盔，曾是给人们带来绝望的黑暗之物，但也能指引人们走向极乐。（多余的四魔将头盔可以在活动期间前往联动幻想创造器·宴中兑换成「辉煌精华」）',Feature=1,TFValidDate='2020-06-25 05:00:00',ValidDate='2020-07-02 05:00:00',Delete=3002071}",
