  [3002104] = "{id=3002104,NameZh='冠军的证明',Icon='item_3002104',Type=61,UseMode=30040,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='只要努力参与，即便没有获得伟大的成就，你也可以是冠军！',GetLimit={limit={[999]={800,0}},source={22},type=1},ExistTimeType=2,ExistTime='2020-09-01 05:00:00',}",
