  [3002106] = "{id=3002106,NameZh='夏日运动邀请匣',Icon='item_3002106',Type=30,MaxNum=99999,SellPrice=100,Desc='明媚的阳光与新鲜的空气在呼唤着你，快来参加夏日运动吧~打开后可获得「冠军的证明」 x200，有概率获得「来自女武神的馈赠」 x4，「金质勋章」 x4，「祈祷晶片包」x4，「光洁的符文石」 x2，「闪耀的符文石」 x1，「玛丝黛拉种子」 x1中的一种。',}",
  [3002107] = "{id=3002107,NameZh='夏日能量补给箱',Icon='item_3002107',Type=30,MaxNum=99999,SellPrice=100,}",
  [3002108] = "{id=3002108,NameZh='夏日三千问',Icon='item_3002108',Type=30,MaxNum=99999,SellPrice=100,Desc='每个小朋友的脑袋里都装满了大大的问号，答对问题便可获得礼物盒。打开后可获得「B格猫福利券·宴」x2、「金质勋章」x1、「尘封的符文袋·Ⅰ」x2。',}",
  [3002109] = "{id=3002109,NameZh='破损零件包',Icon='item_3002109',Type=30,MaxNum=99999,SellPrice=100,Desc='被魔物破坏的零件包，本应该装满制造降雪机的重要部件，但是现在只有「神谕之尘」 x6，「神谕之晶」 x4，「古拉姆晶末」 x15，「咔吱咔吱刨冰机零件」 x1，偶尔会出现「零件」 x1，「破损零件」x1。',}",
  [3002110] = "{id=3002110,NameZh='竞技的荣耀·日',Icon='item_3002110',Type=30,MaxNum=99999,SellPrice=100,Desc='汗水与艰辛为证，这是竞技者所应得的荣耀。听，那是太阳的颂赞。打开后可获得「冠军的证明」 x300，Zeny x30000，有10%概率获得「荣誉奖杯试作型」 x1。',ExistTimeType=2,ExistTime='2020-09-01 05:00:00',}",
  [3002111] = "{id=3002111,NameZh='竞技的荣耀·月',Icon='item_3002111',Type=30,MaxNum=99999,SellPrice=100,Desc='汗水与艰辛为证，这是竞技者所应得的荣耀。听，那是月亮的抚慰。打开后可获得「冠军的证明」 x200，Zeny x20000，有5%概率获得「荣誉奖杯试作型」 x1。',ExistTimeType=2,ExistTime='2020-09-01 05:00:00',}",
  [3002112] = "{id=3002112,NameZh='竞技的荣耀·星',Icon='item_3002112',Type=30,MaxNum=99999,SellPrice=100,Desc='汗水与艰辛为证，这是竞技者所应得的荣耀。听，那是星星的歌唱。打开后可获得「冠军的证明」 x100，Zeny x10000，有1%概率获得「荣誉奖杯试作型」 x1。',ExistTimeType=2,ExistTime='2020-09-01 05:00:00',}",
