  [3002114] = "{id=3002114,NameZh='灼热之日宝石',Icon='item_3002114',Type=30,MaxNum=99999,SellPrice=100,Desc='装满烈日精华的礼盒，「B格猫福利券·宴」x2，「金质勋章」x1，「尘封的符文袋·Ⅰ」x2。',}",
