  [3002125] = "{id=3002125,NameZh='幻想原石',Icon='item_700105',Type=61,UseMode=30048,MaxNum=99999,SellPrice=100,Desc='据说是组成幻想创造器的原件，使用之后可以兑换「B格猫福利券·宴」x10或「魔神坛斗士扭蛋币」x10，2020-07-30 5：00后将仅可兑换「B格猫福利券·宴」x10',Feature=1,Delete=3002125}",
  [3002126] = "{id=3002126,NameZh='妖邪帝王秘卷',Icon='task_53630',Type=30,MaxNum=99999,SellPrice=100,Desc='据说是妖邪帝王留下的秘卷，使用之后可以必定获得Zeny x 15W、「幻想原石」x1（可自选「B格猫福利券·宴」x10或「魔神坛斗士扭蛋币」x10），10%概率获赠四魔将头饰中的1种：「幻魔将头盔」x1、「暗魔将头盔」x1、「毒魔将头盔」x1、「鬼魔将头盔」x1。集齐不同的4个魔将头盔，可以触发特殊任务「妖邪帝王之盔」，完成任务后，可以获得「妖邪帝王头盔」x1，同时解锁限定成就「妖邪帝王」，奖励限定时装「幻·妖邪帝王」x1、限定背饰「阿罗格之威」x1。特殊任务将在2020-08-15 5：00失效。',Feature=1,Delete=3002126}",
