  [3002131] = "{id=3002131,NameZh='刚烈剑',Icon='item_3002099',Type=180,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='传说中的神剑，较之于烈火剑有着更强的威力，是能够与辉煌帝铠甲相匹配的强大武器。',TFValidDate='2020-06-25 05:00:00',ValidDate='2020-07-02 05:00:00',LoadShowSize=1.1,LoadShowRotate=70,LoadShowPose={0,0,0},Delete=3002131}",
  [3002132] = "{id=3002132,NameZh='烈火剑',Icon='item_3002132',Type=180,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='烈火剑—火焰神真田辽的武器现世！曾陪伴着火焰神经历了无数艰辛的战斗，必杀“双~炎~斩！”',Feature=1,TFValidDate='2020-06-25 05:00:00',ValidDate='2020-07-02 05:00:00',LoadShowSize=1.5,LoadShowRotate=70,LoadShowPose={0,0,0},Delete=3002132}",
