  [3002146] = "{id=3002146,NameZh='午餐肉罐头',Icon='item_3002146',Type=103,MaxNum=99999,SellPrice=100,Desc='优质的午餐肉罐头，是宠物白炎最喜欢吃的东西。',Feature=1,Delete=3002146}",
  [3002147] = "{id=3002147,NameZh='魔神坛斗士扭蛋币',Icon='item_3002147',Type=41,MaxNum=99999,SellPrice=100,Desc='为了欢迎魔神坛斗士的到来特意发行的扭蛋币，冒险者可以使用它去参与魔神坛斗士异次元扭蛋机~但是在魔神坛斗士离开了之后，这个扭蛋币也就没什么用啦，所以各位冒险者请注意使用期限哦~',ExistTimeType=2,ExistTime='2020-07-30 05:00:00',Feature=1,Delete=3002147}",
  [3002148] = "{id=3002148,NameZh='异乡武士的谢礼',Icon='item_3896',Type=30,MaxNum=99999,SellPrice=100,Desc='异乡武士的谢礼，使用之后必定获得「生命宝石碎片」x20、「魔神坛斗士扭蛋币」x5、「料理兑换券」x1，随机获得以下奖励的一种：「祈祷晶片包」x3、「来自女武神的馈赠」x2、「莫拉硬币」x5、「神谕之尘」x5、「神谕之晶」x5、「金质勋章」x2，还有10%概率获赠限定背饰「迦雄须之杖」，该背饰可以幻化法杖武器外观。',Feature=1,Delete=3002148}",
  [3002149] = "{id=3002149,NameZh='迦雄须的谢礼',Icon='item_3000172',Type=30,MaxNum=99999,SellPrice=100,Desc='迦雄须为了感谢冒险者的付出准备的礼物，专为想要多个角色体验火焰神的冒险者而准备。使用之后必定获得「魔神坛斗士扭蛋币」x300、火焰神转职道具「迦雄须来信」x1',Feature=1,Delete=3002149}",
  [3002150] = "{id=3002150,NameZh='瓶中之星[1]',Icon='item_3002150',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9711,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='在混有水银的玻璃瓶中培育出的大块六芒星状水晶，便是极为珍罕的瓶中之星，可给主人带来富贵。至于为什么玻璃瓶外会贴着猫脸贴纸——这种小事就不要在意啦。',TFValidDate='2020-08-01 05:00:00',ValidDate='2020-08-01 05:00:00',LoadShowPose={0,0,0},}",
  [3002151] = "{id=3002151,NameZh='扉之守护者',Icon='item_3002151',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9712,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='被异域的富豪之王所委任宝藏的神奇生物。异色双瞳可看穿一切谎言，小脑袋瓜里计算着所有的收益。倘若被如此小巧可爱的外表蒙蔽而试图掠夺财富，它就会让你知晓它的可怕。',TFValidDate='2020-08-01 05:00:00',ValidDate='2020-08-01 05:00:00',LoadShowSize=1.5,LoadShowPose={0,-0.4,0},}",
  [3002152] = "{id=3002152,NameZh='千里瞳[1]',Icon='item_3002152',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9713,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='左金右银的一双瞳孔，搜寻起赚钱的机会毫不含糊。哪怕没有这个能力，仅仅只是戴上也很可爱嘛！',TFValidDate='2020-08-01 05:00:00',ValidDate='2020-08-01 05:00:00',LoadShowSize=1,LoadShowPose={-0.15,0.55,0.5},}",
  [3002153] = "{id=3002153,NameZh='魔幻储宝箱',Icon='item_3002153',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9714,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='具有不可思议力量的造物，可保护持有者的财产。据说根据财产的增多，会有宝箱之灵幻化为各种形态来保护金钱。如果想知道宝箱之灵是什么……那就多多储钱吧。',TFValidDate='2020-08-01 05:00:00',ValidDate='2020-08-01 05:00:00',LoadShowSize=1.5,LoadShowRotate=180,LoadShowPose={-0.2,0.5,0},}",
  [3002154] = "{id=3002154,NameZh='瑰色女王',Icon='item_3002154',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9715,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='华美的玫瑰色宝石是王向深爱之人赠送的定情礼物。或许有一天，它会在不断翻转流逝的时光之中，见证主人真挚纯净的爱。',TFValidDate='2020-08-01 05:00:00',ValidDate='2020-08-01 05:00:00',LoadShowSize=4,LoadShowRotate=-40,LoadShowPose={0,0.5,0},}",
  [3002155] = "{id=3002155,NameZh='金色照耀',Icon='item_3002155',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9716,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='黄金打造出的面具，贴合面部曲线，极其舒适。锐利的眼神掩盖了真实的心情，那么，一二三，猜猜面具下是谁呢？',TFValidDate='2020-08-01 05:00:00',ValidDate='2020-08-01 05:00:00',LoadShowRotate=-10,LoadShowPose={0,0.2,0},}",
  [3002156] = "{id=3002156,NameZh='轻唇喵喵',Icon='item_3002156',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9060,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='以“可以叼着后颈”为最大卖点的系列新作！让一只软软乎乎的团子喵温顺地伏在嘴角，增加主人温柔可爱的气质。请注意不要因为太过可爱而不小心吞下去了哟。',TFValidDate='2020-08-01 05:00:00',ValidDate='2020-08-01 05:00:00',LoadShowSize=4,LoadShowRotate=-10,LoadShowPose={0,0.8,0},}",
  [3002160] = "{id=3002160,NameZh='海上公爵·靛',Icon='item_3002160',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000020}},Desc='加入曙光舰队的少年，和海上的水手日夜相伴，渐渐地也看不出来羸弱的贵族样。现在的他，拥有潇洒的气概，被尊称为海上公爵。',TFValidDate='2020-08-10 05:00:00',ValidDate='2020-08-13 05:00:00',MainColor='f6ede6FF',}",
  [3002161] = "{id=3002161,NameZh='海上公爵·阎',Icon='item_3002160',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000020}},Desc='加入曙光舰队的少年，和海上的水手日夜相伴，渐渐地也看不出来羸弱的贵族样。现在的他，拥有王者的气概，被尊称为海上公爵。',TFValidDate='2020-08-10 05:00:00',ValidDate='2020-08-13 05:00:00',MainColor='221c19FF',}",
  [3002162] = "{id=3002162,NameZh='海上公爵·朱',Icon='item_3002160',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000020}},Desc='加入曙光舰队的少年，和海上的水手日夜相伴，渐渐地也看不出来羸弱的贵族样。现在的他，拥有霸道的气概，被尊称为海上公爵。',TFValidDate='2020-08-10 05:00:00',ValidDate='2020-08-13 05:00:00',MainColor='d13935FF',}",
