  [3002271] = "{id=3002271,NameZh='荆棘',Icon='item_3002271',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15368,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='一圈小小的刺枝倔强守护着柔弱的美好，正如明朗的女孩子也有足够的勇气来保护自己。',TFValidDate='2020-09-14 05:00:00',ValidDate='2020-09-17 05:00:00',LoadShowPose={0,0.7,0},}",
