  [3002273] = "{id=3002273,NameZh='五弦',Icon='item_3002273',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15370,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='五根金属丝制成的乐器，正是洛阳吟游诗人的最爱。如果有幸前往花街一睹花魁，也能听到不同凡响的五弦曲哦！',TFValidDate='2020-09-14 05:00:00',ValidDate='2020-09-17 05:00:00',LoadShowSize=1.5,LoadShowRotate=180,LoadShowPose={0,0.6,-0.1},}",
  [3002274] = "{id=3002274,NameZh='大头虎',Icon='item_3002274',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15371,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='洛阳流传的十二生肖之一，可驱邪避祸的百兽之王。没有想到居然这么可爱！',TFValidDate='2020-09-14 05:00:00',ValidDate='2020-09-17 05:00:00',LoadShowPose={0,-0.1,0},}",
  [3002275] = "{id=3002275,NameZh='昙花水镜',Icon='item_3002275',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15372,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='掬一捧银鱼湖最清澈的湖水，辅以昙花凝聚而成的水镜，仿佛充满着神秘的力量。',TFValidDate='2020-09-14 05:00:00',ValidDate='2020-09-17 05:00:00',LoadShowSize=3,LoadShowPose={-0.2,0.5,0},}",
  [3002276] = "{id=3002276,NameZh='流月扇子',Icon='item_3002276',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15373,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='用来祈愿的礼扇。据说月夜时用此扇照出月影，就能获得更多的智慧。',TFValidDate='2020-09-14 05:00:00',ValidDate='2020-09-17 05:00:00',LoadShowSize=1.5,LoadShowPose={0.5,-0.8,-0.3},}",
  [3002277] = "{id=3002277,NameZh='花之羽翼',Icon='item_3002277',Type=810,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=15374,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='青白二色寓意清澈明净。用洛阳特有的昙花花瓣拼出羽翼状，等待永恒的幸福降临。',TFValidDate='2020-09-14 05:00:00',ValidDate='2020-09-17 05:00:00',LoadShowSize=1.6,LoadShowRotate=-10,LoadShowPose={0,0.2,-0.2},}",
  [3002280] = "{id=3002280,NameZh='苍星飞羽',Icon='item_3002280',Type=810,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9717,AdventureValue=1,StorageReward={buffid={82000250}},Condition=8,Desc='曾经，一颗苍星不知疲倦地旅行，直到力竭坠落在米德加尔特大陆。如今它被制成双翼，又能和冒险者一起遨游天地。',TFValidDate='2020-09-01 05:00:00',ValidDate='2020-09-01 05:00:00',LoadShowSize=1.5,LoadShowRotate=170,LoadShowPose={0.1,0.1,-0.8},}",
  [3002281] = "{id=3002281,NameZh='星芒单片镜',Icon='item_3002281',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9718,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='由星辰碎片打造的单片镜，模样古怪却蕴藏着星空精灵的魔法。“持有星芒的冒险者呀，你看见星星预示的未来了吗？”',TFValidDate='2020-09-01 05:00:00',ValidDate='2020-09-01 05:00:00',LoadShowSize=3,LoadShowRotate=330,LoadShowPose={-0.3,0.3,0},}",
  [3002282] = "{id=3002282,NameZh='绒绒',Icon='item_3002282',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9719,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='不知名的奇幻生物，因为毛绒绒的，所以被暂时命名为“绒绒”。某天突然出现在冒险者身后，似乎非常喜欢他们……身上的星之石。',TFValidDate='2020-09-01 05:00:00',ValidDate='2020-09-01 05:00:00',LoadShowPose={0,-0.1,0},}",
  [3002283] = "{id=3002283,NameZh='繁星之爱',Icon='item_3002283',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9720,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='有些心意就像天上的星光，沉默无言却依旧可以照到你的心底。',TFValidDate='2020-09-01 05:00:00',ValidDate='2020-09-01 05:00:00',LoadShowSize=5,LoadShowRotate=350,LoadShowPose={0,1,0},}",
  [3002284] = "{id=3002284,NameZh='星屑的回忆[1]',Icon='item_3002284',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9721,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='群星俯瞰人间，人们向星星祈愿。有些回忆即便破碎，仍然历久弥新。“嘘……倾听，那跨越时间的思念。”',TFValidDate='2020-09-01 05:00:00',ValidDate='2020-09-01 05:00:00',}",
  [3002285] = "{id=3002285,NameZh='星之石假面',Icon='item_3002285',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9722,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='星空精灵用星之石制作的假面，美丽又神秘。“冒险者，记得来参加我们的舞会哟。”',TFValidDate='2020-09-01 05:00:00',ValidDate='2020-09-01 05:00:00',LoadShowSize=4,LoadShowRotate=350,LoadShowPose={0,0.4,-0.2},}",
  [3002286] = "{id=3002286,NameZh='星河宝冠',Icon='item_3002286',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9061,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='星星坠落人间，化为璀璨的宝石。用它打造的头冠，无论白天黑夜都能散发出星辰的光辉。',TFValidDate='2020-09-01 05:00:00',ValidDate='2020-09-01 05:00:00',LoadShowPose={0,0.6,-0.2},}",
  [3002287] = "{id=3002287,NameZh='天蓝结晶',Icon='item_700142',Type=30,MaxNum=99999,SellPrice=100,Desc='天蓝宝石集合而成的晶石，打开可以获得「B格猫福利券·宴」x5、「金质勋章」x2、「尘封的符文袋·Ⅰ」x4、「小木锤」x1',Feature=1,}",
  [3002288] = "{id=3002288,NameZh='暗黄结晶',Icon='item_700137',Type=30,MaxNum=99999,SellPrice=100,Desc='黄宝石集合而成的晶石，打开可以获得「B格猫福利券·Ⅰ」x4、「坠星陨铁」x2、「神谕之晶」x4',Feature=1,}",
  [3002289] = "{id=3002289,NameZh='亮紫结晶',Icon='item_700135',Type=30,MaxNum=99999,SellPrice=100,Desc='紫宝石集合而成的晶石，打开可以获得「B格猫福利券·Ⅱ」x4、「光洁的符文石」x2、「神秘箱子7.0」x3',Feature=1,}",
  [3002290] = "{id=3002290,NameZh='愤怒的魔锅蛋图纸',Icon='item_3033290',Type=50,Quality=2,MaxNum=99999,SellPrice=100,ComposeID=3002290,Desc='充满怒气的魔锅蛋，令它愤怒的点，主要是，它也不知道为什么，自己就莫名其妙地成为了黄金蛋炒饭的材料，以至于差点灭绝。',Feature=1,}",
  [3002291] = "{id=3002291,NameZh='旋风锅铲',Icon='item_3002291',Type=810,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10275,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='黄金美食节指定厨具，据说只有使用这把锅铲，才能做出传说中的蛋炒饭哦~',Feature=1,TFValidDate='2020-09-24 05:00:00',ValidDate='2020-10-01 05:00:00',LoadShowRotate=180,LoadShowPose={0,0.4,-0.6},}",
  [3002292] = "{id=3002292,NameZh='魔法泡泡糖',Icon='item_3002292',Type=850,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10276,AdventureValue=1,StorageReward={buffid={80012930}},Condition=8,Desc='被大魔法师开过光的泡泡糖，与普通的泡泡糖相比，它永远不会被吹爆哦！',Feature=1,TFValidDate='2020-09-24 05:00:00',ValidDate='2020-10-01 05:00:00',LoadShowPose={-0.3,0.5,0.5},}",
  [3002293] = "{id=3002293,NameZh='从月亮到地球的感恩',Icon='item_3000170',Type=30,MaxNum=99999,SellPrice=100,Desc='被你拯救的小兔几送你的礼物~因为装了太多的礼物，小兔几可是吭哧吭哧地把这个礼物挪到你的面前的！打开之后可以获得「神谕之尘」x5、「神谕之晶」x5、「莫拉硬币」x5、「闪耀的符文石·星」x1、「小木锤」x3',Feature=1,}",
  [3002294] = "{id=3002294,NameZh='厨神日记',Icon='item_63406',Type=30,MaxNum=99999,SellPrice=100,Desc='看起来粉嫩嫩、充满少女心，却不想竟然是厨神的日记！打开之后可以获得「神秘箱子7.0」x2、「小木锤」x2',Feature=1,}",
  [3002295] = "{id=3002295,NameZh='兔宝贝的珍藏',Icon='item_3944',Type=30,MaxNum=99999,SellPrice=100,Desc='普隆德拉南门兔子家族的传家之宝，虽然知道这样贸然打开不是很礼貌，但是手就是不听使唤呀！打开之后必定获得「料理兑换券」x1、「小木锤」x1，还有10%的概率额外获赠以下道具中的一种：「夜光魔法」x1、「银河梦游」x1、「摇曳月光」x1、「满月头饰图纸」x1、「万象月盘图纸」x1、「月光小怪兽」x1、「广寒仙子」x1',GetLimit={limit={[999]={1,0}},source={22},type=4},Feature=1,}",
  [3002296] = "{id=3002296,NameZh='猴大王的珍藏',Icon='item_3000522',Type=30,MaxNum=99999,SellPrice=100,Desc='普隆德拉西门一霸——猴大王的珍藏，打开之后必定获得「B格猫福利券·宴」x5、「小木锤」x1、「萃光结晶」x1，还有10%概率额外获赠活动限定嘴饰「魔法泡泡糖」x1',GetLimit={limit={[999]={1,0}},source={22},type=4},Feature=1,}",
  [3002297] = "{id=3002297,NameZh='阴森森的宝箱',Icon='item_3001766',Type=30,MaxNum=99999,SellPrice=100,Desc='散发着阴森森诡异气息的宝箱，但是里面的东西却一点都不诡异。打开之后必定获得「万圣节秘制海鲜汤」x1，以下道具随机获得一种：「祈祷晶片包」x4、「莫拉硬币」x5、「神谕之尘」x5、「神谕之晶」x5、「好运币」x3、「萃光结晶」x2',Feature=1,}",
  [3002298] = "{id=3002298,NameZh='我才是大王！',Icon='item_3002298',Type=10,SellPrice=100,Desc='管它什么兔大王猴大王，我才是大王！',}",
  [3002299] = "{id=3002299,NameZh='小木锤',Icon='item_3001889',Type=30,UseMode=31043,MaxNum=99999,SellPrice=100,Desc='虽然是普通木制小锤，但是却能发挥巨大威力，真是惊人！“喂！这个不可以用来打人！”',ExistTimeType=2,ExistTime='2020-11-01 05:00:00',Feature=1,}",
  [3002300] = "{id=3002300,NameZh='虹光碎片',Icon='item_3002300',Type=61,UseMode=31114,MaxNum=99999,AuctionPrice=1,SellPrice=10,Desc='彩虹桥被击碎时散落的能量碎片，仔细观察可以发现，这碎片的边缘好像在随着时间的流逝而慢慢消失……',GetLimit={limit={[999]={400,0}},source={22},type=4},ExistTimeType=2,ExistTime='2021-1-01 05:00:00',Delete=3002300}",
  [3002301] = "{id=3002301,NameZh='虹光宝匣',Icon='item_3002301',Type=30,MaxNum=99999,SellPrice=100,Desc='用彩虹桥碎片打造的宝箱，用于奖励那些在【虹色坠落】事件中作出贡献的人们。打开后可获得以下道具中的一种：「来自女武神的馈赠」x2，「金质勋章」x2，「祈祷晶片包」x2，「光洁的符文石」x1，「尘封的符文袋」x1，「玛斯黛拉种子」x1。',Delete=3002301}",
  [3002302] = "{id=3002302,NameZh='瓦尔基里的恩赐·正义',Icon='item_3002302',Type=30,MaxNum=99999,SellPrice=100,Desc='击败被控制的英灵获得的战利品，似乎有着特殊的意志。打开后可获得「随机MVP材料」x2，有概率获得「天水古钱」x1，「魔法残片·梅丽尔」x1',Delete=3002302}",
  [3002303] = "{id=3002303,NameZh='小花仙图纸',Icon='item_3033303',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=3002303,Desc='穿梭在花丛间，寻找能够为人们带来幸运的四叶草——小花仙就是我啦！',TFValidDate='2020-10-07 05:00:00',ValidDate='2020-10-14 05:00:00',}",
  [3002304] = "{id=3002304,NameZh='聚焦虹冠图纸',Icon='item_3033304',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=3002304,Desc='使用彩虹桥碎片打造的头冠，能够在前方映射出一道小小的彩虹。',TFValidDate='2020-10-07 05:00:00',ValidDate='2020-10-14 05:00:00',}",
  [3002305] = "{id=3002305,NameZh='不祥的魔法书',Icon='item_3002305',Type=41,MaxNum=99999,SellPrice=100,Desc='散发着不祥气息的魔法书，上面记载着意义不明的咒语——要不把咒语念出来试试？使用后可获得Zeny x 100000，「随机MVP材料」x2。',}",
  [3002306] = "{id=3002306,NameZh='虹光守望者',Icon='item_3002306',Type=10,MaxNum=1,Desc='在崩碎的虹光中，坚定守卫米德加尔特的无畏战士。',}",
  [3002307] = "{id=3002307,NameZh='黯月浮光图纸',Icon='item_3033307',Type=50,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=3002307,Desc='岸上的人永远不知道溺水者的感受，身处光明的人也无法理解为何有人在黑暗中沉沦——我已沉入深渊，无法回头。',TFValidDate='2020-11-11 05:00:00',ValidDate='2020-11-18 05:00:00',}",
  [3002308] = "{id=3002308,NameZh='异界战利品',Icon='item_3002308',Type=30,MaxNum=1,SellPrice=100,Desc='阿卡娜裂隙中魔物掉落的物品，权当战利品送给你吧！打开后可获得「随机MVP材料」x2，「闪耀的符文石」x1，有概率获得「天水古钱」x1，「黯月浮光图纸」x1。',NoStorage=5,ExistTimeType=1,ExistTime='86400',}",
  [3002309] = "{id=3002309,NameZh='影胧密卷·残章',Icon='item_3002309',Type=41,MaxNum=99999,SellPrice=100,Desc='印着奇怪文字与图形的书页，似乎记载着某种力量的传承。阅读后或许能够短暂的使用这种力量。',Delete=3002309}",
  [3002310] = "{id=3002310,NameZh='上位任务委托书',Icon='item_3002310',Type=41,MaxNum=99999,SellPrice=100,Desc='看似平平无奇的书卷，却是天水之国某个特别组织的委托书。使用后获得来自天水之国的援助。',Delete=3002310}",
  [3002311] = "{id=3002311,NameZh='阿卡娜的杂物箱',Icon='item_3002311',Type=30,MaxNum=99999,SellPrice=100,Desc='似乎是阿卡娜收纳杂物的储物箱，打开必定获得「不祥的魔法书」x1，「来自女武神的馈赠」x1，「祈祷晶片包」x1。',Delete=3002311}",
  [3002312] = "{id=3002312,NameZh='虹光英雄功勋箱',Icon='item_3002312',Type=30,MaxNum=99999,SellPrice=100,Desc='为在【虹色坠落】事件中守护米德加尔特作出卓越贡献的冒险者们准备的谢礼。打开后可获得「虹色奇遇·时光」x1，「雷神的小脾气」x1，「星光祈愿」x1，「荣誉之证」x10000，Zenyx10000000',Delete=3002312}",
  [3002313] = "{id=3002313,NameZh='净化之息',Icon='item_3002313',Type=62,MaxNum=1,SellPrice=100,Desc='拥有吸附邪念的神奇能力，可以用来净化被控制的英灵。',NoStorage=5,ExistTimeType=1,ExistTime='345600',Delete=3002313}",
  [3002314] = "{id=3002314,NameZh='天水古钱',Icon='item_3002314',Type=62,MaxNum=99999,SellPrice=100,Desc='许多年前天水之国发行的货币，如今已经不再流通。但似乎“某些人”仍在使用它作为信物。',Delete=3002314}",
  [3002315] = "{id=3002315,NameZh='魔法残片·梅丽尔',Icon='item_3002315',Type=48,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='神秘的魔法残片，附着了英灵梅丽尔的气息。普隆德拉的教堂边，有一名神官似乎对此物有所了解。（注意：每个账号仅可使用一次）',Delete=3002315}",
  [3002316] = "{id=3002316,NameZh='美食节自选礼盒',Icon='item_3712',Type=30,MaxNum=99999,SellPrice=100,Desc='美食节主席特意为你准备的礼盒，可以自行选择获得以下奖励的一种：「旋风锅铲」x1、「魔法泡泡糖」x1、「弗雷硬币」x1、「小木锤」x5',Feature=1,}",
  [3002317] = "{id=3002317,NameZh='美食节幸运宝箱',Icon='item_3843',Type=30,MaxNum=99999,SellPrice=100,Desc='美食节组委会藏在主会场的宝箱，据说只有幸运儿才能得到~使用之后必定获得「小木锤」x1，必定获得以下奖励的一种：「弗雷硬币」x1、「祈祷晶片包」x2、「莫拉硬币」x5、「神谕之尘」x5、「神谕之晶」x5、「好运币」x2、「萃光结晶」x1，有10%概率额外获赠限定背饰「旋风锅铲」，该背饰可以幻化短剑武器外观。',Feature=1,}",
  [3002318] = "{id=3002318,NameZh='万圣节秘制海鲜汤',Icon='item_500622',Type=41,MaxNum=99999,SellPrice=100,Desc='看起来不是很好喝的海鲜汤，甚至还有中毒的可能，冒险者请谨慎食用！使用后1小时内，野外击杀魔物获得的Base经验和Job经验翻倍！（死亡及非战斗状态下消耗Buff时长，离线状态不消耗Buff时长）',Feature=1,}",
  [3002320] = "{id=3002320,NameZh='逢考必过',Icon='item_3002320',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10264,AdventureValue=80,AdventureReward={buffid={61000560}},StorageReward={buffid={80012640}},Condition=4,ComposeID=3002363,Desc='带上这个头戴我们一起努力！一定会逢考必过！',TFValidDate='2020-08-25 05:00:00',ValidDate='2020-09-01 05:00:00',LoadShowSize=2.5,LoadShowRotate=340,LoadShowPose={0,0.7,0},}",
  [3002321] = "{id=3002321,NameZh='万能公式',Icon='item_3002321',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10265,AdventureValue=140,AdventureReward={buffid={61001090}},StorageReward={buffid={80012970}},Condition=4,ComposeID=3002364,Desc='听说这个公式是可以解开一切的万能公式，快试试吧！',TFValidDate='2020-08-25 05:00:00',ValidDate='2020-09-01 05:00:00',LoadShowPose={0.5,0.5,-1.5},}",
  [3002330] = "{id=3002330,NameZh='翡翠小白龙',Icon='item_3002330',Type=840,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9723,AdventureValue=1,StorageReward={buffid={82000260}},Condition=8,Desc='小白龙族最有灵力的孩子，小小年纪就学会了掌控雷电。也是因为长得太可爱，被长辈指派守护龙族的青印。',TFValidDate='2020-10-01 05:00:00',ValidDate='2020-10-01 05:00:00',LoadShowSize=1.5,LoadShowPose={0,-0.1,0},}",
  [3002331] = "{id=3002331,NameZh='龙之绒',Icon='item_3002331',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9724,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='那些以为龙只有鳞片的冒险者，可能没见过雪地里的龙。雪龙为了御寒脖子上长了一圈细软的绒毛。',TFValidDate='2020-10-01 05:00:00',ValidDate='2020-10-01 05:00:00',}",
  [3002332] = "{id=3002332,NameZh='东洋的龙面',Icon='item_3002332',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9725,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='依斯鲁得的东海有一座叫做东洋的小岛，那里的年轻男子喜欢带着不同款式的面具，其中最华贵的面具被称为龙面。',TFValidDate='2020-10-01 05:00:00',ValidDate='2020-10-01 05:00:00',}",
  [3002333] = "{id=3002333,NameZh='青天[1]',Icon='item_3002333',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9726,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='青天是条帅气的龙，它有个特殊的本领，每当它在天空中飞翔的时候，地面都会下雨。雨过之后的天空一尘不染，带着干净的清辉。',TFValidDate='2020-10-01 05:00:00',ValidDate='2020-10-01 05:00:00',LoadShowRotate=25,LoadShowPose={0,0.6,-0.1},}",
  [3002334] = "{id=3002334,NameZh='叱咤龙刃',Icon='item_3002334',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9727,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='古老的神龙，具有吞云吐雾的本领，能够自由的控制天气。为了学会神龙的魔法，大将军智仁设计了龙首的刀刃，每天佩戴在身上，领略神龙的威力。',TFValidDate='2020-10-01 05:00:00',ValidDate='2020-10-01 05:00:00',LoadShowPose={0.3,0.3,-1.2},}",
  [3002335] = "{id=3002335,NameZh='妖娆的尾',Icon='item_3002335',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9728,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='雌性蛟龙的尾巴，摆动的时候像柔带一样，带着一种妖娆的气质。',TFValidDate='2020-10-01 05:00:00',ValidDate='2020-10-01 05:00:00',LoadShowRotate=30,LoadShowPose={0.5,0.5,0},}",
  [3002336] = "{id=3002336,NameZh='龙不语',Icon='item_3002336',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9062,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='看上去潇洒的龙族，其实都是话痨，经常因为讲话太多被其他种族嫌弃。龙族长老为了改变现状，专门设计了防止话痨说话的面具，以此来保持龙族的威严。',TFValidDate='2020-10-01 05:00:00',ValidDate='2020-10-01 05:00:00',LoadShowPose={-0.3,0.6,1},}",
