  [3002399] = "{id=3002399,NameZh='神龙的馈赠',Icon='item_3002112',Type=30,MaxNum=99999,SellPrice=100,Desc='使用后有概率获得「金质勋章」x2，「光洁的符文石」x1，「神谕之尘」x4，「祈祷晶片包」x2，「尘封的符文袋·Ⅱ」x1，「神谕之晶」x2，「玛斯黛拉种子」x1。',Delete=3002399}",
  [3002400] = "{id=3002400,NameZh='忍法·惊喜礼盒',Icon='item_3002114',Type=30,MaxNum=99999,SellPrice=100,Desc='你永远都不知道火美子会送你什么东西，一切都是惊喜~打开后必定获得随机紫色材料*1，并有概率获得「莫拉硬币」*8，「神谕之尘」*4，「神谕之晶」*2中的一种。',Delete=3002400}",
