  [3002404] = "{id=3002404,NameZh='神龙勾玉',Icon='item_3002404',Type=61,UseMode=31091,MaxNum=99999,SellPrice=10,Desc='蕴藏着异世界能量的勾玉，据说对着它许愿可以梦想成真哦~活动期间内，可打开限时神龙商店，兑换丰厚奖励，勾玉将在11月8日过期哦~',GetLimit={limit={[999]={60,0}},source={22},type=4},ExistTimeType=2,ExistTime='2020-11-08 05:00:00',Delete=3002404}",
  [3002405] = "{id=3002405,NameZh='神龙扭蛋币',Icon='item_3002405',Type=41,MaxNum=99999,SellPrice=100,Desc='集齐七颗龙珠就能召唤神龙。。。异次元扭蛋机。。。除此之外也没其它用啦，冒险者记得在活动期间内用完哦~神龙扭蛋币将在11月8日过期哦~',ExistTimeType=2,ExistTime='2020-11-08 05:00:00',Delete=3002405}",
