  [3002491] = "{id=3002491,NameZh='骇客小子',Icon='item_3002491',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15379,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='电子扫描的灯光闪烁着，骇客小子漫不经心地压了压帽檐，低头走过。在她看似冷酷的外表下，藏着的却是其热烈的探索欲与好奇心。',TFValidDate='2020-11-16 05:00:00',ValidDate='2020-11-19 05:00:00',LoadShowPose={0,0.8,0.1},}",
  [3002492] = "{id=3002492,NameZh='音速行星',Icon='item_3002492',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15380,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='在急速变化的音乐旋律的引领下，少年仿佛漂浮在群星之间，奔向了一个更广阔的世界。',TFValidDate='2020-11-16 05:00:00',ValidDate='2020-11-19 05:00:00',LoadShowRotate=10,LoadShowPose={0,0.7,0},}",
  [3002493] = "{id=3002493,NameZh='旋律漫游者',Icon='item_3002493',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15381,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='不安分的少年背起了他的行囊准备再次出发，“在神秘的城市森林里追随音乐的节拍，音乐将是我唯一的向导。”',TFValidDate='2020-11-16 05:00:00',ValidDate='2020-11-19 05:00:00',LoadShowPose={0,0.5,-0.4},}",
