  [3002496] = "{id=3002496,NameZh='霓虹小精灵',Icon='item_3002496',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15384,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='聪明可爱的人工智能生命，会为乐队精彩的演出献上由衷的喝彩，“喂喂，不要把聚光灯投在我的身上！”',TFValidDate='2020-11-16 05:00:00',ValidDate='2020-11-19 05:00:00',}",
  [3002497] = "{id=3002497,NameZh='矩阵空间',Icon='item_3002497',Type=810,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=15385,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='“如果说，现在和过去都只是自我思维的投射呢？”倔强的少年却并不愿意相信这一点，他固执地在数据洪流中穿梭往返，努力寻找着迷失的记忆。',TFValidDate='2020-11-16 05:00:00',ValidDate='2020-11-19 05:00:00',LoadShowRotate=170,LoadShowPose={0.5,0.1,-1.5},}",
  [3002521] = "{id=3002521,NameZh='KFC宅享礼盒',Icon='item_6519',Type=30,MaxNum=99999,SellPrice=100,Desc='打开后必定获得「Zeny」x300000、「KFC豪华吃鸡餐盒」x5、「疾行小闪电24小时体验券」x1、「闪耀的符文石·星」x1，有额外25%的概率获得「大吉大利桶图纸」哦。',Feature=1,Delete=3002521}",
