  [3002541] = "{id=3002541,NameZh='头顶的小章鱼',Icon='item_3002541',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10292,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='不是真的章鱼爬到头顶了，只是一些另类先锋喜欢章鱼形状的头饰！也许……是克苏鲁爱好者呢……',TFValidDate='2020-12-30 05:00:00',ValidDate='2021-01-06 05:00:00',Delete=3002541}",
