  [3002543] = "{id=3002543,NameZh='依斯鲁得鱼生拼盘',Icon='item_3002543',Type=610,Quality=3,MaxNum=9999,SellPrice=100,Desc='只有在限定季节才出售的豪华鱼生拼盘，布满了新鲜的鱼虾，看上去十分美味。',Delete=3002543}",
  [3002544] = "{id=3002544,NameZh='变！章！鱼！',Icon='item_3002544',Type=77,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=246,AdventureValue=1,StorageReward={buffid={82000100}},Condition=8,Desc='献给超爱章鱼的冒险者，除了吃章鱼、佩戴章鱼饰品、溜章鱼宠物以外，现在隆重推出吃下去就会变章鱼的神奇药水！最好的商品，献给最爱章鱼的你！',NoSale=1,Feature=1,TFValidDate='2020-12-30 05:00:00',ValidDate='2021-01-06 05:00:00',Delete=3002544}",
  [3002545] = "{id=3002545,NameZh='八哥',Icon='item_3002545',Type=101,Quality=3,MaxNum=1,SellPrice=100,Desc='因为有八只脚，被自己的朋友们亲切的称呼为八哥，全身都裹着小斗篷，一副深沉的模样。',TFValidDate='2020-12-30 05:00:00',ValidDate='2021-01-06 05:00:00',Delete=3002545}",
  [3002546] = "{id=3002546,NameZh='杰路刚帝士头像',Icon='Zelgadis_head',Type=1200,Quality=3,MaxNum=1,SellPrice=100,Desc='杰路刚帝士的头像。他是一名极其精英的魔法剑士，精通魔法和剑术。 对力量的追求让他变成了合成兽，目前正在寻找回归原形的方法。',Delete=3002546}",
  [3002547] = "{id=3002547,NameZh='加梅莉亚头像',Icon='Amelia_head',Type=1200,Quality=3,MaxNum=1,SellPrice=100,Desc='加梅莉亚的头像。 塞伦王国的公主。 她精通精灵魔法和白魔法，体术方面也不差。 是一名遗传了父亲强烈的正义感，勇于与邪恶抗争的热血少女。',Delete=3002547}",
  [3002548] = "{id=3002548,NameZh='杰洛士头像',Icon='Xellos_head',Type=1200,Quality=3,MaxNum=1,SellPrice=100,Desc='杰洛士的头像。侍奉于魔王的心腹兽王洁拉丝身边。一头黑色的头发配上娃娃头造型的男性，打扮成神官模样总是微笑着，但本性是冷酷而残忍的。',Delete=3002548}",
  [3002549] = "{id=3002549,NameZh='白蛇娜卡头像',Icon='Naga_head',Type=1200,Quality=3,MaxNum=1,SellPrice=100,Desc='白蛇娜卡的头像。她是个身材火辣的性感美人魔导士，性格有些脱线但却是一位非常有能力的魔导士。',Delete=3002549}",
  [3002550] = "{id=3002550,NameZh='高里·加布列夫头像',Icon='Gourry_head',Type=1200,Quality=3,MaxNum=1,SellPrice=100,Desc='高里·加布列夫的头像，他是佣兵出身的剑士，光之剑士的后裔，性格宽厚纯良，是个拥有一头灿烂金黄头发的年轻男子。',Delete=3002550}",
  [3002551] = "{id=3002551,NameZh='莉娜·因巴斯头像',Icon='Lina_head',Type=1200,Quality=3,MaxNum=1,SellPrice=100,Desc='莉娜·因巴斯的头像。被坏蛋、甚至是巨龙所惧畏着的美丽的天才少女魔导士。除了最强的攻击性法术“龙破斩”外，她还会使用自己的原创魔法“重破斩”、“神灭斩”等。',Delete=3002551}",
  [3002552] = "{id=3002552,NameZh='负面能量',Icon='item_6225',Type=61,Quality=3,UseMode=31137,MaxNum=99999,SellPrice=100,Desc='因为人类的负面情感，产生的能量，对魔族来说是美味的食物。',GetLimit={limit={[999]={80,0}},source={22},type=4},ExistTimeType=2,ExistTime='2021-01-31 05:00:00',Delete=3002552}",
  [3002553] = "{id=3002553,NameZh='火龙的藏宝箱',Icon='item_5757',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='烫手的宝箱，还带着龙焰的高温，是巨龙的心爱之物。打开后可获得「B格猫福利券·宴」x20，有概率获得以下道具中的一种：「乐园币」x200、「冒险丸子」x200、「玛丝黛拉种子」x1、「九界原石」x1、「高原坚木」x20。',Delete=3002553}",
  [3002554] = "{id=3002554,NameZh='海鲜冷藏盒',Icon='item_3002608',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='带有低温机械核心的小盒子，能够使盒子里的食物保持新鲜。打开后有概率获得「神谕之尘」x2、「祈祷晶片包」x1、「莫拉硬币」x2、「金质勋章」x1、「玛丝黛拉种子」x1、「来自女武神的馈赠」x1。',Delete=3002554}",
  [3002555] = "{id=3002555,NameZh='魔王的赏赐',Icon='item_3038',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='来自魔王的礼盒，打开的时候要格外注意，否则可能会被魔王诅咒哦~打开后可获得「负面能量」x40，有概率获得以下道具中的一种：「神谕之尘」x2、「祈祷晶片包」x1、「莫拉硬币」x2、「金质勋章」x1、「玛斯黛拉种子」x1、「来自女武神的馈赠」x1。',Delete=3002555}",
  [3002556] = "{id=3002556,NameZh='异世界的礼物',Icon='item_3951',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='从异世界漂流而来的礼物，里面可能装着一些好东西！打开后可获得「负面能量」x35，「B格猫福利券·宴」x20.',Delete=3002556}",
  [3002557] = "{id=3002557,NameZh='海族的谢礼',Icon='item_146566',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='依斯鲁德海底的海族为了感谢冒险者的帮助，制作的感恩礼，一定要好好使用不要辜负海族的心意。',Delete=3002557}",
  [3002558] = "{id=3002558,NameZh='龙见愁',Icon='item_3002558',Type=10,Quality=3,MaxNum=99999,SellPrice=100,Desc='传言道，巨龙似乎也惧畏着她。',TFValidDate='2021-01-03 05:00:00',ValidDate='2021-01-10 05:00:00',Delete=3002558}",
  [3002559] = "{id=3002559,NameZh='章鱼王冠',Icon='item_3002559',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15399,AdventureValue=1,StorageReward={buffid={80012930}},Condition=8,Desc='深海里章鱼王族拥有的皇冠，是章鱼族身份与地位的象征。',TFValidDate='2020-12-30 05:00:00',ValidDate='2021-01-06 05:00:00',Delete=3002559}",
  [3002560] = "{id=3002560,NameZh='魔力小章鱼',Icon='item_3002560',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15400,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='拥有魔力的章鱼，全身燃烧着黑紫色的火焰，看上去非常威风。',TFValidDate='2020-12-30 05:00:00',ValidDate='2021-01-06 05:00:00',Delete=3002560}",
  [3002561] = "{id=3002561,NameZh='魔鬼小章鱼',Icon='item_3002561',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15401,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='长角的章鱼，外皮是罕见的火红色，因为长得像魔鬼被动物学家起名为魔鬼小章鱼。',TFValidDate='2020-12-30 05:00:00',ValidDate='2021-01-06 05:00:00',LoadShowSize=1,Delete=3002561}",
