  [3002584] = "{id=3002584,NameZh='混沌语的残页',Icon='item_6733',Type=48,Quality=3,MaxNum=1,SellPrice=100,Desc='记载着混沌语言的书籍，尽管无法阅读，但是能感受到上面附着的强大力量。使用后可以开启转职任务。',Delete=3002584}",
  [3002585] = "{id=3002585,NameZh='火焰之心',Icon='item_3002585',Type=810,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=15408,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='火焰的灵魂，火焰的光芒，学会龙破斩的少女，从烈火之中取出的火焰之心。这是所有魔导士的梦想，在龙之烈焰中领悟火焰的魅力。',TFValidDate='2020-12-30 05:00:00',ValidDate='2021-01-06 05:00:00',Delete=3002585}",
  [3002600] = "{id=3002600,NameZh='神之锻造盒-烈焰剑',Icon='item_6631',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='打开后获得「龙鳞」x8~10、「断柄之刃」x30~50、「铠甲碎片」x100、「深渊花」x1000，必定并随机获得以下一组材料：「时间扭曲键」x1、「闪耀圣水」x1、「小红帽」x1、「盾牌的碎片」x1、「黯魂粉尘」x15或「安眠木」x50。',Delete=3002600}",
  [3002601] = "{id=3002601,NameZh='萃光武器自选礼盒',Icon='item_3002601',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='专为装备萃取功能打造的武器礼盒，使用之后可以自行选择物理穿刺效果的「易燃短剑[1]」x1，或者魔法穿刺效果的「邪念的权杖[1]」x1',Feature=1,Delete=3002601}",
  [3002602] = "{id=3002602,NameZh='萃光材料补给箱',Icon='item_3952',Type=30,MaxNum=99999,SellPrice=100,Desc='神秘商人特意准备的礼盒，使用之后可以获得「萃光结晶」x5~10，有10%概率额外获赠「萃光武器自选礼盒」x1，可以自行选择物理穿刺效果的「易燃短剑[1]」x1，或者魔法穿刺效果的「邪念的权杖[1]」x1',Feature=1,Delete=3002602}",
  [3002603] = "{id=3002603,NameZh='萃光材料体验箱',Icon='item_3951',Type=30,MaxNum=99999,SellPrice=100,Desc='神秘商人特意准备的礼盒，使用之后可以获得「萃光结晶」x5',Feature=1,Delete=3002603}",
