  [3002605] = "{id=3002605,NameZh='秀逗魔导士',Icon='item_3002605',Type=501,Quality=3,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000010}},Desc='华丽的披风虽然有点碍事，但谁让它是莉娜喜欢的造型呢！看上去是个超酷的美少女！',TFValidDate='2020-12-30 05:00:00',ValidDate='2021-01-06 05:00:00',Delete=3002605}",
