  [3002620] = "{id=3002620,NameZh='达纳托斯的神恩',Icon='item_3977',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='达纳托斯的神恩，使用之后最多可以获得四份奖励！\n必定获得以下道具中的一种：「神之恩赐宝箱」x1、「奥术至宝」x1、「深渊之匣」x1、「逝去的荣光之匣」x1\n12%概率额外获得以下道具中的一种：「迷你狮鹫魔物蛋」x1、「女武神头冠[1]」x1、「女武神之翼」x1、「炽热符文之影」x1、「慧光之钥[1]」x1、「破碎圣裁」x1、「残破噩梦」x1、「诅咒戾痕[1]」x1、「堕落辉光」x1、「深渊低语」x1、「腐朽沉眠[1]」x1、「月光梦魇」x1\n0.1%概率额外获得以下道具中的一种：「女武神拉斯格瑞丝卡片」x1、「奥术魔方卡片」x1、「意念聚合体卡片」x1、「魔剑士达纳托斯卡片」x1\n0.25%概率额外获得「圣雪羽」x1',Delete=3002620}",
  [3002630] = "{id=3002630,NameZh='初心豆芽',Icon='item_3002630',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10298,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='头顶上的豆芽会随风摇曳，象征着萌新的你正生机盎然。愿你不忘初心，一同守护这永恒的爱。',Feature=1,TFValidDate='2020-12-30 05:00:00',ValidDate='2021-01-06 05:00:00',}",
  [3002631] = "{id=3002631,NameZh='初心花冠',Icon='item_3002631',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10299,AdventureValue=1,StorageReward={buffid={80012630}},Condition=8,Desc='精致的花冠轻轻戴在头顶，那美丽的花朵正在绽放。愿你不忘初心，一同守护这永恒的爱。',Feature=1,TFValidDate='2020-12-30 05:00:00',ValidDate='2021-01-06 05:00:00',}",
