  [3002650] = "{id=3002650,NameZh='天穹彼望·苍夜',Icon='item_3002650',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='云端之上，明月之下，传说中的天穹城静谧无声。守护此地的天空骑士翱翔于天际，他融于夜色，与星辰为伴，是永不松懈的守夜人。',TFValidDate='2020-10-12 05:00:00',ValidDate='2020-10-15 05:00:00',MainColor='8121caFF',}",
  [3002651] = "{id=3002651,NameZh='天穹彼望·青空',Icon='item_3002650',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='云端之上，烈阳之下，传说中的天穹城煜煜生辉。守护此地的天空骑士翱翔于天际，他与轻风为伴，是忠诚可靠的巡游者。',TFValidDate='2020-10-12 05:00:00',ValidDate='2020-10-15 05:00:00',MainColor='22d6d0FF',}",
  [3002652] = "{id=3002652,NameZh='天穹彼望·绯羽',Icon='item_3002650',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='云端之上，夕阳之下，传说中的天穹城煜煜生辉。守护此地的天空骑士翱翔于天际，晚霞为他的羽翼染上绯红。',MainColor='da2153FF',}",
  [3002653] = "{id=3002653,NameZh='天穹彼望·炽翎',Icon='item_3002650',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='云端之上，朝阳之下，传说中的天穹城煜煜生辉。守护此地的天空骑士翱翔于天际，朝阳为他的羽翼染上火焰的颜色，他以火一般的热情保护天穹城。',TFValidDate='2020-10-12 05:00:00',ValidDate='2020-10-15 05:00:00',MainColor='f8a334FF',}",
  [3002660] = "{id=3002660,NameZh='云端漫舞·苍夜',Icon='item_3002660',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='她漫步天空，在云间起舞，婀娜的舞姿扬起云岚，遮蔽了夜晚的天穹城，令外界无法发现这座传说之城的踪迹。',TFValidDate='2020-10-12 05:00:00',ValidDate='2020-10-15 05:00:00',MainColor='8121caFF',}",
  [3002661] = "{id=3002661,NameZh='云端漫舞·青空',Icon='item_3002660',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='她漫步天空，在云间起舞，轻盈的舞姿扬起云岚，遮蔽了青空中的天穹城，令外界无法发现这座传说之城的踪迹。',TFValidDate='2020-10-12 05:00:00',ValidDate='2020-10-15 05:00:00',MainColor='22d6d0FF',}",
  [3002662] = "{id=3002662,NameZh='云端漫舞·绯羽',Icon='item_3002660',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='她漫步天空，在云间起舞，曼妙的舞姿唤来晚霞萦绕天际，遮蔽了天穹城，令外界无法发现这座传说之城的踪迹。',TFValidDate='2020-10-12 05:00:00',ValidDate='2020-10-15 05:00:00',MainColor='da2153FF',}",
  [3002663] = "{id=3002663,NameZh='云端漫舞·炽翎',Icon='item_3002660',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='她漫步天空，在云间起舞，轻灵的舞姿如同跳动的火焰，将天穹城隐藏于耀眼的阳光中，令外界无法发现这座传说之城的踪迹。',MainColor='f8a334FF',}",
