  [3002697] = "{id=3002697,NameZh='逐日者之翼',Icon='item_3002697',Type=810,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=15396,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='传说中的天穹城，建立在云端之上的城市。“总有一天，我要亲眼到那里看看！”小铁匠许下宏愿。这双用羽毛黏连的翅膀，将带他到达梦想的彼岸。',TFValidDate='2020-10-12 05:00:00',ValidDate='2020-10-15 05:00:00',LoadShowRotate=340,LoadShowPose={0,0.1,-0.6},}",
  [3002700] = "{id=3002700,NameZh='王国的谢礼',Icon='item_3663',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='参与魔法炮“海姆达尔之眼”的建设获得的酬劳。打开后可获得以下道具中的一种：「乐园币」x200，「高原坚木」x20，「九界原石」x1，「荣誉之证」x200，「莫拉硬币」x2。',}",
  [3002701] = "{id=3002701,NameZh='虹光功勋箱',Icon='item_3877',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='为在【虹色坠落】事件中守护米德加尔特作出突出贡献的冒险者们准备的谢礼。',}",
  [3002702] = "{id=3002702,NameZh='异界守卫长的遗物',Icon='item_6604',Type=30,Quality=3,MaxNum=1,SellPrice=100,Desc='击败异界守卫守卫长获得的战利品，打开后有概率获得「神谕之晶」x4、「神谕之尘」x4、「萃光结晶」x2、「祈祷晶片包」x2、「金质勋章」x2中的一种，还有额外概率获得「天水古钱」x1.',NoStorage=5,ExistTimeType=1,ExistTime='86400',}",
  [3002703] = "{id=3002703,NameZh='海姆达尔之眼·原型机',Icon='item_3002703',Type=77,Quality=3,MaxNum=99999,SellPrice=100,AdventureValue=1,StorageReward={buffid={82000150}},Condition=8,Desc='魔法炮“海姆达尔之眼”的设计样品。虽然体积很小，但原理与“海姆达尔之眼”完全相同，全力发射足以击碎一整只波利。',TFValidDate='2020-09-30 05:00:00',ValidDate='2020-10-07 05:00:00',}",
  [3002704] = "{id=3002704,NameZh='虹光幻舞',Icon='item_47232',Type=810,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=10285,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='用欢笑、幸福、青春等美好之物为材料制成的翅膀，如同霓虹般绚烂。所过之处，洒落虹光，为人们带来希望。',TFValidDate='2020-11-25 05:00:00',ValidDate='2020-12-02 05:00:00',}",
  [3002705] = "{id=3002705,NameZh='羽化之匣',Icon='item_3838',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='拥有着令人羽化成蝶的力量。使用后必定获得「神谕之晶」x6~12、「神谕之尘」x8~15、「不祥的魔法书」x1、「祈祷晶片包」x1，有概率获得背饰「虹光幻舞」x1。（使用「不祥的魔法书」可获得「随机MVP材料」x2，Zeny x100000。）',}",
  [3002706] = "{id=3002706,NameZh='魔法残片·赫德',Icon='item_3002706',Type=48,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='神秘的魔法残片，附着了英灵赫德的气息。普隆德拉的教堂边，有一名神官似乎对此物有所了解。（注意：每个账号仅可使用一次）',}",
  [3002707] = "{id=3002707,NameZh='魔法残片·梅菲尔林瑟',Icon='item_3002707',Type=48,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='神秘的魔法残片，附着了英灵梅菲尔林瑟的气息。普隆德拉的教堂边，有一名神官似乎对此物有所了解。（注意：每个账号仅可使用一次）',}",
  [3002708] = "{id=3002708,NameZh='魔法残片·诺曼',Icon='item_3002708',Type=48,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='神秘的魔法残片，附着了英灵诺曼的气息。普隆德拉的教堂边，有一名神官似乎对此物有所了解。（注意：每个账号仅可使用一次）',}",
