  [3002731] = "{id=3002731,NameZh='伊莉雅的谢礼',Icon='item_3620',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='“幸福是要自己去争取的”伊莉雅赠与冒险者的箴言。打开后有概率获得「光洁的符文石」x1、「闪耀的符文石」x1、「祈祷晶片包」x2、「尘封的符文袋·Ⅱ」x1、「神谕之晶」x2、「玛斯黛拉种子」x1，必定获得「小木锤」x1。',}",
  [3002732] = "{id=3002732,NameZh='堕天的意志图纸',Icon='item_3002792',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=3002732,Desc='\"实力来源于自己所坚持的骄傲与自信\"抵制一切美好的力量最终会反噬自己。',TFValidDate='2020-10-25 05:00:00',ValidDate='2020-11-01 05:00:00',}",
  [3002735] = "{id=3002735,NameZh='恋爱酸臭礼盒',Icon='item_6632',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='如果可能的话，我希望打开的时候没有恋爱的酸臭味。打开后可获得「家具提货券」x6、「B格猫福利券·Ⅰ」x6、「神谕之尘」x6、「神谕之晶」x4、「小木锤」x1。',}",
  [3002738] = "{id=3002738,NameZh='小木锤',Icon='item_3001889',Type=30,UseMode=31043,MaxNum=99999,SellPrice=100,Desc='虽然是普通木制小锤，但是却能发挥巨大威力，真是惊人！“喂！这个不可以用来打人！”',ExistTimeType=2,ExistTime='2020-12-01 05:00:00',Feature=1,}",
  [3002740] = "{id=3002740,NameZh='初心者手账',Icon='item_6590',Type=41,Quality=3,UseMode=31132,MaxNum=1,SellPrice=100,Desc='初到米德加尔特的罗安，对一切都感到好奇，熟悉而又陌生，于是他记录了这期间的所见所闻。',NoSale=1,ExistTimeType=2,ExistTime='2021-03-06 05:00:00',Feature=1,}",
  [3002741] = "{id=3002741,NameZh='学习笔记',Icon='item_3995',Type=30,Quality=3,MaxNum=9999,SellPrice=100,Desc='从洛林那里学习的冒险技巧，分享给其他人将获得双倍的快乐！使用后，获赠「B格猫福利券·宴」x10、「坠星陨铁」x1、「料理兑换券」x1、「波利成长秘药」x1',Feature=1,}",
  [3002742] = "{id=3002742,NameZh='记忆棱镜',Icon='item_6099',Type=61,Quality=3,UseMode=31123,MaxNum=9999,SellPrice=100,Desc='这小小的东西似乎能融入「初心者手账」中，能逐渐感到其封印的力量正在变弱……',GetLimit={limit={[999]={500,0}},source={22},type=4},ExistTimeType=2,ExistTime='2021-01-17 05:00:00',Feature=1,}",
  [3002743] = "{id=3002743,NameZh='闪光记忆',Icon='item_5961',Type=61,Quality=3,UseMode=31123,MaxNum=9999,SellPrice=100,Desc='闪闪发光的记忆凝聚了每一个美好的瞬间，没想到竟然完好的保存了下来。',ExistTimeType=2,ExistTime='2021-01-17 05:00:00',Feature=1,}",
  [3002744] = "{id=3002744,NameZh='记忆礼盒',Icon='item_146561',Type=30,Quality=3,MaxNum=9999,SellPrice=100,Desc='为了感谢你捐赠的「记忆棱镜」，特别赠予了你这个礼盒。使用后，必定获得「闪光记忆」x1。必定获得以下道具中的2种：「玛丝黛拉种子」x1、「乐园币」x150、「金质勋章」x1、「祈祷晶片包」x1、「神谕之晶」x2、「神谕之尘」x2、「莫拉硬币」x2',Feature=1,}",
  [3002745] = "{id=3002745,NameZh='罗安的谢礼',Icon='item_3900',Type=30,Quality=3,MaxNum=9999,SellPrice=100,Desc='为感谢你这段时间的照顾，罗安决定赠送这份礼物给你。使用后，获赠「B格猫福利券·宴」x10、「来自女武神的馈赠」x2、「祈祷晶片包」x2、「神秘箱子v2.0」x2',Feature=1,}",
  [3002746] = "{id=3002746,NameZh='契约之誓·罗安',Icon='item_3002746',Type=77,Quality=2,MaxNum=1,SellPrice=100,AdventureSort=116,AdventureValue=1,StorageReward={buffid={82000100}},Condition=8,Desc='我是罗安，我们再次一起冒险吧！',Feature=1,TFValidDate='2020-12-30 05:00:00',ValidDate='2021-01-06 05:00:00',}",
