  [3002748] = "{id=3002748,NameZh='异国硬币',Icon='item_1000006',Type=61,Quality=2,UseMode=31108,MaxNum=9999,SellPrice=100,Desc='异世界使用的普通货币，可以用来兑换稀有道具。',GetLimit={limit={[999]={100,0}},source={22},type=4},ExistTimeType=2,ExistTime='2021-01-27 05:00:00',Feature=1,}",
  [3002749] = "{id=3002749,NameZh='异国魔币',Icon='item_1000007',Type=61,Quality=3,UseMode=31109,MaxNum=9999,SellPrice=100,Desc='异世界使用的稀有货币，只有「异界·梦罗克」才会掉落，可以用来兑换稀有道具。',GetLimit={limit={[999]={6,0}},source={22},type=4},ExistTimeType=2,ExistTime='2021-01-27 05:00:00',Feature=1,}",
  [3002750] = "{id=3002750,NameZh='异界珍宝',Icon='item_5943',Type=30,Quality=3,MaxNum=9999,SellPrice=100,Desc='「异界·梦罗克」携带的宝箱，里面或许有一些好东西！使用后，获赠Zeny x 50,000、「B格猫福利券·宴」x5、「龙之宝箱」x1',GetLimit={limit={[999]={3,0}},source={22},type=4},Feature=1,}",
  [3002751] = "{id=3002751,NameZh='庆典礼盒',Icon='item_3001763',Type=30,Quality=3,MaxNum=9999,SellPrice=100,Desc='嘿，又有盛大的庆典举办了！快跟罗安去看看吧！使用后，获赠「金质勋章」x1、「古拉姆晶末」x5、「神秘箱子v2.0」x2',Feature=1,}",
  [3002752] = "{id=3002752,NameZh='七彩惊喜盒',Icon='item_3944',Type=30,Quality=3,MaxNum=9999,SellPrice=100,Desc='收纳了众多魔物喜欢的东西，总有一款能带给你惊喜！使用后，获赠「任意宠物捕捉材料」x1',Feature=1,}",
  [3002753] = "{id=3002753,NameZh='誓约之契',Icon='item_3689',Type=30,Quality=2,MaxNum=1,SellPrice=100,Desc='象征着友情的物件，在使用了神奇的魔法之后，竟然可以分离出「誓约之契·罗安」或者是「誓约之契·优法」',Feature=1,}",
  [3002754] = "{id=3002754,NameZh='普通骰子',Icon='item_3002754',Type=61,UseMode=31129,MaxNum=99,SellPrice=100,Desc='常见的骰子，每次投掷后随机出1个点数。',ExistTimeType=2,ExistTime='2021-01-28 05:00:00',Feature=1,}",
  [3002755] = "{id=3002755,NameZh='魔力骰子',Icon='item_3002755',Type=61,UseMode=31129,MaxNum=99,SellPrice=100,Desc='具有魔力的骰子，每次可自定义1个点数。',ExistTimeType=2,ExistTime='2021-01-28 05:00:00',Feature=1,}",
  [3002756] = "{id=3002756,NameZh='初心者手账·纪念册',Icon='item_63406',Type=77,UseMode=31132,MaxNum=1,SellPrice=100,AdventureSort=115,AdventureValue=1,StorageReward={buffid={82000110}},Condition=8,Desc='收录了异世界冒险者罗安首次来到米德加尔特大陆的珍贵回忆，想念那段时光的时候就打开看看吧！',Feature=1,TFValidDate='2020-12-30 05:00:00',ValidDate='2021-01-06 05:00:00',}",
  [3002760] = "{id=3002760,NameZh='波利雪顶·清莓',Icon='item_3002760',Type=800,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80013080}},Desc='“好热呀，感觉自己快要融化了！”小波利躲进冰淇淋盒子，果然这样就凉快多了！“噫？这清甜的味道，是草莓！”那沁人的香气，甜中微酸的口味，让人忘记炎热——这是夏日的凉风，是雨后的初晴，是回忆中的那一抹甜。',Feature=1,TFValidDate='2020-09-27 05:00:00',ValidDate='2020-09-27 05:00:00',LoadShowPose={0,0,0},Delete=3002760}",
  [3002761] = "{id=3002761,NameZh='波利雪顶·缤果',Icon='item_3002761',Type=800,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80013080}},Desc='“好热呀，感觉自己快要融化了！”土波利躲进冰淇淋盒子，果然这样就凉快多了！“噫？这香味——是芒果和百香果！”蓝天白云、阳光沙滩，拂面的海风中带着水果的芬芳。果然呐，夏天就是要去海滩！',Feature=1,TFValidDate='2020-09-27 05:00:00',ValidDate='2020-09-27 05:00:00',Delete=3002761}",
  [3002762] = "{id=3002762,NameZh='波利雪顶·茶忆',Icon='item_3002762',Type=800,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80013080}},Desc='“好热呀，感觉自己快要融化了！”波波利躲进冰淇淋盒子，果然这样就凉快多了！“噫？这个味道，是抹茶！”这是天水之国的味道：淡淡的苦味，弥漫着清香，令人回味无穷。眼前浮现的面容，是天津町的波利MM，那是逝去的青春。',Feature=1,TFValidDate='2020-09-27 05:00:00',ValidDate='2020-09-27 05:00:00',Delete=3002762}",
  [3002763] = "{id=3002763,NameZh='波利雪顶·甜心',Icon='item_3002763',Type=800,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80013080}},Desc='“好热呀，感觉自己快要融化了！”天使波利躲进冰淇淋盒子，果然这样就凉快多了！“噫？好甜的香味——是黑糖奶茶！”焦香的黑糖、浓郁的牛奶与甘美的红茶交织成一杯百分百香浓的黑糖奶茶，从嘴里甜到心头——这，是恋爱的感觉嘛！',Feature=1,TFValidDate='2020-09-27 05:00:00',ValidDate='2020-09-27 05:00:00',Delete=3002763}",
  [3002764] = "{id=3002764,NameZh='波利雪顶·奇趣',Icon='item_3002764',Type=800,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80013080}},Desc='“好热呀，感觉自己快要融化了！”金属波利躲进冰淇淋盒子，果然这样就凉快多了！“噫？好浓郁的味道——是巧克力！”这细腻的芳香、丝滑的触感——等等！在绵软的冰淇淋中隐藏着爽脆的巧克力珍珠！这感觉，就像寻找埋藏于沙海中的宝藏——这，就是夏日的惊喜吗？',Feature=1,TFValidDate='2020-09-27 05:00:00',ValidDate='2020-09-27 05:00:00',Delete=3002764}",
  [3002765] = "{id=3002765,NameZh='波利冰淇淋系列头饰',Icon='item_3002765',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10289,AdventureValue=1,StorageReward={buffid={80013080}},Condition=8,Feature=1,TFValidDate='2020-09-27 05:00:00',ValidDate='2020-09-27 05:00:00',Delete=3002765}",
  [3002766] = "{id=3002766,NameZh='梦幻波利雪顶·极光',Icon='item_3002766',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=10290,AdventureValue=1,StorageReward={buffid={80012810}},Condition=8,Desc='“好热呀，感觉自己快要融化了！”虹光波利躲进冰淇淋盒子，果然这样就凉快多了！“咦咦咦！！这光芒——是极光？！”生活就像冰淇淋，在打开前你永远不知道有怎样的惊喜等着你。就像现在这样，一盒混合了多种口味的冰淇淋，迸发出璀璨的虹光，多种的口味交织出复杂味道，就像我们的生活，等着我们细细品味。',Feature=1,TFValidDate='2020-09-27 05:00:00',ValidDate='2020-09-27 05:00:00',LoadShowPose={0,0,0},Delete=3002766}",
  [3002770] = "{id=3002770,NameZh='黑山羊的怒火[1]',Icon='item_3002770',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9729,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='死神最爱的宠物，就是黑金山羊，据说这山羊的脾气极大，当它生气的时候，可以将地狱里的亡灵都踏碎。',TFValidDate='2020-11-01 05:00:00',ValidDate='2020-11-01 05:00:00',}",
  [3002771] = "{id=3002771,NameZh='雷霆之子',Icon='item_3002771',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9730,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='掌控雷电的天空之子，虽然拥有强大的力量，可内心还是个孩子，如果看见他哭鼻子也不要惊讶。',TFValidDate='2020-11-01 05:00:00',ValidDate='2020-11-01 05:00:00',LoadShowPose={0,-0.3,0},}",
  [3002772] = "{id=3002772,NameZh='大力神头盔[1]',Icon='item_3002772',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9731,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='拥有世间至高之力的大力神，用黄金、金苹果和咒文制成大力神头盔。佩戴者能够获得无边的怪力！',TFValidDate='2020-11-01 05:00:00',ValidDate='2020-11-01 05:00:00',LoadShowRotate=345,}",
  [3002773] = "{id=3002773,NameZh='战争降临',Icon='item_3002773',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9732,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='战神的武器，由天启之四骑士在世界最后之日从天空中掷下，引起大陆国家之间的战争。',TFValidDate='2020-11-01 05:00:00',ValidDate='2020-11-01 05:00:00',LoadShowPose={0,0.3,-0.5},}",
  [3002774] = "{id=3002774,NameZh='爱的狩猎',Icon='item_3002774',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9733,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='爱神之箭，虽然不会让人肉体受到伤害，却比最锋利的刀剑都要致命。',TFValidDate='2020-11-01 05:00:00',ValidDate='2020-11-01 05:00:00',LoadShowPose={-0.2,0.5,0.8},}",
  [3002775] = "{id=3002775,NameZh='入梦',Icon='item_3002775',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9734,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='黑夜降临之时，睡梦之神都会引诱人类进入香甜的梦里，这是一个人一天之中最安宁的时刻。',TFValidDate='2020-11-01 05:00:00',ValidDate='2020-11-01 05:00:00',LoadShowRotate=345,LoadShowPose={-0.2,0.2,0.5},}",
  [3002776] = "{id=3002776,NameZh='大洋的王冠',Icon='item_3002776',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9063,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='海神的王冠，戴上后可以获得掌控海洋的力量。',TFValidDate='2020-11-01 05:00:00',ValidDate='2020-11-01 05:00:00',LoadShowRotate=345,LoadShowPose={-0.2,0.2,0.3},}",
  [3002780] = "{id=3002780,NameZh='神之锻造盒-龙神之剑',Icon='item_6635',Type=30,Quality=4,MaxNum=99999,SellPrice=100,Desc='蕴含了各种锻造「龙神之剑」的材料，打开之后必定获得「黑云母」x4~6、「断柄之刃」x30~50、「铠甲碎片」x100、「泯灭之心」x1000，随机获得以下材料中的一种：「闪耀圣水」x1、「破斗篷的碎片」x1、「盾牌的碎片」x1、「钟塔之钥」x1、「黯然粉尘」x15、「安眠木」x50',Feature=1,Delete=3002780}",
  [3002781] = "{id=3002781,NameZh='极速成长礼包',Icon='item_6605',Type=30,Quality=4,MaxNum=99999,SellPrice=100,Desc='活动商人卡特为小救星的成长保驾护航特意推出的极具性价比的礼包！打开之后可以获得以下道具：\n「专属job药水」x2100，秒速升至四转！\n随机「小救星专属S级符文」x5\n一整套推荐装备，包括：「龙王之剑[1]」x1、「蔷薇姬的腕轮」x1、「铁质铠甲」x1、「伯爵斗篷」x1、「狼外婆的拖鞋」x1、「强力戒指」x1、「黑狐颈链」x1。',Feature=1,Delete=3002781}",
  [3002782] = "{id=3002782,NameZh='专属job药水',Icon='item_12387',Type=41,Quality=4,MaxNum=99999,SellPrice=1,Desc='小救星系职业专属！使用之后可以获得4000000 JOB经验！（使用时请注意当前JOB经验上限，若超过上限，请先进行转职任务）',Feature=1,Delete=3002782}",
