  [3002822] = "{id=3002822,NameZh='煌炎之冠',Icon='item_3002822',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10294,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='纯金打造的头饰，镶嵌了许多带有魔力的宝石。据说是从某个古代遗迹中所发掘，在极特殊情况下可散发出炽热的火焰。',TFValidDate='2020-12-30 05:00:00',ValidDate='2021-01-06 05:00:00',LoadShowPose={0,0.8,0.1},Delete=3002822}",
  [3002823] = "{id=3002823,NameZh='杰路刚帝士的剑【武器外观】',Icon='item_3002823',Type=180,MaxNum=99,SellPrice=100,AdventureValue=1,Condition=8,Desc='杰路刚帝士的武器，锋利无比像岩石般坚硬。',TFValidDate='2020-12-30 05:00:00',ValidDate='2021-01-06 05:00:00',LoadShowSize=1.3,LoadShowRotate=90,LoadShowPose={0,-0.4,0},Delete=3002823}",
