  [3002826] = "{id=3002826,NameZh='永恒的笑靥',Icon='item_3002826',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10297,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='原本是一个三流魔法师想要让世界陷入绝望、悲伤的情绪中所制造的魔法药剂，结果因为魔力枯竭， 最终却让人永远欢笑。',TFValidDate='2020-12-30 05:00:00',ValidDate='2021-01-06 05:00:00',LoadShowRotate=340,LoadShowPose={-0.3,0.6,1},Delete=3002826}",
  [3002827] = "{id=3002827,NameZh='瑟菲丽亚熔渣',Icon='item_3002827',Type=90,Quality=5,MaxNum=1,SellPrice=100,AdventureSort=1023,AdventureValue=1,AdventureReward={buffid={63000240}},Condition=8,Desc='魔法之地瑟菲丽亚诞生的巨龙，天生拥有掌控火焰的力量，能够吐出炙热的龙息将一切敌人化为灰烬。魔物观察者怀着敬意给它起名为熔渣。',TFValidDate='2020-12-30 05:00:00',ValidDate='2021-01-06 05:00:00',Delete=3002827}",
  [3002828] = "{id=3002828,NameZh='魔语者转职礼盒',Icon='item_3896',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='专为想要多个角色体验魔语者的冒险者而准备。使用之后必定获得「B格猫福利券·宴」x300、魔语者转职道具「混沌语的残页」x1',Feature=1,Delete=3002828}",
  [3002830] = "{id=3002830,NameZh='坐骑折扣券',Icon='item_3000545',Type=61,UseMode=31113,MaxNum=99999,SellPrice=100,Desc='使用之后可以打开「特惠坐骑商城」，以更低的价格购入心仪的坐骑哦~',ExistTimeType=2,ExistTime='2020-12-05 05:00:00',Feature=1,Delete=3002830}",
  [3002831] = "{id=3002831,NameZh='黑猫秘宝',Icon='item_6504',Type=30,MaxNum=99999,SellPrice=100,Desc='没有人知道黑猫收集了多少宝贝，就像不知道仓鼠颊囊中藏了多少食物~打开后可获得「弗雷硬币」x30。',Feature=1,Delete=3002831}",
  [3002840] = "{id=3002840,NameZh='锦鳞浮绘·花火',Icon='item_3002840',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000020}},Desc='少年穿上新装，准备迎来自己的成人礼，在这之后，他就要为了梦想远走他乡。礼服上精美的纹路配饰，传承自天水之国的古老习俗，也是家人们对他的美好寄愿：人生当如花火般绚烂，虽短短一瞬却可点亮漫漫长夜。',TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',MainColor='870c0cFF',}",
  [3002841] = "{id=3002841,NameZh='锦鳞浮绘·御庭樱',Icon='item_3002840',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000020}},Desc='少年穿上新装，准备迎来自己的成人礼，在这之后，他就要为了梦想远走他乡。礼服上精美的纹路配饰，传承自天水之国的古老习俗，也是家人们对他的美好寄愿：樱花花期只有短短数天，但花开时的烂漫却让一年的等待变得值得，人生当如庭中樱花，厚积薄发。',TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',MainColor='cb25a6FF',}",
  [3002842] = "{id=3002842,NameZh='锦鳞浮绘·弥生',Icon='item_3002840',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000020}},Desc='少年穿上新装，准备迎来自己的成人礼，在这之后，他就要为了梦想远走他乡。礼服上精美的纹路配饰，传承自天水之国的古老习俗，也是家人们对他的美好寄愿：春天万物弥生，少年应当像春天一样，充满朝气。',TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',MainColor='04a9b8FF',}",
  [3002843] = "{id=3002843,NameZh='锦鳞浮绘·夜樱',Icon='item_3002840',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000020}},Desc='少年穿上新装，准备迎来自己的成人礼，在这之后，他就要为了梦想远走他乡。礼服上精美的纹路配饰，传承自天水之国的古老习俗，也是家人们对他的美好寄愿：少年当注重内在，如隐于夜色的樱花，不见其形而芬芳仍在。',TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',MainColor='221c19FF',}",
  [3002850] = "{id=3002850,NameZh='樱绽余华·花火',Icon='item_3002850',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000020}},Desc='少女穿上成人仪式的礼服，其华美令烂漫的樱花也黯然失色。精美的纹路配饰，传承自天水之国的古老习俗，也寄托着亲人们对她的美好祝愿：青春如点亮夜空的花火，绚烂却稍纵即逝，愿她惜取光阴，不负年少。',TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',MainColor='870c0cFF',}",
  [3002851] = "{id=3002851,NameZh='樱绽余华·御庭樱',Icon='item_3002850',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000020}},Desc='少女穿上成人仪式的礼服，其华美令烂漫的樱花也黯然失色。精美的纹路配饰，传承自天水之国的古老习俗，也寄托着亲人们对她的美好祝愿：青春如庭中樱花，默默积蓄一年的养分，只为一月的花开烂漫。',TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',MainColor='cb25a6FF',}",
  [3002852] = "{id=3002852,NameZh='樱绽余华·弥生',Icon='item_3002850',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000020}},Desc='少女穿上成人仪式的礼服，其华美令烂漫的樱花也黯然失色。精美的纹路配饰，传承自天水之国的古老习俗，也寄托着亲人们对她的美好祝愿：年少时光如春日，万物弥生，天地之间生机盎然。',TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',MainColor='04a9b8FF',}",
  [3002853] = "{id=3002853,NameZh='樱绽余华·夜樱',Icon='item_3002850',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000020}},Desc='少女穿上成人仪式的礼服，其华美令烂漫的樱花也黯然失色。精美的纹路配饰，传承自天水之国的古老习俗，也寄托着亲人们对她的美好祝愿：愿她如夜晚的樱花，虽然无法看出形貌，却难以掩盖她的芬芳。',TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',MainColor='221c19FF',}",
  [3002854] = "{id=3002854,NameZh='花鲤物语系列时装',Icon='item_3002854',Type=501,MaxNum=99,SellPrice=100,AdventureSort=15419,AdventureValue=1,AdventureReward={buffid={62000010}},StorageReward={buffid={82000020}},Condition=8,TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',MainColor='X',}",
  [3002855] = "{id=3002855,NameZh='花鲤物语时装碎片',Icon='item_3002855',Type=61,UseMode=4027,MaxNum=99999,SellPrice=100,Desc='5个花鲤物语时装碎片可以在弗雷硬币商店兑换花鲤物语系列时装哦~',TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',}",
  [3002856] = "{id=3002856,NameZh='花鲤物语时装兑换券',Icon='item_3002856',Type=121,MaxNum=99999,SellPrice=100,ComposeID=4000054,Desc='使用之后可以获得一件对应阁下性别的花鲤物语系列时装哦~',}",
  [3002860] = "{id=3002860,NameZh='元服登鲤',Icon='item_3002840',Type=501,MaxNum=99,SellPrice=100,Desc='当鲤鱼成群结队逆流而上越过瀑布，天水之国便迎来传统节日“鲤鱼日”。这一天人们会举办庆典祈福，祈求孩子们像鲤鱼一样健康、充满活力。',TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',MainColor='17519aFF',}",
  [3002861] = "{id=3002861,NameZh='樱华雏祭',Icon='item_3002850',Type=501,MaxNum=99,SellPrice=100,Desc='樱花烂漫之时，天水之国便迎来传统节日“雏祭”。父母会在家中摆放小人偶，供奉樱花、糕点，以祈求女儿幸福平安。',TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',MainColor='17519aFF',}",
  [3002862] = "{id=3002862,NameZh='鲜衣繁花时装兑换券',Icon='item_3002862',Type=121,MaxNum=99999,SellPrice=100,ComposeID=4000055,Desc='使用之后可以获得一件对应阁下性别的鲜衣繁花系列时装哦~',}",
  [3002863] = "{id=3002863,NameZh='鲜衣繁花系列时装',Icon='item_3002854',Type=501,MaxNum=99,SellPrice=100,AdventureSort=15420,AdventureValue=1,Condition=8,TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',MainColor='17519aFF',}",
  [3002870] = "{id=3002870,NameZh='岭上花鲤·花火',Icon='item_3002870',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='岭上花开，鲤鱼登瀑，这是父母对孩子的期盼。夏夜一家人共赏庆典的烟火，是孩子对家最温暖的回忆。',TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',LoadShowRotate=350,LoadShowPose={0,0.8,0.3},MainColor='d13935FF',}",
  [3002871] = "{id=3002871,NameZh='岭上花鲤·御庭樱',Icon='item_3002870',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='岭上花开，鲤鱼登瀑，这是父母对孩子的期盼。 庭院樱花树下一家人共享天伦，是孩子对家最温暖的回忆。',TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',MainColor='d85276FF',}",
  [3002872] = "{id=3002872,NameZh='岭上花鲤·弥生',Icon='item_3002870',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='岭上花开，鲤鱼登瀑，这是父母对孩子的期盼。 一家人在春日萌发的绿野上漫步，是孩子对家最温暖的回忆。',TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',MainColor='14ac8aFF',}",
  [3002873] = "{id=3002873,NameZh='岭上花鲤·夜樱',Icon='item_3002870',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='岭上花开，鲤鱼登瀑，这是父母对孩子的期盼。 夜晚一家人在樱花的芬芳中闲谈，是孩子对家最温暖的回忆。',TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',MainColor='221c19FF',}",
  [3002874] = "{id=3002874,NameZh='岭上花鲤头饰系列',Icon='item_3002874',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15410,AdventureValue=1,StorageReward={buffid={80012930}},Condition=8,TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',MainColor='X',}",
  [3002875] = "{id=3002875,NameZh='月入春池·花火',Icon='item_3002875',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='池中锦鲤佁然不动，如同一弯新月。花火明灭，照出一双人影。鱼动，少女心亦动。',TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',LoadShowPose={0,0.8,0.2},MainColor='d13935FF',}",
  [3002876] = "{id=3002876,NameZh='月入春池·御庭樱',Icon='item_3002875',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='池中锦鲤佁然不动，如同一弯新月。樱花树下，两人相傍而坐。花瓣落入水池，鱼动，少女心亦动。',TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',MainColor='d85276FF',}",
  [3002877] = "{id=3002877,NameZh='月入春池·弥生',Icon='item_3002875',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='池中锦鲤佁然不动，如同一弯新月。两人漫步新草地，他说：今夜月色真美。人声惊动池中鲤，鱼动，少女心亦动。',TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',MainColor='5cc6acFF',}",
  [3002878] = "{id=3002878,NameZh='月入春池·夜樱',Icon='item_3002875',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='池中锦鲤佁然不动，如同一弯新月。今夜的樱花不知为何格外香甜，甚至吸引了那尾锦鲤。鱼动，少女心亦动。',TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',MainColor='221c19FF',}",
  [3002879] = "{id=3002879,NameZh='月入春池头饰系列',Icon='item_3002879',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15411,AdventureValue=1,StorageReward={buffid={80012920}},Condition=8,TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',MainColor='X',}",
  [3002880] = "{id=3002880,NameZh='花鲤物语头饰兑换券',Icon='item_3002880',Type=61,UseMode=31126,MaxNum=99999,SellPrice=100,Desc='使用之后可以兑换任意一件花鲤物语系列头饰哦~',}",
  [3002881] = "{id=3002881,NameZh='龙女的花冠',Icon='item_3002881',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15412,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='善良又爱幻想的少年在海岸边救下搁浅的鲸鱼，为了报答他的恩情，鲸鱼载着他来到海底的水晶宫。在那里他遇到美丽温柔的龙女，那是他此生难忘的幻梦。',TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',LoadShowRotate=170,LoadShowPose={0,0.7,0},}",
  [3002882] = "{id=3002882,NameZh='缘结团子',Icon='item_3002882',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15413,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='锦鲤成双成对，衔尾结环。相传这种饰品更给佩戴者带来美好的姻缘。',TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',LoadShowRotate=15,LoadShowPose={0,1,0.2},}",
  [3002883] = "{id=3002883,NameZh='纳福锦幡',Icon='item_3002883',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15414,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='在天水之国的习俗中，鲤鱼被认为是一种充满活力的生物，能够为人们带来好运。天水之国的居民会在家门口悬挂鲤鱼旗，期盼家中的孩子们像鲤鱼那样充满活力，健康成长。',TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',LoadShowPose={0,0.3,-0.5},}",
  [3002884] = "{id=3002884,NameZh='画缚鲤',Icon='item_3002884',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15415,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='一尾锦鲤的游魂被束缚在绣球中，在无人时会跃出绣球，在四周游动。',TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',LoadShowRotate=300,LoadShowPose={0,0.3,-0.5},}",
  [3002885] = "{id=3002885,NameZh='鲤观诸世',Icon='item_3002885',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15416,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='鱼眼中的世界，会是什么样子的呢？',TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',LoadShowRotate=340,LoadShowPose={-0.2,0.4,0.6},}",
  [3002886] = "{id=3002886,NameZh='龙女巡行',Icon='item_3002886',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15417,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='天水之国的传说中，海下有一座水晶宫，美丽的龙女是那里的主人，她的美丽令所有海洋生灵倾慕。每当龙女出行，必有万千锦鲤相随，所过之处，金鳞如同樱花的花瓣一样飘落。',TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',LoadShowRotate=180,LoadShowPose={0,0.5,-1},}",
  [3002887] = "{id=3002887,NameZh='花见轮舞',Icon='item_3002887',Type=810,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=15418,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='“他问我愿意跟他走吗，去看看真正的樱花，即使那样会让我一无所有……可我们不知道的事，一无所有的道路上，连花都不会再开……”',TFValidDate='2020-12-14 05:00:00',ValidDate='2020-12-17 05:00:00',LoadShowRotate=160,LoadShowPose={0.3,0.4,-1.5},}",
