  [3002900] = "{id=3002900,NameZh='凛冬桂冠',Icon='item_3002900',Type=830,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9735,AdventureValue=1,StorageReward={buffid={82000240}},Condition=8,Desc='冰雪凝聚的桂冠，只要带上它，便是冬天的主人。月桂叶从桂冠上抖落，化作飘零的冰雪——凛冬将至！',TFValidDate='2020-12-01 05:00:00',ValidDate='2020-12-01 05:00:00',LoadShowRotate=340,LoadShowPose={-0.2,0.1,0.5},}",
  [3002901] = "{id=3002901,NameZh='雪童子[1]',Icon='item_3002901',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9736,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='独居的老爷爷在家门外捡到长着豹耳的可爱婴儿，悉心照料。孩子的到来让老爷爷的生活不再孤单——他或许不会记得，多年前的雪夜，他曾救下一只受伤的雪豹……',TFValidDate='2020-12-01 05:00:00',ValidDate='2020-12-01 05:00:00',LoadShowRotate=345,LoadShowPose={-0.2,0.8,0.3},}",
  [3002902] = "{id=3002902,NameZh='冬灵旅社',Icon='item_3002902',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9737,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='冰霜精灵最喜欢四处游荡玩耍，玩累了就化身成小雪豹，钻进背包，让过路的旅人载他一程。',TFValidDate='2020-12-01 05:00:00',ValidDate='2020-12-01 05:00:00',LoadShowRotate=160,LoadShowPose={0,0.5,-0.2},}",
  [3002903] = "{id=3002903,NameZh='风雪游人',Icon='item_3002903',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9738,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='风雪中，旅行者裹紧了母亲为他织的围巾，温暖一如全家人围绕着火炉。',TFValidDate='2020-12-01 05:00:00',ValidDate='2020-12-01 05:00:00',LoadShowPose={-0.2,0.7,0.3},}",
  [3002904] = "{id=3002904,NameZh='冰原猎手的尾巴',Icon='item_3002904',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9739,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='冰原上，雪豹搜寻着自己的猎物，脚步轻巧，静默无声，尾巴轻轻摆动，拂去雪面上的掌印。',TFValidDate='2020-12-01 05:00:00',ValidDate='2020-12-01 05:00:00',LoadShowRotate=80,LoadShowPose={0.6,0.3,0},}",
  [3002905] = "{id=3002905,NameZh='冬日小憩[1]',Icon='item_3002905',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9740,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='冬日的阳光洒在身上，暖洋洋的好舒服！这么好的天气，冰霜精灵决定睡个午觉吧！咕噜咕噜~',TFValidDate='2020-12-01 05:00:00',ValidDate='2020-12-01 05:00:00',LoadShowRotate=350,LoadShowPose={0,0.7,0.3},}",
  [3002906] = "{id=3002906,NameZh='冰霜精灵',Icon='item_3002906',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9064,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='初到米德加尔特的冰霜精灵对人类世界的一切充满好奇。于是他决定化身成人类的模样好好游览一番——不过他似乎忘记要藏起自己的胡须。',TFValidDate='2020-12-01 05:00:00',ValidDate='2020-12-01 05:00:00',LoadShowRotate=340,LoadShowPose={-0.3,0.5,1},}",
  [3002930] = "{id=3002930,NameZh='小小圣诞信使',Icon='item_3002930',Type=840,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10303,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='滑雪的小企鹅，滑稽的步伐里隐藏了它小小的梦想：要为全天下的孩子都送上圣诞礼物。',TFValidDate='2020-11-24 05:00:00',ValidDate='2020-12-01 05:00:00',LoadShowPose={0,0.1,0},}",
