  [3002940] = "{id=3002940,NameZh='神之锻造盒-咒言护手',Icon='item_6630',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='为「魔语者」系列职业量身定制的礼包，打开之后可以获得职业专属武器「咒言护手」x1，以下材料随机获得一种：「闪耀圣水」x1、「小红帽」x1、「破斗蓬的碎片」x1、「龙鳞」x1、「黯魂粉尘」x15、「安眠木」x50',Delete=3002940}",
  [3002950] = "{id=3002950,NameZh='小木锤',Icon='item_3001889',Type=30,UseMode=31043,MaxNum=99999,SellPrice=100,Desc='虽然是普通木制小锤，但是却能发挥巨大威力，真是惊人！“喂！这个不可以用来打人！”',ExistTimeType=2,ExistTime='2021-01-01 05:00:00',Delete=3002950}",
  [3002951] = "{id=3002951,NameZh='雪国伴手礼',Icon='item_3945',Type=30,MaxNum=99999,SellPrice=100,Desc='雪国常见的伴手礼，里面装满了雪国的特产。使用后必定获得「小木锤」x2；可能会获得「光洁的符文石」x1，「闪耀的符文石」x1，「祈祷晶片包」x2，「尘封的符文袋·Ⅱ」x1，「神谕之晶」x2，「玛斯黛拉种子」x1。',Delete=3002951}",
  [3002952] = "{id=3002952,NameZh='薄雪宝箱',Icon='item_3871',Type=30,MaxNum=99999,SellPrice=100,Desc='冰冰凉凉的小宝箱，里面装满了各种各样的宝贝。使用后会获得「B格猫福利券·宴」x5，「萃光结晶」x2，「尘封的符文袋·Ⅰ」x4，「小木锤」x1。',Delete=3002952}",
  [3002953] = "{id=3002953,NameZh='寒雪宝箱',Icon='item_3864',Type=30,MaxNum=99999,SellPrice=100,Desc='寒雪包裹着的小宝箱，打开后有额外的惊喜。使用后会获得「B格猫福利券·Ⅰ」x4，「坠星陨铁」x2，「神谕之晶」x4，「小木锤」x1。',Delete=3002953}",
  [3002954] = "{id=3002954,NameZh='冻雪宝箱',Icon='item_3866',Type=30,MaxNum=99999,SellPrice=100,Desc='被冻住的小宝箱，不要怀疑，里面一定有你想要的！使用后会获得「B格猫福利券·Ⅱ」x4，「光洁的符文石」x2，「神秘箱子7.0」x3，「小木锤」x1。',Delete=3002954}",
  [3002955] = "{id=3002955,NameZh='冰雪的馈赠',Icon='item_700136',Type=30,MaxNum=99999,SellPrice=100,Delete=3002955}",
  [3002956] = "{id=3002956,NameZh='璀璨冰晶礼盒',Icon='item_3002113',Type=30,MaxNum=99999,SellPrice=100,Desc='装满了宝贝的小礼盒，不要怀疑，打开它！使用后有50%概率获得「小木锤」x1；必定获得10000zeny；可能会获得「礼盒纸」x50，「冰之心」x50，「冰块之角」x50，「圣诞花环」x5，「圣诞袜子」x1，「冰雪之心」x1，「冰之粉末」x1。',Delete=3002956}",
  [3002957] = "{id=3002957,NameZh='圣夜纪念礼盒',Icon='item_3900',Type=30,MaxNum=99999,SellPrice=100,Desc='圣夜时期可能会出现的小礼盒，一定要拿到哦~使用后会获得「神谕之尘」x4，「神谕之晶」x4，「祈祷晶片包」x2，「金质勋章」x2，「坠星陨铁」x2。',Delete=3002957}",
  [3002958] = "{id=3002958,NameZh='芙洛丝的谢礼',Icon='item_3711',Type=30,MaxNum=99999,SellPrice=100,Desc='冰雪女王芙洛丝为冒险者准备的礼物哦~「料理兑换券」x5，「玛斯黛拉种子」x1，「九界原石」x5，「高原坚木」x200，「精研型job药水」x10。',Delete=3002958}",
  [3002959] = "{id=3002959,NameZh='K上校的圣诞礼物',Icon='item_3878',Type=30,MaxNum=99999,SellPrice=100,Desc='K上校专门为冒险者准备的圣诞礼物~「料理兑换券」x5，「KFC吃鸡餐盒」x10，「九界原石」x5，「高原坚木」x200，「精研型job药水」x10。',Delete=3002959}",
  [3002960] = "{id=3002960,NameZh='雪国硬币',Icon='item_700001',Type=61,UseMode=31124,MaxNum=99999,SellPrice=100,Desc='被铸造成雪花样式的小硬币，是雪国特有的钱币，要妥善运用哦~',ExistTimeType=2,ExistTime='2021-01-15 05:00:00',Delete=3002960}",
  [3002970] = "{id=3002970,NameZh='刹那永恒·月长石',Icon='item_3002970',Type=501,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={82000060}},Desc='“这是冰雪与宝石的国度，狂风止息之地，连时间都凝结成冰的永恒冻土……”那人端坐在王座上，月长石的光华映照出冷峻的面容。“而我，是这片土地的主人，你可以叫我——冰川之主！”',MainColor='3772f0FF',}",
  [3002971] = "{id=3002971,NameZh='刹那永恒·虎睛石',Icon='item_3002970',Type=501,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={82000060}},Desc='“这是冰雪与宝石的国度，狂风止息之地，连时间都凝结成冰的永恒冻土……”虎睛石闪烁着幽光，一如那人的炯炯双目，目光刺穿一切。“而我，是这片土地的主人，你可以叫我——冰川之主！”',MainColor='c76b08FF',}",
  [3002972] = "{id=3002972,NameZh='刹那永恒·紫水晶',Icon='item_3002970',Type=501,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={82000060}},Desc='“这是冰雪与宝石的国度，狂风止息之地，连时间都凝结成冰的永恒冻土……”那人端坐在王座上，紫水晶的光芒为他的面容披上神秘的幔纱。“而我，是这片土地的主人，你可以叫我——冰川之主！”',MainColor='8c58edFF',}",
  [3002973] = "{id=3002973,NameZh='刹那永恒·红宝石',Icon='item_3002970',Type=501,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={82000060}},Desc='“这是冰雪与宝石的国度，狂风止息之地，连时间都凝结成冰的永恒冻土……”红宝石的光芒如火，映着他如冰的面孔，令人难辨悲喜。“而我，是这片土地的主人，你可以叫我——冰川之主！”',MainColor='c53a07FF',}",
  [3002980] = "{id=3002980,NameZh='万华灵镜·月长石',Icon='item_3002980',Type=501,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={82000060}},Desc='光芒照射在月长石上，绽放的光华将空荡的大厅映成蔚蓝色。“看，漂亮吧~这是大海的颜色！”少女问冰川之主，“你——见过大海吗？”“没见过，但也没什么大不了的……”冰川之主语气淡然，面无表情。只是那晚，他做了一个关于大海和鲸鱼的美梦。',MainColor='3772f0FF',}",
  [3002981] = "{id=3002981,NameZh='万华灵镜·虎睛石',Icon='item_3002980',Type=501,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={82000060}},Desc='虎睛石在少女掌心流转，幽光明灭。“真漂亮~真的跟虎王的眼睛一模一样！”少女问冰川之主，“你知道虎王吗！”“不知道，但也没什么大不了的……”冰川之主语气淡然，面无表情。只是那晚的梦里，他见到了一只戴着帽子、叼着烟斗的大猫。',MainColor='c76b08FF',}",
  [3002982] = "{id=3002982,NameZh='万华灵镜·紫水晶',Icon='item_3002980',Type=501,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={82000060}},Desc='光芒照射在紫水晶上，漫射的光华在大厅的墙上留下点点光瓣。“哇，好漂亮~就像天津町的樱花一样！”少女问冰川之主，“你——见过樱花吗？”“没见过，应该跟雪花差不多吧……”冰川之主语气淡然，面无表情。只是那晚，他的梦中飘起漫天落花。',MainColor='8c58edFF',}",
  [3002983] = "{id=3002983,NameZh='万华灵镜·红宝石',Icon='item_3002980',Type=501,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={82000060}},Desc='光芒照射在红宝石上，绽放出璀璨的红色光华。“真漂亮，就像一团跳动的火焰！”少女问冰川之主，“你——见过火焰吗？”“没见过，但也没什么大不了的……”冰川之主语气淡然，面无表情。只是在那之后，他难得的对什么是“炎热”感到好奇。',MainColor='c53a07FF',}",
