  [3002990] = "{id=3002990,NameZh='宝石男爵',Icon='item_3002990',Type=501,MaxNum=99,SellPrice=100,Desc='怪盗宝石男爵的目标是将世上所有的珍奇宝石收入囊中，为了得到传说中的宝石，他来到永恒冻土——在这里，他将遇到令他此生难忘的魔女。',MainColor='5cc6acFF',}",
  [3002991] = "{id=3002991,NameZh='冰雪魔女',Icon='item_3002991',Type=501,MaxNum=99,SellPrice=100,Desc='冰雪魔女立志成为最强大的魔法师，为了了解冰系魔法的真义，她来到永恒冻土——在这里，她将遇到那个令她此生难忘的怪人。',MainColor='5cc6acFF',}",
  [3002992] = "{id=3002992,NameZh='雪域奇幻夜时装兑换券',Icon='item_3002992',Type=121,MaxNum=99999,SellPrice=100,ComposeID=4000058,Desc='使用之后可以获得一件对应阁下性别的雪域奇幻夜系列时装哦~',}",
