  [3003000] = "{id=3003000,NameZh='冰脉主宰·月长石',Icon='item_3003000',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='当戴上这顶王冠，你的命运将与永恒冻土的万年寒冰融为一体。你如月长石般的理性之光将为这片土地带来智慧与启迪。',MainColor='4ca3f6FF',}",
  [3003001] = "{id=3003001,NameZh='冰脉主宰·虎晴石',Icon='item_3003000',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='当戴上这顶王冠，你的命运将与永恒冻土的万年寒冰融为一体。你如虎睛石般的勇气光辉将为这片土地带来胜利与荣耀。',MainColor='f8cd56FF',}",
  [3003002] = "{id=3003002,NameZh='冰脉主宰·紫水晶',Icon='item_3003000',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='当戴上这顶王冠，你的命运将与永恒冻土的万年寒冰融为一体。你如紫水晶般的正义之光将为这片土地带来公正与和平。',MainColor='a70c40FF',}",
  [3003003] = "{id=3003003,NameZh='冰脉主宰·青金石',Icon='item_3003000',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='当戴上这顶王冠，你的命运将与永恒冻土的万年寒冰融为一体。你如青金石般的坚定意志将感染这片土地上的每个生灵。',MainColor='22d6d0FF',}",
  [3003004] = "{id=3003004,NameZh='冰脉主宰头饰系列',Icon='item_3003004',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15426,AdventureValue=1,StorageReward={buffid={80012930}},Condition=8,MainColor='X',}",
  [3003005] = "{id=3003005,NameZh='冰晶女皇·月长石',Icon='item_3003005',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='当戴上这顶王冠，你就是这片永恒冻土的女皇，此地的生灵都是你的子民，受你庇佑。“以女皇之名祈愿，璀璨的月长石啊，请将智慧与理性赐予我的子民！”',MainColor='4ca3f6FF',}",
  [3003006] = "{id=3003006,NameZh='冰晶女皇·虎睛石',Icon='item_3003005',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='当戴上这顶王冠，你就是这片永恒冻土的女皇，此地的生灵都是你的子民，受你庇佑。“以女皇之名祈愿，璀璨的虎睛石啊，请将勇气与永不言弃的意志赐予我的子民！”',MainColor='f8cd56FF',}",
  [3003007] = "{id=3003007,NameZh='冰晶女皇·紫水晶',Icon='item_3003005',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='当戴上这顶王冠，你就是这片永恒冻土的女皇，此地的生灵都是你的子民，受你庇佑。“以女皇之名祈愿，璀璨的紫水晶啊，请将健康与内心的平静赐予我的子民！”',MainColor='a70c40FF',}",
  [3003008] = "{id=3003008,NameZh='冰晶女皇·青金石',Icon='item_3003005',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='当戴上这顶王冠，你就是这片永恒冻土的女皇，此地的生灵都是你的子民，受你庇佑。“以女皇之名祈愿，璀璨的青金石啊，请将甜美的梦境赐予我的子民！”',MainColor='22d6d0FF',}",
  [3003009] = "{id=3003009,NameZh='冰晶女皇头饰系列',Icon='item_3003009',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15427,AdventureValue=1,StorageReward={buffid={80012920}},Condition=8,MainColor='X',}",
  [3003010] = "{id=3003010,NameZh='璨晶永恒头饰兑换券',Icon='item_3003010',Type=61,UseMode=31140,MaxNum=99999,SellPrice=100,Desc='使用之后可以兑换任意一件璨晶永恒系列头饰哦~',}",
  [3003011] = "{id=3003011,NameZh='水晶波利帽',Icon='item_3003011',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15428,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='神秘的永恒冻土生活着许多神奇的生物，居住在这里的水晶波利全身结晶化，虽然不再Q弹，但是闪闪惹人爱。',}",
  [3003012] = "{id=3003012,NameZh='永恒之吻',Icon='item_3003012',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15429,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='生长在永恒冻土的神奇植物，花语是“纯洁的爱恋”。但它释放出的凛冽寒气甚至能够冻结灵魂——所以不要为了浪漫而将它叼在嘴里……（糟了，嘴巴失去知觉了！）',LoadShowRotate=340,LoadShowPose={-0.2,0.5,0.8},}",
  [3003013] = "{id=3003013,NameZh='冰川统御',Icon='item_3003013',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15430,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='身处绝巅，万千冰川尽在脚下。',LoadShowRotate=170,LoadShowPose={0.3,0.8,-1},}",
  [3003014] = "{id=3003014,NameZh='魂晶小丑',Icon='item_3003014',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15431,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='独居在空荡的宫殿中的王者，苦寂难耐的他创造了魂晶小丑“布奇”，以永不融化的冰雪为躯体，用纯净无暇的灵魂水晶赋予生命。在毫无生气的璨晶堡垒中，王者与魔偶相伴，度过数以万年计的漫长岁月……',LoadShowRotate=340,LoadShowPose={0,0,0},}",
  [3003015] = "{id=3003015,NameZh='魔晶勘探者',Icon='item_3003015',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15432,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='冒险者们深入永恒冻土，寻找传说中具有神奇力量的魔法水晶，这副护目镜可以帮助他们辨认出宝石中的稀世珍品——戴上它之后，感觉天更蓝了！',LoadShowPose={-0.3,0.4,0.8},}",
  [3003016] = "{id=3003016,NameZh='十方风凝',Icon='item_3003016',Type=810,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=15433,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='极北之地、只存在于传说中的永恒冻土，这是世上最寒冷的地方，一切都会在此冰结，连呼啸的凜风也不例外。',TFValidDate='2029-12-14 05:00:00',ValidDate='2029-12-17 05:00:00',LoadShowRotate=170,LoadShowPose={0.3,0.7,-1.2},}",
  [3003020] = "{id=3003020,NameZh='三瓣嘴神',Icon='item_3003020',Type=840,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10331,AdventureValue=1,StorageReward={buffid={81000220}},Condition=8,Desc='带有长耳和白绒绒皮毛的小神灵，因为过于可爱尤其受到孩子们的欢迎。但它似乎对自己裂成三瓣的嘴和巨大的门牙有些自卑……',Feature=1,TFValidDate='2023-11-03 05:00:00',ValidDate='2023-11-10 05:00:00',LoadShowPose={0,-0.25,0},}",
  [3003030] = "{id=3003030,NameZh='异世界·苹果头饰',Icon='item_3003030',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10300,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='以前有一位名射手把苹果放在儿子的头上，一箭射中而闻名的苹果。（据说这是来自异世界的头饰）',Feature=1,TFValidDate='2020-12-30 05:00:00',ValidDate='2021-01-06 05:00:00',}",
