  [3003060] = "{id=3003060,NameZh='轻食主义',Icon='item_3003060',Type=850,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9741,AdventureValue=1,StorageReward={buffid={82000240}},Condition=8,Desc='要多吃绿色食品才能保持健康哦~风歌牧场的牧草可是原生态无污染的——快停下！那是给奶牛吃的！',TFValidDate='2021-01-01 05:00:00',ValidDate='2021-01-01 05:00:00',LoadShowRotate=340,LoadShowPose={0,0.3,0.2},}",
  [3003061] = "{id=3003061,NameZh='风歌牧犬',Icon='item_3003061',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9742,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='风歌牧场的幼犬从小就要接受牧牛的训练，不过它太小了，会被牛群遮挡住视线，只能爬到热气球上啦！',TFValidDate='2021-01-01 05:00:00',ValidDate='2021-01-01 05:00:00',LoadShowPose={0,0,0},}",
  [3003062] = "{id=3003062,NameZh='哞哞博士[1]',Icon='item_3003062',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9743,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='风歌牧场的兽医哞哞博士可是奶牛饲养专家哦！最喜欢扮成奶牛近距离观察它们的习性。',TFValidDate='2021-01-01 05:00:00',ValidDate='2021-01-01 05:00:00',LoadShowRotate=340,LoadShowPose={0,0.7,0},}",
  [3003063] = "{id=3003063,NameZh='牧语童梦',Icon='item_3003063',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9744,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='“老爹，我长大了要成为一名游侠！”\n“哈哈，用稻草弓的游侠吗？”\n“别小看人！我一定会变强的！”',TFValidDate='2021-01-01 05:00:00',ValidDate='2021-01-01 05:00:00',LoadShowRotate=180,LoadShowPose={0,0.4,-0.5},}",
  [3003064] = "{id=3003064,NameZh='坚蛋堡垒[1]',Icon='item_3003064',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9745,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='母鸡决定在一个“绝对安全”的地方修筑鸡窝，这样就能保护好自己的蛋——看来看去，似乎只有冒险者头上最安全呢！“要负起守护鸡蛋的责任哦~”',TFValidDate='2021-01-01 05:00:00',ValidDate='2021-01-01 05:00:00',LoadShowPose={0,0.3,0},}",
  [3003065] = "{id=3003065,NameZh='乳味学霸',Icon='item_3003065',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9746,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='风歌牧场主人的儿子是个学霸，让隔壁地主羡慕不已。\n“多喝牛奶会变聪明哦~”',TFValidDate='2021-01-01 05:00:00',ValidDate='2021-01-01 05:00:00',LoadShowRotate=345,LoadShowPose={0,0.35,0},}",
  [3003066] = "{id=3003066,NameZh='天降甘露',Icon='item_3003066',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9065,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='牧场主人为蜜蜂们修建了新蜂巢，蜜蜂为了报答将珍藏的蜂蜜送给他——诶，等等！我的头发不是容器啊喂！',TFValidDate='2021-01-01 05:00:00',ValidDate='2021-01-01 05:00:00',}",
  [3003070] = "{id=3003070,NameZh='离线战斗体验卡',Icon='item_163',Type=41,MaxNum=99999,SellPrice=100,Desc='使用后可获得7天的离线战斗使用资格，天数可以累加，剩余天数不足并不会影响已经开启的离线战斗。',NoStorage=5,ExistTimeType=2,ExistTime='2020-10-21 05:00:00',}",
  [3003071] = "{id=3003071,NameZh='纯真的小恶魔帽[1]',Icon='item_3032500',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10321,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='依照小恶魔的样子改良而成，与原版相比，更多了一份无瑕的纯真。',Feature=1,}",
  [3003080] = "{id=3003080,NameZh='祈祷晶片自选包',Icon='item_3720',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='使用之后可以自行选择获得「攻击晶片」x1、「防御晶片」x1、「元素晶片」x1中的一种。可以使用晶片在公会中提升【女神祝福】等级。',}",
  [3003081] = "{id=3003081,NameZh='女武神的善意礼盒',Icon='item_3855',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='蕴含了女武神的善意和祝福的礼盒，使用之后可以获得「金质勋章」x1、「来自女武神的馈赠」x1',}",
  [3003082] = "{id=3003082,NameZh='初心者成长礼盒',Icon='item_3002711',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='专门为初心者定制的极具性价比的礼盒，使用之后可以获得限定时装「皇家庆典时装兑换券」x1，还可以自选一套物理系或是法术系的推荐头饰礼包！（推荐头饰包括头饰、脸部、嘴部、背部、尾部各1个，均为付费类头饰）',}",
  [3003083] = "{id=3003083,NameZh='自选头饰礼包',Icon='item_3712',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='使用之后可以自选一套物理系或是法术系的推荐头饰礼包！（推荐头饰包括头饰、脸部、嘴部、背部、尾部各1个，均为付费类头饰）',}",
  [3003084] = "{id=3003084,NameZh='物理系头饰礼包',Icon='item_3682',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='为物理系职业量身定做的头饰礼包，打开可以获得「安毕斯假面[1]」x1、「琴语乐目」x1、「武魂信仰」x1、「守护爱的女神」x1、「妖娆的尾」x1。',}",
  [3003085] = "{id=3003085,NameZh='法术系头饰礼包',Icon='item_3681',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='为法术系职业量身定做的头饰礼包，打开可以获得「金字塔的谜题[1]」x1、「琴语乐目」x1、「命运卡牌」x1、「守护爱的女神」x1、「幸福的小鸟」x1。',}",
  [3003087] = "{id=3003087,NameZh='圣徒装备礼盒',Icon='item_6630',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='从远古时期流传下来的礼盒 ，使用之后可以获得一整套圣徒装备，包括可以自选一把武器的「圣徒武器兑换券」x1、「光明圣徒之铠」x1、「光明圣徒之盾」x1、「光明圣徒披风」x1、「光明圣徒战靴」x1、「圣徒之戒」x1、「圣徒项链」x1。虽然在属性上，圣徒装备并不是最优的选择，但是它所提供的Base、Job经验加成却是冒险者培养多职业的最佳选择！',}",
  [3003088] = "{id=3003088,NameZh='圣徒武器兑换券',Icon='item_6089',Type=30,Quality=3,UseMode=31139,MaxNum=99999,SellPrice=100,Desc='使用之后可以在以下圣徒武器中自选一把：「圣徒长剑[1]」x1、「圣徒之矛[1]」x1、「圣徒之杖[1]」x1、「圣徒之锤[1]」x1、「圣徒之弓[1]」x1、「圣徒短剑[1]」x1、「圣徒拳刃[1]」x1、「圣徒拳套[1]」x1、「圣徒巨斧[1]」x1、「圣徒鞭子[1]」x1、「圣徒之琴[1]」x1、「圣徒魔书[1]」x1、「圣徒狐尾草[1]」x1、「圣徒风魔轮[1]」x1、「圣徒手枪[1]」x1、「圣徒步枪[1]」x1',}",
  [3003089] = "{id=3003089,NameZh='月辉武器外观兑换券',Icon='item_6082',Type=61,Quality=4,UseMode=31141,MaxNum=99999,SellPrice=100,Desc='祝贺你，成为被命运选中的冒险家，请兑换自己想要的武器外观吧！',Feature=1,}",
  [3003100] = "{id=3003100,NameZh='惠顾制服',Icon='item_3003100',Type=501,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={82000060}},Desc='罗森便利制服的男员工款。搭载了围裙，藏有速速魔力的外套。即使气候恶劣，也能让你把冰点心热便当以最佳贮藏温度送到食品柜。',Feature=1,TFValidDate='2021-01-04 05:00:00',ValidDate='2021-01-11 05:00:00',Delete=3003100}",
  [3003101] = "{id=3003101,NameZh='光临店服',Icon='item_3003101',Type=501,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={82000060}},Desc='罗森便利制服的女员工款。含棉率96%，员工穿着舒适，视觉上也给了顾客放松的感受。但是，短裙摸起来很像冰皮月亮蛋糕这点，不知是否也属于设计的一环……',Feature=1,TFValidDate='2021-01-04 05:00:00',ValidDate='2021-01-11 05:00:00',Delete=3003101}",
  [3003102] = "{id=3003102,NameZh='罗森便利制服兑换券',Icon='item_3003102',Type=121,Quality=3,MaxNum=99999,SellPrice=100,ComposeID=4000063,Desc='使用后可以获得1件符合阁下性别的“罗森便利制服”系列时装。最好单独收纳在卡包里，免得错当作驿站会员卡刷掉！',Feature=1,TFValidDate='2021-01-04 05:00:00',ValidDate='2021-01-11 05:00:00',Delete=3003102}",
  [3003103] = "{id=3003103,NameZh='罗森便利制服',Icon='item_3003103',Type=501,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10330,AdventureValue=1,StorageReward={buffid={82000060}},Condition=8,Desc='罗森店员的服装。美观性和实用性兼备。既能让你吸引客人，也能帮你去污挡雨。它还有一个隐藏功能：失眠时穿上它，就能让你收获温暖的拥抱。',Feature=1,TFValidDate='2021-01-04 05:00:00',ValidDate='2021-01-11 05:00:00',Delete=3003103}",
  [3003104] = "{id=3003104,NameZh='亿亿酱发饰',Icon='item_3003104',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10327,AdventureValue=1,StorageReward={buffid={80013080}},Condition=8,Desc='蓝白条纹的蝴蝶结，亿亿酱最钟意的饰品之一。它可以整理慵懒的发丝，让亿亿酱每天都能保持快乐的笑容。',Feature=1,TFValidDate='2021-01-04 05:00:00',ValidDate='2021-01-11 05:00:00',Delete=3003104}",
  [3003105] = "{id=3003105,NameZh='趴趴亿亿酱',Icon='item_3003105',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10328,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='“冒险者的脑壳好软呐。”休班时间的亿亿酱解锁了摸鱼补觉的新地点。\n直到她的手摁深了1厘米。\n“好多手印！难不成这里是公共场所……？”她的手打起无聊的圈圈。趴过这里的不止自己一个，看来不能写下“到此一游”了。',Feature=1,TFValidDate='2021-01-04 05:00:00',ValidDate='2021-01-11 05:00:00',Delete=3003105}",
  [3003106] = "{id=3003106,NameZh='天波头套',Icon='item_3003106',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10329,AdventureValue=1,StorageReward={buffid={80012810}},Condition=8,Desc='天使波利为其形象代言的毛茸头套。适宜秋冬换季，以及与孙辈、宠物、男朋友逛街时穿戴。',Feature=1,TFValidDate='2021-01-04 05:00:00',ValidDate='2021-01-11 05:00:00',}",
  [3003110] = "{id=3003110,NameZh='圣诞老人的礼物',Icon='item_3620',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='圣诞老人在这个冬天特意为冒险者准备的礼物，打开必定获得「小木锤」x1、「B格猫福利券·宴」x30，以下奖励随机获得一种：「神谕之尘」x10、「神谕之晶」x10、「祈祷晶片包」x5、「弗雷硬币」x1、「天火碎片·锋锐型」x1',GetLimit={limit={[999]={1,0}},source={22},type=4},Feature=1,Delete=3003110}",
  [3003120] = "{id=3003120,NameZh='康纳尔公爵',Icon='item_3003120',Type=501,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000010}},Desc='如果有人问，王宫之中最受欢迎的年轻贵族是谁？那么99%的人都会说，是康纳尔公爵吧，他不仅英俊潇洒才华横溢，还拥有一颗金子般纯净的心。',}",
  [3003121] = "{id=3003121,NameZh='午夜的圆舞曲',Icon='item_3003121',Type=501,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000010}},Desc='王宫里举行了一场盛大的舞会，一位带着面具的年轻少女凭借优雅的舞姿，赢取了在场所有男士的心。可为什么，午夜钟声响起，少女就慌忙地逃离呢？',}",
  [3003122] = "{id=3003122,NameZh='紫蔷薇王朝系列时装',Icon='item_3003122',Type=501,MaxNum=99,SellPrice=100,AdventureSort=10325,AdventureValue=1,AdventureReward={buffid={62000010}},StorageReward={buffid={82000010}},Condition=8,}",
  [3003123] = "{id=3003123,NameZh='紫蔷薇王朝时装兑换券',Icon='item_3003123',Type=61,Quality=3,MaxNum=9999,SellPrice=100,ComposeID=4000059,Desc='使用之后可以获得1件符合阁下性别的紫蔷薇王朝系列时装',}",
  [3003130] = "{id=3003130,NameZh='粉黛公子',Icon='item_3003130',Type=800,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80012970}},Desc='没人知道这个粉头发的高贵公子是什么出身，他总是用帷幔遮住自己线条分明的脸。如果说康纳尔公爵是明面上的掌权者，那么他就是王国地下的主人。',}",
  [3003131] = "{id=3003131,NameZh='金丝雀佳人',Icon='item_3003131',Type=800,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80012970}},Desc='贵族小姐嘉美莉是王国里出名的美人，也有一个谣言，说她受到了女巫的诅咒，每到午夜十二点会变成一只金丝雀。',}",
  [3003132] = "{id=3003132,NameZh='富丽堂皇系列头饰',Icon='item_3003132',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10323,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,}",
  [3003133] = "{id=3003133,NameZh='富丽堂皇头饰兑换券',Icon='item_3003133',Type=61,Quality=3,MaxNum=9999,SellPrice=100,ComposeID=4000106,Desc='使用之后可以获得1件符合阁下性别的富丽堂皇系列头饰',}",
  [3003134] = "{id=3003134,NameZh='2021的第一个礼盒',Icon='item_3001435',Type=30,Quality=2,MaxNum=9999,SellPrice=100,Desc='不射猎为大家准备的2021年的第一个礼盒，虽然2020年冒险者们都面临了很多挑战，但是在新的一年，大家一定会向着更美好的方向大步前进的！打开之后可以获得「好运币」x20、「闪耀的符文石·星」x2、「闪耀的符文石」x2、「精致的维修碎片」x1、「神谕之尘」x20、「神谕之晶」x20、「萃光结晶」x5',Feature=1,Delete=3003134}",
  [3003135] = "{id=3003135,NameZh='2021',Icon='item_3002298',Type=10,SellPrice=100,Desc='带着祝福，朝着更美好的方向，大步前行！',Feature=1,Delete=3003135}",
  [3003136] = "{id=3003136,NameZh='皇家庆典头像框',Icon='item_3003136',Type=41,MaxNum=1,SellPrice=100,Desc='皇家庆典专属头像框。',NoSale=1,NoStorage=5,Feature=1,Delete=3003136}",
  [3003137] = "{id=3003137,NameZh='皇家庆典荣耀宝箱',Icon='item_3838',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='只在B格猫皇家庆典中产出的宝箱，使用之后必定获得「弗雷硬币」x1~10，以下道具必定获得一种：「B格猫福利券·Ⅰ」x30、「B格猫福利券·宴」x30，有概率获赠以下道具中的一种：「精炼+8武器券」x1、「精炼+8副手券」x1、「精炼+8盔甲券」x1、「精炼+8披风券」x1、「精炼+8鞋子券」x1，还有额外概率获得「2021.02宴的馈赠」x1、「2021.02头饰赠礼」x1。在第3次开启该礼包时，100%额外获赠「精炼+15头饰券」!',GetLimit={limit={[999]={1,0}},source={22},type=4},Feature=1,Delete=3003137}",
  [3003138] = "{id=3003138,NameZh='精炼+15头饰券',Icon='item_3032040',Type=41,MaxNum=99999,SellPrice=100,Desc='这个道具包含了B格猫星人对精炼的终极理解，使用之后可以将精炼等级小于15的不可交易的头饰（包括头部、背部、嘴部、尾部、脸部）精炼至15！',ItemTarget={type=4},ExistTimeType=2,ExistTime='2021-05-01 05:00:00',Feature=1,Delete=3003138}",
  [3003139] = "{id=3003139,NameZh='2021.02宴的馈赠',Icon='item_3002110',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='使用之后获得一整套2021.02幻想创造器·宴中的最新外观，需要在当期活动开启后才可使用。',Feature=1,Delete=3003139}",
  [3003140] = "{id=3003140,NameZh='2021.02头饰赠礼',Icon='item_3002111',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='使用之后获得一整套2021.02幻想创造器·Ⅰ中的头饰，需要在当期活动开启后才可使用。',Feature=1,Delete=3003140}",
  [3003141] = "{id=3003141,NameZh='皇家庆典宠物礼盒',Icon='item_49536',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='只在B格猫皇家庆典中产出的宝箱，打开可以获得1个随机2星及以上品质的宠物蛋（联动宠物不包含在内）。',Feature=1,Delete=3003141}",
  [3003142] = "{id=3003142,NameZh='皇家庆典图纸礼盒',Icon='item_49537',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='只在B格猫皇家庆典中产出的宝箱，打开可以获得1张绝版图纸。',Feature=1,Delete=3003142}",
  [3003143] = "{id=3003143,NameZh='皇家庆典Mini解锁卡册',Icon='item_3883',Type=41,MaxNum=99999,SellPrice=100,Desc='B格猫星人的最新科技，使用之后可以解锁一张未解锁的Mini卡片，由于研究还没到位，因此只能解锁，并不能获得对应卡片。如果符合条件的所有卡片均已解锁，那么将可以获得「冒险家硬币」x30。',Feature=1,Delete=3003143}",
  [3003150] = "{id=3003150,NameZh='丰愿春盘[1]',Icon='item_3003150',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9747,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='饺子香， 金穗摇。层叠的发饰祈愿着丰收。“来年也望大家吃顿富足的年夜饭！”牛灵在此之中寄予了祝福的魔力。',TFValidDate='2021-02-01 05:00:00',ValidDate='2021-02-01 05:00:00',}",
  [3003151] = "{id=3003151,NameZh='年兽朱面',Icon='item_3003151',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9748,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='朱色染料在眉心、脸颊、眼角点画面纹，模仿出鬼齿模样。传说这妖娆的妆容，具有吓退神话中“年兽”的奇效。',TFValidDate='2021-02-01 05:00:00',ValidDate='2021-02-01 05:00:00',LoadShowRotate=340,LoadShowPose={-0.3,0.4,0.8},}",
  [3003152] = "{id=3003152,NameZh='青牛铜火',Icon='item_3003152',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9749,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='对各位冒险者来说，旅行和美食是两大开心事。牛灵创造性地结合两者，做成了这把能随时涮牛肉的仪杖。“新年吉祥，胃里暖洋！饿了的话，就来涮鲜牛肉吧！”',TFValidDate='2021-02-01 05:00:00',ValidDate='2021-02-01 05:00:00',LoadShowPose={0,0.5,-0.5},}",
  [3003153] = "{id=3003153,NameZh='暖暖内含春',Icon='item_3003153',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9750,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='脆而多汁，绵软丰嫩，使人不忍松口。想尝尝是什么馅儿吗？戴上它吧，让舌尖融入春的味道。',TFValidDate='2021-02-01 05:00:00',ValidDate='2021-02-01 05:00:00',LoadShowPose={-0.3,0.65,0.7},}",
  [3003154] = "{id=3003154,NameZh='铃尾红符',Icon='item_3003154',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9751,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='系以牛灵铃铛和辟邪的红纸，你便能像牛尾赶虫子一样，将去年的坏运气一扫而光。',TFValidDate='2021-02-01 05:00:00',ValidDate='2021-02-01 05:00:00',LoadShowPose={0,0.5,0.8},}",
  [3003155] = "{id=3003155,NameZh='祥云蒸饺',Icon='item_3003155',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9752,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='香气缭绕，悄悄然地卷成祥云。蒸笼盖下，荷叶片上，化成饺子的牛灵呼呼酣睡，耕耘了一场团圆的梦。',TFValidDate='2021-02-01 05:00:00',ValidDate='2021-02-01 05:00:00',LoadShowPose={0,0.5,-0.5},}",
  [3003156] = "{id=3003156,NameZh='辞旧礼炮',Icon='item_3003156',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9067,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='牛灵勤恳地将鞭炮响声送到洛阳的家家户户。但兜来转去，小小的它还是回到了冒险者身边。“新的一年我会伴你左右。”鞭炮便是牛灵的庇佑。',TFValidDate='2021-02-01 05:00:00',ValidDate='2021-02-01 05:00:00',LoadShowPose={0,0.3,0},}",
  [3003160] = "{id=3003160,NameZh='时来运转·烈焰',Icon='item_3003160',Type=501,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={82000060}},Desc='新年特制的上等礼袍，是将所有的祈愿揉进丝线，汇成衣服上的锦绣花纹。喜庆祥和配上少年的飒爽英姿，“我的力量足以让我保护你世世生生”。',TFValidDate='2021-02-09 05:00:00',ValidDate='2021-02-12 05:00:00',MainColor='e31800FF',}",
  [3003161] = "{id=3003161,NameZh='时来运转·雪神',Icon='item_3003160',Type=501,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={82000060}},Desc='新年特制的上等礼袍，是将所有的祈愿揉进丝线，汇成衣服上的锦绣花纹。配上少年星空下的恬静庄重，“相比银河雪夜清冷，有你的人间烟火着实温暖喧嚣，令人迷恋”。',TFValidDate='2021-02-09 05:00:00',ValidDate='2021-02-12 05:00:00',MainColor='4147edFF',}",
  [3003162] = "{id=3003162,NameZh='时来运转·溯光',Icon='item_3003160',Type=501,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={82000060}},Desc='新年特制的上等礼袍，是将所有的祈愿揉进丝线，汇成衣服上的锦绣花纹。如御用的远航船只乘风破浪，高台上的少年艳若朝阳，正迎着霞光勇敢向前。',TFValidDate='2021-02-09 05:00:00',ValidDate='2021-02-12 05:00:00',MainColor='ff820dFF',}",
  [3003163] = "{id=3003163,NameZh='时来运转·绀紫',Icon='item_3003160',Type=501,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={82000060}},Desc='新年特制的上等礼袍，是将所有的祈愿揉进丝线，汇成衣服上的锦绣花纹。少年从太阳上采撷的浪漫与亮丽，参与编制而成这件梦的华服。我们在爱中创造一切，包括我们自己，和我们的未来。',TFValidDate='2021-02-09 05:00:00',ValidDate='2021-02-12 05:00:00',MainColor='8121caFF',}",
  [3003170] = "{id=3003170,NameZh='璀璨前路·烈焰',Icon='item_3003170',Type=501,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={82000060}},Desc='新年特制的上等礼袍，是将所有的祈愿揉进丝线，汇成衣服上的锦绣花纹。喜庆祥和配上少女的温柔坚毅，“护你平安喜乐是我此生永不磨灭的誓言”。',TFValidDate='2021-02-09 05:00:00',ValidDate='2021-02-12 05:00:00',MainColor='e31800FF',}",
  [3003171] = "{id=3003171,NameZh='璀璨前路·雪神',Icon='item_3003170',Type=501,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={82000060}},Desc='新年特制的上等礼袍，是将所有的祈愿揉进丝线，汇成衣服上的锦绣花纹。配上少女来星空下的典雅美丽，“对你思念至此飘过天际，山水一程风雪又一程”。',TFValidDate='2021-02-09 05:00:00',ValidDate='2021-02-12 05:00:00',MainColor='4147edFF',}",
  [3003172] = "{id=3003172,NameZh='璀璨前路·溯光',Icon='item_3003170',Type=501,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={82000060}},Desc='新年特制的上等礼袍，是将所有的祈愿揉进丝线，汇成衣服上的锦绣花纹。似天堂河流穿越神宫，沐浴金光的少女典雅庄重，带着希望与圣光。',TFValidDate='2021-02-09 05:00:00',ValidDate='2021-02-12 05:00:00',MainColor='ff820dFF',}",
  [3003173] = "{id=3003173,NameZh='璀璨前路·绀紫',Icon='item_3003170',Type=501,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={82000060}},Desc='新年特制的上等礼袍，是将所有的祈愿揉进丝线，汇成衣服上的锦绣花纹。从少女心中飞出的高雅和柔美，幻化成日出与日落间的一缕芳香。内心还有我不曾认知的大陆，所以新的一年，必当继续远航。',TFValidDate='2021-02-09 05:00:00',ValidDate='2021-02-12 05:00:00',MainColor='8121caFF',}",
