  [3003193] = "{id=3003193,NameZh='春之华章·绀紫',Icon='item_3003190',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='“初春伊始的喜庆祥和是前行的动力，为善良的人们继续我的守护。乘风破浪吧，光芒会永远灿烂地照耀在我们的肩上！”',TFValidDate='2021-02-09 05:00:00',ValidDate='2021-02-12 05:00:00',MainColor='8121caFF',}",
  [3003194] = "{id=3003194,NameZh='春之华章头饰系列',Icon='item_3003194',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15436,AdventureValue=1,StorageReward={buffid={80012930}},Condition=8,TFValidDate='2021-02-09 05:00:00',ValidDate='2021-02-12 05:00:00',MainColor='X',}",
  [3003195] = "{id=3003195,NameZh='春之福音·烈焰',Icon='item_3003195',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='“万象更新的吉祥欢乐让内心富足，为善良的人们继续我的祝愿，祝你万事胜意。”',TFValidDate='2021-02-09 05:00:00',ValidDate='2021-02-12 05:00:00',LoadShowPose={0,1.2,-0.8},MainColor='e31800FF',}",
  [3003196] = "{id=3003196,NameZh='春之福音·雪神',Icon='item_3003195',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='“万象更新的吉祥欢乐让内心富足底蕴十足，为善良的人们继续我的祝愿，新年更添贵气不畏风雨。”',TFValidDate='2021-02-09 05:00:00',ValidDate='2021-02-12 05:00:00',MainColor='4147edFF',}",
  [3003197] = "{id=3003197,NameZh='春之福音·溯光',Icon='item_3003195',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='“万象更新的吉祥欢乐让内心富足底蕴十足，为善良的人们继续我的祝愿，新年依旧刚正不阿心地光明。',TFValidDate='2021-02-09 05:00:00',ValidDate='2021-02-12 05:00:00',MainColor='ff820dFF',}",
  [3003198] = "{id=3003198,NameZh='春之福音·绀紫',Icon='item_3003195',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='“万象更新的吉祥欢乐让内心富足底蕴十足，为善良的人们继续我的祝愿，勇往直前吧，希望会永远灿烂地照耀在我们的肩上！”',TFValidDate='2021-02-09 05:00:00',ValidDate='2021-02-12 05:00:00',MainColor='8121caFF',}",
