  [3003200] = "{id=3003200,NameZh='希冀春之晨头饰兑换券',Icon='item_3003200',Type=61,UseMode=31152,MaxNum=99999,SellPrice=100,Desc='使用之后可以兑换任意一件希冀春之晨系列头饰哦~',}",
  [3003201] = "{id=3003201,NameZh='萌牛初生',Icon='item_3003201',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15438,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='“嘿嘿，爬到你头上啦！诶，我……我只是想看烟花能清楚一点，才没有要蹬鼻子上脸呢，哼！”',TFValidDate='2021-02-09 05:00:00',ValidDate='2021-02-12 05:00:00',}",
  [3003202] = "{id=3003202,NameZh='福满新岁',Icon='item_3003202',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15439,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='“吖，趴在毛茸茸帽子上可真暖和，诶？对哦……我也是毛茸茸的，那你感觉到温暖了嘛？嘻嘻～。”',TFValidDate='2021-02-09 05:00:00',ValidDate='2021-02-12 05:00:00',LoadShowRotate=0,LoadShowPose={0,0.8,0},}",
  [3003203] = "{id=3003203,NameZh='金羽幻翅',Icon='item_3003203',Type=810,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=15440,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='鸿蒙雾气中开启最闪亮的登场！在朝阳照耀下的云中前行，新一年你注定是人群中最靓丽的风景线。',TFValidDate='2021-02-09 05:00:00',ValidDate='2021-02-12 05:00:00',LoadShowRotate=160,LoadShowPose={0.5,0.3,-1.5},}",
  [3003204] = "{id=3003204,NameZh='爆竹精灵',Icon='item_3003204',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15441,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='谁说年兽怕炮竹来着，我可是最喜欢热闹闪亮的东西呢！哈？这点小声音根本吓不到我，我吼起来可比这个大声得多喔！',TFValidDate='2021-02-09 05:00:00',ValidDate='2021-02-12 05:00:00',LoadShowRotate=180,LoadShowPose={0,0.5,-0.5},}",
  [3003205] = "{id=3003205,NameZh='牛气大波利',Icon='item_3003205',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15442,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='藏在萌萌牛头帽里的大波利，给主人表演一段刚学的烟花绝活吧，表演完了记得要给波利好吃的，好吃的，好吃的喔！',TFValidDate='2021-02-09 05:00:00',ValidDate='2021-02-12 05:00:00',LoadShowPose={0,0.4,0},}",
  [3003206] = "{id=3003206,NameZh='未知银河',Icon='item_3003206',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15443,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='带有精灵色彩的你眼底仿佛盛满整个星空，虽不善言语，却拥有看穿世界，俯瞰大地的力量。',TFValidDate='2021-02-09 05:00:00',ValidDate='2021-02-12 05:00:00',LoadShowRotate=340,}",
  [3003253] = "{id=3003253,NameZh='初心庆典礼盒',Icon='item_710044',Type=30,MaxNum=9999,SellPrice=100,Desc='欢迎各位冒险者来到新世界，使用之后可以获得「B格猫福利券·Ⅰ」x30、「B格猫福利券·宴」x30',Delete=3003253}",
  [3003260] = "{id=3003260,NameZh='加拉尔之光',Icon='item_3003260',Type=77,Quality=2,MaxNum=1,SellPrice=100,AdventureSort=118,AdventureValue=1,StorageReward={buffid={82000100}},Condition=8,Desc='由米德加尔特的守护神所持有的宝物，平日收在世界之树的高枝里。只有在重要的节日才会取出赠与世人。伴随着徐徐飞升的灯光，许愿者心中的梦想也一定会实现！',Feature=1,TFValidDate='2021-01-25 05:00:00',ValidDate='2021-02-01 05:00:00',}",
  [3003261] = "{id=3003261,NameZh='勇武加冕',Icon='item_3003261',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10341,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='通晓东方文化的匠人倾心打造的头饰，注入了神圣魔法的它在保暖的同时可以护佑使用者战斗所向披靡。头顶的牛角可不单单是装饰，防御值也超高，不小心撞到会很疼喔！',Feature=1,TFValidDate='2021-01-25 05:00:00',ValidDate='2021-02-01 05:00:00',}",
  [3003262] = "{id=3003262,NameZh='友谊之证',Icon='item_6076',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='是米娅用心制作的精致礼盒，打开后会得到有带着斐扬气质的谢礼。在选色上，米娅挑了路奇最喜欢的粉粉红红，甜蜜又可爱！使用后可获得「新春鞭炮」 x 30、「金质勋章 」x 2、「坠星陨铁」 x 2、「女武神的馈赠 」x 2 、「小木锤 」x 1。',Feature=1,}",
  [3003263] = "{id=3003263,NameZh='新春鞭炮',Icon='item_3001422',Type=61,Quality=3,UseMode=31155,MaxNum=99999,SellPrice=10,Desc='要不要一起来普隆德拉放鞭炮啊！你负责点，我负责……捂耳朵。',ExistTimeType=2,ExistTime='2021-03-04 05:00:00',Feature=1,}",
  [3003264] = "{id=3003264,NameZh='幻想创造机Ⅰ号的感恩礼·2021',Icon='item_6069',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='幻想创造器Ⅰ号为了感谢各位冒险者这一年来的付出，特意推出的礼物，打开后随机获得1个2021年3月发行的蓝色品质及以上小扭蛋，有小概率获得2021年3月发行的全部小扭蛋。\n该礼盒需在2021年3月1日后可开启。',Feature=1,Delete=3003264}",
  [3003265] = "{id=3003265,NameZh='小木锤',Icon='item_3001889',Type=30,Quality=3,UseMode=31043,MaxNum=99999,SellPrice=100,Desc='虽然是普通木制小锤，但是却能发挥巨大威力，真是惊人！“喂！这个不可以用来打人！”',ExistTimeType=2,ExistTime='2021-03-01 05:00:00',Feature=1,}",
  [3003266] = "{id=3003266,NameZh='一夜暴富图纸',Icon='item_3034266',Type=50,Quality=3,MaxNum=99999,AuctionPrice=1,SellPrice=100,ComposeID=3003266,Desc='红包里鼓鼓囊囊，不用说也知道里面塞得是什么了吧。这份是我的，谁都不要想跟我抢！',Feature=1,}",
  [3003267] = "{id=3003267,NameZh='雪花的快乐',Icon='item_3945',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='不去那冷寞的幽谷，不去那凄清的山麓，也不上荒街去惆怅，看着我就好啦。毕竟我带着冬天的礼物出现啦！使用后可获得「新春鞭炮」 x 30、「B格猫福利券·I 」x 5 、「家具提货券」 x 4、「莫拉硬币」x 8 、「小木锤 」x 1。',Feature=1,}",
  [3003268] = "{id=3003268,NameZh='狩猎之证',Icon='item_3856',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='鼓鼓囊囊的大奖礼包，里面装着一般情况下得不到的好东西。包装束口有点猫爪的感觉。欸，不好！要被喵化了！打开必定获得「新春鞭炮」x 20，有概率获得「莫拉硬币」 x 9 、「玛丝黛拉果实」x 1 、「神谕之尘」x 6 、「神谕之晶」x 4 、「精装卡册残页」x 5 、「料理兑换券」x 1，并有50%概率额外获得「小木锤」x 1。',Feature=1,}",
  [3003269] = "{id=3003269,NameZh='路奇的私藏',Icon='item_3000526',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='为了不让别人拿走盒子里的宝贝故意在开口处贴了片树叶打掩护。但好像产生了反效果……使用后可获得：「新春鞭炮」 x 60、「B格猫福利券·宴 」x 10 、「B格猫福利券·I 」 x 10、「莫拉硬币」x 10 、「龙之宝箱 」x 1 、「小木锤 」x 2。',Feature=1,Delete=3003269}",
  [3003270] = "{id=3003270,NameZh='爱心轰趴',Icon='item_3003270',Type=77,Quality=3,MaxNum=1,SellPrice=100,AdventureSort=119,AdventureValue=1,StorageReward={buffid={82000140}},Condition=8,Desc='无论何时何地，都要被爱包围着！爱神护佑，你就是集万千专宠于一身的那一位！',Feature=1,TFValidDate='2021-01-25 05:00:00',ValidDate='2021-02-01 05:00:00',}",
  [3003272] = "{id=3003272,NameZh='离线战斗7天体验卡',Icon='item_163',Type=41,MaxNum=99999,SellPrice=100,Desc='使用后可获得7天的离线战斗使用资格，天数可以累加，剩余天数不足并不会影响已经开启的离线战斗。',NoStorage=5,Delete=3003272}",
  [3003273] = "{id=3003273,NameZh='波利鞭泡',Icon='item_3003273',Type=41,MaxNum=99999,SellPrice=1,Desc='鞭泡不是鞭炮！只要波利躲在大泡泡里，就不会被炸到……吧？使用后可以对目标造成2021点真实伤害。',}",
  [3003274] = "{id=3003274,NameZh='治愈礼盒',Icon='item_5904',Type=30,MaxNum=9999,SellPrice=100,Desc='材料捐献获得的礼盒，乍一看有点像符文的感觉。打开会有惊喜在等着你喔！使用后可获得：「B格猫福利券·宴」 x 5、「坠星陨铁 」x 2 、「神谕之尘」 x 6、「乐园币」x 200 、「小木锤 」x 1。',Feature=1,}",
  [3003275] = "{id=3003275,NameZh='智慧礼盒',Icon='item_5903',Type=30,MaxNum=9999,SellPrice=100,Desc='材料捐献获得的礼盒，乍一看上面像是雕刻着某种图腾。打开会有惊喜在等着你喔！使用后可获得：「B格猫福利券·Ⅰ」 x 4、「坠星陨铁 」x 2 、「神谕之晶」 x 4、「光洁的符文石」x 1 、「小木锤 」x 1。',Feature=1,}",
  [3003276] = "{id=3003276,NameZh='光明礼盒',Icon='item_5902',Type=30,MaxNum=9999,SellPrice=100,Desc='材料捐献获得的礼盒，拿在手中闪闪发光还有点重量。打开会有惊喜在等着你喔！使用后可获得：「祈祷晶片包」 x 2、「古拉姆晶末」x 20 、「金质勋章」 x 2、「尘封的符文袋·Ⅰ」x 2 、「小木锤 」x 1。',Feature=1,}",
  [3003277] = "{id=3003277,NameZh='B格猫守岁红包·2021',Icon='item_6504',Type=30,MaxNum=9999,SellPrice=100,Desc='新的一年，作为大陆上最有钱的喵星人，本喵要给你们每个人都发守岁红包~喵呜~\n开启后获得「B格猫福利券·I」×30、「B格猫福利券·宴」×60、「莫拉硬币」×10、「神谕之尘」×10、「神谕之晶」×10、「金质勋章」×5、「玛丝黛拉果实」×1、「祈祷晶片包」×5。',Feature=1,Delete=3003277}",
  [3003280] = "{id=3003280,NameZh='花妖铃兰',Icon='item_3003280',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9753,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='生活在密林中的灵兽，具备分辨草药的能力。浮空精灵的魔药学者们会用零食与玩具跟铃兰搞好关系，这样铃兰就会带他们寻找各种稀有的草药。',TFValidDate='2021-03-01 05:00:00',ValidDate='2021-03-01 05:00:00',}",
  [3003281] = "{id=3003281,NameZh='命运轮序',Icon='item_3003281',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9754,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='我在此处守望，转动的命运之轮终会令我们重聚。',TFValidDate='2021-03-01 05:00:00',ValidDate='2021-03-01 05:00:00',LoadShowPose={0,0.3,0},}",
  [3003282] = "{id=3003282,NameZh='乐团新星[1]',Icon='item_3003282',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9755,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='“阿多尼斯因他俊美的容貌遭嫉，被恶人杀害。他的恋人日夜祷告，感动了诸神。神明复活了阿多尼斯，令他与恋人团聚……”——《风之轻语乐团歌剧选·阿多尼斯的回归》。\n据说艾卡拉奇超过一半的女性因这部伟大的歌剧流泪，此剧的男主演也成为了那个辰星年最闪耀的新星。',TFValidDate='2021-03-01 05:00:00',ValidDate='2021-03-01 05:00:00',LoadShowPose={0,0.8,0},}",
  [3003283] = "{id=3003283,NameZh='星雨沐空',Icon='item_3003283',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9756,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='看了他和她的故事，夜空也在雨里流泪。',TFValidDate='2021-03-01 05:00:00',ValidDate='2021-03-01 05:00:00',LoadShowPose={-0.2,0.5,0.6},}",
  [3003284] = "{id=3003284,NameZh='占星师之镜',Icon='item_3003284',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9757,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='这副浮空精灵的占星师们世代相传的眼镜上镌刻这一行小字：“即使洞察过去、现在与未来全部的命运，也难以看穿朝夕相处之人的内心。”',TFValidDate='2021-03-01 05:00:00',ValidDate='2021-03-01 05:00:00',LoadShowRotate=330,LoadShowPose={-0.3,0.4,0.8},}",
  [3003285] = "{id=3003285,NameZh='相位星晷[1]',Icon='item_3003285',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9758,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='浮空精灵的占星师们常用这种仪器测量星辰的相对位置与运行轨迹，推演岁月变迁。',TFValidDate='2021-03-01 05:00:00',ValidDate='2021-03-01 05:00:00',LoadShowPose={0,0.8,0},}",
