  [3003310] = "{id=3003310,NameZh='夜幕孤星·土象',Icon='item_3003310',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='高悬的明星，成为漆黑夜幕下唯一的光源，如同黑暗时代的英杰，他们如大地般坚毅，承担着引领着世人，守护他们。',TFValidDate='2021-03-13 05:00:00',ValidDate='2021-03-16 05:00:00',MainColor='696ed8FF',}",
