  [3003320] = "{id=3003320,NameZh='月光清鳞·弦月',Icon='item_3003320',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='明月如同一泓清泉，将澄澈的月光撒下，那高悬的弦月，就是在夜幕中遨游的一尾锦鲤。',TFValidDate='2021-03-13 05:00:00',ValidDate='2021-03-16 05:00:00',MainColor='696ed8FF',}",
