  [3003330] = "{id=3003330,NameZh='晦夜无光·蚀',Icon='item_3003310',Type=501,MaxNum=99,SellPrice=100,Desc='晦暗无边的天幕，不见皎月与群星，苍茫大地上谁在祈祷着，期盼那个带来光明的人出现。',TFValidDate='2021-03-13 05:00:00',ValidDate='2021-03-16 05:00:00',MainColor='383671FF',}",
  [3003331] = "{id=3003331,NameZh='残月未明·蚀',Icon='item_3003320',Type=501,MaxNum=99,SellPrice=100,Desc='新月时月光黯淡，夜幕漆黑。但月相轮转，满月终将到来，圣洁的月光将洒满大地。',TFValidDate='2021-03-13 05:00:00',ValidDate='2021-03-16 05:00:00',MainColor='383671FF',}",
  [3003332] = "{id=3003332,NameZh='晦夜守望时装兑换券',Icon='item_3003332',Type=121,MaxNum=99999,SellPrice=100,ComposeID=4000064,Desc='使用之后可以获得一件对应阁下性别的晦夜守望系列时装哦~',}",
  [3003333] = "{id=3003333,NameZh='晦夜守望系列时装',Icon='item_3003324',Type=501,MaxNum=99,SellPrice=100,AdventureSort=15456,AdventureValue=1,Condition=8,TFValidDate='2021-03-13 05:00:00',ValidDate='2021-03-16 05:00:00',MainColor='383671FF',}",
  [3003340] = "{id=3003340,NameZh='星愿·土',Icon='item_3003340',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='接受群星的赐福吧，那是代表着务实的土象星座，它将赋予你坚毅的内心，让你拥有面对一切艰险的勇气。',TFValidDate='2021-03-13 05:00:00',ValidDate='2021-03-16 05:00:00',LoadShowPose={0,1.2,-0.8},MainColor='696ed8FF',}",
  [3003341] = "{id=3003341,NameZh='星愿·风',Icon='item_3003340',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='接受群星的赐福吧，那是代表着变革的风象星座，它将赋予你无尽的知识，帮助你思考，理解这个世界。',TFValidDate='2021-03-13 05:00:00',ValidDate='2021-03-16 05:00:00',MainColor='14ac8aFF',}",
  [3003342] = "{id=3003342,NameZh='星愿·水',Icon='item_3003340',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='接受群星的赐福吧，那是代表着情感的水象星座，它将赋予你敏锐的感知，让你领略这世间的人情百态。',TFValidDate='2021-03-13 05:00:00',ValidDate='2021-03-16 05:00:00',MainColor='57b9faFF',}",
  [3003343] = "{id=3003343,NameZh='星愿·火',Icon='item_3003340',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='接受群星的赐福吧，那是代表着生命的火象星座，它将赋予你热情与活力，让你在冒险旅程中不断成长。',TFValidDate='2021-03-13 05:00:00',ValidDate='2021-03-16 05:00:00',MainColor='f8aad5FF',}",
  [3003344] = "{id=3003344,NameZh='星愿头饰系列',Icon='item_3003344',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15446,AdventureValue=1,StorageReward={buffid={80012930}},Condition=8,TFValidDate='2021-03-13 05:00:00',ValidDate='2021-03-16 05:00:00',MainColor='X',}",
  [3003345] = "{id=3003345,NameZh='月灵·弦',Icon='item_3003345',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='月之精灵为你奉上月光的祝福，弦月代表着平衡与和谐，以月光之名，亲近这个世界的生灵，拥抱自然吧！',TFValidDate='2021-03-13 05:00:00',ValidDate='2021-03-16 05:00:00',LoadShowPose={0,1.2,-0.8},MainColor='696ed8FF',}",
  [3003346] = "{id=3003346,NameZh='月灵·初',Icon='item_3003345',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='月之精灵为你奉上月光的祝福，初月代表着新生的力量，在月光的庇护下茁壮的成长吧！',TFValidDate='2021-03-13 05:00:00',ValidDate='2021-03-16 05:00:00',MainColor='14ac8aFF',}",
  [3003347] = "{id=3003347,NameZh='月灵·宵',Icon='item_3003345',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='月之精灵为你奉上月光的祝福，盈凸月日渐圆满，它预示着通往成功的道路。在月光的指引下，你将战胜一切艰难险阻。',TFValidDate='2021-03-13 05:00:00',ValidDate='2021-03-16 05:00:00',MainColor='57b9faFF',}",
  [3003348] = "{id=3003348,NameZh='月灵·满',Icon='item_3003345',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='月之精灵为你奉上月光的祝福，满月象征着完美，月光将永远庇护着你，守护这世间的美好。',TFValidDate='2021-03-13 05:00:00',ValidDate='2021-03-16 05:00:00',MainColor='f8aad5FF',}",
  [3003349] = "{id=3003349,NameZh='月灵头饰系列',Icon='item_3003349',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15447,AdventureValue=1,StorageReward={buffid={80012920}},Condition=8,TFValidDate='2021-03-13 05:00:00',ValidDate='2021-03-16 05:00:00',MainColor='X',}",
  [3003350] = "{id=3003350,NameZh='逐光幻想头饰兑换券',Icon='item_3003350',Type=61,UseMode=31168,MaxNum=99999,SellPrice=100,Desc='使用之后可以兑换任意一件逐光幻想系列头饰哦~',}",
  [3003351] = "{id=3003351,NameZh='流萤之火',Icon='item_3003351',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15448,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='夜空中游动的萤火虫，是人们触手可及的星光。',TFValidDate='2021-03-13 05:00:00',ValidDate='2021-03-16 05:00:00',}",
  [3003352] = "{id=3003352,NameZh='星尘桂冠',Icon='item_3003352',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15449,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='这顶头冠用星星的碎片铸成，戴着它奔跑时会有星尘散落——只要你跑的足够快，你就会像彗星一样！',TFValidDate='2021-03-13 05:00:00',ValidDate='2021-03-16 05:00:00',LoadShowPose={0,0.9,0},}",
  [3003353] = "{id=3003353,NameZh='蝶语星声',Icon='item_3003353',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15450,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='听那蝴蝶的低语，她诉说着旅途中听闻的故事；听那星辰的歌声，它们讲述着千万年来这片星空下英雄们的史诗。',TFValidDate='2021-03-13 05:00:00',ValidDate='2021-03-16 05:00:00',LoadShowPose={0.5,0.5,-1.2},}",
  [3003354] = "{id=3003354,NameZh='羽月蛾',Icon='item_3003354',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15451,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='羽月蛾昼伏夜出，喜欢追逐月光，相传它原是居住在月之湖附近的精灵，因为意外坠落在米德加尔特，一直想要回到自己的家乡。',TFValidDate='2021-03-13 05:00:00',ValidDate='2021-03-16 05:00:00',LoadShowPose={0,0.3,-0.5},}",
  [3003355] = "{id=3003355,NameZh='星座启示',Icon='item_3003355',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15452,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='“我从来不相信什么占星术，因为我们这个星座的人生性多疑！”',TFValidDate='2021-03-13 05:00:00',ValidDate='2021-03-16 05:00:00',LoadShowPose={0,0.4,0},}",
  [3003356] = "{id=3003356,NameZh='云枕成眠',Icon='item_3003356',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15453,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='蝴蝶成双飞，飞累了便隐入云朵中休憩，连风也不忍吵醒它们。',TFValidDate='2021-03-13 05:00:00',ValidDate='2021-03-16 05:00:00',LoadShowRotate=340,}",
  [3003357] = "{id=3003357,NameZh='逐光梦羽',Icon='item_3003357',Type=810,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=15454,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='久卧病床的少年看向窗外，月光为庭院披上一层银纱，轻风搅动池塘，波光粼粼。“多么美妙的月光啊，要是可以永远看到它就好了……”神听到了他的祈愿，将他化作一只飞蛾，永远地追逐着这皎洁的月光。',TFValidDate='2021-03-13 05:00:00',ValidDate='2021-03-16 05:00:00',LoadShowSize=1.6,LoadShowRotate=170,LoadShowPose={0.3,0,-1},}",
  [3003359] = "{id=3003359,NameZh='有爱礼盒',Icon='item_6748',Type=30,Quality=3,MaxNum=9999,SellPrice=100,Desc='为了感谢各位冒险者的支持而特意推出的礼盒，打开之后可以获得「B格猫福利券·Ⅰ」x30、「B格猫福利券·宴」x30、「波利成长秘药」x5',Feature=1,Delete=3003359}",
  [3003360] = "{id=3003360,NameZh='冒险礼盒',Icon='item_6746',Type=30,Quality=3,MaxNum=9999,SellPrice=100,Desc='为了感谢各位冒险者的支持而特意推出的礼盒，打开之后可以获得 Zeny x 2888888、「好运币」x30、「祈祷晶片自选包」x10、「萃光结晶」x10',Feature=1,Delete=3003360}",
  [3003370] = "{id=3003370,NameZh='精灵之眼',Icon='item_3003370',Type=830,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10354,AdventureValue=120,AdventureReward={buffid={61001100}},StorageReward={buffid={80012660}},Condition=4,ComposeID=3003540,Desc='他那深邃的像是黄宝石一般的眼睛，脸上美丽神奇的纹路。哇！不会是精灵吧！',TFValidDate='2021-02-22 05:00:00',ValidDate='2021-03-01 05:00:00',}",
  [3003371] = "{id=3003371,NameZh='精灵的祝福',Icon='item_3003371',Type=840,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10355,AdventureValue=140,AdventureReward={buffid={61001130}},StorageReward={buffid={80012920}},Condition=4,ComposeID=3003541,Desc='诶？哪里冒出来的小精灵，挥舞着小翅膀，自用自在的飞翔，好可爱呀！她会给我带来什么好事呢？',TFValidDate='2021-02-22 05:00:00',ValidDate='2021-03-01 05:00:00',LoadShowPose={0,-0.2,0},}",
  [3003380] = "{id=3003380,NameZh='辉煌的棒球帽[1]',Icon='item_3003380',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10350,AdventureValue=1,StorageReward={buffid={80011150}},Condition=8,Desc='象征着光与远方的棒球帽，戴上它，就可以让爱穿梭于现实和冒险世界，永远记住“爱与勇气的冒险”的初心。',Feature=1,TFValidDate='2021-01-06 05:00:00',ValidDate='2021-01-06 05:00:00',}",
  [3003390] = "{id=3003390,NameZh='羞涩时刻[1]',Icon='item_3003390',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9765,AdventureValue=1,StorageReward={buffid={82000240}},Condition=8,Desc='亲爱的泰迪熊啊，请闭上眼睛，给我们一个独处的时刻吧。这一枚手作糖果，我想和我爱的人一起分享。',TFValidDate='2021-05-01 05:00:00',ValidDate='2021-05-01 05:00:00',LoadShowRotate=345,LoadShowPose={0,0.7,0},}",
  [3003391] = "{id=3003391,NameZh='甘草魔泡棒',Icon='item_3003391',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9766,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='可以用它吹出甜味的泡泡哦！眼看着甜蜜在空中飞舞，比在口中感受更让人愉悦',TFValidDate='2021-05-01 05:00:00',ValidDate='2021-05-01 05:00:00',LoadShowPose={0,0.5,0.2},}",
  [3003392] = "{id=3003392,NameZh='糖分不确定性',Icon='item_3003392',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9767,AdventureValue=1,StorageReward={buffid={80012810}},Condition=8,Desc='人生，正如一排不断转动的扭蛋机。你明知道其中隐藏着最美味的糖果，却无法确定下一次是否能摇到。不过，这不正是乐趣所在吗？',TFValidDate='2021-05-01 05:00:00',ValidDate='2021-05-01 05:00:00',LoadShowRotate=345,LoadShowPose={0,0.3,0.3},}",
  [3003393] = "{id=3003393,NameZh='泰迪之吻[1]',Icon='item_3003393',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9768,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='为什么泰迪熊会成为糖果最好的伙伴呢？若你不知道答案，那我就会戴起这个头箍，再凑近你耳边，悄悄地告诉你。',TFValidDate='2021-05-01 05:00:00',ValidDate='2021-05-01 05:00:00',}",
  [3003394] = "{id=3003394,NameZh='甜蜜星月',Icon='item_3003394',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9769,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='隐藏着甜蜜糖果的权杖啊，在我面前展现你真正的力量吧。和你定下约定的冒险者命令你，给我糖分——！',TFValidDate='2021-05-01 05:00:00',ValidDate='2021-05-01 05:00:00',LoadShowPose={0,0.3,-0.5},}",
  [3003395] = "{id=3003395,NameZh='巧豆姑娘',Icon='item_3003395',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9770,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='巧豆姑娘温柔又甜美，只要你向她讨要，就会得到美味的巧克力豆。胖又怎么样啦？快乐才是最重要的！',TFValidDate='2021-05-01 05:00:00',ValidDate='2021-05-01 05:00:00',LoadShowPose={0,0,0},}",
  [3003396] = "{id=3003396,NameZh='安慰蛋糕',Icon='item_3003396',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9070,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='甜品万般好，唯有热量高。要让快乐和身材兼得，只能用安慰蛋糕来欺骗自己……黑科技产品，有着草莓蛋糕的外形，吃下去就是空气。骗骗嘴巴就得啦，这样不也很好吗？',TFValidDate='2021-05-01 05:00:00',ValidDate='2021-05-01 05:00:00',LoadShowPose={0,0.5,0.5},}",
  [3003400] = "{id=3003400,NameZh='公主衣柜·白雪',Icon='item_3003400',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000010}},Desc='新一轮公主热潮已经席卷时尚界！谁会对经典的公主裙有抵抗力呢？——淡黄色蓬松的长裙甩开，勇敢咽下那片命运的苹果，醒来的时候，你将会找到真爱。',Feature=1,TFValidDate='2021-05-30 05:00:00',ValidDate='2021-06-30 05:00:00',Delete=3003400}",
  [3003401] = "{id=3003401,NameZh='公主衣柜·灰姑娘',Icon='item_3003401',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000010}},Desc='皇家风范引领潮流！身着经典公主裙，脚踩水晶鞋，舞步直到午夜不停歇。自信勇敢的你会赢得王子的青睐和幸福的人生，但不要忘记在午夜的钟声响起前回家呦。',Feature=1,TFValidDate='2021-05-30 05:00:00',ValidDate='2021-06-30 05:00:00',Delete=3003401}",
  [3003402] = "{id=3003402,NameZh='公主衣柜·贝尔',Icon='item_3003402',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000010}},Desc='皇家风范引领潮流！身着经典公主裙，走自己的路。透过野兽的外表，你能发现人性的光辉，还有救赎爱情的勇气。',Feature=1,TFValidDate='2021-05-30 05:00:00',ValidDate='2021-06-30 05:00:00',Delete=3003402}",
  [3003403] = "{id=3003403,NameZh='公主衣柜·爱洛',Icon='item_3003403',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000010}},Desc='新一轮公主热潮已经席卷时尚界！谁会对经典的公主裙有抵抗力呢？——天真和纯朴就是最强大的力量，所有的诅咒都无法污染这份美好。',Feature=1,TFValidDate='2021-05-30 05:00:00',ValidDate='2021-06-30 05:00:00',Delete=3003403}",
  [3003404] = "{id=3003404,NameZh='公主衣柜·乐佩',Icon='item_3003404',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=15495,AdventureValue=1,Condition=8,Desc='新一轮公主热潮已经席卷时尚界！谁会对经典的公主裙有抵抗力呢？——什么也不能阻挡对自由和远方的向往。长发是累赘？才不呢！只要你会用，它就是最好的伙伴。',Feature=1,TFValidDate='2021-05-30 05:00:00',ValidDate='2021-06-30 05:00:00',Delete=3003404}",
  [3003405] = "{id=3003405,NameZh='迪士尼公主系列时装',Icon='item_3003405',Type=501,MaxNum=99,SellPrice=100,AdventureSort=15494,AdventureValue=1,AdventureReward={buffid={62000010}},StorageReward={buffid={82000010}},Condition=8,Feature=1,TFValidDate='2021-05-30 05:00:00',ValidDate='2021-06-30 05:00:00',Delete=3003405}",
  [3003410] = "{id=3003410,NameZh='公主妆面·白雪',Icon='item_3003410',Type=800,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='雪一样白的肌肤，乌木一样黑的头发，玫瑰一样红的朱唇，还有勇敢善良的心灵，让你光彩照人。',Feature=1,TFValidDate='2021-05-30 05:00:00',ValidDate='2021-06-30 05:00:00',Delete=3003410}",
  [3003411] = "{id=3003411,NameZh='公主妆面·灰姑娘',Icon='item_3003411',Type=800,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='用黑灰遮掩住美丽并非因为怯懦，而是对现实的权衡和妥协。在有必要的时候，我会焕发比谁都华丽的光辉。',Feature=1,TFValidDate='2021-05-30 05:00:00',ValidDate='2021-06-30 05:00:00',Delete=3003411}",
  [3003412] = "{id=3003412,NameZh='公主妆面·贝尔',Icon='item_3003412',Type=800,Quality=3,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='长发挽起，耳环闪耀，你是舞会上的璀璨明珠。但最迷人的，还是你的智慧与善良。',Feature=1,TFValidDate='2021-05-30 05:00:00',ValidDate='2021-06-30 05:00:00',Delete=3003412}",
