  [3003531] = "{id=3003531,NameZh='天水风铃',Icon='item_3003531',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9760,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='传说中天水之国的居民们，习惯在春夏交际的时候，制作精致的风铃挂在屋檐下。每当清风吹过就能听见铃铛清脆的声音，仿佛在提醒人们夏天在一步步走近。',TFValidDate='2021-04-01 05:00:00',ValidDate='2021-04-01 05:00:00',LoadShowPose={0,0.5,0.2},}",
