  [3003544] = "{id=3003544,NameZh='神树的汁液',Icon='item_551012',Type=610,Quality=2,MaxNum=99999,SellPrice=100,AdventureSort=1017,AdventureValue=1,Condition=4,Desc='具有神奇味道的神树的汁液，貌似可以喝下去。使用后物理攻击+40、MaxHp+500、物理穿刺+2.5%、魔法穿刺+2.5%、MaxSp+50、魔法攻击+40。使用多个后增益效果叠加。',}",
