  [3003602] = "{id=3003602,NameZh='迎客姬',Icon='item_3003602',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15460,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='这位客人，欢迎来到天津町哟~客人真是挑了个好时候呢，现在是最适合赏樱的时节哦～',LoadShowRotate=160,LoadShowPose={0,0.3,0},}",
