  [3003620] = "{id=3003620,NameZh='TapTap 拿铁',Icon='item_3003620',Type=41,MaxNum=99999,SellPrice=100,Desc='强化神经，激活肌肉张力。适合通关新买的游戏时饮用，帮你保持深夜好状态！HP、SP恢复速度+10%，持续30分钟（6v6、12v12、GVG中不生效）。',}",
  [3003621] = "{id=3003621,NameZh='TapTap 能量',Icon='item_3003621',Type=41,MaxNum=99999,SellPrice=100,Desc='仿佛灌注某种风之魔能的饮料。反应非常迅猛，往吸管吹气便能如上升寒流般冒出好多泡泡。魔法伤害、物理伤害+3%，持续30分钟（6v6、12v12、GVG中不生效）。',}",
  [3003622] = "{id=3003622,NameZh='TapTap 特调',Icon='item_3003622',Type=41,MaxNum=99999,SellPrice=100,Desc='此饮料的爱好者可能不想知道：这种酸甜又丝滑的液体，其实是一群看不见的小生物用眼泪做成的。全能力+5，持续30分钟（6v6、12v12、GVG中不生效）。',}",
