  [3003630] = "{id=3003630,NameZh='嗒啦啦趴趴',Icon='item_3003630',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10357,AdventureValue=1,StorageReward={buffid={80012610}},Condition=8,Desc='“冒险者的脑壳好软呐……”刚趴上去的嗒啦啦感叹道，冒险者却毫无回应。“看来你好像习惯头上趴人了。”于是嗒啦啦更没忌惮地掏出手机玩起了游戏，度过愉快的一天。',TFValidDate='2021-05-29 05:00:00',ValidDate='2021-06-05 05:00:00',Delete=3003630}",
  [3003631] = "{id=3003631,NameZh='元气嗒啦啦',Icon='item_3003631',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10358,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='青蓝挑染的金发，富有科技感和青春活力。这种发型的唯一不便是：乘坐巨大圆形机器人飞行时会带来巨大惯性，扯得人后脑勺生疼。',TFValidDate='2021-06-04 05:00:00',ValidDate='2021-06-11 05:00:00',LoadShowPose={0,1,-0.3},Delete=3003631}",
  [3003632] = "{id=3003632,NameZh='透明软糖罐',Icon='item_3003632',Type=61,UseMode=31171,MaxNum=99999,SellPrice=10,Desc='嗒啦啦最爱吃的软糖。晃动时会摩擦出微妙的白噪音，十分适合催眠。',}",
  [3003633] = "{id=3003633,NameZh='噗噜噜便携版',Icon='item_3003633',Type=77,MaxNum=1,SellPrice=100,AdventureSort=245,AdventureValue=1,Condition=8,Desc='迷你噗噜噜。掌中的贴心管家。有了它，就再也不用怕被贴上“低头族”的标签了。',Feature=1,TFValidDate='2021-05-25 05:00:00',ValidDate='2021-06-01 05:00:00',}",
  [3003634] = "{id=3003634,NameZh='软糖猎手',Icon='item_3003634',Type=10,MaxNum=1,SellPrice=100,Desc='不论是在追踪波利和噗噜噜时，还是在陪我冒险时，你都展现了应有的出色才能！特此奖励，以资鼓励！——嗒啦啦',TFValidDate='2021-05-29 05:00:00',ValidDate='2021-06-05 05:00:00',}",
  [3003635] = "{id=3003635,NameZh='天水蜜桃',Icon='item_3003635',Type=103,MaxNum=99999,SellPrice=100,Desc='出产自天水之国的蜜桃。天知道为什么“噗噜噜”对它那么感兴趣！',}",
