  [3003650] = "{id=3003650,NameZh='青空之梦',Icon='item_3003650',Type=840,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10359,AdventureValue=1,StorageReward={buffid={80012990}},Condition=8,Desc='据说洛阳的春日，会有平民小儿将自己的愿望放飞。如果把风筝带在身后，是不是我的梦也能翱翔于天空呢？',TFValidDate='2021-03-29 05:00:00',ValidDate='2021-04-05 05:00:00',LoadShowRotate=345,LoadShowPose={0,-0.2,0},}",
  [3003651] = "{id=3003651,NameZh='熊猫背篓',Icon='item_3003651',Type=810,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10360,AdventureValue=1,StorageReward={buffid={80012600}},Condition=8,Desc='青翠欲滴的竹子做成的背篓，附赠一只黑白相间的熊猫。友情提醒：请及时回血，避免被萌死。',TFValidDate='2021-04-08 05:00:00',ValidDate='2021-04-15 05:00:00',LoadShowRotate=160,LoadShowPose={0,0.3,-0.3},}",
  [3003652] = "{id=3003652,NameZh='春樱发卡',Icon='item_3003652',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10361,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='天津町的暖熏春风将淡淡樱粉吹至你的发丝，轻轻一嗅，就会有恋爱的清甜香气。',TFValidDate='2021-04-01 05:00:00',ValidDate='2021-04-08 05:00:00',LoadShowRotate=290,}",
  [3003655] = "{id=3003655,NameZh='樱花礼盒',Icon='item_6602',Type=30,MaxNum=99999,SellPrice=100,Desc='当最严酷的寒冬过去，坚忍的冒险者将会得春日最美好的馈赠。打开后必定获得「小木锤」x1，有概率获得以下道具中的一种：「闪耀的符文石」x1、「光洁的符文石」x1、「神谕之尘」x4、「神谕之晶」x2、「祈祷晶片包」x2、「玛丝黛拉种子」x1。',Delete=3003655}",
  [3003656] = "{id=3003656,NameZh='环游世界礼包',Icon='item_6605',Type=30,MaxNum=99999,SellPrice=100,Desc='罗伯特先生游历米德加尔特所收集的礼包。放心，里面装满的并不只是冷笑话。打开后必定获得「小木锤」x1、「莫拉硬币」x4、「乐园币」x300、「冒险丸子」x200、「信仰之证」x100。',Delete=3003656}",
  [3003657] = "{id=3003657,NameZh='纸糊的魔纹箱',Icon='item_3003657',Type=30,MaxNum=99999,SellPrice=100,Desc='不要因为是纸做的宝箱就小看它，它的锋利边缘堪比刀刃。当然，内容也不会让你失望。打开后必定获得「祈祷晶片包」x1、「金质勋章」x1、「随机MVP材料」x1、「幻想樱花」x1，有概率获得「魔纹纸妖卡片」x1。',GetLimit={limit={[999]={2,0}},source={11},type=4},Delete=3003657}",
  [3003658] = "{id=3003658,NameZh='幻想樱花',Icon='item_3003658',Type=61,UseMode=31198,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='纵然只是小小花瓣，却饱含着爱、期待和梦想。如果用它制造器物，会做成怎样美丽的物品呢？（可以在普隆德拉「阿尔勒」处兑换饰品）',ExistTimeType=2,ExistTime='2021-05-01 05:00:00',}",
  [3003659] = "{id=3003659,NameZh='种植百科全书',Icon='item_44085',Type=30,MaxNum=99999,SellPrice=100,Desc='斐扬种稻专家萨柯娜的倾情力作！据作者本人说，如果精通此书，以后就一定饮食无忧。打开后必定获得「料理兑换券」x1、「秘制亲子丼」x1、「坠星陨铁」x1、「波利成长秘药」x1、「自然之恩」x1、「小木锤」x1。',}",
  [3003660] = "{id=3003660,NameZh='自然之恩',Icon='item_5124',Type=61,UseMode=31198,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='感谢上天赠予的恩赐，让我们免于饥饿，收获幸福。以此诚心，感谢神明。（可以在普隆德拉「阿尔勒」处兑换饰品）',ExistTimeType=2,ExistTime='2021-05-01 05:00:00',}",
  [3003661] = "{id=3003661,NameZh='优秀助手奖状',Icon='item_30723',Type=30,MaxNum=99999,SellPrice=100,Desc='从阿尔勒的助手小哥手里得到的奖状。虽然有点哭笑不得，但也包含着他的一片心意。打开后必定获得「小木锤」x1，有概率获得以下道具中的一种：「闪耀的符文石·星」x1、「未知上古遗物碎片」x1、「华丽卡册」x1、「闪耀的符文石」x1、「玛丝黛拉种子」x1。',Delete=3003661}",
  [3003662] = "{id=3003662,NameZh='小木锤',Icon='item_3001889',Type=30,UseMode=31043,MaxNum=99999,SellPrice=100,Desc='虽然是普通木制小锤，但是却能发挥巨大威力，真是惊人！“喂！这个不可以用来打人！”',ExistTimeType=2,ExistTime='2021-05-01 05:00:00',Delete=3003662}",
  [3003663] = "{id=3003663,NameZh='锦时春岁时装自选券',Icon='item_51536',Type=61,UseMode=31172,MaxNum=99999,SellPrice=100,Desc='使用之后可以兑换任意一件精锦时春岁系列时装哦~',}",
  [3003664] = "{id=3003664,NameZh='散华妖夜行时装自选券',Icon='item_51346',Type=61,UseMode=31173,MaxNum=99999,SellPrice=100,Desc='使用之后可以兑换任意一件散华妖夜行系列时装哦~',}",
  [3003665] = "{id=3003665,NameZh='森空鹿谣时装自选券',Icon='item_3000486',Type=61,UseMode=31174,MaxNum=99999,SellPrice=100,Desc='使用之后可以兑换任意一件森空鹿谣系列时装哦~',}",
  [3003666] = "{id=3003666,NameZh='锦时春岁头饰兑换券',Icon='item_6571',Type=61,UseMode=31175,MaxNum=99999,SellPrice=100,Desc='使用之后可以兑换任意一件锦时春岁系列头饰哦~',}",
  [3003667] = "{id=3003667,NameZh='咚咚惊喜箱',Icon='item_3877',Type=30,MaxNum=99999,SellPrice=100,Desc='闪闪发亮，被糖果和星星包围的神秘礼盒。摇晃的话可以听到咚咚的声音，似乎藏着不得了的宝贝。好像只有在新年到来的时候才会出现。打开后必定获得「噼啪波利弹」x1、「神谕之尘」x6、「神谕之晶」x4、「莫拉硬币」x8，有概率获赠「新春宠物蛋」x1、「新春头饰兑换券」x1、「新春时装兑换券」x1。',}",
  [3003668] = "{id=3003668,NameZh='噼啪波利弹',Icon='item_12640',Type=61,UseMode=31176,MaxNum=99999,SellPrice=100,Desc='轻轻一碰便会发出噼啪声响的神奇炮弹，可以用它换些特别的小礼物~',ExistTimeType=2,ExistTime='2021-03-01 05:00:00',}",
  [3003669] = "{id=3003669,NameZh='新春头饰兑换券',Icon='item_6570',Type=61,UseMode=31178,MaxNum=99999,SellPrice=100,Desc='使用之后可以兑换任意一件往期春节系列头饰哦~',ExistTimeType=2,ExistTime='2021-03-01 05:00:00',}",
