  [3003680] = "{id=3003680,NameZh='星辰使者·天玑',Icon='item_3003680',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000020}},Desc='天空歌剧院里有一位奇怪的客人，只有守护灵小姐演唱的时候他才会出现，并为守护灵送上999朵玫瑰花。只是，连歌剧院都不知道守护灵小姐什么时候才会来演唱，他是怎么准确地预知未来呢？',TFValidDate='2021-05-13 05:00:00',ValidDate='2021-05-16 05:00:00',MainColor='22d6d0FF',}",
