  [3003700] = "{id=3003700,NameZh='追星星的少年',Icon='item_3003680',Type=501,MaxNum=99,SellPrice=100,Desc='宇宙里诞生的神明，在无数条时间线里与猎户座的守护灵擦肩而过，从此成为了一个追星星的少年。',TFValidDate='2021-05-13 05:00:00',ValidDate='2021-05-16 05:00:00',MainColor='5d32faFF',}",
  [3003701] = "{id=3003701,NameZh='猎户座少女',Icon='item_3003690',Type=501,MaxNum=99,SellPrice=100,Desc='猎户座是天空中最明亮的星座，传说猎户座的守护灵是一位少女，她时常在空旷的星座里巡游，专心的守护自己的家园。',TFValidDate='2021-05-13 05:00:00',ValidDate='2021-05-16 05:00:00',MainColor='5d32faFF',}",
