  [3003710] = "{id=3003710,NameZh='银河英雄·天玑',Icon='item_3003710',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='旧星历2000年，宇宙发生了一场大战，黑骑士率领无首部队袭击了人类赖以生存的家园。危机之中，岚将军牺牲自己的生命，呼唤宇宙共鸣阻挡敌人的入侵。年轻的将军发现自己的精神并未消亡，而是与宇宙意志融为一体，成为广阔宇宙的一部分永远地保护着人类。他的传说在宇宙里广为流传，这就是银河英雄的故事。',TFValidDate='2021-05-13 05:00:00',ValidDate='2021-05-16 05:00:00',MainColor='2a87ffFF',}",
