  [3003790] = "{id=3003790,NameZh='七分鸡',Icon='item_3003790',Type=90,MaxNum=1,SellPrice=100,AdventureSort=21,AdventureValue=1,AdventureReward={buffid={63000030}},Condition=8,Desc='七分鸡是最严格的健康减脂大师。它随身携带低脂食材，并时时监督冒险者：管住嘴，迈开腿，七分饱腹最完美！',}",
  [3003791] = "{id=3003791,NameZh='梦魇小丑',Icon='item_3003791',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10380,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='梦魇小丑悄悄藏在睡帽之下，一声不吭地把噩梦都吃掉，只剩下瑰丽的美梦留在你记忆里的童话王国。',}",
  [3003792] = "{id=3003792,NameZh='睡衣派对帽',Icon='item_3003792',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10381,AdventureValue=1,StorageReward={buffid={80012840}},Condition=8,Desc='仿佛巫师装束一般带着尖尖头的帽子，点燃所有幻想派对的激情：不错，欢乐的时光，现在刚刚开始哟！',}",
  [3003793] = "{id=3003793,NameZh='兰花红茶',Icon='item_3003793',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10382,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='据说顶级的红茶带有兰花香气。现在在眉间盛开的花朵，是不是被这杯热茶的馥郁浓香所培育出来的呢？',}",
  [3003794] = "{id=3003794,NameZh='威严的证明',Icon='item_3003794',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10383,AdventureValue=1,StorageReward={buffid={80012630}},Condition=8,Desc='奔跑！不可停滞不前！吾等正是守卫此处的胡桃夹子卫兵，为了保护心爱之人，必将奋不顾身！',}",
  [3003795] = "{id=3003795,NameZh='追逐白兔',Icon='item_3003795',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10384,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='“快点、快点！要来不及了！”总是慌慌张张的小兔子啊，为了追逐面前永远够不到的胡萝卜，今天也充满活力地继续奔跑呢。',}",
  [3003796] = "{id=3003796,NameZh='隐匿时钟',Icon='item_3003796',Type=810,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=10385,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='当指针无声转至12点，就会有各种神奇的事情发生。日与夜交替的这一个瞬间，正是逢魔的刹那。',}",
  [3003797] = "{id=3003797,NameZh='豚豚救生圈',Icon='item_3003797',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7131,AdventureValue=1,StorageReward={buffid={80012930}},Condition=8,Desc='河豚造型的救生圈，像河豚一样鼓起来的时候就可以正常使用啦！',}",
  [3003798] = "{id=3003798,NameZh='冲浪少年',Icon='item_3003798',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7132,AdventureValue=1,StorageReward={buffid={80012920}},Condition=8,Desc='今天天气正好，一起去克克魔海滩冲浪吧~~“大鲨鱼来咯！”',}",
  [3003799] = "{id=3003799,NameZh='日光浴',Icon='item_3003799',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7133,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='悠闲的假期，在海滩上享受明媚的阳光吧！',}",
  [3003800] = "{id=3003800,NameZh='巫骨面',Icon='item_3003800',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7144,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='先祖祭祀使用的骨质面具，克魔岛大祭司代代相传的宝物。',}",
  [3003801] = "{id=3003801,NameZh='唤潮者',Icon='item_3003801',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7145,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='一只神奇的魔法海螺，吹响它可以听到海风与海浪的声音。',}",
  [3003802] = "{id=3003802,NameZh='捕鱼达人',Icon='item_3003802',Type=810,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=7146,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='克魔岛的岛民与海为邻，也依靠大海谋生，快看看今天的收获如何吧！“我可是克魔岛最好的渔夫！”',}",
  [3003810] = "{id=3003810,NameZh='绮境乐园·长剑',Icon='item_3003810',Type=180,MaxNum=99,SellPrice=100,AdventureSort=100022,AdventureValue=1,Condition=8,Desc='克魔岛出品的庆典纪念品，据说是仿照传说中勇者的配剑制成的武器——但总觉得这种说法不太可信的样子。',LoadShowSize=1,}",
  [3003811] = "{id=3003811,NameZh='绮境乐园·短剑',Icon='item_3003811',Type=250,MaxNum=99,SellPrice=100,AdventureSort=100022,AdventureValue=1,Condition=8,Desc='克魔岛出品的庆典纪念品，据说是仿照克魔岛最大流氓团体“美男团”团长哈兹的短剑制成——哈兹：不传谣，不信谣，我玩弓的。',LoadShowSize=1,}",
  [3003812] = "{id=3003812,NameZh='绮境乐园·拳套',Icon='item_3003812',Type=290,MaxNum=99,SellPrice=100,AdventureSort=100022,AdventureValue=1,Condition=8,Desc='克魔岛出品的庆典纪念品，据说戴上后可以释放传说中的“超必杀·喵喵拳”——如果释放不了，至少可以让你变得更可爱。',LoadShowPose={0,0.35,0},}",
  [3003813] = "{id=3003813,NameZh='绮境乐园·拳刃',Icon='item_3003813',Type=200,MaxNum=99,SellPrice=100,AdventureSort=100022,AdventureValue=1,Condition=8,Desc='克魔岛出品的庆典纪念品，设计初衷是云端城堡的模型，由于工匠的疏忽导致屋顶过于尖锐，转而被当作“拆信刀”出售。',LoadShowPose={0,0.35,0},}",
  [3003814] = "{id=3003814,NameZh='绮境乐园·盾',Icon='item_3003814',Type=510,MaxNum=99,SellPrice=100,AdventureSort=100022,AdventureValue=1,Condition=8,Desc='克魔岛出品的庆典纪念品，盾面上图案所表达的信息是个谜，据说破解的人可以获知关于克魔岛的秘密——“嘿，有谁看到我的填字游戏了吗？”',}",
  [3003815] = "{id=3003815,NameZh='绮境乐园·斧',Icon='item_3003815',Type=230,MaxNum=99,SellPrice=100,AdventureSort=100022,AdventureValue=1,Condition=8,Desc='克魔岛出品的庆典纪念品，这把看上去粉嫩可爱的斧子总给人一种很危险的感觉——毕竟穿的越粉，打人越狠。',}",
  [3003816] = "{id=3003816,NameZh='绮境乐园·矛',Icon='item_3003816',Type=170,MaxNum=99,SellPrice=100,AdventureSort=100022,AdventureValue=1,Condition=8,Desc='克魔岛出品的庆典纪念品，据说勇士团团长、克魔岛第一美男阿尔泰曾想在勇士团列装这款长矛，但因某种原因被制止了——已入选A.W.980年度猛男最爱武器榜单。',LoadShowSize=1,LoadShowPose={0,-0.35,0},}",
  [3003817] = "{id=3003817,NameZh='绮境乐园·书',Icon='item_3003817',Type=240,MaxNum=99,SellPrice=100,AdventureSort=100022,AdventureValue=1,Condition=8,Desc='克魔岛出品的庆典纪念品，记载了许多克魔岛流传的童话故事，是极佳的睡前读物——“骑士和恶龙幸福的生活在了一起……”这是什么意思？',LoadShowSize=2.5,LoadShowPose={0,0.35,0},}",
  [3003818] = "{id=3003818,NameZh='绮境乐园·琴',Icon='item_3003818',Type=260,MaxNum=99,SellPrice=100,AdventureSort=100022,AdventureValue=1,Condition=8,Desc='克魔岛出品的庆典纪念品，无需拨动琴弦，只要按下按钮，就会循环播放可爱的童谣哦——甚至还有炫酷的走马灯！',LoadShowSize=1.5,LoadShowPose={0,0.75,0},}",
  [3003819] = "{id=3003819,NameZh='绮境乐园·鞭',Icon='item_3003819',Type=270,MaxNum=99,SellPrice=100,AdventureSort=100022,AdventureValue=1,Condition=8,Desc='克魔岛出品的庆典纪念品，前方的转轮在绳索的牵引下收放自如，是深受孩子们喜爱的新奇玩具——但也有来自天水之国的游客声称它的设计灵感来自该国传统玩具：剑玉。',}",
  [3003820] = "{id=3003820,NameZh='绮境乐园·杖',Icon='item_3003820',Type=190,MaxNum=99,SellPrice=100,AdventureSort=100022,AdventureValue=1,Condition=8,Desc='克魔岛出品的庆典纪念品，按下按钮会发出“变身~”的音效和“Blingbling”的闪光——别试了，孩子，男孩子是没法变身成魔法少女的！',LoadShowSize=1,LoadShowPose={0,0.3,0},}",
  [3003821] = "{id=3003821,NameZh='绮境乐园·弓',Icon='item_3003821',Type=210,MaxNum=99,SellPrice=100,AdventureSort=100022,AdventureValue=1,Condition=8,Desc='克魔岛出品的庆典纪念品，过去每个克魔岛男孩都想拥有一把自己的弓，直到它的出现——现在每个克魔岛女孩都想拥有一把自己的弓。',LoadShowSize=1,LoadShowPose={0,0.3,0},}",
  [3003822] = "{id=3003822,NameZh='绮境乐园·锤',Icon='item_3003822',Type=220,MaxNum=99,SellPrice=100,AdventureSort=100022,AdventureValue=1,Condition=8,Desc='克魔岛出品的庆典纪念品，由于是充气玩具，所以分量很轻，非常安全——前提是不要往里面充可燃气体。',LoadShowSize=1,}",
  [3003823] = "{id=3003823,NameZh='绮境乐园·狐尾草',Icon='item_3003823',Type=190,MaxNum=99,SellPrice=100,AdventureSort=100022,AdventureValue=1,Condition=8,Desc='克魔岛出品的庆典纪念品，豪华版彩虹棉花糖，由于外形酷似狐尾草也会被多兰族当作武器使用——再也不用担心打架的时候肚子饿了！',LoadShowSize=1,}",
  [3003824] = "{id=3003824,NameZh='绮境乐园·风魔轮',Icon='item_3003824',Type=300,MaxNum=99,SellPrice=100,AdventureSort=100022,AdventureValue=1,Condition=8,Desc='克魔岛出品的庆典纪念品，这个陀螺在旋转时呈现的色彩如同绚烂的彩红一样——别盯着看，会晕的！',LoadShowPose={0,0.35,0},}",
  [3003825] = "{id=3003825,NameZh='绮境乐园·手枪',Icon='item_3003825',Type=310,MaxNum=99,SellPrice=100,AdventureSort=100022,AdventureValue=1,Condition=8,Desc='克魔岛出品的庆典纪念品，虽然看起来非常可爱，却是深受枪手喜爱的武器——毕竟谁能拒绝一把会吐泡泡的枪呢？',}",
  [3003826] = "{id=3003826,NameZh='绮境乐园·来复枪',Icon='item_3003826',Type=320,MaxNum=99,SellPrice=100,AdventureSort=100022,AdventureValue=1,Condition=8,Desc='克魔岛出品的庆典纪念品，这把水枪激射的水流会让你成为打水仗时全场瞩目的焦点——友情提示，做个善良的人，别加开水。',LoadShowSize=1.5,LoadShowRotate=60,LoadShowPose={0,-0.1,0},}",
  [3003827] = "{id=3003827,NameZh='美梦绒绒帽',Icon='item_3003827',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=7147,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='甜心棉绒制成的帽子，不仅非常保暖，还能为它的主人编织甜美的梦境。但无论是原材料，还是制作工艺，都只能在幻想乡找到。冒险者，你赚大啦！',}",
  [3003828] = "{id=3003828,NameZh='轻吻河豚',Icon='item_3003828',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7134,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='河豚不会在生气的时候亲吻喜欢的人，因为那样会刺伤对方！',}",
  [3003829] = "{id=3003829,NameZh='海鸥水手',Icon='item_3003829',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=7135,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='一只梦想成为船员的海鸥，最宝贵的东西是“派罗船长”送给它的水手帽。',}",
  [3003830] = "{id=3003830,NameZh='浪潮勇士·水',Icon='item_3003830',Type=501,Quality=4,MaxNum=99,SellPrice=100,StorageReward={buffid={82000060}},Desc='生于浪潮之中的少年，被赋予勇士之名，坚守着守护海岛的职责。',}",
