  [3003840] = "{id=3003840,NameZh='雨林之歌·风',Icon='item_3003840',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012840}},Desc='密林之中传来悠远的歌谣，那是颂唱古代英雄的史诗，那是被季风抚慰的勇士。',}",
