  [3004060] = "{id=3004060,NameZh='不思议国度头饰兑换券',Icon='item_3004060',Type=61,UseMode=31229,MaxNum=99999,SellPrice=100,Desc='使用之后可以兑换任意一件不思议国度系列头饰哦~',Feature=1,}",
  [3004061] = "{id=3004061,NameZh='狼的盛宴',Icon='item_3004061',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15479,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='“外婆外婆，你的嘴巴为什么这么大呀？”“嘴巴大是为了……能一口把你吞下呀！”——所以，今天的狼外婆吃到小红帽了吗？',Feature=1,TFValidDate='2021-06-13 05:00:00',ValidDate='2021-06-16 05:00:00',LoadShowPose={0,0.3,0},}",
  [3004062] = "{id=3004062,NameZh='凶凶尾巴书',Icon='item_3004062',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15480,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='住手！不许动！不许打开这本书！如果打开的话，你就会看到一只凶凶的小狼张牙舞爪！什么，更想打开了？……不、不要过来啊啊啊啊~',Feature=1,TFValidDate='2021-06-13 05:00:00',ValidDate='2021-06-16 05:00:00',LoadShowRotate=180,LoadShowPose={0,0.4,0},}",
  [3004063] = "{id=3004063,NameZh='崽狼快乐篮',Icon='item_3004063',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15481,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='小狼崽子能有什么坏心眼呢？它不过是想吃吃奶嘴，看看蝴蝶，在安稳温暖的摇篮中熟睡，等待着自己慢慢成长。',Feature=1,TFValidDate='2021-06-13 05:00:00',ValidDate='2021-06-16 05:00:00',LoadShowPose={0,0.1,0},}",
  [3004064] = "{id=3004064,NameZh='白兔萨克斯',Icon='item_3004064',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15482,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='一二一、抬高腿！今天的白兔先生也一边吹着萨克斯，一边撒下一路的小音符哟！',Feature=1,TFValidDate='2021-06-13 05:00:00',ValidDate='2021-06-16 05:00:00',LoadShowPose={-0.1,0.5,0.3},}",
  [3004065] = "{id=3004065,NameZh='生命使徒',Icon='item_3004065',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15483,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='花朵盛开，然后凋谢。小鸟飞来，然后飞走。一切都是徒劳无功吗？当然不是。在看似重复的循环之中，孕育着完全不同的生命。',Feature=1,TFValidDate='2021-06-13 05:00:00',ValidDate='2021-06-16 05:00:00',LoadShowPose={0,0.5,0.3},}",
  [3004066] = "{id=3004066,NameZh='幻境呼唤者',Icon='item_3004066',Type=810,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=15484,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='盛放的花朵引来鸟儿纵情歌唱，飘落的羽毛集结为光辉翅膀。以它为翼，飞向不可思议的奇幻国度，却不知究竟是远方在呼唤着我，还是我的内心在呼唤远方？',Feature=1,TFValidDate='2021-06-13 05:00:00',ValidDate='2021-06-16 05:00:00',LoadShowRotate=160,LoadShowPose={0.3,0.3,-1},}",
  [3004070] = "{id=3004070,NameZh='异次元扭蛋机头饰礼盒',Icon='item_1000287',Type=30,Quality=2,MaxNum=9999,SellPrice=100,Desc='来自异次元扭蛋机的馈赠，使用时候可以自选获得「迪士尼公主头饰兑换券」x1，或者「米奇和朋友们头饰兑换券」x1',Feature=1,Delete=3004070}",
  [3004071] = "{id=3004071,NameZh='骑士感恩礼',Icon='item_3003137',Type=30,MaxNum=9999,SellPrice=100,Desc='某个倒霉骑士留给你的礼物，打开之后必定获得「料理兑换券」x1、「迪士尼扭蛋币」x6，同时，获得以下奖励中的一种：「闪耀的符文石」x1、「光洁的符文石」x1、「神谕之尘」x5、「神谕之晶」x5、「祈祷晶片包」x2、「玛丝黛拉种子」x1',Feature=1,Delete=3004071}",
