  [3004310] = "{id=3004310,NameZh='上古遗物材料礼盒',Icon='item_3003303',Type=30,Quality=4,MaxNum=99999,SellPrice=100,Desc='装着上古遗物材料的礼盒，使用后必定获得其中一个：「变形头盔的碎片」x1、「常青槲寄生」x1、「天地树琥珀」x1。',}",
  [3004470] = "{id=3004470,NameZh='微醺夏日[1]',Icon='item_3004470',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9783,AdventureValue=1,StorageReward={buffid={82000260}},Condition=8,Desc='“加点海的泡沫，星的幻影，光的碎片，摇一摇，晃一晃……嘭！”酷酷的章鱼酒保独创的流砂星光特调，盛情邀请各位游客来品一品其中滋味~',TFValidDate='2021-08-01 05:00:00',ValidDate='2021-08-01 05:00:00',LoadShowPose={0,0,0},}",
  [3004471] = "{id=3004471,NameZh='虹色倾情',Icon='item_3004471',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9784,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='属于酷暑的最美好的回忆是什么？是甜甜的波利汽水的味道！只要轻轻啜饮一口，就能看见被浪花折射出的七色彩虹哦！',TFValidDate='2021-08-01 05:00:00',ValidDate='2021-08-01 05:00:00',LoadShowRotate=350,LoadShowPose={-0.5,0.7,1},}",
  [3004472] = "{id=3004472,NameZh='盛夏嬉游',Icon='item_3004472',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9785,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='“居然用冰淇淋做诱饵，耍赖……放了我，下次我一定不会中陷阱了，呜呜呜……”不管多少次都会上钩的小河豚赛蒙的第115次失利，怎么才能等到它认输的那天呢？',TFValidDate='2021-08-01 05:00:00',ValidDate='2021-08-01 05:00:00',LoadShowRotate=180,}",
  [3004473] = "{id=3004473,NameZh='清凉椰之梦',Icon='item_3004473',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9786,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='在炎炎盛夏，畅饮一口清凉的椰子水，乘着轻飘飘的游泳圈，漂浮在一望无际的湛蓝海面上，做一场散发出冰凉清甜的椰子香气的美梦。',TFValidDate='2021-08-01 05:00:00',ValidDate='2021-08-01 05:00:00',LoadShowRotate=20,LoadShowPose={0.1,0.5,0.2},}",
  [3004474] = "{id=3004474,NameZh='冰爽柠香',Icon='item_3004474',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9787,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='“只要在薄荷冰沙上放一小片柠檬，然后躲在一旁静静地等候……看！抓到了一只热到融化的小波利！”',TFValidDate='2021-08-01 05:00:00',ValidDate='2021-08-01 05:00:00',LoadShowRotate=340,LoadShowPose={0,0.3,0.5},}",
  [3004475] = "{id=3004475,NameZh='激浪狂鲨',Icon='item_3004475',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9788,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='热爱冲浪的神秘魔法师用魔法改造的盾牌，可以作为冲浪板使用。像勇往直前的鲨鱼一样，绽放夏日激情，迎着海浪冲刺吧！',TFValidDate='2021-08-01 05:00:00',ValidDate='2021-08-01 05:00:00',LoadShowRotate=160,LoadShowPose={0,0.5,-0.2},}",
  [3004476] = "{id=3004476,NameZh='动感一夏',Icon='item_3004476',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9074,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='动次打次、动次打次！跟随动感的节拍一起摇摆，抖落热情似火的夏夜狂欢！戴上这副属于南国盛夏的动感眼镜，你就是整片海滩上最靓的DJ！',TFValidDate='2021-08-01 05:00:00',ValidDate='2021-08-01 05:00:00',LoadShowRotate=345,LoadShowPose={0,0.3,0.5},}",
  [3004490] = "{id=3004490,NameZh='霜炎交响曲',Icon='item_3004490',Type=810,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=10458,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='冰霜与熔炎的交织，随着星辰、钢铁与羽翼在天空中挥洒，谱成一曲荡气回肠的交响曲。',Feature=1,TFValidDate='2023-03-25 05:00:00',ValidDate='2023-04-01 05:00:00',}",
  [3004500] = "{id=3004500,NameZh='松赞的调查状',Icon='item_900009',Type=48,MaxNum=1,SellPrice=100,Desc='松赞啊，松赞，你可长点心吧，每天到处跑，不记事。调查他会有什么有用的线索吗？\n（使用后可以获得一个调查任务）',ExistTimeType=2,ExistTime='2021-07-27 05:00:00',}",
  [3004501] = "{id=3004501,NameZh='调查币',Icon='item_700180',Type=61,UseMode=31234,MaxNum=99999,SellPrice=100,Desc='使用之后可以去兑换七个不同人物调查状哦，听听他们是什么描述这件离奇的案件的吧！（冒险家每天在里奇这里会得到一个调查币，每个调查状只能兑换一次哦）',ExistTimeType=2,ExistTime='2021-07-27 05:00:00',}",
  [3004502] = "{id=3004502,NameZh='莎乐美的证词',Icon='item_3004250',Type=64,MaxNum=99999,SellPrice=100,Desc='里奇每过一段时间似乎都会消失几天呢~这是为什么呢……难道说，里奇有生理期吗？',ExistTimeType=2,ExistTime='2021-08-01 05:00:00',}",
  [3004503] = "{id=3004503,NameZh='咕噜的证词',Icon='item_3004250',Type=64,MaxNum=99999,SellPrice=100,Desc='我上次有见到一个奇怪的波利！居然、长着两条腿！长着腿的波利！',ExistTimeType=2,ExistTime='2021-08-01 05:00:00',}",
  [3004504] = "{id=3004504,NameZh='多利亚的证词',Icon='item_3004250',Type=64,MaxNum=99999,SellPrice=100,Desc='其实，我有件事一直藏在心里没说……我，我有一次偶然遇到里奇，他好像变了个人似的，整个人特别粗暴。我和平时一样跟他打招呼，结果他二话不说就要攻击我……但是第二天里奇又变回原来的里奇了。如果不是逃跑路上摔了一跤留下疤痕，我真要以为自己是做梦了……',ExistTimeType=2,ExistTime='2021-08-01 05:00:00',}",
  [3004505] = "{id=3004505,NameZh='帕兰的证词',Icon='item_3004250',Type=64,MaxNum=99999,SellPrice=100,Desc='……其实，恶魔瑞克啊，有自己的弱点哦……据说，他有喜欢的对象，而且超级痴情的……难以想象对吧……',ExistTimeType=2,ExistTime='2021-08-01 05:00:00',}",
  [3004600] = "{id=3004600,NameZh='昏睡魔菇',Icon='item_3004600',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10455,AdventureValue=1,StorageReward={buffid={80012840}},Condition=8,Desc='“1个冰域龙鳞、2个不死心脏、3朵曼陀罗再加4枝雪覆花，放入坩埚用蒸馏水浸没大火炖煮7个小时后冷却，即可获得……zZzZzZ”',Feature=1,TFValidDate='2021-09-15 05:00:00',ValidDate='2021-09-20 05:00:00',LoadShowPose={0,0.3,0},}",
  [3004601] = "{id=3004601,NameZh='陌生人假面',Icon='item_3004601',Type=830,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10456,AdventureValue=1,StorageReward={buffid={80012630}},Condition=8,Desc='来自学院前辈的赠礼，只要戴上这幅眼罩即便再熟悉你的人也认不出你的本来面目，非常适合某些需要隐藏身份的行动（我庄严宣誓我在做好事！）。',Feature=1,TFValidDate='2021-09-01 05:00:00',ValidDate='2021-09-06 05:00:00',LoadShowPose={0,0.3,0},}",
  [3004602] = "{id=3004602,NameZh='咬咬博士',Icon='item_3004602',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10457,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='“咔哒咔哒！吼……咔咔咔咔咔！（瞪眼）”。一本看起来十分凶恶的魔法书，如果不想手被咬伤的话还是离它远点吧。',Feature=1,TFValidDate='2021-09-02 05:00:00',ValidDate='2021-09-09 05:00:00',LoadShowRotate=160,LoadShowPose={0,0.2,-0.5},}",
