  [3004604] = "{id=3004604,NameZh='纯真许愿币',Icon='item_3004604',Type=61,UseMode=31252,MaxNum=99999,SellPrice=1,Desc='对美好事物的向往，对美好未来的憧憬。由学生们的纯真心愿而凝结成的特殊硬币，据说扔进许愿池中可100%实现一个愿望。',GetLimit={limit={[999]={200,0}},source={22},type=4},ExistTimeType=2,ExistTime='2021-10-01 05:00:00',Feature=1,}",
