  [3004610] = "{id=3004610,NameZh='成长快乐礼包',Icon='item_12915',Type=30,MaxNum=99999,SellPrice=100,Desc='打开后可获得：「纯真许愿币」x1、「坠星陨铁」x1、「波利成长秘药」x1，有概率获得以下道具中的一种：：「B格猫福利券·Ⅰ」x5、「B格猫福利券·宴」x5、「拾光邀请函」x5、「神谕之尘」x5、「神谕之晶」x5、「光洁的符文石」x2、「古拉姆晶末」x20、「金质勋章」x5、「尘封的符文袋·Ⅰ」x2、「好运币」x5、「玛丝黛拉种子」x1。',Feature=1,}",
  [3004611] = "{id=3004611,NameZh='黄金茶会礼包',Icon='item_3000165',Type=30,MaxNum=99999,SellPrice=100,Desc='打开后有概率获得以下道具中的一种：「莫拉硬币」x4、「神谕之尘」x4、「神谕之晶」x4。必定获得：Zeny x200000、「纯真许愿币」x60。',Feature=1,}",
  [3004612] = "{id=3004612,NameZh='校园系列往期头饰自选礼盒',Icon='item_6745',Type=30,MaxNum=99999,SellPrice=100,Desc='使用之后可以自选一个往期活动产出的「校园」主题头饰及图纸：「逃学大王帽图纸」x1、「飞行的智慧图纸」x1、「逢考必过图纸」x1、「万能公式图纸」x1、「草莓棉花糖」x1。',Feature=1,}",
  [3004620] = "{id=3004620,NameZh='美妙合奏',Icon='item_3004620',Type=840,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9789,AdventureValue=1,StorageReward={buffid={82000240}},Condition=8,Desc='满面慈祥、蓄着胡子的安可老先生，掌握了控制俏皮的小波利们唱诗音调高度的奇妙方法，只需轻轻扯动手中的丝线，就能演绎一出魅力四射的和谐协奏曲。',TFValidDate='2021-09-01 05:00:00',ValidDate='2021-09-01 05:00:00',LoadShowPose={0,0,0},}",
  [3004621] = "{id=3004621,NameZh='迷你指挥家[1]',Icon='item_3004621',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9790,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='“那边的小家伙注意！别以为只张口不发声我听不出来~”严肃认真的萌萌小黑兔指挥温洁妮，每次进入指挥家状态时，周身都会散发出令人肃然起敬的神圣光辉。',TFValidDate='2021-09-01 05:00:00',ValidDate='2021-09-01 05:00:00',LoadShowPose={0,0.1,0},}",
  [3004622] = "{id=3004622,NameZh='颂者的乐章',Icon='item_3004622',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9791,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='记录了从古至今一切颂者诗篇的魔法书籍，只要点触开启，便能与亘古的颂者产生共鸣，随之颂唱出有着摄人心魄魔力的乐章。',TFValidDate='2021-09-01 05:00:00',ValidDate='2021-09-01 05:00:00',LoadShowRotate=170,}",
  [3004623] = "{id=3004623,NameZh='唱诗礼帽的秘密[1]',Icon='item_3004623',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9792,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='“嘿嘿，只要藏在这个礼帽下面，他们就看不见我啦~”正在因为捉迷藏中的巨大优势而沾沾自喜的小波利，似乎丝毫没有注意到自己已经露出恶魔的小“尾巴”了。',TFValidDate='2021-09-01 05:00:00',ValidDate='2021-09-01 05:00:00',}",
  [3004624] = "{id=3004624,NameZh='圣歌悠扬',Icon='item_3004624',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9793,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='即使是初学者也易于上手的精美六孔竖笛，演奏出纯正清丽的音色，如同朦胧晨曦中穿透晨雾的第一缕温柔阳光，第一声清脆鸟鸣。',TFValidDate='2021-09-01 05:00:00',ValidDate='2021-09-01 05:00:00',LoadShowPose={-0.2,0.65,0.5},}",
  [3004625] = "{id=3004625,NameZh='被偷窥的诗谱',Icon='item_3004625',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9794,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='“嗯，貌似很有趣，让我看看……”在唱诗班成员唱诵旋律时冒出的捣蛋鬼尼克斯，总是恰到好处地遮挡住冒险家望向诗谱的视线。',TFValidDate='2021-09-01 05:00:00',ValidDate='2021-09-01 05:00:00',LoadShowPose={0,0.3,0},}",
  [3004626] = "{id=3004626,NameZh='萨克斯弹弹乐',Icon='item_3004626',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9075,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='“噗哇……以后再也不躲在萨克斯里了~”藏身在萨克斯管中的小恶魔波利，似乎被闷坏了，软弹的身躯和红红的脸颊，让人忍不住想要欺负一下。',TFValidDate='2021-09-01 05:00:00',ValidDate='2021-09-01 05:00:00',LoadShowRotate=180,LoadShowPose={0,0.2,0},}",
  [3004630] = "{id=3004630,NameZh='盛夏时光·夕照',Icon='item_3004630',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000020}},Desc='盛夏时光中，最难忘的是海岸边的夕照。在那一期一会的景致中，少年背对着将海水染成火焰色彩的艳丽夕阳，向着你大方招手，健气的呼声萦绕于耳畔。“明年，还想和你一起来打水仗！”',Feature=1,TFValidDate='2021-08-13 05:00:00',ValidDate='2021-08-16 05:00:00',MainColor='c53a07FF',}",
  [3004631] = "{id=3004631,NameZh='盛夏时光·青椰',Icon='item_3004630',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000020}},Desc='盛夏时光中，最难忘的是清甜的椰子水。在那一期一会的景致中，少年捧着大个儿的椰子，随手拭去额角的汗水，向着你大方招手，健气的呼声萦绕于耳畔。“明年，还想和你一起来打水仗！”',Feature=1,TFValidDate='2021-08-13 05:00:00',ValidDate='2021-08-16 05:00:00',MainColor='14ac8aFF',}",
  [3004632] = "{id=3004632,NameZh='盛夏时光·碧海',Icon='item_3004630',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000020}},Desc='盛夏时光中，最难忘的是无垠的碧海。在那一期一会的景致中，少年踏着浪花翻涌的碧色汪洋，向着你大方招手，健气的呼声萦绕于耳畔。“明年，还想和你一起来打水仗！”',Feature=1,TFValidDate='2021-08-13 05:00:00',ValidDate='2021-08-16 05:00:00',MainColor='2e2f9cFF',}",
  [3004633] = "{id=3004633,NameZh='盛夏时光·甜柠',Icon='item_3004630',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000020}},Desc='盛夏时光中，最难忘的是散发着酸甜香气的柠檬汽水。在那一期一会的景致中，少年手提着泡沫涌动的柠檬汽水，闪烁着期望的目光，向着你大方招手，健气的呼声萦绕于耳畔。“明年，还想和你一起来打水仗！”',Feature=1,TFValidDate='2021-08-13 05:00:00',ValidDate='2021-08-16 05:00:00',MainColor='bfcc5fFF',}",
  [3004640] = "{id=3004640,NameZh='夏日追忆·夕照',Icon='item_3004640',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000020}},Desc='“你知道吗？如果对着海风许愿，它就会带着你的愿望走遍整个米德加尔特。”少女笃定地说出隐秘的话语，暖橘的夕照倒映在视野中，熔化成夏日最耀眼的回忆。',Feature=1,TFValidDate='2021-08-13 05:00:00',ValidDate='2021-08-16 05:00:00',MainColor='c53a07FF',}",
  [3004641] = "{id=3004641,NameZh='夏日追忆·青椰',Icon='item_3004640',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000020}},Desc='“你知道吗？如果对着海风许愿，它就会带着你的愿望走遍整个米德加尔特。”少女笃定地说出隐秘的话语，青翠的椰林倒映在视野中，熔化成夏日最耀眼的回忆。',Feature=1,TFValidDate='2021-08-13 05:00:00',ValidDate='2021-08-16 05:00:00',MainColor='128a32FF',}",
  [3004642] = "{id=3004642,NameZh='夏日追忆·碧海',Icon='item_3004640',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000020}},Desc='“你知道吗？如果对着海风许愿，它就会带着你的愿望走遍整个米德加尔特。”少女笃定地说出隐秘的话语，绀碧的海面倒映在视野中，熔化成夏日最耀眼的回忆。',Feature=1,TFValidDate='2021-08-13 05:00:00',ValidDate='2021-08-16 05:00:00',MainColor='3330dbFF',}",
  [3004643] = "{id=3004643,NameZh='夏日追忆·柠檬',Icon='item_3004640',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000020}},Desc='“你知道吗？如果对着海风许愿，它就会带着你的愿望走遍整个米德加尔特。”少女笃定地说出隐秘的话语，淡黄的柠檬汽水倒映在视野中，熔化成夏日最耀眼的回忆。',Feature=1,TFValidDate='2021-08-13 05:00:00',ValidDate='2021-08-16 05:00:00',MainColor='bfcc5fFF',}",
