  [3004650] = "{id=3004650,NameZh='盛夏晚霞',Icon='item_3004630',Type=501,MaxNum=99,SellPrice=100,Desc='夏日的日落来得晚，匆匆迟来的晚霞将天穹的尽头染成一片温柔的淡紫。在暮色四合中，少年的笑意像是被记忆染上了一层朦胧的光晕。',Feature=1,TFValidDate='2021-08-13 05:00:00',ValidDate='2021-08-16 05:00:00',MainColor='8121caFF',}",
  [3004651] = "{id=3004651,NameZh='夏日霞风',Icon='item_3004640',Type=501,MaxNum=99,SellPrice=100,Desc='日落时分，天际的紫霞随着晚风缓缓流动，如同纠缠在天际的丝绢。“要是能用晚霞织一条围巾就好了！”',Feature=1,TFValidDate='2021-08-13 05:00:00',ValidDate='2021-08-16 05:00:00',MainColor='8121caFF',}",
