  [3004660] = "{id=3004660,NameZh='消暑鸭舌帽·夕照',Icon='item_3004660',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='“夏日遮阳首选，自然是鸭舌帽啦……只不过，对鸭舌帽的鸭是不是有什么误解……？”满头问号的小鸭子莱达尔成为了鸭舌帽上夕照色墨镜的邻居，不知道他们能不能好好相处呢？',Feature=1,TFValidDate='2021-08-13 05:00:00',ValidDate='2021-08-16 05:00:00',LoadShowPose={0,0.8,0},MainColor='f3e16dFF',}",
