  [3004665] = "{id=3004665,NameZh='艳阳侦察兵·夕照',Icon='item_3004665',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='“鸭鸭出手侦查过了，前面就是一片椰子林，快去避暑吧，鸭鸭都热到融化了~”摇摇晃晃的小鸭子莱达尔，居住在夕阳橘色的遮阳帽上，协助主人探查树荫所在。不过，它怎么好像比主人还要怕热呢~',Feature=1,TFValidDate='2021-08-13 05:00:00',ValidDate='2021-08-16 05:00:00',LoadShowRotate=340,LoadShowPose={0,0.6,0},MainColor='4b3f5dFF',}",
  [3004666] = "{id=3004666,NameZh='艳阳侦察兵·碧海',Icon='item_3004665',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='“鸭鸭出手侦查过了，前面就是一片椰子林，快去避暑吧，鸭鸭都热到融化了~”摇摇晃晃的小鸭子莱达尔，居住在海浪碧色的遮阳帽上，协助主人探查树荫所在。不过，它怎么好像比主人还要怕热呢~',Feature=1,TFValidDate='2021-08-13 05:00:00',ValidDate='2021-08-16 05:00:00',LoadShowRotate=340,LoadShowPose={0,0.6,0},MainColor='a70c40FF',}",
