  [3004668] = "{id=3004668,NameZh='艳阳侦察兵·紫霞',Icon='item_3004665',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='“鸭鸭出手侦查过了，前面就是一片椰子林，快去避暑吧，鸭鸭都热到融化了~”摇摇晃晃的小鸭子莱达尔，居住在晚霞紫色的遮阳帽上，协助主人探查树荫所在。不过，它怎么好像比主人还要怕热呢~',Feature=1,TFValidDate='2021-08-13 05:00:00',ValidDate='2021-08-16 05:00:00',LoadShowRotate=340,LoadShowPose={0,0.6,0},MainColor='a1c0c2FF',}",
  [3004669] = "{id=3004669,NameZh='艳阳侦察兵头饰系列',Icon='item_3004669',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15525,AdventureValue=1,StorageReward={buffid={80012920}},Condition=8,Feature=1,TFValidDate='2021-08-13 05:00:00',ValidDate='2021-08-16 05:00:00',MainColor='X',}",
  [3004670] = "{id=3004670,NameZh='浅滩风情头饰兑换券',Icon='item_3004670',Type=61,UseMode=31246,MaxNum=99999,SellPrice=100,Desc='使用之后可以兑换任意一件浅滩风情系列头饰哦~',Feature=1,}",
  [3004671] = "{id=3004671,NameZh='热情沙堡',Icon='item_3004671',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15526,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='“喂，这是沙堡，不是游泳池啦~”可是，热晕的小鸭子莱达尔已经听不进去这些话语了，主人只能叹口气接纳，“算了，谁让我们是热情大方的沙堡呢~”',Feature=1,TFValidDate='2021-08-13 05:00:00',ValidDate='2021-08-16 05:00:00',LoadShowPose={0,0.2,0},}",
  [3004672] = "{id=3004672,NameZh='悠悠随心桶',Icon='item_3004672',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15527,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='“……还有小沙铲、沙滩皮球……海滩冒险的必备品，已经全都放进桶里了！”小鲨鱼西伦不明就里地探出头：原来，我也是其中的一部分吗？',Feature=1,TFValidDate='2021-08-13 05:00:00',ValidDate='2021-08-16 05:00:00',LoadShowRotate=170,LoadShowPose={0,0.3,-0.2},}",
  [3004673] = "{id=3004673,NameZh='心跳碰碰鲨',Icon='item_3004673',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15528,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='“331，332……”传说中只要连续顶球520下，心动的她就会出现在面前。小鲨鱼西伦铆足了劲儿，全副武装地朝着那个命运中的甜蜜相逢时刻高歌猛进。',Feature=1,TFValidDate='2021-08-13 05:00:00',ValidDate='2021-08-16 05:00:00',}",
  [3004674] = "{id=3004674,NameZh='霸气巡航者',Icon='item_3004674',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15529,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='螃蟹先生是海洋中最霸道的生物。“虽然我不是故意横着走的，但想要在潜航中模仿我绝对不行！”',Feature=1,TFValidDate='2021-08-13 05:00:00',ValidDate='2021-08-16 05:00:00',LoadShowPose={0,0.25,0},}",
  [3004675] = "{id=3004675,NameZh='漫舞翩跹',Icon='item_3004675',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15530,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='闪耀的光之蝶，盘旋环绕着热烈盛放的繁花，漫舞出翩跹的曲线。若是伸出指尖去触碰，便会感受到那蝶吻在指尖绽放零落，留下星星点点的斑驳光影。',Feature=1,TFValidDate='2021-08-13 05:00:00',ValidDate='2021-08-16 05:00:00',LoadShowPose={-0.25,0.55,0.7},}",
  [3004676] = "{id=3004676,NameZh='闪耀馈赠',Icon='item_3004676',Type=810,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=15531,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='用深海珊瑚和彩霞珍珠贝打造成的翅膀，闪耀着独属于海洋贝类的神秘渐变光泽。这是海洋对陆地的馈赠，是隐秘的海洋宇宙的专属造物。',Feature=1,TFValidDate='2021-08-13 05:00:00',ValidDate='2021-08-16 05:00:00',LoadShowSize=1.5,LoadShowRotate=170,LoadShowPose={0.3,0.2,-1},}",
  [3004677] = "{id=3004677,NameZh='上古遗物材料礼盒·浅滩风情',Icon='item_3003303',Type=30,Quality=4,MaxNum=99999,SellPrice=100,Desc='装着上古遗物材料的礼盒，使用后必定获得其中一个：「变形头盔的碎片」x1、「女武神的砾石」x1、「冥思之石」x1。',Feature=1,Delete=3004677}",
  [3004678] = "{id=3004678,NameZh='一小袋玉米粒',Icon='item_3635',Type=30,MaxNum=99999,SellPrice=100,Desc='装着玉米粒的袋子，打开之后随机获得「玉米粒」x1~5',ExistTimeType=2,ExistTime='2021-12-01 05:00:00',Feature=1,}",
  [3004680] = "{id=3004680,NameZh='小木锤',Icon='item_3001889',Type=30,UseMode=31043,MaxNum=99999,SellPrice=100,Desc='虽然是普通木制小锤，但是却能发挥巨大威力，真是惊人！“喂！这个不可以用来打人！”',ExistTimeType=2,ExistTime='2021-09-01 05:00:00',Feature=1,}",
  [3004681] = "{id=3004681,NameZh='真爱狩猎礼盒',Icon='item_3038',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='赠予参与了本次狩猎活动的冒险者的奖励，打开之后必定获得「B格猫福利券·宴」x6、Zeny x 150,000，以下奖励随机获得一种：「闪耀的符文石」x1、「光洁的符文石」x1、「神谕之尘」x5、「神谕之晶」x5、「祈祷晶片包」x2、「玛丝黛拉种子」x1',Feature=1,}",
  [3004682] = "{id=3004682,NameZh='真爱占卜礼盒',Icon='item_3901',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='恋爱占卜不仅可以收获真爱，还可以获得奖励哦~打开之后必定获得Zeny x 100,000、「坠星陨铁」x1、「波利成长秘药」x1、「高原坚木」x50、「九界原石」x2、「家居提货券」x2',Feature=1,}",
  [3004683] = "{id=3004683,NameZh='真爱告白礼盒',Icon='item_3000170',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='爱要大声告诉TA，然后带着你爱的TA，走遍米德加尔特浪漫的地方吧~！打开之后必定获得Zeny x 100,000，以下奖励随机获得一种：「天火碎片·锋锐型」x1、「真爱饰品自选礼盒」x1、「诺伦卡片」x50、「草莓棉花糖」x2、「魔力卡册」x1、「神谕之尘」x10、「神谕之晶」x10、「拾光邀请函」x10、「B格猫福利券·宴」x10',Feature=1,}",
