  [3004689] = "{id=3004689,NameZh='小木锤',Icon='item_3001889',Type=41,UseMode=31043,MaxNum=99999,SellPrice=100,Desc='虽然是普通木制小锤，但是却能发挥巨大威力，真是惊人！“喂！这个不可以用来打人！”',ExistTimeType=2,ExistTime='2021-12-01 05:00:00',Feature=1,}",
  [3004700] = "{id=3004700,NameZh='原味爆米花',Icon='item_3004700',Type=41,MaxNum=9999,SellPrice=100,Desc='香甜可口的原味爆米花，是追剧、挂机、谈恋爱的必备零食，食用之后可以获得2000000 JOB经验！',Feature=1,}",
  [3004701] = "{id=3004701,NameZh='玉米粒',Icon='item_3004701',Type=61,UseMode=31271,MaxNum=9999,SellPrice=100,Desc='新鲜饱满的玉米粒，是制作爆米花的必备食材。',GetLimit={limit={[999]={10,0}},source={22},type=4},ExistTimeType=2,ExistTime='2021-12-01 05:00:00',Feature=1,}",
