  [3004703] = "{id=3004703,NameZh='大大大鸡腿',Icon='item_3004703',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10481,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='能让味蕾尖叫的超级美味，人见人爱的鸡中至宝——其受欢迎程度不亚于快乐水。',Feature=1,TFValidDate='2021-10-25 05:00:00',ValidDate='2021-11-01 05:00:00',LoadShowRotate=160,LoadShowPose={0,0.5,-0.3},}",
  [3004704] = "{id=3004704,NameZh='孜然爆米花',Icon='item_3004704',Type=61,UseMode=31271,MaxNum=9999,SellPrice=100,Desc='孜然味的爆米花，咸味党的最爱。爆米花嘉年华组委会的「南南」正在收集它！',ExistTimeType=2,ExistTime='2021-12-01 05:00:00',Feature=1,}",
  [3004705] = "{id=3004705,NameZh='麻辣爆米花',Icon='item_3004705',Type=61,UseMode=31271,MaxNum=9999,SellPrice=100,Desc='麻辣味的爆米花，搭配碳酸饮料更过瘾。爆米花嘉年华组委会的「南南」正在收集它！',ExistTimeType=2,ExistTime='2021-12-01 05:00:00',Feature=1,}",
  [3004706] = "{id=3004706,NameZh='奶油爆米花',Icon='item_3004706',Type=61,UseMode=31271,MaxNum=9999,SellPrice=100,Desc='奶油味的爆米花，与原味相比，奶油味的甜味更加充足。爆米花嘉年华组委会的「南南」正在收集它！',ExistTimeType=2,ExistTime='2021-12-01 05:00:00',Feature=1,}",
  [3004707] = "{id=3004707,NameZh='焦糖爆米花',Icon='item_3004707',Type=61,UseMode=31271,MaxNum=9999,SellPrice=100,Desc='焦糖味的爆米花，虽然没剩下多少糖味了，但是那种独特的糖香味却更加吸引人。爆米花嘉年华组委会的「南南」正在收集它！',ExistTimeType=2,ExistTime='2021-12-01 05:00:00',Feature=1,}",
  [3004708] = "{id=3004708,NameZh='咸味礼盒',Icon='item_1000009',Type=41,MaxNum=99,SellPrice=100,Desc='咸味党的执着，对其余的冒险家使用后，你和TA都可以获得装有「孜然调味剂」、「辣椒调味剂」的「调味剂礼盒·咸」x1。（建议与异性好友互相使用哦~可以更快速得获得所有口味的调味剂！）',ItemTarget={range=10,type=3},ExistTimeType=2,ExistTime='2021-12-01 05:00:00',Feature=1,}",
  [3004709] = "{id=3004709,NameZh='甜味礼盒',Icon='item_1000010',Type=41,MaxNum=99,SellPrice=100,Desc='甜味党的信仰，对其余的冒险家使用后，你和TA都可以获得装有「奶油调味剂」、「焦糖调味剂」的「调味剂礼盒·甜」x1。（建议与异性好友互相使用哦~可以更快速得获得所有口味的调味剂！）',ItemTarget={range=10,type=3},ExistTimeType=2,ExistTime='2021-12-01 05:00:00',Feature=1,}",
  [3004710] = "{id=3004710,NameZh='上古宝藏',Icon='item_3002312',Type=30,Quality=2,MaxNum=9999,SellPrice=100,Desc='遗忘至今的上古宝藏，打开后必定获得「上古遗物精华」x1、「魔力树枝·梦幻」x2、「瓦特阿尔凡尘」x4，以及「随机MVP材料·梦幻」x2。',Feature=1,}",
  [3004711] = "{id=3004711,NameZh='调味剂礼盒·咸',Icon='item_3953',Type=30,MaxNum=9999,SellPrice=100,Desc='咸味党的执着，使用之后获得「玉米粒」x1，并且随机获得「孜然调味剂」x1或者「辣椒调味剂」x1。',ExistTimeType=2,ExistTime='2021-12-01 05:00:00',Feature=1,}",
  [3004712] = "{id=3004712,NameZh='调味剂礼盒·甜',Icon='item_3952',Type=30,MaxNum=9999,SellPrice=100,Desc='甜味党的执着，使用之后获得「玉米粒」x1，并且随机获得「奶油调味剂」x1或者「焦糖调味剂」x1。',ExistTimeType=2,ExistTime='2021-12-01 05:00:00',Feature=1,}",
  [3004713] = "{id=3004713,NameZh='调味剂自选福袋',Icon='item_1000239',Type=30,MaxNum=9999,SellPrice=100,Desc='不管你是咸味党还是甜味党，这个福袋满足你的所有，使用之后可以在以下调味剂中自选一种：「孜然调味剂」x1、「辣椒调味剂」x1、「奶油调味剂」x1、「焦糖调味剂」x1。',ExistTimeType=2,ExistTime='2021-12-01 05:00:00',Feature=1,}",
  [3004714] = "{id=3004714,NameZh='料理精粹',Icon='item_710030',Type=41,MaxNum=9999,SellPrice=100,ComposeID=4000081,Desc='神奇的道具，根据使用者的不同，将可以获得不同口味的礼盒。咸味党可以使用「料理精粹」x50获得「咸味礼盒」x1，甜味党可以使用「料理精粹」x50获得「甜味礼盒」x1。',GetLimit={limit={[999]={200,0}},source={22},type=4},ExistTimeType=2,ExistTime='2021-12-01 05:00:00',Feature=1,}",
