  [3004717] = "{id=3004717,NameZh='职业坐骑半价券',Icon='item_700174',Type=41,UseMode=31268,MaxNum=9999,SellPrice=100,Desc='一年一度的购物狂欢节，一年一次的半价购买坐骑的机会，错过这次，再等一年！使用之后可以打开「职业坐骑商店」，半价购买心仪的职业坐骑！',Feature=1,}",
