  [3004824] = "{id=3004824,NameZh='万圣糖果福袋',Icon='item_3635',Type=30,MaxNum=99999,SellPrice=100,Desc='尼夫海姆每年这个时候都会准备的福袋，送给每一位捣蛋鬼。打开后必定获赠「万圣糖果」x10、「莫拉硬币」x10。',Feature=1,}",
