  [3004826] = "{id=3004826,NameZh='美食节纪念礼盒',Icon='item_3038',Type=30,MaxNum=99999,SellPrice=100,Desc='那些错过的美好，终有重逢之时。打开后，自行选择获得以下奖励的一种：「鱼子酱寿司图纸」x1、「河豚料理师图纸」x1、「愤怒的魔锅蛋图纸」x1、「旋风锅铲」x1、「厨神之魂图纸」x1、「草莓棉花糖」x1。',Feature=1,}",
  [3004827] = "{id=3004827,NameZh='万圣糖果礼盒',Icon='item_3713',Type=30,MaxNum=99999,SellPrice=100,Desc='好吧好吧，拿走这个糖果礼盒，你们这些捣蛋鬼不要来捉弄我了。打开后必定获赠「万圣糖果」x10，0.01%概率获赠「深渊巡刑者」x1，随机获得以下金额的Zeny中的一种：100,000,000 Zeny、30,000,000 Zeny、10,000,000 Zeny、5,000,000 Zeny、3,000,000 Zeny、2,500,000 Zeny、2,000,000 Zeny、1,500,000 Zeny、1,000,000 Zeny！',Feature=1,}",
  [3004828] = "{id=3004828,NameZh='神谕补给箱',Icon='item_5753',Type=30,MaxNum=99999,SellPrice=100,Desc='装满了神谕附魔材料的补给箱，打开后，自行选择获得以下奖励的一种：「神谕之尘」x1、「神谕之晶」x1。',Feature=1,}",
  [3004829] = "{id=3004829,NameZh='美味小鱼干',Icon='item_3004829',Type=61,UseMode=31605,MaxNum=99999,SellPrice=100,Desc='想必没有喵能拒绝这口感，一口下去，能让味蕾尖叫……“啊！好好吃！”',ExistTimeType=2,ExistTime='2023-11-10 05:00:00',Feature=1,}",
  [3004832] = "{id=3004832,NameZh='祈祷晶片自选包·活动',Icon='item_3720',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='仅在特殊活动中产出。使用之后可以自行选择获得「攻击晶片」x1、「防御晶片」x1、「元素晶片」x1中的一种。',NoStorage=5,}",
  [3004840] = "{id=3004840,NameZh='秋之约定',Icon='item_3004840',Type=810,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=10476,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='“小蝴蝶小蝴蝶~我遵守约定来一起看落叶了喵~你在哪里呀喵~~你看，我特别让主人给我穿上了翅膀，这样就可以跟你一起飞了喵~~”',Feature=1,TFValidDate='2022-10-19 05:00:00',ValidDate='2022-10-26 05:00:00',}",
  [3004850] = "{id=3004850,NameZh='小幽灵万圣烛台',Icon='item_3004850',Type=810,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9795,AdventureValue=1,StorageReward={buffid={82000250}},Condition=8,Desc='摇曳的蓝色烛火中，似乎有一双双眼睛正在注视着热闹的万圣夜，你并没有看错，那不是普通的烛火，而是小幽灵们的灵魂之火！',TFValidDate='2021-10-01 05:00:00',ValidDate='2021-10-01 05:00:00',LoadShowRotate=170,LoadShowPose={0.1,0.4,-0.8},}",
  [3004851] = "{id=3004851,NameZh='捣蛋幽灵与南瓜派',Icon='item_3004851',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9796,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='请你吃个南瓜派，哎呀，不好意思，一不小心手滑了~',TFValidDate='2021-10-01 05:00:00',ValidDate='2021-10-01 05:00:00',LoadShowPose={0,0.4,0},}",
