  [3004854] = "{id=3004854,NameZh='布偶兔与南瓜烤饼',Icon='item_3004854',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9799,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='要尝尝布偶兔制作的南瓜烤饼吗？很好吃哦~不过，千万要小心……不要被南瓜烤饼给吃掉哦',TFValidDate='2021-10-01 05:00:00',ValidDate='2021-10-01 05:00:00',LoadShowPose={0,0.2,0},}",
