  [3004880] = "{id=3004880,NameZh='时尚枫潮·炽红',Icon='item_3004880',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000010}},Desc='“我的背带裤，时尚时尚最时尚~”哼着不着调的小曲，炽热的红色身影踏着滑板在曲折的小巷里灵巧地穿梭，他所到之处，片片枫叶随风乱舞。',Feature=1,TFValidDate='2022-07-14 05:00:00',ValidDate='2022-07-27 05:00:00',MainColor='d13935FF',}",
  [3004881] = "{id=3004881,NameZh='时尚枫潮·金棕',Icon='item_3004880',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000010}},StorageReward={buffid={82000010}},Desc='“我的背带裤，时尚时尚最时尚~”哼着不着调的小曲，明快的棕色身影踏着滑板在曲折的小巷里灵巧地穿梭，他所到之处，片片枫叶随风乱舞。',Feature=1,TFValidDate='2022-07-14 05:00:00',ValidDate='2022-07-27 05:00:00',MainColor='c76b08FF',}",
