  [3004921] = "{id=3004921,NameZh='喀嚓波利喵',Icon='item_3004921',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15546,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='喀嚓喀嚓，萌萌波利喵手中的相机闪着光，记录下枫叶飘落的每个浪漫瞬间~',Feature=1,TFValidDate='2022-07-14 05:00:00',ValidDate='2022-07-27 05:00:00',}",
  [3004922] = "{id=3004922,NameZh='旅行肥啾',Icon='item_3004922',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15547,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='今天的航向，是神秘的东方，还是遥远的西方？小肥啾在蘑菇伞上停驻，然后听见主人的回复：“不如哪儿也别去，留下来陪陪我吧。”',Feature=1,TFValidDate='2022-07-14 05:00:00',ValidDate='2022-07-27 05:00:00',LoadShowRotate=170,LoadShowPose={0,0.5,-0.3},}",
  [3004923] = "{id=3004923,NameZh='秋意野餐篮',Icon='item_3004923',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15548,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='“嘿咻，只要没人发现，这颗橡果就是我的了~”尾巴蓬蓬的松鼠自以为隐蔽地藏身在银杏叶片后，却不知沉甸甸的野餐篮早已出卖了它……',Feature=1,TFValidDate='2022-07-14 05:00:00',ValidDate='2022-07-27 05:00:00',LoadShowPose={0,0.3,0},}",
  [3004924] = "{id=3004924,NameZh='骨碌风车喵',Icon='item_3004924',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15549,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='骨碌骨碌，小小的纸风车旋转，悠远的时光，也在这一圈圈循环中悄然而散……',Feature=1,TFValidDate='2022-07-14 05:00:00',ValidDate='2022-07-27 05:00:00',LoadShowRotate=320,LoadShowPose={-0.4,0.4,0},}",
