  [3004982] = "{id=3004982,NameZh='滑稽先生的胡子',Icon='item_3004982',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10493,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='又到了一年最快乐的时光，知名搞笑艺人“滑稽先生”以自己为蓝本，制作了一副新假面。他希望这个世界上可以有更多的“滑稽先生”，为他人带来快乐。',Feature=1,TFValidDate='2021-12-25 05:00:00',ValidDate='2022-01-01 05:00:00',LoadShowSize=4,}",
  [3004983] = "{id=3004983,NameZh='庆典三角旗',Icon='item_3004983',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10494,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='庆典专用的小旗子，旗面上还描绘着一只可爱的波利，可惜旗杆并没有做成口哨的样式。“如果可以发出清亮的哨音，庆典一定会更热闹吧？”',Feature=1,TFValidDate='2021-12-25 05:00:00',ValidDate='2022-01-01 05:00:00',LoadShowSize=4,}",
