  [3005157] = "{id=3005157,NameZh='达纳托斯的神赐',Icon='item_3002308',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='达纳托斯的神赐，使用之后最多可以获得5份奖励！\n必定获得以下所有道具：「达纳托斯的荣光」x1、「卢恩古币」x4\n必定获得以下奖励中的一种：「神之恩赐宝箱」x1、「奥术至宝」x1、「深渊之匣」x1、「逝去的荣光之匣」x1\n0.50%概率额外获赠坐骑「月光梦魇」x1\n0.25%概率额外获赠专属道具「圣雪羽」x1\n0.20%概率额外获赠以下专属卡片中的一种：「女武神拉斯格瑞丝卡片」x1、「奥术魔方卡片」x1、「意念聚合体卡片」x1、「魔剑士达纳托斯卡片」x1\n（「达纳托斯的荣光」为货币类道具，使用之后可以兑换达纳托斯塔中除坐骑、卡片之外的其余外观奖励）',Feature=1,}",
  [3005158] = "{id=3005158,NameZh='达纳托斯的荣光',Icon='item_5536',Type=61,UseMode=31296,MaxNum=99999,SellPrice=100,Desc='达纳托斯的荣光，使用之后可以打开专属商店，兑换各类奖励！',Feature=1,}",
  [3005170] = "{id=3005170,NameZh='波利的假期',Icon='item_3005170',Type=840,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10489,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='在南门生活的波利终于有了假期可以去姜饼城玩耍了。可是为什么感觉身体在变得僵硬，这就是寒冷吗？抖抖抖……',TFValidDate='2021-11-24 05:00:00',ValidDate='2021-12-01 05:00:00',LoadShowPose={0,0,0},}",
  [3005171] = "{id=3005171,NameZh='圣诞颂歌',Icon='item_3005171',Type=810,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10490,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='“叮叮当，叮叮当，铃儿响叮当……”，看啊，有雪花从留声机里飘出来了~',TFValidDate='2021-11-24 05:00:00',ValidDate='2021-12-01 05:00:00',LoadShowRotate=170,LoadShowPose={0,0.2,-0.8},}",
