  [3005175] = "{id=3005175,NameZh='上古遗物材料礼盒·绮想万圣夜',Icon='item_3003303',Type=30,Quality=4,MaxNum=99999,SellPrice=100,Desc='装着上古遗物材料的礼盒，使用后必定获得其中一个：「云霞纱线」x1、「精灵神木」x1、「陈旧的号角」x1。',}",
  [3005176] = "{id=3005176,NameZh='七王室礼盒',Icon='item_6743',Type=30,MaxNum=99999,SellPrice=100,Desc='装有七王室为冒险者精心准备的礼物。（七王室版本上线后才可使用）',}",
  [3005177] = "{id=3005177,NameZh='往期头饰自选礼盒·圣诞',Icon='item_3620',Type=30,MaxNum=99999,SellPrice=100,Desc='B格猫星人为各位有遗憾的冒险家特意准备的礼物，使用之后可以在以下奖励中自选1件：「圣诞祝福帽图纸」x1、「圣诞之歌图纸」x1、「萌萌驯鹿角图纸」x1、「小小圣诞信使」x1、「槲寄生发冠」x1、「草莓棉花糖」x1。',}",
  [3005180] = "{id=3005180,NameZh='破晓飞翼',Icon='item_3005180',Type=810,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=10497,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='参考破晓时的朝霞，以金红白三色为主调的飞翼，承载着对于未来的期许。勇敢的冒险者，愿这双翅膀为你施加助力，飞跃困厄与险阻，抵达你心目中的理想之地。',}",
  [3005185] = "{id=3005185,NameZh='俄赛里斯的圣诞珍藏',Icon='item_3725',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='俄赛里斯为了庆祝这个圣诞节而准备的全部家当！\n打开必定获得Zeny x750,000。有概率获得以下道具中的一种：「俄赛里斯卡片」x1、「流浪之狼卡片」x1、「爱丽丝女仆卡片」x1、「狸猫卡片」x1、「吹笛人卡片」x1、「暖心熊妹妹[1]」x1、「弗雷硬币」x1、「神谕之尘」x15~30、「神谕之晶」x12~25、「诺伦卡片」x100~200、「祈祷晶片包」x5~10、「古拉姆晶末」x100、「金质勋章」x10、「玛丝黛拉果实」x1，0.5%概率额外获赠「圣诞坐骑自选券」x1。\n「圣诞坐骑自选券」/「俄赛里斯卡片」的概率将随着开启次数的增加而增加：最多在开启第200个礼盒时，必定获得「圣诞坐骑自选券」；最多在开启第400个礼盒时，必定获得「俄赛里斯卡片」！\n每个道具的保底均仅可触发1次，若在保底次数之前已经获得该道具，则保底将取消。（通过礼盒获得的卡片可在冒险手册解锁。「圣诞坐骑自选券」可上架交易所，使用之后可以自选「银翼雪鹿」x1、「驯鹿波利」x1或「星途雪橇」x1）',Feature=1,}",
  [3005186] = "{id=3005186,NameZh='圣诞坐骑自选券',Icon='item_51366',Type=30,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='使用之后可以自选「银翼雪鹿」x1、「驯鹿波利」x1或「星途雪橇」x1。「圣诞坐骑自选券」在未使用之前可以上架交易所，使用之后获得的坐骑为不可交易状态，请各位冒险者注意哦~',Feature=1,}",
  [3005190] = "{id=3005190,NameZh='贪食小怪',Icon='item_3005190',Type=850,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9813,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='为了吃的能把自己送到猎人嘴边的恶魔，虽然长着恶龙般邪恶的橙黄色大眼，本质却是个笨蛋。总之，比那些表里不一的人要可爱多了。',Feature=1,TFValidDate='2022-01-01 05:00:00',ValidDate='2022-01-01 05:00:00',}",
  [3005191] = "{id=3005191,NameZh='凝视之眼[1]',Icon='item_3005191',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9814,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='乍一看破旧肮脏的皮帽，实则是猎人重要的宝物。上面的装饰物，是货真价实的恶魔之眼。相传，恶魔有着识别同类的能力，当它开始眨动，便说明恶魔就在你的身边。',Feature=1,TFValidDate='2022-01-01 05:00:00',ValidDate='2022-01-01 05:00:00',}",
  [3005192] = "{id=3005192,NameZh='迪蒙伯爵',Icon='item_3005192',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9815,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='真名未知的恶魔领主，因为与初代恶魔猎人贝尔蒙德打赌失败，被迫寄宿在玩偶的体内，协助其后嗣狩猎。据说当你遇到无法战胜的敌人时，只要将玩偶丢向对面，就会有奇迹出现！',Feature=1,TFValidDate='2022-01-01 05:00:00',ValidDate='2022-01-01 05:00:00',}",
  [3005193] = "{id=3005193,NameZh='死之吻',Icon='item_3005193',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9816,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='恶魔猎人的双枪，赐予过魔物死亡，也同样抵上过人类的额头。毕竟有一类“恶魔”，披着人类的皮囊，却长着野兽的心。',Feature=1,TFValidDate='2022-01-01 05:00:00',ValidDate='2022-01-01 05:00:00',}",
  [3005194] = "{id=3005194,NameZh='恶作剧礼盒[1]',Icon='item_3005194',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9817,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='滚圆白胖的小恶魔，以人类惊恐的情绪为食物，经常把自己伪装成礼物盒。不过对胆大的恶魔猎人来说，它们只是增添趣味的饰品罢了。',Feature=1,TFValidDate='2022-01-01 05:00:00',ValidDate='2022-01-01 05:00:00',}",
  [3005195] = "{id=3005195,NameZh='猎人眼罩',Icon='item_3005195',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9818,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='初代恶魔猎人贝尔蒙德与恶魔领主战斗，以一只眼睛为代价击败了对方。他的后继者为了纪念他，又或者为了跟风，便将眼罩加入了恶魔猎人的标配。',Feature=1,TFValidDate='2022-01-01 05:00:00',ValidDate='2022-01-01 05:00:00',}",
  [3005196] = "{id=3005196,NameZh='弹簧梦魇',Icon='item_3005196',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9080,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='参照幼年期梦魇制作的头饰，底部的弹簧使得它能够在头顶轻盈晃动。但请不要佩戴着它在梦魇群中活动，一些眼神不好的梦魇，可能会认为你拐带了幼崽，而对你发起进攻。',Feature=1,TFValidDate='2022-01-01 05:00:00',ValidDate='2022-01-01 05:00:00',}",
  [3005200] = "{id=3005200,NameZh='虎虎生风[1]',Icon='item_3005200',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9819,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='锣鼓喧天，鞭炮齐鸣。辞旧迎新，虎虎生风！',Share=1,Feature=1,TFValidDate='2022-02-01 05:00:00',ValidDate='2022-02-01 05:00:00',}",
  [3005201] = "{id=3005201,NameZh='利是封',Icon='item_3005201',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9820,AdventureValue=1,StorageReward={buffid={80012870}},Condition=8,Desc='每当新年到来，洛阳的居民们都会将钱币装入红包，赠予亲朋，祈求在新的一年大吉大利，好运连连。',Feature=1,TFValidDate='2022-02-01 05:00:00',ValidDate='2022-02-01 05:00:00',}",
  [3005202] = "{id=3005202,NameZh='伏虎记',Icon='item_3005202',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9821,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='洛阳城中广为流传的话本小说，控诉了一名男子酒后拳打萌虎的“罪恶”行径。',Feature=1,TFValidDate='2022-02-01 05:00:00',ValidDate='2022-02-01 05:00:00',}",
  [3005203] = "{id=3005203,NameZh='丰年有余',Icon='item_3005203',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9822,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='又是辛勤劳作的一年，吃顿好的犒劳一下自己吧！',Feature=1,TFValidDate='2022-02-01 05:00:00',ValidDate='2022-02-01 05:00:00',}",
  [3005204] = "{id=3005204,NameZh='萌虎战纹',Icon='item_3005204',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9823,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='不是虎斑猫，是真正的老虎哦！诶，老虎怎么叫来着？嗷呜——喵？',Feature=1,TFValidDate='2022-02-01 05:00:00',ValidDate='2022-02-01 05:00:00',}",
  [3005205] = "{id=3005205,NameZh='虎佑平安',Icon='item_3005205',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9824,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='在洛阳的居民们看来，老虎是一种瑞兽，凶猛的它们可以将邪祟吓退，护佑人们的平安。',Feature=1,TFValidDate='2022-02-01 05:00:00',ValidDate='2022-02-01 05:00:00',}",
  [3005206] = "{id=3005206,NameZh='金库守护者',Icon='item_3005206',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9081,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='宝贵的金币就要有凶恶的猛兽来守护哦——“嗷呜！别倒了别倒了！真的一个都不剩了！”',Feature=1,TFValidDate='2022-02-01 05:00:00',ValidDate='2022-02-01 05:00:00',}",
  [3005220] = "{id=3005220,NameZh='虎王宝宝魔物蛋',Icon='item_3005220',Type=101,MaxNum=1,SellPrice=100,Desc='一颗神奇的魔物蛋，里面可以孵化出宠物虎王宝宝。',Feature=1,TFValidDate='2021-01-24 05:00:00',ValidDate='2022-01-31 05:00:00',}",
  [3005221] = "{id=3005221,NameZh='草莓酸奶',Icon='item_3005221',Type=103,MaxNum=99999,SellPrice=100,Desc='草莓味的酸奶，酸酸的、甜甜的。是魔物虎王宝宝最喜爱的食物。',Feature=1,TFValidDate='2022-01-24 05:00:00',ValidDate='2022-01-31 05:00:00',}",
  [3005230] = "{id=3005230,NameZh='双心棒棒糖',Icon='item_3005230',Type=810,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10500,AdventureValue=1,StorageReward={buffid={80012920}},Condition=8,Desc='两颗心形的糖果被串在一起，听说这种棒棒糖在小情侣间极受欢迎！',Feature=1,TFValidDate='2022-01-24 05:00:00',ValidDate='2022-01-31 05:00:00',}",
  [3005231] = "{id=3005231,NameZh='虎虎灯笼',Icon='item_3005231',Type=800,Quality=4,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10501,AdventureValue=1,StorageReward={buffid={80013030}},Condition=8,Desc='小老虎造型的灯笼，戴在头上是为了祈福在新的一年会有好运降临~！',Share=1,Feature=1,TFValidDate='2022-01-24 05:00:00',ValidDate='2022-01-31 05:00:00',}",
  [3005232] = "{id=3005232,NameZh='寅头巾',Icon='item_3005232',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10502,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='可爱的小老虎闯进了童年的梦境。如果你发现了它，记得打个招呼，会得到神灵的祝福，一整年都会交好运呢！',Feature=1,TFValidDate='2022-01-24 05:00:00',ValidDate='2022-01-31 05:00:00',}",
  [3005240] = "{id=3005240,NameZh='克魔岛的冬日',Icon='item_3945',Type=30,MaxNum=99999,SellPrice=100,Desc='使用后必定获得：「小木锤」x1、Zeny x150000，有概率获得以下道具中的一种：「闪耀的符文石」x1、「光洁的符文石」x1、「神谕之尘」x4、「神谕之晶」x4、「祈祷晶片包」x2、「玛丝黛拉种子」x1。',}",
