  [3005246] = "{id=3005246,NameZh='幻想创造器Ⅰ号的馈赠',Icon='item_6072',Type=30,MaxNum=99999,SellPrice=100,Desc='来自幻想创造器Ⅰ号的馈赠，打开后可选择以下其中任意一种道具：「萃光结晶」x20，「瓦特阿尔仙尘」x6，「祈祷晶片包」x20。',}",
  [3005247] = "{id=3005247,NameZh='小木锤',Icon='item_3001889',Type=30,UseMode=31043,MaxNum=99999,SellPrice=100,Desc='虽然是普通木制小锤，但是却能发挥巨大威力，真是惊人！“喂！这个不可以用来打人！”',ExistTimeType=2,ExistTime='2022-01-01 05:00:00',Feature=1,}",
  [3005250] = "{id=3005250,NameZh='冬幕华尔兹·雪松',Icon='item_3005250',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='以严冬中的雪松为主题点缀色调，加上干净利落的剪裁，彰显贵族气质。这套礼服会让你成为圣诞舞会的焦点，所有人都会因你的俊朗而动容。',Feature=1,TFValidDate='2021-12-13 05:00:00',ValidDate='2021-12-16 05:00:00',MainColor='f6ede6FF',}",
  [3005251] = "{id=3005251,NameZh='冬幕华尔兹·合欢',Icon='item_3005250',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='以对暖春的期盼为主题点缀色调，加上干净利落的剪裁，彰显贵族气质。这套礼服会让你成为圣诞舞会上耀眼的明星，所有人都会因你的温柔而动容。',Feature=1,TFValidDate='2021-12-13 05:00:00',ValidDate='2021-12-16 05:00:00',MainColor='d85276FF',}",
  [3005252] = "{id=3005252,NameZh='冬幕华尔兹·冷杉',Icon='item_3005250',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='以峻岭之上的冷杉为主题点缀色调，加上干净利落的剪裁，彰显贵族气质。这套礼服会让你成为圣诞舞会上耀眼的明星，所有人都会因你的冷峻而动容。',Feature=1,TFValidDate='2021-12-13 05:00:00',ValidDate='2021-12-16 05:00:00',MainColor='3772f0FF',}",
  [3005253] = "{id=3005253,NameZh='冬幕华尔兹·冬青',Icon='item_3005250',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='以骄傲常绿的冬青为主题点缀色调，加上干净利落的剪裁，彰显贵族气质。这套礼服会让你成为圣诞舞会上耀眼的明星，所有人都会因你的坚毅而动容。',Feature=1,TFValidDate='2021-12-13 05:00:00',ValidDate='2021-12-16 05:00:00',MainColor='3f614dFF',}",
