  [3005293] = "{id=3005293,NameZh='圣诞波利叠叠乐',Icon='item_3005293',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15568,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='这三只被魔法装扮的波利，总是会跟随真正的快乐源泉。摇响铃铛，让冬日里所有美妙的事物，都聚集在你身边。',Feature=1,TFValidDate='2021-12-13 05:00:00',ValidDate='2021-12-16 05:00:00',LoadShowPose={0,0,0},}",
