  [3005295] = "{id=3005295,NameZh='棉花糖胡须',Icon='item_3005295',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15570,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='模仿圣诞老人的红鼻头和白胡须，用樱桃和棉花糖制成的装饰。戴上之后不能大口吸气。',Feature=1,TFValidDate='2021-12-13 05:00:00',ValidDate='2021-12-16 05:00:00',}",
  [3005296] = "{id=3005296,NameZh='圣诞之翼',Icon='item_3005296',Type=810,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=15571,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='搜集美好的祝愿，散播欢笑和幸福时光。要不是已经有雪橇了，就连圣诞老人自己都想要一对。',Feature=1,TFValidDate='2021-12-13 05:00:00',ValidDate='2021-12-16 05:00:00',LoadShowRotate=165,LoadShowPose={0.3,0,-1},}",
