  [3005430] = "{id=3005430,NameZh='虎王贺礼',Icon='item_6601',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='虎王为了庆祝这个春节，特意为冒险者准备的惊喜。打开后必定获得Zeny x 150,000、「B格猫福利券·宴」x6、「好运币」x2，以下奖励随机获得1种：「炉心余烬」x1、「光洁的符文石」x1、「神谕之尘」x5、「神谕之晶」x5、「祈祷晶片包」x2、「玛丝黛拉种子」x1。',Feature=1,}",
  [3005431] = "{id=3005431,NameZh='虎王感恩礼',Icon='item_6600',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='来自虎王的感恩，打开后必定获得Zeny x 150,000、「福利券自选礼包」x5、「祈祷晶片自选包」x5、「金质勋章」x5、「来自女武神的馈赠」x5。',Feature=1,}",
  [3005432] = "{id=3005432,NameZh='压岁钱·2022',Icon='item_3869',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='一份沉甸甸的压岁钱！祝愿冒险者在新的一年顺风顺水、欧气满满~！打开后必定获得Zeny x 888,88~8,888,888、「弗雷硬币」x2、「闪耀的符文石」x2、「闪耀的符文石·星」x2、「B格猫福利券·宴」x30、「拾光邀请函」x30。',Feature=1,}",
  [3005433] = "{id=3005433,NameZh='锦鲤福袋',Icon='item_6508',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='新年新气象，新春新好运！打开这个福袋可以获得Zeny x 88,888、「料理兑换券」x1、「坠星陨铁」x1、「波利成长秘药」x1，以下奖励随机获得1种：「B格猫福利券·宴」x5、「B格猫福利券·Ⅰ」x5、「拾光邀请函」x5，还有10%的概率额外获赠限定头饰「虎虎灯笼」x1。',GetLimit={limit={[999]={5,0}},source={22},type=4},Feature=1,}",
  [3005434] = "{id=3005434,NameZh='年兽的珍藏',Icon='item_3001200',Type=61,Quality=3,UseMode=31315,MaxNum=99999,SellPrice=100,Desc='年兽视为宝贝的珍藏，据说拿着这些东西，可以兑换很多稀有的东西~！（该道具将在2022-03-01 05:00:00失效回收，请各位冒险者抓紧使用，以免造成损失哦~）',ExistTimeType=2,ExistTime='2022-03-01 05:00:00',Feature=1,}",
  [3005435] = "{id=3005435,NameZh='拜年红包',Icon='item_3635',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='新年快乐，红包拿来！打开这个红包，可以随机获得以下奖励中的1种：「神谕之尘」x10、「神谕之晶」x10、「莫拉硬币」x10、「好运币」x5、「光洁的符文石」x1、「闪耀的符文石」x1、「闪耀的符文石·星」x1、「尘封的符文袋·Ⅰ」x2、「玛丝黛拉种子」x1、「祈祷晶片自选包」x3。',Feature=1,}",
  [3005436] = "{id=3005436,NameZh='财神福袋',Icon='item_3707',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='新的一年，财神永远陪伴着你~！打开这个福袋，可以获得Zeny x 888,88~8,888,888，「弗雷硬币」x1~10。',Feature=1,}",
  [3005437] = "{id=3005437,NameZh='开工利是',Icon='item_3001439',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='特别的利是送给今天需要开工的人儿~祝你在新的一年里步步高升~打开这封利是，必定获得「好运币」x20、「古塔·超能弹射器」x1、「冒险丸子」x128、「炉心余烬」x5、「每日特惠冒险礼盒」x1、「命运合成补给箱」x1。',Feature=1,}",
  [3005438] = "{id=3005438,NameZh='小爱神的谢礼',Icon='item_3000170',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='小爱神的礼物可不多见哦~打开之后必定获得「料理兑换券」x1、「坠星陨铁」x1、「波利成长秘药」x1，以下奖励随机获得1种：「B格猫福利券·Ⅰ」x5、「B格猫福利券·宴」x5、「拾光邀请函」x5、「神谕之尘」x5、「神谕之晶」x5、「光洁的符文石」x2、「古拉姆晶末」x20、「金质勋章」x5、「尘封的符文袋·Ⅰ」x2、「好运币」x5、「玛丝黛拉种子」x1。',Feature=1,}",
  [3005439] = "{id=3005439,NameZh='元宵礼盒',Icon='item_3003137',Type=30,MaxNum=99999,SellPrice=100,Desc='哇哦~阁下真是个小聪明，那么刁钻的题目都能答对~打开这个礼盒，可以获得「好运币」x2、「月之碎片」x1、「金质勋章」x2、「草莓棉花糖」x1、「精研型JOB药水」x10。',Feature=1,}",
  [3005440] = "{id=3005440,NameZh='月之碎片',Icon='item_6210',Type=41,Quality=2,MaxNum=99999,SellPrice=100,ComposeID=4000088,Desc='5个「月之碎片」可以合成「月圆头饰自选礼盒」，自选往期活动产出的「月圆系列头饰」x1，或者「草莓棉花糖」x1。',Feature=1,}",
  [3005441] = "{id=3005441,NameZh='元宵礼盒·Ⅲ',Icon='item_3003140',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='哇哦~阁下一定是整个米德加尔特最聪明的人，这份特殊的奖励，只有最聪明的人才能打开！打开之后，可以获得「诺伦卡片」x100、「弗雷硬币」x1、「月圆头饰自选礼盒」x1。',Feature=1,}",
  [3005442] = "{id=3005442,NameZh='新春焕新时装券',Icon='item_1000411',Type=61,Quality=3,UseMode=31316,MaxNum=99999,SellPrice=100,Desc='穿新衣过新年，为了庆祝这个新年，B格猫星人特意奉上这张时装券，愿你在新的一年里有新的精彩~使用后可打开商店，兑换[itemid]3005081[/itemid]、[itemid]3003663[/itemid]、[itemid]3005096[/itemid]等稀有道具（该道具将在2022-05-01 05:00:00失效回收，请各位冒险者抓紧使用，以免造成损失哦~）',ExistTimeType=2,ExistTime='2022-05-01 05:00:00',Feature=1,}",
