  [3005600] = "{id=3005600,NameZh='虎啸新春头饰兑换券',Icon='item_3005600',Type=61,UseMode=31318,MaxNum=99999,SellPrice=100,Desc='使用之后可以兑换任意一件虎啸新春系列头饰哦~',Feature=1,}",
  [3005601] = "{id=3005601,NameZh='伏虎绒帽',Icon='item_3005601',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15586,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='毛绒绒的大老虎发现了你……毛绒绒的大老虎扑到了你的头上！“有我在，这个冬天就不冷了，嗷呜~”',Feature=1,TFValidDate='2022-01-13 05:00:00',ValidDate='2022-01-16 05:00:00',}",
  [3005602] = "{id=3005602,NameZh='萌虎福卷',Icon='item_3005602',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15587,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='由可爱的小老虎们亲手“写”下的对联，承载了对冒险者的美好祝福。不过，老虎的艺术对人类来说为时尚早，没有人能解读出这些爪印说了什么。',Feature=1,TFValidDate='2022-01-13 05:00:00',ValidDate='2022-01-16 05:00:00',LoadShowRotate=175,LoadShowPose={0,0.5,-0.8},}",
  [3005603] = "{id=3005603,NameZh='胖虎的美梦',Icon='item_3005603',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15588,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='小胖虎的理想生活，便是不用睁眼，就能啃到心爱的精华火腿。如今它的梦想已经实现，愿将美梦成真的幸运分你一点。',Feature=1,TFValidDate='2022-01-13 05:00:00',ValidDate='2022-01-16 05:00:00',}",
  [3005604] = "{id=3005604,NameZh='招财包子',Icon='item_3005604',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15589,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='险些被放进蒸笼烹熟的波利包子，喜欢与冒险者玩抛铜钱的游戏。它认为这种举动，可以为冒险者带来滚滚财源。',Feature=1,TFValidDate='2022-01-13 05:00:00',ValidDate='2022-01-16 05:00:00',}",
  [3005605] = "{id=3005605,NameZh='饿虎围脖',Icon='item_3005605',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15590,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='绒绒的小老虎，为你提供暖暖的服务。赌上百兽之王的尊严，绝不会让一丝冷风灌入你的脖颈。',Feature=1,TFValidDate='2022-01-13 05:00:00',ValidDate='2022-01-16 05:00:00',}",
  [3005606] = "{id=3005606,NameZh='福虎披帛',Icon='item_3005606',Type=810,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=15591,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='来自东方的锦缎披帛，特意挽成了翅膀的形状。金红色的缎面上盖满了墨色的爪印，据说是虎族内部流传的祈福符文。',Feature=1,TFValidDate='2022-01-13 05:00:00',ValidDate='2022-01-16 05:00:00',LoadShowRotate=170,LoadShowPose={0,0.6,-1},}",
  [3005607] = "{id=3005607,NameZh='2022的第一个礼盒',Icon='item_3620',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='新的一年，新的开始，今年也要一起过！使用之后获得「好运币」x20、「闪耀的符文石」x2、「闪耀的符文石·星」x2、「B格猫福利券·宴」x30、「拾光邀请函」x30。',Feature=1,}",
