  [3005609] = "{id=3005609,NameZh='皇家庆典纪念礼盒',Icon='item_3711',Type=30,MaxNum=99999,SellPrice=100,Desc='只在B格猫皇家庆典中产出的礼盒。使用之后获得「皇家庆典珍藏绘本」x1、「弗雷硬币」x2、「精致的维修碎片」x1、「B格猫福利券·Ⅰ」x30。',Feature=1,}",
  [3005610] = "{id=3005610,NameZh='皇家庆典珍藏绘本',Icon='item_500620',Type=65,Quality=3,UseMode=31180,MaxNum=1,SellPrice=100,Desc='以「皇家庆典」为主题的四格漫画绘本，打开后冒险家可以进行自由填色！',Feature=1,}",
  [3005611] = "{id=3005611,NameZh='时光的见证',Icon='item_3736',Type=30,MaxNum=99999,SellPrice=100,Desc='使用之后，必定获得「小木锤」x1、Zeny x150,000、「B格猫福利券·宴」x6。以下奖励随机获得1种：「炉心余烬」x1、「光洁的符文石」x1、「神谕之尘」x5、「神谕之晶」x5、「祈祷晶片包」x2、「玛丝黛拉种子」x1。',Feature=1,}",
  [3005612] = "{id=3005612,NameZh='金色十字头饰礼盒',Icon='item_6069',Type=30,MaxNum=99999,SellPrice=100,Desc='只在B格猫皇家庆典中产出的礼盒。使用之后，可以选择获得「白金十字」x1或「金红十字冠」x1。',Feature=1,}",
  [3005613] = "{id=3005613,NameZh='帕罗船长的宝物',Icon='item_5753',Type=30,MaxNum=99999,SellPrice=100,Desc='使用之后，必定获得「小木锤」x1、「坠星陨铁」x1、「波利成长秘药」x1。以下奖励随机获得1种：「B格猫福利券·Ⅰ」x5、「B格猫福利券·宴」x5、「拾光邀请函」x5、「神谕之尘」x5、「神谕之晶」x5、「光洁的符文石」x2、「古拉姆晶末」x20、「金质勋章」x5、「尘封的符文袋·Ⅰ」x2、「好运币」x5、「玛丝黛拉种子」x1。',Feature=1,}",
  [3005614] = "{id=3005614,NameZh='甜心蛋糕礼盒',Icon='item_49536',Type=30,MaxNum=99999,SellPrice=100,Desc='无甜不欢，这就像分享的快乐是双倍的糖分！使用之后，必定获得「坠星陨铁」x1、「心愿蛋糕」x1，50%概率获得「小木锤」x1。以下奖励随机获得1种：「B格猫福利券·Ⅰ」x5、「神谕之尘」x5、Zeny x100,000。',Feature=1,}",
  [3005615] = "{id=3005615,NameZh='暖暖蜡烛礼盒',Icon='item_49518',Type=30,MaxNum=99999,SellPrice=100,Desc='小小的蜡烛，在寒冷的冬天带给你一丝温暖。使用之后，必定获得「坠星陨铁」x1、「心愿蛋糕」x1，50%概率获得「小木锤」x1。以下奖励随机获得1种：「B格猫福利券·宴」x5、「神谕之晶」x5、Zeny x100,000。',Feature=1,}",
  [3005616] = "{id=3005616,NameZh='庆典欢乐礼盒',Icon='item_49537',Type=30,MaxNum=99999,SellPrice=100,Desc='欢乐的时光，是与你，还有你们在一起！使用之后，必定获得「坠星陨铁」x1、「心愿蛋糕」x1，50%概率获得「小木锤」x1。以下奖励随机获得1种：「拾光邀请函」x5、「莫拉硬币」x5、Zeny x100,000。',Feature=1,}",
  [3005617] = "{id=3005617,NameZh='尘封的宝箱',Icon='item_3681',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='被灰尘掩盖的宝箱，难道是什么上古的宝藏？使用之后，必定获得「小木锤」x1、「弗雷硬币」x1~5。以下奖励必定获得1种：「拾光邀请函」 x30、「B格猫福利券·宴」x30。有额外概率获得：「宠物礼盒」x1、「远古装备精炼自选礼包」x1、「2021」宴的馈赠·自选x1、「2021」头饰的馈赠·自选x1。在第3次开启该礼包时，100%额外获赠限定背饰「彩虹的祝福」!',GetLimit={limit={[999]={1,0}},source={22},type=4},Feature=1,}",
  [3005618] = "{id=3005618,NameZh='闪耀的宝箱',Icon='item_3682',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='金光闪闪的宝箱，看起来似乎藏着些什么价值不菲的宝贝~！使用之后，必定获得「小木锤」x1、「弗雷硬币」x1~5。以下奖励必定获得1种：「B格猫福利券·Ⅰ」 x30、「B格猫福利券·宴」x30。有额外概率获得：「庆典头饰自选礼盒」x1、「远古装备精炼自选礼包」x1、「2022.02」宴的馈赠x1、「2022.02」头饰的馈赠x1。在第3次开启该礼包时，100%额外获赠「精炼头饰+15券」!',GetLimit={limit={[999]={1,0}},source={22},type=4},Feature=1,}",
  [3005619] = "{id=3005619,NameZh='庆典头饰自选礼盒',Icon='item_3712',Type=30,MaxNum=99999,SellPrice=100,Desc='微笑小姐一年一度对冒险者的回馈，使用之后，可自选「庆典系列头饰」x1，或者「草莓棉花糖」x1。',Feature=1,}",
