  [3005649] = "{id=3005649,NameZh='精炼+15头饰券',Icon='item_3032040',Type=41,MaxNum=99999,SellPrice=100,Desc='这个道具包含了B格猫星人对精炼的终极理解，使用之后可以将精炼等级小于15的不可交易的头饰（包括头部、背部、嘴部、尾部、脸部）精炼至15！',ItemTarget={type=4},ExistTimeType=2,ExistTime='2022-05-01 05:00:00',Feature=1,}",
  [3005650] = "{id=3005650,NameZh='庆典特供补给箱',Icon='item_6603',Type=30,Quality=4,MaxNum=99999,SellPrice=100,Desc='使用之后，可自选以下道具之一：「白金十字」x1，「金红十字冠」x1、「滑稽先生的胡子」x1、「庆典三角旗」x1、「彩虹的祝福」x1、「波利大奖杯」x1、「草莓棉花糖」x1。',Feature=1,}",
  [3005660] = "{id=3005660,NameZh='冰霜魔龙契约',Icon='item_25174',Type=41,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='诞生于北境雪国的契约，使用后将可以获得限定坐骑「极冰之混沌」！契约在未使用前可上架交易所自由交易，使用后获得的坐骑将与冒险者绑定灵魂关系，无法再上架交易所，请各位冒险者谨慎使用！',Feature=1,}",
  [3005661] = "{id=3005661,NameZh='魔龙的祝福',Icon='item_3002607',Type=41,Quality=2,MaxNum=99999,SellPrice=100,Desc='冰霜魔龙的祝福，打开后必定获得「诺伦卡片」x50，有概率获得以下道具中的一种：「天火碎片·锋锐型」x1、「神谕之尘」x15~30、「神谕之晶」x12~25、「诺伦卡片」x100~200、「祈祷晶片包」x5~10、「古拉姆晶末」x100、「金质勋章」x10、「魔力树枝·梦幻」x2、「金之星」x1。0.5%概率额外获赠「冰霜魔龙契约」x1、0.5%概率额外获赠「诺伦的指引·月」。\n「冰霜魔龙契约」的概率将随着开启次数的增加而增加，最多在开启第250个礼盒时，必定获得！保底仅可触发1次，若在保底次数之前已经获得该道具，则保底将取消。（「诺伦的指引·月」为解锁类道具，使用后可以解锁一张未解锁的Mvp卡片。「冰霜魔龙契约」可上架交易所。）',Feature=1,}",
  [3005690] = "{id=3005690,NameZh='摇滚迷兔',Icon='item_3005690',Type=840,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9831,AdventureValue=1,StorageReward={buffid={82000240}},Condition=8,Desc='当今普隆德拉最炙手可热的音乐家，演奏的乐曲据说来自异界，名为“摇滚”。',Feature=1,TFValidDate='2022-04-01 05:00:00',ValidDate='2022-04-01 05:00:00',}",
  [3005691] = "{id=3005691,NameZh='粉墨登场',Icon='item_3005691',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9832,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='戴上墨镜，迈出六亲不认的步伐——都闪开，巨星登场了！',Feature=1,TFValidDate='2022-04-01 05:00:00',ValidDate='2022-04-01 05:00:00',}",
