  [3005694] = "{id=3005694,NameZh='赛博之牙',Icon='item_3005694',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9835,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='智能机器人“赛博小兔”为适应战斗而变化成的重装形态，小兔的AI能够在战斗中为使用者提供帮助。',Feature=1,TFValidDate='2022-04-01 05:00:00',ValidDate='2022-04-01 05:00:00',}",
  [3005695] = "{id=3005695,NameZh='欢乐源泉',Icon='item_3005695',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9836,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='来自异界的红罐饮料，气泡带来刺激的口感，是能够给人带来能量——还有快乐的饮料！',Feature=1,TFValidDate='2022-04-01 05:00:00',ValidDate='2022-04-01 05:00:00',}",
