  [3005710] = "{id=3005710,NameZh='众神之瞳·秩序',Icon='item_3005710',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='当神还没有在天空画上彩虹的时候，整个世界是被翠绿环绕。绿色滋润灵魂、带来智慧，是侦探最爱的颜色。',Feature=1,TFValidDate='2022-03-13 05:00:00',ValidDate='2022-03-16 05:00:00',MainColor='1d9661FF',}",
  [3005711] = "{id=3005711,NameZh='众神之瞳·线索',Icon='item_3005710',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='众神用紫色包裹新生儿，象征着尊敬与荣耀。正义的使者穿梭于真相与谎言之间，为心灵带来神秘的气息。',Feature=1,TFValidDate='2022-03-13 05:00:00',ValidDate='2022-03-16 05:00:00',MainColor='696ed8FF',}",
  [3005712] = "{id=3005712,NameZh='众神之瞳·希望',Icon='item_3005710',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='是突如其来的暴风雨中唯一的光芒，洗净世界上的灰暗与残酷。真相与正义永远不会被黑暗吞噬，如同心中燃烧的热血一样。',Feature=1,TFValidDate='2022-03-13 05:00:00',ValidDate='2022-03-16 05:00:00',MainColor='d13935FF',}",
  [3005713] = "{id=3005713,NameZh='众神之瞳·魅影',Icon='item_3005710',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='抛去感性的外衣，告诫自己不可盲目思索。一个人也能了解整个世界，一个人也可以将真相大白于天下。',Feature=1,TFValidDate='2022-03-13 05:00:00',ValidDate='2022-03-16 05:00:00',MainColor='04a9b8FF',}",
  [3005720] = "{id=3005720,NameZh='众神之证·秩序',Icon='item_3005720',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='当神还没有在天空画上彩虹的时候，整个世界是被翠绿环绕。绿色滋润灵魂、蕴含着复活的希望，是侦探最爱的颜色。',Feature=1,TFValidDate='2022-03-13 05:00:00',ValidDate='2022-03-16 05:00:00',MainColor='1d9661FF',}",
  [3005721] = "{id=3005721,NameZh='众神之证·线索',Icon='item_3005720',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='众神用紫色包裹新生儿，象征着尊敬与荣耀。正义的使者穿梭于真相与谎言之间，坚定守护心灵深处的高贵品格。',Feature=1,TFValidDate='2022-03-13 05:00:00',ValidDate='2022-03-16 05:00:00',MainColor='696ed8FF',}",
  [3005722] = "{id=3005722,NameZh='众神之证·希望',Icon='item_3005720',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='是突如其来的暴风雨中唯一的光芒。火红的朝阳下，真相与正义永远不会被吞噬，是洗净世界上灰暗与残酷的希望。',Feature=1,TFValidDate='2022-03-13 05:00:00',ValidDate='2022-03-16 05:00:00',MainColor='d13935FF',}",
  [3005723] = "{id=3005723,NameZh='众神之证·魅影',Icon='item_3005720',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='抛去感性的外衣，告诫自己不可盲目思索。一个人也能了解整个世界，一个人也可以保护弱者，成为弱者的希望。',Feature=1,TFValidDate='2022-03-13 05:00:00',ValidDate='2022-03-16 05:00:00',MainColor='04a9b8FF',}",
