  [3005730] = "{id=3005730,NameZh='智慧之瞳·正义',Icon='item_3005710',Type=501,MaxNum=99,SellPrice=100,Desc='泛黄的旧物、阴暗的烛光，和暖黄的外衣一起融进探索真相的旅途。它带来温暖与启蒙，阳光撒过，闪闪发亮。',Feature=1,TFValidDate='2022-03-13 05:00:00',ValidDate='2022-03-16 05:00:00',MainColor='e79f35FF',}",
  [3005731] = "{id=3005731,NameZh='智慧之证·正义',Icon='item_3005720',Type=501,MaxNum=99,SellPrice=100,Desc='泛黄的旧物、阴暗的烛光，和暖黄的外衣一起融进探索真相的旅途。它代表着誓言与维持社会秩序的准则，不可被撼动，熠熠生辉。',Feature=1,TFValidDate='2022-03-13 05:00:00',ValidDate='2022-03-16 05:00:00',MainColor='e79f35FF',}",
