  [3005741] = "{id=3005741,NameZh='真相之冕·线索',Icon='item_3005740',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='一切罪恶被黑暗隐藏，但洁白的月光会为正义的使者留下线索，等待真相重见天日。',Feature=1,TFValidDate='2022-03-13 05:00:00',ValidDate='2022-03-16 05:00:00',MainColor='696ed8FF',}",
  [3005742] = "{id=3005742,NameZh='真相之冕·希望',Icon='item_3005740',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='纵使失去一切光芒，也要无所畏惧，洗净世界上灰暗与残酷，越过悲伤的碎片，冲向未来的方向。',Feature=1,TFValidDate='2022-03-13 05:00:00',ValidDate='2022-03-16 05:00:00',MainColor='d13935FF',}",
  [3005743] = "{id=3005743,NameZh='真相之冕·魅影',Icon='item_3005740',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='微风吹拂着悸动的内心，告诫自己沉静的孤独是最好的馈赠，努力穿越黑暗吧，真相就在前方。',Feature=1,TFValidDate='2022-03-13 05:00:00',ValidDate='2022-03-16 05:00:00',MainColor='20c7e5FF',}",
