  [3005745] = "{id=3005745,NameZh='誓言之冠·秩序',Icon='item_3005745',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='为了履行誓言，将崇高的律条法典做为行事唯一准则，绝无动摇。',Feature=1,TFValidDate='2022-03-13 05:00:00',ValidDate='2022-03-16 05:00:00',MainColor='5cc6acFF',}",
  [3005746] = "{id=3005746,NameZh='誓言之冠·线索',Icon='item_3005745',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='在纷争和虚伪中，只有心灵深处的坚守会让罪恶无处遁形，犹如灯光照亮无月的夜空。',Feature=1,TFValidDate='2022-03-13 05:00:00',ValidDate='2022-03-16 05:00:00',MainColor='696ed8FF',}",
  [3005747] = "{id=3005747,NameZh='誓言之冠·希望',Icon='item_3005745',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='纵使失去一切光芒，也要无所畏惧，洗净世界上灰暗与残酷，越过悲伤的碎片，守护心中盛开的蔷薇。',Feature=1,TFValidDate='2022-03-13 05:00:00',ValidDate='2022-03-16 05:00:00',MainColor='d13935FF',}",
