  [3005750] = "{id=3005750,NameZh='侦探的品格头饰兑换券',Icon='item_3005750',Type=61,UseMode=31329,MaxNum=99999,SellPrice=100,Desc='使用之后可以兑换任意一件侦探的品格系列头饰哦~',Feature=1,}",
  [3005751] = "{id=3005751,NameZh='控方证词',Icon='item_3005751',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15596,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='如果你愿意沉下心来阅读这本记录，你会从异常详实的文字里，看到一个个令人匪夷所思的案件，和案件背后环环相扣不可告人的秘密，是刑案辩护时获胜的关键。',Feature=1,TFValidDate='2022-03-13 05:00:00',ValidDate='2022-03-16 05:00:00',}",
  [3005752] = "{id=3005752,NameZh='时光刻度',Icon='item_3005752',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15597,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='时间在用沙子计量的沙漏中流失，探索世界的关键变得具象，王朝与正义能否在流逝的时间中长存。',Feature=1,TFValidDate='2022-03-13 05:00:00',ValidDate='2022-03-16 05:00:00',}",
  [3005753] = "{id=3005753,NameZh='断案高手',Icon='item_3005753',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15598,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='可千万别看轻这个小家伙，很多人透过放大的玻璃棱镜也只能看到现状，但它能捕捉到更多细节，助你发现真相。',Feature=1,TFValidDate='2022-03-13 05:00:00',ValidDate='2022-03-16 05:00:00',LoadShowPose={0,0,0},}",
  [3005754] = "{id=3005754,NameZh='怪盗的凝视',Icon='item_3005754',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15599,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='藏匿双眼，并非禁锢双眼的视线。相反，所有的形式都会在阴影中被消解，真实的世界开始向你展开。',Feature=1,TFValidDate='2022-03-13 05:00:00',ValidDate='2022-03-16 05:00:00',}",
