  [3005822] = "{id=3005822,NameZh='小木锤',Icon='item_3001889',Type=30,UseMode=31043,MaxNum=99999,SellPrice=100,Desc='虽然是普通木制小锤，但是却能发挥巨大威力，真是惊人！“喂！这个不可以用来打人！”',ExistTimeType=2,ExistTime='2022-04-01 05:00:00',Feature=1,}",
