  [3005906] = "{id=3005906,NameZh='哥布灵的冒险礼盒',Icon='item_3657',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='热爱冒险的哥布灵留给冒险者的礼物，打开之后必定获得Zeny x150,000、「B格猫福利券·宴」x6、「好运币」x2，以下奖励随机获得一件：「远古材料自选箱」x1、「光洁的符文石」x1、「神谕之尘」x5、「神谕之晶」x5、「祈祷晶片包」x2、「玛丝黛拉种子」x1',Feature=1,}",
  [3005907] = "{id=3005907,NameZh='哥布灵珍宝',Icon='item_3658',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='哥布灵的珍宝，打开之后必定获得「坠星陨铁」x1、「波利成长秘药」x1、「料理兑换券」x1，以下奖励随机获得一件：「B格猫福利券·Ⅰ」x5、「B格猫福利券·宴」x5、「拾光邀请函」x5、「神谕之尘」x5、「神谕之晶」x5、「光洁的符文石」x2、「古拉姆晶末」x20、「金质勋章」x5、「尘封的符文袋·Ⅰ」x2、「好运币」x5、「玛丝黛拉种子」x1',Feature=1,}",
  [3005908] = "{id=3005908,NameZh='哥布灵忏悔礼盒',Icon='item_3000188',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='哥布灵庆典中产出的礼盒，打开之后必定获得「哥布灵的求饶信」x1，以下奖励随机获得一件：「神谕之尘」x10、「神谕之晶」x10、「莫拉硬币」x10、「好运币」x5、「光洁的符文石」x1、「闪耀的符文石」x1、「闪耀的符文石·星」x1、「尘封的符文袋·Ⅰ」x2、「祈祷晶片自选包」x3、「玛丝黛拉种子」x1。收集「哥布灵的求饶信」x5上交给「博学的哥布灵」可以获取额外奖励~！',GetLimit={limit={[999]={1,0}},source={22},type=4},Feature=1,}",
  [3005909] = "{id=3005909,NameZh='哥布灵的求饶信',Icon='item_13408',Type=62,Quality=2,MaxNum=99999,SellPrice=100,Desc='歪歪扭扭的笔迹一看就知道是哥布灵一族写的，上面写着“呜呜呜呜呜~再也不调皮了~！”听说「博学的哥布灵」有收集这些求饶信的小癖好，快去找他看看吧~',ExistTimeType=2,ExistTime='2022-05-01 05:00:00',}",
