  [3005979] = "{id=3005979,NameZh='灵枭羽饰头饰系列',Icon='item_3005979',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15615,AdventureValue=1,StorageReward={buffid={80012920}},Condition=8,Feature=1,TFValidDate='2022-05-13 05:00:00',ValidDate='2022-05-16 05:00:00',MainColor='X',}",
  [3005980] = "{id=3005980,NameZh='圣晶神话头饰兑换券',Icon='item_3005980',Type=61,UseMode=31335,MaxNum=99999,SellPrice=100,Desc='使用之后可以兑换任意一件圣晶神话系列头饰哦~',Feature=1,}",
  [3005981] = "{id=3005981,NameZh='圣晶波利帽',Icon='item_3005981',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15616,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='吞噬了不明属性魔晶，而变成不明品种的波利！爱好是趴在人类的头上搭便车，“呼呼~既然有两脚兽，为什么要靠自己蹦着赶路啊~”',Feature=1,TFValidDate='2022-05-13 05:00:00',ValidDate='2022-05-16 05:00:00',}",
  [3005982] = "{id=3005982,NameZh='圣晶五弦琴',Icon='item_3005982',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15617,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='出自名贵匠人之手的五弦琴，以纯白的欧珀与蔚蓝的水晶装点，琴弦上更是镀上了一层圣晶粉末。奏响时乐声如梦如幻，令万物沉醉。',Feature=1,TFValidDate='2022-05-13 05:00:00',ValidDate='2022-05-16 05:00:00',}",
  [3005983] = "{id=3005983,NameZh='守秘幽灵',Icon='item_3005983',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15618,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='有着如雪的发丝，与夜一般皮肤的奇幻生物。单从外貌看，似乎与情绪幽灵有着什么关系。平日里，她只会沉默而害羞的跟着你。莫非……她是人类最隐秘、最不可言说的情感的化身？',Feature=1,TFValidDate='2022-05-13 05:00:00',ValidDate='2022-05-16 05:00:00',LoadShowSize=1.5,LoadShowPose={0,-0.5,0},}",
  [3005984] = "{id=3005984,NameZh='流光翩然',Icon='item_3005984',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15619,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='凝萃着流光的蝴蝶，翩然飞舞在你的身边。最终，它们收拢双翼，轻轻吻你的脸颊。',Feature=1,TFValidDate='2022-05-13 05:00:00',ValidDate='2022-05-16 05:00:00',}",
  [3005985] = "{id=3005985,NameZh='星幕面纱',Icon='item_3005985',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15620,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='幽邃如夜幕的纱巾上，点缀着如星子般的黄金。佩戴这样的面纱，一定能增添不少魅力与神秘感吧~',Feature=1,TFValidDate='2022-05-13 05:00:00',ValidDate='2022-05-16 05:00:00',}",
  [3005986] = "{id=3005986,NameZh='圣晶幻翼',Icon='item_3005986',Type=810,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=15621,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='圣晶打造的翼片，以牢固的金属联结并装订在一起。这双翅膀是科技的产物，也是人们对于神性与飞翔的终极幻想。',Feature=1,TFValidDate='2022-05-13 05:00:00',ValidDate='2022-05-16 05:00:00',}",
  [3005987] = "{id=3005987,NameZh='上古遗物材料礼盒·圣晶神话',Icon='item_3003303',Type=30,Quality=4,MaxNum=99999,SellPrice=100,Desc='装着上古遗物材料的礼盒，使用后必定获得其中一个：「云霞纱线」x1、「精灵神木」x1、「陈旧的号角」x1。',Feature=1,}",
  [3005990] = "{id=3005990,NameZh='海底物语',Icon='item_3005990',Type=830,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9843,AdventureValue=1,StorageReward={buffid={82000250}},Condition=8,Desc='生活在海底的生物，也有上岸享受日光浴的梦想。“感谢冒险者的魔法，我们终于不会见光死啦！”',Feature=1,TFValidDate='2022-06-01 05:00:00',ValidDate='2022-06-01 05:00:00',}",
  [3005991] = "{id=3005991,NameZh='冰瓜兔兔[1]',Icon='item_3005991',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9844,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='天气实在太热了，为了避免融化，可爱的兔兔只能去西瓜里避暑。“你问甜甜的、冰冰的西瓜瓤去了哪里？当然是被本兔兔吃掉了啦！”',Feature=1,TFValidDate='2022-06-01 05:00:00',ValidDate='2022-06-01 05:00:00',}",
  [3005992] = "{id=3005992,NameZh='夏浪兔兔',Icon='item_3005992',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9845,AdventureValue=1,StorageReward={buffid={82000220}},Condition=8,Desc='金色的阳光在海面上绽放，可爱的兔兔也有乘风破浪的梦想。“哇~海水打在身上的感觉，好清凉呀！”',Feature=1,TFValidDate='2022-06-01 05:00:00',ValidDate='2022-06-01 05:00:00',}",
  [3005993] = "{id=3005993,NameZh='西瓜冰棒',Icon='item_3005993',Type=850,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9846,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='是第一口多汁的西瓜，是盛夏里舒服的清凉~',Feature=1,TFValidDate='2022-06-01 05:00:00',ValidDate='2022-06-01 05:00:00',}",
  [3005994] = "{id=3005994,NameZh='热带部落拳刃',Icon='item_3005994',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9847,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='从远方海岛舶来的贵重之物，相传曾被岛上的巨人勇士所使用。可惜这副拳刃实在太大了，只能挂在背后作为装饰。',Feature=1,TFValidDate='2022-06-01 05:00:00',ValidDate='2022-06-01 05:00:00',LoadShowRotate=180,}",
  [3005995] = "{id=3005995,NameZh='热带部落角冠[1]',Icon='item_3005995',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9848,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='以黄金、织锦与巨大野猪獠牙制成的角冠，在部落文化中，是荣誉和勇气的象征。如今，它被授予遥远大陆上的冒险者。',Feature=1,TFValidDate='2022-06-01 05:00:00',ValidDate='2022-06-01 05:00:00',}",
  [3005996] = "{id=3005996,NameZh='狂欢椰椰精',Icon='item_3005996',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9085,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='准备参加海边狂欢节的椰椰精，不仅为自己戴上鲜花装饰了一番，还拿出了祖传的椰树叶伞盖。“不许碰，这可是我爷爷的爷爷用过的椰椰伞！”',Feature=1,TFValidDate='2022-06-01 05:00:00',ValidDate='2022-06-01 05:00:00',}",
  [3006000] = "{id=3006000,NameZh='电音节限定礼',Icon='item_3994',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='参与了电音节的特别纪念！打开之后可以获得Zeny x200,000，「福利券自选礼包」x5、「祈祷晶片自选包」x5、「金质勋章」x5、「来自女武神的馈赠」x5。',Feature=1,}",
  [3006001] = "{id=3006001,NameZh='费雷德的答谢礼',Icon='item_3736',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='费雷德送给冒险者的谢礼。多亏了你，电音节才能如期举行！打开之后必定获得Zeny x150,000，以下奖励随机获得一件：「金质勋章」x2、「光洁的符文石」x1、「神谕之尘」x6、「神谕之晶」x6、「祈祷晶片包」x2、「玛丝黛拉种子」x1。',Feature=1,}",
  [3006002] = "{id=3006002,NameZh='打工人必需品',Icon='item_6630',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='每个辛勤劳作的人，今天都值得被赞扬！打开之后可以获得Zeny x300,000，「弗雷硬币」x1、「闪耀的符文石」x1、「闪耀的符文石·星」x1、「B格猫福利券·宴」x30。',Feature=1,}",
  [3006003] = "{id=3006003,NameZh='热夜音浪',Icon='item_700185',Type=61,Quality=2,UseMode=31336,MaxNum=99999,SellPrice=100,Desc='躁动的音符响彻整个夜空，一起来快乐吧！使用之后可以打开商店，兑换稀有道具。',ExistTimeType=2,ExistTime='2025-08-01 05:00:00',Feature=1,}",
  [3006004] = "{id=3006004,NameZh='波利粉狂想曲',Icon='item_4002',Type=61,Quality=3,UseMode=31336,MaxNum=99999,SellPrice=100,Desc='这座城市怎么回事？怎么所有人都在听《波利粉狂想曲》！使用之后可以打开商店，兑换稀有道具。',ExistTimeType=2,ExistTime='2025-08-01 05:00:00',Feature=1,}",
  [3006005] = "{id=3006005,NameZh='往期头饰礼盒·5月',Icon='item_3000165',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='打开之后可以自选1件往期5月活动中产出的头饰道具：「南十字导航仪图纸」x1、「勤劳的波利们」x1、「南瓜田的守望图纸」x1、「回梦之泉图纸」x1、「星耀之门」x1、「闪耀的收获图纸」x1、「茜色回忆图纸」x1、「国王波利的威严图纸」x1、「国王波利的忧郁图纸」x1、「透明翅膀图纸」x1、「草莓棉花糖」x1。',Feature=1,ItemShow=1,}",
  [3006006] = "{id=3006006,NameZh='波利粉的典藏周边',Icon='item_3002000',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='不曾在市面上流通过的奇奇怪怪周边。仅对于粉丝而言，收藏价值极高。打开之后，以下奖励随机获得两件：「B格猫福利券·宴」x1、「B格猫福利券·Ⅰ」x1、「拾光邀请函」x1、「神谕之尘」x4、「神谕之晶」x4、「莫拉硬币」x4、「好运币」x5、「光洁的符文石」x1、「闪耀的符文石」x1、「闪耀的符文石·星」x1、「尘封的符文袋·Ⅰ」x2、「玛丝黛拉种子」x1、「祈祷晶片自选包」x1。',GetLimit={limit={[999]={3,0}},source={22},type=4},Feature=1,}",
  [3006007] = "{id=3006007,NameZh='首次演出的门票',Icon='item_1000399',Type=61,Quality=3,UseMode=31337,MaxNum=99999,SellPrice=100,Desc='只有极少数的狂热粉丝才拥有这张门票，留作纪念也是不错的选择。使用之后可以打开商店，兑换稀有道具。',GetLimit={limit={[999]={1,0}},source={22},type=4},ExistTimeType=2,ExistTime='2022-06-01 05:00:00',Feature=1,}",
  [3006008] = "{id=3006008,NameZh='波利粉的答谢礼',Icon='item_3001435',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='即将远行的波利粉乐队，留给冒险者的礼物。打开之后必定获得「料理兑换券」x1、「坠星陨铁」x1、「波利成长秘药」x1，以下奖励随机获得一件：「B格猫福利券·Ⅰ」x5、「B格猫福利券·宴」x5、「拾光邀请函」x5、「神谕之尘」x5、「神谕之晶」x5、「光洁的符文石」x2、「古拉姆晶末」x20、「金质勋章」x5、「尘封的符文袋·Ⅰ」x2、「好运币」x5、「玛丝黛拉种子」x1。',Feature=1,}",
  [3006009] = "{id=3006009,NameZh='暖暖的心意',Icon='item_3000170',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='所有美好的念想都是关于你。打开之后可以获得「暖心料理」x10、「弗雷硬币」x1、「好运币」x10、「闪耀的符文石·星」x1、「B格猫福利券·Ⅰ」x30。',Feature=1,}",
  [3006020] = "{id=3006020,NameZh='庆典自选礼盒',Icon='item_3839',Type=30,MaxNum=99999,SellPrice=100,Desc='使用之后，可以自选1个礼盒：「甜心蛋糕礼盒」x1、「暖暖蜡烛礼盒」x1、「庆典欢乐礼盒」x1。',GetLimit={limit={[999]={3,0}},source={280},type=4},Feature=1,}",
  [3006021] = "{id=3006021,NameZh='优选符文礼盒',Icon='item_3007901',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='极具性价比的符文礼盒，只有2转及以上职业才有能力打开，打开之后必定获得「闪耀的符文石」x1或「闪耀的符文石·星」x1，每当该礼盒为第5次开启时，必定额外获赠「本职业S级符文」x1或「本职业星符文」x1。',Feature=1,}",
  [3006022] = "{id=3006022,NameZh='优选萃取礼盒',Icon='item_3007903',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='极具性价比的萃取礼盒，打开之后可以获得「萃光结晶」x3~6，每当该礼盒为第5次开启时，必定额外获赠[itemid]3002601[/itemid]x1！',Feature=1,ItemShow=1,}",
  [3006023] = "{id=3006023,NameZh='优选装备礼盒',Icon='item_3007900',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='极具性价比的装备礼盒，打开之后必定获得「神之金属」x25、「铝」x25、「远古材料自选箱」x3，每当该礼盒为第5次开启时，必定额外获赠[itemid]6861[/itemid]x1！',Feature=1,ItemShow=1,}",
  [3006024] = "{id=3006024,NameZh='优选附魔礼盒',Icon='item_3007902',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='极具性价比的附魔礼盒，打开之后必定获得「莫拉金币」x4、「莫拉硬币」x20、「神谕之尘」x12、「神谕之晶」12，每当该礼盒为第5次开启时，必定额外获赠[itemid]3006025[/itemid]x1！',Feature=1,ItemShow=1,}",
  [3006025] = "{id=3006025,NameZh='附魔结晶',Icon='item_13415',Type=61,Quality=5,UseMode=10000006,MaxNum=99999,SellPrice=100,Desc='从千万次附魔中沉淀出来的晶石，可以在「普隆德拉-伊蒂亚」处兑换「附魔券」，让你的装备在附魔时直接拥有极品[enchantbuff]0[/enchantbuff]！同时也是附魔重置属性和锁定附魔属性的重要材料',Feature=1,}",
  [3006030] = "{id=3006030,NameZh='蛋糕小偷[1]',Icon='item_3006030',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=9849,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='“蛋糕怎么会不见呢~？它只是换了种方式陪伴我，吱吱吱吱~~”',Feature=1,TFValidDate='2022-07-01 05:00:00',ValidDate='2022-07-01 05:00:00',}",
  [3006031] = "{id=3006031,NameZh='唐纳滋陷阱',Icon='item_3006031',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9850,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='\"吱吱！哪个混蛋？！居然做陷阱抓我！吱吱！以为我出不去吗？吃掉不就好了！！”',Feature=1,TFValidDate='2022-07-01 05:00:00',ValidDate='2022-07-01 05:00:00',}",
  [3006032] = "{id=3006032,NameZh='谁的奶酪',Icon='item_3006032',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=9851,AdventureValue=1,StorageReward={buffid={82000230}},Condition=8,Desc='“吱！这是我的奶酪！你看！上面有我的徽章！”',Feature=1,TFValidDate='2022-07-01 05:00:00',ValidDate='2022-07-01 05:00:00',}",
  [3006033] = "{id=3006033,NameZh='无效健身',Icon='item_3006033',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9852,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='“不可以再胖下去啦！吱吱——瓜子真香——”',Feature=1,TFValidDate='2022-07-01 05:00:00',ValidDate='2022-07-01 05:00:00',}",
  [3006034] = "{id=3006034,NameZh='蛋糕卷卷',Icon='item_3006034',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9853,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='“吱吱——蛋糕卷卷的香气！嗷呜~好吃好吃~~~”',Feature=1,TFValidDate='2022-07-01 05:00:00',ValidDate='2022-07-01 05:00:00',}",
