  [3006036] = "{id=3006036,NameZh='餐后午睡',Icon='item_3006036',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9086,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='“吱——吃饱饱~睡觉觉……Zzzzzzz……”',Feature=1,TFValidDate='2022-07-01 05:00:00',ValidDate='2022-07-01 05:00:00',}",
  [3006040] = "{id=3006040,NameZh='潮流的棒球帽[1]',Icon='item_3006040',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=10534,AdventureValue=1,StorageReward={buffid={80011150}},Condition=8,Desc='是最潮流的长春花蓝，在冒险的道路上，闪烁着最耀眼的光！',Feature=1,TFValidDate='2030-03-24 05:00:00',ValidDate='2030-04-07 05:00:00',}",
  [3006041] = "{id=3006041,NameZh='热血的棒球帽[1]',Icon='item_3006041',Type=800,Quality=4,MaxNum=99,SellPrice=100,AdventureSort=10533,AdventureValue=1,StorageReward={buffid={80011150}},Condition=8,Desc='是不服输的好战精神汇聚而成的那一抹红，在米德加尔特大陆散发着耀眼的光！',Feature=1,TFValidDate='2022-03-24 05:00:00',ValidDate='2022-04-07 05:00:00',}",
  [3006060] = "{id=3006060,NameZh='归来的祝愿',Icon='item_3004253',Type=61,UseMode=31338,MaxNum=99999,SellPrice=100,Desc='为久别重逢的冒险者准备的礼物，可以在「旅途再续」商店中兑换奖励。\n与回归冒险者组队，完成以下副本获得：恩德勒斯塔、神谕副本、达纳托斯塔、波纳佩博物岛、探秘迷踪岛、瓦尔哈拉遗迹、无限回廊、尼夫海姆炼狱。',ExistTimeType=2,ExistTime='2022-06-10 05:00:00',Feature=1,}",
  [3006061] = "{id=3006061,NameZh='邂逅的赠礼',Icon='item_3005174',Type=4208,UseMode=31302,MaxNum=99999,SellPrice=100,Desc='为久别重逢的冒险者准备的福利，使用后可以在「世界频道」免费发放Zeny红包哦~',ExistTimeType=2,ExistTime='2022-06-10 05:00:00',Feature=1,}",
  [3006062] = "{id=3006062,NameZh='公会的赠礼',Icon='item_3034266',Type=4208,UseMode=31302,MaxNum=99999,SellPrice=100,Desc='为久别重逢的冒险者准备的福利，使用后可以在「公会频道」免费发放Zeny红包哦~',ExistTimeType=2,ExistTime='2022-06-10 05:00:00',Feature=1,}",
  [3006063] = "{id=3006063,NameZh='重逢的谢礼',Icon='item_6512',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='只要热情帮助他人，就能得到特别的眷顾！打开后，必定获得「归来的祝愿」x15，随机获得以下奖励中的1种：「神谕补给箱」x5、Zeny x100,000，「好运币」x2，「玛丝黛拉种子」x1、限定背饰「长夜晦明」x1。',Feature=1,}",
  [3006070] = "{id=3006070,NameZh='丛林探险家·冷苔',Icon='item_3006070',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='落日的旷野吹来秋日的风，骤来的雨水拍打过青苔与玫瑰，让空气溢满泥土的清香，用心保持这块土地的样子，过你想过的生活！即使戴着蝴蝶结草帽的女孩儿，今日还没有从你的身边经过。',Feature=1,TFValidDate='2022-11-16 05:00:00',ValidDate='2022-11-16 05:00:00',MainColor='395923FF',}",
  [3006071] = "{id=3006071,NameZh='丛林探险家·赤霞',Icon='item_3006070',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='落日的旷野吹来秋日的风，繁花盛开的枝丫低垂在眼帘。明亮的霞光照耀脸庞，一时间恍惚忘记了花开。',Feature=1,TFValidDate='2022-11-16 05:00:00',ValidDate='2022-11-16 05:00:00',MainColor='d13935FF',}",
  [3006072] = "{id=3006072,NameZh='丛林探险家·姜茶',Icon='item_3006070',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='落日的旷野吹来秋日的风，繁花盛开的枝丫低垂在眼帘。不远处堆放着新鲜的水果，散发着层次丰富的香味，每一层都被有心之人写进诗里，酿成爱意。',Feature=1,TFValidDate='2022-11-16 05:00:00',ValidDate='2022-11-16 05:00:00',MainColor='f8cd56FF',}",
  [3006073] = "{id=3006073,NameZh='丛林探险家·蓝莓',Icon='item_3006070',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='落日的旷野吹来秋日的风，繁花盛开的枝丫低垂在眼帘。远方的大海重新变成靛蓝色，潮湿但热烈，永远生机勃勃！',Feature=1,TFValidDate='2022-11-16 05:00:00',ValidDate='2022-11-16 05:00:00',MainColor='4147edFF',}",
  [3006080] = "{id=3006080,NameZh='丛林冒险家·冷苔',Icon='item_3006080',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='落日的旷野吹来秋日的风，骤来的雨水拍打过青苔与玫瑰，让空气溢满泥土的清香，精神城堡的大门自此开启，成就了拥有魔法的秋日光景。',Feature=1,TFValidDate='2022-11-16 05:00:00',ValidDate='2022-11-16 05:00:00',MainColor='395923FF',}",
  [3006081] = "{id=3006081,NameZh='丛林冒险家·赤霞',Icon='item_3006080',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='落日的旷野吹来秋日的风，繁花盛开的枝丫低垂在眼帘。明亮的霞光照耀脸庞，莫名地有一种快乐充斥在心间。',Feature=1,TFValidDate='2022-11-16 05:00:00',ValidDate='2022-11-16 05:00:00',MainColor='d13935FF',}",
  [3006082] = "{id=3006082,NameZh='丛林冒险家·姜茶',Icon='item_3006080',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='落日的旷野吹来秋日的风，繁花盛开的枝丫低垂在眼帘。不远处堆放着新鲜的水果，散发着层次丰富的香味，秋季的田野从头至尾都是美食的调调。',Feature=1,TFValidDate='2022-11-16 05:00:00',ValidDate='2022-11-16 05:00:00',MainColor='f8cd56FF',}",
  [3006083] = "{id=3006083,NameZh='丛林冒险家·蓝莓',Icon='item_3006080',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='落日的旷野吹来秋日的风，繁花盛开的枝丫低垂在眼帘。躺在透蓝的天空下，秋季成为了心中最完美的甜蜜季节。',Feature=1,TFValidDate='2022-11-16 05:00:00',ValidDate='2022-11-16 05:00:00',MainColor='4147edFF',}",
