  [3006086] = "{id=3006086,NameZh='丛林法则时装兑换券',Icon='item_3006086',Type=121,MaxNum=99999,SellPrice=100,Desc='使用之后可以获得一件对应阁下性别的丛林法则系列时装哦~',Feature=1,}",
  [3006087] = "{id=3006087,NameZh='丛林法则时装自选券',Icon='item_3006086',Type=61,UseMode=31353,MaxNum=99999,SellPrice=100,Desc='使用之后可以兑换任意一件丛林法则系列时装哦~',Feature=1,}",
  [3006090] = "{id=3006090,NameZh='丛林精神·诗',Icon='item_3006070',Type=501,MaxNum=99,SellPrice=100,Desc='落日的旷野吹来秋日的风，开始结果的枝丫低垂在眼帘。整个傍晚都可以坐在湖边略带湿气的草地上，摩挲手边的游记，那是曾经感知过的没有边界的天地。',Feature=1,TFValidDate='2022-11-16 05:00:00',ValidDate='2022-11-16 05:00:00',MainColor='bfcc5fFF',}",
  [3006091] = "{id=3006091,NameZh='丛林精神·花',Icon='item_3006080',Type=501,MaxNum=99,SellPrice=100,Desc='落日的旷野吹来秋日的风，繁花盛开的枝丫低垂在眼帘。整个傍晚都可以坐在湖边略带湿气的草地上，哼着随意想起的曲调，歌声里有曾经感知过的没有边界的天地。',Feature=1,TFValidDate='2022-11-16 05:00:00',ValidDate='2022-11-16 05:00:00',MainColor='bfcc5fFF',}",
  [3006092] = "{id=3006092,NameZh='丛林精神时装兑换券',Icon='item_3006092',Type=121,MaxNum=99999,SellPrice=100,ComposeID=4000095,Desc='使用之后可以获得一件对应阁下性别的丛林精神系列时装哦~',Feature=1,}",
  [3006093] = "{id=3006093,NameZh='丛林精神系列时装',Icon='item_3006084',Type=501,MaxNum=99,SellPrice=100,AdventureSort=15656,AdventureValue=1,Condition=8,Feature=1,TFValidDate='2022-11-16 05:00:00',ValidDate='2022-11-16 05:00:00',MainColor='bfcc5fFF',}",
  [3006100] = "{id=3006100,NameZh='林间朝阳·冷苔',Icon='item_3006100',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='调皮的微风吹乱草帽，带来潮湿林间的味道，整个秋日也至此丰沛了起来，宛如在梦中。',Feature=1,TFValidDate='2022-11-16 05:00:00',ValidDate='2022-11-16 05:00:00',MainColor='a86b12FF',}",
  [3006101] = "{id=3006101,NameZh='林间朝阳·赤霞',Icon='item_3006100',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='墨色的眼镜装饰在头顶，宽大的帽檐遮挡住耀眼的阳光，但却不会遮挡我们看向外面的世界，那个由一束光所呈现出的世界。',Feature=1,TFValidDate='2022-11-16 05:00:00',ValidDate='2022-11-16 05:00:00',MainColor='221c19FF',}",
  [3006102] = "{id=3006102,NameZh='林间朝阳·姜茶',Icon='item_3006100',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='白天热气褪去后的秋夜带了些许凉意，适合取一点肉桂与生姜细细磨碎，冲进清香的茶中，温和的辛香温暖肠胃，白天忙碌的精神可以得到彻底的放松。',Feature=1,TFValidDate='2022-11-16 05:00:00',ValidDate='2022-11-16 05:00:00',MainColor='56291eFF',}",
  [3006103] = "{id=3006103,NameZh='林间朝阳·蓝莓',Icon='item_3006100',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='顶着宽大的帽檐走过小径交织的秋日花园，这里的每一束盛放都让你感到欣慰，每一束盛放，都是爱的回应。',Feature=1,TFValidDate='2022-11-16 05:00:00',ValidDate='2022-11-16 05:00:00',MainColor='e2e6f8FF',}",
  [3006104] = "{id=3006104,NameZh='林间朝阳头饰系列',Icon='item_3006100',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15647,AdventureValue=1,StorageReward={buffid={80012930}},Condition=8,Feature=1,TFValidDate='2022-11-16 05:00:00',ValidDate='2022-11-16 05:00:00',MainColor='X',}",
  [3006105] = "{id=3006105,NameZh='林间柔光·冷苔',Icon='item_3006105',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='调皮的微风吹乱草帽，带来雨后泥土的香气和整个秋天的美好时光，让人恣意沉迷。',Feature=1,TFValidDate='2022-11-16 05:00:00',ValidDate='2022-11-16 05:00:00',MainColor='a86b12FF',}",
  [3006106] = "{id=3006106,NameZh='林间柔光·赤霞',Icon='item_3006105',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='轻巧的蝴蝶结装饰在头顶，宽大的帽檐遮挡住耀眼的阳光，但却不会遮挡我们看向外面的世界，那个由一束光所呈现出的世界。',Feature=1,TFValidDate='2022-11-16 05:00:00',ValidDate='2022-11-16 05:00:00',MainColor='221c19FF',}",
  [3006107] = "{id=3006107,NameZh='林间柔光·姜茶',Icon='item_3006105',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='白天热气褪去后的秋夜带了些许凉意，适合取一点肉桂与生姜细细磨碎，冲进清香的茶中，温和的辛香温暖肠胃，心灵自此更加恬静。',Feature=1,TFValidDate='2022-11-16 05:00:00',ValidDate='2022-11-16 05:00:00',MainColor='56291eFF',}",
  [3006108] = "{id=3006108,NameZh='林间柔光·蓝莓',Icon='item_3006105',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='带着靛蓝色的蝴蝶结走过小径交织的秋日花园，接受所有的光彩，所有的生长，所有让人欣喜的活泼。',Feature=1,TFValidDate='2022-11-16 05:00:00',ValidDate='2022-11-16 05:00:00',MainColor='e2e6f8FF',}",
  [3006109] = "{id=3006109,NameZh='林间柔光头饰系列',Icon='item_3006105',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15648,AdventureValue=1,StorageReward={buffid={80012920}},Condition=8,Feature=1,TFValidDate='2022-11-16 05:00:00',ValidDate='2022-11-16 05:00:00',MainColor='X',}",
  [3006110] = "{id=3006110,NameZh='丛林法则头饰兑换券',Icon='item_3006110',Type=61,UseMode=31354,MaxNum=99999,SellPrice=100,Desc='使用之后可以兑换任意一件丛林法则系列头饰哦~',Feature=1,}",
  [3006111] = "{id=3006111,NameZh='小小旅行家',Icon='item_3006111',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15649,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='朝阳就要升起，从帐篷探出头的小仓鼠也已经做好了万全的准备。难得露营的好日子，要用心感受路上的景色，一刻也不能错过。',Feature=1,TFValidDate='2022-11-16 05:00:00',ValidDate='2022-11-16 05:00:00',}",
  [3006112] = "{id=3006112,NameZh='怪怪户外包',Icon='item_3006112',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15650,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='徒步野营时最适合携带的包包，倒不是说它有大的容量，而是背包小精灵会偷偷帮你准备很多意想不到的东西，在你不知所措的时候拿出来帮你渡过难关。但……怎么说呢，这包自重也就变得不轻了倒也是真的……',Feature=1,TFValidDate='2022-11-16 05:00:00',ValidDate='2022-11-16 05:00:00',}",
  [3006113] = "{id=3006113,NameZh='温暖独眼仔',Icon='item_3006113',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15651,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='独眼仔会拿手里的蘑菇灯帮你照亮来时的路，顺便咿咿呀呀说些笑话逗你开心。有他在身后，会有满满的安全感，独自一人走夜路也不会害怕了。',Feature=1,TFValidDate='2022-11-16 05:00:00',ValidDate='2022-11-16 05:00:00',}",
  [3006114] = "{id=3006114,NameZh='绝佳视野',Icon='item_3006114',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15652,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='从老一辈远航者那里得到的贵重礼物，手持的铜制双筒望远镜是露营的必备。躺在草地上用它看天空，你会看到云朵与飞鸟;看到自己柔软且舒展的内心。',Feature=1,TFValidDate='2022-11-16 05:00:00',ValidDate='2022-11-16 05:00:00',}",
  [3006115] = "{id=3006115,NameZh='春河边的烤鱼',Icon='item_3006115',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15653,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='没有烤鱼的野营是不完整的！均匀的炭火、新鲜的活鱼、肆意散发的香气配上牙齿接触皮脂发出的第一声脆响！这或许就是人们对于融入或回归自然，最根本的期待。',Feature=1,TFValidDate='2022-11-16 05:00:00',ValidDate='2022-11-16 05:00:00',}",
  [3006116] = "{id=3006116,NameZh='萤光的指引',Icon='item_3006116',Type=810,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=15654,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='秋日的夜色，让人不经意间便可身处在飘落的花丛中。',Feature=1,TFValidDate='2022-11-16 05:00:00',ValidDate='2022-11-16 05:00:00',}",
  [3006117] = "{id=3006117,NameZh='上古遗物材料礼盒·怒火焚世',Icon='item_3003303',Type=30,Quality=4,MaxNum=99999,SellPrice=100,Desc='装着上古遗物材料的礼盒，使用后必定获得其中一个：「变形头盔的碎片」x1、「女武神的砾石」x1、「冥思之石」x1。',Feature=1,}",
  [3006118] = "{id=3006118,NameZh='上古遗物材料礼盒·丛林法则',Icon='item_3003303',Type=30,Quality=4,MaxNum=99999,SellPrice=100,Desc='装着上古遗物材料的礼盒，使用后必定获得其中一个：「变形头盔」x1、「常青槲寄生」x1、「天地树琥珀」x1。',Feature=1,}",
  [3006120] = "{id=3006120,NameZh='暑意未浓·赤蜻',Icon='item_3006120',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='阳光越发炽烈，夏日的脚步已然临近。拿上网兜，一起去捕捉罕见的红色蜻蜓吧！',Feature=1,TFValidDate='2022-07-16 05:00:00',ValidDate='2022-07-16 05:00:00',MainColor='d13935FF',}",
  [3006121] = "{id=3006121,NameZh='暑意未浓·菱鲜',Icon='item_3006120',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='阳光越发炽烈，夏日的脚步已然临近。唔，想吃菱角了……要不去问问船家，可有新鲜货？',Feature=1,TFValidDate='2022-07-16 05:00:00',ValidDate='2022-07-16 05:00:00',MainColor='8c58edFF',}",
