  [3006163] = "{id=3006163,NameZh='盒盒虾',Icon='item_3006163',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15641,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='不断颤动的可疑盒子，似乎装着危险物品……“噗噗，人家只是想要上岸的虾虾而已。因为离不开水，才躲在盛着水的盒子里啊！”',Feature=1,TFValidDate='2022-07-16 05:00:00',ValidDate='2022-07-16 05:00:00',}",
  [3006164] = "{id=3006164,NameZh='鲜妍妆',Icon='item_3006164',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15642,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='充满个性的面妆，尤其是一双眉毛，被削短描浓成了垂珠眉的样式。配合橘红色的美瞳，显示出一种凌厉的美感。',Feature=1,TFValidDate='2022-07-16 05:00:00',ValidDate='2022-07-16 05:00:00',}",
  [3006165] = "{id=3006165,NameZh='口中鲜',Icon='item_3006165',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15643,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='刚刚从湖水里打捞而出的活虾，无论怎么烹制都鲜美异常，叫人忍不住一口一只！',Feature=1,TFValidDate='2022-07-16 05:00:00',ValidDate='2022-07-16 05:00:00',}",
  [3006166] = "{id=3006166,NameZh='飞鹰逐日',Icon='item_3006166',Type=810,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=15644,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='鹰王统御天空，追逐日升日落。它们的羽毛即便被做成饰物，仍旧散发着骄阳灼热的气息。',Feature=1,TFValidDate='2022-07-16 05:00:00',ValidDate='2022-07-16 05:00:00',}",
  [3006167] = "{id=3006167,NameZh='上古遗物材料礼盒·夏时景',Icon='item_3003303',Type=30,Quality=4,MaxNum=99999,SellPrice=100,Desc='装着上古遗物材料的礼盒，使用后必定获得其中一个：「云霞纱线」x1、「精灵神木」x1、「陈旧的号角」x1。',}",
  [3006170] = "{id=3006170,NameZh='魔焰御兽契约',Icon='item_25211',Type=41,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='封印着魔焰御兽的契约，使用后可以获得限定坐骑[itemid]25211[/itemid]！契约在未使用前可上架交易所自由交易，使用后获得的坐骑将与冒险者绑定灵魂关系，无法再上架交易所，请各位冒险者谨慎使用！',Feature=1,}",
  [3006171] = "{id=3006171,NameZh='魔焰御兽礼盒Ⅰ',Icon='item_3896',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='使用之后可以获得「圣兽精华」x1、「神谕之尘」x5、「神谕之晶」x5、「祈祷晶片包」x2。\n「圣兽精华」为代币类道具，可以兑换[itemid]3006170[/itemid]、[itemid]3005491[/itemid]等稀有奖励。',Feature=1,}",
  [3006172] = "{id=3006172,NameZh='魔焰御兽礼盒Ⅱ',Icon='item_3897',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='使用之后必定获得Zeny x 750,000、「圣兽精华」x1，有概率获得以下道具中的一种：「天火碎片」x1、「神谕之尘」x15~30、「神谕之晶」x12~25、「诺伦卡片」x100~200、「古拉姆晶末」x100、「金质勋章」x10、「魔力树枝·王室」x2、「金之星」x1。0.5%概率额外获赠[itemid]3006170[/itemid]x1、0.5%概率额外获赠[itemid]3005491[/itemid]x1。（「诺伦的指引·月」为解锁类道具，使用后可以解锁一张未解锁的Mvp卡片。「魔焰御兽契约」可上架交易所。）',Feature=1,}",
  [3006173] = "{id=3006173,NameZh='圣兽精华',Icon='item_6208',Type=61,Quality=2,UseMode=31339,MaxNum=99999,SellPrice=100,Desc='圣兽身上流淌着的精华，使用后可以打开商店，兑换各类稀有道具！',Feature=1,}",
  [3006176] = "{id=3006176,NameZh='精选远古装备·盔甲',Icon='item_42054',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='使用后可以自选1件精良品质的远古盔甲，助你赢在冒险的起跑线上！仅限二转以上职业开启。',Feature=1,}",
  [3006177] = "{id=3006177,NameZh='战斗时长恢复剂·30分钟',Icon='item_3005420',Type=41,Quality=4,MaxNum=99999,SellPrice=100,Desc='吉芬魔法部最新推出的超级强力特效药剂！只需一瓶，就可以临时延长你的战斗时间，只是临时哦，该药剂没有使用限制，但到第二天药剂的效果会消失哦！使用后可立即恢复30分钟战斗时长。',Feature=1,}",
  [3006178] = "{id=3006178,NameZh='萌新特典·7天',Icon='item_810005',Type=47,Quality=4,MaxNum=99999,SellPrice=100,Desc='著名的卡普拉公司准备了一份特别的「限定特典」给大家，这将是在常规自然月限定特典以外的一个独立纪念版，只有你们才会获得！使用后可以激活「限定特典」特权，持续7天！',Feature=1,}",
  [3006179] = "{id=3006179,NameZh='离线战斗资格证·7天',Icon='item_163',Type=41,MaxNum=99999,SellPrice=100,Desc='使用后可获得7天的离线战斗使用资格，天数可以累加，剩余天数不足并不会影响已经开启的离线战斗。',Feature=1,}",
