  [3006411] = "{id=3006411,NameZh='军备红包袋',Icon='item_3002302',Type=30,Quality=2,MaxNum=1,SellPrice=100,Desc='公会的发展离不开各位菁英的无私奉献，这是给予他们最好的嘉奖！每隔3天可开启一次，共计可获得「B格猫金币」x3288的公会红包！',Feature=1,}",
