  [3006422] = "{id=3006422,NameZh='蛇妖的卡片珍藏',Icon='item_5850',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='蛇妖戈耳工的卡片珍藏，使用之后必定获得「诺伦卡片」x50、「古拉姆晶末」x20，以下道具随机获得一种：[itemid]3005491[/itemid]x1、「蓝疯兔卡片」x1、「蛙王卡片」x1、「莉姆露卡片」x1、「兽人婴儿卡片」x1、「远古魔力卡册」x1、「神谕专属卡片」x1、「贝壳魔灵卡片」x1、「米诺斯卡片」x1、「吃人草卡片」x1、「甜心罗达蛙卡片」x1、「精装埃米尔的卡册」x1、「埃米尔卡册」x1。0.2%概率额外获赠[itemid]23051[/itemid]x1。\n「诺伦的指引·月」、「蛇妖戈耳工卡片」的概率将随着开启次数的增加而增加：最多在开启第200个礼盒时，必定获得「诺伦的指引·月」；最多在开启第400个礼盒时，必定获得「蛇妖戈耳工卡片」！\n「蛇妖戈耳工卡片」、「诺伦的指引·月」两个道具的保底均仅可触发1次，若在保底次数之前已经获得该道具，则保底将取消。（通过礼盒直接获得的卡片可在冒险手册解锁。）',Feature=1,ItemShow=1,}",
  [3006423] = "{id=3006423,NameZh='蛇妖的卡片珍藏x10',Icon='item_3005821',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='蛇妖戈耳工的卡片珍藏，使用之后可以获得[itemid]3006422[/itemid]x10！',Feature=1,ItemShow=1,}",
  [3006424] = "{id=3006424,NameZh='赛博惠比特契约',Icon='item_25196',Type=41,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='封印着赛博惠比特的契约，使用后可以获得限定坐骑[itemid]25196[/itemid]！契约在未使用前可上架交易所自由交易，使用后获得的坐骑将与冒险者绑定灵魂关系，无法再上架交易所，请各位冒险者谨慎使用！',Feature=1,}",
  [3006425] = "{id=3006425,NameZh='赛博猎犬礼盒Ⅰ',Icon='item_3896',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='使用之后可以获得「赛博结晶」x1、「神谕之尘」x5、「神谕之晶」x5、「祈祷晶片包」x2。\n「赛博结晶」为代币类道具，可以兑换[itemid]3006424[/itemid]、[itemid]3005491[/itemid]等稀有奖励。',Feature=1,}",
  [3006426] = "{id=3006426,NameZh='赛博猎犬礼盒Ⅱ',Icon='item_3897',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='使用之后必定获得Zeny x 750,000、「赛博结晶」x1，有概率获得以下道具中的一种：「天火碎片」x1、「神谕之尘」x15~30、「神谕之晶」x12~25、「诺伦卡片」x100~200、「古拉姆晶末」x100、「金质勋章」x10、「魔力树枝·王室」x2、「金之星」x1。0.5%概率额外获赠[itemid]3006424[/itemid]x1、0.5%概率额外获赠[itemid]3005491[/itemid]x1。（「诺伦的指引·月」为解锁类道具，使用后可以解锁一张未解锁的Mvp卡片。「赛博惠比特契约」可上架交易所。）',Feature=1,}",
  [3006427] = "{id=3006427,NameZh='赛博结晶',Icon='item_700109',Type=61,Quality=2,UseMode=31347,MaxNum=99999,SellPrice=100,Desc='赛博惠比特最喜欢的东西，使用后可以打开商店，兑换各类稀有道具！',Feature=1,}",
  [3006428] = "{id=3006428,NameZh='命运之光',Icon='item_6951',Type=77,MaxNum=1,SellPrice=100,AdventureSort=1001,AdventureValue=1,StorageReward={buffid={82000110}},Condition=8,Desc='可以承载伊米尔之心碎片的神圣容器，来自英雄的达纳托斯。它能和伊米尔之心的碎片产生共鸣，为命运之风带来霜巨人伊米尔的祝福与对抗邪祟的强大力量。',Feature=1,TFValidDate='2020-12-30 05:00:00',ValidDate='2021-01-06 05:00:00',}",
  [3006430] = "{id=3006430,NameZh='玉树长衫·清辉',Icon='item_3006430',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='缎面绣着金纹，收紧的腰线更显英姿勃发。苍蓝与素白的配色，为你增添明月般清傲的气质。',Feature=1,TFValidDate='2022-09-16 05:00:00',ValidDate='2022-09-16 05:00:00',MainColor='696ed8FF',}",
