  [3006484] = "{id=3006484,NameZh='猫妖的卡片珍藏',Icon='item_5850',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='迷梦猫妖的卡片珍藏，使用之后必定获得「诺伦卡片」x50、「古拉姆晶末」x20，以下道具随机获得一种：[itemid]3005491[/itemid]x1、「爱丽丝女仆卡片」x1、「娣洁卡片」x1、「巴西里斯克卡片」x1、「火焰鸟啾利卡片」x1、「远古魔力卡册」x1、「神谕专属卡片」x1、「沙漠之狼卡片」x1、「月光三角兽卡片」x1、「鱼人卡片」x1、「海獭卡片」x1、「精装埃米尔的卡册」x1、「埃米尔卡册」x1。0.2%概率额外获赠[itemid]23060[/itemid]x1。\n「诺伦的指引·月」、「迷梦猫妖卡片」的概率将随着开启次数的增加而增加：最多在开启第200个礼盒时，必定获得「诺伦的指引·月」；最多在开启第400个礼盒时，必定获得「迷梦猫妖卡片」！\n「迷梦猫妖卡片」、「诺伦的指引·月」两个道具的保底均仅可触发1次，若在保底次数之前已经获得该道具，则保底将取消。（通过礼盒直接获得的卡片可在冒险手册解锁。）',Feature=1,ItemShow=1,}",
  [3006485] = "{id=3006485,NameZh='猫妖的卡片珍藏x10',Icon='item_3005821',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='迷梦猫妖的卡片珍藏，使用之后可以获得[itemid]3006484[/itemid]x10！',Feature=1,ItemShow=1,}",
  [3006486] = "{id=3006486,NameZh='上古遗物材料礼盒·月影霓裳',Icon='item_3003303',Type=30,Quality=4,MaxNum=99999,SellPrice=100,Desc='装着上古遗物材料的礼盒，使用后必定获得其中一个：「云霞纱线」x1、「精灵神木」x1、「陈旧的号角」x1。',Feature=1,}",
  [3006490] = "{id=3006490,NameZh='手制点心袋',Icon='item_1000239',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='纯手工制作的各种点心，心意满满！打开之后可以获得Zeny x200,000，「福利券自选礼包」x5、「祈祷晶片自选包」x5、「金质勋章」x5、「来自女武神的馈赠」x5。',Feature=1,}",
