  [3006828] = "{id=3006828,NameZh='每日福袋',Icon='item_6508',Type=74,Quality=2,MaxNum=99999,SellPrice=100,Desc='看起来装得满满的，不知道里面会有什么好东西呢？打开之后，有概率获得以下道具中的一种：「福利券自选礼包」x1、「莫拉硬币」x5、「神谕之尘」x5、「神谕之晶」x5。每当该福袋为第3次开启时，必定获得 「福利券自选礼包 」x1。',Feature=1,}",
  [3006830] = "{id=3006830,NameZh='圣诞福袋',Icon='item_3006830',Type=810,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10567,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='圣诞老人的大福袋，里面装着要分送给世界各地孩子的礼物。',Feature=1,TFValidDate='2022-11-24 05:00:00',ValidDate='2022-12-01 05:00:00',}",
