  [3006832] = "{id=3006832,NameZh='特殊的赠礼',Icon='item_6842',Type=30,MaxNum=99999,SellPrice=100,Desc='使用后可以自选「万象天书[1]」x1或「诸天星图[1]」x1。',Feature=1,}",
  [3006833] = "{id=3006833,NameZh='顶级食材',Icon='item_3000561',Type=62,MaxNum=99999,SellPrice=100,Desc='每位厨师都会喜欢的顶级食材，只要稍稍加工一下，就会变得非常美味！',ExistTimeType=2,ExistTime='2022-11-01 05:00:00',Feature=1,}",
  [3006834] = "{id=3006834,NameZh='珍珠奶茶',Icon='item_1000018',Type=62,MaxNum=99999,SellPrice=100,Desc='甘美的红茶加上浓郁的牛奶，再配上Q弹的珍珠，从嘴里甜到心头，没有人会不喜欢吧？',ExistTimeType=2,ExistTime='2022-11-01 05:00:00',Feature=1,}",
  [3006835] = "{id=3006835,NameZh='白熊玩偶',Icon='item_53855',Type=62,MaxNum=99999,SellPrice=100,Desc='按照白熊的模样制作的玩偶，相当憨态可掬，让人备感亲切，因此深深获得女性及小孩子们的喜爱。',ExistTimeType=2,ExistTime='2022-11-01 05:00:00',Feature=1,}",
  [3006836] = "{id=3006836,NameZh='奥西里斯的谢礼',Icon='item_3708',Type=30,MaxNum=99999,SellPrice=100,Desc='奥西里斯送给她最喜欢的人的礼物，打开之后必定获得Zeny x 150,000、「福利券自选礼盒」x5、「祈祷晶片自选包」x5、「金质勋章」x5、「来自女武神的馈赠」x5。',Feature=1,}",
  [3006837] = "{id=3006837,NameZh='往期头饰礼盒·10月',Icon='item_6068',Type=30,MaxNum=99999,SellPrice=100,Desc='那些错过的美好，终有重逢之时。打开后，自行选择获得以下奖励的一种：「绒绒卡普拉」x1、「鱼子酱寿司图纸」x1、「河豚料理师图纸」x1、「愤怒的魔锅蛋图纸」x1、「旋风锅铲」x1、「厨神之魂图纸」x1、「草莓棉花糖」x1。',Feature=1,}",
  [3006838] = "{id=3006838,NameZh='随机礼物盒',Icon='item_1000107',Type=30,MaxNum=99999,SellPrice=100,Desc='不知道送什么？随机一个准没错！打开后，随机获得以下奖励的一种：「顶级食材」x3、「珍珠奶茶」x3、「白熊玩偶」x3。',Feature=1,}",
