  [3006944] = "{id=3006944,NameZh='冰雪猎人',Icon='item_3006944',Type=810,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9883,AdventureValue=1,StorageReward={buffid={82000200}},Condition=8,Desc='背上这只弓，你就是冰雪中最靓的那个仔。',Feature=1,TFValidDate='2022-12-01 05:00:00',ValidDate='2022-12-01 05:00:00',}",
  [3006945] = "{id=3006945,NameZh='风暴勇士',Icon='item_3006945',Type=830,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9884,AdventureValue=1,StorageReward={buffid={82000210}},Condition=8,Desc='命运对勇士低语：你无法抵御风暴，勇士高声回应：谢谢，我戴了挡风镜。',Feature=1,TFValidDate='2022-12-01 05:00:00',ValidDate='2022-12-01 05:00:00',}",
  [3006946] = "{id=3006946,NameZh='软绵绵冰淇淋',Icon='item_3006946',Type=840,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=9091,AdventureValue=1,StorageReward={buffid={80012640}},Condition=8,Desc='一团永远也不会融化的冰淇淋，就是咬起来会吃到一嘴毛。',Feature=1,TFValidDate='2022-12-01 05:00:00',ValidDate='2022-12-01 05:00:00',}",
  [3006950] = "{id=3006950,NameZh='溶雪星辰·烟火',Icon='item_3006950',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='我曾经梦见过大雪中的奇异光影，游荡在黄昏赤橙的光晕下，闪亮到要敲开下一个黎明的大门。能工巧匠将这片景色裁剪下，编织成华服，让灵魂即使在寂寥天地，也能感受到的温暖与希望。',Feature=1,TFValidDate='2022-12-16 05:00:00',ValidDate='2022-12-16 05:00:00',MainColor='e2e6f8FF',}",
  [3006951] = "{id=3006951,NameZh='溶雪星辰·烈焰',Icon='item_3006950',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='我曾经梦见过雪夜里火一般热烈的心境，游荡在暗夜痛苦的光晕下，闪亮到要敲开下一个黎明的大门。能工巧匠将这片景色裁剪下，编织成华服。让灵魂即使在寂寥天地，也能感受到的温暖与希望。',Feature=1,TFValidDate='2022-12-16 05:00:00',ValidDate='2022-12-16 05:00:00',MainColor='221c19FF',}",
  [3006952] = "{id=3006952,NameZh='溶雪星辰·沐白',Icon='item_3006950',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='我曾经梦见过雪夜里荒凉的忏悔，游荡在沐白的光晕与洁净的高空中。能工巧匠将这片景色裁剪下，编织成华服。梦想无论多么孤单，总能找到希望的微光。',Feature=1,TFValidDate='2022-12-16 05:00:00',ValidDate='2022-12-16 05:00:00',MainColor='a9b7d9FF',}",
  [3006953] = "{id=3006953,NameZh='溶雪星辰·馨晴',Icon='item_3006950',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='我曾经梦见过白日雪天闪光的身影，在大地折射出比春天还绚烂的光影。能工巧匠将这片景色裁剪下，编织成华服。离开不是空白，是给即将到来的世纪鲜活的生命力。',Feature=1,TFValidDate='2022-12-16 05:00:00',ValidDate='2022-12-16 05:00:00',MainColor='bfcc5fFF',}",
  [3006960] = "{id=3006960,NameZh='飘雪星辰·烟火',Icon='item_3006960',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='我曾经梦见过雪夜里火一般热烈的心境，划破死寂一般的黑夜。能工巧匠将这片景色裁剪下，编织成华服。燃烧清风拂过皑皑白雪，带来生机与希望',Feature=1,TFValidDate='2022-12-16 05:00:00',ValidDate='2022-12-16 05:00:00',MainColor='e2e6f8FF',}",
  [3006961] = "{id=3006961,NameZh='飘雪星辰·烈焰',Icon='item_3006960',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='我曾经梦见过雪夜里火一般热烈的心境，游荡在暗夜痛苦的光晕下，闪亮到要敲开下一个黎明的大门。能工巧匠将这片景色裁剪下，编织成华服。燃烧清风拂过皑皑白雪，带来生机与希望',Feature=1,TFValidDate='2022-12-16 05:00:00',ValidDate='2022-12-16 05:00:00',MainColor='221c19FF',}",
  [3006962] = "{id=3006962,NameZh='飘雪星辰·沐白',Icon='item_3006960',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='我曾经梦见过雪夜里荒凉的忏悔，游荡在沐白的光晕与洁净的高空中。能工巧匠将这片景色裁剪下，编织成华服。灵魂之舞从未停止，它是熠熠星光。',Feature=1,TFValidDate='2022-12-16 05:00:00',ValidDate='2022-12-16 05:00:00',MainColor='a9b7d9FF',}",
  [3006963] = "{id=3006963,NameZh='飘雪星辰·馨晴',Icon='item_3006960',Type=501,Quality=4,MaxNum=99,SellPrice=100,AdventureReward={buffid={62000040}},StorageReward={buffid={82000040}},Desc='我曾经梦见过白日雪天闪光的身影，在大地折射出比春天还绚烂的光影。能工巧匠将这片景色裁剪下，编织成华服。雪花飘摇，但世间艳丽不减。',Feature=1,TFValidDate='2022-12-16 05:00:00',ValidDate='2022-12-16 05:00:00',MainColor='bfcc5fFF',}",
