  [3006970] = "{id=3006970,NameZh='踏雪行歌·蔚蓝',Icon='item_3006950',Type=501,MaxNum=99,SellPrice=100,Desc='我曾经梦见过天鹅绒般大雪降下，盖住大海的瞬间。亦热亦冷，呼啸却又带着无边的荒凉。能工巧匠将这片景色裁剪下，编织成华服。凛冽的海风与暴雪让人迹罕至，但心依旧想扬帆远行。',Feature=1,TFValidDate='2022-12-16 05:00:00',ValidDate='2022-12-16 05:00:00',MainColor='5451a2FF',}",
  [3006971] = "{id=3006971,NameZh='履雪高歌·蔚蓝',Icon='item_3006960',Type=501,MaxNum=99,SellPrice=100,Desc='我曾经梦见过天鹅绒般大雪降下，盖住大海的瞬间。亦热亦冷，呼啸却又带着无边的荒凉。能工巧匠将这片景色裁剪下，编织成华服。忧郁的美难以言表，却会长存。',Feature=1,TFValidDate='2022-12-16 05:00:00',ValidDate='2022-12-16 05:00:00',MainColor='5451a2FF',}",
  [3006972] = "{id=3006972,NameZh='伴雪寻歌时装兑换券',Icon='item_3006972',Type=121,MaxNum=99999,SellPrice=100,ComposeID=4000102,Desc='使用之后可以获得一件对应阁下性别的伴雪寻歌系列时装哦~',Feature=1,}",
