  [3006980] = "{id=3006980,NameZh='冰凝雪冠·烟火',Icon='item_3006980',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='冰与魔法的国土，寒风凛冽。签订盟誓的冬境之主，为子民带来的优雅与和平。呼啸的狂风是冬日的吟游诗人，不断讲述着这块土地上刻下的记忆，如同骄傲的群星。',Feature=1,TFValidDate='2022-12-16 05:00:00',ValidDate='2022-12-16 05:00:00',MainColor='c8beadFF',}",
  [3006981] = "{id=3006981,NameZh='冰凝雪冠·烈焰',Icon='item_3006980',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='冰与魔法的国土，寒风凛冽。签订盟誓的冬境之主，为子民带来的优雅与和平。呼啸的狂风是冬日的吟游诗人，传唱着火一般热烈的心境，如同一团燃烧的雪，不断复刻着这块土地的荣耀，纯净且明亮。',Feature=1,TFValidDate='2022-12-16 05:00:00',ValidDate='2022-12-16 05:00:00',MainColor='221c19FF',}",
  [3006982] = "{id=3006982,NameZh='冰凝雪冠·沐白',Icon='item_3006980',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='冰与魔法的国土，寒风凛冽。签订盟誓的冬境之主，为子民带来的优雅与和平。呼啸的狂风是冬日的吟游诗人，正在穿越风景。折射出的五彩斑斓，是这块土地的颜色，清澈且闪亮。',Feature=1,TFValidDate='2022-12-16 05:00:00',ValidDate='2022-12-16 05:00:00',MainColor='8d9dc3FF',}",
  [3006983] = "{id=3006983,NameZh='冰凝雪冠·馨晴',Icon='item_3006980',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012930}},Desc='冰与魔法的国土，寒风凛冽。签订盟誓的冬境之主，为子民带来的优雅与和平。呼啸的狂风是冬日的吟游诗人，带着太阳的光芒，发出细微但坚定的声响，温柔且宁静。',Feature=1,TFValidDate='2022-12-16 05:00:00',ValidDate='2022-12-16 05:00:00',MainColor='b99172FF',}",
