  [3006985] = "{id=3006985,NameZh='冰晶雪冠·烟火',Icon='item_3006985',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='冰与魔法的国土，寒风凛冽。建立盟誓的冬境少女，为子民带来的信仰与繁荣。呼啸的狂风是冬日的吟游诗人，不断传唱着这块土地上明亮的记忆，如同骄傲的群星。',Feature=1,TFValidDate='2022-12-16 05:00:00',ValidDate='2022-12-16 05:00:00',MainColor='c8beadFF',}",
  [3006986] = "{id=3006986,NameZh='冰晶雪冠·烈焰',Icon='item_3006985',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='冰与魔法的国土，寒风凛冽。建立盟誓的冬境少女，为子民带来的信仰与繁荣。呼啸的狂风是冬日的吟游诗人，传唱着火一般热烈的心境，如同一团燃烧的雪，不断复刻着这块土地的荣耀，纯净且明亮。',Feature=1,TFValidDate='2022-12-16 05:00:00',ValidDate='2022-12-16 05:00:00',MainColor='221c19FF',}",
  [3006987] = "{id=3006987,NameZh='冰晶雪冠·沐白',Icon='item_3006985',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='冰与魔法的国土，寒风凛冽。建立盟誓的冬境少女，为子民带来的信仰与繁荣。呼啸的狂风是冬日的吟游诗人，正在穿越风景。折射出的绚丽多彩，是这块土地的颜色，清澈且闪亮。',Feature=1,TFValidDate='2022-12-16 05:00:00',ValidDate='2022-12-16 05:00:00',MainColor='8d9dc3FF',}",
  [3006988] = "{id=3006988,NameZh='冰晶雪冠·馨晴',Icon='item_3006985',Type=800,Quality=2,MaxNum=99,SellPrice=100,StorageReward={buffid={80012920}},Desc='冰与魔法的国土，寒风凛冽。建立盟誓的冬境少女，为子民带来的信仰与繁荣。呼啸的狂风是冬日的吟游诗人，带着太阳的光芒，发出细微但坚定的声响，平和且充满慰藉。',Feature=1,TFValidDate='2022-12-16 05:00:00',ValidDate='2022-12-16 05:00:00',MainColor='b99172FF',}",
  [3006989] = "{id=3006989,NameZh='冰晶雪冠系列头饰',Icon='item_3006985',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15695,AdventureValue=1,StorageReward={buffid={80012920}},Condition=8,TFValidDate='2022-12-16 05:00:00',ValidDate='2022-12-16 05:00:00',MainColor='X',}",
  [3006990] = "{id=3006990,NameZh='雪落星辰头饰兑换券',Icon='item_3006990',Type=61,UseMode=31380,MaxNum=99999,SellPrice=100,Desc='使用之后可以兑换任意一件橙色品质以外的雪落星辰系列头饰哦~',Feature=1,TFValidDate='2022-12-16 05:00:00',ValidDate='2022-12-16 05:00:00',}",
  [3006991] = "{id=3006991,NameZh='踏雪肥啾',Icon='item_3006991',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15696,AdventureValue=1,StorageReward={buffid={80012660}},Condition=8,Desc='新买的帽子上印着海浪、白雪和鲜花。吸引了害怕但又想挑战雪地的小肥啾。“妈妈你看，宝宝敢踩雪了，宝宝做到了！”',Feature=1,TFValidDate='2022-12-16 05:00:00',ValidDate='2022-12-16 05:00:00',}",
  [3006992] = "{id=3006992,NameZh='箱庭雪景球',Icon='item_3006992',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15697,AdventureValue=1,StorageReward={buffid={80012940}},Condition=8,Desc='在有限的水晶瓶中，嵌造一个优美精致的雪中世界。在这里，时间还是我的朋友，我还能体验年少时踏雪高歌的快乐。',Feature=1,TFValidDate='2022-12-16 05:00:00',ValidDate='2022-12-16 05:00:00',}",
  [3006993] = "{id=3006993,NameZh='炙热冰冻',Icon='item_3006993',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15698,AdventureValue=1,StorageReward={buffid={80012620}},Condition=8,Desc='上班第一天的冰雪小执事，手忙脚乱的派送礼物中：“啊不好意思，您的，您的礼物一开始不是这样的！呜呜呜！”',Feature=1,TFValidDate='2022-12-16 05:00:00',ValidDate='2022-12-16 05:00:00',}",
  [3006994] = "{id=3006994,NameZh='雪中魅影',Icon='item_3006994',Type=830,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15699,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='在梦中的雪地里他向我歌唱，迎面走来。声声呼唤我的名字，我就这样和雪中魅影相见。',Feature=1,TFValidDate='2022-12-16 05:00:00',ValidDate='2022-12-16 05:00:00',}",
  [3006995] = "{id=3006995,NameZh='胆小雪贴贴',Icon='item_3006995',Type=850,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=15700,AdventureValue=1,StorageReward={buffid={80012970}},Condition=8,Desc='天地间随意飘落的一枚雪花来到你的肩头，噗得变成可爱的小精灵，小心翼翼又满怀激动把自己见过的冰天雪地讲给你听。你以为你们的相遇是一场意外，但其实……这个胆小雪精灵已经喜欢你很久了~',Feature=1,TFValidDate='2022-12-16 05:00:00',ValidDate='2022-12-16 05:00:00',}",
  [3006996] = "{id=3006996,NameZh='奇澜雪夜',Icon='item_3006996',Type=810,Quality=5,MaxNum=99,SellPrice=100,AdventureSort=15701,AdventureValue=1,StorageReward={buffid={80012590}},Condition=8,Desc='如同瓷盘上盛开的水仙，夜色下的雪夜，是诸神馈赠给世间的礼物。而人生的乐趣，便在于从礼物间走过。',Feature=1,TFValidDate='2022-12-16 05:00:00',ValidDate='2022-12-16 05:00:00',}",
  [3006997] = "{id=3006997,NameZh='上古遗物材料礼盒·雪落星辰',Icon='item_3003303',Type=30,Quality=4,MaxNum=99999,SellPrice=100,Desc='装着上古遗物材料的礼盒，使用后必定获得其中一个：「变形头盔的碎片」x1、「女武神的砾石」x1、「冥思之石」x1。',Feature=1,}",
