  [3007080] = "{id=3007080,NameZh='神龙勾玉',Icon='item_3002404',Type=61,Quality=2,UseMode=31367,MaxNum=99999,SellPrice=10,Desc='蕴藏着异世界能量的勾玉，据说对着它许愿可以梦想成真哦~活动期间内，可打开限时神龙商店，兑换丰厚奖励，勾玉将在10月30日过期哦~',ExistTimeType=2,ExistTime='2022-10-30 05:00:00',Feature=1,Delete=3007080}",
