  [3007082] = "{id=3007082,NameZh='神龙的馈赠',Icon='item_3002112',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='来自神龙的馈赠，打开后必定获得Zeny x 150,000、「好运币」x5，以下奖励随机获得一种：「远古材料自选箱」x1、「光洁的符文石」x1、「神谕之尘」x10、「神谕之晶」x10、「祈祷晶片包」x5、「玛斯黛拉种子」x1、「玛斯黛拉果实」x1。',Feature=1,Delete=3007082}",
