  [3007364] = "{id=3007364,NameZh='驯鹿的珍藏',Icon='item_6541',Type=30,MaxNum=99999,SellPrice=100,Desc='驯鹿跟随圣诞老人多年的时间里偷偷积攒下来的宝贝。打开之后，必定获得Zeny x200,000、「福利券自选礼包」x5、「祈祷晶片自选包」x5、「金质勋章」x5、「来自女武神的馈赠」x5。',Feature=1,}",
