  [3007978] = "{id=3007978,NameZh='暖暖的赐福',Icon='TechTree_13062',Type=74,Quality=3,MaxNum=99999,SellPrice=100,Desc='感觉自己被满满的爱包围着，每一分每一秒都觉得温暖哦~\n物理、魔法伤害增加1%，持续12小时',Feature=1,}",
