  [3007980] = "{id=3007980,NameZh='小木锤',Icon='item_3001889',Type=30,UseMode=31043,MaxNum=99999,SellPrice=100,Desc='虽然是普通木制小锤，但是却能发挥巨大威力，真是惊人！“喂！这个不可以用来打人！”',ExistTimeType=2,ExistTime='2023-04-01 05:00:00',Feature=1,}",
  [3007981] = "{id=3007981,NameZh='春日的馈赠',Icon='item_3001762',Type=74,Quality=2,MaxNum=99999,SellPrice=100,Desc='领取后直接获得Zeny x 200,000、「福利券自选礼盒」x5、「祈祷晶片自选包」x5、「金质勋章」x5、「来自女武神的馈赠」x5。',Feature=1,}",
  [3007982] = "{id=3007982,NameZh='奶油芭娜娜',Icon='item_53720',Type=30,Quality=2,UseMode=31414,MaxNum=99999,SellPrice=100,Desc='不要小看香蕉的魔力，只要添加少量奶油，浅浅一口，就能感受到舌尖的狂欢！把它转交给哭泣的溜溜猴，可以换取丰厚的奖励哦~',GetLimit={limit={[999]={1,0}},source={22},type=4},ExistTimeType=2,ExistTime='2023-03-23 05:00:00',Feature=1,}",
  [3007983] = "{id=3007983,NameZh='爱丽丝的礼物',Icon='item_3001763',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='爱丽丝只会送给最好的朋友，打开之后可以获得「料理兑换券」x1、「坠星陨铁」x1、「波利成长秘药」x1、「B格猫福利券·Ⅰ」x3',Feature=1,}",
  [3007984] = "{id=3007984,NameZh='往期头饰礼盒·3月',Icon='item_6068',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='打开这个礼盒，可以自选以下道具中的一个：「约定之冕图纸」x1、「心芽芽图纸」x1、「傀儡之心」x1、「精灵之眼图纸」x1、「精灵的祝福图纸」x1、「藻藻球」x1、「趴趴灵鹿」x1、「白雪棉花糖」x1',Feature=1,}",
  [3007985] = "{id=3007985,NameZh='B格猫巧克力',Icon='item_700007',Type=64,Quality=2,MaxNum=99999,SellPrice=100,Desc='整条街道正在处于幸福的节日中！这是一份来自B格猫的特殊祝福。听说交给正在普隆德拉广场的恋之双子星可以亲手制作节日特别的巧克力！',ExistTimeType=2,ExistTime='2023-03-21 05:00:00',Feature=1,}",
  [3007986] = "{id=3007986,NameZh='情谊巧克力',Icon='item_700005',Type=41,Quality=2,MaxNum=99999,SellPrice=100,Desc='由B格猫星球的恋之神在特定日子到来时才在人间进行出售的拥有独特口味的巧克力，是这个节日赠送亲朋好友的最佳礼物。对其余的冒险家使用后，你和TA都可以获得「暖暖的爱意」x1和「暖暖的赐福」。\n「暖暖的赐福」：物理、魔法伤害增加1%，持续12小时',ItemTarget={range=10,type=3},NoStorage=5,ExistTimeType=2,ExistTime='2023-03-21 05:00:00',Feature=1,}",
  [3007987] = "{id=3007987,NameZh='本命巧克力',Icon='item_700006',Type=41,Quality=2,MaxNum=99999,SellPrice=100,Desc='充满纯洁美丽爱意的巧克力，只有通过特殊的素材并借由来自B格猫星球的恋之神的祝福才能制作成的特别巧克力，因为是本命，所以只能赠送给最特别的那个人！对其余的冒险家使用后，你和TA都可以获得「幸福的爱意」x1和「幸福的赐福」。\n「幸福的赐福」：每30秒恢复520HP，持续12小时',ItemTarget={range=10,type=3},NoStorage=5,ExistTimeType=2,ExistTime='2023-03-21 05:00:00',Feature=1,}",
  [3007988] = "{id=3007988,NameZh='暖暖的爱意',Icon='item_3000281',Type=64,Quality=3,MaxNum=99999,SellPrice=100,Desc='感觉自己被满满的爱包围着，每一分每一秒都觉得温暖哦~\n收集「暖暖的爱意」和「幸福的爱意」交给正在普隆德拉广场的【恋之双子星】，可兑换限定卡片「恋之双子星卡片」哦~',ExistTimeType=2,ExistTime='2023-03-21 05:00:00',Feature=1,}",
  [3007989] = "{id=3007989,NameZh='幸福的爱意',Icon='item_3000282',Type=64,Quality=3,MaxNum=99999,SellPrice=100,Desc='感觉自己被特别的爱关注着，每一分每一秒都觉得幸福哦~\n收集「暖暖的爱意」和「幸福的爱意」交给正在普隆德拉广场的【恋之双子星】，可兑换限定卡片「恋之双子星卡片」哦~',ExistTimeType=2,ExistTime='2023-03-21 05:00:00',Feature=1,}",
  [3007990] = "{id=3007990,NameZh='归来的证明',Icon='item_3004252',Type=61,UseMode=31411,MaxNum=99999,SellPrice=100,Desc='为久别重逢的冒险者准备的礼物，可以在「旅途再续」商店中兑换奖励。\n与回归冒险者组队，完成以下副本获得：恩德勒斯塔、神谕副本、达纳托斯塔、波纳佩博物岛、探秘迷踪岛、瓦尔哈拉遗迹、无限回廊、尼夫海姆炼狱。',ExistTimeType=2,ExistTime='2023-03-05 05:00:00',Feature=1,Delete=3007990}",
