  [3008172] = "{id=3008172,NameZh='勇气之证',Icon='item_6525',Type=61,UseMode=31479,MaxNum=99999,SellPrice=1,Desc='赋予勇士的证明。使用之后可以打开活动商店，兑换各类稀有道具~！\n击败周六、周日16~24点刷新的暴走魔物可以获得大量「勇气之证」。',GetLimit={limit={[999]={1000,0}},source={11,22,44},type=4},ExistTimeType=2,ExistTime='2023-08-01 05:00:00',Feature=1,Delete=3008172}",
  [3008173] = "{id=3008173,NameZh='勇气礼盒',Icon='item_5756',Type=30,Quality=2,MaxNum=99999,SellPrice=100,Desc='打开之后可以在以下奖励中随机获得一种：[itemid]3008606[/itemid]x1、[itemid]3008607[/itemid]x1、「莫拉金币」x5、「附魔结晶」x1、「光洁的符文石」x1、「闪耀的符文石」x1、「闪耀的符文石·星」x1',Feature=1,Delete=3008173}",
  [3008174] = "{id=3008174,NameZh='勇气礼盒·MVP',Icon='item_5756',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='打开之后可以在以下奖励中随机获得一种：[itemid]3008606[/itemid]x1、[itemid]3008607[/itemid]x1、「莫拉金币」x10、「附魔结晶」x1、「光洁的符文石」x1、「闪耀的符文石」x1、「闪耀的符文石·星」x1。\n[itemid]3008607[/itemid]的概率将随着开启次数的增加而增加，最多在开启第3个礼盒时，必定获得！保底仅可触发1次，若在保底次数之前已经获得该道具，则保底将取消。',GetLimit={limit={[999]={1,0}},source={11,22,44},type=4},Feature=1,Delete=3008174}",
  [3008180] = "{id=3008180,NameZh='深渊御兽坐骑自选券',Icon='item_3000545',Type=30,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='打开之后可以在[itemid]25175[/itemid]、[itemid]25211[/itemid]中自选一只坐骑~',Feature=1,Delete=3008180}",
  [3008181] = "{id=3008181,NameZh='曳光双鱼绝版礼盒',Icon='item_3003139',Type=30,Quality=3,MaxNum=9999,SellPrice=100,Desc='B格猫星人在双鱼月推出的礼盒，内含极具收藏价值的绝版外观道具！打开之后可以在以下奖励中随机获得1个(括号内展示稀有道具的获得概率)：[itemid]145655[/itemid]x1(0.3%)、[itemid]3008180[/itemid]x1(0.3%)、[itemid]3005556[/itemid]x1(0.3%)、[itemid]3001307[/itemid]x1(0.3%)、[itemid]3005491[/itemid]x1(0.3%)、[itemid]23263[/itemid]x1(0.5%)、[itemid]23265[/itemid]x1(0.5%)、[itemid]3005490[/itemid]x1(0.5%)、「绝版特典自选礼盒·2017」x1、「弗雷硬币」x1、「瓦特阿尔仙尘」x2、「古拉姆晶末」x200、「诺伦卡片」x200~300、「莫拉金币」x10~20、「神谕之尘」x15~30、「神谕之晶」x12~25、「莫拉硬币」x30~60',Feature=1,ItemShow=1,Delete=3008181}",
  [3008182] = "{id=3008182,NameZh='臻选附魔礼盒',Icon='item_3897',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='打开之后必定获得「莫拉金币」x10~20，20%概率额外获赠[itemid]3006025[/itemid]x1，0.5%概率额外获赠[itemid]3008184[/itemid]x1。\n「附魔神晶」的概率将随着开启次数的增加而增加：最多在开启第100个礼盒时，必定获得「附魔神晶」，该保底可循环触发！\n「附魔神晶」为货币类道具，使用之后可以兑换「神之附魔礼盒」；5个「附魔神晶」可以兑换任意附魔等级4的词条券',Feature=1,ItemShow=1,Delete=3008182}",
  [3008183] = "{id=3008183,NameZh='臻选附魔礼盒x10',Icon='item_3006673',Type=30,Quality=3,MaxNum=99999,SellPrice=100,Desc='打开之后可以获得[itemid]3008182[/itemid]x10',Feature=1,Delete=3008183}",
  [3008184] = "{id=3008184,NameZh='附魔神晶',Icon='item_13600',Type=61,Quality=3,UseMode=31417,MaxNum=99999,SellPrice=100,Desc='从亿万次附魔中沉淀出来的晶石，可以用来兑换各类顶级「词条券」，让你的装备直接拥有极品[enchantbuff]0[/enchantbuff]！',Feature=1,Delete=3008184}",
  [3008185] = "{id=3008185,NameZh='神之附魔礼盒',Icon='item_5965',Type=30,Quality=4,MaxNum=99999,SellPrice=100,Desc='打开之后必定随机获得一张附魔等级3~4的高级词条券，点击右上方四个小方块，可以查看礼盒内包含的词条券列表。',Feature=1,ItemShow=1,Delete=3008185}",
  [3008186] = "{id=3008186,NameZh='泰雅的祝福',Icon='item_1000010',Type=30,Quality=4,MaxNum=99999,SellPrice=100,Desc='打开之后必定获得Zeny x 2,000,000，「莫拉金币」x8~12、「诺伦卡片」x40~60、「古拉姆晶末」x20~35，0.5%概率额外获赠[itemid]3005491[/itemid]x1，0.2%概率额外获赠情人节限定双人坐骑契约[itemid]3008187[/itemid]x1。\n「泰雅象契约」的概率将随着开启次数的增加而增加：最多在开启第200个礼盒时，必定获得「泰雅象契约」，该保底仅可触发1次，若在保底次数之前已经获得该道具，则保底将取消。',Feature=1,ItemShow=1,Delete=3008186}",
  [3008187] = "{id=3008187,NameZh='泰雅象契约',Icon='item_3000545',Type=30,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,Desc='来自于遥远的神秘国度的契约，使用后将可以获得限定双人坐骑[itemid]25194[/itemid]x1！契约在未使用前可上架交易所自由交易，使用后获得的坐骑将与冒险者绑定灵魂关系，无法再上架交易所，请各位冒险者谨慎使用！',Feature=1,Delete=3008187}",
  [3008190] = "{id=3008190,NameZh='精粹之水',Icon='item_700187',Type=64,MaxNum=99999,SellPrice=100,Desc='只会在某些时节凝聚在水属性魔物体内的珍贵水源。听说普隆德拉广场的【库拉拉】正在收集它。',GetLimit={limit={[999]={1,0}},source={22},type=4},ExistTimeType=2,ExistTime='2023-04-17 05:00:00',Feature=1,Delete=3008190}",
  [3008191] = "{id=3008191,NameZh='圣水祝福',Icon='item_5522',Type=41,MaxNum=99999,SellPrice=100,Desc='库拉拉只会将这份特别的礼物，赠予最真诚的朋友！对其余的冒险家使用后，你和TA都可以获得「庆典花环」x1或「庆典圣水」x1。',ItemTarget={range=10,type=3},NoStorage=5,ExistTimeType=2,ExistTime='2023-04-17 05:00:00',Feature=1,Delete=3008191}",
  [3008192] = "{id=3008192,NameZh='庆典花环',Icon='item_3006174',Type=64,MaxNum=99999,SellPrice=100,Desc='只在特殊的日子才能获得的纪念品。收集「庆典花环」和「庆典圣水」，交给正在普隆德拉广场的【库拉拉】可以兑换活动专属卡片「圣水祝福卡片」！',ExistTimeType=2,ExistTime='2023-04-17 05:00:00',Feature=1,Delete=3008192}",
