  [3008893] = "{id=3008893,NameZh='魔神坛斗士扭蛋币',Icon='item_3002147',Type=41,UseMode=31389,MaxNum=99999,SellPrice=100,Desc='为了欢迎魔神坛斗士的到来特意发行的扭蛋币，冒险者可以使用它去参与魔神坛斗士异次元扭蛋机~但是在魔神坛斗士离开了之后，这个扭蛋币也就没什么用啦，所以各位冒险者请注意使用期限哦~',ExistTimeType=2,ExistTime='2023-08-31 05:00:00',Feature=1,Delete=3008893}",
  [3008894] = "{id=3008894,NameZh='烈火之力',Icon='item_700138',Type=61,UseMode=31503,MaxNum=99999,SellPrice=100,Desc='烫手的宝石，还带着烈火的灼烧感。使用之后可以打开活动商店，兑换各类稀有道具。',ExistTimeType=2,ExistTime='2023-08-31 05:00:00',Feature=1,Delete=3008894}",
  [3008895] = "{id=3008895,NameZh='辉煌精华',Icon='item_700135',Type=61,UseMode=31504,MaxNum=99999,SellPrice=100,Desc='通过分解联动扭蛋中的外观可以获得，使用之后可以打开魔神坛斗士异次元商店，用来兑换[itemid]23302[/itemid]等稀有道具。',Feature=1,Delete=3008895}",
  [3008896] = "{id=3008896,NameZh='妖邪帝王秘宝',Icon='item_3002607',Type=30,MaxNum=99999,SellPrice=100,Desc='据说是妖邪帝王留下的秘宝，使用之后可以必定获得Zeny x 1,500,000、[itemid]3008897[/itemid]x1，10%概率获赠四魔将头饰中的1种：「幻魔将头盔」x1、「暗魔将头盔」x1、「毒魔将头盔」x1、「鬼魔将头盔」x1。集齐不同的4个魔将头盔，可以触发特殊任务「妖邪帝王之盔」，完成任务后，可以获得「妖邪帝王头盔」x1，同时解锁限定成就「妖邪帝王」，奖励限定时装「幻·妖邪帝王」x1、限定背饰「 阿罗格之威」x1。特殊任务将在2024/1/1 05:00失效。',Feature=1,ItemShow=1,Delete=3008896}",
  [3008897] = "{id=3008897,NameZh='秘卷自选礼',Icon='task_53630',Type=61,UseMode=31505,MaxNum=99999,SellPrice=100,Desc='打开之后，可自选「B格猫福利券·宴」x10或「魔神坛斗士扭蛋币」x10。\n（在魔神坛斗士离开了之后，只能兑换「B格猫福利券·宴」x10，请注意使用期限哦）',Feature=1,Delete=3008897}",
  [3008898] = "{id=3008898,NameZh='极速成长礼包·烈火',Icon='item_3008841',Type=30,Quality=4,MaxNum=99999,SellPrice=100,Desc='联动职业「烈火」的专属极速成长礼包，打开之后可以获得以下道具：[itemid]3008899[/itemid]x1、[itemid]3007403[/itemid]x1、[itemid]3009030[/itemid]x2000、「龙骨盾」x1、「白骨之惧战甲」x1、「勇士肩甲」x1、「平衡之理靴子」x1、「鲜花发卡」x1、「灼炎之精」x1、「黑暗觉醒·星符文」x1、「死亡牢笼·星符文」x1、「狂暴吐息符文」x1、「破风巧打符文」x1、「武器格挡符文」x1、「怒意回流符文」x1、「狂裂强击符文」x1、「刚毅印记符文」x1，联动职业，立即体验！\n(该礼包仅限联动职业「烈火」开启)',Feature=1,ItemShow=1,Delete=3008898}",
