  [3009517] = "{id=3009517,NameZh='备战晶片补给箱',Icon='item_3009517',Type=30,Quality=3,MaxNum=9999,SellPrice=100,Desc='可以快速提升祝福等级的礼盒，打开之后可以获得女神祝福通用提升材料[itemid]3720[/itemid]x5，20%概率额外获赠神圣祝福专属提升材料[itemid]5551[/itemid]x1。',Feature=1,ItemShow=1,Delete=3009517}",
  [3009518] = "{id=3009518,NameZh='活动头饰补给箱',Icon='item_3009518',Type=30,Quality=3,MaxNum=9999,SellPrice=100,Desc='用来快速解锁活动头饰的礼盒，打开之后必定获得[itemid]6768[/itemid]x10，有10%概率额外获赠往期活动中产出的可交易头饰或头饰图纸1个。',Feature=1,ItemShow=1,Delete=3009518}",
