  [3009520] = "{id=3009520,NameZh='星选卡片礼盒·MVP',Icon='item_3009520',Type=30,Quality=3,MaxNum=9999,SellPrice=100,Desc='价值连城的卡片礼盒，打开之后可以随机获得一张MVP星选卡，通过礼盒获得的卡片可以在冒险手册中解锁！\n（星选卡意为在「国王波利」处可以通过“高级定制”功能合成同名带★卡的卡片，点击礼盒左上角的小方格可以查看所有可获得的卡片）',Feature=1,Delete=3009520}",
  [3009521] = "{id=3009521,NameZh='星选卡片礼盒·MINI',Icon='item_3009521',Type=30,Quality=3,MaxNum=9999,SellPrice=100,Desc='价值不菲的卡片礼盒，打开之后可以随机获得一张Mini星选卡，通过礼盒获得的卡片可以在冒险手册中解锁！\n（星选卡意为在「国王波利」处可以通过“高级定制”功能合成同名带★卡的卡片，点击礼盒左上角的小方格可以查看所有可获得的卡片）',Feature=1,Delete=3009521}",
  [3009522] = "{id=3009522,NameZh='星选卡片补给箱 ',Icon='item_3009522',Type=30,Quality=3,MaxNum=9999,SellPrice=100,Desc='用来快速解锁卡片的礼盒，打开之后必定获得[itemid]3009519[/itemid]x1、[itemid]52836[/itemid]x50，1%概率额外获赠[itemid]3009521[/itemid]x1，0.3%概率额外获赠[itemid]3009520[/itemid]x1。\n[itemid]3009519[/itemid]为代币类道具，使用之后可以打开代币商店，兑换[itemid]3009520[/itemid]、[itemid]3009521[/itemid]等稀有道具。\n（星选卡意为在「国王波利」处可以通过“高级定制”功能合成同名带★卡的卡片）',Feature=1,ItemShow=1,Delete=3009522}",
