  [3012685] = "{id=3012685,NameZh='B格猫巧克力',Icon='item_700007',Type=64,Quality=2,MaxNum=99999,SellPrice=100,Desc='整条街道正在处于幸福的节日中！这是一份来自B格猫的特殊祝福。听说交给普隆德拉的【零钱·银牙】可以亲手制作节日特别的巧克力！',ExistTimeType=2,ExistTime='2025-04-01 05:00:00',Feature=1,}",
  [3012686] = "{id=3012686,NameZh='暖暖的爱意',Icon='item_3000281',Type=64,Quality=3,MaxNum=99999,SellPrice=100,Desc='感觉自己被满满的爱包围着，每一分每一秒都觉得温暖哦~\n收集「暖暖的爱意」和「幸福的爱意」交给普隆德拉的【零钱·银牙】，可兑换「幸福白色季节卡片」哦~',ExistTimeType=2,ExistTime='2025-04-01 05:00:00',Feature=1,}",
  [3012687] = "{id=3012687,NameZh='幸福的爱意',Icon='item_3000282',Type=64,Quality=3,MaxNum=99999,SellPrice=100,Desc='感觉自己被特别的爱关注着，每一分每一秒都觉得幸福哦~\n收集「暖暖的爱意」和「幸福的爱意」交给普隆德拉的【零钱·银牙】，可兑换「幸福白色季节卡片」哦~',ExistTimeType=2,ExistTime='2025-04-01 05:00:00',Feature=1,}",
  [3012688] = "{id=3012688,NameZh='情谊巧克力',Icon='item_700005',Type=41,Quality=2,MaxNum=99999,SellPrice=100,Desc='由B格猫星球的恋之神在特定日子到来时才在人间进行出售的拥有独特口味的巧克力，是这个节日赠送亲朋好友的最佳礼物。对其余的冒险家使用后，你和TA都可以获得「暖暖的爱意」x1和「暖暖的赐福」。\n「暖暖的赐福」：物理、魔法伤害增加1%，持续12小时',ItemTarget={range=10,type=3},NoStorage=5,ExistTimeType=2,ExistTime='2025-04-01 05:00:00',Feature=1,}",
  [3012689] = "{id=3012689,NameZh='本命巧克力',Icon='item_700006',Type=41,Quality=2,MaxNum=99999,SellPrice=100,Desc='充满纯洁美丽爱意的巧克力，只有通过特殊的素材并借由来自B格猫星球的恋之神的祝福才能制作成的特别巧克力，因为是本命，所以只能赠送给最特别的那个人！对其余的冒险家使用后，你和TA都可以获得「幸福的爱意」x1和「幸福的赐福」。\n「幸福的赐福」：每30秒恢复520HP，持续12小时',ItemTarget={range=10,type=3},NoStorage=5,ExistTimeType=2,ExistTime='2025-04-01 05:00:00',Feature=1,}",
  [3012710] = "{id=3012710,NameZh='归来的证明',Icon='item_3004252',Type=61,UseMode=31802,MaxNum=99999,SellPrice=100,Desc='为久别重逢的冒险者准备的礼物，可以在「旅途再续」商店中兑换奖励。\n与回归冒险者组队，完成以下副本获得：恩德勒斯塔、神谕副本、达纳托斯之塔、波纳佩博物岛、探秘迷踪岛、瓦尔哈拉遗迹、无限回廊、混沌入侵、波纳佩秘境、幽灵皇宫。',ExistTimeType=2,ExistTime='2025-04-01 05:00:00',Feature=1,}",
