  [3013898] = "{id=3013898,NameZh='情人节Zeny礼盒',Icon='item_3013892',Type=74,Quality=3,MaxNum=9999,SellPrice=100,Desc='购买后立即获得1.5倍Zeny补给，共计Zeny x49,200,000，同时额外赠送情人节限定装扮「情人节时装外观礼盒」！礼盒在未开启前可上架交易所自由交易，打开后获得的时装将与冒险者绑定灵魂关系，无法再上架交易所，请各位冒险者谨慎使用！',Feature=1,}",
