  [3031167] = "{id=3031167,NameZh='闪耀的收获',Icon='item_3031167',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10139,AdventureValue=80,AdventureReward={buffid={61000860}},StorageReward={buffid={80012640}},Condition=4,ComposeID=3000167,Desc='阳光与汗水洒满了金色的五月，而收获之日来临时，过往的辛劳都会化为喜悦的笑容。“愿你的付出总有回报！”',Feature=1,TFValidDate='2019-04-29 05:00:00',ValidDate='2019-05-02 05:00:00',}",
  [3031168] = "{id=3031168,NameZh='茜色回忆',Icon='item_3031168',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10140,AdventureValue=110,AdventureReward={buffid={61001130}},StorageReward={buffid={80012970}},Condition=4,ComposeID=3000168,Desc='波利造型的可爱头巾，见证了努力和付出的每一个瞬间。此刻所有的勤恳与辛劳，在未来都会化作回忆的珍藏。',Feature=1,TFValidDate='2019-04-29 05:00:00',ValidDate='2019-05-02 05:00:00',}",
