  [3031520] = "{id=3031520,NameZh='逃学大王帽',Icon='item_3031520',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10145,AdventureValue=80,AdventureReward={buffid={61000860}},StorageReward={buffid={80012640}},Condition=4,ComposeID=3000520,Desc='“哟，想和我们一起搞点大事吗？来加入逃学社吧！”逃学社社长卡卡亲手设计的帽子，只赠送给被他认可的人类。但被多咪施加了整蛊魔法，佩戴时需要小心哦。',Share=1,Feature=1,TFValidDate='2019-08-29 05:00:00',ValidDate='2019-09-01 05:00:00',}",
