  [3031552] = "{id=3031552,NameZh='鱼子酱寿司',Icon='item_3031552',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10153,AdventureValue=80,AdventureReward={buffid={61000560}},StorageReward={buffid={80012640}},Condition=4,ComposeID=3000552,Desc='河豚老板料理店的招牌美食！松软的米饭外加满满的鱼子酱，一口下去让你绝对的满足。咕噜噜~咕噜噜~完了！我的肚子在叫嚣了！',Share=1,Feature=1,TFValidDate='2019-09-28 05:00:00',ValidDate='2019-10-01 05:00:00',LoadShowSize=3,}",
  [3031553] = "{id=3031553,NameZh='河豚料理师',Icon='item_3031553',Type=840,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10154,AdventureValue=120,AdventureReward={buffid={61000460}},StorageReward={buffid={80012640}},Condition=4,ComposeID=3000553,Desc='河豚老板是大陆上最有名的日式料理师，每个尝过它料理的人再吃别的食物都觉得索然无味，不过，要记住千万不要在他面前提到河豚刺身，否则……',Share=1,Feature=1,TFValidDate='2019-09-28 05:00:00',ValidDate='2019-10-01 05:00:00',}",
