  [3031851] = "{id=3031851,NameZh='我不是bug',Icon='item_3031851',Type=810,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10160,AdventureValue=120,AdventureReward={buffid={61000460}},StorageReward={buffid={80012640}},Condition=4,ComposeID=3000851,Desc='“警报！警报！loading图陷入了死循环，波利跳不动了！！”“根据调查这是来自异次元的虫子搞的鬼，交给我们吧！不过，事后你们需要提供一些绿色的硬币作为补偿……”一群头顶光辉的年轻人如是说。',Feature=1,TFValidDate='2019-10-29 05:00:00',ValidDate='2019-11-01 05:00:00',}",
  [3031856] = "{id=3031856,NameZh='Npc的忏悔',Icon='item_3031856',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10161,AdventureValue=1,StorageReward={buffid={80012980}},Condition=8,Desc='“如果有时候这里的故事让你感到困扰了，请相信那不是我们的本意……如果可以，我们也想一直陪伴在你身边。还有，便当真的很难吃，拜托那些策划不要再发了。”——某位不愿透露姓名的蓝发少女',Feature=1,TFValidDate='2019-10-29 05:00:00',ValidDate='2019-11-01 05:00:00',}",
