  [3032214] = "{id=3032214,NameZh='爱与勇气的冒险·2020',Icon='item_3032214',Type=800,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10173,AdventureValue=80,AdventureReward={buffid={61000590}},StorageReward={buffid={80012640}},Condition=4,ComposeID=3001214,Desc='3rd!从1st到3rd，一千零一夜的陪伴，仿佛只是一瞬间！第一次转职，第一次牵手，第一次MVP……所有的第一次都还历历在目，往后的日子还会迎来更多的第一次！勇敢的冒险者，向新的一年前进吧！',Feature=1,TFValidDate='2019-12-25 05:00:00',ValidDate='2020-01-01 05:00:00',}",
  [3032248] = "{id=3032248,NameZh='炸鸡之魂',Icon='item_3032248',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10189,AdventureValue=110,AdventureReward={buffid={61001120}},StorageReward={buffid={80012980}},Condition=4,ComposeID=3001248,Desc='不要小看美食的力量，味蕾间的每一次绽放都是整个世界对食客的拥抱。对炸鸡怀着虔诚的心，终有一天，炸鸡之魂会降临在身边，让冒险者充满无尽的活力。',TFValidDate='2020-01-01 05:00:00',ValidDate='2020-01-01 05:00:00',}",
  [3032290] = "{id=3032290,NameZh='子头巾',Icon='item_3032290',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10181,AdventureValue=1,AdventureReward={buffid={61000520}},StorageReward={buffid={80012990}},Condition=8,Desc='可爱的大耳鼠闯进了童年的梦境。如果你发现了它，记得打个招呼，会得到神灵的祝福，一整年都会交好运呢！',}",
  [3032401] = "{id=3032401,NameZh='心芽芽',Icon='item_3001401',Type=810,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10199,AdventureValue=1,AdventureReward={buffid={61000520}},StorageReward={buffid={80012990}},Condition=4,ComposeID=3001401,Desc='传说来自爱之国度的种子，将它埋入土壤细心浇灌，在阳光的沐浴下，爱的枝芽便会破土而出，为你带来温暖与幸福',Feature=1,TFValidDate='2020-02-23 05:00:00',ValidDate='2020-03-01 05:00:00',LoadShowSize=3,LoadShowPose={0,0,0},}",
  [3032420] = "{id=3032420,NameZh='恶兽假面',Icon='item_3032420',Type=830,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10192,AdventureValue=110,AdventureReward={buffid={61001130}},StorageReward={buffid={80012920}},Condition=4,ComposeID=3001420,Desc='“你知道吗？恶兽并不邪恶，之所以被称为恶兽，是因为它想亲近人类，却把人类吓坏了。说这个其实是想告诉你，很抱歉戴着面具恶作剧，但我只是想要亲近你……”',TFValidDate='2020-01-17 05:00:00',ValidDate='2020-01-24 05:00:00',}",
  [3032434] = "{id=3032434,NameZh='爱的电灯泡',Icon='item_3032434',Type=800,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10193,AdventureValue=110,AdventureReward={buffid={61001120}},StorageReward={buffid={80012930}},Condition=4,ComposeID=3001434,Desc='“你们看起来好甜蜜呀，我可以和你们一起玩吗？哎呀呀，别跑嘛……”据说只要戴上，就会成为人群中最闪亮的电灯泡。虽然似乎会遭到一些情侣的嫌弃，但也能吸引更多人的目光，增加找到自己理想伴侣的几率哦！',TFValidDate='2020-01-22 05:00:00',ValidDate='2020-02-05 05:00:00',}",
  [3032437] = "{id=3032437,NameZh='璀璨星灯',Icon='item_3032437',Type=810,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10194,AdventureValue=80,AdventureReward={buffid={61000520}},StorageReward={buffid={80012990}},Condition=4,ComposeID=3001437,Desc='一盏盏星灯是人间的心愿，升到空中汇聚成了星河。灯火点燃时，孩子们都欢呼雀跃，踮起脚来抬头仰望。仿佛灯火飞得越高，他们的愿望就离实现更近了一些。',TFValidDate='2020-02-02 05:00:00',ValidDate='2020-02-08 05:00:00',}",
  [3032504] = "{id=3032504,NameZh='KFC宅急送春日礼包',Icon='item_3620',Type=30,Quality=3,MaxNum=99,SellPrice=100,Desc='春天来临啦，KFC为冒险者们送上迎春礼包，打开可以获得「魔力树枝SP」x2、「天地树果实」x10、「KFC炸鸡料理」x5。',Delete=3032504}",
