  [3033006] = "{id=3033006,NameZh='爱做梦的木马',Icon='item_3002006',Type=840,Quality=2,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10237,AdventureValue=100,AdventureReward={buffid={61000590}},StorageReward={buffid={80012640}},Condition=4,ComposeID=3002006,Desc='陪伴在女王身边的木马，大多数时间都在睡觉，梦里似乎有什么开心的事情发生。',Feature=1,TFValidDate='2020-05-25 05:00:00',ValidDate='2020-06-01 05:00:00',LoadShowSize=1,LoadShowPose={0,0,0},}",
  [3033007] = "{id=3033007,NameZh='巨大的棒棒糖',Icon='item_3002007',Type=810,Quality=3,MaxNum=99,AuctionPrice=1,SellPrice=100,AdventureSort=10238,AdventureValue=170,AdventureReward={buffid={61001090}},StorageReward={buffid={80012970}},Condition=4,ComposeID=3002007,Desc='既能作为装饰，又能作为武器的巨大棒棒糖，饿了馋了的时候，还能咬一口~',Feature=1,TFValidDate='2020-05-25 05:00:00',ValidDate='2020-06-01 05:00:00',}",
  [3033021] = "{id=3033021,NameZh='流星',Icon='item_3033021',Type=840,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10260,AdventureValue=1,StorageReward={buffid={80012920}},Condition=8,Desc='每一颗划过天际的流星，最后都会去往何方呢？',Feature=1,TFValidDate='2020-07-25 05:00:00',ValidDate='2020-08-01 05:00:00',LoadShowSize=1,LoadShowPose={0,0,-0.2},}",
  [3033290] = "{id=3033290,NameZh='愤怒的魔锅蛋',Icon='item_3033290',Type=800,Quality=2,MaxNum=99,SellPrice=100,AdventureSort=10274,AdventureValue=80,AdventureReward={buffid={61000590}},StorageReward={buffid={80012630}},Condition=4,ComposeID=3002290,Desc='充满怒气的魔锅蛋，令它愤怒的点，主要是，它也不知道为什么，自己就莫名其妙地成为了黄金蛋炒饭的材料，以至于差点灭绝。',Feature=1,TFValidDate='2020-09-24 05:00:00',ValidDate='2020-10-01 05:00:00',LoadShowRotate=300,LoadShowPose={0,0.4,-0.5},}",
  [3033303] = "{id=3033303,NameZh='小花仙',Icon='item_3033303',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10282,AdventureValue=110,AdventureReward={buffid={61001130}},StorageReward={buffid={80012660}},Condition=4,ComposeID=3002303,Desc='穿梭在花丛间，寻找能够为人们带来幸运的四叶草——小花仙就是我啦！',TFValidDate='2020-10-07 05:00:00',ValidDate='2020-10-14 05:00:00',}",
  [3033304] = "{id=3033304,NameZh='聚焦虹冠',Icon='item_3033304',Type=800,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10283,AdventureValue=110,AdventureReward={buffid={63000230}},StorageReward={buffid={80012660}},Condition=4,ComposeID=3002304,Desc='使用彩虹桥碎片打造的头冠，能够在前方映射出一道小小的彩虹。',TFValidDate='2020-10-07 05:00:00',ValidDate='2020-10-14 05:00:00',}",
  [3033307] = "{id=3033307,NameZh='黯月浮光',Icon='item_3033307',Type=810,Quality=3,MaxNum=99,SellPrice=100,AdventureSort=10284,AdventureValue=170,AdventureReward={buffid={61001120}},StorageReward={buffid={80012660}},Condition=4,ComposeID=3002307,Desc='岸上的人永远不知道溺水者的感受，身处光明的人也无法理解为何有人在黑暗中沉沦——我已沉入深渊，无法回头。',TFValidDate='2020-11-11 05:00:00',ValidDate='2020-11-18 05:00:00',}",
  [3033308] = "{id=3033308,NameZh='爱之缤纷礼盒',Icon='item_6606',Type=30,MaxNum=99999,SellPrice=100,Desc='亲爱的冒险者，累了就休息一下，打开礼盒看看会有惊喜哦~！（使用后可能获得冰雕玫瑰、红玛瑙、犬牙、炽焰、强效剂、圣诞红色转蛋等材料）',NoStorage=5,Delete=3033308}",
  [3033750] = "{id=3033750,NameZh='四周年波利蛋糕',Icon='item_3033750',Type=41,MaxNum=99,SellPrice=100,Desc='针对无甜不欢的异世界冒险者伙伴，罗森结合波利药水的功效和草莓味蛋糕的风味，出品了这款蛋糕。\n可是，手工小哥不忍心看“波利奶团大家族”被客户咬塌，故每日只上架少许的份数。这时，就得牢记那句永恒的真理了：“售完即止，先到先得。”\n使用后1小时内，野外击杀魔物获得的Base经验和Job经验翻倍！（死亡及非战斗状态下消耗Buff时长，离线状态不消耗Buff时长）',Feature=1,Delete=3033750}",
  [3033751] = "{id=3033751,NameZh='罗森·樱色相约',Icon='item_6602',Type=30,MaxNum=99,SellPrice=100,Desc='献给与众人相遇罗森的你~望你的魂之力如樱花般常开不谢！使用后，获赠「B格猫福利券·I」x6、「超大型JOB药水」x50、「超大型BASE药水」x50。',Feature=1,Delete=3033751}",
  [3033752] = "{id=3033752,NameZh='冒险驿站补给包',Icon='item_6509',Type=30,MaxNum=99,SellPrice=100,Desc='对于每位光临驿站的冒险者，罗森都满怀感激，赠此礼包。使用后，获赠「龙之宝箱」x3、限定头饰「亿亿酱发饰」x1。',Feature=1,Delete=3033752}",
  [3033753] = "{id=3033753,NameZh='冒险驿站速成包',Icon='item_3711',Type=30,MaxNum=99,SellPrice=100,Desc='罗森冒险驿站赠予彩虹波利蛋糕的试吃者们，以嘉奖其勇气的礼包。使用后，获赠「四周年波利蛋糕」x1、限定头饰「趴趴亿亿酱」x1。',Feature=1,Delete=3033753}",
  [3033754] = "{id=3033754,NameZh='罗森莓红礼包',Icon='item_3001435',Type=30,MaxNum=99,SellPrice=100,Desc='由罗森推出，以波利红为主题色的礼包。给人喜庆或浪漫的印象。但沉甸甸的不易搬运，材料也很精贵，不建议拿到情人节和亲朋的婚宴上循环利用。使用后，获赠「好运币」x5、「祈祷晶片包」x1、「料理兑换券」x1。',Feature=1,Delete=3033754}",
  [3033755] = "{id=3033755,NameZh='罗森樱粉礼包',Icon='item_49536',Type=30,MaxNum=99,SellPrice=100,Desc='由罗森推出，以天水之国樱花为主题色的礼包。给人唯美的印象，似乎盛放了Miao先森从几位贪吃神明那里借来的“本金”。使用后，获赠限定头饰「天波头套」x1、「玛丝黛拉种子」x5、「神谕之晶」x10、「神谕之尘」x10。',Feature=1,Delete=3033755}",
  [3033756] = "{id=3033756,NameZh='罗森芋蓝礼包',Icon='item_49537',Type=30,MaxNum=99,SellPrice=100,Desc='由罗森亿亿酱打包，以冰波利和恶魔波利为主题色的礼包。冷峻的包裹下装有店长本人……呃不，本喵，可谓冒险驿站的镇店之宝。使用后，获赠限定宠物「Miao先森宠物蛋」x1、「金质勋章」x4、「来自女武神的馈赠」x4、「莫拉硬币」x20。',Feature=1,Delete=3033756}",
  [3033757] = "{id=3033757,NameZh='樱誓琥珀',Icon='item_3852',Type=41,MaxNum=1,SellPrice=100,Desc='在樱花树下许下的誓言，被琥珀封存，这一刻便是永恒。传说在花嫁节对心爱的人使用可以得到“誓约之戒”哟！',ItemTarget={range=10,type=3},ExistTimeType=2,ExistTime='2025-09-01 05:00:00',Feature=1,}",
  [3033758] = "{id=3033758,NameZh='誓约之戒',Icon='item_44091',Type=64,MaxNum=1,SellPrice=100,Desc='将誓言说给你听，期盼郑重的誓约能缠绕着你的无名指，永不摘下。',ExistTimeType=2,ExistTime='2025-09-01 05:00:00',Feature=1,}",
  [3033760] = "{id=3033760,NameZh='圣雪福袋',Icon='item_3725',Type=30,MaxNum=9999,SellPrice=100,Desc='听说装满了「圣雪精华」，可是它不会化掉吗？打开后获赠「圣雪精华」x5~15，可用做兑换圣诞礼物！',Feature=1,Delete=3033760}",
  [3033761] = "{id=3033761,NameZh='圣雪精华',Icon='item_6220',Type=61,UseMode=31154,MaxNum=9999,SellPrice=100,Desc='冰雪凝聚而成的纯粹精华，每一枚都极其珍贵。使用之后，可以打开「圣诞老人的特别商店」，兑换圣诞礼物！',ExistTimeType=2,ExistTime='2021-02-01 05:00:00',Feature=1,Delete=3033761}",
  [3033762] = "{id=3033762,NameZh='圣雪礼包',Icon='item_3726',Type=30,MaxNum=9999,SellPrice=100,Desc='圣诞老人留下的礼物~打开后获赠「圣雪精华」x10，可用做兑换圣诞礼物！',Feature=1,Delete=3033762}",
  [3033763] = "{id=3033763,NameZh='波利大集市礼盒',Icon='item_6602',Type=30,MaxNum=9999,SellPrice=100,Desc='波利大集市拼下来的礼盒~使用后「诺伦卡片」x40~60、「古拉姆晶末」x15~30、「莫拉硬币」x12~24、「Zeny」x300000。',Feature=1,Delete=3033763}",
  [3033765] = "{id=3033765,NameZh='碧蓝传说',Icon='item_3033765',Type=501,MaxNum=99,SellPrice=100,Desc='远方传来机械的轰鸣，伴着齿轮的滴答声，他是那个时代的一抹碧蓝，缓缓揭开包围着谜团的雾。',Feature=1,TFValidDate='2023-07-03 05:00:00',ValidDate='2023-06-26 05:00:00',}",
  [3033766] = "{id=3033766,NameZh='深空幻想',Icon='item_3033766',Type=501,MaxNum=99,SellPrice=100,Desc='雾中弥漫着铁锈的气息，她将指针回溯至工业时代，在爱与冒险的深空中，等待那场机械与魔法的狂欢。',Feature=1,TFValidDate='2023-07-03 05:00:00',ValidDate='2023-06-26 05:00:00',}",
  [3033767] = "{id=3033767,NameZh='碧蓝守望',Icon='item_3033767',Type=800,Quality=3,MaxNum=99,SellPrice=100,Desc='机械师常备的优雅高帽，以柔韧皮革制成，配以特殊的齿轮护目镜，每一处都显示着精致与高雅。',Feature=1,TFValidDate='2023-07-03 05:00:00',ValidDate='2023-06-26 05:00:00',}",
  [3033768] = "{id=3033768,NameZh='深空守望',Icon='item_3033768',Type=800,Quality=3,MaxNum=99,SellPrice=100,Desc='风靡一时的精巧圆帽，除了圆镜外还有着隆重的发带拖尾。戴上它，不论何时都是人群的焦点。',TFValidDate='2023-07-03 05:00:00',ValidDate='2023-06-26 05:00:00',}",
