  [10000233] = "{id=10000233,NameZh='2025.4月限定特典',Icon='item_800404',Type=47,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,AdventureSort=13,AdventureValue=100,Condition=64,Desc='“樱花盛开的季节应约而至，叫上可爱的伙伴们一起去远足吧！走在绚烂的春光下，微风轻拂过你的面庞，连草地上铺展开的野餐布都有着阳光的味道呢~”著名的卡普拉公司为答谢长久以来支持本社的冒险者的厚爱，特别推出以月刊形式发售的特别小卡片，拿在手里仿佛能感受到充满神奇的魔力，实用和珍藏价值极高。每次使用均可获得限定头饰[itemid]3001466[/itemid]x1。',Feature=1,}",
