  [10000235] = "{id=10000235,NameZh='2025.6月限定特典',Icon='item_800406',Type=47,Quality=4,MaxNum=99999,AuctionPrice=1,SellPrice=100,AdventureSort=15,AdventureValue=100,Condition=64,Desc='“阳光洒向了你的眼中，空气中荡漾起一抹柔软的涟漪。时光流逝，物换星移，可童年的梦想永不改变。”著名的卡普拉公司为答谢长久以来支持本社的冒险者的厚爱，特别推出以月刊形式发售的特别小卡片，拿在手里仿佛能感受到充满神奇的魔力，实用和珍藏价值极高。每次使用均可获得限定头饰[itemid]3001906[/itemid]x1。',Feature=1,}",
